	public CharacterProfile Profile
	{
		get
		{
			return _profile;
		}
		set
		{
			_profile = value;
			HookProfileColors();
			// 换存档：遗物列表的「序号 + 空槽行」要改挂到新存档的 Relics 上（旧的那份要摘掉订阅），
			// 并把镜像集合按新存档重铺一遍 —— 见 HookRelicListOrder / SyncRelicRows
			HookRelicListOrder();
			SyncRelicRows();
			RelicUiSelection = null;
			// 药水页同理（V0.2.127：「药水方面参考遗物的优化方案」——序号 + 空槽 + 拖动）
			HookPotionListOrder();
			SyncPotionRows();
			PotionUiSelection = null;
			// 卡牌页（V0.2.130 左侧序号；V0.2.140 改成**每 5 个一块 + 空槽带灰色序号**）：
			// 三页的镜像集合（CardRows / CurseRows / AncientRows）要跟着新存档重铺一遍
			SyncCardRowMirrors();
			_cardMirror.SelectedRow = null;
			_curseMirror.SelectedRow = null;
			_ancientMirror.SelectedRow = null;
			Raise("HasCardSelection");
			Raise("HasCurseSelection");
			Raise("HasAncientSelection");
			// 「动画」页的设置区是直接绑 AnimationSpec 字段的，换了存档要重新挂监听
			// （界面右下角那行诊断 / 橙色提示都靠它刷新）
			HookAnimationSpec();
			// 「本体关键词改名」是固定 7 行的表格：换存档时把缺的行补齐并接上事件
			EnsureKeywordRenameRows();
			// 「自定义参数 / 组」两页：换存档要重新挂监听（列表里的显示文字是算出来的）
			HookParamsAndGroups();
			Raise("Profile");
			Raise("PresetSelection");
			Raise("FrameSelection");
		}
	}

	/// <summary>
	/// 「自定义参数 / 组」页的监听：参数改了任何字段（名字 / 来源 / 目标 / 状态 / 给予量）
	/// 都要让右边那句「等于什么」和「给予能量」两个下拉的候选跟着刷新。"
	/// 换存档时先全部摘掉再重挂，避免重复订阅（和 <see cref="EnsureKeywordRenameRows"/> 一个套路）。"
	/// </summary>
	private void HookParamsAndGroups()
	{
		foreach (var old in _paramHooked) old.PropertyChanged -= OnParamSpecChanged;
		_paramHooked.Clear();
		foreach (var p in _profile.CustomParams)
		{
			p.PropertyChanged += OnParamSpecChanged;
			_paramHooked.Add(p);
		}
		foreach (var old in _groupHooked) old.PropertyChanged -= OnGroupSpecChanged;
		_groupHooked.Clear();
		foreach (var g in _profile.CardGroups)
		{
			g.PropertyChanged += OnGroupSpecChanged;
			_groupHooked.Add(g);
		}
		Raise("ParamSummaryRows");
		Raise("ParamGrantChoices");
		Raise("ParamNameWarnText");
		Raise("CardGroupRows");
		Raise("NoCardGroups");
		Raise("CardGroupRowHint");
		Raise("GroupCardRows");
		// V0.2.257：组增删 / 改名之后，「这个组里有哪些状态」和「清除指定状态 → 选组」的下拉都要重新求值
		Raise("GroupPowerRows");
		Raise("GroupAudioRows");   // V0.2.265：音频那一列同理
		Raise("PowerGroupChoices");
	}

	private readonly List<ParamSpec> _paramHooked = new();
	private readonly List<CardGroupSpec> _groupHooked = new();

	private void OnParamSpecChanged(object? sender, PropertyChangedEventArgs e)
	{
		Raise("ParamSummaryRows");
		Raise("ParamGrantChoices");
		Raise("ParamNameWarnText");
		Raise("ParamChoices");
		if (e.PropertyName is "Source" or "") Raise("ParamSourceHint");
	}

	private void OnGroupSpecChanged(object? sender, PropertyChangedEventArgs e)
	{
		Raise("GroupCardRows");
		Raise("CardGroupRows");
		Raise("CardGroupChoices");
		// 组名改了 → 「组：XXX」那几条候选的显示文字跟着变"
		Raise("SpawnFilters");
		Raise("CardFilterOptions");   // 「只对哪类牌生效」里也有「组：XXX」那几条（V0.2.118）"
		Raise("ScrapeConds");
		// V0.2.257：组名改了 → 「清除指定状态 → 或者清空一个组」下拉里的文字跟着变；
		// 组的 PowerIds 变了 → 右边那个状态勾选列表重算（勾上 / 取消立刻反映）
		Raise("PowerGroupChoices");
		Raise("GroupPowerRows");
		Raise("GroupAudioRows");   // V0.2.265：组的 AudioIds 变了 → 音频勾选列表重算
	}

	/// <summary>
	/// 本体关键词改名：把 7 行补齐（本体关键词是封闭枚举，不能增删），并监听每一行 ——
	/// 改了名字/说明之后要刷新那一节下面的实时说明（否则界面上那句「会把 N 条文案换掉」永远不动）。
	/// 每次换存档都会重新挂钩，所以老的处理器会先全部摘掉，避免重复订阅（重复订阅只是多跑几次，不致命，
	/// 但会让自检里的计数和实际不符）。
	/// </summary>
	private void EnsureKeywordRenameRows()
	{
		foreach (var old in _keywordRenameHooked)
			old.PropertyChanged -= OnKeywordRenameChanged;
		_keywordRenameHooked.Clear();

		ProfileFactory.EnsureKeywordRenameRows(_profile);
		foreach (var row in _profile.KeywordRenames)
		{
			row.PropertyChanged += OnKeywordRenameChanged;
			_keywordRenameHooked.Add(row);
		}
		Raise("KeywordRenameHint");
	}

	private void OnKeywordRenameChanged(object? sender, PropertyChangedEventArgs e)
	{
		// 改名字/说明都要重算那句提示（换关键词时 Specification 也会同时通知 VanillaName）
		Raise("KeywordRenameHint");
	}

