	/// <summary>
	/// 「…」菜单里到底有哪些条目（**纯数据**，自检直接钉它，不用真弹菜单）。
	/// Group = 分组标题（空 = 普通条目）；Id 是插进公式框的文本。
	///
	/// 顺序就是界面顺序：卡牌专用读数 → X / Y → 自定义参数 → 其余内置读数。
	/// 用户报「怎么没看到 ThisCardBlock / ThisCardExhaust …」以后，卡牌专用那一组**必须排第一**。
	/// </summary>
	public static List<(string Group, string Id, string Header)> FormulaInsertItems(CharacterProfile profile)
	{
		var list = new List<(string Group, string Id, string Header)>();
		var cardOnly = FormulaBuiltins.All.Where(b => b.CardOnly).ToList();
		if (cardOnly.Count > 0)
		{
			const string g = "这张牌这一次打出（只能用在卡牌上）";
			foreach (var b in cardOnly) list.Add((g, b.Id, $"{b.Id} — {b.Display}"));
		}
		list.Add(("特殊变量 X / Y", "X", "X — 打出这张牌那一刻的当前能量"));
		list.Add(("特殊变量 X / Y", "Y", "Y — 当前额外资源量"));
		var pars = (profile?.CustomParams ?? new System.Collections.ObjectModel.ObservableCollection<ParamSpec>())
			.Select(p => ParamNames.Normalize(p.Name)).Where(n => n.Length > 0).Distinct().ToList();
		foreach (string name in pars) list.Add(("自定义参数（当前存档）", name, name));
		const string allGroup = "内置实时读数（所有链都能用）";
		foreach (var b in FormulaBuiltins.All.Where(b => !b.CardOnly)) list.Add((allGroup, b.Id, $"{b.Id} — {b.Display}"));
		return list;
	}

	/// <summary>把 <see cref="FormulaInsertItems"/> 铺成菜单（分组标题置灰 + 分隔线）。</summary>
	public void InsertFormulaParamInto(Button btn)
	{
		if (btn is null) return;
		var box = btn.Tag as TextBox ?? FindFormulaBoxFor(btn);
		if (box is null) { SetStatus("没找到要填的那个公式框（界面刚变过？重开这个页面再试）。"); return; }
		if (FormulaBuiltinRows.Count == 0) { SetStatus("内置读数清单是空的（本体数据没读到），只能手写参数名。"); return; }
		var menu = new ContextMenu { PlacementTarget = btn };
		string? lastGroup = null;
		foreach (var (group, id, header) in FormulaInsertItems(Profile))
		{
			if (!string.Equals(group, lastGroup, StringComparison.Ordinal))
			{
				if (lastGroup is not null) menu.Items.Add(new Separator());
				if (group.Length > 0) menu.Items.Add(new MenuItem { Header = group, IsEnabled = false });
				lastGroup = group;
			}
			string text = id;
			var item = new MenuItem { Header = header };
			item.Click += delegate { InsertFormulaText(box, text); };
			menu.Items.Add(item);
		}
		menu.IsOpen = true;
	}

	/// <summary>按钮 Tag 没绑上时（例如模板里 ElementName 没解析到）退回「视觉树里最近的那个可编辑公式框」。</summary>
	private static TextBox? FindFormulaBoxFor(DependencyObject start)
	{
		// 按钮本身没子节点 → 从它的父级往下找第一个 TextBox（同一行里那个公式框）
		DependencyObject? cur = System.Windows.Media.VisualTreeHelper.GetParent(start);
		for (int guard = 0; guard < 6 && cur is not null; guard++)
		{
			if (cur is TextBox direct) return direct;
			var found = FindChildTextBox(cur);
			if (found is not null) return found;
			cur = System.Windows.Media.VisualTreeHelper.GetParent(cur);
		}
		return null;
	}

	private static TextBox? FindChildTextBox(DependencyObject root)
	{
		int n = System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < n; i++)
		{
			var child = System.Windows.Media.VisualTreeHelper.GetChild(root, i);
			if (child is TextBox tb && !tb.IsReadOnly) return tb;
			var nested = FindChildTextBox(child);
			if (nested is not null) return nested;
		}
		return null;
	}

	/// <summary>把一段名字插到光标处（公式框用；和自定义描述那个 <see cref="InsertAtCaret"/> 分开，免得混用占位符）。</summary>
	private static void InsertFormulaText(TextBox box, string text)
	{
		int at = box.CaretIndex < 0 ? box.Text.Length : box.CaretIndex;
		box.Text = box.Text.Insert(at, text);
		box.CaretIndex = Math.Min(box.Text.Length, at + text.Length);
		box.Focus();
	}

	/// <summary>
	/// 「填入参数…」：把这条模型能用的数值占位符插进自定义描述里（用户要求）。
	///
	/// 候选来自 <see cref="CSharpCodeGen.ParamHints"/>（只列这条模型**真的声明过**的动态变量）：
	/// 卡牌给 <c>{Damage:diff()}</c> 这种（升级后显示升级值），遗物 / 药水给 <c>{Damage}</c>。
	/// 一个候选就直接插，多个弹一个菜单让你挑。
	/// </summary>
	private void OnInsertParam(object sender, RoutedEventArgs e)
	{
		if (sender is not Button btn || btn.Tag is not TextBox box) return;
		string which = box.Name;
		IEnumerable<EffectSpec>? effects = which switch
		{
			"RelicCustomDesc" => (RelicList?.SelectedItem as RelicSpec)?.Effects,
			"PotionCustomDesc" => (PotionList?.SelectedItem as PotionSpec)?.Effects,
			_ => ActivePortraitCard()?.Effects,
		};
		bool isCard = which is not ("RelicCustomDesc" or "PotionCustomDesc");
		var hints = CSharpCodeGen.ParamHints(effects ?? Enumerable.Empty<EffectSpec>(), isCard);
		// ⚠ V0.2.130：原来这里给卡牌多塞三个「牌堆实时张数」占位符
		//   （{DrawPile} / {DiscardPile} / {ExhaustPile}，配「卡面显示牌堆张数」那个勾选框）。
		//   用户要求整块去掉 → 那三个候选、那句「先去勾它」的提示、以及那个勾选框一起删了。
		if (hints.Count == 0)
		{
			SetStatus("这条还没有能填的数值参数：先给它加一条带数值的效果（伤害 / 格挡 / 抽牌 / 状态层数…）。");
			return;
		}
		if (hints.Count == 1) { InsertAtCaret(box, hints[0].Token); return; }
		var menu = new ContextMenu { PlacementTarget = btn };
		foreach (var (token, desc) in hints)
		{
			var item = new MenuItem { Header = $"{token} — {desc}" };
			item.Click += delegate { InsertAtCaret(box, token); };
			menu.Items.Add(item);
		}
		menu.IsOpen = true;
	}

	/// <summary>
	/// 「自动填入」：把这张牌**自动生成的那段描述**填进自定义描述框（锻造卡=从节点图写出来的那句）。"
	/// 用户要求：「给卡牌的自定义描述加个自动填入」。"
	///
	/// ⚠ 填完会顺手勾上「替换掉自动生成的描述」：不勾的话卡面上会变成「自动那段 + 你填的这段」—— 
	/// 而这一段本来**就是**自动那段，等于同一句话印两遍。"
	/// </summary>
	private void OnAutoFillCardDesc(object sender, RoutedEventArgs e) => AutoFillCardDesc(sender, upgraded: false);

	/// <summary>
	/// 「自动填入（升级后）」：填**升级后**那一版（锻造卡 = 升级后那张布的文案）。"
	/// 用户要求：「在锻造卡的卡牌自定义描述加一个能够填入卡牌升级后的自定义描述」。"
	/// </summary>
	private void OnAutoFillCardUpgradedDesc(object sender, RoutedEventArgs e) => AutoFillCardDesc(sender, upgraded: true);

	private void AutoFillCardDesc(object sender, bool upgraded)
	{
		if (sender is not Button btn || btn.Tag is not TextBox box) return;
		var card = ActivePortraitCard();
		if (card is null) { SetStatus("先在左边选一张卡」"); return; }
		string auto = LocalizationGen.CardAutoText(Profile, card, upgraded);
		if (auto.Length == 0)
		{
			SetStatus(upgraded
				? "这张牌**升级后**没有自动描述可填（升级后那张带 / 那套效果是空的）—— 想写就自己写一段。"
				: "这张牌没有自动描述可填（效果栏 / 节点图都是空的）—— 想写就自己写一段。");
			return;
		}
		box.Text = auto;
		// 见方法注释：这一段本来就是「自动描述」，不勾替换会印两遍
		bool turnedOn = false;
		if (!card.CustomDescriptionReplaces) { card.CustomDescriptionReplaces = true; turnedOn = true; }
		SetStatus($"已把{(upgraded ? "升级后" : "")}自动描述填进「{(upgraded ? "升级后的" : "")}自定义描述」"
			+ (turnedOn ? "（顺手勾上了「替换掉自动生成的描述」—— 不勾的话卡面上会和自动那段重复一遍）" : "")
			+ $"，现在可以随意改。\n自动描述：{auto.Replace("\n", " / ")}");
	}
	private static void InsertAtCaret(TextBox box, string token)
	{
		string text = box.Text ?? "";
		int at = Math.Clamp(box.SelectionStart, 0, text.Length);
		int len = Math.Clamp(box.SelectionLength, 0, text.Length - at);
		box.Text = text.Remove(at, len).Insert(at, token);
		box.SelectionStart = at + token.Length;
		box.SelectionLength = 0;
		box.Focus();
	}

