	private void OnAddAncientRow(object sender, RoutedEventArgs e)
	{
		var effect = CurrentEditEffect;
		if (effect is null || !effect.IsAncientTranscend) return;
		// 默认挑一个**还没用过**的组，免得新加的行和上一行一样（用户自己改也行）
		var used = new HashSet<string>(effect.AncientRows.Select(r => r.Group), StringComparer.Ordinal);
		var next = AncientGroupChoices.FirstOrDefault(g => !used.Contains(g.Id));
		effect.AncientRows.Add(new AncientTranscendRow { Group = next?.Id ?? "" });
		_ancientEditRow = effect.AncientRows.Count - 1;
		Raise("AncientRowItems");
		Raise("AncientCardRows");
		Raise("AncientRowHint");
		SetStatus("已加一行配对：左边选「组」，右边勾要换成的先古卡」");
	}

	private void OnRemoveAncientRow(object sender, RoutedEventArgs e)
	{
		var effect = CurrentEditEffect;
		if (effect is null || !effect.IsAncientTranscend) return;
		int idx = (sender as FrameworkElement)?.DataContext is AncientRowItem item ? item.Index : -1;
		if (idx < 0 || idx >= effect.AncientRows.Count) return;
		effect.AncientRows.RemoveAt(idx);
		if (_ancientEditRow >= effect.AncientRows.Count) _ancientEditRow = Math.Max(0, effect.AncientRows.Count - 1);
		Raise("AncientRowItems");
		Raise("AncientCardRows");
		Raise("AncientRowHint");
	}

	/// <summary>点某一行的「组」下拉 = 把那一行设成「当前在配先古卡池的那一行」。 /summary>
	internal void MarkAncientEditRow(int index)
	{
		if (_ancientEditRow == index) return;
		_ancientEditRow = index;
		Raise("AncientCardRows");
	}

	/// <summary>某一行的「组」下拉展开：先把「当前在配的行」切到它，再刷下面那排先古卡勾选框」 /summary>
	private void OnAncientRowDropDownOpened(object sender, EventArgs e)
	{
		if ((sender as FrameworkElement)?.DataContext is AncientRowItem item) MarkAncientEditRow(item.Index);
		else RefreshAncientRows();
	}

	/// <summary>配对表 / 先古卡池里的勾选变了：重刷小结与提示。 /summary>
	internal void RefreshAncientRows()
	{
		Raise("AncientRowItems");
		Raise("AncientCardRows");
		Raise("AncientRowHint");
	}

	/// <summary>选中的效果换了 / 换了遗物：配对表整个重刷（并把「当前在配第几行」摆回第一行）。 /summary>
	private void OnRelicEffectSelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		_ancientEditRow = 0;
		Raise("AncientRowItems");
		Raise("AncientCardRows");
		Raise("AncientRowHint");
	}

	// ==================== 遗物的「触发时机列表」（第 10 批；V0.2.126 起时机只管「什么时候触发」） ====================
	//
	// 用户原话（V0.2.126）：「中间的触发时机并不是每条各配效果，而是决定整只遗物的触发时机，
	// 只有同时满足或者满足其中一个才能触发遗物的效果，另外效果右侧应能添加多个效果种类」。
	// 所以现在的结构是：遗物 = **一份效果**（右栏效果栏，RelicSpec.Effects）+ **一组触发时机**
	// （中间栏列表，每条只有 种类 / 盯哪个状态 / 数值 / 统计范围 / 只对哪类牌生效）。
	// 关系（任意一条 / 全部满足）在**中间栏上面那个开关**上（RelicSpec.TriggerMode）。

	/// <summary>选中某条遗物触发时机：给「重置范围」兜一下主人（列表增删时 RelicSpec 会自动挂）。</summary>
	private void OnRelicTriggerSelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		// 「重置范围」存在整只遗物上（RelicSpec.AndScope），触发时机自己靠 OwnerRelic 读它 ——
		// 老存档 / 从工程恢复的时机可能没挂上，这里再兜一次
		if (RelicTriggerList?.SelectedItem is RelicTriggerSpec sel && RelicList?.SelectedItem is RelicSpec owner)
			sel.OwnerRelic = owner;
		Raise("RelicTriggerSummary");
	}

	/// <summary>
	/// 「添加触发时机」：新的一条默认「每回合开始时」（效果是遗物那一份，这里不再塞效果）。
	/// </summary>
	private void OnAddRelicTrigger(object sender, RoutedEventArgs e)
	{
		if (!(RelicList.SelectedItem is RelicSpec relic))
		{
			SetStatus("请先在上面选中一只遗物。");
			return;
		}
		var trig = new RelicTriggerSpec { Kind = "PlayerTurnStart" };
		relic.Triggers.Add(trig);       // RelicSpec 会自动把 OwnerRelic 挂上
		if (RelicTriggerList is not null) RelicTriggerList.SelectedItem = trig;
		Raise("RelicTriggerSummary");
		SetStatus("已给这只遗物加了一条触发时机（默认「每回合开始时」，在下面改）；触发后做什么在右边效果栏里配。");
	}

	/// <summary>「删除触发时机」：支持 Ctrl / Shift 多选一次删掉多条。</summary>
	private void OnRemoveRelicTrigger(object sender, RoutedEventArgs e)
	{
		if (!(RelicList.SelectedItem is RelicSpec relic))
		{
			SetStatus("请先在上面选中一只遗物。");
			return;
		}
		List<RelicTriggerSpec> picked = SelectedOf<RelicTriggerSpec>(RelicTriggerList);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的触发时机（可 Ctrl/Shift 多选）。");
			return;
		}
		// 至少留一条：全删光的话这只遗物就没有触发时机了（生成出来什么都不做，用户会以为坏了）
		if (picked.Count >= relic.Triggers.Count)
		{
			SetStatus("至少得留一条触发时机（想让它什么都不做请直接删掉这只遗物）。");
			return;
		}
		string what = picked.Count == 1 ? "「" + picked[0].Summary + "」这条触发时机" : $"选中的 {picked.Count} 条触发时机";
		if (Confirm($"确定删掉{what}吗？", "确认删除"))
		{
			int value = RemoveManyWithUndo(relic.Triggers, picked, _relicUndo, "触发时机", delegate
			{
				if (RelicTriggerList is not null) RelicTriggerList.SelectedItem = picked[0];
			});
			Raise("RelicTriggerSummary");
			SetStatus($"已删除 {value} 条触发时机（可点「撤回删除」恢复）。");
		}
	}

	/// <summary>遗物页那句「这只遗物配了哪些时机」的汇总（改了时机 / 效果就重算）。</summary>
	public string RelicTriggerSummary
	{
		get
		{
			if (!(RelicList?.SelectedItem is RelicSpec r)) return "";
			var list = r.Triggers.Where(t => t is not null).ToList();
			if (list.Count == 0) return "这只遗物还没有触发时机。";
			return $"这只遗物有 {list.Count} 条触发时机：" + string.Join("；", list.Select(t => t.Summary));
		}
	}

