	// ===== V0.2.240：小屏幕适配（用户反馈「有一些人的屏幕小，就会发生有一些地方被遮挡」）=====
	//
	// 三件事一起做，缺一件都还会被裁：
	//   ① 启动时把窗口**压进屏幕可用区域**（WorkArea，扣掉任务栏）—— 以前写死 1420×880，
	//      在 1366×768 / 1280×720 这类屏上，右边和下边直接被屏幕边切掉（截图里效果编辑区那一截就是这么没的）；
	//   ② 再按屏幕大小自动挑一个**整窗缩放**档（LayoutTransform，布局跟着缩、文字不糊）；
	//   ③ 顶栏留一个「界面缩放」下拉，用户随时能手动改，选过的值记在
	//      %LOCALAPPDATA%\Sts2CharForge\ui-scale.txt（没有写权限就静默跳过，不影响启动）。
	//
	// 为什么不用 RenderTransform：它只改绘制、不改布局 —— 内容仍按原尺寸参与测量，于是依然被裁，
	// 而且文字会被拉伸糊掉。LayoutTransform 会让布局按缩放后的尺寸重新排，这才是「小屏能看全」。

	/// <summary>整窗缩放档位（百分数）。下拉框里展示的就是这些。</summary>
	public static readonly int[] UiScalePercents = { 60, 70, 75, 80, 90, 100, 110, 125 };

	/// <summary>按屏幕可用区域挑一档缩放（纯函数，自检直接钉它）。</summary>
	public static int AutoUiScaleFor(double workWidth, double workHeight)
	{
		// 高度是主要矛盾（工具是「左边列表 + 右边编辑区」的竖向布局），先按高度定档
		int percent = workHeight >= 900 ? 100
			: workHeight >= 800 ? 90
			: workHeight >= 700 ? 80
			: workHeight >= 620 ? 75
			: 70;
		// 特别窄的屏（< 1300）再降一档：左栏固定 380、右栏编辑区本来就挤
		if (workWidth < 1300 && percent > 80) percent = 80;
		return Math.Clamp(percent, UiScalePercents[0], UiScalePercents[^1]);
	}

	/// <summary>缩放配置文件（手动选过就记下来；读不到 / 写不了都不报错）。</summary>
	private static string UiScaleFilePath => Path.Combine(
		Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Sts2CharForge", "ui-scale.txt");

	private static int LoadSavedUiScale()
	{
		try
		{
			if (!File.Exists(UiScaleFilePath)) return 0;
			return int.TryParse(File.ReadAllText(UiScaleFilePath).Trim(), out int v) ? v : 0;
		}
		catch { return 0; }
	}

	private static void SaveUiScale(int percent)
	{
		try
		{
			string dir = Path.GetDirectoryName(UiScaleFilePath)!;
			Directory.CreateDirectory(dir);
			File.WriteAllText(UiScaleFilePath, percent.ToString(System.Globalization.CultureInfo.InvariantCulture));
		}
		catch { /* 没权限就只在本进程里生效，不值得打扰用户 */ }
	}

	/// <summary>把一个缩放档应用到整窗（同时把下拉框的选中项对齐，不触发递归）。</summary>
	public void ApplyUiScale(int percent)
	{
		percent = Math.Clamp(percent, UiScalePercents[0], UiScalePercents[^1]);
		double s = percent / 100.0;
		if (RootPanel is not null) RootPanel.LayoutTransform = new ScaleTransform(s, s);
		if (UiScaleBox is not null && !_uiScaleBoxSyncing)
		{
			_uiScaleBoxSyncing = true;
			try
			{
				string want = percent + "%";
				if (UiScaleBox.Items.Contains(want)) UiScaleBox.SelectedItem = want;
				else UiScaleBox.SelectedIndex = Array.IndexOf(UiScalePercents, percent);
			}
			finally { _uiScaleBoxSyncing = false; }
		}
		_uiScalePercent = percent;
	}

	private bool _uiScaleBoxSyncing;
	private int _uiScalePercent = 100;

	/// <summary>当前生效的整窗缩放（百分数，自检用）。</summary>
	public int UiScalePercent => _uiScalePercent;

	/// <summary>启动时把窗口塞进屏幕可用区域，并按屏幕大小选一档缩放。</summary>
	public void FitWindowToScreen()
	{
		Rect work = SystemParameters.WorkArea;
		// ① 窗口尺寸压进可用区域（留 16px 余量给窗口边框 / 阴影）
		double maxW = Math.Max(MinWidth, work.Width - 16);
		double maxH = Math.Max(MinHeight, work.Height - 16);
		if (Width > maxW) Width = maxW;
		if (Height > maxH) Height = maxH;
		// 屏比 MinWidth/MinHeight 还小时最大化，至少把任务栏那块地方用上
		if (work.Width <= 1000 || work.Height <= 640) WindowState = WindowState.Maximized;
		// ② 缩放：用户手动选过就用他的，否则按屏幕自动挑
		int saved = LoadSavedUiScale();
		ApplyUiScale(saved > 0 ? saved : AutoUiScaleFor(work.Width, work.Height));
	}

	/// <summary>顶栏「界面缩放」下拉：手动改（并记住）。</summary>
	private void OnUiScaleChanged(object sender, SelectionChangedEventArgs e)
	{
		if (_uiScaleBoxSyncing) return;
		if (UiScaleBox?.SelectedItem is not string s) return;
		if (!int.TryParse(s.TrimEnd('%'), out int percent)) return;
		ApplyUiScale(percent);
		// 自检里不要往真实用户目录写文件（和 SuppressProfileWrites 同一套约定）
		if (!SuppressProfileWrites) SaveUiScale(percent);
	}

	public MainWindow()
	{
		InitializeComponent();
		// V0.2.240：先把窗口压进屏幕、挑好缩放档（必须在其它初始化之前 —— 后面很多地方按控件实际宽度算排版）
		try
		{
			UiScaleBox.ItemsSource = UiScalePercents.Select(p => p + "%").ToList();
			FitWindowToScreen();
		}
		catch { /* 缩放只是适配手段，出问题也不能挡住启动 */ }
		// V0.2.140：三个卡牌列表页（卡牌 / 诅咒卡 / 先古卡）的界面镜像集合（真卡 + 末尾空槽行）。
		// ⚠ 必须**最早**建：下面的 RefreshAll / BuildAncientRows / HookCardCount 中途就可能调到
		// RefreshCardOrdinals / OnCardsChanged / SyncDetail，那些路径都要往镜像里写。
		InitCardRowMirrors();
		// 标题带上版本号（和整合包 / 启动器用的是同一个版本号：App.csproj 里的 InformationalVersion）
		Title = $"Sts2CharForge {AppVersion.Current} —— 杀戮尖塔2 自定义角色生成器";
		BuildArtSlots();
		BuildAnimSlots();
		HookAnimationSpec();
		BuildAncientRows();
		PresetItems = CardColorSpec.Presets.Select((CardColorSpec.Preset pz) => new PresetItem(pz, pz.Name)).Append(_customPreset).ToList();
		FrameItems = CardColorSpec.Frames.Select((string f) => new FrameItem(f, f)).Append(_customFrame).ToList();
		// 「诅咒 / 先古卡」页那两个下拉：第一项是「跟角色配色（默认）」，其余和上面的框色一样。
		// 复用同一个 _customFrame 实例，自检里就能用引用比较认出「自定义」。
		SpecialFrameItems = new[] { _followRoleFrame }.Concat(FrameItems).ToList();
		// 诅咒那一栏**没有「自定义」**（用户要求去掉诅咒的自定义颜色选项）：
		// 只给「跟角色配色（默认）」+ 本体的框色名。
		CurseFrameItems = new[] { _followRoleFrame }
			.Concat(FrameItems.Where((FrameItem i) => i.Value is not null)).ToList();
		HookProfileColors();
		// 启动时那份配置也要先把「本体关键词改名」的 7 行补齐（Profile 的 setter 只在换存档时跑）
		EnsureKeywordRenameRows();
		RecheckEnvironment();
		string text = MigrateLegacyProfileFolder();
		NormalizeOutputDir();
		base.DataContext = this;
		ReloadCatalog();
		RefreshAll();
		RefreshProfiles();
		// 遗物列表的「序号」（用户要求第 2 条）：载入存档后先算一遍，
		// 并挂上 CollectionChanged —— 之后任何增删（撤回删除 / 导入 / 自检造数据）都会自动重排
		HookRelicListOrder();
		// 药水列表同理（V0.2.127：药水照抄遗物页的序号 + 空槽 + 拖动）——
		// ⚠ 启动这条路径**不走 Profile 的 setter**（上面 RefreshAll 用的是 _profile 字段），
		// 所以这里必须自己挂一次，否则 PotionRows 一直是空的（自检实测：镜像 0 行）。
		HookPotionListOrder();
		SyncPotionRows();
		// 卡牌三页同理（V0.2.140）：启动这条路径也不走 Profile 的 setter，
		// 镜像集合（CardRows / CurseRows / AncientRows）必须在这里自己铺一遍。
		SyncCardRowMirrors();
		// 换存档（`Raise("Profile")`）：两个界面镜像集合必须跟着新存档重铺一遍。
		//
		// ⚠ 为什么非要在**通知**上做，而不是只在 <see cref="Profile"/> 的 setter 里做：
		// 有几处历史自检是**直接给 `_profile` 字段赋值**再 `Raise("Profile")` 的（不走属性 setter），
		// 那种路径下 setter 里那两条重铺根本不会跑。
		// 以前这条链是被一个**副作用**兜住的：药水列表当时直接绑 `Profile.Potions`，
		// `Raise("Profile")` 一刷新绑定就把选中项打断 → `PotionList.SelectionChanged` → `SyncDetail()`
		// → `RefreshRelicOrdinals()` → `SyncRelicRows()` 的「挂错存档就重挂」自愈跑起来。
		// V0.2.127 把药水列表改成绑 `PotionRows` 镜像（不再绑 Profile.*）之后，那条副作用没有了 ——
		// 实测：「转化为先古卡」那组界面断言全红（RelicRows 还停在上一份存档的 5 只，选中的效果变成旧遗物的「获得格挡」）。
		// 所以把这个契约**显式**写出来：收到「Profile 换了」的通知就把两个镜像重铺一遍（幂等，重复调没副作用）。
		PropertyChanged += delegate(object? _, PropertyChangedEventArgs e)
		{
			if (e.PropertyName != "Profile") return;
			HookRelicListOrder();
			SyncRelicRows();
			HookPotionListOrder();
			SyncPotionRows();
			// V0.2.140：卡牌三页的镜像也不能漏（同一个理由 —— 直接给 _profile 字段赋值的路径不走 setter）
			SyncCardRowMirrors();
			Raise("HasCardSelection");
			Raise("HasCurseSelection");
			Raise("HasAncientSelection");
		};
		CardList.SelectionChanged += delegate
		{
			// 「详情栏显隐」看的是列表里有没有选中一行（含空槽行），它不在 CardUiSelection 的变化里，
			// 得单独通知一次（和遗物 / 药水页同一个套路）
			NoteCardRowsSelection(CardList, _cardMirror);
			Raise("HasCardSelection");
			// ⚠ 正在铺镜像集合（SyncCardRows）时**不要**再递归进 SyncDetail：那一次选中变化是
			// CardRows.Clear() / SelectedItem = null 自己引发的，外层那次 SyncDetail 会把该做的全做完；
			// 递归进去的坏处是**时机**（那一刻三页的镜像 / 选中都还在半路上，遗物页实测踩过）。
			if (_cardMirror.IsSyncing) return;
			// V0.2.165：卡牌页选中真卡 → 把「诅咒 / 先古 / 状态」三栏的选中清掉
			//（三处共用同一套卡面预览；不清的话切到先古页时预览还指着卡牌页那张，见 ClearSpecialCardSelections）
			if (CardUiSelection is not null) ClearSpecialCardSelections();
			SyncDetail();
			// 换卡之后「右边效果栏锁不键 / 中间费用栏显不显示」要跟着变（锻造卡都藏掉，需求）
			Raise("CardEffectsAreForged");
			Raise("CardEffectsEditable");
			Raise("CardCoreFieldsVisible");
		};
		CurseList.SelectionChanged += delegate
		{
			// 诅咒页（V0.2.140 起也有空槽行）：选中变化 → 重认一次真诅咒 + 刷新显隐
			NoteCardRowsSelection(CurseList, _curseMirror);
			_curseMirror.RefreshUiSelection();
			Raise("HasCurseSelection");
		};
		AncientCardList.SelectionChanged += delegate
		{
			// 先古卡那一栏同理
			NoteCardRowsSelection(AncientCardList, _ancientMirror);
			_ancientMirror.RefreshUiSelection();
			Raise("HasAncientSelection");
		};
		RelicList.SelectionChanged += delegate
		{
			// 「详情栏显隐」看的是列表里有没有选中一行（含空槽行），它不在 RelicUiSelection 的变化里，
			// 得单独通知一次
			Raise("HasRelicSelection");
			SyncDetail();
		};
		PotionList.SelectionChanged += delegate
		{
			// 「详情栏显隐」看的是列表里有没有选中一行（含空槽行），它不在 PotionUiSelection 的变化里，得单独通知一次
			Raise("HasPotionSelection");
			// ⚠ 正在铺镜像集合（SyncPotionRows）时**不要**再递归进 SyncDetail：
			// 那一次选中变化是 PotionRows.Clear() / SelectedItem = null 自己引发的，外层那次 SyncDetail
			// 会把该做的（数据上下文 / 效果列表绑定 / 显隐）全做完。递归进去的坏处是**时机**：
			// 那一刻遗物页的镜像集合还没铺完（RelicUiSelection 还是上一份存档的那只），
			// 这一层会把 RelicEffectList 的数据源绑到**旧遗物**身上 —— 实测踩到：「转化为先古卡」
			// 那一组界面断言全红（选中的效果变成了旧遗物的「获得格挡」）。
			if (_inSyncPotionRows) return;
			SyncDetail();
		};
		// 「自定义关键词」和「召唤物」两个列表也必须接上 —— 详情是「换选中项 → 重新指向新对象」，
		// 漏了这两行时详情会**卡在第一次选中的那条上**：在第二条里打字会写进第一条、
		// 图片预览一直显示上一只（用户实测报过：「第一个输入框打不进字、第二个的内容跑到第一个」）。
		KeywordList.SelectionChanged += delegate
		{
			SyncDetail();
		};
		SummonList.SelectionChanged += delegate
		{
			SyncDetail();
		};
		// 新增的两页：「自定义参数 / 组」与「锻造」"
		ParamList.SelectionChanged += OnParamSelectionChanged;
		GroupList.SelectionChanged += OnGroupSelectionChanged;
		GroupCardList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("GroupCardRows") { Source = this });
		ForgeItemList.SelectionChanged += delegate
		{
			SyncForgeDetail();
		};
		ForgeItemList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("ForgeVisible") { Source = this });
		// 节点图那块布：改了图（加模块 / 连线 / 拖动）之后刷新说明与问题列表
		ForgeCanvas.Changed += delegate
		{
			Raise("ForgeGraphTabHint");
			RefreshIssues();
		};
		// 积木编辑器：拖块 / 加块 / 删块都会把树写回图（只重建连线，节点还是同一批）。"
		// 写完把节点图也重画一遍，让「节点图 → 积木」两个视图看到的是同一块布。"
		ForgeBlocks.Changed += delegate
		{
			ForgeCanvas?.Rebuild();
			Raise("ForgeGraphTabHint");
			RefreshIssues();
		};
		// 锻造页左上角那四个分类单选：**在 XAML 里不按 Checked**（解析到一半就会触发，后面的控件还没造出来），"
		// 等所有控件都在了再挂。"
		// V0.2.194 起多了第五个「状态列表」（Power）—— 挂法一模一样，晚了 XAML 解析那一次就漏刷新。
		ForgeKindNone.Checked += OnForgeKindChanged;
		ForgeKindCard.Checked += OnForgeKindChanged;
		ForgeKindPotion.Checked += OnForgeKindChanged;
		ForgeKindRelic.Checked += OnForgeKindChanged;
		ForgeKindPower.Checked += OnForgeKindChanged;
		// 所有控件都造好了：这一页现在可以安全刷新 
		_uiReady = true;
		RefreshForgeList();
		SetStatus(text ?? "就绪。填好配置 → 「① 生成工程」→「② 一键构建 + 安装」。");
	}

	private void SyncDetail()
	{
		// 遗物页：先把「序号 / 空槽行」铺一遍（换存档 / 载入后 RelicRows 要跟着新 Profile 走），
		// 再认一遍「当前界面上选中的是哪只真遗物」（选中项可能已经被删 / 被撤回删除换了对象）
		RefreshRelicOrdinals();
		RefreshRelicUiSelection();
		// 增删 / 撤回 / 换存档之后列表选中项可能自己变成 null（不是通过点击），显隐判据要重算一遍
		Raise("HasRelicSelection");
		// 药水页同理（V0.2.127）：序号 / 空槽行 + 「当前选中的是哪瓶真药水」
		RefreshPotionOrdinals();
		RefreshPotionUiSelection();
		Raise("HasPotionSelection");
		// 卡牌页（V0.2.130 左侧序号；V0.2.140 每 5 个一块 + 空槽带灰色序号，三页都做）：
		// 先把三个镜像铺一遍（真卡 1..N + 末尾空槽），再算位置号，最后认一遍「当前选中的真卡是哪张」。
		SyncCardRowMirrors();
		RefreshCardOrdinals();
		_cardMirror.RefreshUiSelection();
		_curseMirror.RefreshUiSelection();
		_ancientMirror.RefreshUiSelection();
		Raise("HasCardSelection");
		Raise("HasCurseSelection");
		Raise("HasAncientSelection");
		CardDetail.DataContext = CardUiSelection;
		RelicDetail.DataContext = RelicUiSelection;
		PotionDetail.DataContext = PotionUiSelection;
		KeywordDetail.DataContext = KeywordList.SelectedItem;
		Raise("CustomKeywordRows");
		// V0.2.136：「自定义关键词 · 升级后获得 / 失去」两栏 + 底下那行小结
		Raise("UpgradeAddedKeywordRows");
		Raise("UpgradeRemovedKeywordRows");
		Raise("UpgradeCustomKeywordHint");
		Raise("KeywordChoices");
		// 需求 ⑦：「生成出来的卡加上关键词」的下拉与自定义关键词注册联动（同源的那一份候选）
		Raise("SpawnKeywordChoices");
		// V0.2.220：「为抽到的牌加关键词」那个下拉和上面同源
		Raise("DrawnKeywordChoices");
		// 关键词改了名字 / 加了删了 → 「范围限定」里那一组选项跟着变（生成 / 变化卡牌能只从这一组里出牌）
		RefreshCustomKeywordRegistry();
		Raise("HasCustomKeywords");
		Raise("NoCustomKeywords");
		Raise("SelectedCardUpgradeCost");
		Raise("UpgradeCostHint");
		Raise("UpgradeKeywordRows");
		// ⚠ V0.2.137：「高亮字段…」那行汇总已按用户要求撤掉（见 OnUpgradedCustomDescChanged 的说明）
		// 召唤物：图片预览 + 效果编辑器「召唤物（哪一只）」下拉的候选（只列已启用的）
		Raise("SelectedSummonImagePreview");
		RaisePetSummonChoices();
		// V0.2.140：三个卡牌列表页的 ItemsSource 改成**界面镜像集合**（真卡 + 末尾空槽行），
		// 所以在 XAML 里直接绑（CardRows / CurseRows / AncientRows），这里不再重绑 Profile.Cards ——
		// 免得每跑一次 SyncDetail 就把镜像换回真集合（遗物 / 药水页那两行还在，它们本来就绑镜像）。
		RelicList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("RelicRows") { Source = this });
		PotionList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("PotionRows") { Source = this });
		KeywordList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.CustomKeywords"));
		SummonList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.Summons"));
		CardEffectList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Effects"));
		// V0.2.126：遗物页的「触发时机列表」绑到当前选中遗物的 Triggers；
		// 效果列表绑的是**遗物那一份** Effects（和 RelicDetail 的 DataContext 一致，不随选中哪条时机变）。
		if (RelicUiSelection is RelicSpec selRelic)
		{
			if (selRelic.Triggers.Count == 0) selRelic.Triggers.Add(new RelicTriggerSpec());
			RelicTriggerList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Triggers") { Source = selRelic });
			if (RelicTriggerList.SelectedItem is null) RelicTriggerList.SelectedIndex = 0;
		}
		else
		{
			RelicTriggerList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Triggers"));
		}
		RelicTriggerList.SelectionChanged -= OnRelicTriggerSelectionChanged;
		RelicTriggerList.SelectionChanged += OnRelicTriggerSelectionChanged;
		OnRelicTriggerSelectionChanged(RelicTriggerList, new SelectionChangedEventArgs(ListBox.SelectionChangedEvent, new List<object>(), new List<object>()));
		Raise("RelicTriggerSummary");
		// 遗物的效果栏 = **整只遗物那一份**（RelicDetail 的 DataContext 就是 RelicSpec，裸 "Effects" 正好是它）
		RelicEffectList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Effects"));
		RelicEffectList.SelectionChanged -= OnRelicEffectSelectionChanged;
		RelicEffectList.SelectionChanged += OnRelicEffectSelectionChanged;
		PotionEffectList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Effects"));
		// 新增的两页：列表数据源 + 算出来的候选"
		ParamList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.CustomParams"));
		GroupList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.CardGroups"));
		GroupCardList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("GroupCardRows") { Source = this });
		Raise("CardGroupRows");
		Raise("NoCardGroups");
		Raise("CardGroupRowHint");
		Raise("ParamChoices");
		Raise("ParamGrantChoices");
		Raise("ParamSummaryRows");
		Raise("ParamNameWarnText");
		Raise("ParamSourceHint");
		RaiseGroupsChanged();
		RaiseCardPortrait();
		Raise("RelicIconPreview");
		// V0.2.199：药水图标预览也得跟着「换选中项」刷新。以前这里只有遗物那一行，
		// 于是「给第 1 瓶传了图标 → 点第 2 瓶」时，右下角那张预览图**还停在上一瓶**，
		// 看起来就像「上传的图标出现在每一瓶药水上」（用户实测报过）。
		// 预览框绑的是 Window.PotionIconPreview（RelativeSource=Window），换 DataContext 不会让它重读，
		// 必须显式发一次 PropertyChanged。
		Raise("PotionIconPreview");
		Raise("PotionIconHint");
	}

	/// <summary>
	/// 认一遍「界面上当前选中的那一只真遗物」：选中项是真遗物就跟着它；选中项是空槽行时**保持不变**
	/// （用户要的是「空槽不能被当成遗物」，不是「点一下空槽就把右边详情清空」）。
	///
	/// <para>⚠ 判据是 <c>is RelicSpec</c> 而不是 cast：空槽行 <c>SlotPlaceholder</c> 不是 <c>RelicSpec</c>
	/// —— 这一条就是「空槽不可能变成 RelicUiSelection / 污染 RelicSpec 相关逻辑」的保证；
	/// 配套的 <c>SelectedOf&lt;RelicSpec&gt;</c> / 全选里的 <c>IsPlaceholder</c> 跳过也是同一个道理。</para>
	/// </summary>
	private void RefreshRelicUiSelection()
	{
		if (RelicList?.SelectedItem is RelicSpec sel && _profile.Relics.Contains(sel))
		{
			RelicUiSelection = sel;
			return;
		}
		// 选中的不是真遗物（空槽行）或者本来是空选中：RelicUiSelection 只在「它指向的那只还在集合里」时留着，
		// 被删掉 / 换存档就清空 —— 这样「一只都没选（SelectedIndex = -1 / 点空白处）」时右侧详情照旧收起来。
		if (_relicUiSelection is not null && !_profile.Relics.Contains(_relicUiSelection)) RelicUiSelection = null;
	}

	/// <summary>
	/// 刷新卡面预览那一整块（图 / 比例说明 / 预览框尺寸 / 拉伸方式 / 上传按钮上的建议尺寸）。
	/// 为什么要一起通知：先古卡的显示区域是**竖的**（606×852 且游戏里直接拉满），
	/// 切换到先古卡时预览框、说明、上传提示都得跟着变（以前写死 1000×760，先古卡上的图会被拉变形）。
	/// </summary>
	private void RaiseCardPortrait()
