	}

	public async Task BuildForTestAsync(string? profilePath = null)
	{
		Stopwatch sw = Stopwatch.StartNew();
		string temp2 = Path.Combine(Path.GetTempPath(), "forge_buildtest");
		try
		{
			// ===== 先做隔离：把要测的存档【复制】到临时目录，再把它当成「当前存档」载入 =====
			// 为什么要这样：以前直接载入用户真实存档，构建过程中界面会静默保存（自动填路径等），
			// 结果把测试用的临时输出目录写进了用户的存档里，甚至会把工程生成到真实存档目录里
			// （实测踩过：用户的存档被改了 OutputDir、存档目录里多出一个 forge_build_snapshot 工程）。
			string? real = profilePath is { Length: > 0 } && File.Exists(profilePath)
				? profilePath
				: (Directory.Exists(ProfileFolder) ? Directory.GetFiles(ProfileFolder, "*.json").OrderByDescending(File.GetLastWriteTime).FirstOrDefault() : null);
			Directory.CreateDirectory(temp2);
			if (real is not null)
			{
				string copy = Path.Combine(temp2, Path.GetFileName(real));
				FsSafe.Copy(real, copy, true);
				OverrideProfileFolderForTest(temp2);        // 之后所有静默保存都只写临时目录
				LoadProfileCore(copy);                       // 当前存档 = 临时副本
			}
		}
		catch
		{
		}
		string text2 = Path.Combine(temp2, "out");
		Profile.Paths.OutputDir = text2;
		Profile.Paths.InstallDir = Path.Combine(text2, "install");
		// 关键：载入存档之后要按它的路径重载效果库（界面正常流程是 LoadProfileCore 做的），
		// 否则效果库还是空的 → 校验直接报「效果库为空」→ 构建秒失败。
		ReloadCatalog();
		// 注意：ReloadCatalog 里会自动填路径（OutputDir 空 / 目录不存在时会被改成存档目录），
		// 所以这里必须【再设一次】，否则构建会生成到用户真实存档目录里去。
		Profile.Paths.OutputDir = text2;
		Profile.Paths.InstallDir = Path.Combine(text2, "install");
		RecheckEnvironment();
		RefreshAll();
		DispatcherTimer timer = new DispatcherTimer
		{
			Interval = TimeSpan.FromMilliseconds(200L, 0L)
		};
		timer.Tick += delegate
		{
			_uiTicks++;
		};
		timer.Start();
		await RunBuild(install: true);
		timer.Stop();
		sw.Stop();
		string value = (Directory.Exists(Profile.Paths.InstallDir) ? string.Join(", ", from f in Directory.GetFiles(Profile.Paths.InstallDir)
			select Path.GetFileName(f)) : "(空)");
		LastBuildTestReport = $"存档: {Profile.ModId}（卡牌 {Profile.Cards.Count} 张 / 遗物 {Profile.Relics.Count} / 药水 {Profile.Potions.Count}）{Environment.NewLine}构建总耗时: {sw.Elapsed.TotalSeconds:N1} 秒{Environment.NewLine}界面定时器刷新次数: {_uiTicks}  （构建期间界面是否卡死：{((_uiTicks > 10) ? "没有卡死 ✅" : "疑似卡死 ❌")}）{Environment.NewLine}状态栏: {StatusText}{Environment.NewLine}安装目录产物: {value}{Environment.NewLine}"
			+ "----- 构建日志（尾部）-----" + Environment.NewLine + BuildLogTail + Environment.NewLine;
		DumpLogTo(Path.Combine(AppContext.BaseDirectory, "buildtest_log.txt"));
		// 注意：这里【不要】Close()。
		// 以前 Close() 会在 DispatcherFrame 还压着的时候触发「关掉唯一窗口 → 程序退出」，
		// 结果 PushFrame 永远等不到 Continue，进程挂死、buildtest_result.txt 也写不出来（实测踩过）。
		// 退出交给 App.xaml.cs：写完结果文件后自己 Shutdown(0)。
	}

	private async Task RunBuild(bool install)
	{
		if (_buildBusy)
		{
			SetStatus("正在构建中，请稍候…（进度见「构建 · 日志」）");
		}
		else
		{
			if (!EnsureVanillaProject())
			{
				return;
			}
			string text = (_profile.Paths.InstallDir ?? "").Trim();
			if (!install || text.Length != 0)
			{
				if (install)
				{
					try
					{
						Directory.CreateDirectory(text);
					}
					catch (Exception ex)
					{
						Issues.Add("[错误] 安装目录不可用：" + ex.Message);
						SetStatus("安装目录不可用：" + text);
						return;
					}
				}
				_buildBusy = true;
				string title = "一键" + (install ? "构建 + 安装" : "构建");
				SetStatus(title + " 进行中…（界面不会卡，进度见右侧日志）");
				AppendLog("========== " + title + " 开始 ==========");
				IProgress<string> progress = new Progress<string>(AppendLog);
				CharacterProfile profile = _profile;
				CleanLeftoverSnapshotProject(profile);
				try
				{
					SyncArt();
					SyncAnim();   // 动画槽位和美术槽位一样：用之前先把界面上的值写回配置
					// 「自动编号的英文类名 / 关键词键」先固定下来、并把失效的引用修好 —— 必须在这里做
					// （快照之前）：留空类名时按位置编号，中间插 / 删一条会让后面的集体改名，
					// 而效果里存的是类名 / 键的字符串 → 引用失效或串到别的模型上（用户实测：每次构建都要手工重排）。
					// 修完顺手静默保存存档，这样「固定下来的名字」下次打开还在。
					try
					{
						var stab = NameStabilizer.Stabilize(profile, ModGenerator.ProjectRootOf(profile));
						foreach (string note in stab.Notes) AppendLog("  " + note);
						if (stab.Changed)
						{
							AppendLog($"已固定英文类名 / 关键词键并修好失效引用（{stab.Notes.Count} 处），存档已更新。");
							RefreshCardChoices();
							RefreshCustomKeywordRegistry();
							SaveCurrentProfileQuietly();
						}
					}
					catch (Exception ex) { AppendLog("[警告] 类名固定 / 引用修复失败（继续构建）：" + ex.Message); }
					CharacterProfile snapshot;
					try
					{
						// 关键：ProfileFactory.Save 会把 SaveName 改成文件名（= forge_build_snapshot）。
						// 那是**内存里那份配置**（profile 就是 _profile），改完工程目录名就变成
						// <输出目录>\forge_build_snapshot（很难看，而且和「工程目录=存档名」的约定不符）。
						// 所以先记下真实存档名，存完快照再还回去。
						string realSaveName = profile.SaveName;
						string path = Path.Combine(Path.GetTempPath(), "forge_build_snapshot.json");
						ProfileFactory.Save(profile, path);
						profile.SaveName = realSaveName;              // 把内存里那份改回来
						snapshot = ProfileFactory.Load(path);
						snapshot.SaveName = realSaveName;              // 工程目录名 = 真实存档名
					}
					catch
					{
						snapshot = profile;
					}
					string godotExe = profile.Paths.GodotExe;
					string dotnetExe = profile.Paths.DotnetExe;
					string installTo = (install ? text : null);
					(List<ValidationIssue>, BuildResult) tuple = await Task.Run(delegate
					{
						GenerationResult generationResult = ModGenerator.Generate(snapshot, progress.Report);
						if (!generationResult.Success)
						{
							return ((List<ValidationIssue> Issues, BuildResult Build))(Issues: generationResult.Issues, Build: null);
						}
						Naming naming = Naming.From(snapshot);
						// 工程目录要用「生成结果里那个真实目录」，不能自己拼 OutputDir\ModId：
						// 存档名和 ModId 不一样时（例：示例角色_恢复.json / ModId=示例角色）那个目录根本不存在，
						// dotnet 会报 MSB1009 项目文件不存在 → 界面显示「构建失败」（用户报的「构建无法生成」就是这个）。
						BuildResult item = ModBuilder.Build(generationResult.ProjectRoot, naming.ModId, godotExe, installTo, progress.Report, dotnetExe, _profile.Paths.GameDataDir);
						return (Issues: generationResult.Issues, Build: item);
					});
					Issues.Clear();
					foreach (ValidationIssue item2 in tuple.Item1)
					{
						Issues.Add(item2.ToString());
					}
					if ((object)tuple.Item2 == null)
					{
						SetStatus("生成失败（校验没通过），无法构建。原因见弹框 / 左下角问题列表。");
						ReportGenerateFailure(tuple.Item1);
						return;
					}
					foreach (BuildStepResult step in tuple.Item2.Steps)
					{
						AppendLog($"--- {step.Name} {(step.Success ? "OK" : "失败")} ---");
						AppendLog(step.Output.Trim());
					}
					SetStatus((!tuple.Item2.Success) ? "构建失败，详见日志。" : ((tuple.Item2.InstalledTo == null) ? "构建完成（未安装）。" : ("构建完成并已安装到 " + tuple.Item2.InstalledTo)));
					// 构建失败也要弹框写明「哪一步失败、报了什么」，只写一句「构建失败」等于没说
					if (!tuple.Item2.Success)
					{
						var failed = tuple.Item2.Steps.Where((BuildStepResult st) => !st.Success).ToList();
						var sb = new System.Text.StringBuilder();
						sb.AppendLine("构建失败了，出问题的是这几步：" + Environment.NewLine);
						foreach (BuildStepResult st in failed.Take(4))
						{
							sb.AppendLine("【" + st.Name + "】");
							var tail = (st.Output ?? "").Replace("\r\n", "\n").Split('\n')
								.Where((string l) => l.Trim().Length > 0).TakeLast(8);
							foreach (string l in tail) sb.AppendLine("   " + l.Trim());
							sb.AppendLine();
						}
						sb.AppendLine("完整日志在「构建 · 日志」页，可以点「导出日志」存成文件发我。");
						MessageBox.Show(this, sb.ToString(), "Sts2CharForge —— 构建失败的原因", MessageBoxButton.OK, MessageBoxImage.Warning);
					}
					return;
				}
				catch (Exception ex2)
				{
					AppendLog("[X] 构建过程发生异常：" + ex2);
					// 「拒绝访问」是用户自己机器上的文件问题（只读属性 / 被别的程序占用 / 目录权限），
					// 不是配置问题 —— 光给一页英文堆栈用户不知道该干什么，这里把「为什么 + 怎么办」也打出来"
					if (FsSafe.IsAccessProblem(ex2))
					{
						AppendLog("  上面这种「拒绝访间 / Access is denied」不是配置错了，是目标目录里的文件写不进去：");
						AppendLog(FsSafe.FixHint);
					}
					Issues.Add("[错误] 构建异常：" + ex2.Message);
					SetStatus("构建异常：" + ex2.Message + "（详情见日志）");
					return;
				}
				finally
				{
					_buildBusy = false;
					AppendLog("========== " + title + " 结束 ==========");
				}
			}
			SetStatus("请先填写「安装目录」（通常是游戏 mods 目录）。");
		}
	}

	/// <summary>
	/// 清掉早期版本留下的 `<输出目录>\forge_build_snapshot` 工程目录。
	/// 那时候「一键构建」用快照（SaveName = forge_build_snapshot）当配置去生成，
	/// 于是真实工程被生成到这个名字很怪的目录里；现在改成用存档名了，留着的旧目录顺手清掉
	/// （只删「确实是我们生成过的工程」：目录里有 project.godot）。
	/// </summary>
	private void CleanLeftoverSnapshotProject(CharacterProfile profile)
	{
		try
		{
			if (string.IsNullOrWhiteSpace(profile.Paths.OutputDir)) return;
			string stale = Path.Combine(profile.Paths.OutputDir, "forge_build_snapshot");
			if (stale == ModGenerator.ProjectRootOf(profile)) return;      // 就叫这个名字的存档，别动
			if (!Directory.Exists(stale)) return;
			if (!File.Exists(Path.Combine(stale, "project.godot"))) return;
			FsSafe.DeleteTree(stale);
			AppendLog("已清掉早期版本留下的临时工程目录：" + stale);
		}
		catch { }
	}

	/// <summary>
	/// 生成代码里 <c>CanonicalVars</c> 的动态变量键（和本体 DynamicVarSet 的规则一致：
	/// 有名字参数就用名字，没有就是类型默认名 —— PowerVar&lt;T&gt; 用 T，其余用类型名）。
	/// 用来断言「同一种变量不会重名」——重名会让本体抛异常、整场战斗卡死。
	/// </summary>
	private static List<string> VarKeysOf(string source)
	{
		var keys = new List<string>();
		foreach (System.Text.RegularExpressions.Match mVars in System.Text.RegularExpressions.Regex.Matches(source, @"CanonicalVars =>\s*\[(.*?)\];", System.Text.RegularExpressions.RegexOptions.Singleline))
			foreach (System.Text.RegularExpressions.Match v in System.Text.RegularExpressions.Regex.Matches(mVars.Groups[1].Value, @"new (\w+)Var(?:<(\w+)>)?\(([^)]*)\)"))
			{
				string type = v.Groups[1].Value;
				string? generic = v.Groups[2].Success ? v.Groups[2].Value : null;
				var named = System.Text.RegularExpressions.Regex.Match(v.Groups[3].Value, "^\"([^\"]+)\"");
				if (named.Success) keys.Add(named.Groups[1].Value);
				else keys.Add(generic ?? type);
			}
		return keys;
	}

	private static bool HasDuplicateVarKeys(string source) =>
		VarKeysOf(source).GroupBy(k => k, StringComparer.Ordinal).Any(g => g.Count() > 1);

	private void OnOpenOutput(object sender, RoutedEventArgs e)
	{
		// 和生成器用同一套目录规则（存档名 = 目录名），别再拼 OutputDir\ModId
		string text = ModGenerator.ProjectRootOf(_profile);
		if (!Directory.Exists(text))
		{
			SetStatus("还没有生成工程： " + text);
			return;
		}
		Process.Start(new ProcessStartInfo("explorer.exe", "\"" + text + "\"")
		{
			UseShellExecute = true
		});
	}

	private void OnAddCard(object sender, RoutedEventArgs e)
	{
		var c = new CardSpec
		{
			Name = "新卡",
			CardType = "Attack",
			Rarity = "Common",
			Cost = 1
		};
		_profile.Cards.Add(c);
		SyncDetail();
		// V0.2.140：列表里现在还有「每 5 个一块」的空槽行，SelectedIndex = Count-1 会落到空槽上
		//（Count 是真卡数、不是行数）—— 照遗物 / 药水页的做法用**对象本身**选。
		CardList.SelectedItem = c;
		SetStatus("已添加卡牌，右侧填写属性与效果。想照本体「粘液」做一张状态牌：类型选「状态」、稀有度选「状态」。");
	}

	/// <summary>把初始卡组用的本体「打击 ×5 / 防御 ×5」补回卡牌列表（删掉之后可以再加回来）。</summary>
	private void OnAddVanillaBasics(object sender, RoutedEventArgs e)
	{
		int before = _profile.Cards.Count;
		ProfileFactory.AddVanillaBasics(_profile);
		int added = _profile.Cards.Count - before;
		SyncDetail();
		HookCardCount();
		Raise("CardCountText");
		if (added == 0)
		{
			SetStatus("「打击 / 防御」已经在列表最上面了（数值 / 升级 / 卡面都能改，标了 Strike / Defend 标签）。");
			return;
		}
		CardList.SelectedItem = _profile.Cards.FirstOrDefault();
		SetStatus("已补上「打击 ×5 / 防御 ×5」—— 是你自己的两张卡（类名固定 Strike / Defend），数值默认照抄本体。");
	}

	private void OnCopyCard(object sender, RoutedEventArgs e)
	{
		if (!(CardList.SelectedItem is CardSpec cardSpec))
		{
			SetStatus("请先在左边选中一张卡牌再点「复制」。");
			return;
		}
		if (cardSpec.IsVanillaCard)
		{
			SetStatus("这是本体卡（只做引用），不能复制 —— 想要更多份请直接改它的「初始份数」。");
			return;
		}
		CardSpec cardSpec2 = DeepCloneCard(cardSpec);
		cardSpec2.Name = cardSpec.Name + "·改";
		cardSpec2.ClassName = "";     // 留空 = 自动编号（照抄类名会和原卡撞模型 ID → 模组加载失败）
		_profile.Cards.Add(cardSpec2);
		SyncDetail();
		CardList.SelectedItem = cardSpec2;
		SetStatus($"已复制「{cardSpec.Name}」→「{cardSpec2.Name}」：自定义关键词 / 卡牌关键字 / 标签 / 效果（含数值、升级增量、召唤物、概率、条件）/ 升级后关键字 全部照抄。");
	}

	/// <summary>
	/// 整张卡片的**深拷贝**（JSON 往返，和存档 / 工程回读用的是同一套字段）。
	///
	/// 为什么不能手写 <c>new CardSpec { … }</c>（上一版就是这么写的）：手写**一定会漏字段**。
	/// 用户实测漏掉的：勾选的自定义关键词（KeywordIds）、卡牌关键字（消耗/虚无/固有/保留/不可打出/奇巧）、
	/// 标签（Tags）、升级后关键字（UpgradeKeywords），以及效果上除 Kind/Amount 以外的一切
	/// （「召唤物（哪一只）」、牺牲伙伴的收益/公式/倍率、概率生效、条件…）——
	/// 结果复制出来的牌只是长得像，实际配置完全不是同一张。
	/// 走 JSON 往返还有一个好处：以后给 CardSpec / EffectSpec 加字段，这里**不需要改**，不会再漏。
	/// </summary>
	private static CardSpec DeepCloneCard(CardSpec src) =>
		System.Text.Json.JsonSerializer.Deserialize<CardSpec>(
			System.Text.Json.JsonSerializer.Serialize(src, ProfileFactory.JsonOpts),
			ProfileFactory.JsonOpts) ?? new CardSpec();

	// ==================== 三个卡牌列表页：序号 + 每 5 个一块的空槽 + 拖动换位置 ====================
	//
	// V0.2.140（用户对 V0.2.130 / V0.2.137 那两次的**更正**，原话）：
	//   「不是说卡牌左侧的序号做的像遗物一样，五个五个列，直接显示出来，比如只有一张卡时，有1-5序号，
	//     当有6张卡时，出现6到10序号」
	// 含义 = **完全照遗物页 / 药水页那套版式**（见 V0.2.125 / V0.2.127）：
	//   · 显示的**行数** = 5 × ⌈max(N,1)/5⌉（N = 真卡牌数）：1 张 → 1~5 行；5 张 → 1~5；
	//     **6 张 → 1~10**（7~10 是空槽）；11 张 → 1~15；
	//   · 序号**直接在每行最左侧显示**，空槽也带灰色序号；
	//   · 序号仍是**位置号**（拖动 / 增删后重算），**不跟随卡牌移动**；
	//   · 空槽**可以当拖放落点、不能当卡选中、不进全选**。
	// 范围（用户 2026-10-10 已确认「要」）：**三个卡牌列表页全做** —— 卡牌 / 诅咒卡 / 先古卡，
	// 各自的前缀照 V0.2.137 不变（Card / Curse / Ancient），序号各自从 1 起、= 该页列表里的位置号。
	//
	// ⚠ 三页**共用同一份实现**（<see cref="SlotRowMirror{T}"/>，抽出来就是为了不复制三份以后漂）；
	//   三个镜像实例只有「读哪个真集合」和「详情栏绑哪一组属性」不同。
	// ⚠ 空槽只活在界面镜像集合（CardRows / CurseRows / AncientRows）里，
	//   <c>Profile.Cards</c> / <c>Curses</c> / <c>AncientCards</c> 里**永远只有真卡** ——
	//   生成 / 存档 / 回读 / 校验都看不到空槽（红线①：生成结果逐字节不变）。

	/// <summary>
	/// 卡牌列表（「卡牌」页）**真正绑的那个集合**：真卡（按 <c>Profile.Cards</c> 的顺序）+ 末尾的空槽行。
	///
	/// <para>⚠ 必须是 <c>public</c>：WPF 的 <c>PropertyPath</c> 走反射时**读不到 internal 成员**
	/// （遗物页实测踩过：绑 internal 字段时绑定状态直接是 <c>PathError</c>、<c>ItemsSource</c> 永远是 null）。</para>
	/// </summary>
	public ObservableCollection<ISlotRow> CardRows => _cardMirror.Rows;

	/// <summary>诅咒卡列表（「诅咒 / 先古 / 状态」页第一栏）绑的镜像集合：真诅咒 + 末尾空槽行。</summary>
	public ObservableCollection<ISlotRow> CurseRows => _curseMirror.Rows;

	/// <summary>先古卡列表（同一页第二栏）绑的镜像集合：真先古卡 + 末尾空槽行。</summary>
	public ObservableCollection<ISlotRow> AncientRows => _ancientMirror.Rows;

	/// <summary>
	/// 界面上「当前选中的那一张真卡（卡牌页）」：选中项是真卡就是它；点中空槽行时**保持上一张**
	/// （点空槽不该把右边详情清空）。卡牌详情栏的数据上下文绑它。
	/// </summary>
	public CardSpec? CardUiSelection => _cardMirror.UiSelection;

	/// <summary>同上，诅咒页那一栏选中的真诅咒。</summary>
	public CardSpec? CurseUiSelection => _curseMirror.UiSelection;

	/// <summary>同上，先古卡那一栏选中的真先古卡。</summary>
	public CardSpec? AncientUiSelection => _ancientMirror.UiSelection;

	/// <summary>
	/// 卡牌页详情栏 / 「请选择卡牌」提示的显隐判据：**列表里有没有选中一行**（选中的那行是空槽也算选了
	/// —— 空槽行照样是列表里的一行，右侧详情不该闪没）。真的取消选中时列表选中项是 null → 回到「请选择卡牌」。
	/// </summary>
	public bool HasCardSelection => _cardMirror.HasSelection;

	/// <summary>诅咒页详情栏的显隐判据（同上）。</summary>
	public bool HasCurseSelection => _curseMirror.HasSelection;

	/// <summary>先古卡详情栏的显隐判据（同上）。</summary>
	public bool HasAncientSelection => _ancientMirror.HasSelection;

	/// <summary>三页共用的那份镜像逻辑：每个列表页一个实例（各自的行集合 / 序号 / 前缀）。</summary>
	private SlotRowMirror<CardSpec> _cardMirror = null!;

	private SlotRowMirror<CardSpec> _curseMirror = null!;

	private SlotRowMirror<CardSpec> _ancientMirror = null!;

	/// <summary>
	/// 建三个卡牌列表页的镜像（构造函数里调 —— 必须早于任何会碰这三个列表的代码：
	/// <c>RefreshCardOrdinals</c> / <c>SyncDetail</c> / <c>OnCardsChanged</c> 都可能在建窗口的中途被调到）。
	/// </summary>
	private void InitCardRowMirrors()
	{
		_cardMirror = new SlotRowMirror<CardSpec>(p => p.Cards, () => Raise("CardUiSelection"));
		_curseMirror = new SlotRowMirror<CardSpec>(p => p.Curses, () => Raise("CurseUiSelection"));
		_ancientMirror = new SlotRowMirror<CardSpec>(p => p.AncientCards, () => Raise("AncientUiSelection"));
	}

	/// <summary>把「列表里选中的那一行」告诉镜像（它据此算 <c>HasSelection</c> / <c>UiSelection</c>）。</summary>
	private void NoteCardRowsSelection(ListBox list, SlotRowMirror<CardSpec> mirror)
	{
		mirror.View = list;
		mirror.SelectedRow = list.SelectedItem;
	}

	/// <summary>
	/// 给三页的每张卡重新发一遍「我在**自己那一页**列表里排第几」（1 起算），
	/// 再把三个界面镜像集合铺一遍（真卡 1..N + 末尾空槽行）。
	///
	/// <para>为什么要有它：序号 = **当前位置**，不是跟着卡牌走的标记（用户原话「序号不会跟随卡牌的移动」）
	/// —— 所以每次增删 / 拖动 / 载入存档之后都要重算一遍，绑在界面上的 <c>OrdinalText</c> 才会跟着变。
	/// 由 <see cref="OnCardsChanged"/>（三个真集合的 <c>CollectionChanged</c> 都挂在它上面）和
	/// <see cref="SyncDetail"/> 各调一次，覆盖加 / 删 / 撤回 / 拖动 / 换存档全部路径。</para>
	///
	/// <para>⚠ V0.2.137 口径（用户拍板 A，改成「和遗物页一样」）：<c>Ordinal</c> = 它在**自己那一页列表**
	/// 里排第几（普通卡 / 诅咒卡 / 先古卡**各自** 1..N）；<c>LastAutoOrdinal</c> = 同一个号
	/// （自动英文类名跟的就是它）；前缀按稀有度填进 <c>AutoClassNameStem</c>
	/// （普通卡 Card / 诅咒卡 Curse / 先古卡 Ancient）—— 老口径是「全部卡一条连续编号、只有一个 Card
	/// 前缀」，所以诅咒 / 先古卡的号以前比列表行号大。</para>
	///
	/// <para>⚠ 发的号是**真集合里的位置**（1..N），**不是**镜像集合里的行号 —— 空槽行不占号。</para>
	/// </summary>
	internal void RefreshCardOrdinals()
	{
		if (_profile?.Cards is null) return;
		// ⚠⚠ V0.2.156：**必须在写 LastAutoOrdinal 之前**把「按类名存的引用」搬一次！
		// 为什么：自动类名是**按行号**算的，而「旧名字 → 新名字」这张映射表正是靠 LastAutoOrdinal
		// （这张卡**上一次**的号）算出来的（见 NameStabilizer.RenumberCardNames）。下面这个循环
		// 会把 LastAutoOrdinal 就地改成**新**行号 —— 先改的话映射就永远算不出来，
		// 于是「目标卡」引用、上传的卡面（按类名存）全都不跟着走，落到**现在叫这个名字的另一张卡**身上。
		// 用户实测报的「在卡牌列表拖动卡牌后，卡面会变成其他卡」就是这条路径（拖动的落点逻辑
		// MoveCardTo 先 Move、紧接着就调本方法，而 SyncDetail/RefreshCardChoices 都在它后面）。
		SyncCardClassReferences();
		string charClass = Naming.From(_profile).CharClass;
		foreach (var list in new[] { _profile.Cards, _profile.Curses, _profile.AncientCards })
		{
			if (list is null) continue;
			for (int i = 0; i < list.Count; i++)
			{
				CardSpec? c = list[i];
				if (c is null) continue;
				if (c.Ordinal != i + 1) c.Ordinal = i + 1;
				// ⚠ 这两个只在「界面上那行小字」里用（都是 [JsonIgnore]，不写存档、不参与生成）；
				//   生成端认的是 Naming.CardClassName(p, c) / AutoCardClassName(p, c)，同一个口径。
				if (c.LastAutoOrdinal != i + 1) c.LastAutoOrdinal = i + 1;
				string stem = Naming.CardStemOf(c);
				if (!string.Equals(c.AutoClassNameStem, stem, StringComparison.Ordinal)) c.AutoClassNameStem = stem;
				if (!string.Equals(c.CharClass, charClass, StringComparison.Ordinal)) c.CharClass = charClass;
			}
		}
	}

	/// <summary>
	/// 只铺**一张卡牌列表页**的镜像（加 / 删 / 拖动之后只要铺动过的那一页就够了）。
	/// 序号由 <see cref="RefreshCardOrdinals"/> 统一算，这里只管空槽行。
	/// </summary>
	internal void SyncCardRows()
	{
		if (_profile?.Cards is null) return;
		_cardMirror.Sync(_profile);
	}

	/// <summary>只铺诅咒卡那一页的镜像（同上）。</summary>
	internal void SyncCurseRows()
	{
		if (_profile?.Curses is null) return;
		_curseMirror.Sync(_profile);
	}

	/// <summary>只铺先古卡那一页的镜像（同上）。</summary>
	internal void SyncAncientRows()
	{
		if (_profile?.AncientCards is null) return;
		_ancientMirror.Sync(_profile);
	}

	/// <summary>三页一起铺（换存档 / 载入 / 总刷新时用；幂等，重复调没副作用）。</summary>
	internal void SyncCardRowMirrors()
	{
		SyncCardRows();
		SyncCurseRows();
		SyncAncientRows();
	}

	/// <summary>序号行数：<c>5 × ceil(max(N,1) / 5)</c>（卡牌 / 诅咒 / 先古卡三页同一个口径）。</summary>
	internal static int CardSlotRowCount(int cardCount) => SlotRowMirror<CardSpec>.RowCountOf(cardCount);

	/// <summary>
	/// 自检用（V0.2.140）：先古卡那一栏的空槽行「在屏幕上点得到、但拿不到卡」。
	/// 用真正的命中测试走一遍（<c>InputHitTest</c> → 往上找 <c>ListBoxItem</c>），
	/// 顺便验「点空槽不会把已选中的真先古卡冲掉」。
	/// </summary>
	private bool AncientSlotRowProbe()
	{
		int slotIndex = Profile.AncientCards.Count;            // 第一行空槽的行号（0 起算的索引）
		if (slotIndex >= AncientRows.Count) return false;
		if (AncientCardList.ItemContainerGenerator.ContainerFromIndex(slotIndex) is not FrameworkElement fe) return false;
		CardSpec? before = AncientUiSelection;
		Point off = fe.TransformToVisual(AncientCardList).Transform(new Point(0, 0));
		var hit = AncientRowAtPointForTest(new Point(off.X + fe.ActualWidth * 0.5, off.Y + fe.ActualHeight * 0.5));
		AncientCardList.SelectedItem = AncientRows[slotIndex];
		UpdateLayout();
		return hit.Index == slotIndex && hit.Card is null
			&& AncientCardList.SelectedItem is ISlotRow { IsPlaceholder: true }
			&& ReferenceEquals(AncientUiSelection, before);
	}

	/// <summary>自检用：先古卡那一栏按鼠标位置找行（和拖动落点用的是同一套可视树命中）。</summary>
	private (int Index, CardSpec? Card) AncientRowAtPointForTest(Point p)
	{
		DependencyObject? hit = AncientCardList.InputHitTest(p) as DependencyObject;
		while (hit is not null && hit is not ListBoxItem)
			hit = VisualTreeHelper.GetParent(hit);
		if (hit is not ListBoxItem item) return (-1, null);
		return (AncientCardList.ItemContainerGenerator.IndexFromContainer(item), item.DataContext as CardSpec);
	}

	/// <summary>自检用：卡牌列表里最高的那一行有多宽（照遗物 / 药水页那条：行宽必须 ≤ 列表宽 + 2px）。</summary>
	internal double CardListActualMaxItemWidth()
	{
		double max = 0;
		for (int i = 0; i < CardList.Items.Count; i++)
		{
			if (CardList.ItemContainerGenerator.ContainerFromIndex(i) is FrameworkElement fe)
				max = Math.Max(max, fe.ActualWidth);
		}
		return max;
	}

	// 拖动换位置：MouseDown 记起点 → MouseMove 超过系统阈值才开始拖 → DragOver 画插入线 → Drop 真插进去
	private Point _cardDragStart;
	private CardSpec? _cardDragItem;

	/// <summary>
	/// 拖动换位置（用户要求：拖谁到哪就插到哪，<c>Profile.Cards</c> 里的顺序真的变）。
	/// 只在按住某一行往下 / 往上拖超过系统拖动阈值时才起拖 ——
	/// 不然「点一下选中一行」会被当成拖动（列表就点不动了）。
	/// </summary>
	private void OnCardListPreviewMouseDown(object sender, MouseButtonEventArgs e)
	{
		_cardDragStart = e.GetPosition(CardList);
		_cardDragItem = CardAtPoint(e.GetPosition(CardList));
	}

	/// <summary>
	/// 鼠标位置下面是**哪一行**（用可视树往上找 ListBoxItem，再按它在列表里的位置给行号；
	/// 比按坐标算索引可靠）。返回值里 <c>Card</c> 为 null = 鼠标下面是列表空白处。
	/// </summary>
	private (int Index, CardSpec? Card) CardRowAtPoint(Point p)
	{
		DependencyObject? hit = CardList.InputHitTest(p) as DependencyObject;
		while (hit is not null && hit is not ListBoxItem)
			hit = VisualTreeHelper.GetParent(hit);
		if (hit is not ListBoxItem item) return (-1, null);
		int index = CardList.ItemContainerGenerator.IndexFromContainer(item);
		return (index, item.DataContext as CardSpec);
	}

	/// <summary>鼠标位置下面是哪张卡（空白处 → null）。拖动「拿起来」那条路径用它。</summary>
	private CardSpec? CardAtPoint(Point p) => CardRowAtPoint(p).Card;

	private void OnCardListPreviewMouseMove(object sender, MouseEventArgs e)
	{
		if (e.LeftButton != MouseButtonState.Pressed || _cardDragItem is null) return;
		Point now = e.GetPosition(CardList);
		if (Math.Abs(now.X - _cardDragStart.X) < SystemParameters.MinimumHorizontalDragDistance
			&& Math.Abs(now.Y - _cardDragStart.Y) < SystemParameters.MinimumVerticalDragDistance) return;
		CardSpec dragged = _cardDragItem;
		_cardDragItem = null;
		try
		{
			DragDrop.DoDragDrop(CardList, new DataObject(typeof(CardSpec), dragged), DragDropEffects.Move);
		}
		catch (Exception ex)
		{
			// 拖放起不来不该把界面搞崩（极端情况：鼠标已经松开 / 另一个拖放正在进行）
			SetStatus("拖动卡牌失败：" + ex.Message);
		}
	}

	private void OnCardListDragOver(object sender, DragEventArgs e)
	{
		e.Effects = e.Data.GetDataPresent(typeof(CardSpec)) ? DragDropEffects.Move : DragDropEffects.None;
		e.Handled = true;
	}

	/// <summary>
	/// 松手：把被拖的那张卡**移到**鼠标下面那一行的位置（插到它前面；拖到列表空白处 = 移到末尾）。
	/// </summary>
	private void OnCardListDrop(object sender, DragEventArgs e)
	{
		if (!e.Data.GetDataPresent(typeof(CardSpec))) return;
		if (e.Data.GetData(typeof(CardSpec)) is not CardSpec dragged) return;
		(int index, CardSpec? over) = CardRowAtPoint(e.GetPosition(CardList));
		if (!MoveCardTo(dragged, over, index))
		{
			SetStatus($"「{dragged.Name}」已经在这个位置了。");
			return;
		}
		SetStatus($"已把卡牌「{dragged.Name}」拖到第 {Profile.Cards.IndexOf(dragged) + 1} 位（自动生成的英文类名会在下次重新生成时跟着序号走）。");
	}

	/// <summary>
	/// 拖动落点的那一步（**纯逻辑**，和鼠标 / 拖放事件无关 —— 自检直接调它）。
	///
	/// <para><paramref name="over"/> = 鼠标松手时下面那一行的卡；
	/// <paramref name="overRowIndex"/> = 那一行在列表里的行号（空白处时 <paramref name="over"/> 是 null，
	/// 这时就按行号算落点：行号 k → 插到第 k 位，超出末尾就夹到末尾）。
	/// 语义：**插到那一行的位置**（拖谁到哪就插到哪）。返回 false = 位置没变（不用刷界面）。</para>
	/// </summary>
	internal bool MoveCardTo(CardSpec dragged, CardSpec? over, int overRowIndex = -1)
	{
		int from = _profile.Cards.IndexOf(dragged);
		if (from < 0) return false;
		int to;
		if (over is not null)
		{
			to = _profile.Cards.IndexOf(over);
		}
		else
		{
			to = overRowIndex >= 0 ? overRowIndex : _profile.Cards.Count - 1;
		}
		to = Math.Clamp(to, 0, Math.Max(_profile.Cards.Count - 1, 0));
		if (to == from) return false;
		_profile.Cards.Move(from, to);          // 顺序真的变 → 序号 / 自动类名都跟着它走
		RefreshCardOrdinals();
		CardList.SelectedItem = dragged;
		SyncDetail();
		return true;
	}

	private bool ConfirmDelete(string what)
	{
		ConfirmRequests++;
		if (SuppressConfirmations)
		{
			return true;
		}
		return MessageBox.Show(this, "确定要删除" + what + "吗？\n\n删错了不要紧：删除后可以点旁边的「撤回删除」恢复。", "确认删除", MessageBoxButton.YesNo, MessageBoxImage.Question, MessageBoxResult.No) == MessageBoxResult.Yes;
	}

	private bool Confirm(string message, string title = "确认操作")
	{
		ConfirmRequests++;
		if (SuppressConfirmations)
		{
			return true;
		}
		return MessageBox.Show(this, message, title, MessageBoxButton.YesNo, MessageBoxImage.Question, MessageBoxResult.No) == MessageBoxResult.Yes;
	}

	public bool HasUnsavedProfileChanges()
	{
		try
		{
			SyncArt();
			SyncAnim();   // 动画槽位和美术槽位一样：用之前先把界面上的值写回配置
			string a = JsonSerializer.Serialize(_profile, ProfileFactory.JsonOpts);
			string b = ((string.IsNullOrWhiteSpace(_currentProfilePath) || !File.Exists(_currentProfilePath)) ? JsonSerializer.Serialize(ProfileFactory.Sample(), ProfileFactory.JsonOpts) : JsonSerializer.Serialize(ProfileFactory.Load(_currentProfilePath), ProfileFactory.JsonOpts));
			return !string.Equals(a, b, StringComparison.Ordinal);
		}
		catch
		{
			return false;
		}
	}

	protected override void OnClosing(CancelEventArgs e)
	{
		base.OnClosing(e);
		if (e.Cancel || _allowClose || SuppressClosePromptForTest || SuppressClosePrompt || SuppressProfileWrites || !HasUnsavedProfileChanges())
		{
			return;
		}
		// 关键：不要在 OnClosing 里同步弹模态框。
		// 以前是直接 MessageBox.Show 然后按结果决定 e.Cancel —— 两个毛病：
		//   ① 命令行自检（--buildtest 等）里没人点，直接卡死（实测：进程永远不退出、结果文件写不出来）；
		//   ② 正常关窗口时，窗口已经在「正在关闭」状态，弹框偶尔会跑到窗口后面 → 看着像整个程序卡住。
		// 现在的做法：先把这次关闭取消掉，等界面回到空闲再问；用户选了「关闭」才真的关。
		e.Cancel = true;
		Dispatcher.BeginInvoke(new Action(PromptSaveThenClose), System.Windows.Threading.DispatcherPriority.Background);
	}

	/// <summary>「有改动，关闭前要保存吗？」：问完再决定关不关（在关闭流程之外问）。</summary>
	private void PromptSaveThenClose()
	{
		if (_allowClose || SuppressClosePromptForTest || SuppressClosePrompt || SuppressProfileWrites) return;
		bool hasFile = !string.IsNullOrWhiteSpace(_currentProfilePath) && File.Exists(_currentProfilePath);
		string target = hasFile ? ("「" + Path.GetFileName(_currentProfilePath) + "」") : "一个新的存档文件";
		MessageBoxResult result = MessageBox.Show(this,
			"当前配置有改动，关闭前要保存吗？\n\n是 = 保存到" + target + "\n否 = 不保存，直接关闭\n取消 = 返回继续编辑",
			"还没保存", MessageBoxButton.YesNoCancel, MessageBoxImage.Question, MessageBoxResult.Yes);
		if (result == MessageBoxResult.Cancel) return;
		if (result == MessageBoxResult.Yes)
		{
			// 和「保存配置」走同一条路：直接保存进原存档，不弹路径选择
			// （没存过的新配置才落到 存档目录\<模组 ID>.json；失败时窗口先不关）
			if (!SaveProfileInPlace()) return;
		}
		_allowClose = true;
		Close();
	}

	private bool _allowClose;

	private void PushUndo(Stack<UndoEntry> stack, string label, Action restore)
	{
		stack.Push(new UndoEntry(label, restore));
		if (stack.Count > 30)
		{
			List<UndoEntry> list = stack.Take(30).Reverse().ToList();
			stack.Clear();
			foreach (UndoEntry item in list)
			{
				stack.Push(item);
			}
		}
		RaiseUndoState();
	}

	private void UndoLast(Stack<UndoEntry> stack)
	{
		if (stack.Count == 0)
		{
			SetStatus("没有可撤回的删除。");
			return;
		}
		UndoEntry undoEntry = stack.Pop();
		undoEntry.Restore();
		RaiseUndoState();
		SetStatus("已撤回：删除了" + undoEntry.Label);
		// 撤回也是一次真实改动（可能刚把图片接回来）：顺手写进存档，别再让用户手动保存
		PersistArtChange("已撤回：删除了" + undoEntry.Label);
	}

	private void RaiseUndoState()
	{
		Raise("CanUndoCard");
		Raise("CanUndoRelic");
		Raise("CanUndoPotion");
		Raise("CanUndoKeyword");
		Raise("CanUndoSummon");
		Raise("CanUndoCurse");
		Raise("CanUndoAncient");
		Raise("CanUndoStatus");
		Raise("UndoCurseHint");
		Raise("UndoAncientHint");
		Raise("UndoStatusHint");
		Raise("CanUndoArt");
		Raise("CanUndoProfile");
		Raise("UndoCardHint");
		Raise("UndoRelicHint");
		Raise("UndoPotionHint");
		Raise("UndoKeywordHint");
		Raise("UndoSummonHint");
		Raise("UndoPowerHint");
		Raise("CanUndoPower");
		Raise("UndoArtHint");
		Raise("CanUndoAnim");
		Raise("UndoAnimHint");
		Raise("UndoProfileHint");
	}

	private static string HintOf(Stack<UndoEntry> s)
	{
		if (s.Count <= 0)
		{
			return "没有可撤回的删除";
		}
		return "撤回删除：" + s.Peek().Label;
	}

