	public bool ClickButtonByContent(string content, DependencyObject root)
	{
		string content2 = content;
		List<Button> list = new List<Button>();
		CollectButtons(root, list);
		Button button = list.FirstOrDefault((Button x) => x.Content as string == content2);
		if (button == null)
		{
			return false;
		}
		button.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));
		return true;
	}

	public Button? FindButtonByContent(string content, DependencyObject root)
	{
		string content2 = content;
		List<Button> list = new List<Button>();
		CollectButtons(root, list);
		return list.FirstOrDefault((Button x) => x.Content as string == content2);
	}

	/// <summary>
	/// 自检用：找出「Tag 绑定的是某个 x:Name」的按钮（效果栏那三个按钮都是这个形状：
	/// <c>Tag="{Binding ElementName=XXXEffectList}"</c>）。
	/// 为什么要专门找它：这一类按钮**没有唯一的内容**（每一页都有「添加效果 / 删除效果」），
	/// 只按内容找会拿到页面里第一个同名按钮 —— V0.2.137 验「额外资源量页的添加效果」时正是要盯住
	/// 「它 Tag 指的到底是不是 ExtraResourceEffectList」。
	/// ⚠ 绑定还没解析出来时 Tag 是 null（模板 / 元素名没对上），那种情况这里也返回 null —— 正好当断言用。
	/// </summary>
	internal Button? FindButtonByTag(DependencyObject root, string elementName)
	{
		var all = new List<Button>();
		CollectButtons(root, all);
		return all.FirstOrDefault(b => BindingOperations.GetBinding(b, FrameworkElement.TagProperty)?.ElementName == elementName);
	}

	/// <summary>
	/// 在**标题包含** <paramref name="groupHeader"/> 的那个 GroupBox 里点按钮。"
	/// 同一页里有好几个同名按钮（「诅咒 / 先古 / 状态」页三栏各有一个「删除 / 撤回删除」）时，必须先定位到那一栏，
	/// 否则点到的永远是页面里第一个同名按钮（自检里真踩过这个坑）。"
	/// </summary>
	public bool ClickButtonInGroup(string groupHeader, string content, DependencyObject root)
	{
		List<GroupBox> boxes = new List<GroupBox>();
		CollectGroupBoxes(root, boxes);
		GroupBox? box = boxes.FirstOrDefault(b => (b.Header as string)?.Contains(groupHeader, StringComparison.Ordinal) == true);
		return box is not null && ClickButtonByContent(content, box);
	}

	private static void CollectGroupBoxes(DependencyObject root, List<GroupBox> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is GroupBox item) into.Add(item);
			CollectGroupBoxes(child, into);
		}
	}

	public CheckBox? FindCheckBoxByContent(string content, DependencyObject root)
	{
