	private static bool ToggleViaClick(ToggleButton tb)
	{
		if (new ToggleButtonAutomationPeer(tb).GetPattern(PatternInterface.Toggle) is IToggleProvider toggleProvider)
		{
			toggleProvider.Toggle();
			return true;
		}
		return false;
	}

	private static bool CanAddToSelection(ListBox lb)
	{
		if (lb.Items.Count < 2)
		{
			return lb.SelectionMode != SelectionMode.Single;
		}
		lb.SelectedIndex = 0;
		try
		{
			lb.SelectedItems.Add(lb.Items[1]);
		}
		catch
		{
			return false;
		}
		return lb.SelectedItems.Count == 2;
	}

	private int RemoveManyWithUndo<T>(IList<T> list, List<T> selected, Stack<UndoEntry> stack, string unit, Action? afterRestore = null, Action? afterRemove = null) where T : class
	{
		IList<T> list2 = list;
		Action afterRestore2 = afterRestore;
		if (selected.Count == 0)
		{
			return 0;
		}
		List<(T item, int index)> removed = (from item in selected
			select (item: item, index: list2.IndexOf(item)) into x
			where x.index >= 0
			orderby x.index
			select x).ToList();
		if (removed.Count == 0)
		{
			return 0;
		}
		foreach (var item4 in removed)
		{
			T item2 = item4.item;
			list2.Remove(item2);
		}
		afterRemove?.Invoke();
		string label = ((removed.Count == 1) ? (unit + "「" + NameOf(removed[0].item) + "」") : $"{removed.Count} 个{unit}");
		PushUndo(stack, label, delegate
		{
			foreach (var (item3, value) in removed)
			{
				list2.Insert(Math.Clamp(value, 0, list2.Count), item3);
			}
			afterRestore2?.Invoke();
			SyncDetail();
		});
		return removed.Count;
	}

	private static string NameOf<T>(T item)
	{
		if (!(item is CardSpec cardSpec))
		{
			if (!(item is RelicSpec relicSpec))
			{
				if (!(item is PotionSpec potionSpec))
				{
					if (item is EffectSpec effectSpec)
					{
						return effectSpec.Display;
					}
					return item?.ToString() ?? "";
				}
				return potionSpec.Name;
			}
			return relicSpec.Name;
		}
		return cardSpec.Name;
	}

	private void OnRemoveCard(object sender, RoutedEventArgs e)
	{
		ListBox list = ListFromTag(sender) ?? CardList;
		List<CardSpec> picked = SelectedOf<CardSpec>(list);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的卡牌（可 Ctrl/Shift 多选，或点「全选」）。");
			return;
		}
		string what = ((picked.Count == 1) ? ("卡牌「" + picked[0].Name + "」") : $"选中的 {picked.Count} 张卡牌");
		if (ConfirmDelete(what))
		{
			int value = RemoveManyWithUndo(_profile.Cards, picked, _cardUndo, "卡牌", delegate
			{
				list.SelectedItem = picked[0];
			});
			SetStatus($"已删除 {value} 张卡牌（可点「撤回删除」恢复）");
		}
	}

	// ===== 「诅咒 / 先古 / 状态」页（三个列表共用详情区，靠选中项决定显示哪一个）=====
	private readonly Stack<UndoEntry> _curseUndo = new Stack<UndoEntry>();
	private readonly Stack<UndoEntry> _ancientUndo = new Stack<UndoEntry>();
	private readonly Stack<UndoEntry> _statusUndo = new Stack<UndoEntry>();

	public bool CanUndoCurse => _curseUndo.Count > 0;
	public string UndoCurseHint => HintOf(_curseUndo);
	public bool CanUndoAncient => _ancientUndo.Count > 0;
	public string UndoAncientHint => HintOf(_ancientUndo);
	public bool CanUndoStatus => _statusUndo.Count > 0;
	public string UndoStatusHint => HintOf(_statusUndo);

	/// <summary>
	/// 「诅咒 / 先古 / 状态」页第三个列表：**状态卡**。"
	/// 状态卡不是单独的集合 —— 它就是 <see cref="CharacterProfile.Cards"/> 里稀有度为「状态」的那些
	/// （用户要求：把状态卡并进这一页，不复制一份数据）。所以这里是一件**只读的镜像**）"
	/// 增删都作用在 Profile.Cards 上，改完调 <see cref="RebuildStatusCards"/> 重新铺一遍。"
	/// </summary>
	public ObservableCollection<CardSpec> StatusCards { get; } = new();

	/// <summary>把 Profile.Cards 里稀有度为「状态」的牌同步到 <see cref="StatusCards"/>（顺序照 Cards）。 /summary>
	internal void RebuildStatusCards()
	{
		var want = _profile.Cards.Where(c => c is not null && c.IsStatusCard).ToList();
		if (want.Count == StatusCards.Count && want.Zip(StatusCards).All(p => ReferenceEquals(p.First, p.Second)))
			return;     // 没变就别动（避免把列表的选择 / 滚动位置抖掉）"
		CardSpec? wasSelected = StatusCardList?.SelectedItem as CardSpec;
		StatusCards.Clear();
		foreach (CardSpec c in want) StatusCards.Add(c);
		if (StatusCardList is not null && wasSelected is not null && want.Contains(wasSelected))
			StatusCardList.SelectedItem = wasSelected;
	}

	/// <summary>
	/// 「先古卡 / 状态卡」共用详情区的当前对象（两个列表里有一个选中就是它）。
	///
	/// <para>⚠ V0.2.140：先古卡那栏的列表里加了空槽行 —— 点一下空槽时
	/// <c>AncientCardList.SelectedItem</c> 会是 <c>SlotPlaceholder</c>，用 <c>as CardSpec</c> 读它得 null，
	/// 于是 <see cref="ShowSpecialCardDetail"/> 变 false、右侧详情**整块收起**（而 <c>AncientUiSelection</c>
	/// 里其实还留着上一张真先古卡）。所以这一档必须读镜像属性 —— 和诅咒那栏
	/// （<see cref="SpecialCardOf"/> 用 <see cref="CurseUiSelection"/>）同一个理由。</para>
	/// </summary>
	public CardSpec? SpecialCard => AncientUiSelection ?? (StatusCardList?.SelectedItem as CardSpec);

	/// <summary>先古卡 / 状态卡详情区要不要显示（诅咒走它自己那块）。</summary>
	public bool ShowSpecialCardDetail => SpecialCard is not null;

	/// <summary>
	/// 「诅咒 / 先古 / 状态」页当前选中的那张牌（三个列表里有一个选中就算）。
	///
	/// <para>⚠ V0.2.140：诅咒那栏和先古卡那栏的列表里都加了空槽行（点空槽时
	/// <c>SelectedItem</c> 会是 <c>SlotPlaceholder</c>），所以这两档都改读镜像属性
	/// —— 它们只在「选中的是真卡」时才有值（空槽行天然被 <c>is CardSpec</c> 滤掉）。</para>
	/// </summary>
	internal CardSpec? SpecialCardOf() =>
		CurseUiSelection ?? AncientUiSelection ?? (StatusCardList.SelectedItem as CardSpec);

	/// <summary>
	/// 自检用（V0.2.140）：把 `Visibility` 这类**绑定驱动**的属性立刻重算一遍。
	///
	/// <para>为什么需要它：源属性变了之后，WPF 的绑定不一定马上写目标属性 ——
	/// `PropertyChanged → 绑定重算 → SetValue` 可能被排进 <c>Dispatcher</c> 队列，而
	/// <c>--uicheck</c> 是**同步**跑的（没有消息循环在转），于是断言读到的是上一帧的值。
	/// 实测踩到：<c>ShowSpecialCardHint</c> 明明已经是 false（面板该收起），
	/// 元素上的 <c>Visibility</c> 还留着 <c>Visible</c>，那句「选中诅咒后空态提示收起」就白 FAIL 了。</para>
	///
	/// <para>只对**显式传进来的**那几个元素做（不去动别的绑定），自检里用一次就扔。</para>
	/// </summary>
	private static void FlushBindings(params FrameworkElement[] elements)
	{
		foreach (FrameworkElement fe in elements)
		{
			if (fe is null) continue;
			fe.GetBindingExpression(UIElement.VisibilityProperty)?.UpdateTarget();
			fe.UpdateLayout();
		}
	}

	/// <summary>三个列表都没选中时显示那句空态提示。</summary>
	public bool ShowSpecialCardHint => SpecialCardOf() is null;

	/// <summary>三个列表（卡牌 / 诅咒 / 先古卡）共用同一套「卡面预览」属性，所以选中要互斥：
	/// 选中这一栏就把另外两栏的选择清掉，否则预览会看着像串了（用户报过类似的观感问题）。
	/// </summary>
	/// <summary>
	/// 遗物页那块「额外资源量遗物」要不要显示）  额外资源量页勾了「启用额外资源量」）。"
	/// 那只隐藏起始遗物） 角色>ExtraResourceRelic）本来就是自动生成的，用户要求能在这页给它加效果。"
	/// </summary>
	public bool ExtraResourceRelicVisible => Profile.ExtraResource.Enabled;

	/// <summary>
	/// 遗物页那块「额外资源量遗物」里显示的**身份**（用户要求：这页要能看见那只自动生成的遗物），"
	/// 类名 + 稀有度 + 「自动生成」，让用户知道它不在下面的遗物列表里、也不用去配它的名字 / 图标」"
	/// </summary>
	public string ExtraResourceRelicSummary
	{
		get
		{
			var n = Naming.From(Profile);
			return $"{n.ExtraResourceRelicClass}　｜　稀有度「{EffectCatalog.RelicRarityZh("Starter")}」（RelicRarity.Starter）　｜　自动生成，不在遗物页那张列表里";
		}
	}

	/// <summary>
	/// 选中「额外资源量遗物」里的一条效果：把遗物列表的选择清掉（两块编辑区在同一格，靠选择互斥），
	/// 并把「请选择遗物」那行空提示藏掉（否则它会透在效果编辑器后面）。"
	/// </summary>
	private void OnExtraResourceEffectSelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		if (ExtraResourceEffectList.SelectedItem is not null)
		{
			RelicList.SelectedItem = null;
			// 两块编辑区在同一格，靠选择互斥：这里必须把「当前选中的真遗物」也清掉
			//（详情栏现在绑的是 RelicUiSelection，光清 RelicList.SelectedItem 不够）
			RelicUiSelection = null;
			SyncDetail();
			if (RelicEmptyHint is not null) RelicEmptyHint.Visibility = Visibility.Collapsed;
		}
		else if (RelicEmptyHint is not null)
		{
			// 清掉本地值，认 XAML 里那条绑定（RelicList 没选中就显示）重新生效
			RelicEmptyHint.ClearValue(VisibilityProperty);
		}
		Raise("ExtraResourceRelicVisible");
	}

	/// <summary>
	/// V0.2.165：把**卡牌页**那一栏的选中彻底清掉（列表选中 + 镜像的 <c>CardUiSelection</c>）。
	///
	/// <para>为什么不能只写 <c>CardList.SelectedItem = null</c>：卡牌页那个镜像的语义是
	/// 「点空槽行时**保持上一张**」（见 <see cref="SlotRowMirror{T}.UiSelection"/>），
	/// 而三栏互斥的判据是 <c>CardUiSelection ?? SpecialCardOf()</c> —— 光清 SelectedItem 时
	/// 镜像不会松手，切到先古页后卡面预览拿到的还是卡牌页那张：**竖图比例变成横图、先古卡面「消失」**
	/// （用户实测报的就是这个）。所以互斥时必须连镜像一起清。</para>
	/// </summary>
	private void ClearCardPageSelectionForPortrait()
	{
		CardList.SelectedItem = null;
		_cardMirror.ClearSelection();
		Raise("CardUiSelection");
	}

	/// <summary>
	/// V0.2.165：反方向 —— 在卡牌页选中一张真卡之后，把「诅咒 / 先古 / 状态」三栏的选中也清掉。
	/// 三处共用同一套「卡面预览」属性，留下旧选中会让预览 / 详情串到另一页那张牌上。
	/// </summary>
	private void ClearSpecialCardSelections()
	{
		if (CurseUiSelection is null && AncientUiSelection is null && StatusCardList.SelectedItem is not CardSpec) return;
		_curseMirror.ClearSelection();
		_ancientMirror.ClearSelection();
		StatusCardList.SelectedItem = null;
		Raise("HasCurseSelection");
		Raise("HasAncientSelection");
		Raise("ShowSpecialCardHint");
		Raise("SpecialCard");
		Raise("ShowSpecialCardDetail");
	}

	private void OnSpecialCardSelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		// 三个列表（诅咒 / 先古卡 / 状态卡）的选择互斥：选中这一栏就把另外两栏（+ 卡牌页的列表）清掉，
		// 否则卡面预览会看着像串了。
		// ⚠ V0.2.140：诅咒栏和先古卡栏的列表里都有空槽行了，所以「选中的是空槽」也要当成**没选中**处理
		// —— 否则点一下诅咒那栏的空槽，先古卡那栏的选中就会被清掉、右侧却什么都没切过去。
		// ⚠ 判据一律用 `SelectedItems.Count`，不要用 `SelectedItem is not null`：
		// 走 `SelectedItems.Add()` 那条路时，WPF 是**先**更新选中集合、**后**才把 `SelectedItem` 补上，
		// 而 `SelectionChanged` 事件在这一步之前就发出来了 —— 那时读 `SelectedItem` 还是 null，
		// 互斥那一步会被整段跳过（V0.2.140 实测：`OnAddStatusCard` 里用 SelectedItems.Add 选新卡，
		// 结果诅咒 / 先古两栏的选中一直留着，右侧详情显示的是上一张先古卡）。
		if (sender == CurseList && CurseList.SelectedItems.Count > 0 && CurseList.SelectedItem is not SlotPlaceholder)
		{
			_ancientMirror.ClearSelection();
			StatusCardList.SelectedItem = null;
			ClearCardPageSelectionForPortrait();
		}
		else if (sender == AncientCardList && AncientCardList.SelectedItems.Count > 0 && AncientCardList.SelectedItem is not SlotPlaceholder)
		{
			_curseMirror.ClearSelection();
			StatusCardList.SelectedItem = null;
			ClearCardPageSelectionForPortrait();
		}
		else if (sender == StatusCardList && StatusCardList.SelectedItems.Count > 0)
		{
			_curseMirror.ClearSelection();
			_ancientMirror.ClearSelection();
			ClearCardPageSelectionForPortrait();
		}
		// ⚠⚠ V0.2.140 必须补这一步：上面把另外两栏的 `SelectedItem` 置 null 之后，
		// **镜像集合里认的「当前选中行」还停在旧的那一行**（`SlotRowMirror.SelectedRow` 是我们自己在
		// SelectionChanged 里喂进去的，直接给 SelectedItem 赋 null 时若值没变就**不会**再触发那两条委托）。
		// 不补的话 `CurseUiSelection` / `AncientUiSelection` 会一直留着上一张牌 ⇒ `SpecialCard` 拿到旧对象 ⇒
		// 右侧「先古卡 / 状态卡」那块详情显示错的那张（实测：加一张状态卡，详情里却是上一张先古卡）。
		//
		// ⚠ 这里**不能**用 forceClear，也不能对**被点的那一栏**调 ClearSelection：用户点的是空槽行时
		// `SelectedItem` 是 `SlotPlaceholder`（不是 null），那时要按老规矩**保持上一张真卡**
		//（点空槽不该把右边详情清空）。所以要清的只是「明确置 null 的那两栏」，正是上面 ClearSelection 干的事。
		NoteCardRowsSelection(CurseList, _curseMirror);
		NoteCardRowsSelection(AncientCardList, _ancientMirror);
		_curseMirror.RefreshUiSelection();
		_ancientMirror.RefreshUiSelection();
		Raise("HasCurseSelection");
		Raise("HasAncientSelection");
		Raise("ShowSpecialCardHint");
		Raise("SpecialCard");
		Raise("ShowSpecialCardDetail");
		RaiseCardPortrait();
	}

	private void OnAddCurse(object sender, RoutedEventArgs e)
	{
		var c = new CardSpec
		{
			Name = "新诅咒",
			CardType = "Curse",
			Rarity = "Curse",
			Cost = -1,
			Unplayable = true,      // 诅咒一律打不出去（生成时也会强制加上这个关键字）
		};
		_profile.Curses.Add(c);
		SyncDetail();
		// V0.2.140：列表里有空槽行了，不能用 SelectedIndex；用对象本身最稳
		CurseList.SelectedItem = c;
		SetStatus("已添加诅咒：费用 -1、不能被打出，右边加的效果会在「你的回合结束时，如果它还在你的手牌里」触发。");
	}

	private void OnRemoveCurse(object sender, RoutedEventArgs e)
	{
		List<CardSpec> picked = SelectedOf<CardSpec>(CurseList);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的诅咒（可 Ctrl/Shift 多选）。");
			return;
		}
		string what = picked.Count == 1 ? "诅咒「" + picked[0].Name + "」" : $"选中的 {picked.Count} 张诅咒";
		if (ConfirmDelete(what))
		{
			int n = RemoveManyWithUndo(_profile.Curses, picked, _curseUndo, "诅咒", delegate
			{
				CurseList.SelectedItem = picked[0];
			});
			SetStatus($"已删除 {n} 张诅咒（可点「撤回删除」恢复）");
		}
	}

	private void OnUndoCurse(object sender, RoutedEventArgs e)
	{
		UndoLast(_curseUndo);
	}

	private void OnSelectAllCurses(object sender, RoutedEventArgs e)
	{
		SelectAll(CurseList, "诅咒");
	}

