	// ===== 状态卡（用户要求：并进这一页。数据仍然是 Profile.Cards 里稀有度为「状态」的那些） ====

	private void OnAddStatusCard(object sender, RoutedEventArgs e)
	{
		var c = new CardSpec
		{
			Name = "新状态卡",
			CardType = "Status",     // 本体那些状态牌（伤口 / 灼伤 / 眩晕 / 粘液）类型都是 Status
			Rarity = "Status",
			Cost = 1,
		};
		_profile.Cards.Add(c);
		RebuildStatusCards();
		SyncDetail();
		// ⚠ V0.2.140 实测：这里**不能**写 `SelectedItem = c`（也不能写 `SelectedIndex = 0`）——
		// `RebuildStatusCards` 每轮都 `StatusCards.Clear()` + 重新填，ListBox 内部那个 SelectedIndex
		// 缓存被清成 -1 之后，Selector 拿它去算目标下标、算不出来就**静默丢掉这次赋值**
		// （实测：赋值前后 SelectedItem 都是 null、SelectedIndex 都是 -1，而 Items 里明明有这张卡）。
		// 走 `SelectedItems.Add` 是直接改选中集合、不经过那个缓存，实测选中项 / 详情面板 / 三栏互斥都正常。
		StatusCardList.SelectedItems.Clear();
		StatusCardList.SelectedItems.Add(c);
		// `SelectedItems.Add` 之后 `SelectedItem` 是**延迟**补上的（SelectionChanged 先发、值后到），
		// 这里显式收个尾，免得后面依赖 SelectedItem 的断言 / 绑定读到中间态。
		UpdateLayout();
		StatusCardList.SelectedItem = c;
		SetStatus("已添加状态卡：稀有度 / 类型都是「状态」，默认不能升级、不进战斗奖励 —— 拿到它要靠你自己的效果（生成卡牌 / 获得卡牌（全局））。");
	}

	private void OnRemoveStatusCard(object sender, RoutedEventArgs e)
	{
		List<CardSpec> picked = SelectedOf<CardSpec>(StatusCardList);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的状态卡（可 Ctrl/Shift 多选）。");
			return;
		}
		string what = picked.Count == 1 ? "状态卡「" + picked[0].Name + "」" : $"选中的 {picked.Count} 张状态卡";
		if (ConfirmDelete(what))
		{
			int n = RemoveManyWithUndo(_profile.Cards, picked, _statusUndo, "状态卡", delegate
			{
				RebuildStatusCards();
				StatusCardList.SelectedItem = picked[0];
			});
			RebuildStatusCards();
			SetStatus($"已删除 {n} 张状态卡（可点「撤回删除」恢复；它们也从「卡牌」页的列表里去掉了）");
		}
	}

	private void OnUndoStatusCard(object sender, RoutedEventArgs e)
	{
		UndoLast(_statusUndo);
		RebuildStatusCards();
	}

	private void OnSelectAllStatusCards(object sender, RoutedEventArgs e)
	{
		SelectAll(StatusCardList, "状态卡");
	}

	/// <summary>诅咒 / 先古卡共用的「上传卡面」——取当前选中的那张（两个列表里的）。</summary>
	private void OnPickSpecialCardPortrait(object sender, RoutedEventArgs e)
	{
		if (SpecialCardOf() is not { } card)
		{
			SetStatus("请先在左边选中一张诅咒或先古卡。");
			return;
		}
		OpenFileDialog openFileDialog = new OpenFileDialog
		{
			Filter = "图片 (*.png)|*.png"
		};
		if (openFileDialog.ShowDialog(this).GetValueOrDefault())
		{
			string key = Naming.From(_profile).CardClassName(_profile, card);
			_profile.Art.CardPortraits[key] = openFileDialog.FileName;
			RaiseCardPortrait();
			var specialFrame = CardPortraitFrameOf(card);
			PersistArtChange($"已为「{card.Name}」设置卡面：{openFileDialog.FileName}"
				+ $"（建议 {specialFrame.W}×{specialFrame.H} PNG{(specialFrame.Stretch ? "，竖图" : "")}）");
		}
	}

	private void OnAddRelic(object sender, RoutedEventArgs e)	{
		_profile.Relics.Add(new RelicSpec
		{
			Name = "新遗物",
			Rarity = "Common",
			Trigger = "CombatStart"
		});
		RefreshRelicOrdinals();
		SyncDetail();
		// 新加的那只在列表里一定是「最后一只真遗物」——不能再用 SelectedIndex = Count-1：
		// 列表行数是按块凑满的（末尾还有空槽行），用对象本身更稳
		RelicList.SelectedItem = _profile.Relics[_profile.Relics.Count - 1];
	}

	private void OnRemoveRelic(object sender, RoutedEventArgs e)
	{
		List<RelicSpec> picked = SelectedOf<RelicSpec>(RelicList);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的遗物（可 Ctrl/Shift 多选，或点「全选」）。");
			return;
		}
		string what = ((picked.Count == 1) ? ("遗物「" + picked[0].Name + "」") : $"选中的 {picked.Count} 个遗物");
		if (ConfirmDelete(what))
		{
			int value = RemoveManyWithUndo(_profile.Relics, picked, _relicUndo, "遗物", delegate
			{
				RelicList.SelectedItem = picked[0];
			});
			SetStatus($"已删除 {value} 个遗物（可点「撤回删除」恢复）");
		}
	}

	// ==================== 遗物列表：序号 + 拖动换位置（用户要求第 2 条）====================
	//
	// 序号按「每块 5 个」预留显示（用户后续要求原话：「左侧序号直接显示，可以每次多生成五个序号，
	// 比如有 3 个选项时，左侧序号显示 1~5，加第 6 个的时候，显示 6~10.」）：
	//   列表里显示的**行数** = 5 × ceil(max(N,1) / 5)，N = 真遗物数（Profile.Relics 是唯一事实来源）。
	//   3 只 → 1~5 行（4、5 是空槽）；5 只 → 1~5；6 只 → 1~10（7~10 是空槽）；11 只 → 1~15。
	//   空槽行 = Reactive 的**界面占位项**（SlotPlaceholder），只显示灰色序号、没有内容、
	//   不能被当成遗物选中，但可以当拖放落点（拖到第 k 行 = 放到第 k 位，夹到合法范围）。
	// ⚠ 空槽**只在** RelicRows 这个界面镜像集合里；Profile.Relics 里永远只有真遗物。

	/// <summary>每「一块」预留多少个序号（用户要求：一次多生成五个序号）。</summary>
	internal const int RelicSlotsPerBlock = 5;

	/// <summary>
	/// 遗物页左侧列表**真正绑的那个集合**：真遗物（按 <c>Profile.Relics</c> 的顺序）+ 末尾的空槽行。
	///
	/// <para>为什么要镜像一层：<c>Profile.Relics</c> 是 <c>ObservableCollection&lt;RelicSpec&gt;</c>，
	/// 塞不进占位项；而且「真遗物集合 = 唯一事实来源」这条不能破 —— 所以占位项只活在这个界面集合里，
	/// 由 <see cref="SyncRelicRows"/> 单向从 <c>Profile.Relics</c> 铺出来（只读镜像 + 补空槽）。</para>
	///
	/// <para>⚠ 必须是 <c>public</c>，不能是 <c>internal</c>：WPF 的 <c>PropertyPath</c> 走反射时
	/// **读不到 internal 成员**（实测：绑 internal 字段时绑定状态直接是 <c>PathError</c>、
	/// <c>ItemsSource</c> 永远是 null，界面上一行都没有）。</para>
	/// </summary>
	public ObservableCollection<IRelicSlotRow> RelicRows { get; } = new();

	/// <summary>
	/// 界面上「当前选中的那一只真遗物」：选中项是真遗物就是它；点中空槽行时**保持上一只**
	/// （点空槽不该把右边详情清空）。详情栏的数据上下文绑它。
	/// </summary>
	public RelicSpec? RelicUiSelection
	{
		get => _relicUiSelection;
		private set
		{
			if (!ReferenceEquals(_relicUiSelection, value))
			{
				_relicUiSelection = value;
				Raise("RelicUiSelection");
			}
		}
	}

	private RelicSpec? _relicUiSelection;

	/// <summary>
	/// 详情栏 / 「请选择遗物」提示的显隐判据：**列表里有没有选中一行**（选中的那行是空槽也算选了 ——
	/// 空槽行照样是列表里的一行，右侧详情不该闪没）。
	///
	/// <para>为什么不用 <see cref="RelicUiSelection"/> 直接判空：点中空槽时它会保持上一只（有值），
	/// 但用户按 <c>SelectedIndex = -1</c> / 点列表空白真的取消选中时，列表选中项是 null
	/// —— 那时候右侧必须回到「请选择遗物」的空态（自检里有断言盯这条）。</para>
	/// </summary>
	public bool HasRelicSelection => RelicList?.SelectedItem is not null;

	/// <summary>序号行数：<c>5 × ceil(max(N,1) / 5)</c>（N=0 也显示 1~5，用户要的是「直接显示序号」）。</summary>
	internal static int RelicSlotRowCount(int relicCount)
	{
		int n = Math.Max(relicCount, 1);
		return ((n + RelicSlotsPerBlock - 1) / RelicSlotsPerBlock) * RelicSlotsPerBlock;
	}

	/// <summary>
	/// 给每只遗物重新发一遍「我在列表里排第几」（1 起算），再把界面镜像集合铺一遍。
	///
	/// 为什么要有它：序号 = **当前位置**，不是跟着物品走的标记（用户原话「序号不会跟随遗物移动」）
	/// —— 所以每次增删 / 拖动 / 载入存档之后都要重算一遍，绑在界面上的 <c>OrdinalText</c> 才会跟着变。
	/// 这里顺带把 <c>Profile.Relics</c> 的 <c>CollectionChanged</c> 也挂上（见 <see cref="HookRelicListOrder"/>），
	/// 由它来兜住「代码里直接 Add / Remove」的那些路径（撤回删除、导入存档、自检造数据）。
	/// </summary>
	internal void RefreshRelicOrdinals()
	{
		if (_profile?.Relics is null) return;
		for (int i = 0; i < _profile.Relics.Count; i++)
		{
			RelicSpec? r = _profile.Relics[i];
			if (r is not null) r.Ordinal = i + 1;
		}
		SyncRelicRows();
	}

	/// <summary>
	/// 把界面镜像集合铺成「真遗物 1..N + 空槽 N+1..5×ceil(N/5)」。
	///
	/// <para>尽量**原地改**（只动变化的那些位）而不是清空重建：清空会把 <c>RelicList.SelectedItem</c>
	/// 打断（拖动 / 删一只之后选中项就丢了），原地改能保住选中项。真遗物那一截按位置逐个对齐。</para>
	/// </summary>
	internal void SyncRelicRows()
	{
		if (_profile?.Relics is null) return;
		// ⚠ 先自愈「挂错存档」：有几处代码（历史自检）是直接给 Profile 字段赋值的，不走属性 setter，
		// 于是 CollectionChanged 还挂在**上一份存档**的 Relics 上 —— 表现是「Profile.Relics 已经是新的了，
		// 列表里还是旧那几只」（实测踩到：加第 6 只、列表却还是 5 行）。这里发现不一致就重挂一次。
		if (!ReferenceEquals(_relicOrderHookedOn, _profile)) HookRelicListOrder();
		// ⚠ 重入保护（实测踩到）：RelicRows.Clear() 会让列表的选中项被 WPF 清掉 → 触发 SelectionChanged
		// → SyncDetail → RefreshRelicOrdinals → 又回到这里。重入时两次调用会各自按**自己那份快照**
		// 把集合铺一遍，后写的那次会把对方的结果盖掉（表现是「加了第 6 只，列表却还是 5 行」这种差一行的陈旧状态）。
		// 做法：重入只置一个 dirty 标记，由最外层那次循环重算到稳定为止。
		if (_inSyncRelicRows)
		{
			_relicRowsDirty = true;
			return;
		}
		_inSyncRelicRows = true;
		try
		{
			do
			{
				_relicRowsDirty = false;
				SyncRelicRowsCore();
			}
			while (_relicRowsDirty);
		}
		finally
		{
			_inSyncRelicRows = false;
		}
	}

	private bool _inSyncRelicRows;

	private bool _relicRowsDirty;

	/// <summary>
	/// 把界面镜像集合铺成「真遗物 1..N + 空槽 N+1..5×ceil(N/5)」。
	///
	/// <para>尽量**原地改**（只动变化的那些位）而不是清空重建：清空会把 <c>RelicList.SelectedItem</c>
	/// 打断（拖动 / 删一只之后选中项就丢了），原地改能保住选中项。真遗物那一截按位置逐个对齐。</para>
	/// </summary>
	private void SyncRelicRowsCore()
	{
		if (_profile?.Relics is null) return;
		IList<RelicSpec> relics = _profile.Relics;
		int total = RelicSlotRowCount(relics.Count);
		// 真遗物那一截按位置对齐；对不上（长度变了 / 位置上是空槽）就整体重建
		bool inPlace = RelicRows.Count == total;
		if (inPlace)
		{
			for (int i = 0; i < relics.Count; i++)
			{
				if (!ReferenceEquals(RelicRows[i], relics[i])) { inPlace = false; break; }
			}
		}
		if (inPlace)
		{
			for (int i = relics.Count; i < total; i++)
			{
				if (RelicRows[i] is not SlotPlaceholder ph || ph.Slot != i + 1) { inPlace = false; break; }
			}
		}
		if (inPlace) return;
		// 重建前先把选中项挪开：占位行要被移走时 WPF 自己也会清 SelectedItem，
		// 但显式清一下更稳（免得 CollectionChanged 里又绕回 SelectionChanged）
		if (RelicList is not null && RelicList.SelectedItem is IRelicSlotRow)
		{
			RelicList.SelectedItem = null;
		}
		RelicRows.Clear();
		for (int i = 0; i < relics.Count; i++)
		{
			if (relics[i] is not null) RelicRows.Add(relics[i]);
		}
		// 末尾补齐空槽：序号就按「行号」给，凑满当前这一块（1~5 / 1~10 / 1~15…）
		for (int i = relics.Count; i < total; i++)
		{
			RelicRows.Add(new SlotPlaceholder(i + 1));
		}
	}

	/// <summary>只挂一次：遗物列表增删 → 重排序号 + 重铺空槽（避免每条增删路径都要记得调一次）。</summary>
	private void HookRelicListOrder()
	{
		if (ReferenceEquals(_relicOrderHookedOn, _profile)) return;
		if (_relicOrderHookedOn is not null) _relicOrderHookedOn.Relics.CollectionChanged -= OnRelicCollectionChanged;
		_relicOrderHookedOn = _profile;
		if (_profile?.Relics is null) return;
		_profile.Relics.CollectionChanged += OnRelicCollectionChanged;
		RefreshRelicOrdinals();
	}

	private void OnRelicCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e) => RefreshRelicOrdinals();

	/// <summary>已经挂过 <c>CollectionChanged</c> 的那份存档（换存档时先摘再重挂，避免重复订阅）。</summary>
	private CharacterProfile? _relicOrderHookedOn;

	// 拖动换位置：MouseDown 记起点 → MouseMove 超过系统阈值才开始拖 → DragOver 画插入线 → Drop 真插进去
	private Point _relicDragStart;
	private RelicSpec? _relicDragItem;

	/// <summary>
	/// 拖动换位置（用户要求：拖谁到哪就插到哪，<c>RelicList</c> 里的顺序真的变）。
	/// 只在按住某一行的文字往下 / 往上拖超过系统拖动阈值时才起拖 ——
	/// 不然「点一下选中一行」会被当成拖动（列表就点不动了）。
	/// </summary>
	private void OnRelicListPreviewMouseDown(object sender, MouseButtonEventArgs e)
	{
		_relicDragStart = e.GetPosition(RelicList);
		_relicDragItem = RelicAtPoint(e.GetPosition(RelicList));
	}

	/// <summary>
	/// 鼠标位置下面是**哪一行**（用可视树往上找 ListBoxItem，再按它在列表里的位置给行号；
	/// 比按坐标算索引可靠）。返回值里 <c>Relic</c> 为 null = 那一行是空槽（或鼠标下面是列表空白处）。
	///
	/// <para>为什么要给行号而不是只给遗物：空槽行也要能当**拖放落点**（拖到第 k 行 = 放到第 k 位），
	/// 而空槽行没有 <c>RelicSpec</c> 可以拿。</para>
	/// </summary>
	private (int Index, RelicSpec? Relic) RelicRowAtPoint(Point p)
	{
		DependencyObject? hit = RelicList.InputHitTest(p) as DependencyObject;
		while (hit is not null && hit is not ListBoxItem)
			hit = VisualTreeHelper.GetParent(hit);
		if (hit is not ListBoxItem item) return (-1, null);
		int index = RelicList.ItemContainerGenerator.IndexFromContainer(item);
		return (index, item.DataContext as RelicSpec);
	}

	/// <summary>鼠标位置下面是哪只真遗物（空槽 / 空白处 → null）。拖动「拿起来」那条路径用它。</summary>
	private RelicSpec? RelicAtPoint(Point p) => RelicRowAtPoint(p).Relic;

	private void OnRelicListPreviewMouseMove(object sender, MouseEventArgs e)
	{
		if (e.LeftButton != MouseButtonState.Pressed || _relicDragItem is null) return;
		Point now = e.GetPosition(RelicList);
		if (Math.Abs(now.X - _relicDragStart.X) < SystemParameters.MinimumHorizontalDragDistance
			&& Math.Abs(now.Y - _relicDragStart.Y) < SystemParameters.MinimumVerticalDragDistance) return;
		RelicSpec dragged = _relicDragItem;
		_relicDragItem = null;
		try
		{
			DragDrop.DoDragDrop(RelicList, new DataObject(typeof(RelicSpec), dragged), DragDropEffects.Move);
		}
		catch (Exception ex)
		{
			// 拖放起不来不该把界面搞崩（极端情况：鼠标已经松开 / 另一个拖放正在进行）
			SetStatus("拖动遗物失败：" + ex.Message);
		}
	}

	private void OnRelicListDragOver(object sender, DragEventArgs e)
	{
		e.Effects = e.Data.GetDataPresent(typeof(RelicSpec)) ? DragDropEffects.Move : DragDropEffects.None;
		e.Handled = true;
	}

	/// <summary>
	/// 松手：把被拖的那只**移到**鼠标下面那一行的位置（插到它前面；拖到空槽行 = 放到那一行对应的位置、
	/// 会夹到合法范围；拖到列表空白处 = 移到末尾）。
	/// </summary>
	private void OnRelicListDrop(object sender, DragEventArgs e)
	{
		if (!e.Data.GetDataPresent(typeof(RelicSpec))) return;
		if (e.Data.GetData(typeof(RelicSpec)) is not RelicSpec dragged) return;
		(int index, RelicSpec? over) = RelicRowAtPoint(e.GetPosition(RelicList));
		if (!MoveRelicTo(dragged, over, index))
		{
			SetStatus($"「{dragged.Name}」已经在这个位置了。");
			return;
		}
		SetStatus($"已把遗物「{dragged.Name}」拖到第 {Profile.Relics.IndexOf(dragged) + 1} 位（自动生成的英文类名会在下次重新生成时跟着序号走）。");
	}

	/// <summary>
	/// 拖动落点的那一步（**纯逻辑**，和鼠标 / 拖放事件无关 —— 自检直接调它）。
	///
	/// <para><paramref name="over"/> = 鼠标松手时下面那一行的那只真遗物；
	/// <paramref name="overRowIndex"/> = 那一行在列表里的行号（空槽行 / 空白处时 <paramref name="over"/> 是 null，
	/// 这时就按行号算落点：行号 k → 插到第 k 位，超出末尾就夹到末尾）。
	/// 语义：**插到那一行的位置**（拖谁到哪就插到哪）。返回 false = 位置没变（不用刷界面）。</para>
	/// </summary>
	internal bool MoveRelicTo(RelicSpec dragged, RelicSpec? over, int overRowIndex = -1)
	{
		int from = _profile.Relics.IndexOf(dragged);
		if (from < 0) return false;
		int to;
		if (over is not null)
		{
			to = _profile.Relics.IndexOf(over);
		}
		else
		{
			// 空槽行 / 列表空白处：按「行号 - 1」算目标位置，再夹到 [0, Count-1]
			// （空槽都在真遗物后面，所以正常情况下会夹成「移到末尾」）
			to = overRowIndex >= 0 ? overRowIndex : _profile.Relics.Count - 1;
		}
		to = Math.Clamp(to, 0, Math.Max(_profile.Relics.Count - 1, 0));
		if (to == from) return false;
		_profile.Relics.Move(from, to);          // 顺序真的变 → 序号 / 空槽行数 / 自动类名都跟着它走
		RefreshRelicOrdinals();
		RelicList.SelectedItem = dragged;
		SyncDetail();
		return true;
	}

	// ==================== 药水列表：序号 + 空槽 + 拖动换位置（用户要求第 6 条「药水方面参考遗物的优化方案」）====================
	//
	// 照遗物页那套**逐字搬过来**（V0.2.125 的「每块 5 个预留空槽」+ V0.2.124 的「左侧序号 / 拖动 / 自动类名跟序号走」）：
	//   行数 = 5 × ceil(max(N, 1) / 5)，N = 真药水数（Profile.Potions 是唯一事实来源）：
	//   3 瓶 → 1~5 行（4、5 是空槽）；5 瓶 → 1~5；6 瓶 → 1~10（7~10 是空槽）。
	//   序号是**位置号**（1..N 连续）、不跟随药水移动；空槽只显示灰色序号，
	//   不能被当成药水选中（不污染选中 / 删除 / 全选 / 生成），但可以当拖放落点。
	// ⚠ 空槽**只在** PotionRows 这个界面镜像集合里；Profile.Potions 里永远只有真药水。

	/// <summary>每「一块」预留多少个序号（和遗物页同一个数：一次多生成五个序号）。</summary>
	internal const int PotionSlotsPerBlock = 5;

	/// <summary>
	/// 药水页左侧列表**真正绑的那个集合**：真药水（按 <c>Profile.Potions</c> 的顺序）+ 末尾的空槽行。
	///
	/// <para>为什么要镜像一层：<c>Profile.Potions</c> 是 <c>ObservableCollection&lt;PotionSpec&gt;</c>，
	/// 塞不进占位项；而且「真药水集合 = 唯一事实来源」这条不能破 —— 所以占位项只活在这个界面集合里，
	/// 由 <see cref="SyncPotionRows"/> 单向从 <c>Profile.Potions</c> 铺出来。</para>
	///
	/// <para>⚠ 必须是 <c>public</c>，不能是 <c>internal</c>：WPF 的 <c>PropertyPath</c> 走反射时
	/// **读不到 internal 成员**（遗物页实测踩过：绑 internal 字段时绑定状态直接是 <c>PathError</c>、
	/// <c>ItemsSource</c> 永远是 null，界面上一行都没有）。</para>
	/// </summary>
	public ObservableCollection<ISlotRow> PotionRows { get; } = new();

	/// <summary>
	/// 界面上「当前选中的那一瓶真药水」：选中项是真药水就是它；点中空槽行时**保持上一瓶**
	/// （点空槽不该把右边详情清空）。详情栏的数据上下文绑它。
	/// </summary>
	public PotionSpec? PotionUiSelection
	{
		get => _potionUiSelection;
		private set
		{
			if (!ReferenceEquals(_potionUiSelection, value))
			{
				_potionUiSelection = value;
				Raise("PotionUiSelection");
			}
		}
	}

	private PotionSpec? _potionUiSelection;

	/// <summary>
	/// 详情栏 / 「请选择药水」提示的显隐判据：**列表里有没有选中一行**（选中的那行是空槽也算选了
	/// —— 空槽行照样是列表里的一行，右侧详情不该闪没）。
	/// </summary>
	public bool HasPotionSelection => PotionList?.SelectedItem is not null;

	/// <summary>序号行数：<c>5 × ceil(max(N,1) / 5)</c>（N=0 也显示 1~5）。</summary>
	internal static int PotionSlotRowCount(int potionCount)
	{
		int n = Math.Max(potionCount, 1);
		return ((n + PotionSlotsPerBlock - 1) / PotionSlotsPerBlock) * PotionSlotsPerBlock;
	}

	/// <summary>给每瓶药水重新发一遍「我在列表里排第几」（1 起算），再把界面镜像集合铺一遍。</summary>
	internal void RefreshPotionOrdinals()
	{
		if (_profile?.Potions is null) return;
		for (int i = 0; i < _profile.Potions.Count; i++)
		{
			PotionSpec? s = _profile.Potions[i];
			if (s is not null) s.Ordinal = i + 1;
		}
		SyncPotionRows();
	}

	/// <summary>
	/// 把界面镜像集合铺成「真药水 1..N + 空槽 N+1..5×ceil(N/5)」。
	///
	/// <para>⚠ 和遗物页一样有两个坑要一起挡：
	/// ① <c>Clear()</c> 会让列表的选中项被 WPF 清掉 → 触发 <c>SelectionChanged → SyncDetail → 又回到这里</c>
	/// 的**重入**，两次调用各按自己那份快照铺一遍 → 差一行的陈旧状态（遗物页实测踩到）；
	/// ② 有几处历史代码直接给 <c>Profile</c> 字段赋值（不走属性 setter），
	/// <c>CollectionChanged</c> 还挂在**上一份存档**上 → 这里发现不一致就重挂一次。</para>
	/// </summary>
	internal void SyncPotionRows()
	{
		if (_profile?.Potions is null) return;
		if (!ReferenceEquals(_potionOrderHookedOn, _profile)) HookPotionListOrder();
		if (_inSyncPotionRows)
		{
			_potionRowsDirty = true;
			return;
		}
		_inSyncPotionRows = true;
		try
		{
			do
			{
				_potionRowsDirty = false;
				SyncPotionRowsCore();
			}
			while (_potionRowsDirty);
		}
		finally
		{
			_inSyncPotionRows = false;
		}
	}

	private bool _inSyncPotionRows;

	private bool _potionRowsDirty;

	private void SyncPotionRowsCore()
	{
		if (_profile?.Potions is null) return;
		IList<PotionSpec> potions = _profile.Potions;
		int total = PotionSlotRowCount(potions.Count);
		bool inPlace = PotionRows.Count == total;
		if (inPlace)
		{
			for (int i = 0; i < potions.Count; i++)
			{
				if (!ReferenceEquals(PotionRows[i], potions[i])) { inPlace = false; break; }
			}
		}
		if (inPlace)
		{
			for (int i = potions.Count; i < total; i++)
			{
				if (PotionRows[i] is not SlotPlaceholder ph || ph.Slot != i + 1) { inPlace = false; break; }
			}
		}
		if (inPlace) return;
		if (PotionList is not null && PotionList.SelectedItem is ISlotRow)
		{
			PotionList.SelectedItem = null;
		}
		PotionRows.Clear();
		for (int i = 0; i < potions.Count; i++)
		{
			if (potions[i] is not null) PotionRows.Add(potions[i]);
		}
		for (int i = potions.Count; i < total; i++)
		{
			PotionRows.Add(new SlotPlaceholder(i + 1));
		}
	}

	/// <summary>只挂一次：药水列表增删 → 重排序号 + 重铺空槽。</summary>
	private void HookPotionListOrder()
	{
		if (ReferenceEquals(_potionOrderHookedOn, _profile)) return;
		if (_potionOrderHookedOn is not null) _potionOrderHookedOn.Potions.CollectionChanged -= OnPotionCollectionChanged;
		_potionOrderHookedOn = _profile;
		if (_profile?.Potions is null) return;
		_profile.Potions.CollectionChanged += OnPotionCollectionChanged;
		RefreshPotionOrdinals();
	}

	private void OnPotionCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e) => RefreshPotionOrdinals();

	/// <summary>已经挂过 <c>CollectionChanged</c> 的那份存档（换存档时先摘再重挂，避免重复订阅）。</summary>
	private CharacterProfile? _potionOrderHookedOn;

	/// <summary>认一遍「界面上当前选中的那一瓶真药水」（选中项是空槽行 / 已失效时就保持 / 清空）。</summary>
	private void RefreshPotionUiSelection()
	{
		if (PotionList?.SelectedItem is PotionSpec sel && _profile.Potions.Contains(sel))
		{
			PotionUiSelection = sel;
			return;
		}
		if (_potionUiSelection is not null && !_profile.Potions.Contains(_potionUiSelection)) PotionUiSelection = null;
	}

	// 拖动换位置：MouseDown 记起点 → MouseMove 超过系统阈值才开始拖 → Drop 真插进去
	private Point _potionDragStart;
	private PotionSpec? _potionDragItem;

	/// <summary>拖动换位置：按住某一行的文字往下 / 往上拖超过系统拖动阈值才起拖（不然点一下选中会被当成拖动）。</summary>
	private void OnPotionListPreviewMouseDown(object sender, MouseButtonEventArgs e)
	{
		_potionDragStart = e.GetPosition(PotionList);
		_potionDragItem = PotionAtPoint(e.GetPosition(PotionList));
	}

	/// <summary>
	/// 鼠标位置下面是**哪一行**（可视树往上找 ListBoxItem，再按它在列表里的位置给行号）。
	/// 返回值里 <c>Potion</c> 为 null = 那一行是空槽（或鼠标下面是列表空白处）。
	///
	/// <para>为什么要给行号而不是只给药水：空槽行也要能当**拖放落点**（拖到第 k 行 = 放到第 k 位），
	/// 而空槽行没有 <c>PotionSpec</c> 可以拿。</para>
	/// </summary>
	private (int Index, PotionSpec? Potion) PotionRowAtPoint(Point p)
	{
		DependencyObject? hit = PotionList.InputHitTest(p) as DependencyObject;
		while (hit is not null && hit is not ListBoxItem)
			hit = VisualTreeHelper.GetParent(hit);
		if (hit is not ListBoxItem item) return (-1, null);
		int index = PotionList.ItemContainerGenerator.IndexFromContainer(item);
		return (index, item.DataContext as PotionSpec);
	}

	/// <summary>鼠标位置下面是哪瓶真药水（空槽 / 空白处 → null）。拖动「拿起来」那条路径用它。</summary>
	private PotionSpec? PotionAtPoint(Point p) => PotionRowAtPoint(p).Potion;

	private void OnPotionListPreviewMouseMove(object sender, MouseEventArgs e)
	{
		if (e.LeftButton != MouseButtonState.Pressed || _potionDragItem is null) return;
		Point now = e.GetPosition(PotionList);
		if (Math.Abs(now.X - _potionDragStart.X) < SystemParameters.MinimumHorizontalDragDistance
			&& Math.Abs(now.Y - _potionDragStart.Y) < SystemParameters.MinimumVerticalDragDistance) return;
		PotionSpec dragged = _potionDragItem;
		_potionDragItem = null;
		try
		{
			DragDrop.DoDragDrop(PotionList, new DataObject(typeof(PotionSpec), dragged), DragDropEffects.Move);
		}
		catch (Exception ex)
		{
			SetStatus("拖动药水失败：" + ex.Message);
		}
	}

	private void OnPotionListDragOver(object sender, DragEventArgs e)
	{
		e.Effects = e.Data.GetDataPresent(typeof(PotionSpec)) ? DragDropEffects.Move : DragDropEffects.None;
		e.Handled = true;
	}

	private void OnPotionListDrop(object sender, DragEventArgs e)
	{
		if (!e.Data.GetDataPresent(typeof(PotionSpec))) return;
		if (e.Data.GetData(typeof(PotionSpec)) is not PotionSpec dragged) return;
		(int index, PotionSpec? over) = PotionRowAtPoint(e.GetPosition(PotionList));
		if (!MovePotionTo(dragged, over, index))
		{
			SetStatus($"「{dragged.Name}」已经在这个位置了。");
			return;
		}
		SetStatus($"已把药水「{dragged.Name}」拖到第 {Profile.Potions.IndexOf(dragged) + 1} 位（自动生成的英文类名会在下次重新生成时跟着序号走）。");
	}

	/// <summary>
	/// 拖动落点的那一步（**纯逻辑**，和鼠标 / 拖放事件无关 —— 自检直接调它）。
	/// 语义和遗物页的 <see cref="MoveRelicTo"/> 完全一致：**插到那一行的位置**（拖谁到哪就插到哪）。
	/// 返回 false = 位置没变（不用刷界面）。
	/// </summary>
	internal bool MovePotionTo(PotionSpec dragged, PotionSpec? over, int overRowIndex = -1)
	{
		int from = _profile.Potions.IndexOf(dragged);
		if (from < 0) return false;
		int to;
		if (over is not null)
		{
			to = _profile.Potions.IndexOf(over);
		}
		else
		{
			to = overRowIndex >= 0 ? overRowIndex : _profile.Potions.Count - 1;
		}
		to = Math.Clamp(to, 0, Math.Max(_profile.Potions.Count - 1, 0));
		if (to == from) return false;
		_profile.Potions.Move(from, to);
		RefreshPotionOrdinals();
		PotionList.SelectedItem = dragged;
		SyncDetail();
		return true;
	}

	/// <summary>自检用：药水效果列表里最高的那一行有多宽（照遗物页那条：行宽必须 ≤ 列表宽）。</summary>
	internal double PotionEffectListActualMaxItemWidth()
	{
		double max = 0;
		for (int i = 0; i < PotionEffectList.Items.Count; i++)
		{
			if (PotionEffectList.ItemContainerGenerator.ContainerFromIndex(i) is FrameworkElement fe)
				max = Math.Max(max, fe.ActualWidth);
		}
		return max;
	}

	/// <summary>自检用：效果列表里最高的那一行有多宽（V0.2.124 那个 bug 里它是 8260、视口只有 414）。</summary>
	internal double RelicEffectListActualMaxItemWidth()
	{
		double max = 0;
		for (int i = 0; i < RelicEffectList.Items.Count; i++)
		{
			if (RelicEffectList.ItemContainerGenerator.ContainerFromIndex(i) is FrameworkElement fe)
				max = Math.Max(max, fe.ActualWidth);
		}
		return max;
	}

	// ===== 自检用：效果栏的「看得见的证据」 =====
	//
	// V0.2.144 起三页（遗物 / 药水 / 额外资源量）右侧和卡牌页**同一个形状**：
	//   上面 = 一行摘要列表（每行就是 EffectSpec.Display），下面 = 一整块共享编辑区
	//   （DataContext 绑列表的 SelectedItem）。
	// 所以自检要的证据是**可视树上的**：
	//   · 列表里某一行的容器（ItemContainerGenerator）里显示的那一行摘要文字；
	//   · 选中一条之后，编辑区那块 Border 的 DataContext 真的换成了这条效果（不是 null / 不是上一条）；
	//   · 编辑区里真的有「效果种类」下拉 / 「数值」框 / 这条效果自己的条件下拉，并且改值真的写回模型。
	// ⚠ ListBox 默认虚拟化：行容器只在**滚到视口里**才生成，所以这些断言只对前几行有意义
	//   （自检一律取第 0 行）。

	/// <summary>自检用：可视树里第一个叫这个名字的元素（找不到返回 null）。</summary>
	internal static FrameworkElement? FindNamedElement(DependencyObject root, string name)
	{
		if (root is FrameworkElement fe && string.Equals(fe.Name, name, StringComparison.Ordinal)) return fe;
		int n = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < n; i++)
		{
			FrameworkElement? hit = FindNamedElement(VisualTreeHelper.GetChild(root, i), name);
			if (hit is not null) return hit;
		}
		return null;
	}

	/// <summary>自检用：可视树里所有叫这个名字的元素。</summary>
	internal static List<FrameworkElement> FindNamedElements(DependencyObject root, string name)
	{
		var found = new List<FrameworkElement>();
		if (root is FrameworkElement fe && string.Equals(fe.Name, name, StringComparison.Ordinal)) found.Add(fe);
		int n = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < n; i++) found.AddRange(FindNamedElements(VisualTreeHelper.GetChild(root, i), name));
		return found;
	}

	/// <summary>自检用：效果列表里第 <paramref name="row"/> 行的容器（没生成返回 null —— 见上面虚拟化的说明）。</summary>
	internal static FrameworkElement? EffectRowContainer(ListBox list, int row) =>
		row >= 0 && row < list.Items.Count ? list.ItemContainerGenerator.ContainerFromIndex(row) as FrameworkElement : null;

	/// <summary>
	/// 自检用：摘要列表里第 <paramref name="row"/> 行**显示出来的那一行文字**
	/// （= 列表行绑定 <c>EffectSpec.Display</c> 渲染出来的文本；行容器还没生成就返回 null）。
	/// </summary>
	internal static string? EffectRowSummaryText(ListBox list, int row)
	{
		FrameworkElement? container = EffectRowContainer(list, row);
		if (container is null) return null;
		var blocks = new List<TextBlock>();
		CollectTextBlocks(container, blocks);
		return blocks.Select(b => b.Text)
			.FirstOrDefault(t => !string.IsNullOrWhiteSpace(t));
	}

	/// <summary>
	/// 自检用：效果列表的这一行里有没有 <see cref="Button"/>。
	///
	/// <para>V0.2.144 起三页效果行是**普通 ListBoxItem**（一行摘要），「展开 / 收起」那套交互整块删了 ——
	/// 所以这里恒为 false；万一以后有人把「整行是一颗 Button」那种写法加回来，这条断言会立刻红
	/// （那正是 V0.2.143「条件选完存不住」的结构性原因）。</para>
	/// </summary>
	internal static bool EffectRowContainsButton(FrameworkElement row)
	{
		var buttons = new List<Button>();
		CollectButtons(row, buttons);
		return buttons.Count > 0;
	}

	/// <summary>自检用：子树里第一个「绑到指定路径」的下拉（用来确认展开区里的编辑器真的在）。</summary>
	internal static ComboBox? FindFirstComboBoxBound(DependencyObject root, string path)
	{
		var all = new List<ComboBox>();
		CollectCombos(root, all);
		return all.FirstOrDefault(c => BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == path);
	}

	/// <summary>自检用：子树里第一个「绑到指定路径」的输入框（用来确认展开区里改值真的写回模型）。</summary>
	internal static TextBox? FindFirstTextBoxBound(DependencyObject root, string path)
	{
		var all = new List<TextBox>();
		CollectTextBoxes(root, all);
		return all.FirstOrDefault(t => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path == path);
	}

	/// <summary>
	/// 自检用：这棵子树里有没有「跑出 <paramref name="panel"/> 之外」的可见控件。
	/// 只比**不包含任何子元素**的那些（叶子 / 无孩子容器）—— 父容器天然包着孩子，拿它们比会全是误报。
	/// 容差 <paramref name="tol"/> 像素用来吃掉边框 / 内边距。
	/// </summary>
	internal static List<FrameworkElement> VisibleElementsOutside(DependencyObject panel, double tol)
	{
		var result = new List<FrameworkElement>();
		if (panel is not FrameworkElement root || !root.IsVisible) return result;
		Rect bounds = new Rect(0, 0, root.ActualWidth, root.ActualHeight);
		var all = new List<FrameworkElement>();
		CollectFrameworkElements(panel, all);
		foreach (FrameworkElement fe in all)
		{
			if (!fe.IsVisible || fe.ActualWidth <= 0 || fe.ActualHeight <= 0) continue;
			if (VisualTreeHelper.GetChildrenCount(fe) > 0) continue;   // 只看叶子，父容器天然重叠
			Point p;
			try { p = fe.TransformToAncestor(root).Transform(new Point(0, 0)); } catch { continue; }
			Rect r = new Rect(p.X, p.Y, fe.ActualWidth, fe.ActualHeight);
			// 自检用：这棵子树里有没有「明显跑出 <paramref name="panel"/> 右侧」的可见控件。
			// 只比**不包含任何子元素**的那些（叶子 / 无孩子容器）—— 父容器天然包着孩子，拿它们比会全是误报。
			// 判据用**相对容差**（默认 25%）：排版里「一段不换行的文字比格子宽几十像素」是正常现象，
			// 而 V0.2.124 那个 bug 是宽出 7800 多像素（19 倍），一定抓得住。
			if (r.Right - bounds.Right > Math.Max(tol, bounds.Width * 0.25)) result.Add(fe);
		}
		return result;
	}

	/// <summary>自检用：可见、但实际尺寸小到没法用的控件（把「看得见」和「真的能用」分开验）。</summary>
	internal static List<FrameworkElement> VisibleZeroSizedControls(DependencyObject panel, double minPixels)
	{
		var result = new List<FrameworkElement>();
		var all = new List<FrameworkElement>();
		CollectFrameworkElements(panel, all);
		foreach (FrameworkElement fe in all)
		{
			if (!fe.IsVisible) continue;
			// 只挑「本该有尺寸」的那些：输入控件 / 列表 / 按钮
			if (fe is not (Control or ListBoxItem)) continue;
			if (fe.ActualWidth >= minPixels && fe.ActualHeight >= minPixels) continue;
			if (fe.ActualWidth <= 0.01 && fe.ActualHeight <= 0.01) result.Add(fe);
		}
		return result;
	}

	/// <summary>自检用：把一棵子树里所有 FrameworkElement 收进来。</summary>
	private static void CollectFrameworkElements(DependencyObject root, List<FrameworkElement> into)
	{
		int n = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < n; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is FrameworkElement fe) into.Add(fe);
			CollectFrameworkElements(child, into);
		}
	}

	private void OnAddPotion(object sender, RoutedEventArgs e)
	{
		_profile.Potions.Add(new PotionSpec
		{
			Name = "新药水",
			Rarity = "Common",
			Usage = "CombatOnly",
			TargetType = "Self"
		});
		SyncDetail();
		// V0.2.127：列表 ItemsSource 改成**界面镜像集合** PotionRows（真药水 + 末尾空槽行），
		// SelectedIndex 会被空槽占掉 —— 选对象本身更稳（和 OnAddRelic 同一套）。
		PotionList.SelectedItem = _profile.Potions[_profile.Potions.Count - 1];
	}

	private void OnRemovePotion(object sender, RoutedEventArgs e)
	{
		List<PotionSpec> picked = SelectedOf<PotionSpec>(PotionList);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的药水（可 Ctrl/Shift 多选，或点「全选」）。");
			return;
		}
		string what = ((picked.Count == 1) ? ("药水「" + picked[0].Name + "」") : $"选中的 {picked.Count} 瓶药水");
		if (ConfirmDelete(what))
		{
			int value = RemoveManyWithUndo(_profile.Potions, picked, _potionUndo, "药水", delegate
			{
				PotionList.SelectedItem = picked[0];
			});
			SetStatus($"已删除 {value} 瓶药水（可点「撤回删除」恢复）");
		}
	}

	private void OnAddKeyword(object sender, RoutedEventArgs e)
	{
		_profile.CustomKeywords.Add(new CustomKeywordSpec { Name = "新关键词" });
		SyncDetail();
		KeywordList.SelectedIndex = _profile.CustomKeywords.Count - 1;
		SetStatus("已添加关键词：填好名字和说明，然后到「卡牌」页勾选哪张牌用它。");
	}

	private void OnRemoveKeyword(object sender, RoutedEventArgs e)
	{
		List<CustomKeywordSpec> picked = SelectedOf<CustomKeywordSpec>(KeywordList);
		if (picked.Count == 0)
		{
			SetStatus("请先选中要删除的关键词（没有就点左边的「添加关键词」）。");
			return;
		}
		string what = picked.Count == 1 ? "关键词「" + picked[0].Name + "」" : $"选中的 {picked.Count} 条关键词";
		if (ConfirmDelete(what))
		{
			// 卡牌上的引用一起清掉：否则生成前校验会报「引用了不存在的关键词」，用户还得逐张去取消勾选。
			// 注意「撤回删除」只恢复关键词本身，卡牌上的勾选要重新点。
			int cleaned = ClearKeywordRefs(picked);
			int value = RemoveManyWithUndo(_profile.CustomKeywords, picked, _keywordUndo, "关键词", delegate
			{
				KeywordList.SelectedItem = picked[0];
			});
			SyncDetail();
			SetStatus($"已删除 {value} 条关键词" + (cleaned > 0 ? $"（同时取消了 {cleaned} 张卡上的引用）" : "")
				+ "（可点「撤回删除」恢复关键词，卡牌上的勾选要重新点）");
		}
	}

	/// <summary>删除关键词时，把卡牌上对它的引用一并去掉（本地化键和中文名两种写法都清）。</summary>
	private int ClearKeywordRefs(List<CustomKeywordSpec> removed)
	{
		var keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var item in KeywordGen.All(_profile))
		{
			if (!removed.Contains(item.Spec)) continue;
			keys.Add(item.Key);
			keys.Add((item.Spec.Name ?? "").Trim());
		}
		int cleaned = 0;
		foreach (var card in _profile.Cards)
		{
			var kept = card.CustomKeywordList.Where(x => !keys.Contains(x.Trim())).ToList();
			if (kept.Count != card.KeywordIds.Count)
			{
				card.KeywordIds = kept;
				cleaned++;
			}
		}
		return cleaned;
	}

	private ListBox? ListFromTag(object sender)
	{
		return (sender as FrameworkElement)?.Tag as ListBox;
	}

	/// <summary>
	/// 卡牌页的效果列表换了选中项：告诉那条效果「你现在在**卡牌链**上」。"
	///
	/// 为什么要这个标记（用户要求：「效果那边只要保留公式就行，去掉数值框」），"
	/// 公式**只做在卡牌上**（遗物 / 药水 / 状态那几条链没有「打出这张牌」那一刻的上下文，校验器会拦住），
	/// 所以只有卡牌上的那 5 种效果才把「数值」框收起来（公式留空 = 0）；别处照旧要那个框。"
	/// 效果对象自己分不清「我在哪条链上」，所以由界面在这里点一下。"
	/// </summary>
	private void OnCardEffectSelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		if (CardEffectList.SelectedItem is EffectSpec shown) shown.IsCardChain = true;
		// 同一张牌上没被选中的那几条也算卡牌链上的（切过去时不会先闪一下「数值」框）"
		if (CardList.SelectedItem is CardSpec card)
			foreach (EffectSpec fx in card.Effects)
				if (fx is not null) fx.IsCardChain = true;
	}

	private void OnAddEffect(object sender, RoutedEventArgs e)	{
		ListBox listBox = ListFromTag(sender);
		object obj = listBox?.DataContext;
		IList<EffectSpec> list = EffectsOf(obj);
		if (listBox == null || list == null)
		{
			SetStatus("请先在左边选中要编辑的条目。");
			return;
		}
		// 新效果的数值 / 升级增量一律默认 0（用户要求）：以前卡牌上默认「伤害 6 / 升级 +3」，
		// 用户只是想加一条别的效果时，先得把这两个数字清掉，很容易漏 → 生成出莫名其妙的数值。
		// 默认 0 之后：选好「效果种类」再自己填，填漏了校验器也会提示（例：伤害要大于 0）。
		EffectSpec effectSpec = new EffectSpec
		{
			Kind = "Damage",
			Amount = 0m,
			UpgradeAmount = 0m,
			TargetSide = "Enemy",
			AllowDuplicates = true,
		};
		list.Add(effectSpec);
		SyncDetail();
		listBox.SelectedItem = effectSpec;
	}

	// ===== V0.2.144：折叠行那一套（OnToggleEffectRow / SelectEffectRowOf / ListBoxOwningEffect /
	//       CollectListBoxes / ToggleEffectRow）**整块删掉** =====
	//
	// 为什么可以删：三页右侧（遗物 / 药水 / 额外资源量）现在和卡牌页**同一个形状** ——
	//   上面一行摘要列表（普通 ListBoxItem，没有任何 Button 挡点击）→ 点一条 = 原生选中；
	//   下面一整块共享编辑区（DataContext 绑 SelectedItem），条件的入口就在编辑区里。
	// 于是：
	//   · 不需要「点行顺手把这一行选中」的补丁了 —— 行不再是 Button，ListBoxItem 的选中行为天然生效
	//     （V0.2.143 那个「条件选完存不住」的结构性原因**从根上没有了**）；
	//   · 不需要 EffectSpec.IsExpanded 这个纯界面标记了（已从模型删掉）。
	// 卡牌页一直是这个形状，所以它一个字都没动。

	/// <summary>
	/// 自检用：验证「CLI 的 `--build` **不给 `--install` 时绝不安装**」这条红线⑧没被改回去
	/// （V0.2.137：根因是 `ModBuilder.Build(..., installDir ?? profile.Paths.InstallDir, ...)` 那个兜底）。
	///
	/// <para>分两层证据：
	/// ① <b>契约层（编译进 dll，任何环境都能查）</b>：<see cref="ModBuilder.Build"/> 的文档里必须写着
	///    「调用方不许在这里替用户兜底填目录」——改回兜底的人一定会踩到这条；</para>
	/// ② <b>源码层（只在仓库里跑得起来；部署版找不到就跳过）</b>：CLI 的 <c>Program.cs</c> 里不许出现
	///    那个兜底表达式，且必须把 <c>installDir</c> 直接透传给 ModBuilder。</para>
	///
	/// <returns>(是否通过, 证据文本, 是否只验了契约层)。</returns>
	/// </summary>
	internal static (bool Ok, string Detail, bool ContractOnly) CheckCliNeverInstallsImplicitly()
	{
		var detail = new List<string>
		{
			"契约：ModBuilder.Build 的 installDir 为 null 时安装整块跳过（注释里写明「调用方不许兜底」）",
		};

		// 源码层：从 exe 目录往上找 CLI 的 Program.cs（部署版找不到 → 跳过这一层）
		string? programCs = null;
		try
		{
			var dir = new DirectoryInfo(AppContext.BaseDirectory);
			for (int up = 0; up < 8 && dir is not null && programCs is null; up++, dir = dir.Parent)
			{
				string candidate = Path.Combine(dir.FullName, "src", "Sts2CharForge.Cli", "Program.cs");
				if (File.Exists(candidate)) { programCs = candidate; break; }
			}
		}
		catch { }
		if (programCs is null)
		{
			detail.Add("源码层：找不到 CLI 的 Program.cs（部署版正常，跳过）");
			return (true, string.Join(" ｜ ", detail), true);
		}
		string src;
		try { src = File.ReadAllText(programCs); }
		catch { return (true, string.Join(" ｜ ", detail) + " ｜ 源码层：读不到 Program.cs（跳过）", true); }

		// ⚠ 必须**先去掉注释行**再查：Program.cs 里故意留着「以前写的是 `installDir ?? …`」那句说明根因的注释，
		// 直接 Contains 会误报（第一版就是这么 FAIL 的 —— 注释里也含那个表达式）。去掉注释才是真正的代码。
		string code = string.Join("\n", src.Replace("\r\n", "\n").Split('\n')
			.Where(line => !line.TrimStart().StartsWith("//", StringComparison.Ordinal)));

		bool oldFallback = code.Contains("installDir ?? profile.Paths.InstallDir", StringComparison.Ordinal);
		bool passesThrough = code.Contains("installDir, Console.WriteLine, profile.Paths.DotnetExe", StringComparison.Ordinal);
		detail.Add(oldFallback
			? "源码层：**代码里又出现了** `installDir ?? profile.Paths.InstallDir` 兜底！"
			: "源码层：代码里没有 `installDir ?? profile.Paths.InstallDir` 兜底（注释里那句说明不受影响）");
		detail.Add(passesThrough ? "源码层：`installDir` 直接透传给 ModBuilder" : "源码层：**没有**把 installDir 直接透传（Build 调用形状变了）");
		return (!oldFallback && passesThrough, string.Join(" ｜ ", detail), false);
	}

	/// <summary>
	/// 自检用：GUI 侧「装不装」是由用户点的（<c>install ? text : null</c>），不是拿 <c>Paths.InstallDir</c>
	/// 硬装 —— 这条和 CLI 那条是同一个契约的两半。只做源码层检查（找不到源码就跳过）。
	/// </summary>
	internal static (bool Ok, string Detail) CheckGuiInstallIsExplicit()
	{
		string? me = null;
		try
		{
			var dir = new DirectoryInfo(AppContext.BaseDirectory);
			for (int up = 0; up < 8 && dir is not null && me is null; up++, dir = dir.Parent)
			{
				string candidate = Path.Combine(dir.FullName, "src", "Sts2CharForge.App", "MainWindow.xaml.cs");
				if (File.Exists(candidate)) { me = candidate; break; }
			}
		}
		catch { }
		if (me is null) return (true, "源码层：找不到 MainWindow.xaml.cs（部署版正常，跳过）");
		try
		{
			string src = File.ReadAllText(me);
			bool explicitGate = src.Contains("string installTo = (install ? text : null);", StringComparison.Ordinal);
			bool passedIn = src.Contains("godotExe, installTo, progress.Report, dotnetExe", StringComparison.Ordinal);
			return (explicitGate && passedIn,
				(explicitGate ? "有 `install ? text : null`" : "**没有** `install ? text : null` 那道闸")
				+ " ｜ " + (passedIn ? "installTo 透传进 ModBuilder" : "**没有**把 installTo 透传进 ModBuilder"));
		}
		catch { return (true, "源码层：读不到 MainWindow.xaml.cs（跳过）"); }
	}

	private void OnRemoveEffect(object sender, RoutedEventArgs e)
	{
		ListBox lb = ListFromTag(sender);
		object obj = lb?.DataContext;
		IList<EffectSpec> list = EffectsOf(obj);
		if (lb == null || list == null)
		{
			return;
		}
		List<EffectSpec> list2 = lb.SelectedItems.OfType<EffectSpec>().ToList();
		if (list2.Count == 0)
		{
			SetStatus("请先选中要删除的效果（可 Ctrl/Shift 多选）。");
			return;
		}
		// ⚠ V0.2.137：这里原来只认 卡牌 / 遗物 / 药水 / 自定义状态，**额外资源量页的「删除效果」**
		// 会掉进最后那个兜底分支（撤回栈 = _cardUndo、文案 = 光秃秃的「效果」）——
		// 栈虽然能对上（那一页的「撤回删除」按钮走的就是 OnUndoCard/_cardUndo），但文案看不出删的是哪一份。
		// 现在给它一条自己的分支（栈仍然是 _cardUndo，和「撤回删除」按钮一致）。
		(Stack<UndoEntry>, string) tuple = ((obj is CardSpec cardSpec) ? (_cardUndo, "卡牌「" + cardSpec.Name + "」的效果") : ((obj is RelicSpec relicSpec) ? (_relicUndo, "遗物「" + relicSpec.Name + "」的效果") : ((obj is PotionSpec potionSpec) ? (_potionUndo, "药水「" + potionSpec.Name + "」的效果") : ((obj is ExtraResourceSpec) ? (_cardUndo, "额外资源量遗物的效果") : ((!(obj is PowerTriggerSpec powerTriggerSpec)) ? (_cardUndo, "效果") : (_powerUndo, "自定义状态的「" + (PowerTriggers.Find(powerTriggerSpec.Kind)?.Display ?? powerTriggerSpec.Kind) + "」效果"))))));
		(Stack<UndoEntry>, string) tuple2 = tuple;
		Stack<UndoEntry> item = tuple2.Item1;
		string item2 = tuple2.Item2;
		string what = ((list2.Count == 1) ? (item2 + "「" + list2[0].Display + "」") : $"{item2}（{list2.Count} 条）");
		if (ConfirmDelete(what))
		{
			int value = RemoveManyWithUndo(list, list2, item, "效果", delegate
			{
				lb.SelectedIndex = 0;
			});
			SetStatus($"已删除 {value} 条效果（可点「撤回删除」恢复）");
		}
	}

	private static IList<EffectSpec>? EffectsOf(object? spec)
	{
		if (!(spec is CardSpec cardSpec))
		{
			if (!(spec is RelicSpec relicSpec))
			{
				// ⚠ V0.2.126：触发时机**不再挂效果**（效果是整只遗物那一份）—— 所以这里没有
				// RelicTriggerSpec 分支了（效果栏的 DataContext 现在一定是 RelicSpec / 卡牌 / 药水 / 状态）。
				if (!(spec is PotionSpec potionSpec))
				{
					// ⚠ V0.2.137：补上**额外资源量**那一支。这页右栏的效果列表
					// （<c>ExtraResourceEffectList</c>，MainWindow.xaml:513）的 DataContext 是
					// <c>Profile.ExtraResource</c>（ExtraResourceSpec），效果就在 <c>ExtraResourceSpec.Effects</c>。
					// 以前这里没有这一支 → 返回 null → 「添加效果 / 删除效果」只弹一句
					// 「请先在左边选中要编辑的条目。」什么都不做（用户当天报的①原话：
					// 「额外资源量右侧那个添加效果点了没反应」）。它的视图类不是 SpecBase、也不参与
					// 遗物池，所以最容易漏 —— 以后再加「效果栏」的宿主时，这个函数是**必改点**。
					if (spec is ExtraResourceSpec extraResourceSpec)
					{
						return extraResourceSpec.Effects;
					}
					if (spec is PowerTriggerSpec powerTriggerSpec)
					{
						return powerTriggerSpec.Effects;
					}
					return null;
				}
				return potionSpec.Effects;
			}
			return relicSpec.Effects;
		}
		return cardSpec.Effects;
	}

	private void OnPickCardPortrait(object sender, RoutedEventArgs e)
	{
