		}
	}

	private DependencyObject SelectTabRoot(string header)
	{
		foreach (object item in (IEnumerable)MainTabs.Items)
		{
			if (item is TabItem tabItem && string.Equals(tabItem.Header as string, header, StringComparison.Ordinal))
			{
				MainTabs.SelectedItem = tabItem;
				UpdateLayout();
				return (DependencyObject)tabItem.Content;
			}
		}
		throw new InvalidOperationException("界面上没有标题为「" + header + "」的选项卡");
	}

	private TabItem? FindTab(string header)
	{
		foreach (object item in (IEnumerable)MainTabs.Items)
		{
			if (item is TabItem tabItem && string.Equals(tabItem.Header as string, header, StringComparison.Ordinal))
			{
				return tabItem;
			}
		}
		return null;
	}

	private static CharacterProfile WithCarryOver(CharacterProfile p, bool carryOver)
	{
		CharacterProfile characterProfile = ProfileFactory.Sample();
		characterProfile.CharacterClass = p.CharacterClass;
		characterProfile.ExtraResource.Enabled = p.ExtraResource.Enabled;
		characterProfile.ExtraResource.Initial = p.ExtraResource.Initial;
		characterProfile.ExtraResource.AlwaysShowCounter = p.ExtraResource.AlwaysShowCounter;
		characterProfile.ExtraResource.CarryOver = carryOver;
		return characterProfile;
	}

	/// <summary>
	/// 本体 <c>StringHelper.Slugify</c> 的等价实现 —— <b>只在自检里当参照物</b>（不参与生成，生成走
	/// <see cref="Naming.Slug"/>）。本体就是这三步：连续大写的驼峰插下划线 → 转大写 → 滤掉 <c>[^A-Z0-9_]</c>。
	/// 第一个正则里那个 <c>\G(?!^)</c> 分支是关键：连续大写时**每个**大写字母前面都要插下划线
	/// （<c>AIPet → A_I_PET</c>），只写 <c>([A-Za-z0-9])([A-Z])</c> 会漏掉后面那几个。
	/// </summary>
	private static string VanillaSlugify(string txt)
	{
		string text = System.Text.RegularExpressions.Regex.Replace(txt.Trim(), "([A-Za-z0-9]|\\G(?!^))([A-Z])", "$1_$2");
		string input = System.Text.RegularExpressions.Regex.Replace(text.ToUpperInvariant(), "\\s+", "_");
		return System.Text.RegularExpressions.Regex.Replace(input, "[^A-Z0-9_]", "");
	}

	/// <summary>自检用：造一份只含一张「消耗手牌」效果的存档，用来验「取几张」三档」 /summary>
	private static CharacterProfile WithCountMode(string mode, string pick)
	{
		CharacterProfile p = ProfileFactory.Sample();
		p.Cards.Clear();
		var c = new CardSpec { Name = "自检取几张", ClassName = "UiCheckModeX", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
		c.Effects.Clear();
		c.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 3m, CardPick = pick, SelectPile = "Hand", CountMode = mode });
		p.Cards.Add(c);
		return p;
	}

	/// <summary>
	/// 自检用：「取几张」支持「全部（不弹选牌界面）」的那 15 种选牌类效果
	/// （V0.2.163；和 <see cref="Sts2CharForge.Core.Effects.EffectFieldPolicy.UsesCountMode"/> 同一份名单）。
	/// </summary>
	private static readonly string[] AllModeKinds =
		new[] { "ExhaustCard", "DiscardCard", "UpgradeCard", "CopyCard", "ReplayCard", "TransformCard",
			"TurnEndPlay", "PlaceCard", "GiveKeyword", "TakeFromDraw", "TakeFromDiscard", "TakeFromExhaust",
			"RemoveCardGlobal", "UpgradeCardGlobal", "TransformCardGlobal" };

	/// <summary>自检用：造一条「取几张 = 全部」的效果（按种类补齐它必须的那几个字段）。</summary>
	private static EffectSpec AllModeEffect(string kind) => new()
	{
		Kind = kind,
		Amount = 3m,
		Copies = 2,
		ReplayTimes = 1,
		CardPick = "Chosen",
		SelectPile = kind switch
		{
			"TakeFromDraw" => "Draw",
			"TakeFromDiscard" => "Discard",
			"TakeFromExhaust" => "Exhaust",
			_ => "Hand",
		},
		PlaceTo = "Discard",
		GivenKeyword = "Ethereal",
		CountMode = "All",
		TargetSide = "Self",
	};

	/// <summary>自检用：把某一种「全部」档效果的生成代码 + 卡面文字一起返回。</summary>
	private static string AllModeCodeFor(string kind)
	{
		CharacterProfile p = ProfileFactory.Sample();
		p.Cards.Clear();
		var c = new CardSpec { Name = "全部档", ClassName = "UiCheckAll" + kind, CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
		c.Effects.Clear();
		c.Effects.Add(AllModeEffect(kind));
		p.Cards.Add(c);
		return CSharpCodeGen.CardSource(p, c, 0) + "\u0001" + LocalizationGen.CardsJson(p);
	}

	/// <summary>自检用的样例：常规驼峰 + 连续大写（连续大写是踩过的坑）。</summary>
	private static readonly string[] SlugSamples =
		new string[8] { "XiaoQi", "XiaoQI", "MyPetAI", "AIPet", "SparklePet2", "SevenCard1", "WeakPower", "UiCheckPet2" };

	/// <summary>
	/// 自检用（V0.2.167）：造一张「锻造卡」——【触发时机】=卡牌被打出时 →【效果】生成 / 复制卡牌，
	/// 并且在新编辑器那份 <c>EffectSpec</c> 上勾附加处理 / 加关键词 / 复制份数（老字段里没有这几栏）。
	/// </summary>
	private static CardSpec MakeGraphModProbeCard(string name, string cls, string target, bool copy = false,
		bool tempUpgradeThisTurn = false, int copies = 1, ForgeNodeSpec? replaceEffect = null)
	{
		var card = new CardSpec { Name = name, ClassName = cls, CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true };
		card.ForgeGraph = new ForgeGraphSpec();
		var trig = new ForgeNodeSpec { Kind = "Trigger" };
		trig.SetField("Timing", ForgeTimings.CardPlayed);
		card.ForgeGraph.Nodes.Add(trig);
		var eff = replaceEffect ?? new ForgeNodeSpec { Kind = "Effect" };
		if (replaceEffect is null)
		{
			eff.SetField("Effect", copy ? "CopyCard" : "GenerateCard");
			eff.SetField("Amount", "2");
			eff.SetField("Pick", "Random");
			eff.SetField("SpawnCardId", target);
			eff.SetField("SpawnTo", "Hand");
		}
		card.ForgeGraph.Nodes.Add(eff);
		card.ForgeGraph.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id, FromPort = 0, ToPort = 0 });
		if (replaceEffect is null)
		{
			var spec = ForgeEffectBridge.Ensure(eff, authored: true);
			if (spec is not null)
			{
				spec.SpawnUpgraded = true;
				spec.SpawnFreeThisTurn = true;
				spec.SpawnKeyword = "Retain";
				spec.SpawnUpgradedThisTurn = tempUpgradeThisTurn;
				if (copy && copies > 1) spec.Copies = copies;
			}
		}
		return card;
	}

	public string SelfTest()
	{
		StringBuilder sb = _selfTestLog;
		sb.Clear();
		SuppressConfirmations = true;
		SuppressClosePromptForTest = true;
		// 自检必须在【临时目录】里跑：自检会枚举/新建/删除存档，还可能触发静默保存。
		// 打包后的 exe 里 RootFolder 就是部署根目录，ProfileFolder 正是用户真实的「自定义角色存档」——
		// 以前在部署目录里跑 --uicheck 会直接动用户的存档（踩过，很危险）。
		_selfTestRealProfileFolder = ProfileFolder;
		string selfTestFolder = Path.Combine(Path.GetTempPath(), "forge_selftest_" + Guid.NewGuid().ToString("N").Substring(0, 8));
		Directory.CreateDirectory(selfTestFolder);
		OverrideProfileFolderForTest(selfTestFolder);
		RefreshProfiles();
		Show();
		Check("窗口已建立", ok: true);
		// 版本号只有一个来源（csproj 的 InformationalVersion）：启动器名 / 包名 / 窗口标题都用它
		Check("版本号读得到（形如 V0.0.1）",
			AppVersion.Current.StartsWith("V", StringComparison.Ordinal) && AppVersion.Current.Length >= 5
			&& AppVersion.Current.Count((char c) => c == '.') >= 2, AppVersion.Current);
		Check("窗口标题里带版本号", Title.Contains(AppVersion.Current, StringComparison.Ordinal), Title);
		// ===== V0.2.240：小屏幕适配（用户反馈「有一些人的屏幕小，就会发生有一些地方被遮挡」）=====
		// 三件事：① 窗口能被压进屏幕可用区域（MinWidth/MinHeight 也别大到放不下）；② 按屏幕自动挑缩放档；
		// ③ 顶栏有「界面缩放」下拉，改了立刻生效（LayoutTransform —— 布局跟着缩，文字不糊）。
		{
			Check("V0.2.240：窗口有最小尺寸限制（拖不小到不可用），而且不会比常见小屏还宽",
				MinWidth >= 900 && MinWidth <= 1280 && MinHeight >= 520 && MinHeight <= 800,
				$"MinWidth={MinWidth} MinHeight={MinHeight}");
			Check("V0.2.240：启动时会把自己压进屏幕可用区域（宽高都不超过 WorkArea）",
				Width <= Math.Max(MinWidth, SystemParameters.WorkArea.Width) + 0.5
				&& Height <= Math.Max(MinHeight, SystemParameters.WorkArea.Height) + 0.5,
				$"窗口 {Width:0}×{Height:0} / 可用 {SystemParameters.WorkArea.Width:0}×{SystemParameters.WorkArea.Height:0}");
			// 自动档：矮屏要降档，够高的屏保持 100%（纯函数，和真实屏幕无关）
			Check("V0.2.240：自动缩放档按屏幕高度/宽度选（1920×1040 → 100%，1366×728 → 80%，1280×620 → 75%，1024×600 → 70%）",
				AutoUiScaleFor(1920, 1040) == 100 && AutoUiScaleFor(1366, 728) == 80
				&& AutoUiScaleFor(1280, 620) == 75 && AutoUiScaleFor(1024, 600) == 70,
				$"{AutoUiScaleFor(1920, 1040)} / {AutoUiScaleFor(1366, 728)} / {AutoUiScaleFor(1280, 620)} / {AutoUiScaleFor(1024, 600)}");
			Check("V0.2.240：窄屏额外再降一档（宽 < 1300 时最高只给 80%）",
				AutoUiScaleFor(1280, 1040) == 80 && AutoUiScaleFor(1920, 1040) == 100,
				$"1280 宽 → {AutoUiScaleFor(1280, 1040)}%");
			// 顶栏那个下拉：候选就是 UiScalePercents 那一份（界面和自检不会各写一份清单）
			int before = UiScalePercent;
			ApplyUiScale(80);
			Check("V0.2.240：改缩放档立刻作用到整窗（RootPanel.LayoutTransform = 0.8）",
				UiScalePercent == 80 && RootPanel.LayoutTransform is ScaleTransform st80
				&& Math.Abs(st80.ScaleX - 0.8) < 1e-6 && Math.Abs(st80.ScaleY - 0.8) < 1e-6,
				$"scale={(RootPanel.LayoutTransform as ScaleTransform)?.ScaleX:0.00}");
			Check("V0.2.240：「界面缩放」下拉里选中的就是当前档（不会和实际缩放对不上）",
				UiScaleBox is not null && (string?)UiScaleBox.SelectedItem == "80%"
				&& UiScaleBox.Items.Count == UiScalePercents.Length,
				$"选中={(string?)UiScaleBox?.SelectedItem} / 共 {UiScaleBox?.Items.Count} 档");
			ApplyUiScale(before == 0 ? 100 : before);
			Check("V0.2.240：（收尾）缩放恢复原档，后面的排版类自检不受影响",
				UiScalePercent == (before == 0 ? 100 : before)
				&& RootPanel.LayoutTransform is ScaleTransform stBack
				&& Math.Abs(stBack.ScaleX - UiScalePercent / 100.0) < 1e-6,
				$"现在是 {UiScalePercent}%");
		}
		Check("Power 效果库非空（增益+减益）", AllPowers.Count > 0, $"{AllPowers.Count} 项 / {EffectCatalog.CatalogStatus}");
		Check("效果种类选项非空", Kinds.Count > 0, $"{Kinds.Count} 项");
		// 本地化键的算法必须和本体 StringHelper.Slugify 一致（连续大写是踩过的坑：键对不上 → LocException）
		{
			var slugBad = new List<string>();
			var slugRows = new List<string>();
			foreach (string s in SlugSamples)
			{
				string ours = Naming.Slug(s);
				slugRows.Add(s + "→" + ours);
				if (!string.Equals(ours, VanillaSlugify(s), StringComparison.Ordinal))
					slugBad.Add(s + "：我们=" + ours + " / 本体=" + VanillaSlugify(s));
			}
			Check("本地化键：Naming.Slug 与本体 StringHelper.Slugify 完全一致（连续大写 XiaoQI → XIAO_Q_I、AIPet → A_I_PET）",
				slugBad.Count == 0, string.Join(" ｜ ", slugRows));
		}
		// ⚠ V0.2.140 起：卡牌列表的 ItemsSource 也变成**界面镜像集合** CardRows（真卡 + 末尾空槽行），
		// 和遗物 / 药水那两行同一个形状；真卡集合 Profile.Cards 仍是唯一事实来源 ——
		// 这里验「镜像 = Profile.Cards 的真卡那一截 + 末尾按行号给的空槽」。
		Check("卡牌列表绑定到 Profile.Cards 的界面镜像（真卡一截 + 末尾空槽行，每 5 个一块）",
			CardList.ItemsSource == CardRows
			&& CardRows.Count == CardSlotRowCount(Profile.Cards.Count)
			&& CardRows.Take(Profile.Cards.Count).SequenceEqual<ISlotRow>(Profile.Cards)
			&& CardRows.Skip(Profile.Cards.Count).All(r => r.IsPlaceholder && r is SlotPlaceholder),
			$"镜像 {CardRows.Count} 行 = 真卡 {Profile.Cards.Count} + 空槽 {CardRows.Count - Profile.Cards.Count}");
		// ⚠ V0.2.125 起：列表的 ItemsSource 变成**界面镜像集合** RelicRows
		//（真遗物 + 末尾空槽行），真遗物集合 Profile.Relics 仍是唯一事实来源 ——
		// 所以这里改验「镜像 = Profile.Relics 的真遗物那一截」，以及集合身份没被换掉。
		Check("遗物列表绑定到 Profile.Relics 的界面镜像（真遗物一截 + 末尾空槽行）",
			RelicList.ItemsSource == RelicRows
			&& RelicRows.Count == RelicSlotRowCount(Profile.Relics.Count)
			&& RelicRows.Take(Profile.Relics.Count).SequenceEqual<IRelicSlotRow>(Profile.Relics)
			&& RelicRows.Skip(Profile.Relics.Count).All(r => r.IsPlaceholder),
			$"镜像 {RelicRows.Count} 行 = 真遗物 {Profile.Relics.Count} + 空槽 {RelicRows.Count - Profile.Relics.Count}");
		Check("药水列表绑定到 Profile.Potions 的界面镜像（真药水一截 + 末尾空槽行）—— V0.2.127 起和遗物页同一套",
			PotionList.ItemsSource == PotionRows
			&& PotionRows.Count == PotionSlotRowCount(Profile.Potions.Count)
			&& PotionRows.Take(Profile.Potions.Count).SequenceEqual<ISlotRow>(Profile.Potions)
			&& PotionRows.Skip(Profile.Potions.Count).All(r => r.IsPlaceholder),
			$"镜像 {PotionRows.Count} 行 = 真药水 {Profile.Potions.Count} + 空槽 {PotionRows.Count - Profile.Potions.Count}");
		Check("关键词列表绑定到 Profile.CustomKeywords", KeywordList.ItemsSource == Profile.CustomKeywords);
		Check("美术槽位已建立（13 个上传槽位 + 描边颜色输入）", ArtSlots.Count == 13, $"{ArtSlots.Count} 个");
		// ===== 无色卡（用户要求：进本体无色卡池 + 用本体无色卡框）=====
		{
			CharacterProfile clProbe = ProfileFactory.Sample();
			CardSpec clCard = new CardSpec { Name = "自检无色卡", ClassName = "UiCheckColorless", CardType = "Skill", Rarity = "Uncommon", Cost = 0, InCardPool = true, IsColorless = true };
			clCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			clProbe.Cards.Add(clCard);
			string clPool = CSharpCodeGen.CardPoolSource(clProbe);
			Check("无色卡**不进**本角色卡池的成员表（一张卡只能属于一个池，否则 CardModel.Pool 反查结果不确定）",
				!clPool.Contains("UiCheckColorless"), clPool.Contains("UiCheckColorless") ? "还在角色池里" : "已排除");
			string clEntry = PatchesGen.ModEntrySource(clProbe, null);
			Check("无色卡由 cs/ModEntry.cs 用 ModHelper.AddModelToPool(无色卡池, 卡类) 登记（本体只允许在游戏初始化之前登记）",
				clEntry.Contains("MegaCrit.Sts2.Core.Models.CardPools.ColorlessCardPool")
				&& clEntry.Contains("AddModelToPool(__colorlessPool, __tUiCheckColorless)"), "登记在");
			Check("不是无色卡时一句登记都不写（老存档生成结果不变，注解文字不算）",
				!PatchesGen.ModEntrySource(ProfileFactory.Sample(), null).Contains("AddModelToPool(__colorlessPool"), "没写");
			Check("校验器：无色卡 + 稀有度 Ancient → 报错（本体 CardFactory 对那几档有特殊处理）",
				ProfileValidator.Validate(MakeColorless("Ancient")).Any((ValidationIssue i) => i.IsError && i.Message.Contains("无色")),
				"拦住了");
			Check("校验器：无色卡会提示「不进你角色卡池 / 用本体无色卡框」",
				ProfileValidator.Validate(clProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("无色") && i.Message.Contains("卡框")),
				"提示了");
			// 生成 → 真编译 → 回读
			string clRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_colorless_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				clProbe.Paths.OutputDir = clRoot;
				clProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				clProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var clGen = ModGenerator.Generate(clProbe);
				Check("（准备）带无色卡的存档能生成工程", clGen.Success, clGen.ProjectRoot);
				Check("生成出来的 ModEntry 里有登记语句（CS 里就是那句）",
					File.Exists(Path.Combine(clGen.ProjectRoot, "cs", "ModEntry.cs"))
					&& File.ReadAllText(Path.Combine(clGen.ProjectRoot, "cs", "ModEntry.cs")).Contains("AddModelToPool(__colorlessPool, __tUiCheckColorless)"), "在");
				var clRec = ProjectRecovery.FromProject(clGen.ProjectRoot);
				Check("从工程恢复：无色卡这个标记认得回来（扫 cs/ModEntry.cs 的登记语句）",
					clRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckColorless")?.IsColorless == true, "认回来了");
				Check("从工程恢复（带无色卡）：没认出来的语句为 0", !clRec.HasUnparsed, clRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				// 用户报的坑「无色牌卡面丢失」：本体按**卡所在池**的 Title 找卡面 
				//（CardModel.PortraitPngPath / PortraitPath），而无色卡登记进的是本体的无色卡池
				//（ColorlessCardPool.Title = "colorless"）→ 卡面素材必须写到 colorless/ 目录下，
				// 以前一律写在我们自己的池目录里，游戏找不到 = 卡面丢失。"
				string clEntryLower = Naming.EntryOf("UiCheckColorless").ToLowerInvariant();
				string clPngOk = Path.Combine(clGen.ProjectRoot, "images", "packed", "card_portraits", "colorless", clEntryLower + ".png");
				string clTresOk = Path.Combine(clGen.ProjectRoot, "images", "atlases", "card_atlas.sprites", "colorless", clEntryLower + ".tres");
				string clPngWrong = Path.Combine(clGen.ProjectRoot, "images", "packed", "card_portraits", Naming.From(clProbe).PoolTitle, clEntryLower + ".png");
				Check("无色卡的卡面写在 colorless/ 目录下（本体就是这么找的：Pool.Title = \"colorless\"）",
					File.Exists(clPngOk) && File.Exists(clTresOk), $"png={File.Exists(clPngOk)} tres={File.Exists(clTresOk)}");
				Check("无色卡的卡面**不再**写进本角色池目录（以前写错地方 = 游戏里卡面丢失）",
					!File.Exists(clPngWrong), File.Exists(clPngWrong) ? "还写在错的地方" : "没写错地方");
				Check("那份 .tres 指向的也是 colorless/ 下的 png（本体按它加载卡面）",
					File.Exists(clTresOk) && File.ReadAllText(clTresOk).Contains($"res://images/packed/card_portraits/colorless/{clEntryLower}.png"),
					File.Exists(clTresOk) ? "指向对" : "(缺 ");
				// 对照：普通卡照旧写在自己的池目录里"
				Check("（对照）普通卡（诅咒 / 先古卡同理）的卡面照旧写在本角色池目录下",
					File.Exists(Path.Combine(clGen.ProjectRoot, "images", "packed", "card_portraits", Naming.From(clProbe).PoolTitle,
						Naming.EntryOf(Naming.From(clProbe).CharClass + "Slash").ToLowerInvariant() + ".png"))
					|| Directory.GetFiles(Path.Combine(clGen.ProjectRoot, "images", "packed", "card_portraits", Naming.From(clProbe).PoolTitle), "*.png").Length > 0,
					"照旧");
			}
			finally
			{
				try { Directory.Delete(clRoot, true); } catch { }
			}
			CharacterProfile MakeColorless(string rarity)
			{
				var pr = ProfileFactory.Sample();
				var c = new CardSpec { Name = "无色先古", ClassName = "UiCheckColorlessAncient", CardType = "Skill", Rarity = rarity, InCardPool = true, IsColorless = true };
				pr.Cards.Add(c);
				return pr;
			}
		}
		// 「额外资源量遗物」（那只隐藏起始遗物）的界面：列表绑到 ExtraResource.Effects。"
		// ⚠ 第 11 批 ①（用户要求「遗物页去除左上角关于额外资源量的内容」）：这一整块**搬到
		// 「额外资源量」页**了 —— 所以这里也要切到那一页去验（以前切的是遗物页）。
		// V0.2.127：那一页改成「左=额外资源量本体 + 那只载体遗物 / 右=效果栏」，效果列表搬到**右栏**
		//（用户要求「在右侧增加效果栏」），所以下面找那个「在游戏中隐藏」勾选框要从**页根**收。
		{
			bool wasEnabled = Profile.ExtraResource.Enabled;
			Profile.ExtraResource.Enabled = true;
			Raise("ExtraResourceRelicVisible");
			Check("「额外资源量遗物」块在启用时显示（选中它的效果时会把遗物列表的选择清掉）",
				ExtraResourceRelicVisible, "启用时可见");
			SelectTabRoot("额外资源量");
			UpdateLayout();
			var erList = (ExtraResourceEffectList as ListBox);
			Check("遗物页左上角不再有「额外资源量」的内容（那块搬到额外资源量页了）",
				!TextsIn(SelectTabRoot("遗物")).Any(t => t.Contains("额外资源量遗物")), "遗物页已经没有它");
			Check("「额外资源量遗物」的效果列表在额外资源量页里、绑到 Profile.ExtraResource.Effects（生成端就在那只遗物上跑）",
				erList?.ItemsSource == Profile.ExtraResource.Effects, erList is null ? "(没找到列表 " : "绑定对");
			Profile.ExtraResource.Enabled = false;
			Raise("ExtraResourceRelicVisible");
			Check("资源量没启用时那块隐藏（那只遗物根本不会生成）", !ExtraResourceRelicVisible, "隐藏");
			// 资源量没启用却留着效果 → 校验器要提醒（不静默）"
			Profile.ExtraResource.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
			Check("校验器：没启用额外资源量但遗物上有效果 → 警告说清这些效果不会生效",
				ProfileValidator.Validate(Profile).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("额外资源量遗物")),
				ProfileValidator.Validate(Profile).FirstOrDefault((ValidationIssue i) => i.Message.Contains("额外资源量遗物"))?.Message ?? "(没报)");
			Profile.ExtraResource.Effects.Clear();
			Profile.ExtraResource.Enabled = wasEnabled;
			Raise("ExtraResourceRelicVisible");
		}
		// 多人联机宝箱房：四个本体手势 + 我们自己的「拿取」，一个都不能少 
		Check("美术页有宝箱房四个本体手势槽位",
			ArtSlots.Count((ArtSlot s) => s.Name.StartsWith("多人联机宝箱房手势（", StringComparison.Ordinal)) == 5,
			string.Join("。", ArtSlots.Where(s => s.Name.Contains("宝箱房手动")).Select(s => s.Name)));
		Check("宝箱房四个手势槽位都对到 ArtSpec 的四个字段",
			ArtSlots.First(s => s.Name.EndsWith("（选择）", StringComparison.Ordinal)).FrameWidth == 422
			&& ArtSlots.First(s => s.Name.EndsWith("（拿取）", StringComparison.Ordinal)).EmptyLabel == "未上会",
			"422×1200 / 拿取=未上传");
		// 催促文本那个输入框（在槽位列表下面）：XAML 里确实摆出来了，而且绑的是 Art.TreasureFightText
		//（值的字 / 读由下面「存档往返」那条管）。"
		// 注意：这里必须走**逻辑标** —— 美术页不是当前选中的标签页时，它的可视树还没建出来
		//（WPF 只给选中的 TabItem 建 ContentPresenter），`CollectTextBoxes`（可视树）在自检里找不到它。"
		{
			var artNodes = new List<object>();
			void WalkArt(DependencyObject node)
			{
				artNodes.Add(node);
				try
				{
					foreach (object child in LogicalTreeHelper.GetChildren(node))
						if (child is DependencyObject d) WalkArt(d);
				}
				catch { }
			}
			if (ArtTab?.Content is DependencyObject artContent) WalkArt(artContent);
			Check("美术页有「宝箱房那句催促文本」输入框（绑 Profile.Art.TreasureFightText）",
				artNodes.OfType<TextBox>().Any((TextBox tb) =>
					(BindingOperations.GetBinding(tb, TextBox.TextProperty)?.Path?.Path ?? "").Contains("TreasureFightText"))
				&& artNodes.OfType<TextBlock>().Any((TextBlock t) => (t.Text ?? "").Contains("宝箱房那句催促文本")),
				ArtTab is null ? "(没找到美术页 ArtTab)" : $"{artNodes.Count} 个节点");
		}
		// ===== V0.2.172（用户要求）：①角色页底部也能填「多人催促文本」（和美术页同一份数据）
		// ②新增「角色最大能量」（本体 CharacterModel.MaxEnergy 默认 3；一个 override 就够）=====
		{
			var roleNodes = new List<object>();
			void WalkRole(DependencyObject node)
			{
				roleNodes.Add(node);
				try
				{
					foreach (object child in LogicalTreeHelper.GetChildren(node))
						if (child is DependencyObject d) WalkRole(d);
				}
				catch { }
			}
			if (RoleTab?.Content is DependencyObject roleContent) WalkRole(roleContent);
			string PathOf(TextBox tb) => BindingOperations.GetBinding(tb, TextBox.TextProperty)?.Path?.Path ?? "";
			// V0.2.173（用户澄清）：这一栏**不是**宝箱房那句「开抢！！！」——
			// 「多人催促文本」指的是联机时**右下角那个 Ping 按钮**按下去冒出的对话气泡
			//（本体键 characters.<角色>.banter.alive.endTurnPing），绑的是 Profile.EndTurnPingText。
			Check("角色页底部有「多人催促文本」输入框（绑 Profile.EndTurnPingText = 联机 Ping 那句）",
				roleNodes.OfType<TextBox>().Any((TextBox tb) => PathOf(tb) == "Profile.EndTurnPingText")
				&& roleNodes.OfType<TextBlock>().Any((TextBlock t) => (t.Text ?? "").Contains("多人催促文本")),
				RoleTab is null ? "(没找到角色页 RoleTab)" : $"{roleNodes.Count} 个节点");
			Check("（V0.2.173 改正）角色页那一栏**不再**绑宝箱房那句（Profile.Art.TreasureFightText 只留在美术页）",
				!roleNodes.OfType<TextBox>().Any((TextBox tb) => PathOf(tb).Contains("TreasureFightText")),
				"解开了");
			// 生成端：留空 → 仍然是那句老默认「……继续。」（老存档 / --samplegen 逐字不变）；
			// 填了 → 进 characters.json 的 <角色>.banter.alive.endTurnPing（不需要任何补丁）。
			{
				string pingDefault = LocalizationGen.CharactersJson(ProfileFactory.Sample());
				Check("（红线）多人催促文本留空 → characters.json 里仍是老默认那句「……继续。」",
					pingDefault.Contains("\"SEVEN.banter.alive.endTurnPing\": \"……继续。\""), "逐字不变");
				var pingProf = ProfileFactory.Sample();
				pingProf.EndTurnPingText = "快点啊，我的回合呢？";
				Check("多人催促文本填了 → 写进 characters.json 的 banter.alive.endTurnPing（Ping 那句）",
					LocalizationGen.CharactersJson(pingProf)
						.Contains("\"SEVEN.banter.alive.endTurnPing\": \"快点啊，我的回合呢？\""), "写进去了");
				// 回读：生成端那句默认值要当作「没填」认回来（不然恢复出来的存档会无中生有一句，
				// 再生成一次 characters.json 就跟第一次不一样 —— 和「角色说明」那个坑同一个道理）。
				// 这里直接钉住那条判据用的常量（真工程回读由下面「从工程恢复」那一大块管）。
				Check("（回读）生成端默认那句「……继续。」不在存档里落地（恢复时当作没填）",
					LocalizationGen.DefaultEndTurnPingText == "……继续。"
					&& ProfileFactory.Sample().EndTurnPingText.Length == 0, "默认值只有一处定义");
			}
			// （美术页那个宝箱房框「还在」由上面那条自检管着；V0.2.173 起角色页这一栏改绑 ping 那句，
			//   两边不再是同一份数据 —— 宝箱房那句只留在美术页）
			Check("角色页有「角色最大能量」输入框（绑 Profile.MaxEnergy）",
				roleNodes.OfType<TextBox>().Any((TextBox tb) => PathOf(tb) == "Profile.MaxEnergy")
				&& roleNodes.OfType<TextBlock>().Any((TextBlock t) => (t.Text ?? "").Contains("角色最大能量")), "框在");
			// 生成端：默认 3 一个字都不写（老存档 / --samplegen 基线红线）；不是 3 才写 override
			string energy3 = CSharpCodeGen.CharacterSource(ProfileFactory.Sample());
			Check("（红线）角色最大能量 = 3（本体默认）→ 生成的角色类里**没有** MaxEnergy override",
				!energy3.Contains("MaxEnergy"), "一个字都没写");
			var p5 = ProfileFactory.Sample();
			p5.MaxEnergy = 5;
			Check("角色最大能量 = 5 → 写 public override int MaxEnergy => 5;",
				CSharpCodeGen.CharacterSource(p5).Contains("public override int MaxEnergy => 5;"), "写了");
			static CharacterProfile WithMaxEnergy(int v) { var q = ProfileFactory.Sample(); q.MaxEnergy = v; return q; }
			Check("校验器：角色最大能量 0 / 200 报**错误**；5 只给**提示**；3 一条都不出",
				ProfileValidator.Validate(WithMaxEnergy(0)).Any((ValidationIssue i) => i.IsError && i.Message.Contains("最大能量"))
				&& ProfileValidator.Validate(WithMaxEnergy(200)).Any((ValidationIssue i) => i.IsError && i.Message.Contains("最大能量"))
				&& ProfileValidator.Validate(WithMaxEnergy(5)).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("最大能量"))
				&& !ProfileValidator.Validate(WithMaxEnergy(3)).Any((ValidationIssue i) => i.Message.Contains("最大能量")), "1~99 之外报错");
			// ===== V0.2.230：地图上画线的「蜡笔」颜色（用户要求「能不能自定义在地图上的蜡笔的颜色」）=====
			// 引擎依据：NMapDrawings.CreateLine 里 `line2D.DefaultColor = player.Character.MapDrawingColor;`，
			// CharacterModel.MapDrawingColor 默认 Colors.Black（本体每个角色各自覆盖成专属色）。
			// 所以角色类里写一个 override 就够，不需要补丁；留空 = 一个字不写（老存档逐字不变）。
			Check("角色页有「地图画线颜色（蜡笔）」输入框（绑 Profile.MapDrawingColor）",
				roleNodes.OfType<TextBox>().Any((TextBox tb) => PathOf(tb) == "Profile.MapDrawingColor")
				&& roleNodes.OfType<TextBlock>().Any((TextBlock t) => (t.Text ?? "").Contains("地图画线颜色")), "框在");
			string mapDrawBlank = CSharpCodeGen.CharacterSource(ProfileFactory.Sample());
			Check("V0.2.230：（红线）地图画线颜色留空 → 生成的角色类里**没有** MapDrawingColor override（沿用本体默认黑色）",
				!mapDrawBlank.Contains("MapDrawingColor"), "一个字都没写");
			var mapDraw6 = ProfileFactory.Sample();
			mapDraw6.MapDrawingColor = "#3fa9f5";
			Check("V0.2.230：填 #3fa9f5 → 写 public override Color MapDrawingColor => new Color(\"3FA9F5\");（去掉 #、转大写）",
				CSharpCodeGen.CharacterSource(mapDraw6).Contains("public override Color MapDrawingColor => new Color(\"3FA9F5\");"),
				"写了");
			var mapDraw8 = ProfileFactory.Sample();
			mapDraw8.MapDrawingColor = "3FA9F580";
