		// ===== 概率公式（用户要求⑦ 批次 3） ====
		{
			var chEff = new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", ChanceEnabled = true, ChancePercent = 50m };
			chEff.ChanceFormula = "Turn * 10";
			Check("概率也能写公式（勾了「概率生效」才出现那一格）",
