			Check("概率写了公式时，列表 / 卡面文案印公式本身",
				chEff.ChanceText.Contains("Turn * 10"), chEff.ChanceText);
			// 生成：写了公式的那条**自己独立判一次**（不再参与「同组共用一次掷骰、各占一段区间」）
			CharacterProfile chProfile = ProfileFactory.Sample();
			var chCard = new CardSpec { Name = "概率公式卡", ClassName = "UiCheckChanceFormula", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
			var chA = new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", ChanceEnabled = true, ChancePercent = 50m };
			chA.ChanceFormula = "Turn * 10";
			var chB = new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Enemy", ChanceEnabled = true, ChancePercent = 30m };
			chCard.Effects.Add(chA);
			chCard.Effects.Add(chB);
			chProfile.Cards.Add(chCard);
			string chSrc = CSharpCodeGen.CardSource(chProfile, chCard, 0);
			Check("写了公式的那条：`__chanceRoll < (double)(现算的百分比)`（自己独立判一次）",
				chSrc.Contains("if (__chanceRoll < (double)(((__fgPlayer?.PlayerCombatState?.TurnNumber ?? 0) * (10m))))"), "对");
			Check("同一张牌里**没写公式**的那条照旧走「区间划分」（两条加起来仍是一段一段）",
				chSrc.Contains("__chanceRoll >= 0 && __chanceRoll < 30"), "对");
			Check("概率公式也写进 CET:CountFormulas 标记（回读用）",
				chSrc.Contains("// CET:CountFormulas=Chance=Turn * 10"), "有标记");
			Check("（红线）没勾概率效果的卡：不写掷骰那一行、也不写标记",
				!CSharpCodeGen.CardSource(ProfileFactory.Sample(), new CardSpec
				{
					Name = "无概率卡", ClassName = "UiCheckNoChance", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true,
					Effects = { new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Enemy" } },
				}, 0).Contains("__chanceRoll"), "老样子");
			Check("校验器：概率公式和同组固定概率混用时 → 提示「不再共用一次掷骰」",
				ProfileValidator.Validate(chProfile).Any(i => i.Level == "提示" && i.Message.Contains("独立判一次")), "提示了");
			Check("不能写公式的地方在界面说明里写明了（费用 / 升级增量 / 页面常量）",
				chEff.CountFormulaHint.Contains("费用") && chEff.CountFormulaHint.Contains("页面常量"), "写明了");
			// 生成 → 真编译 → 回读
			string chRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_chancef_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				chProfile.Paths.OutputDir = chRoot;
				chProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				chProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var chGen = ModGenerator.Generate(chProfile);
				Check("（准备）带概率公式的存档能生成工程", chGen.Success,
					chGen.Success ? chGen.ProjectRoot : string.Join(" ｜ ", chGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
				if (chGen.Success)
				{
					var chRec = ProjectRecovery.FromProject(chGen.ProjectRoot);
					CardSpec? chBack = chRec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckChanceFormula");
					Check("从工程恢复：概率公式认得回来（同一张牌里两条效果的公式不会串）",
						chBack is not null && chBack.Effects.Count == 2
						&& chBack.Effects[0].ChanceFormula == "Turn * 10" && chBack.Effects[1].ChanceFormula == "",
						chBack is null ? "(缺 " : string.Join(" / ", chBack.Effects.Select(x => x.ChanceFormula.Length == 0 ? "(时 " : x.ChanceFormula)));
					Check("从工程恢复（概率公式）：没认出来的语句为 0", !chRec.HasUnparsed, chRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
			}
			finally
			{
				try { Directory.Delete(chRoot, true); } catch { }
			}
		}
		// 用户实测报的：「设 A 为敌人的虚弱、伤害写 A+3，却没效果」—— 
		// 根因是那张牌是「对所有敌人」→ 打出时不选目标"→ cardPlay.Target 是 null → A 恒为 0。"
		CharacterProfile aoeFormulaProfile = ProfileFactory.Sample();
		aoeFormulaProfile.CustomParams.Clear();
		aoeFormulaProfile.CustomParams.Add(new ParamSpec { Name = "A", Source = ParamSources.Power, Target = ParamTargets.ChosenEnemy, PowerId = "WeakPower" });
		CardSpec aoeFormulaCard = new CardSpec { Name = "自检全敌公式", ClassName = "UiCheckAoeFormula", Cost = 1, CardType = "Attack" };
		aoeFormulaCard.Effects.Clear();
		aoeFormulaCard.Effects.Add(new EffectSpec { Kind = "Damage", TargetSide = "AllEnemies", Amount = 0m, AmountFormula = "A+3", RepeatCount = 4 });
		aoeFormulaProfile.Cards.Add(aoeFormulaCard);
		Check("「数值公式」用了「指定敌人」的参数、牌却是全敌人 → 报错拦住（那个参数永远是 0）",
			ProfileValidator.Validate(aoeFormulaProfile).Any((ValidationIssue i) => i.IsError && i.Message.Contains("永远是 0")), "拦住了");
		aoeFormulaCard.Effects[0].TargetSide = "Enemy";
		Check("（对照）把作用对象改成「指定敌人」就不报了",
			!ProfileValidator.Validate(aoeFormulaProfile).Any((ValidationIssue i) => i.IsError && i.Message.Contains("永远是 0")), "不报了");
		aoeFormulaCard.Effects[0].TargetSide = "AllEnemies";
		aoeFormulaCard.Effects[0].AmountFormula = "";
		aoeFormulaCard.Effects[0].Amount = 6m;
		string aoeSrcText = CSharpCodeGen.CardSource(aoeFormulaProfile, aoeFormulaCard, 0);
		Check("「全体敌人 + 命中次数 4」生成 .WithHitCount(4)（以前这个数字被整个忽略，只打 1 下）",
			aoeSrcText.Contains(".TargetingAllOpponents(base.CombatState)") && aoeSrcText.Contains(".WithHitCount(4)"), "打 4 下");
		aoeFormulaCard.Effects[0].RepeatCount = 1;
		Check("（对照）命中 1 次时不写 WithHitCount（老存档生成的代码逐字不变）",
			!CSharpCodeGen.CardSource(aoeFormulaProfile, aoeFormulaCard, 0).Contains("WithHitCount"), "没多写");
		DependencyObject root10 = SelectTabRoot("遗物");
		if (Profile.Relics.Count > 0)
		{
			RelicList.SelectedIndex = 0;
			if (((RelicSpec)RelicList.SelectedItem).Effects.Count > 0)
			{
				RelicEffectList.SelectedIndex = 0;
			}
			UpdateLayout();
		}
		List<TextBox> list16 = new List<TextBox>();
		CollectTextBoxes(root10, list16);
		Check("遗物的效果编辑器里没有「升级增量」（遗物不能升级）", !list16.Any((TextBox b) => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path == "UpgradeAmount"), string.Join(" / ", list16.Select((TextBox b) => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path)));
		DependencyObject root11 = SelectTabRoot("药水");
		if (Profile.Potions.Count > 0)
		{
			PotionList.SelectedIndex = 0;
			if (((PotionSpec)PotionList.SelectedItem).Effects.Count > 0)
			{
				PotionEffectList.SelectedIndex = 0;
			}
			UpdateLayout();
		}
		List<TextBox> list17 = new List<TextBox>();
		CollectTextBoxes(root11, list17);
		Check("药水的效果编辑器里也没有「升级增量」", !list17.Any((TextBox b) => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path == "UpgradeAmount"), "药水没有");
		Check("遗物/药水页也不再用文字提「升级增量」", !TextsIn(root10).Any((string x) => x.Contains("升级增量")) && !TextsIn(root11).Any((string x) => x.Contains("升级增量")), "文字里没有");
		// ===== V0.2.126（用户要求）：遗物 = 一份效果 + 一组触发时机 =====
		// 原话：「中间的触发时机并不是每条各配效果，而是决定整只遗物的触发时机，只有同时满足或者
		// 满足其中一个才能触发遗物的效果，另外效果右侧应能添加多个效果种类」。
		// 这一块验：老存档迁移（合并 / 去重 / 幂等 / 同时成立→全部满足）、生成（单条逐字不变 / Any / All）、
		// 回读（时机条数 + 字段 + 关系 + 共享效果，0 条「没认出来」）。
		{
			// ① 迁移：2 条时机各带 1 条效果（其中第 2 条与第 1 条**完全重复**）+ 都勾过「同时成立」
			var migRelic = new RelicSpec { Name = "迁移试验", ClassName = "UiCheckMigrateRelic", Rarity = "Common", AndScope = "Combat" };
			migRelic.Triggers.Clear();
			var migT1 = new RelicTriggerSpec { Kind = "PlayerTurnStart", RequireAllTriggers = true };
			migT1.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			var migT2 = new RelicTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack", RequireAllTriggers = true };
			migT2.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });   // 与上面完全重复
			migT2.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
			migRelic.Triggers.Add(migT1);
			migRelic.Triggers.Add(migT2);
			var migProfile = ProfileFactory.Sample();
			migProfile.Relics.Clear();
			migProfile.Relics.Add(migRelic);
			ProfileFactory.NormalizeRelicEffects(migProfile);
			Check("迁移：2 条时机各带效果 → 合并进遗物（完全重复的只留 1 份：格挡/伤害 = 2 条）",
				migRelic.Effects.Count == 2
				&& migRelic.Effects[0].Kind == "Block" && migRelic.Effects[0].Amount == 3m
				&& migRelic.Effects[1].Kind == "Damage" && migRelic.Effects[1].Amount == 5m,
				string.Join("+", migRelic.Effects.Select(e => e.Kind + ":" + e.Amount)));
			Check("迁移：时机上的效果被清空（新存档不再写老字段）",
				migRelic.Triggers.All(t => t.Effects.Count == 0) && migRelic.Triggers.All(t => !t.RequireAllTriggers),
				"清空 + 置 false");
			Check("迁移：勾过「同时成立」→ 关系切成「全部满足才触发」，重置范围沿用原值（Combat）",
				migRelic.TriggerMode == "All" && migRelic.IsAllTriggers && migRelic.AndScope == "Combat",
				migRelic.TriggerMode + "/" + migRelic.AndScope);
			// 幂等：再跑一遍，一个字节都不动
			int migEffectCount = migRelic.Effects.Count;
			string migSignature = string.Join("|", migRelic.Effects.Select(e => e.Kind + ":" + e.Amount));
			ProfileFactory.NormalizeRelicEffects(migProfile);
			ProfileFactory.NormalizeRelicEffects(migProfile);
			Check("迁移是幂等的（再跑两遍：效果条数 / 内容 / 关系 / 范围全都不变）",
				migRelic.Effects.Count == migEffectCount
				&& string.Join("|", migRelic.Effects.Select(e => e.Kind + ":" + e.Amount)) == migSignature
				&& migRelic.TriggerMode == "All" && migRelic.AndScope == "Combat",
				migRelic.Effects.Count + " 条 / " + migRelic.TriggerMode);
			// 老存档（V0.2.121 及更早：只有一个时机、效果直接挂在遗物上）迁移后一个字符都不变
			var oldStyle = new RelicSpec { Name = "极老遗物", ClassName = "UiCheckOldStyleRelic", Trigger = "PlayerTurnStart" };
			oldStyle.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" });
			var oldProfile = ProfileFactory.Sample();
			oldProfile.Relics.Clear();
			oldProfile.Relics.Add(oldStyle);
			ProfileFactory.NormalizeRelicEffects(oldProfile);
			Check("迁移：极老存档（效果本来就挂在遗物上）→ 内容 / 条数 / 关系一个都不变",
				oldStyle.Effects.Count == 1 && oldStyle.Effects[0].Amount == 4m
				&& oldStyle.TriggerMode == "Any" && oldStyle.Triggers.Count == 1
				&& oldStyle.Triggers[0].Effects.Count == 0,
				oldStyle.Effects.Count + " 条 / " + oldStyle.TriggerMode);

			// ② 生成：单条时机 + Any（= 老存档形状）逐字一致
			var genProfile = ProfileFactory.Sample();
			genProfile.Relics.Clear();
			var oneRelic = new RelicSpec { Name = "单条", ClassName = "UiCheckOneTriggerRelic", Rarity = "Common", Trigger = "PlayerTurnStart" };
			oneRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			genProfile.Relics.Add(oneRelic);
			string oneSrc = CSharpCodeGen.RelicSource(genProfile, oneRelic, 0);
			Check("生成：单条时机 + Any **不写** CET:TriggerMode 标记（老存档生成文本逐字不变）",
				!oneSrc.Contains("CET:TriggerMode") && !oneSrc.Contains("CET:RequireAll"), "没写标记");
			Check("生成：单条时机 + Any 里跑的就是遗物那份效果（获得格挡）", oneSrc.Contains("CreatureCmd.GainBlock"), "有格挡");

			// 三条生成形状做「逐字对照」：同一个效果、不同关系/时机数
			var twoAny = new RelicSpec { Name = "两条任意", ClassName = "UiCheckTwoAnyRelic", Rarity = "Common" };
			twoAny.Triggers.Clear();
			twoAny.Triggers.Add(new RelicTriggerSpec { Kind = "PlayerTurnStart" });
			twoAny.Triggers.Add(new RelicTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack" });
			twoAny.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			string twoAnySrc = CSharpCodeGen.RelicSource(genProfile, twoAny, 0);
			Check("生成：2 条时机 + Any → 两个钩子各自跑**同一份**共享效果（格挡出现 2 次）",
				twoAnySrc.Contains("AfterPlayerTurnStart") && twoAnySrc.Contains("BeforeCardPlayed")
				&& System.Text.RegularExpressions.Regex.Matches(twoAnySrc, "CreatureCmd\\.GainBlock").Count == 2,
				"格挡 ×" + System.Text.RegularExpressions.Regex.Matches(twoAnySrc, "CreatureCmd\\.GainBlock").Count);
			Check("生成：2 条时机 + Any 不生成 __andHit 标记位（复用老字段的写法都没出现）",
				!twoAnySrc.Contains("private bool __andHit") && !twoAnySrc.Contains("__andHit0 = "),
				"没有标记位");

			var twoAll = new RelicSpec { Name = "两条全部", ClassName = "UiCheckTwoAllRelic", Rarity = "Common", TriggerMode = "All", AndScope = "Turn" };
			twoAll.Triggers.Clear();
			twoAll.Triggers.Add(new RelicTriggerSpec { Kind = "PlayerTurnStart" });
			twoAll.Triggers.Add(new RelicTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack" });
			twoAll.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			string twoAllSrc = CSharpCodeGen.RelicSource(genProfile, twoAll, 0);
			Check("生成：2 条时机 + All → 两条各打标记（__andHit0 / __andHit1）",
				twoAllSrc.Contains("private bool __andHit0, __andHit1;") && twoAllSrc.Contains("__andHit0 = true;") && twoAllSrc.Contains("__andHit1 = true;"), "有标记");
			Check("生成：2 条时机 + All → 「凑齐跑一次 + 跑完清标记」（if (__andHit0 && __andHit1) + 两个置 false）",
				twoAllSrc.Contains("if (__andHit0 && __andHit1)")
				&& twoAllSrc.Contains("__andHit0 = false; __andHit1 = false;"), "凑齐才跑");
			// V0.2.168（别人实测报的「遗物的两个触发时机同时满足需要两次触发」）：
			// 以前 All 模式只让**最后那条**时机检查标记，于是「最后那条先触发、别的时机后触发」时，
			// 凑齐的那一刻没人检查 → 必须等最后那条**再触发一次**才跑（表现就是「要触发两次」）。
			// 现在**每段都带效果体 + 都检查标记**：谁凑齐谁跑，跑完清标记（一个窗口仍然只跑一次）。
			Check("V0.2.168：2 条时机 + All → **每一段都**检查标记并带效果体（谁凑齐谁跑，不再要「最后那条再触发一次」）",
				System.Text.RegularExpressions.Regex.Matches(twoAllSrc, "if \\(__andHit0 && __andHit1\\)").Count == 2
				&& System.Text.RegularExpressions.Regex.Matches(twoAllSrc, "CreatureCmd\\.GainBlock").Count == 2,
				$"检查点 ×{System.Text.RegularExpressions.Regex.Matches(twoAllSrc, "if \\(__andHit0 && __andHit1\\)").Count} / 格挡 ×{System.Text.RegularExpressions.Regex.Matches(twoAllSrc, "CreatureCmd\\.GainBlock").Count}");
			Check("V0.2.168：每段跑完都清标记（一个窗口仍然只跑一次）",
				System.Text.RegularExpressions.Regex.Matches(twoAllSrc, "__andHit0 = false; __andHit1 = false;").Count >= 2, "清标记 ×2");
			Check("生成：All 写回读标记 CET:TriggerMode=All CET:AndScope=Turn",
				twoAllSrc.Contains("CET:TriggerMode=All CET:AndScope=Turn"), "有标记");
			Check("生成：Turn 档有「换回合清标记」（__andTurn + 回合号比较）",
				twoAllSrc.Contains("__andTurn = __andPcs.TurnNumber;"), "Turn 档清零");
			var twoAllCombat = new RelicSpec { Name = "两条全部战斗", ClassName = "UiCheckTwoAllCombatRelic", Rarity = "Common", TriggerMode = "All", AndScope = "Combat" };
			twoAllCombat.Triggers.Clear();
			twoAllCombat.Triggers.Add(new RelicTriggerSpec { Kind = "PlayerTurnStart" });
			twoAllCombat.Triggers.Add(new RelicTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack" });
			twoAllCombat.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			string twoAllCombatSrc = CSharpCodeGen.RelicSource(genProfile, twoAllCombat, 0);
			Check("生成：Combat 档**不写** __andTurn（整场凑齐一次，不需要按回合清零）",
				!twoAllCombatSrc.Contains("__andTurn") && twoAllCombatSrc.Contains("CET:AndScope=Combat"), "Combat 档不重置");

			// ③ 校验器：遗物那份效果只校验一次；All 但只有 1 条时机 → 提示「不生效」
			var vOne = ProfileFactory.Sample();
			vOne.Relics.Clear();
			var vAllOne = new RelicSpec { Name = "全部只有一条", ClassName = "UiCheckValidateAllOne", Rarity = "Common", TriggerMode = "All" };
			vAllOne.Triggers.Clear();
			vAllOne.Triggers.Add(new RelicTriggerSpec { Kind = "CardPlayed", CardFilter = "Group:没有这个组" });
			vAllOne.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			vOne.Relics.Add(vAllOne);
			var vAllOneIssues = ProfileValidator.Validate(vOne);
			Check("校验器：All 但只有 1 条时机 → 提示「不生效」",
				vAllOneIssues.Any(i => !i.IsError && i.Message.Contains("不生效") && i.Message.Contains("全部满足才触发")),
				"提示了");
			// 「只对哪类牌生效」选了个空组是**错误**级 —— 遗物那份共享效果只该被校验一次，
			// 所以这条错误在整份校验结果里只出现 1 次（老写法按每条时机各校验一遍会重复）。
			int filterErrors = vAllOneIssues.Count(i => i.IsError && i.Message.Contains("只对哪类牌生效"));
			Check("校验器：遗物那份效果只校验**一次**（空组错误只报 1 条，不按时机数重复）",
				filterErrors == 1, filterErrors + " 条");

			// ④ 生成 → 回读（Any / All 各一只，字段逐项还原、0 条「没认出来」）
			var recProfile2 = ProfileFactory.Sample();
			recProfile2.Paths.VanillaProject = Profile.Paths.VanillaProject;
			recProfile2.Paths.GameDataDir = Profile.Paths.GameDataDir;
			recProfile2.Relics.Clear();
			var recAny = new RelicSpec { Name = "回读任意", ClassName = "UiCheckRecAnyRelic", Rarity = "Common", TriggerMode = "Any" };
			recAny.Triggers.Clear();
			recAny.Triggers.Add(new RelicTriggerSpec { Kind = "PlayerTurnStart" });
			recAny.Triggers.Add(new RelicTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack", Amount = 2m, Scope = "Combat" });
			recAny.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
			recAny.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 7m, TargetSide = "Enemy" });
			recProfile2.Relics.Add(recAny);
			var recAll = new RelicSpec { Name = "回读全部", ClassName = "UiCheckRecAllRelic", Rarity = "Rare", TriggerMode = "All", AndScope = "Combat" };
			recAll.Triggers.Clear();
			recAll.Triggers.Add(new RelicTriggerSpec { Kind = "PlayerTurnStart" });
			recAll.Triggers.Add(new RelicTriggerSpec { Kind = "PowerReached", PowerId = "VulnerablePower", Amount = 3m });
			recAll.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" });
			recProfile2.Relics.Add(recAll);
			string recRoot2 = Path.Combine(Path.GetTempPath(), "forge_uicheck_relicshared_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				recProfile2.Paths.OutputDir = recRoot2;
				var recGen2 = ModGenerator.Generate(recProfile2, delegate { });
				Check("（准备）V0.2.126 探针存档能生成", recGen2.Success, recGen2.Success ? recGen2.ProjectRoot
					: string.Join(" | ", recGen2.Issues.Where(i => i.IsError).Select(i => i.Message).Take(2)));
				if (recGen2.Success)
				{
					var recRes2 = ProjectRecovery.FromProject(recGen2.ProjectRoot);
					var backAny = recRes2.Profile.Relics.FirstOrDefault(delegate (RelicSpec x) { return x.ClassName == "UiCheckRecAnyRelic"; });
					var backAll = recRes2.Profile.Relics.FirstOrDefault(delegate (RelicSpec x) { return x.ClassName == "UiCheckRecAllRelic"; });
					Check("回读：Any 那只回来了 2 条时机 + 字段对（第 2 条 筛选=攻击 / 数值=2 / 范围=本场战斗）",
						backAny is not null && backAny.Triggers.Count == 2
						&& backAny.Triggers[0].Kind == "PlayerTurnStart"
						&& backAny.Triggers[1].Kind == "CardPlayed"
						&& backAny.Triggers[1].CardFilter == "Attack"
						&& backAny.Triggers[1].Amount == 2m && backAny.Triggers[1].Scope == "Combat",
						backAny is null ? "(缺" : string.Join("/", backAny.Triggers.Select(delegate (RelicTriggerSpec t) { return t.Kind + ":" + t.CardFilter; })));
					Check("回读：Any 那只的**共享效果**原样回来（格挡 3 + 伤害 7，共 2 条）",
						backAny is not null && backAny.Effects.Count == 2
						&& backAny.Effects[0].Kind == "Block" && backAny.Effects[0].Amount == 3m
						&& backAny.Effects[1].Kind == "Damage" && backAny.Effects[1].Amount == 7m,
						backAny is null ? "(缺" : string.Join("+", backAny.Effects.Select(delegate (EffectSpec e) { return e.Kind + ":" + e.Amount; })));
					Check("回读：Any 那只的关系是 TriggerMode=Any",
						backAny is not null && backAny.TriggerMode == "Any", backAny?.TriggerMode ?? "(缺");
					Check("回读：All 那只回来了 2 条时机 + 关系=全部满足 + 重置范围=本场战斗",
						backAll is not null && backAll.Triggers.Count == 2 && backAll.TriggerMode == "All" && backAll.AndScope == "Combat",
						backAll is null ? "(缺" : backAll.Triggers.Count + " 条 / " + backAll.TriggerMode + "/" + backAll.AndScope);
					Check("回读：All 那只是「某个状态层数到达 N 层」的盯状态 / 到达层数也回来了",
						backAll is not null && backAll.Triggers[1].Kind == "PowerReached"
						&& backAll.Triggers[1].PowerId == "VulnerablePower" && backAll.Triggers[1].Amount == 3m,
						backAll?.Triggers.ElementAtOrDefault(1) is { } t2 ? t2.Kind + "/" + t2.PowerId + "/" + t2.Amount : "(缺");
					Check("回读：All 那只的共享效果原样回来（格挡 4）",
						backAll is not null && backAll.Effects.Count == 1 && backAll.Effects[0].Kind == "Block" && backAll.Effects[0].Amount == 4m,
						backAll is null ? "(缺" : string.Join("+", backAll.Effects.Select(delegate (EffectSpec e) { return e.Kind + ":" + e.Amount; })));
					Check("回读：这两只遗物 0 条「没认出来」",
						!recRes2.Unparsed.Any(delegate (string u) { return u.Contains("UiCheckRecAnyRelic") || u.Contains("UiCheckRecAllRelic"); }),
						string.Join(" | ", recRes2.Unparsed.Take(2)));
					Check("回读：回读结果**再生成一次**是同构的（时机条数 / 共享效果条数 / 关系都不变）",
						backAll is not null && CSharpCodeGen.RelicSource(recRes2.Profile, backAll, 0) == CSharpCodeGen.RelicSource(recProfile2, recAll, 1),
						"逐字相同");
				}
			}
			finally
			{
				try { if (Directory.Exists(recRoot2)) Directory.Delete(recRoot2, true); } catch { }
			}
		}
		// ===== 第 10 批①（用户要求）：遗物页那条「触发时机列表」（V0.2.126 起时机只管「什么时候触发」）=====
		{
			SelectTabRoot("遗物");
			if (RelicList.Items.Count > 0 && RelicList.SelectedItem == null) RelicList.SelectedIndex = 0;
			UpdateLayout();
			var relicUi = RelicUiSelection;
			Check("遗物页有「触发时机列表」（绑在选中遗物的 Triggers 上）",
				relicUi != null && RelicTriggerList.ItemsSource == relicUi.Triggers, RelicTriggerList.Items.Count + " 条");
			Check("遗物页「触发时机列表」的每一行显示的是时机摘要（Summary）",
				RelicTriggerList.DisplayMemberPath == "Summary", RelicTriggerList.DisplayMemberPath ?? "(空)");
			Check("遗物页有「添加触发时机」按钮", TextsIn(RelicDetail).Contains("添加触发时机"), "按钮在");
			int relicsBefore = Profile.Relics.Count;
			OnAddRelicTrigger(this, new RoutedEventArgs());
			var lastRelic = RelicList.SelectedItem as RelicSpec;
			Check("「添加触发时机」给这只遗物加了第二条",
				lastRelic != null && lastRelic.Triggers.Count == 2 && ReferenceEquals(lastRelic, relicUi),
				lastRelic is null ? "(没选中)" : lastRelic.Triggers.Count + " 条");
			Check("加完自动选中新加的那条（编辑的是第二条）",
				lastRelic != null && lastRelic.Triggers.Count >= 2 && ReferenceEquals(RelicTriggerList.SelectedItem, lastRelic.Triggers[1]),
				(lastRelic?.Triggers.Count > 1) ? lastRelic.Triggers[1].Summary : "(没加上)");
			Check("遗物数没被改动（加的是这只遗物的时机，不是新遗物）", Profile.Relics.Count == relicsBefore,
				Profile.Relics.Count + "/" + relicsBefore);
			if (lastRelic != null && lastRelic.Triggers.Count >= 2)
			{
				// V0.2.126：效果是**整只遗物那一份** → 换选中哪条时机，效果栏绑的都不该变
				RelicTriggerList.SelectedItem = lastRelic.Triggers[1];
				UpdateLayout();
				Check("效果栏绑的是**整只遗物**那一份效果（RelicSpec.Effects），换时机不换绑",
					ReferenceEquals(RelicEffectList.ItemsSource, lastRelic.Effects),
					RelicEffectList.ItemsSource is null ? "(null)" : "绑在遗物上");
				Check("效果栏那一份效果不是「哪条时机的 Effects」（时机的 Effects 一直是空的）",
					lastRelic.Triggers[1].Effects.Count == 0 && lastRelic.Triggers[0].Effects.Count == 0,
					$"{lastRelic.Triggers[0].Effects.Count} / {lastRelic.Triggers[1].Effects.Count}");
				// 关系开关：默认「满足其中一个就触发」→「重置范围」不显示；切到「全部满足才触发」→ 显示
				Check("关系开关默认是「满足其中一个就触发」（TriggerMode = Any）",
					lastRelic.TriggerMode == "Any" && lastRelic.TriggerModeIsAny && !lastRelic.ShowAndScope,
					lastRelic.TriggerMode);
				Check("关系开关的两个单选按钮绑的是 TriggerModeIsAny / TriggerModeIsAll，且「全部满足」那个可见可用",
					BindingOperations.GetBinding(RelicTriggerModeAny, ToggleButton.IsCheckedProperty)?.Path?.Path == "TriggerModeIsAny"
					&& BindingOperations.GetBinding(RelicTriggerModeAll, ToggleButton.IsCheckedProperty)?.Path?.Path == "TriggerModeIsAll"
					&& RelicTriggerModeAll.IsVisible && RelicTriggerModeAll.IsEnabled,
					"绑定 / 可见都对");
				Check("默认（Any）时「重置范围」下拉那一行不显示",
					!RelicAndScopeCombo.IsVisible, RelicAndScopeCombo.IsVisible.ToString());
				lastRelic.TriggerMode = "All";     // 界面上的单选按钮绑的就是它
				UpdateLayout();
				Check("切到「全部满足才触发」→ ShowAndScope 为真、「重置范围」看得见",
					lastRelic.ShowAndScope && RelicAndScopeCombo.IsVisible
					&& VisibleTextsIn(RelicDetail).Contains("重置范围"),
					"重置范围可见");
				Check("「重置范围」下拉绑的是 AndScope（落在整只遗物上）",
					BindingOperations.GetBinding(RelicAndScopeCombo, Selector.SelectedValueProperty)?.Path?.Path == "AndScope"
					&& lastRelic.AndScope == "Turn",
					lastRelic.AndScope);
				lastRelic.AndScope = "Combat";
				Check("「重置范围」能改成「本场战斗」", lastRelic.AndScope == "Combat", lastRelic.AndScope);
				lastRelic.TriggerMode = "Any";
				lastRelic.AndScope = "Turn";
				// 删除时机时如果关系是「全部满足才触发」会被拦？——不会（只是提示不生效），这里先切回 Any
				RelicTriggerList.SelectedItem = lastRelic.Triggers[1];
				OnRemoveRelicTrigger(this, new RoutedEventArgs());
				Check("「删除触发时机」删掉后只剩 1 条", lastRelic.Triggers.Count == 1, lastRelic.Triggers.Count + " 条");
			}
			// ===== 第 11 批（用户要求）：序号 / 拖动换位置 / 自动类名跟序号走 =====
			// ⚠ 做法：**往列表末尾追加** 4 只临时的，不去动原来的那些（清空再重建会把
			// RelicList / RelicTriggerList / RelicEffectList 的选中项全打断，后面一大段自检就没对象了）。
			{
				var testRelics = new List<RelicSpec>
				{
					new RelicSpec { Name = "排序甲", ClassName = "SevenRelic1", Rarity = "Common", Trigger = "CombatStart" },
					new RelicSpec { Name = "排序乙", ClassName = "MyCharm", Rarity = "Rare", Trigger = "CombatStart" },
					new RelicSpec { Name = "排序丙", ClassName = "", Rarity = "Uncommon", Trigger = "CombatStart" },
					new RelicSpec { Name = "排序丁", ClassName = "HunterCharm", Rarity = "Shop", Trigger = "CombatStart" },
				};
				foreach (RelicSpec r in testRelics) Profile.Relics.Add(r);
				try
				{
					RelicList.SelectedIndex = 0;
					UpdateLayout();
					RefreshRelicOrdinals();
					int baseCount = Profile.Relics.Count - testRelics.Count;
					int a = baseCount, b = baseCount + 1, c = baseCount + 2, d = baseCount + 3;

					Check("遗物列表每一行最左边显示序号（1..N，跟着位置算）",
						Profile.Relics.Select((r, i) => r.Ordinal == i + 1).All(x => x)
						&& Profile.Relics[a].OrdinalText == (a + 1) + "." && Profile.Relics[d].OrdinalText == (d + 1) + ".",
						Profile.Relics[a].OrdinalText + " / … / " + Profile.Relics[d].OrdinalText);
					// 列表行的模板里真的有一个绑 OrdinalText 的 TextBlock（不是只算在模型上）。
					// ⚠ V0.2.125 起列表里多了空槽行，ListBox 默认虚拟化 → 容器要**先量过布局**才有；
					// 所以这里显式 UpdateLayout + 先探一个容器的宽度（不改虚化设置，布局断言还按老口径量）。
					UpdateLayout();
					_ = (RelicList.ItemContainerGenerator.ContainerFromIndex(0) as FrameworkElement)?.ActualWidth;
					List<TextBlock> ordTexts = new List<TextBlock>();
					CollectTextBlocks(RelicList, ordTexts);
					Check("列表行的模板里真的绑了序号（OrdinalText）",
						ordTexts.Any(t => BindingOperations.GetBinding(t, TextBlock.TextProperty)?.Path?.Path == "OrdinalText"),
						ordTexts.Count + " 个 TextBlock");

					// 拖动：把「排序甲」拖到「排序丙」那一行上（= 插到第 3 位）
					bool relicMoved = MoveRelicTo(testRelics[0], testRelics[2]);
					UpdateLayout();
					Check("拖动换位置：RelicList.Items 的顺序真的变了（拖第 1 只到第 3 只那一行 = 插到第 3 位）",
						relicMoved
						&& Profile.Relics[c].Name == "排序甲" && Profile.Relics[a].Name == "排序乙" && Profile.Relics[b].Name == "排序丙",
						string.Join(" → ", Profile.Relics.Skip(baseCount).Select(r => r.Name)));
					Check("拖动之后序号仍然是从 1 开始的连续 N（序号跟着位置变，不是跟着遗物走）",
						Profile.Relics.Select((r, i) => r.Ordinal == i + 1 && r.OrdinalText == (i + 1) + ".").All(x => x),
						string.Join(" / ", Profile.Relics.Select(r => r.Name + "=" + r.OrdinalText)));
					Check("「排序甲」的序号从 1 变成了 3（跟着位置走，不是跟着物品走）",
						Profile.Relics[c].Name == "排序甲" && Profile.Relics[c].Ordinal == c + 1,
						Profile.Relics[c].Name + "=" + Profile.Relics[c].Ordinal);

					// 自动类名跟序号走 / 手填的不动（生成端那一步：Naming.RenumberRelicClassNames）
					var n2 = Naming.From(Profile);
					// ⚠ 期望值按**实际位置**算（baseCount 是这只存档里原有的遗物数，测试遗物接在它们后面）：
					// 写死「SevenRelic3」只在「列表里没有别的遗物」时才对。
					string autoA = "SevenRelic" + (c + 1);   // 排序甲被拖到第 c+1 位（旧名字 SevenRelic1 是自动名 → 跟过来）
					int renum = n2.RenumberRelicClassNames(Profile.Relics);
					Check($"重新生成时：旧自动类名「SevenRelic1」跟到新位置（第 {c + 1} 位 → {autoA}）",
						Profile.Relics[c].ClassName == autoA, Profile.Relics[c].ClassName);
					Check($"重新生成时：没填类名的**类名保持留空**、只记下「这个位置对应第 {b + 1} 号自动名」"
						+ "（留空才不会把「工具生成的」和「用户手打的」混在一起）",
						Profile.Relics[b].ClassName == "" && Profile.Relics[b].LastAutoOrdinal == b + 1
						&& n2.RelicClassName(Profile.Relics[b], b) == "SevenRelic" + (b + 1),
						$"ClassName='{Profile.Relics[b].ClassName}' 自动名={n2.RelicClassName(Profile.Relics[b], b)}");
					Check("重新生成时：**手填的**类名一个字都不动（MyCharm / HunterCharm —— 认不出是自动名的都当手填）",
						Profile.Relics[a].ClassName == "MyCharm" && Profile.Relics[d].ClassName == "HunterCharm",
						Profile.Relics[a].ClassName + " / " + Profile.Relics[d].ClassName);
					string[] afterFirstPass = Profile.Relics.Select(r => r.ClassName).ToArray();
					int[] autoAfterFirstPass = Profile.Relics.Select(r => r.LastAutoOrdinal).ToArray();
					int renum2 = n2.RenumberRelicClassNames(Profile.Relics);
					Check("重新编号是幂等的（再跑一遍类名和自动名序号都不改）",
						renum2 == 0 && Profile.Relics.Select(r => r.ClassName).SequenceEqual(afterFirstPass)
						&& Profile.Relics.Select(r => r.LastAutoOrdinal).SequenceEqual(autoAfterFirstPass),
						$"第二次改了 {renum2} 个");
					Check("认得出「自动生成的类名」形状：SevenRelic1 是、MyCharm / StelleRelic1 / SevenRelic1x / SevenRelic0 都不是",
						n2.IsAutoRelicClassName("SevenRelic1") && n2.IsAutoRelicClassName("SevenRelic12")
						&& !n2.IsAutoRelicClassName("MyCharm") && !n2.IsAutoRelicClassName("StelleRelic1")
						&& !n2.IsAutoRelicClassName("SevenRelic1x") && !n2.IsAutoRelicClassName("SevenRelic0")
						&& !n2.IsAutoRelicClassName("") && !n2.IsAutoRelicClassName(null),
						"判据对（共动了 " + renum + " 只）");
					// 用户要求原话：「如果没有填写英文类名，自动清除之前自动生成的英文类名，然后按照左侧序列号生成」
					// —— 这里直接照原话验一遍：把排序丁的类名改成**它自己原来位置的自动名**，
					// 再把它拖到第 1 位，重新编号后它必须换成正序号那个名字。
					Profile.Relics[d].ClassName = "SevenRelic" + (d + 1);
					Profile.Relics.Move(d, 0);
					RefreshRelicOrdinals();
					int renum3 = n2.RenumberRelicClassNames(Profile.Relics);
					Check("照用户原话：没填类名的（旧自动名）拖到第 1 位 → 旧自动名被清掉、按序列号重新生成（SevenRelic1）",
						Profile.Relics[0].Name == "排序丁" && Profile.Relics[0].ClassName == "SevenRelic1" && renum3 > 0,
						Profile.Relics[0].Name + " → " + Profile.Relics[0].ClassName);
					Check("界面上能看出这只遗物的类名是自动还是手填（ClassNameIsAuto / ClassNameHint）",
						Profile.Relics[a].ClassNameIsAuto == false && Profile.Relics[a].ClassNameHint.Contains("手填")
						&& Profile.Relics[c].ClassNameIsAuto && Profile.Relics[c].ClassNameHint.Contains("自动"),
						Profile.Relics[a].Name + "=" + (Profile.Relics[a].ClassNameIsAuto ? "自动" : "手填")
						+ " / " + Profile.Relics[c].Name + "=" + (Profile.Relics[c].ClassNameIsAuto ? "自动" : "手填"));
				}
				finally
				{
					foreach (RelicSpec r in testRelics) Profile.Relics.Remove(r);
					RelicList.SelectedIndex = 0;
					UpdateLayout();
					RefreshRelicOrdinals();
					if (RelicTriggerList.Items.Count > 0) RelicTriggerList.SelectedIndex = 0;
					if (RelicEffectList.Items.Count > 0) RelicEffectList.SelectedIndex = 0;
					UpdateLayout();
				}
			}
			// ===== 第 11 批（用户要求）：稀有度中文 / 中间底下有触发时机列表+自定义描述 / 右侧效果栏 + 右下角条件 =====
			{
				RelicSpec? cur = RelicList.SelectedItem as RelicSpec ?? Profile.Relics.FirstOrDefault();
				Check("稀有度下拉显示中文（初始 / 常见 / 罕见 / 稀有 / 先古 / 商店），存的值还是英文 id",
					EffectCatalog.RelicRarityOptions.Count == 6
					&& EffectCatalog.RelicRarityOptions.Select(o => o.Display).SequenceEqual(new[] { "初始", "常见", "罕见", "稀有", "先古", "商店" })
					&& EffectCatalog.RelicRarityOptions.Select(o => o.Id).SequenceEqual(new[] { "Starter", "Common", "Uncommon", "Rare", "Ancient", "Shop" }),
					string.Join(" / ", EffectCatalog.RelicRarityOptions.Select(o => o.Id + "=" + o.Display)));
				Check("稀有度下拉真的绑到 RelicRarityOptions（DisplayMemberPath=Display / SelectedValuePath=Id）",
					RelicRarityCombo is not null && ReferenceEquals(RelicRarityCombo.ItemsSource, RelicRarityOptions)
					&& RelicRarityCombo.DisplayMemberPath == "Display" && RelicRarityCombo.SelectedValuePath == "Id"
					&& BindingOperations.GetBinding(RelicRarityCombo, Selector.SelectedValueProperty)?.Path?.Path == "Rarity",
					RelicRarityCombo is null ? "(没找到下拉)" : "绑定对");
				Check("列表里显示的稀有度也是中文（第 1 只 = 初始）",
					cur is not null && cur.Display.Contains(EffectCatalog.RelicRarityZh(cur.Rarity)),
					cur?.Display ?? "(没选中)");

				// 中间部分底下：触发时机列表 + 自定义描述两栏（用户要求「在中间部分底下增加…在下方增加自定义描述」）
				List<TextBox> midBoxes = new List<TextBox>();
				CollectTextBoxes(RelicDetail, midBoxes);
				List<string> midPaths = midBoxes.Select(t => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path ?? "").ToList();
				List<CheckBox> midChecks = new List<CheckBox>();
				CollectCheckBoxes(RelicDetail, midChecks);
				List<string> midCheckPaths = midChecks.Select(c => BindingOperations.GetBinding(c, ToggleButton.IsCheckedProperty)?.Path?.Path ?? "").ToList();
				Check("中间部分底下有自定义描述那一栏（绑 CustomDescription）", midPaths.Contains("CustomDescription"), string.Join(" / ", midPaths.Where(p => p.Length > 0)));
				Check("自定义描述的第二栏「替换掉自动生成的描述」也在（绑 CustomDescriptionReplaces）",
					midCheckPaths.Contains("CustomDescriptionReplaces"), string.Join(" / ", midCheckPaths));
				Check("整只遗物的「条件选项」也还在中间这部分（绑 Condition.Kind）",
					midPaths.Contains("Condition.Amount2") && RelicConditionBox is not null && RelicConditionBox.IsVisible,
					RelicConditionBox is null ? "(没找到)" : "在");

				// 右侧 = 效果栏（V0.2.144）：上面一行摘要列表 + 下面一整块共享编辑区（绑 SelectedItem）；
				// 单条效果自己的「条件」跟着那条效果长在编辑区里（以前是右下角单独一块，已撤）。
				Check("右侧效果栏在（效果列表 + 添加效果 / 删除效果按钮）",
					RelicEffectList.IsVisible && RelicEffectList.Items.Count > 0
					&& TextsIn(RelicDetail).Contains("添加效果") && TextsIn(RelicDetail).Contains("删除效果"),
					RelicEffectList.Items.Count + " 条效果");
				if (RelicEffectList.Items.Count > 0) RelicEffectList.SelectedIndex = 0;
				UpdateLayout();
				Check("效果栏是「一行摘要列表 + 一块共享编辑区」（DisplayMemberPath=Display、没有 ItemTemplate、编辑区绑 SelectedItem）",
					RelicEffectList.DisplayMemberPath == "DisplayPlain" && RelicEffectList.ItemTemplate is null
					&& RelicEffectEditorBox is not null
					&& BindingOperations.GetBinding(RelicEffectEditorBox, FrameworkElement.DataContextProperty)?.ElementName == "RelicEffectList"
					&& BindingOperations.GetBinding(RelicEffectEditorBox, FrameworkElement.DataContextProperty)?.Path?.Path == "SelectedItem",
					"DisplayMemberPath=" + (RelicEffectList.DisplayMemberPath ?? "(null)") + " / ItemTemplate=" + (RelicEffectList.ItemTemplate is null ? "无" : "有"));
				List<ComboBox> condCombos = new List<ComboBox>();
				CollectCombos(RelicEffectEditorBox, condCombos);
				Check("编辑区里能改「这条效果自己的条件」（RelicEffectEditorBox 里的条件下拉绑 EffectSpec.Condition.Kind，DataContext = 选中的那条效果）",
					RelicEffectEditorBox is not null && RelicEffectEditorBox.IsVisible
					&& RelicEffectList.SelectedItem is EffectSpec
					&& ReferenceEquals(RelicEffectEditorBox.DataContext, RelicEffectList.SelectedItem)
					&& condCombos.Any(c => BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "Condition.Kind"),
					condCombos.Count + " 个下拉 / 编辑区 DataContext=" + ((RelicEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
			}
			// ===== 布局体检（本轮修的那个 bug：效果编辑器的行被排成 8260px 宽）=====
			{
				SelectTabRoot("遗物");
				if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
				if (RelicTriggerList.Items.Count > 0) RelicTriggerList.SelectedIndex = 0;
				if (RelicEffectList.Items.Count > 0) RelicEffectList.SelectedIndex = 0;
				UpdateLayout();
				double maxItemW = RelicEffectListActualMaxItemWidth();
				Check("效果编辑器不再被排成超宽（行宽 <= 列表宽 + 2px；以前是 8260px）",
					RelicEffectList.Items.Count == 0 || maxItemW <= RelicEffectList.ActualWidth + 2.0,
					maxItemW.ToString("F0") + " <= " + RelicEffectList.ActualWidth.ToString("F0"));
				Check("遗物页关键面板都没有 0 尺寸（列表 / 触发时机列表 / 效果栏 / 效果编辑区 / 自定义描述）",
					RelicList.ActualWidth > 10 && RelicList.ActualHeight > 10
					&& RelicTriggerList.ActualWidth > 10 && RelicTriggerList.ActualHeight > 10
					&& RelicEffectList.ActualWidth > 10 && RelicEffectList.ActualHeight > 10
					&& RelicEffectEditorBox.ActualWidth > 10 && RelicEffectEditorBox.ActualHeight > 10
					&& RelicCustomDesc.ActualWidth > 10 && RelicCustomDesc.ActualHeight > 10,
					$"列表 {RelicList.ActualWidth:F0}x{RelicList.ActualHeight:F0}，时机 {RelicTriggerList.ActualWidth:F0}x{RelicTriggerList.ActualHeight:F0}，"
					+ $"效果 {RelicEffectList.ActualWidth:F0}x{RelicEffectList.ActualHeight:F0}，编辑区 {RelicEffectEditorBox.ActualWidth:F0}x{RelicEffectEditorBox.ActualHeight:F0}，"
					+ $"自定义描述 {RelicCustomDesc.ActualWidth:F0}x{RelicCustomDesc.ActualHeight:F0}");
				double winW = ActualWidth;
				List<FrameworkElement> outOfPanel = VisibleElementsOutside(RelicDetail, 4.0);
				Check("遗物页没有控件横向跑出窗口 / 互相压住",
					outOfPanel.Count == 0 && RelicDetail.ActualWidth <= winW + 1.0,
					outOfPanel.Count == 0
						? $"详情宽 {RelicDetail.ActualWidth:F0} <= 窗口 {winW:F0}"
						: string.Join(" · ", outOfPanel.Take(4).Select(x =>
						{
							Point pp = default;
							try { pp = x.TransformToAncestor(RelicDetail).Transform(new Point(0, 0)); } catch { }
							return x.GetType().Name + " " + x.ActualWidth.ToString("F0") + "x" + x.ActualHeight.ToString("F0")
								+ " @" + pp.X.ToString("F0") + "," + pp.Y.ToString("F0");
						})));
				List<FrameworkElement> zeroSized = VisibleZeroSizedControls(RelicDetail, 24.0);
				Check("遗物页没有「看得见却量成 0 尺寸」的控件",
					zeroSized.Count == 0,
					zeroSized.Count == 0 ? "没有" : string.Join(" · ", zeroSized.Take(4).Select(x => x.GetType().Name + " " + x.ActualWidth.ToString("F0") + "x" + x.ActualHeight.ToString("F0"))));

				// ===== V0.2.144（用户拍板 A）：三页效果栏照卡牌页版式 =====
				// 用户原话：「遗物药水右侧的效果栏能不能同步卡牌的」——上面一行摘要列表（普通 ListBoxItem），
				// 下面一整块共享编辑区（DataContext 绑 SelectedItem）；折叠行那一套与 EffectSpec.IsExpanded 都没了。
				// 这里钉的都是**可视树上的证据**（不是模型属性）：行薄且显示一行摘要 → 选中一条 → 编辑区换成它 →
				// 编辑区里改「数值」真的写回模型 → 换一条跟着换 → 行里没有 Button（不再有「展开 / 收起」）。
				{
					SelectTabRoot("遗物");
					if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
					if (RelicTriggerList.Items.Count > 0) RelicTriggerList.SelectedIndex = 0;
					Check("V0.2.144 遗物效果栏至少有一条效果可以拿来验（样例存档里有）", RelicEffectList.Items.Count > 0, RelicEffectList.Items.Count + " 条");
					if (RelicEffectList.Items.Count > 0)
					{
						RelicEffectList.SelectedIndex = 0;
						UpdateLayout();
						var fx0 = RelicEffectList.Items[0] as EffectSpec;
						FrameworkElement? row0 = EffectRowContainer(RelicEffectList, 0);
						Check("V0.2.144 遗物页：列表那一行**很薄**（一行摘要 ≤60px；以前整块编辑器塞在行里是几百像素）",
							row0 is not null && row0.ActualHeight is > 0 and <= 60, $"行高 {(row0?.ActualHeight ?? 0):F0}");
						Check("V0.2.144 遗物页：那一行显示的就是 EffectSpec.Display（效果种类 + 数值 / 作用对象…）",
							fx0 is not null && EffectRowSummaryText(RelicEffectList, 0) == fx0.DisplayPlain,
							EffectRowSummaryText(RelicEffectList, 0) ?? "(没读到)");
						Check("V0.2.144 遗物页：选中一条 → 下面那块编辑区的 DataContext 立刻就是它",
							fx0 is not null && ReferenceEquals(RelicEffectEditorBox?.DataContext, fx0) && RelicEffectEditorBox?.IsVisible == true,
							"DataContext=" + ((RelicEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
						Check("V0.2.144 遗物页：那一行的行宽 ≤ 列表宽 + 2px（V0.2.124 那个 8260px 的坑不许被踩回来）",
							(row0?.ActualWidth ?? 0) <= RelicEffectList.ActualWidth + 2.0,
							$"{(row0?.ActualWidth ?? 0):F0} <= {RelicEffectList.ActualWidth:F0}");
						var kindBox = RelicEffectEditorBox is null ? null : FindFirstComboBoxBound(RelicEffectEditorBox, "Kind");
						Check("V0.2.144 遗物页：编辑区里是完整那套编辑器（「效果种类」下拉绑 EffectSpec.Kind）", kindBox is not null,
							kindBox is null ? "(没找到效果种类下拉)" : "在");
						if (fx0 is not null)
						{
							var amountBox = RelicEffectEditorBox is null ? null : FindFirstTextBoxBound(RelicEffectEditorBox, "Amount");
							decimal before = fx0.Amount;
							if (amountBox is not null)
							{
								amountBox.Text = "7";
								amountBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
								UpdateLayout();
							}
							Check("V0.2.144 遗物页：在编辑区改「数值」框 → **真的写回模型**（Amount 变成 7）",
								amountBox is not null && fx0.Amount == 7m,
								amountBox is null ? "(没找到数值框)" : $"{before:0.##} → {fx0.Amount:0.##}");
							if (amountBox is not null && before != 7m)
							{
								amountBox.Text = before.ToString("0.##");
								amountBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
								UpdateLayout();
							}
							Check("V0.2.144 遗物页：改完复原（自检不留痕）", fx0.Amount == before, $"{fx0.Amount:0.##}");
						}
						if (RelicEffectList.Items.Count > 1)
						{
							RelicEffectList.SelectedIndex = 1;
							UpdateLayout();
							Check("V0.2.144 遗物页：换选中另一条 → 编辑区跟着换（不串到上一条）",
								ReferenceEquals(RelicEffectEditorBox?.DataContext, RelicEffectList.Items[1]),
								"DataContext=" + ((RelicEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
							RelicEffectList.SelectedIndex = 0;
							UpdateLayout();
						}
						Check("V0.2.144 遗物页：效果行里不再有「展开 / 收起」那套交互（行就是普通 ListBoxItem，行里没有 Button）",
							row0 is not null && !EffectRowContainsButton(row0), row0 is null ? "(没生成行容器)" : "行里没有按钮");
						Check("V0.2.144：模型里的 EffectSpec.IsExpanded 已经删掉（折叠状态不再是界面状态）",
							typeof(EffectSpec).GetProperty("IsExpanded") is null, "属性不存在");
					}
				}

			}
			// ===== 药水页照抄遗物页（用户要求第 6 条「药水方面参考遗物的优化方案」，V0.2.127）=====
			// 逐条：① 左侧序号列（每块 5 个预留空槽，序号是位置号、不跟着药水走）；
			// ② 拖动药水项换位置（空槽也能当落点）；③ 自动英文类名跟序号走（手填的不动、幂等）；
			// ④ 稀有度英文改中文；⑤ 右侧效果栏（列表行内编辑 + 右下角单条效果的条件）+ 自定义描述保留。
			// 不适用、没做的：药水**没有「触发时机」**这个概念（遗物的「触发时机列表 / 关系开关 / 重置范围」
			// 一律不搬），「范围界定 / 关键词」这类药水用不到的效果模块也不无中生有。
			{
				// ---- ④ 稀有度英文改中文 ----
				Check("药水稀有度下拉显示中文（常见 / 罕见 / 稀有），存的值还是英文 id",
					EffectCatalog.PotionRarityOptions.Count == 3
					&& EffectCatalog.PotionRarityOptions.Select(o => o.Display).SequenceEqual(new[] { "常见", "罕见", "稀有" })
					&& EffectCatalog.PotionRarityOptions.Select(o => o.Id).SequenceEqual(EffectCatalog.PotionRarities),
					string.Join(" / ", EffectCatalog.PotionRarityOptions.Select(o => o.Id + "=" + o.Display)));
				Check("药水稀有度下拉真的绑到 PotionRarityOptions（DisplayMemberPath=Display / SelectedValuePath=Id）",
					PotionRarityCombo is not null && ReferenceEquals(PotionRarityCombo.ItemsSource, PotionRarityOptions)
					&& PotionRarityCombo.DisplayMemberPath == "Display" && PotionRarityCombo.SelectedValuePath == "Id"
					&& BindingOperations.GetBinding(PotionRarityCombo, Selector.SelectedValueProperty)?.Path?.Path == "Rarity",
					PotionRarityCombo is null ? "(没找到下拉)" : "绑定对");
				Check("药水列表里显示的稀有度也是中文（不再是 Common / Uncommon / Rare）",
					new PotionSpec { Name = "自检药水", Rarity = "Uncommon" }.Display.Contains("罕见")
					&& !new PotionSpec { Name = "自检药水", Rarity = "Uncommon" }.Display.Contains("Uncommon"),
					new PotionSpec { Name = "自检药水", Rarity = "Uncommon" }.Display);

				// ---- ③ 自动英文类名跟序号走（纯模型逻辑，和界面无关）----
				{
					var rn = Naming.From(ProfileFactory.Sample());
					var rnProfile = ProfileFactory.Sample();
					rnProfile.Potions.Clear();
					var rnHand = new PotionSpec { Name = "手填甲", ClassName = "MyOwnFlask", Rarity = "Common" };
					var rnEmpty = new PotionSpec { Name = "留空乙", ClassName = "", Rarity = "Common" };
					var rnAuto = new PotionSpec { Name = "自动丙", ClassName = rn.CharClass + "Potion9", Rarity = "Common" };
					var rnForeign = new PotionSpec { Name = "别家丁", ClassName = "SomebodyElsePotion5", Rarity = "Common" };
					rnProfile.Potions.Add(rnHand);
					rnProfile.Potions.Add(rnEmpty);
					rnProfile.Potions.Add(rnAuto);
					rnProfile.Potions.Add(rnForeign);
					int rnMoved = rn.RenumberPotionClassNames(rnProfile.Potions);
					Check("自动类名跟序号走：手填的一个字不动、留空的保持留空只记序号、工具自动生成的按当前序号重命名",
						rnHand.ClassName == "MyOwnFlask" && rnHand.LastAutoOrdinal == 0
						&& rnEmpty.ClassName == "" && rnEmpty.LastAutoOrdinal == 2
						&& rnAuto.ClassName == rn.CharClass + "Potion3" && rnAuto.LastAutoOrdinal == 3
						&& rnForeign.ClassName == "SomebodyElsePotion5",
						$"手填={rnHand.ClassName} / 留空='{rnEmpty.ClassName}':{rnEmpty.LastAutoOrdinal} / 自动={rnAuto.ClassName} / 别家={rnForeign.ClassName}（改了 {rnMoved} 处）");
					Check("自动类名的编号只认**本角色类名**前缀（别的角色的 PotionN 不会被当成我们的自动名）",
						rn.IsAutoPotionClassName(rn.CharClass + "Potion1") && !rn.IsAutoPotionClassName("SomebodyElsePotion5")
						&& !rn.IsAutoPotionClassName(rn.CharClass + "Potion0") && !rn.IsAutoPotionClassName(rn.CharClass + "PotionX"),
						rn.CharClass + "Potion1 = true / SomebodyElsePotion5 = false");
					// 幂等：再跑两遍一个字节都不动
					string rnSig = string.Join("|", rnProfile.Potions.Select(s => s.Name + ":" + s.ClassName + ":" + s.LastAutoOrdinal));
					rn.RenumberPotionClassNames(rnProfile.Potions);
					rn.RenumberPotionClassNames(rnProfile.Potions);
					Check("自动类名重编号是**幂等**的（连跑三遍：类名 / 序号一个字节都不变）",
						string.Join("|", rnProfile.Potions.Select(s => s.Name + ":" + s.ClassName + ":" + s.LastAutoOrdinal)) == rnSig,
						rnSig);
					Check("「拖到第 3 位、类名早就正好是 Potion3」也把 LastAutoOrdinal 同步好（界面小字不写上一个序号）",
						rnAuto.LastAutoOrdinal == 3, rnAuto.LastAutoOrdinal.ToString());
					// 拖到别的序号之后：自动名跟着换
					rnProfile.Potions.Move(2, 0);                       // 「自动丙」从第 3 位拖到第 1 位
					rn.RenumberPotionClassNames(rnProfile.Potions);
					Check("把自动命名的药水拖到第 1 位后重新生成 → 类名变成 <角色类名>Potion1（用户要的链路）",
						rnAuto.ClassName == rn.CharClass + "Potion1" && rnHand.ClassName == "MyOwnFlask"
						&& rnEmpty.ClassName == "" && rnEmpty.LastAutoOrdinal == 3,
						$"自动={rnAuto.ClassName} / 手填={rnHand.ClassName} / 留空序号={rnEmpty.LastAutoOrdinal}");
					// 「删掉英文类名 → 重新生成」：留空的保持留空，但记的序号是当前的
					rnAuto.ClassName = "";
					rn.RenumberPotionClassNames(rnProfile.Potions);
					Check("删掉英文类名后再生成 → 类名保持留空（生成端按当前序号拼）、只记序号",
						rnAuto.ClassName == "" && rnAuto.LastAutoOrdinal == 1
						&& rn.PotionClassName(rnAuto, 0) == rn.CharClass + "Potion1",
						$"留空 / 序号={rnAuto.LastAutoOrdinal} / 生成端会写 {rn.PotionClassName(rnAuto, 0)}");
					// 校验器不许静默：手打了一个「长得像自动编号但序号对不上」的名字要提示
					var rnWarn = ProfileFactory.Sample();
					rnWarn.Potions.Clear();
					rnWarn.Potions.Add(new PotionSpec { Name = "像自动名", ClassName = Naming.From(rnWarn).CharClass + "Potion7", Rarity = "Common" });
					Check("校验器：手填的类名长得像自动编号但序号对不上 → 提示「下次生成会改名」（不许静默）",
						ProfileValidator.Validate(rnWarn).Any(i => i.Level == "提示" && i.Message.Contains("自动生成的编号")),
						ProfileValidator.Validate(rnWarn).FirstOrDefault(i => i.Message.Contains("自动生成的编号"))?.Message ?? "(没报)");
					rnWarn.Potions[0].ClassName = "SevenFlask";
					Check("（对照）手填一个不像自动编号的名字 → 不报（别刷没用的提示）",
						!ProfileValidator.Validate(rnWarn).Any(i => i.Message.Contains("自动生成的编号")), "没报");
				}

				// ---- ①②⑤ 界面：序号 / 空槽 / 拖动 / 效果栏 ----
				List<PotionSpec> keptPotions = Profile.Potions.ToList();     // 这一轮的临时改动最后原样还回去
				PotionSpec? savedPotionSel = PotionUiSelection;
				int VisiblePotionOrdinals()
				{
					UpdateLayout();
					List<TextBlock> blocks = new List<TextBlock>();
					CollectTextBlocks(PotionList, blocks);
					return blocks.Count(t => (t.Text ?? "").EndsWith(".") && (t.Text ?? "").Length >= 2
						&& char.IsDigit((t.Text ?? "x")[0]) && t.Text!.Length <= 3);
				}
				try
				{
					SelectTabRoot("药水");
					// 断言 1：3 瓶 → 1~5 行（4、5 空槽），空槽不能被当成药水选中
					Profile.Potions.Clear();
					Profile.Potions.Add(new PotionSpec { Name = "瓶甲", ClassName = "UiCheckPotion1", Rarity = "Common" });
					Profile.Potions.Add(new PotionSpec { Name = "瓶乙", ClassName = "UiCheckPotion2", Rarity = "Uncommon" });
					Profile.Potions.Add(new PotionSpec { Name = "瓶丙", ClassName = "UiCheckPotion3", Rarity = "Rare" });
					PotionList.SelectedItem = Profile.Potions[0];
					UpdateLayout();
					string pOrd3 = string.Join(",", PotionRows.Select(r => r.OrdinalText));
					Check("（药水空槽 ①）3 瓶药水 → 列表显示 1~5 行（4、5 是空槽）",
						PotionRows.Count == 5 && pOrd3 == "1.,2.,3.,4.,5."
						&& PotionRows.Take(3).All(r => !r.IsPlaceholder) && PotionRows.Skip(3).All(r => r.IsPlaceholder)
						&& PotionList.Items.Count == 5,
						$"行 {PotionRows.Count} / 序号 {pOrd3} / 列表 Items {PotionList.Items.Count}");
					Check("（药水空槽 ①）界面上真画出了 5 个序号（序号在药水名最左侧一列）",
						VisiblePotionOrdinals() == 5, $"看到 {VisiblePotionOrdinals()} 个「N.」");
					string pBeforeDump = string.Join(" | ", Profile.Potions.Select(s => s.Name + ":" + s.Ordinal + ":" + s.ClassName));
					PotionList.SelectedItem = Profile.Potions[0];
					PotionSpec? pBeforeSel = PotionUiSelection;
					PotionList.SelectedItem = PotionRows[3];
					UpdateLayout();
					Check("（药水空槽 ①）选中空槽行：选中项不是 PotionSpec、当前选中的真药水没变、真药水一个字段都没被改",
						PotionList.SelectedItem is not PotionSpec && ReferenceEquals(PotionUiSelection, pBeforeSel)
						&& string.Join(" | ", Profile.Potions.Select(s => s.Name + ":" + s.Ordinal + ":" + s.ClassName)) == pBeforeDump
						&& Profile.Potions.Count == 3,
						$"SelectedItem={PotionList.SelectedItem?.GetType().Name ?? "(null)"}（空槽行） UiSel={PotionUiSelection?.Name ?? "(null)"} 药水 {Profile.Potions.Count} 瓶");
					// 断言 2：加到 6 瓶 → 1~10 行
					for (int i = 4; i <= 6; i++)
						Profile.Potions.Add(new PotionSpec { Name = "瓶" + i, ClassName = "UiCheckPotion" + i, Rarity = "Common" });
					UpdateLayout();
					string pOrd6 = string.Join(",", PotionRows.Select(r => r.OrdinalText));
					Check("（药水空槽 ②）加到 6 瓶 → 列表显示 1~10 行（7~10 是空槽）",
						PotionRows.Count == 10 && pOrd6 == string.Join(",", Enumerable.Range(1, 10).Select(i => i + "."))
						&& PotionRows.Take(6).All(r => !r.IsPlaceholder) && PotionRows.Skip(6).All(r => r.IsPlaceholder),
						$"行 {PotionRows.Count} / 序号 {pOrd6}");
					Check("（药水空槽 ②）界面上真画出了 10 个序号", VisiblePotionOrdinals() == 10, $"看到 {VisiblePotionOrdinals()} 个「N.」");
					// 断言 3：删回 5 瓶 → 5 行
					Profile.Potions.RemoveAt(5);
					UpdateLayout();
					string pOrd5 = string.Join(",", PotionRows.Select(r => r.OrdinalText));
					Check("（药水空槽 ③）删回 5 瓶 → 行数回到 5（序号 1~5，没有空槽）",
						PotionRows.Count == 5 && pOrd5 == "1.,2.,3.,4.,5." && PotionRows.All(r => !r.IsPlaceholder)
						&& Profile.Potions.Count == 5,
						$"行 {PotionRows.Count} / 序号 {pOrd5} / 真药水 {Profile.Potions.Count}");
					// 断言 4：拖一瓶到空槽 → Profile.Potions 顺序真的变、序号仍是 1..N 连续
					Profile.Potions.RemoveAt(4);                    // 退回 4 瓶：1~4 真药水 + 第 5 行空槽
					PotionSpec draggedPotion = Profile.Potions[0];
					PotionList.SelectedItem = draggedPotion;
					UpdateLayout();
					DependencyObject? pRowC = PotionList.ItemContainerGenerator.ContainerFromIndex(4) as DependencyObject;
					bool pSlotHitNull = false;
					string pSlotDetail = "(没有容器)";
					if (pRowC is FrameworkElement pRowCFe)
					{
						Point pOffset = pRowCFe.TransformToVisual(PotionList).Transform(new Point(0, 0));
						var pAt = PotionRowAtPoint(new Point(pOffset.X + pRowCFe.ActualWidth * 0.5, pOffset.Y + pRowCFe.ActualHeight * 0.5));
						pSlotHitNull = pAt.Potion is null && pAt.Index == 4;
						pSlotDetail = $"行{pAt.Index}/{(pAt.Potion?.Name ?? "无药水")}";
					}
					Check("（药水空槽 ④）空槽那一行在屏幕上点得到、而且它不给任何药水（Potion = null）",
						pSlotHitNull, pSlotDetail);
					string pNamesBefore = string.Join("→", Profile.Potions.Select(s => s.Name));
					bool pMoved = MovePotionTo(draggedPotion, null, 4);       // 拖到第 5 行（空槽）→ 夹到末尾
					UpdateLayout();
					Check("（药水空槽 ④）拖一瓶药水到空槽：Profile.Potions 顺序真的变、序号仍是 1..N 连续",
						pMoved && Profile.Potions[Profile.Potions.Count - 1] == draggedPotion
						&& Profile.Potions.Select(s => s.Ordinal).SequenceEqual(Enumerable.Range(1, Profile.Potions.Count))
						&& PotionRows.Take(Profile.Potions.Count).SequenceEqual<ISlotRow>(Profile.Potions)
						&& PotionRows[Profile.Potions.Count].IsPlaceholder && PotionRows.Count == 5,
						$"{pNamesBefore} → " + string.Join("→", Profile.Potions.Select(s => s.Name))
						+ $" ／ 序号 {string.Join(",", PotionRows.Select(r => r.OrdinalText))}");
					// 断言 5：空槽不出现在真集合 / 生成结果里
					Check("（药水空槽 ⑤）Profile.Potions 里只有真药水，空槽项一个都没混进去",
						Profile.Potions.Count == 4 && Profile.Potions.All(s => s is not null)
						&& !PotionRows.OfType<PotionSpec>().Any(r => !Profile.Potions.Contains(r) && !ReferenceEquals(r, draggedPotion)),
						$"{Profile.Potions.Count} 瓶 / 镜像 {PotionRows.Count} 行");
					{
						var pSlotProfile = ProfileFactory.Sample();
						pSlotProfile.Potions.Clear();
						pSlotProfile.Potions.Add(new PotionSpec { Name = "唯一瓶", ClassName = "UiCheckSlotPotion", Rarity = "Common" });
						pSlotProfile.Paths.OutputDir = Path.Combine(Path.GetTempPath(), "forge_uicheck_potionslot_" + Guid.NewGuid().ToString("N").Substring(0, 8));
						// ⚠ 这两条必须从当前存档抄过来：生成要先看「解包工程目录 / 游戏 data 目录」在不在，
						// 不抄就是两条「环境没配」的错误（遗物页那段同样是这么补的）。
						pSlotProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
						pSlotProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
						var pSlotGen = ModGenerator.Generate(pSlotProfile);
						string pSlotFiles = pSlotGen.Success
							? string.Join("\n", Directory.GetFiles(pSlotGen.ProjectRoot, "*", SearchOption.AllDirectories)
								.Select(f => Path.GetRelativePath(pSlotGen.ProjectRoot, f).Replace('\\', '/'))
								.OrderBy(x => x, StringComparer.Ordinal))
							: "";
						Check("（药水空槽 ⑤）真生成一遍：没有空槽类 / 空槽文件（也没多出第 2 瓶药水）",
							pSlotGen.Success && pSlotFiles.Length > 0
							&& !pSlotFiles.Contains("SlotPlaceholder") && !pSlotFiles.Contains("空槽")
							&& pSlotProfile.Potions.Count == 1,
							pSlotGen.Success ? $"生成 {pSlotFiles.Split('\n').Length} 个文件，一个「空槽」都没有" : string.Join(" / ", pSlotGen.Issues.Where(i => i.IsError).Take(3)));
						try { if (Directory.Exists(pSlotProfile.Paths.OutputDir)) Directory.Delete(pSlotProfile.Paths.OutputDir, true); } catch { }
					}
					// 断言 6：空槽行是灰序号、名字列空、全选不含空槽
					UpdateLayout();
					List<TextBlock> pOrdBlocks = new List<TextBlock>();
					CollectTextBlocks(PotionList, pOrdBlocks);
					var pOrdInfos = pOrdBlocks
						.Where(t => (t.Text ?? "").Length is 2 or 3 && (t.Text ?? "").EndsWith(".") && char.IsDigit((t.Text ?? "x")[0]))
						.Select(t => (Text: t.Text!, Color: (t.Foreground as SolidColorBrush)?.Color.ToString() ?? "(不是纯色)", Visible: t.IsVisible))
						.ToList();
					var pRealInfos = pOrdInfos.Where(o => Profile.Potions.Any(s => s.OrdinalText == o.Text)).ToList();
					var pSlotInfos = pOrdInfos.Where(o => PotionRows.Any(r => r.IsPlaceholder && r.OrdinalText == o.Text)).ToList();
					Check("（药水空槽 ⑥）空槽行的序号是**灰**的：颜色和真药水行不一样、行本身可见",
						pRealInfos.Count > 0 && pSlotInfos.Count > 0
						&& pSlotInfos.All(s => s.Visible
							&& (s.Color.Contains("AAAAAA", StringComparison.OrdinalIgnoreCase) || s.Color.Contains("170,170,170", StringComparison.Ordinal)))
						&& pRealInfos.All(r => !r.Color.Contains("AAAAAA", StringComparison.OrdinalIgnoreCase) && !r.Color.Contains("170,170,170", StringComparison.Ordinal)),
						$"实化序号 {string.Join(" / ", pOrdInfos.Select(o => o.Text + "=" + o.Color))} ／ 真药水 {pRealInfos.Count} 行、空槽 {pSlotInfos.Count} 行");
					Check("（药水空槽 ⑥）空槽行的「药水名」那一列是空的（没有内容、也不给提示）",
						PotionRows[Profile.Potions.Count] is SlotPlaceholder pPh && pPh.Display.Length == 0 && pPh.RowTip is null
						&& !string.IsNullOrEmpty(PotionRows[Profile.Potions.Count].OrdinalText),
						$"Display='{((SlotPlaceholder)PotionRows[Profile.Potions.Count]).Display}' RowTip={(PotionRows[Profile.Potions.Count].RowTip ?? "(null)")}");
					ToggleButton? pMulti = FindToggleButtonByContent("多选", SelectTabRoot("药水"));
					if (pMulti is not null && pMulti.IsChecked != true) ToggleViaClick(pMulti);
					UpdateLayout();
					ClickButtonByContent("全选", SelectTabRoot("药水"));
					UpdateLayout();
					Check("（药水空槽 ⑥）「全选」只选中真药水：SelectedItems 里一个空槽都没有",
						PotionList.SelectedItems.Count == Profile.Potions.Count
						&& PotionList.SelectedItems.OfType<SlotPlaceholder>().Count() == 0
						&& !PotionList.SelectedItems.Cast<object>().Any(o => o is ISlotRow { IsPlaceholder: true }),
						$"选中 {PotionList.SelectedItems.Count} / 真药水 {Profile.Potions.Count} / 行数 {PotionRows.Count}");
					PotionList.SelectedItems.Clear();
					if (pMulti is not null && pMulti.IsChecked == true) ToggleViaClick(pMulti);
					UpdateLayout();
				}
				finally
				{
					Profile.Potions.Clear();
					foreach (PotionSpec s in keptPotions) Profile.Potions.Add(s);
					RefreshPotionOrdinals();
					PotionList.SelectedItem = (savedPotionSel is not null && Profile.Potions.Contains(savedPotionSel))
						? savedPotionSel
						: Profile.Potions.FirstOrDefault();
					SyncDetail();
					UpdateLayout();
				}

				// ---- ⑤ 右侧效果栏 + 右下角单条效果的条件（照遗物页那套）----
				SelectTabRoot("药水");
				if (PotionList.Items.Count > 0) PotionList.SelectedIndex = 0;
				if (PotionEffectList.Items.Count > 0) PotionEffectList.SelectedIndex = 0;
				UpdateLayout();
				Check("药水页右边是**效果栏**：上面一行摘要列表（DisplayMemberPath=Display）+ 下面一整块共享编辑区",
					PotionEffectList.DisplayMemberPath == "DisplayPlain" && PotionEffectList.ItemTemplate is null
					&& PotionEffectEditorBox is not null
					&& BindingOperations.GetBinding(PotionEffectEditorBox, FrameworkElement.DataContextProperty)?.ElementName == "PotionEffectList"
					&& BindingOperations.GetBinding(PotionEffectEditorBox, FrameworkElement.DataContextProperty)?.Path?.Path == "SelectedItem",
					(PotionEffectList.DisplayMemberPath ?? "(null)") + " / " + (PotionEffectList.ItemTemplate is null ? "无模板" : "有模板"));
				List<ComboBox> potionCondCombos = new List<ComboBox>();
				CollectCombos(PotionEffectEditorBox, potionCondCombos);
				Check("药水页编辑区里能改「这条效果自己的条件」（绑 EffectSpec.Condition.Kind，DataContext = 选中的那条效果）",
					PotionEffectEditorBox is not null && PotionEffectEditorBox.IsVisible
					&& PotionEffectList.SelectedItem is EffectSpec
					&& ReferenceEquals(PotionEffectEditorBox.DataContext, PotionEffectList.SelectedItem)
					&& potionCondCombos.Any(c => BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "Condition.Kind"),
					potionCondCombos.Count + " 个下拉 / 编辑区 DataContext=" + ((PotionEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
				// 药水**没有**「触发时机」：不要把遗物的时机列表 / 关系开关硬塞过来
				Check("药水页没有「触发时机」那套（药水没有这个概念，需求里也说了不适用）",
					!TextsIn(PotionDetail).Any(t => t.Contains("触发时机列表"))
					&& !TextsIn(PotionDetail).Any(t => t.Contains("满足其中一个就触发") || t.Contains("全部满足才触发")),
					"没有时机列表 / 关系开关");
				Check("药水自定义描述保留（绑 CustomDescription / CustomDescriptionReplaces）",
					PotionCustomDesc is not null && PotionCustomDesc.IsVisible
					&& BindingOperations.GetBinding(PotionCustomDesc, TextBox.TextProperty)?.Path?.Path == "CustomDescription",
					PotionCustomDesc is null ? "(没找到)" : "在");
				// ---- 布局体检（照遗物页：行宽 / 0 尺寸 / 别横向跑出面板）----
				double pMaxItemW = PotionEffectListActualMaxItemWidth();
				Check("药水效果栏的列表行不再被排成超宽（行宽 <= 列表宽 + 2px）",
					PotionEffectList.Items.Count == 0 || pMaxItemW <= PotionEffectList.ActualWidth + 2.0,
					pMaxItemW.ToString("F0") + " <= " + PotionEffectList.ActualWidth.ToString("F0"));
				Check("药水页关键面板都没有 0 尺寸（列表 / 效果栏 / 效果编辑区 / 自定义描述 / 稀有度下拉）",
					PotionList.ActualWidth > 10 && PotionList.ActualHeight > 10
					&& PotionEffectList.ActualWidth > 10 && PotionEffectList.ActualHeight > 10
					&& PotionEffectEditorBox.ActualWidth > 10 && PotionEffectEditorBox.ActualHeight > 10
					&& PotionCustomDesc.ActualWidth > 10 && PotionCustomDesc.ActualHeight > 10
					&& PotionRarityCombo.ActualWidth > 10 && PotionRarityCombo.ActualHeight > 10,
					$"列表 {PotionList.ActualWidth:F0}x{PotionList.ActualHeight:F0}，效果 {PotionEffectList.ActualWidth:F0}x{PotionEffectList.ActualHeight:F0}，"
					+ $"编辑区 {PotionEffectEditorBox.ActualWidth:F0}x{PotionEffectEditorBox.ActualHeight:F0}，"
					+ $"自定义描述 {PotionCustomDesc.ActualWidth:F0}x{PotionCustomDesc.ActualHeight:F0}，稀有度 {PotionRarityCombo.ActualWidth:F0}x{PotionRarityCombo.ActualHeight:F0}");
				List<FrameworkElement> pOutOfPanel = VisibleElementsOutside(PotionDetail, 4.0);
				Check("药水页没有控件横向跑出窗口",
					pOutOfPanel.Count == 0 && PotionDetail.ActualWidth <= ActualWidth + 1.0,
					pOutOfPanel.Count == 0
						? $"详情宽 {PotionDetail.ActualWidth:F0} <= 窗口 {ActualWidth:F0}"
						: string.Join(" · ", pOutOfPanel.Take(4).Select(x => x.GetType().Name + " " + x.ActualWidth.ToString("F0"))));
				List<FrameworkElement> pZeroSized = VisibleZeroSizedControls(PotionDetail, 24.0);
				Check("药水页没有「看得见却量成 0 尺寸」的控件",
					pZeroSized.Count == 0,
					pZeroSized.Count == 0 ? "没有" : string.Join(" · ", pZeroSized.Take(4).Select(x => x.GetType().Name + " " + x.ActualWidth.ToString("F0") + "x" + x.ActualHeight.ToString("F0"))));

				// ===== V0.2.144：药水页也是「一行摘要列表 + 一块共享编辑区」（和遗物 / 卡牌页同一个形状）=====
				{
					SelectTabRoot("药水");
					if (PotionList.Items.Count > 0) PotionList.SelectedIndex = 0;
					if (PotionEffectList.Items.Count > 0) PotionEffectList.SelectedIndex = 0;
					UpdateLayout();
					Check("V0.2.144 药水效果栏至少有一条效果可以拿来验（样例存档里有）", PotionEffectList.Items.Count > 0, PotionEffectList.Items.Count + " 条");
					if (PotionEffectList.Items.Count > 0)
					{
						var pfx = PotionEffectList.Items[0] as EffectSpec;
						FrameworkElement? pRow = EffectRowContainer(PotionEffectList, 0);
						Check("V0.2.144 药水页：列表那一行很薄（一行摘要 ≤60px）",
							pRow is not null && pRow.ActualHeight is > 0 and <= 60, $"行高 {(pRow?.ActualHeight ?? 0):F0}");
						Check("V0.2.144 药水页：那一行显示的就是 EffectSpec.Display",
							pfx is not null && EffectRowSummaryText(PotionEffectList, 0) == pfx.DisplayPlain,
							EffectRowSummaryText(PotionEffectList, 0) ?? "(没读到)");
						Check("V0.2.144 药水页：选中一条 → 编辑区的 DataContext 立刻就是它（含它自己的条件）",
							pfx is not null && ReferenceEquals(PotionEffectEditorBox?.DataContext, pfx)
							&& PotionEffectEditorBox?.IsVisible == true
							&& FindFirstComboBoxBound(PotionEffectEditorBox, "Condition.Kind") is not null,
							"DataContext=" + ((PotionEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
						Check("V0.2.144 药水页：列表行行宽 ≤ 列表宽 + 2px",
							(pRow?.ActualWidth ?? 0) <= PotionEffectList.ActualWidth + 2.0,
							$"{(pRow?.ActualWidth ?? 0):F0} <= {PotionEffectList.ActualWidth:F0}");
						Check("V0.2.144 药水页：效果行里不再有「展开 / 收起」那套交互（行里没有 Button）",
							pRow is not null && !EffectRowContainsButton(pRow), pRow is null ? "(没生成行容器)" : "行里没有按钮");
					}
				}


				// ---- 额外资源量页：改名后的页头 + 「在游戏中隐藏」勾选框 + 右侧效果栏（用户要求第 1 条）----
				{
					bool erWasEnabled2 = Profile.ExtraResource.Enabled;
					Profile.ExtraResource.Enabled = true;
					Raise("ExtraResourceRelicVisible");
					DependencyObject erRoot = SelectTabRoot("额外资源量");
					UpdateLayout();
					Check("页头就叫「额外资源量」（用户原话：额外资源量/状态页改名为额外资源量页）",
						(ExtraResourceTab?.Header as string) == "额外资源量"
						&& FindTab("额外资源量/状态") is null,
						"Header=" + (ExtraResourceTab?.Header as string ?? "(null)"));
					List<CheckBox> erChecks = new List<CheckBox>();
					CollectCheckBoxes(erRoot, erChecks);
					Check("这一页有「是否隐藏额外资源量遗物」的勾选项、而且是勾得动、真的写回配置",
						erChecks.Any(c => (c.Content as string ?? "").StartsWith("在游戏中隐藏", StringComparison.Ordinal)
							&& BindingOperations.GetBinding(c, ToggleButton.IsCheckedProperty)?.Path?.Path == "HideInGame"),
						string.Join(" / ", erChecks.Select(c => c.Content as string)));
					Check("这一页右侧有**效果栏**（一行摘要列表 + 添加/删除效果 + 一块共享编辑区，和遗物 / 药水页同一个形状）",
						ExtraResourceEffectList.ItemTemplate is null && ExtraResourceEffectList.DisplayMemberPath == "DisplayPlain"
						&& ExtraResourceEffectList.ItemsSource == Profile.ExtraResource.Effects
						&& ExtraResourceEffectList.IsVisible
						&& TextsIn(erRoot).Contains("效果栏：额外资源量遗物的效果（触发时机固定「战斗开始时」）"),
						ExtraResourceEffectList.Items.Count + " 条效果 / 模板=" + (ExtraResourceEffectList.ItemTemplate is null ? "无" : "有")
						+ " / DisplayMemberPath=" + (ExtraResourceEffectList.DisplayMemberPath ?? "(null)"));
					List<ComboBox> erCondCombos = new List<ComboBox>();
					if (ExtraResourceEffectList.Items.Count > 0) ExtraResourceEffectList.SelectedIndex = 0;
					UpdateLayout();
					CollectCombos(ExtraResourceEffectEditorBox, erCondCombos);
					Check("额外资源量页的共享编辑区里也能改「单条效果的条件」（和遗物 / 药水页一一对应）",
						ExtraResourceEffectEditorBox is not null
						&& (ExtraResourceEffectList.Items.Count == 0
							|| (ExtraResourceEffectEditorBox.IsVisible
								&& ReferenceEquals(ExtraResourceEffectEditorBox.DataContext, ExtraResourceEffectList.SelectedItem))),
						erCondCombos.Count + " 个下拉 / 编辑区 DataContext=" + ((ExtraResourceEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
					// 效果只有**一份**（就是那只载体遗物的效果）——不许搞出第二份数据
					Check("效果仍然只有一份（Profile.ExtraResource.Effects 那一个集合，界面没有第二份镜像）",
						ReferenceEquals(ExtraResourceEffectList.ItemsSource, Profile.ExtraResource.Effects)
						&& ReferenceEquals(Profile.ExtraResource.Effects, Profile.ExtraResource.Effects),
						"同一份集合");
					double erMaxItemW = 0;
					for (int i = 0; i < ExtraResourceEffectList.Items.Count; i++)
					{
						if (ExtraResourceEffectList.ItemContainerGenerator.ContainerFromIndex(i) is FrameworkElement fe)
							erMaxItemW = Math.Max(erMaxItemW, fe.ActualWidth);
					}
					Check("额外资源量效果栏的列表行也没被排成超宽（行宽 <= 列表宽 + 2px）",
						ExtraResourceEffectList.Items.Count == 0 || erMaxItemW <= ExtraResourceEffectList.ActualWidth + 2.0,
						erMaxItemW.ToString("F0") + " <= " + ExtraResourceEffectList.ActualWidth.ToString("F0"));
					Check("额外资源量页关键面板都没有 0 尺寸（效果栏 / 效果编辑区 / 隐藏勾选框）",
						ExtraResourceEffectList.ActualWidth > 10 && ExtraResourceEffectList.ActualHeight > 10
						&& ExtraResourceEffectEditorBox.ActualWidth > 10 && ExtraResourceEffectEditorBox.ActualHeight > 10
						&& (ExtraResourceEffectList.Items.Count == 0
							|| (EffectRowContainer(ExtraResourceEffectList, 0)?.ActualHeight ?? 0) > 0),
						$"效果 {ExtraResourceEffectList.ActualWidth:F0}x{ExtraResourceEffectList.ActualHeight:F0}，编辑区 {ExtraResourceEffectEditorBox.ActualWidth:F0}x{ExtraResourceEffectEditorBox.ActualHeight:F0}");
					List<FrameworkElement> erOut = VisibleElementsOutside(ExtraResourceTab.Content as DependencyObject ?? erRoot, 4.0);
					Check("额外资源量页没有控件横向跑出页面",
						erOut.Count == 0,
						erOut.Count == 0 ? "没有" : string.Join(" · ", erOut.Take(4).Select(x =>
							x.GetType().Name + " " + x.ActualWidth.ToString("F0")
							+ (x is TextBlock tb && tb.Text.Length > 0 ? "「" + (tb.Text.Length > 28 ? tb.Text[..28] + "…" : tb.Text) + "」" : ""))));
