			var ancFilters = EffectCatalog.GroupOnlyFiltersFor(ancUi);
			Check("「转化为先古卡」的源组候选**只有组**（不自带攻击 / 技能 / 能力 / 诅咒 / 状态那几条）",
				ancFilters.Count == 2 && ancFilters.All((SpawnFilterOption f) => f.Id.StartsWith("Group:", StringComparison.Ordinal)),
				string.Join(" / ", ancFilters.Select((SpawnFilterOption f) => f.Id)));
			Check("「转化为先古卡」的源组候选里**没有**内置类型那几条（用户要求「来源只用组」）",
				!ancFilters.Any((SpawnFilterOption f) => f.Id is "Attack" or "Skill" or "Power" or "Curse" or "Status" or ""),
				$"{ancFilters.Count} 条候选");
			// 生成：一组 → 各不相同
			CharacterProfile ancGen = ProfileFactory.Sample();
			ancGen.CardGroups.Clear();
			ancGen.CardGroups.Add(new CardGroupSpec { Id = "uiGrpA", Name = "初始牌组" });
			ancGen.Cards.Clear();
			ancGen.Cards.Add(new CardSpec { Name = "打击", ClassName = "UiAncStrike", CardType = "Attack", Rarity = "Basic", Cost = 1, InStartingDeck = true, StartingCopies = 3, GroupIds = { "uiGrpA" } });
			ancGen.Cards.Add(new CardSpec { Name = "防御", ClassName = "UiAncDefend", CardType = "Skill", Rarity = "Basic", Cost = 1, InStartingDeck = true, StartingCopies = 2, GroupIds = { "uiGrpA" } });
			ancGen.Cards.Add(new CardSpec { Name = "凑数", ClassName = "UiAncFiller", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true });
			var ancRelic = new RelicSpec { Name = "先古牙齿", ClassName = "UiAncTooth", Rarity = "Rare", Trigger = "Obtained", InRelicPool = true };
			var ancEffect = new EffectSpec { Kind = "AncientTranscend", TargetSide = "Self" };
			ancEffect.AncientRows.Add(new AncientTranscendRow { Group = "Group:uiGrpA", AncientCards = { "Break", "Suppress", "Protector" } });
			ancRelic.Effects.Clear();
			ancRelic.Effects.Add(ancEffect);
			ancGen.Relics.Clear();
			ancGen.Relics.Add(ancRelic);
			string ancRelicSrc = CSharpCodeGen.RelicSource(ancGen, ancRelic, 0);
			Check("生成里按「组」筛牌组（类名白名单，不是随机挑一张）",
				ancRelicSrc.Contains("\"UiAncStrike\", \"UiAncDefend\"") && ancRelicSrc.Contains(".Contains(c.Id.Entry)"),
				ancRelicSrc.Contains("UiAncStrike") ? "白名单在" : "没按组筛");
			Check("生成里带 c.IsRemovable（本体永恒牌不能被变化）", ancRelicSrc.Contains("c.IsRemovable"), "带上了");
			Check("生成里用**批量** CardCmd.Transform（本体潘多拉的写法），不是一张一张地变",
				ancRelicSrc.Contains("new List<CardTransformation>()") && ancRelicSrc.Contains("await CardCmd.Transform(__fgAncient0_0_tx"), "批量在");
			Check("「各不相同」：循环上界是 牌数 与 池子数 的较小值（池子用完就不换，不循环复用）",
				ancRelicSrc.Contains("__fgAncient0_0_i < __fgAncient0_0_src.Count && __fgAncient0_0_i < __fgAncient0_0_pool.Count"), "上界对");
			Check("保留升级 / 保留附魔（和本体古老牙齿一致）",
				ancRelicSrc.Contains("if (__fgAncient0_0_from.IsUpgraded)") && ancRelicSrc.Contains("CardCmd.Enchant("), "都带上了");
			Check("池子不够时会打一行日志（不静默少换）",
				ancRelicSrc.Contains("Log.Warn(\"转化为先古卡：这一行匹配到 \""), "有日志");
			Check("预览：用本体那个 public static 的 NSimpleCardsViewScreen 弹一屏（用户要求「预览要弹」）",
				ancRelicSrc.Contains("NSimpleCardsViewScreen.ShowScreen(__fgAncientPreview"), "弹窗在");
			Check("预览的说明文案有自己的本地化键（不会显示成缺键）",
				LocalizationGen.RelicsJson(ancGen).Contains(CSharpCodeGen.AncientPreviewLocKey), CSharpCodeGen.AncientPreviewLocKey);
			// 校验器：只许「获得时」  空表 / 空池 / 太短
			Check("「转化为先古卡」挂在「获得时」→ 校验器不报这条错",
				!ProfileValidator.Validate(ancGen).Any((ValidationIssue i) => i.IsError && i.Message.Contains("转化为先古卡")),
				string.Join(" / ", ProfileValidator.Validate(ancGen).Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message)));
			var ancWrong = new RelicSpec { Name = "错时机牙齐", ClassName = "UiAncWrong", Rarity = "Rare", Trigger = "CombatStart", InRelicPool = true };
			var ancWrongEffect = new EffectSpec { Kind = "AncientTranscend", TargetSide = "Self" };
			ancWrongEffect.AncientRows.Add(new AncientTranscendRow { Group = "Group:uiGrpA", AncientCards = { "Break" } });
			ancWrong.Effects.Clear();
			ancWrong.Effects.Add(ancWrongEffect);
			CharacterProfile ancWrongProf = ProfileFactory.Sample();
			ancWrongProf.Relics.Clear();
			ancWrongProf.Relics.Add(ancWrong);
			Check("「转化为先古卡」挂在别的触发时机上 → 校验器报**错误**（它改的是牌组，本体只在拾取那一刻做）",
				ProfileValidator.Validate(ancWrongProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只允许挂在「获得时」")),
				"拦住了");
			var ancEmpty = new EffectSpec { Kind = "AncientTranscend", TargetSide = "Self" };
			var ancEmptyRelic = new RelicSpec { Name = "空表牙齿", ClassName = "UiAncEmpty", Rarity = "Rare", Trigger = "Obtained", InRelicPool = true };
			ancEmptyRelic.Effects.Clear();
			ancEmptyRelic.Effects.Add(ancEmpty);
			CharacterProfile ancEmptyProf = ProfileFactory.Sample();
			ancEmptyProf.Relics.Clear();
			ancEmptyProf.Relics.Add(ancEmptyRelic);
			Check("配对表是空的 → 校验器报错并告诉你点「加一行」",
				ProfileValidator.Validate(ancEmptyProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("还没有配对表")), "报错了");
			var ancNoPool = new EffectSpec { Kind = "AncientTranscend", TargetSide = "Self" };
			ancNoPool.AncientRows.Add(new AncientTranscendRow { Group = "Group:uiGrpA" });
			ancEmptyRelic.Effects.Clear();
			ancEmptyRelic.Effects.Add(ancNoPool);
			Check("某一行没勾先古卡 → 校验器报错",
				ProfileValidator.Validate(ancEmptyProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("还没勾任何先古卡")), "报错了");
			// 界面：配对表跟着「当前选中的那条效果」走（用一条真效果走一遍加行 / 勾卡）"
			CharacterProfile ancUiProf = ProfileFactory.Sample();
			ancUiProf.CardGroups.Clear();
			ancUiProf.CardGroups.Add(new CardGroupSpec { Id = "uiGrpA", Name = "初始牌组" });
			ancUiProf.CardGroups.Add(new CardGroupSpec { Id = "uiGrpB", Name = "幻想牌" });   // 第二行要用到「还没用过的组」
			ancUiProf.Relics.Clear();
			ancUiProf.Relics.Add(ancRelic);
			CharacterProfile ancUiSaved = _profile;
			// 换存档会把各页的列表清一遍（药水页的选中项会没掉），收尾时要摆回去 
			int ancSavedPotionSel = PotionList.SelectedIndex;
			_profile = ancUiProf;
			Raise("Profile");
			if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
			if (RelicEffectList.Items.Count > 0) RelicEffectList.SelectedIndex = 0;
			UpdateLayout();
			Check("界面：遗物页选中了这条「转化为先古卡」效果",
				CurrentEditEffect is { IsAncientTranscend: true },
				CurrentEditEffect is null ? "没选中任何效果" : CurrentEditEffect.Kind);
			Check("界面：配对表里有 1 行", AncientRowItems.Count == 1, $"{AncientRowItems.Count} 行");
			Check("界面：先古卡池非空（本体先古卡都在里面）", AncientCardRows.Count >= 19, $"{AncientCardRows.Count} 张候选");
			OnAddAncientRow(this, new RoutedEventArgs());
			UpdateLayout();
			Check("界面：点「＋ 加一行」真的往配对表里加了一行",
				ancEffect.AncientRows.Count == 2, $"{ancEffect.AncientRows.Count} 行");
			bool secondRowOk = ancEffect.AncientRows.Count >= 2 && ancEffect.AncientRows[1].Group.Length > 0
				&& ancEffect.AncientRows[1].Group != ancEffect.AncientRows[0].Group;
			Check("界面：新加的这行默认选了另一个组（不重复）", secondRowOk,
				ancEffect.AncientRows.Count >= 2 ? ancEffect.AncientRows[1].Group : "没有第二行");
			AncientCardItem? poolItem = AncientCardRows.FirstOrDefault((AncientCardItem c) => c.ClassName == "Apotheosis");
			Check("界面：先古卡池里有「神化」这类本体先古卡", poolItem is not null, poolItem?.Name ?? "没找到");
			if (poolItem is not null && ancEffect.AncientRows.Count >= 2)
			{
				poolItem.IsChecked = true;
				Check("界面：勾一张先古卡会写进**当前那一行**的池子里",
					ancEffect.AncientRows[1].AncientCards.Contains("Apotheosis"), string.Join(",", ancEffect.AncientRows[1].AncientCards));
				poolItem.IsChecked = false;
			}
			// 收尾：把窗口摆回原来那份存档，别影响后面的自检
			_profile = ancUiSaved;
			Raise("Profile");
			if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
			if (PotionList.Items.Count > 0) PotionList.SelectedIndex = Math.Min(Math.Max(0, ancSavedPotionSel), PotionList.Items.Count - 1);
			UpdateLayout();
		}

		// ===== 转化为先古遗物（用户要求：「先古遗物的替换遗物也搞一个类似的吧」）=====
		{
			Check("效果种类里有「转化为先古遗物」",
				Kinds.Any((EffectKindOption k) => k.Kind == "AncientRelicSwap"),
				Kinds.FirstOrDefault((EffectKindOption k) => k.Kind == "AncientRelicSwap")?.Display ?? "没找到");
			var rswapFilters = EffectCatalog.RelicSwapFilters();
			Check("源遗物那一栏有「不限 / 只换初始遗物 / 指定某一类本体遗物」三档",
				rswapFilters.Count >= 3 && rswapFilters[0].Id == "" && rswapFilters[1].Id == EffectCatalog.RelicFilterStarter
				&& rswapFilters.Any((SpawnFilterOption f) => f.Id.StartsWith(EffectCatalog.RelicFilterPrefix, StringComparison.Ordinal)),
				$"{rswapFilters.Count} 档");
			Check("「只换初始遗物」那一档的中文说明写对了",
				EffectCatalog.RelicSwapFilterZh(EffectCatalog.RelicFilterStarter) == "初始遗物", "初始遗物");
			CharacterProfile rswapProf = ProfileFactory.Sample();
			rswapProf.Relics.Clear();
			var starterRelic = new RelicSpec { Name = "起始血瓶", ClassName = "UiSwapStarter", Rarity = "Starter", IsStartingRelic = true, Trigger = "CombatStart", InRelicPool = true };
			var toothRelic = new RelicSpec { Name = "欧洛巴斯之触·改", ClassName = "UiSwapTooth", Rarity = "Rare", Trigger = "Obtained", InRelicPool = true };
			var rswapEffect = new EffectSpec { Kind = "AncientRelicSwap", SpawnFilter = EffectCatalog.RelicFilterStarter, SpawnCardId = "BlackBlood" };
			toothRelic.Effects.Clear();
			toothRelic.Effects.Add(rswapEffect);
			rswapProf.Relics.Add(starterRelic);
			rswapProf.Relics.Add(toothRelic);
			string rswapSrc = CSharpCodeGen.RelicSource(rswapProf, toothRelic, 1);
			Check("生成里按「只换初始遗物」筛（本体欧洛巴斯之触的判据 r.Rarity == RelicRarity.Starter）",
				rswapSrc.Contains("base.Owner.Relics.FirstOrDefault(r => r.Rarity == RelicRarity.Starter)"), "筛法对");
			Check("生成里用 RelicCmd.Replace 做**原地**替换（位置不变，不是先删再加）",
				rswapSrc.Contains("await RelicCmd.Replace(__fgSwapSrc, __fgSwapTo);"), "Replace 在");
			Check("目标遗物是本体遗物时直接 ModelDb.Relic<T>().ToMutable()",
				rswapSrc.Contains("ModelDb.Relic<BlackBlood>().ToMutable()"), "构造对");
			Check("没匹配到符合条件的遗物时打一行日志（不静默）",
				rswapSrc.Contains("身上没有符合条件的遗物"), "有日志");
			Check("「转化为先古遗物」挂在「获得时」→ 校验器不报这条错",
				!ProfileValidator.Validate(rswapProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("转化为先古遗物")),
				string.Join(" / ", ProfileValidator.Validate(rswapProf).Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message)));
			var rswapWrong = new RelicSpec { Name = "错时机", ClassName = "UiSwapWrong", Rarity = "Rare", Trigger = "CombatStart", InRelicPool = true };
			var rswapWrongEffect = new EffectSpec { Kind = "AncientRelicSwap", SpawnFilter = "", SpawnCardId = "BlackBlood" };
			rswapWrong.Effects.Clear();
			rswapWrong.Effects.Add(rswapWrongEffect);
			CharacterProfile rswapWrongProf = ProfileFactory.Sample();
			rswapWrongProf.Relics.Clear();
			rswapWrongProf.Relics.Add(rswapWrong);
			Check("「转化为先古遗物」挂在别的触发时机 → 校验器报**错误**",
				ProfileValidator.Validate(rswapWrongProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只允许挂在「获得时」")), "拦住了");
			var rswapNoTarget = new EffectSpec { Kind = "AncientRelicSwap", SpawnFilter = "" };
			rswapWrong.Effects.Clear();
			rswapWrong.Effects.Add(rswapNoTarget);
			rswapWrong.Trigger = "Obtained";
			Check("没选目标遗物 → 校验器报错",
				ProfileValidator.Validate(rswapWrongProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("还没选「目标遗物」")), "报错了");
			// 界面：目标遗物那一栏的候选（自己的遗物 + 本体遗物）"
			CharacterProfile rswapSaved = _profile;
			_profile = rswapProf;
			Raise("Profile");
			Check("界面上「目标遗物」候选里既有自己的遗物、也有本体遗物（不会再空着）",
				RelicSwapTargets.Any((PowerEntry x) => x.Id == "UiSwapStarter") && RelicSwapTargets.Any((PowerEntry x) => x.Id == "BlackBlood"),
				$"{RelicSwapTargets.Count} 条候选");
			_profile = rswapSaved;
			Raise("Profile");
			UpdateLayout();
		}

		// ===== 卡牌页 UI：两个「自动填入」按钮真的能把文案填进框里（用户要求） ====
		{
			var prevSel = CardList.SelectedItem as CardSpec;
			var demo = new CardSpec { Name = "自动填入自检卡", ClassName = "UiAutoFillDemo", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			demo.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 7m, TargetSide = "Enemy" });
			Profile.Cards.Add(demo);
			SelectTabRoot("卡牌");
			CardList.SelectedItem = demo;
			UpdateLayout();
			DependencyObject cardRoot = SelectTabRoot("卡牌");
			var descBoxes = new List<TextBox>();
			CollectTextBoxes(cardRoot, descBoxes);
			var baseBox = descBoxes.FirstOrDefault(b => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path == "CustomDescription");
			var upBox = descBoxes.FirstOrDefault(b => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path == "UpgradedCustomDescription");
			Check("卡牌页有「自定义描述」和「升级后的自定义描述」两个框，并且分别绑到两个字段",
				baseBox is not null && upBox is not null && !ReferenceEquals(baseBox, upBox),
				$"基础={baseBox?.Name ?? "(没找到 "} 升级后 {upBox?.Name ?? "(没找到 "}");
			Button? fillBase = FindButtonByContent("自动填入", cardRoot);
			Button? fillUp = FindButtonByContent("自动填入（升级后）", cardRoot);
			Check("自定义描述旁边有「自动填入」和「自动填入（升级后）」两个按钮",
				fillBase is not null && fillUp is not null, $"{fillBase?.Content ?? "(没有)"} / {fillUp?.Content ?? "(没有)"}");
			if (baseBox is not null && upBox is not null && fillBase is not null && fillUp is not null)
			{
				// 走真实的点击处理：把 DataContext 设成这张卡（模板里的按钮就是这么绑的）"
				fillBase.Tag = baseBox;
				fillBase.DataContext = demo;
				baseBox.DataContext = demo;
				ClickButtonByContent("自动填入", cardRoot);
				UpdateLayout();
				Check("点「自动填入」→ 描述框里是自动生成的那段（可以接着改）",
					baseBox.Text.Contains("造成") && baseBox.Text.Contains("{Damage:diff()}"),
					baseBox.Text.Replace("\n", " ⏎ "));
				Check("点「自动填入」顺手勾上「替换掉自动生成的描述」（不勾的话卡面会印两遍）",
					demo.CustomDescriptionReplaces, $"替换={demo.CustomDescriptionReplaces}");
				fillUp.Tag = upBox;
				fillUp.DataContext = demo;
				upBox.DataContext = demo;
				ClickButtonByContent("自动填入（升级后）", cardRoot);
				UpdateLayout();
				Check("点「自动填入（升级后）」→ 升级后那个框也有内容了（普通卡和升级前一样，改一改就能让升级后换句话）",
					upBox.Text.Length > 0, upBox.Text.Replace("\n", " ⏎ "));
				Check("两个框填完 → 生成的描述是 {IfUpgraded:show:升级后|没升级}（只有一段一样时才不包）",
					LocalizationGen.CardsJson(Profile).Contains("IfUpgraded:show:") || upBox.Text == baseBox.Text,
					upBox.Text == baseBox.Text ? "两段一样（不包也对）" : "包起来了");
			}
			Profile.Cards.Remove(demo);
			if (prevSel is not null) CardList.SelectedItem = prevSel;
			UpdateLayout();
		}

		// ===== 牌堆实时张数（V0.2.130：用户要求整块删掉「卡面显示牌堆张数」）=====
		// 老版本这里钉着 9 条断言（三个占位符 / 不带 :diff() / 辅助文件 / 三个变量名 / 现取 /
		// 不在战斗返回 0 / 勾了声明三行 / 没勾一个字符不多 / 自定义描述里原样写进卡面）。
		// 功能删掉之后那些断言全部失效 → 改成「功能真的没了」这一组（逐条对应）。
		{
			Check("卡牌属性面板上不再有「卡面显示牌堆张数」勾选框",
				!TextsIn(CardDetail).Any((string t) => t.Contains("卡面显示牌堆张数")), "没这个勾选框了");
			Check("CardSpec 上已经没有 ShowPileCounts 这个属性（模型层删干净）",
				typeof(CardSpec).GetProperty("ShowPileCounts") is null, "属性不存在");
			Check("CSharpCodeGen 上已经没有 PileCountHints（占位符表删干净）",
				typeof(CSharpCodeGen).GetProperty("PileCountHints") is null, "占位符表不存在");
			Check("ForgeGraphGen 上已经没有 PileCountSource / NeedsPileCountVars / PileCountFile（辅助类删干净）",
				typeof(ForgeGraphGen).GetMethod("PileCountSource") is null
				&& typeof(ForgeGraphGen).GetMethod("NeedsPileCountVars") is null
				&& typeof(ForgeGraphGen).GetField("PileCountFile") is null, "三个都不存在");
			Check("本工具自己的代码里不再有 ForgePileCountVar 这个类（生成端不再写它）",
				typeof(ForgeGraphGen).Assembly.GetTypes().All((Type t) => t.Name != "ForgePileCountVar"), "类型不存在");
			// 老存档兼容：JSON 里带 "ShowPileCounts": true 也要能读进来（不报错、字段被忽略）
			string legacyJson = Path.Combine(Path.GetTempPath(), "forge_uicheck_pilecount_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
			CardSpec? pileLegacy = null;
			try
			{
				const string legacyText = """
{
  "ModId": "PileLegacyMod",
  "CharacterClass": "PileLegacy",
  "DisplayName": "旧存档",
  "Cards": [
    { "Name": "旧卡", "ClassName": "UiPileLegacy", "CardType": "Attack", "Rarity": "Common", "Cost": 1, "ShowPileCounts": true }
  ]
}
""";
				File.WriteAllText(legacyJson, legacyText, new System.Text.UTF8Encoding(false));
				pileLegacy = ProfileFactory.Load(legacyJson).Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiPileLegacy");
			}
			finally { try { if (File.Exists(legacyJson)) File.Delete(legacyJson); } catch { } }
			Check("老存档里那个字段（\"ShowPileCounts\": true）读进来**不报错**、被直接忽略",
				pileLegacy is not null, pileLegacy is null ? "没读回来（加载报错了）" : $"读回来「{pileLegacy.Name}」（{pileLegacy.ClassName}），旧字段被忽略");
			// 真的生成一次：工程里不许再有 cs/ForgePileCountVar.cs（老版本勾过开关才会写这个文件）
			CharacterProfile pileProf = ProfileFactory.Sample();
			pileProf.Cards[0].CustomDescription = "抽牌堆还有 {DrawPile} 张";   // 老存档里写过这个占位符也照旧不生成变量
			string pileRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_pilecount_gen_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				pileProf.Paths.OutputDir = pileRoot;
				pileProf.Paths.VanillaProject = Profile.Paths.VanillaProject;
				pileProf.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var pileGen = ModGenerator.Generate(pileProf);
				Check("生成出来的工程里不再有 cs/ForgePileCountVar.cs（连老存档写过占位符也一样）",
					pileGen.Success && !File.Exists(Path.Combine(pileGen.ProjectRoot, "cs", "ForgePileCountVar.cs"))
					&& !Directory.GetFiles(pileGen.ProjectRoot, "*ForgePileCountVar*", SearchOption.AllDirectories).Any(),
					pileGen.Success ? "没有这个文件" : (pileGen.Issues.FirstOrDefault((ValidationIssue i) => i.IsError)?.Message ?? "生成失败"));
				Check("生成出来的卡牌源码里一个 ForgePileCountVar 都没有",
					!CSharpCodeGen.CardSource(pileProf, pileProf.Cards[0], 0).Contains("ForgePileCountVar"), "干净");
			}
			finally
			{
				try { if (Directory.Exists(pileRoot)) Directory.Delete(pileRoot, true); } catch { }
			}
			Check("「填入参数…」菜单里不再列出 {DrawPile} / {DiscardPile} / {ExhaustPile}",
				CSharpCodeGen.ParamHints(pileProf.Cards[0].Effects, true).All((h) => !h.Token.Contains("Pile")
					&& !h.Token.Contains("DrawPile") && !h.Token.Contains("DiscardPile") && !h.Token.Contains("ExhaustPile")),
				string.Join(" / ", CSharpCodeGen.ParamHints(pileProf.Cards[0].Effects, true).Select((h) => h.Token)));
		}

		// ===== 卡牌页：左侧序号 + 拖动换位置 + 按序号自动英文类名（用户要求第 1 条，V0.2.130）=====
		// 口径按用户拍板 Q5 = A：序号 = **列表里全部行**（含本体卡 / 初始打击防御），序号是位置号、不跟随卡牌。
		// 自动英文类名跟这个号走：清掉以前工具自动生成的类名 → 按当前序号重拼；手填的一个字不动；
		// 没填的保持留空只记序号（判据照遗物 / 药水那套「按名字形状认」，见 Naming.IsAutoCardClassName）。
		{
			// ---- 纯模型逻辑：自动类名跟序号走 ----
			{
				var rn = Naming.From(ProfileFactory.Sample());
				var rnProfile = ProfileFactory.Sample();
				rnProfile.Curses.Clear();
				rnProfile.AncientCards.Clear();
				rnProfile.Cards.Clear();
				var rnHand = new CardSpec { Name = "手填甲", ClassName = "MyOwnSlash", CardType = "Attack", Rarity = "Common", Cost = 1 };
				var rnEmpty = new CardSpec { Name = "留空乙", ClassName = "", CardType = "Attack", Rarity = "Common", Cost = 1 };
				var rnAuto = new CardSpec { Name = "自动丙", ClassName = rn.CharClass + "Card9", CardType = "Attack", Rarity = "Common", Cost = 1 };
				var rnForeign = new CardSpec { Name = "别家丁", ClassName = "SomebodyElseCard5", CardType = "Attack", Rarity = "Common", Cost = 1 };
				rnProfile.Cards.Add(rnHand);
				rnProfile.Cards.Add(rnEmpty);
				rnProfile.Cards.Add(rnAuto);
				rnProfile.Cards.Add(rnForeign);
				// 用户上传的卡面是按**类名**存的（ArtSpec.CardPortraits）—— 改号不能把上传的图弄丢
				rnProfile.Art.CardPortraits[rn.CharClass + "Card9"] = @"D:\fake\probe_art.png";
				// 这里走**生成端真正走的那一步**（NameStabilizer.RenumberCardNames：改号 + 把引用 / 卡面一起搬）
				int rnMoved = NameStabilizer.RenumberCardNames(rnProfile);
				Check("改号时顺手把「上传的卡面」也搬到新类名上（不然卡面会静悄悄退回占位图）",
					rnProfile.Art.CardPortraits.TryGetValue(rn.CharClass + "Card3", out string? movedArt)
					&& movedArt == @"D:\fake\probe_art.png"
					&& !rnProfile.Art.CardPortraits.ContainsKey(rn.CharClass + "Card9"),
					"CardPortraits = " + string.Join(" / ", rnProfile.Art.CardPortraits.Select(kv => kv.Key + "→" + kv.Value)));
				Check("卡牌自动类名跟序号走：手填的一个字不动、留空的保持留空只记序号、工具自动生成的按当前序号重命名",
					rnHand.ClassName == "MyOwnSlash" && rnHand.LastAutoOrdinal == 0
					&& rnEmpty.ClassName == "" && rnEmpty.LastAutoOrdinal == 2
					&& rnAuto.ClassName == rn.CharClass + "Card3" && rnAuto.LastAutoOrdinal == 3
					&& rnForeign.ClassName == "SomebodyElseCard5",
					$"手填={rnHand.ClassName} / 留空='{rnEmpty.ClassName}':{rnEmpty.LastAutoOrdinal} / 自动={rnAuto.ClassName} / 别家={rnForeign.ClassName}（改了 {rnMoved} 处）");
				Check("卡牌自动名的编号只认**本角色类名**前缀（别的角色的 CardN 不会被当成我们的自动名）",
					rn.IsAutoCardClassName(rn.CharClass + "Card1") && !rn.IsAutoCardClassName("SomebodyElseCard5")
					&& !rn.IsAutoCardClassName(rn.CharClass + "Card0") && !rn.IsAutoCardClassName(rn.CharClass + "CardX"),
					rn.CharClass + "Card1=true / SomebodyElseCard5=false / Card0=false / CardX=false");
				// 幂等：再跑两遍一个字节都不动
				string rnSig = string.Join("|", rnProfile.Cards.Select(c => c.Name + ":" + c.ClassName + ":" + c.LastAutoOrdinal));
				rn.RenumberCardClassNames(rnProfile.AllCards);
				rn.RenumberCardClassNames(rnProfile.AllCards);
				Check("卡牌自动类名重编号是**幂等**的（连跑三遍：类名 / 序号一个字节都不变）",
					string.Join("|", rnProfile.Cards.Select(c => c.Name + ":" + c.ClassName + ":" + c.LastAutoOrdinal)) == rnSig,
					rnSig);
				Check("「拖到第 3 位、类名早就正好是 Card3」也把 LastAutoOrdinal 同步好（界面小字不写上一个序号）",
					rnAuto.LastAutoOrdinal == 3, rnAuto.LastAutoOrdinal.ToString());
				// 拖到别的序号之后：自动名跟着换（用户要的链路）
				rnProfile.Cards.Move(2, 0);                       // 「自动丙」从第 3 位拖到第 1 位
				rn.RenumberCardClassNames(rnProfile.AllCards);
				Check("把自动命名的卡拖到第 1 位后重新生成 → 类名变成 <角色类名>Card1（用户要的链路）",
					rnAuto.ClassName == rn.CharClass + "Card1" && rnHand.ClassName == "MyOwnSlash"
					&& rnEmpty.ClassName == "" && rnEmpty.LastAutoOrdinal == 3,
					$"自动={rnAuto.ClassName} / 手填={rnHand.ClassName} / 留空序号={rnEmpty.LastAutoOrdinal}");
				// 「删掉英文类名 → 重新生成」：留空的保持留空，但记的序号是当前的
				rnAuto.ClassName = "";
				rn.RenumberCardClassNames(rnProfile.AllCards);
				Check("删掉英文类名后再生成 → 类名保持留空（生成端按当前序号拼）、只记序号",
					rnAuto.ClassName == "" && rnAuto.LastAutoOrdinal == 1
					&& rn.CardClassName(rnProfile, rnAuto) == rn.CharClass + "Card1",
					$"留空 / 序号={rnAuto.LastAutoOrdinal} / 生成端会写 {rn.CardClassName(rnProfile, rnAuto)}");
			}
			// ---- 用户原话的验收场景（sparkle 存档「面具虚影」排第三 → SparkleCard3）----
			{
				var sparkle = new CharacterProfile { ModId = "SparkleMod", CharacterClass = "Sparkle", DisplayName = "星光" };
				sparkle.Cards.Add(new CardSpec { Name = "序幕", ClassName = "SparkleDance", CardType = "Attack", Rarity = "Common", Cost = 1 });
				sparkle.Cards.Add(new CardSpec { Name = "假面", ClassName = "SparkleWard", CardType = "Skill", Rarity = "Common", Cost = 1 });
				var mask = new CardSpec { Name = "面具虚影", ClassName = "", CardType = "Skill", Rarity = "Common", Cost = 1 };
				sparkle.Cards.Add(mask);
				Check("用户原话的验收场景：面具虚影排第 3 行、英文类名留空 → 生成 SparkleCard3",
					Naming.From(sparkle).CardClassName(sparkle, mask) == "SparkleCard3",
					Naming.From(sparkle).CardClassName(sparkle, mask));
				// 老存档里的自动名（SparkleCard7）也要按新序号清掉重拼
				var sparkle2 = new CharacterProfile { ModId = "SparkleMod", CharacterClass = "Sparkle", DisplayName = "星光" };
				sparkle2.Cards.Add(new CardSpec { Name = "序幕", ClassName = "SparkleDance", CardType = "Attack", Rarity = "Common", Cost = 1 });
				sparkle2.Cards.Add(new CardSpec { Name = "假面", ClassName = "SparkleWard", CardType = "Skill", Rarity = "Common", Cost = 1 });
				var mask2 = new CardSpec { Name = "面具虚影", ClassName = "SparkleCard7", CardType = "Skill", Rarity = "Common", Cost = 1 };
				sparkle2.Cards.Add(mask2);
				int sparkleMoved = Naming.From(sparkle2).RenumberCardClassNames(sparkle2.AllCards);
				Check("老存档里的自动名（SparkleCard7）排到第 3 行 → 自动清掉、按当前序号重拼成 SparkleCard3",
					mask2.ClassName == "SparkleCard3" && sparkleMoved == 1, $"{mask2.ClassName}（改了 {sparkleMoved} 处）");
				Check("（对照）手填的 SparkleDance / SparkleWard 一动不动",
					sparkle2.Cards[0].ClassName == "SparkleDance" && sparkle2.Cards[1].ClassName == "SparkleWard", "没动");
			}
			// ---- 校验器：手打的「像自动编号但序号对不上」要提示（不许静默）----
			{
				var rnWarn = ProfileFactory.Sample();
				rnWarn.Cards.Clear();
				rnWarn.Curses.Clear();
				rnWarn.AncientCards.Clear();
				rnWarn.Cards.Add(new CardSpec { Name = "像自动名", ClassName = "SevenCard7", CardType = "Attack", Rarity = "Common", Cost = 1 });
				Check("校验器：手填的卡牌类名长得像自动编号但序号对不上 → 提示「下次生成会改名」（不许静默）",
					ProfileValidator.Validate(rnWarn).Any(i => i.Level == "提示" && i.Message.Contains("自动生成的编号")),
					ProfileValidator.Validate(rnWarn).FirstOrDefault(i => i.Message.Contains("自动生成的编号"))?.Message ?? "(没报)");
				rnWarn.Cards[0].ClassName = "SevenSlash";
				Check("（对照）手填一个不像自动编号的名字 → 不报（别刷没用的提示）",
					!ProfileValidator.Validate(rnWarn).Any(i => i.Message.Contains("自动生成的编号")), "没报");
			}
			// ---- 界面：序号列 / 可拖动 / 拖动真的换位置 ----
			{
				List<string> VisibleCardOrdinals()
				{
					UpdateLayout();
					List<TextBlock> blocks = new List<TextBlock>();
					CollectTextBlocks(CardList, blocks);
					return blocks.Select(t => t.Text ?? "")
						.Where(t => System.Text.RegularExpressions.Regex.IsMatch(t, @"^\d+\.$"))
						.ToList();
				}
				List<CardSpec> keptCards = Profile.Cards.ToList();     // 这一轮的临时改动最后原样还回去
				CardSpec? keptCardSel = CardUiSelection;
				try
				{
					SelectTabRoot("卡牌");
					Check("卡牌列表不再用 DisplayMemberPath（改成带序号列的模板）",
						CardList.DisplayMemberPath is null && CardList.ItemTemplate is not null,
						(CardList.DisplayMemberPath ?? "(null)") + " / " + (CardList.ItemTemplate is null ? "无模板" : "有模板"));
					Check("卡牌列表允许拖放（AllowDrop=True，四个拖放事件都接上了）",
						CardList.AllowDrop, "AllowDrop=" + CardList.AllowDrop);
					Check("ItemsSource 绑的是界面镜像集合 CardRows（真卡 + 末尾空槽行）；真卡集合 Profile.Cards 仍是唯一事实来源",
						ReferenceEquals(CardList.ItemsSource, CardRows) && !ReferenceEquals(CardList.ItemsSource, Profile.Cards)
						&& CardRows.Take(Profile.Cards.Count).SequenceEqual<ISlotRow>(Profile.Cards)
						&& CardRows.Skip(Profile.Cards.Count).All(r => r.IsPlaceholder),
						$"镜像 {CardRows.Count} 行 = 真卡 {Profile.Cards.Count} + 空槽 {CardRows.Count - Profile.Cards.Count}");
					// 序号从 1 连续到 N（含本体卡 / 初始打击防御）
					UpdateLayout();
					string ordAll = string.Join(",", Profile.Cards.Select(c => c.OrdinalText));
					Check("左侧序号从上到下就是 1..N（口径 = 列表里全部行，含本体卡 / 初始打击防御）",
						Profile.Cards.Select(c => c.Ordinal).SequenceEqual(Enumerable.Range(1, Profile.Cards.Count))
						&& ordAll == string.Join(",", Enumerable.Range(1, Profile.Cards.Count).Select(i => i + ".")),
						$"共 {Profile.Cards.Count} 张 / 序号 {ordAll}");
					List<string> visibleOrds = VisibleCardOrdinals();
					Check("界面上真画出了「N.」序号（序号在卡牌名最左侧一列），而且是从 1 开始连续的下标",
						visibleOrds.Count >= 3
						&& visibleOrds.SequenceEqual(Enumerable.Range(1, visibleOrds.Count).Select(i => i + ".")),
						$"看到 {visibleOrds.Count} 个（{string.Join(",", visibleOrds)}）/ 共 {Profile.Cards.Count} 张"
						+ "（列表虚拟化：只画出可见的那几行，所以看到的不一定等于总张数）");
					Check("打击 / 防御（本体卡）也占号：它们就是第 1、2 行",
						Profile.Cards.Count >= 2 && Profile.Cards[0].IsStartingBasic && Profile.Cards[0].Ordinal == 1
						&& Profile.Cards[1].Ordinal == 2,
						$"第 1 行 {Profile.Cards[0].Name}（{Profile.Cards[0].ClassName}），第 2 行 {Profile.Cards[1].Name}");
					// 拖动：第 1 张拖到第 3 张的位置 → 真集合顺序变、序号仍 1..N 连续
					string cardsBefore = string.Join("→", Profile.Cards.Select(c => c.Name));
					CardSpec draggedCard = Profile.Cards[0];
					CardList.SelectedItem = draggedCard;
					UpdateLayout();
					CardSpec overCard = Profile.Cards[2];
					bool cardMoved = MoveCardTo(draggedCard, overCard, 2);
					UpdateLayout();
					Check("拖动卡牌项换位置：Profile.Cards 顺序真的变、序号仍是 1..N 连续、选中项跟着被拖的那张",
						cardMoved && ReferenceEquals(Profile.Cards[2], draggedCard)
						&& Profile.Cards.Select(c => c.Ordinal).SequenceEqual(Enumerable.Range(1, Profile.Cards.Count))
						&& ReferenceEquals(CardUiSelection, draggedCard),
						$"{cardsBefore} → " + string.Join("→", Profile.Cards.Select(c => c.Name))
						+ $" ／ 序号 {string.Join(",", Profile.Cards.Select(c => c.OrdinalText))}");
					// 拖到列表最后一行的位置（over = null 时按行号算落点）
					CardSpec lastDragged = Profile.Cards[0];
					int lastDropRow = CardRows.Count - 1;
					bool movedToEnd = MoveCardTo(lastDragged, null, lastDropRow);
					UpdateLayout();
					Check("拖到列表末尾（落点没有卡、只给行号）：照样真换位置、序号仍 1..N 连续",
						movedToEnd && ReferenceEquals(Profile.Cards[Profile.Cards.Count - 1], lastDragged)
						&& Profile.Cards.Select(c => c.Ordinal).SequenceEqual(Enumerable.Range(1, Profile.Cards.Count)),
						string.Join("→", Profile.Cards.Select(c => c.Name)));
					// 行命中：屏幕上点得到某一行、拿到的是那一行的卡
					int probeRow = Math.Min(2, Profile.Cards.Count - 1);
					DependencyObject? rowC = CardList.ItemContainerGenerator.ContainerFromIndex(probeRow) as DependencyObject;
					string rowDetail = "(没有容器)";
					bool rowHitOk = false;
					if (rowC is FrameworkElement rowCFe)
					{
						Point offset = rowCFe.TransformToVisual(CardList).Transform(new Point(0, 0));
						var at = CardRowAtPoint(new Point(offset.X + rowCFe.ActualWidth * 0.5, offset.Y + rowCFe.ActualHeight * 0.5));
						rowHitOk = at.Index == probeRow && ReferenceEquals(at.Card, Profile.Cards[probeRow]);
						rowDetail = $"行{at.Index}/{at.Card?.Name ?? "无卡"}";
					}
					Check("CardRowAtPoint 能按行号认出鼠标下面是哪张卡（拖动起手 / 落点都用它）",
						rowHitOk, rowDetail);
					// 拖动本身不改卡的任何字段（只改顺序）
					Check("拖动只改顺序，不改卡的任何字段（名称 / 类名 / 费用一个都没动）",
						Profile.Cards.All(c => c.ClassName is not null) && Profile.Cards.Count == keptCards.Count, "字段没动");
				}
				finally
				{
					// 原样还回去（顺序 + 选中项），免得影响后面的断言
					Profile.Cards.Clear();
					foreach (CardSpec c in keptCards) Profile.Cards.Add(c);
					RefreshCardOrdinals();
					if (keptCardSel is not null) CardList.SelectedItem = keptCardSel;
					SyncDetail();
					UpdateLayout();
				}
			}

			// ===== 卡牌页：**每 5 个一块 + 空槽带灰色序号**（V0.2.140，用户对 V0.2.130 那次的更正）=====
			// 用户原话：「不是说卡牌左侧的序号做的像遗物一样，五个五个列，直接显示出来，比如只有一张卡时，
			// 有1-5序号，当有6张卡时，出现6到10序号」。
			// 照 V0.2.125 遗物页 / V0.2.127 药水页那套**逐条**重做（同一份实现 SlotRowMirror<CardSpec>，
			// 三个卡牌列表页共用），这里把用户要求的三档数字 + 空槽的每一条性质都钉成断言。
			{
				List<CardSpec> slotKeptCards = Profile.Cards.ToList();
				CardSpec? slotKeptSel = CardUiSelection;
				// ⚠ 这一段要看「实化出来的行」（颜色 / 命中测试），而列表默认虚拟化 —— 屏幕高度只放得下
				// 前几行，第 7 行之后的空槽根本不会实化，断言就会白 FAIL。所以这一段**临时关掉虚拟化**，
				// 让所有行都实化；跑完在 finally 里原样打开。
				bool slotVirtWas = VirtualizingPanel.GetIsVirtualizing(CardList);
				try
				{
					VirtualizingPanel.SetIsVirtualizing(CardList, false);
					SelectTabRoot("卡牌");
					// 造 N 张探针卡（自动类名留空 = 走「自动编号」那条路，顺便验序号→类名对得上）
					List<CardSpec> MakeProbeCards(int n)
					{
						var made = new List<CardSpec>();
						for (int i = 0; i < n; i++)
						{
							made.Add(new CardSpec
							{
								Name = "槽" + (i + 1),
								ClassName = "",
								CardType = "Attack",
								Rarity = "Common",
								Cost = 1,
								InCardPool = true,
							});
						}
						return made;
					}
					void SetProbeCards(int n)
					{
						Profile.Cards.Clear();
						foreach (CardSpec c in MakeProbeCards(n)) Profile.Cards.Add(c);
						RefreshCardOrdinals();
						SyncDetail();
						UpdateLayout();
					}
					// 界面上真画出来的序号（列表虚拟化 → 只数已实化的行）
					(int Real, int Slot, int OrdinalTexts, string Colors) OrdinalEvidence()
					{
						UpdateLayout();
						var blocks = new List<TextBlock>();
						CollectTextBlocks(CardList, blocks);
						var infos = blocks
							.Where(t => (t.Text ?? "").Length is 2 or 3 && (t.Text ?? "").EndsWith(".") && char.IsDigit((t.Text ?? "x")[0]))
							.Select(t => (Text: t.Text!, Color: (t.Foreground as SolidColorBrush)?.Color.ToString() ?? "(不是纯色)", Visible: t.IsVisible))
							.ToList();
						int real = infos.Count(o => Profile.Cards.Any(c => c.OrdinalText == o.Text));
						int slot = infos.Count(o => CardRows.Any(r => r.IsPlaceholder && r.OrdinalText == o.Text));
						return (real, slot, infos.Count,
							string.Join(" / ", infos.Select(o => o.Text + "=" + o.Color + (o.Visible ? "" : "(不可见)"))));
					}

					// ---- ① 1 张卡 → 显示 1~5 行（2~5 是空槽），序号也画出来了 ----
					SetProbeCards(1);
					string ord1 = string.Join(",", CardRows.Select(r => r.OrdinalText));
					Check("（空槽 ①）1 张卡 → 列表显示 1~5 行，2~5 是空槽（用户原话「只有一张卡时，有1-5序号」）",
						CardRows.Count == 5 && CardRows.Count == CardSlotRowCount(1)
						&& ord1 == "1.,2.,3.,4.,5."
						&& CardRows.Take(1).All(r => !r.IsPlaceholder) && CardRows.Skip(1).All(r => r.IsPlaceholder)
						&& CardRows.Count == 5 && Profile.Cards.Count == 1,
						$"行 {CardRows.Count} / 序号 {ord1} / 列表 Items {CardList.Items.Count} / 真卡 {Profile.Cards.Count}"
						+ " / 名册[" + string.Join(" | ", CardRows.Select(r => r is CardSpec cc ? "卡:" + cc.Name + ":" + cc.Ordinal : "空槽:" + r.OrdinalText)) + "]");
					Check("（空槽 ①）界面上真画出了 5 个「N.」序号（不是只算在集合里）",
						OrdinalEvidence().OrdinalTexts == 5, $"看到 {OrdinalEvidence().OrdinalTexts} 个");
					// 空槽行不能被当成卡选中：点它 → 选中项不是 CardSpec、右栏还停在原来那张、卡一个字段都没被改
					CardList.SelectedItem = Profile.Cards[0];
					UpdateLayout();
					string dump1 = string.Join(" | ", Profile.Cards.Select(c => c.Name + ":" + c.Ordinal + ":" + c.ClassName));
					CardSpec? selBeforeSlot = CardUiSelection;
					CardList.SelectedItem = CardRows[2];     // 第 3 行 = 空槽
					UpdateLayout();
					Check("（空槽 ①）点空槽行：选中项不是 CardSpec / 当前选中的真卡没变 / 真卡一个字段都没被改",
						CardList.SelectedItem is not CardSpec && CardList.SelectedItem is ISlotRow { IsPlaceholder: true }
						&& ReferenceEquals(CardUiSelection, selBeforeSlot) && CardUiSelection is not null
						&& string.Join(" | ", Profile.Cards.Select(c => c.Name + ":" + c.Ordinal + ":" + c.ClassName)) == dump1
						&& CardEmptyHint.Visibility != Visibility.Visible && CardDetail.Visibility == Visibility.Visible,
						$"SelectedItem={CardList.SelectedItem?.GetType().Name ?? "(null)"}（空槽行）/ CardUiSelection={CardUiSelection?.Name ?? "(null)"}"
						+ $" / 提示={CardEmptyHint.Visibility} / 详情={CardDetail.Visibility}");

					// ---- ② 6 张卡 → 显示 1~10 行（7~10 是空槽，用户原话「当有6张卡时，出现6到10序号」）----
					SetProbeCards(6);
					string ord6 = string.Join(",", CardRows.Select(r => r.OrdinalText));
					Check("（空槽 ②）6 张卡 → 列表显示 1~10 行，7~10 是空槽、序号 1..10 都在",
						CardRows.Count == 10 && CardRows.Count == CardSlotRowCount(6)
						&& ord6 == string.Join(",", Enumerable.Range(1, 10).Select(i => i + "."))
						&& CardRows.Take(6).All(r => !r.IsPlaceholder) && CardRows.Skip(6).All(r => r.IsPlaceholder)
						&& Profile.Cards.Count == 6,
						$"行 {CardRows.Count} / 序号 {ord6} / 真卡 {Profile.Cards.Count}");
					Check("（空槽 ②）卡片的序号仍然是「位置号」1..N 连续（空槽不占号）",
						Profile.Cards.Select((c, i) => c.Ordinal == i + 1 && c.OrdinalText == (i + 1) + ".").All(x => x),
						string.Join(",", Profile.Cards.Select(c => c.OrdinalText)));
					// 11 张 → 1~15（用户口径的第三档）
					SetProbeCards(11);
					Check("（空槽 ②）11 张卡 → 列表显示 1~15 行（序号 1..15、12~15 是空槽）",
						CardRows.Count == 15 && CardRows.Count == CardSlotRowCount(11)
						&& CardRows.Take(11).All(r => !r.IsPlaceholder) && CardRows.Skip(11).All(r => r.IsPlaceholder)
						&& string.Join(",", CardRows.Select(r => r.OrdinalText)) == string.Join(",", Enumerable.Range(1, 15).Select(i => i + ".")),
						$"行 {CardRows.Count} / 真卡 {Profile.Cards.Count} / 末尾 4 行={string.Join(",", CardRows.Skip(11).Select(r => r.OrdinalText))}");

					// ---- ③ 删回 5 张 → 行数回到 5（没有空槽）----
					SetProbeCards(6);
					Profile.Cards.RemoveAt(5);
					RefreshCardOrdinals();
					SyncDetail();
					UpdateLayout();
					string ord5 = string.Join(",", CardRows.Select(r => r.OrdinalText));
					Check("（空槽 ③）从 6 张删回 5 张 → 行数回到 5（序号 1~5，一个空槽都没有）",
						CardRows.Count == 5 && ord5 == "1.,2.,3.,4.,5." && CardRows.All(r => !r.IsPlaceholder)
						&& Profile.Cards.Count == 5,
						$"行 {CardRows.Count} / 序号 {ord5} / 真卡 {Profile.Cards.Count}");

					// ---- ④ 拖到空槽 → 顺序真变 + 序号仍 1..N 连续（空槽能当落点）----
					SetProbeCards(6);
					CardSpec slotDragged = Profile.Cards[0];
					CardList.SelectedItem = slotDragged;
					UpdateLayout();
					bool slotMoved = MoveCardTo(slotDragged, null, 8);      // 第 9 行是空槽 → 夹到末尾
					UpdateLayout();
					Check("（空槽 ④）拖一张卡到空槽那一行：Profile.Cards 顺序真的变、序号仍是 1..N 连续、空槽数不变",
						slotMoved && ReferenceEquals(Profile.Cards[5], slotDragged)
						&& Profile.Cards.Select((c, i) => c.Ordinal == i + 1 && c.OrdinalText == (i + 1) + ".").All(x => x)
						&& CardRows.Count == 10 && CardRows.Take(6).SequenceEqual<ISlotRow>(Profile.Cards)
						&& CardRows.Skip(6).All(r => r.IsPlaceholder),
						"拖到末尾 → " + string.Join(" → ", Profile.Cards.Select(c => c.Name))
						+ $" ／ 序号 {string.Join(",", Profile.Cards.Select(c => c.OrdinalText))} / 行 {CardRows.Count}");
					// 空槽那一行在屏幕上点得到，而且它不给出任何卡（CardRowAtPoint.Card = null）
					DependencyObject? slotRowC = CardList.ItemContainerGenerator.ContainerFromIndex(6) as DependencyObject;
					(CardSpec? SlotRowData, string SlotRowDetail) = (null, "(没有容器)");
					if (slotRowC is FrameworkElement slotRowCFe)
					{
						Point slotOffset = slotRowCFe.TransformToVisual(CardList).Transform(new Point(0, 0));
						int slotNullHits = 0;
						var slotGot = new List<string>();
						foreach ((double fx, double fy) in new (double, double)[] { (0.5, 0.5), (0.5, 0.25), (0.5, 0.75) })
						{
							var atSlot = CardRowAtPoint(new Point(slotOffset.X + slotRowCFe.ActualWidth * fx, slotOffset.Y + slotRowCFe.ActualHeight * fy));
							slotGot.Add($"({fx:F2},{fy:F2})→行{atSlot.Index}/{(atSlot.Card?.Name ?? "无卡")}");
							if (atSlot.Card is null) slotNullHits++;
						}
						SlotRowData = slotNullHits > 0 ? null : CardRowAtPoint(new Point(slotOffset.X + slotRowCFe.ActualWidth / 2, slotOffset.Y + slotRowCFe.ActualHeight / 2)).Card;
						SlotRowDetail = $"容器 {slotRowCFe.ActualWidth:F0}x{slotRowCFe.ActualHeight:F0}@{slotOffset.X:F0},{slotOffset.Y:F0} " + string.Join(" ", slotGot);
					}
					Check("（空槽 ④）空槽那一行在屏幕上点得到、而且它不给出任何卡（CardRowAtPoint.Card = null）",
						slotRowC is not null && SlotRowData is null && CardRows[6].IsPlaceholder,
						SlotRowDetail);

					// ---- ⑤ 空槽序号实测是**灰**的（真卡是 #FF1F4E79 加粗）----
					var slotColorEv = OrdinalEvidence();
					Check("（空槽 ⑤）空槽行的序号是灰的（#AAAAAA / 170,170,170）、真卡行不是灰的，而且行本身可见",
						slotColorEv.Real > 0 && slotColorEv.Slot > 0
						&& slotColorEv.Colors.Contains("AAAAAA", StringComparison.OrdinalIgnoreCase),
						$"实化序号 {slotColorEv.OrdinalTexts} 个（真卡 {slotColorEv.Real} / 空槽 {slotColorEv.Slot}）／ {slotColorEv.Colors}");
					var slotPh = CardRows[6] as SlotPlaceholder;
					Check("（空槽 ⑤）空槽行的「卡名」那一列是空的、ToolTip 是空（只有灰色序号）",
						slotPh is not null && slotPh.Display.Length == 0 && slotPh.RowTip is null
						&& !string.IsNullOrEmpty(CardRows[6].OrdinalText),
						$"Display='{slotPh?.Display}' RowTip={(CardRows[6].RowTip ?? "(null)")} Ordinal='{CardRows[6].OrdinalText}'");

					// ---- ⑥ 空槽不进全选 / Profile.Cards 里没有占位项 / 真生成一遍零「空槽」痕迹 ----
					CardList.SelectedItems.Clear();
					foreach (ISlotRow row in CardRows)
					{
						if (!row.IsPlaceholder) CardList.SelectedItems.Add(row);
					}
					Check("（空槽 ⑥）「全选」只选中真卡：SelectedItems 里一个空槽都没有",
						CardList.SelectedItems.Count == Profile.Cards.Count
						&& CardList.SelectedItems.OfType<SlotPlaceholder>().Count() == 0
						&& !CardList.SelectedItems.Cast<object>().Any(o => o is ISlotRow { IsPlaceholder: true }),
						$"选中 {CardList.SelectedItems.Count} / 真卡 {Profile.Cards.Count} / 行数 {CardRows.Count}");
					CardList.SelectedItems.Clear();
					Check("（空槽 ⑥）Profile.Cards / Curses / AncientCards 里没有 `SlotPlaceholder` 占位项（真集合是唯一事实来源）",
						!Profile.Cards.Any(c => c is SlotPlaceholder) && !Profile.Curses.Any(c => c is SlotPlaceholder)
						&& !Profile.AncientCards.Any(c => c is SlotPlaceholder)
						&& CardRows.OfType<SlotPlaceholder>().Count() > 0,
						$"{Profile.Cards.Count} / {Profile.Curses.Count} / {Profile.AncientCards.Count} 张（镜像里占位 {CardRows.OfType<SlotPlaceholder>().Count()} 个）");
					var slotCardProfA = ProfileFactory.Sample();
					slotCardProfA.Paths.OutputDir = Path.Combine(Path.GetTempPath(), "forge_cardslot_a_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					slotCardProfA.Paths.VanillaProject = Profile.Paths.VanillaProject;
					slotCardProfA.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var slotCardGen = ModGenerator.Generate(slotCardProfA);
					string slotCardFiles = slotCardGen.Success
						? string.Join("\n", Directory.GetFiles(slotCardGen.ProjectRoot, "*", SearchOption.AllDirectories)
							.Select(f => Path.GetRelativePath(slotCardGen.ProjectRoot, f).Replace('\\', '/'))
							.OrderBy(x => x, StringComparer.Ordinal))
						: "";
					Check("（空槽 ⑥）真生成一遍：文件清单 / 源码里一个「空槽 / SlotPlaceholder」痕迹都没有",
						slotCardGen.Success && slotCardFiles.Length > 0
						&& !slotCardFiles.Contains("SlotPlaceholder") && !slotCardFiles.Contains("空槽")
						&& !slotCardFiles.Contains("SlotRowMirror"),
						slotCardGen.Success ? $"生成 {slotCardFiles.Split('\n').Length} 个文件，一个「空槽」都没有" : string.Join(" / ", slotCardGen.Issues.Where(i => i.IsError).Take(3)));
					try { if (Directory.Exists(slotCardProfA.Paths.OutputDir)) Directory.Delete(slotCardProfA.Paths.OutputDir, true); } catch { }

					// ---- ⑦ 布局体检（照遗物 / 药水页：行宽 ≤ 列表宽 + 2px、没有 0 尺寸控件）----
					SetProbeCards(6);
					double cardMaxItemW = CardListActualMaxItemWidth();
					Check("（空槽 ⑦）卡牌列表的行没被排成超宽（行宽 <= 列表宽 + 2px）",
						Profile.Cards.Count == 0 || cardMaxItemW <= CardList.ActualWidth + 2.0,
						cardMaxItemW.ToString("F0") + " <= " + CardList.ActualWidth.ToString("F0"));
					Check("（空槽 ⑦）卡牌列表有正常尺寸（不是 0 尺寸）",
						CardList.ActualWidth > 10 && CardList.ActualHeight > 10,
						$"{CardList.ActualWidth:F0}x{CardList.ActualHeight:F0}");

					// ---- ⑧ 序号 → 自动类名仍然对得上（V0.2.137 口径不变：Card<序号>）----
					var namingNow = Naming.From(Profile);
					for (int i = 0; i < Profile.Cards.Count; i++)
					{
						CardSpec c = Profile.Cards[i];
						Check($"（空槽 ⑧）第 {i + 1} 张（留空类名）→ 生成端拼出 {namingNow.CharClass}Card{i + 1}",
							namingNow.CardClassName(Profile, c) == namingNow.CharClass + "Card" + (i + 1),
							$"序 {c.Ordinal} / 生成端 {namingNow.CardClassName(Profile, c)} / 手填='{c.ClassName}'");
					}
					string handName = "MyOwnSlashProbe";
					string autoName = namingNow.CharClass + "Card1";
					Profile.Cards[1].ClassName = handName;
					Profile.Cards[2].ClassName = autoName;
					RefreshCardOrdinals();
					SyncDetail();
					UpdateLayout();
					namingNow.RenumberCardClassNames(Profile.Cards);
					Check($"（空槽 ⑧）手填的类名一个字不动、工具自动名跟着序号走、留空的保持留空",
						Profile.Cards[1].ClassName == handName
						&& Profile.Cards[0].ClassName == "" && Profile.Cards[0].LastAutoOrdinal == 1
						&& Profile.Cards[2].ClassName == namingNow.CharClass + "Card3",
						$"手填={Profile.Cards[1].ClassName} / 留空='{Profile.Cards[0].ClassName}':{Profile.Cards[0].LastAutoOrdinal} / 自动={Profile.Cards[2].ClassName}");
					Check("（空槽 ⑧）顺序号仍然是「位置号」：自动名重编号是幂等的（连跑两遍一个字不变）",
						string.Join("|", Profile.Cards.Select(c => c.Name + ":" + c.ClassName + ":" + c.LastAutoOrdinal)) is string sig1
						&& namingNow.RenumberCardClassNames(Profile.Cards) >= 0
						&& namingNow.RenumberCardClassNames(Profile.Cards) >= 0
						&& string.Join("|", Profile.Cards.Select(c => c.Name + ":" + c.ClassName + ":" + c.LastAutoOrdinal)) == sig1,
						$"{Profile.Cards.Count} 张卡");
				}
				finally
				{
					// 虚拟化原样打开
					VirtualizingPanel.SetIsVirtualizing(CardList, slotVirtWas);
					// 原样还回去（真集合 + 选中项），免得影响后面的断言
					Profile.Cards.Clear();
					foreach (CardSpec c in slotKeptCards) Profile.Cards.Add(c);
					RefreshCardOrdinals();
					if (slotKeptSel is not null && Profile.Cards.Contains(slotKeptSel)) CardList.SelectedItem = slotKeptSel;
					SyncDetail();
					UpdateLayout();
				}
			}

			// ===== 诅咒卡 / 先古卡两页：同样是「每 5 个一块 + 空槽灰色序号」（V0.2.140，用户确认三页都做）=====
			{
				List<CardSpec> spKeptCurse = Profile.Curses.ToList();
				List<CardSpec> spKeptAncient = Profile.AncientCards.ToList();
				try
				{
					SelectTabRoot("诅咒 / 先古 / 状态");
					// 诅咒：2 张 → 5 行（3~5 空槽），序号用 Curse 前缀
					Profile.Curses.Clear();
					Profile.Curses.Add(new CardSpec { Name = "槽咒甲", ClassName = "", CardType = "Curse", Rarity = "Curse", Cost = -1, Unplayable = true });
					Profile.Curses.Add(new CardSpec { Name = "槽咒乙", ClassName = "", CardType = "Curse", Rarity = "Curse", Cost = -1, Unplayable = true });
					RefreshCardOrdinals();
					SyncDetail();
					UpdateLayout();
					string cOrd = string.Join(",", CurseRows.Select(r => r.OrdinalText));
					Check("（诅咒页）2 张诅咒 → 列表显示 1~5 行（3~5 是空槽），ItemsSource 是镜像 CurseRows",
						ReferenceEquals(CurseList.ItemsSource, CurseRows) && CurseRows.Count == 5 && cOrd == "1.,2.,3.,4.,5."
						&& CurseRows.Take(2).All(r => !r.IsPlaceholder) && CurseRows.Skip(2).All(r => r.IsPlaceholder)
						&& CurseRows.Count == 5,
						$"行 {CurseRows.Count} / 序号 {cOrd} / 列表 Items {CurseList.Items.Count}");
					var curseNaming = Naming.From(Profile);
					Check("（诅咒页）序号 → 自动类名仍按 Curse 前缀、各自从 1 数（V0.2.137 口径不变）",
						curseNaming.CardClassName(Profile, Profile.Curses[0]) == curseNaming.CharClass + "Curse1"
						&& curseNaming.CardClassName(Profile, Profile.Curses[1]) == curseNaming.CharClass + "Curse2"
						&& Profile.Curses[1].Ordinal == 2,
						$"{curseNaming.CardClassName(Profile, Profile.Curses[0])} / {curseNaming.CardClassName(Profile, Profile.Curses[1])}");
					// 加到 6 张 → 10 行
					for (int i = 3; i <= 6; i++)
						Profile.Curses.Add(new CardSpec { Name = "槽咒" + i, ClassName = "", CardType = "Curse", Rarity = "Curse", Cost = -1, Unplayable = true });
					RefreshCardOrdinals();
					SyncDetail();
					UpdateLayout();
					Check("（诅咒页）加到 6 张 → 列表显示 1~10 行（7~10 是空槽）",
						CurseRows.Count == 10 && CurseRows.Take(6).All(r => !r.IsPlaceholder) && CurseRows.Skip(6).All(r => r.IsPlaceholder)
						&& string.Join(",", CurseRows.Select(r => r.OrdinalText)) == string.Join(",", Enumerable.Range(1, 10).Select(i => i + ".")),
						$"行 {CurseRows.Count} / 序号 {string.Join(",", CurseRows.Select(r => r.OrdinalText))}");
					// 点诅咒那栏的空槽：不能被当成卡选中、右栏不清空、先古卡那栏的选中也不该被误清
					CurseList.SelectedItem = Profile.Curses[0];
					UpdateLayout();
					CardSpec? curseSelBefore = CurseUiSelection;
					CurseList.SelectedItem = CurseRows[7];
					UpdateLayout();
					Check("（诅咒页）点空槽行：选中项不是 CardSpec / CurseUiSelection 没变 / 右栏没被收起来",
						CurseList.SelectedItem is ISlotRow { IsPlaceholder: true } && ReferenceEquals(CurseUiSelection, curseSelBefore)
						&& CurseUiSelection is not null && HasCurseSelection,
						$"SelectedItem={CurseList.SelectedItem?.GetType().Name ?? "(null)"} / CurseUiSelection={CurseUiSelection?.Name ?? "(null)"}");
					// 诅咒那栏的空槽不进全选
					CurseList.SelectedItems.Clear();
					foreach (ISlotRow row in CurseRows)
					{
						if (!row.IsPlaceholder) CurseList.SelectedItems.Add(row);
					}
					Check("（诅咒页）「全选」只选中真诅咒：SelectedItems 里一个空槽都没有",
						CurseList.SelectedItems.Count == Profile.Curses.Count
						&& CurseList.SelectedItems.OfType<SlotPlaceholder>().Count() == 0,
						$"选中 {CurseList.SelectedItems.Count} / 真诅咒 {Profile.Curses.Count} / 行数 {CurseRows.Count}");
					CurseList.SelectedItems.Clear();

					// 先古卡：1 张 → 5 行，序号用 Ancient 前缀
					Profile.AncientCards.Clear();
					Profile.AncientCards.Add(new CardSpec { Name = "槽古甲", ClassName = "", CardType = "Skill", Rarity = "Ancient", Cost = 1 });
					RefreshCardOrdinals();
					SyncDetail();
					UpdateLayout();
					string aOrd = string.Join(",", AncientRows.Select(r => r.OrdinalText));
					Check("（先古卡页）1 张 → 列表显示 1~5 行（2~5 是空槽），ItemsSource 是镜像 AncientRows",
						ReferenceEquals(AncientCardList.ItemsSource, AncientRows) && AncientRows.Count == 5 && aOrd == "1.,2.,3.,4.,5."
						&& AncientRows.Take(1).All(r => !r.IsPlaceholder) && AncientRows.Skip(1).All(r => r.IsPlaceholder),
						$"行 {AncientRows.Count} / 序号 {aOrd}");
					Check("（先古卡页）序号 → 自动类名仍按 Ancient 前缀、从 1 数（V0.2.137 口径不变）",
						Naming.From(Profile).CardClassName(Profile, Profile.AncientCards[0]) == Naming.From(Profile).CharClass + "Ancient1",
						Naming.From(Profile).CardClassName(Profile, Profile.AncientCards[0]));
					// 三页各自独立：改其中一页的行数不影响另一页
					Check("（三页独立）诅咒 6 张 → 10 行、先古卡 1 张 → 5 行，互不影响；卡牌页也还是自己的行数",
						CurseRows.Count == 10 && AncientRows.Count == 5
						&& CardRows.Count == CardSlotRowCount(Profile.Cards.Count)
						&& !ReferenceEquals(CurseRows, AncientRows) && !ReferenceEquals(CardRows, CurseRows),
						$"卡牌 {CardRows.Count} / 诅咒 {CurseRows.Count} / 先古 {AncientRows.Count}");
					// 拖先古卡到它那栏的空槽 → 点得到那行、但它不给卡；也不能污染已选中的真先古卡
					AncientCardList.SelectedItem = Profile.AncientCards[0];
					UpdateLayout();
					Check("（先古卡页）空槽那一行在屏幕上点得到、而且它不给出任何卡（Ancient = null）",
						AncientSlotRowProbe(), "见上（空槽行可点但拿不到卡）");
					AncientCardList.SelectedItems.Clear();
					foreach (ISlotRow row in AncientRows)
					{
						if (!row.IsPlaceholder) AncientCardList.SelectedItems.Add(row);
					}
					Check("（先古卡页）「全选」只选中真先古卡：SelectedItems 里一个空槽都没有",
						AncientCardList.SelectedItems.Count == Profile.AncientCards.Count
						&& AncientCardList.SelectedItems.OfType<SlotPlaceholder>().Count() == 0,
						$"选中 {AncientCardList.SelectedItems.Count} / 真先古卡 {Profile.AncientCards.Count} / 行数 {AncientRows.Count}");
					AncientCardList.SelectedItems.Clear();
				}
				finally
				{
					Profile.Curses.Clear();
					foreach (CardSpec c in spKeptCurse) Profile.Curses.Add(c);
					Profile.AncientCards.Clear();
					foreach (CardSpec c in spKeptAncient) Profile.AncientCards.Add(c);
					RefreshCardOrdinals();
					SyncDetail();
					UpdateLayout();
				}
			}
		}

		// ===== 临时增益：两档撤法（本回合结束 / 下回合开始）=====
		{
			Check("「临时增益什么时候撤」有两档，默认是「本回合结束时撤」",
				TempPowerReverses.All.Count == 2 && TempPowerReverses.All[0].Id == ""
				&& new EffectSpec { Kind = "TempPower" }.TempPowerReverse == TempPowerReverses.TurnEnd,
				string.Join(" / ", TempPowerReverses.All.Select(o => o.Id + "=" + o.Display)));
			Check("只有「临时增益」才显示那一行（绑 IsTempPower）",
				new EffectSpec { Kind = "TempPower" }.IsTempPower && !new EffectSpec { Kind = "ApplyPower" }.IsTempPower, "只对它显示");
			Check("两档的类名不一样（回读才认得出是哪一档）",
				Naming.TempPowerSuffix(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower" })
					!= Naming.TempPowerSuffix(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", TempPowerReverse = TempPowerReverses.NextTurnStart }),
				Naming.TempPowerSuffix(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower" }) + " vs "
				+ Naming.TempPowerSuffix(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", TempPowerReverse = TempPowerReverses.NextTurnStart }));
			// 同一个状态的两档都要生成各自的类（去重键必须带上「哪一档」）
			CharacterProfile tpProf = ProfileFactory.Sample();
			tpProf.CustomPowers.Clear();
			tpProf.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "临时档状态", Enabled = true,
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = {
					new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", Amount = 5m, TargetSide = "Self", TempPowerReverse = TempPowerReverses.NextTurnStart },
					new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", Amount = 3m, TargetSide = "Self", TempPowerReverse = TempPowerReverses.TurnEnd },
				} } },
			});
			Check("同一个状态的两档会生成**两个**临时 Power 类（去重键带上了哪一档）",
				CSharpCodeGen.CollectTempPowerEffects(tpProf).Count() == 2,
				CSharpCodeGen.CollectTempPowerEffects(tpProf).Count() + " 个");
			string tpSrc = CSharpCodeGen.TempPowersSource(tpProf);
			Check("「下回合开始时才撤」那一档生成的是 AfterPlayerTurnStart（不是 AfterSideTurnEnd）",
				tpSrc.Contains("AfterPlayerTurnStart") && tpSrc.Contains("ForgeTempStrengthPowerNextTurn"), "下回合档");
			Check("默认那一档仍然生成 AfterSideTurnEnd（老存档行为一个字节都不变）",
				tpSrc.Contains("AfterSideTurnEnd"), "回合结束档");
			Check("卡面描述按档写（「回合结束时消失」/「下回合开始时消失」）",
				LocalizationGen.PowersJson(tpProf).Contains("回合结束时消失")
				&& LocalizationGen.PowersJson(tpProf).Contains("下回合开始时消失"), "两句都有");
			// 回读：从类名把「哪一档」也认回来"
			Check("从工程回读：类名带 NextTurn 的那一档能认出「下回合开始才撤」",
				ProjectRecovery.TempPowerReverseForCheck("SparkleForgeTempStrengthPowerNextTurn") == TempPowerReverses.NextTurnStart
				&& ProjectRecovery.TempPowerReverseForCheck("SparkleForgeTempStrengthPower") == TempPowerReverses.TurnEnd,
				ProjectRecovery.TempPowerReverseForCheck("SparkleForgeTempStrengthPowerNextTurn") + " / "
				+ ProjectRecovery.TempPowerReverseForCheck("SparkleForgeTempStrengthPower"));
			// 负数档（让目标失去 N 层、到点加回来）：类名带 Abs，回读要认得出来
			var tpNeg = new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", Amount = -5m, TargetSide = "Enemy" };
			Check("「临时增益」能填负数（让敌人失去 5 点临时力量）—— 范围是 -99~99",
				EffectCatalog.FindKind("TempPower").Min == -99m && EffectCatalog.FindKind("TempPower").Max == 99m
				&& new EffectSpec { Kind = "TempPower", Amount = -5m }.Amount == -5m,
				$"{EffectCatalog.FindKind("TempPower").Min}~{EffectCatalog.FindKind("TempPower").Max}");
			Check("负数档的类名/回读都带 Abs 标记（和正数档不会撞成一个类）",
				Naming.TempPowerSuffix(tpNeg).Contains("Abs")
				&& ProjectRecovery.TempPowerIsNegativeForCheck("SparkleForgeTempStrengthPowerAbs") 
				&& !ProjectRecovery.TempPowerIsNegativeForCheck("SparkleForgeTempStrengthPower"),
				Naming.TempPowerSuffix(tpNeg));
			// 负数档两种写法（用户第 9 打 ①：「临时增益不生效，参考本体尖啸」），"
			//   · 力量 / 敏捷 / 专注（本体 AllowNegative => true）→ **照尖啸那套**直接施加负数层数）"
			//     目标身上本来 0 层也能扣成负的（以前只扣「已有层数」，0 层就什么都不做 = 不生效），"
			//   · 虚弱 / 易伤这类层数不能为负的 → 仍旧 GetPower + ModifyAmount 扣已有层数」"
			Check("填负数 + 力量（本体 AllowNegative）→ 照本体「尖啸」那套直接施加负数层数",
				EffectCatalog.AllowsNegativeLayers("StrengthPower")
				&& EffectCatalog.AllowsNegativeLayers("DexterityPower")
				&& EffectCatalog.AllowsNegativeLayers("FocusPower")
				&& !EffectCatalog.AllowsNegativeLayers("WeakPower")
				&& !EffectCatalog.AllowsNegativeLayers("VulnerablePower"),
				"力量/敏捷/专注 允许负层数，虚弱/易伤 不允许");
			string tpNegStr = CSharpCodeGen.TempPowersSource(tpProfWithNeg());
			Check("负数 + 力量：生成的是 Apply<StrengthPower>(—  amount)（负数直接施加，不再面 GetPower）",
				tpNegStr.Contains("await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), target, amount")
				&& !tpNegStr.Contains("target.GetPower<StrengthPower>()"),
				"照尖啸那套");
			string tpNegWeak = CSharpCodeGen.TempPowersSource(tpProfWithNeg("WeakPower"));
			Check("负数 + 虚弱（本体不允许负层数）：仍旧是 GetPower + ModifyAmount 扣已有层数",
				tpNegWeak.Contains("PowerModel? __real = target.GetPower<WeakPower>();")
				&& tpNegWeak.Contains("await PowerCmd.ModifyAmount(new ThrowingPlayerChoiceContext(), __real, amount")
				&& !tpNegWeak.Contains("Apply<WeakPower>(new ThrowingPlayerChoiceContext(), target, amount"),
				"扣层走 ModifyAmount");
			Check("临时 Power 都实现了本体那套 ITemporaryPower（OriginModel / InternallyAppliedPower）",
				tpNegStr.Contains(": PowerModel, ITemporaryPower")
				&& tpNegStr.Contains("public AbstractModel OriginModel => this;")
				&& tpNegStr.Contains("public PowerModel InternallyAppliedPower => ModelDb.Power<StrengthPower>();"),
				"接口在");
			Check("临时 Power 开了 AllowNegative（负层数状态不会被本体当成 0 层当场移除）",
				tpNegStr.Contains("public override bool AllowNegative => true;"), "开了");
			// ⚠ V0.2.237（用户实测：「自带减层的效果加上临时之后只要层数是 1，回合结束就会扣成 -1」）
			// 本体 TemporaryStrengthPower.cs:153 是**盲写** `Apply(-Sign * base.Amount)` —— 它只会配
			// 力量 / 敏捷 / 专注，那几个自己**不扣层**，盲还原安全。而本工具允许把**任何**状态做成临时：
			// 虚弱 / 易伤 / 脆弱本体在 AfterSideTurnEnd 里自己 TickDownDuration（WeakPower.cs:49 /
			// VulnerablePower.cs:60 / FrailPower.cs:35），于是「临时 +1 层」被它自己扣掉、归 0 后整个状态被
			// 移除，我们再 Apply(-1) → `PowerModel.ApplyInternal` 直接 SetAmount((int)amount)（不夹 0）
			// → **凭空造出一个层数 -1 的状态**。修法：还原前先取实例（没了就什么都不做），再夹到不跨过 0。
			Check("V0.2.237：临时增益的还原先取真实状态实例（它已经被自己的回合结束扣光移除时什么都不做）",
				tpNegStr.Contains("PowerModel? __back = base.Owner.GetPower<StrengthPower>();")
				&& tpNegStr.Contains("if (__back is not null)"), "先取实例");
			Check("V0.2.237：还原量夹到「不跨过 0」，且只对不允许负层数的状态夹（力量 / 敏捷照旧盲还原）",
				tpNegStr.Contains("if (!__back.AllowNegative && __now + __amount < 0m) __amount = -__now;"), "夹住了");
			Check("V0.2.237：不再出现「把 -base.Amount 直接塞进 Apply」的盲还原",
				!tpNegStr.Contains("base.Owner, -base.Amount, base.Owner, null)"), "没有盲还原了");
			Check("V0.2.237：两档还原（回合结束 / 下回合开始）都带守卫（各 1 处，共 2 处）",
				tpSrc.Contains("AfterSideTurnEnd") && tpSrc.Contains("AfterPlayerTurnStart")
				&& tpSrc.Split("if (__back is not null)").Length - 1 == 2
				&& tpSrc.Split("if (!__back.AllowNegative && __now + __amount < 0m) __amount = -__now;").Length - 1 == 2,
				"守卫处数 = " + (tpSrc.Split("if (__back is not null)").Length - 1));
			// 图（锻造页）里的「临时增益」：以前**没有**生成临时 Power，施加的是永久状态"
			CharacterProfile forgedTempProf = ForgedTempPowerProfile(out string tpvCall);
			Check("节点图里的「临时增益」会生成临时 Power 类（扫描时也带上自定义状态的图）",
				CSharpCodeGen.CollectTempPowerEffects(forgedTempProf).Any(e => e.PowerId == "StrengthPower")
				&& CSharpCodeGen.UsesTempPower(forgedTempProf),
				"类 = " + string.Join(" / ", CSharpCodeGen.CollectTempPowerEffects(forgedTempProf).Select(e => Naming.From(forgedTempProf).TempPowerClass(e))));
			Check("节点图里的「临时增益」调用点用的是那个临时 Power（不是直接施加真状态）",
				tpvCall.Contains("PowerCmd.Apply<") && tpvCall.Contains("ForgeTempStrengthPowerNextTurn>"),
				"调用点 " + tpvCall.Trim());
			Check("节点图里【效果】多了「什么时候撤掉」这一栏（和效果栏那份候选同一件 id）",
				ForgeGraphCatalog.Find("Effect").Fields.Any(f => f.Key == "Reverse")
				&& ForgeGraphCatalog.Find("Effect").Fields.First(f => f.Key == "Reverse").OptionList.Count == 2
				&& ForgeGraphCatalog.Find("Effect").Fields.First(f => f.Key == "Reverse").OptionList[0].Id == TempPowerReverses.TurnEnd
				&& ForgeGraphCatalog.Find("Effect").Fields.First(f => f.Key == "Reverse").OptionList[1].Id == TempPowerReverses.NextTurnStart,
				string.Join(" / ", ForgeGraphCatalog.Find("Effect").Fields.First(f => f.Key == "Reverse").OptionList.Select(o => o.Id + "=" + o.Display)));
			Check("节点图里【效果】选「临时增益」 「Reverse=NextTurn」→ 合成的那条效果带 NextTurn 档（类名后缀对得上）",
				ForgeGraphGen.TempPowerEffectOf(ForgeEffectNode("TempPower", "StrengthPower", 4, TempPowerReverses.NextTurnStart))
					.TempPowerReverse == TempPowerReverses.NextTurnStart
				&& ForgeGraphGen.TempPowerEffectOf(ForgeEffectNode("TempPower", "StrengthPower", 4, ""))
					.TempPowerReverse == TempPowerReverses.TurnEnd,
				"两档都对");
			// ⚠ V0.2.139：这一条改的是**判据**（不是放宽）—— 锻造图上的「施加状态」填负数，以前内联生成的
			// `if (amount < 0m) { GetPower<T>() → ModifyAmount(amount) }` 有两处错：传进去的 amount 本身就是负的
			// （ModifyAmount(-6) = **加** 6 层，方向反了）、而且把允许负层数的状态白白降级成「只扣已有层数」。
			// 现在统一走 CSharpCodeGen.ApplyPowerLine：力量（本体 AllowNegative）→ **直接施加 -6m**（照本体「尖啸」）。
			// 这里照样钉住「符号没反」：施加的必须是 -6m，绝不许出现 `-(-6m)` / `((6m))` 这种被取正的东西。
			Check("节点图里「施加状态」填负数：力量（本体允许负层数）→ 施加的就是 amount 本身 -6m"
				+ "（照本体「尖啸」那套直接施加负值；以前那种内联写法会把 -(amount) 变成**加**层数）",
				CSharpCodeGen.CardSource(ForgedNegativeApplyPowerProfile(), ForgedNegativeApplyPowerProfile().Cards[^1], 0)
					.Contains("await PowerCmd.Apply<StrengthPower>(choiceContext, __fgFoe, (-6m)", StringComparison.Ordinal)
				&& !CSharpCodeGen.CardSource(ForgedNegativeApplyPowerProfile(), ForgedNegativeApplyPowerProfile().Cards[^1], 0)
					.Contains("-((6m))", StringComparison.Ordinal),
				"符号对了");
			// 数值 0（默认值）= 打出去一点变化都没有：以前是「提示」，现在**拦住说清**（用户报的就是这个）
			CharacterProfile zeroTempProf = ProfileFactory.Sample();
			var zeroTempCard = new CardSpec { Name = "零临时", ClassName = "UiCheckZeroTemp", CardType = "Skill", Rarity = "Common", Cost = 1 };
			zeroTempCard.Effects.Add(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", Amount = 0m, TargetSide = "Self" });
			zeroTempProf.Cards.Add(zeroTempCard);
			var zeroTempIssues = ProfileValidator.Validate(zeroTempProf);
			Check("「临时增益」数值 0 是**错误**（拦住说清：本体 Apply 收到 0 直接返回 = 不生效）",
				zeroTempIssues.Any(i => i.IsError && i.Message.Contains("临时增益") && i.Message.Contains("直接返回")),
				"错误=" + string.Join(" | ", zeroTempIssues.Where(i => i.IsError).Select(i => i.Message)));
			Check("「临时增益」数值 0 的错误里给了解法（填数值 / 数值公式 / 升级增量）",
				zeroTempIssues.Any(i => i.IsError && i.Message.Contains("升级增量")), "有解法");
			Check("「临时增益」没选状态仍旧是错误",
				ProfileValidator.Validate(ProfileWithTempPowerPowerId("")).Any(i => i.IsError && i.Message.Contains("还没选状态")),
				"没选状态会拦");
			var negTpIssues = ProfileValidator.Validate(tpProfWithNeg());
			// ⚠ 自定义状态触发器那条链**不走** ValidateEffects（所以「失去 N 层」那句提示只在卡牌 / 遗物 / 药水上出），
			// 这里只钉住关键点：不再有拦生成的那种错误。"
			Check("负数档不再被拦下生成（自定义状态触发器里也一样）",
				!negTpIssues.Any(i => i.IsError),
				"错误=" + string.Join(" | ", negTpIssues.Where(i => i.IsError).Select(i => i.Message)));
			Check("负数档的状态栏说明写对了：印「力量 -5」+「加回来」，不是「+{Amount}」那套",
				LocalizationGen.PowersJson(tpProfWithNeg()).Contains("力量 -5")
				&& LocalizationGen.PowersJson(tpProfWithNeg()).Contains("加回来")
				&& !LocalizationGen.PowersJson(tpProfWithNeg()).Contains("力量 +{Amount}"),
				LocalizationGen.PowersJson(tpProfWithNeg()).Length > 200 ? "(见下方 JSON)" : LocalizationGen.PowersJson(tpProfWithNeg()));
		}

		// ===== 「取几张」：恰好 / 最多 / 任意（需求：「消耗任意张手牌」）=====
		{
			Check("「取几张」有四档（恰好 / 最多 / 任意 / 全部）",				CountModeChoices.Count == 4 && CountModeChoices[0].Id == "" && CountModeChoices.Any(o => o.Id == "UpTo")
				&& CountModeChoices.Any(o => o.Id == "Any") && CountModeChoices.Any(o => o.Id == "All"),
				string.Join(" / ", CountModeChoices.Select(o => o.Id + "=" + o.Display)));
			Check("只有选牌类效果才显示「取几张」（消耗 / 丢弃 / 升级 / 从三摞拿牌）",
				new EffectSpec { Kind = "ExhaustCard" }.UsesCountMode
				&& new EffectSpec { Kind = "DiscardCard" }.UsesCountMode
				&& new EffectSpec { Kind = "UpgradeCard" }.UsesCountMode
				&& new EffectSpec { Kind = "TakeFromDraw" }.UsesCountMode
				&& !new EffectSpec { Kind = "Damage" }.UsesCountMode
				&& !new EffectSpec { Kind = "GenerateCard" }.UsesCountMode, "五种");
			string ModeSrc(string mode, decimal upgrade = 1m)
			{
				CharacterProfile mp = ProfileFactory.Sample();
				mp.Cards.Clear();
				var mc = new CardSpec { Name = "自检取几张", ClassName = "UiCheckMode" + (mode.Length == 0 ? "Exact" : mode), CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				mc.Effects.Clear();
				mc.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 3m, UpgradeAmount = upgrade, CardPick = "Chosen", SelectPile = "Hand", CountMode = mode });
				mp.Cards.Add(mc);
				return CSharpCodeGen.CardSource(mp, mc, 0) + "\u0001" + LocalizationGen.CardsJson(mp);
			}
			string exactSrc = ModeSrc("");
			string upToSrc = ModeSrc("UpTo");
			string anySrc = ModeSrc("Any");
			string exactPlain = ModeSrc("", 0m);
			string upToPlain = ModeSrc("UpTo", 0m);
			Check("「恰好 N 张」（默认）**没填升级增量**时生成的东西和以前一模一样（老存档的回归红线）",
				exactPlain.Contains("prefs: new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt, 3)"), "逐字一致");
			Check("「最多 N 张」**没填增量**时还是本体「净化」那种 0..N（可以少选，界面会要确认）",
				upToPlain.Contains("new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt, minCount: 0, maxCount: 3)"), "0..N");
			Check("「任意张」= 上限给一个很大的数（本体自己也是 999999999）",
				anySrc.Contains("maxCount: 999999999"), "任意张");
			Check("「任意张」不声明 Cards 变量（没有数字可显示，也不会让 OnUpgrade 去写一个没声明的变量）",
				!anySrc.Contains("new CardsVar") && !anySrc.Contains("UpgradeValueBy"), "没有变量");
			Check("「最多 / 恰好」照旧声明 Cards 变量、升级增量照旧生效（可以升级后多选几张）",
				upToSrc.Contains("new CardsVar(3)") && upToSrc.Contains("base.DynamicVars[\"Cards\"].UpgradeValueBy(1m);"), "变量与增量都在");
			// ⚠ 这一条是「升级增量到底有没有真的生效」的回归线：光有 UpgradeValueBy 不够 —— 
			//   实际选几张 / 生成几张的那一行也必须**读动态变量**，否则卡面写 {Cards:diff()}（升级后显示 4）"
			//   而代码还是写死 3（用户报过「生成卡牌的升级增量好像没反应」）。"
			Check("填了升级增量 → 实际张数**读动态变量**（不然卡面写升级后的数、代码还是老数字）",
				exactSrc.Contains("maxCount: (int)base.DynamicVars.Cards.BaseValue") || exactSrc.Contains("(int)base.DynamicVars.Cards.BaseValue")
				&& upToSrc.Contains("maxCount: (int)base.DynamicVars.Cards.BaseValue"),
				(exactSrc.Split('\n').FirstOrDefault(l => l.Contains("CardSelectorPrefs")) ?? "(没找到 ").Trim());
			Check("注释里写的是人类可读的张数（「3（升级后 4）」），不会把表达式印进注释",
				exactSrc.Contains("自己从手牌选 3（升级后 4）") && !exactSrc.Contains("// 自己从手牌选 (int)base"),
				(exactSrc.Split('\n').FirstOrDefault(l => l.Contains("自己从手牌选")) ?? "(没找到 ").Trim());
			Check("卡面描述：恰好写数字 / 最多写「最多」/ 任意写「任意张」",
				exactSrc.Contains("消耗 {Cards:diff()} 张手牌。") && upToSrc.Contains("消耗 最多 {Cards:diff()} 张手牌。")
				&& anySrc.Contains("消耗 任意张手牌。"), "三档描述");
			Check("「随机」取牌时选「任意 / 最多」会被校验器提醒（那条路没有选牌界面）",
				ProfileValidator.Validate(WithCountMode("Any", "Random")).Any(i => i.Level == "警告" && i.Message.Contains("随机那条路没有选牌界面")),
				"有提醒");
			Check("（对照）「自己选」时不会多这条提醒",
				!ProfileValidator.Validate(WithCountMode("Any", "Chosen")).Any(i => i.Message.Contains("随机那条路没有选牌界面")), "不多报");

			// ===== 第四档「全部」（V0.2.163，用户要求「要」：本体恶魔之焰那种「消耗所有手牌」）=====
			string allSrc = ModeSrc("All");
			Check("「全部」= **不弹选牌界面**：生成的是对手牌那一摞的 foreach（本体「恶魔之焰」的写法），一句 CardSelectCmd 都没有",
				allSrc.Contains("foreach (CardModel c in PileType.Hand.GetPile(base.Owner).Cards.ToList()) await CardCmd.Exhaust(choiceContext, c);")
				&& !allSrc.Contains("CardSelectCmd.FromHand"), "恶魔之焰原样写法");
			Check("「全部」不声明 Cards 变量（没有张数可显示，也不会让 OnUpgrade 去写一个没声明的变量）",
				!allSrc.Contains("new CardsVar") && !allSrc.Contains("UpgradeValueBy"), "没有变量");
			Check("卡面描述：全部写「所有」（不带「张」），不写「自己选」",
				allSrc.Contains("消耗 所有手牌。"), "所有手牌");
			Check("列在 15 种选牌类效果上都有「全部」这一档：消耗 / 丢弃 / 升级 / 复制 / 重放 / 变化 / 回合结束自动打出 / 放置 / 给关键词 / 三处拿牌 / 三种全局牌组",
				AllModeKinds.All(k => new EffectSpec { Kind = k }.ShowCountModeRow), string.Join(" / ", AllModeKinds));
			Check("每种都生成了「全部」分支（一次性把 15 种都生成出来逐个数）",
				AllModeKinds.Count(k => AllModeCodeFor(k).Contains("全部", StringComparison.Ordinal)) == AllModeKinds.Length,
				string.Join(" / ", AllModeKinds.Where(k => !AllModeCodeFor(k).Contains("全部", StringComparison.Ordinal))));
			Check("「全部」在生成代码里带一行 CET:CountMode 标记（回读靠它还原 —— 「全部」那一档根本没有选牌语句，逐行猜不出来）",
				AllModeKinds.All(k => AllModeCodeFor(k).Contains("// CET:CountMode=All", StringComparison.Ordinal)), "都带标记");
			Check("「全部」+ 随机/牌顶：校验器提示「选牌方式不生效」（不是静默忽略）",
				ProfileValidator.Validate(WithCountMode("All", "Random")).Any(i => i.Message.Contains("不弹选牌界面") && i.Message.Contains("选牌方式")),
				"有提醒");
			Check("「全部」+ 升级增量：校验器提示「升级增量对这条没有作用」",
				ProfileValidator.Validate(WithCountMode("All", "Chosen")).Any(i => i.Message.Contains("取全部") && i.Message.Contains("升级增量")),
				"有提醒");
			// 生成 → 回读：三种非默认档都要原样认回来（尤其是「全部」—— 它没有选牌语句，只能靠标记）
			foreach (string mode in new[] { "UpTo", "Any", "All" })
			{
				CharacterProfile cmProfile = ProfileFactory.Sample();
				// ⚠ 不能把样例卡清空：奖励池至少要 3 张可抽的卡，清空了生成会直接报错（踩过）
				var cmCard = new CardSpec { Name = "回读取几张", ClassName = "UiCheckCountMode" + mode, CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = false };
				cmCard.Effects.Clear();
				cmCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 3m, CardPick = "Chosen", SelectPile = "Draw", CountMode = mode, TargetSide = "Self" });
				cmProfile.Cards.Add(cmCard);
				string cmRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_countmode_" + mode + "_" + Guid.NewGuid().ToString("N").Substring(0, 6));
				try
				{
					cmProfile.Paths.OutputDir = cmRoot;
					cmProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					cmProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var cmGen = ModGenerator.Generate(cmProfile);
					Check($"（准备）「取几张 = {mode}」的卡能生成工程", cmGen.Success,
						cmGen.Success ? cmGen.ProjectRoot : string.Join(" ｜ ", cmGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (cmGen.Success)
					{
						var cmRec = ProjectRecovery.FromProject(cmGen.ProjectRoot);
						CardSpec? cmBack = cmRec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckCountMode" + mode);
						Check($"从工程恢复：「取几张 = {mode}」原样认得回来（含「从哪里选牌 = 抽牌堆」）",
							cmBack is not null && cmBack.Effects.Count == 1 && cmBack.Effects[0].CountMode == mode
							&& cmBack.Effects[0].SelectPile == "Draw",
							cmBack is null ? "(缺 " : $"{cmBack.Effects.Count} 条效果 / {cmBack.Effects.FirstOrDefault()?.CountMode ?? "(空)"} / {cmBack.Effects.FirstOrDefault()?.SelectPile}");
						Check($"从工程恢复（取几张 = {mode}）：没认出来的语句为 0", !cmRec.HasUnparsed, cmRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { if (Directory.Exists(cmRoot)) Directory.Delete(cmRoot, true); } catch { }
				}
			}
			// 「全部」档 15 种逐条走一遍「生成 → 回读」：每种都必须是**正好一条**效果、没认出来的语句为 0。
			// （这一条很值：All 档每种的实现行都不一样，靠标记收尾；漏一个跳过规则就会多回读一条 / 报没认出来。）
			foreach (string kind in AllModeKinds)
			{
				CharacterProfile akProfile = ProfileFactory.Sample();
				var akCard = new CardSpec { Name = "全部回读", ClassName = "UiCheckAllBack", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = false };
				akCard.Effects.Clear();
				akCard.Effects.Add(AllModeEffect(kind));
				akProfile.Cards.Add(akCard);
				string akRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_allmode_" + kind + "_" + Guid.NewGuid().ToString("N").Substring(0, 6));
				try
				{
					akProfile.Paths.OutputDir = akRoot;
					akProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					akProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var akGen = ModGenerator.Generate(akProfile);
					if (!akGen.Success)
					{
						Check($"（准备）「{kind}」的「全部」档能生成工程", false,
							string.Join(" ｜ ", akGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
						continue;
					}
					var akRec = ProjectRecovery.FromProject(akGen.ProjectRoot);
					CardSpec? akBack = akRec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckAllBack");
					Check($"「全部」档回读（{kind}）：正好一条效果、取几张 = 全部、种类对得上",
						akBack is not null && akBack.Effects.Count == 1
						&& akBack.Effects[0].Kind == kind && akBack.Effects[0].CountMode == "All",
						akBack is null ? "(缺 " : $"{akBack.Effects.Count} 条 / {akBack.Effects.FirstOrDefault()?.Kind} / {akBack.Effects.FirstOrDefault()?.CountMode}");
					Check($"「全部」档回读（{kind}）：没认出来的语句为 0", !akRec.HasUnparsed, akRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
				finally
				{
					try { if (Directory.Exists(akRoot)) Directory.Delete(akRoot, true); } catch { }
				}
			}
		}

		// ===== 多人联机：几份角色模组装在同一台机器上不能互相撞（用户问的「英文类名 / 额外资源量 / 状态的冲突」）=====
		// 本体的握手要求「所有玩法模组一致 + 模型 ID 库哈希一致」→ 一起玩时每个人都会装齐所有人的模组，
		// 于是**同名类 / 同一个本体键**就会互相覆盖。所以：类名要带角色前缀；资源名走我们自己的键。"
		{
			CharacterProfile mp = ProfileFactory.Sample();
			mp.Cards.Clear();
			mp.Cards.Add(new CardSpec
			{
				Name = "撞名卡", ClassName = "MyStrike", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects = { new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" } },
			});
			Check("手填的类名没带角色前缀 → 提示（多人联机时两份额外的模组同名类会让游戏起不来）",
				ProfileValidator.Validate(mp).Any(i => i.Message.Contains("没带角色前缀")), "提示了");
			mp.Cards.Clear();
			mp.Cards.Add(new CardSpec
			{
				Name = "带前缀卡", ClassName = "SevenMyStrike", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects = { new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" } },
			});
			Check("（对照）带了角色前缀的类名不提示", !ProfileValidator.Validate(mp).Any(i => i.Message.Contains("没带角色前缀")), "不提示");
			mp.Cards.Clear();
			mp.Cards.Add(new CardSpec
			{
				Name = "自动编号卡", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects = { new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" } },
			});
			Check("（对照）留空类名（工具自动编号）也不提示", !ProfileValidator.Validate(mp).Any(i => i.Message.Contains("没带角色前缀")), "不提示");
		}

		// ===== 「取几张」类效果：填了升级增量时**实际张数**必须读动态变量（用户报「生成卡牌的升级增量没反应」）=====
		// 光在 OnUpgrade 里写 UpgradeValueBy 不够 —— 真正决定「选几张 / 生成几张」的那一行也必须读它）"
		// 否则卡面写 {Cards:diff()}（升级后显示 3）而代码还是写死 1（实际只生成 1 张）。"
		{
			string One(EffectSpec e)
			{
				CharacterProfile gp = ProfileFactory.Sample();
				gp.Cards.Clear();
				var gc = new CardSpec { Name = "计数自检", ClassName = "UiCount" + Math.Abs(e.Kind.GetHashCode() % 9973), CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				gc.Effects.Clear();
				gc.Effects.Add(e);
				gp.Cards.Add(gc);
				return CSharpCodeGen.CardSource(gp, gc, 0);
			}
			var countKinds = new (string Label, EffectSpec Spec, string Probe)[]
			{
				("生成卡牌（指定卡）", new EffectSpec { Kind = "GenerateCard", Amount = 1m, UpgradeAmount = 1m, SpawnCardId = "Strike", SpawnTo = "Hand", TargetSide = "Self" }, "AddToCombatAndPreview<MegaCrit.Sts2.Core.Models.Cards.Strike>(base.Owner.Creature, PileType.Hand, (int)base.DynamicVars.Cards.BaseValue"),
				("生成卡牌（按范围随机）", new EffectSpec { Kind = "GenerateCard", Amount = 2m, UpgradeAmount = 1m, SpawnFilter = "Attack", SpawnPick = "Random", SpawnTo = "Hand", TargetSide = "Self" }, "GetDistinctForCombat(base.Owner, __genPool, (int)base.DynamicVars.Cards.BaseValue"),
				("消耗卡牌", new EffectSpec { Kind = "ExhaustCard", Amount = 2m, UpgradeAmount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("丢弃卡牌", new EffectSpec { Kind = "DiscardCard", Amount = 2m, UpgradeAmount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("升级卡牌", new EffectSpec { Kind = "UpgradeCard", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("变化卡牌", new EffectSpec { Kind = "TransformCard", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("复制卡牌", new EffectSpec { Kind = "CopyCard", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self" }, "(int)base.DynamicVars[\"Cards\"].BaseValue"),
				("重放卡牌", new EffectSpec { Kind = "ReplayCard", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self" }, "(int)base.DynamicVars[\"Cards\"].BaseValue"),
				("预见", new EffectSpec { Kind = "Scry", Amount = 2m, UpgradeAmount = 1m, TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("从抽牌堆拿牌", new EffectSpec { Kind = "TakeFromDraw", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("从弃牌堆拿牌", new EffectSpec { Kind = "TakeFromDiscard", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
				("从消耗牌堆拿牌", new EffectSpec { Kind = "TakeFromExhaust", Amount = 1m, UpgradeAmount = 1m, CardPick = "Chosen", TargetSide = "Self" }, "(int)base.DynamicVars.Cards.BaseValue"),
			};
			foreach (var (label, spec, probe) in countKinds)
			{
				string srcUp = One(spec);
				decimal keep = spec.UpgradeAmount;
				spec.UpgradeAmount = 0m;
				string srcPlain = One(spec);
				spec.UpgradeAmount = keep;
				bool readsVar = srcUp.Contains(probe, StringComparison.Ordinal);
				bool plainLiteral = !srcPlain.Contains("base.DynamicVars.Cards.BaseValue", StringComparison.Ordinal);
				Check($"「{label}」填了升级增量 → 实际张数读动态变量（卡面写升级后的数、代码也得跟着变）",
					readsVar, readsVar ? "读变量" : (srcUp.Split('\n').FirstOrDefault(l => l.Contains("Cards")) ?? "(没找到 ").Trim());
				Check($"（对照）「{label}」没填升级增量 → 仍是字面量（老存档生成的东西一个字都不变）",
					plainLiteral, plainLiteral ? "字面量" : "变成了读变量");
			}
		}

		// ===== 「升级卡牌」的升级增量到底有没有用（用户问过）=====
		// 战斗内的「升级卡牌」：声明 Cards 变量 + OnUpgrade 里 UpgradeValueBy → **有用**（卡面 {Cards:diff()} 跟着变）。"
		// 带「（全局）」的那几个（升级 / 获得 / 变化 / 删除牌组里的牌）+ 结束回合 / 额外回合 / 获得药水 /
		// 给予关键词 / 回合结束自动打出：数字是写死的循环次数、没有可升级的数值 → **没用**（以前是静默忽略的）。"
		{
			CharacterProfile upIncProf = ProfileFactory.Sample();
			CardSpec UpIncCard(string cls, string kind) => new()
			{
				Name = "增量自检" + kind, ClassName = cls, CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects = { new EffectSpec { Kind = kind, Amount = 1m, UpgradeAmount = 1m, TargetSide = "Self", CardPick = "Chosen", SelectPile = "Hand", SpawnCardId = "Strike", PotionId = "BlockPotion" } },
			};
			var upWork = UpIncCard("UpIncWork", "UpgradeCard");
			var upDead = UpIncCard("UpIncDead", "UpgradeCardGlobal");
			var upDmg = UpIncCard("UpIncDmg", "Damage");
			upIncProf.Cards.Add(upWork);
			upIncProf.Cards.Add(upDead);
			upIncProf.Cards.Add(upDmg);
			string workSrc = CSharpCodeGen.CardSource(upIncProf, upWork, 0);
			string deadSrc = CSharpCodeGen.CardSource(upIncProf, upDead, 0);
			string dmgSrc = CSharpCodeGen.CardSource(upIncProf, upDmg, 0);
			Check("「升级卡牌」（战斗内从手牌 / 牌堆挑）：升级增量**有用** —— 声明了 Cards 变量，OnUpgrade 里 UpgradeValueBy",
				workSrc.Contains("new CardsVar(1)") && workSrc.Contains("base.DynamicVars[\"Cards\"].UpgradeValueBy(1m);"),
				workSrc.Contains("UpgradeValueBy") ? "有增量" : "没有增量");
			Check("「升级卡牌」的卡面描述用 {Cards:diff()}（升级后显示多一张）",
				LocalizationGen.CardsJson(upIncProf).Contains("升级 {Cards:diff()} 张手牌"),
				LocalizationGen.CardsJson(upIncProf).Split('\n').FirstOrDefault(l => l.Contains("UP_INC_WORK.description"))?.Trim() ?? "(没找到)");
			Check("（对照）「造成伤害」的升级增量照旧有用（回归红线）",
				dmgSrc.Contains("base.DynamicVars.Damage.UpgradeValueBy(1m);") || dmgSrc.Contains("base.DynamicVars[\"Damage\"].UpgradeValueBy(1m);"),
				dmgSrc.Contains("UpgradeValueBy") ? "有增量" : "没有增量");
			Check("「升级卡牌（全局）」：升级增量**不会生效**（数字是写死的循环次数）→ 生成里没有 UpgradeValueBy",
				!deadSrc.Contains("UpgradeValueBy"), "没有增量");
			Check("而且这种情况校验器会**警告**（以前是静默忽略 —— 用户问过「升级卡牌的升级增量没用吗」）",
				ProfileValidator.Validate(upIncProf).Any(i => i.Level == "警告" && i.Message.Contains("没有可以升级的数值")),
				string.Join(" ｜ ", ProfileValidator.Validate(upIncProf).Where(i => i.Message.Contains("没有可以升级的数值")).Select(i => i.Message).Take(1)));
			Check("（对照）「升级卡牌」（有用的那个）不会被这条警告误报",
				!ProfileValidator.Validate(upIncProf).Any(i => i.Message.Contains("没有可以升级的数值") && i.Message.Contains("「升级卡牌」")),
				"不误报");
		}

		// ===== 锻造页「积木视图」：按执行顺序排成一摞积木（可拖 / 可加 / 可删的编辑器） =====
		{
			Check("锻造页有「节点图 / 积木」两个视图的切换（默认节点图）",
				ForgeViewGraph is not null && ForgeViewBlocks is not null && ForgeViewGraph.IsChecked == true,
				$"图={ForgeViewGraph?.IsChecked} 积木={ForgeViewBlocks?.IsChecked}");
			Check("积木视图是**可拖的编辑器**：标签上写着「可拖」（不再是只读观感版）",
				(ForgeViewBlocks?.Content as string ?? "").Contains("可拖"), ForgeViewBlocks?.Content as string ?? "(空 ");
			// 实测踩过：这一行先声明了左边的分页、右边的视图框被挤到没宽度，界面上只剩「视图：」三个字。"
			// 自检里窗口已给 Show 过了，所以能量到真宽度 —— 但要**临时**选一件物品，不然整块详情是收起的。"
			// ⚠ 量完必须原样还原（尤其是「一类都不选」的那个状态，后面还有断言要看它）。"
			var prevKind = ForgeKindCard!.IsChecked == true ? ForgeKindCard
				: ForgeKindPotion!.IsChecked == true ? ForgeKindPotion
				: ForgeKindRelic!.IsChecked == true ? ForgeKindRelic : ForgeKindNone;
			var prevSelIdx = ForgeItemList!.SelectedIndex;
			var prevTab = MainTabs!.SelectedItem as TabItem;
			ForgeTab!.IsSelected = true;
			ForgeKindCard.IsChecked = true;
			var demoShot = new CardSpec { Name = "布局用", ClassName = "ShotLayout", CardType = "Attack", Rarity = "Common" };
			demoShot.IsForged = true;
			Profile.Cards.Add(demoShot);
			RefreshForgeList();
			ForgeItemList.SelectedIndex = 0;
			UpdateLayout();
			Check("两个视图单选在界面上真的占了宽度（没被左边的分页=/ 说明文字挤出窗口）",
				ForgeViewGraph!.ActualWidth > 20 && ForgeViewBlocks!.ActualWidth > 20,
				$"节点图={ForgeViewGraph.ActualWidth:F0}px 积木={ForgeViewBlocks.ActualWidth:F0}px");
			Profile.Cards.Remove(demoShot);
			ForgeItemList.SelectedIndex = -1;
			prevKind!.IsChecked = true;
			ForgeItemList.SelectedIndex = prevSelIdx;
			if (prevTab is not null) prevTab.IsSelected = true;
			RefreshForgeList();
			UpdateLayout();
			Check("切到积木视图时两块视图的显隐是互斥的",
				ForgeGraphVisible && !ForgeBlocksVisible, $"图={ForgeGraphVisible} 积木={ForgeBlocksVisible}");
			ForgeViewBlocks!.IsChecked = true;
			UpdateLayout();
			Check("勾上「积木」后：积木显示、节点图收起",
				ForgeBlocksVisible && !ForgeGraphVisible, $"图={ForgeGraphVisible} 积木={ForgeBlocksVisible}");
			ForgeViewGraph!.IsChecked = true;
			UpdateLayout();

			// 排布：触发时机 → 【if】→（是 / 否两支，缩进一层）
			var bg = new ForgeGraphSpec();
			var bTrig = new ForgeNodeSpec { Kind = "Trigger" };
			bTrig.SetField("Timing", ForgeTimings.CardPlayed);
			var bIf = new ForgeNodeSpec { Kind = "If" };
			var bCond = new ForgeNodeSpec { Kind = "Condition" };
			var bYes = new ForgeNodeSpec { Kind = "Effect" };
			bYes.SetField("Effect", "Damage");
			bYes.SetField("Amount", "6");
			var bNo = new ForgeNodeSpec { Kind = "Effect" };
			bNo.SetField("Effect", "Block");
			bNo.SetField("Amount", "5");
			bg.Nodes.AddRange(new[] { bTrig, bIf, bCond, bYes, bNo });
			bg.Links.Add(new ForgeLinkSpec { From = bTrig.Id, To = bIf.Id, FromPort = 0, ToPort = 0 });
			bg.Links.Add(new ForgeLinkSpec { From = bCond.Id, To = bIf.Id, FromPort = 0, ToPort = 1 });   // 条件口（左边入口 1）"
			bg.Links.Add(new ForgeLinkSpec { From = bIf.Id, To = bYes.Id, FromPort = 0, ToPort = 0 });     // 是 
			bg.Links.Add(new ForgeLinkSpec { From = bIf.Id, To = bNo.Id, FromPort = 1, ToPort = 0 });      // 名 
			int nodesBefore = bg.Nodes.Count, linksBefore = bg.Links.Count;
			var blocks = ForgeBlockLayout.Build(bg);
			Check("积木排布：一行一块积木、顺序 = 执行顺序（触发时机在最上面）",
				blocks.Count >= 4 && blocks[0].Kind == "Trigger" && blocks[1].Kind == "If",
				string.Join(" → ", blocks.Select(x => x.Kind)));
			Check("【if】的两支分别标了「是」/「否」，并且**缩进一层**",
				blocks.Any(x => x.Branch == "是" && x.Indent == 1) && blocks.Any(x => x.Branch == "否" && x.Indent == 1),
				string.Join(" / ", blocks.Select(x => $"{x.Kind}@{x.Indent}{(x.Branch.Length > 0 ? ":" + x.Branch : "")}")));
			Check("积木上带着「实际配了什么」（伤害那块能读出数值 6）",
				blocks.Any(x => x.Text.Contains("伤害", StringComparison.Ordinal) && x.Summary.Contains("6")),
				blocks.FirstOrDefault(x => x.Text.Contains("伤害", StringComparison.Ordinal))?.Summary ?? "(没有伤害块 ");
			// 报告块 / C 形块：用一个「数值 → 效果」的小图直接验（条件块会被内联进 if，不出现在列表里）"
			var bg2 = new ForgeGraphSpec();
			var bg2Trig = new ForgeNodeSpec { Kind = "Trigger" };
			bg2Trig.SetField("Timing", ForgeTimings.CardPlayed);
			var bg2Eff = new ForgeNodeSpec { Kind = "Effect" };
			bg2Eff.SetField("Effect", "Damage");
			var bg2Val = new ForgeNodeSpec { Kind = "Value" };
			bg2Val.SetField("Formula", "M*3");
			bg2.Nodes.AddRange(new[] { bg2Trig, bg2Eff, bg2Val });
			bg2.Links.Add(new ForgeLinkSpec { From = bg2Trig.Id, To = bg2Eff.Id, FromPort = 0, ToPort = 0 });
			bg2.Links.Add(new ForgeLinkSpec { From = bg2Val.Id, To = bg2Eff.Id, FromPort = 0, ToPort = 1 });
			var bg2Blocks = ForgeBlockLayout.Build(bg2);
			Check("数值块被**内联**进它作用的那一块（不单独占一行，像 Scratch 的「槽」）",
				bg2Blocks.Any(x => x.Kind == "Effect" && x.Summary.Contains("M*3", StringComparison.Ordinal))
				&& !bg2Blocks.Any(x => x.Kind == "Value"),
				string.Join(" / ", bg2Blocks.Select(x => x.Kind + ":" + x.Summary)));
			Check("C 形块（if）被标出来（左边一条竖边 + 内槽那种）",
				blocks.Any(x => x.IsContainer), string.Join(" / ", blocks.Select(x => x.Kind + (x.IsContainer ? "(C)" : ""))));
			Check("【if】那一行只写**条件**，不把左边的「触发时机」当成条件（两个下标都是 0，靠出口类型区分）",
				blocks.Any(x => x.Kind == "If" && !x.Summary.Contains("打出时", StringComparison.Ordinal)),
				blocks.FirstOrDefault(x => x.Kind == "If")?.Summary ?? "(没有 if 块 ");
			Check("**排布本身不改图**：只排一遍积木不动图（节点数 / 连线数不变）",
				bg.Nodes.Count == nodesBefore && bg.Links.Count == linksBefore, $"{bg.Nodes.Count}/{bg.Links.Count}");
			// 视图控件真的能把这块布画出来（不抛异常、状态行有内容）
			ForgeBlocks!.Show(bg);
			UpdateLayout();
			Check("积木编辑器能把这块布画出来（没抛异常）",
				ForgeBlocks.DrawnBlockCount >= 4, $"{ForgeBlocks.DrawnBlockCount} 块");

			// ===== 积木编辑器：拿 / 加 / 到 =====
			// ⚠ 一定要**先 Show 再取块**：Show 会把编辑器内部那棵树重建一遍，
			//   之前取到的 TreeBlock 属于旧树，Move 会「定位不到」而静默什么都不做。"
			var eb = EditableGraph();
			ForgeBlocks.Show(eb);
			var et = ForgeBlocks.Tree!;
			int nodes0 = eb.Nodes.Count;
			var ifB = et.All().FirstOrDefault(x => x.Kind == "If");
			var unitB = et.All().FirstOrDefault(x => x.Kind == "Unit");
			bool dragOk = ifB is not null && unitB is not null && ForgeBlocks.DragForCheck(unitB, ifB, DropWhere.Before);
			UpdateLayout();
			var et2 = ForgeBlockTree.Build(eb);
			var if2 = et2.All().FirstOrDefault(x => x.Kind == "If");
			Check("积木编辑器：把一块拖进【if】的「是」支里面（拖完它挂在 if 名下）",
				dragOk && ifB is not null
				&& et.All().Count(x => x.Kind == "If") == 1
				&& et.All().Any(x => x.Kind == "Unit"),
				"拖=" + dragOk + " / if 的出口 " + (ifB is null ? "(没有 if)" : ifB.ParentPort.ToString()));
			Check("积木编辑器：拖完写回图（节点一个没多一个没少）",
				eb.Nodes.Count == nodes0 && eb.Links.Count > 0, $"节点 {eb.Nodes.Count}（原 {nodes0}）  级 {eb.Links.Count}");
			Check("积木编辑器：拖完图里的节点一个没少（拖拽只重连线，不删块）",
				eb.Nodes.Count == nodes0 && CountKind(eb, "Effect") == 2 && et.DuplicatedNodes().Count == 0,
				$"节点 {eb.Nodes.Count}（原 {nodes0}）  效果 {CountKind(eb, "Effect")}");
			// 防成环：【if】自己的后代不能当它的容器（拖进去会绕起来）
			var descendant = ifB?.Children.FirstOrDefault();
			Check("积木编辑器：不许把父块拖进自己的子树（防绕成环）",
				descendant is null || !ForgeBlocks.DragForCheck(ifB!, descendant, DropWhere.Into),
				descendant is null ? "没有子块可试" : "被拒绝");

			// 加块：在一张空布上从零搭出「【效果】→【效果】。"
			var eb2 = new ForgeGraphSpec();
			ForgeBlocks.Show(eb2);
			var a1 = ForgeBlocks.AddBlockForCheck("Effect", null);
			var a2 = ForgeBlocks.AddBlockForCheck("Effect", a1);
			UpdateLayout();
			var et3 = ForgeBlockTree.Build(eb2);
			Check("积木编辑器：空布上点【效果】能加出两块（顺手补一个【触发时机】）",
				a1 is not null && a2 is not null && et3.Docs.Count == 1 && CountKind(eb2, "Effect") == 2
				&& et3.All().Count(x => x.Kind == "Effect") == 2,
				$"文档 {et3.Docs.Count} / 效果 {CountKind(eb2, "Effect")} / 节点 {eb2.Nodes.Count}");
			Check("积木编辑器：加出来的两块真的连上了（生成端能顺着走完）",
				ChainKinds(eb2) == "Trigger→Effect→Effect", ChainKinds(eb2));
			// 【能量】是固定模块（新布上就有一块、还不能删），所以积木编辑器**不给加**它 —— 
			// 加了只会多出一块删不掉的重复块（左上角还会重叠）。"
			{
				int energyBefore = CountKind(eb2, "Energy");
				var attempt = ForgeBlocks.AddBlockForCheck("Energy", null);
				UpdateLayout();
				Check("积木编辑器：调色板里没有【能量】，也不给加（固定模块，加了就是一块删不掉的重复块）",
					CountKind(eb2, "Energy") == energyBefore && attempt is null,
					$"能量块 {energyBefore} → {CountKind(eb2, "Energy")} / 说明：{ForgeBlocks.StatusText}");
			}
			// V0.2.192：新模块【状态列表】在积木调色板里也能加（加完随手删掉，别影响后面几条）
			{
				int listBefore = CountKind(eb2, ForgeGraphCatalog.PowerListKind);
				var listBlock = ForgeBlocks.AddBlockForCheck(ForgeGraphCatalog.PowerListKind, null);
				UpdateLayout();
				Check("积木编辑器：调色板里有【状态列表】，点一下真的加得出来",
					listBlock is not null && CountKind(eb2, ForgeGraphCatalog.PowerListKind) == listBefore + 1,
					$"状态列表块 {listBefore} → {CountKind(eb2, ForgeGraphCatalog.PowerListKind)}");
				if (listBlock is not null)
				{
					ForgeBlocks.DeleteBlockForCheck(listBlock);
					UpdateLayout();
				}
			}

			// 删块：删掉刚加的第二块"
			ForgeBlocks.DeleteBlockForCheck(a2!);
			UpdateLayout();
			Check("积木编辑器：✕ 删一块（节点跟着从图里去掉，链还连着）",
				CountKind(eb2, "Effect") == 1 && ChainKinds(eb2) == "Trigger→Effect",
				CountKind(eb2, "Effect") + " 个效果 / " + ChainKinds(eb2));

