		Check("只有带条件的那条效果被包进 if（第 1 条无条件的照常执行）",
			textPer.Contains("if (base.Owner.Creature.GetPowerAmount<VulnerablePower>() >= 2)")
			&& textPer.IndexOf("CreatureCmd.GainBlock", StringComparison.Ordinal) < textPer.IndexOf("if (base.Owner.Creature.GetPowerAmount", StringComparison.Ordinal),
			"条件只包住第 2 条效果");
		Check("每条效果的条件写在注释里、点名是哪条效果", textPer.Contains("条件（只对「造成伤害」这条效果）"), "注释点名了效果");
		Check("效果各自的条件不会生成 IsPlayable（勾的是「只是这条不生效」）", !textPer.Contains("IsPlayable =>"), "没有 IsPlayable");
		perEffect.Effects[1].Condition.UnplayableWhenUnmet = true;
		string textPer2 = CSharpCodeGen.CardSource(characterProfile16, perEffect, 0);
		Check("勾上「不满足时打不出去」后会生成 IsPlayable", textPer2.Contains("protected override bool IsPlayable => (base.Owner.Creature.GetPowerAmount<VulnerablePower>() >= 2)"), "有 IsPlayable");
		perEffect.Effects[1].Condition.UnplayableWhenUnmet = false;
		// ===== #3 额外资源量条件 =====
		CardSpec resourceCond = new CardSpec { Name = "资源条件", ClassName = "UiCheckResCond", Cost = 1 };
		resourceCond.Effects.Clear();
		resourceCond.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m });
		resourceCond.Effects[0].Condition.Kind = "ExtraResourceAtLeast";
		resourceCond.Effects[0].Condition.Amount = 3m;
		characterProfile16.Cards.Add(resourceCond);
		string textRes = CSharpCodeGen.CardSource(characterProfile16, resourceCond, 0);
		Check("「拥有额外资源量至少 N 点」读的是本体星星计数（PlayerCombatState.Stars）",
			textRes.Contains("(base.Owner?.PlayerCombatState?.Stars) ?? 0) >= 3"), "读了额外资源量");
		Check("额外资源量条件的说明是中文且带 N", CSharpCodeGen.ConditionText(resourceCond.Effects[0].Condition) == "拥有额外资源量至少 3 点", CSharpCodeGen.ConditionText(resourceCond.Effects[0].Condition));
		// ===== #4 条件的指向对象 =====
		ConditionSpec targetCond = new ConditionSpec { Kind = "HasPowerAtLeast", Amount = 2m, PowerId = "VulnerablePower" };
		string selfExpr = CSharpCodeGen.ConditionExpr(targetCond, isCard: true);
		targetCond.Target = "AnyEnemy";
		string anyExpr = CSharpCodeGen.ConditionExpr(targetCond, isCard: true);
		targetCond.Target = "AllEnemies";
		string allExpr = CSharpCodeGen.ConditionExpr(targetCond, isCard: true);
		Check("指向对象 = 自己：读自己身上的层数", selfExpr == "base.Owner.Creature.GetPowerAmount<VulnerablePower>() >= 2", selfExpr);
		Check("指向对象 = 任意一个敌人：任一活着的敌人满足即可", anyExpr.Contains("base.CombatState.Enemies.Any(c => c.IsAlive && c.GetPowerAmount<VulnerablePower>() >= 2)"), anyExpr);
		Check("指向对象 = 全部敌人：每个活着的敌人都得满足（且至少有一个敌人）", allExpr.Contains("base.CombatState.Enemies.Any(c => c.IsAlive)") && allExpr.Contains("base.CombatState.Enemies.All(c => !c.IsAlive || c.GetPowerAmount<VulnerablePower>() >= 2)"), allExpr);
		Check("指向对象会写进条件说明里（（全部敌人））", CSharpCodeGen.ConditionText(targetCond) == "拥有易伤至少 2 层（全部敌人）", CSharpCodeGen.ConditionText(targetCond));
		Check("指向对象也管生命值条件", CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpBelowPercent", Amount = 50m, Target = "AllEnemies" }, isCard: true).Contains("Enemies.All(c => !c.IsAlive || c.CurrentHp * 100 <= c.MaxHp * 50)"), "生命值条件也支持指向对象");
		Check("指向对象只在需要的条件上出现（手牌数这种不看对象）", !EffectCatalog.FindCondition("HandAtLeast")!.NeedsTarget, "手牌条件不需要对象");
		// ===== #6 升级后的关键字 =====
		CardSpec kwCard = new CardSpec { Name = "关键字升级", ClassName = "UiCheckKw", Cost = 1 };
		kwCard.Effects.Clear();
		kwCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m });
		kwCard.Exhausts = true;
		kwCard.UpgradeKeywords.Innate = "Add";
		kwCard.UpgradeKeywords.Exhaust = "Remove";
		characterProfile16.Cards.Add(kwCard);
		string textKw = CSharpCodeGen.CardSource(characterProfile16, kwCard, 0);
		Check("升级后的关键字生成 OnUpgrade + AddKeyword（本体残影的做法）", textKw.Contains("protected override void OnUpgrade()") && textKw.Contains("AddKeyword(CardKeyword.Innate);"), "有 AddKeyword");
		Check("升级后的关键字也支持 RemoveKeyword（本体幻影 / 寒冰的做法）", textKw.Contains("RemoveKeyword(CardKeyword.Exhaust);"), "有 RemoveKeyword");
		Check("升级后的关键字只改关键字、不误改数值", textKw.Split("AddKeyword(CardKeyword.Innate);").Length - 1 == 1, "只写了一次");
		Check("卡牌列表显示里会写出「升级后：获得 固有」", kwCard.Display.Contains("升级后：获得 固有") && kwCard.Display.Contains("失去 消耗"), kwCard.Display);
		Check("三态没配时不生成任何关键字升级代码", !CSharpCodeGen.CardSource(characterProfile16, new CardSpec { Name = "无升级关键字", ClassName = "UiCheckKwNone", Cost = 1, Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } }, 0).Contains("AddKeyword"), "没有 AddKeyword");
		Check("「升级后的关键字」只列本体有的 6 个关键字", KeywordUpgradeSpec.All.Length == 6 && KeywordUpgradeStates.Count == 3, string.Join(" / ", KeywordUpgradeSpec.All.Select(k => k.Zh)));
		// 小窗口也要能滚下去：卡牌 / 遗物 / 药水的属性栏必须在可滚动区域里
		Check("「卡牌属性」那一栏能上下滚动（小窗口也能看到下面的关键字 / 卡面）",
			FindLabelledTextAndHasScrollAncestor("卡牌属性", "卡牌"), "卡牌属性已放进滚动区");
		Check("「遗物属性」那一栏能上下滚动", FindLabelledTextAndHasScrollAncestor("遗物属性", "遗物"), "遗物属性已放进滚动区");
		Check("「药水属性」那一栏能上下滚动", FindLabelledTextAndHasScrollAncestor("药水属性", "药水"), "药水属性已放进滚动区");
		// 界面上那 6 行下拉必须真的有选项（之前绑错了路径 → 下拉是空的）
		SelectTabRoot("卡牌");
		// V0.2.140：列表里现在有空槽行，所以「有没有选中一张真卡」要问 CardUiSelection
		//（CardList.SelectedItem 可能是空槽行；而 CardList.Items.Count 至少 5 行、恒 > 0）。
		if (CardUiSelection is null && Profile.Cards.Count > 0) CardList.SelectedItem = Profile.Cards[0];
		UpdateLayout();
		List<ComboBox> kwCombos = new List<ComboBox>();
		CollectCombos(CardDetail, kwCombos);
		var kwCombo = kwCombos.FirstOrDefault((ComboBox c) => c.ItemsSource == KeywordUpgradeStates);
		Check("卡牌页「升级后的关键字」的下拉绑到了那三个选项上", kwCombo != null, $"{kwCombos.Count} 个下拉里找到 {((kwCombo == null) ? 0 : 1)} 个");
		Check("「升级后的关键字」下拉里真的有选项（不变 / 升级后获得 / 升级后失去）", kwCombo != null && kwCombo.Items.Count == 3, $"{(kwCombo == null ? 0 : kwCombo.Items.Count)} 个选项");
		Check("关键字那 6 行都渲染出来了（固有 / 虚无 / 保留…）",
			UpgradeKeywordRows.Count == 6 && UpgradeKeywordRows.Any((KeywordUpgradeRow r) => r.Zh == "虚无"),
			$"{UpgradeKeywordRows.Count} 行：" + string.Join("、", UpgradeKeywordRows.Select((KeywordUpgradeRow r) => r.Zh)));
		if (CardList.SelectedItem is CardSpec kwUiCard)
		{
			var innRow = UpgradeKeywordRows.First((KeywordUpgradeRow r) => r.Zh == "固有");
			innRow.State = "Add";     // 等价于在下拉里选「升级后获得」
			Check("在下拉里选「升级后获得」会写进这张牌（并生成 AddKeyword）",
				kwUiCard.UpgradeKeywords.Innate == "Add" && CSharpCodeGen.CardSource(Profile, kwUiCard, 0).Contains("AddKeyword(CardKeyword.Innate);"), kwUiCard.UpgradeKeywords.Display);
			innRow.State = "Keep";
		}
		// 下面这些「整张牌」的检查会切到别的数据上，先切回卡牌页
		SelectTabRoot("卡牌");
		// ===== 老存档迁移：整张牌一个条件 → 第一条效果 =====
		CharacterProfile oldSave = ProfileFactory.Sample();
		// 注意：列表最上面两条是初始卡组的本体卡（打击 / 防御），这里挑「自己的卡」
		CardSpec oldSaveCard = oldSave.Cards.First((CardSpec c) => !c.IsVanillaCard);
		oldSaveCard.Condition.Kind = "HandAtLeast";
		oldSaveCard.Condition.Amount = 2m;
		Check("老存档读回时会把「整张牌的条件」搬到第一条效果上", ProfileFactory.Normalize(oldSave).Cards.First((CardSpec c) => !c.IsVanillaCard).Effects[0].Condition.Kind == "HandAtLeast" && oldSaveCard.Condition.IsNone, "已迁移");
		Check("迁移后生成出来的是效果级条件（不是 IsPlayable 那种整张牌的旧写法）", CSharpCodeGen.CardSource(oldSave, oldSaveCard, 0).Contains("条件（只对「造成伤害」这条效果）") && !CSharpCodeGen.CardSource(oldSave, oldSaveCard, 0).Contains("老存档的「整张牌」条件"), "按新写法生成");
		// ===== #7 左下角卡牌数量统计 =====
		Check("左下角统计按 攻击 / 技能 / 能力 分开报、并给出总数",
			CardCountText.Contains("攻击") && CardCountText.Contains("技能") && CardCountText.Contains("能力") && CardCountText.Contains($"共 {_profile.Cards.Count((CardSpec c) => !c.IsVanillaCard)} 张"), CardCountText);
		List<TextBlock> statusTexts = new List<TextBlock>();
		CollectTextBlocks(MainStatusBar, statusTexts);
		Check("卡牌数量就在状态栏（左下角）最前面那个位置上",
			statusTexts.Count > 0 && BindingOperations.GetBinding(statusTexts[0], TextBlock.TextProperty)?.Path?.Path == "CardCountText",
			string.Join(" / ", statusTexts.Select((TextBlock b) => BindingOperations.GetBinding(b, TextBlock.TextProperty)?.Path?.Path)));
		CardSpec counted = new CardSpec { Name = "计数用", ClassName = "UiCheckCount", Cost = 0, CardType = "Power" };
		counted.Effects.Clear();
		counted.Effects.Add(new EffectSpec { Kind = "Block", Amount = 1m });
		int beforeCount = _profile.Cards.Count((CardSpec c) => !c.IsVanillaCard);
		_profile.Cards.Add(counted);
		Check("加一张牌后统计立刻跟着变（数量 +1）", CardCountText.Contains($"共 {beforeCount + 1} 张"), CardCountText);
		_profile.Cards.Remove(counted);
		Check("删掉后统计回到原来的数量", CardCountText.Contains($"共 {beforeCount} 张"), CardCountText);

		// ===== 初始卡组里的本体卡（打击 / 防御）：不再是勾选框，而是卡牌列表里的两条「本体卡引用」 =====
		DependencyObject rootCharPage = SelectTabRoot("角色");
		List<CheckBox> charPageChecks = new List<CheckBox>();
		CollectCheckBoxes(rootCharPage, charPageChecks);
		Check("角色页不再有「初始卡组包含 5 张打击 + 5 张防御（本体占位）」这个勾选框",
			!charPageChecks.Any((CheckBox c) => (c.Content as string)?.Contains("初始卡组包含") == true),
			string.Join(" / ", charPageChecks.Select((CheckBox c) => c.Content)));
		CharacterProfile basics = ProfileFactory.Sample();
		List<CardSpec> vanillaRows = basics.Cards.Where((CardSpec c) => c.ClassName is "Strike" or "Defend").ToList();
		Check("新建存档时卡牌列表里默认就有两条初始牌（打击 / 防御）", vanillaRows.Count == 2, $"{vanillaRows.Count} 条");
		Check("只有英文类名是固定的 Strike / Defend（本体没有这两个裸类名，不会撞 ID），各 5 张",
			vanillaRows.Select((CardSpec c) => c.ClassName).SequenceEqual(new string[2] { "Strike", "Defend" })
			&& vanillaRows.All((CardSpec c) => c.StartingCopies == 5 && c.InStartingDeck),
			string.Join(" / ", vanillaRows.Select((CardSpec c) => $"{c.Name}={c.ClassName}×{c.StartingCopies}")));
		Check("初始的打击 / 防御是「你自己的卡」，数值 / 效果 / 卡面都能改（ValueEditable = true）",
			vanillaRows.All((CardSpec c) => c.ValueEditable), "可改");
		Check("出厂数值照抄本体（打击 1 费 6 伤害、防御 1 费 5 格挡，升级都 +3）",
			vanillaRows[0].Effects[0].Kind == "Damage" && vanillaRows[0].Effects[0].Amount == 6m && vanillaRows[0].Effects[0].UpgradeAmount == 3m
			&& vanillaRows[1].Effects[0].Kind == "Block" && vanillaRows[1].Effects[0].Amount == 5m && vanillaRows[1].Effects[0].UpgradeAmount == 3m,
			$"{vanillaRows[0].Effects[0].Amount}+{vanillaRows[0].Effects[0].UpgradeAmount} / {vanillaRows[1].Effects[0].Amount}+{vanillaRows[1].Effects[0].UpgradeAmount}");
		Check("标了本体卡标签（Strike / Defend）+ 稀有度 Basic —— 本体那些「升级初始打击 / 防御」的遗物就是按这个找牌的",
			vanillaRows[0].TagList.Contains("Strike") && vanillaRows[1].TagList.Contains("Defend")
			&& vanillaRows.All((CardSpec c) => c.Rarity == "Basic"),
			string.Join(" / ", vanillaRows.Select((CardSpec c) => $"{c.ClassName}:{string.Join("+", c.TagList)}/{c.Rarity}")));
		string basicsStrikeSrc = CSharpCodeGen.CardSource(basics, vanillaRows[0], 0);
		string basicsDefendSrc = CSharpCodeGen.CardSource(basics, vanillaRows[1], 1);
		Check("生成的打击卡带 CanonicalTags => CardTag.Strike",
			basicsStrikeSrc.Contains("CanonicalTags => new HashSet<CardTag> { CardTag.Strike }"), "有标签");
		Check("生成的防御卡带 CardTag.Defend 和 GainsBlock = true（和本体防御牌一样）",
			basicsDefendSrc.Contains("CanonicalTags => new HashSet<CardTag> { CardTag.Defend }") && basicsDefendSrc.Contains("public override bool GainsBlock => true;"), "有标签 + GainsBlock");
		// ===== V0.2.168：按效果**自动**声明 GainsBlock（用户要求：「能不能加一个格挡的本体卡标签，不然透镜触发不了」）=====
		// 本体「透镜 FresnelLens」给牌附魔 Nimble 时按 CardModel.GainsBlock 筛
		//（Nimble.CanEnchant = base.CanEnchant(card) && card.GainsBlock）——
		// 以前只有勾了「本体卡标签 → Defend」的牌才有这一条，用户那些「获得格挡」的牌全都没标 Defend
		//（本体也只给初始那几张防御标了），于是透镜碰都不碰它们。
		{
			var gbProf = ProfileFactory.Sample();
			var gbOk = new CardSpec { Name = "自检格挡牌", ClassName = "UiCheckGainsBlock", CardType = "Skill", Rarity = "Common", Cost = 1 };
			gbOk.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
			gbOk.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
			var gbNext = new CardSpec { Name = "自检下回合格挡", ClassName = "UiCheckGainsBlockNext", CardType = "Skill", Rarity = "Common", Cost = 1 };
			gbNext.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", NextTurn = true });
			var gbNeg = new CardSpec { Name = "自检失去格挡", ClassName = "UiCheckGainsBlockNeg", CardType = "Skill", Rarity = "Common", Cost = 1 };
			gbNeg.Effects.Add(new EffectSpec { Kind = "Block", Amount = -5m, TargetSide = "Self" });
			var gbHook = new CardSpec { Name = "自检被消耗才格挡", ClassName = "UiCheckGainsBlockHook", CardType = "Skill", Rarity = "Common", Cost = 1 };
			gbHook.Effects.Add(new EffectSpec
			{
				Kind = "Block", Amount = 5m, TargetSide = "Self",
				Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Exhausted" },
			});
			gbProf.Cards.Add(gbOk);
			gbProf.Cards.Add(gbNext);
			gbProf.Cards.Add(gbNeg);
			gbProf.Cards.Add(gbHook);
			string gbOkSrc = CSharpCodeGen.CardSource(gbProf, gbOk, gbProf.Cards.IndexOf(gbOk));
			string gbNextSrc = CSharpCodeGen.CardSource(gbProf, gbNext, gbProf.Cards.IndexOf(gbNext));
			string gbNegSrc = CSharpCodeGen.CardSource(gbProf, gbNeg, gbProf.Cards.IndexOf(gbNeg));
			string gbHookSrc = CSharpCodeGen.CardSource(gbProf, gbHook, gbProf.Cards.IndexOf(gbHook));
			string GbWhy(CardSpec c, string src) =>
				$"NextTurn={c.Effects[0].NextTurn} Amount={c.Effects[0].Amount} CondKind={c.Effects[0].Condition?.Kind} "
				+ "命中=" + (src.Contains("public override bool GainsBlock => true;", StringComparison.Ordinal) ? "有" : "没有");
			// ⚠ 判据用**整行** `public override bool GainsBlock => true;` —— 不能只看 "GainsBlock" 这个词：
			//   自检那几张卡自己的类名里就带着它（UiCheckGainsBlockNeg…），只看词会永远命中（踩过）。
			Check("V0.2.168：打出时获得格挡（正数）→ 自动声明 `GainsBlock => true`（本体「透镜」附魔 Nimble 就是按它筛的）",
				gbOkSrc.Contains("public override bool GainsBlock => true;", StringComparison.Ordinal), GbWhy(gbOk, gbOkSrc));
			Check("V0.2.168（不误报）：只有「下回合生效」的格挡 → **不**声明 GainsBlock（那是 BlockNextTurnPower，本轮没立刻拿到）",
				!gbNextSrc.Contains("public override bool GainsBlock => true;", StringComparison.Ordinal), GbWhy(gbNext, gbNextSrc));
			Check("V0.2.168（不误报）：负数 = 失去格挡 → **不**声明 GainsBlock",
				!gbNegSrc.Contains("public override bool GainsBlock => true;", StringComparison.Ordinal), GbWhy(gbNeg, gbNegSrc));
			Check("V0.2.168（不误报）：格挡只挂在「卡牌时机 = 被消耗时」上 → **不**声明 GainsBlock（打出时并不获得格挡）",
				!gbHookSrc.Contains("public override bool GainsBlock => true;", StringComparison.Ordinal), GbWhy(gbHook, gbHookSrc));
			// 锻造图上「获得格挡」的卡同样算（那种卡的效果全在图上）
			var gbGraphProf = ProfileFactory.Sample();
			var gbForge = new CardSpec { Name = "自检锻造格挡卡", ClassName = "UiCheckGainsBlockForge", CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true };
			var gbG = new ForgeGraphSpec();
			var gbTrig = new ForgeNodeSpec { Kind = "Trigger" };
			gbTrig.SetField("Timing", ForgeTimings.CardPlayed);
			var gbEff = new ForgeNodeSpec { Kind = "Effect" };
			gbEff.SetField("Effect", "Block");
			gbEff.SetField("Amount", "6");
			gbG.Nodes.AddRange(new[] { gbTrig, gbEff });
			gbG.Links.Add(new ForgeLinkSpec { From = gbTrig.Id, To = gbEff.Id, FromPort = 0, ToPort = 0 });
			gbForge.ForgeGraph = gbG;
			gbGraphProf.Cards.Add(gbForge);
			Check("V0.2.168：锻造节点图上「获得格挡」的卡也自动声明 GainsBlock",
				CSharpCodeGen.CardSource(gbGraphProf, gbForge, gbGraphProf.Cards.Count - 1)
					.Contains("public override bool GainsBlock => true;", StringComparison.Ordinal), "有");
		}
		string basicsChar = CSharpCodeGen.CharacterSource(basics);
		// 打击 / 防御生成出来的类名带角色类名前缀（<角色>Strike / <角色>Defend）—— 避免和别的模组撞模型 ID
		string basicsCharClass = Naming.From(basics).CharClass;
		string bStrike = basicsCharClass + "Strike", bDefend = basicsCharClass + "Defend";
		string deckPart = basicsChar.Length > 0 ? basicsChar.Substring(basicsChar.IndexOf("StartingDeck", StringComparison.Ordinal)) : "";
		int strikeAt = deckPart.IndexOf($"ModelDb.Card<{bStrike}>(),", StringComparison.Ordinal);
		int defendAt = deckPart.IndexOf($"ModelDb.Card<{bDefend}>(),", StringComparison.Ordinal);
		int firstOwnAt = -1;
		foreach (System.Text.RegularExpressions.Match mm in System.Text.RegularExpressions.Regex.Matches(deckPart, @"ModelDb\.Card<(\w+)>\(\)"))
		{
			string cn = mm.Groups[1].Value;
			if (cn == bStrike || cn == bDefend) continue;
			firstOwnAt = mm.Index;
			break;
		}
		Check("生成的初始卡组里正好 5 张打击 + 5 张防御，而且排在最前面",
			System.Text.RegularExpressions.Regex.Matches(basicsChar, "ModelDb\\.Card<" + bStrike + ">\\(\\)").Count == 5
			&& System.Text.RegularExpressions.Regex.Matches(basicsChar, "ModelDb\\.Card<" + bDefend + ">\\(\\)").Count == 5
			&& strikeAt >= 0 && defendAt > strikeAt && firstOwnAt > defendAt, $"打击@{strikeAt} 防御@{defendAt} 首张自有牌@{firstOwnAt}");
		string basicsPool = CSharpCodeGen.CardPoolSource(basics);
		Check("打击 / 防御在卡池里（本体那些按标签查牌的遗物是从角色卡池里找牌的）",
			basicsPool.Contains($"ModelDb.Card<{bStrike}>()") && basicsPool.Contains($"ModelDb.Card<{bDefend}>()"), "在池子里");
		Check("但不进奖励 / 商店（稀有度是 Basic，本体抽奖励只在 Common/Uncommon/Rare 里挑）",
			!basicsPool.Contains($"RemoveAll(c => c.Id == ModelDb.Card<{bStrike}>().Id")   // 不再靠卡池排除（排除会害本体按标签查牌时崩）
			&& basics.Cards.First((CardSpec c) => c.ClassName == "Strike").Rarity == "Basic"
			&& basics.Cards.First((CardSpec c) => c.ClassName == "Defend").Rarity == "Basic"
			&& !CSharpCodeGen.RewardEligibleCards(basics).Any((CardSpec c) => c.ClassName is "Strike" or "Defend"), "靠 Basic 稀有度排除");
		Check("打击 / 防御有自己的本地化（名字 + 描述，按自己的数值显示）",
			LocalizationGen.CardsJson(basics).Contains("STRIKE.title") && LocalizationGen.CardsJson(basics).Contains("STRIKE.description")
			&& LocalizationGen.CardsJson(basics).Contains("DEFEND.title"), "有本地化");
		Check("README 里的「初始卡组」写成 打击×5 / 防御×5",
			ModGenerator.InitialDeckSummary(basics).Contains("打击×5") && ModGenerator.InitialDeckSummary(basics).Contains("防御×5"),
			ModGenerator.InitialDeckSummary(basics));
		// 老存档迁移：以前那个勾选框 = true 的话，读回来自动变成两条本体卡，初始卡组内容不变
		CharacterProfile legacyBasics = ProfileFactory.Sample();
		foreach (CardSpec v in legacyBasics.Cards.Where((CardSpec c) => c.ClassName is "Strike" or "Defend").ToList()) legacyBasics.Cards.Remove(v);
		legacyBasics.IncludeVanillaStrikeDefend = true;                 // 老存档里那个勾选框
		ProfileFactory.Normalize(legacyBasics);
		Check("老存档（勾过那个开关）读回时自动补成两条初始牌、开关归零",
			legacyBasics.Cards.Count((CardSpec c) => c.ClassName is "Strike" or "Defend") == 2 && !legacyBasics.IncludeVanillaStrikeDefend,
			$"{legacyBasics.Cards.Count((CardSpec c) => c.ClassName is "Strike" or "Defend")} 条 / 开关={legacyBasics.IncludeVanillaStrikeDefend}");
		Check("初始牌排在列表最上面、顺序是「打击 → 防御」",
			legacyBasics.Cards[0].ClassName == "Strike" && legacyBasics.Cards[1].ClassName == "Defend",
			string.Join(" / ", legacyBasics.Cards.Take(2).Select((CardSpec c) => c.Name)));
		// 老存档里这两条可能被追加在末尾、甚至顺序颠倒（早期版本）——读回来也要挪到最前面并纠正顺序
		CharacterProfile misplaced = ProfileFactory.Sample();
		var vRows = misplaced.Cards.Where((CardSpec c) => c.ClassName is "Strike" or "Defend").ToList();
		foreach (CardSpec v in vRows) misplaced.Cards.Remove(v);
		misplaced.Cards.Add(vRows[1]);      // 故意颠倒顺序、并放到最后
		misplaced.Cards.Add(vRows[0]);
		ProfileFactory.MoveVanillaBasicsToTop(misplaced);
		Check("老存档里被放到末尾/顺序颠倒的初始牌会被挪到最前面并纠正顺序",
			misplaced.Cards[0].ClassName == "Strike" && misplaced.Cards[1].ClassName == "Defend" && misplaced.Cards.Count == ProfileFactory.Sample().Cards.Count,
			string.Join(" / ", misplaced.Cards.Take(3).Select((CardSpec c) => c.Name)));
		// 自动编号口径（V0.2.130 用户拍板 Q5 = A）：**列表里全部行都占号**（含本体卡 / 初始打击防御），
		// 所以打击（第 1 行）、防御（第 2 行）也占号 —— 第一张自有卡是第 3 行 → SevenCard3。
		CharacterProfile numbering = ProfileFactory.Sample();
		numbering.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend")).ClassName = "";   // 第一张自有卡改成自动编号
		Check("序号口径 = 列表里全部行：打击 / 防御占第 1、2 行，第一张自有卡就是第 3 行（SevenCard3）",
			Naming.From(numbering).CardClassName(numbering, numbering.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend"))) == "SevenCard3",
			Naming.From(numbering).CardClassName(numbering, numbering.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend"))));
		Check("自动号和它「在列表里的行号」一致（就是左侧那个序号）",
			Naming.From(numbering).CardClassName(numbering, numbering.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend")))
				== "SevenCard" + (numbering.Cards.IndexOf(numbering.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend"))) + 1),
			"行号=" + (numbering.Cards.IndexOf(numbering.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend"))) + 1));
		Check("迁移后生成的初始卡组和以前完全一样（5 打击 + 5 防御）",
			System.Text.RegularExpressions.Regex.Matches(CSharpCodeGen.CharacterSource(legacyBasics),
				"ModelDb\\.Card<" + Naming.From(legacyBasics).CharClass + "Strike>\\(\\)").Count == 5, "5 张");
		ProfileFactory.Normalize(legacyBasics);
		Check("再读一次不会重复添加初始牌", legacyBasics.Cards.Count((CardSpec c) => c.ClassName is "Strike" or "Defend") == 2, $"{legacyBasics.Cards.Count((CardSpec c) => c.ClassName is "Strike" or "Defend")} 条");
		// 老存档里的「本体卡引用」行（IsVanillaCard）→ 自动转成你自己的 Strike / Defend（标签 / 数值 / 稀有度都对上）
		CharacterProfile legacyRef = ProfileFactory.Sample();
		foreach (CardSpec v in legacyRef.Cards.Where((CardSpec c) => c.ClassName is "Strike" or "Defend").ToList()) legacyRef.Cards.Remove(v);
		legacyRef.Cards.Add(new CardSpec { Name = "打击", ClassName = "StrikeIronclad", IsVanillaCard = true, InStartingDeck = true, StartingCopies = 4 });
		legacyRef.Cards.Add(new CardSpec { Name = "防御", ClassName = "DefendIronclad", IsVanillaCard = true, InStartingDeck = true, StartingCopies = 4 });
		ProfileFactory.Normalize(legacyRef);
		CardSpec convStrike = legacyRef.Cards.First((CardSpec c) => c.ClassName == "Strike");
		Check("老存档里的「本体卡引用」会自动转成你自己的打击 / 防御（名字和初始张数保留、标上标签、数值照抄本体）",
			!convStrike.IsVanillaCard && convStrike.StartingCopies == 4 && convStrike.TagList.Contains("Strike")
			&& convStrike.Rarity == "Basic" && convStrike.Effects.Count == 1 && convStrike.Effects[0].Amount == 6m
			&& legacyRef.Cards.First((CardSpec c) => c.ClassName == "Defend").TagList.Contains("Defend"),
			$"{convStrike.ClassName} ×{convStrike.StartingCopies} 标签={string.Join("+", convStrike.TagList)} 数值={convStrike.Effects[0].Amount}");
		Check("转完之后初始卡组引用的是你自己的卡（不再引用本体的 StrikeIronclad）",
			!CSharpCodeGen.CharacterSource(legacyRef).Contains("StrikeIronclad")
			&& System.Text.RegularExpressions.Regex.Matches(CSharpCodeGen.CharacterSource(legacyRef),
				"ModelDb\\.Card<" + Naming.From(legacyRef).CharClass + "Strike>\\(\\)").Count == 4, "4 张自己的打击");
		// 类名撞本体要拦住（否则模组加载时抛 DuplicateModelException）
		CharacterProfile clash = ProfileFactory.Sample();
		clash.Cards.First((CardSpec c) => c.ClassName is not ("Strike" or "Defend")).ClassName = "PommelStrike";
		Check("卡牌类名和本体卡重名时校验器直接报错（本机读到了本体卡牌表才算）",
			EffectCatalog.Cards.Count == 0 || ProfileValidator.Validate(clash).Any((ValidationIssue i) => i.IsError && i.Message.Contains("PommelStrike")),
			$"本体卡牌表 {EffectCatalog.Cards.Count} 项");
		Check("初始打击 / 防御漏标 CardTag 时会警告",
			ProfileValidator.Validate(new CharacterProfile { Cards = { new CardSpec { Name = "打击", ClassName = "Strike", CardType = "Attack", Rarity = "Basic", Cost = 1 } } })
				.Any((ValidationIssue i) => i.Message.Contains("CardTag")), "有警告");
		// ===== 没填英文类名的卡：文件名 / 类名声明 / 卡池引用 / 本地化键必须**完全一致** =====
		// 踩过的坑（用户报「无法构建」的真凶）：CardSource 用的是「列表下标」编号，而文件名和卡池用的是
		// 「自有卡序号」—— 初始打击/防御插到最前面差 2，于是 SevenCard9.cs 里声明成 SevenCard11，
		// 卡池引用的 SevenCard9 找不到 → 编译报 CS0246。
		{
			CharacterProfile auto = ProfileFactory.Sample();
			auto.Cards.Add(new CardSpec { Name = "没填类名的新卡", ClassName = "", CardType = "Attack", Rarity = "Common", Cost = 1 });
			CardSpec autoCard = auto.Cards.Last();
			string autoCls = Naming.From(auto).CardClassName(auto, autoCard);
			Check("没填类名的卡按「列表里全部行的行号」编号（打击 / 防御占第 1、2 行 → 第 11 张卡是 Card11）",
				autoCls == "SevenCard11", autoCls);
			string autoSrc = CSharpCodeGen.CardSource(auto, autoCard, auto.Cards.IndexOf(autoCard));
			Check("生成的类名和文件名用的是同一个名字（就是卡池引用的那个）",
				autoSrc.Contains($"public sealed class {autoCls} : CardModel") && CSharpCodeGen.CardPoolSource(auto).Contains($"ModelDb.Card<{autoCls}>()"),
				autoCls);
			Check("本地化键也用的是同一个名字", LocalizationGen.CardsJson(auto).Contains(Naming.EntryOf(autoCls) + ".title"), Naming.EntryOf(autoCls));
			// 真的生成一次到临时目录：卡池引用的卡类必须都有对应文件（这条是 CS0246 的根因回归测试）
			string autoRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_autoname_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				auto.Paths.OutputDir = autoRoot;
				auto.Paths.VanillaProject = Profile.Paths.VanillaProject;
				auto.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var autoGen = ModGenerator.Generate(auto);
				string autoFile = Path.Combine(autoGen.ProjectRoot, "cs", "Cards", autoCls + ".cs");
				Check("没填类名的卡：生成出的文件名 / 类名声明 / 卡池引用三者一致（不会再有 CS0246）",
					autoGen.Success && File.Exists(autoFile) && File.ReadAllText(autoFile, System.Text.Encoding.UTF8).Contains($"class {autoCls} : CardModel")
					&& File.ReadAllText(Path.Combine(autoGen.ProjectRoot, "cs", "SevenCardPool.cs"), System.Text.Encoding.UTF8).Contains($"ModelDb.Card<{autoCls}>()"),
					autoGen.Success ? autoCls : (autoGen.Issues.FirstOrDefault((ValidationIssue i) => i.IsError)?.Message ?? "生成失败"));
			}
			finally
			{
				try { if (Directory.Exists(autoRoot)) Directory.Delete(autoRoot, true); } catch { }
			}
		}
		// UI：选中本体卡时数值编辑变灰、效果栏整列禁用，但「初始份数」还能改
		CardSpec vanillaProbe = new CardSpec { Name = "打击", ClassName = "StrikeIronclad", IsVanillaCard = true, InStartingDeck = true, StartingCopies = 5 };
		_profile.Cards.Add(vanillaProbe);
		SyncDetail();
		CardList.SelectedItem = vanillaProbe;
		UpdateLayout();
		List<ComboBox> vanillaCombos = new List<ComboBox>();
		CollectCombos(CardDetail, vanillaCombos);
		Check("选中本体卡时：类型 / 稀有度下拉变灰（数值由本体决定）",
			vanillaCombos.Any((ComboBox c) => BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "CardType" && !c.IsEnabled)
			&& vanillaCombos.Any((ComboBox c) => BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "Rarity" && !c.IsEnabled),
			string.Join(" / ", vanillaCombos.Select((ComboBox c) => $"{BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path}={c.IsEnabled}")));
		List<TextBox> vanillaBoxes = new List<TextBox>();
		CollectTextBoxes(CardDetail, vanillaBoxes);
		Check("选中本体卡时：「初始份数」仍然可以改",
			vanillaBoxes.Any((TextBox t) => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path == "StartingCopies" && t.IsEnabled), "可改");
		List<Button> vanillaButtons = new List<Button>();
		CollectButtons(CardDetail, vanillaButtons);
		Check("选中本体卡时：效果栏整列禁用（没有效果可编）",
			vanillaButtons.Any((Button b) => (b.Content as string) == "添加效果" && !b.IsEnabled), "禁用了");
		Check("选中本体卡时：面板上有黄色说明写着「只做引用、不能改」",
			TextsIn(CardDetail).Any((string t) => t.Contains("这是本体卡（只做引用）")), "有说明");
		Check("本体卡在列表里显示成「【本体卡】…」并写出本体英文类名",
			vanillaProbe.Display.Contains("【本体卡】") && vanillaProbe.Display.Contains("StrikeIronclad"), vanillaProbe.Display);
		_profile.Cards.Remove(vanillaProbe);
		SyncDetail();
		// 状态栏：本体卡单独列出来，不算进「自己的卡」
		int vanBefore = _profile.Cards.Count((CardSpec c) => c.IsVanillaCard);
		int vanCopiesBefore = _profile.Cards.Where((CardSpec c) => c.IsVanillaCard).Sum((CardSpec c) => Math.Max(1, c.StartingCopies));
		_profile.Cards.Add(vanillaProbe);
		Check("状态栏把本体卡单独列出来、不计入「自己的卡」数量",
			CardCountText.Contains($"共 {beforeCount} 张") && CardCountText.Contains($"本体卡 {vanBefore + 1} 条（初始 {vanCopiesBefore + 5} 张）"), CardCountText);
		_profile.Cards.Remove(vanillaProbe);
		Check("删掉本体卡后统计跟着变回去",
			vanBefore == 0 ? !CardCountText.Contains("本体卡") : CardCountText.Contains($"本体卡 {vanBefore} 条（初始 {vanCopiesBefore} 张）"), CardCountText);

		// ===== 先古遗物替换：这次选项里没有那个「原本的遗物」→ 什么都不做（不顶掉别的选项） =====
		CharacterProfile anc = ProfileFactory.Sample();
		AncientTalkSpec ancTalk = new AncientTalkSpec { AncientId = "THE_ARCHITECT" };
		ancTalk.RelicReplacements.Add(new AncientRelicReplaceSpec { FromRelicId = "Astrolabe", RelicId = "SneckoEye" });
		anc.Ancients.Add(ancTalk);
		string ancSrc = AncientPatchGen.HasRelicReplacements(anc) ? AncientPatchGen.RelicReplacementSource(anc) : "";
		Check("先古遗物替换补丁能生成（这次选项里有它才换）", ancSrc.Contains("ForgeAncientRelicReplace.Replace<SneckoEye>"), ancSrc.Length > 0 ? "已生成" : "没生成");
		Check("替换代码里不再有「没抽到就顶掉最后一个选项」的兜底",
			!ancSrc.Contains("index = options.Count - 1") && ancSrc.Contains("本次不替换"), "只换不挤");
		AncientRelicReplaceSpec bare = new AncientRelicReplaceSpec { RelicId = "SneckoEye" };
		Check("界面上没选「原本的遗物」时明确写「这条不会生效」", bare.StateText.Contains("不会生效"), bare.StateText);
		AncientRelicReplaceSpec full = new AncientRelicReplaceSpec { FromRelicId = "Astrolabe", RelicId = "SneckoEye" };
		Check("配全了的说明变成「没抽到就不动（不会顶掉别的选项）」", full.StateText.Contains("不会顶掉别的选项"), full.StateText);
		Check("校验器也不再宣传「会顶掉最后一个选项」",
			ProfileValidator.Validate(anc).All((ValidationIssue i) => !i.Message.Contains("顶掉最后一个")), "措辞已更新");

		// ===== ① 初始的打击 / 防御：自己卡池里的普通卡，外观自动跟随模组（不再需要外观补丁） =====
		CharacterProfile skin = ProfileFactory.Sample();
		Check("初始的打击 / 防御不需要「本体卡外观补丁」了（它们本来就在你自己的卡池里，卡框 / 能量图标自动跟随）",
			!FlavorGen.NeedsVanillaSkin(skin) && !ModGenerator.InitialDeckSummary(skin).Contains("本体 StrikeIronclad"),
			ModGenerator.InitialDeckSummary(skin));

		// ===== ② 死亡描述文本 / 阵亡后台词真的会在游戏里出现 =====
		CharacterProfile flavor = ProfileFactory.Sample();
		flavor.DeathText = "七，到此为止。";
		flavor.DeadBanterText = "……原来如此。";
		Check("配了死亡文本就会生成补丁", FlavorGen.NeedsDeathFlavor(flavor), "会生成");
		string flavorSrc = FlavorGen.DeathFlavorSource(flavor);
		Check("死亡描述文本：给本体取死亡结算文案的方法挂 postfix（本体没有「每个角色一句」的键）",
			flavorSrc.Contains("NRunHistory.GetDeathQuote") && flavorSrc.Contains("ref string __result") && flavorSrc.Contains("七，到此为止。"), "死亡结算那句");
		Check("死亡描述文本只改我们自己的角色（按 ModelId 比对）",
			flavorSrc.Contains("characterId != ModelDb.Character<Seven>().Id"), "只认自己");
		Check("引号沿用本体那对（game_over_screen.ENCOUNTER_QUOTE_LEFT / RIGHT）",
			flavorSrc.Contains("\"game_over_screen\", \"ENCOUNTER_QUOTE_LEFT\"") && flavorSrc.Contains("ENCOUNTER_QUOTE_RIGHT"), "引号一致");
		Check("阵亡后台词：挂在 CreatureCmd.Kill 上（本体所有死亡都经过它），阵亡瞬间冒对话气泡",
			flavorSrc.Contains("typeof(CreatureCmd), \"Kill\"") && flavorSrc.Contains("NSpeechBubbleVfx.Create(\"……原来如此。\"") && flavorSrc.Contains("SpeechBubbleColor"),
			"阵亡气泡");
		Check("两句都没填时不会生成任何补丁",
			!FlavorGen.NeedsDeathFlavor(new CharacterProfile { DeathText = "", DeadBanterText = "  " }), "不生成");
		CharacterProfile onlyBanter = ProfileFactory.Sample();
		onlyBanter.DeathText = "";
		Check("只填了阵亡后台词时只生成气泡那段（不动死亡文案）",
			FlavorGen.DeathFlavorSource(onlyBanter).Contains("DeathBanterPatch") && !FlavorGen.DeathFlavorSource(onlyBanter).Contains("DeathQuotePatch"), "只气泡");

		// ===== ③ 不再有「默认携带燃烧之血」的开关，也不再偷偷塞本体遗物 =====
		DependencyObject charPage2 = SelectTabRoot("角色");
		List<CheckBox> charChecks2 = new List<CheckBox>();
		CollectCheckBoxes(charPage2, charChecks2);
		Check("角色页已删掉「没有自定义初始遗物时，默认携带燃烧之血」这个勾选框",
			!charChecks2.Any((CheckBox c) => (c.Content as string)?.Contains("燃烧之血") == true)
			&& !TextsIn(charPage2).Any((string t) => t.Contains("初始卡组里") && t.Contains("不再是一个开关")), "已删干净");
		CharacterProfile noRelic = ProfileFactory.Sample();
		noRelic.Relics.Clear();
		noRelic.ExtraResource.Enabled = false;
		Check("一只起始遗物都没配时，生成的初始遗物是空的（不再兜底塞燃烧之血）",
			!CSharpCodeGen.CharacterSource(noRelic).Contains("BurningBlood"), "没有兜底");
		Check("老存档里的 StartWithBurningBlood 字段不再被读（开着也一样）",
			!CSharpCodeGen.CharacterSource(new CharacterProfile { StartWithBurningBlood = true }).Contains("BurningBlood"), "不读旧字段");
		// ===== #8 遗物 / 药水效果栏的描述会随选择变化 =====
		EffectSpec plainEffect = new EffectSpec { Kind = "Damage", Amount = 3m };
		string plainBefore = plainEffect.DisplayPlain;
		bool plainChanged = false;
		plainEffect.PropertyChanged += delegate(object? _, System.ComponentModel.PropertyChangedEventArgs ev)
		{
			if (ev.PropertyName == "DisplayPlain") plainChanged = true;
		};
		plainEffect.Kind = "Block";
		Check("改了效果种类后「遗物 / 药水效果栏」的描述会跟着变（不再显示旧种类）",
			plainChanged && plainEffect.DisplayPlain != plainBefore && plainEffect.DisplayPlain.Contains("格挡"), plainEffect.DisplayPlain);
		EffectSpec plainEffect2 = new EffectSpec { Kind = "Damage", Amount = 3m, UpgradeAmount = 2m };
		Check("遗物 / 药水列表里不显示「升级 +N」（它们不能升级）", !plainEffect2.DisplayPlain.Contains("升级"), plainEffect2.DisplayPlain);
		// ===== #9 自定义状态的触发时机说明：要同时反映「什么时候」和「做什么」 =====
		SelectTabRoot("自定义状态");
		if (CustomPowerList.Items.Count == 0) OnAddCustomPower(this, new RoutedEventArgs());
		if (CustomPowerList.SelectedItem is CustomPowerSpec powerSpec)
		{
			// V0.2.179：这里用**新 id 的真名**（`PlayerTurnStartEarly` = 「回合开始后（抽牌前）」）——
			// 老 id `TurnStart` 也会规范化到 PlayerTurnStart，但断言写新 id 才能同时钉住「新时刻的名字进了文案」。
			PowerTriggerSpec triggerSpec = new PowerTriggerSpec { Kind = "PlayerTurnStartEarly" };
			triggerSpec.Effects.Clear();
			triggerSpec.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
			powerSpec.Triggers.Clear();
			powerSpec.Triggers.Add(triggerSpec);
			powerSpec.Description = null;
			CustomTriggerList.SelectedItem = triggerSpec;
			UpdateLayout();
			string hintBefore = TriggerHint;
			string descBefore = CustomPowerDescriptionHint;
			Check("触发时机说明里写清了「什么时候 + 做什么」",
				hintBefore.Contains("回合开始后（抽牌前）") && hintBefore.Contains("获得") && hintBefore.Contains("格挡"), hintBefore);
			Check("描述预览会按当前触发时机 + 效果写出来（留空时的自动描述）",
				descBefore.Contains("回合开始后（抽牌前）") && descBefore.Contains("获得 3 点格挡"), descBefore);
			triggerSpec.Kind = "CardPlayed";
			triggerSpec.CardFilter = "Attack";
			UpdateLayout();
			Check("改了触发时机后说明立刻跟着变（不再显示旧的时机）",
				TriggerHint != hintBefore && TriggerHint.Contains("打出一张牌时（这张牌还没生效）") && TriggerHint.Contains("（只对攻击牌）"), TriggerHint);
			Check("改了触发时机后描述预览也跟着变", CustomPowerDescriptionHint != descBefore && CustomPowerDescriptionHint.Contains("打出一张牌时（这张牌还没生效）（攻击牌）"), CustomPowerDescriptionHint);
			// ===== 「某个状态层数变化后」要能选「盯哪个状态」（用户报过：没地方选）=====
			{
				triggerSpec.Kind = "PowerChanged";
				UpdateLayout();
				DependencyObject powerPage = SelectTabRoot("自定义状态");
				List<ComboBox> powerCombos = new List<ComboBox>();
				CollectCombos(powerPage, powerCombos);
				List<SearchComboBox> powerSearch = new List<SearchComboBox>();
				CollectSearchCombos(powerPage, powerSearch);
				// 「盯哪个状态」现在是可搜索下拉（和「增益 / 减益」一样的控件），所以两种都查
				DependencyObject? watchBox = powerCombos.FirstOrDefault((ComboBox c) =>
						BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "PowerId")
					?? (DependencyObject?)powerSearch.FirstOrDefault((SearchComboBox c) =>
						BindingOperations.GetBinding(c, SearchComboBox.SelectedValueProperty)?.Path?.Path == "PowerId");
				SearchComboBox? watchSearch = watchBox as SearchComboBox;
				Check("「自定义状态」页上有「盯哪个状态」的下拉并绑在 PowerId 上", watchBox != null,
					$"{powerCombos.Count} 个下拉 + {powerSearch.Count} 个搜索框，找到={(watchBox != null)}");
				Check("「盯哪个状态」下拉是可搜索的（和「增益 / 减益」一样能打字过滤）",
					watchSearch != null && watchSearch.SearchPath == "Display" && watchSearch.ItemsSource == AllPowers,
					watchSearch is null ? "不是可搜索控件" : $"SearchPath={watchSearch.SearchPath}");
				if (watchBox != null)
				{
					// 它的显示/隐藏跟着「这个触发时机需不需要选状态」走
					var holder = (System.Windows.FrameworkElement?)VisualTreeHelper.GetParent(watchBox);
					while (holder != null && !(holder is StackPanel)) holder = (System.Windows.FrameworkElement?)VisualTreeHelper.GetParent(holder);
					Check("这个下拉只在「某个状态层数变化后」时显示（绑 NeedsPower）",
						holder is not null && BindingOperations.GetBinding(holder, UIElement.VisibilityProperty)?.Path?.Path == "NeedsPower",
						holder is null ? "没找到容器" : (BindingOperations.GetBinding(holder, UIElement.VisibilityProperty)?.Path?.Path ?? "(没绑定)"));
					Check("选中的是「力量」时，说明里写出这个状态名",
						triggerSpec.Display.Contains("力量") || triggerSpec.Summary.Contains("力量") || triggerSpec.PowerId == "",
						triggerSpec.Display);
					triggerSpec.PowerId = "StrengthPower";
					UpdateLayout();
					Check("选了「力量」之后，界面上那行说明立刻写出「（力量）」",
						TriggerHint.Contains("力量") && CustomPowerDescriptionHint.Contains("力量"), TriggerHint);
				}
			}
			// 改「触发时做什么」——以前这里说明完全不变（用户反馈过两次）
			string hintBeforeEffect = TriggerHint;
			string descBeforeEffect = CustomPowerDescriptionHint;
			triggerSpec.Effects[0].Kind = "Damage";
			triggerSpec.Effects[0].Amount = 5m;
			triggerSpec.Effects[0].TargetSide = "Enemy";
			UpdateLayout();
			Check("改了「触发时做什么」后触发时机说明也跟着变", TriggerHint != hintBeforeEffect && TriggerHint.Contains("造成 5 点伤害"), TriggerHint);
			Check("改了「触发时做什么」后描述预览也跟着变", CustomPowerDescriptionHint != descBeforeEffect && CustomPowerDescriptionHint.Contains("造成 5 点伤害"), CustomPowerDescriptionHint);
			// 界面上真正显示的那几处文字也要变（只看属性不够：绑定断了的话属性对了、界面还是旧的）
			List<TextBlock> powerTexts = new List<TextBlock>();
			CollectTextBlocks(SelectTabRoot("自定义状态"), powerTexts);
			TextBlock? hintBlock = powerTexts.FirstOrDefault((TextBlock b) => BindingOperations.GetBinding(b, TextBlock.TextProperty)?.Path?.Path == "TriggerHint");
			TextBlock? summaryBlock = powerTexts.FirstOrDefault((TextBlock b) => BindingOperations.GetBinding(b, TextBlock.TextProperty)?.Path?.Path == "CustomTriggersSummary");
			TextBlock? previewBlock = powerTexts.FirstOrDefault((TextBlock b) => BindingOperations.GetBinding(b, TextBlock.TextProperty)?.Path?.Path == "CustomPowerDescriptionHint");
			Check("页面上真有显示「触发时机说明」的文字块", hintBlock != null);
			Check("页面上真有显示「行为汇总」的文字块（就在「触发时机（什么时候做事）」下面）", summaryBlock != null);
			Check("页面上真有显示「描述预览」的文字块", previewBlock != null);
			Check("界面上那句触发时机说明真的显示了「做什么」",
				hintBlock != null && hintBlock.Text.Contains("造成 5 点伤害"), hintBlock?.Text ?? "(没找到)");
			Check("界面上那行行为汇总真的显示了「做什么」",
				summaryBlock != null && summaryBlock.Text.Contains("造成 5 点伤害"), summaryBlock?.Text ?? "(没找到)");
			Check("界面上那行描述预览真的显示了「做什么」",
				previewBlock != null && previewBlock.Text.Contains("造成 5 点伤害"), previewBlock?.Text ?? "(没找到)");
			// 加一条效果 / 删一条效果
			string hintBeforeAdd = TriggerHint;
			triggerSpec.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m });
			UpdateLayout();
			Check("加一条效果后说明里会多出那条效果", TriggerHint != hintBeforeAdd && TriggerHint.Contains("抽 1 张牌"), TriggerHint);
			Check("加一条效果后界面上那行汇总也会多出那条效果",
				summaryBlock != null && summaryBlock.Text.Contains("抽 1 张牌"), summaryBlock?.Text ?? "(没找到)");
			Check("加一条效果后「触发时机列表」那一行也跟着变",
				triggerSpec.Display.Contains("抽牌 1"), triggerSpec.Display);
			triggerSpec.Effects.RemoveAt(1);
			UpdateLayout();
			Check("删掉效果后说明里那条也没了", !TriggerHint.Contains("抽 1 张牌"), TriggerHint);
			Check("删掉效果后列表那一行也没了", !triggerSpec.Display.Contains("抽牌 1"), triggerSpec.Display);
			powerSpec.Triggers.Clear();
		}
		SelectTabRoot("卡牌");
		// ===== 从工程恢复存档（存档被误覆盖时的救命功能）=====
		string recRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_recover_" + Guid.NewGuid().ToString("N").Substring(0, 8));
		try
		{
			CharacterProfile recSrc = ProfileFactory.Sample();
			recSrc.Paths.OutputDir = recRoot;
			recSrc.Paths.VanillaProject = Profile.Paths.VanillaProject;   // 生成要用解包工程（占位美术 / 场景）
			recSrc.Paths.GameDataDir = Profile.Paths.GameDataDir;
			recSrc.ExtraResource.Enabled = true;
			recSrc.ExtraResource.Name = "血怒";
			// 注意：列表最上面两条是初始卡组的本体卡（打击 / 防御），比较要挑「自己的卡」
			List<CardSpec> srcOwn = recSrc.Cards.Where((CardSpec c) => !c.IsVanillaCard).ToList();
			srcOwn[0].Effects[0].Times = 2;                  // 生效次数
			srcOwn[1].UpgradeCost = 0;                       // 升级后费用（1 费 → 0 费，差值才不是 0）
			srcOwn[1].UpgradeKeywords.Innate = "Add";         // 升级后获得关键字
			srcOwn[1].Effects[0].Condition.Kind = "HandAtLeast";
			srcOwn[1].Effects[0].Condition.Amount = 3m;
			// 「战斗胜利后」的卡牌奖励（生成的是 AfterCombatEnd）：恢复时也要能认出这条触发时机
			CustomPowerSpec recPower = new CustomPowerSpec { Name = "恢复用奖励状态" };
			PowerTriggerSpec recVictory = new PowerTriggerSpec { Kind = "CombatVictory" };
			recVictory.Effects.Add(new EffectSpec { Kind = "CardReward", Amount = 3m, TargetSide = "Self" });
			recPower.Triggers.Add(recVictory);
			recSrc.CustomPowers.Add(recPower);
			// 自定义关键词：一条自己填英文标识、一条留空（走自动键 KEYWORD_2），都挂在第一张自有卡上
			recSrc.CustomKeywords.Add(new CustomKeywordSpec
			{
				Name = "命定",
				Key = "FATE",
				Description = "打出后，本回合每打出一张牌就抽一张。",
			});
			recSrc.CustomKeywords.Add(new CustomKeywordSpec
			{
				Name = "回响",
				Description = "第二条关键词（没填英文标识，走自动键）。",
			});
			// 本体关键词改名（这一节和「自定义关键词」共用同一张 card_keywords 表）：
			// 一条改名、一条**只改说明**（只改说明时表里只有 description 键 —— 回读不能把它丢了）
			recSrc.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "EXHAUST", Name = "献祭" });
			recSrc.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "INNATE", Description = "开局就在手里。" });
			srcOwn[0].KeywordIds = new List<string> { "FATE", "回响" };
			// 强化指定卡牌（像「精准」）：目标卡 / 强化什么 / 数值都要能从工程读回来（靠 // CET:BoostCard= 标记）
			srcOwn[0].Effects.Add(new EffectSpec
			{
				Kind = "BoostCard", Amount = 3m, UpgradeAmount = 1m,
				SpawnCardId = "SevenCrush", BoostStat = "Damage", TargetSide = "Self",
			});
			// 卡牌自定义描述（追加模式 + 多行）：靠 .cs 里的 // CET:CustomDescription= 标记读回来
			srcOwn[2].CustomDescription = "自检：第一行\n第二行";
			// 另一种模式：整段替换掉自动描述（标记里的 CustomDescReplace=1 也要读回来）
			srcOwn[3].CustomDescription = "自检：只留这段话。";
			srcOwn[3].CustomDescriptionReplaces = true;
			// 诅咒 + 先古卡：回读时也要各自回到「诅咒 / 先古卡」页的那两个列表里（按稀有度分）
			var recCurse = new CardSpec
			{
				Name = "恢复用诅咒", ClassName = "UiCheckRecCurse", CardType = "Curse", Rarity = "Curse",
				Cost = -1, Unplayable = true, Eternal = true, CurseRemoveAfterCombat = true,
			};
			recCurse.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 3m, TargetSide = "Self" });
			recSrc.Curses.Add(recCurse);
			var recAncient = new CardSpec
			{
				Name = "恢复用先古卡", ClassName = "UiCheckRecAncient", CardType = "Skill", Rarity = "Ancient", Cost = 1,
				InCardPool = true,
			};
			recAncient.Effects.Add(new EffectSpec { Kind = "Block", Amount = 11m, UpgradeAmount = 4m, TargetSide = "Self" });
			recSrc.AncientCards.Add(recAncient);
			// 两类牌各自的卡框 + 角色自己的自定义框色，回读时要能从生成的代码 / 材质文件读回来。
			// 诅咒这份用**本体框色名**（「自定义颜色」已经在界面上去掉了，见 CurseStyle.AllowsCustomColor）；
			// 先古卡那份用「自定义颜色」，走材质文件的 h/s/v 反算。
			recSrc.CurseStyle.Frame = "card_frame_curse";
			recSrc.AncientStyle.Frame = SpecialCardStyleSpec.CustomFrame;
			recSrc.AncientStyle.FrameColor = "8A5CF6";
			recSrc.Colors.CardFrameColor = "123456";
			var gen = ModGenerator.Generate(recSrc);
			// 失败时把「为什么」打出来（校验错误 + 日志尾部）—— 不然这条 FAIL 只有空细节，根本没法查
			Check("（准备）能从示例配置生成工程", gen.Success && Directory.Exists(gen.ProjectRoot),
				gen.Success
					? gen.ProjectRoot
					: (string.Join(" | ", gen.Issues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(4))
					   + "  ‖ 日志尾部：" + string.Join(" ‖ ", gen.Log.TakeLast(8))));
			// ===== 自定义关键词：本地化表 / 悬停说明 / 卡面描述，三处产物都要有 =====
			string kwLocPath = Path.Combine(gen.ProjectRoot, recSrc.ModId, "localization", "zhs", "card_keywords.json");
			Check("自定义关键词：生成了 card_keywords.json（写进本体那张表）", File.Exists(kwLocPath), kwLocPath);
			string kwLoc = File.Exists(kwLocPath) ? File.ReadAllText(kwLocPath, Encoding.UTF8) : "";
			Check("自定义关键词：表里有 FATE.title = 命定 和说明",
				kwLoc.Contains("\"FATE.title\": \"命定\"") && kwLoc.Contains("FATE.description"), kwLoc.Replace("\r", "").Replace("\n", " "));
			Check("自定义关键词：没填英文标识的那条自动用 KEYWORD_2",
				kwLoc.Contains("KEYWORD_2.title") && kwLoc.Contains("\"KEYWORD_2.title\": \"回响\""), "KEYWORD_2.title = 回响");
			string kwCardFile = Path.Combine(gen.ProjectRoot, "cs", "Cards",
				Naming.From(recSrc).CardClassName(recSrc, srcOwn[0]) + ".cs");
			string kwCardSrc = File.Exists(kwCardFile) ? File.ReadAllText(kwCardFile, Encoding.UTF8) : "";
			Check("自定义关键词：卡牌生成了悬停说明（读本体 card_keywords 表）",
				kwCardSrc.Contains("LocString(\"card_keywords\", \"FATE.title\")")
				&& kwCardSrc.Contains("LocString(\"card_keywords\", \"KEYWORD_2.description\")"), "两条都在");
			string kwCardsLoc = File.ReadAllText(Path.Combine(gen.ProjectRoot, recSrc.ModId, "localization", "zhs", "cards.json"), Encoding.UTF8);
			Check("自定义关键词：卡面描述最前面是 [gold]命定[/gold]。",
				kwCardsLoc.Contains("[gold]命定[/gold]。"), "描述里有");
			Check("自定义关键词：两条都按引用顺序拼进卡面描述（一行一个）",
				kwCardsLoc.Contains("[gold]命定[/gold]。\\n[gold]回响[/gold]。"), "命定 → 回响");
			// ===== 本体关键词改名：写进本体 card_keywords 表 + 旧名字全文替换 =====
			Check("本体关键词改名：EXHAUST.title 写成了新名字（本体卡面上的金色词会跟着变）",
				kwLoc.Contains("\"EXHAUST.title\": \"献祭\""), "EXHAUST.title = 献祭");
			Check("本体关键词改名：没动 PERIOD（那是标点占位键，不是关键词）",
				!kwLoc.Contains("PERIOD"), "表里没有 PERIOD");
			// 规则（写进表的边界）：Name 填了才写 <ID>.title、Description 填了才写 <ID>.description，
			// **一个字都没填的关键词一个键都不许写** —— 写了就等于拿空 / 兜底值覆盖本体那条。
			Check("本体关键词改名：一个字都没填的关键词（虚无 / 保留 / 奇巧 / 永恒 / 不能被打出）不会被写进表里",
				!kwLoc.Contains("ETHEREAL.") && !kwLoc.Contains("RETAIN.")
				&& !kwLoc.Contains("SLY.") && !kwLoc.Contains("ETERNAL.") && !kwLoc.Contains("UNPLAYABLE."),
				kwLoc.Replace("\r", "").Replace("\n", " "));
			// 本用例里 INNATE 只填了说明：那就只该有 description 键，**绝不能**有 title
			//（有了就说明「没填名字也写了 title」→ 本体那个名字被空值覆盖）。
			Check("本体关键词改名：只填说明的关键词只写 <ID>.description、不写 <ID>.title",
				kwLoc.Contains("\"INNATE.description\"") && !kwLoc.Contains("INNATE.title"),
				kwLoc.Replace("\r", "").Replace("\n", " "));
			Check("本体关键词改名：只填名字（说明留空）时不会把本体说明覆盖成空串",
				!kwLoc.Contains("\"EXHAUST.description\""), "没写 description 键");
			{
				// 旧名字全文替换：本体卡牌/遗物/药水描述里写着的「消耗」要换成「献祭」。
				// 本机不一定读得到本体中文表，所以这里先往表里塞一条**合成**条目
				// （只加一个绝不和本体撞的键），把「替换 + 合并进 cards.json」这条链路验死。
				IReadOnlyDictionary<string, string> oldCardLoc = EffectCatalog.InjectCardLocForTest(
					new[] { new KeyValuePair<string, string>("UICHECK_KEYWORD_TEXT_1.description", "消耗 1 张牌。") });
				try
				{
					List<(string Table, string Key, string Text)> kwText =
						VanillaKeywordGen.KeywordTextReplacements(recSrc).ToList();
					Check("本体关键词改名：本体卡面描述里的旧名字会被换掉（消耗 → 献祭）",
						kwText.Any((r) => r.Table == "cards" && r.Key == "UICHECK_KEYWORD_TEXT_1.description"
							&& r.Text.Contains("献祭") && !r.Text.Contains("消耗")),
						$"{kwText.Count} 条替换项");
					// 替换是**按本体表逐条**做的，所以每条替换项的键必须在「它自己那张本体表」里
					//（以前拿 cards 表去查 relics / potions 的键 → 必然查不到，白白 FAIL）。
					static bool InOwnTable((string Table, string Key, string Text) r) => r.Table switch
					{
						"cards" => EffectCatalog.ZhCardLoc.ContainsKey(r.Key),
						"relics" => EffectCatalog.ZhRelicLoc.ContainsKey(r.Key),
						"potions" => EffectCatalog.ZhPotionLoc.ContainsKey(r.Key),
						_ => false,
					};
					List<string> strayKeys = kwText.Where((r) => !InOwnTable(r)).Select((r) => r.Table + " / " + r.Key).ToList();
					Check("本体关键词改名：替换项只覆盖本体本来就有那个键的条目（不会给我们的自定义卡造键）",
						strayKeys.Count == 0,
						strayKeys.Count == 0
							? $"{kwText.Count} 条替换项，键都在各自的本体表里"
							  + $"（cards {kwText.Count((r) => r.Table == "cards")} / relics {kwText.Count((r) => r.Table == "relics")} / potions {kwText.Count((r) => r.Table == "potions")}）"
							: "不在本体表里的键：" + string.Join(" ｜ ", strayKeys.Take(5)));
					Check("本体关键词改名：没填名字（只改说明）的关键词不产生替换项",
						VanillaKeywordGen.KeywordTextReplacements(ProfileWithKeywordRename("EXHAUST", "", "只改说明")).Count() == 0,
						"没改名 → 不替换");
					Check("本体关键词改名：新名字和本体原名一样时也不产生替换项",
						VanillaKeywordGen.KeywordTextReplacements(ProfileWithKeywordRename("EXHAUST", "消耗", "")).Count() == 0,
						"等于没改 → 不替换");
					var kwTextGen2 = ModGenerator.Generate(recSrc);
					string kwCards2 = File.ReadAllText(Path.Combine(kwTextGen2.ProjectRoot, recSrc.ModId, "localization", "zhs", "cards.json"), Encoding.UTF8);
					Check("本体关键词改名：替换项真的合进了生成的 cards.json",
						kwCards2.Contains("献祭 1 张牌。"), "cards.json 里已是新名字");
				}
				finally
				{
					EffectCatalog.InjectCardLocForTest(oldCardLoc);
				}
			}
			// 校验：id 非法 / 名字带富文本标记 / 和别的本体关键词撞名 → 都必须是错误
			// 注意：这几份配置要带上「环境路径」，否则校验器还会报「解包工程目录不存在」那两条，
			// 第一条错误就不是我们要查的那条了。
			CharacterProfile badRename = RenameCheckProfile();
			badRename.KeywordRenames.Clear();
			badRename.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "NOT_A_KEYWORD", Name = "随便" });
			Check("本体关键词改名：枚举名不是那 7 个之一 → 错误",
				ProfileValidator.Validate(badRename).Any((ValidationIssue i) => i.IsError && i.Message.Contains("不是本体关键词")),
				ProfileValidator.Validate(badRename).First((ValidationIssue i) => i.IsError).Message);
			CharacterProfile badRich = RenameCheckProfile();
			badRich.KeywordRenames.Clear();
			badRich.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "EXHAUST", Name = "[gold]烧掉[/gold]" });
			Check("本体关键词改名：新名字里带 [ ] 富文本标记 → 错误（会把卡面 [gold]…[/gold] 解析坏）",
				ProfileValidator.Validate(badRich).Any((ValidationIssue i) => i.IsError && i.Message.Contains("方括号")),
				ProfileValidator.Validate(badRich).First((ValidationIssue i) => i.IsError).Message);
			CharacterProfile badClash = RenameCheckProfile();
			badClash.KeywordRenames.Clear();
			badClash.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "EXHAUST", Name = "虚无" });   // 和本体「虚无」撞名
			ProfileFactory.EnsureKeywordRenameRows(badClash);
			Check("本体关键词改名：新名字和另一个本体关键词撞车 → 错误（玩家分不清这两条）",
				ProfileValidator.Validate(badClash).Any((ValidationIssue i) => i.IsError && i.Message.Contains("撞车")),
				ProfileValidator.Validate(badClash).FirstOrDefault((ValidationIssue i) => i.IsError)?.Message ?? "(没有错误)");
			CharacterProfile dupRename = RenameCheckProfile();
			dupRename.KeywordRenames.Clear();
			dupRename.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "EXHAUST", Name = "燃烧" });
			dupRename.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "ETHEREAL", Name = "燃烧" });
			ProfileFactory.EnsureKeywordRenameRows(dupRename);
			Check("本体关键词改名：两条改成同一个新名字也会被撞车检查拦住",
				ProfileValidator.Validate(dupRename).Any((ValidationIssue i) => i.IsError && i.Message.Contains("撞车")),
				ProfileValidator.Validate(dupRename).FirstOrDefault((ValidationIssue i) => i.IsError)?.Message ?? "(没有错误)");
			CharacterProfile goodRename = RenameCheckProfile();
			goodRename.KeywordRenames.Clear();
			goodRename.KeywordRenames.Add(new VanillaKeywordRenameSpec { KeywordId = "EXHAUST", Name = "献祭", Description = "打出后进入献祭堆。" });
			ProfileFactory.EnsureKeywordRenameRows(goodRename);
			Check("本体关键词改名：合法改名不会被校验器拦（改成「献祭」→ 不撞车、没富文本）",
				!ProfileValidator.Validate(goodRename).Any((ValidationIssue i) => i.IsError && i.Message.Contains("本体关键词")),
				string.Join(" | ", ProfileValidator.Validate(goodRename).Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message)));
			// 「自定义关键词」页最上面那一节：表格必须一直有那 7 行，而且绑到存档上
			Check("本体关键词改名：界面上是固定 7 行（本体关键词是封闭枚举，不能增删）",
				KeywordRenameTable != null && Profile.KeywordRenames.Count == VanillaKeywordCatalog.All.Count,
				KeywordRenameTable is null ? "没找到表格" : $"{Profile.KeywordRenames.Count} 行");
			Check("本体关键词改名：表格绑的是 Profile.KeywordRenames",
				KeywordRenameTable != null && ReferenceEquals(KeywordRenameTable.ItemsSource, Profile.KeywordRenames),
				KeywordRenameTable?.ItemsSource?.GetType().Name ?? "(没绑)");
			// 关键回归测试：工程目录 = 存档名（不是 ModId）。以前构建流程自己拼 OutputDir\ModId，
			// 存档名和 ModId 不一样时（示例角色_恢复.json / ModId=示例角色）会指向不存在的目录 →
			// dotnet 报 MSB1009 → 界面「构建失败」（用户报的「构建无法生成」）。
			recSrc.SaveName = "别的存档名";
			Check("工程目录跟着存档文件名走（不是 ModId）",
				ModGenerator.ProjectRootOf(recSrc) == Path.Combine(recSrc.Paths.OutputDir, "别的存档名"),
				ModGenerator.ProjectRootOf(recSrc));
			Check("构建流程用的目录 == 生成器返回的目录（存档名≠ModId 时也对得上，修过 MSB1009）",
				ModGenerator.ProjectRootOf(recSrc) != Path.Combine(recSrc.Paths.OutputDir, recSrc.ModId), "两者必须不同（这就是以前踩的坑）");
			var gen2 = ModGenerator.Generate(recSrc);
			Check("存档名≠ModId 时生成目录 = ProjectRootOf 算出来的目录",
				gen2.Success && gen2.ProjectRoot == ModGenerator.ProjectRootOf(recSrc), gen2.ProjectRoot);
			var rec = ProjectRecovery.FromProject(gen.ProjectRoot);
			// 回读时会按 7 行本体关键词补齐（见 ProfileFactory.EnsureKeywordRenameRows）：
			// 恢复出来的存档里这 7 行要都在，界面表格才不会少行
			ProfileFactory.EnsureKeywordRenameRows(rec.Profile);
			Check("从工程恢复：没认出来的语句为 0", !rec.HasUnparsed, rec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			Check("从工程恢复：卡牌张数一致", rec.Profile.Cards.Count == recSrc.Cards.Count, $"{rec.Profile.Cards.Count} / {recSrc.Cards.Count}");
			Check("从工程恢复：初始的打击 / 防御也找回来了（含 CardTag 标签），并且排在最上面",
				rec.Profile.Cards[0].ClassName == "Strike" && rec.Profile.Cards[1].ClassName == "Defend"
				&& rec.Profile.Cards[0].TagList.Contains("Strike") && rec.Profile.Cards[1].TagList.Contains("Defend"),
				string.Join(" / ", rec.Profile.Cards.Take(3).Select((CardSpec c) => c.Name)));
			List<CardSpec> recOwn = rec.Profile.Cards.Where((CardSpec c) => !c.IsVanillaCard).ToList();
			Check("从工程恢复：卡名一致（中文名从本地化表读回来）",
				recOwn[0].Name == srcOwn[0].Name, recOwn[0].Name);
			Check("从工程恢复：自定义关键词找回来了（名字 / 说明 / 英文标识 / 自动键）",
				rec.Profile.CustomKeywords.Count == 2
				&& rec.Profile.CustomKeywords.Any((CustomKeywordSpec k) => k.Key == "FATE" && k.Name == "命定" && k.Description.Contains("抽一张"))
				&& rec.Profile.CustomKeywords.Any((CustomKeywordSpec k) => k.Key == "KEYWORD_2" && k.Name == "回响"),
				string.Join(" · ", rec.Profile.CustomKeywords.Select((CustomKeywordSpec k) => k.Display)));
			Check("从工程恢复：卡牌上的关键词引用找回来了",
				recOwn[0].CustomKeywordList.Contains("FATE") && recOwn[0].CustomKeywordList.Contains("KEYWORD_2"),
				string.Join("·", recOwn[0].CustomKeywordList));
			// 本体关键词改名：在「自定义关键词」页最上面那一节填的 7 行，也要能从工程读回来
			// （以前这里把本体那 7 个键直接 continue 丢掉 → 恢复后改名静默消失，再生成卡面就变回「消耗」）
			Check("从工程恢复：本体关键词改名（消耗 → 献祭）找回来了",
				rec.Profile.KeywordRenames.Any((VanillaKeywordRenameSpec r) => r.KeywordId == "EXHAUST" && r.Name == "献祭"),
				string.Join(" · ", rec.Profile.KeywordRenames.Where((VanillaKeywordRenameSpec r) => r.ChangesAnything).Select((VanillaKeywordRenameSpec r) => r.Display)));
			Check("从工程恢复：只改了说明的关键词（固有）也找回来了",
				rec.Profile.KeywordRenames.Any((VanillaKeywordRenameSpec r) => r.KeywordId == "INNATE" && r.Description == "开局就在手里。"),
				string.Join(" · ", rec.Profile.KeywordRenames.Where((VanillaKeywordRenameSpec r) => r.ChangesAnything).Select((VanillaKeywordRenameSpec r) => r.Display)));
			Check("从工程恢复：没改的关键词不会凭空变出一条改名（虚无 / 保留 … 都还是空的）",
				rec.Profile.KeywordRenames.Count((VanillaKeywordRenameSpec r) => r.ChangesAnything) == 2,
				$"改了 {rec.Profile.KeywordRenames.Count((VanillaKeywordRenameSpec r) => r.ChangesAnything)} 条");
			Check("从工程恢复：费用 / 类型 / 稀有度一致",
				recOwn[0].Cost == srcOwn[0].Cost && recOwn[0].CardType == srcOwn[0].CardType
				&& recOwn[0].Rarity == srcOwn[0].Rarity,
				$"{recOwn[0].Cost}费 {recOwn[0].CardType} {recOwn[0].Rarity}");
			Check("从工程恢复：效果条数一致",
				recOwn[0].Effects.Count == srcOwn[0].Effects.Count,
				$"{recOwn[0].Effects.Count} / {srcOwn[0].Effects.Count}");
			Check("从工程恢复：效果数值一致（升级增量也算）",
				recOwn[0].Effects.Select(x => x.Amount + x.UpgradeAmount).SequenceEqual(srcOwn[0].Effects.Select(x => x.Amount + x.UpgradeAmount)),
				string.Join(" / ", recOwn[0].Effects.Select(x => $"{x.Kind} {x.Amount}+{x.UpgradeAmount}")));
			Check("从工程恢复：目标对象一致", recOwn[0].Effects.Select(x => x.TargetSide).SequenceEqual(srcOwn[0].Effects.Select(x => x.TargetSide)),
				string.Join(" / ", recOwn[0].Effects.Select(x => x.TargetSide)));
			Check("从工程恢复：生效次数一致", recOwn[0].Effects[0].Times == 2, recOwn[0].Effects[0].Times.ToString());
			Check("从工程恢复：升级后费用一致", recOwn[1].UpgradeCost == 0, recOwn[1].UpgradeCost?.ToString() ?? "(空)");
			Check("从工程恢复：升级后的关键字一致", recOwn[1].UpgradeKeywords.Innate == "Add", recOwn[1].UpgradeKeywords.Display);
			Check("从工程恢复：效果条件一致（手牌数不少于 3 张）",
				recOwn[1].Effects[0].Condition.Kind == "HandAtLeast" && recOwn[1].Effects[0].Condition.Amount == 3m,
				recOwn[1].Effects[0].Condition.DisplayShort);
			Check("从工程恢复：遗物 / 药水数量一致",
				rec.Profile.Relics.Count == recSrc.Relics.Count && rec.Profile.Potions.Count == recSrc.Potions.Count,
				$"遗物 {rec.Profile.Relics.Count} / {recSrc.Relics.Count}，药水 {rec.Profile.Potions.Count} / {recSrc.Potions.Count}");
			Check("从工程恢复：遗物触发时机一致", rec.Profile.Relics[0].Trigger == recSrc.Relics[0].Trigger, rec.Profile.Relics[0].Trigger);
			Check("从工程恢复：状态的「战斗胜利后」也认得出来（生成的是 AfterCombatEnd，不是 AfterCombatVictory）",
				rec.Profile.CustomPowers.Count == 1
				&& rec.Profile.CustomPowers[0].Triggers.Count == 1
				&& rec.Profile.CustomPowers[0].Triggers[0].Kind == "CombatVictory"
				&& rec.Profile.CustomPowers[0].Triggers[0].Effects.Count == 1
				&& rec.Profile.CustomPowers[0].Triggers[0].Effects[0].Kind == "CardReward",
				rec.Profile.CustomPowers.Count == 1
					? string.Join(" / ", rec.Profile.CustomPowers[0].Triggers.Select((PowerTriggerSpec t) => t.Kind + "(" + t.Effects.Count + " 条)"))
					: $"恢复了 {rec.Profile.CustomPowers.Count} 个状态");
			Check("从工程恢复：角色属性一致（血量 / 金币 / 职业名）",
				rec.Profile.StartingHp == recSrc.StartingHp && rec.Profile.StartingGold == recSrc.StartingGold && rec.Profile.CharacterClass == recSrc.CharacterClass,
				$"{rec.Profile.StartingHp}/{rec.Profile.StartingGold} {rec.Profile.CharacterClass}");
			Check("从工程恢复：额外资源量名字找回来了", rec.Profile.ExtraResource.Name == "血怒", rec.Profile.ExtraResource.Name);
			Check("从工程恢复：初始卡组 / 卡池归属找回来了",
				recOwn[0].InStartingDeck && recOwn[0].StartingCopies == srcOwn[0].StartingCopies
				&& rec.Profile.Cards.Count(c => !c.InCardPool) == recSrc.Cards.Count(c => !c.InCardPool),
				$"初始 {recOwn[0].StartingCopies} 张 / 不入池 {rec.Profile.Cards.Count(c => !c.InCardPool)} 张");
			Check("从工程恢复：强化指定卡牌找回来了（目标卡 / 伤害还是格挡 / 数值 / 升级增量）",
				recOwn[0].Effects.Any((EffectSpec x) => x.Kind == "BoostCard" && x.SpawnCardId == "SevenCrush"
					&& x.BoostStat == "Damage" && x.Amount == 3m && x.UpgradeAmount == 1m),
				string.Join(" / ", recOwn[0].Effects.Select((EffectSpec x) => $"{x.Kind} {x.Amount}+{x.UpgradeAmount} {x.SpawnCardId}")));
			Check("从工程恢复：卡牌自定义描述找回来了（多行也完整，没被截成一行）",
				recOwn[2].CustomDescription == "自检：第一行\n第二行" && !recOwn[2].CustomDescriptionReplaces,
				(recOwn[2].CustomDescription ?? "(空)").Replace("\n", "\\n"));
			Check("从工程恢复：勾了「替换掉自动描述」的那张也找回来了",
				recOwn[3].CustomDescription == "自检：只留这段话。" && recOwn[3].CustomDescriptionReplaces,
				$"{(recOwn[3].CustomDescription ?? "(空)")} / 替换={recOwn[3].CustomDescriptionReplaces}");
			Check("从工程恢复：诅咒回到「诅咒」列表里（不是混进普通卡），效果也读回来了",
				rec.Profile.Curses.Count == 1
				&& rec.Profile.Curses[0].Name == "恢复用诅咒"
				&& rec.Profile.Curses[0].Rarity == "Curse"
				&& rec.Profile.Curses[0].Cost == -1
				&& rec.Profile.Curses[0].Eternal
				&& rec.Profile.Curses[0].CurseRemoveAfterCombat
				&& rec.Profile.Curses[0].Effects.Any(x => x.Kind == "HpLoss" && x.Amount == 3m),
				rec.Profile.Curses.Count == 0 ? "一条都没恢复"
					: $"{rec.Profile.Curses[0].Name} / {rec.Profile.Curses[0].Rarity} / 费 {rec.Profile.Curses[0].Cost}"
					  + $" / 自删={rec.Profile.Curses[0].CurseRemoveAfterCombat}"
					  + $" / 效果={string.Join("、", rec.Profile.Curses[0].Effects.Select(x => x.Kind + " " + x.Amount + "+" + x.UpgradeAmount))}"
					  + $" / {string.Join("·", rec.Profile.Curses[0].KeywordList)}");
			Check("从工程恢复：先古卡回到「先古卡」列表里，数值 / 升级增量都在",
				rec.Profile.AncientCards.Count == 1
				&& rec.Profile.AncientCards[0].Rarity == "Ancient"
				&& rec.Profile.AncientCards[0].CardType == "Skill"
				&& rec.Profile.AncientCards[0].Effects.Any(x => x.Kind == "Block" && x.Amount == 11m && x.UpgradeAmount == 4m),
				rec.Profile.AncientCards.Count == 0 ? "一条都没恢复"
					: rec.Profile.AncientCards[0].Effects[0].Amount + "+" + rec.Profile.AncientCards[0].Effects[0].UpgradeAmount);
			Check("从工程恢复：诅咒 / 先古卡不会被算成普通卡（三张列表各归各位）",
				rec.Profile.Cards.All(x => x.Rarity != "Curse" && x.Rarity != "Ancient"), "各归各位");
			Check("从工程恢复：诅咒选了本体框色（card_frame_curse）也认得出来",
				rec.Profile.CurseStyle.Frame == "card_frame_curse" && rec.Profile.CurseStyle.FrameColor.Length == 0
				&& !rec.Profile.CurseStyle.IsCustomFrame,
				$"{rec.Profile.CurseStyle.Frame} / '{rec.Profile.CurseStyle.FrameColor}'");
			Check("从工程恢复：先古卡的自定义卡框颜色从材质文件的 h/s/v 反算回来了",
				rec.Profile.AncientStyle.Frame == SpecialCardStyleSpec.CustomFrame && rec.Profile.AncientStyle.FrameColor == "8A5CF6",
				$"{rec.Profile.AncientStyle.Frame} / {rec.Profile.AncientStyle.FrameColor}");
			Check("从工程恢复：角色自己的自定义边框颜色也读回来了（以前路径写错，一直静默退回默认红）",
				rec.Profile.Colors.CardFrameColor == "123456", rec.Profile.Colors.CardFrameColor);
		}
		catch (Exception ex)
		{
			Check("从工程恢复存档（整体）", ok: false, ex.GetType().Name + ": " + ex.Message + "  @" + string.Join(" | ", (ex.StackTrace ?? "").Split('\n').Take(4).Select((string s) => s.Trim())));
		}
		finally
		{
			try { Directory.Delete(recRoot, true); } catch { }
		}

		// ===== 召唤物（列表 + 独立选项卡；本体的通用宠物 API，不需要 Harmony 补丁）=====
		// ① 界面接线：选项卡位置 / 列表绑定 / 详情里的字段 / 效果编辑器的「召唤物」下拉
		{
			TabItem summonTabItem = FindTab("召唤物");
			Check("有「召唤物」选项卡", summonTabItem != null, summonTabItem is null ? "没找到" : "找到了");
			int idxRole = -1, idxSummon = -1, idxExtra = -1, idxCard = -1, idxParam = -1, idxForge = -1, idxRelic = -1, idxPotion = -1;
			int idxCurse = -1, idxKeyword = -1, idxAncient = -1, idxPowerOverride = -1, idxCustomPower = -1, idxArt = -1;
			for (int ti = 0; ti < MainTabs.Items.Count; ti++)
			{
				if (!(MainTabs.Items[ti] is TabItem t)) continue;
				switch ((t.Header as string) ?? "")
				{
					case "角色": idxRole = ti; break;
					case "召唤物": idxSummon = ti; break;
					case "额外资源量": idxExtra = ti; break;
					case "卡牌": idxCard = ti; break;
					case "自定义参数 / 组": idxParam = ti; break;
					case "锻造": idxForge = ti; break;
					case "遗物": idxRelic = ti; break;
					case "药水": idxPotion = ti; break;
					case "诅咒 / 先古 / 状态": idxCurse = ti; break;
					case "自定义关键词": idxKeyword = ti; break;
					case "先古之民": idxAncient = ti; break;
					case "本体状态改写": idxPowerOverride = ti; break;
					case "自定义状态": idxCustomPower = ti; break;
					case "美术资源": idxArt = ti; break;
				}
			}
			Check("选项卡顺序：角色=0、召唤物=1、额外资源量=2、卡牌=3、自定义参数 / 组=4、锻造=5、遗物=6、药水=7、诅咒 / 先古 / 状态=8、自定义关键词=9、先古之民=10、本体状态改写=11、自定义状态=12、美术资源=13",
				idxRole == 0 && idxSummon == 1 && idxExtra == 2 && idxCard == 3 && idxParam == 4 && idxForge == 5
				&& idxRelic == 6 && idxPotion == 7
				&& idxCurse == 8 && idxKeyword == 9 && idxAncient == 10 && idxPowerOverride == 11 && idxCustomPower == 12 && idxArt == 13,
				$"角色={idxRole} / 召唤物 {idxSummon} / 额外资源量 {idxExtra} / 卡牌={idxCard} / 自定义参数组={idxParam} / 锻造 {idxForge}"
				+ $" / 遗物={idxRelic} / 药水={idxPotion}"
				+ $" / 诅咒先古卡={idxCurse} / 自定义关键词={idxKeyword} / 先古之民={idxAncient} / 本体状态改写={idxPowerOverride} / 自定义状态={idxCustomPower} / 美术资源={idxArt}");

			// ===== 用户报的两个硬伤（问题清单第 1 / 2 条）：钉住，别回退 =====
			{
				// ① GIF 解码器：色表尺寸不能写 `(1 << (N+1)) & 31`（N=7 时算出 0 → 整条链错位，
				//    实测「真定 GIF 一律解不开」）。这里用真实 GIF 尺寸断言） 56 色的必须能解出来。"
				string gifProbe = Path.Combine(Path.GetTempPath(), "forge_uicheck_gifpal.gif");
				WriteSyntheticGif(gifProbe);
				var gif = GifFrames.Decode(gifProbe);
				Check("GIF 解码器：256 色（满色表）的真实结构能解开（色表尺寸不能再被 & 31 夹成 0）",
					gif is not null && gif.Width == 16 && gif.Height == 16 && gif.Frames.Count == 1,
					gif is null ? "解不开" : $"{gif.Width}x{gif.Height} {gif.Frames.Count} 帧");
				try { File.Delete(gifProbe); } catch { }

				// ① 空壳解包工程不能再「看着可用」：目录在、文件全是 1 字节时要判成不可用，
				//    这样才会去读 sts2.dll（以前直接 return false → 效果库为空 → 生成被拦死）。"
				string stubRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_stub_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				string stubPowers = Path.Combine(stubRoot, "src", "Core", "Models", "Powers");
				Directory.CreateDirectory(stubPowers);
				for (int i = 0; i < 12; i++) File.WriteAllText(Path.Combine(stubPowers, $"Fake{i}.cs"), " ");
				Check("空壳解包工程（1 字节的 *.cs）判成「不可用」→ 会去读 sts2.dll",
					!EffectCatalog.LooksLikeUsableVanillaSources(stubRoot, "src/Core/Models/Powers"), "判成不可用");
				File.WriteAllText(Path.Combine(stubPowers, "Real.cs"), "namespace X; public class Y { public int Z => 1; }");
				Check("只要有**一个**文件有真内容，就仍然认成可用工程（不误伤）",
					EffectCatalog.LooksLikeUsableVanillaSources(stubRoot, "src/Core/Models/Powers"), "认成可用");
				try { Directory.Delete(stubRoot, true); } catch { }

				// ① 元数据读取器本身：拿本机 sts2.dll 试（有就读，没有就跳过 —— 自检不能依赖游戏文件）"
				string? realDll = null;
				foreach (string? cand in new[]
				{
					Path.Combine(_profile?.Paths?.GameDataDir ?? "", "sts2.dll"),
					// 开发机上的那份：走**仓库相对路径**找（不写死绝对路径 —— 会被编进 DLL，发布自检会拦）"
					FindRepoFile(Path.Combine("..", "..", "..", "..", "4", "自定义角色存档", "SevenMod", "libs", "sts2.dll")),
				})
					if (cand is not null && File.Exists(cand)) { realDll = cand; break; }
				if (realDll is not null)
				{
					var powers = Sts2Metadata.Powers(realDll);
					var cards = Sts2Metadata.Cards(realDll);
					Check("sts2.dll 用**元数据**读得到类型（Assembly.GetTypes 会抛 / 打爆栈，不能用）",
						powers.Count > 100 && cards.Count > 100,
						$"状态 {powers.Count} / 卡牌 {cards.Count}");
					Check("元数据读出来的状态里，常见那几个都在",
						powers.Any(t => t.Name == "VulnerablePower") && powers.Any(t => t.Name == "WeakPower")
						&& powers.Any(t => t.Name == "StrengthPower"), "在");
					Check("元数据读取没有报错", Sts2Metadata.LastError is null, Sts2Metadata.LastError ?? "无错误");

					// 签名漂移核对那两条（用户报的「只有一条 FromCard 签名错、来回问 dll 太慢」）：
					// ① HasMethod 对真 dll 要能说「有」；② 说「没有」时，MethodOverloads 要把**真实签名**打出来
					Check("签名核对：本机 sts2.dll 上 AttackCommand.FromCard 有 2 参重载（工具生成端就是这么写死的）",
						Sts2Metadata.HasMethod(realDll, "AttackCommand", "FromCard", 2) == true,
						Sts2Metadata.HasMethod(realDll, "AttackCommand", "FromCard", 2)?.ToString() ?? "读不到");
					var fromCardOverloads = Sts2Metadata.MethodOverloads(realDll, "AttackCommand", "FromCard");
					Check("签名核对：漂移时能把「实际有哪些重载」打出来（不用再问用户要 dll）",
						fromCardOverloads.Count > 0
						&& fromCardOverloads.All(s => s.StartsWith("FromCard(", StringComparison.Ordinal))
						&& fromCardOverloads.Any(s => s.Contains("CardModel", StringComparison.Ordinal)),
						string.Join(" / ", fromCardOverloads));
					Check("签名核对：类型在但方法不在 → 明确 false（这才是「漂移」，不能拿 read 失败当 false）",
						Sts2Metadata.HasMethod(realDll, "AttackCommand", "NoSuchMethodXYZ", 2) == false
						&& Sts2Metadata.HasMethod(realDll, "NoSuchTypeXYZ", "FromCard", 2) == null,
						"方法不在=false / 类型不在=null");

					// 游戏版本核对：release_info.json → v0.111.0 这种；前两位不同才提示
					string? gameDir = Path.GetDirectoryName(Path.GetDirectoryName(realDll));
					string? gameVer = Sts2Metadata.GameVersion(gameDir);
					Check("版本核对：能从 release_info.json 读出本体版本",
						gameVer is not null && gameVer.StartsWith("v0.", StringComparison.OrdinalIgnoreCase), gameVer ?? "读不到");
					Check("版本核对：只比前两位（0.111.x 之间不打扰；0.112 才算不匹配）",
						!Sts2Metadata.VersionMismatch("v0.111.9") && Sts2Metadata.VersionMismatch("v0.112.0")
						&& !Sts2Metadata.VersionMismatch(null), "前两位比");
				}
				else Check("（跳过）本机没有 sts2.dll，元数据读取未实测", true, "跳过");
			}

			// ===== 「自定义参数 / 组」页（需求：新建「自定义参数/组」页） ====
			{
				DependencyObject paramRoot = SelectTabRoot("自定义参数 / 组");
				List<string> paramTexts = TextsIn(paramRoot);
				Check("自定义参数页有「新建参数」按钮与参数列表",
					paramTexts.Contains("新建参数") && ParamList != null, "控件在");
				Check("参数列表绑定到 Profile.CustomParams",
					BindingOperations.GetBinding(ParamList, ItemsControl.ItemsSourceProperty)?.Path?.Path == "Profile.CustomParams",
					BindingOperations.GetBinding(ParamList, ItemsControl.ItemsSourceProperty)?.Path?.Path ?? "(没绑定 ");
				Check("组列表绑定到 Profile.CardGroups",
					BindingOperations.GetBinding(GroupList, ItemsControl.ItemsSourceProperty)?.Path?.Path == "Profile.CardGroups",
					BindingOperations.GetBinding(GroupList, ItemsControl.ItemsSourceProperty)?.Path?.Path ?? "(没绑定 ");

				// 「新建参数」必须自动挑一个**没被占用**的字每 
				int before = Profile.CustomParams.Count;
				OnAddParam(this, new RoutedEventArgs());
				Check("点「新建参数」会自动生成一条参数", Profile.CustomParams.Count == before + 1, $"{before} → {Profile.CustomParams.Count}");
				ParamSpec created = Profile.CustomParams[Profile.CustomParams.Count - 1];
				// 参数右侧详情（「给予能量 / 给予额外资源量」两栏）要先选中这条参数才会出现在树里"
				ParamList.SelectedItem = created;
				UpdateLayout();
				Check("参数页有「给予能量 / 给予额外资源量」两个指定（需求：默认显示给予 X 参数给能量、给予 Y 参数给额外资源量）",
					TextsIn(paramRoot).Any(t => t.Contains("给予能量")) && TextsIn(paramRoot).Any(t => t.Contains("给予额外资源量")), "两栏在");
				Check("新参数的字母不是保留字 X / Y，也不和已有的重名",
					!ParamNames.Reserved.Contains(ParamNames.Normalize(created.Name), StringComparer.Ordinal)
					&& Profile.CustomParams.Count(x => string.Equals(ParamNames.Normalize(x.Name), ParamNames.Normalize(created.Name), StringComparison.Ordinal)) == 1,
					created.Name);

				// 来源下拉的候选必须就是需求里点名的那几项
				List<string> srcIds = ParamSourceOptions.Select(o => o.Id).ToList();
				Check("参数来源候选含「当前血量 / 最大生命 / 金币数 / 能量数 / 最大能量数 / 增益减益」",
					new[] { "CurrentHp", "MaxHp", "Gold", "Energy", "MaxEnergy", "Power" }.All(srcIds.Contains),
					string.Join(" / ", srcIds));
				created.Source = "MaxHp";
				created.Target = "Self";
				Check("选「自己 + 最大生命」时参数说明写成「自己的最大生命」",
					created.Summary.Contains("自己") && created.Summary.Contains("最大生命"), created.Summary);
				created.Source = "Power";
				created.Target = "ChosenEnemy";
				created.PowerId = "VulnerablePower";
				Check("选「指定敌人 + 易伤」时参数说明写成「指定敌人的…层数」",
					created.Summary.Contains("指定敌人") && created.Summary.Contains("层数"), created.Summary);
				// 「增益 / 减益」那一栏必须是**可搜索**下拉（本体 200+ 个状态，不打字很难找）"
				UpdateLayout();
				List<SearchComboBox> paramSearch = new List<SearchComboBox>();
				CollectSearchCombos(paramRoot, paramSearch);
				Check("参数页的「增益 / 减益」是可搜索下拉（不是普通下拉）",
					paramSearch.Any(sc => BindingOperations.GetBinding(sc, SearchComboBox.SelectedValueProperty)?.Path?.Path == "PowerId"),
					string.Join(" / ", paramSearch.Select(sc => BindingOperations.GetBinding(sc, SearchComboBox.SelectedValueProperty)?.Path?.Path)));

				// 组：新建 → 勾选一张卡 → 卡牌页也能看到这个勾选框
				int groupsBefore = Profile.CardGroups.Count;
				OnAddCardGroup(this, new RoutedEventArgs());
				Check("点「新建组」会创建一个可以命名的组", Profile.CardGroups.Count == groupsBefore + 1, $"{groupsBefore} → {Profile.CardGroups.Count}");
				CardGroupSpec group = Profile.CardGroups[Profile.CardGroups.Count - 1];
				group.Name = "自检组";
				if (Profile.Cards.Count == 0) OnAddCard(this, new RoutedEventArgs());
				CardSpec memberCard = Profile.Cards[0];
				MainWindow.SetCardGroupMembership(memberCard, group, true);
				Check("勾选后这张牌真的进了这个组（存的是组的 Id，改名字不会掉出去）",
					memberCard.GroupIdList.Contains(group.Id), string.Join(",", memberCard.GroupIdList));
				string oldGroupName = group.Name;
				group.Name = "自检组改名";
				Check("改组名之后这张牌还在组里",
					memberCard.GroupIdList.Contains(group.Id) && memberCard.GroupIdList.Contains(oldGroupName) == false,
					group.Name);
				Check("「范围」候选里有「组：XXX」这一档（需求：当选择范围时可以选择组）",
					CardGroupChoices.Any(c => c.Display == "组：自检组改名"), string.Join(" / ", CardGroupChoices.Select(c => c.Display)));
				// 这一档还要真的能当范围用：范围限定 / 范围界定 / 刮削条件三处共用同一件 SpawnFilter 字段
				Check("「组：XXX」真的接进了范围限定那份候选表（不只是界面装饰）",
					SpawnFilters.Any(f => f.Id == EffectCatalog.GroupFilterPrefix + group.Id && f.Display == "组：自检组改名"),
					string.Join(" / ", SpawnFilters.Select(f => f.Id)));
				Check("按组筛牌时查出来就是这一组里的牌（CardGroupCards）",
					EffectCatalog.CardGroupCards(Profile, EffectCatalog.GroupFilterPrefix + group.Id).Contains(memberCard),
					$"{EffectCatalog.CardGroupCards(Profile, EffectCatalog.GroupFilterPrefix + group.Id).Count} 张");
				Check("按组筛牌会翻成生成期的显式条件（和自定义关键词那一组同一套写法）",
					EffectCatalog.CardGroupCards(Profile, EffectCatalog.GroupFilterPrefix + group.Id).Count == 1
					&& EffectCatalog.IsCardGroupFilter(EffectCatalog.GroupFilterPrefix + group.Id)
					&& EffectCatalog.IsKnownScrapeCond(EffectCatalog.GroupFilterPrefix + group.Id),
					$"{EffectCatalog.CardGroupCards(Profile, EffectCatalog.GroupFilterPrefix + group.Id).Count} 张 / 前缀认得出来");

				// 清理：把自检造出来的东西删掉，别影响后面的断言
				MainWindow.SetCardGroupMembership(memberCard, group, false);
				Profile.CardGroups.Remove(group);
				Profile.CustomParams.Remove(created);
				RaiseGroupsChanged();
				RaiseParamsChanged();
			}

			// ===== 「锻造」页（需求：在卡牌页后新增「锻造」页） ====
			{
				DependencyObject forgeRoot = SelectTabRoot("锻造");
				List<string> forgeTexts = TextsIn(forgeRoot);
				Check("锻造页最左侧可以选「卡牌列表 / 药水列表 / 遗物列表」",
					forgeTexts.Contains("卡牌列表") && forgeTexts.Contains("药水列表") && forgeTexts.Contains("遗物列表"), "三个分类在");
				Check("锻造页**不再有**「自定义状态列表」那一类（用户要求删掉：自定义状态在「自定义状态」页配，别让人以为在锻造页也能配）",
					!forgeTexts.Contains("自定义状态列表"), forgeTexts.Contains("自定义状态列表") ? "还在" : "已删掉");
				Check("一类都没选时右侧提示「请选择卡牌、药水、遗物」",
					ForgeKindNone.IsChecked == true && ForgeNoKind && forgeTexts.Any(t => t.Contains("请选择卡牌、药水、遗物")),
					$"ForgeNoKind={ForgeNoKind}");

				// 选「卡牌列表」→ 添加 → 生成一项前缀带「*」的卡"
				ForgeKindCard.IsChecked = true;
				int cardsBefore = Profile.Cards.Count;
				OnAddForged(this, new RoutedEventArgs());
				Check("在锻造页点「添加」会生成一张卡", Profile.Cards.Count == cardsBefore + 1, $"{cardsBefore} → {Profile.Cards.Count}");
				CardSpec forged = Profile.Cards[Profile.Cards.Count - 1];
				Check("锻造出来的卡带 IsForged 标记、列表显示前缀有「*」",
					forged.IsForged && forged.Display.StartsWith("*", StringComparison.Ordinal), forged.Display);
				Check("锻造卡不显示「费用 / 升级后 X + 1」那一栏（CostFieldVisible=false）", !forged.CostFieldVisible, $"CostFieldVisible={forged.CostFieldVisible}");
				Check("锻造卡在锻造页的列表里（ForgeVisible 里能找到它）", ForgeVisible.Contains(forged), $"{ForgeVisible.Count} 项");
				Check("锻造卡在卡牌页被选中时：属性照常能改、只有效果栏锁死（提示里写清了）",
					forged.ForgeEditingHint.Contains("锻造") && forged.ForgeEditingHint.Contains("效果"), forged.ForgeEditingHint.Replace("\n", " "));
				// 需求：卡牌页选中锻造卡时右边效果栏锁死（属性在中间照常改）
				{
					CardSpec? keepSel = CardUiSelection;   // V0.2.140：读镜像属性（列表里有空槽行，SelectedItem 可能是占位项）
					PumpDispatcher(120);
					CardList.SelectedItem = forged;
					PumpDispatcher(120);
					Check("卡牌页选中锻造卡 → 效果栏锁死（CardEffectsEditable=false）",
						CardEffectsAreForged && !CardEffectsEditable, $"IsForged={CardEffectsAreForged}");
					// 用户报过「在锻造页修改能量后，卡牌页还是显示原来 0 的数值」：费用那一栏藏起来之后）"
					// 卡牌页要把锻造页【能量】模块上的数字读出来**只读显示**，否则用户看到的是没人再改的时 Cost。"
					Check("卡牌页选中锻造卡 → 显示「费用：N 点能量（由锻造页【能量】模块决定）」这一行只读提示",
						ForgeEnergyCostText.Contains("由锻造页") && ForgeEnergyCostText.Contains("能量"), ForgeEnergyCostText);
					Check("卡牌页选中锻造卡 → 中间的「费用 / X 费用 / 额外资源量费用 / 升级后 X+1」整块藏掉（需求）",
						!CardCoreFieldsVisible, $"CardCoreFieldsVisible={CardCoreFieldsVisible}");
					// ⚠ V0.2.140 起不能拿「进来时选中的那一张」当恢复目标：清单里现在会**保住**选中项
					//（以前 Add 之后选中项会被打断成 null），所以 keepSel 有可能正好就是这张锻造卡。
					// 这里明确挑一张**非锻造**的卡恢复（断言要的就是「普通卡那两块回来了」）。
					CardList.SelectedItem = keepSel is CardSpec ks && !ks.IsForged
						? ks
						: Profile.Cards.FirstOrDefault((CardSpec c) => !c.IsForged);
					PumpDispatcher(120);
					Check("换回普通卡后这两块又回来了",
						CardEffectsEditable && CardCoreFieldsVisible,
						$"效果栏 {CardEffectsEditable} 费用栏={CardCoreFieldsVisible} / 现在选中的={CardUiSelection?.Name ?? "(null)"}（IsForged={CardUiSelection?.IsForged}）");
				}

				// ===== 节点图（那块「布」）=====
				// 用户要求：【触发时机】后面**固定连着一个【指向对象」 *（声明「这张牌在游戏里选中谁」），"
				// 所以新布是 3 块：触发时机 + 能量 + 指向对象，而且触发时机已经接好指向对象」"
				var newTarget = forged.ForgeGraph?.Nodes.FirstOrDefault(n => n.Kind == "Target");
				Check("新锻造卡自带一块布（【触发时机】+ 左上角【能量】+ 触发时机后面那个【指向对象】）",
					forged.ForgeGraph is not null && forged.ForgeGraph.Nodes.Count == 3
					&& forged.ForgeGraph.Nodes.Any(n => n.Kind == "Trigger") && forged.ForgeGraph.Nodes.Any(n => n.Kind == "Energy")
					&& newTarget is not null,
					forged.ForgeGraph is null ? "没有图" : string.Join("/", forged.ForgeGraph.Nodes.Select(n => n.Kind)));
				Check("【触发时机】固定连到【指向对象】（用户要求）",
					newTarget is not null && forged.ForgeGraph!.Outgoing(forged.ForgeGraph.TriggerNode!.Id, 0).Count == 1
					&& forged.ForgeGraph.Outgoing(forged.ForgeGraph.TriggerNode!.Id, 0)[0].To == newTarget.Id,
					"接上了");
				// 用户报的坑：布上【能量】模块填了」  能量 + 1 额外资源量」时，卡牌页列表和游戏里都是」  费」，
				// 但打出后真的扣了 1+1（因为那两栏以前只当成「打出时的动作」，没声明成卡牌自己的费用）。"
				// 现在：能量"→ 卡牌构造函数的费用（本体显示 / 判定都用它），资源量 → CanonicalStarCost（本体星星费用）。"
				{
					var costEnergyNode = forged.ForgeGraph!.Nodes.FirstOrDefault(x => x is not null && x.Kind == "Energy");
					costEnergyNode?.SetNumber("EnergyCost", 1);
					costEnergyNode?.SetNumber("ResourceCost", 1);
					Check("锻造卡的费用取自布上【能量】模块（能量 1 / 额外资源量 1）",
						CSharpCodeGen.CardCostOf(forged) == 1 && CSharpCodeGen.StarCostOf(forged) == 1,
						$"能量={CSharpCodeGen.CardCostOf(forged)} 资源量 {CSharpCodeGen.StarCostOf(forged)}");
					string costSrc = CSharpCodeGen.CardSource(Profile, forged, 0);
					Check("生成的卡牌构造函数费用== 1（本体据此显示费用、能量不够时打不出去）",
						costSrc.Contains(": base(1, CardType."), "构造函数带费用");
					Check("额外资源量消耗生成本体的星星费用（CanonicalStarCost => 1：不够时本体禁止打出、卡面数字变红）",
						costSrc.Contains("public override int CanonicalStarCost => 1;"), "有 CanonicalStarCost");
					Check("打出时**不再**偷偷扣第二次（老写法里的 LoseEnergy / SetStars 已经没了）",
						!costSrc.Contains("LoseEnergy(1m, __fgPlayer)") && !costSrc.Contains("SetStars(System.Math.Max"),
						"不再重复扣");
					Check("X / Y 还是「扣完这张牌费用之后的当前值」（数值和以前一样，只是改由本体在打出前扣）",
						costSrc.Contains("decimal __X = ForgeFormulaRuntime.Energy(__fgPlayer);")
						&& costSrc.Contains("decimal __Y = ForgeFormulaRuntime.Stars(__fgPlayer);"), "对");
					Check("卡牌页列表里显示的是布上那个费用（不再是 0 费，也不用点进去看提示）",
						forged.Display.Contains("/ 1 费 + 资源量1"), forged.Display);
					// 升级后那块布的费用不一样时：按本体的办法在 OnUpgrade 里改（EnergyCost.UpgradeBy）"
					forged.UpgradedForgeGraph = ForgeGraphSpec.NewCardGraph();
					forged.UpgradedForgeGraph.Nodes.First(x => x.Kind == "Energy").SetNumber("EnergyCost", 0);
					string costUpSrc = CSharpCodeGen.CardSource(Profile, forged, 0);
					Check("升级后那块布的费用不同 → OnUpgrade 里用本体的 EnergyCost.UpgradeBy(差值) 改费用",
						costUpSrc.Contains("base.EnergyCost.UpgradeBy(-1);"), "有 UpgradeBy");
					forged.UpgradedForgeGraph = null;
					costEnergyNode?.SetNumber("EnergyCost", 0);
					costEnergyNode?.SetNumber("ResourceCost", 0);
					Check("（红线）费用填回 0 → 生成文本逐字回到老写法",
						CSharpCodeGen.CardSource(Profile, forged, 0).Contains("decimal __X = ForgeFormulaRuntime.Energy(__fgPlayer) - 0m;")
						&& CSharpCodeGen.CardSource(Profile, forged, 0).Contains(": base(0, CardType."), "老样子");
				}
				Check("【指向对象】默认「指定单体敌人」（= 效果没自己接【对象】时还是打「选中/第一个敌人」，和以前一致）",
					newTarget?.Get("Pick", "") == "ChosenEnemy", newTarget?.Get("Pick", "") ?? "(没有)");
				Check("【指向对象】的候选和【对象】一样（10 档），右边还有一个「指向对象」口可以当对象用",
					ForgeGraphCatalog.Find("Target")!.Fields.Any(f => f.Key == "Pick" && f.OptionList.Count == ForgeGraphCatalog.UnitPicks.Count)
					&& ForgeGraphCatalog.Find("Target")!.Outputs.Count == 2
					&& ForgeGraphCatalog.Find("Target")!.Outputs[1].AcceptsKind == "Object",
					"ForgeGraphCatalog.Target");
				Check("【关系符】有 8 个运算符（大于 / 小于 / 等于 / 大于等于 / 小于等于 / 非 / 且 / 或）",
					ForgeGraphCatalog.RelateOps.Count == 8
					&& new[] { "Gt", "Lt", "Eq", "Ge", "Le", "Not", "And", "Or" }.All(op => ForgeGraphCatalog.RelateOps.Any(o => o.Id == op)),
					string.Join("/", ForgeGraphCatalog.RelateOps.Select(o => o.Id)));
				Check("【关系符】左右两个口是**联合类型**（既能接数值，也能接条件）",
					ForgeGraphCatalog.Find("Relate")!.Inputs[1].Key == "L"
					&& ForgeGraphCatalog.Find("Relate")!.Inputs[1].AcceptsKind == ForgeGraphCatalog.NumberOrBool
					&& ForgeGraphCatalog.Find("Relate")!.Inputs[2].Key == "R"
					&& ForgeGraphCatalog.Find("Relate")!.Inputs[2].AcceptsKind == ForgeGraphCatalog.NumberOrBool
					&& ForgeGraphCatalog.Find("Relate")!.Outputs[0].AcceptsKind == "Bool",
					"ForgeGraphCatalog.Relate");
				Check("联合类型的匹配规则：数值 / 条件都能进【关系符】，但对象进不去",
					ForgeGraphCatalog.TypesCompatible("Number", ForgeGraphCatalog.NumberOrBool)
					&& ForgeGraphCatalog.TypesCompatible("Bool", ForgeGraphCatalog.NumberOrBool)
					&& !ForgeGraphCatalog.TypesCompatible("Object", ForgeGraphCatalog.NumberOrBool)
					&& !ForgeGraphCatalog.TypesCompatible("Number", "Bool"),
					"TypesCompatible");
				Check("【能量】模块按需求固定在左上角",
					forged.ForgeGraph!.Nodes.First(n => n.Kind == "Energy").X == ForgeGraphCatalog.EnergyX
					&& forged.ForgeGraph.Nodes.First(n => n.Kind == "Energy").Y == ForgeGraphCatalog.EnergyY,
					$"({forged.ForgeGraph.Nodes.First(n => n.Kind == "Energy").X},{forged.ForgeGraph.Nodes.First(n => n.Kind == "Energy").Y})");
				ForgeItemList.SelectedItem = forged;
				SyncForgeDetail();
				UpdateLayout();
				Check("选中锻造卡后那块布指向它的图（编辑前）",
					ReferenceEquals(ForgeCanvas.Graph, forged.ForgeGraph), ForgeCanvas.Graph is null ? "空" : ForgeCanvas.Graph.Display);
				Check("默认显示的是「升级前」那一页", ForgeGraphTabs.SelectedIndex == 0, $"SelectedIndex={ForgeGraphTabs.SelectedIndex}");
				Check("「升级前」页上不显示「一键复制」按钮（那是升级后那一页的）",
					!ForgeCopyVisible, $"ForgeCopyVisible={ForgeCopyVisible}");

				// 模块目录：需求里点名的 11 种一个都不能少 
				var wantedKinds = new[] { "Trigger", "If", "Unit", "Power", "Value", "Energy", "Effect", "And", "Or", "Condition" };
				var haveKinds = ForgeGraphCatalog.All.Select(k => k.Id).ToList();
				Check("模块目录里有需求点名的那些模块（触发时机 / if / 对象 / 状态 / 数值 / 能量 / 效果 / 且 / 或 / 条件）",
					wantedKinds.All(haveKinds.Contains), string.Join("/", haveKinds));
				Check("【触发时机】默认是「卡牌被打出时」",
					forged.ForgeGraph.TriggerNode!.Get("Timing") == ForgeTimings.CardPlayed,
					forged.ForgeGraph.TriggerNode.Get("Timing"));
				Check("卡牌的触发时机候选里有「卡牌被自动打出时」（用户要求新增的那一档）",
					ForgeTimings.For("Card").Any(t => t.Id == ForgeTimings.CardAutoPlayed),
					string.Join("/", ForgeTimings.For("Card").Select(t => t.Id)));
				Check("遗物的触发时机候选里有「当遗物被点击时」和「血量低于 N」（用户要求新增的两档）",
					ForgeTimings.For("Relic").Any(t => t.Id == ForgeTimings.RelicClicked)
					&& ForgeTimings.For("Relic").Any(t => t.Id == ForgeTimings.HpBelow),
					string.Join("/", ForgeTimings.For("Relic").Select(t => t.Id)));
				Check("「血量低于 N」的 N 填小于 1 的值时按百分比算（说明里写出来了）",
					ForgeTimings.Find(ForgeTimings.HpBelow)!.Hint.Contains("百分比"), ForgeTimings.Find(ForgeTimings.HpBelow)!.Hint);

				// 连一条线：触发时机 → 效果
				var effNode = new ForgeNodeSpec { Kind = "Effect", X = 700, Y = 200 };
				effNode.SetField("Effect", "Damage");
				forged.ForgeGraph.Nodes.Add(effNode);
				var trig = forged.ForgeGraph.TriggerNode!;
				Check("触发时机右边只有一个出口（需求：仅右侧一个出口点）",
					trig.KindDef!.Outputs.Count == 1, $"{trig.KindDef.Outputs.Count} 个");
				Check("【if】左边两个口（接入 + **条件**）；右边「是 / 否」两个出口（用户要求：条件挪到左边入口）",
					ForgeGraphCatalog.Find("If")!.Inputs.Count == 2 && ForgeGraphCatalog.Find("If")!.Inputs[0].Key == "In"
					&& ForgeGraphCatalog.Find("If")!.Inputs[1].Key == "Cond"
					&& ForgeGraphCatalog.Find("If")!.Inputs[1].AcceptsKind == "Bool"
					&& ForgeGraphCatalog.Find("If")!.Outputs.Count == 2
					&& ForgeGraphCatalog.Find("If")!.Outputs[0].Key == "True"
					&& ForgeGraphCatalog.Find("If")!.Outputs[1].Key == "False",
					"入口 " + string.Join(" / ", ForgeGraphCatalog.Find("If")!.Inputs.Select(p => p.Key))
					+ "；出口 " + string.Join(" / ", ForgeGraphCatalog.Find("If")!.Outputs.Select(p => p.Key)));
				Check("【能量】只有右侧两个【数值】出口（能量 / 额外资源量）",
					ForgeGraphCatalog.Find("Energy")!.Inputs.Count == 0 && ForgeGraphCatalog.Find("Energy")!.Outputs.Count == 2,
					"ForgeGraphCatalog.Energy");
				Check("【效果】左边三个口（接入 / 数值 / 指向对象）+ 右边一个「完成」出口",
					ForgeGraphCatalog.Find("Effect")!.Inputs.Count == 3
					&& ForgeGraphCatalog.Find("Effect")!.Inputs[1].Key == "Value"
					&& ForgeGraphCatalog.Find("Effect")!.Inputs[1].AcceptsKind == "Number"
					&& ForgeGraphCatalog.Find("Effect")!.Inputs[2].Key == "Target"
					&& ForgeGraphCatalog.Find("Effect")!.Inputs[2].AcceptsKind == "Object"
					&& ForgeGraphCatalog.Find("Effect")!.Outputs.Count == 1,
					"ForgeGraphCatalog.Effect");
				Check("【状态】左边接入点是「归属」，右边是「数值」出口",
					ForgeGraphCatalog.Find("Power")!.Inputs[0].Label == "归属" && ForgeGraphCatalog.Find("Power")!.Outputs[0].Label == "数值",
					"ForgeGraphCatalog.Power");

				forged.ForgeGraph.Links.Add(new ForgeLinkSpec { From = newTarget!.Id, To = effNode.Id, FromPort = 0, ToPort = 0 });
				Check("连线记的是「哪个模块的第几个出口 → 哪个模块的第几个入口」",
					forged.ForgeGraph.Incoming(effNode.Id, 0) is not null
					&& forged.ForgeGraph.Outgoing(trig.Id, 0).Count == 1
					&& forged.ForgeGraph.Outgoing(newTarget.Id, 0).Count == 1,
					$"{forged.ForgeGraph.Links.Count} 条");

				// 数值模块 + 公式解析（参数 M 要真的在「自定义参数 / 组」页里存在，生成时才会现算它）"
				var mSpec = new ParamSpec { Name = "M", Source = "MaxHp", Target = "Self" };
				Profile.CustomParams.Add(mSpec);
				var valNode = new ForgeNodeSpec { Kind = "Value" };
				valNode.SetField("Formula", "M*3");
				forged.ForgeGraph.Nodes.Add(valNode);
				forged.ForgeGraph.Links.Add(new ForgeLinkSpec { From = valNode.Id, To = effNode.Id, FromPort = 0, ToPort = 1 });
				Check("公式解析：M*3 认得出来，用到参数 M",
					ForgeFormula.TryParse("M*3", out _) is not null
					&& ForgeFormula.Identifiers(ForgeFormula.TryParse("M*3", out _)).SequenceEqual(new[] { "M" }),
					"M*3");
				Check("公式写得不对时给一句中文原因（不是丢给 dotnet 报 CS 错）",
					ForgeFormula.TryParse("M*", out string ferr) is null && ferr.Length > 0, ferr);
				Check("公式里的 X / Y 是固定的（当前所有能量 / 当前所有额外资源量）",
					ForgeFormula.Identifiers(ForgeFormula.TryParse("min(2, X) + Y", out _)).SequenceEqual(new[] { "X", "Y" }),
					"min(2, X) + Y");
				// ===== V0.2.196（用户要求）：公式里也能写条件 =====
				// 用户原话：「能不能让生成器使用上述」+ 15 个「(条件 ? 1 : 0) 再参与算术」的例子。
				{
					string Emit2(string f, params (string Name, string Expr)[] vars)
						=> ForgeFormula.Emit(ForgeFormula.TryParse(f, out _),
							id => vars.FirstOrDefault(v => v.Name == id).Expr, out _) ?? "";
					Check("公式支持比较 / 逻辑 / 三元：a > 0 && b > 0 ? 1 : 0 认得出、翻成 C#",
						Emit2("a > 0 && b > 0 ? 1 : 0", ("A", "__pA"), ("B", "__pB")).Contains("&& ") && Emit2("a > 0 && b > 0 ? 1 : 0", ("A", "__pA"), ("B", "__pB")).Contains("? (1m) : (0m)"),
						Emit2("a > 0 && b > 0 ? 1 : 0", ("A", "__pA"), ("B", "__pB")));
					Check("布尔当数值用 = 真取 1、假取 0（例子：三个数里正数个数）",
						Emit2("(a > 0 ? 1 : 0) + (b > 0 ? 1 : 0) + (c > 0 ? 1 : 0)", ("A", "__pA"), ("B", "__pB"), ("C", "__pC"))
							.Contains("? (1m) : (0m)"), "生成 1/0");
					Check("「(a > 0) * 5」这种把布尔直接乘进数值的写法也认（自动补 真1/假0）",
						Emit2("(a > 0) * 5", ("A", "__pA")).Contains(") ? 1m : 0m) * (5m)"), Emit2("(a > 0) * 5", ("A", "__pA")));
					Check("数字当条件用 = 「不等于 0」（例子：flag ? 1 : 0，flag 只是 0/1 的参数）",
						Emit2("f ? 1 : 0", ("F", "__pF")).Contains("(__pF != 0m)"), Emit2("f ? 1 : 0", ("F", "__pF")));
					Check("嵌套三元（例子：符号函数 x>0 ? 1 : x<0 ? -1 : 0）",
						Emit2("x > 0 ? 1 : x < 0 ? -1 : 0", ("X", "__X")).Contains("? (1m) : ((__X < (0m)) ? -((1m)) : (0m))"),
						Emit2("x > 0 ? 1 : x < 0 ? -1 : 0", ("X", "__X")));
					Check("也认 C# 那套写法：Math.Abs(…) / Math.Max(…) / Convert.ToInt32(…) / true·false",
						Emit2("Math.Abs(a) + Math.Max(1, b)", ("A", "__pA"), ("B", "__pB")).Contains("System.Math.Abs(__pA)")
						&& Emit2("Convert.ToInt32(a > 0)", ("A", "__pA")).Contains("System.Math.Truncate(")
						&& Emit2("(true ? 1 : 0) * 8").Contains("? (1m) : (0m)"),
						Emit2("Math.Abs(a) + Math.Max(1, b)", ("A", "__pA"), ("B", "__pB")));
					Check("比较 / 逻辑 / 三元都能在生成期折成常数（真 1 假 0）",
						ForgeFormula.TryEvalConst(ForgeFormula.TryParse("((2 > 1) ? 1 : 0) * 2", out _), _ => null, out decimal f1, out _) && f1 == 2m
						&& ForgeFormula.TryEvalConst(ForgeFormula.TryParse("(a > 0 ? 1 : 0) + (b > 0 ? 1 : 0) + (c > 0 ? 1 : 0)", out _),
							id => id switch { "A" => 5m, "B" => 3m, "C" => -2m, _ => null }, out decimal f2, out _) && f2 == 2m
						&& ForgeFormula.TryEvalConst(ForgeFormula.TryParse("a % 2 == 1 ? 10 : 0", out _), id => id == "A" ? 5m : null, out decimal f3, out _) && f3 == 10m,
						$"2 / 2 / 10");
					Check("三元少写冒号时给一句中文原因（不丢给 dotnet 报 CS 错）",
						ForgeFormula.TryParse("a > 0 ? 1", out string terr) is null && terr.Contains("冒号"), terr);
					Check("老公式生成文本没变（2*3 → (2m) * (3m)）",
						Emit2("2*3") == "((2m) * (3m))", Emit2("2*3"));
					// ===== V0.2.197（用户贴了整张 .NET Math 表问「这些能用吗」）：Math 那一套 =====
					Check("常量：Math.PI / Math.E / Math.Tau 认得出（照 C# 写就行）",
						Emit2("Math.PI * 2").Contains("(3.1415926535897932384626433833m)")
						&& Emit2("Math.E").Contains("(2.7182818284590452353602874714m)")
						&& Emit2("Math.Tau").Contains("(6.2831853071795864769252867666m)"), "常量在");
					Check("decimal 有重载的直接调（min/max/abs/sign/clamp/floor/ceiling/round/truncate）",
						Emit2("Math.Clamp(15, 0, 10)").Contains("System.Math.Clamp(")
						&& Emit2("Math.Sign(-8)").Contains("System.Math.Sign(")
						&& Emit2("Math.Truncate(3.9)").Contains("System.Math.Truncate("), "直接调");
					Check("只有 double 重载的（pow/sqrt/log/三角）→ 参数转 double、结果转回 decimal",
						Emit2("Math.Pow(2, 3)").Contains("(decimal)System.Math.Pow((double)(")
						&& Emit2("Math.Sqrt(16)").Contains("(decimal)System.Math.Sqrt((double)(")
						&& Emit2("Math.Log(8, 2)").Contains("(decimal)System.Math.Log((double)("), "转手");
					Check("三角 / 双曲 / atan2 都在（只有 double 重载，参数转一手）",
						Emit2("Math.Sin(x) + Math.Cos(x) + Math.Tan(x)", ("X", "__X")).Contains("System.Math.Tan((double)")
						&& Emit2("Math.Sinh(x) + Math.Cosh(x) + Math.Tanh(x)", ("X", "__X")).Contains("System.Math.Tanh((double)")
						&& Emit2("Math.Asin(x) + Math.Acos(x) + Math.Atan(x) + Math.Atan2(1, 1)", ("X", "__X")).Contains("System.Math.Atan2("), "都在");
					Check("Math.Round(x, AwayFromZero) = 传统四舍五入（2.5 → 3），默认 Round 仍是银行家舍入",
						Emit2("Math.Round(2.5, AwayFromZero)").Contains(">= 0m ? System.Math.Floor(")
						&& Emit2("Math.Round(2.5)").Contains("System.Math.Round((2.5m))"), "两档都在");
					Check("本体没有现成重载的照语义拼（MaxMagnitude / MinMagnitude / CopySign / 角度↔弧度）",
						Emit2("Math.MaxMagnitude(-5, 3)").Contains("System.Math.Abs(")
						&& Emit2("Math.CopySign(3, -1)").Contains("System.Math.Sign(")
						&& Emit2("Math.RadiansToDegrees(Math.PI)").Contains("* 180m / "), "拼出来了");
					Check("判断族（double.IsNaN / IsFinite…）在 decimal 上是确定的（NaN 恒假、有限恒真）",
						Emit2("double.IsNaN(3.14) ? 7 : 8").Contains("(false) ?") && Emit2("double.IsFinite(3.14) ? 7 : 8").Contains("(true) ?"), "常数");
					Check("Math 公式也能在生成期折成常数（卡牌费用那种要常量的地方能用）",
						ForgeFormula.TryEvalConst(ForgeFormula.TryParse("Math.Pow(2, 3) + Math.Sqrt(16) + Math.Cbrt(27)", out _), _ => null, out decimal m1, out _) && m1 == 15m
						&& ForgeFormula.TryEvalConst(ForgeFormula.TryParse("Math.Clamp(15, 0, 10) + Math.Sign(-8)", out _), _ => null, out decimal m2, out _) && m2 == 9m,
						$"15 / 9");
					Check("没这个函数时给中文原因（不是丢给 dotnet 报 CS 错）",
						ForgeFormula.TryParse("nosuchfn(1)", out string merr) is null && merr.Contains("没有"), merr);
				}

				// 生成：图非空时卡牌源码里要有 ForgeGraphOnPlay 和那条伤害 
				string cardSrc = CSharpCodeGen.CardSource(Profile, forged, 0);
				Check("卡牌源码里生成了 ForgeGraphOnPlay，并在 OnPlay 里调用它",
					cardSrc.Contains("ForgeGraphOnPlay") && cardSrc.Contains("await ForgeGraphOnPlay(choiceContext, cardPlay);"),
					"生成在");
				Check("公式 M*3 翻成了 C# 表达式（参数是运行时现算的局部变量）",
					cardSrc.Contains("* (3m)") && cardSrc.Contains("__pM ="), "生成在");
				Check("伤害那一行带着「指向对象」和「数值」两条线",
					cardSrc.Contains("DamageCmd.Attack(") && cardSrc.Contains("Targeting("), "生成在");
				Check("图非空时才会写运行时辅助类（默认档不多一个文件）",
					ForgeGraphGen.AnyGraphs(Profile) && !ForgeGraphGen.AnyGraphs(ProfileFactory.Sample()),
					$"本配置={ForgeGraphGen.AnyGraphs(Profile)} / 示例配置={ForgeGraphGen.AnyGraphs(ProfileFactory.Sample())}");
				Check("运行时辅助类里有夹零除法 / 取状态层数 / 读能量与额外资源量",
					ForgeGraphGen.RuntimeSource(Profile).Contains("public static decimal Div(")
					&& ForgeGraphGen.RuntimeSource(Profile).Contains("PowerAmount(")
					&& ForgeGraphGen.RuntimeSource(Profile).Contains("Stars(Player? player)"),
					"都在");
				Profile.CustomParams.Remove(mSpec);

				// ===== if / 个 / 成 真正接管执行顺序（需求第 2 / 8 / 9 条）=====
				{
					Check("【if】左边两个口（接入 + 条件）；右边「是 / 否」两个出口（用户要求：条件挪到左边入口）",
						ForgeGraphCatalog.Find("If")!.Inputs.Count == 2
						&& ForgeGraphCatalog.Find("If")!.Inputs[0].Key == "In"
						&& ForgeGraphCatalog.Find("If")!.Inputs[1].Key == "Cond"
						&& ForgeGraphCatalog.Find("If")!.Inputs[1].AcceptsKind == "Bool"
						&& ForgeGraphCatalog.Find("If")!.Outputs.Count == 2
						&& ForgeGraphCatalog.Find("If")!.Outputs[0].Key == "True"
						&& ForgeGraphCatalog.Find("If")!.Outputs[1].Key == "False",
						$"入口 {ForgeGraphCatalog.Find("If")!.Inputs.Count} 个 / 出口 {ForgeGraphCatalog.Find("If")!.Outputs.Count} 个：" +
						string.Join(" / ", ForgeGraphCatalog.Find("If")!.Outputs.Select(p => p.Key)));
					Check("【条件】右边是布尔出口、左边是可选数值入口（可以接【数值】让 N 运行时才算）",
						ForgeGraphCatalog.Find("Condition")!.Outputs[0].AcceptsKind == "Bool"
						&& ForgeGraphCatalog.Find("Condition")!.Inputs[0].AcceptsKind == "Number",
						"ForgeGraphCatalog.Condition");
					Check("【且】/【或】是「两个条件入口 + 一个布尔出口」",
						ForgeGraphCatalog.Find("And")!.Inputs.Count == 2 && ForgeGraphCatalog.Find("And")!.Outputs[0].AcceptsKind == "Bool"
						&& ForgeGraphCatalog.Find("Or")!.Inputs.Count == 2,
						"And/Or");

					// 造一张「有易伤就打 9，否则上 2 层易伤」的图，看生成出来是不是真 if / else
					var bCard = new CardSpec { Name = "自检分支卡", ClassName = "UiCheckBranch", CardType = "Attack", Cost = 0, IsForged = true };
					bCard.ForgeGraph = new ForgeGraphSpec();
					var bt = new ForgeNodeSpec { Kind = "Trigger" };
					bt.SetField("Timing", ForgeTimings.CardPlayed);
					var bcond = new ForgeNodeSpec { Kind = "Condition" };
					bcond.SetField("Cond", "HasPowerAtLeast");
					bcond.SetField("Amount", "1");
					bcond.SetField("PowerId", "VulnerablePower");
					var bif = new ForgeNodeSpec { Kind = "If" };
					var bEffT = new ForgeNodeSpec { Kind = "Effect" };
					bEffT.SetField("Effect", "Damage");
					bEffT.SetField("Amount", "9");
					var bEffF = new ForgeNodeSpec { Kind = "Effect" };
					bEffF.SetField("Effect", "Block");
					bEffF.SetField("Amount", "5");
					bCard.ForgeGraph.Nodes.AddRange(new[] { bt, bcond, bif, bEffT, bEffF });
					bCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = bt.Id, To = bif.Id, FromPort = 0, ToPort = 0 });
					// 条件接在【if」 *左边**那个「条件」口（入口下标 1）上 —— 用户要求挪过去的
					bCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = bcond.Id, To = bif.Id, FromPort = 0, ToPort = 1 });
					bCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = bif.Id, To = bEffT.Id, FromPort = 0, ToPort = 0 });   // 出口 0 = 是 
					bCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = bif.Id, To = bEffF.Id, FromPort = 1, ToPort = 0 });   // 出口 1 = 名 
					string bSrc = CSharpCodeGen.CardSource(Profile, bCard, 0);
					Check("【if】生成了真的 if / else，两个分支各在自己的括号里",
						bSrc.Contains("if (base.Owner.Creature.GetPowerAmount<VulnerablePower>() >= 1)")
						&& bSrc.Contains("else"),
						bSrc.Contains("if (") ? "有 if" : "没有 if");
					Check("「是」那一支走【效果】伤害、「否」那一支走【效果】格挡（按出口分对了）",
						bSrc.IndexOf("DamageCmd.Attack(", StringComparison.Ordinal) > 0
						&& bSrc.IndexOf("CreatureCmd.GainBlock(", StringComparison.Ordinal) > 0
						&& bSrc.IndexOf("DamageCmd.Attack(", StringComparison.Ordinal) < bSrc.IndexOf("else", StringComparison.Ordinal)
						&& bSrc.IndexOf("CreatureCmd.GainBlock(", StringComparison.Ordinal) > bSrc.IndexOf("else", StringComparison.Ordinal),
						"分支顺序对");
					Check("条件里的状态层数用的是本体判据（GetPowerAmount<状态>() >= N）",
						bSrc.Contains("GetPowerAmount<VulnerablePower>() >= 1"), "生成在");
					// 条件口上多一条没类型的线（老存档 / 手写 JSON 可能有）时按**来源种类**挑，不会误取定"
					var bExtra = new ForgeNodeSpec { Kind = "Unit" };
					bCard.ForgeGraph.Nodes.Add(bExtra);
					bCard.ForgeGraph.Links.Insert(0, new ForgeLinkSpec { From = bExtra.Id, To = bif.Id, FromPort = 0, ToPort = 1 });
					string bSrc2 = CSharpCodeGen.CardSource(Profile, bCard, 0);
					Check("同一入口上有多余的线时不会把条件判丢（仍取能出布尔的那一条）",
						bSrc2.Contains("GetPowerAmount<VulnerablePower>() >= 1"), 
						bSrc2.Contains("GetPowerAmount<VulnerablePower>") ? "生成在" : "条件丢了");
					Profile.Cards.Remove(bCard);
				}

				// ===== V0.2.216（用户报的「处于二形态时触发不了多效卡效果只能打24的基础效果」）=====
				// 两个真 bug：
				//  ① 三层「且」串起来时（且(且(A,B),C)），第二个【且】的条件以前取的是**它 Out 口上接进来的那一块**
				//     （= 第一个【且】），于是 C 被整个丢掉 —— 形态判断只剩两个；
				//  ② 图上有「会做事」的模块没接到【触发时机】这条链上时，生成端**一个字都不输出**（静默失效）。
				{
					// ① 三层且：A && B && C 必须一个不落
					var andCard = new CardSpec { Name = "自检三层且", ClassName = "UiCheckAnd3", CardType = "Skill", Cost = 0, IsForged = true };
					andCard.ForgeGraph = new ForgeGraphSpec();
					var aTrig = new ForgeNodeSpec { Kind = "Trigger" };
					aTrig.SetField("Timing", ForgeTimings.CardPlayed);
					ForgeNodeSpec AndCond(int amt)
					{
						var u = new ForgeNodeSpec { Kind = "Unit" };
						u.SetField("Pick", "Self");
						var p2 = new ForgeNodeSpec { Kind = "Power" };
						p2.SetField("PowerId", "VulnerablePower");
						var rel = new ForgeNodeSpec { Kind = "Relate" };
						rel.SetField("Op", "Lt");
						rel.SetField("Amount", amt.ToString());
						andCard.ForgeGraph.Nodes.AddRange(new[] { u, p2, rel });
						andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = u.Id, To = rel.Id, FromPort = 0, ToPort = 0 });
						andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = p2.Id, To = rel.Id, FromPort = 0, ToPort = 1 });
						return rel;
					}
					// 三个独立的「状态 < N」条件（N = 1 / 2 / 3，生成出来能一眼看出三个都在）+ 两层【且】
					var r1 = AndCond(1);
					var r2 = AndCond(2);
					var r3 = AndCond(3);
					var and1 = new ForgeNodeSpec { Kind = "And" };
					var and2 = new ForgeNodeSpec { Kind = "And" };
					var finalEff = new ForgeNodeSpec { Kind = "Effect" };
					finalEff.SetField("Effect", "Block");
					finalEff.SetField("Amount", "5");
					andCard.ForgeGraph.Nodes.Add(aTrig);
					andCard.ForgeGraph.Nodes.AddRange(new[] { and1, and2, finalEff });
					andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = aTrig.Id, To = and1.Id, FromPort = 0, ToPort = 0 });
					andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = r1.Id, To = and1.Id, FromPort = 0, ToPort = 0 });
					andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = r2.Id, To = and1.Id, FromPort = 0, ToPort = 1 });
					andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = and1.Id, To = and2.Id, FromPort = 0, ToPort = 0 });
					andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = r3.Id, To = and2.Id, FromPort = 0, ToPort = 1 });
					andCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = and2.Id, To = finalEff.Id, FromPort = 0, ToPort = 0 });
					string andSrc = CSharpCodeGen.CardSource(Profile, andCard, 0);
					Check("V0.2.216：三层「且」串起来时三个条件**一个都不丢**（以前第二个【且】只认第一个输入）",
						andSrc.Contains("< (1))", StringComparison.Ordinal)
						&& andSrc.Contains("< (2))", StringComparison.Ordinal)
						&& andSrc.Contains("< (3))", StringComparison.Ordinal)
						&& andSrc.Contains("&&", StringComparison.Ordinal),
						$"len={andSrc.Length} 1={andSrc.Contains("< (1))")} 2={andSrc.Contains("< (2))")} 3={andSrc.Contains("< (3))")} &&={andSrc.Contains("&&")} hasPlay={andSrc.Contains("ForgeGraphOnPlay")}");
					Profile.Cards.Remove(andCard);

					// ② 没接上的模块：生成代码里要有可见警告 + 校验器给一条警告
					var orphanCard = new CardSpec { Name = "自检漏接线", ClassName = "UiCheckOrphan", CardType = "Skill", Cost = 0, IsForged = true };
					orphanCard.ForgeGraph = new ForgeGraphSpec();
					var oTrig = new ForgeNodeSpec { Kind = "Trigger" };
					oTrig.SetField("Timing", ForgeTimings.CardPlayed);
					var oEff = new ForgeNodeSpec { Kind = "Effect" };
					oEff.SetField("Effect", "Damage");
					oEff.SetField("Amount", "24");
					var oOrphan = new ForgeNodeSpec { Kind = "Effect" };
					oOrphan.SetField("Effect", "Damage");
					oOrphan.SetField("Amount", "27");
					orphanCard.ForgeGraph.Nodes.AddRange(new[] { oTrig, oEff, oOrphan });
					orphanCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = oTrig.Id, To = oEff.Id, FromPort = 0, ToPort = 0 });
					var missed = ForgeGraphGen.UnreachableModules(orphanCard.ForgeGraph);
					Check("V0.2.216：能算出「没接到触发时机」的模块（这里就是那条 27 伤害）",
						missed.Count == 1 && missed[0].Get("Amount") == "27", $"算出 {missed.Count} 块");
					string orphanSrc = CSharpCodeGen.CardSource(Profile, orphanCard, 0);
					Check("V0.2.216：生成出来的卡里写了一段「没接到【触发时机】」的警告（不再静默失效）",
						orphanSrc.Contains("没接到【触发时机】", StringComparison.Ordinal)
						&& orphanSrc.Contains("fg:" + oOrphan.Id, StringComparison.Ordinal), "有警告");
					Check("V0.2.216：校验器给一条**警告**（不是错误：留备用模块是正常用法）",
						ForgeGraphGen.Issues(orphanCard.ForgeGraph, Profile, "Card")
							.Any(x => x.Level == "警告" && x.Message.Contains("没接到【触发时机】", StringComparison.Ordinal)),
						string.Join(" / ", ForgeGraphGen.Issues(orphanCard.ForgeGraph, Profile, "Card").Select(x => x.Level + ":" + x.Message)));
					Check("V0.2.216：（红线）没有漏接线的图不会多出这段警告",
						!CSharpCodeGen.CardSource(Profile, new CardSpec
						{
							Name = "自检干净卡", ClassName = "UiCheckClean", CardType = "Skill", Cost = 0, IsForged = true,
							ForgeGraph = new ForgeGraphSpec
							{
								Nodes = { new ForgeNodeSpec { Kind = "Trigger", Fields = { ["Timing"] = ForgeTimings.CardPlayed } } },
							},
						}, 0).Contains("没接到【触发时机】", StringComparison.Ordinal), "没多写");
					Profile.Cards.Remove(orphanCard);
				}

				// ===== V0.2.218（用户要求：「锻造无法『处于某种条件下时，该牌无法被打出』」）=====
				// 【条件】模块多一栏「不满足时」：跳过这一支（默认）/ **整张牌打不出去**（本体 IsPlayable + 描金边）。
				{
					Check("V0.2.218：【条件】模块上有「不满足时」这一栏，两个档位（跳过 / 整张牌打不出去）",
						ForgeGraphCatalog.Find("Condition")!.Fields.Any(f => f.Key == "WhenUnmet"
							&& f.OptionList.Count == 2
							&& f.OptionList[0].Id == "Pass" && f.OptionList[1].Id == "Unplayable"),
						string.Join(" / ", (ForgeGraphCatalog.Find("Condition")!.Fields.FirstOrDefault(f => f.Key == "WhenUnmet")?.OptionList ?? Array.Empty<ForgeFieldOption>()).Select(o => o.Id)));
					var gateCard = new CardSpec { Name = "自检打不出", ClassName = "UiCheckUnplayable", CardType = "Attack", Cost = 1, IsForged = true, InCardPool = true };
					gateCard.ForgeGraph = new ForgeGraphSpec();
					var gTrig = new ForgeNodeSpec { Kind = "Trigger" };
					gTrig.SetField("Timing", ForgeTimings.CardPlayed);
					var gCond = new ForgeNodeSpec { Kind = "Condition" };
					gCond.SetField("Cond", "HandAtLeast");
					gCond.SetField("Amount", "3");
					var gEff = new ForgeNodeSpec { Kind = "Effect" };
					gEff.SetField("Effect", "Damage");
					gEff.SetField("Amount", "9");
					gateCard.ForgeGraph.Nodes.AddRange(new[] { gTrig, gCond, gEff });
					gateCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = gTrig.Id, To = gEff.Id, FromPort = 0, ToPort = 0 });
					string gateOff = CSharpCodeGen.CardSource(Profile, gateCard, 0);
					Check("V0.2.218：（默认档）没选「整张牌打不出去」时**不生成** IsPlayable（老图逐字不变）",
						!gateOff.Contains("IsPlayable", StringComparison.Ordinal), gateOff.Contains("IsPlayable") ? "多写了" : "没写");
					gCond.SetField("WhenUnmet", "Unplayable");
					string gateOn = CSharpCodeGen.CardSource(Profile, gateCard, 0);
					Check("V0.2.218：选「整张牌打不出去」→ 生成 IsPlayable（条件 = 布上那个【条件】）",
						gateOn.Contains("protected override bool IsPlayable =>", StringComparison.Ordinal)
						&& gateOn.Contains("PileType.Hand).Count() >= 3)", StringComparison.Ordinal),
						gateOn.Contains("IsPlayable") ? "生成了" : "没生成");
					Check("V0.2.218：同时生成描金边（条件满足时可以打，本体「死亡之门」那种提示）",
						gateOn.Contains("ShouldGlowGoldInternal", StringComparison.Ordinal), "描金边在");
					Check("V0.2.218：只当「打不出去」用的【条件】不算「漏接线」（不误报那条警告）",
						ForgeGraphGen.UnreachableModules(gateCard.ForgeGraph).Count == 0
						&& !gateOn.Contains("没接到【触发时机】", StringComparison.Ordinal), "没误报");
					// 遗物 / 药水 / 状态布上没有「打出」，这一栏不显示、校验器报错说清
					var gateIssuesRelic = ForgeGraphGen.Issues(gateCard.ForgeGraph, Profile, "Relic");
					Check("V0.2.218：非卡牌布上勾了「整张牌打不出去」→ 校验器报错说清（没有「打出」这回事）",
						gateIssuesRelic.Any(x => x.Level == "错误" && x.Message.Contains("打不出去", StringComparison.Ordinal)),
						string.Join(" / ", gateIssuesRelic.Select(x => x.Level + ":" + x.Message).Take(3)));
					// 数值写运行时公式 → 跳过 + 警告（IsPlayable 是表达式体属性，放不下局部变量）
					gCond.SetField("Amount", "X");
					var gateIssuesX = ForgeGraphGen.Issues(gateCard.ForgeGraph, Profile, "Card");
					Check("V0.2.218：条件的数值写了运行时公式 → 警告说清「这一条不会生效」（不静默）",
						gateIssuesX.Any(x => x.Level == "警告" && x.Message.Contains("打不出去", StringComparison.Ordinal)),
						string.Join(" / ", gateIssuesX.Select(x => x.Level + ":" + x.Message).Take(3)));
					Profile.Cards.Remove(gateCard);
				}

				// ===== 【对象】的多人 / 召唤物 / 全体单位（这一轮做的细分）=====
				{
					var uCard = new CardSpec { Name = "自检对象卡", ClassName = "UiCheckUnit", CardType = "Skill", Cost = 0, IsForged = true };
					uCard.ForgeGraph = new ForgeGraphSpec();
					var ut = new ForgeNodeSpec { Kind = "Trigger" };
					ut.SetField("Timing", ForgeTimings.CardPlayed);
					var uUnit = new ForgeNodeSpec { Kind = "Unit" };
					var uEff = new ForgeNodeSpec { Kind = "Effect" };
					uEff.SetField("Effect", "Block");
					uEff.SetField("Amount", "4");
					uCard.ForgeGraph.Nodes.AddRange(new[] { ut, uUnit, uEff });
					uCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = ut.Id, To = uEff.Id, FromPort = 0, ToPort = 0 });
					uCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = uUnit.Id, To = uEff.Id, FromPort = 0, ToPort = 2 });

					string ForPick(string pick)
					{
						uUnit.SetField("Pick", pick);
						return CSharpCodeGen.CardSource(Profile, uCard, 0);
					}
					string srcSelf = ForPick("Self");
					string srcAllies = ForPick("AllAllies");
					string srcSummons = ForPick("AllSummons");
					string srcEnemies = ForPick("AllEnemies");
					string srcAllUnits = ForPick("AllUnits");
					string srcChosenEnemy = ForPick("ChosenEnemy");

					Check("【对象】「自己」→ 只作用在自己身上（AllAllies 那条不含自己以外的）",
						srcSelf.Contains("AllAllies(__fgPlayer)"), "自己");
					Check("【对象】「全部友方」= 自己 + 召唤物（AllAllies 助手）",
						srcAllies.Contains("ForgeFormulaRuntime.AllAllies("), "全部友方");
					Check("【对象】「全部召唤物」= 只作用于召唤物（SummonList，不含自己）",
						srcSummons.Contains("ForgeFormulaRuntime.SummonList(") && !srcSummons.Contains("AllAllies("), "召唤物");
					Check("【对象】「全部敌人」= 敌人列表（EnemyList，不是「第一个敌人」）",
						srcEnemies.Contains("ForgeFormulaRuntime.EnemyList("), "全部敌人");
					Check("【对象】「全体单位」= AllUnits（自己 + 召唤物 + 敌人）",
						srcAllUnits.Contains("ForgeFormulaRuntime.AllUnits("), "全体单位");
					Check("【对象】「指定单体敌人」= 打出时选中的那个目标（拿不到才退回第一个敌人）",
						srcChosenEnemy.Contains("TargetOrFirst(__fgTarget"), "指定单体敌人");
					Check("这三种对象是真不一样（不是都落到自己）",
						srcAllies.Contains("AllAllies(") && srcSummons.Contains("SummonList(") && srcAllUnits.Contains("AllUnits(")
						&& srcEnemies.Contains("EnemyList("), "四种目标各不相同");
					Check("每个目标都会走一遍本体 API（foreach，而不是只打第一个）",
						srcEnemies.Contains("foreach (Creature __fgFoe in"), "foreach 在");

					// 图里【效果】造成伤害 + 【对象】自己 = 走本体**攻击链**（DamageCmd.Attack）→ **格挡能挡**）"
					// 只有「失去生命」才带 Unblockable（无视格挡）。用户问过「为什么对自己造成伤害不被护盾挡」—— 
					// 出问题的是效果栏那一条路（这一版修好了），图里这条路一直是对的，这里把它一起钉住。"
					uEff.SetField("Effect", "Damage");
					uEff.SetField("Amount", "5");
					string srcGraphSelfDmg = ForPick("Self");
					uEff.SetField("Effect", "HpLoss");
					uEff.SetField("Amount", "3");
					string srcGraphSelfHpLoss = ForPick("Self");
					Check("图里【造成伤害】+【对象】自己：走 DamageCmd.Attack（本体攻击链，**格挡能挡**）",
						srcGraphSelfDmg.Contains("DamageCmd.Attack(") && !srcGraphSelfDmg.Contains("ValueProp.Unblockable"),
						(srcGraphSelfDmg.Split('\n').FirstOrDefault(l => l.Contains("DamageCmd.Attack(")) ?? "(没找到 ").Trim());
					Check("（对照）图里【失去生命】+【对象】自己：Unblockable | Unpowered | Move（**无视格挡**）",
						srcGraphSelfHpLoss.Contains("ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move"),
						(srcGraphSelfHpLoss.Split('\n').FirstOrDefault(l => l.Contains("CreatureCmd.Damage")) ?? "(没找到 ").Trim());
					uEff.SetField("Effect", "Block");
					uEff.SetField("Amount", "4");

					// 选牌类效果（提示语要用 base.*，所以必须是内联生成的语句）
					string ExhaustSrc(string pick)
					{
						uEff.SetField("Effect", "ExhaustCard");
						uEff.SetField("Amount", "1");
						uEff.SetField("Pick", pick);
						return CSharpCodeGen.CardSource(Profile, uCard, 0);
					}
					string exChosen = ExhaustSrc("Chosen");
					string exRandom = ExhaustSrc("Random");
					Check("「消耗卡牌」自己选 = 弹本体选牌界面（CardSelectCmd.FromHand + ExhaustSelectionPrompt）",
						exChosen.Contains("CardSelectCmd.FromHand") && exChosen.Contains("CardSelectorPrefs.ExhaustSelectionPrompt")
						&& exChosen.Contains("CardCmd.Exhaust"), "生成在");
					Check("「消耗卡牌」随机 = 不用选牌界面（直接挑）",
						!exRandom.Contains("CardSelectCmd.FromHand") && exRandom.Contains("CardCmd.Exhaust"), "生成在");
					Check("提示语用的是本体的 LocString（不是字符串字面量 —— 那样编译不过）",
						exChosen.Contains("new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt"), "用的 LocString");
					Check("「从抽牌堆 / 弃牌堆 / 消耗牌堆拿牌」三档在**状态触发器**里也能用（用户报的用例：追忆「回合开始时从弃牌堆拿 1 张」）",
						PowerTriggers.Supports("TakeFromDiscard") && PowerTriggers.Supports("TakeFromDraw")
						&& PowerTriggers.Supports("TakeFromExhaust"), "状态里支持了");

					// 新一批效果（变化 / 复制 / 预见 / 药水 / 卡牌奖励）"
					string SrcFor(string fx, params (string K, string V)[] fields)
					{
						uEff.SetField("Effect", fx);
						foreach (var (k, v) in fields) uEff.SetField(k, v);
						return CSharpCodeGen.CardSource(Profile, uCard, 0);
					}
					Check("「变化卡牌」：指定目标卡时生成 CardCmd.Transform（带那张卡的类）",
						SrcFor("TransformCard", ("SpawnCardId", "Strike"), ("Pick", "Chosen")).Contains("CardCmd.Transform("),
						"生成在");
					Check("「变化卡牌」：没选目标卡时生成 TransformToRandom",
						SrcFor("TransformCard", ("SpawnCardId", ""), ("Pick", "Random")).Contains("TransformToRandom("), "生成在");
					Check("「复制卡牌」：CreateClone + AddGeneratedCardToCombat（本体二刀流的写法）",
						SrcFor("CopyCard", ("Pick", "Random")).Contains("CreateClone()"), "生成在");
					Check("「预见」：看抽牌堆顶 N 张 + FromSimpleGrid 挑要丢的（可以一张都不丢）",
						SrcFor("Scry", ("Amount", "3")).Contains("FromSimpleGrid("), "生成在");
					Check("「获得药水」：随机时走本体药水工厂（不是硬编码某一瓶）",
						SrcFor("GainPotion", ("PotionPick", "Random")).Contains("PotionFactory.CreateRandomPotionInCombat("), "生成在");
					Check("「获得药水」：指定时走 PotionCmd.TryToProcure<那一瓶>",
						SrcFor("GainPotion", ("PotionPick", "Fixed")).Contains("PotionCmd.TryToProcure"), "生成在");

					// 同一条链上两个同种效果：局部变量名必须各不相同（CS0128 回归钉子）"
					uEff.SetField("Effect", "CopyCard");
					uEff.SetField("Pick", "Random");
					var twin = new ForgeNodeSpec { Kind = "Effect" };
					twin.SetField("Effect", "CopyCard");
					twin.SetField("Pick", "Random");
					uCard.ForgeGraph!.Nodes.Add(twin);
					uCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = uEff.Id, To = twin.Id, FromPort = 0, ToPort = 0 });
					string twinSrc = CSharpCodeGen.CardSource(Profile, uCard, 0);
					var decls = System.Text.RegularExpressions.Regex.Matches(twinSrc, @"var (__fgSel\w*) =")
						.Select(m => m.Groups[1].Value).ToList();
					Check("同一条链上两个「复制卡牌」用的局部变量名不同（不然生成出来 CS0128 编译不过）",
						decls.Count == 2 && decls.Distinct().Count() == 2, string.Join(" / ", decls));
					uCard.ForgeGraph.Nodes.Remove(twin);
					uCard.ForgeGraph.Links.RemoveAll(l => l.From == uEff.Id && l.To == twin.Id);
					Profile.Cards.Remove(uCard);
				}

				// ===== 「战斗胜利时」 【卡牌奖励】（本体只在战斗结算里加奖励，所以必须嵌进那个钩子）=====
				{
					var rCard = new RelicSpec { Name = "自检奖励遗物", ClassName = "UiCheckReward", Rarity = "Common", Trigger = "CombatVictory", IsForged = true };
					rCard.ForgeGraph = new ForgeGraphSpec();
					var rt = new ForgeNodeSpec { Kind = "Trigger" };
					rt.SetField("Timing", ForgeTimings.CombatVictory);
					var rEff = new ForgeNodeSpec { Kind = "Effect" };
					rEff.SetField("Effect", "CardReward");
					rEff.SetField("Amount", "1");
					rCard.ForgeGraph.Nodes.AddRange(new[] { rt, rEff });
					rCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = rt.Id, To = rEff.Id, FromPort = 0, ToPort = 0 });
					Check("遗物图时机和遗物触发时机是同一个钩子时会被认出来（不然会生成两个同名 override）",
						ForgeGraphGen.RelicGraphNestsInTrigger(rCard, "CombatVictory"), "认出来了");
					string rSrc = CSharpCodeGen.RelicSource(Profile, rCard, 0);
					Check("节点图嵌进了遗物自己的触发钩子里（调 ForgeGraphOnTrigger(room)）",
						rSrc.Contains("await ForgeGraphOnTrigger(room);"), "嵌进去了");
					Check("嵌进来的那个方法带着 CombatRoom 参数（不然里面的 room 是未定义标识符）",
						rSrc.Contains("public async Task ForgeGraphOnTrigger(CombatRoom room)"), "带 room");
					Check("【卡牌奖励】生成的是本体那套 AddExtraReward + CardReward（不带 flag，存档不会抛异常）",
						rSrc.Contains("AddExtraReward(") && rSrc.Contains("new MegaCrit.Sts2.Core.Rewards.CardReward(")
						&& rSrc.Contains("CardCreationOptions.ForRoom("), "生成在");
					var wrongTrig = new ForgeNodeSpec { Kind = "Trigger" };
					wrongTrig.SetField("Timing", ForgeTimings.PlayerTurnStart);
					var wrongEff = new ForgeNodeSpec { Kind = "Effect" };
					wrongEff.SetField("Effect", "CardReward");
					wrongEff.SetField("Amount", "1");
					var wrongRelic = new RelicSpec
					{
						Name = "自检错时机", ClassName = "UiCheckRewardWrong", Trigger = "PlayerTurnStart", IsForged = true,
					};
					wrongRelic.ForgeGraph = new ForgeGraphSpec { Nodes = { wrongTrig, wrongEff } };
					wrongRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = wrongTrig.Id, To = wrongEff.Id, FromPort = 0, ToPort = 0 });
					string wrongSrc = CSharpCodeGen.RelicSource(Profile, wrongRelic, 0);
					bool wrongHasReward = wrongSrc.Contains("AddExtraReward(", StringComparison.Ordinal);
					bool wrongHasHint = wrongSrc.Contains("本体只能在", StringComparison.Ordinal);
					Check("【卡牌奖励】挂在别的时机上时不生成代码、只写一句说明（本体没有战斗中弹奖励的入口）",
						!wrongHasReward && wrongHasHint,
						$"生成奖励={wrongHasReward} / 有说明 {wrongHasHint}");
					Profile.Relics.Remove(rCard);

					// 「【效果】下拉里选得到、但节点图里什么都没生成」这一整类（别人报的「给召唤物 buff 不生效」），"
					// 以前整块布的图问题**一个都不报**（ForgeGraphGen.Problems 是死代码），现在都进校验器。"
					Check("节点图的「支持名单」认得出来（挡住「选了等于白选」的那一类）",
						ForgeGraphGen.SupportedEffectKinds.Contains("Damage") && ForgeGraphGen.SupportedEffectKinds.Contains("ApplyPower")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("PetApplyPower") && ForgeGraphGen.SupportedEffectKinds.Contains("CardReward")
						// V0.2.176：伙伴组 / 放置卡牌 / 给予关键词 / 刮削 / 填满手牌 / 暴露 / 额外回合 /
						// 抽到就减费 / 资源上限 / 透支能量 / 大限已至 / 转化为先古卡 都接上了（用户要求「全做」）
						&& ForgeGraphGen.SupportedEffectKinds.Contains("PetAttack")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("PetSacrifice")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("SummonPet")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("PlaceCard")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("GiveKeyword")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("ScrapeDraw")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("FillHand")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("Expose")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("ExtraTurn")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("CheapenDraw")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("RaiseResourceCap")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("OverdraftEnergy")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("TimesUp")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("AncientTranscend")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("ReplayCard")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("TurnEndPlay")
						&& ForgeGraphGen.SupportedEffectKinds.Contains("ReturnSelfToHand")
						// V0.2.203：用户截图报的「处决」用的就是这一档，现在卡牌图能生成
						&& ForgeGraphGen.SupportedEffectKinds.Contains("CheapenSelf")
						// 反例：仍然没接的（抽到就减费那档要挂卡自己的钩子 + 只有遗物 / 药水能配的那一档）
						&& !ForgeGraphGen.SupportedEffectKinds.Contains("CheapenSelfOnDraw")
						&& !ForgeGraphGen.SupportedEffectKinds.Contains("AncientRelicSwap"), "名单在");
					var badKindTrig = new ForgeNodeSpec { Kind = "Trigger" };
					badKindTrig.SetField("Timing", ForgeTimings.CardPlayed);
					var badKindEff = new ForgeNodeSpec { Kind = "Effect" };
					badKindEff.SetField("Effect", "AncientRelicSwap");   // 节点图没接上的一种（只有遗物 / 药水能配）
					badKindEff.SetField("Amount", "6");
					var badKindCard = new CardSpec
					{
						Name = "自检没接上的种类", ClassName = "UiCheckGraphKind", Cost = 1, CardType = "Attack", IsForged = true,
					};
					badKindCard.ForgeGraph = new ForgeGraphSpec { Nodes = { badKindTrig, badKindEff } };
					badKindCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = badKindTrig.Id, To = badKindEff.Id, FromPort = 0, ToPort = 0 });
					Profile.Cards.Add(badKindCard);
					var badKindIssues = ProfileValidator.Validate(Profile);
					Check("图里【效果】选了节点图没接上的种类 → **报错**拦住（以前是静默不生效）",
						badKindIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("节点图里还没接上")),
						string.Join(" ｜ ", badKindIssues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
					Check("报错里写清了两条出路（换种类 / 放到卡牌页的效果列表里）",
						badKindIssues.Any((ValidationIssue i) => i.Message.Contains("节点图现在支持") && i.Message.Contains("效果」列表")), "写清了");
					// 【效果】需要状态却没选：说「没选状态」，不能说成「节点图没接上这个种类。"
					foreach (var n2 in badKindCard.ForgeGraph!.Nodes) if (n2.Kind == "Effect") n2.SetField("Effect", "ApplyPower");
					var noPowerIssues = ProfileValidator.Validate(Profile);
					Check("图里【效果】没选状态 → 报错说的是「没选状态」（不是「节点图没接上」）",
						noPowerIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("还没选「状态」"))
						&& !noPowerIssues.Any((ValidationIssue i) => i.Message.Contains("节点图里还没接上")), "说对了");
					// 【数值】公式里的参数不存在：以前这条也没人把 
					var badVal = new ForgeNodeSpec { Kind = "Value" };
					badVal.SetField("Formula", "Q*2");
					badKindCard.ForgeGraph.Nodes.Add(badVal);
					badKindCard.ForgeGraph.Links.Add(new ForgeLinkSpec
					{
						From = badVal.Id, To = badKindEff.Id, FromPort = 0, ToPort = 1,
					});
					Check("图里【数值】用了没定义的参数 → 报错（以前这条没人报）",
						ProfileValidator.Validate(Profile).Any((ValidationIssue i) => i.IsError && i.Message.Contains("没有这个参数")), "报了");
					Profile.Cards.Remove(badKindCard);
					// 自定义状态上那块布：V0.2.194 起生成端**已经接了**（锻造页 →「状态列表」）——
					// 新口径是「**图非空 = 图说了算**」（ForgeGraphGen.UsesGraph(CustomPowerSpec)），
					// 所以这里要钉住的是那件**用户会踩的事**：页面上配过触发时机 / 效果、布上又有图时，
					// 老那套**不再参与生成** —— 必须说出来（不然用户在「自定义状态」页改了没反应会一头雾水）。
					// ⚠ 老断言写的是「生成端还没接（要警告）」，那句话已经过期（Core 已接），这里跟着换掉。
					var cpGraph = new CustomPowerSpec { Name = "自检布状态", Enabled = true, HpBarColor = "" };
					cpGraph.Triggers.Add(new PowerTriggerSpec { Kind = "TurnStart" });      // 老内容：页面上配过
					cpGraph.ForgeGraph = new ForgeGraphSpec { Nodes = { new ForgeNodeSpec { Kind = "Trigger" } } };
					Profile.CustomPowers.Add(cpGraph);
					Check("自定义状态：布上有图 + 页面上也配过 → 警告「现在由锻造页那块布说了算（老那套不再参与生成）」",
						ProfileValidator.Validate(Profile).Any((ValidationIssue i) => i.Level == "警告"
							&& i.Message.Contains("现在由锻造页那块布说了算") && i.Message.Contains("不再参与生成")), "警告了");
					// 反过来：只画了图、页面上一样都没配 → 没有「盖过老那套」这回事，不该报这条警告
					//（不然「纯在锻造页新造一只状态」这种最正常的用法会平白多一句警告）。
					cpGraph.Triggers.Clear();
					Check("（对照）只画了图、页面上没配过东西 → 不报那条警告（没有可盖的）",
						!ProfileValidator.Validate(Profile).Any((ValidationIssue i) => i.Message.Contains("现在由锻造页那块布说了算")), "没报");
					Profile.CustomPowers.Remove(cpGraph);
				}

				// ===== 第 9 批 ④（后半段）：锻造页【触发时机】和遗物 / 状态 / 卡牌那份菜单**合并成同一套** =====
				// 三件事一起钉住：① 菜单 id 集合双向相等（单一事实来源 = 遗物页那份）；
				//            ② 菜单里列出来的每一条都**真的生成正确代码**（签名 = 遗物页同一份 + 归属守卫）；
				//            ③ 本体没给 choiceContext 的时机自己造一个（造不出来时校验器报错拦住）。
				{
					// ---- (1) 菜单同步 ----
					var forgeRelicIds = ForgeTimings.For("Relic").Select(t => t.Id).ToList();
					var pageRelicIds = EffectCatalog.RelicTriggers.Select(t => t.Id).ToList();
					// 锻造页专属的两条（「当遗物被点击时」「血量低于 N」）**不在**遗物页那份里 ——
					// 比集合时先把它们去掉，剩下的必须和遗物页**双向相等**（一条不多一条不少）。
					var forgeSharedIds = forgeRelicIds
						.Where(id => id != ForgeTimings.RelicClicked && id != ForgeTimings.HpBelow).ToList();
					var missing = pageRelicIds.Except(forgeSharedIds).ToList();
					var extra = forgeSharedIds.Except(pageRelicIds).ToList();
					Check("锻造页遗物档的触发时机（去掉锻造页专属那两条）= 遗物页那份（双向相等：一条不多一条不少）",
						forgeSharedIds.ToHashSet(StringComparer.Ordinal).SetEquals(pageRelicIds)
						&& forgeSharedIds.Count == forgeSharedIds.Distinct(StringComparer.Ordinal).Count(),
						$"锻造共享 {forgeSharedIds.Count} 条 / 遗物页 {pageRelicIds.Count} 条；"
						+ "多=" + (extra.Count == 0 ? "（无）" : string.Join("/", extra))
						+ " 少=" + (missing.Count == 0 ? "（无）" : string.Join("/", missing)));
					Check("锻造页专属的两条（当遗物被点击时 / 血量低于 N）是**唯一**的额外项（第 9 批 ④ 前半段那两条不动）",
						forgeRelicIds.Except(pageRelicIds).OrderBy(x => x, StringComparer.Ordinal)
							.SequenceEqual(new[] { ForgeTimings.HpBelow, ForgeTimings.RelicClicked })
						&& !pageRelicIds.Except(forgeRelicIds).Any(),
						"额外项=" + string.Join("/", forgeRelicIds.Except(pageRelicIds)) + "（正好这两条）");
					// 补齐的那 20 条：Id / 显示名 / 钩子名都逐字照抄遗物页那条（copy 一份就够，别再自己写一套）
					string[] addedIds =
					{
						"CombatEnd", "DamageDealt", "EnergySpent", "StarsSpent", "CardGenerated", "PowerReached",
						"CardPlayed", "CardExhausted", "CardDrawn", "CardDiscarded", "HpLost", "BlockGained",
						"EnemyDeath", "EnemyTurnStart", "EnemyTurnEnd", "EnemyDamaged", "EnemyDealtDamage",
						"EnemyBlockGained", "PowerChanged", "PowerRemoved",
						// V0.2.179：回合开始那三档（用户要求「触发时机加一个回合开始后」）
						"PlayerTurnStartEarly", "PlayerTurnStartLate",
					};
					var copyBad = new List<string>();
					foreach (string id in addedIds)
					{
						var pageOpt = EffectCatalog.RelicTriggers.FirstOrDefault(t => t.Id == id);
						var forgeOpt = ForgeTimings.For("Relic").FirstOrDefault(t => t.Id == id);
						if (pageOpt is null || forgeOpt is null) { copyBad.Add(id + "(缺)"); continue; }
						if (!string.Equals(pageOpt.Display, forgeOpt.Display, StringComparison.Ordinal)) copyBad.Add(id + "(显示名)");
						// 钩子名：PowerRemoved 那条遗物页写的是「工具补丁：…」说明，锻造页用补丁调过来的方法名
						if (id != "PowerRemoved")
						{
							int paren = pageOpt.HookSignature.IndexOf('(');
							string pageHook = paren > 0 ? pageOpt.HookSignature[..paren] : pageOpt.HookSignature;
							if (!string.Equals(pageHook, forgeOpt.Hook, StringComparison.Ordinal)) copyBad.Add(id + "(钩子名)");
						}
						else if (!string.Equals(forgeOpt.Hook, CSharpCodeGen.PowerRemovedMethod, StringComparison.Ordinal))
							copyBad.Add(id + "(钩子名)");
					}
					Check("补齐的那 20 条：Id / 显示名 / 钩子名都逐字照抄遗物页（单一事实来源）",
						copyBad.Count == 0, copyBad.Count == 0 ? $"{addedIds.Length} 条全对" : string.Join(" ｜ ", copyBad));

					// ---- (2) 守卫：逐个时机造一张最小锻造遗物图（【触发时机】+【效果：获得格挡 1 点】）调生成 ----
					// 期望表 = 「**需要**归属守卫」的那些时机 → 期望出现的片段（和 CSharpCodeGen.ForgeTriggerGuardLines
					// / 遗物页那个 switch 一一对应）。
					var guardTable = new (string Id, string Guard)[]
					{
						(ForgeTimings.CombatStart, "if (!participants.Contains(base.Owner.Creature) || base.Owner.PlayerCombatState.TurnNumber > 1) return;"),
						(ForgeTimings.PlayerTurnStart, "if (player != base.Owner) return;"),
						// V0.2.179：回合开始那两档（抽牌前 / 最晚）—— 三个不同钩子，归属判据和上面那条一样
						(ForgeTimings.PlayerTurnStartEarly, "if (player != base.Owner) return;"),
						(ForgeTimings.PlayerTurnStartLate, "if (player != base.Owner) return;"),
						(ForgeTimings.PlayerTurnEnd, "if (side != base.Owner.Creature.Side) return;"),
						(ForgeTimings.DamageReceived, "if (result.UnblockedDamage <= 0) return;"),
						(ForgeTimings.Attacked, "if (__takenThisAttack <= 0) return;"),
						(ForgeTimings.GoldGained, "if (player != base.Owner) return;"),
						(ForgeTimings.DamageDealt, "if (dealer != base.Owner.Creature) return;"),
						(ForgeTimings.EnergySpent, "if (amount <= 0 || card?.Owner?.Creature != base.Owner.Creature) return;"),
						(ForgeTimings.StarsSpent, "if (amount <= 0 || spender != base.Owner) return;"),
						(ForgeTimings.CardGenerated, "if (creator is null || creator != base.Owner) return;"),
						(ForgeTimings.PowerReached, "power.Amount - amount <"),
						(ForgeTimings.CardPlayed, "if (cardPlay.Player != base.Owner) return;"),
						(ForgeTimings.CardResolved, "if (cardPlay.Player != base.Owner) return;"),
						(ForgeTimings.CardExhausted, "if (card?.Owner?.Creature != base.Owner.Creature) return;"),
						(ForgeTimings.CardDrawn, "if (card?.Owner?.Creature != base.Owner.Creature) return;"),
						(ForgeTimings.CardDiscarded, "if (card?.Owner?.Creature != base.Owner.Creature) return;"),
						(ForgeTimings.HpLost, "if (delta >= 0m) return;"),
						(ForgeTimings.BlockGained, "if (creature != base.Owner.Creature) return;"),
						(ForgeTimings.EnemyDeath, "if (!creature.IsEnemy) return;"),
						(ForgeTimings.EnemyTurnStart, "if (side != CombatSide.Enemy) return;"),
						(ForgeTimings.EnemyTurnEnd, "if (side != CombatSide.Enemy) return;"),
						(ForgeTimings.EnemyDamaged, "if (target == base.Owner.Creature || !target.IsAlive) return;"),
						(ForgeTimings.EnemyDealtDamage, "if (dealer is null || dealer == base.Owner.Creature) return;"),
						(ForgeTimings.EnemyBlockGained, "if (creature == base.Owner.Creature) return;"),
						(ForgeTimings.PowerChanged, "if (power is not StrengthPower) return;"),
						(ForgeTimings.PowerRemoved, "if (power is not StrengthPower) return;"),
						(ForgeTimings.Shuffle, "if (shuffler != base.Owner) return;"),
					};
					// **合理没有**归属守卫的（遗物页那边同样没有）：这几个时刻本身就是「全部条件」，
					// 或者那个钩子只会为自己触发。锻造页专属的 RelicClicked / HpBelow 的进门条件是
					// 「血量门槛 / 生效次数」（EmitTimingGate），不是归属守卫。
					var noGuardIds = new[]
					{
						ForgeTimings.Obtained, ForgeTimings.CombatVictory, ForgeTimings.CombatEnd,
						ForgeTimings.RelicClicked, ForgeTimings.HpBelow,
					};
					// 「本体没给 choiceContext、但能自己造一个」的时机（第 9 批 ④ 第 4 条）：
					// 战斗里那几条造 HookPlayerChoiceContext（造不出来的话效果会拿到 null! 在运行时炸）
					string[] hookBootstrapIds =
					{
						"EnergySpent", "StarsSpent", "CardGenerated", "HpLost", "BlockGained",
						"EnemyTurnStart", "EnemyBlockGained", "PowerRemoved", "HpBelow",
						// V0.2.157：「打出一张牌时」= BeforeCardPlayed(CardPlay)，本体没给 choiceContext → 自己造
						"CardPlayed",
					};
					// 造不出来的那几条（战斗胜利 / 战斗结束 / 获得金币 / 遗物被点击）：需要 context 的效果由校验器报错拦住
					string[] noContextIds = { "CombatVictory", "CombatEnd", "GoldGained", "RelicClicked" };
					// 一共 34 条 = 29 条「需要守卫」+ 5 条「本来就没有守卫」（Obtained / CombatVictory / CombatEnd /
					// RelicClicked / HpBelow）—— 和 ForgeTimings.For("Relic") 的条数一致。
					var rows = guardTable.Select(x => (x.Id, x.Guard))
						.Concat(noGuardIds.Select(id => (id, ""))).ToList();
					// 兜底：清单和目录**必须一一对应**（漏一条就少测一条时机；多一条就是清单里写了个不存在的 id）
					var rowIds = rows.Select(x => x.Item1).ToList();
					Check("自检清单和 ForgeTimings.For(\"Relic\") 一一对应（一条不多一条不少，且没有重复 id）",
						rowIds.ToHashSet(StringComparer.Ordinal).SetEquals(forgeRelicIds)
						&& rowIds.Count == forgeRelicIds.Count
						&& rowIds.Distinct(StringComparer.Ordinal).Count() == rowIds.Count,
						$"清单 {rowIds.Count} 条 / 目录 {forgeRelicIds.Count} 条；"
						+ "多=" + (rowIds.Except(forgeRelicIds).Any() ? string.Join("/", rowIds.Except(forgeRelicIds)) : "（无）")
						+ " 少=" + (forgeRelicIds.Except(rowIds).Any() ? string.Join("/", forgeRelicIds.Except(rowIds)) : "（无）"));
					int guardPass = 0, noGuardPass = 0, sigPass = 0, ctxPass = 0, sharedCount = 0;
					var guardBad = new List<string>();
					var noGuardBad = new List<string>();
					var sigBad = new List<string>();
					var ctxBad = new List<string>();
					foreach (var (id, guard) in rows)
					{
						var probeRelic = new RelicSpec
						{
							Name = "自检守卫" + id, ClassName = "UiCheckGuard" + id, Rarity = "Common",
							Trigger = "Obtained", IsForged = true,
						};
						probeRelic.ForgeGraph = new ForgeGraphSpec();
						var pTrig = new ForgeNodeSpec { Kind = "Trigger" };
						pTrig.SetField("Timing", id);
						pTrig.SetField("PowerId", "StrengthPower");
						pTrig.SetNumber("PowerAmount", 3);
						var pEff = ForgeEffectNode("Block", "", 1, "");
						probeRelic.ForgeGraph.Nodes.AddRange(new[] { pTrig, pEff });
						probeRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = pTrig.Id, To = pEff.Id, FromPort = 0, ToPort = 0 });
						string guardSrc = CSharpCodeGen.RelicSource(Profile, probeRelic, 0);
						string zh = ForgeTimings.Find(id, "Relic")?.Display ?? id;
						// ① 守卫（「只认属于自己的那件事」）
						//    需要守卫的：必须含期望片段；不需要的：**一条守卫都不许混进来**
						bool gOk;
						if (guard.Length > 0)
						{
							gOk = guardSrc.Contains(guard, StringComparison.Ordinal);
							if (gOk) guardPass++; else guardBad.Add(id + "（缺「" + guard + "」）");
						}
						else
						{
							gOk = !guardTable.Any(x => guardSrc.Contains(x.Guard, StringComparison.Ordinal));
							if (gOk) noGuardPass++; else noGuardBad.Add(id);
						}
						Check(guard.Length > 0
							? $"锻造遗物用「{zh}」时带归属守卫（{guard}）"
							: $"锻造遗物用「{zh}」时**不需要**归属守卫（这一刻就是全部条件 / 是锻造页专属），生成结果里也没混进任何守卫",
							gOk, gOk ? "对" : "不对");
						// ② 签名 = 遗物页那一份（逐字；RelicSource 里那条 override 就是它）。
						//    RelicClicked / HpBelow 是锻造页专属的两条，签名留在 ForgeGraphGen 自己的 switch 里
						//    （见下面 (3) 单独钉），所以这里只查共享的那些。
						if (pageRelicIds.Contains(id))
						{
							sharedCount++;
							bool sOk = guardSrc.Contains(CSharpCodeGen.RelicTriggerSignature(id), StringComparison.Ordinal);
							if (sOk) sigPass++; else sigBad.Add(id);
						}
						// ③ choiceContext：能造的必须造出来（不然效果里引用不存在的变量 / 传 null!）
						string wantCtx =
							hookBootstrapIds.Contains(id, StringComparer.Ordinal) ? "Hook"
							: noContextIds.Contains(id, StringComparer.Ordinal) ? "None"
							: id == ForgeTimings.Obtained ? "Blocking"   // 嵌在 AfterObtained 里 → 阻塞式
							: "Param";                                   // 本体钩子自带 choiceContext
						bool cOk = wantCtx switch
						{
							"Hook" => guardSrc.Contains("HookPlayerChoiceContext", StringComparison.Ordinal)
								&& !guardSrc.Contains("null!", StringComparison.Ordinal),
							"Blocking" => guardSrc.Contains("BlockingPlayerChoiceContext", StringComparison.Ordinal),
							"None" => guardSrc.Contains("null!", StringComparison.Ordinal),
							_ => !guardSrc.Contains("null!", StringComparison.Ordinal)
								&& !guardSrc.Contains("HookPlayerChoiceContext", StringComparison.Ordinal)
								&& !guardSrc.Contains("BlockingPlayerChoiceContext", StringComparison.Ordinal),
						};
						if (cOk) ctxPass++; else ctxBad.Add(id + "（期望 " + wantCtx + "）");
					}
					Check($"**需要**归属守卫的 {guardTable.Length} 条时机全都有守卫（以前一条都没有：敌人打我 / 敌人打牌也会触发自己的遗物）",
						guardPass == guardTable.Length && guardBad.Count == 0,
						guardPass == guardTable.Length ? $"{guardPass}/{guardTable.Length}" : $"缺：{string.Join("/", guardBad)}");
					Check($"另外 {noGuardIds.Length} 条**本来就不该有**归属守卫（这一刻就是全部条件 / 是锻造页专属）—— 生成结果里也没混进守卫",
						noGuardPass == noGuardIds.Length && noGuardBad.Count == 0,
						noGuardPass == noGuardIds.Length ? $"{noGuardPass}/{noGuardIds.Length}（合理）" : $"混进守卫：{string.Join("/", noGuardBad)}");
					Check($"共享的 {sharedCount} 条时机签名都 = 遗物页那份 RelicTriggerSignature（逐字，别再抄第二份）",
						sigPass == sharedCount && sigBad.Count == 0,
						sigPass == sharedCount ? $"{sigPass}/{sharedCount}" : $"不对：{string.Join("/", sigBad)}");
					Check($"{rows.Count} 条时机的 choiceContext 都对：本体钩子自带的直接用 / 获得时造阻塞式 / 战斗里造 HookPlayerChoiceContext / 造不出来的（CombatVictory·CombatEnd·GoldGained·RelicClicked）留 null! 由校验器拦",
						ctxPass == rows.Count && ctxBad.Count == 0,
						ctxPass == rows.Count ? $"{ctxPass}/{rows.Count}" : $"不对：{string.Join("/", ctxBad)}");

					// ---- (3) 锻造页专属那两条（不能碰，单独钉住）----
					{
						var clickedRelic = new RelicSpec { Name = "自检点击", ClassName = "UiCheckGuardClicked", Rarity = "Common", Trigger = "Obtained", IsForged = true };
						clickedRelic.ForgeGraph = new ForgeGraphSpec();
						var cTrig = new ForgeNodeSpec { Kind = "Trigger" };
						cTrig.SetField("Timing", ForgeTimings.RelicClicked);
						var cEff = ForgeEffectNode("Block", "", 1, "");
						clickedRelic.ForgeGraph.Nodes.AddRange(new[] { cTrig, cEff });
						clickedRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = cTrig.Id, To = cEff.Id, FromPort = 0, ToPort = 0 });
						string cSrc = CSharpCodeGen.RelicSource(Profile, clickedRelic, 0);
						Check("「当遗物被点击时」照旧生成普通方法 ForgeOnRelicClicked()（补丁转发；这条是锻造页专属，不动）",
							cSrc.Contains("public async Task ForgeOnRelicClicked()", StringComparison.Ordinal), "生成在");
						Check("「当遗物被点击时」照旧**不造** choiceContext（点击可能发生在局外，造了会卡住）",
							!cSrc.Contains("HookPlayerChoiceContext", StringComparison.Ordinal)
							&& !cSrc.Contains("BlockingPlayerChoiceContext", StringComparison.Ordinal), "没造");

						var hpRelic = new RelicSpec { Name = "自检血量图", ClassName = "UiCheckGuardHp", Rarity = "Common", Trigger = "Obtained", IsForged = true };
						hpRelic.ForgeGraph = new ForgeGraphSpec();
						var hTrig = new ForgeNodeSpec { Kind = "Trigger" };
						hTrig.SetField("Timing", ForgeTimings.HpBelow);
						hTrig.SetNumber("HpThreshold", 0.5);
						var hEff = ForgeEffectNode("Block", "", 1, "");
						hpRelic.ForgeGraph.Nodes.AddRange(new[] { hTrig, hEff });
						hpRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = hTrig.Id, To = hEff.Id, FromPort = 0, ToPort = 0 });
						string hSrc = CSharpCodeGen.RelicSource(Profile, hpRelic, 0);
						Check("「血量低于 N」照旧是 AfterCurrentHpChanged + 血量门槛守卫",
							hSrc.Contains("public override async Task AfterCurrentHpChanged(Creature creature, decimal delta)", StringComparison.Ordinal)
							&& hSrc.Contains("if (__fgWatch is null", StringComparison.Ordinal), "生成在");
						Check("「血量低于 N」的图里需要用 choiceContext 的效果现在也能用了（以前引用不存在的变量 → CS0103）",
							hSrc.Contains("HookPlayerChoiceContext", StringComparison.Ordinal), "造出来了");
					}

					// ---- (4) 造不出 choiceContext 的时机 + 需要它的效果 → 校验器**报错**拦住（不静默生成坏代码）----
					{
						var noneRelic = new RelicSpec { Name = "自检没上下文", ClassName = "UiCheckNoCtx", Rarity = "Common", Trigger = "Obtained", IsForged = true };
						noneRelic.ForgeGraph = new ForgeGraphSpec();
						var nTrig = new ForgeNodeSpec { Kind = "Trigger" };
						nTrig.SetField("Timing", ForgeTimings.CombatVictory);
						var nEff = ForgeEffectNode("Draw", "", 1, "");     // 抽牌要 choiceContext
						noneRelic.ForgeGraph.Nodes.AddRange(new[] { nTrig, nEff });
						noneRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = nTrig.Id, To = nEff.Id, FromPort = 0, ToPort = 0 });
						var noneIssues = ForgeGraphGen.Issues(noneRelic.ForgeGraph, Profile, "Relic");
						Check("「战斗胜利时 + 需要 choiceContext 的效果」→ 校验器报**错误**并说清（本体那个钩子没给、也造不出来）",
							noneIssues.Any(x => x.Level == "错误" && x.Message.Contains("choiceContext")),
							noneIssues.FirstOrDefault(x => x.Level == "错误").Message ?? "(没报)");
					}

					// ---- (5)「状态被移除时」：只用在**锻造图**上时也必须生成那个通知补丁，并把这个类列进去 ----
					{
						var prProf = ProfileFactory.Sample();
						prProf.Relics.Clear();
						var prRelic = new RelicSpec { Name = "自检移除", ClassName = "UiCheckGraphPowerRemoved", Rarity = "Common", Trigger = "Obtained", IsForged = true };
						prRelic.ForgeGraph = new ForgeGraphSpec();
						var prTrig = new ForgeNodeSpec { Kind = "Trigger" };
						prTrig.SetField("Timing", ForgeTimings.PowerRemoved);
						prTrig.SetField("PowerId", "VulnerablePower");
						var prEff = ForgeEffectNode("Block", "", 1, "");
						prRelic.ForgeGraph.Nodes.AddRange(new[] { prTrig, prEff });
						prRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = prTrig.Id, To = prEff.Id, FromPort = 0, ToPort = 0 });
						prProf.Relics.Add(prRelic);
						string prSrc = CSharpCodeGen.PowerRemovalSource(prProf);
						Check("锻造图选「某个状态被移除时」→ 也生成通知补丁，并且把这只遗物列进转发名单"
							+ "（不列的话那个方法永远不会被调用 = 菜单里有、什么都不做）",
							CSharpCodeGen.UsesPowerRemovedTrigger(prProf)
							&& prSrc.Contains("case UiCheckGraphPowerRemoved __r:", StringComparison.Ordinal), "列进去了");
						Check("没用到这条时机时**不**生成那个补丁文件（默认档一个字符都不多）",
							!CSharpCodeGen.UsesPowerRemovedTrigger(ProfileFactory.Sample()), "干净");
					}

					// ---- (6)【触发时机】上新加的两栏：只在状态层数那三条时机上显示 ----
					{
						var uiTrig = new ForgeNodeSpec { Kind = "Trigger" };
						Check("【触发时机】的「盯哪个状态 / 到达 N 层」只在「到达 N 层 / 层数变化 / 被移除」这三条时机上显示",
							ForgeCanvas.TriggerFieldVisibleForCheck(uiTrig, ForgeTimings.PowerReached, "PowerId")
							&& ForgeCanvas.TriggerFieldVisibleForCheck(uiTrig, ForgeTimings.PowerReached, "PowerAmount")
							&& ForgeCanvas.TriggerFieldVisibleForCheck(uiTrig, ForgeTimings.PowerChanged, "PowerId")
							&& ForgeCanvas.TriggerFieldVisibleForCheck(uiTrig, ForgeTimings.PowerRemoved, "PowerAmount")
							&& !ForgeCanvas.TriggerFieldVisibleForCheck(uiTrig, ForgeTimings.PlayerTurnStart, "PowerId")
							&& !ForgeCanvas.TriggerFieldVisibleForCheck(uiTrig, ForgeTimings.EnemyDeath, "PowerAmount"),
							"该显示的显示 / 该藏起来的藏起来");
					}

					// ---- (7) 探针踩出来的两个坑（本次一并修掉，钉死防止回来）----
					{
						// (a)「生效次数」填 0 = 无限次时，以前生成的是 `if (__fgUses >= 0) return;` ——
						//    那个条件恒成立，整张图一次都不跑（「菜单里有、生成出来什么都不做」）。
						RelicSpec MakeCount(string cls, string timing, double count)
						{
							var r = new RelicSpec { Name = cls, ClassName = cls, Rarity = "Common", Trigger = "Obtained", IsForged = true };
							r.ForgeGraph = new ForgeGraphSpec();
							var t = new ForgeNodeSpec { Kind = "Trigger" };
							t.SetField("Timing", timing);
							if (count >= 0) t.SetNumber("CountLimit", count);
							var e = ForgeEffectNode("Block", "", 1, "");
							r.ForgeGraph.Nodes.AddRange(new[] { t, e });
							r.ForgeGraph.Links.Add(new ForgeLinkSpec { From = t.Id, To = e.Id, FromPort = 0, ToPort = 0 });
							return r;
						}
						foreach (string tId in new[] { ForgeTimings.HpBelow, ForgeTimings.RelicClicked })
						{
							string unlimited = CSharpCodeGen.RelicSource(Profile, MakeCount("UiCheckCountFree", tId, 0), 0);
							string twice = CSharpCodeGen.RelicSource(Profile, MakeCount("UiCheckCountTwice", tId, 2), 0);
							string zh = ForgeTimings.Find(tId, "Relic")!.Display;
							Check($"「{zh}」的生效次数填 0（无限次）时**真的会做事**（以前那句 `__fgUses >= 0` 恒成立 = 永不触发）",
								unlimited.Contains("CreatureCmd.GainBlock(", StringComparison.Ordinal)
								&& !unlimited.Contains("__fgUses >= 0", StringComparison.Ordinal), "会做事");
							Check($"「{zh}」的生效次数填 2 时仍然是老写法（够了就 return + 变灰）",
								twice.Contains("if (__fgUses >= 2) return;", StringComparison.Ordinal)
								&& twice.Contains("Status = RelicStatus.Disabled;", StringComparison.Ordinal), "生成在");
						}
						// (b) 图嵌进遗物自己的触发钩子时**不能再写一遍**归属守卫：外面那个 override 已经判过，
						//    而且那个普通方法没有钩子参数（写了会 CS0103）。
						var nestRelic = new RelicSpec { Name = "自检嵌套", ClassName = "UiCheckNestGuard", Rarity = "Common", Trigger = "CardPlayed", IsForged = true };
						nestRelic.ForgeGraph = new ForgeGraphSpec();
						var nestTrig = new ForgeNodeSpec { Kind = "Trigger" };
						nestTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var nestEff = ForgeEffectNode("Draw", "", 1, "");
						nestRelic.ForgeGraph.Nodes.AddRange(new[] { nestTrig, nestEff });
						nestRelic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = nestTrig.Id, To = nestEff.Id, FromPort = 0, ToPort = 0 });
						string nestSrc = CSharpCodeGen.RelicSource(Profile, nestRelic, 0);
						int guardTimes = nestSrc.Split("if (cardPlay.Player != base.Owner) return;").Length - 1;
						Check("图嵌进遗物自己的触发钩子时守卫只判一次（外面那次就够了；里面再写会引用不存在的 cardPlay → CS0103）",
							guardTimes == 1 && nestSrc.Contains("await ForgeGraphOnTrigger();", StringComparison.Ordinal),
							$"守卫出现 {guardTimes} 次");
						Check("嵌进去的那个方法里要用 choiceContext 的效果也有上下文（自己造一个，不再引用不存在的变量）",
							nestSrc.Contains("HookPlayerChoiceContext", StringComparison.Ordinal), "造出来了");
					}
				}

				// ===== 【if】的「条件」挪到左边入口（用户要求）：老存档必须自动迁移 =====
				// 老版端口：出口 0 = 条件插槽」  = 是」  = 否；新版：入口 1 = 条件、出口 0 = 是」  = 否」"
				// 不迁移的话「是 / 否」两边会**悄悄对调**（下标含义变了）—— 所以这里把它锁死。"
				{
					var oldProf = new CharacterProfile();
					var oldCard = new CardSpec { Name = "老图", ClassName = "UiCheckOldIfPorts", IsForged = true };
					var og = new ForgeGraphSpec();
					var oTrig = new ForgeNodeSpec { Kind = "Trigger" };
					oTrig.SetField("Timing", ForgeTimings.CardPlayed);
					var oIf = new ForgeNodeSpec { Kind = "If" };
					var oYes = new ForgeNodeSpec { Kind = "Effect" };
					oYes.SetField("Effect", "Damage");
					var oNo = new ForgeNodeSpec { Kind = "Effect" };
					oNo.SetField("Effect", "HpLoss");
					var oCond = new ForgeNodeSpec { Kind = "Condition" };
					oCond.SetField("Cond", "HandAtLeast");
					var oJunk = new ForgeNodeSpec { Kind = "Unit" };
					og.Nodes.AddRange(new[] { oTrig, oIf, oYes, oNo, oCond, oJunk });
					// 老版存法：链线进 if.0；条件是 if.0 → 条件（从条件口往外拖的反向线）；是 1、否=2
					og.Links.Add(new ForgeLinkSpec { From = oTrig.Id, To = oIf.Id, FromPort = 0, ToPort = 0 });
					og.Links.Add(new ForgeLinkSpec { From = oIf.Id, To = oCond.Id, FromPort = 0, ToPort = 0 });
					og.Links.Add(new ForgeLinkSpec { From = oIf.Id, To = oYes.Id, FromPort = 1, ToPort = 0 });
					og.Links.Add(new ForgeLinkSpec { From = oIf.Id, To = oNo.Id, FromPort = 2, ToPort = 0 });
					oldCard.ForgeGraph = og;
					oldProf.Cards.Add(oldCard);
					Check("老存档（没有端口版本号）会被识别成要迁移", oldProf.ForgeGraphPortVersion == 0, $"{oldProf.ForgeGraphPortVersion}");
					int migrated = ForgeGraphGen.MigrateIfPorts(oldProf);
					Check("迁移：入口版本号被抬到新版", oldProf.ForgeGraphPortVersion == ForgeGraphGen.PortVersion, $"{oldProf.ForgeGraphPortVersion}");
					Check("迁移：「是」从出口 1 挪到 0、「否」从 2 挪到 1（**不会对调**）",
						og.Links.Any(l => l.From == oIf.Id && l.FromPort == 0 && l.To == oYes.Id)
						&& og.Links.Any(l => l.From == oIf.Id && l.FromPort == 1 && l.To == oNo.Id),
						string.Join(" / ", og.Links.Where(l => l.From == oIf.Id).Select(l => l.FromPort + "→" + (l.To == oYes.Id ? "是" : "否"))));
					Check("迁移：老版那条「从条件口往外拖」的反向残留线被删掉（**但条件本身被扶正、没丢**）",
						!og.Links.Any(l => l.From == oIf.Id && l.To == oCond.Id)
						&& og.Links.Any(l => l.From == oCond.Id && l.To == oIf.Id && l.ToPort == 1), "扶正了");
					Check("迁移：接进 if 的执行链线不动（还是入口 0）",
						og.Links.Any(l => l.To == oIf.Id && l.ToPort == 0 && l.From == oTrig.Id), "链线在");
					int again = ForgeGraphGen.MigrateIfPorts(oldProf);
					Check("迁移是幂等的（再跑一次什么都不改）", again == 0, $"{again}");
					// 新版布局下：链线过 0、条件线过 1，两条各走各的口（不再像老版那样两个口都是 0）"
					Check("新版：条件线在入口 1、链线在入口 0（各走各的，不会互相顶掉）",
						og.Links.Count(l => l.To == oIf.Id && l.ToPort == 1) == 1
						&& og.Links.Count(l => l.To == oIf.Id && l.ToPort == 0) == 1, "两条都在");
					var oldSrc = CSharpCodeGen.CardSource(oldProf, oldCard, 0);
					Check("新版：这样连出来的条件真的进了 if（老存档不用重连）",
						oldSrc.Contains("PileType.Hand") && !oldSrc.Contains("if (false)"),
						(oldSrc.Split('\n').FirstOrDefault(l => l.TrimStart().StartsWith("if (", StringComparison.Ordinal)) ?? "(没找到 if)").Trim());
					// 条件口上再插一条别的条件：执行链那条线（入口 0）不受影响"
					var rel2 = new ForgeNodeSpec { Kind = "Relate" };
					rel2.SetField("Op", "Gt");
					rel2.SetField("Amount", "3");
					og.Nodes.Add(rel2);
					var rel2L = new ForgeNodeSpec { Kind = "Value" };
					rel2L.SetField("Formula", "1");
					og.Nodes.Add(rel2L);
					og.Links.Add(new ForgeLinkSpec { From = rel2L.Id, To = rel2.Id, FromPort = 0, ToPort = 1 });
					og.Links.Add(new ForgeLinkSpec { From = rel2.Id, To = oIf.Id, FromPort = 0, ToPort = 1 });
					Check("新版：条件口上换一条来源，执行链那条线（入口 0）还在（老版会被一起删掉）",
						og.Links.Count(l => l.To == oIf.Id && l.ToPort == 0) == 1
						&& og.Links.Any(l => l.To == oIf.Id && l.ToPort == 1 && l.From == rel2.Id), "链线没被波及");
				}

				{
					ForgeItemList.SelectedItem = forged;
					SyncForgeDetail();
					UpdateLayout();
					ForgeCanvas.SelectAll();
					int sel = ForgeCanvas.SelectedCount;
					int energyNodes = forged.ForgeGraph!.Nodes.Count(n => n.Kind == "Energy");
					// V0.2.128：固定模块变成两个 —— 【能量】和【触发时机】都不参与全选（都删不掉）
					int triggerNodes = forged.ForgeGraph.Nodes.Count(n => n.Kind == "Trigger");
					Check("画布「全选」选上了全部模块（【能量】/【触发时机】是固定模块，不参与选中）",
						sel == forged.ForgeGraph.Nodes.Count - energyNodes - triggerNodes,
						$"{sel} / {forged.ForgeGraph.Nodes.Count}（能量 {energyNodes} 块、触发时机 {triggerNodes} 块）");
					// 需求：「让【能量】无法被选中和删除」。用一张**自己的小图**验（不动 forged 那块布）。"
					{
						var lkTrig = new ForgeNodeSpec { Kind = "Trigger", X = 20, Y = 20 };
						lkTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var lkEnergy = new ForgeNodeSpec { Kind = "Energy", X = ForgeGraphCatalog.EnergyX, Y = ForgeGraphCatalog.EnergyY };
						var lkVal = new ForgeNodeSpec { Kind = "Value", X = 320, Y = 120 };
						lkVal.SetField("Formula", "X");
						var lkEff = new ForgeNodeSpec { Kind = "Effect", X = 20, Y = 200 };
						lkEff.SetField("Effect", "Block");
						lkEff.SetField("Amount", "5");
						var lockGraph = new ForgeGraphSpec { Nodes = { lkTrig, lkEnergy, lkVal, lkEff } };
						lockGraph.Links.Add(new ForgeLinkSpec { From = lkTrig.Id, To = lkEff.Id, FromPort = 0, ToPort = 0 });
						lockGraph.Links.Add(new ForgeLinkSpec { From = lkEnergy.Id, To = lkVal.Id, FromPort = 0, ToPort = 0 });
						lockGraph.Links.Add(new ForgeLinkSpec { From = lkVal.Id, To = lkEff.Id, FromPort = 0, ToPort = 1 });
						ForgeCanvas.Graph = lockGraph;
						UpdateLayout();
						Check("（准备）小图上画出了 4 块（含一块【能量】）", ForgeCanvas.DrawnNodeCount == 4, $"{ForgeCanvas.DrawnNodeCount} 块");
						// ① 全选不含它
						ForgeCanvas.SelectAll();
						Check("「全选」选上 2 块（【能量】和【触发时机】都被跳过）",
							ForgeCanvas.SelectedCount == 2 && !ForgeCanvas.SelectedNodesForCheck.Contains(lkEnergy)
							&& !ForgeCanvas.SelectedNodesForCheck.Contains(lkTrig),
							$"{ForgeCanvas.SelectedCount} 块");
						// ① 点它的标题栏不会选中它（也不会开始拖动）
						ForgeCanvas.ClearSelectionForCheck();
						bool startedEnergy = ForgeCanvas.BeginDragFromHeader(lkEnergy);
						Check("点【能量】的标题栏**不会**选中它、也不会开始拖它（它是固定模块）",
							startedEnergy && ForgeCanvas.SelectedCount == 0, $"{ForgeCanvas.SelectedCount} 块被选中");
						double ex = lkEnergy.X, ey = lkEnergy.Y;
						ForgeCanvas.NudgeSelection(40, 40);
						Check("（顺便）选中别的模块再拖，【能量】的位置一动不动",
							Math.Abs(lkEnergy.X - ex) < 0.01 && Math.Abs(lkEnergy.Y - ey) < 0.01,
							$"({lkEnergy.X:0},{lkEnergy.Y:0}) 原来 ({ex:0},{ey:0})");
						// ① 标题栏上没有「×」；别的模块上有
						Check("【能量】的标题栏上没有「×」删除按钮", !ForgeCanvas.NodeHeaderHasDeleteForCheck(lkEnergy), "没有 ×");
						Check("（对照）别的模块的标题栏上照旧有「×」", ForgeCanvas.NodeHeaderHasDeleteForCheck(lkEff), "有 ×");
						// ① 只选它一个 → 「删除选中」什么都不删（图原样，一个字节都不动）"
						ForgeCanvas.ClearSelectionForCheck();
						ForgeCanvas.ForceSelectForCheck(lkEnergy);
						ForgeCanvas.RemoveSelectedForCheck();
						Check("只选【能量】再点删除 → 一块都不删（节点 / 连线数原样）",
							lockGraph.Nodes.Count == 4 && lockGraph.Links.Count == 3
							&& !ForgeCanvas.SelectedNodesForCheck.Contains(lkEnergy),
							$"节点 {lockGraph.Nodes.Count} / 线 {lockGraph.Links.Count}");
						// ① 它和别的混在一起选 → 别的照删，它留着（不会被一起带走）
						ForgeCanvas.SelectAll();
						ForgeCanvas.ForceSelectForCheck(lkEnergy);
						ForgeCanvas.RemoveSelectedForCheck();
						Check("和别的模块混在一起删：【能量】和【触发时机】都**留着**，别的照旧删掉",
							lockGraph.Nodes.Count == 2 && lockGraph.Nodes.Any(n => ReferenceEquals(n, lkEnergy))
							&& lockGraph.Nodes.Any(n => ReferenceEquals(n, lkTrig)),
							$"剩 {lockGraph.Nodes.Count} 块：{string.Join(",", lockGraph.Nodes.Select(n => n.Kind))}");
						ForgeCanvas.Graph = forged.ForgeGraph;      // 换回原来那块布，给后面的自检用 
						UpdateLayout();
					}
					// ===== V0.2.128 需求 2：【触发时机】不可被删除 + 新增「这张牌被保留时」 =====
					{
						var tTrig = new ForgeNodeSpec { Kind = "Trigger", X = 20, Y = 20 };
						tTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var tEnergy = new ForgeNodeSpec { Kind = "Energy", X = ForgeGraphCatalog.EnergyX, Y = ForgeGraphCatalog.EnergyY };
						var tEff = new ForgeNodeSpec { Kind = "Effect", X = 320, Y = 200 };
						tEff.SetField("Effect", "Block");
						tEff.SetField("Amount", "5");
						var trigGraph = new ForgeGraphSpec { Nodes = { tTrig, tEnergy, tEff } };
						trigGraph.Links.Add(new ForgeLinkSpec { From = tTrig.Id, To = tEff.Id, FromPort = 0, ToPort = 0 });
						ForgeCanvas.Graph = trigGraph;
						UpdateLayout();
						Check("【触发时机】的标题栏上没有「×」删除按钮（用户要求：不可被删除）",
							!ForgeCanvas.NodeHeaderHasDeleteForCheck(tTrig), "没有 ×");
						Check("（对照）别的模块的标题栏上照旧有「×」", ForgeCanvas.NodeHeaderHasDeleteForCheck(tEff), "有 ×");
						ForgeCanvas.SelectAll();
						Check("「全选」不带上【触发时机】（也不能被全选带走）",
							!ForgeCanvas.SelectedNodesForCheck.Contains(tTrig) && ForgeCanvas.SelectedCount == 1,
							$"选中 {ForgeCanvas.SelectedCount} 块");
						// 只选它一个 → 删除什么都不做，并把说明写到状态栏
						ForgeCanvas.ClearSelectionForCheck();
						ForgeCanvas.ForceSelectForCheck(tTrig);
						ForgeCanvas.RemoveSelectedForCheck();
						Check("只选【触发时机】再点删除 → 一块都不删（图原样），状态栏说明「固定模块」",
							trigGraph.Nodes.Count == 3 && trigGraph.Links.Count == 1
							&& ForgeCanvas.StatusText.Contains("触发时机") && ForgeCanvas.StatusText.Contains("固定模块"),
							$"节点 {trigGraph.Nodes.Count} / 线 {trigGraph.Links.Count}｜{ForgeCanvas.StatusText}");
						// 混在一起删 → 别的照删、它留着
						ForgeCanvas.SelectAll();
						ForgeCanvas.ForceSelectForCheck(tTrig);
						ForgeCanvas.RemoveSelectedForCheck();
						Check("和别的模块混在一起删：【触发时机】和【能量】都**留着**，别的照旧删掉",
							trigGraph.Nodes.Count == 2 && trigGraph.Nodes.Any(n => ReferenceEquals(n, tTrig))
							&& trigGraph.Nodes.Any(n => ReferenceEquals(n, tEnergy)),
							$"剩 {trigGraph.Nodes.Count} 块：{string.Join(",", trigGraph.Nodes.Select(n => n.Kind))}");
						// 它照样可以选中 / 拖动（只锁「删除」，位置还是用户自己摆）
						ForgeCanvas.ClearSelectionForCheck();
						bool startedTrig = ForgeCanvas.BeginDragFromHeader(tTrig);
						Check("【触发时机】照常能选中 / 拖动（只锁删除，不是像【能量】那样钉死）",
							startedTrig && ForgeCanvas.SelectedCount == 1, $"{ForgeCanvas.SelectedCount} 块被选中");
						double tx = tTrig.X;
						ForgeCanvas.NudgeSelection(30, 10);
						Check("拖动它位置真的变了",
							Math.Abs(tTrig.X - (tx + 30)) < 0.01, $"({tTrig.X:0},{tTrig.Y:0})");
						ForgeCanvas.EndDragForCheck();
						ForgeCanvas.Graph = forged.ForgeGraph;
						UpdateLayout();

						// ===== V0.2.168：一块布上可以有多块【触发时机】（每块配自己后面那一条链）=====
						// 用户要求：「多个触发时机能用了吗」→ 加。以前下拉里加过一块就把【触发时机】从菜单里删掉，
						// 而且生成端只认**第一块**（g.TriggerNode）—— 第二块配了也白配。
						{
							Check("模块下拉里**始终**有【触发时机】（加过一块之后还能再加一块）",
								ForgeCanvas.KindPickItemsForCheck.Any(x => x.Contains("触发时机", StringComparison.Ordinal)),
								string.Join(" / ", ForgeCanvas.KindPickItemsForCheck));
							var mtGraph = new ForgeGraphSpec();
							var mtA = new ForgeNodeSpec { Kind = "Trigger", X = 20, Y = 20 };
							mtA.SetField("Timing", ForgeTimings.CardPlayed);
							var mtE1 = new ForgeNodeSpec { Kind = "Effect", X = 340, Y = 20 };
							mtE1.SetField("Effect", "Damage");
							mtE1.SetField("Amount", "6");
							mtGraph.Nodes.AddRange(new[] { mtA, mtE1 });
							mtGraph.Links.Add(new ForgeLinkSpec { From = mtA.Id, To = mtE1.Id, FromPort = 0, ToPort = 0 });
							ForgeCanvas.Graph = mtGraph;
							UpdateLayout();
							Check("（准备）这块布上现在只有 1 块【触发时机】", mtGraph.TriggerNodes.Count == 1, $"{mtGraph.TriggerNodes.Count} 块");
							ForgeCanvas.AddKindForCheck("触发时机");
							Check("再点一次「加一个」→ 布上真的多了一块【触发时机】（第二块起是普通模块）",
								mtGraph.TriggerNodes.Count == 2, $"{mtGraph.TriggerNodes.Count} 块");
							var mtB = mtGraph.TriggerNodes.Count > 1 ? mtGraph.TriggerNodes[1] : null;
							Check("新加的那块默认挑**这块布上还没用过**的时机（不会又落在「卡牌被打出时」上撞车）",
								mtB is not null && mtB.Get("Timing") != ForgeTimings.CardPlayed, mtB?.Get("Timing") ?? "(没有)");
							Check("第一块【触发时机】标题栏上照旧没有「×」（固定模块），第二块上有",
								!ForgeCanvas.NodeHeaderHasDeleteForCheck(mtA)
								&& mtB is not null && ForgeCanvas.NodeHeaderHasDeleteForCheck(mtB),
								$"第一块 {(ForgeCanvas.NodeHeaderHasDeleteForCheck(mtA) ? "有" : "没有")} × / 第二块 {(mtB is not null && ForgeCanvas.NodeHeaderHasDeleteForCheck(mtB) ? "有" : "没有")} ×");
							// 生成端：两块各生成一个钩子
							var mtCard = new CardSpec { Name = "自检双时机卡", ClassName = "UiCheckMultiTrig", CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true, InCardPool = true };
							var mtCardGraph = new ForgeGraphSpec();
							var mtC1 = new ForgeNodeSpec { Kind = "Trigger" };
							mtC1.SetField("Timing", ForgeTimings.CardPlayed);
							var mtC1e = new ForgeNodeSpec { Kind = "Effect" };
							mtC1e.SetField("Effect", "Damage");
							mtC1e.SetField("Amount", "6");
							var mtC2 = new ForgeNodeSpec { Kind = "Trigger" };
							mtC2.SetField("Timing", ForgeTimings.CardExhausted);
							var mtC2e = new ForgeNodeSpec { Kind = "Effect" };
							mtC2e.SetField("Effect", "Draw");
							mtC2e.SetField("Amount", "1");
							mtCardGraph.Nodes.AddRange(new[] { mtC1, mtC1e, mtC2, mtC2e });
							mtCardGraph.Links.Add(new ForgeLinkSpec { From = mtC1.Id, To = mtC1e.Id, FromPort = 0, ToPort = 0 });
							mtCardGraph.Links.Add(new ForgeLinkSpec { From = mtC2.Id, To = mtC2e.Id, FromPort = 0, ToPort = 0 });
							mtCard.ForgeGraph = mtCardGraph;
							Profile.Cards.Add(mtCard);
							string mtSrc = CSharpCodeGen.CardSource(Profile, mtCard, Profile.Cards.Count - 1);
							Check("生成端：两块【触发时机】各生成一个钩子（打出时 → 私有方法 ForgeGraphOnPlay；被消耗时 → AfterCardExhausted 覆写）",
								mtSrc.Contains("public async Task ForgeGraphOnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)", StringComparison.Ordinal)
								&& mtSrc.Contains("public override async Task AfterCardExhausted(", StringComparison.Ordinal)
								&& mtSrc.Contains("await ForgeGraphOnPlay(choiceContext, cardPlay)", StringComparison.Ordinal),
								$"ForgeGraphOnPlay={mtSrc.Contains("public async Task ForgeGraphOnPlay", StringComparison.Ordinal)} / AfterCardExhausted={mtSrc.Contains("public override async Task AfterCardExhausted(", StringComparison.Ordinal)}");
							Check("V0.2.168：卡牌档「这张牌被消耗时」的钩子会先判 `card != this`（以前**任何**一张牌被消耗都会触发这张图的链）",
								mtSrc.Contains("if (card != this || base.CombatState is null) return;", StringComparison.Ordinal), "有守卫");
							Check("两块【触发时机】的注释各带「第 N 块」的抬头（一眼看得出是两块）",
								mtSrc.Contains("第 1 块【触发时机】", StringComparison.Ordinal) && mtSrc.Contains("第 2 块【触发时机】", StringComparison.Ordinal), "有");
							// 撞同一个本体钩子 → 校验器报错（生成端只写第一块，兜底不出坏代码）
							var clashGraph = new ForgeGraphSpec();
							foreach (double cy in new[] { 0.0, 260.0 })
							{
								var ct = new ForgeNodeSpec { Kind = "Trigger", Y = cy };
								ct.SetField("Timing", ForgeTimings.CardPlayed);
								var ce = new ForgeNodeSpec { Kind = "Effect", X = 340, Y = cy };
								ce.SetField("Effect", "Block");
								ce.SetField("Amount", "5");
								clashGraph.Nodes.AddRange(new[] { ct, ce });
								clashGraph.Links.Add(new ForgeLinkSpec { From = ct.Id, To = ce.Id, FromPort = 0, ToPort = 0 });
							}
							var clashIssues = ForgeGraphGen.Issues(clashGraph, Profile, "Card", null);
							Check("两块【触发时机】落在**同一个本体钩子**上 → 校验器报错说清（否则是同一个类里两个同名 override，整个模组编译不过）",
								clashIssues.Any(x => x.Level == "错误" && x.Message.Contains("同一个本体钩子", StringComparison.Ordinal)),
								string.Join(" / ", clashIssues.Select(x => x.Level + ":" + x.Message[..Math.Min(40, x.Message.Length)])));
							// 遗物档：两块各嵌进遗物自己的一个触发钩子 → 两个私有方法（不能都叫 ForgeGraphOnTrigger）
							var mtRelic = new RelicSpec { Name = "自检双时机遗物", ClassName = "UiCheckMultiTrigRelic", Rarity = "Common", IsForged = true };
							mtRelic.Triggers.Clear();
							mtRelic.Triggers.Add(new RelicTriggerSpec { Kind = ForgeTimings.CombatStart });
							mtRelic.Triggers.Add(new RelicTriggerSpec { Kind = ForgeTimings.PlayerTurnStart });
							var mtRelicGraph = new ForgeGraphSpec();
							foreach (var (rt, re, ry) in new[] { (ForgeTimings.CombatStart, "Block", 0.0), (ForgeTimings.PlayerTurnStart, "Draw", 260.0) })
							{
								var rtNode = new ForgeNodeSpec { Kind = "Trigger", Y = ry };
								rtNode.SetField("Timing", rt);
								var reNode = new ForgeNodeSpec { Kind = "Effect", X = 340, Y = ry };
								reNode.SetField("Effect", re);
								reNode.SetField("Amount", re == "Block" ? "4" : "1");
								mtRelicGraph.Nodes.AddRange(new[] { rtNode, reNode });
								mtRelicGraph.Links.Add(new ForgeLinkSpec { From = rtNode.Id, To = reNode.Id, FromPort = 0, ToPort = 0 });
							}
							mtRelic.ForgeGraph = mtRelicGraph;
							Profile.Relics.Add(mtRelic);
							string mtRelicSrc = CSharpCodeGen.RelicSource(Profile, mtRelic, Profile.Relics.Count - 1);
							Check("遗物档：图上两块【触发时机】分别嵌进遗物自己的两个钩子 → 生成两个私有方法（ForgeGraphOnTrigger / ForgeGraphOnTrigger2）",
								mtRelicSrc.Contains("public async Task ForgeGraphOnTrigger(", StringComparison.Ordinal)
								&& mtRelicSrc.Contains("public async Task ForgeGraphOnTrigger2(", StringComparison.Ordinal)
								&& mtRelicSrc.Contains("await ForgeGraphOnTrigger(", StringComparison.Ordinal)
								&& mtRelicSrc.Contains("await ForgeGraphOnTrigger2(", StringComparison.Ordinal), "两个方法 + 两处调用");
							Profile.Cards.Remove(mtCard);
							Profile.Relics.Remove(mtRelic);
							ForgeCanvas.Graph = forged.ForgeGraph;
							UpdateLayout();
						}
						// 新时机：卡牌档多一条「这张牌被保留时」（Id = 卡牌页那份 Retained，Hook = AfterFlush）
						var cardTimings = ForgeTimings.For("Card");
						var retained = ForgeTimings.Find(ForgeTimings.CardRetained, "Card");
						Check("锻造页卡牌档的时机里多了一条「这张牌被保留时」（Id=Retained）",
							retained is not null && cardTimings.Any(x => x.Id == ForgeTimings.CardRetained),
							$"卡牌档 {cardTimings.Count} 条：{string.Join(" / ", cardTimings.Select(x => x.Display))}");
						Check("它的钩子是 AfterFlush（本体没有 AfterCardRetained，走丢手牌那一刻的回调）",
							retained is not null && retained.Hook == "AfterFlush", retained?.Hook ?? "(没有)");
						Check("按 scope 查时机不会串档（Retained 只在卡牌档；遗物档没有它）",
							ForgeTimings.Find("Retained", "Relic") is null || ForgeTimings.Find("Retained", "Relic")?.Scope == "Card",
							ForgeTimings.Find("Retained", "Relic")?.Scope ?? "（遗物档没有）");
						// 生成端：签名必须是本体那个 AfterFlush（以前会落到默认分支生成不存在的签名 → CS0114/CS0115）
						var retCard = new CardSpec { Name = "自检保留卡", ClassName = "UiCheckRetained", CardType = "Skill", Rarity = "Common", IsForged = true, InCardPool = true };
						{
							var g = new ForgeGraphSpec();
							var retTrig = new ForgeNodeSpec { Kind = "Trigger" };
							retTrig.SetField("Timing", ForgeTimings.CardRetained);
							var eff = new ForgeNodeSpec { Kind = "Effect" };
							eff.SetField("Effect", "Block");
							eff.SetField("Amount", "3");
							g.Nodes.AddRange(new[] { retTrig, eff });
							g.Links.Add(new ForgeLinkSpec { From = retTrig.Id, To = eff.Id, FromPort = 0, ToPort = 0 });
							retCard.ForgeGraph = g;
						}
						string refSrc = CSharpCodeGen.CardSource(Profile, retCard, 0);
						Check("生成端：签名 = 本体那个 AfterFlush(choiceContext, player, flushedCards, retainedCards)",
							refSrc.Contains("public override async Task AfterFlush(PlayerChoiceContext choiceContext, Player player, IReadOnlyCollection<CardModel> flushedCards, IReadOnlyCollection<CardModel> retainedCards)"),
							refSrc.Split('\n').FirstOrDefault(l => l.Contains("AfterFlush("))?.Trim() ?? "(没生成)");
						Check("生成端：进门守卫 = retainedCards.Contains(this)（和卡牌页「被保留」那档同一套判据）",
							refSrc.Contains("if (!retainedCards.Contains(this)) return;"), "守卫在");
						Check("生成端：**没有**生成那个不存在的 AfterFlush(PlayerChoiceContext)（那会 CS0114/CS0115）",
							!refSrc.Contains("AfterFlush(PlayerChoiceContext choiceContext)"), "没生成错签名");
						Check("生成端：这个钩子没有 cardPlay 参数 → 补一句 CardPlay? cardPlay = null;（不然 CS0103）",
							refSrc.Contains("CardPlay? cardPlay = null;"), "占位在");
						Check("生成端：正文里没出现「卡牌被打出时」那种 OnPlay 转发（时机确实是保留）",
							!refSrc.Contains("await ForgeGraphOnPlay("), "没走 OnPlay");
						// 校验器：图的时机和卡牌档对得上（认不出来时报错）
						Check("校验器：用「这张牌被保留时」的图**没有**错误级问题",
							!ForgeGraphGen.Issues(retCard.ForgeGraph, Profile, "Card").Any(x => x.Level == "错误"),
							string.Join(" / ", ForgeGraphGen.Issues(retCard.ForgeGraph, Profile, "Card").Select(x => x.Level + ":" + x.Message)));
						// 老存档安全实测：图里**没有**【触发时机】时整张图不生成。
						// 这正是「锁住【触发时机】不改生成语义」的根据（Plan() 返回 null；锁定只动界面）。
						var noTrigCard = new CardSpec { Name = "自检无时机卡", ClassName = "UiCheckNoTrigger", CardType = "Skill", Rarity = "Common", IsForged = true, InCardPool = true };
						{
							var ng = new ForgeGraphSpec();
							var ne = new ForgeNodeSpec { Kind = "Effect" };
							ne.SetField("Effect", "Block");
							ne.SetField("Amount", "5");
							ng.Nodes.Add(ne);
							noTrigCard.ForgeGraph = ng;
						}
						string ngSrc = CSharpCodeGen.CardSource(Profile, noTrigCard, 0);
						Check("老存档安全：图里没有【触发时机】→ 整张图一个字符都不生成（锁定只动界面、不改生成语义）",
							!ngSrc.Contains("锻造节点图") && !ngSrc.Contains("__fgPlayer"),
							ngSrc.Contains("锻造节点图") ? "居然生成了节点图代码" : "没生成（对）");
						Check("（对照）同一条链补上【触发时机】就会生成（说明上面那条不是因为图太简单）",
							CSharpCodeGen.CardSource(Profile, retCard, 0).Contains("锻造节点图"), "补了时机就生成");
					}
					// ===== V0.2.128 需求 1：12 个数字框都能填公式/参数（用户拍板 Q2=A：保留数字框） =====
					{
						Check("数字框清单就是那 12 处（生成端 / 校验器 / 界面共用这一份）",
							ForgeNumbers.NumberFields.Count == 12,
							string.Join(" / ", ForgeNumbers.NumberFields.Select(f => f.Kind + "." + f.Key)));
						// ① 纯数字 / 常量公式：还是老样子（红线：默认档一个字符都不变）
						var numNode = new ForgeNodeSpec { Kind = "Effect" };
						numNode.SetField("Effect", "Damage");
						numNode.SetField("Amount", "6");
						Check("纯数字还是老样子（GetNumber=6）", Math.Abs(numNode.GetNumber("Amount", 0) - 6) < 0.001, $"{numNode.GetNumber("Amount", 0)}");
						numNode.SetField("Amount", "2*3");
						Check("常量公式在生成期折叠（2*3 → 6，生成出来还是老样子）",
							Math.Abs(numNode.GetNumber("Amount", 0) - 6) < 0.001, $"{numNode.GetNumber("Amount", 0)}");
						// ② 运行时公式：解析成运行时表达式，不再是「静默回落成默认值」
						numNode.SetField("Amount", "X*2");
						var resolved = ForgeNumbers.Resolve(Profile, numNode, "Amount", 6);
						Check("运行时公式（X*2）认得出来：Runtime=true、生成了表达式（不再静默变默认值）",
							resolved.Ok && resolved.Runtime && resolved.Expr.Contains("__X"), resolved.Expr);
						numNode.SetField("Amount", "2+");
						var bad = ForgeNumbers.Resolve(Profile, numNode, "Amount", 6);
						Check("写错的公式：Ok=false + 中文原因（校验器会报错说清哪一栏）",
							!bad.Ok && bad.Error.Length > 0, bad.Error);
						// 校验器只在一张「有触发时机」的图上跑（没触发时机时它第一句就返回了）
						var badTrig = new ForgeNodeSpec { Kind = "Trigger" };
						badTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var badIssues = ForgeGraphGen.Issues(
							new ForgeGraphSpec { Nodes = { badTrig, numNode } }, Profile, "Card");
						Check("校验器：写错的公式报「错误」并说清模块 + 哪一栏",
							badIssues.Any(x => x.Level == "错误" && x.Message.Contains("【效果】") && x.Message.Contains("数值")),
							string.Join(" / ", badIssues.Select(x => x.Level + ":" + x.Message)));
						// ③ 卡牌费用那两栏只收「生成期算得出来」的数
						//  V0.2.215（用户截图报的「虚化」）：**X / Y 是合法的** —— 那是本体「消耗全部能量 /
						//  全部额外资源量」那套（HasEnergyCostX / HasStarCostX）；真正拦的是其它运行时读数。
						var costNode = new ForgeNodeSpec { Kind = "Energy" };
						costNode.SetField("EnergyCost", "X");
						var costGraph = new ForgeGraphSpec { Nodes = { badTrig, costNode } };
						var costIssues = ForgeGraphGen.Issues(costGraph, Profile, "Card");
						Check("校验器V0.2.215：【能量】写 X 不再报错（= 消耗全部能量），而且被认成 X 费",
							!costIssues.Any(x => x.Level == "错误") && ForgeGraphGen.IsEnergyCostX(costGraph),
							string.Join(" / ", costIssues.Select(x => x.Level + ":" + x.Message)));
						costNode.SetField("EnergyCost", "MyHp");
						var costIssues2 = ForgeGraphGen.Issues(costGraph, Profile, "Card");
						Check("校验器V0.2.215：真正跑起来才知道的量（MyHp）在费用那栏仍然报错说清要编译期常量",
							costIssues2.Any(x => x.Level == "错误" && x.Message.Contains("编译期常量")),
							string.Join(" / ", costIssues2.Select(x => x.Level + ":" + x.Message)));
						costNode.SetField("EnergyCost", "1+1");
						Check("【能量】的费用写常量公式（1+1）→ 折叠成 2、没有错误",
							ForgeGraphGen.EnergyCostOf(costGraph) == 2
							&& !ForgeGraphGen.Issues(costGraph, Profile, "Card").Any(x => x.Level == "错误"),
							$"费用={ForgeGraphGen.EnergyCostOf(costGraph)}");
						// ④ 生成端：数值 / 生效次数 / 命中次数 / 概率四栏写公式都要落到生成代码里
						// （临时加一个「固定数值」来源的参数 A，验「能折叠成常数的公式」这一档）
						var savedParams = Profile.CustomParams.ToList();
						Profile.CustomParams.Add(new ParamSpec { Name = "A", Source = ParamSources.Value, Value = 2m });
						var fCard = new CardSpec { Name = "自检公式卡", ClassName = "UiCheckFormula", CardType = "Attack", Rarity = "Common", IsForged = true, InCardPool = true };
						{
							var g = new ForgeGraphSpec();
							var fTrig = new ForgeNodeSpec { Kind = "Trigger" };
							fTrig.SetField("Timing", ForgeTimings.CardPlayed);
							var tgt = new ForgeNodeSpec { Kind = "Target" };
							tgt.SetField("Pick", "ChosenEnemy");
							var eff = new ForgeNodeSpec { Kind = "Effect" };
							eff.SetField("Effect", "Damage");
							eff.SetField("Amount", "X");            // X = 当前能量
							eff.SetField("Hits", "A");              // 自定义参数（固定数值 2 → 生成期折叠）
							eff.SetField("Times", "Y");             // Y = 当前额外资源量（运行时循环上界）
							eff.SetField("Chance", "Turn");         // 内置只读量
							g.Nodes.AddRange(new[] { fTrig, tgt, eff });
							g.Links.Add(new ForgeLinkSpec { From = fTrig.Id, To = tgt.Id, FromPort = 0, ToPort = 0 });
							g.Links.Add(new ForgeLinkSpec { From = tgt.Id, To = eff.Id, FromPort = 0, ToPort = 0 });
							g.Links.Add(new ForgeLinkSpec { From = tgt.Id, To = eff.Id, FromPort = 1, ToPort = 2 });
							fCard.ForgeGraph = g;
						}
						string fSrc = CSharpCodeGen.CardSource(Profile, fCard, 0);
						Check("生成端：数值写 X → decimal __fgAmt… = __X;（不再当成默认值 6）",
							fSrc.Contains("= __X;") && fSrc.Contains("【效果】数值（公式：X）"), "数值公式在");
						Check("生成端：生效次数写 Y → 真的生成一个以公式为界的 for 循环",
							fSrc.Contains("= Math.Max(1, (int)(__Y))") && fSrc.Contains("for (int t = 0; t <"), "运行时循环在");
						Check("生成端：概率写 Turn（内置只读量）→ 概率判定用算出来的值",
							fSrc.Contains("int __fgChance") && fSrc.Contains("ForgeFormulaRuntime.Roll(__fgPlayer, __fgChance"), "概率公式在");
						Check("生成端：命中次数写 A（固定数值参数）→ 生成期折叠成 2（老写法 .WithHitCount(2)）",
							fSrc.Contains(".WithHitCount(2)"), ".WithHitCount(2)");
						Check("校验器：这张卡的图**没有**错误级问题",
							!ForgeGraphGen.Issues(fCard.ForgeGraph, Profile, "Card").Any(x => x.Level == "错误"),
							string.Join(" / ", ForgeGraphGen.Issues(fCard.ForgeGraph, Profile, "Card").Select(x => x.Level + ":" + x.Message)));
						// ⑤ 界面：数字框旁边有「…」插入按钮 + 填错描红 + 运行时公式标蓝
						//   ⚠ V0.2.129 起【效果】模块整块换成了**和卡牌共用**的 EffectSpec 编辑器
						//     （那 4 栏是模板里的文本框，不再走数据驱动的 Number 字段）——
						//     所以这一套（「…」按钮 / 描红 / 标蓝）改用照旧走数据驱动字段的【能量】费用栏来验，
						//     锻造【效果】模块自己的界面在下一条（V0.2.129）里单独验。
						var uiEnergy = new ForgeNodeSpec { Kind = "Energy" };
						// V0.2.215：X 现在是**合法**的（绿色「X 费」提示），标蓝那一档改用真正跑起来才知道的量（MyHp）
						uiEnergy.SetField("EnergyCost", "MyHp");
						var uiNum = ForgeCanvas.NumberFieldUiForCheck(uiEnergy, "EnergyCost");
						Check("界面：数字框旁边有「…」插入参数 / 可用量的按钮", uiNum.HasInsert, $"HasInsert={uiNum.HasInsert}");
						Check("界面：填了运行时公式的框标蓝 + ToolTip 里写出它变成什么表达式",
							uiNum.Runtime && uiNum.Tip.Contains("运行时才算"), uiNum.Tip.Replace("\n", " "));
						uiEnergy.SetField("EnergyCost", "X");
						var uiX = ForgeCanvas.NumberFieldUiForCheck(uiEnergy, "EnergyCost");
						Check("界面V0.2.215：费用那栏填 X 不标红也不标蓝，ToolTip 说清「X 费 = 消耗全部能量」",
							!uiX.Invalid && uiX.Tip.Contains("X 费"), uiX.Tip.Replace("\n", " "));
						uiEnergy.SetField("EnergyCost", "2+");
						var uiBad = ForgeCanvas.NumberFieldUiForCheck(uiEnergy, "EnergyCost");
						Check("界面：填错的框当场描红 + ToolTip 里写出原因（不再静默变默认值）",
							uiBad.Invalid && uiBad.Tip.Contains("❌"), uiBad.Tip.Replace("\n", " "));
						uiEnergy.SetField("EnergyCost", "6");
						var uiPlain = ForgeCanvas.NumberFieldUiForCheck(uiEnergy, "EnergyCost");
						Check("界面：纯数字的框不标色（默认档观感和以前一样）",
							!uiPlain.Invalid && !uiPlain.Runtime, $"Invalid={uiPlain.Invalid} Runtime={uiPlain.Runtime}");
						Check("界面：【能量】费用栏的 ToolTip 写清了「这一栏只收生成期算得出来的数」（不能写运行时公式）",
							uiPlain.Tip.Contains("生成期就算得出来"), uiPlain.Tip.Replace("\n", " "));
						Check("界面：「可用量」清单写清了这些位置能用什么（X / Y / 内置只读量名字都在）",
							ForgeCanvas.FormulaHintTextForCheck.Contains("X = 当前所有能量")
							&& ForgeCanvas.FormulaHintTextForCheck.Contains("HandCount")
							&& ForgeCanvas.FormulaHintTextForCheck.Contains("编译期常量"),
							ForgeCanvas.FormulaHintTextForCheck);
						// 还原临时加的参数（后面的自检项按原样那份配置跑）
						Profile.CustomParams.Clear();
						foreach (var sp in savedParams) Profile.CustomParams.Add(sp);
						ForgeCanvas.Graph = forged.ForgeGraph;
						UpdateLayout();
					}
					// ===== V0.2.129（需求 3 / 用户拍板 Q1=A）：锻造【效果】模块 = 卡牌那套 EffectSpec 编辑器 =====
					{
						// （对照）非锻造链（卡牌 / 遗物 / 药水 / 自定义状态）那四处的显隐判据一个字都没变
						static bool PlainChainRowsUnchanged()
						{
							foreach (var k in new[] { "Damage", "Block", "ApplyPower", "GenerateCard", "GainPotion", "ExhaustCard", "TempPower" })
							{
								var s = new EffectSpec { Kind = k };
								if (s.IsForgeChain || s.ShowForgeValueRows || s.ShowForgeTimesBox || s.ShowForgeRepeatBox || s.ShowChanceRowForge)
									return false;
								if (s.ShowAmountBoxNormal != s.ShowAmountBox) return false;
								if (s.ShowAmountFormulaNormal != s.ShowAmountFormula) return false;
								if (!s.ShowFixedTimesBox) return false;
								if (s.ShowFixedRepeatBox != s.ShowRepeatCountInput) return false;
								if (!s.ShowChanceRowNormal) return false;
							}
							return true;
						}
						// 老形状（只有 ForgeNodeField 那一串老字段）→ 打开存档时幂等迁移出 EffectSpec
						var mgCard = new CardSpec { Name = "自检效果合并卡", ClassName = "UiCheckEffectMerge", CardType = "Attack", Rarity = "Common", IsForged = true, InCardPool = true };
						var mgGraph = new ForgeGraphSpec();
						var mgTrig = new ForgeNodeSpec { Kind = "Trigger" };
						mgTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var mgEff = new ForgeNodeSpec { Kind = "Effect" };
						mgEff.SetField("Effect", "Damage");
						mgEff.SetField("Amount", "6");
						mgEff.SetField("Hits", "2");
						mgEff.SetField("Chance", "50");
						mgGraph.Nodes.AddRange(new[] { mgTrig, mgEff });
						mgGraph.Links.Add(new ForgeLinkSpec { From = mgTrig.Id, To = mgEff.Id, FromPort = 0, ToPort = 0 });
						mgCard.ForgeGraph = mgGraph;

						Check("迁移：老形状的【效果】模块打开存档时迁出了 EffectSpec（还没被编辑器改过 → FromLegacy）",
							ForgeEffectBridge.Ensure(mgEff) is not null && mgEff.EffectFromLegacy,
							$"spec={mgEff.EffectSpec is not null} FromLegacy={mgEff.EffectFromLegacy}");
						Check("迁移：老字段一个键都没动（Amount / Hits / Chance 还是原文）",
							mgEff.Get("Amount") == "6" && mgEff.Get("Hits") == "2" && mgEff.Get("Chance") == "50",
							$"{mgEff.Get("Amount")} / {mgEff.Get("Hits")} / {mgEff.Get("Chance")}");
						var specJsonA = System.Text.Json.JsonSerializer.Serialize(mgEff.EffectSpec, ProfileFactory.JsonOpts);
						int fieldsBefore = mgEff.Fields.Count;
						ForgeEffectBridge.NormalizeGraph(mgGraph);      // 第二次跑（模拟「再打开一次存档」）
						ForgeEffectBridge.SyncGraph(mgGraph);           // 生成前那一遍
						Check("迁移**幂等**：再跑一遍（加载 + 生成前同步）spec 与老字段都没变",
							System.Text.Json.JsonSerializer.Serialize(mgEff.EffectSpec, ProfileFactory.JsonOpts) == specJsonA
							&& mgEff.Fields.Count == fieldsBefore, $"{fieldsBefore} 个键");
						Check("（红线）没被编辑器改过的老模块，生成端**不回写**老字段（FromLegacy 仍是 true）",
							mgEff.EffectFromLegacy, $"FromLegacy={mgEff.EffectFromLegacy}");

						// 界面：整块换成卡牌那套模板（同一个 EffectSpec / 同一个 EffectEditorForge）
						ForgeCanvas.Graph = mgGraph;
						UpdateLayout();
						var host = ForgeCanvas.EffectEditorHostForCheck(mgEff);
						Check("界面：【效果】模块里装的是「卡牌」页那套效果编辑器（宿主 = ContentControl + 同一个 EffectSpec）",
							host is not null && ReferenceEquals(host.Content, mgEff.EffectSpec),
							host is null ? "没找到宿主" : $"Content={(host.Content is EffectSpec ? "EffectSpec" : host.Content?.GetType().Name)}");
						Check("界面：这一份 spec 标成锻造链 → 数值 / 生效次数 / 命中次数 / 概率换成**能写公式**的框",
							mgEff.EffectSpec!.IsForgeChain && mgEff.EffectSpec.ShowForgeValueRows && mgEff.EffectSpec.ShowForgeTimesBox
							&& mgEff.EffectSpec.ShowForgeRepeatBox && mgEff.EffectSpec.ShowChanceRowForge,
							$"IsForgeChain={mgEff.EffectSpec.IsForgeChain}");
						Check("界面：（对照）卡牌 / 遗物 / 药水 / 自定义状态四处一个字都没变：非锻造链时那一套控件照旧",
							PlainChainRowsUnchanged(), "ShowForge* 全关 / 原来是哪套还是哪套");
						var mgVisible = VisibleTextsIn(ForgeCanvas);
						Check("界面：真画出来了那几栏（数值 / 生效次数 / 命中次数 / 概率生效（%））"
							+ " —— V0.2.182 起**不再**在编辑器里摆「可用量」清单（改到启动时弹出的参考窗）",
							mgVisible.Any(t => t == "数值") && mgVisible.Any(t => t.Contains("生效次数"))
							&& mgVisible.Any(t => t.Contains("命中次数")) && mgVisible.Any(t => t.Contains("概率生效（%）"))
							&& !mgVisible.Any(t => t.Contains("可用量")),
							string.Join(" / ", mgVisible.Where(t => t.Contains("数值") || t.Contains("次数") || t.Contains("概率")).Take(5)));
						Check("界面：卡牌那种独立的「数值（公式）」框在锻造链上**不重复摆**（那个「数值」框本身就能写公式）",
							!mgVisible.Any(t => t == "数值（公式）"), string.Join(" / ", mgVisible.Where(t => t.Contains("数值")).Take(3)));
						// 真渲染：换效果种类 → 按种类出现的那几栏真的跟着出现 / 收起（判据 = 卡牌页同一份）
						mgEff.EffectSpec!.Kind = "GenerateCard";
						UpdateLayout();
						var mgGenVisible = VisibleTextsIn(ForgeCanvas);
						Check("界面（真渲染）：选「生成卡牌」→ 取卡方式 / 范围界定那些栏真的出现在布上（和卡牌页一致）",
							mgGenVisible.Any(t => t.Contains("取卡方式")), string.Join(" / ", mgGenVisible.Where(t => t.Contains("取卡方式")).Take(2)));
						mgEff.EffectSpec!.Kind = "Damage";
						UpdateLayout();
						var mgDmgVisible = VisibleTextsIn(ForgeCanvas);
						Check("界面（真渲染）：（对照）选「造成伤害」→ 取卡方式 / 目标药水那些栏不出现",
							!mgDmgVisible.Any(t => t.Contains("取卡方式")) && !mgDmgVisible.Any(t => t.Contains("目标药水")),
							string.Join(" / ", mgDmgVisible.Where(t => t.Contains("取卡方式") || t.Contains("目标药水")).Take(2)));

						// 编辑 → 回写老字段 → 生成（五处配套里的「生成」）
						var mgSpec = mgEff.EffectSpec!;
						mgSpec.Kind = "ApplyPower";
						mgSpec.PowerId = "VulnerablePower";
						mgSpec.ForgeAmountText = "X";
						mgSpec.ForgeTimesText = "3";
						Check("编辑后回写老字段：Effect / PowerId / Amount / Times（老字段是生成端唯一读的地方）",
							mgEff.Get("Effect") == "ApplyPower" && mgEff.Get("PowerId") == "VulnerablePower"
							&& mgEff.Get("Amount") == "X" && mgEff.Get("Times") == "3" && !mgEff.EffectFromLegacy,
							$"{mgEff.Get("Effect")} / {mgEff.Get("PowerId")} / {mgEff.Get("Amount")} / {mgEff.Get("Times")}");
						string mgSrc = CSharpCodeGen.CardSource(Profile, mgCard, 0);
						Check("生成端：编辑器里改的东西真的进了生成代码（VulnerablePower + 运行时公式 __X）",
							mgSrc.Contains("VulnerablePower") && mgSrc.Contains("= __X;"), "VulnerablePower + __X");
						Check("校验器：改完之后的图没有错误级问题",
							!ForgeGraphGen.Issues(mgGraph, Profile, "Card").Any(x => x.Level == "错误"),
							string.Join(" / ", ForgeGraphGen.Issues(mgGraph, Profile, "Card").Select(x => x.Level + ":" + x.Message)));

						// 校验器：编辑器里能填、但节点图这一版不生成的栏位**报错拦住**（不许静默）
						mgSpec.Kind = "GenerateCard";
						mgSpec.SpawnCardId = "UiCheckEffectMerge";
						mgSpec.SpawnPick = "Random";
						mgSpec.SpawnFilter = "Attack";
						var gateIssues = ForgeGraphGen.Issues(mgGraph, Profile, "Card");
						// V0.2.170：「取卡方式」四档现在**真的支持了**（生成端复用卡牌页那份实现），
						// 所以这里从「报错拦住」改成「不再报这条错」+「生成代码里真的有按范围随机的池子」。
						Check("校验器：生成卡牌选了「按范围随机 / 范围限定」→ **不再**报错拦住（V0.2.170 起真的支持）",
							!gateIssues.Any(x => x.Level == "错误" && x.Message.Contains("按范围随机")),
							string.Join(" / ", gateIssues.Where(x => x.Level == "错误").Select(x => x.Message).Take(1)));
						Check("生成端：节点图的「按范围随机」真的生成了范围池 + 候选（不再是「生成指定那张卡」）",
							CSharpCodeGen.CardSource(Profile, mgCard, 0).Contains("__genPool")
							|| CSharpCodeGen.CardSource(Profile, mgCard, 0).Contains("GetDistinctForCombat"),
							"有范围池");
						mgSpec.SpawnPick = "Fixed"; mgSpec.SpawnFilter = "";
						mgSpec.NextTurn = false;
						mgSpec.Kind = "ReplayCard";
						gateIssues = ForgeGraphGen.Issues(mgGraph, Profile, "Card");
						Check("V0.2.170：节点图里的「重放卡牌」真的生成了代码（用户点的第 3 条）",
							CSharpCodeGen.CardSource(Profile, mgCard, 0).Contains("BaseReplayCount"),
							"有 BaseReplayCount");
						mgSpec.NextTurn = true;
						gateIssues = ForgeGraphGen.Issues(mgGraph, Profile, "Card");
						Check("V0.2.170：节点图的「重放卡牌 + 下回合生效」不再报「只有格挡 / 抽牌有延迟分支」那条警告（现在全铺开了）",
							!gateIssues.Any(x => x.Level == "警告" && x.Message.Contains("下回合生效")),
							string.Join(" / ", gateIssues.Where(x => x.Message.Contains("下回合生效")).Select(x => x.Level + ":" + x.Message).Take(1)));
						Check("V0.2.170：节点图的「重放卡牌 + 下回合生效」挂的是延迟状态（不是立即重放）",
							CSharpCodeGen.CardSource(Profile, mgCard, 0).Contains("ForgeDelayed"),
							"有 ForgeDelayed");
						mgSpec.Kind = "PlaySfx";
						mgSpec.NextTurn = true;
						gateIssues = ForgeGraphGen.Issues(mgGraph, Profile, "Card");
						Check("V0.2.170：只有本体真做不了延迟的种类（播放音效）才警告「下回合生效」不生效",
							gateIssues.Any(x => x.Level == "警告" && x.Message.Contains("下回合生效")),
							string.Join(" / ", gateIssues.Where(x => x.Message.Contains("下回合生效")).Select(x => x.Level + ":" + x.Message).Take(1)));
						mgSpec.NextTurn = false;
						// V0.2.203（用户截图报的「处决」）：「本回合这张牌自己费用变 0」在**卡牌**的锻造图上
						// 现在真的能生成了（`this.SetToFreeThisTurn()`）—— 卡牌图不该再报错。
						// 这一档不吃数值 / 生效次数，前面用例留下的 X / 3 要先清掉（否则会报「X 在节点图里不生效」，
						// 那条是对的、只是和本条断言无关）。
						mgSpec.ForgeAmountText = "";
						mgSpec.ForgeTimesText = "";
						mgSpec.AmountIsX = false;
						mgSpec.TimesIsX = false;
						mgSpec.RepeatIsX = false;
						mgSpec.AmountFormula = "";
						mgSpec.TimesFormula = "";
						mgSpec.RepeatFormula = "";
						mgSpec.Kind = "CheapenSelf";
						gateIssues = ForgeGraphGen.Issues(mgGraph, Profile, "Card");
						Check("V0.2.203：卡牌锻造图里「本回合这张牌自己费用变 0」不再报错（以前被拦成「还没接上」）",
							!gateIssues.Any(x => x.Level == "错误"),
							string.Join(" / ", gateIssues.Where(x => x.Level == "错误").Select(x => x.Message).Take(1)));
						string cheapenSelfFgSrc = ForgeGraphGen.CardHooks(Profile, mgCard, isUpgraded: false);
						Check("V0.2.203：卡牌锻造图里这一档生成的就是 `this.SetToFreeThisTurn()`（和卡牌页那条链同一句）",
							cheapenSelfFgSrc.Contains("this.SetToFreeThisTurn();"), "生成了");
						// 同一档放到**状态 / 遗物 / 药水**的布上仍然要拦住（那三块布没有「这张牌」）
						var cheapenSelfBadIssues = ForgeGraphGen.Issues(mgGraph, Profile, "Potion");
						Check("V0.2.203：（对照）同一档放在药水 / 遗物 / 状态的布上照旧报错，并说清只有卡牌有「这张牌」",
							cheapenSelfBadIssues.Any(x => x.Level == "错误" && x.Message.Contains("只有「卡牌」的锻造图")),
							string.Join(" / ", cheapenSelfBadIssues.Where(x => x.Level == "错误").Select(x => x.Message).Take(1)));
						// 收尾：这张自检卡不进后面的用例
						Profile.Cards.Remove(mgCard);
						ForgeCanvas.Graph = forged.ForgeGraph;
						UpdateLayout();
					}
					// 锻造页【状态」 【效果」 【条件】模块里那个「增益 / 减益」下拉的数据源：
					// 以前它直接读 EffectCatalog.Powers） *只有本体状态**的静态清单），玩家自己配的 
					// 自定义状态根本不在里面（用户报过两次：「锻造页里状态 / 效果模块的状态菜单还是没有自定义状态」）。"
					{
						// 先按「当前存档」重新登记一次自定义状态（这正是打开 / 编辑存档时走的那条路）。"
						// 这块布的下拉是**重建布时现搭**的：不重新登记 + 不重建，它就一直用旧清卡"
						// （用户报过两次：「锻造页里状态 / 效果模块的状态菜单还是没有自定义状态」）。"
						var savedEntries = EffectCatalog.CustomPowerEntries.ToList();
						RefreshCustomPowerRegistry();
						IReadOnlyList<string> forgePowers = ForgeCanvas.PowerItemsForCheck;
						List<string> minePowers = _profile.CustomPowers
							.Select((CustomPowerSpec cp, int i) => (cp, id: CustomPowerGen.ClassNameOf(_profile, cp, i)))
							.Where(x => CustomPowerGen.IsActive(x.cp))
							.Select(x => x.id).ToList();
						Check("锻造页的状态下拉非空（不再是空清单）", forgePowers.Count > 0, $"{forgePowers.Count} 条");
						Check("布上的状态下拉绑到了窗口那个「含自定义状态」的集合（XAML 绑定真的生效了）",
							ReferenceEquals(ForgeCanvas.PowerSource, PowerChoices), ForgeCanvas.PowerSource is null ? "PowerSource 是 null（绑没生效）" : "绑上了");
						Check("自定义状态排在**下拉最前面**（本体状态一两百条，排在最后等于看不见 —— 用户截图里就是翻不到）",
							minePowers.Count == 0 || minePowers.All(ForgeCanvas.PowerItemsTopForCheck.Contains),
							$"前 8 条：{string.Join(" / ", ForgeCanvas.PowerItemsTopForCheck)}");
						// 「数据源换了、布没重画」是用户连报四次的根因：现在 Rebuild() 的第一句会自己检查一遍。"
						// 这里直接模拟那种「画布手里是空清单、但数据源其实是好的」的坏状态：
						// 把 PowerSource 摘掉刷新一次（下拉清空），再挂回去只调 Rebuild()（不调刷新），看它能不能自愈。"
						{
							var saved = ForgeCanvas.PowerSource;
							ForgeCanvas.PowerSource = null;        // 触发一次刷新 → 下拉变空
							int emptied = ForgeCanvas.PowerItemsForCheck.Count;
							ForgeCanvas.PowerSource = saved;       // 挂回去 → 刷新
							int restored = ForgeCanvas.PowerItemsForCheck.Count;
							Check("数据源摘掉再挂回来，下拉条数跟着变（说明刷新这条路是通的）",
								emptied == 0 && restored > 0, $"摘掉后 {emptied} 条 → 挂回后 {restored} 条");
						}
						Check("锻造页的状态下拉里**每一条自定义状态都在**（用户报过两次：锻造页状态 / 效果模块里没有自定义状态）",
							minePowers.Count > 0 && minePowers.All(forgePowers.Contains),
							minePowers.Count == 0
								? "这份存档没有自定义状态 —— 这条没意义"
								: $"自定义 {minePowers.Count} 条，缺：{string.Join(" / ", minePowers.Where((string id) => !forgePowers.Contains(id)))}");
						Check("锻造页的状态下拉和卡牌页是同一份清单（条数一致，一个都不少）",
							forgePowers.Count == AllPowers.Count((PowerEntry p) => !p.Id.StartsWith("-", StringComparison.Ordinal)),
							$"锻造页 {forgePowers.Count} / 卡牌页（去掉伪条目）{AllPowers.Count((PowerEntry p) => !p.Id.StartsWith("-", StringComparison.Ordinal))}");
						Check("锻造页的状态下拉里没有 '-' 开头的伪条目（那是「给予能量」那种，不是状态）",
							forgePowers.All((string id) => !id.StartsWith("-", StringComparison.Ordinal)),
							$"{forgePowers.Count((string id) => id.StartsWith("-", StringComparison.Ordinal))} 条伪条目混进来了");
						// 恢复成这一条之前的登记（后面的自检项还在用探针那套自定义状态）
						EffectCatalog.SetCustomPowers(savedEntries.Select((PowerEntry e) => (e.Id, e.Zh, false, false)).ToList());
						RefreshPowerChoices();
					}
					// 拖动标题栏：按钮事件里以前写的是 (Border)header.Parent（标题栏的 Parent 其实是 StackPanel），
					// 一点标题栏就抛 InvalidCastException，选中 / 拖动 / 连线全做不了（用户报的 bug）。"
					// 自检里造不出真鼠标事件，只能直接跑「查外框 + 选中 + 挂处理器」那一段。"
					{
						var valueNode = forged.ForgeGraph.Nodes.First(n => n.Kind == "Value");
						Check("画布上画出来的模块数和数据一致（画和数据对不上时后面的拖动查外框一定失败）",
							ForgeCanvas.DrawnNodeCount == forged.ForgeGraph.Nodes.Count,
							$"画出 {ForgeCanvas.DrawnNodeCount} / 数据 {forged.ForgeGraph.Nodes.Count}（{ForgeCanvas.DrawnNodeIds}）");
						// 从标题栏顺视觉树往上走：以前拖动就是在这一步写死成 (Border)header.Parent）"
						// 而标题栏的 Parent 是 StackPanel —— 一点标题栏就抛 InvalidCastException。"
						var header = ForgeCanvas.NodeHeader(valueNode);
						Border? viaTree = null;
						for (DependencyObject? cur = header; cur is not null; cur = VisualTreeHelper.GetParent(cur))
							if (cur is Border bb && bb.Child is StackPanel) { viaTree = bb; break; }
						Check("从标题栏顺视觉树往上找得到这个模块自己的外框（拖动用的就是这条路径）",
							header is not null && viaTree is not null && ReferenceEquals(viaTree, ForgeCanvas.NodeView(valueNode)),
							viaTree is null ? "没找到" : "找到了");
						Check("拖动前查得到模块的外框（外框是 Border，不是标题栏的 StackPanel 父级）",
							ForgeCanvas.NodeView(valueNode) is Border b0 && b0.Child is StackPanel, "查到了");
						bool started = ForgeCanvas.BeginDragFromHeader(valueNode);
						Check("在标题栏上按下左键能开始拖动（以前这条路上抛「StackPanel 转 Border」的异常）",
							started, "没抛异常");
						// 缩放（需求：Ctrl + 滚轮放大缩小布）—— 走的是 Ctrl+滚轮同一条路
						{
							double z0 = ForgeCanvas.ZoomForCheck;
							ForgeCanvas.ZoomForCheckSet(1.5);
							double z1 = ForgeCanvas.ZoomForCheck;
							ForgeCanvas.ZoomForCheckSet(0.6);
							double z2 = ForgeCanvas.ZoomForCheck;
							ForgeCanvas.ZoomForCheckSet(99);       // 上限
							double z3 = ForgeCanvas.ZoomForCheck;
							ForgeCanvas.ResetZoom();
							Check("布能缩放：放大 / 缩小 / 有上下限 / 能回到 100%",
								Math.Abs(z1 - 1.5) < 0.001 && Math.Abs(z2 - 0.6) < 0.001 && z3 <= 3.0 + 0.001
								&& Math.Abs(ForgeCanvas.ZoomForCheck - 1.0) < 0.001,
								$"{z0:0.00} → {z1:0.00} → {z2:0.00} → 上限 {z3:0.00} → {ForgeCanvas.ZoomForCheck:0.00}");
						}
						Check("点标题栏 = 选中这一块（不是全选，也不清空）",
							ForgeCanvas.SelectedCount == 1, $"{ForgeCanvas.SelectedCount} 个");
						double dragX = valueNode.X, dragY = valueNode.Y;
						ForgeCanvas.NudgeSelection(25, -15);
						Check("拖动后位置按位移走（和真拖动用的是同一套算术）",
							Math.Abs(valueNode.X - Math.Max(0, dragX + 25)) < 0.01 && Math.Abs(valueNode.Y - Math.Max(0, dragY - 15)) < 0.01,
							$"({valueNode.X:0},{valueNode.Y:0})");
						ForgeCanvas.EndDragForCheck();
					}
					// 连线：点出口圆点 → 点入口圆点，走的是圆点自己的 Tag（和真点击同一条路）"
					{
						var wireTrig = new ForgeNodeSpec { Kind = "Trigger", X = 20, Y = 500 };
						var wireEff = new ForgeNodeSpec { Kind = "Effect", X = 500, Y = 500 };
						wireEff.SetField("Effect", "Damage");
						wireEff.SetField("Amount", "6");
						var fresh = new ForgeGraphSpec { Nodes = { wireTrig, wireEff } };
						ForgeCanvas.Graph = fresh;
						UpdateLayout();
						Check("新图上画出了 2 块模块（画布跟着 Graph 重建）",
							ForgeCanvas.DrawnNodeCount == 2, $"{ForgeCanvas.DrawnNodeCount} 块");
						bool okOut = ForgeCanvas.PortClickForCheck(wireTrig, 0, isOutput: true);
						Check("出口圆点找得到（读得出「第几块模块的第几个口」）", okOut,
							$"起点 {(okOut ? "OK" : "没找到")} / 图 {ForgeCanvas.DrawnNodeCount} 块");
						bool okIn = ForgeCanvas.PortClickForCheck(wireEff, 0, isOutput: false);
						Check("入口圆点找得到", okIn, okIn ? "OK" : "没找到");
						Check("点出口圆点、再点入口圆点就能接上一条线（圆点的 Tag 读得出端口）",
							okOut && okIn && fresh.Links.Count == 1 && fresh.Links[0].From == wireTrig.Id && fresh.Links[0].To == wireEff.Id,
							$"连线 {fresh.Links.Count} 条");
						UpdateLayout();
						// 「从出口往出口拖」：出口不是接入点，接不上（会画一条红虚线 + 说明）"
						var badNode = new ForgeNodeSpec { Kind = "Value", X = 800, Y = 560 };
						fresh.Nodes.Add(badNode);
						ForgeCanvas.Rebuild();
						bool badOut = ForgeCanvas.PortClickForCheck(wireTrig, 0, isOutput: true);
						bool badIn = ForgeCanvas.PortClickForCheck(badNode, 0, isOutput: true);
						Check("连到出口上（类型不对）不会加线，只给一句红字说明",
							badOut && badIn && fresh.Links.Count == 1, $"连线 {fresh.Links.Count} 条");
						fresh.Nodes.Remove(badNode);
						Check("圆点的 Tag 读不出来时返回 null，不抛异常",
							ForgeCanvasView.PortFromTag("坏掉的标记") is null
							&& ForgeCanvasView.PortFromTag(null) is null
							&& ForgeCanvasView.PortFromTag($"{wireTrig.Id}|x|out") is null, "返回 null");
						// ===== 用户报过三次的「锻造页状态下拉里没有自定义状态」：拿**磁盘上真实的存档**复现一遍 =====
						// 光断言「窗口当前这份档里的自定义状态在列表里」不多 —— 用户是**打开自己的存档**之后去看的，
						// 所以这里把「读存档 → 登记 → 画布下拉」这条真实路径整个走一遍，再用磁盘上每个存档验一次。"
						{
							CharacterProfile beforeDiag = _profile;
							var diagReport = new List<string>();
							int checkedProfiles = 0;
							int withStatus = 0;
							int missing = 0;
							foreach (string file in Directory.GetFiles(ProfileFolder, "*.json"))
							{
								CharacterProfile loaded;
								try { loaded = ProfileFactory.Load(file); }
								catch { continue; }                     // 坏档不参与（别把自检搞崩）"
								if (loaded.CustomPowers.Count == 0) continue;
								checkedProfiles++;
								var activeIds = loaded.CustomPowers
									.Select((CustomPowerSpec cp, int i) => (cp, id: CustomPowerGen.ClassNameOf(loaded, cp, i)))
									.Where(x => CustomPowerGen.IsActive(x.cp))
									.Select(x => x.id).ToList();
								withStatus++;
								// 走真实路径：换成这份存档 → 登记 → 让画布重算下拉"
								_profile = loaded;
								RefreshCustomPowerRegistry();
								ForgeCanvas!.RefreshPowerItems();
								IReadOnlyList<string> shown = ForgeCanvas.PowerItemsForCheck;
								var notShown = activeIds.Where(id => !shown.Contains(id)).ToList();
								missing += notShown.Count;
								diagReport.Add($"{Path.GetFileNameWithoutExtension(file)}: 自定义 {activeIds.Count} 条  缩 {notShown.Count}"
									+ (notShown.Count == 0 ? "" : " → " + string.Join("/", notShown)));
							}
							_profile = beforeDiag;
							RefreshCustomPowerRegistry();
							ForgeCanvas!.RefreshPowerItems();
							Check("拿磁盘上**每份**存档走一遍「读档 → 登记 → 画布下拉」：自定义状态一条都不缺",
								missing == 0,
								checkedProfiles == 0 ? $"存档目录里没有配了自定义状态的存档（{ProfileFolder}）"
									: string.Join(" ｜ ", diagReport));
							Check("（对照）至少验到了一份真实存档",
								checkedProfiles == 0 || withStatus == checkedProfiles,
								$"验了 {checkedProfiles} 份");
						}
						// 【if】的端口方向（需求）：左边上面「接入」接前置、左边下面「条件」接判断条件（新版布局）"
						{
							var gIf = new ForgeNodeSpec { Kind = "If", X = 900, Y = 1300 };
							var gTrig = new ForgeNodeSpec { Kind = "Trigger", X = 900, Y = 1200 };
							var gCond = new ForgeNodeSpec { Kind = "Condition", X = 1200, Y = 1300 };
							var gUnit = new ForgeNodeSpec { Kind = "Unit", X = 900, Y = 1400 };
							var gVal = new ForgeNodeSpec { Kind = "Value", X = 1200, Y = 1400 };
							fresh.Nodes.Add(gIf);
							fresh.Nodes.Add(gTrig);
							fresh.Nodes.Add(gCond);
							fresh.Nodes.Add(gUnit);
							fresh.Nodes.Add(gVal);
							Check("【if】左边「接入」能接【触发时机】（前置），也能接【对象】",
								ForgeCanvas.CouldConnectForCheck(gTrig, 0, gIf, 0) && ForgeCanvas.CouldConnectForCheck(gUnit, 0, gIf, 0),
								ForgeCanvas.ConnectionProblemForCheck(gTrig, 0, gIf, 0) ?? "能连");
							Check("【if】**左边**那个「条件」口能接【条件】的布尔出口（用户要求：条件挪到左边入口）",
								ForgeCanvas.CouldConnectForCheck(gCond, 0, gIf, 1),
								ForgeCanvas.ConnectionProblemForCheck(gCond, 0, gIf, 1) ?? "能连");
							Check("【数值】接到【if】的「条件」口上不行（条件口只收布尔）",
								!ForgeCanvas.CouldConnectForCheck(gVal, 0, gIf, 1),
								ForgeCanvas.ConnectionProblemForCheck(gVal, 0, gIf, 1) ?? "（居然能连）");
							Check("【数值】接到【if】左边「接入」上也不行（那是执行链的入口）",
								!ForgeCanvas.CouldConnectForCheck(gVal, 0, gIf, 0),
								ForgeCanvas.ConnectionProblemForCheck(gVal, 0, gIf, 0) ?? "（居然能连）");
						}
						ForgeCanvas.Graph = forged.ForgeGraph;      // 换回原来那块布，给后面的自检用 
						UpdateLayout();
						ForgeCanvas.SelectAll();                    // 换布会清掉选中，这里重新全选"
					}
					// 拉线：按住出口拖到入口松手（拖的时候线跟着鼠标）"
					{
						var dTrig = new ForgeNodeSpec { Kind = "Trigger", X = 20, Y = 900 };
						var dEff = new ForgeNodeSpec { Kind = "Effect", X = 520, Y = 900 };
						dEff.SetField("Effect", "Block");
						dEff.SetField("Amount", "5");
						var dg = new ForgeGraphSpec { Nodes = { dTrig, dEff } };
						ForgeCanvas.Graph = dg;
						UpdateLayout();
						ForgeCanvas.StartWireDragForCheck(dTrig, 0, isOutput: true);
						Check("按住出口圆点开始拉线（线跟着鼠标走）", ForgeCanvas.PendingWireVisible, "线在");
						ForgeCanvas.WireToForCheck(new Point(300, 950));
						// 松手时鼠标底下是入口圆点本身（真的鼠标事件里 OriginalSource 就是它）
						ForgeCanvas.FinishWireDragForCheck(ForgeCanvas.PortDot(dEff, 0, isOutput: false));
						Check("拖到入口圆点上松手就接上了",
							dg.Links.Count == 1 && dg.Links[0].From == dTrig.Id && dg.Links[0].To == dEff.Id,
							$"连线 {dg.Links.Count} 条");
						Check("松手之后拉线中那条线收掉了", !ForgeCanvas.PendingWireVisible, "收掉了");
						// 松在空白处 = 不接
						ForgeCanvas.StartWireDragForCheck(dTrig, 0, isOutput: true);
						ForgeCanvas.FinishWireDragForCheck(null);
						Check("松在空白处不会多出一条线", dg.Links.Count == 1, $"{dg.Links.Count} 条");
						// 右键点连线 = 删掉这条线"
						int before = dg.Links.Count;
						Check("画出图来以后布上就有这条线（右键点它用的就是它）", before == 1, $"{before} 条");
						if (before > 0) ForgeCanvas.RemoveLinkForCheck(dg.Links[0]);
						Check("右键点连线能把它删掉", dg.Links.Count == before - 1, $"{before} → {dg.Links.Count}");
						// 端口的「进出」方向：用户报过「某一块的数值出口接不上【数值】」，
						// 这里把该连的 / 不该连的一次性钉住（错了能直接看出是哪一格）。"
						{
							var cvValA = new ForgeNodeSpec { Kind = "Value", X = 20, Y = 1200 };
							var cvValB = new ForgeNodeSpec { Kind = "Value", X = 320, Y = 1200 };
							var cvUnit = new ForgeNodeSpec { Kind = "Unit", X = 20, Y = 1400 };
							var cvEff = new ForgeNodeSpec { Kind = "Effect", X = 620, Y = 1200 };
							cvEff.SetField("Effect", "Damage");
							cvEff.SetField("Amount", "6");
							var cv = new ForgeGraphSpec { Nodes = { cvValA, cvValB, cvEff, cvUnit } };
							ForgeCanvas.Graph = cv;
							UpdateLayout();
							{
								static string Dump(string id)
								{
									var k = ForgeGraphCatalog.Find(id);
									if (k is null) return id + "=(没有)";
									return $"{id}: 入[{string.Join(",", k.Inputs.Select(p => p.Key + ":" + (p.AcceptsKind ?? "-")))}] " +
										   $"出[{string.Join(",", k.Outputs.Select(p => p.Key + ":" + (p.AcceptsKind ?? "-")))}]";
								}
								Check("端口总览（接入点都在左边 / 出口都在右边）", true,
									Dump("Trigger") + " ｜ " + Dump("Value") + " ｜ " + Dump("Effect") + " ｜ " + Dump("If"));
							}
							Check("（端口方向自检的起点）【效果】的「数值」入口在左边（下标 1）、「指向对象」在下标 2",
								cvEff.InputPort(1)?.Key == "Value" && cvEff.InputPort(1)?.AcceptsKind == "Number"
								&& cvEff.InputPort(2)?.Key == "Target" && cvEff.InputPort(2)?.AcceptsKind == "Object",
								$"入口 {cvEff.KindDef?.Inputs.Count} / 出口 {cvEff.KindDef?.Outputs.Count}）" +
								$"入2={(cvEff.InputPort(1)?.Key ?? "null")}/{cvEff.InputPort(1)?.AcceptsKind ?? "-"} " +
								$"入2={(cvEff.InputPort(2)?.Key ?? "null")}/{cvEff.InputPort(2)?.AcceptsKind ?? "-"}");
							Check("【数值】的出口 →【效果】的「数值」口（下标 1）：**可以**连（【效果】就是从这个口拿数值的）",
								ForgeCanvas.CouldConnectForCheck(cvValA, 0, cvEff, 1),
								ForgeCanvas.ConnectionProblemForCheck(cvValA, 0, cvEff, 1) ?? "能连");
							Check("【效果】的「数值」口是**放**的：拿【数值】接它才行；反过来（把它接到【数值】上）不成 —— " +
								"它是「这一条效果打多少」的输入，不是「打出了多少」的输出",
								!ForgeCanvas.CouldConnectForCheck(cvEff, 0, cvValB, 0),
								ForgeCanvas.ConnectionProblemForCheck(cvEff, 0, cvValB, 0) ?? "（居然能连）");
							Check("【效果】的「指向对象」口（下标 2）同理：收对象、不收数值",
								!ForgeCanvas.CouldConnectForCheck(cvValA, 0, cvEff, 2),
								ForgeCanvas.ConnectionProblemForCheck(cvValA, 0, cvEff, 2) ?? "（居然能连）");
							Check("【对象】的出口 →【效果】的「指向对象」口：**可以**连",
								ForgeCanvas.CouldConnectForCheck(cvUnit, 0, cvEff, 2),
								ForgeCanvas.ConnectionProblemForCheck(cvUnit, 0, cvEff, 2) ?? "能连");
						}
						ForgeCanvas.Graph = forged.ForgeGraph;
						UpdateLayout();
						ForgeCanvas.SelectAll();
					}
					// 【能量】右边两个出口：接「能量」取 __X、接「额外资源量」取 __Y。"
					// 以前两个口都算成 __X（取值时不知道是从哪个口接过来的），第二个口等于没用。"
					{
						var eCard = new CardSpec { Name = "自检能量出口", ClassName = "UiCheckEnergyPort", CardType = "Attack", Cost = 0, IsForged = true };
						var eTrig = new ForgeNodeSpec { Kind = "Trigger" };
						eTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var eEff = new ForgeNodeSpec { Kind = "Effect" };
						eEff.SetField("Effect", "Damage");
						eEff.SetField("Amount", "1");
						var eEnergy = new ForgeNodeSpec { Kind = "Energy", X = ForgeGraphCatalog.EnergyX, Y = ForgeGraphCatalog.EnergyY };
						var eValX = new ForgeNodeSpec { Kind = "Value" };
						var eValY = new ForgeNodeSpec { Kind = "Value" };
						eValX.SetField("Formula", "X");
						eValY.SetField("Formula", "Y");
						eCard.ForgeGraph = new ForgeGraphSpec { Nodes = { eTrig, eEff, eEnergy, eValX, eValY } };
						var eg = eCard.ForgeGraph;
						eg.Links.Add(new ForgeLinkSpec { From = eTrig.Id, To = eEff.Id, FromPort = 0, ToPort = 0 });
						// 能量出口 0 →【数值】；数值 →【效果】的数值口
						eg.Links.Add(new ForgeLinkSpec { From = eEnergy.Id, To = eValX.Id, FromPort = 0, ToPort = 0 });
						eg.Links.Add(new ForgeLinkSpec { From = eValX.Id, To = eEff.Id, FromPort = 0, ToPort = 1 });
						Profile.Cards.Add(eCard);
						// 【数值】模块自己填了公式时，公式里写 X / Y 就够用了（用不着接线）；
						// 要验「接线取到的是哪个出口」，得把公式**留空** —— 那时它转发接进来的那一块。"
						eValX.Fields["Formula"] = "";
						string energySrc = CSharpCodeGen.CardSource(Profile, eCard, 0);
						Check("【能量】的「能量」出口接【数值】→ 生成里 __X = 当前能量（已扣掉【能量】模块填的打出消耗）",
							energySrc.Contains("decimal __X = ForgeFormulaRuntime.Energy("), "用 __X");
						Check("【能量】的「能量」出口 → 生成 __X 那个变量；出口 1 另起一个变量名，不会同名撞车",
							energySrc.Contains($"decimal {eEnergy.VarName} = __X;   // fg:{eEnergy.Id}【能量】"),
							"出口 0 = __X");
						// 换成接出口 1（额外资源量）"
						eValX.Fields["Formula"] = "X";
						eg.Links.RemoveAll(l => l is not null && l.From == eEnergy.Id);
						eg.Links.Add(new ForgeLinkSpec { From = eEnergy.Id, To = eValY.Id, FromPort = 1, ToPort = 0 });
						eg.Links.RemoveAll(l => l is not null && l.From == eValX.Id);
						eg.Links.Add(new ForgeLinkSpec { From = eValY.Id, To = eEff.Id, FromPort = 0, ToPort = 1 });
						eValY.Fields["Formula"] = "";
						string energySrc2 = CSharpCodeGen.CardSource(Profile, eCard, 0);
						Check("【能量】的「额外资源量」出口 → 生成 __Y（以前这个口也算成 __X，等于第二个口没用）",
							energySrc2.Contains($"decimal {eEnergy.VarName}p1 = __Y;   // fg:{eEnergy.Id}【能量】额外资源量"),
							"出口 1 = __Y（独立变量，不和 __X 撞名）");
						Profile.Cards.Remove(eCard);
					}
					double beforeX = forged.ForgeGraph.Nodes.First(n => n.Kind == "Value").X;
					double beforeY = forged.ForgeGraph.Nodes.First(n => n.Kind == "Value").Y;
					double energyX = forged.ForgeGraph.Nodes.First(n => n.Kind == "Energy").X;
					ForgeCanvas.MoveSelection(30, 20);
					var movedValue = forged.ForgeGraph.Nodes.First(n => n.Kind == "Value");
					Check("多选之后一起移动：所有选中的模块都动了",
						Math.Abs(movedValue.X - (beforeX + 30)) < 0.01 && Math.Abs(movedValue.Y - (beforeY + 20)) < 0.01,
						$"({movedValue.X},{movedValue.Y})");
					Check("【能量】模块固定不动（需求：放置于左上角固定）",
						Math.Abs(forged.ForgeGraph.Nodes.First(n => n.Kind == "Energy").X - energyX) < 0.01,
						"ForgeGraphCatalog.EnergyX");
				}

				// 升级后那一项 + 一键复制"
				ForgeGraphTabs.SelectedIndex = 1;
				UpdateLayout();
				Check("切到「升级后」之后显示「一键复制升级前」按钮", ForgeCopyVisible, $"ForgeCopyVisible={ForgeCopyVisible}");
				OnForgeCopyUpgraded(this, new RoutedEventArgs());
				Check("一键复制：升级后那块布和升级前内容一致但是**两块独立的布**",
					forged.UpgradedForgeGraph is not null
					&& forged.UpgradedForgeGraph.Nodes.Count == forged.ForgeGraph.Nodes.Count
					&& forged.UpgradedForgeGraph.Links.Count == forged.ForgeGraph.Links.Count
					&& !forged.UpgradedForgeGraph.Nodes.Select(n => n.Id).Intersect(forged.ForgeGraph.Nodes.Select(n => n.Id)).Any(),
					$"升级后 {forged.UpgradedForgeGraph?.Nodes.Count} 个模块 / {forged.UpgradedForgeGraph?.Links.Count} 条线");
				Check("升级后那张布自己也是可生成的（升级后走它）",
					CSharpCodeGen.CardSource(Profile, forged, 0).Contains("（升级后）"), "生成在");
				// 复制 = 抓那一刻的模样：复制之后在「升级前」上再改，不能影响「升级后」"
				{
					var upNodesBefore = forged.UpgradedForgeGraph!.Nodes.Select(n => n.Id).ToList();
					var sink = new ForgeNodeSpec { Kind = "Value" };
					sink.SetField("Formula", "99");
					forged.ForgeGraph.Nodes.Add(sink);
					forged.ForgeGraph.Links.Add(new ForgeLinkSpec { From = sink.Id, To = forged.UpgradedForgeGraph.Nodes[0].Id, FromPort = 0, ToPort = 0 });
					Check("复制之后在「升级前」上继续改，不影响「升级后」（只抓复制那一刻的模样）",
						forged.UpgradedForgeGraph.Nodes.Count == upNodesBefore.Count
						&& forged.UpgradedForgeGraph.Nodes.Select(n => n.Id).SequenceEqual(upNodesBefore)
						&& forged.UpgradedForgeGraph.Links.All(l => forged.ForgeGraph.Nodes.All(n => n.Id != l.From) || upNodesBefore.Contains(l.From)),
						$"升级后还是 {forged.UpgradedForgeGraph.Nodes.Count} 块 / {forged.UpgradedForgeGraph.Links.Count} 条线");
					Check("反过来也一样：两块布没有共用同一个模块对象（改一块不会连带改另一块）",
						!forged.ForgeGraph.Nodes.Any(n => forged.UpgradedForgeGraph.Nodes.Any(u => ReferenceEquals(u, n))),
						"没有共用对象");
					forged.ForgeGraph.Nodes.Remove(sink);
					forged.ForgeGraph.Links.RemoveAll(l => l is not null && (l.From == sink.Id || l.To == sink.Id));
				}
				// 两块布都设成「打出时」：不能生成两个同名方法（CS0111），也不能两个都调用
				{
					string twoSrc = CSharpCodeGen.CardSource(Profile, forged, 0);
					Check("两块布都是「打出时」时，升级前 / 升级后用的是两个不同的方法名（不然 CS0111）",
						twoSrc.Contains("ForgeGraphOnPlay(") && twoSrc.Contains("ForgeGraphOnPlayUpgraded("),
						"两个名字都在");
					Check("两块布都在时按「这张牌升级了没有」二选一（不是两套效果都跑一遍）",
						twoSrc.Contains("if (base.IsUpgraded) await ForgeGraphOnPlayUpgraded(")
						&& twoSrc.Contains("else await ForgeGraphOnPlay("),
						"二选一在");
				}
				// ===== V0.2.180：两块布都设成**卡自己那个钩子之外**的卡牌时刻 → 只能留一个 override =====
				// 用户实测报的：锻造卡的「升级前」「升级后」两块布都设「这张牌被抽到时」→ 生成两个
				// `public override async Task AfterCardDrawn(...)` → 整个模组 CS0111 编译不过。
				// 卡自己**没有**那个钩子（没有「卡牌时机 = 被抽到」这种效果）时靠 UnusedNested 兜：
				// 图那两块变成私有方法，CSharpCodeGen.EmitGraphOnlyHookContainers 补**唯一一个**壳 override。
				{
					var hookClash = new CardSpec
					{
						Name = "自检碰撞卡", ClassName = "UiCheckHookClash", CardType = "Skill", Rarity = "Common",
						Cost = 1, IsForged = true, InCardPool = false,
					};
					ForgeGraphSpec Mk(string timing)
					{
						var g = ForgeGraphSpec.NewWithTiming(timing);
						var t = g.TriggerNode!;
						var e = new ForgeNodeSpec { Kind = "Effect" };
						e.SetField("Effect", "Block");
						e.SetField("Amount", "2");
						e.SetField("TargetSide", "Self");
						g.Nodes.Add(e);
						g.Links.Add(new ForgeLinkSpec { From = t.Id, To = e.Id, FromPort = 0, ToPort = 0 });
						return g;
					}
					hookClash.ForgeGraph = Mk(ForgeTimings.CardDrawn);
					hookClash.UpgradedForgeGraph = Mk(ForgeTimings.CardDrawn);
					Profile.Cards.Add(hookClash);
					string clashSrc = CSharpCodeGen.CardSource(Profile, hookClash, Profile.Cards.Count - 1);
					int drawnOverrides = clashSrc.Split("public override async Task AfterCardDrawn(").Length - 1;
					Check("V0.2.180：两块布都设「这张牌被抽到时」→ 只生成**一个** AfterCardDrawn override（两个就 CS0111）",
						drawnOverrides == 1, $"{drawnOverrides} 个");
					Check("V0.2.180：那一个 override 里按 base.IsUpgraded 二选一调用两块布的私有方法",
						clashSrc.Contains("if (base.IsUpgraded) await ForgeGraphOnAfterCardDrawnUpgraded(choiceContext);", StringComparison.Ordinal)
						&& clashSrc.Contains("else await ForgeGraphOnAfterCardDrawn(choiceContext);", StringComparison.Ordinal)
						&& clashSrc.Contains("public async Task ForgeGraphOnAfterCardDrawn(PlayerChoiceContext choiceContext)", StringComparison.Ordinal)
						&& clashSrc.Contains("public async Task ForgeGraphOnAfterCardDrawnUpgraded(PlayerChoiceContext choiceContext)", StringComparison.Ordinal),
						"二选一 + 两个私有方法都在");
					Check("V0.2.180：壳 override 的守卫照卡牌时机那份写（card != this + 战斗中）",
						clashSrc.Contains("if (card != this || base.CombatState is null) return;", StringComparison.Ordinal), "有守卫");
					// 反例：只有一块布（升级后那块没设）时**不许**多出壳 override —— 那时图自己写一个 override 就够了
					//（判成「两块都撞上」会凭空多一个，自检里那条「不许生成 AfterFlush(PlayerChoiceContext) 这种
					//  不存在的签名」就是这么 FAIL 的）。
					var single = new CardSpec
					{
						Name = "自检单布卡", ClassName = "UiCheckHookSingle", CardType = "Skill", Rarity = "Common",
						Cost = 1, IsForged = true, InCardPool = false,
					};
					single.ForgeGraph = Mk(ForgeTimings.CardDrawn);
					Profile.Cards.Add(single);
					string singleSrc = CSharpCodeGen.CardSource(Profile, single, Profile.Cards.Count - 1);
					int singleOverrides = singleSrc.Split("public override async Task AfterCardDrawn(").Length - 1;
					Check("V0.2.180：只有一块布时照旧由它自己写一个 override（不多出壳、也不变私有方法）",
						singleOverrides == 1
						&& singleSrc.Contains("if (card != this || base.CombatState is null) return;", StringComparison.Ordinal)
						&& !singleSrc.Contains("ForgeGraphOnAfterCardDrawn(choiceContext)", StringComparison.Ordinal),
						$"{singleOverrides} 个 override");
					Profile.Cards.Remove(hookClash);
					Profile.Cards.Remove(single);
				}
				Check("「升级前 / 升级后」差异说明会点出「改了几块 / 多了几块 / 少了几块」",
					ForgeGraphGen.UpgradeDiff(forged).Contains("升级后"), ForgeGraphGen.UpgradeDiff(forged));
				Check("升级后那块布空着时，说明里写清「跟升级前一模一样」",
					ForgeGraphGen.UpgradeDiff(new CardSpec { IsForged = true, ForgeGraph = ForgeGraphSpec.NewCardGraph() })
						.Contains("一模一样"),
					"写清了");
				// 存盘 → 重新打开 → 再生成：节点图（含升级后那张布）必须完整保留
				{
					string rtPath = Path.Combine(Path.GetTempPath(), "forge_uicheck_rt_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
					ProfileFactory.Save(Profile, rtPath);
					var back = ProfileFactory.Load(rtPath);
					var card2 = back.Cards.FirstOrDefault(c => c is not null && c.IsForged && c.ForgeGraph is not null);
					Check("锻造节点图能存盘再读回来（模块 / 连线 / 升级后那块布都不丢）",
						card2 is not null
						&& card2.ForgeGraph!.Nodes.Count == forged.ForgeGraph!.Nodes.Count
						&& card2.ForgeGraph.Links.Count == forged.ForgeGraph.Links.Count
						&& (card2.UpgradedForgeGraph?.Nodes.Count ?? 0) == (forged.UpgradedForgeGraph?.Nodes.Count ?? 0),
						card2 is null ? "读回来没有图" : $"{card2.ForgeGraph!.Nodes.Count} 块 / 升级后 {(card2.UpgradedForgeGraph?.Nodes.Count ?? 0)} 块");
					try { File.Delete(rtPath); } catch { }
				}
				ForgeGraphTabs.SelectedIndex = 0;
				UpdateLayout();

				// 药水 / 遗物两类也要能添加 
				ForgeKindPotion.IsChecked = true;
				int potionsBefore = Profile.Potions.Count;
				OnAddForged(this, new RoutedEventArgs());
				Check("锻造页也能添加药水（前缀带 *）",
					Profile.Potions.Count == potionsBefore + 1 && Profile.Potions[Profile.Potions.Count - 1].IsForged
					&& Profile.Potions[Profile.Potions.Count - 1].Display.StartsWith("*", StringComparison.Ordinal),
					Profile.Potions[Profile.Potions.Count - 1].Display);
				ForgeKindRelic.IsChecked = true;
				int relicsBefore = Profile.Relics.Count;
				OnAddForged(this, new RoutedEventArgs());
				Check("锻造页也能添加遗物（前缀带 *）",
					Profile.Relics.Count == relicsBefore + 1 && Profile.Relics[Profile.Relics.Count - 1].IsForged
					&& Profile.Relics[Profile.Relics.Count - 1].Display.StartsWith("*", StringComparison.Ordinal),
					Profile.Relics[Profile.Relics.Count - 1].Display);

				// 清理
				Profile.Cards.Remove(forged);
				if (Profile.Potions.Count > potionsBefore) Profile.Potions.RemoveAt(Profile.Potions.Count - 1);
				if (Profile.Relics.Count > relicsBefore) Profile.Relics.RemoveAt(Profile.Relics.Count - 1);
				ForgeKindNone.IsChecked = true;
				RefreshForgeList();
			}

			// ===== 锻造页「状态列表」那一档（V0.2.194：用那块布给自定义状态编触发时机 / 效果）=====
			{
				// ①【触发时机】上新加的「只对哪类牌生效」只在**状态那一档 + 打牌类时机**上出现。
				// 量它必须真把这块布切到那一档 —— Scope 是 ForgeCanvasView 的私有字段，
				// 光看代码量不出「那一栏到底显不显示」（见 ForgeCanvasView.ScopeForCheck）。
				var prevScope = ForgeCanvas.Scope;
				var probeTrigger = new ForgeNodeSpec { Kind = "Trigger" };
				ForgeCanvas.ScopeForCheck(ForgeTimings.PowerScope);
				bool powerCardPlayed = ForgeCanvas.TriggerFieldVisibleForCheck(probeTrigger, ForgeTimings.CardPlayed, "CardFilter");
				// 状态档，但时机换成一条非打牌类的（这条在状态那一档确实有）—— 没有「这张牌」可筛，不该显示
				bool powerTurnStart = ForgeCanvas.TriggerFieldVisibleForCheck(probeTrigger, "PlayerTurnStart", "CardFilter");
				ForgeCanvas.ScopeForCheck("Card");
				bool cardCardPlayed = ForgeCanvas.TriggerFieldVisibleForCheck(probeTrigger, ForgeTimings.CardPlayed, "CardFilter");
				ForgeCanvas.ScopeForCheck(prevScope);
				Check("「状态列表」档 + 「打出一张牌时」→【触发时机】上有「只对哪类牌生效」那一栏（从「自定义状态」页搬过来的状态不能丢掉这个筛选）",
					powerCardPlayed, powerCardPlayed ? "显示" : "没显示");
				Check("（对照）状态那一档的「玩家回合开始时」上不显示那一栏（这个时机没有「这张牌」可筛）",
					!powerTurnStart, powerTurnStart ? "还显示着（错）" : "藏起来了");
				Check("（对照）同一个时机在**卡牌**那一档上不显示那一栏（卡牌自己就是那张牌）",
					!cardCardPlayed, cardCardPlayed ? "还显示着（错）" : "藏起来了");

				// ②「状态列表」档的「加模块」下拉里**没有【能量】**；卡牌档照旧有（回归红线：那一档一个字节都不许变）
				string energyDisplay = ForgeGraphCatalog.Find("Energy")?.Display ?? "能量";
				ForgeCanvas.ScopeForCheck(ForgeTimings.PowerScope);
				bool powerHasEnergy = ForgeCanvas.KindPickItemsForCheck.Contains(energyDisplay);
				ForgeCanvas.ScopeForCheck("Card");
				bool cardHasEnergy = ForgeCanvas.KindPickItemsForCheck.Contains(energyDisplay);
				ForgeCanvas.ScopeForCheck(prevScope);
				Check("「状态列表」档的「加模块」下拉里没有【能量】（状态没有「费用」这一说，摆了也不参与生成）",
					!powerHasEnergy, powerHasEnergy ? "下拉里还有（错）" : "没有");
				Check("（对照）卡牌档的下拉里照旧有【能量】",
					cardHasEnergy, cardHasEnergy ? "有" : "没有（错）");

				// ③ 红线：有老内容（「自定义状态」页配过触发时机）又没图的状态，选中它**绝对不许自动建布**
				// —— 布上一旦有【触发时机】就不算空（ForgeGraphSpec.IsEmpty 判的是「一个模块都没有」），
				// 生成端立刻切成「图说了算」，老配置的触发时机 / 效果全丢。只能用户自己按那个按钮搬。
				var legacy = new CustomPowerSpec { Name = "自检老内容状态", Enabled = true };
				legacy.Triggers.Add(new PowerTriggerSpec
				{
					Kind = "PlayerTurnStart",
					Effects = { new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" } },
				});
				Profile.CustomPowers.Add(legacy);
				ForgeKindPower.IsChecked = true;
				RefreshForgeList();
				ForgeItemList.SelectedItem = legacy;
				SyncForgeDetail();
				Check("有老配置又没图的状态：选中它**不会**自动建布（红线 —— 建了老配置就全丢了）",
					legacy.ForgeGraph is null,
					legacy.ForgeGraph is null ? "没建（对）" : $"建了 {legacy.ForgeGraph.Nodes.Count} 块（错）");
				Check("这种情况（有老内容 + 还没图）下「⤓ 把现在的触发时机 / 效果搬到这块布上」那个按钮会露出来",
					ForgeMigrateVisible, $"ForgeMigrateVisible={ForgeMigrateVisible}");
				OnForgeMigrateToGraph(this, new RoutedEventArgs());
				Check("点了「搬到这块布上」→ 这块布非空、生成端从此认它（ForgeGraphGen.UsesGraph）",
					ForgeGraphGen.UsesGraph(legacy), $"图={legacy.ForgeGraph?.Nodes.Count ?? 0} 块");
				Check("搬完那个按钮就收起来了（没有可搬的了）", !ForgeMigrateVisible, $"ForgeMigrateVisible={ForgeMigrateVisible}");
				Check("搬的是**同一份**老配置（效果对象没被复制掉，之后两边还看得见）",
					legacy.Triggers.Count == 1 && legacy.Triggers[0].Effects.Count == 1,
					$"{legacy.Triggers.Count} 条时机 / {legacy.Triggers.FirstOrDefault()?.Effects.Count ?? 0} 条效果");

				// ④「添加」：新建的状态会立刻自带一块只有【触发时机】的空布
				int powersBefore = Profile.CustomPowers.Count;
				OnAddForged(this, new RoutedEventArgs());
				CustomPowerSpec added = Profile.CustomPowers[Profile.CustomPowers.Count - 1];
				Check("「状态列表」档点「添加」→ 新建一只自定义状态，而且立刻自带一块布（有【触发时机】可接）",
					Profile.CustomPowers.Count == powersBefore + 1 && added.ForgeGraph is not null
					&& added.ForgeGraph.Nodes.Any(n => n is not null && n.Kind == "Trigger"),
					$"{powersBefore} → {Profile.CustomPowers.Count} 只 / 图={added.ForgeGraph?.Nodes.Count ?? 0} 块");
				Check("刚建的状态会立刻选中，右边那块布马上指向它",
					ReferenceEquals(ForgeItemList.SelectedItem, added) && ReferenceEquals(ForgeCanvas.Graph, added.ForgeGraph),
					ForgeItemList.SelectedItem is CustomPowerSpec cur ? cur.Name : "(没选中)");
				Check("新建的状态名字沿用「自定义状态」页那套（新状态N）",
					added.Name.StartsWith("新状态", StringComparison.Ordinal), added.Name);

				// 清理：自检造出来的两只状态删掉。
				// ⚠ 这里**不能**走 OnRemoveForged —— 它会弹确认框，自检会卡在那儿等人点。
				Profile.CustomPowers.Remove(legacy);
				Profile.CustomPowers.Remove(added);
				ForgeKindNone.IsChecked = true;
				RefreshForgeList();
				Check("自检造出来的两只自定义状态已清理", Profile.CustomPowers.Count == powersBefore - 1,
					$"{Profile.CustomPowers.Count} 只");
			}
			// ===== V0.2.194：状态那块布的**生成端**（上面那一段量的是界面；这一段量生成的代码）=====
			{
				// ① 时机菜单：Power 档 = 「自定义状态」页那一整套（id / 显示名逐条对齐，一个不漏）
				var forgePowerTimings = ForgeTimings.For(ForgeTimings.PowerScope);
				Check("状态那一档的触发时机 = 「自定义状态」页那份（逐条对齐，一个不漏）",
					forgePowerTimings.Count == PowerTriggers.All.Count
					&& PowerTriggers.All.All(t => forgePowerTimings.Any(x => x.Id == t.Kind && x.Display == t.Display)),
					$"Power {forgePowerTimings.Count} 条 / PowerTriggers {PowerTriggers.All.Count} 条");
				Check("状态那一档的钩子分组 = 「自定义状态」页那份（同一个本体钩子只生成一个 override）",
					forgePowerTimings.All(x => CustomPowerGen.PowerHookOf(x.Id) == x.Hook)
					&& CustomPowerGen.PowerHookOf("PlayerTurnEnd") == "TurnEnd"
					&& CustomPowerGen.PowerHookOf("EnemyTurnEnd") == "TurnEnd"
					&& CustomPowerGen.PowerHookOf("CombatEnd") == "CombatVictory", "同一份");
				Check("状态那一档的时机没有混进卡牌 / 药水 / 遗物那三档（默认档输出不变的前提）",
					ForgeTimings.For("Card").All(x => x.Scope == "Card") && ForgeTimings.For("Card").Count == 6
					&& ForgeTimings.For("Potion").Count == 1
					&& ForgeTimings.For("Relic").All(x => x.Scope == "Relic"), "各归各档");

				// ② 老路：图空 → 「自定义状态」页那套照旧（没有图的序幕，也没有图标记）
				var genLegacy = new CustomPowerSpec { Name = "自检老路状态", ClassName = "UiCheckPowerLegacyGen", Type = "Debuff" };
				var genLegacyTrig = new PowerTriggerSpec { Kind = "PlayerTurnEnd" };
				genLegacyTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = -6m });
				genLegacy.Triggers.Add(genLegacyTrig);
				string genLegacySrc = CustomPowerGen.Source(Profile, genLegacy, 0);
				Check("状态这一类：图空 = 老路（触发时机 + 效果列表照旧，且**没有**图的序幕 / 标记）",
					genLegacySrc.Contains("public override async Task BeforeSideTurnEnd(")
					&& genLegacySrc.Contains("CreatureCmd.LoseBlock")
					&& !genLegacySrc.Contains("锻造节点图：执行点先算好这几个值")
					&& !genLegacySrc.Contains("CET:ForgeGraph="), "老路");

				// ③ 图版：「玩家回合开始时 → 获得 5 格挡」+「打出一张牌时（只对攻击牌）→ if(自己身上减益数 ≥ 3) 抽 2 张」
				var genGraph = new CustomPowerSpec { Name = "自检布状态", ClassName = "UiCheckPowerGraphGen", Type = "Buff" };
				var genSpec = new ForgeGraphSpec();
				var genTrig1 = new ForgeNodeSpec { Kind = "Trigger" };
				genTrig1.SetField("Timing", "PlayerTurnStart");
				var genBlock = new ForgeNodeSpec { Kind = "Effect" };
				genBlock.SetField("Effect", "Block");
				genBlock.SetField("Amount", "5");
				var genTrig2 = new ForgeNodeSpec { Kind = "Trigger" };
				genTrig2.SetField("Timing", "CardPlayed");
				genTrig2.SetField("CardFilter", "Attack");
				var genIf = new ForgeNodeSpec { Kind = "If" };
				var genList = new ForgeNodeSpec { Kind = "PowerList" };
				genList.SetField("ListFilter", "Debuff");
				genList.SetField("ListWhat", "Count");
				var genRel = new ForgeNodeSpec { Kind = "Relate" };
				genRel.SetField("Op", "Ge");
				genRel.SetField("Amount", "3");
				var genDraw = new ForgeNodeSpec { Kind = "Effect" };
				genDraw.SetField("Effect", "Draw");
				genDraw.SetField("Amount", "2");
				genSpec.Nodes.AddRange(new[] { genTrig1, genBlock, genTrig2, genIf, genList, genRel, genDraw });
				genSpec.Links.Add(new ForgeLinkSpec { From = genTrig1.Id, To = genBlock.Id });
				genSpec.Links.Add(new ForgeLinkSpec { From = genTrig2.Id, To = genIf.Id });
				genSpec.Links.Add(new ForgeLinkSpec { From = genIf.Id, To = genDraw.Id, FromPort = 0, ToPort = 0 });
				genSpec.Links.Add(new ForgeLinkSpec { From = genList.Id, To = genRel.Id, FromPort = 0, ToPort = 1 });
				genSpec.Links.Add(new ForgeLinkSpec { From = genRel.Id, To = genIf.Id, FromPort = 0, ToPort = 1 });
				genGraph.ForgeGraph = genSpec;
				string genGraphSrc = CustomPowerGen.Source(Profile, genGraph, 0);
				Check("状态那块布：每条【触发时机】各生成一个本体钩子（方法壳复用「自定义状态」页那一份）",
					genGraphSrc.Contains("public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)")
					&& genGraphSrc.Contains("public override async Task BeforeCardPlayed(CardPlay cardPlay)"), "两个钩子");
				Check("状态那块布：序幕按状态取（base.Owner.Player / base.Owner），不写卡牌 / 遗物那套",
					genGraphSrc.Contains("Player __fgPlayer = base.Owner.Player!;")
					&& genGraphSrc.Contains("Creature __fgSelf = base.Owner;")
					&& !genGraphSrc.Contains("__fgPlayer.Creature"), "状态那一档");
				Check("状态那块布：图上【效果】真的进了钩子（获得格挡 / 抽牌都写出来了）",
					genGraphSrc.Contains("CreatureCmd.GainBlock") && genGraphSrc.Contains("CardPileCmd.Draw"), "都在");
				Check("状态那块布：【状态列表】没接【对象】时默认数**自己身上**的（不是第一个敌人）",
					genGraphSrc.Contains("ForgeFormulaRuntime.PowerCount(__fgSelf,"), "自己");
				Check("状态那块布：写了 CET:ForgeGraph 标记（「从工程恢复」靠它把图整份装回来）",
					genGraphSrc.Contains("// CET:ForgeGraph=1:"), "有标记");
				Check("状态那块布：「只对哪类牌生效」那一栏保住（打牌类时机，从「自定义状态」页搬过来不会丢）",
					genGraphSrc.Contains("cardPlay.Card.Type == CardType.Attack"), "筛攻击牌");

				// ④ 「数值 / 生效次数 / 命中次数 = 本状态层数」三个开关（用户 31 只状态里 16 只用它）
				var genStack = new CustomPowerSpec { Name = "自检层数状态", ClassName = "UiCheckPowerStackGen", Type = "Buff" };
				var genStackGraph = new ForgeGraphSpec();
				var genStackTrig = new ForgeNodeSpec { Kind = "Trigger" };
				genStackTrig.SetField("Timing", "PlayerTurnStart");
				var genStackFx = new ForgeNodeSpec { Kind = "Effect" };
				genStackFx.SetField("Effect", "Block");
				genStackFx.SetField("Amount", "3");
				var genStackSpec = ForgeEffectBridge.Author(genStackFx);
				genStackSpec.Kind = "Block";
				genStackSpec.Amount = 3m;
				genStackSpec.AmountIsStack = true;      // 「数值 = 本状态层数」那一栏
				genStackGraph.Nodes.AddRange(new[] { genStackTrig, genStackFx });
				genStackGraph.Links.Add(new ForgeLinkSpec { From = genStackTrig.Id, To = genStackFx.Id });
				genStack.ForgeGraph = genStackGraph;
				string genStackSrc = CustomPowerGen.Source(Profile, genStack, 0);
				Check("状态那块布：「数值 = 本状态层数」生成 base.Amount（不是那个固定数字）",
					genStackSrc.Contains("GainBlock(__fgFoe, ((decimal)base.Amount)"), "base.Amount");
				Check("状态那块布：「= 本状态层数」只对**状态**放行（卡牌 / 遗物 / 药水照旧报「不生效」拦住）",
					!ForgeGraphGen.UnsupportedEffectSettings(genStackGraph, genStackFx, ForgeTimings.PowerScope)
						.Any(x => x.Message.Contains("本状态层数"))
					&& ForgeGraphGen.UnsupportedEffectSettings(genStackGraph, genStackFx)
						.Any(x => x.Message.Contains("本状态层数")), "只对状态放行");

				// ⑤ 搬迁助手（界面那个按钮背后那份逻辑）：能不能自动建布 / 搬了什么
				Check("搬迁：有老内容的状态**不能**自动建布（一建布生成就改成图说了算，老配置会静默失效）",
					!ForgePowerGraph.CanAutoCreate(genLegacy) && ForgePowerGraph.HasLegacyContent(genLegacy)
					&& ForgePowerGraph.CanAutoCreate(new CustomPowerSpec { Name = "自检空状态", ClassName = "UiCheckPowerEmptyGen" }),
					"不自动");
				var genMove = new CustomPowerSpec { Name = "自检搬迁", ClassName = "UiCheckPowerMoveGen", Type = "Debuff" };
				var genMoveTrig = new PowerTriggerSpec { Kind = "PlayerTurnEnd", CardFilter = "Attack" };
				genMoveTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = -6m });
				genMove.Triggers.Add(genMoveTrig);
				var genMoved = ForgePowerGraph.MigrateToGraph(genMove, out List<string> genMoveNotes);
				Check("搬迁：触发时机 / 效果都搬到布上（图非空 → 生成改由图说了算）",
					ForgeGraphGen.UsesGraph(genMove) && genMoved.TriggerNodes.Count == 1
					&& genMoved.TriggerNodes[0].Get("Timing") == "PlayerTurnEnd"
					&& genMoved.Nodes.Count(n => n.Kind == "Effect") == 1
					&& genMoved.Nodes.First(n => n.Kind == "Effect").Get("Effect") == "Block"
					&& genMoved.Nodes.First(n => n.Kind == "Effect").EffectSpec?.Amount == -6m
					&& genMoveNotes.Any(x => x.Contains("这块布说了算")), $"{genMoved.Nodes.Count} 个模块");
				Check("搬迁：原来那条「只对哪类牌生效」也搬过去了（不然会变成「任意一张牌都触发」）",
					string.Equals(genMoved.TriggerNodes[0].Get("CardFilter"), "Attack", StringComparison.Ordinal),
					genMoved.TriggerNodes[0].Get("CardFilter"));
				string genMoveSrc = CustomPowerGen.Source(Profile, genMove, 0);
				Check("搬迁后生成：钩子 / 效果跟老路语义一致（回合结束失去 6 点格挡，打在自己身上）",
					genMoveSrc.Contains("public override async Task BeforeSideTurnEnd(")
					&& genMoveSrc.Contains("LoseBlock(choiceContext, __fgFoe, 6m")
					&& genMoveSrc.Contains("new List<Creature> { __fgSelf }"), "一致");

				// ⑥ 校验器：布上做不了 / 会静默不生效的几条（一律报错或警告，不许静默）
				var vpPower = ProfileFactory.Sample();
				var badNoTrig = new CustomPowerSpec { Name = "自检空布状态", ClassName = "UiCheckPowerNoTrig", Enabled = true };
				badNoTrig.ForgeGraph = new ForgeGraphSpec();
				badNoTrig.ForgeGraph.Nodes.Add(new ForgeNodeSpec { Kind = "Effect" });      // 只有【效果】，没有【触发时机】
				var badObtained = new CustomPowerSpec { Name = "自检获得时状态", ClassName = "UiCheckPowerObtained", Enabled = true };
				var badObtainedGraph = new ForgeGraphSpec();
				var badObtainedTrig = new ForgeNodeSpec { Kind = "Trigger" };
				badObtainedTrig.SetField("Timing", "Obtained");
				badObtainedGraph.Nodes.Add(badObtainedTrig);
				badObtained.ForgeGraph = badObtainedGraph;
				var badReward = new CustomPowerSpec { Name = "自检奖励状态", ClassName = "UiCheckPowerReward", Enabled = true };
				var badRewardGraph = new ForgeGraphSpec();
				var badRewardTrig = new ForgeNodeSpec { Kind = "Trigger" };
				badRewardTrig.SetField("Timing", "CombatVictory");
				var badRewardFx = new ForgeNodeSpec { Kind = "Effect" };
				badRewardFx.SetField("Effect", "CardReward");
				badRewardGraph.Nodes.AddRange(new[] { badRewardTrig, badRewardFx });
				badRewardGraph.Links.Add(new ForgeLinkSpec { From = badRewardTrig.Id, To = badRewardFx.Id });
				badReward.ForgeGraph = badRewardGraph;
				var badEnergy = new CustomPowerSpec { Name = "自检能量布状态", ClassName = "UiCheckPowerEnergyNode", Enabled = true };
				var badEnergyGraph = new ForgeGraphSpec();
				var badEnergyTrig = new ForgeNodeSpec { Kind = "Trigger" };
				badEnergyTrig.SetField("Timing", "PlayerTurnStart");
				badEnergyGraph.Nodes.AddRange(new[] { badEnergyTrig, new ForgeNodeSpec { Kind = "Energy" } });
				badEnergy.ForgeGraph = badEnergyGraph;
				vpPower.CustomPowers.Add(badNoTrig);
				vpPower.CustomPowers.Add(badObtained);
				vpPower.CustomPowers.Add(badReward);
				vpPower.CustomPowers.Add(badEnergy);
				var vIssues = ProfileValidator.Validate(vpPower);
				Check("校验：布上一个【触发时机】都没有 → 错误（那样一个钩子都不会生成）",
					vIssues.Any(x => x.Level == "错误" && x.Message.Contains("自检空布状态") && x.Message.Contains("一块【触发时机】都没有")), "报错");
				Check("校验：布上用了【触发时机】=「获得时」→ 错误（遗物专属，状态上不生成任何东西）",
					vIssues.Any(x => x.Level == "错误" && x.Message.Contains("自检获得时状态") && x.Message.Contains("获得时")), "报错");
				Check("校验：布上放了【获得卡牌奖励】→ 错误（那几句要 base.Owner.Character，状态上没有）",
					vIssues.Any(x => x.Level == "错误" && x.Message.Contains("自检奖励状态") && x.Message.Contains("获得卡牌奖励")), "报错");
				Check("校验：布上摆了【能量】模块 → 警告（状态没有费用这一说，那一块不参与生成）",
					vIssues.Any(x => x.Level == "警告" && x.Message.Contains("自检能量布状态") && x.Message.Contains("能量")), "警告");
				var mixedPower = new CustomPowerSpec { Name = "自检图说了算", ClassName = "UiCheckPowerGraphWins", Enabled = true };
				var mixedTrig = new PowerTriggerSpec { Kind = "PlayerTurnEnd" };
				mixedTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
				mixedPower.Triggers.Add(mixedTrig);
				var mixedGraph = new ForgeGraphSpec();
				var mixedNode = new ForgeNodeSpec { Kind = "Trigger" };
				mixedNode.SetField("Timing", "PlayerTurnStart");
				mixedGraph.Nodes.Add(mixedNode);
				mixedPower.ForgeGraph = mixedGraph;
				vpPower.CustomPowers.Add(mixedPower);
				var vIssues2 = ProfileValidator.Validate(vpPower);
				Check("校验：图说了算 + 页面上还配着老内容 → 警告（说清「页面上那套不再参与生成」）",
					vIssues2.Any(x => x.Level == "警告" && x.Message.Contains("自检图说了算") && x.Message.Contains("那块布说了算")), "警告");
			}
			Check("召唤物列表绑定到 Profile.Summons（列表，不是单对象）",
				SummonList != null && BindingOperations.GetBinding(SummonList, ItemsControl.ItemsSourceProperty)?.Path?.Path == "Profile.Summons",
				SummonList is null ? "没找到列表" : (BindingOperations.GetBinding(SummonList, ItemsControl.ItemsSourceProperty)?.Path?.Path ?? "(没绑定)"));
			DependencyObject summonRoot = SelectTabRoot("召唤物");
			List<string> summonTexts = TextsIn(summonRoot);
			Check("召唤物页有「添加召唤物 / 删除 / 撤回删除」按钮",
				summonTexts.Contains("添加召唤物") && summonTexts.Contains("删除") && summonTexts.Contains("撤回删除"), "控件在");
			// 没选中任何召唤物时右边是**收起**的（只显示一句空态提示）—— 先确认这条空态在，
			// 再自己加一条并选中，后面那些「详情里的控件」断言才有东西可查
			//（以前直接读 TextsIn 页 root，详情折叠着，于是一律查不到 → 白白 FAIL）。
			Check("召唤物页未选中时显示空态提示（右侧详情收起，不是一张空表单）",
				summonTexts.Any((string t) => t.Contains("请选择召唤物")),
				string.Join(" / ", summonTexts.Take(6)));
			Check("召唤物：示例配置自带 0 只（新存档不凭空多一只宠物，也就不会凭空生成 cs/Pet.cs）",
				Profile.Summons.Count == 0, $"{Profile.Summons.Count} 条");
			var summonProbe = new SummonSpec
			{
				Enabled = true,
				ClassName = "UiCheckPetPageProbe",
				Name = "界面自检伙伴",
				Hp = 10,
				StandDistance = 120,
			};
			Profile.Summons.Add(summonProbe);
			SummonList.SelectedItem = summonProbe;
			UpdateLayout();
			summonTexts = TextsIn(summonRoot);
			Check("召唤物页有「启用 / 名字 / 英文类名 / 生命 / 站位距离 / 替主人承伤」（选中一条后详情展开才有）",
				summonTexts.Any((string t) => t.Contains("启用这只召唤物")) && summonTexts.Any((string t) => t.Contains("名字（宠物名牌）"))
				&& summonTexts.Any((string t) => t.Contains("英文类名")) && summonTexts.Any((string t) => t.Contains("召唤时的生命"))
				&& summonTexts.Any((string t) => t.Contains("站位距离")) && summonTexts.Any((string t) => t.Contains("替主人承伤")),
				string.Join(" / ", summonTexts.Where((string t) => t.Contains("召唤") || t.Contains("站位") || t.Contains("承伤")).Take(6)));
			Check("召唤物页写明了「替主人承伤」可以勾多只、承伤的是列表里第一只活着的（本体伤害重定向是链式遍历，由我们仲裁）",
				summonTexts.Any((string t) => t.Contains("可以勾多只") && t.Contains("第一只活着")),
				string.Join(" / ", summonTexts.Where((string t) => t.Contains("承伤")).Take(4)));
			// 详情里的输入框要双向绑定到「选中的那一只」上（数据源是列表的 SelectedItem）
			{
				List<TextBox> summonBoxes = new List<TextBox>();
				CollectTextBoxes(summonRoot, summonBoxes);
				List<string> summonPaths = summonBoxes.Select((TextBox b) => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path ?? "").ToList();
				Check("召唤物详情里有「名字 / 英文类名 / 生命 / 站位距离」四个输入框",
					summonPaths.Contains("Name") && summonPaths.Contains("ClassName") && summonPaths.Contains("Hp") && summonPaths.Contains("StandDistance"),
					string.Join(" / ", summonPaths));
				// 效果编辑器里的「召唤物（哪一只）」下拉：卡牌 / 遗物两处都要有
				// （用 SelectTabRoot 切页再收文字 —— 顺手也保证这两个页本身能正常选中）
				Check("效果编辑器有「召唤物（哪一只）」下拉（卡牌页）",
					TextsIn(SelectTabRoot("卡牌")).Contains("召唤物（哪一只）"), "下拉在");
				// ⚠ V0.2.144：遗物页的效果编辑器现在在**下面那块共享编辑区**里（一行摘要列表 + 编辑区）——
				// 只要在列表里选中一条，编辑区（含这个下拉）就在可视树里。
				{
					DependencyObject relicRoot2 = SelectTabRoot("遗物");
					if (RelicEffectList.Items.Count > 0)
					{
						if (RelicEffectList.SelectedIndex < 0) RelicEffectList.SelectedIndex = 0;
						UpdateLayout();
					}
					Check("效果编辑器有「召唤物（哪一只）」下拉（遗物页）",
						TextsIn(relicRoot2).Contains("召唤物（哪一只）"), "下拉在");
				}
			}

			// ===== 宠物类效果：不再有专属选项卡，全部在「卡牌」页的效果种类下拉里选 =====
			// 用户要求删掉「召唤物卡牌」页（那个页的列表 / 专属效果栏 / 自动归类 /「这是召唤物卡」勾选全没了），
			// 但 12 个宠物效果本身必须继续能在「卡牌」页选到，选到之后「召唤物（哪一只）」下拉要出来。
			{
				Check("界面上已经没有「召唤物卡牌」选项卡（整页删除后不该再冒出来）",
					FindTab("召唤物卡牌") is null,
					FindTab("召唤物卡牌") is null ? "已删除" : "还在");
				DependencyObject cardRoot = SelectTabRoot("卡牌");
				// 没选中卡牌时右侧详情是**收起**的（只显示一句空态提示）→ 效果种类下拉根本不在树里，
				// 下面的断言会白白 FAIL。先确认选中一张（自检里前面几段多半已经选过，这里兜底）。
				if (CardUiSelection is null && Profile.Cards.Count > 0) CardList.SelectedItem = Profile.Cards[0];
				UpdateLayout();
				List<ComboBox> cardCombos = new List<ComboBox>();
				CollectCombos(cardRoot, cardCombos);
				List<ComboBox> cardKindCombos = cardCombos.Where((ComboBox c) => c.SelectedValuePath == "Kind").ToList();
				List<EffectKindOption> petKinds = EffectCatalog.PetEffectKinds.ToList();
				Check("EffectCatalog 里那 12 个宠物效果一个都不少（删除的只是页面，不是效果）",
					petKinds.Count == 12 && petKinds.All(k => EffectCatalog.IsPetKind(k.Kind))
					&& new[] { "SummonPet", "PetAttack", "PetDamageByMaxHp", "PetDamageByCurHp", "PetDamageByMissingHp",
							   "PetHeal", "PetLoseHp", "PetGainMaxHp", "PetSacrifice", "PetApplyPower",
							   "PetGuardOn", "PetGuardOff" }.All(id => petKinds.Any(k => k.Kind == id)),
					$"{petKinds.Count} 个：" + string.Join(" / ", petKinds.Select(k => k.Kind)));
				// ===== V0.2.168：自定义状态（触发时机）里也能放「召唤伙伴」 =====
				// 用户实测报的：状态页「生成卡牌时 → 召唤伙伴」被生成拦住了
				//（PowerTriggers.SupportedEffectKinds 里没有它、生成端也没实现）。
				{
					Check("V0.2.168：状态那条链的支持清单里有「召唤伙伴」（以前会被校验拦成错误）",
						PowerTriggers.Supports("SummonPet"), "支持");
					Check("V0.2.168：召唤伙伴算进「需要 choiceContext」那一档（生成的 Summon(choiceContext, …) 第一个参数就是它）",
						CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "SummonPet" }), "要上下文");
					var petStateProbe = ProfileFactory.Sample();
					petStateProbe.Summons.Clear();
					petStateProbe.Summons.Add(new SummonSpec { Enabled = true, Name = "自检伙伴", ClassName = "UiCheckSummonState", Hp = 10 });
					var petStatePow = new CustomPowerSpec { Name = "自检召唤状态", ClassName = "UiCheckSummonStatePower", Enabled = true };
					var petStateTrig = new PowerTriggerSpec { Kind = "CardGenerated" };
					petStateTrig.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 12m, PetSummon = "UiCheckSummonState" });
					petStateTrig.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, PetSummon = "UiCheckSummonState" });
					petStatePow.Triggers.Add(petStateTrig);
					petStateProbe.CustomPowers.Add(petStatePow);
					var petStateIssues = ProfileValidator.Validate(petStateProbe);
					Check("V0.2.168：校验器不再拦「状态里放召唤伙伴」",
						!petStateIssues.Any((ValidationIssue x) => x.IsError && x.Message.Contains("召唤伙伴", StringComparison.Ordinal)),
						petStateIssues.FirstOrDefault((ValidationIssue x) => x.IsError)?.Message ?? "没有错误");
					string petStateSrc = CustomPowerGen.Source(petStateProbe, petStatePow, petStateProbe.CustomPowers.Count - 1);
					Check("V0.2.168：状态链生成 `XxxCmd.Summon(choiceContext, base.Owner.Player, …)`（召唤者要传玩家 —— 状态钩子里 base.Owner 是 Creature）",
						petStateSrc.Contains("UiCheckSummonStateCmd.Summon(choiceContext, base.Owner.Player, 12m)", StringComparison.Ordinal)
						&& petStateSrc.Contains("UiCheckSummonStateCmd.Summon(choiceContext, base.Owner.Player, 10m)", StringComparison.Ordinal),
						"召唤者传玩家");
					Check("V0.2.168：这条时机的钩子本体不给 choiceContext 时会自己造一个（不然 CS0103）",
						petStateSrc.Contains("HookPlayerChoiceContext", StringComparison.Ordinal), "造了上下文");
					string petStateDesc = PowerTriggers.AutoDescription(petStatePow);
					Check("V0.2.168：状态描述里写「召唤伙伴」而不是英文种类名",
						petStateDesc.Contains("召唤伙伴", StringComparison.Ordinal) && !petStateDesc.Contains("SummonPet", StringComparison.Ordinal),
						petStateDesc.Replace("\n", " ⏎ "));
					// 不放手：状态里放了召唤伙伴，但一只召唤物都没启用 → 仍然报错（会引用不存在的类）
					var petBadProbe = ProfileFactory.Sample();
					petBadProbe.Summons.Clear();
					var petBadPow = new CustomPowerSpec { Name = "自检无伙伴状态", ClassName = "UiCheckNoPetPower", Enabled = true };
					var petBadTrig = new PowerTriggerSpec { Kind = "CardGenerated" };
					petBadTrig.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 5m, PetSummon = "UiCheckSummonState" });
					petBadPow.Triggers.Add(petBadTrig);
					petBadProbe.CustomPowers.Add(petBadPow);
					Check("V0.2.168（不放手）：状态里放了召唤伙伴，但一只召唤物都没启用 → 仍然报错拦住",
						ProfileValidator.Validate(petBadProbe).Any((ValidationIssue x) => x.IsError
							&& x.Message.Contains("召唤", StringComparison.Ordinal)),
						ProfileValidator.Validate(petBadProbe).FirstOrDefault((ValidationIssue x) => x.IsError)?.Message ?? "(没报！)");
				}

				// ===== V0.2.210：自定义状态触发器里的**其余宠物效果** =====
				// 用户截图报的：状态「新状态29」『打出一张牌时（这张牌还没生效）』第 1 条是「给伙伴施加状态」，
				// 被校验拦成错误（PowerTriggers.SupportedEffectKinds 里没有它，生成端也没实现）。
				{
					Check("V0.2.210：状态那条链的支持清单里有「给伙伴施加状态 / 治疗伙伴 / 伙伴失去生命 / 伙伴最大生命 +N / 承伤开关」",
						PowerTriggers.Supports("PetApplyPower") && PowerTriggers.Supports("PetHeal")
						&& PowerTriggers.Supports("PetLoseHp") && PowerTriggers.Supports("PetGainMaxHp")
						&& PowerTriggers.Supports("PetGuardOn") && PowerTriggers.Supports("PetGuardOff"),
						"六个都在");
					Check("V0.2.210：那六个都进了状态编辑器的效果下拉（= PowerKinds 筛 Supports 出来的那份）",
						new[] { "PetApplyPower", "PetHeal", "PetLoseHp", "PetGainMaxHp", "PetGuardOn", "PetGuardOff" }
							.All(id => PowerKinds.Any(k => k.Kind == id)),
						string.Join(" / ", PowerKinds.Where(k => EffectCatalog.IsPetKind(k.Kind)).Select(k => k.Kind)));
					// 「给伙伴施加状态」需要 choiceContext（PowerCmd.Apply 第一个实参）；治疗 / 加最大生命不需要
					Check("V0.2.210：需要 choiceContext 的那几条被认出来了（施加上状态 / 失去生命 / 承伤开关要，治疗 / 加最大生命不要）",
						CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetApplyPower" })
						&& CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetLoseHp" })
						&& CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetGuardOn" })
						&& CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetGuardOff" })
						&& !CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetHeal" })
						&& !CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetGainMaxHp" }),
						"判据对");
					// 「牺牲伙伴」收益 = 造成伤害 / 获得状态 也要（以前漏了 → 那种配置生成出来 CS0103）
					Check("V0.2.210：「牺牲伙伴」按收益档位判 choiceContext（伤害 / 状态要，格挡不要）",
						CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Damage" })
						&& CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Power" })
						&& !CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Block" }),
						"判据对");

					// 真的生成一遍：状态「打出一张牌时 → 给伙伴施加状态 2 层易伤」
					var petFxProbe = ProfileFactory.Sample();
					petFxProbe.Summons.Clear();
					petFxProbe.Summons.Add(new SummonSpec { Enabled = true, Name = "自检大运", ClassName = "UiCheckPetFx", Hp = 20 });
					var petFxPow = new CustomPowerSpec { Name = "自检宠物效果状态", ClassName = "UiCheckPetFxPower", Enabled = true };
					var petFxTrig = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Any" };
					petFxTrig.Effects.Add(new EffectSpec { Kind = "PetApplyPower", Amount = 2m, PowerId = "VulnerablePower", PetSummon = "UiCheckPetFx" });
					petFxTrig.Effects.Add(new EffectSpec { Kind = "PetHeal", Amount = 5m, PetSummon = "UiCheckPetFx" });
					petFxTrig.Effects.Add(new EffectSpec { Kind = "PetLoseHp", Amount = 3m, PetSummon = "UiCheckPetFx" });
					petFxTrig.Effects.Add(new EffectSpec { Kind = "PetGainMaxHp", Amount = 4m, PetSummon = "UiCheckPetFx" });
					petFxTrig.Effects.Add(new EffectSpec { Kind = "PetGuardOn", PetSummon = "UiCheckPetFx" });
					petFxTrig.Effects.Add(new EffectSpec { Kind = "PetGuardOff", PetSummon = "UiCheckPetFx" });
					petFxPow.Triggers.Add(petFxTrig);
					petFxProbe.CustomPowers.Add(petFxPow);
					var petFxIssues = ProfileValidator.Validate(petFxProbe);
					Check("V0.2.210：校验器不再拦「状态里放给伙伴施加状态 / 治疗 / 失去生命 / 最大生命 / 承伤开关」（用户报的那条）",
						!petFxIssues.Any((ValidationIssue x) => x.IsError
							&& (x.Message.Contains("给伙伴施加状态", StringComparison.Ordinal)
								|| x.Message.Contains("治疗伙伴", StringComparison.Ordinal)
								|| x.Message.Contains("伙伴失去生命", StringComparison.Ordinal)
								|| x.Message.Contains("伙伴最大生命", StringComparison.Ordinal))),
						petFxIssues.FirstOrDefault((ValidationIssue x) => x.IsError)?.Message ?? "没有错误");
					string petFxSrc = CustomPowerGen.Source(petFxProbe, petFxPow, petFxProbe.CustomPowers.Count - 1);
					Check("V0.2.210：状态链先查那只伙伴（`XxxCmd.Get(base.Owner.Player)` —— 生成的方法收的是 Player）",
						petFxSrc.Contains("UiCheckPetFxCmd.Get(base.Owner.Player)", StringComparison.Ordinal),
						"查了伙伴");
					Check("V0.2.210：「给伙伴施加状态」生成 `PowerCmd.Apply<VulnerablePower>(choiceContext, __伙伴, 2m, base.Owner, null)`"
						+ "（施加者是 base.Owner；**不能**是 this —— 状态里 this 是 PowerModel，会 CS1503）",
						petFxSrc.Contains("PowerCmd.Apply<VulnerablePower>(choiceContext,", StringComparison.Ordinal)
						&& petFxSrc.Contains("2m, base.Owner, null)", StringComparison.Ordinal)
						&& !petFxSrc.Contains("2m, base.Owner, this)", StringComparison.Ordinal),
						"施加者 = base.Owner");
					Check("V0.2.210：治疗 / 加最大生命 / 失去生命都用状态链的写法人称（没有 base.Owner.Creature、没有 cardPlay.Target / FromCard、没有 base.DynamicVars）",
						petFxSrc.Contains("CreatureCmd.Heal(", StringComparison.Ordinal)
						&& petFxSrc.Contains("CreatureCmd.GainMaxHp(", StringComparison.Ordinal)
						&& petFxSrc.Contains("CreatureCmd.Damage(choiceContext,", StringComparison.Ordinal)
						&& !petFxSrc.Contains("base.Owner.Creature", StringComparison.Ordinal)
						&& !petFxSrc.Contains("cardPlay.Target", StringComparison.Ordinal)
						&& !petFxSrc.Contains("FromCard(", StringComparison.Ordinal)
						&& !petFxSrc.Contains("base.DynamicVars", StringComparison.Ordinal),
						"写法对");
					Check("V0.2.210：承伤开 / 关挂的是共用的守卫类（Apply + Remove）",
						petFxSrc.Contains("PowerCmd.Apply<", StringComparison.Ordinal)
						&& petFxSrc.Contains("ForgePetGuardianPower", StringComparison.Ordinal)
						&& petFxSrc.Contains("PowerCmd.Remove<", StringComparison.Ordinal),
						"守卫类");
					string petFxDesc = PowerTriggers.Plain(PowerTriggers.AutoDescription(petFxPow));
					Check("V0.2.210：状态描述里写中文（不印出 PetApplyPower 这种英文种类名）",
						petFxDesc.Contains("给伙伴施加 2 层", StringComparison.Ordinal)
						&& petFxDesc.Contains("治疗伙伴 5 点生命", StringComparison.Ordinal)
						&& !petFxDesc.Contains("PetApplyPower", StringComparison.Ordinal)
						&& !petFxDesc.Contains("PetHeal", StringComparison.Ordinal),
						petFxDesc.Replace("\n", " ⏎ "));

					// 「全部召唤物」：状态里也要逐只展开（以前 PetGen.Resolve("*") 返回 null → 生成一句
					// 「⚠ 没有可用的召唤物」然后什么都不做，而校验器明确允许这个组合 = 静默失效）
					var petAllProbe = ProfileFactory.Sample();
					petAllProbe.Summons.Clear();
					petAllProbe.Summons.Add(new SummonSpec { Enabled = true, Name = "自检甲", ClassName = "UiCheckPetAllA", Hp = 10 });
					petAllProbe.Summons.Add(new SummonSpec { Enabled = true, Name = "自检乙", ClassName = "UiCheckPetAllB", Hp = 10 });
					var petAllPow = new CustomPowerSpec { Name = "自检全部伙伴状态", ClassName = "UiCheckPetAllPower", Enabled = true };
					var petAllTrig = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Any" };
					petAllTrig.Effects.Add(new EffectSpec { Kind = "PetApplyPower", Amount = 1m, PowerId = "WeakPower", PetSummon = PetGen.AllId });
					petAllTrig.Effects.Add(new EffectSpec { Kind = "PetSacrifice", Amount = 2m, PetSacrificeGain = "Block", PetSacrificeFormula = "Fixed", PetSummon = PetGen.AllId });
					petAllPow.Triggers.Add(petAllTrig);
					petAllProbe.CustomPowers.Add(petAllPow);
					string petAllSrc = CustomPowerGen.Source(petAllProbe, petAllPow, petAllProbe.CustomPowers.Count - 1);
					Check("V0.2.210：状态里「全部召唤物」会**逐只展开**（两只各查一次），不再生成「没有可用的召唤物」",
						petAllSrc.Contains("UiCheckPetAllACmd.Get(base.Owner.Player)", StringComparison.Ordinal)
						&& petAllSrc.Contains("UiCheckPetAllBCmd.Get(base.Owner.Player)", StringComparison.Ordinal)
						&& !petAllSrc.Contains("没有可用的召唤物", StringComparison.Ordinal),
						"逐只展开");
					Check("V0.2.210：状态里的「牺牲伙伴」不再引用 base.DynamicVars / cardPlay.Target（状态类里根本没有这两样 → 会 CS0103）",
						!petAllSrc.Contains("base.DynamicVars", StringComparison.Ordinal)
						&& !petAllSrc.Contains("cardPlay.Target", StringComparison.Ordinal),
						"没引用");
					// 「下回合生效」+「全部召唤物」不能一起用 → 明确报错（延迟状态里只认一只伙伴）
					petAllTrig.Effects[0].NextTurn = true;
					Check("V0.2.210：「下回合生效」+「全部召唤物」→ 报错说清（不生成一段什么都不做的注释）",
						ProfileValidator.Validate(petAllProbe).Any((ValidationIssue x) => x.IsError
							&& x.Message.Contains("下回合生效", StringComparison.Ordinal)
							&& x.Message.Contains("全部召唤物", StringComparison.Ordinal)),
						ProfileValidator.Validate(petAllProbe).FirstOrDefault((ValidationIssue x) => x.IsError)?.Message ?? "(没报！)");
					petAllTrig.Effects[0].NextTurn = false;
					// 「下回合生效」单只伙伴：走卡牌链同一个入口（挂延迟状态 + CET 标记），不在这里直接施加
					petAllTrig.Effects[0].PetSummon = "UiCheckPetAllA";
					petAllTrig.Effects[0].NextTurn = true;
					string petDelayedSrc = CustomPowerGen.Source(petAllProbe, petAllPow, petAllProbe.CustomPowers.Count - 1);
					Check("V0.2.210：「下回合生效」的给伙伴施加状态走 EmitDelayedPowerApply（挂延迟状态 + 写 CET:NextTurn 标记，不再直接施加）",
						petDelayedSrc.Contains("CET:NextTurn=1", StringComparison.Ordinal)
						&& petDelayedSrc.Contains("ForgeDelayedPetApplyPower", StringComparison.Ordinal)
						&& !petDelayedSrc.Contains("PowerCmd.Apply<WeakPower>", StringComparison.Ordinal),
						"挂延迟状态");
					Check("V0.2.210：那只伙伴被编进延迟状态类名（两只伙伴各配一条同名状态时不会撞成同一个类 → CS0101）",
						petDelayedSrc.Contains("ForgeDelayedPetApplyPowerWeakPowerUiCheckPetAllA", StringComparison.Ordinal),
						"类名带伙伴");
				}
				List<string> cardKindItems = cardKindCombos.Count == 0
					? new List<string>()
					: (cardKindCombos[0].ItemsSource?.Cast<object>().OfType<EffectKindOption>().Select((EffectKindOption k) => k.Kind).ToList() ?? new List<string>());
				List<string> missingPetKinds = petKinds.Select(k => k.Kind).Where(id => !cardKindItems.Contains(id)).ToList();
				Check("「卡牌」页的效果种类下拉包含全部 12 个宠物效果（宠物效果就在卡牌页的效果种类下拉里）",
					cardKindCombos.Count > 0 && cardKindItems.Count == Kinds.Count && missingPetKinds.Count == 0,
					cardKindCombos.Count == 0 ? "没找到「效果种类」下拉"
						: $"下拉 {cardKindItems.Count} 项 / Kinds {Kinds.Count} 项 / 缺：" + (missingPetKinds.Count == 0 ? "无" : string.Join(" / ", missingPetKinds)));
				Check("「卡牌」页的效果种类下拉是**全量** Kinds（宠物效果不再被专属效果栏收窄/过滤）",
					cardKindCombos.Any((ComboBox c) => c.Items.Count == Kinds.Count && c.Items.Count > petKinds.Count),
					cardKindCombos.Count == 0 ? "没找到「效果种类」下拉" : string.Join(" / ", cardKindCombos.Select((ComboBox c) => c.Items.Count + " 项")));
				// 在卡牌页给一张牌选上宠物效果 →「召唤物（哪一只）」下拉必须出现，
				// 而且候选里就有上面那只召唤物、选中值确实读到效果上（PetSummon 用的是宠物类名这个稳定标识）。
				{
					string summonId = PetGen.ClassNameOf(Profile, summonProbe);
					CardSpec probePetFx = new CardSpec { Name = "自检宠物效果卡", ClassName = "UiCheckPetFxOnCardTab", Cost = 1, InCardPool = true };
					probePetFx.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy", AllowDuplicates = true });
					Profile.Cards.Add(probePetFx);
					CardList.SelectedItem = probePetFx;
					CardEffectList.SelectedIndex = 0;
					UpdateLayout();
					EffectSpec probeFx = probePetFx.Effects[0];
					probeFx.Kind = "PetHeal";
					probeFx.PetSummon = summonId;
					UpdateLayout();
					cardRoot = SelectTabRoot("卡牌");
					UpdateLayout();
					List<TextBlock> fxTexts = new List<TextBlock>();
					CollectTextBlocks(cardRoot, fxTexts);
					bool summonLabelVisible = fxTexts.Any((TextBlock t) => t.Text == "召唤物（哪一只）" && t.IsVisible);
					cardCombos = new List<ComboBox>();
					CollectCombos(cardRoot, cardCombos);
					ComboBox? petCombo = cardCombos.FirstOrDefault((ComboBox c) => c.SelectedValuePath == "Id" && BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "PetSummon");
					Check("在「卡牌」页选到宠物效果时「召唤物（哪一只）」下拉会出现（PetAction 驱动，宠物效果本来就能在卡牌页配）",
						probeFx.PetAction && summonLabelVisible && petCombo is not null && petCombo.IsVisible,
						$"PetAction={probeFx.PetAction} / 标签可见={summonLabelVisible} / 下拉={(petCombo is null ? "没找到" : (petCombo.IsVisible ? "可见" : "隐藏"))}");
					Check("「卡牌」页的「召唤物（哪一只）」下拉双向绑在效果的 PetSummon 上（值没被清成空）",
						petCombo is not null && petCombo.SelectedValue is string sv && sv == summonId && probeFx.PetSummon == summonId,
						petCombo is null ? "没找到下拉" : $"选中={petCombo.SelectedValue ?? "(空)"} / 效果上={probeFx.PetSummon ?? "(空)"} / 候选 {petCombo.Items.Count} 项");
					// 收尾：换回普通效果，确认它不再显示（免得留下一个「一直是宠物效果」的错觉）
					probeFx.Kind = "Damage";
					UpdateLayout();
					cardRoot = SelectTabRoot("卡牌");
					UpdateLayout();
					fxTexts = new List<TextBlock>();
					CollectTextBlocks(cardRoot, fxTexts);
					Check("把效果种类换回普通效果（造成伤害）后「召唤物（哪一只）」下拉收起（没有绑定残留）",
						!probeFx.PetAction && !fxTexts.Any((TextBlock t) => t.Text == "召唤物（哪一只）" && t.IsVisible),
						$"PetAction={probeFx.PetAction}");
					Profile.Cards.Remove(probePetFx);
					CardList.SelectedIndex = Profile.Cards.Count - 1;
					UpdateLayout();
				}
			}

			// ===== 「强化指定卡牌」的「强化什么」下拉 +「目标卡」标签（界面上真的能看到 / 双向绑得上）=====
			{
				CardSpec probeBoostFxCard = new CardSpec { Name = "自检强化界面", ClassName = "UiCheckBoostTab", Cost = 1, InCardPool = true };
				probeBoostFxCard.Effects.Add(new EffectSpec
				{
					Kind = "BoostCard", Amount = 2m, SpawnCardId = "SevenCrush", BoostStat = "Damage", TargetSide = "Self",
				});
				Profile.Cards.Add(probeBoostFxCard);
				CardList.SelectedItem = probeBoostFxCard;
				CardEffectList.SelectedIndex = 0;
				UpdateLayout();
				DependencyObject boostRoot = SelectTabRoot("卡牌");
				UpdateLayout();
				List<TextBlock> boostTexts = new List<TextBlock>();
				CollectTextBlocks(boostRoot, boostTexts);
				Check("「目标卡」那一行的标签写明了它也用于「强化」（生成 / 变化 / 强化用）",
					boostTexts.Any((TextBlock t) => t.Text == "目标卡（生成 / 变化 / 强化用）" && t.IsVisible), "标签在");
				Check("选到「强化指定卡牌」时「强化什么」那一行才会出现（IsBoostCard 驱动）",
					boostTexts.Any((TextBlock t) => t.Text == "强化什么" && t.IsVisible), "标签在");
				List<ComboBox> boostCombos = new List<ComboBox>();
				CollectCombos(boostRoot, boostCombos);
				ComboBox? statCombo = boostCombos.FirstOrDefault((ComboBox c) => c.SelectedValuePath == "Id"
					&& BindingOperations.GetBinding(c, Selector.SelectedValueProperty)?.Path?.Path == "BoostStat");
				Check("「强化什么」下拉绑在效果的 BoostStat 上（候选 = 伤害 / 格挡两项）",
					statCombo is not null && statCombo.IsVisible && statCombo.Items.Count == EffectCatalog.BoostStats.Count
					&& (statCombo.SelectedValue as string) == "Damage",
					statCombo is null ? "没找到下拉" : $"选中={statCombo.SelectedValue ?? "(空)"} / 候选 {statCombo.Items.Count} 项");
				if (statCombo is not null)
				{
					statCombo.SelectedValue = "Block";
					UpdateLayout();
					Check("下拉改成「格挡」后效果上跟着变（生成出来就是 ModifyBlockAdditive 那套）",
						probeBoostFxCard.Effects[0].BoostStat == "Block", probeBoostFxCard.Effects[0].BoostStatZh);
				}
				// 收尾：换回普通效果 → 「强化什么」那一行收起（没有绑定残留）
				probeBoostFxCard.Effects[0].Kind = "Damage";
				UpdateLayout();
				boostRoot = SelectTabRoot("卡牌");
				UpdateLayout();
				List<TextBlock> boostTexts2 = new List<TextBlock>();
				CollectTextBlocks(boostRoot, boostTexts2);
				Check("换回普通效果后「强化什么」那一行收起（不残留）",
					!boostTexts2.Any((TextBlock t) => t.Text == "强化什么" && t.IsVisible), "已收起");
				Profile.Cards.Remove(probeBoostFxCard);
				CardList.SelectedIndex = Profile.Cards.Count - 1;
				UpdateLayout();
			}
			// 勾选框 / 字段都要能双向编辑到「列表里选中的那一只」上
			bool oldEnabled2 = false, oldGuard = false;
			string oldName2 = "", oldCls2 = "";
			int oldHp2 = 0, oldDist = 0;
			try
			{
				SummonList.SelectedIndex = 0;
				UpdateLayout();
				var probe = SummonList.SelectedItem as SummonSpec;
				// 示例配置本身不带召唤物（上面那条已经验过 0 条），这一条是本节自己加进去的 ——
				// 断言它真的能选中、能读出详情（字段 / 勾选框都挂在「选中的那只」上）。
				Check("召唤物列表里能选到前面加的那一只（选中后详情字段才有数据源）",
					ReferenceEquals(probe, summonProbe), probe?.Display ?? "(空列表)");
				if (probe is not null)
				{
					oldEnabled2 = probe.Enabled; oldGuard = probe.TakesDamageForOwner;
					oldName2 = probe.Name; oldCls2 = probe.ClassName;
					oldHp2 = probe.Hp; oldDist = probe.StandDistance;
					probe.Enabled = true;
					probe.Name = "测试伙伴";
					probe.Hp = 12;
					probe.StandDistance = 130;
					probe.ClassName = "";
					UpdateLayout();
					Check("类名留空时按位置自动推（第 1 只 = <角色类名>Pet）",
						PetGen.ClassNameOf(Profile, probe) == Profile.CharacterClass + "Pet"
						&& PetGen.DisplayNameOf(probe, PetGen.ClassNameOf(Profile, probe)) == "测试伙伴"
						&& PetGen.HpOf(probe) == 12 && PetGen.StandDistanceOf(probe) == 130,
						$"{PetGen.ClassNameOf(Profile, probe)} / {PetGen.HpOf(probe)} / {PetGen.StandDistanceOf(probe)}");
					// V0.2.198（用户实测报的「触发召唤时好像会直接把召唤物回满血」）：
					// 已经在场的召唤物**再召唤一次**只该加最大生命（本体 GainMaxHp 本身会把新加的那部分补上），
					// 不许再补一句 Heal(MaxHp − CurrentHp) 把它整个奶满（那等于把之前挨的打一笔勾销）。
					{
						string petSrc = PetGen.Source(Profile);
						Check("召唤物：再召唤（已经在场）只加最大生命 —— 不会把召唤物直接回满血",
							petSrc.Contains("await CreatureCmd.GainMaxHp(alive, hp);")
							&& !petSrc.Contains("alive.MaxHp - alive.CurrentHp"),
							petSrc.Contains("alive.MaxHp - alive.CurrentHp") ? "还在补满（错）" : "只加最大生命（对）");
						Check("召唤物：新召一只仍然是满血（SetMaxHp + Heal 到上限，不然攻击会因为 0 血静默早退）",
							petSrc.Contains("await CreatureCmd.SetMaxHp(") && petSrc.Contains("hp - ", StringComparison.Ordinal),
							"满血新召");
						// 没上传图片也必须写一个占位场景：本体按约定找 <entry>.tscn，找不到时视觉加载会抛
						// NullReferenceException（用户日志里就是这个），宠物连登记都过不去 → 每次触发召唤都新建一只满血的。
						string petArtDir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "forge_petcheck_" + Guid.NewGuid().ToString("N"));
						try
						{
							System.IO.Directory.CreateDirectory(petArtDir);
							PetGen.GenerateVisuals(Profile, petArtDir, null);
							var sc = System.IO.Path.Combine(petArtDir,
								PetGen.SceneRelPath(PetGen.DefOf(Profile, probe)).Replace('/', System.IO.Path.DirectorySeparatorChar));
							if (!System.IO.File.Exists(sc)) sc = null;
							Check("召唤物：没上传图片也会生成占位场景（贴本体 error.png）—— 不然加载视觉会抛异常、宠物登记不上",
								sc is not null && System.IO.File.ReadAllText(sc).Contains("images/monsters/error.png"),
								sc is null ? "没生成（错）" : System.IO.Path.GetFileName(sc));
							Check("召唤物：宠物类永远指着这个场景（不管有没有图）",
								petSrc.Contains($"VisualsPath => \"res://{PetGen.SceneRelPath(PetGen.DefOf(Profile, probe))}\""), "指着");
						}
						finally
						{
							try { System.IO.Directory.Delete(petArtDir, true); } catch { }
						}
					}
					// 「哪一只」下拉的候选 = 第一条「全部召唤物」+ 各只已启用的召唤物
					RaisePetSummonChoices();
					Check("「召唤物（哪一只）」下拉的候选 = 「全部召唤物」+ 各只已启用的召唤物",
						PetSummonsCard.Count == PetGen.Enabled(Profile).Count + 1
						&& PetSummonsCard[0].Id == PetGen.AllId
						&& PetSummonsCard.Skip(1).All((PetGen.PetChoice c) => c.Id.Length > 0),
						string.Join(" / ", PetSummonsCard.Select((PetGen.PetChoice c) => c.Display)));
					Check("「全部召唤物」那一项的文案看得懂（★ 全部召唤物…）",
						PetGen.IsAll(PetGen.AllId) && PetGen.Choices(Profile)[0].Display.StartsWith("★ 全部召唤物"),
						PetGen.Choices(Profile)[0].Display);
					Check("「全部召唤物」不是真的宠物标识（Resolve 认不出来、ResolveMany 返回全部）",
						PetGen.Resolve(Profile, PetGen.AllId) is null
						&& PetGen.ResolveMany(Profile, PetGen.AllId).Count == PetGen.Enabled(Profile).Count,
						$"Resolve=null / ResolveMany={PetGen.ResolveMany(Profile, PetGen.AllId).Count} 只");
					// 【对象】选「指定召唤物」→ 多出「召唤物名称」一栏，且生成代码按名称取那一只（需求）
					{
						var pjCard = new CardSpec { Name = "自检指定召唤物", ClassName = "UiCheckChosenSummon", CardType = "Attack", Cost = 0, IsForged = true };
						var pjTrig = new ForgeNodeSpec { Kind = "Trigger" };
						pjTrig.SetField("Timing", ForgeTimings.CardPlayed);
						var pjUnit = new ForgeNodeSpec { Kind = "Unit" };
						var pjEff = new ForgeNodeSpec { Kind = "Effect" };
						pjEff.SetField("Effect", "Damage");
						pjEff.SetField("Amount", "5");
						pjCard.ForgeGraph = new ForgeGraphSpec { Nodes = { pjTrig, pjUnit, pjEff } };
						pjCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = pjTrig.Id, To = pjEff.Id, FromPort = 0, ToPort = 0 });
						pjCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = pjUnit.Id, To = pjEff.Id, FromPort = 0, ToPort = 2 });
						string petCls = PetGen.ClassNameOf(Profile, probe);
						// 生成端：数值口径用「伤害」，但宠物不是可打目标 —— 这里直接看【对象】那一块的解析结果
						pjUnit.SetField("Pick", "RandomSummon");
						string pickRandom = ForgeGraphGen.UnitExprForCheck(Profile, pjCard.ForgeGraph, pjUnit);
						pjUnit.SetField("Pick", "ChosenSummon");
						pjUnit.SetField("SummonId", petCls);
						string pickChosen = ForgeGraphGen.UnitExprForCheck(Profile, pjCard.ForgeGraph, pjUnit);
						Check("【对象】「指定召唤物」按选中的名称取那一只（不再和「随机召唤物」一样都是第一只）",
							pickChosen.Contains($"NamedSummon(__fgPlayer, \"{petCls}\")"),
							$"选中 {petCls} → {pickChosen}");
						Check("「随机召唤物」还是第一只（两种选项确实不一样）",
							pickRandom.Contains("FirstSummon(__fgPlayer)"), $"随机 → {pickRandom}");
						Check("「召唤物名称」那一栏只在选了「指定召唤物」时才出现",
							ForgeCanvas.UnitSummonFieldVisibleForCheck(pjUnit, "RandomSummon") == false
							&& ForgeCanvas.UnitSummonFieldVisibleForCheck(pjUnit, "ChosenSummon") == true,
							"随机时隐藏 / 指定时显示");
						// ===== 锻造图里【造成伤害」 【对象：全体敌人」 「命中次数 N」 ====
						// 用户实测报的 bug：命中次数填 4 时生成了「每个敌人各打 4 下」，
						// 而他要的是「一次打全体、命中 4 次」。根因：【全体敌人】被当成「逐个动手」处理。"
						{
							string GraphDamage(CharacterProfile prof, string unitPick, int hits, string owner)
							{
								var hc = new CardSpec { Name = "命中次数自检", ClassName = "UiCheckHits" + owner, CardType = "Attack", Rarity = "Common" };
								hc.IsForged = true;
								var hTrig = new ForgeNodeSpec { Kind = "Trigger" };
								hTrig.SetField("Timing", ForgeTimings.CardPlayed);
								var hEff = new ForgeNodeSpec { Kind = "Effect" };
								hEff.SetField("Effect", "Damage");
								hEff.SetField("Amount", "6");
								hEff.SetField("Hits", hits.ToString());
								var hUnit = new ForgeNodeSpec { Kind = "Unit" };
								hUnit.SetField("Pick", unitPick);
								hc.ForgeGraph = new ForgeGraphSpec { Nodes = { hTrig, hEff, hUnit } };
								hc.ForgeGraph.Links.Add(new ForgeLinkSpec { From = hTrig.Id, To = hEff.Id, FromPort = 0, ToPort = 0 });
								hc.ForgeGraph.Links.Add(new ForgeLinkSpec { From = hUnit.Id, To = hEff.Id, FromPort = 0, ToPort = 2 });
								prof.Cards.Add(hc);
								return CSharpCodeGen.CardSource(prof, hc, 0);
							}

							CharacterProfile hitProf = ProfileFactory.Sample();
							hitProf.Cards.Clear();
							string gAll4 = GraphDamage(hitProf, "AllEnemies", 4, "All4");
							string gAll1 = GraphDamage(hitProf, "AllEnemies", 1, "All1");
							string gRand4 = GraphDamage(hitProf, "RandomEnemy", 4, "Rand4");
							Check("图里【全体敌人】+伤害走**群体版本的一次性命令**（TargetingAllOpponents），不再逐只循环",
								gAll4.Contains("TargetingAllOpponents") && !gAll4.Contains("foreach (Creature __fgFoe"), "群体命令");
							Check("（用户报的 bug）图里【全体敌人】+命中次数 4 = **一次打全体、命中 4 次**（不是每个敌人各打 4 下）",
								gAll4.Contains(".WithHitCount(4)") && !gAll4.Contains("Targeting(__fgFoe)"), "命中 4 次");
							Check("图里【全体敌人】+命中次数 1 不写 WithHitCount（默认一下，和以前一致）",
								!gAll1.Contains("WithHitCount"), "不写");
							// V0.2.222（用户报的「对群数和命中次数在锻造里写在一起、随机多段异常」）：
							// 旧断言锁的是**旧行为**（随机敌人 = 对全体 foreach + WithHitCount = 每个敌人各挨 4 下），
							// 那个行为本身就是 bug；现在和「卡牌」页同一口径 = 本体的 TargetingRandomOpponents
							//（每一下随机挑一个敌人）× 命中次数。
							Check("图里【随机敌人】+命中次数 4 = **随机打 4 下**（TargetingRandomOpponents + WithHitCount(4)），"
								+ "不是「每个敌人各挨 4 下」",
								gRand4.Contains("TargetingRandomOpponents")
								&& gRand4.Contains(".WithHitCount(4)")
								&& !gRand4.Contains("foreach (Creature __fgFoe"), "随机多段");
						}

						// 【效果】（V0.2.129）：现在和「卡牌」页**同一份判据**（同一条 EffectSpec 的 Show* 属性）——
						// 所以「每一条效果的选择出现的可填写项」两边一致：按种类 / 作用对象出现的那一整套都跟着走。
						{
							var gate = new ForgeNodeSpec { Kind = "Effect" };
							var gateTrig = new ForgeNodeSpec { Kind = "Trigger" };
							gateTrig.SetField("Timing", ForgeTimings.CardPlayed);
							var gateGraph = new ForgeGraphSpec { Nodes = { gateTrig, gate } };
							gateGraph.Links.Add(new ForgeLinkSpec { From = gateTrig.Id, To = gate.Id, FromPort = 0, ToPort = 0 });
							var gates = new (string Kind, string Field, bool Want)[]
							{
								// 效果种类那一行永远在；「数值」在锻造链上换成能写公式的那个框（卡牌那种独立公式框不摆）
								("Damage", "Effect", true),
								("Damage", "Amount", true),
								("Damage", "AmountFormula", false),
								("Damage", "Times", true),
								("Damage", "Hits", true),
								("Damage", "Chance", true),
								("Damage", "TargetSide", true),
								// 按种类出现的那几栏（判据与卡牌页同一份）
								("Damage", "SpawnPick", false),
								("GenerateCard", "SpawnPick", true),
								("GenerateCard", "RangeFilter", true),
								("GenerateCard", "SpawnTo", true),
								("GainPotion", "PotionPick", true),
								("GainPotion", "PotionId", true),
								("Damage", "PotionId", false),
								("ExhaustCard", "SelectPile", true),
								("ExhaustCard", "CountMode", true),
								("Damage", "SelectPile", false),
								("CopyCard", "Copies", true),
								("Damage", "Copies", false),
								("TempPower", "TempPowerReverse", true),
								("Damage", "TempPowerReverse", false),
								("Block", "NextTurn", true),
								// V0.2.133：「下回合生效」补齐到全部效果（除语义上做不了的那 8 种），
								// 所以「造成伤害」这一类也**显示**勾选框了（以前只给 12 种显示）
								("Damage", "NextTurn", true),
								// 语义上做不了延迟的（刮削 / 结束回合 / 费用变 0…）仍然**不显示**
								("ScrapeDraw", "NextTurn", false),
								("EndTurn", "NextTurn", false),
								("PlaceCard", "PlaceTo", true),
								// 卡牌那种独立「数值（公式）」框：锻造链一律不摆（上面那个「数值」框就能写公式）
								("Block", "AmountFormula", false),
							};
							var wrongGates = gates
								.Where(x => ForgeCanvas.EffectFieldVisibleForCheck(gate, x.Kind, x.Field) != x.Want)
								.Select(x => $"{x.Kind}.{x.Field} 应{(x.Want ? "显示" : "隐藏")}")
								.ToList();
							Check("【效果】模块的栏位显隐 = 卡牌页同一份判据（按效果种类 / 作用对象出现的那一套都跟着走）",
								wrongGates.Count == 0,
								wrongGates.Count == 0 ? "都对" : string.Join(" / ", wrongGates));
						}
						Profile.Cards.Remove(pjCard);
					}
					// 停用后候选里就没有它了
					probe.Enabled = false;					RaisePetSummonChoices();
					Check("把召唤物停用后「哪一只」下拉里就看不到它了",
						!PetSummonsCard.Any((PetGen.PetChoice c) => c.Id == PetGen.ClassNameOf(Profile, probe)),
						string.Join(" / ", PetSummonsCard.Select((PetGen.PetChoice c) => c.Display)));
					// 效果引用了一只「停用的」召唤物 → 校验器要报错拦住
					CardSpec petOffCard = new CardSpec { Name = "激活检查", ClassName = "UiCheckPetOff", Cost = 1 };
					petOffCard.Effects.Clear();
					petOffCard.Effects.Add(new EffectSpec
					{
						Kind = "SummonPet", Amount = 0m, TargetSide = "Self",
						PetSummon = PetGen.ClassNameOf(Profile, probe),
					});
					string disabledCard = CSharpCodeGen.CardSource(Profile, petOffCard, 0);
					// 生成器**故意**不给「找不到的召唤物」写调用（否则会引用一个不存在的宠物类 → CS0103），
					// 只留一行说明注释；拦住生成的是校验器。所以这里断言「不抛异常 + 留下说得清的说明」，
					// 而不是「照样写出调用」（那反而会生成编译不过的代码）。
					Check("即使召唤物被停用，卡牌代码也照常生成（不抛异常，留一行「没有可用的召唤物」说明；拦住生成的是校验器）",
						disabledCard.Contains("没有可用的召唤物") && disabledCard.Contains("SevenPet")
						&& !disabledCard.Contains("SevenPetCmd.Summon("),
						disabledCard.Contains("没有可用的召唤物") ? "有说明、没写调用" : "说明缺失");
					Profile.Cards.Add(petOffCard);
					var petOffIssues = ProfileValidator.Validate(Profile);
					string petOffErrors = string.Join(" | ", petOffIssues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message));
					Check("引用了「停用的召唤物」时校验器会报错拦住（否则生成的牌会引用不存在的宠物类 → CS0103）",
						petOffIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("已经被停用")),
						petOffErrors.Length > 0 ? petOffErrors : "(没有错误)");
					Profile.Cards.Remove(petOffCard);
				}
			}
			finally
			{
				var restore = SummonList.SelectedItem as SummonSpec;
				if (restore is not null)
				{
					restore.Enabled = oldEnabled2; restore.TakesDamageForOwner = oldGuard;
					restore.Name = oldName2; restore.ClassName = oldCls2;
					restore.Hp = oldHp2; restore.StandDistance = oldDist;
				}
				// 自检自己加的那一只读完就撤掉：后面的用例都按「示例配置 0 只召唤物」来验
				Profile.Summons.Remove(summonProbe);
				RaisePetSummonChoices();
			}
		}

		// ===== 召唤物：端到端（两只同时在场 → 生成 → 产物 → 回读 → 校验拦截）=====
		string petRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_pet_" + Guid.NewGuid().ToString("N").Substring(0, 8));
		try
		{
			CharacterProfile petSrc = ProfileFactory.Sample();
			// 「替主人承伤」守卫 Power 的类名带角色类名前缀（<角色>ForgePetGuardianPower）—— 断言按它算
			string guardName = Naming.From(petSrc).GuardianPowerClass;
			petSrc.Paths.OutputDir = petRoot;
			// 生成要用解包工程（占位美术 / 场景），和上面「从工程恢复」那段一样
			petSrc.Paths.VanillaProject = Profile.Paths.VanillaProject;
			petSrc.Paths.GameDataDir = Profile.Paths.GameDataDir;
			petSrc.SaveName = "召唤物自检";
			// 两只召唤物都勾「替主人承伤」（现在允许，由共用的守卫类自己仲裁：列表里第一只活着的承担），
			// 且两只的站位距离不同
			petSrc.Summons.Clear();
			petSrc.Summons.Add(new SummonSpec
			{
				Enabled = true, ClassName = "UiCheckPet", Name = "小石头", Hp = 9,
				Image = null, TakesDamageForOwner = true, StandDistance = 140,
			});
			petSrc.Summons.Add(new SummonSpec
			{
				Enabled = true, ClassName = "UiCheckPet2", Name = "小铁块", Hp = 15,
				Image = null, TakesDamageForOwner = true, StandDistance = 90,
			});
			List<CardSpec> petOwn = petSrc.Cards.Where((CardSpec c) => !c.IsVanillaCard).ToList();
			CardSpec petSummonCard = new CardSpec { Name = "召唤小石头", ClassName = "UiCheckPetSummon", CardType = "Skill", Cost = 1, InCardPool = true };
			petSummonCard.Effects.Clear();
			petSummonCard.Effects.Add(new EffectSpec
			{
				Kind = "SummonPet", Amount = 0m, TargetSide = "Self", PetSummon = "UiCheckPet",
			});   // 0 = 用配置的 9 点生命
			petSrc.Cards.Add(petSummonCard);
			CardSpec petAttackCard = new CardSpec { Name = "小石头撞击", ClassName = "UiCheckPetAttack", CardType = "Attack", Cost = 1, InCardPool = true };
			petAttackCard.Effects.Clear();
			petAttackCard.Effects.Add(new EffectSpec
			{
				Kind = "PetAttack", Amount = 7m, UpgradeAmount = 3m, TargetSide = "Enemy", PetSummon = "UiCheckPet",
			});
			petSrc.Cards.Add(petAttackCard);
			// 第二只也有自己的攻击卡：验证同一张牌 / 不同牌能分别指向不同的召唤物
			CardSpec petAttackCard2 = new CardSpec { Name = "小铁块撞击", ClassName = "UiCheckPetAttack2", CardType = "Attack", Cost = 1, InCardPool = true };
			petAttackCard2.Effects.Clear();
			petAttackCard2.Effects.Add(new EffectSpec
			{
				Kind = "PetAttack", Amount = 5m, TargetSide = "AllEnemies", PetSummon = "UiCheckPet2",
			});
			petSrc.Cards.Add(petAttackCard2);
			// 遗物「战斗开始时召唤」= 本体 Byrdpip 的写法
			RelicSpec petRelic = new RelicSpec { Name = "会召唤的遗物", ClassName = "UiCheckPetRelic", Trigger = "CombatStart", IsStartingRelic = true };
			petRelic.Effects.Clear();
			petRelic.Effects.Add(new EffectSpec
			{
				Kind = "SummonPet", Amount = 12m, TargetSide = "Self", PetSummon = "UiCheckPet2",
			});
			petSrc.Relics.Add(petRelic);

			var petGen = ModGenerator.Generate(petSrc);
			Check("（准备）带两只召唤物的配置能生成工程", petGen.Success && Directory.Exists(petGen.ProjectRoot),
				string.Join(" | ", petGen.Issues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message)));

			// ① cs/Pet.cs：两只宠物类 + 两个命令助手 + 一个守卫 Power
			string petCsPath = Path.Combine(petGen.ProjectRoot, "cs", "Pet.cs");
			Check("召唤物：生成了 cs/Pet.cs", File.Exists(petCsPath), petCsPath);
			string petCs = File.Exists(petCsPath) ? File.ReadAllText(petCsPath, Encoding.UTF8) : "";
			Check("召唤物：两只都生在同一个 cs/Pet.cs 里（各一个 MonsterModel 子类，本体靠扫描子类自动注册）",
				petCs.Contains("public sealed class UiCheckPet : MonsterModel") && petCs.Contains("public sealed class UiCheckPet2 : MonsterModel"),
				"两个宠物类");
			Check("召唤物：第二只也有自己的命令助手（PlayerCmd.AddPet<UiCheckPet2>）",
				petCs.Contains("PlayerCmd.AddPet<UiCheckPet2>(player)"), "用了通用 API");
			Check("召唤物：宠物类写了空操作自循环的 NOTHING_MOVE（宠物没有自主回合，照抄本体 Osty）",
				petCs.Contains("NOTHING_MOVE"), "有 NOTHING_MOVE");
			Check("召唤物：召唤命令里有 SetMaxHp（本体造宠物时给的是初始生命随机值）",
				petCs.Contains("CreatureCmd.SetMaxHp(__uiCheckPet, hp)"), "有 SetMaxHp");
			// V0.2.198（用户实测「召唤时召唤物回满血」的根因之一）：以前没图就**不写场景、不 override**，
			// 指望本体按约定回退 fallback —— 可那条路在真机上会抛 NullReferenceException（用户日志里就有），
			// 宠物连登记都过不去（于是每次触发召唤都新建一只满血的新宠物）。现在没图也写占位场景并指过去。
			Check("召唤物：没上传图片也 override VisualsPath（指到生成出来的占位场景，不再靠本体回退）",
				petCs.Contains("VisualsPath => \"res://scenes/creature_visuals/"), "指着占位场景");
			Check("召唤物：两只的生命各自独立（9 / 15）",
				petCs.Contains("private const int BaseHp = 9;") && petCs.Contains("private const int BaseHp = 15;"), "BaseHp 9 / 15");

			// ①-a 站位 / 血条（bug：多只宠物时血条只剩最后一只；本体摆位会把全体叠回主人身上）
			Check("站位：宠物类覆写了 AfterCreatureAddedToCombat（本体摆位在这个钩子之前跑，改完不会被抢回去）",
				petCs.Contains("public override Task AfterCreatureAddedToCombat(Creature creature)")
				&& petCs.Contains("ForgePetLayout.RelayoutAll(creature.PetOwner);"), "有站位钩子");
			Check("站位：**同一主人的任何伙伴进场**都把全体重排一遍（不再只管自己那一只 —— 本体 AddCreature 会把该玩家所有宠物叠回主人身上）",
				petCs.Contains("if (creature.PetOwner is not null && ReferenceEquals(creature.PetOwner, base.Creature.PetOwner))")
				&& !petCs.Contains("if (creature != base.Creature) return Task.CompletedTask;"), "判的是「同一主人」");
			Check("站位：站位距离是**每只自己的配置值**（140 / 90），不是全局写死",
				petCs.Contains("private const float StandDistance = 140f;") && petCs.Contains("private const float StandDistance = 90f;")
				&& petCs.Contains("[typeof(UiCheckPet)] = 140f,") && petCs.Contains("[typeof(UiCheckPet2)] = 90f,"),
				"两只各自的距离（常量 + ForgePetLayout._dist）");
			Check("站位：算上了半个包围盒宽（不然有一半身子压在主人身上）",
				petCs.Contains("node.Visuals.Bounds.Size.X * 0.5f"), "有半宽");
			Check("站位：本体摆位用的那个「主人 X − 20」偏移没有出现在摆位代码里（20 只作为 _dist 查不到时的兜底）",
				!petCs.Contains("- 20f"), "干净");

			// ①-b bug②：血条（覆写 IsHealthBarVisible + 召唤后 ForgePetLayout.RelayoutAll 重开全体血条）
			Check("bug②血条：宠物类覆写了 IsHealthBarVisible（照本体 Osty）",
				petCs.Contains("public override bool IsHealthBarVisible => base.Creature.IsAlive;"), "有覆写");
			Check("bug②血条：召唤后调 ForgePetLayout.RelayoutAll 把**全体**血条重新开回来（本体 AddCreature 会把该玩家所有宠物的交互关掉 → 血条只剩最后一只）",
				petCs.Contains("internal static class ForgePetLayout")
				&& petCs.Contains("room.SetCreatureIsInteractable(pet, on: true);"), "有共用助手 + 重开血条");

			// ①-c 可选④：替主人承伤（共用守卫 Power，照抄 DieForYouPower + 自己仲裁）
			Check("替主人承伤：勾了几只都只生成**一个共用**的守卫 Power 类（不是每只一个 —— Creature.HasPower<T>() 只认同一类型，仲裁要跨宠物认人）",
				petCs.Contains($"public sealed class {guardName} : PowerModel")
				&& !petCs.Contains("public sealed class ForgePetGuardianUiCheckPet")
				&& !petCs.Contains("public sealed class ForgePetGuardianUiCheckPet2")
				&& petCs.Split($"public sealed class {guardName} : PowerModel").Length - 1 == 1, "共用一个守卫类");
			Check("替主人承伤：守卫里有我们自己写的仲裁（宠物列表里第一只活着且挂了守卫的才承担，它死后下一只自动接手）",
				petCs.Contains($"FirstOrDefault(p => p.IsAlive && p.HasPower<{guardName}>())")
				&& petCs.Contains("if (current is not null && !ReferenceEquals(current, base.Owner)) return target;"), "有仲裁");
			Check("替主人承伤：两只勾了的召唤物，召唤命令里都挂同一个守卫",
				petCs.Contains($"if (!__uiCheckPet.HasPower<{guardName}>())")
				&& petCs.Contains($"await PowerCmd.Apply<{guardName}>(choiceContext, __uiCheckPet, 1m, null, null);")
				&& petCs.Contains($"if (!__uiCheckPet2.HasPower<{guardName}>())")
				&& petCs.Contains($"await PowerCmd.Apply<{guardName}>(choiceContext, __uiCheckPet2, 1m, null, null);"), "两只都挂了");
			Check("替主人承伤：守卫只吸「可格挡的攻击伤害」（中毒 / 失去生命照旧打在主人身上）",
				petCs.Contains("if (!props.IsPoweredAttack()) return target;")
				&& petCs.Contains("public override Creature ModifyUnblockedDamageTarget(Creature target, decimal amount, ValueProp props, Creature? dealer)"), "有判定");
			Check("替主人承伤：目标不是自己主人就放过、自己死了就放过",
				petCs.Contains("if (target != base.Owner.PetOwner?.Creature) return target;")
				&& petCs.Contains("if (base.Owner.IsDead) return target;"), "有守卫");
			Check("替主人承伤：关掉状态图标（IsVisibleInternal => false）—— 不关的话本体要去 powers 表查 title/description，模组没这张表 → 名字显示成原始键名 + 图标退回 missing_power.png",
				petCs.Contains("protected override bool IsVisibleInternal => false;"), "有覆写");
			Check("替主人承伤：**不**覆写 ShouldCreatureBeRemovedFromCombatAfterDeath / ShouldPowerBeRemovedAfterOwnerDeath（那两个是 Osty「留尸等复活」的语义：会让尸体不消失、每次召唤都新建一只、越堆越多）",
				!petCs.Contains("ShouldCreatureBeRemovedFromCombatAfterDeath")
				&& !petCs.Contains("ShouldPowerBeRemovedAfterOwnerDeath"), "两个都不在生成结果里");
			Check("替主人承伤：保留 ShouldAllowHitting（自己死了以后不再接受攻击，本体 DieForYouPower 的写法）",
				petCs.Contains("public override bool ShouldAllowHitting(Creature creature)"), "还在");

			// ①-f 回归：只用了「伙伴替主人承伤（开 / 关）」效果、但那只召唤物**没勾**勾选框
			// （用户实测：生成出来的卡牌引用了 <角色>ForgePetGuardianPower，类却没生成 → CS0246 构建失败）
			{
				CharacterProfile guardOnly = ProfileFactory.Sample();
				guardOnly.Summons.Clear();
				guardOnly.Summons.Add(new SummonSpec { Enabled = true, ClassName = "UiCheckGuardPet", Name = "自检守卫宠", Hp = 20, TakesDamageForOwner = false });
				var guardCard = new CardSpec { Name = "自检开启承伤", ClassName = "UiCheckGuardOn", Cost = 1, InCardPool = true };
				guardCard.Effects.Add(new EffectSpec { Kind = "PetGuardOn", PetSummon = "UiCheckGuardPet" });
				guardCard.Effects.Add(new EffectSpec { Kind = "PetGuardOff", PetSummon = "UiCheckGuardPet" });
				guardOnly.Cards.Add(guardCard);
				string guardPetCs = PetGen.Source(guardOnly);
				string guardCardCs = CSharpCodeGen.CardSource(guardOnly, guardCard, 0);
				string guardCls = Naming.From(guardOnly).GuardianPowerClass;
				Check("只用了「替主人承伤（开 / 关）」效果、勾选框没勾时，守卫 Power 类照样生成（否则卡牌里那句 Apply<T> 会 CS0246 编译不过）",
					guardCardCs.Contains($"PowerCmd.Apply<{guardCls}>(") && guardPetCs.Contains($"public sealed class {guardCls} : PowerModel"),
					guardCardCs.Contains($"PowerCmd.Apply<{guardCls}>(") ? (guardPetCs.Contains(guardCls) ? "类也生成了" : "类没生成 ← 就是那个 CS0246") : "卡牌没引用");
				Check("没勾勾选框时守卫的说明里写清「由效果在战斗中开启」（不写「谁」会是一句空话）",
					guardPetCs.Contains("会在战斗中开启"), "说明在");
				Check("一只都没用守卫时**不**生成守卫类（不给模组塞没用的类）",
					!PetGen.Source(ProfileFactory.Sample()).Contains(Naming.From(ProfileFactory.Sample()).GuardianPowerClass), "没生成");
				Check("UsesGuardianEffect 认得出卡牌 / 遗物 / 药水 / 自定义状态四条路上的守卫效果",
					PetGen.UsesGuardianEffect(guardOnly)
					&& PetGen.UsesGuardianEffect(new CharacterProfile { Relics = { new RelicSpec { Name = "r", Trigger = "PlayerTurnStart", Effects = { new EffectSpec { Kind = "PetGuardOn" } } } } })
					&& PetGen.UsesGuardianEffect(new CharacterProfile { Potions = { new PotionSpec { Name = "p", Effects = { new EffectSpec { Kind = "PetGuardOff" } } } } })
					&& PetGen.UsesGuardianEffect(new CharacterProfile { CustomPowers = { new CustomPowerSpec { Name = "cp", Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "PetGuardOn" } } } } } } })
					&& !PetGen.UsesGuardianEffect(ProfileFactory.Sample()), "四条路都认");
				Check("勾选框没勾 + 用了守卫效果 → 校验给一句提示（说清「效果照样有效，只是开场不自动承伤」）",
					ProfileValidator.Validate(guardOnly).Any(i => i.Message.Contains("效果照样有效")), "有提示");

				// ①-g 回归：卡牌**打不出去**（用户实测：「召唤小八替你挨打」在战斗里是红的、点不动）
				// 根因：那张牌有「替主人承伤（开）」效果，而 NeedsExistingPet 把它也算成「要已有伙伴」，
				// 于是生成了 IsPlayable => xiaobaCmd.Get(base.Owner) != null —— 而小八正是这张牌负责召的，
				// 第一次打出时它必然不存在 → 永远打不出去。
				{
					CharacterProfile canPlay = ProfileFactory.Sample();
					canPlay.Summons.Clear();
					canPlay.Summons.Add(new SummonSpec { Enabled = true, ClassName = "UiCheckPlayPet", Name = "自检出场宠", Hp = 30, TakesDamageForOwner = false });
					var summonGuard = new CardSpec { Name = "自检召唤并承伤", ClassName = "UiCheckSummonGuard", Cost = 1, InCardPool = true };
					summonGuard.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, PetSummon = "UiCheckPlayPet" });
					summonGuard.Effects.Add(new EffectSpec { Kind = "PetGuardOn", PetSummon = "UiCheckPlayPet" });
					canPlay.Cards.Add(summonGuard);
					string sg = CSharpCodeGen.CardSource(canPlay, summonGuard, 0);
					Check("「召唤伙伴 + 替主人承伤」的牌**不会**被「必须先有伙伴」卡住打不出去（用户实测那张就是这个问题）",
						!sg.Contains("protected override bool IsPlayable")
						&& !sg.Contains("ShouldGlowRedInternal"), sg.Contains("IsPlayable") ? "还有 IsPlayable 判定" : "没有判定");
					Check("召唤命令返回的那只写回 OnPlay 开头的查询变量（不然同一张牌后面的承伤 / 攻击第一次会被整条跳过）",
						sg.Contains("__uiCheckPlayPet = await UiCheckPlayPetCmd.Summon(choiceContext, base.Owner,"), "写回了");
					// 同一张牌「召唤 + 伙伴攻击」也是同一个坑：不能因为「要有伙伴才能打」而永远打不出去
					var summonAttack = new CardSpec { Name = "自检召唤并攻击", ClassName = "UiCheckSummonAttack", Cost = 1, InCardPool = true };
					summonAttack.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, PetSummon = "UiCheckPlayPet" });
					summonAttack.Effects.Add(new EffectSpec { Kind = "PetAttack", Amount = 6m, PetSummon = "UiCheckPlayPet", TargetSide = "Enemy" });
					canPlay.Cards.Add(summonAttack);
					string sa = CSharpCodeGen.CardSource(canPlay, summonAttack, 0);
					Check("「召唤伙伴 + 伙伴攻击」的牌同理（这张牌自己会召，就不该要求「已经召出来」）",
						!sa.Contains("protected override bool IsPlayable"), sa.Contains("IsPlayable") ? "还有 IsPlayable 判定" : "没有判定");
					Check("但如果这张牌**不**负责召唤那只伙伴，「必须先有它」的判定照旧保留（本体 Osty 牌那套）",
						CSharpCodeGen.CardSource(canPlay, new CardSpec
						{
							Name = "自检只攻击", ClassName = "UiCheckAttackOnly", Cost = 1,
							Effects = { new EffectSpec { Kind = "PetAttack", Amount = 5m, PetSummon = "UiCheckPlayPet", TargetSide = "Enemy" } },
						}, 0).Contains("protected override bool IsPlayable => (UiCheckPlayPetCmd.Get(base.Owner) != null);"), "保留了");
				}
			}

			// ①-e bug④/⑤：死亡语义 + 召唤命令（Get 判活 + 每个分支都重排全体）
			Check("召唤命令：Get 扫列表**判活**（player.PlayerCombatState?.Pets.FirstOrDefault(p => p.Monster is X && p.IsAlive)），不再用 GetPet<T>() —— 它会返回已经死掉的那只，于是每次召唤都新建一只",
				petCs.Contains("return player.PlayerCombatState?.Pets.FirstOrDefault(p => p.Monster is UiCheckPet && p.IsAlive);")
				&& petCs.Contains("return player.PlayerCombatState?.Pets.FirstOrDefault(p => p.Monster is UiCheckPet2 && p.IsAlive);")
				&& !petCs.Contains("GetPet<"), "两只都改成判活");
			int petCmd2At = petCs.IndexOf("public static class UiCheckPet2Cmd", StringComparison.Ordinal);
			string petCmd1Body = petCmd2At > 0 ? petCs.Substring(0, petCmd2At) : "";
			string petCmd2Body = petCmd2At > 0 ? petCs.Substring(petCmd2At) : "";
			int relayout1 = petCmd1Body.Split("ForgePetLayout.RelayoutAll(player);").Length - 1;
			int relayout2 = petCmd2Body.Split("ForgePetLayout.RelayoutAll(player);").Length - 1;
			Check("召唤命令：每只宠物的召唤命令里都有 ForgePetLayout.RelayoutAll(player)（「已存在→加血」和「新建」两个分支各一次 → 每只 2 处）",
				petCmd2At > 0 && relayout1 == 2 && relayout2 == 2, $"UiCheckPetCmd={relayout1} / UiCheckPet2Cmd={relayout2}");

			// ①-d bug③：攻击不生效 —— 不再用 FromMonster，改成 FromCard + FromPetAttacker（扩展方法）
			string petExtPath = Path.Combine(petGen.ProjectRoot, "cs", "PetAttackExtensions.cs");
			Check("bug③攻击：生成了 cs/PetAttackExtensions.cs（把攻击者换成宠物的扩展方法）", File.Exists(petExtPath), petExtPath);
			string petExt = File.Exists(petExtPath) ? File.ReadAllText(petExtPath, Encoding.UTF8) : "";
			Check("bug③攻击：扩展方法用反射设 AttackCommand.Attacker 的 private setter（不是 Harmony 补丁）",
				petExt.Contains("public static AttackCommand FromPetAttacker(this AttackCommand command, Creature pet)")
				&& petExt.Contains("typeof(AttackCommand).GetProperty(\"Attacker\",")
				&& petExt.Contains("System.Reflection.BindingFlags.NonPublic")
				// 「不是 Harmony 补丁」要按**真的用了 Harmony** 判：文件头的说明注释里写着
				// 「为什么不用 Harmony 补丁」，直接 Contains("Harmony") 会把注释也算成命中（以前就这么误判过）。
				&& !petExt.Contains("HarmonyPatch") && !petExt.Contains("HarmonyLib") && !petExt.Contains("using Harmony"),
				"反射方案");
			// 四种「由宠物发起攻击」的效果都必须触发这个文件：漏一种 → 生成的卡引用不存在的
			// 扩展方法 → CS1061（编译直接过不去）。这里逐个种类验一遍需要它。
			Check("bug③攻击：四种宠物攻击类效果（PetAttack / 按最大·当前·已损失生命）都算「要用扩展方法」",
				PetGen.IsAttackKind("PetAttack") && PetGen.IsAttackKind("PetDamageByMaxHp")
				&& PetGen.IsAttackKind("PetDamageByCurHp") && PetGen.IsAttackKind("PetDamageByMissingHp")
				&& !PetGen.IsAttackKind("PetHeal") && !PetGen.IsAttackKind("PetSacrifice"),
				string.Join(" / ", new[] { "PetAttack", "PetDamageByMaxHp", "PetDamageByCurHp", "PetDamageByMissingHp" }
					.Select(k => k + "=" + PetGen.IsAttackKind(k))));
			Check("bug③攻击：没有生成任何 Harmony 补丁", !Directory.GetFiles(Path.Combine(petGen.ProjectRoot, "cs"), "*.cs", SearchOption.AllDirectories)
				.Any((string f) => File.ReadAllText(f, Encoding.UTF8).Contains("HarmonyPatch(typeof(MegaCrit.Sts2.Core.Commands.Builders.AttackCommand)")), "没有攻击补丁");

			// ② monsters.json：两只的名字都在
			string petLocPath = Path.Combine(petGen.ProjectRoot, petSrc.ModId, "localization", "zhs", "monsters.json");
			Check("召唤物：生成了 monsters.json", File.Exists(petLocPath), petLocPath);
			string petLoc = File.Exists(petLocPath) ? File.ReadAllText(petLocPath, Encoding.UTF8) : "";
			Check("召唤物：monsters.json 里两只的名字都有（本体怪物名字的键格式）",
				petLoc.Contains("\"UI_CHECK_PET.name\": \"小石头\"") && petLoc.Contains("\"UI_CHECK_PET2.name\": \"小铁块\""),
				petLoc.Replace("\r", "").Replace("\n", " "));
			// 键必须是**本体算法**算出来的 <ENTRY>.name：本体 MonsterModel.Title 读的就是 Id.Entry，
			// 而 Id.Entry = StringHelper.Slugify(类名)。我们的 Naming.Slug 差一个字符，本体就查不到这个名字；
			// 更糟的是非中文语言下 LocTable 查不到键会直接抛 LocException（宠物节点初始化中断）。
			var petKeyDefs = PetGen.All(petSrc);
			Check("召唤物：monsters.json 每个键 = 用本体算法算出来的 <ENTRY>.name（两只召唤物逐个核对）",
				petKeyDefs.Count == 2 && petKeyDefs.All((PetGen.PetDef pd) =>
					string.Equals(Naming.Slug(pd.ClassName), VanillaSlugify(pd.ClassName), StringComparison.Ordinal)
					&& petLoc.Contains("\"" + VanillaSlugify(pd.ClassName) + ".name\":", StringComparison.Ordinal)),
				string.Join(" / ", petKeyDefs.Select((PetGen.PetDef pd) =>
					pd.ClassName + " → 我们=" + Naming.Slug(pd.ClassName) + " / 本体=" + VanillaSlugify(pd.ClassName))));
			// 中英文两份内容相同：模组本地化只合并「当前语言」的同名表（ModManager.cs:966-979 + LocManager.cs:468），
			// 英文会话下缺 <ENTRY>.name 会让 LocTable 抛 LocException —— 显示中文名总比崩好。
			string petLocEngPath = Path.Combine(petGen.ProjectRoot, petSrc.ModId, "localization", "eng", "monsters.json");
			Check("召唤物：monsters.json 同时写了 eng 一份（内容与 zhs 相同）",
				File.Exists(petLocEngPath)
				&& string.Equals(File.ReadAllText(petLocEngPath, Encoding.UTF8), petLoc, StringComparison.Ordinal),
				petLocEngPath);

			// ③ 召唤牌：只召唤它自己那只
			string petSummonSrc = File.ReadAllText(Path.Combine(petGen.ProjectRoot, "cs", "Cards", "UiCheckPetSummon.cs"), Encoding.UTF8);
			Check("召唤卡：生成的代码里出现召唤调用（UiCheckPetCmd.Summon）",
				petSummonSrc.Contains("UiCheckPetCmd.Summon(choiceContext, base.Owner,"), "有召唤调用");
			Check("召唤卡：数值填 0 时用**那只自己的**血量（9m），不是 0、也不是别的召唤物的血量",
				petSummonSrc.Contains(", 9m);") && !petSummonSrc.Contains(", 15m);"), "用配置血量");
			Check("召唤卡：不需要额外查宠物（Summon 内部自己找），所以不声明查询变量",
				!petSummonSrc.Contains("Creature? __uiCheckPet"), "没有多余局部变量");
			Check("召唤卡：仍然有「战斗状态不为 null」的守卫（关闭括号要对上，缺一个就编译不过）",
				petSummonSrc.Contains("if (base.Owner.PlayerCombatState is not null)"), "有守卫");
			string petSummonLoc = File.ReadAllText(Path.Combine(petGen.ProjectRoot, petSrc.ModId, "localization", "zhs", "cards.json"), Encoding.UTF8);
			Check("召唤卡：卡面描述里写着那只的名字（召唤小石头。）", petSummonLoc.Contains("召唤小石头。"), "描述里有名字");

			// ④ 伙伴攻击牌（单体：FromCard + Targeting + FromPetAttacker）
			string petAtkSrc = File.ReadAllText(Path.Combine(petGen.ProjectRoot, "cs", "Cards", "UiCheckPetAttack.cs"), Encoding.UTF8);
			Check("bug③攻击：生成的代码不再用 .FromMonster(（那会把来源标成 Monster → 去打玩家自己人、还和 Targeting 冲突）",
				!petAtkSrc.Contains(".FromMonster("), "没有 FromMonster");
			Check("bug③攻击：先走正常卡牌路径（FromCard），再把攻击者换成宠物（FromPetAttacker）",
				petAtkSrc.Contains(".FromCard(this, cardPlay)")
				&& petAtkSrc.Contains(".FromPetAttacker(__uiCheckPet)"), "FromCard + FromPetAttacker");
			Check("bug③攻击：FromCard 在前、FromPetAttacker 在后（FromCard 会校验 Attacker 必须为空）",
				petAtkSrc.IndexOf(".FromCard(this, cardPlay)", StringComparison.Ordinal) < petAtkSrc.IndexOf(".FromPetAttacker(__uiCheckPet)", StringComparison.Ordinal),
				"顺序对");
			Check("bug③攻击：单体目标仍然用 .Targeting(cardPlay.Target)（现在和 FromCard 不冲突了）",
				petAtkSrc.Contains(".Targeting(cardPlay.Target)"), "有 Targeting");
			Check("bug③攻击：给宠物播自己的攻击动画（没有该动画就退化成不动，无副作用）",
				petAtkSrc.Contains(".WithAttackerAnim(\"Attack\", 0.3f)"), "有动画");
			Check("bug③攻击：打之前先判宠物在不在场（不在就跳过，不让整张牌报错）",
				petAtkSrc.Contains("if (__uiCheckPet is not null)"), "有守卫");
			Check("bug③攻击：伤害走我们自己的动态变量 PetDamage（不是兜底的 Value）",
				petAtkSrc.Contains("new DynamicVar(\"PetDamage\", 7m)") && petAtkSrc.Contains("base.DynamicVars[\"PetDamage\"].BaseValue"), "用 PetDamage");
			Check("伙伴攻击卡：TargetType 是 AnyEnemy（要玩家选目标）", petAtkSrc.Contains("TargetType.AnyEnemy"), "AnyEnemy");
			string petAtkLoc = File.ReadAllText(Path.Combine(petGen.ProjectRoot, petSrc.ModId, "localization", "zhs", "cards.json"), Encoding.UTF8);
			Check("伙伴攻击卡：卡面描述里写着「让小石头…造成伤害」", petAtkLoc.Contains("让小石头"), "描述里有名字");

			// ④-b 第二只的全体攻击卡：换了一只 → 局部变量名也不同、TargetSide 走 TargetingAllOpponents
			string petAtk2Src = File.ReadAllText(Path.Combine(petGen.ProjectRoot, "cs", "Cards", "UiCheckPetAttack2.cs"), Encoding.UTF8);
			Check("第二只召唤物的攻击卡用的是它自己的查询变量和命令（__uiCheckPet2 / UiCheckPet2Cmd）",
				petAtk2Src.Contains("Creature? __uiCheckPet2 = UiCheckPet2Cmd.Get(base.Owner);")
				&& petAtk2Src.Contains(".FromPetAttacker(__uiCheckPet2)")
				&& petAtk2Src.Contains("if (__uiCheckPet2 is not null)"), "用第二只");
			Check("第二只召唤物的全体攻击卡走 .TargetingAllOpponents(base.CombatState)（攻击者已经换成宠物）",
				petAtk2Src.Contains(".TargetingAllOpponents(base.CombatState)"), "全体目标");

			// ⑤ 遗物触发（战斗开始时召唤第二只，血量 12）
			string petRelicSrc = File.ReadAllText(Path.Combine(petGen.ProjectRoot, "cs", "Relics", "UiCheckPetRelic.cs"), Encoding.UTF8);
			Check("遗物触发：战斗开始时也能召唤（本体 Byrdpip 的写法），而且召唤的是指定的那一只",
				petRelicSrc.Contains("BeforeSideTurnStart") && petRelicSrc.Contains("UiCheckPet2Cmd.Summon(choiceContext, base.Owner,"), "有召唤");
			Check("遗物触发：遗物上的召唤支持自定义血量（PetHp 动态变量）",
				System.Text.RegularExpressions.Regex.IsMatch(petRelicSrc, @"base\.DynamicVars\[""PetHp""\]\.BaseValue\);"),
				"12m");

			// ⑥ 药水：两条都不支持 —— 但必须留一行注释，不能静默丢掉
			PotionSpec petPotion = new PotionSpec { Name = "召唤药水", ClassName = "UiCheckPetPotion", Rarity = "Common" };
			petPotion.Effects.Clear();
			petPotion.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 5m, TargetSide = "Self", PetSummon = "UiCheckPet" });
			petPotion.Effects.Add(new EffectSpec { Kind = "PetAttack", Amount = 5m, TargetSide = "AnyEnemy", PetSummon = "UiCheckPet" });
			petSrc.Potions.Add(petPotion);
			Check("药水：召唤伙伴 / 伙伴攻击都不支持，但生成的代码里留了说明注释（不静默丢）",
				CSharpCodeGen.PotionSource(petSrc, petPotion, 0).Contains("药水不支持"),
				"有注释");
			Check("药水：校验器对药水里的「召唤伙伴 / 伙伴攻击」直接报错",
				ProfileValidator.Validate(petSrc).Count((ValidationIssue i) => i.IsError && i.Message.Contains("药水不支持")) >= 2,
				string.Join(" | ", ProfileValidator.Validate(petSrc).Where((ValidationIssue i) => i.IsError && i.Message.Contains("药水不支持")).Select((ValidationIssue i) => i.Message)));
			petSrc.Potions.Remove(petPotion);

			// ⑦ 回读：列表 / 顺序 / 站位 / 守卫 / 「哪一只」都要回来
			var petRec = ProjectRecovery.FromProject(petGen.ProjectRoot);
			Check("从工程恢复：召唤物列表找回来了（两只、顺序一致、启用 / 类名 / 名字 / 生命）",
				petRec.Profile.Summons.Count == 2
				&& petRec.Profile.Summons[0].Enabled && petRec.Profile.Summons[0].ClassName == "UiCheckPet"
				&& petRec.Profile.Summons[0].Name == "小石头" && petRec.Profile.Summons[0].Hp == 9
				&& petRec.Profile.Summons[1].ClassName == "UiCheckPet2"
				&& petRec.Profile.Summons[1].Name == "小铁块" && petRec.Profile.Summons[1].Hp == 15,
				string.Join(" · ", petRec.Profile.Summons.Select((SummonSpec s) => s.Display)));
			Check("从工程恢复：站位距离找回来了（每只各自的 140 / 90）",
				petRec.Profile.Summons[0].StandDistance == 140 && petRec.Profile.Summons[1].StandDistance == 90,
				$"{petRec.Profile.Summons[0].StandDistance} / {petRec.Profile.Summons[1].StandDistance}");
			Check("从工程恢复：「替主人承伤」的勾选找回来了（两只勾了的都回读成 True —— 守卫是共用的一个类，要按每只自己的召唤命令逐只判）",
				petRec.Profile.Summons[0].TakesDamageForOwner && petRec.Profile.Summons[1].TakesDamageForOwner,
				$"{petRec.Profile.Summons[0].TakesDamageForOwner} / {petRec.Profile.Summons[1].TakesDamageForOwner}");
			Check("从工程恢复：卡牌上的「召唤伙伴」效果找回来了（数值 0 = 用配置血量，而且知道是哪一只）",
				petRec.Profile.Cards.Any((CardSpec c) => c.ClassName == "UiCheckPetSummon"
					&& c.Effects.Count == 1 && c.Effects[0].Kind == "SummonPet" && c.Effects[0].Amount == 0m
					&& c.Effects[0].PetSummon == "UiCheckPet"),
				string.Join(" · ", petRec.Profile.Cards.Where((CardSpec c) => c.ClassName == "UiCheckPetSummon")
					.SelectMany((CardSpec c) => c.Effects).Select((EffectSpec e) => e.Kind + "/" + (e.PetSummon ?? "?"))));
			Check("从工程恢复：卡牌上的「伙伴攻击」效果找回来了（伤害 7 + 升级 3 + 指向第一只）",
				petRec.Profile.Cards.Any((CardSpec c) => c.ClassName == "UiCheckPetAttack"
					&& c.Effects.Count == 1 && c.Effects[0].Kind == "PetAttack" && c.Effects[0].Amount == 7m
					&& c.Effects[0].UpgradeAmount == 3m && c.Effects[0].TargetSide == "Enemy"
					&& c.Effects[0].PetSummon == "UiCheckPet"),
				string.Join(" · ", petRec.Profile.Cards.Where((CardSpec c) => c.ClassName == "UiCheckPetAttack")
					.SelectMany((CardSpec c) => c.Effects).Select((EffectSpec e) => e.Kind + "/" + (e.PetSummon ?? "?"))));
			Check("从工程恢复：第二只的攻击卡也指向第二只（列表里不同召唤物不会串）",
				petRec.Profile.Cards.Any((CardSpec c) => c.ClassName == "UiCheckPetAttack2"
					&& c.Effects.Count == 1 && c.Effects[0].Kind == "PetAttack" && c.Effects[0].Amount == 5m
					&& c.Effects[0].TargetSide == "AllEnemies" && c.Effects[0].PetSummon == "UiCheckPet2"),
				string.Join(" · ", petRec.Profile.Cards.Where((CardSpec c) => c.ClassName == "UiCheckPetAttack2")
					.SelectMany((CardSpec c) => c.Effects).Select((EffectSpec e) => e.Kind + "/" + (e.PetSummon ?? "?"))));
			Check("从工程恢复：遗物上的「召唤伙伴」效果找回来了（12 点生命 + 指向第二只）",
				petRec.Profile.Relics.Any((RelicSpec r) => r.Effects.Any((EffectSpec e) => e.Kind == "SummonPet"
					&& e.Amount == 12m && e.PetSummon == "UiCheckPet2")),
				string.Join(" · ", petRec.Profile.Relics.SelectMany((RelicSpec r) => r.Effects).Select((EffectSpec e) => e.Kind + "/" + (e.PetSummon ?? "?"))));
			Check("从工程恢复：没认出来的语句为 0（召唤物相关的生成代码都认得）", !petRec.HasUnparsed,
				petRec.Unparsed.Count == 0 ? "全部认出来了" : $"{petRec.Unparsed.Count} 条：" + string.Join(" ｜ ", petRec.Unparsed.Take(3)));

			// ⑧ 校验拦截：全部停用 → 不生成 cs/Pet.cs（卡牌还引用着 → 校验器报错拦住）
			foreach (var s in petSrc.Summons) s.Enabled = false;
			var petGen2 = ModGenerator.Generate(petSrc);
			Check("全部召唤物停用后不会生成 cs/Pet.cs（但卡牌还引用着它们 → 由校验器报错拦住，生成会被中止）",
				!petGen2.Success || !File.Exists(Path.Combine(petGen2.ProjectRoot, "cs", "Pet.cs")),
				petGen2.Success ? "生成成功但没写 Pet.cs" : "生成被校验拦住了");
			foreach (var s in petSrc.Summons) s.Enabled = true;

			// ⑨ 校验：同时勾两只「替主人承伤」现在**不再是错误**（共用守卫自己仲裁），只给一句提示
			petSrc.Summons[1].TakesDamageForOwner = true;
			var petGuardIssues = ProfileValidator.Validate(petSrc);
			Check("同时有两只召唤物勾了「替主人承伤」时校验器**不再报错**（生成代码自己仲裁：列表里第一只活着的承担，死了换下一只）",
				!petGuardIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("只能勾一只"))
				&& !petGuardIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("替主人承伤")),
				string.Join(" | ", petGuardIssues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
			Check("同时勾两只时校验器给出了「第一只活着的承伤、死了自动换下一只」的提示（非错误，不拦生成）",
				petGuardIssues.Any((ValidationIssue i) => !i.IsError && i.Message.Contains("有 2 只召唤物勾了「替主人承伤」")
					&& i.Message.Contains("第一只活着")),
				string.Join(" | ", petGuardIssues.Where((ValidationIssue i) => i.Message.Contains("替主人承伤")).Select((ValidationIssue i) => i.Message)));
			// 两只都勾着也能照常生成（守卫类只有一个，两只的召唤命令都挂它）
			var petGen3 = ModGenerator.Generate(petSrc);
			Check("两只都勾「替主人承伤」时生成照常成功（校验器不再拦），且 Pet.cs 里只有一个共用守卫类",
				petGen3.Success && File.Exists(Path.Combine(petGen3.ProjectRoot, "cs", "Pet.cs"))
				&& File.ReadAllText(Path.Combine(petGen3.ProjectRoot, "cs", "Pet.cs"), Encoding.UTF8)
					.Split($"public sealed class {guardName} : PowerModel").Length - 1 == 1,
				string.Join(" | ", petGen3.Issues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
			petSrc.Summons[1].TakesDamageForOwner = false;

			// ⑩ 校验拦截：两只召唤物的类名重名
			petSrc.Summons[1].ClassName = "UiCheckPet";
			var petDupIssues = ProfileValidator.Validate(petSrc);
			Check("两只召唤物用了同一个英文类名时校验器报错拦住（本体按类名注册模型 → DuplicateModelException）",
				petDupIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("重复")),
				string.Join(" | ", petDupIssues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
			petSrc.Summons[1].ClassName = "UiCheckPet2";

			// ⑪ 校验拦截：效果指向一只不存在的召唤物
			petSrc.Cards.First((CardSpec c) => c.ClassName == "UiCheckPetSummon").Effects[0].PetSummon = "NoSuchPet";
			var petMissIssues = ProfileValidator.Validate(petSrc);
			Check("效果指向一只不存在的召唤物时校验器报错拦住（否则生成的代码会 CS0103）",
				petMissIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("NoSuchPet")),
				string.Join(" | ", petMissIssues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
			petSrc.Cards.First((CardSpec c) => c.ClassName == "UiCheckPetSummon").Effects[0].PetSummon = "UiCheckPet";

			// ⑫ 老存档兼容：单个 Summon（上一版的格式）要能迁移进列表
			var legacyPet = ProfileFactory.Sample();
			legacyPet.Summons.Clear();
			legacyPet.Summon = new SummonSpec { Enabled = true, ClassName = "UiCheckLegacyPet", Name = "老伙伴", Hp = 11 };
			ProfileFactory.Normalize(legacyPet);
			Check("老存档兼容：单个 Summon 会迁移进 Summons 列表并把老字段清空（不能静默丢配置）",
				legacyPet.Summon is null && legacyPet.Summons.Count == 1
				&& legacyPet.Summons[0].ClassName == "UiCheckLegacyPet" && legacyPet.Summons[0].Name == "老伙伴"
				&& legacyPet.Summons[0].Hp == 11 && legacyPet.Summons[0].StandDistance == SummonSpec.DefaultStandDistance,
				legacyPet.Summon is null ? string.Join(" · ", legacyPet.Summons.Select((SummonSpec s) => s.Display)) : "老字段还在");
			// 老存档里那个单对象是全空的（老版默认值）→ 不该凭空多出一条记录
			var legacyEmpty = ProfileFactory.Sample();
			legacyEmpty.Summons.Clear();
			legacyEmpty.Summon = new SummonSpec();
			ProfileFactory.Normalize(legacyEmpty);
			Check("老存档兼容：全空的单个 Summon 不会迁成一条空召唤物（否则列表里会凭空多一条）",
				legacyEmpty.Summon is null && legacyEmpty.Summons.Count == 0, $"{legacyEmpty.Summons.Count} 条");

			// ⑬ 老效果（PetSummon 为空）自动用第一只启用的召唤物（行为与上一版单只召唤物一致）
			var legacyEffectCard = new CardSpec { Name = "老召唤卡", ClassName = "UiCheckPetLegacyEffect", Cost = 1 };
			legacyEffectCard.Effects.Clear();
			legacyEffectCard.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, TargetSide = "Self" });   // 没填 PetSummon
			string legacyEffectSrc = CSharpCodeGen.CardSource(petSrc, legacyEffectCard, 0);
			Check("老存档的「召唤伙伴」效果没填「哪一只」时自动用第一只启用的召唤物（行为和上一版单只召唤物一致）",
				legacyEffectSrc.Contains("UiCheckPetCmd.Summon(choiceContext, base.Owner, 9m);"), "用第一只");

			// ===================== ⑭ 新增的那批宠物效果（10 个）=====================
			// 每个都要：① 生成代码里出现「关键的那一句」；② 从工程回读能原样认回来（不同步改回读就会静默丢配置）。
			// 顺便把「按生命值算」的三个伙伴攻击的三件套 / 静态倍率 lambda 也断言掉。
			{
				// —— 按最大生命值造成伤害（三件套 + 静态 lambda + IsPlayable / 描红框）——
				CardSpec newMax = new CardSpec { Name = "重压", ClassName = "UiCheckPetNewMax", CardType = "Attack", Cost = 1, InCardPool = true };
				newMax.Effects.Add(new EffectSpec { Kind = "PetDamageByMaxHp", Amount = 0m, UpgradeAmount = 3m, TargetSide = "Enemy", PetSummon = "UiCheckPet" });
				string maxSrc = CSharpCodeGen.CardSource(petSrc, newMax, 0);
				Check("新效果「伙伴攻击（按最大生命值）」生成了计算三件套（CalculationBase + ExtraDamage + CalculatedDamage）",
					maxSrc.Contains("new CalculationBaseVar(0m)") && maxSrc.Contains("new ExtraDamageVar(1m)")
					&& maxSrc.Contains("new CalculatedDamageVar(ValueProp.Move).WithMultiplier(")
					&& maxSrc.Contains("pet.MaxHp"), "三件套在");
				Check("新效果：倍率 lambda 是**静态**的（delegate(CardModel card, Creature? _)，绝不捕获实例）—— 写成实例方法本体在 CalculatedVar.cs:50 直接抛「Multiplier calc must be static!」",
					maxSrc.Contains("WithMultiplier(delegate(CardModel card, Creature? _) {")
					&& maxSrc.Contains("UiCheckPetCmd.Get(card.Owner)"), "静态 lambda");
				Check("新效果：攻击走 DamageCmd.Attack(base.DynamicVars.CalculatedDamage) + FromCard + FromPetAttacker（没写死数字）",
					maxSrc.Contains("await DamageCmd.Attack(base.DynamicVars.CalculatedDamage)")
					&& maxSrc.Contains(".FromCard(this, cardPlay)")
					&& maxSrc.Contains(".FromPetAttacker(__uiCheckPet)"), "攻击链对");
				Check("新效果：没伙伴时这张牌打不出去（IsPlayable）+ 缺伙伴描红框（ShouldGlowRedInternal）",
					maxSrc.Contains("protected override bool IsPlayable => (UiCheckPetCmd.Get(base.Owner) != null);")
					&& maxSrc.Contains("protected override bool ShouldGlowRedInternal => !(UiCheckPetCmd.Get(base.Owner) != null);"), "两句守卫都在");
				Check("新效果：宠物不在场时那条效果**安全跳过**（if (__uiCheckPet is not null) 包着，不抛异常）",
					maxSrc.Contains("if (__uiCheckPet is not null)"), "有跳过守卫");
				Check("新效果：升级增量写在 CalculationBase 上（「按生命值算」的 CalculatedDamage 名字是本体固定死的）",
					maxSrc.Contains("base.DynamicVars.CalculationBase.UpgradeValueBy(3m);"), "升级落点对");
				// 卡面描述里的 {名字:diff()} 必须是 CanonicalVars 里**真实声明**的那个键。
				// 用户实测报过（截图）：三种「按生命值算」的伙伴攻击 + 牺牲伙伴的收益，卡面上直接原样印出
				// {PetMissingHpDamage:diff()} —— 因为描述用的是我们的内部名字，而声明的是本体的
				// CalculatedDamage / CalculatedBlock（名字对不上，本体在 DynamicVars 里找不到 → 原样显示）。
				Check("卡面描述用 {CalculatedDamage…} 占位，**没有写死数字**（伤害按宠物生命值算）",
					LocalizationGen.CardsJson(petSrc).Length >= 0 && CSharpCodeGen.MarkerText(newMax.Effects[0]).Contains("CET:PetFormula=maxhp"), "标记在");
				Check("卡面描述里的变量名 = 真正声明的那个（CalculatedDamage），不是内部名字",
					CSharpCodeGen.DisplayVarNameOf(newMax.Effects[0]) == "CalculatedDamage"
					&& CSharpCodeGen.VarNameOf(newMax.Effects[0]) == "PetMaxHpDamage",
					CSharpCodeGen.DisplayVarNameOf(newMax.Effects[0]) + "（内部名字 " + CSharpCodeGen.VarNameOf(newMax.Effects[0]) + "）");

				// —— 按当前生命 / 已损失生命：变量名 + 公式标记要能区分 ——
				CardSpec newCur = new CardSpec { Name = "榨取", ClassName = "UiCheckPetNewCur", CardType = "Attack", Cost = 1, InCardPool = true };
				newCur.Effects.Add(new EffectSpec { Kind = "PetDamageByCurHp", Amount = 0m, TargetSide = "AllEnemies", PetSummon = "UiCheckPet" });
				CardSpec newMiss = new CardSpec { Name = "绝境", ClassName = "UiCheckPetNewMiss", CardType = "Attack", Cost = 1, InCardPool = true };
				newMiss.Effects.Add(new EffectSpec { Kind = "PetDamageByMissingHp", Amount = 0m, TargetSide = "RandomEnemies", RepeatCount = 2, PetSummon = "UiCheckPet" });
				string curSrc = CSharpCodeGen.CardSource(petSrc, newCur, 0);
				string missSrc = CSharpCodeGen.CardSource(petSrc, newMiss, 0);
				Check("新效果：三种「按生命值算」的伙伴攻击各自一套变量名（PetMaxHpDamage / PetCurHpDamage / PetMissingHpDamage）",
					!maxSrc.Contains("new DynamicVar(\"PetMaxHpDamage\", 0m)")   // 现在是计算三件套，不再是普通 DynamicVar
					&& CSharpCodeGen.VarNameOf(newMax.Effects[0]) == "PetMaxHpDamage"
					&& CSharpCodeGen.VarNameOf(newCur.Effects[0]) == "PetCurHpDamage"
					&& CSharpCodeGen.VarNameOf(newMiss.Effects[0]) == "PetMissingHpDamage",
					CSharpCodeGen.VarNameOf(newMax.Effects[0]) + " / " + CSharpCodeGen.VarNameOf(newCur.Effects[0]) + " / " + CSharpCodeGen.VarNameOf(newMiss.Effects[0]));
				Check("新效果：当前生命 / 已损失生命的倍率表达式各自正确（pet.CurrentHp / pet.MaxHp - pet.CurrentHp）",
					curSrc.Contains("(decimal)pet.CurrentHp") && missSrc.Contains("(decimal)(pet.MaxHp - pet.CurrentHp)")
					&& !curSrc.Contains("pet.MaxHp - pet.CurrentHp"), "两个公式对");
				Check("卡面描述的变量名（三种按生命值算）= 真正声明的 CalculatedDamage，**不是**内部名字（否则卡面原样印出 {PetMissingHpDamage:diff()}）",
					CSharpCodeGen.DisplayVarNameOf(newMax.Effects[0]) == "CalculatedDamage"
					&& CSharpCodeGen.DisplayVarNameOf(newCur.Effects[0]) == "CalculatedDamage"
					&& CSharpCodeGen.DisplayVarNameOf(newMiss.Effects[0]) == "CalculatedDamage",
					CSharpCodeGen.DisplayVarNameOf(newMax.Effects[0]) + " / " + CSharpCodeGen.DisplayVarNameOf(newCur.Effects[0])
					+ " / " + CSharpCodeGen.DisplayVarNameOf(newMiss.Effects[0]));
				Check("新效果：全部敌人 / 随机敌人各自走 TargetingAllOpponents / TargetingRandomOpponents（FromPetAttacker 在后）",
					curSrc.Contains(".TargetingAllOpponents(base.CombatState)")
					&& missSrc.Contains(".TargetingRandomOpponents(base.CombatState, allowDuplicates: true)"), "目标对");
				Check("新效果：按生命值算的宠物攻击标记里写了公式（回读按它区分三种倍率）",
					CSharpCodeGen.MarkerText(newMax.Effects[0]) == "PetCalcAttack CET:PetFormula=maxhp"
					&& CSharpCodeGen.MarkerText(newCur.Effects[0]) == "PetCalcAttack CET:PetFormula=curhp"
					&& CSharpCodeGen.MarkerText(newMiss.Effects[0]) == "PetCalcAttack CET:PetFormula=missinghp",
					CSharpCodeGen.MarkerText(newMax.Effects[0]));

				// —— 治疗 / 失去生命 / 最大生命 / 施加状态 / 守卫开 / 守卫关 ——
				CardSpec newMisc = new CardSpec { Name = "照料", ClassName = "UiCheckPetNewMisc", CardType = "Skill", Cost = 1, InCardPool = true };
				newMisc.Effects.Add(new EffectSpec { Kind = "PetHeal", Amount = 6m, UpgradeAmount = 3m, TargetSide = "Self", PetSummon = "UiCheckPet" });
				newMisc.Effects.Add(new EffectSpec { Kind = "PetLoseHp", Amount = 3m, TargetSide = "Self", PetSummon = "UiCheckPet" });
				newMisc.Effects.Add(new EffectSpec { Kind = "PetGainMaxHp", Amount = 4m, TargetSide = "Self", PetSummon = "UiCheckPet" });
				newMisc.Effects.Add(new EffectSpec { Kind = "PetApplyPower", Amount = 2m, PowerId = "StrengthPower", TargetSide = "Self", PetSummon = "UiCheckPet" });
				newMisc.Effects.Add(new EffectSpec { Kind = "PetGuardOn", TargetSide = "Self", PetSummon = "UiCheckPet" });
				newMisc.Effects.Add(new EffectSpec { Kind = "PetGuardOff", TargetSide = "Self", PetSummon = "UiCheckPet" });
				string miscSrc = CSharpCodeGen.CardSource(petSrc, newMisc, 0);
				Check("新效果「治疗伙伴」：CreatureCmd.Heal(pet, Heal.BaseValue)",
					miscSrc.Contains("await CreatureCmd.Heal(__uiCheckPet, base.DynamicVars.Heal.BaseValue);"), "有治疗");
				Check("新效果「伙伴失去生命」：CreatureCmd.Damage + Unblockable|Unpowered|Move（本体 DamageProps.cardHpLoss）",
					miscSrc.Contains("await CreatureCmd.Damage(choiceContext, __uiCheckPet, base.DynamicVars.HpLoss.BaseValue,")
					&& miscSrc.Contains("ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move,"), "失去生命对");
				Check("新效果「伙伴最大生命 +N」：CreatureCmd.GainMaxHp（注释里写明当前生命会同时回复）",
					miscSrc.Contains("await CreatureCmd.GainMaxHp(__uiCheckPet, base.DynamicVars.MaxHp.BaseValue);")
					&& miscSrc.Contains("当前生命同时回复"), "最大生命对");

				// ===== 「造成伤害 + 作用对象 = 自己」必须**能被格挡**（用户报的：护盾一格都吃不到）=====
				// 本体判据（Creature.cs）：`props.HasFlag(Unblockable) ? 0 : Math.Min(Block, amount)` —— 
				// 所以只要带 Unblockable 就穿盾。以前这条路写的是 Unblockable|Unpowered|Move
				// ）  DamageProps.cardHpLoss，和「失去生命」生成的一模一样），于是自己造成伤害也穿盾。"
				{
					CharacterProfile selfProf = ProfileFactory.Sample();
					var selfCard = new CardSpec { Name = "自伤", ClassName = "UiCheckSelfDamage", CardType = "Skill", Cost = 1, InCardPool = true };
					selfCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Self" });
					selfCard.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 3m, TargetSide = "Self" });
					selfProf.Cards.Add(selfCard);
					string selfSrc = CSharpCodeGen.CardSource(selfProf, selfCard, 0);
					Check("卡牌「造成伤害 + 自己」：走 ValueProp.Unpowered | Move（**格挡能挡**、不被力量放大）",
						selfSrc.Contains("CreatureCmd.Damage(choiceContext, base.Owner.Creature, base.DynamicVars.Damage.BaseValue, ValueProp.Unpowered | ValueProp.Move,"),
						(selfSrc.Split('\n').FirstOrDefault(l => l.Contains("base.Owner.Creature, base.DynamicVars.Damage")) ?? "(没找到 ").Trim());
					Check("卡牌「造成伤害 + 自己」不再带 Unblockable（带了就穿盾 —— 护盾一格都吃不到）",
						!selfSrc.Contains("base.DynamicVars.Damage.BaseValue, ValueProp.Unblockable"), "没有 Unblockable");
					Check("（对照）「失去生命 + 自己」照旧是 Unblockable（本体 DamageProps.cardHpLoss：**无视格挡**）",
						selfSrc.Contains("base.DynamicVars[\"HpLoss\"].BaseValue, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move,"), "失去生命照旧穿盾");
					Check("卡面描述也对得上：造成伤害写「受到 N 点伤害」、失去生命写「失去 N 点生命」",
						LocalizationGen.CardsJson(selfProf).Contains("受到 {Damage:diff()} 点伤害") || LocalizationGen.CardsJson(selfProf).Contains("受到 5 点伤害"),
						(LocalizationGen.CardsJson(selfProf).Split('\n').FirstOrDefault(l => l.Contains("受到")) ?? "(没找到卡面 ").Trim());
				}
				// 遗物 / 自定义状态上的「对自己造成伤害」：非卡牌来源 = 本体 DamageProps.nonCardUnpowered（Unpowered），
				// 同样**没有** Unblockable（自定义状态那条本来就是对的，这里把它一起钉住）
				{
					CharacterProfile relicProf = ProfileFactory.Sample();
					var selfRelic = new RelicSpec { Name = "自伤遗物", ClassName = "UiCheckSelfDamageRelic", Rarity = "Common", Trigger = "PlayerTurnStart" };
					selfRelic.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Self" });
					relicProf.Relics.Add(selfRelic);
					string relicSrc = CSharpCodeGen.RelicSource(relicProf, selfRelic, 0);
					Check("遗物「造成伤害 + 自己」：走 ValueProp.Unpowered（**格挡能挡**，本体 DamageProps.nonCardUnpowered）",
						relicSrc.Contains("CreatureCmd.Damage(choiceContext, base.Owner.Creature, base.DynamicVars.Damage.BaseValue, ValueProp.Unpowered,"),
						(relicSrc.Split('\n').FirstOrDefault(l => l.Contains("base.Owner.Creature, base.DynamicVars.Damage")) ?? "(没找到 ").Trim());
					Check("遗物「造成伤害 + 自己」也不带 Unblockable",
						!relicSrc.Contains("base.DynamicVars.Damage.BaseValue, ValueProp.Unblockable"), "没有 Unblockable");

					CharacterProfile powProf = ProfileFactory.Sample();
					var selfPow = new CustomPowerSpec { Name = "自伤状态", Type = "Debuff" };
					var powTrig = new PowerTriggerSpec { Kind = "TurnStart" };
					powTrig.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Self" });
					selfPow.Triggers.Add(powTrig);
					powProf.CustomPowers.Add(selfPow);
					string powSrc = CustomPowerGen.Source(powProf, selfPow, 0);
					Check("自定义状态「造成伤害 + 自己」：也是 ValueProp.Unpowered、不带 Unblockable",
						powSrc.Contains("CreatureCmd.Damage(choiceContext, base.Owner, 4m, ValueProp.Unpowered,")
						&& !powSrc.Contains("4m, ValueProp.Unblockable"),
						(powSrc.Split('\n').FirstOrDefault(l => l.Contains("CreatureCmd.Damage")) ?? "(没找到 ").Trim());

					// 药水：目标是自己 + 「造成伤害」  **生成出来一条都不会执行**（药水没有「自己挨打」这条路）。"
					// 以前只在生成的代码里留一行注里 —— 生成 / 编译 / 进游戏全都不报错，就是没反应，所以加一条警告。"
					CharacterProfile potProf = ProfileFactory.Sample();
					var selfPot = new PotionSpec
					{
						Name = "自伤药", ClassName = "UiCheckSelfDamagePotion", Rarity = "Common",
						Usage = "CombatOnly", TargetType = "Self",
					};
					selfPot.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Self" });
					potProf.Potions.Add(selfPot);
					Check("药水「目标 = 自己」+「造成伤害」→ 校验器**警告**说清这条不会执行（以前是静默的）",
						ProfileValidator.Validate(potProf).Any(i => i.Level == "警告" && i.Message.Contains("不会执行")),
						string.Join(" ｜ ", ProfileValidator.Validate(potProf).Where(i => i.Message.Contains("药水")).Select(i => i.Message).Take(1)));
					selfPot.TargetType = "AnyEnemy";
					Check("（对照）把药水的目标改成敌人就不再警告（那条路是真会执行的）",
						!ProfileValidator.Validate(potProf).Any(i => i.Message.Contains("不会执行")), "不报了");
				}
				Check("新效果「给伙伴施加状态」：PowerCmd.Apply<StrengthPower>(choiceContext, pet, …)（数值走 PetPowerStrengthPower 变量）",
					miscSrc.Contains("await PowerCmd.Apply<StrengthPower>(choiceContext, __uiCheckPet, base.DynamicVars[\"PetPowerStrengthPower\"].BaseValue,"), "施加状态对");
				Check("新效果「伙伴替主人承伤（开）」：PowerCmd.Apply<ForgePetGuardianPower>（我们自己的共用守卫类，不是本体 DieForYouPower）",
					miscSrc.Contains($"await PowerCmd.Apply<{guardName}>(choiceContext, __uiCheckPet, 1m, null, null);"), "守卫开对");
				Check("新效果「取消伙伴替主人承伤（关）」：PowerCmd.Remove<ForgePetGuardianPower>(pet)（本体签名 PowerCmd.cs:282）",
					miscSrc.Contains($"await PowerCmd.Remove<{guardName}>(__uiCheckPet);"), "守卫关对");
				Check("新效果：两条「替主人承伤」开关**不声明**动态变量（否则会多出 DynamicVar(\"Value\")，两条就撞名 → 开新局崩）",
					!miscSrc.Contains("new DynamicVar(\"Value\", 0m)"), "没有多余变量");

				// —— 牺牲伙伴：格挡（最大生命×3）/ 伤害（固定 7）/ 格挡（当前生命）——
				CardSpec sacBlock = new CardSpec { Name = "献身", ClassName = "UiCheckPetNewSacBlock", CardType = "Skill", Cost = 1, InCardPool = true };
				sacBlock.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Block", PetSacrificeFormula = "MaxHp", PetSacrificeMultiplier = 3m });
				CardSpec sacDmg = new CardSpec { Name = "骨刺", ClassName = "UiCheckPetNewSacDmg", CardType = "Attack", Cost = 1, InCardPool = true };
				sacDmg.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Enemy", PetSummon = "UiCheckPet", PetSacrificeGain = "Damage", PetSacrificeFormula = "Fixed", Amount = 7m });
				CardSpec sacCur = new CardSpec { Name = "同命", ClassName = "UiCheckPetNewSacCur", CardType = "Skill", Cost = 1, InCardPool = true };
				sacCur.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Block", PetSacrificeFormula = "CurHp" });
				string sacBlockSrc = CSharpCodeGen.CardSource(petSrc, sacBlock, 0);
				string sacDmgSrc = CSharpCodeGen.CardSource(petSrc, sacDmg, 0);
				string sacCurSrc = CSharpCodeGen.CardSource(petSrc, sacCur, 0);
				Check("新效果「牺牲伙伴（格挡 / 最大生命×倍率）」：用 CalculationExtraVar（**不是** ExtraDamageVar）+ CalculatedBlockVar",
					sacBlockSrc.Contains("new CalculationExtraVar(1m)")
					&& sacBlockSrc.Contains("new CalculatedBlockVar(ValueProp.Move).WithMultiplier(")
					&& !sacBlockSrc.Contains("new ExtraDamageVar(1m)")
					&& sacBlockSrc.Contains("(decimal)pet.MaxHp * 3m"), "格挡三件套对");
				Check("新效果「牺牲伙伴」：先算收益、再杀宠物（decimal gain = … 在 CreatureCmd.Kill 之前）",
					sacBlockSrc.IndexOf("decimal gain = ", StringComparison.Ordinal) < sacBlockSrc.IndexOf("await CreatureCmd.Kill(__uiCheckPet);", StringComparison.Ordinal)
					&& sacBlockSrc.Contains("await CreatureCmd.GainBlock(base.Owner.Creature, gain, base.DynamicVars.CalculatedBlock.Props, cardPlay);"), "顺序对");
				Check("新效果「牺牲伙伴（伤害 / 固定 N）」：固定值走普通 DamageVar，先 Kill 再用 DamageCmd.Attack(数字)（顺序不能反）",
					sacDmgSrc.Contains("new DamageVar(\"PetSacrificeDamage\", 7m, ValueProp.Move)")
					&& sacDmgSrc.IndexOf("await CreatureCmd.Kill(__uiCheckPet);", StringComparison.Ordinal) < sacDmgSrc.IndexOf("await DamageCmd.Attack(dmg)", StringComparison.Ordinal), "伤害版对");
				Check("新效果「牺牲伙伴（伤害）」的 TargetType 是 AnyEnemy（生成的是 .Targeting(cardPlay.Target)，不能是 Self）",
					sacDmgSrc.Contains("TargetType.AnyEnemy"), "AnyEnemy");
				Check("新效果「牺牲伙伴（当前生命）」标记里带 curhp（回读按它还原公式）",
					sacCurSrc.Contains("CET:PetFormula=curhp") && sacCurSrc.Contains("(decimal)pet.CurrentHp"), "curhp 在");
				Check("新效果「牺牲伙伴（最大生命×倍率）」标记里带倍率（回读要能还原 3 倍）",
					sacBlockSrc.Contains("CET:PetMul=3m"), "倍率标记在");

				// ===== V0.2.200（用户要求「召唤物即死：收益的造成伤害能不能加个选择对象」）=====
				// 以前「牺牲伙伴」**一律不摆**「作用对象」那一栏（判据只看 Kind），收益选「造成伤害」时
				// 生成端写死 `.Targeting(cardPlay.Target)` —— 想「牺牲一只伙伴、对所有敌人造成伤害」根本做不到。
				{
					var sacUiBlock = new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Block" };
					var sacUiPower = new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Power", PowerId = "StrengthPower" };
					var sacUiDmg = new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Damage", TargetSide = "AllEnemies" };
					Check("V0.2.200：牺牲伙伴**只有收益=造成伤害**时才摆「作用对象」（格挡 / 状态挂在自己身上，摆了等于骗人）",
						!sacUiBlock.ShowTargetSideRow && !sacUiPower.ShowTargetSideRow && sacUiDmg.ShowTargetSideRow
						&& !sacUiBlock.ShowsTargetSideSuffix && sacUiDmg.ShowsTargetSideSuffix,
						$"格挡={sacUiBlock.ShowTargetSideRow} / 状态={sacUiPower.ShowTargetSideRow} / 伤害={sacUiDmg.ShowTargetSideRow}");
					Check("V0.2.200：收益=伤害时列表行尾写「→ 全体敌人」（格挡那一档不写「→ 自己」）",
						sacUiDmg.Display.Contains("→ 全体敌人") && !sacUiBlock.Display.Contains("→"),
						sacUiBlock.Display + " ／ " + sacUiDmg.Display);
					// 把收益从「格挡」切成「造成伤害」→ 界面要收到「作用对象那一行该出来了」的通知
					//（漏了 Raise 的话：切档后那一行不出现，用户以为还是不能选）
					var gainRaises = new List<string>();
					PropertyChangedEventHandler gainSpy = (_, ev) => { if (ev.PropertyName is { Length: > 0 } gp) gainRaises.Add(gp); };
					var gainProbe = new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Block" };
					gainProbe.PropertyChanged += gainSpy;
					try { gainProbe.PetSacrificeGain = "Damage"; } finally { gainProbe.PropertyChanged -= gainSpy; }
					Check("V0.2.200：把「收益」从格挡切成造成伤害会通知界面刷新「作用对象」那一行",
						gainRaises.Contains("ShowTargetSideRow") && gainRaises.Contains("ShowsTargetSideSuffix"),
						string.Join("/", gainRaises));

					// 生成端：默认「单体敌人」= 老路（逐字节不变）；其它档按 EmitPerCreature 一只一只打
					CardSpec sacAll = new CardSpec { Name = "骨刺群", ClassName = "UiCheckPetNewSacAll", CardType = "Attack", Cost = 1, InCardPool = true };
					sacAll.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "AllEnemies", PetSummon = "UiCheckPet", PetSacrificeGain = "Damage", PetSacrificeFormula = "Fixed", Amount = 7m });
					string sacAllSrc = CSharpCodeGen.CardSource(petSrc, sacAll, 0);
					Check("V0.2.200：「牺牲伙伴 → 造成伤害」+ 全体敌人 → 对每个可打的敌人各打一下（不再写死 cardPlay.Target）",
						sacAllSrc.Contains("foreach (Creature foe in base.Owner.Creature.CombatState.HittableEnemies)")
						&& sacAllSrc.Contains(".Targeting(foe)")
						&& !sacAllSrc.Contains(".Targeting(cardPlay.Target)")
						&& sacAllSrc.Contains("if (base.Owner.Creature.CombatState is not null)"),
						"按作用对象打");
					Check("V0.2.200：（对照）默认「单体敌人」照旧只打 cardPlay.Target（老存档逐字节不变）",
						sacDmgSrc.Contains(".Targeting(cardPlay.Target)") && !sacDmgSrc.Contains("HittableEnemies"),
						"老路不变");
					Check("V0.2.200：「全体敌人」那一版卡牌 TargetType 变成 AllEnemies（不用玩家再选目标）",
						sacAllSrc.Contains("TargetType.AllEnemies"), "AllEnemies");
					CardSpec sacRand = new CardSpec { Name = "骨刺乱", ClassName = "UiCheckPetNewSacRand", CardType = "Attack", Cost = 1, InCardPool = true };
					sacRand.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "RandomEnemies", PetSummon = "UiCheckPet", PetSacrificeGain = "Damage", PetSacrificeFormula = "Fixed", Amount = 3m, RepeatCount = 2 });
					string sacRandSrc = CSharpCodeGen.CardSource(petSrc, sacRand, 0);
					Check("V0.2.200：+ 随机敌人 → 随机挑，次数 = 「命中次数」（这里 2 次）",
						sacRandSrc.Contains("__foeIdx < 2") && sacRandSrc.Contains("CombatTargets.NextItem(foes)"),
						"随机挑");
					// 卡面描述：打谁也得说对（以前一律印「指定敌人」）
					// 描述在 localization 里（不在卡牌 .cs 里），所以临时把这张卡挂进探针配置再取一次。
					string sacAllLoc;
					{
						petSrc.Cards.Add(sacAll);
						try { sacAllLoc = LocalizationGen.CardsJson(petSrc); }
						finally { petSrc.Cards.Remove(sacAll); }
					}
					Check("V0.2.200：「全体敌人」那一版的卡面描述写「所有敌人」而不是「指定敌人」",
						sacAllLoc.Contains("然后它对所有敌人造成"),
						sacAllLoc.Contains("所有敌人") ? "写对了" : "还写着指定敌人");
				}

				// —— 牺牲伙伴选「固定 N」又填了升级增量 ——
				// 用户实测报过：这种卡一开牌组就是一片空白（牌组界面打不开）。原因：升级增量被写到
				// base.DynamicVars.CalculationBase.UpgradeValueBy(3m)，而「固定 N」声明的是普通
				// BlockVar("PetSacrificeBlock")，**没有 CalculationBase** → 本体按名字取 → KeyNotFoundException
				// （牌组界面的「查看升级」要造升级预览，就炸在这里）。
				CardSpec sacUp = new CardSpec { Name = "献身升级", ClassName = "UiCheckPetNewSacUp", CardType = "Skill", Cost = 1, InCardPool = true };
				sacUp.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Block", PetSacrificeFormula = "Fixed", Amount = 6m, UpgradeAmount = 3m });
				string sacUpSrc = CSharpCodeGen.CardSource(petSrc, sacUp, 0);
				Check("牺牲伙伴（固定 N）+ 升级增量：升级写在**它自己的**变量上（base.DynamicVars[\"PetSacrificeBlock\"]），不再写到没声明的 CalculationBase",
					sacUpSrc.Contains("base.DynamicVars[\"PetSacrificeBlock\"].UpgradeValueBy(3m);")
					&& !sacUpSrc.Contains("CalculationBase"), "升级落点对");
				Check("生成后自检（MissingDynamicVars）：牺牲伙伴固定值的卡「引用的变量全都声明了」",
					CSharpCodeGen.MissingDynamicVars(sacUpSrc).Count == 0,
					string.Join(",", CSharpCodeGen.MissingDynamicVars(sacUpSrc)));
				Check("生成后自检（MissingDynamicVars）：能抓出「引用未声明变量」这种会让牌组界面打不开的代码",
					CSharpCodeGen.MissingDynamicVars("public sealed class X : CardModel {\n"
						+ "protected override IEnumerable<DynamicVar> CanonicalVars => [ new BlockVar(\"PetSacrificeBlock\", 6m, ValueProp.Move) ];\n"
						+ "protected override void OnUpgrade() { base.DynamicVars.CalculationBase.UpgradeValueBy(3m); }\n}")
						.SequenceEqual(new[] { "CalculationBase" }),
					string.Join(",", CSharpCodeGen.MissingDynamicVars("public sealed class X : CardModel {\n"
						+ "protected override IEnumerable<DynamicVar> CanonicalVars => [ new BlockVar(\"PetSacrificeBlock\", 6m, ValueProp.Move) ];\n"
						+ "protected override void OnUpgrade() { base.DynamicVars.CalculationBase.UpgradeValueBy(3m); }\n}")));
				Check("生成后自检（MissingDynamicVars）：正常卡（声明了 Damage/Block2 等）不误报",
					CSharpCodeGen.MissingDynamicVars(CSharpCodeGen.CardSource(petSrc, newMax, 0)).Count == 0
					&& CSharpCodeGen.MissingDynamicVars("CanonicalVars => [ new DamageVar(6m, ValueProp.Move), new DamageVar(\"Damage2\", 6m, ValueProp.Move) ];\n"
						+ "void F() { _ = base.DynamicVars.Damage.BaseValue; _ = base.DynamicVars[\"Damage2\"].BaseValue; }").Count == 0,
					"不误报");

				// ===== 需求 ⑧：牺牲伙伴的收益新增「获得增益 / 减益」那一档 =====
				// 层数复用同一个「收益公式」（固定 N / 最大生命 × 倍率 / 当前生命），状态挂在自己身上；
				// 选的是哪个状态复用「给伙伴施加状态」那一个字段（PowerId）与同一份候选列表。
				Check("牺牲伙伴的收益下拉里有「获得增益 / 减益」这一档（Id = Power）",
					PetSacrificeGains.Any(o => o.Id == "Power" && o.Display.Contains("增益")) && PetSacrificeGains.Count == 3,
					string.Join(" · ", PetSacrificeGains.Select(o => o.Id + "=" + o.Display)));
				CardSpec sacPower = new CardSpec { Name = "献祭得力", ClassName = "UiCheckPetNewSacPower", CardType = "Skill", Cost = 1, InCardPool = true };
				sacPower.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Power", PetSacrificeFormula = "Fixed", Amount = 4m, UpgradeAmount = 2m, PowerId = "StrengthPower" });
				CardSpec sacPowerMul = new CardSpec { Name = "献祭取巧", ClassName = "UiCheckPetNewSacPowerMul", CardType = "Skill", Cost = 1, InCardPool = true };
				sacPowerMul.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Power", PetSacrificeFormula = "MaxHp", PetSacrificeMultiplier = 3m, PowerId = "DexterityPower" });
				string sacPowerSrc = CSharpCodeGen.CardSource(petSrc, sacPower, 0);
				string sacPowerMulSrc = CSharpCodeGen.CardSource(petSrc, sacPowerMul, 0);
				Check("新档「牺牲伙伴 → 获得增益 / 减益」：有它自己的变量（固定 N 走 BlockVar(\"PetSacrificePower\")，升级增量也落在它身上）",
					sacPowerSrc.Contains("new BlockVar(\"PetSacrificePower\", 4m, ValueProp.Move)")
					&& sacPowerSrc.Contains("base.DynamicVars[\"PetSacrificePower\"].UpgradeValueBy(2m);")
					&& CSharpCodeGen.VarNameOf(sacPower.Effects[0]) == "PetSacrificePower"
					&& CSharpCodeGen.MissingDynamicVars(sacPowerSrc).Count == 0,
					"缺失=[" + string.Join(",", CSharpCodeGen.MissingDynamicVars(sacPowerSrc)) + "]");
				Check("新档「牺牲伙伴 → 获得增益 / 减益」：顺序是 先算层数 → 杀宠物 → PowerCmd.Apply<状态>（挂在自己身上），生成的代码里写明了为什么是这个顺序",
					sacPowerSrc.IndexOf("decimal layers = ", StringComparison.Ordinal) >= 0
					&& sacPowerSrc.IndexOf("decimal layers = ", StringComparison.Ordinal) < sacPowerSrc.IndexOf("await CreatureCmd.Kill(__uiCheckPet);", StringComparison.Ordinal)
					&& sacPowerSrc.IndexOf("await CreatureCmd.Kill(__uiCheckPet);", StringComparison.Ordinal) < sacPowerSrc.IndexOf("await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner.Creature, layers, base.Owner.Creature, this);", StringComparison.Ordinal)
					&& sacPowerSrc.Contains("// 先算层数：宠物还活着才取得到它的生命值")
					&& sacPowerSrc.Contains("// 再杀宠物")
					&& sacPowerSrc.Contains("// 最后把状态挂到自己身上")
					&& !sacPowerSrc.Contains("GainBlock") && !sacPowerSrc.Contains("DamageCmd.Attack"),
					"顺序 + 三句注释都在");
				Check("新档「牺牲伙伴 → 获得增益 / 减益」+ 按生命值算：层数走 CalculatedBlock 那套计算变量（本体没有「计算状态层数」的变量），卡面用 {CalculatedBlock:diff()}",
					sacPowerMulSrc.Contains("new CalculatedBlockVar(ValueProp.Move).WithMultiplier(")
					&& sacPowerMulSrc.Contains("decimal layers = base.DynamicVars.CalculatedBlock.Calculate(cardPlay.Target);")
					&& sacPowerMulSrc.Contains("await PowerCmd.Apply<DexterityPower>(choiceContext, base.Owner.Creature, layers, base.Owner.Creature, this);")
					&& CSharpCodeGen.DisplayVarNameOf(sacPowerMul.Effects[0]) == "CalculatedBlock"
					&& CSharpCodeGen.MarkerText(sacPowerMul.Effects[0]) == "PetSacrificePower CET:PetFormula=maxhp CET:PetMul=3m CET:PetPower=DexterityPower",
					CSharpCodeGen.MarkerText(sacPowerMul.Effects[0]));
				// 默认档逐字钉死：加了第三档之后，格挡 / 伤害两档的标记行、变量声明、生成语句一个字符都不许变
				Check("需求 ⑧ 不改默认档：格挡 / 伤害两档的标记行、变量名、生成语句逐字没变",
					CSharpCodeGen.MarkerText(sacBlock.Effects[0]) == "PetSacrificeBlock CET:PetFormula=maxhp CET:PetMul=3m"
					&& CSharpCodeGen.MarkerText(sacDmg.Effects[0]) == "PetSacrificeDamage CET:PetFormula=fixed"
					&& CSharpCodeGen.MarkerText(sacCur.Effects[0]) == "PetSacrificeBlock CET:PetFormula=curhp"
					&& CSharpCodeGen.VarNameOf(sacBlock.Effects[0]) == "PetSacrificeBlock"
					&& CSharpCodeGen.VarNameOf(sacDmg.Effects[0]) == "PetSacrificeDamage"
					&& sacBlockSrc.Contains("// 牺牲小石头换格挡：收益 等于小石头的最大生命 × 3（先算收益、再杀宠物 —— 顺序反了就取不到生命值）")
					&& sacDmgSrc.Contains("// 牺牲小石头换伤害：收益 固定 7 点（先算收益、再杀宠物 —— 顺序反了就取不到生命值）")
					&& sacBlockSrc.Contains("decimal gain = base.DynamicVars.CalculatedBlock.Calculate(cardPlay.Target);")
					&& sacDmgSrc.Contains("decimal dmg = base.DynamicVars[\"PetSacrificeDamage\"].BaseValue;")
					&& sacUpSrc.Contains("new BlockVar(\"PetSacrificeBlock\", 6m, ValueProp.Move)"),
					"标记行：" + CSharpCodeGen.MarkerText(sacBlock.Effects[0]) + " ｜ " + CSharpCodeGen.MarkerText(sacDmg.Effects[0]));

				// ===== 两条同样的「给伙伴施加状态」：第二条声明成别名，运行时必须读同一个别名 =====
				// 用户实测报过（本体的 DynamicVars 按名字取，取不到就 KeyNotFoundException → 牌组界面打不开）：
				// 两条同种效果时 CanonicalVars 里第二条是 PetPowerStrengthPower2（否则 DynamicVarSet 撞名），
				// 而生成代码仍固定读 PetPowerStrengthPower → 生成后自检直接报「引用了没有声明的动态变量」。
				CardSpec petPow2 = new CardSpec { Name = "发力两次", ClassName = "UiCheckPetPow2", CardType = "Skill", Cost = 1, InCardPool = true };
				petPow2.Effects.Add(new EffectSpec { Kind = "PetApplyPower", Amount = 2m, PowerId = "StrengthPower", TargetSide = "Self", PetSummon = "UiCheckPet" });
				petPow2.Effects.Add(new EffectSpec { Kind = "PetApplyPower", Amount = 2m, PowerId = "StrengthPower", TargetSide = "Self", PetSummon = "UiCheckPet" });
				string petPow2Src = CSharpCodeGen.CardSource(petSrc, petPow2, 0);
				Check("两条「给伙伴施加状态」：第二条运行时读的是它的**别名**变量（PetPowerStrengthPower2），不是第一条的名字",
					petPow2Src.Contains("base.DynamicVars[\"PetPowerStrengthPower2\"].BaseValue")
					&& CSharpCodeGen.MissingDynamicVars(petPow2Src).Count == 0,
					"缺失=[" + string.Join(",", CSharpCodeGen.MissingDynamicVars(petPow2Src)) + "]");

				// —— 生成后自检遇到「不认识的那一项」时，只能跳过那一项，不能放弃整张卡 ——
				// 本体 PowerVar.cs 的匿名构造是 base(typeof(T).Name, …)，所以匿名 PowerVar<T> 的键就是 T 的名字。
				// 以前这里写成 return Array.Empty<string>()（整张卡放弃检查）→ 真正的漏声明全被放过。
				Check("生成后自检（MissingDynamicVars）：看不懂的变量类型只跳过那一项，不放弃整张卡（否则真漏报）",
					CSharpCodeGen.MissingDynamicVars(
						"CanonicalVars => [ new PowerVar<StrengthPower>(2m), new SomethingUnknownVar(1m) ];\n"
						+ "void F() { _ = base.DynamicVars.CalculationBase.BaseValue; }")
						.SequenceEqual(new[] { "CalculationBase" }),
					string.Join(",", CSharpCodeGen.MissingDynamicVars(
						"CanonicalVars => [ new PowerVar<StrengthPower>(2m), new SomethingUnknownVar(1m) ];\n"
						+ "void F() { _ = base.DynamicVars.CalculationBase.BaseValue; }")));
				Check("生成后自检（MissingDynamicVars）：匿名 PowerVar<T> 的键按本体规则 = T 的名字，不误报",
					CSharpCodeGen.MissingDynamicVars(
						"CanonicalVars => [ new PowerVar<StrengthPower>(2m) ];\n"
						+ "void F() { _ = base.DynamicVars[\"StrengthPower\"].BaseValue; }").Count == 0,
					"缺失=[" + string.Join(",", CSharpCodeGen.MissingDynamicVars(
						"CanonicalVars => [ new PowerVar<StrengthPower>(2m) ];\n"
						+ "void F() { _ = base.DynamicVars[\"StrengthPower\"].BaseValue; }")) + "]");

				// —— 「全部召唤物」：一条效果按**每一只启用的召唤物**逐只展开（用户要求：下拉加「全选」）——
				CardSpec allPet = new CardSpec { Name = "全体出动", ClassName = "UiCheckPetAll", CardType = "Skill", Cost = 1, InCardPool = true };
				allPet.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, TargetSide = "Self", PetSummon = PetGen.AllId });
				allPet.Effects.Add(new EffectSpec { Kind = "PetHeal", Amount = 5m, UpgradeAmount = 2m, TargetSide = "Self", PetSummon = PetGen.AllId });
				allPet.Effects.Add(new EffectSpec { Kind = "PetGuardOn", TargetSide = "Self", PetSummon = PetGen.AllId });
				string allSrc = CSharpCodeGen.CardSource(petSrc, allPet, 0);
				Check("「全部召唤物」：一条效果按每只宠物各展开一份代码（本例 2 只 → 两次召唤 / 两次治疗 / 两次挂守卫）",
					allSrc.Contains("UiCheckPetCmd.Summon(choiceContext, base.Owner,")
					&& allSrc.Contains("UiCheckPet2Cmd.Summon(choiceContext, base.Owner,")
					&& allSrc.Contains("await CreatureCmd.Heal(__uiCheckPet, base.DynamicVars.Heal.BaseValue);")
					&& allSrc.Contains("await CreatureCmd.Heal(__uiCheckPet2, base.DynamicVars.Heal.BaseValue);")
					&& allSrc.Contains($"await PowerCmd.Apply<{guardName}>(choiceContext, __uiCheckPet, 1m, null, null);")
					&& allSrc.Contains($"await PowerCmd.Apply<{guardName}>(choiceContext, __uiCheckPet2, 1m, null, null);"),
					"两只各来一遍");
				Check("「全部召唤物」：每一份展开都写一行 // CET:PetAll= 标记（回读靠它把多份合并回一条）",
					allSrc.Split(new[] { "// CET:PetAll=" }, StringSplitOptions.None).Length - 1 == 6,
					(allSrc.Split(new[] { "// CET:PetAll=" }, StringSplitOptions.None).Length - 1) + " 行标记（3 条效果 × 2 只 = 6）");
				Check("「全部召唤物」：每只**各自**判在不在场（不在场的那只整段跳过，不会抛异常）",
					allSrc.Contains("if (__uiCheckPet is not null)") && allSrc.Contains("if (__uiCheckPet2 is not null)"), "两只各一层守卫");
				Check("「全部召唤物」：这张牌**自己会召**它们，所以不再被「必须先有伙伴」卡住打不出去",
					!allSrc.Contains("protected override bool IsPlayable"), allSrc.Contains("IsPlayable") ? "还有 IsPlayable 判定" : "没有判定");

				// V0.2.262（用户报「召唤所有召唤物不生效」）：**自定义状态**那条链以前把 "*" 丢给「单只」那套，
				// 认不出来 → 只生成一句「没有可用的召唤物」，一只都不召。
				var allPetPower = new CustomPowerSpec { Name = "全体出动的状态", ClassName = "UiCheckPetAllPower", Enabled = true, Type = "Buff" };
				var allPetTrig = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
				allPetTrig.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, TargetSide = "Self", PetSummon = PetGen.AllId });
				allPetPower.Triggers.Add(allPetTrig);
				petSrc.CustomPowers.Add(allPetPower);
				string allPetPowSrc = CustomPowerGen.Source(petSrc, allPetPower, petSrc.CustomPowers.Count - 1);
				Check("V0.2.262：状态链「召唤伙伴 + 全部召唤物」→ 每只各召一次（不再只写一句「没有可用的召唤物」）",
					allPetPowSrc.Contains("UiCheckPetCmd.Summon(choiceContext, base.Owner.Player,")
					&& allPetPowSrc.Contains("UiCheckPet2Cmd.Summon(choiceContext, base.Owner.Player,"),
					allPetPowSrc.Contains("没有可用的召唤物") ? "还是只写了注释" : "两只都召");
				Check("V0.2.262：状态链「全部召唤物」的两份展开共用同一个 CET:PetAll 组号（回读能合并回一条）",
					System.Text.RegularExpressions.Regex.Matches(allPetPowSrc, "CET:PetAll=p\\d+").Count >= 2,
					"组号标记 " + System.Text.RegularExpressions.Regex.Matches(allPetPowSrc, "CET:PetAll=p\\d+").Count + " 处");
				// 反过来：一张**只让伙伴干活、自己不召**的牌，照旧要有「缺伙伴就打不出去 / 描红框」的判定，
				// 而且「全部召唤物」要用「任意一只在场」的或运算。
				CardSpec allHealOnly = new CardSpec { Name = "全体育疗", ClassName = "UiCheckPetAllHeal", CardType = "Skill", Cost = 1, InCardPool = true };
				allHealOnly.Effects.Add(new EffectSpec { Kind = "PetHeal", Amount = 5m, TargetSide = "Self", PetSummon = PetGen.AllId });
				string allHealSrc = CSharpCodeGen.CardSource(petSrc, allHealOnly, 0);
				Check("「全部召唤物」：不负责召唤时，整张牌的「缺伙伴就打不出去 / 描红框」用「任意一只在场」的或运算",
					allHealSrc.Contains("UiCheckPetCmd.Get(base.Owner) != null || UiCheckPet2Cmd.Get(base.Owner) != null")
					&& allHealSrc.Contains("protected override bool IsPlayable") && allHealSrc.Contains("ShouldGlowRedInternal"),
					"或运算在");

				// 「全部召唤物」+「按生命值算」：一张牌只有一套固定名字的计算变量（CalculatedDamage），
				// 装不下两只各不相同的数字 → 这一档改成**内联**读每只自己的生命值。
				CardSpec allMiss = new CardSpec { Name = "全体绝境", ClassName = "UiCheckPetAllMiss", CardType = "Attack", Cost = 2, InCardPool = true };
				allMiss.Effects.Add(new EffectSpec { Kind = "PetDamageByMissingHp", Amount = 0m, UpgradeAmount = 4m, TargetSide = "Enemy", PetSummon = PetGen.AllId });
				// 同一张牌上再加一条**有升级增量**的伙伴攻击：回读时升级增量必须落在它自己身上
				// （按 CanonicalVars 的顺序对效果 —— 内联的那条不占变量，错位就会把 3 加到计算攻击上）
				allMiss.Effects.Add(new EffectSpec { Kind = "PetAttack", Amount = 7m, UpgradeAmount = 3m, TargetSide = "Enemy", PetSummon = PetGen.AllId });
				string allMissSrc = CSharpCodeGen.CardSource(petSrc, allMiss, 0);
				Check("「全部召唤物」+按生命值算：走**内联**计算（每只各自的 MaxHp - CurrentHp），不碰固定名字的 CalculatedDamage",
					allMissSrc.Contains("(decimal)(__uiCheckPet.MaxHp - __uiCheckPet.CurrentHp)")
					&& allMissSrc.Contains("(decimal)(__uiCheckPet2.MaxHp - __uiCheckPet2.CurrentHp)")
					&& !allMissSrc.Contains("CalculatedDamage")
					&& !allMissSrc.Contains("CalculationBase"), "内联计算");
				Check("「全部召唤物」：同一条「伙伴攻击」也给每只各来一次（FromPetAttacker 两只各一处，共用同一个 PetDamage 变量）",
					allMissSrc.Contains(".FromPetAttacker(__uiCheckPet)")
					&& allMissSrc.Contains(".FromPetAttacker(__uiCheckPet2)")
					&& allMissSrc.Split(new[] { "new DynamicVar(\"PetDamage\", 7m)" }, StringSplitOptions.None).Length - 1 == 1, "两只各一处");
				Check("「全部召唤物」+按生命值算：升级增量内联成 (base.IsUpgraded ? 4m : 0m)（没有 CalculationBase 可抬）",
					allMissSrc.Contains("(base.IsUpgraded ? 4m : 0m)")
					&& !allMissSrc.Contains("CalculationBase.UpgradeValueBy"), "升级内联");

				CardSpec allSac = new CardSpec { Name = "全体献身", ClassName = "UiCheckPetAllSac", CardType = "Skill", Cost = 2, InCardPool = true };
				allSac.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = PetGen.AllId, PetSacrificeGain = "Block", PetSacrificeFormula = "MaxHp", PetSacrificeMultiplier = 3m });
				string allSacSrc = CSharpCodeGen.CardSource(petSrc, allSac, 0);
				Check("「全部召唤物」+牺牲伙伴（按生命值算收益）：每只各自「先算收益再杀自己」（Kill 各自一份）",
					allSacSrc.Contains("(decimal)__uiCheckPet.MaxHp * 3m") && allSacSrc.Contains("(decimal)__uiCheckPet2.MaxHp * 3m")
					&& allSacSrc.Contains("await CreatureCmd.Kill(__uiCheckPet);") && allSacSrc.Contains("await CreatureCmd.Kill(__uiCheckPet2);")
					&& !allSacSrc.Contains("CalculatedBlock"), "两只各自牺牲");

				// —— 生成 → 回读一致性：把这一批卡都加进配置重新生成工程，再回读 ——
				petSrc.Cards.Add(allPet);
				petSrc.Cards.Add(allMiss);
				petSrc.Cards.Add(allSac);
				petSrc.Cards.Add(newMax);
				petSrc.Cards.Add(newCur);
				petSrc.Cards.Add(newMiss);
				petSrc.Cards.Add(newMisc);
				petSrc.Cards.Add(sacBlock);
				petSrc.Cards.Add(sacDmg);
				petSrc.Cards.Add(sacCur);
				petSrc.Cards.Add(sacUp);
				petSrc.Cards.Add(sacPower);
				petSrc.Cards.Add(sacPowerMul);
				var petGenNew = ModGenerator.Generate(petSrc);
				var petRecNew = ProjectRecovery.FromProject(petGenNew.ProjectRoot);
				CardSpec? Rec(string cls) => petRecNew.Profile.Cards.FirstOrDefault(c => c.ClassName == cls);
				Check("从工程恢复：三种「按生命值算」的伙伴攻击都认回来了（Kind + 公式 + 哪一只 + 升级增量）",
					Rec("UiCheckPetNewMax")?.Effects.Any(e => e.Kind == "PetDamageByMaxHp" && e.PetSummon == "UiCheckPet" && e.UpgradeAmount == 3m) == true
					&& Rec("UiCheckPetNewCur")?.Effects.Any(e => e.Kind == "PetDamageByCurHp" && e.TargetSide == "AllEnemies") == true
					&& Rec("UiCheckPetNewMiss")?.Effects.Any(e => e.Kind == "PetDamageByMissingHp" && e.TargetSide == "RandomEnemies" && e.RepeatCount == 2) == true,
					string.Join(" · ", new[] { "UiCheckPetNewMax", "UiCheckPetNewCur", "UiCheckPetNewMiss" }
						.Select(c => c + "=" + string.Join(",", Rec(c)?.Effects.Select(e => e.Kind + "/" + e.Amount + "/" + (e.PetSummon ?? "?") + "/升级" + e.UpgradeAmount) ?? Array.Empty<string>()))));
				Check("从工程恢复：治疗 / 失去生命 / 最大生命 / 施加状态 / 守卫开 / 守卫关 六条都认回来了",
					Rec("UiCheckPetNewMisc")?.Effects.Select(e => e.Kind).SequenceEqual(new[] { "PetHeal", "PetLoseHp", "PetGainMaxHp", "PetApplyPower", "PetGuardOn", "PetGuardOff" }) == true
					&& Rec("UiCheckPetNewMisc")?.Effects[0].Amount == 6m
					&& Rec("UiCheckPetNewMisc")?.Effects[0].UpgradeAmount == 3m
					&& Rec("UiCheckPetNewMisc")?.Effects[3].PowerId == "StrengthPower"
					&& Rec("UiCheckPetNewMisc")?.Effects[3].Amount == 2m,
					string.Join(" · ", Rec("UiCheckPetNewMisc")?.Effects.Select(e => e.Kind + "/" + e.Amount + "/" + e.PowerId) ?? Array.Empty<string>()));
				Check("从工程恢复：牺牲伙伴（格挡 / 最大生命×3）找回来了（收益类型 + 公式 + 倍率 + 哪一只）",
					Rec("UiCheckPetNewSacBlock")?.Effects.Count == 1
					&& Rec("UiCheckPetNewSacBlock")?.Effects.Any(e => e.Kind == "PetSacrifice" && e.PetSacrificeGain == "Block"
						&& e.PetSacrificeFormula == "MaxHp" && e.PetSacrificeMultiplier == 3 && e.PetSummon == "UiCheckPet") == true,
					string.Join(" · ", Rec("UiCheckPetNewSacBlock")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeGain + "/" + e.PetSacrificeFormula) ?? Array.Empty<string>()));
				Check("从工程恢复：牺牲伙伴（伤害 / 固定 7 / 打单体）找回来了 —— 而且只有**一条**（Kill 之后的收尾语句不再多算一条）",
					Rec("UiCheckPetNewSacDmg")?.Effects.Count == 1
					&& Rec("UiCheckPetNewSacDmg")?.Effects.Any(e => e.Kind == "PetSacrifice" && e.PetSacrificeGain == "Damage"
						&& e.PetSacrificeFormula == "Fixed" && e.Amount == 7m && e.TargetSide == "Enemy") == true,
					string.Join(" · ", Rec("UiCheckPetNewSacDmg")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeGain + "/" + e.PetSacrificeFormula + "/" + e.Amount) ?? Array.Empty<string>()));
				Check("从工程恢复：牺牲伙伴（格挡 / 当前生命）找回来了",
					Rec("UiCheckPetNewSacCur")?.Effects.Count == 1
					&& Rec("UiCheckPetNewSacCur")?.Effects.Any(e => e.Kind == "PetSacrifice" && e.PetSacrificeFormula == "CurHp") == true,
					string.Join(" · ", Rec("UiCheckPetNewSacCur")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeFormula) ?? Array.Empty<string>()));
				Check("从工程恢复：牺牲伙伴（固定 N + 升级增量）找回来了，而且升级增量落在它自己身上",
					Rec("UiCheckPetNewSacUp")?.Effects.Count == 1
					&& Rec("UiCheckPetNewSacUp")?.Effects[0].Kind == "PetSacrifice"
					&& Rec("UiCheckPetNewSacUp")?.Effects[0].PetSacrificeFormula == "Fixed"
					&& Rec("UiCheckPetNewSacUp")?.Effects[0].Amount == 6m
					&& Rec("UiCheckPetNewSacUp")?.Effects[0].UpgradeAmount == 3m,
					string.Join(" · ", Rec("UiCheckPetNewSacUp")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeFormula + "/" + e.Amount + "/升级" + e.UpgradeAmount) ?? Array.Empty<string>()));
				Check("从工程恢复：牺牲伙伴（获得状态 / 固定 4 + 升级 2 / 力量）找回来了 —— 收益类型 + 公式 + 状态 + 升级增量",
					Rec("UiCheckPetNewSacPower")?.Effects.Count == 1
					&& Rec("UiCheckPetNewSacPower")?.Effects[0].Kind == "PetSacrifice"
					&& Rec("UiCheckPetNewSacPower")?.Effects[0].PetSacrificeGain == "Power"
					&& Rec("UiCheckPetNewSacPower")?.Effects[0].PetSacrificeFormula == "Fixed"
					&& Rec("UiCheckPetNewSacPower")?.Effects[0].Amount == 4m
					&& Rec("UiCheckPetNewSacPower")?.Effects[0].UpgradeAmount == 2m
					&& Rec("UiCheckPetNewSacPower")?.Effects[0].PowerId == "StrengthPower",
					string.Join(" · ", Rec("UiCheckPetNewSacPower")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeGain + "/" + e.PetSacrificeFormula + "/" + e.Amount + "/升级" + e.UpgradeAmount + "/" + e.PowerId) ?? Array.Empty<string>()));
				Check("从工程恢复：牺牲伙伴（获得状态 / 最大生命×3 / 敏捷）也认回来了（倍率 + 状态）",
					Rec("UiCheckPetNewSacPowerMul")?.Effects.Count == 1
					&& Rec("UiCheckPetNewSacPowerMul")?.Effects[0].PetSacrificeGain == "Power"
					&& Rec("UiCheckPetNewSacPowerMul")?.Effects[0].PetSacrificeFormula == "MaxHp"
					&& Rec("UiCheckPetNewSacPowerMul")?.Effects[0].PetSacrificeMultiplier == 3m
					&& Rec("UiCheckPetNewSacPowerMul")?.Effects[0].PowerId == "DexterityPower",
					string.Join(" · ", Rec("UiCheckPetNewSacPowerMul")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeGain + "/" + e.PetSacrificeFormula + "/" + e.PetSacrificeMultiplier + "/" + e.PowerId) ?? Array.Empty<string>()));
				Check("生成后自检：这一整批卡 + 遗物 + 药水都没有「引用未声明的动态变量」（否则游戏里牌组界面会打不开）",
					!petGenNew.Issues.Any(i => i.Message.Contains("没有声明")),
					string.Join(" ｜ ", petGenNew.Issues.Where(i => i.Message.Contains("没有声明")).Select(i => i.Message)));

				// —— 多模组共存：生成器自己起的固定类名必须带角色类名前缀 ——
				// 本体的 ModelDb 只按**类名**注册模型（忽略命名空间），两个模组各有一个 class Strike /
				// class ForgeExtraTurnPower 就抛 DuplicateModelException，表现是**游戏直接起不来**
				//（用户实测：「mods 里有不同存档构建的角色模组时游戏打不开」）。
				{
					var multi = ProfileFactory.Sample();
					multi.CharacterClass = "Mmod";
					multi.ModId = "MmodMod";
					var nm = Naming.From(multi);
					Check("多模组共存：生成器自己的固定类名全部带角色类名前缀（Strike / Defend / 额外资源量遗物 / Forge* Power）",
						nm.CardClassName(multi, new CardSpec { ClassName = "Strike" }) == "MmodStrike"
						&& nm.CardClassName(multi, new CardSpec { ClassName = "Defend" }) == "MmodDefend"
						&& nm.ExtraResourceRelicClass == "MmodExtraResourceRelic"
						&& nm.ExtraTurnPowerClass == "MmodForgeExtraTurnPower"
						&& nm.GuardianPowerClass == "MmodForgePetGuardianPower"
						&& nm.DelayedPowerClass(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower" }) == "MmodForgeDelayedWeakPower",
						$"{nm.CardClassName(multi, new CardSpec { ClassName = "Strike" })} / {nm.ExtraResourceRelicClass} / {nm.ExtraTurnPowerClass} / {nm.GuardianPowerClass}");
					multi.ExtraResource.Enabled = true;
					string multiDeck = CSharpCodeGen.CharacterSource(multi);
					Check("多模组共存：初始卡组引用的是带前缀的类（ModelDb.Card<MmodStrike>()），遗物同理",
						multiDeck.Contains($"ModelDb.Relic<{nm.ExtraResourceRelicClass}>()")
						&& CSharpCodeGen.ExtraResourceSource(multi).Contains($"public sealed class {nm.ExtraResourceRelicClass} : RelicModel")
						&& CSharpCodeGen.CardSource(multi, new CardSpec { ClassName = "Strike", Name = "打击" }, 0)
							.Contains("public sealed class MmodStrike : CardModel"),
						"初始卡组 / 遗物 / 卡类都带前缀");
					// 手填的英文类名**不**加前缀（那是用户自己的命名，改了会让他的素材 / 存档引用错位）
					Check("多模组共存：用户手填的英文类名保持原样（不加前缀）",
						nm.CardClassName(multi, new CardSpec { ClassName = "MmodCrush" }) == "MmodCrush"
						&& nm.RelicClassName(new RelicSpec { ClassName = "MmodCharm" }, 0) == "MmodCharm", "手填的不动");
				}
				// 多模组撞车检查：同一个存档目录里**另一个存档**的工程有同名模型类时，必须警告
				{
					string tmp = Path.Combine(Path.GetTempPath(), "forge_multimod_" + Guid.NewGuid().ToString("N")[..8]);
					Directory.CreateDirectory(Path.Combine(tmp, "ModB", "cs", "Cards"));
					File.WriteAllText(Path.Combine(tmp, "ModB", "cs", "Cards", "MmodStrike.cs"),
						"namespace B;\npublic sealed class MmodStrike : CardModel { }", new UTF8Encoding(false));
					File.WriteAllText(Path.Combine(tmp, "ModB", "cs", "Mmod.cs"),
						"namespace B;\npublic sealed class Mmod : CharacterModel { }", new UTF8Encoding(false));
					var multiClash = ProfileFactory.Sample();
					multiClash.CharacterClass = "Mmod";
					multiClash.ModId = "MmodMod";
					multiClash.Paths.OutputDir = tmp;
					var multiClashIssues = ProfileValidator.Validate(multiClash);
					Check("多模组撞车检查：别的存档工程里有同名模型类时给警告（并说清是哪条路会炸）",
						multiClashIssues.Any(i => !i.IsError && i.Message.Contains("撞了") && i.Message.Contains("MmodStrike")),
						string.Join(" ｜ ", multiClashIssues.Where(i => i.Message.Contains("撞了")).Select(i => i.Message)));
					Check("多模组撞车检查：撞车的警告里带上另一个存档的目录名（ModB）",
						multiClashIssues.Any(i => i.Message.Contains("「ModB」")),
						string.Join(" ｜ ", multiClashIssues.Where(i => i.Message.Contains("ModB")).Select(i => i.Message)));
					try { Directory.Delete(tmp, true); } catch { /* 清理失败无所谓**/ }
				}
				Check("从工程恢复：「全部召唤物」的多份展开合并回**一条**效果（PetSummon = \"*\"，不会变成好几条）",
					Rec("UiCheckPetAll")?.Effects.Count == 3
					&& Rec("UiCheckPetAll")?.Effects.All(e => PetGen.IsAll(e.PetSummon)) == true
					&& Rec("UiCheckPetAll")?.Effects.Select(e => e.Kind).SequenceEqual(new[] { "SummonPet", "PetHeal", "PetGuardOn" }) == true
					&& Rec("UiCheckPetAll")?.Effects[1].Amount == 5m
					&& Rec("UiCheckPetAll")?.Effects[1].UpgradeAmount == 2m,
					string.Join(" · ", Rec("UiCheckPetAll")?.Effects.Select(e => e.Kind + "/" + (e.PetSummon ?? "?") + "/" + e.Amount) ?? Array.Empty<string>()));
				Check("从工程恢复：「全部召唤物」+按生命值算 也合并回一条（内联的升级增量 4 落回 UpgradeAmount）",
					Rec("UiCheckPetAllMiss")?.Effects.Count == 2
					&& Rec("UiCheckPetAllMiss")?.Effects[0].Kind == "PetDamageByMissingHp"
					&& PetGen.IsAll(Rec("UiCheckPetAllMiss")?.Effects[0].PetSummon)
					&& Rec("UiCheckPetAllMiss")?.Effects[0].UpgradeAmount == 4m
					&& Rec("UiCheckPetAllMiss")?.Effects[1].Kind == "PetAttack"
					&& Rec("UiCheckPetAllMiss")?.Effects[1].Amount == 7m
					&& Rec("UiCheckPetAllMiss")?.Effects[1].UpgradeAmount == 3m,
					string.Join(" · ", Rec("UiCheckPetAllMiss")?.Effects.Select(e => e.Kind + "/" + (e.PetSummon ?? "?") + "/数量" + e.Amount + "/升级" + e.UpgradeAmount) ?? Array.Empty<string>()));
				Check("从工程恢复：「全部召唤物」+牺牲伙伴（最大生命×3）也合并回一条",
					Rec("UiCheckPetAllSac")?.Effects.Count == 1
					&& Rec("UiCheckPetAllSac")?.Effects[0].Kind == "PetSacrifice"
					&& PetGen.IsAll(Rec("UiCheckPetAllSac")?.Effects[0].PetSummon)
					&& Rec("UiCheckPetAllSac")?.Effects[0].PetSacrificeGain == "Block"
					&& Rec("UiCheckPetAllSac")?.Effects[0].PetSacrificeMultiplier == 3m,
					string.Join(" · ", Rec("UiCheckPetAllSac")?.Effects.Select(e => e.Kind + "/" + e.PetSacrificeGain + "/" + (e.PetSummon ?? "?")) ?? Array.Empty<string>()));
				Check("从工程恢复：这一批宠物效果**一条都没漏**（没认出来的语句为 0）", !petRecNew.HasUnparsed,
					petRecNew.Unparsed.Count == 0 ? "全部认出来了" : $"{petRecNew.Unparsed.Count} 条：" + string.Join(" ｜ ", petRecNew.Unparsed.Take(3)));
				//（原先这里还有一条「召唤物卡牌标记 IsPetCard 按内容推回来」的断言 —— 那一页和那个字段都已删除。）

				// —— 校验：必须选到存在且已启用的召唤物 / 收益公式与倍率合法 / 施加状态必须有 PowerId ——
				var badPetCard = new CardSpec { Name = "缺召唤物", ClassName = "UiCheckPetBadRef", Cost = 1 };
				badPetCard.Effects.Add(new EffectSpec { Kind = "PetHeal", Amount = 3m, TargetSide = "Self", PetSummon = "NoSuchPet" });
				petSrc.Cards.Add(badPetCard);
				Check("校验：新效果引用了不存在的召唤物时**报错拦住**（否则生成出来的代码 CS0103）",
					ProfileValidator.Validate(petSrc).Any(i => i.IsError && i.Message.Contains("NoSuchPet")), "有错误");
				petSrc.Cards.Remove(badPetCard);

				var badSac = new CardSpec { Name = "牺牲没选状态", ClassName = "UiCheckPetBadSac", Cost = 1 };
				badSac.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Block", PetSacrificeFormula = "MaxHp", PetSacrificeMultiplier = 0m });
				petSrc.Cards.Add(badSac);
				Check("校验：牺牲伙伴的倍率 ≤ 0 时报错拦住",
					ProfileValidator.Validate(petSrc).Any(i => i.IsError && i.Message.Contains("倍率要大于 0")), "有错误");
				petSrc.Cards.Remove(badSac);

				var badSacPower = new CardSpec { Name = "牺牲没选状态", ClassName = "UiCheckPetBadSacPower", Cost = 1 };
				badSacPower.Effects.Add(new EffectSpec { Kind = "PetSacrifice", TargetSide = "Self", PetSummon = "UiCheckPet", PetSacrificeGain = "Power", PetSacrificeFormula = "Fixed", Amount = 3m });
				petSrc.Cards.Add(badSacPower);
				Check("校验：牺牲伙伴的收益选「获得增益 / 减益」但没选状态时报错拦住（否则生成的 PowerCmd.Apply<> 编译不过）",
					ProfileValidator.Validate(petSrc).Any(i => i.IsError && i.Message.Contains("没有选状态")), "有错误");
				petSrc.Cards.Remove(badSacPower);

				var badPower = new CardSpec { Name = "施加状态没选", ClassName = "UiCheckPetBadPower", Cost = 1 };
				badPower.Effects.Add(new EffectSpec { Kind = "PetApplyPower", Amount = 2m, TargetSide = "Self", PetSummon = "UiCheckPet", PowerId = null });
				petSrc.Cards.Add(badPower);
				Check("校验：「给伙伴施加状态」没选「增益 / 减益」时报错拦住（否则生成的 Apply<> 编译不过）",
					ProfileValidator.Validate(petSrc).Any(i => i.IsError && i.Message.Contains("没有选「增益 / 减益」")), "有错误");
				petSrc.Cards.Remove(badPower);

				var badTwo = new CardSpec { Name = "两条按生命值算", ClassName = "UiCheckPetBadTwo", Cost = 1 };
				badTwo.Effects.Add(new EffectSpec { Kind = "PetDamageByMaxHp", Amount = 0m, TargetSide = "Enemy", PetSummon = "UiCheckPet" });
				badTwo.Effects.Add(new EffectSpec { Kind = "PetDamageByCurHp", Amount = 0m, TargetSide = "Enemy", PetSummon = "UiCheckPet" });
				petSrc.Cards.Add(badTwo);
				Check("校验：一张牌上两条「按生命值算」的宠物效果时报错拦住（本体的计算变量名是固定死的，只能有一条）",
					ProfileValidator.Validate(petSrc).Any(i => i.IsError && i.Message.Contains("只能有一条")), "有错误");
				petSrc.Cards.Remove(badTwo);

				var petPotionNew = new PotionSpec { Name = "宠物药水", ClassName = "UiCheckPetNewPotion", Rarity = "Common" };
				petPotionNew.Effects.Add(new EffectSpec { Kind = "PetHeal", Amount = 3m, TargetSide = "Self", PetSummon = "UiCheckPet" });
				petSrc.Potions.Add(petPotionNew);
				Check("校验：药水里的新宠物效果**报错拦住**（这一档只做卡牌）",
					ProfileValidator.Validate(petSrc).Any(i => i.IsError && i.Message.Contains("药水不支持")), "有错误");
				petSrc.Potions.Remove(petPotionNew);

				// —— 卡面描述（写死数字 = 玩家看到的是错的，所以这里逐句核对）——
				string newLoc = LocalizationGen.CardsJson(petSrc);
				Check("卡面描述：按生命值算的伙伴攻击写的是 {CalculatedDamage:diff()} 占位 + 「此伤害等于伙伴的最大生命值」，**没有写死数字**、也**没有印出内部变量名**",
					newLoc.Contains("此伤害等于[gold]小石头[/gold]的最大生命值。")
					&& newLoc.Contains("此伤害等于[gold]小石头[/gold]的当前生命值。")
					&& newLoc.Contains("此伤害等于[gold]小石头[/gold]的已损失的生命值。")
					&& newLoc.Contains("{CalculatedDamage:diff()}")
					&& !newLoc.Contains("PetMaxHpDamage") && !newLoc.Contains("PetCurHpDamage")
					&& !newLoc.Contains("PetMissingHpDamage"),
					"有 CalculatedDamage=" + newLoc.Contains("{CalculatedDamage:diff()}")
					+ " 内部名残留=" + (newLoc.Contains("PetMaxHpDamage") || newLoc.Contains("PetCurHpDamage") || newLoc.Contains("PetMissingHpDamage")));
				// 六条各自的**实际文案**都放进 detail：FAIL 时一眼看得出是哪一条不对
				//（以前 detail 只有「描述对」三个字，看不出哪条错，白跑一轮）。
				{
					string strengthZh = EffectCatalog.PowerName("StrengthPower");
					var wantTexts = new (string What, string Text)[]
					{
						("治疗", "让[gold]小石头[/gold]回复 {Heal:diff()} 点生命。"),
						("失去生命", "让[gold]小石头[/gold]失去 {HpLoss:diff()} 点生命。"),
						("最大生命", "[gold]小石头[/gold]的最大生命值增加 {MaxHp:diff()} 点（同时回复等量生命）。"),
						("施加状态", $"[gold]小石头[/gold]获得 {{PetPowerStrengthPower:diff()}} 层{strengthZh}。"),
						("守卫开", "[gold]小石头[/gold]开始替主人承伤（主人受到可格挡的攻击伤害时，改由它承担）。"),
						("守卫关", "[gold]小石头[/gold]不再替主人承伤。"),
					};
					List<string> missing = wantTexts.Where((w) => !newLoc.Contains(w.Text, StringComparison.Ordinal))
						.Select((w) => w.What + " → " + w.Text).ToList();
					Check("卡面描述：治疗 / 失去生命 / 最大生命（写明同时回复等量生命）/ 守卫开·关 / 施加状态 都写对了",
						missing.Count == 0,
						missing.Count == 0 ? string.Join(" ｜ ", wantTexts.Select((w) => w.Text))
							: "缺 / 不符：" + string.Join(" ｜ ", missing));
				}
				Check("卡面描述：牺牲伙伴写着「若…存活：它死去，然后你获得…格挡 / 造成…伤害」"
					+ "（按生命值算的收益用真正声明的 CalculatedBlock —— 用内部名字会在卡面印出 {PetSacrificeBlock:diff()}）",
					newLoc.Contains("若[gold]小石头[/gold]存活：它死去，然后你获得{CalculatedBlock:diff()}点[gold]格挡[/gold]。")
					&& newLoc.Contains("若[gold]小石头[/gold]存活：它死去，然后它对指定敌人造成{PetSacrificeDamage:diff()}点伤害。"),
					"C# 里的声明：" + (CSharpCodeGen.DisplayVarNameOf(sacBlock.Effects[0]) + " / " + CSharpCodeGen.DisplayVarNameOf(sacDmg.Effects[0]))
					+ " ｜ 描述里有 CalculatedBlock=" + newLoc.Contains("{CalculatedBlock:diff()}")
					+ " 有 PetSacrificeDamage=" + newLoc.Contains("{PetSacrificeDamage:diff()}")
					+ " 有内部名 PetSacrificeBlock=" + newLoc.Contains("PetSacrificeBlock"));
				Check("卡面描述：牺牲伙伴选「获得增益 / 减益」时写「获得 N 层状态」"
					+ "（固定值用 {PetSacrificePower:diff()}、按生命值算用 {CalculatedBlock:diff()}，状态名跟着「本体状态改写」走）",
					newLoc.Contains("若[gold]小石头[/gold]存活：它死去，然后你获得{PetSacrificePower:diff()}层力量。")
					&& newLoc.Contains("若[gold]小石头[/gold]存活：它死去，然后你获得{CalculatedBlock:diff()}层敏捷。")
					&& !newLoc.Contains("获得{PetSacrificePower:diff()}点[gold]格挡[/gold]"),
					"层力量=" + newLoc.Contains("层力量") + " ｜ 层敏捷=" + newLoc.Contains("层敏捷")
					+ " ｜ 误写成格挡=" + newLoc.Contains("获得{PetSacrificePower:diff()}点[gold]格挡[/gold]"));
				Check("PetAction / IsPetEffect 覆盖了那 10 个新 Kind（否则「召唤物（哪一只）」下拉不会显示）",
					new[] { "PetDamageByMaxHp", "PetDamageByCurHp", "PetDamageByMissingHp", "PetHeal", "PetLoseHp",
						"PetGainMaxHp", "PetSacrifice", "PetApplyPower", "PetGuardOn", "PetGuardOff" }
					.All(k => new EffectSpec { Kind = k }.PetAction && new EffectSpec { Kind = k }.IsPetEffect),
					"10 个都覆盖");
			}
		}
		catch (Exception ex)
		{
			Check("召唤物（整体）", ok: false, ex.GetType().Name + ": " + ex.Message + "  @" + string.Join(" | ", (ex.StackTrace ?? "").Split('\n').Take(4).Select((string s) => s.Trim())));
		}
		finally
		{
			try { Directory.Delete(petRoot, true); } catch { }
		}

		// ===== 动态变量重名（本体 DynamicVarSet 会直接抛异常 → 战斗卡死在第一回合：抽不了牌、结束不了回合）=====
		CardSpec dupVarCard = new CardSpec { Name = "两张伤害变量", ClassName = "UiCheckDupVar", Cost = 2 };
		dupVarCard.Effects.Clear();
		dupVarCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
		dupVarCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 10m, TargetSide = "Enemy", UpgradeAmount = 5m });
		characterProfile16.Cards.Add(dupVarCard);
		string dupText = CSharpCodeGen.CardSource(characterProfile16, dupVarCard, 0);
		Check("同一种动态变量出现两次时会给第二个起别名（本体要求：2 个 BlockVar 必须各自起名）",
			dupText.Contains("new DamageVar(5m, ValueProp.Move)") && dupText.Contains("new DamageVar(\"Damage2\", 10m, ValueProp.Move)"),
			"第二张 DamageVar 带上了名字");
		Check("取值 / 升级 / 描述占位符都用上了别名（否则取不到值）",
			dupText.Contains("base.DynamicVars[\"Damage2\"].BaseValue") && dupText.Contains("base.DynamicVars[\"Damage2\"].UpgradeValueBy(5m)"),
			"DAMAGE2 三处一致");
		Check("同一种变量不会重名（键按本体规则算：有名字用名字，没有用类型默认名）",
			!HasDuplicateVarKeys(dupText), string.Join(" / ", VarKeysOf(dupText)));
		RelicSpec dupVarRelic = new RelicSpec { Name = "双格挡遗物", ClassName = "UiCheckDupVarRelic", Trigger = "PlayerTurnStart" };
		dupVarRelic.Effects.Clear();
		dupVarRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
		dupVarRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 6m });
		characterProfile16.Relics.Add(dupVarRelic);
		string dupRelicText = CSharpCodeGen.RelicSource(characterProfile16, dupVarRelic, 0);
		Check("遗物里的重复变量同样会起别名", dupRelicText.Contains("new BlockVar(\"Block2\", 6m, ValueProp.Move)") && !HasDuplicateVarKeys(dupRelicText),
			string.Join(" / ", VarKeysOf(dupRelicText)));
		PotionSpec dupVarPotion = new PotionSpec { Name = "双抽牌药水", ClassName = "UiCheckDupVarPotion", Rarity = "Common" };
		dupVarPotion.Effects.Clear();
		dupVarPotion.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m });
		dupVarPotion.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 2m });
		characterProfile16.Potions.Add(dupVarPotion);
		string dupPotionText = CSharpCodeGen.PotionSource(characterProfile16, dupVarPotion, 0);
		Check("药水里的重复变量同样会起别名", dupPotionText.Contains("new CardsVar(\"Cards2\", 2)") && !HasDuplicateVarKeys(dupPotionText),
			string.Join(" / ", VarKeysOf(dupPotionText)));
		Check("校验器会提示「同一张牌里同种变量出现多次」（别名是自动的，不用手动改）",
			ProfileValidator.Validate(characterProfile16).Any((ValidationIssue i) => i.Message.Contains("动态变量") || i.Message.Contains("起名字")),
			"有提示（或不需要提示）");

		// ===== ① 格挡 / 回复生命等效果也能打敌人 =====
		Check("遗物稀有度里有「先古」（本体 RelicRarity.Ancient：先古之民给的那些遗物就是这一档）",
			EffectCatalog.RelicRarities.Contains("Ancient")
			&& CSharpCodeGen.RelicSource(ProfileFactory.Sample(), new RelicSpec { Name = "自检先古遗物", ClassName = "UiCheckAncientRelic", Rarity = "Ancient" }, 0)
				.Contains("RelicRarity.Ancient"),
			string.Join(" / ", EffectCatalog.RelicRarities));
		{
			CharacterProfile ancRelicProbe = ProfileFactory.Sample();
			var ancRelic = new RelicSpec
			{
				Name = "自检先古遗物提示", ClassName = "UiCheckAncientRelic2", Rarity = "Ancient", InRelicPool = true, Trigger = "CombatStart",
			};
			ancRelicProbe.Relics.Add(ancRelic);
			Check("校验器：先古遗物还勾着「加入遗物池」→ 提示它不会出现在普通奖励 / 商店（本体机制）",
				ProfileValidator.Validate(ancRelicProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("先古") && i.Message.Contains("不会从普通奖励")),
				ProfileValidator.Validate(ancRelicProbe).FirstOrDefault((ValidationIssue i) => i.Message.Contains("不会从普通奖励"))?.Message ?? "(没提示 ");
		}
		Check("「获得格挡」「回复生命」「失去生命」「最大生命」都能选作用对象",
			EffectCatalog.FindKind("Block").NeedsTarget && EffectCatalog.FindKind("Heal").NeedsTarget
			&& EffectCatalog.FindKind("HpLoss").NeedsTarget && EffectCatalog.FindKind("MaxHp").NeedsTarget, "四种都支持");
		// ===== 作用对象多了「指定队友 / 全部队友」（用户要求：本体 TargetType.AnyAlly / AllAllies） ====
		{
			Check("作用对象候选里有「指定队友 / 全部队友」",
				EffectCatalog.TargetSides.Contains("Ally") && EffectCatalog.TargetSides.Contains("AllAllies"),
				string.Join(" / ", EffectCatalog.TargetSides));
			CharacterProfile allyProbe = ProfileFactory.Sample();
			CardSpec allyCard = new CardSpec { Name = "自检给队友加格挡", ClassName = "UiCheckAllyCard", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			allyCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 6m, TargetSide = "Ally" });
			CardSpec allAllyCard = new CardSpec { Name = "自检全队加格挡", ClassName = "UiCheckAllAlliesCard", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			allAllyCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "AllAllies" });
			CardSpec allyPowerCard = new CardSpec { Name = "自检给队友加力量", ClassName = "UiCheckAllyPower", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			allyPowerCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", Amount = 2m, PowerId = "StrengthPower", TargetSide = "Ally" });
			allyProbe.Cards.Add(allyCard);
			allyProbe.Cards.Add(allAllyCard);
			allyProbe.Cards.Add(allyPowerCard);
			Check("卡牌目标类型跟着作用对象走：指定队友 → AnyAlly、全部队友 → AllAllies（本体卡 BelieveInYou / BladeSymphony 那两档）",
				CSharpCodeGen.TargetTypeOf(allyCard) == "AnyAlly"
				&& CSharpCodeGen.TargetTypeOf(allAllyCard) == "AllAllies"
				&& CSharpCodeGen.TargetTypeOf(allyPowerCard) == "AnyAlly", "三张都对");
			string allySrc = CSharpCodeGen.CardSource(allyProbe, allyCard, 0);
			string allAllySrc = CSharpCodeGen.CardSource(allyProbe, allAllyCard, 0);
			Check("指定队友：用 cardPlay.Target（和指定敌人同一个字段），并写了回读标记 CET:TargetSide=Ally",
				allySrc.Contains("TargetType.AnyAlly") && allySrc.Contains("CET:TargetSide=Ally")
				&& allySrc.Contains("CreatureCmd.GainBlock(cardPlay.Target,"), "对");
			Check("全部队友：遍历**同一边的全部单位**（CombatState.Allies）并排除自己",
				allAllySrc.Contains("base.Owner.Creature.CombatState.Allies.Where(c => c.IsAlive && c != base.Owner.Creature)")
				// V0.2.201：以前用的是 PlayerCreatures —— 那个列表只装 `Player != null` 的单位，
				// 召唤物（只有 PetOwner）不在里面，单人游戏里「除自己」之后一个不剩（等于空转）。
				&& !allAllySrc.Contains("PlayerCreatures"),
				"有循环（Allies，不再是 PlayerCreatures）");
			Check("卡面描述也跟着写「指定队友 / 队友和召唤物」（不再印成「对自己」）",
				LocalizationGen.CardsJson(allyProbe).Contains("指定队友")
				&& LocalizationGen.CardsJson(allyProbe).Contains("队友和所有召唤物"), "文案对");
			var allyIssues = ProfileValidator.Validate(allyProbe);
			Check("校验器提示：指定队友是联机档，单人按本体规则打不出去（不静默）",
				allyIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("打不出去")),
				allyIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("打不出去"))?.Message ?? "(没提示 ");
			// 混用 / 遗物 / 不支持的种类：都要拦住"
			CharacterProfile mixProbe = ProfileFactory.Sample();
			CardSpec mixCard = new CardSpec { Name = "自检混用", ClassName = "UiCheckAllyMix", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			mixCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
			mixCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Ally" });
			mixProbe.Cards.Add(mixCard);
			Check("校验器：同一张牌既打敌人又要指定队友 → 拦住（一张牌只有一个目标类型）",
				ProfileValidator.Validate(mixProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("指定队友") && i.Message.Contains("拆成两张牌")),
				"拦住了");
			CharacterProfile allyRelicProbe = ProfileFactory.Sample();
