						mtGen.Success ? mtGen.ProjectRoot : string.Join(" ｜ ", mtGen.Issues.Where(x => x.IsError).Select(x => x.Message).Take(4)));
					if (mtGen.Success)
					{
						var mtBuild = Sts2CharForge.Core.Build.ModBuilder.Build(mtGen.ProjectRoot, Naming.From(mtProf).ModId,
