				&& EffectCatalog.PowerMechanicNote("StrengthPower") == null, "两条");
			// 顺带钉住「我们的自伤确实是 Unpowered」这条口径（不然上面那段解释就成了空话）
			var selfDmgCard = new CardSpec { Name = "自检自伤", ClassName = "UiCheckSelfDmg", Rarity = "Common", InCardPool = true, Cost = 0, CardType = "Attack" };
			selfDmgCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Self" });
			string selfDmgSrc = CSharpCodeGen.CardSource(ProfileFactory.Sample(), selfDmgCard, 0);
			Check("V0.2.245：卡牌给自己造成伤害用的是 Unpowered（和本体 献血/血墙 同一口径 → 力量/虚弱/翱翔都不吃）",
				selfDmgSrc.Contains("ValueProp.Unpowered"), "Unpowered");

			// ===== V0.2.246（用户报「形态生效、效果没生效」：「多效卡识别不了形态一」）=====
			// 病因：本体 PowerStackType.Single 只是「层数不显示」（注释原文 “Amount is hidden, and is always 1”），
			// 但 PowerCmd.Apply 第二次照样 ModifyAmount(+1) → SetAmount(2)，内部层数真的变 2；
			// 而图上的条件写的是「手刃形态 == 1 层」→ 一旦这个形态被施加过两次，条件不成立、整段效果被跳过
			//（图标还在 ⇒ 看起来就是「形态生效但效果没生效」）。修法：读「只叠一层」的状态时按 0/1 夹取。
			{
				var formProf = ProfileFactory.Sample();
				formProf.CustomPowers.Clear();
				formProf.CustomPowers.Add(new CustomPowerSpec { Name = "自检形态", ClassName = "UiCheckFormSingle", Enabled = true, Single = true });
				formProf.CustomPowers.Add(new CustomPowerSpec { Name = "自检层叠", ClassName = "UiCheckFormMulti", Enabled = true, Single = false });

				ForgeGraphSpec FormProbe(string powerId, bool wireWho)
				{
					var g = new ForgeGraphSpec();
					var trig = new ForgeNodeSpec { Kind = "Trigger" };
					trig.SetField("Timing", ForgeTimings.CardPlayed);
					var pw = new ForgeNodeSpec { Kind = "Power" };
					pw.SetField("PowerId", powerId);
					var rel = new ForgeNodeSpec { Kind = "Relate" };
					rel.SetField("Op", "Eq");
					rel.SetField("Amount", "1");
					var iff = new ForgeNodeSpec { Kind = "If" };
					var dmg = new ForgeNodeSpec { Kind = "Effect" };
					dmg.SetField("Effect", "Damage");
					dmg.SetField("Amount", "5");
					g.Nodes.AddRange(new[] { trig, pw, rel, iff, dmg });
					g.Links.Add(new ForgeLinkSpec { From = trig.Id, To = iff.Id, FromPort = 0, ToPort = 0 });
					g.Links.Add(new ForgeLinkSpec { From = pw.Id, To = rel.Id, FromPort = 0, ToPort = 1 });   // 关系符左值 = 口 1
					g.Links.Add(new ForgeLinkSpec { From = rel.Id, To = iff.Id, FromPort = 0, ToPort = 1 });  // 条件 = 口 1
					g.Links.Add(new ForgeLinkSpec { From = iff.Id, To = dmg.Id, FromPort = 0, ToPort = 0 });  // 是 = 口 0
					if (wireWho)
					{
						var unit = new ForgeNodeSpec { Kind = "Unit" };
						unit.SetField("Pick", "Self");
						g.Nodes.Add(unit);
						g.Links.Add(new ForgeLinkSpec { From = unit.Id, To = pw.Id, FromPort = 0, ToPort = 0 });
					}
					return g;
				}

				var formCard = new CardSpec { Name = "自检形态卡", ClassName = "UiCheckFormCard", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Attack" };
				formCard.IsForged = true;
				formCard.ForgeGraph = FormProbe("UiCheckFormSingle", wireWho: true);
				string singleSrc = CSharpCodeGen.CardSource(formProf, formCard, 0);
				Check("V0.2.246：「只叠一层」的状态按 0/1 夹取（『等于 1 层』不会再因为内部层数变 2 而失效）",
					singleSrc.Contains("<= 0m ? 0m : 1m", StringComparison.Ordinal), "夹取了");

				var multiCard = new CardSpec { Name = "自检层叠卡", ClassName = "UiCheckFormCard2", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Attack" };
				multiCard.IsForged = true;
				multiCard.ForgeGraph = FormProbe("UiCheckFormMulti", wireWho: true);
				formProf.Cards.Add(formCard);
				formProf.Cards.Add(multiCard);
				string multiSrc = CSharpCodeGen.CardSource(formProf, multiCard, 0);
				Check("V0.2.246：（对照）可叠层的状态不加夹取（层数照原样读）",
					!multiSrc.Contains("<= 0m ? 0m : 1m", StringComparison.Ordinal), "仍读原值");

				// 【状态】节点没接【对象】→ 默认读「打出时选中的那个敌人」；校验器要把这件事说出来
				formCard.ForgeGraph = FormProbe("UiCheckFormSingle", wireWho: false);
				var formIssues = ProfileValidator.Validate(formProf);
				Check("V0.2.246：【状态】节点没接【对象】时校验器提示「默认读的是选中那个敌人，不是自己」",
					formIssues.Any((ValidationIssue i) => i.Message.Contains("左边没接【对象】")),
					"提示在");
				formCard.ForgeGraph = FormProbe("UiCheckFormSingle", wireWho: true);
				Check("V0.2.246：（对照）接了【对象】就不再提示",
					!ProfileValidator.Validate(formProf).Any((ValidationIssue i) => i.Message.Contains("左边没接【对象】")), "不提示");
			}

			// ===== V0.2.247（用户要求）：两条新条件 =====
			// ① 「上一张打出的牌带有某关键词」 ② 「上一张打出的牌是某范围（可按组）」
			// 数据源和本体「历史课」一样：History.CardPlaysFinished（按玩家过滤，不限回合），取最后一条的 CardPlay.Card；
			// 范围那一档复用「范围界定」的判据（含每个组）。
			{
				var lcProf = ProfileFactory.Sample();
				lcProf.CardGroups.Clear();
				lcProf.CardGroups.Add(new CardGroupSpec { Id = "uicheckgroup", Name = "自检组" });
				// 组的成员记在**卡**身上（GroupIds），不是组里存卡
				lcProf.Cards.Add(new CardSpec
				{
					Name = "自检组甲", ClassName = "UiCheckLastCardA", Rarity = "Common", InCardPool = true,
					GroupIds = new List<string> { "uicheckgroup" },
				});
				string groupFilter = EffectCatalog.GroupFilterPrefix + "uicheckgroup";

				var lcCard = new CardSpec { Name = "自检上一张", ClassName = "UiCheckLastCard", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Skill" };
				lcProf.Cards.Add(lcCard);
				lcCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Enemy" });
				lcCard.Effects[0].Condition = new ConditionSpec { Kind = "LastCardKeyword", Keyword = "Exhaust" };
				string kwSrc = CSharpCodeGen.CardSource(lcProf, lcCard, 0);
				Check("V0.2.247：「上一张打出的牌带有某关键词」生成的是本体历史里那张牌的 Keywords.Contains（不声明局部变量，防止 CS0128）",
					kwSrc.Contains("History.CardPlaysFinished.LastOrDefault(e => e.CardPlay.Player ==")
					&& kwSrc.Contains(".Keywords.Contains(CardKeyword.Exhaust) == true")
					&& !kwSrc.Contains("__lastCard"), "判据在");

				lcCard.Effects[0].Condition = new ConditionSpec { Kind = "LastCardScope", Scope = "Attack" };
				Check("V0.2.247：「上一张打出的牌是某范围」按类型判（Attack → 上一张牌 .Type == CardType.Attack）",
					CSharpCodeGen.CardSource(lcProf, lcCard, 0).Contains(".Card.Type == CardType.Attack"), "类型判据在");

				// 范围可以填「组」：组里每张牌展开成一条「上一张牌的 Id == …」的判据
				lcCard.Effects[0].Condition = new ConditionSpec { Kind = "LastCardScope", Scope = groupFilter };
				string groupSrc = CSharpCodeGen.CardSource(lcProf, lcCard, 0);
				Check("V0.2.247：「上一张打出的牌是某范围」可以填组（展开成 上一张牌的 .Id == ModelDb.Card<…>().Id）",
					groupSrc.Contains(".Card.Id == ModelDb.Card<") && groupSrc.Contains("UiCheckLastCardA"), "组判据在");

				// 漏填检查：关键词没选 = 错误；范围留空 = 提示（等于没判）
				lcCard.Effects[0].Condition = new ConditionSpec { Kind = "LastCardKeyword", Keyword = "" };
				Check("V0.2.247：关键词没选 → 校验器报错说清（不会静默生成一个恒假条件）",
					ProfileValidator.Validate(lcProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("还没选关键词")), "报错了");
				lcCard.Effects[0].Condition = new ConditionSpec { Kind = "LastCardScope", Scope = "" };
				Check("V0.2.247：范围留空 → 校验器提示「等于没判」",
					ProfileValidator.Validate(lcProf).Any((ValidationIssue i) => i.Message.Contains("这条条件等于没判")), "提示了");
			}

			// 遗物也能用（同一条链的表达式，挂在遗物那个钩子上）
			{
				var lcRelicProf = ProfileFactory.Sample();
				var lcRelic = new RelicSpec { Name = "自检上一张遗物", ClassName = "UiCheckLastCardRelic", Trigger = "PlayerTurnStart" };
				lcRelic.Effects.Clear();
				lcRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				lcRelic.Effects[0].Condition = new ConditionSpec { Kind = "LastCardKeyword", Keyword = "Retain" };
				lcRelicProf.Relics.Add(lcRelic);
				Check("V0.2.247：遗物上也能用「上一张打出的牌带有某关键词」",
					CSharpCodeGen.RelicSource(lcRelicProf, lcRelic, 0).Contains(".Keywords.Contains(CardKeyword.Retain) == true"), "遗物也支持");
			}

			// ===== V0.2.248（用户要求）：「减少指定卡牌类别的费用（类似腐化，刺破帷幕这些）」=====
			// 生成的是本体的 AbstractModel.TryModifyEnergyCostInCombatLate —— 腐化 Corruption /
			// 刺破帷幕 Veilpiercer / 免费攻击 FreeAttackPower 三个本体状态用的是同一个钩子。
			{
				var crProf = ProfileFactory.Sample();
				crProf.CustomPowers.Clear();
				var crPower = new CustomPowerSpec { Name = "自检修道服", ClassName = "UiCheckCostDown", Enabled = true, Type = "Buff" };
				crPower.Triggers.Add(new PowerTriggerSpec { Kind = "TurnStart" });
				crProf.CustomPowers.Add(crPower);

				crPower.CostReduceScope = "";    // 留空 = 不启用
				Check("V0.2.248：（默认）费用修正没配 → 一行都不生成（老存档逐字不变）",
					!CustomPowerGen.Source(crProf, crPower, 0).Contains("TryModifyEnergyCostInCombatLate"), "没生成");

				crPower.CostReduceScope = "Skill";
				crPower.CostReduceAmount = 0m;   // 变成 0 费（腐化那种）
				string zeroSrc = CustomPowerGen.Source(crProf, crPower, 0);
				Check("V0.2.248：「技能牌费用变成 0」（腐化那种）→ 生成 TryModifyEnergyCostInCombatLate + card.Type == Skill + modifiedCost = 0m",
					zeroSrc.Contains("public override bool TryModifyEnergyCostInCombatLate(CardModel card, decimal originalCost, out decimal modifiedCost)")
					&& zeroSrc.Contains("card.Type == CardType.Skill")
					&& zeroSrc.Contains("modifiedCost = 0m;")
					&& zeroSrc.Contains("card.Owner.Creature != base.Owner"), "判据在");

				crPower.CostReduceAmount = 1m;   // -1 费
				string oneSrc = CustomPowerGen.Source(crProf, crPower, 0);
				Check("V0.2.248：填 1 → 减 1 费（Math.Max(0m, originalCost - 1m)，不会变成负费）",
					oneSrc.Contains("modifiedCost = System.Math.Max(0m, originalCost - 1m);"), "减 1");

				crPower.CostReducePerStack = true;
				Check("V0.2.248：勾「按层数」→ 乘以 base.Amount",
					CustomPowerGen.Source(crProf, crPower, 0).Contains("originalCost - base.Amount * 1m"), "按层数");
				crPower.CostReducePerStack = false;

				// 范围可以是「组」：会展开成组里每张牌的 Id 判据
				crProf.CardGroups.Clear();
				crProf.CardGroups.Add(new CardGroupSpec { Id = "costgroup", Name = "减费组" });
				crProf.Cards.Add(new CardSpec { Name = "减费组牌", ClassName = "UiCheckCostCardA", Rarity = "Common", InCardPool = true, GroupIds = new List<string> { "costgroup" } });
				crPower.CostReduceScope = EffectCatalog.GroupFilterPrefix + "costgroup";
				Check("V0.2.248：范围选「组」→ 生成 card.Id == ModelDb.Card<…>().Id 那一串（组内容改了判据跟着变）",
					CustomPowerGen.Source(crProf, crPower, 0).Contains("card.Id == ModelDb.Card<"), "组判据在");

				// 校验器：空组会提醒（不然用户以为减费生效了）
				foreach (var dead in crProf.Cards.Where(c => c.ClassName == "UiCheckCostCardA").ToList()) crProf.Cards.Remove(dead);
				Check("V0.2.248：费用修正选了空组 → 校验器警告「判据永远不成立」",
					ProfileValidator.Validate(crProf).Any((ValidationIssue i) => i.Message.Contains("费用修正") && i.Message.Contains("空组")), "警告了");
			}

			// ===== V0.2.249（用户澄清）：「减少卡牌类别的费用」要的是**效果种类**，不是自定义状态那一页 =====
			{
				var cdProf = ProfileFactory.Sample();
				var cdCard = new CardSpec { Name = "自检减费卡", ClassName = "UiCheckCostDownCard", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Power" };
				cdProf.Cards.Add(cdCard);
				var cdFx = new EffectSpec { Kind = "CostDown", Amount = 0m, SpawnFilter = "Skill" };   // HasCardScope 是只读派生属性（看 SpawnFilter 有没有填）
				cdCard.Effects.Add(cdFx);
				string cdSrc = CSharpCodeGen.CardSource(cdProf, cdCard, 0);
				Check("V0.2.249：效果种类「减少卡牌费用」→ 施加带载荷的内部状态（Create(减几费, 范围档, Id 名单, 只持续本回合)）",
					cdSrc.Contains("PowerCmd.Apply(choiceContext,")
					&& cdSrc.Contains("ForgeCostDownPower.Create(")
					&& cdSrc.Contains("\"Skill\"")
					&& cdSrc.Contains("false)"), "施加在");
				Check("V0.2.249：数值 = 减几费原样传进去（0 = 变成 0 费）",
					cdSrc.Contains("ForgeCostDownPower.Create(0m,"), "传了 0");

				cdFx.CostDownThisTurn = true;
				Check("V0.2.249：勾「只持续本回合」→ Create 最后一个参数是 true",
					CSharpCodeGen.CardSource(cdProf, cdCard, 0).Contains("true)"), "本回合");

				// 范围选「组」→ 生成期展开成那几张牌的 ModelId
				cdProf.CardGroups.Clear();
				cdProf.CardGroups.Add(new CardGroupSpec { Id = "cdgroup", Name = "减费组" });
				cdProf.Cards.Add(new CardSpec { Name = "减费组牌", ClassName = "UiCheckCdA", Rarity = "Common", InCardPool = true, GroupIds = new List<string> { "cdgroup" } });
				cdFx.CostDownThisTurn = false;
				cdFx.SpawnFilter = EffectCatalog.GroupFilterPrefix + "cdgroup";
				Check("V0.2.249：范围选「组」→ 生成的 Id 名单里有组里那张牌（ModelDb.Card<UiCheckCdA>().Id）",
					CSharpCodeGen.CardSource(cdProf, cdCard, 0).Contains("ModelDb.Card<UiCheckCdA>().Id"), "组名单在");

				// 状态类是「按需生成」的：用到了才有文件
				Check("V0.2.249：只有用到这条效果才生成 CostDownPower.cs（没用的存档不多一个文件）",
					CSharpCodeGen.NeedsCostDownPower(cdProf)
					&& !CSharpCodeGen.NeedsCostDownPower(ProfileFactory.Sample()), "按需");
				string cdPower = CSharpCodeGen.CostDownPowerSource(cdProf);
				Check("V0.2.249：那只状态覆写的是本体的 TryModifyEnergyCostInCombatLate（和腐化 / 刺破帷幕同一个钩子），只改自己的牌、最低 0 费",
					cdPower.Contains("TryModifyEnergyCostInCombatLate")
					&& cdPower.Contains("card.Owner?.Creature != base.Owner")
					&& cdPower.Contains("System.Math.Max(0m, originalCost - Reduce)")
					&& cdPower.Contains("Reduce <= 0m ? 0m"), "钩子在");

				// 没选范围 → 校验器警告（不然用户以为整条效果生效了却什么都没减）
				cdFx.SpawnFilter = "";
				Check("V0.2.249：「减少卡牌费用」没选范围 → 校验器警告「一张牌都不会减」",
					ProfileValidator.Validate(cdProf).Any((ValidationIssue i) => i.Message.Contains("减少卡牌费用") && i.Message.Contains("没选范围")), "警告了");

				// ===== V0.2.250（用户问「这个范围怎么不能选组或者特定关键词」）=====
				// 根因：锻造页【效果】模块**压根没有「范围」这一栏**（卡牌页有），所以锻造卡上做不出「只对某一类牌 / 某个组」。
				// 现在图上加了「范围（哪一类牌 / 哪个组）」+「只持续本回合」两栏，候选按当前存档动态取（含自定义关键词组 / 每个组）。
				var cdGate = new ForgeNodeSpec { Kind = "Effect" };
				Check("V0.2.250：锻造图【效果】模块有「范围」这一栏（以前压根没有）",
					ForgeGraphCatalog.All.First(k => k.Id == "Effect").Fields.Any(f => f.Key == "SpawnFilter"),
					"有 SpawnFilter");
				Check("V0.2.250：「范围」只在真的读它的效果上出现（伤害 / 占位不显示；消耗 / 减少卡牌费用 显示）",
					!ForgeCanvas.EffectFieldVisibleForCheck(cdGate, "Damage", "SpawnFilter")
					&& ForgeCanvas.EffectFieldVisibleForCheck(cdGate, "ExhaustCard", "SpawnFilter")
					&& ForgeCanvas.EffectFieldVisibleForCheck(cdGate, "CostDown", "SpawnFilter"),
					"按效果种类显示");
				Check("V0.2.250：「只持续本回合」只有「减少卡牌费用」显示",
					ForgeCanvas.EffectFieldVisibleForCheck(cdGate, "CostDown", "CostDownThisTurn")
					&& !ForgeCanvas.EffectFieldVisibleForCheck(cdGate, "Damage", "CostDownThisTurn"),
					"只给 CostDown");

				// 锻造卡上真的能用：图里摆【触发时机 → 效果(减少卡牌费用, 范围=组)】→ 生成出来要带组名单
				{
					var fProf = ProfileFactory.Sample();
					fProf.CardGroups.Clear();
					fProf.CardGroups.Add(new CardGroupSpec { Id = "fgroup", Name = "锻造组" });
					fProf.Cards.Add(new CardSpec { Name = "锻造组甲", ClassName = "UiCheckFgA", Rarity = "Common", InCardPool = true, GroupIds = new List<string> { "fgroup" } });
					var fCard = new CardSpec { Name = "自检锻造减费", ClassName = "UiCheckFgCostDown", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Skill", IsForged = true };
					fProf.Cards.Add(fCard);
					var fg = new ForgeGraphSpec();
					var fTrig = new ForgeNodeSpec { Kind = "Trigger" };
					fTrig.SetField("Timing", ForgeTimings.CardPlayed);
					var fEff = new ForgeNodeSpec { Kind = "Effect" };
					fEff.SetField("Effect", "CostDown");
					fEff.SetField("Amount", "0");
					fEff.SetField("SpawnFilter", EffectCatalog.GroupFilterPrefix + "fgroup");
					fg.Nodes.AddRange(new[] { fTrig, fEff });
					fg.Links.Add(new ForgeLinkSpec { From = fTrig.Id, To = fEff.Id, FromPort = 0, ToPort = 0 });
					fCard.ForgeGraph = fg;
					string fgSrc = CSharpCodeGen.CardSource(fProf, fCard, 0);
					Check("V0.2.250：锻造卡上「减少卡牌费用 + 范围=组」→ 生成里带组里那张牌的 ModelId（__fgPlayer 上下文）",
						fgSrc.Contains("ForgeCostDownPower.Create(0m,")
						&& fgSrc.Contains("ModelDb.Card<UiCheckFgA>().Id")
						&& fgSrc.Contains("__fgPlayer.Creature"), "锻造链也支持");

					// ===== V0.2.251（用户再问一次「条件增加『上一张打出的牌是某种范围的牌』，范围可以填组」）=====
					// 这条条件 V0.2.247 就有了；这次补的是「图上也要校验」+「下拉候选在 Owner 还没设时也能取到组」。
					// ① 图上的【条件】模块：范围=组 → 生成出来是按组展开的判据
					var fcCard = new CardSpec { Name = "自检锻造条件", ClassName = "UiCheckFgCond", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Attack", IsForged = true };
					fProf.Cards.Add(fcCard);
					var fcg = new ForgeGraphSpec();
					var fcTrig = new ForgeNodeSpec { Kind = "Trigger" };
					fcTrig.SetField("Timing", ForgeTimings.CardPlayed);
					var fcCond = new ForgeNodeSpec { Kind = "Condition" };
					fcCond.SetField("Cond", "LastCardScope");
					fcCond.SetField("Scope", EffectCatalog.GroupFilterPrefix + "fgroup");
					var fcIf = new ForgeNodeSpec { Kind = "If" };
					var fcEff = new ForgeNodeSpec { Kind = "Effect" };
					fcEff.SetField("Effect", "Damage");
					fcEff.SetField("Amount", "6");
					fcg.Nodes.AddRange(new[] { fcTrig, fcCond, fcIf, fcEff });
					fcg.Links.Add(new ForgeLinkSpec { From = fcTrig.Id, To = fcIf.Id, FromPort = 0, ToPort = 0 });
					fcg.Links.Add(new ForgeLinkSpec { From = fcCond.Id, To = fcIf.Id, FromPort = 0, ToPort = 1 });
					fcg.Links.Add(new ForgeLinkSpec { From = fcIf.Id, To = fcEff.Id, FromPort = 0, ToPort = 0 });
					fcCard.ForgeGraph = fcg;
					string fcSrc = CSharpCodeGen.CardSource(fProf, fcCard, 0);
					Check("V0.2.251：锻造【条件】「上一张打出的牌是某种范围的牌 + 范围=组」→ 生成按组展开的判据",
						fcSrc.Contains("CardPlaysFinished.LastOrDefault")
						&& fcSrc.Contains("ModelDb.Card<UiCheckFgA>().Id"), "图上也能填组");

					// ② 图上没填范围 / 关键词 → 校验器要说出来（以前只走 ConditionExpr，没人校验）
					fcCond.SetField("Scope", "");
					var fgIssues = ForgeGraphGen.Issues(fcCard.ForgeGraph, fProf, "Card", "AnyEnemy");
					Check("V0.2.251：锻造【条件】范围留空 → 校验器提示「等于没判」",
						fgIssues.Any(i => i.Message.Contains("范围留空")), "提示在");
					fcCond.SetField("Cond", "LastCardKeyword");
					fcCond.SetField("Keyword", "");
					Check("V0.2.251：锻造【条件】「上一张打出的牌带有某关键词」没选关键词 → 报错（那链永远不执行）",
						ForgeGraphGen.Issues(fcCard.ForgeGraph, fProf, "Card", "AnyEnemy").Any(i => i.Level == "错误" && i.Message.Contains("还没选**关键词**")), "报错了");
				}

				// ===== V0.2.252（用户报「自定义状态为升级手上的状态牌不生效」）=====
				// 真因：本体状态牌 / 诅咒牌 `MaxUpgradeLevel => 0`（不能升级），而生成端「升级卡牌」会像本体
				// 「武装 Armaments」那样用 `c.IsUpgradable` 过滤 → 对状态牌**什么都不做**（不报错、只是没反应）。
				// 以前完全静默。现在：① 校验器说清楚；② 提示「让自己的状态牌能升就勾『可被无限升级』」。
				{
					var upProf = ProfileFactory.Sample();
					var upCard = new CardSpec { Name = "自检升级状态", ClassName = "UiCheckUpStatus", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Skill" };
					upCard.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, SelectPile = "Hand", SpawnFilter = "Status" });
					upProf.Cards.Add(upCard);
					string upSrc = CSharpCodeGen.CardSource(upProf, upCard, 0);
					Check("V0.2.252：「升级卡牌」只会挑能升级的牌（c.IsUpgradable，和本体武装同一个口径）",
						upSrc.Contains("c.IsUpgradable"), "有过滤");
					Check("V0.2.252：范围选「状态牌」时校验器提示「本体状态牌天生不能升级 / 这条效果一件都不会做 / 勾『可被无限升级』」",
						ProfileValidator.Validate(upProf).Any((ValidationIssue i) =>
							i.Message.Contains("天生不能升级") && i.Message.Contains("可被无限升级")),
						string.Join(" ｜ ", ProfileValidator.Validate(upProf).Where(i => i.Message.Contains("升级")).Select(i => i.Message).Take(2)));

					// 修好之后：状态牌勾「可被无限升级」→ 生成的类里 MaxUpgradeLevel 不再是 0，本体就会真的升级它
					var upStatus = new CardSpec
					{
						Name = "自检能升的状态牌", ClassName = "UiCheckUpgradableStatus", Rarity = "Status",
						CardType = "Status", InfinitelyUpgradable = true, InCardPool = false,
					};
					upProf.Cards.Add(upStatus);
					upStatus.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self", UpgradeAmount = 2m });
					string upStatusSrc = CSharpCodeGen.CardSource(upProf, upStatus, 0);
					Check("V0.2.252：状态牌勾了「可被无限升级」→ 生成 MaxUpgradeLevel => int.MaxValue（本体才会真的升级它）",
						upStatusSrc.Contains("public override int MaxUpgradeLevel => int.MaxValue;")
						&& !upStatusSrc.Contains("MaxUpgradeLevel => 0;"), "可升级了");
					upStatus.InfinitelyUpgradable = false;
					Check("V0.2.252：（对照）没勾的状态牌仍然是 MaxUpgradeLevel => 0（和本体粘液一致）",
						CSharpCodeGen.CardSource(upProf, upStatus, 0).Contains("public override int MaxUpgradeLevel => 0;"), "仍然不能升");
				}

				// ===== V0.2.253（用户澄清：是**自定义状态**里的「升级卡牌」升级「能无限升级的状态牌」没效果）=====
				{
					var puProf = ProfileFactory.Sample();
					puProf.CustomPowers.Clear();
					var puPower = new CustomPowerSpec { Name = "自检状态升级", ClassName = "UiCheckPuPower", Enabled = true };
					var puTrig = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
					var puFx = new EffectSpec { Kind = "UpgradeCard", Amount = 1m, SelectPile = "Hand", SpawnFilter = "Status" };
					puTrig.Effects.Add(puFx);
					puPower.Triggers.Add(puTrig);
					puProf.CustomPowers.Add(puPower);
					string puSrc = CustomPowerGen.Source(puProf, puPower, 0);
					Check("V0.2.253：状态里的「升级卡牌」先拦「这个状态挂在没有玩家的生物身上」（以前把 null 传进 GetPile → 运行时炸 / 静默失败）",
						puSrc.Contains("if (base.Owner.Player is null) return;"), "有守卫");
					Check("V0.2.253：状态里的「升级卡牌」仍然只挑能升级的牌（c.IsUpgradable + 范围）",
						puSrc.Contains("c.IsUpgradable") && puSrc.Contains("PileType.Hand.GetPile(base.Owner.Player)"), "判据在");
					// 「全部」那一档以前在状态链里没实现（会被当成随机挑 N 张）
					puFx.CountMode = "All";
					string puAll = CustomPowerGen.Source(puProf, puPower, 0);
					Check("V0.2.253：状态里「升级卡牌 + 全部」→ 生成 foreach 全部升级（不再当成随机挑 N 张）",
						puAll.Contains("foreach (CardModel c in PileType.Hand.GetPile(base.Owner.Player).Cards.Where("), "全部档补上了");
					puFx.CountMode = "Exact";
					// 开调试日志：打出「这一摞里有几张能升级的牌」——「没效果」时一眼看出是不是候选 0 张
					puProf.DebugLog = true;
					Check("V0.2.253：开着调试日志时，状态里的「升级卡牌」会打出「可升级的牌 N 张」",
						CustomPowerGen.Source(puProf, puPower, 0).Contains("可升级的牌"), "日志在");
					puProf.DebugLog = false;
				}

				// ===== V0.2.254（用户报「死焰那张牌是不卡住了，但是灾厄也没上」）=====
				// 真因：死焰的伤害全在**伙伴**身上，而「本张牌这一次打出造成的伤害」（ThisCardDamage）
				// 以前只给**自己打的普通攻击**记账 —— 伙伴攻击没人记账 → 那份公式恒为 0 →
				// 「施加灾厄（数值 = ThisCardDamage）」变成 0 层 = 什么都没上。
				{
					var pdProf = ProfileFactory.Sample();
					pdProf.Summons.Clear();
					pdProf.Summons.Add(new SummonSpec { Enabled = true, Name = "自检伙伴", ClassName = "UiCheckPdPet", Hp = 30 });
					var pdCard = new CardSpec { Name = "自检伙伴伤害记账", ClassName = "UiCheckPdCard", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Attack" };
					pdCard.Effects.Add(new EffectSpec { Kind = "PetAttack", Amount = 3m, RepeatCount = 2, TargetSide = "AllEnemies", PetSummon = "UiCheckPdPet" });
					var pdDoom = new EffectSpec { Kind = "ApplyPower", PowerId = "DoomPower", Amount = 0m, TargetSide = "AllEnemies" };
					pdDoom.AmountFormula = "ThisCardDamage";
					pdCard.Effects.Add(pdDoom);
					pdProf.Cards.Add(pdCard);
					string pdSrc = CSharpCodeGen.CardSource(pdProf, pdCard, 0);
					int atkPos = pdSrc.IndexOf("AttackCommand? __atk", StringComparison.Ordinal);
					int addPos = pdSrc.IndexOf("ForgeThisCardDamage += ", StringComparison.Ordinal);
					int applyPos = pdSrc.IndexOf("PowerCmd.Apply<DoomPower>", StringComparison.Ordinal);
					Check("V0.2.254：伙伴攻击也记「本张牌这一次打出造成的伤害」（接住 AttackCommand → 打完后 ForgeThisCardDamage += 合计）",
						atkPos >= 0 && addPos > atkPos && pdSrc.Contains(".FromPetAttacker("), $"atk={atkPos} add={addPos}");
					Check("V0.2.254：记账发生在「施加灾厄」之前（所以灾厄拿到的是这次伙伴打出的伤害，不是 0）",
						addPos >= 0 && applyPos > addPos, $"add={addPos} apply={applyPos}");

					// 对照：没用到 ThisCardDamage 的伙伴攻击 → 不生成记账（老存档逐字不变）
					var pdCard2 = new CardSpec { Name = "自检伙伴不记账", ClassName = "UiCheckPdCard2", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Attack" };
					pdCard2.Effects.Add(new EffectSpec { Kind = "PetAttack", Amount = 3m, TargetSide = "AllEnemies", PetSummon = "UiCheckPdPet" });
					pdProf.Cards.Add(pdCard2);
					Check("V0.2.254：（对照）没用到 ThisCardDamage 的伙伴攻击不生成记账（生成文本不变）",
						!CSharpCodeGen.CardSource(pdProf, pdCard2, 0).Contains("ForgeThisCardDamage +="), "没生成");
				}

				// ===== 参数（最大生命 / 当前生命）拼进公式时被 `??` 吃掉运算符 =====
				// 用户实测：「参数为最大生命时，造成 参数*0.04 的伤害，结果还是最大生命的伤害」。
				// 真因：参数生成的片段是 `x?.MaxHp ?? 0`（`??` 优先级比 `*` 低），
				// 直接拼进 `* 0.04` 就成了 `x?.MaxHp ?? (0 * 0.04)` = **满血值** ——
				// 卡面那个动态变量（ForgeFormulaDamageVar）就是这么算的。
				// 修法：Emit 拼标识符片段时，凡是带 `??` 的都加一层括号（别的片段原样，生成文本不变）。
				{
					CharacterProfile pmProf = ProfileFactory.Sample();
					pmProf.CustomParams.Clear();
					pmProf.CustomParams.Add(new ParamSpec { Name = "P", Source = ParamSources.MaxHp, Target = ParamTargets.Self });
					var pmCard = new CardSpec
					{
						Name = "自检参数乘小数", ClassName = "UiCheckParamMul", CardType = "Attack", Rarity = "Common",
						Cost = 1, InCardPool = true,
					};
					var pmDmg = new EffectSpec { Kind = "Damage", TargetSide = "Enemy" };
					pmDmg.AmountFormula = "P*0.04";
					pmCard.Effects.Add(pmDmg);
					pmProf.Cards.Add(pmCard);
					string pmSrc = CSharpCodeGen.CardSource(pmProf, pmCard, pmProf.Cards.Count - 1);
					Check("参数=最大生命、公式 P*0.04：卡面数值里 `??` 被括号包住（不然 `x?.MaxHp ?? 0 * 0.04` 等于满血值）",
						pmSrc.Contains(")?.MaxHp ?? 0) * (0.04m)", StringComparison.Ordinal)
						&& !pmSrc.Contains("?? 0 * (0.04m)", StringComparison.Ordinal),
						pmSrc.Contains("?? 0 * (0.04m)", StringComparison.Ordinal) ? "还是被吃掉了" : "包住了");
					Check("参数=最大生命、公式 P*0.04：实际出伤那一句仍是 P×0.04（`__pP * (0.04m)`，本来就没问题）",
						pmSrc.Contains("(__pP * (0.04m))", StringComparison.Ordinal), "对");

					// 红线：不含 `??` 的公式，生成文本不变（X = 当前所有能量）
					var pmCard2 = new CardSpec
					{
						Name = "自检 X 乘二", ClassName = "UiCheckParamX2", CardType = "Attack", Rarity = "Common",
						Cost = 1, InCardPool = true,
					};
					var pmDmg2 = new EffectSpec { Kind = "Damage", TargetSide = "Enemy" };
					pmDmg2.AmountFormula = "X*2";
					pmCard2.Effects.Add(pmDmg2);
					pmProf.Cards.Add(pmCard2);
					string pmSrc2 = CSharpCodeGen.CardSource(pmProf, pmCard2, pmProf.Cards.Count - 1);
					Check("（红线）公式 X*2 里 X 是局部变量、不带 `??` → 不加多余括号（生成文本不变）",
						pmSrc2.Contains("(__X * (2m))", StringComparison.Ordinal)
						&& !pmSrc2.Contains("((__X)", StringComparison.Ordinal),
						pmSrc2.Contains("((__X)", StringComparison.Ordinal) ? "多了括号" : "照旧");
				}

				// ===== 延迟状态类名撞名（用户报的 CS0101 + CS0111：DaqgeForgeDelayedGenRnd 定义了两遍）=====
				// 根因：`Naming.DelayedPowerSuffix` 的类名只带「种类 + 卡 / 随机范围」，
				// 而 `CollectDelayedEffects` 的去重键还带着「生成到哪 / 张数 / 附加处理 / 数值=X」——
				// 两条只在这些栏位上不同的「下回合生效 + 生成卡牌」会被当成两条去生成，
				// 类名却一模一样 ⇒ cs\DelayedPowers.cs 里同一个类写两遍。
				{
					EffectSpec DelayGen(Action<EffectSpec>? tweak = null)
					{
						var e = new EffectSpec
						{
							Kind = "GenerateCard", SpawnCardId = "", SpawnPick = "Random", SpawnFilter = "",
							NextTurn = true, Amount = 1m,
						};
						tweak?.Invoke(e);
						return e;
					}
					var dn = Naming.From(ProfileFactory.Sample());
					Check("延迟状态类名（红线）：栏位全默认时还是老的 …ForgeDelayedGenRnd（老存档生成文本不变）",
						dn.DelayedPowerClass(DelayGen()).EndsWith("ForgeDelayedGenRnd", StringComparison.Ordinal),
						dn.DelayedPowerClass(DelayGen()));
					string dnTo = dn.DelayedPowerClass(DelayGen(e => e.SpawnTo = "Draw"));
					string dnUp = dn.DelayedPowerClass(DelayGen(e => e.SpawnUpgraded = true));
					string dnCnt = dn.DelayedPowerClass(DelayGen(e => e.SpawnChoice = 2m));
					Check("延迟状态类名：只差「生成到哪 / 附加处理 / 张数」→ 类名各自不同（不会再撞成同一个类）",
						dnTo != dn.DelayedPowerClass(DelayGen()) && dnUp != dn.DelayedPowerClass(DelayGen())
						&& dnCnt != dn.DelayedPowerClass(DelayGen()) && dnTo != dnUp && dnUp != dnCnt && dnTo != dnCnt,
						dnTo + " / " + dnUp + " / " + dnCnt);

					// 真生成一遍：DelayedPowers.cs 里不许有重复类名，卡牌里引用的类必须都有定义
					var dupProf = ProfileFactory.Sample();
					var dupCard = new CardSpec
					{
						Name = "自检延迟撞名", ClassName = "UiCheckDelayDup", CardType = "Skill", Rarity = "Common",
						Cost = 1, InCardPool = true,
					};
					dupCard.Effects.Add(DelayGen());
					dupCard.Effects.Add(DelayGen(e => e.SpawnTo = "Draw"));
					dupCard.Effects.Add(DelayGen(e => e.SpawnUpgraded = true));
					dupCard.Effects.Add(DelayGen(e => e.SpawnChoice = 2m));
					dupProf.Cards.Add(dupCard);
					string dupSrc = CSharpCodeGen.DelayedPowersSource(dupProf);
					var dupNames = System.Text.RegularExpressions.Regex
						.Matches(dupSrc, @"public sealed class (\w+) : PowerModel")
						.Select(m => m.Groups[1].Value).ToList();
					var dupRepeats = dupNames.GroupBy(x => x).Where(g => g.Count() > 1).Select(g => g.Key).ToList();
					Check("生成的 DelayedPowers.cs 里没有同名类（以前这里就是 CS0101 / CS0111）",
						dupRepeats.Count == 0,
						dupRepeats.Count == 0 ? dupNames.Count + " 个类，全不重名" : "重复：" + string.Join(" / ", dupRepeats));
					string dupCardSrc = CSharpCodeGen.CardSource(dupProf, dupCard, dupProf.Cards.Count - 1);
					var dupUsed = System.Text.RegularExpressions.Regex.Matches(dupCardSrc, @"\w*ForgeDelayed\w+")
						.Select(m => m.Value)
						.Where(u => u.Contains("Gen") || u.Contains("Copy") || u.Contains("Trans") || u.Contains("Global"))
						.Distinct().ToList();
					var dupMissing = dupUsed.Where(u => !dupNames.Contains(u)).ToList();
					Check("卡牌里引用的延迟类都在 DelayedPowers.cs 里有定义",
						dupMissing.Count == 0 && dupUsed.Count > 0,
						dupMissing.Count == 0 ? "都定义了（" + dupUsed.Count + " 个）" : "缺：" + string.Join(" / ", dupMissing));
				}

				// ===== V0.2.255（用户要求「让状态进组，然后在清空指定状态的效果里可以选组」）=====
				{
					var pgProf = ProfileFactory.Sample();
					pgProf.CardGroups.Clear();
					var pgGroup = new CardGroupSpec { Id = "pggroup", Name = "减益组" };
					pgProf.CardGroups.Add(pgGroup);
					// 组里放两个状态：一个本体（WeakPower）、一个自己的（自定义状态）
					pgGroup.PowerIds = new List<string> { "WeakPower", "UiCheckPgPower" };
					pgProf.CustomPowers.Clear();
					var pgPower = new CustomPowerSpec { Name = "自检组状态", ClassName = "UiCheckPgPower", Enabled = true, Type = "Buff" };
					pgPower.Triggers.Add(new PowerTriggerSpec { Kind = "TurnStart" });
					pgProf.CustomPowers.Add(pgPower);

					var pgCard = new CardSpec { Name = "自检清空组", ClassName = "UiCheckPgClear", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Skill" };
					pgCard.Effects.Add(new EffectSpec { Kind = "ClearPowerOne", Amount = 1m, TargetSide = "Enemy", PowerGroup = "pggroup" });
					pgProf.Cards.Add(pgCard);
					string pgSrc = CSharpCodeGen.CardSource(pgProf, pgCard, 0);
					Check("V0.2.255：「清除指定状态」选组 → 把组里每个状态各展开一句清除（本体状态 + 自己的状态都在）",
						pgSrc.Contains("__clr_WeakPower") && pgSrc.Contains("__clr_UiCheckPgPower")
						&& pgSrc.Contains("清除组里的所有状态"), "组展开了");
					Check("V0.2.255：校验器提示「用的是组「减益组」→ 会把这 2 个状态全部清掉」",
						ProfileValidator.Validate(pgProf).Any((ValidationIssue i) => i.Message.Contains("减益组") && i.Message.Contains("全部")),
						string.Join(" ｜ ", ProfileValidator.Validate(pgProf).Where(i => i.Message.Contains("清除指定状态")).Select(i => i.Message).Take(2)));

					// 空组 → 警告（不然用户以为清掉了）
					pgGroup.PowerIds = new List<string>();
					Check("V0.2.255：组里一个状态都没有 → 校验器警告「什么都不会清」",
						ProfileValidator.Validate(pgProf).Any((ValidationIssue i) => i.Message.Contains("一个状态都没有")), "警告了");

					// 没选组 → 和以前逐字一致（只清那一个状态）
					pgCard.Effects[0].PowerGroup = "";
					pgCard.Effects[0].PowerId = "WeakPower";
					Check("V0.2.255：（对照）没选组 → 生成文本和以前一样（只清那一个状态）",
						CSharpCodeGen.CardSource(pgProf, pgCard, 0).Contains("PowerModel? __clrPower = ")
						&& !CSharpCodeGen.CardSource(pgProf, pgCard, 0).Contains("清除组里的所有状态"), "照旧");
				}

				// ===== V0.2.256（用户报「弹窗 配置解析失败：The JSON value could not be converted to
				// System.String. Path: $.Version」）=====
				// 手写 / 复制粘贴的存档里，本该是字符串的项被写成数字或 true → 以前整份读不进来。
				// 现在宽容：数字 / 布尔按原文当字符串读；我们自己写出去的格式仍然是带引号的字符串。
				{
					var lenProf = ProfileFactory.Sample();
					string lenJson = System.Text.Json.JsonSerializer.Serialize(lenProf, ProfileFactory.JsonOpts);
					Check("V0.2.256：我们自己写出去的存档里 Version 仍然是带引号的字符串（格式不变）",
						lenJson.Contains("\"Version\": \"v1.0.0\""), "格式没变");
					string badJson = lenJson.Replace("\"Version\": \"v1.0.0\"", "\"Version\": 1.5");
					string tmpPath = Path.Combine(Path.GetTempPath(), "uicheck_lenient_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
					try
					{
						File.WriteAllText(tmpPath, badJson);
						bool ok = true; string ver = ""; string err = "";
						try { var back = ProfileFactory.Load(tmpPath); ver = back.Version; }
						catch (Exception ex) { ok = false; err = ex.Message; }
						Check("V0.2.256：存档里 \"Version\": 1.5（数字）也能读进来（以前整份报「配置解析失败」）",
							ok && ver == "1.5", ok ? $"Version={ver}" : err);
					}
					finally { try { File.Delete(tmpPath); } catch { } }
				}

				// ===== V0.2.257（用户报「还是无法选进组」）=====
				// 真因：右边那个「这个组里有哪些状态」是按**选中的组**算的，但切组时只通知了 GroupCardRows，
				// 没通知 GroupPowerRows —— 它一直停在载入时那次求值（空列表），所以右列永远没有可勾的行。
				{
					var gpProf = ProfileFactory.Sample();
					gpProf.CardGroups.Clear();
					var gpGroup = new CardGroupSpec { Id = "gprot", Name = "自检组" };
					gpProf.CardGroups.Add(gpGroup);
					gpProf.CustomPowers.Clear();
					gpProf.CustomPowers.Add(new CustomPowerSpec { Name = "自检状态A", ClassName = "UiCheckGpA", Enabled = true });
					gpProf.CustomPowers.Add(new CustomPowerSpec { Name = "自检状态B", ClassName = "UiCheckGpB", Enabled = true });

					var gpRows = PowerGroupMemberRow.Build(gpProf, gpGroup);
					Check("V0.2.257：状态勾选列表真的能生成行（至少含你自己的两个状态）",
						gpRows.Any(r => r.PowerId == "UiCheckGpA") && gpRows.Any(r => r.PowerId == "UiCheckGpB"),
						$"共 {gpRows.Count} 行");
					Check("V0.2.257：状态勾选列表里也含本体状态（清「一组减益」时要能勾虚弱 / 易伤这类）",
						gpRows.Any(r => r.PowerId == "WeakPower") || EffectCatalog.Powers.Count == 0,
						$"本体状态 {EffectCatalog.Powers.Count} 条");

					// 勾上 = 真的写进组里（并且能读回来）
					MainWindow.SetPowerGroupMembership(gpProf, gpGroup, "UiCheckGpA", true);
					MainWindow.SetPowerGroupMembership(gpProf, gpGroup, "WeakPower", true);
					Check("V0.2.257：勾选「自检状态A / 虚弱」后组里真的记下了",
						gpGroup.PowerIdList.Contains("UiCheckGpA") && gpGroup.PowerIdList.Contains("WeakPower"),
						string.Join(",", gpGroup.PowerIdList));
					Check("V0.2.257：重新生成行时那两个是**已勾选**状态（勾上不会立刻掉回去）",
						PowerGroupMemberRow.Build(gpProf, gpGroup).Where(r => r.PowerId is "UiCheckGpA" or "WeakPower").All(r => r.IsChecked),
						"已勾选");

					// 取消勾选
					MainWindow.SetPowerGroupMembership(gpProf, gpGroup, "UiCheckGpA", false);
					Check("V0.2.257：取消勾选后组里也去掉了",
						!gpGroup.PowerIdList.Contains("UiCheckGpA") && gpGroup.PowerIdList.Contains("WeakPower"),
						string.Join(",", gpGroup.PowerIdList));
				}

				// ===== V0.2.259（用户报「临时护卫加了没用，而且越来越多」）=====
				// 护卫 GuardedPower 本体是 Single + Instanced：层数恒为 1、且每施加一次就是新实例 →
				// 「临时 +1 / 回合结束 -1」只会越堆越多、还撤不干净。这类状态要按**存在性**处理。
				{
					var tpProf = ProfileFactory.Sample();
					var tpCard = new CardSpec { Name = "自检临时护卫", ClassName = "UiCheckTpCard", Rarity = "Common", InCardPool = true, Cost = 1, CardType = "Skill" };
					tpCard.Effects.Add(new EffectSpec { Kind = "TempPower", PowerId = "GuardedPower", Amount = 1m, TargetSide = "Self" });
					tpCard.Effects.Add(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", Amount = 2m, TargetSide = "Self" });
					tpProf.Cards.Add(tpCard);
					string tpSrc = CSharpCodeGen.TempPowersSource(tpProf);
					int gStart = tpSrc.IndexOf("class " + Naming.From(tpProf).TempPowerClass(tpCard.Effects[0]), StringComparison.Ordinal);
					int gEnd = gStart >= 0 ? tpSrc.IndexOf("public sealed class", gStart + 10, StringComparison.Ordinal) : -1;
					string gBody = gStart >= 0 ? tpSrc.Substring(gStart, (gEnd > gStart ? gEnd : tpSrc.Length) - gStart) : "";
					Check("V0.2.259：临时「护卫」（本体 Single 状态）按存在性处理 → 只挂一个，不做 +1 叠层",
						gBody.Contains("if (target.GetPower<GuardedPower>() is null)") && gBody.Contains("Apply<GuardedPower>"),
						gBody.Length == 0 ? "(没生成那个类)" : "存在性语义在");
					Check("V0.2.259：临时「护卫」回合结束是把状态**整个摘掉**，不是按层数撤（以前会撤成 0 / 负数堆实例）",
						gBody.Contains("await PowerCmd.Remove(__back);") && !gBody.Contains("__amount = -base.Amount"),
						gBody.Contains("__amount = -base.Amount") ? "还在按层数撤" : "整个移除");
					Check("V0.2.259：（对照）临时「力量」（Counter 状态）仍然按层数加 / 撤（行为不变）",
						tpSrc.Contains("PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, __amount"), "力量照旧");
				}

				// ===== V0.2.260（用户要求）：先古道具专属勾选 =====
				// 「替换古老牙齿所替换的初始卡牌」/「作为尘封魔典给的先古卡」/「替换欧洛巴斯之触所替换的初始遗物」
				{
					var aiProf = ProfileFactory.Sample();
					var aiAncient = new CardSpec { Name = "自检先古卡", ClassName = "UiCheckAiAncient", CardType = "Skill", Rarity = "Ancient", Cost = 1 };
					aiProf.AncientCards.Add(aiAncient);
					var aiRelic = new RelicSpec { Name = "自检先古遗物", ClassName = "UiCheckAiRelic", Rarity = "Ancient", Trigger = "CombatStart" };
					aiProf.Relics.Add(aiRelic);

					// 都不勾 → 一个文件都不多（生成文本逐字不变）
					Check("V0.2.260：（对照）三个勾都不勾时**不生成** AncientItemPatches（老存档一个文件都不多）",
						!AncientItemPatchGen.Needs(aiProf), "没生成");

					aiAncient.ToothReplace = true;
					aiAncient.DustyTomeGrant = true;
					aiRelic.OrobasReplace = true;
					string aiSrc = AncientItemPatchGen.Source(aiProf);
					Check("V0.2.260：勾了「古老牙齿」→ 生成 Arc…Tooth 前缀，用 SetupForTests 把初始卡 + 这张先古卡定好",
						aiSrc.Contains("typeof(ArchaicTooth)") && aiSrc.Contains("__instance.SetupForTests(starter.ToSerializable(), ancient.ToSerializable())"),
						aiSrc.Length == 0 ? "(没生成)" : "补丁在");
					Check("V0.2.260：勾了「尘封魔典」→ 生成 DustyTome 前缀，直接把 AncientCard 定成这张卡",
						aiSrc.Contains("typeof(DustyTome)") && aiSrc.Contains("__instance.AncientCard = ModelDb.Card<UiCheckAiAncient>().Id"),
						"补丁在");
					Check("V0.2.260：勾了「欧洛巴斯之触」→ 生成 TouchOfOrobas 前缀，初始遗物换成这只",
						aiSrc.Contains("typeof(TouchOfOrobas)") && aiSrc.Contains("SetupForTests(starter.Id, ModelDb.Relic<UiCheckAiRelic>().Id)"),
						"补丁在");
					Check("V0.2.260：每个补丁都先判「这是不是本模组角色」（别的角色 return true 走本体）",
						System.Text.RegularExpressions.Regex.Matches(aiSrc, "Character is not").Count >= 3, "有判断");
					// V0.2.263（用户报「欧罗巴斯的两个遗物都没办法正常生效」+「古老牙齿换出来的先古卡跑进尘封魔典」）：
					// 真正生效的是 AfterObtained，两个都要接过来；另外尘封魔典要排掉我们的「古老牙齿专用」卡
					Check("V0.2.263：古老牙齿 → 还生成 AfterObtained 前缀，直接把那张初始卡 Transform 成这张先古卡",
						aiSrc.Contains("typeof(ArchaicTooth), nameof(ArchaicTooth.AfterObtained)") && aiSrc.Contains("await CardCmd.Transform(starter, ancient);"),
						"AfterObtained 补丁在");
					Check("V0.2.263：欧洛巴斯之触 → 还生成 AfterObtained 前缀，直接 RelicCmd.Replace 成这只",
						aiSrc.Contains("typeof(TouchOfOrobas), nameof(TouchOfOrobas.AfterObtained)") && aiSrc.Contains("await RelicCmd.Replace(starter, replace);"),
						"AfterObtained 补丁在");
					// 「只勾古老牙齿、不勾尘封魔典」的那份配置：尘封魔典的随机池要排掉这张牙齿专用卡
					var aiExProf = ProfileFactory.Sample();
					var aiToothOnly = new CardSpec { Name = "只勾牙齿", ClassName = "UiCheckToothOnly", CardType = "Skill", Rarity = "Ancient", Cost = 1, ToothReplace = true };
					aiExProf.AncientCards.Add(aiToothOnly);
					string aiExSrc = AncientItemPatchGen.Source(aiExProf);
					Check("V0.2.263：尘封魔典的随机池里排掉「古老牙齿专用」的先古卡（本体只排它自己那 5 张）",
						aiExSrc.Contains("DustyTomeExcludePatch") && aiExSrc.Contains("c is not UiCheckToothOnly"),
						aiExSrc.Contains("DustyTomeExcludePatch") ? "排掉了" : "没排（会随机给到牙齿那张）");
					Check("V0.2.260：古老牙齿换掉的初始卡 = 初始卡组里那张（生成里出现 CreateCard<…>(player)）",
						aiSrc.Contains("player.RunState.CreateCard<"), "有");

					// V0.2.264（用户报「被古老牙齿替换的初始卡底下的下拉选项还是只有范例卡」）：
					// 那个下拉的候选按「当前存档的牌」算，但以前从来没 Raise 过 —— ComboBox 只在第一次绑定时取一次，
					// 于是载入别的存档后它一直显示启动时那份（示例）存档的牌。这里钉住「牌表一变就通知」。
					{
						var raiseNames = new List<string>();
						void OnRaised(object? s, System.ComponentModel.PropertyChangedEventArgs ev) => raiseNames.Add(ev.PropertyName ?? "");
						PropertyChanged += OnRaised;
						try { RefreshCardChoices(); }
						finally { PropertyChanged -= OnRaised; }
						Check("V0.2.264：刷新卡牌候选时会通知「ToothStarterChoices」（否则那个下拉一直显示启动时那份示例存档的牌）",
							raiseNames.Contains("ToothStarterChoices"), "通知了 " + raiseNames.Count + " 个项目");
						// 排序：真正的「自己的牌」排在默认项之后；打击 / 防御那种范例牌排到最后
						var ownReal = _profile.AllCards.FirstOrDefault(c => !c.IsVanillaCard && !IsSampleBasic(c));
						if (ownReal is not null)
							Check("V0.2.264：下拉里**自己的牌**排在最前（打击 / 防御那种范例牌排到最后，并标出来）",
								ToothStarterChoices.Count > 1 && ToothStarterChoices[1].Display.Contains(ownReal.Name)
								&& ToothStarterChoices[ToothStarterChoices.Count - 1].Display.Contains("范例牌"),
								ToothStarterChoices.Count > 1 ? ToothStarterChoices[1].Display : "(空)");
					}

					// ===== V0.2.265（用户要求）：音频进组 + 「仅能被下个同组音频顶替」 =====
					{
						var auProf = ProfileFactory.Sample();
						auProf.AudioAssets.Clear();
						auProf.AudioAssets.Add(new AudioAssetSpec { Name = "开场曲", File = @"D:\自检\open.ogg" });
						auProf.AudioAssets.Add(new AudioAssetSpec { Name = "战斗曲", File = @"D:\自检\battle.ogg" });
						string keyOpen = auProf.AudioAssets[0].Key;
						string keyBattle = auProf.AudioAssets[1].Key;
						auProf.CardGroups.Clear();
						var auGroup = new CardGroupSpec { Id = "aubgm", Name = "背景乐" };
						auProf.CardGroups.Add(auGroup);

						// 组页面：音频能勾进组（写进 AudioIds）
						var auRows = AudioGroupMemberRow.Build(auProf, auGroup);
						Check("V0.2.265：音频列表能生成行（存档里上传的每个音频一行）",
							auRows.Count >= 2 && auRows.Any(r => r.AudioKey == keyOpen), $"共 {auRows.Count} 行");
						MainWindow.SetAudioGroupMembership(auProf, auGroup, keyOpen, true);
						MainWindow.SetAudioGroupMembership(auProf, auGroup, keyBattle, true);
						Check("V0.2.265：勾选音频后组里真的记下了（AudioIds）",
							auGroup.AudioIdList.Contains(keyOpen) && auGroup.AudioIdList.Contains(keyBattle),
							string.Join(",", auGroup.AudioIdList));
						Check("V0.2.265：重新生成行时这两个音频是**已勾选**状态",
							AudioGroupMemberRow.Build(auProf, auGroup)
								.Where(r => r.AudioKey == keyOpen || r.AudioKey == keyBattle).All(r => r.IsChecked), "已勾选");
						MainWindow.SetAudioGroupMembership(auProf, auGroup, keyBattle, false);
						Check("V0.2.265：取消勾选后组里也去掉了",
							!auGroup.AudioIdList.Contains(keyBattle) && auGroup.AudioIdList.Contains(keyOpen),
							string.Join(",", auGroup.AudioIdList));

						// 生成端：同组表 + 同组顶替逻辑
						var auCard = new CardSpec { Name = "自检BGM", ClassName = "UiCheckAuCard", CardType = "Skill", Rarity = "Common", Cost = 1 };
						var auFx = new EffectSpec { Kind = "PlaySoundFile", Sfx = keyOpen };
						auFx.SfxReplace = true;
						auFx.SfxSameGroupOnly = true;
						auCard.Effects.Add(auFx);
						auProf.Cards.Add(auCard);
						string auSrc = CSharpCodeGen.SfxRegistrySource(auProf);
						Check("V0.2.265：生成的音频播放器里有「组归属表」和「仅同组可顶替」名单",
							auSrc.Contains("GroupsOf") && auSrc.Contains("SameGroupOnly")
							&& auSrc.Contains($"[\"{keyOpen}\"] = new[]"), auSrc.Length > 0 ? "有" : "(空)");
						Check("V0.2.265：顶替判定写成「勾了同组限制的 → 只有同组才顶替」",
							auSrc.Contains("if (SameGroupOnly.Contains(old.Key) && !SameGroup(old.Key, key)) continue;"), "判定在");
						Check("V0.2.265：只勾「仅同组顶替」也会生成这个文件（不然那条勾等于没生效）",
							CSharpCodeGen.UsesSfxReplace(auProf), "会生成");

						// 校验器：没勾「会被顶替」/ 没进任何组 都要说出来
						var auProf2 = ProfileFactory.Sample();
						auProf2.CardGroups.Clear();
						var auCard2 = new CardSpec { Name = "自检BGM2", ClassName = "UiCheckAuCard2", CardType = "Skill", Rarity = "Common", Cost = 1 };
						var auFx2 = new EffectSpec { Kind = "PlaySoundFile", Sfx = "x.ogg" };
						auFx2.SfxSameGroupOnly = true;
						auCard2.Effects.Add(auFx2);
						auProf2.Cards.Add(auCard2);
						Check("V0.2.265：勾了「仅同组顶替」但没勾「会被顶替」→ 校验器提示",
							ProfileValidator.Validate(auProf2).Any((ValidationIssue i) => i.Message.Contains("没勾") && i.Message.Contains("不会起作用")),
							"提示了");
						auFx2.SfxReplace = true;
						Check("V0.2.265：勾了「仅同组顶替」但音频没进任何组 → 校验器警告",
							ProfileValidator.Validate(auProf2).Any((ValidationIssue i) => i.Message.Contains("没有加入任何组")),
							"警告了");
					}

					// ===== V0.2.266（用户要求）：层数变化细分「上升 / 下降」 =====
					{
						var dirProf = ProfileFactory.Sample();
						string DirSrc(string dir)
						{
							var pw = new CustomPowerSpec { Name = "方向" + dir, ClassName = "UiDir" + (dir.Length == 0 ? "Both" : dir), Enabled = true, Type = "Buff" };
							var tr = new PowerTriggerSpec { Kind = "PowerChanged", PowerId = "StrengthPower", PowerDirection = dir };
							tr.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" });
							pw.Triggers.Add(tr);
							dirProf.CustomPowers.Add(pw);
							return CustomPowerGen.Source(dirProf, pw, dirProf.CustomPowers.Count - 1);
						}
						Check("V0.2.266：状态链「层数变化 + 只要上升」→ 守卫里带 amount > 0m",
							DirSrc("Up").Contains("&& amount > 0m"), "带上上升条件");
						Check("V0.2.266：状态链「层数变化 + 只要下降」→ 守卫里带 amount < 0m",
							DirSrc("Down").Contains("&& amount < 0m"), "带上下降条件");
						Check("V0.2.266：（对照）不选方向 → 守卫里一个 amount 判定都没有（老存档逐字不变）",
							!DirSrc("").Contains("amount > 0m") && !DirSrc("").Contains("amount < 0m"), "没多写");

						// 遗物链
						var dirRelic = new RelicSpec { Name = "方向遗物", ClassName = "UiDirRelic", Trigger = "PowerChanged" };
						dirRelic.TriggerPowerId = "StrengthPower";
						dirRelic.TriggerPowerDirection = "Down";
						dirRelic.Effects.Clear();
						dirRelic.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" });
						dirProf.Relics.Add(dirRelic);
						string relicSrc = CSharpCodeGen.RelicSource(dirProf, dirRelic, 0);
						Check("V0.2.266：遗物链「层数变化 + 只要下降」→ 生成 if (amount >= 0m) return;",
							relicSrc.Contains("if (amount >= 0m) return;"), "遗物也细分了");
						dirRelic.TriggerPowerDirection = "Up";
						Check("V0.2.266：遗物链「层数变化 + 只要上升」→ 生成 if (amount <= 0m) return;",
							CSharpCodeGen.RelicSource(dirProf, dirRelic, 0).Contains("if (amount <= 0m) return;"), "上升版在");
						Check("V0.2.266：下拉候选三项（都算 / 只看上升 / 只看下降）",
							TriggerDirections.Count == 3 && TriggerDirections[1].Id == "Up" && TriggerDirections[2].Id == "Down",
							$"{TriggerDirections.Count} 项");
					}

					// ===== V0.2.267（用户报「自定义参数页监听格挡 + 指定敌人 → 界面稀里糊涂」）=====
					{
						// 「自己的当前格挡」这种实时读数：不可能是别人身上的 → 不显示「从谁身上取」，也不算「指定敌人的…」
						var selfParam = new ParamSpec { Name = "C", Source = "MyBlock", Target = ParamTargets.ChosenEnemy };
						Check("V0.2.267：自己专属的来源（自己的当前格挡）不再保留「指定敌人」",
							selfParam.Target == ParamTargets.Self, selfParam.Target);
						Check("V0.2.267：列表那一行不再印「指定敌人的自己当前格挡」",
							!selfParam.Display.Contains("指定敌人") && selfParam.Display.Contains("自己当前格挡"),
							selfParam.Display);
						Check("V0.2.267：这种来源不显示「从谁身上取」那一栏",
							!selfParam.NeedsTarget && !ParamSources.SelfOnly("CurrentHp"), "藏起来了");
						// 换个来源 → 收回「自己」
						var flip = new ParamSpec { Name = "D", Source = ParamSources.CurrentHp, Target = ParamTargets.ChosenEnemy };
						Check("V0.2.267：（对照）当前血量仍然可以选「指定敌人」",
							flip.NeedsTarget && flip.Display.Contains("指定敌人"), flip.Display);
						flip.Source = "MyBlock";
						Check("V0.2.267：切成「自己的当前格挡」后，目标自动收回「自己」",
							flip.Target == ParamTargets.Self && flip.TargetZh == "自己", flip.Summary);
						// 「减益的个数」要能选目标（以前那一栏被藏起来，列表却印「指定敌人的…」）
						var debuffParam = new ParamSpec { Name = "B", Source = ParamSources.DebuffCount, Target = ParamTargets.ChosenEnemy };
						Check("V0.2.267：「减益的个数」现在会显示「从谁身上取」（以前被藏了）",
							debuffParam.NeedsTarget && debuffParam.Display.Contains("指定敌人"), debuffParam.Display);
						// 金币 / 能量这种也是自己专属
						Check("V0.2.267：金币 / 能量 / 最大能量都算自己专属",
							ParamSources.SelfOnly("Gold") && ParamSources.SelfOnly("Energy") && ParamSources.SelfOnly("MaxEnergy"),
							"都算");
					}

					// V0.2.261（用户问「那我如何决定是哪张牌被替换呢」）：可以先古卡上自己指定「被换掉的那张初始卡」
					var aiStarter = new CardSpec { Name = "自检初始卡", ClassName = "UiCheckAiStarter", CardType = "Attack", Rarity = "Basic", Cost = 1, InStartingDeck = true, StartingCopies = 4 };
					aiProf.Cards.Add(aiStarter);
					Check("V0.2.261：没指定时用「自动」（初始卡组里第一张）",
						AncientItemPatchGen.StarterCardFor(aiProf, aiAncient)?.ClassName == AncientItemPatchGen.StarterCardFor(aiProf)?.ClassName,
						AncientItemPatchGen.StarterCardFor(aiProf, aiAncient)?.Name ?? "(null)");
					aiAncient.ToothStarterClass = Naming.From(aiProf).CardClassName(aiProf, aiStarter);
					string aiSrc2 = AncientItemPatchGen.Source(aiProf);
					Check("V0.2.261：指定了「被换掉的初始卡」→ 生成里用的就是那张（CreateCard<UiCheckAiStarter>）",
						aiSrc2.Contains("player.RunState.CreateCard<UiCheckAiStarter>(player)"), "用的指定那张");
					aiAncient.ToothStarterClass = "ThisCardDoesNotExist";
					Check("V0.2.261：指定的类名找不到 → 自动退回初始卡组第一张 + 校验器给警告",
						!AncientItemPatchGen.Source(aiProf).Contains("CreateCard<ThisCardDoesNotExist>")
						&& ProfileValidator.Validate(aiProf).Any((ValidationIssue i) => i.Message.Contains("找不到") && i.Message.Contains("初始卡组里第一张")),
						"退回了");
					aiAncient.ToothStarterClass = "";

					// 勾两张 → 校验器报错
					var aiAncient2 = new CardSpec { Name = "自检先古卡2", ClassName = "UiCheckAiAncient2", CardType = "Skill", Rarity = "Ancient", Cost = 1, DustyTomeGrant = true };
					aiProf.AncientCards.Add(aiAncient2);
					Check("V0.2.260：两张都勾「尘封魔典」→ 校验器报错（一次只给一张）",
						ProfileValidator.Validate(aiProf).Any((ValidationIssue i) => i.Message.Contains("尘封魔典") && i.Message.Contains("只留一张")),
						"报错了");
				}
			}
		}
		CharacterProfile poisonedProbe = ProfileFactory.Sample();
		CardSpec poisonCardProbe = new CardSpec { Name = "自检中毒卡", ClassName = "UiCheckPoisonHint", Rarity = "Common", InCardPool = true };
		poisonCardProbe.Effects.Clear();
		poisonCardProbe.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "SlowPower", Amount = 20m, TargetSide = "Enemy" });
		poisonedProbe.Cards.Add(poisonCardProbe);
		Check("卡牌上施加「缓慢」也会提醒（卡牌走另一条校验）",
			ProfileValidator.Validate(poisonedProbe).Any((ValidationIssue i) => i.Message.Contains("显示的数字不是层数")),
			"卡牌路径也提醒");
		// 「直接把「缓慢」设成 N%」：本体「缓慢」显示/生效的数字不是层数（= SlowAmount×10），
		// 所以只能直接把它的内部数值写进去（SlowPowerHelper）
		CharacterProfile slowSetProbe = ProfileFactory.Sample();
		CustomPowerSpec slowSetPower = new CustomPowerSpec { Name = "自检缓慢百分比" };
		PowerTriggerSpec slowSetTrigger = new PowerTriggerSpec { Kind = "TurnStart" };
		slowSetTrigger.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "SlowPower", Amount = 1m, SlowPercent = 30m, TargetSide = "AllEnemies" });
		slowSetPower.Triggers.Add(slowSetTrigger);
		slowSetProbe.CustomPowers.Add(slowSetPower);
		CardSpec slowSetCard = new CardSpec { Name = "自检缓慢卡", ClassName = "UiCheckSlowSet", Rarity = "Common", InCardPool = true };
		slowSetCard.Effects.Clear();
		slowSetCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "SlowPower", Amount = 30m, SlowPercent = 30m, TargetSide = "Enemy" });
		slowSetProbe.Cards.Add(slowSetCard);
		string slowSetCardSrc = CSharpCodeGen.CardSource(slowSetProbe, slowSetCard, 0);
		Check("「直接把缓慢设成 30%」：按本体的做法只施加 1 层，然后写它的内部数值",
			slowSetCardSrc.Contains("await PowerCmd.Apply<SlowPower>(choiceContext, cardPlay.Target, 1m, base.Owner.Creature, this)")
			&& slowSetCardSrc.Contains("SlowPowerHelper.SetPercent(cardPlay.Target, 30)"), "1 层 + SetPercent(30)");
		string slowHelperSrc = CSharpCodeGen.SlowPowerHelperSource(slowSetProbe);
		Check("会生成 cs/SlowPowerHelper.cs：直接写 SlowAmount / DisplayAmount，并用反射刷状态栏（InvokeDisplayAmountChanged 是 protected）",
			CSharpCodeGen.NeedsSlowPowerHelper(slowSetProbe) && slowHelperSrc.Contains("InvokeDisplayAmountChanged")
			&& slowHelperSrc.Contains("\"SlowAmount\"") && slowHelperSrc.Contains("\"DisplayAmount\"")
			&& slowHelperSrc.Contains("HarmonyLib.AccessTools.Method"), "助手文件对");
		Check("没配这个选项时不会生成助手文件", !CSharpCodeGen.NeedsSlowPowerHelper(ProfileFactory.Sample()), "不生成");
		Check("描述写成「施加缓慢（受到伤害 +30%）」（层数不再出现在描述里）",
			LocalizationGen.CardsJson(slowSetProbe).Contains("施加缓慢（受到伤害 +30%）。")
			&& LocalizationGen.PowersJson(slowSetProbe).Contains("施加缓慢（受到伤害 +30%）"), "描述对");
		Check("状态触发时机的界面说明也写「施加缓慢（受到伤害 +30%）」",
			PowerTriggers.TriggerWhat(slowSetTrigger).Contains("施加缓慢（受到伤害 +30%）"), PowerTriggers.TriggerWhat(slowSetTrigger));
		var slowSetIssues = ProfileValidator.Validate(slowSetProbe);
		Check("校验器说明「只施加 1 层 + 把内部数值设成 +N%」",
			slowSetIssues.Any((ValidationIssue i) => i.Message.Contains("只施加 1 层")), "有提示");
		CharacterProfile slowOddProbe = ProfileFactory.Sample();
		slowOddProbe.Cards.Add(new CardSpec
		{
			Name = "自检缓慢25",
			ClassName = "UiCheckSlowOdd",
			Rarity = "Common",
			InCardPool = true,
			Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "SlowPower", Amount = 1m, SlowPercent = 25m, TargetSide = "Enemy" } },
		});
		Check("填 25% 会提示按 10% 一档折算成 30%",
			ProfileValidator.Validate(slowOddProbe).Any((ValidationIssue i) => i.Message.Contains("折算成 30%")), "折算提示在");
		CharacterProfile slowWrongProbe = ProfileFactory.Sample();
		slowWrongProbe.Cards.Add(new CardSpec
		{
			Name = "自检缓慢选错状态",
			ClassName = "UiCheckSlowWrong",
			Rarity = "Common",
			InCardPool = true,
			Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = 1m, SlowPercent = 30m, TargetSide = "Enemy" } },
		});
		Check("选了别的状态时提示这个选项会被忽略",
			ProfileValidator.Validate(slowWrongProbe).Any((ValidationIssue i) => i.Message.Contains("这个选项会被忽略")), "忽略提示在");
		DataTemplate? effectTpl = Application.Current?.Resources["EffectCommon"] as DataTemplate;
		string[] effectTplTexts = (effectTpl?.LoadContent() is DependencyObject tplRoot) ? TextsIn(tplRoot).ToArray() : Array.Empty<string>();
		Check("效果编辑面板上有「直接把「缓慢」设成 %」那一行（并且只在选了「缓慢」时显示）",
			effectTplTexts.Any((string t) => t.Contains("直接把「缓慢」设成")) && effectTplTexts.Any((string t) => t.Contains("不是层数")),
			$"模板里 {effectTplTexts.Length} 个文本");
		Check("EffectSpec.IsSlowPower 只在选「缓慢」时为 true",
			new EffectSpec { PowerId = "SlowPower" }.IsSlowPower && !new EffectSpec { PowerId = "PoisonPower" }.IsSlowPower, "判断对");
		// 需求 ⑧ 的界面部分：「牺牲伙伴」的收益选「获得增益 / 减益」时多出一行选状态（复用的是同一个 PowerId 字段）
		Check("效果编辑面板上有「状态（牺牲后获得）」那一行（和「增益 / 减益」共用同一个 PowerId 字段）",
			effectTplTexts.Any((string t) => t.Contains("状态（牺牲后获得）")),
			$"模板里 {effectTplTexts.Length} 个文本");
		Check("EffectSpec.IsPetSacrificePower 只在「牺牲伙伴」且收益 = 获得增益 / 减益 时为 true（那一行显隐绑的就是它）",
			new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Power" }.IsPetSacrificePower
			&& !new EffectSpec { Kind = "PetSacrifice", PetSacrificeGain = "Block" }.IsPetSacrificePower
			&& !new EffectSpec { Kind = "Block" }.IsPetSacrificePower,
			"判断对");
		// ===== 需求 ⑨：效果种类「获得药水」（指定 / 随机）+ 可搜索的「目标药水」栏 =====
		// ① 种类 / 两档 / 候选目录
		Check("效果种类里有「获得药水」（数值 = 瓶数，单位「瓶」，允许填 0）",
			Kinds.Any((EffectKindOption k) => k.Kind == "GainPotion" && k.Display.Contains("获得药水")
				&& k.Unit == "瓶" && k.Min == 0m && k.Max >= 1m),
			string.Join("·", Kinds.Where((EffectKindOption k) => k.Kind == "GainPotion").Select((EffectKindOption k) => $"{k.Kind}/{k.Unit}/{k.Min}~{k.Max}")));
		Check("「获得药水」的两档：指定药水（Fixed，默认）/ 随机药水（Random）",
			PotionPicks.Count == 2 && PotionPicks[0].Id == "Fixed" && PotionPicks[0].Display.Contains("指定药水")
			&& PotionPicks[1].Id == "Random" && PotionPicks[1].Display.Contains("随机"),
			string.Join(" · ", PotionPicks.Select((SpawnPickOption o) => o.Id + "=" + o.Display)));
		Check("「目标药水」的候选 = 本体药水目录（类名 + 中文名），读得到解包工程时非空",
			EffectCatalog.Potions.Count > 0
			&& EffectCatalog.Potions.Any((PotionEntry x) => x.Id == "BlockPotion" && x.Zh == "格挡药水")
			&& EffectCatalog.Potions.Any((PotionEntry x) => x.Display == "格挡药水  (BlockPotion)"),
			$"{EffectCatalog.Potions.Count} 项，例：{EffectCatalog.Potions.FirstOrDefault((PotionEntry x) => x.Id == "BlockPotion")?.Display}");
		Check("药水候选认的是**类名**（本体的 ModelId = Slugify(类名)，所以 BlockPotion ↔ BLOCK_POTION.title）",
			EffectCatalog.FindPotionZh("BlockPotion") == "格挡药水" && EffectCatalog.HasPotion("BlockPotion")
			&& !EffectCatalog.HasPotion("NoSuchPotion"), EffectCatalog.FindPotionZh("BlockPotion"));
		Check("EffectSpec：只有「获得药水」显示那两行；「目标药水」只在指定档显示；列表文字写清哪一瓶",
			new EffectSpec { Kind = "GainPotion" }.UsesPotionOptions
			&& new EffectSpec { Kind = "GainPotion", PotionPick = "Fixed" }.ShowPotionPicker
			&& !new EffectSpec { Kind = "GainPotion", PotionPick = "Random" }.ShowPotionPicker
			&& new EffectSpec { Kind = "GainPotion", PotionPick = "Random" }.IsPotionRandom
			&& !new EffectSpec { Kind = "Block" }.UsesPotionOptions
			&& new EffectSpec { Kind = "GainPotion", PotionId = "BlockPotion" }.Display.Contains("格挡药水")
			&& new EffectSpec { Kind = "GainPotion", PotionPick = "Random" }.Display.Contains("随机"),
			new EffectSpec { Kind = "GainPotion", PotionId = "BlockPotion" }.Display);
		Check("效果编辑面板上有「取药方式（获得药水）」和「目标药水」那两行",
			effectTplTexts.Any((string t) => t.Contains("取药方式（获得药水）")) && effectTplTexts.Any((string t) => t.Contains("目标药水")),
			$"模板里 {effectTplTexts.Length} 个文本");
		// ② 界面：真的长出来的可搜索下拉 + 候选 + 能按中文名搜
		DependencyObject potionUiRoot = SelectTabRoot("卡牌");
		CardSpec potionUiCard = new CardSpec { Name = "自检药水界面", ClassName = "UiCheckPotionUi", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
		potionUiCard.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Fixed", PotionId = "BlockPotion" });
		Profile.Cards.Add(potionUiCard);
		CardList.SelectedItem = potionUiCard;
		CardEffectList.SelectedIndex = 0;
		UpdateLayout();
		var potionSearchBoxes = new List<SearchComboBox>();
		CollectSearchCombos(potionUiRoot, potionSearchBoxes);
		SearchComboBox? potionBox = potionSearchBoxes.FirstOrDefault((SearchComboBox b) =>
			BindingOperations.GetBinding(b, SearchComboBox.SelectedValueProperty)?.Path?.Path == "PotionId");
		Check("找到「目标药水」搜索框（和「目标卡」同构的可搜索下拉）", potionBox != null, $"{potionSearchBoxes.Count} 个搜索框");
		if (potionBox != null)
		{
			Check("「目标药水」里灌的就是本体药水目录",
				potionBox.FilteredCount == EffectCatalog.Potions.Count && EffectCatalog.Potions.Count > 0,
				$"{potionBox.FilteredCount} / 目录 {EffectCatalog.Potions.Count}");
			potionBox.ApplySearch("格挡");
			Check("在「目标药水」里打「格挡」就能搜到「格挡药水」（按中文名搜）",
				potionBox.FilteredCount >= 1 && potionBox.SuggestionTexts.Any((string t) => t.Contains("格挡药水")),
				string.Join(" / ", potionBox.SuggestionTexts.Take(3)));
			potionBox.ApplySearch("");
		}
		var potionCombos = new List<ComboBox>();
		CollectCombos(potionUiRoot, potionCombos);
		ComboBox? potionPickCombo = potionCombos.FirstOrDefault((ComboBox b) =>
			BindingOperations.GetBinding(b, ComboBox.SelectedValueProperty)?.Path?.Path == "PotionPick");
		Check("「取药方式」下拉绑上了 PotionPick，候选就是那两档",
			potionPickCombo != null && potionPickCombo.Items.Count == 2,
			potionPickCombo is null ? "没找到下拉" : $"{potionPickCombo.Items.Count} 项");
		potionUiCard.Effects[0].PotionPick = "Random";
		UpdateLayout();
		Check("切成「随机药水」后「目标药水」那一行收起来（值留着，切回指定档还在）",
			!potionUiCard.Effects[0].ShowPotionPicker && potionUiCard.Effects[0].PotionId == "BlockPotion", "收起来了");
		potionUiCard.Effects[0].PotionPick = "Fixed";
		UpdateLayout();
		Profile.Cards.Remove(potionUiCard);
		RefreshCardChoices();
		UpdateLayout();
		// ③ 校验器：指定档必须选、选错要拦住；随机档只提示（并写明药水栏满的行为）
		CharacterProfile gpBadNoPotion = ProfileFactory.Sample();
		CardSpec gpBadCard = new CardSpec { Name = "自检缺药水", ClassName = "UiCheckPotionBad", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
		gpBadCard.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Fixed" });
		gpBadNoPotion.Cards.Add(gpBadCard);
		Check("校验器：指定档没选「目标药水」→ 错误（生成的是 TryToProcure<类名>，没得填就会编译不过）",
			ProfileValidator.Validate(gpBadNoPotion).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("没选「目标药水」")),
			"错误在");
		CharacterProfile gpBadName = ProfileFactory.Sample();
		CardSpec gpBadNameCard = new CardSpec { Name = "自检错药水", ClassName = "UiCheckPotionBad2", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
		gpBadNameCard.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Fixed", PotionId = "NoSuchPotion" });
		gpBadName.Cards.Add(gpBadNameCard);
		Check("校验器：选的药水类名认不出来 → 错误（不能静默生成一个不存在的类型）",
			ProfileValidator.Validate(gpBadName).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("不是一个本体药水类名")),
			"错误在");
		CharacterProfile gpOkRandom = ProfileFactory.Sample();
		CardSpec gpOkCard = new CardSpec { Name = "自检随机药水", ClassName = "UiCheckPotionOk", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
		gpOkCard.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Random" });
		gpOkRandom.Cards.Add(gpOkCard);
		Check("校验器：随机档不报错，而且提示里写明「药水栏满时什么都不发生」（不静默）",
			!ProfileValidator.Validate(gpOkRandom).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("获得药水"))
			&& ProfileValidator.Validate(gpOkRandom).Any((ValidationIssue i) => i.Message.Contains("随机") && i.Message.Contains("药水栏满")),
			"没问题");
		// ④ 生成 + 回读：四个上下文都放一条，逐条验生成文本与还原
		string gpRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_potion_" + Guid.NewGuid().ToString("N").Substring(0, 8));
		try
		{
			CharacterProfile gpGen = ProfileFactory.Sample();
			gpGen.Paths.OutputDir = gpRoot;
			gpGen.Paths.VanillaProject = Profile.Paths.VanillaProject;
			gpGen.Paths.GameDataDir = Profile.Paths.GameDataDir;
			CardSpec gpFixed = new CardSpec { Name = "自检指定药水", ClassName = "UiCheckPotionFixed", CardType = "Skill", Rarity = "Common", Cost = 0, InCardPool = true };
			gpFixed.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Fixed", PotionId = "BlockPotion" });
			gpGen.Cards.Add(gpFixed);
			CardSpec gpRandom = new CardSpec { Name = "自检随机三瓶", ClassName = "UiCheckPotionRandom", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			gpRandom.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 3m, PotionPick = "Random" });
			gpGen.Cards.Add(gpRandom);
			CardSpec gpZero = new CardSpec { Name = "自检零瓶", ClassName = "UiCheckPotionZero", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			gpZero.Effects.Add(new EffectSpec { Kind = "GainPotion", Amount = 0m, PotionPick = "Fixed", PotionId = "BlockPotion" });
			gpGen.Cards.Add(gpZero);
			// 需求 ⑨ 的回归红线：新种类**不许**动到别的种类的生成文本 ——
			// 这里放一张只用「生成卡牌（指定卡）」的老写法卡，它的标记行必须与需求 ⑨ 之前逐字一致。
			CardSpec gpLegacy = new CardSpec { Name = "自检老生成卡", ClassName = "UiCheckPotionLegacy", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			gpLegacy.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Fixed", SpawnCardId = "Shiv", SpawnTo = "Hand" });
			gpGen.Cards.Add(gpLegacy);
			gpGen.Relics.Add(new RelicSpec
			{
				Name = "自检药水遗物", ClassName = "UiCheckPotionRelic", Rarity = "Common", Trigger = "Obtained",
				Effects = { new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Random" } },
			});
			gpGen.Potions.Add(new PotionSpec
			{
				Name = "自检药水瓶", ClassName = "UiCheckPotionFlask", Rarity = "Common", Usage = "CombatOnly", TargetType = "Self",
				InPotionPool = true,
				Effects = { new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Fixed", PotionId = "FirePotion" } },
			});
			gpGen.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检药水状态", ClassName = "UiCheckPotionPower", Type = "Buff", Enabled = true,
				Triggers =
				{
					new PowerTriggerSpec
					{
						Kind = "TurnStart",
						Effects = { new EffectSpec { Kind = "GainPotion", Amount = 1m, PotionPick = "Fixed", PotionId = "BloodPotion" } },
					},
				},
			});
			Check("（准备）「获得药水」的存档能生成工程（卡牌 / 遗物 / 药水 / 自定义状态四个上下文都放了）",
				ModGenerator.Generate(gpGen).Success, gpRoot);
			string gpFixedSrc = CSharpCodeGen.CardSource(gpGen, gpFixed, 0);
			string gpRandomSrc = CSharpCodeGen.CardSource(gpGen, gpRandom, 0);
			string gpZeroSrc = CSharpCodeGen.CardSource(gpGen, gpZero, 0);
			Check("指定档生成 PotionCmd.TryToProcure<本体药水类名>（泛型重载内部就是 ModelDb.Potion<T>().ToMutable()）",
				gpFixedSrc.Contains("await PotionCmd.TryToProcure<MegaCrit.Sts2.Core.Models.Potions.BlockPotion>(base.Owner);"),
				"有");
			Check("指定档的标记行：有 CET:Effect=GainPotion + CET:Potion=BlockPotion，**没有** CET:PotionPick（默认档不写）",
				gpFixedSrc.Contains("// CET:Effect=GainPotion") && gpFixedSrc.Contains(" CET:Potion=BlockPotion")
				&& !gpFixedSrc.Contains("CET:PotionPick="), "标记对");
			Check("随机档走 PotionFactory（本体「炼制药水」那套：战斗内 / 战斗外两支）+ ToMutable + TryToProcure，并写 CET:PotionPick=Random",
				gpRandomSrc.Contains("MegaCrit.Sts2.Core.Factories.PotionFactory.CreateRandomPotionInCombat(base.Owner, base.Owner.RunState.Rng.CombatPotionGeneration)")
				&& gpRandomSrc.Contains("MegaCrit.Sts2.Core.Factories.PotionFactory.CreateRandomPotionOutOfCombat(base.Owner, base.Owner.RunState.Rng.CombatPotionGeneration)")
				&& gpRandomSrc.Contains("await PotionCmd.TryToProcure(__randPotion.ToMutable(), base.Owner);")
				&& gpRandomSrc.Contains("CET:PotionPick=Random") && !gpRandomSrc.Contains("CET:Potion="), "写法对");
			Check("数值 = 瓶数（3 瓶时套一层 for，变量名 __potionIdx）",
				gpRandomSrc.Contains("for (int __potionIdx = 0; __potionIdx < 3; __potionIdx++)"), "有循环");
			Check("药水栏满 = 什么都不发生，而且生成代码里写明了（不静默）",
				gpFixedSrc.Contains("药水栏满时本体返回 success=false —— 这里什么都不发生"), "写明了");
			Check("卡面描述写明「（药水栏满时不会发生任何事）」+ 指定档写药水中文名",
				LocalizationGen.CardsJson(gpGen).Contains("获得 1 瓶[gold]格挡药水[/gold]（药水栏满时不会发生任何事）。")
				&& LocalizationGen.CardsJson(gpGen).Contains("获得 3 瓶随机药水（药水栏满时不会发生任何事）。"), "描述对");
			Check("「获得药水」不声明动态变量（瓶数写死在代码里）→ 生成后自检没有「引用了没声明的变量」",
				!gpFixedSrc.Contains("new DynamicVar(") && CSharpCodeGen.MissingDynamicVars(gpFixedSrc).Count == 0,
				"缺失=[" + string.Join(",", CSharpCodeGen.MissingDynamicVars(gpFixedSrc)) + "]");
			Check("数值 0 瓶 = 这条效果不显示也不执行（和别的种类同一套规矩）",
				CSharpCodeGen.IsInertZero(gpZero.Effects[0]) && !gpZeroSrc.Contains("TryToProcure")
				&& !LocalizationGen.CardsJson(gpGen).Contains("获得 0 瓶"), "丢掉了");
			Check("需求 ⑨ 不动别的种类：老写法（生成卡牌 / 指定卡）的标记行逐字没变、也不带任何 CET:Potion 项",
				CSharpCodeGen.CardSource(gpGen, gpLegacy, 0).Contains(
					"// CET:SpawnPick=Fixed CET:SpawnFilter=- CET:SpawnChoice=1 CET:SpawnUp=0 CET:SpawnFree=0 CET:SpawnFreeTurn=0 CET:SpawnUpTurn=0")
				&& !CSharpCodeGen.CardSource(gpGen, gpLegacy, 0).Contains("CET:Potion"),
				"老标记行没变");
			// 回读：四个上下文 + 两档都要原样还原
			var gpRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(gpGen));
			Check("回读：没有认不出来的语句", !gpRec.HasUnparsed, gpRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			var gpRecFixed = gpRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckPotionFixed")?.Effects.FirstOrDefault((EffectSpec x) => x.Kind == "GainPotion");
			Check("回读：指定档还原（PotionPick=Fixed + PotionId=BlockPotion）",
				gpRecFixed is not null && gpRecFixed.PotionPick == "Fixed" && gpRecFixed.PotionId == "BlockPotion",
				$"{gpRecFixed?.PotionPick} / {gpRecFixed?.PotionId}");
			var gpRecRandom = gpRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckPotionRandom")?.Effects.FirstOrDefault((EffectSpec x) => x.Kind == "GainPotion");
			Check("回读：随机档还原（PotionPick=Random + 瓶数 3 + PotionId 空）",
				gpRecRandom is not null && gpRecRandom.PotionPick == "Random" && gpRecRandom.Amount == 3m
				&& string.IsNullOrWhiteSpace(gpRecRandom.PotionId),
				$"{gpRecRandom?.PotionPick} / {gpRecRandom?.Amount} / {gpRecRandom?.PotionId ?? "(空)"}");
			var gpRecRelic = gpRec.Profile.Relics.FirstOrDefault((RelicSpec r) => r.ClassName == "UiCheckPotionRelic")?.Effects.FirstOrDefault((EffectSpec x) => x.Kind == "GainPotion");
			Check("回读：遗物「获得时」（没有 choiceContext 的触发时机）那条也还原成随机档",
				gpRecRelic is not null && gpRecRelic.PotionPick == "Random", gpRecRelic?.PotionPick ?? "(没认出来)");
			var gpRecFlask = gpRec.Profile.Potions.FirstOrDefault((PotionSpec x) => x.ClassName == "UiCheckPotionFlask")?.Effects.FirstOrDefault((EffectSpec x) => x.Kind == "GainPotion");
			Check("回读：药水那条还原成指定档 FirePotion",
				gpRecFlask is not null && gpRecFlask.PotionId == "FirePotion", gpRecFlask?.PotionId ?? "(没认出来)");
			var gpRecPower = gpRec.Profile.CustomPowers.FirstOrDefault((CustomPowerSpec cp) => cp.ClassName == "UiCheckPotionPower")
				?.Triggers.SelectMany((PowerTriggerSpec t) => t.Effects).FirstOrDefault((EffectSpec x) => x.Kind == "GainPotion");
			Check("回读：自定义状态触发器里那条也还原成指定档 BloodPotion",
				gpRecPower is not null && gpRecPower.PotionId == "BloodPotion", gpRecPower?.PotionId ?? "(没认出来)");
		}
		finally
		{
			try { if (Directory.Exists(gpRoot)) Directory.Delete(gpRoot, true); } catch { }
		}
		// 「给予卡牌关键词」那两行：只在效果种类 = 给予卡牌关键词 时显示（和「直接把缓慢设成 %」同一套 Visibility 绑定）
		Check("效果编辑面板上有「给予关键词」和「是否为临时关键词」两行（紧跟在「选牌方式」下面）",
			effectTplTexts.Any((string t) => t.Contains("给予关键词"))
			&& effectTplTexts.Any((string t) => t.Contains("是否为临时关键词")),
			$"模板里 {effectTplTexts.Length} 个文本");
		Check("EffectSpec.IsGiveKeyword 只在「给予卡牌关键词」时为 true（那两行显隐绑的就是它）",
			new EffectSpec { Kind = "GiveKeyword" }.IsGiveKeyword && !new EffectSpec { Kind = "Block" }.IsGiveKeyword, "判断对");
		Check("「从哪里选牌」对「给予卡牌关键词」也显示（它也要选手牌 / 抽牌堆 / 弃牌堆）",
			new EffectSpec { Kind = "GiveKeyword" }.UsesSelectPile, "会显示");
		Check("数值 = 0 时列表文字写「自己」，≥1 时写「自己选 / 随机 N 张」",
			new EffectSpec { Kind = "GiveKeyword", Amount = 0m, GivenKeyword = "Retain" }.Display.Contains("自己")
			&& new EffectSpec { Kind = "GiveKeyword", Amount = 2m, GivenKeyword = "Retain", CardPick = "Random" }.Display.Contains("随机 2 张"),
			new EffectSpec { Kind = "GiveKeyword", Amount = 2m, GivenKeyword = "Retain", CardPick = "Random" }.Display);
		// 「生效次数 = 3」+ 随机目标：以前会生成两层 for (int i…) → CS0136 编译不过（用户实测踩过）
		CharacterProfile loopProbe = ProfileFactory.Sample();
		CardSpec loopCard = new CardSpec { Name = "自检多层随机", ClassName = "UiCheckNestedLoop", Rarity = "Common", InCardPool = true };
		loopCard.Effects.Clear();
		// 用「失去生命」（走 EmitPerCreature 那条随机目标的路，就是用户踩到的那张牌）
		loopCard.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 6m, TargetSide = "RandomEnemies", Times = 3 });
		loopProbe.Cards.Add(loopCard);
		string loopSrc = CSharpCodeGen.CardSource(loopProbe, loopCard, 0);
		Check("「生效次数 = 3」+ 随机目标：不会再生成两层同名 for (int i)（CS0136 编译不过）",
			loopSrc.Split("for (int i =").Length - 1 == 1 && loopSrc.Contains("for (int __foeIdx = 0; __foeIdx < 1"),
			$"for (int i 出现 {loopSrc.Split("for (int i =").Length - 1} 次，__foeIdx={(loopSrc.Contains("__foeIdx") ? "有" : "没有")}");
		Check("每条效果都包在自己的作用域里（里面的临时变量不会和别的效果撞名）",
			System.Text.RegularExpressions.Regex.IsMatch(loopSrc, @"for \(int i = 0; i < 3; i\+\+\) \{\s*\{"), "有内层作用域");
		// 「从哪里选牌」：消耗 / 变化卡牌以前只能选「手牌」，现在能选抽牌堆 / 弃牌堆
		CharacterProfile pileProbe = ProfileFactory.Sample();
		CardSpec pileCard = new CardSpec { Name = "自检选牌", ClassName = "UiCheckPile", Rarity = "Common", InCardPool = true };
		pileCard.Effects.Clear();
		pileCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Discard" });
		pileCard.Effects.Add(new EffectSpec { Kind = "TransformCard", Amount = 2m, CardPick = "Random", SelectPile = "Draw" });
		pileCard.Effects.Add(new EffectSpec { Kind = "TakeFromDiscard", Amount = 1m });
		pileProbe.Cards.Add(pileCard);
		string pileSrc = CSharpCodeGen.CardSource(pileProbe, pileCard, 0);
		Check("消耗卡牌能选「弃牌堆」（走本体 FromCombatPile，不再是只有手牌）",
			pileSrc.Contains("CardSelectCmd.FromCombatPile(choiceContext, PileType.Discard.GetPile(base.Owner), base.Owner, new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt, 1))")
			&& !pileSrc.Contains("CardSelectCmd.FromHand"), "弃牌堆消耗");
		Check("变化卡牌「随机」也能从抽牌堆里挑",
			pileSrc.Contains("NextItem(PileType.Draw.GetPile(base.Owner).Cards)"), "抽牌堆随机变化");
		Check("「从弃牌堆拿牌到手牌」用 FromCombatPile + CardPileCmd.Add(…, PileType.Hand)（本体「全息影像 / 挖掘」的做法）",
			pileSrc.Contains("PileType.Discard.GetPile(base.Owner)")
			&& pileSrc.Contains("new CardSelectorPrefs(base.SelectionScreenPrompt, 1)")
			&& pileSrc.Contains("await CardPileCmd.Add(__taken, PileType.Hand)"), "拿回手牌");
		Check("选牌界面提示语跟着生成（<卡牌>.selectionScreenPrompt）",
			LocalizationGen.CardsJson(pileProbe).Contains("\"UI_CHECK_PILE.selectionScreenPrompt\": \"从弃牌堆选择要拿到手牌的牌\""),
			LocalizationGen.CardsJson(pileProbe).Replace("\n", " "));
		Check("描述写清是从哪一摞选的（不再写死「手牌」；张数写成 {Cards:diff()} 占位符，升级后数字跟着变）",
			LocalizationGen.CardsJson(pileProbe).Contains("自己选从弃牌堆消耗 {Cards:diff()} 张牌。")
			&& LocalizationGen.CardsJson(pileProbe).Contains("随机将抽牌堆里的 {Cards2:diff()} 张牌变化为随机卡牌。")
			&& LocalizationGen.CardsJson(pileProbe).Contains("从弃牌堆里选 {Cards3:diff()} 张牌拿到手牌。"), "描述对");
		CharacterProfile handProbe = ProfileFactory.Sample();
		CardSpec handCard = new CardSpec { Name = "自检手牌消耗", ClassName = "UiCheckPileHand", Rarity = "Common", InCardPool = true };
		handCard.Effects.Clear();
		handCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen" });
		handProbe.Cards.Add(handCard);
		Check("没动过「从哪里选牌」时还是手牌（老存档行为不变，走 FromHand）",
			new EffectSpec { Kind = "ExhaustCard" }.SelectPile == "Hand"
			&& new EffectSpec { Kind = "ExhaustCard" }.SelectPileZh == "手牌"
			&& CSharpCodeGen.CardSource(handProbe, handCard, 0).Contains("CardSelectCmd.FromHand(")
			&& EffectCatalog.SelectPiles.Count == 5, $"选项 {EffectCatalog.SelectPiles.Count} 个");
		Check("「从哪里选牌」只有消耗 / 变化 / 丢弃 / 给予关键词用得到",
			new EffectSpec { Kind = "ExhaustCard" }.UsesSelectPile && new EffectSpec { Kind = "TransformCard" }.UsesSelectPile
			// 丢弃要**带张数**才算「会挑牌」：数值 0 那一档 = 丢弃这张牌自己，没有「从哪里选」这回事
			&& new EffectSpec { Kind = "DiscardCard", Amount = 1m }.UsesSelectPile && new EffectSpec { Kind = "GiveKeyword" }.UsesSelectPile
			&& !new EffectSpec { Kind = "Damage" }.UsesSelectPile, "只在这几种上显示");
		Check("状态触发器里**现在支持**「从牌堆拿牌」这一类（用户报的用例：追忆「回合开始时从弃牌堆拿 1 张」）",
			PowerTriggers.Supports("TakeFromDraw") && PowerTriggers.Supports("TakeFromDiscard")
			&& PowerTriggers.Supports("TakeFromExhaust"), "状态里支持");
		// ===== 升级卡牌：状态触发器里也能用（用户报的用例，「参考原版储君的暴政」）=====
		// 本体自己在状态钩子里就是让玩家选牌的（TyrannyPower.AfterPlayerTurnStart → 
		// CardSelectCmd.FromHand(choiceContext, player, prefs, null, this)），所以状态里完全能做）"
		// 差别只是玩家要从 base.Owner.Player 取（状态里 base.Owner 是 Creature）。"
		{
			Check("状态触发器里**现在支持**「升级卡牌」（用户报的用例：玩家回合开始时升级手牌 1 张）",
				PowerTriggers.Supports("UpgradeCard"), "状态里支持");
			Check("「升级卡牌」出现在状态触发器的效果下拉里（PowerKinds 白名单同源）",
				PowerKinds.Any((EffectKindOption k) => k.Kind == "UpgradeCard"), $"{PowerKinds.Count} 种可用");
			Check("「升级卡牌」在状态里被算作「要用 choiceContext」（落进没上下文的钩子时才会自己造一个，否则 CS0103）",
				CustomPowerGen.NeedsChoiceContext(new EffectSpec { Kind = "UpgradeCard" }), "算作需要");
			CharacterProfile upProbe = ProfileFactory.Sample();
			upProbe.CustomPowers.Clear();
			CustomPowerSpec upPow = new CustomPowerSpec { Name = "自检升级", ClassName = "UiCheckUpPow", Enabled = true };
			PowerTriggerSpec upTrig = new PowerTriggerSpec { Kind = "TurnStart" };
			upTrig.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
			upPow.Triggers.Add(upTrig);
			upProbe.CustomPowers.Add(upPow);
			string upSrc = CustomPowerGen.Source(upProbe, upPow, 0);
			Check("状态里的「自己选牌升级」取的是 base.Owner.Player（不是卡牌上下文里的 base.Owner）",
				upSrc.Contains("CardSelectCmd.FromHand(choiceContext, base.Owner.Player,")
				&& upSrc.Contains("CardSelectorPrefs.UpgradeSelectionPrompt"),
				upSrc.Contains("FromHand(") ? "找到了选牌行" : "没生成选牌行");
			Check("状态里的升级只列能升级的牌，并且真的调 CardCmd.Upgrade",
				upSrc.Contains("c => c.IsUpgradable") && upSrc.Contains("CardCmd.Upgrade("), "升级逻辑在");
			// 随机那一条：没有选牌界面，落在**没有** choiceContext 的钩子上也不读 CS0103
			PowerTriggerSpec upTrig2 = new PowerTriggerSpec { Kind = "EnemyTurnStart" };
			upTrig2.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Random", SelectPile = "Discard" });
			upPow.Triggers.Add(upTrig2);
			string upSrc2 = CustomPowerGen.Source(upProbe, upPow, 0);
			Check("状态里的「随机升级」用本体 RNG + 弃牌堆（随机那条没有选牌界面）",
				upSrc2.Contains("Rng.CombatCardSelection.NextItem(PileType.Discard.GetPile(base.Owner.Player).Cards.Where(c => c.IsUpgradable))"),
				"随机那行");
			Check("「敌人回合开始时（钩子不给 choiceContext）」里的升级会自己造一个 choiceContext（否则 CS0103）",
				upSrc2.Contains("var choiceContext = new MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext(this"),
				upSrc2.Contains("HookPlayerChoiceContext(this") ? "造了" : "没选");
			// 消耗 / 丢弃（用户要求：把状态里「仍然不支持」的这两条也做掉）"
			Check("状态触发器里**现在支持**「消耗卡牌 / 丢弃卡牌」（本体 TyrannyPower / ToolsOfTheTradePower 就是状态里选牌）",
				PowerTriggers.Supports("ExhaustCard") && PowerTriggers.Supports("DiscardCard"), "状态里支持");
			Check("「消耗卡牌 / 丢弃卡牌」也出现在状态触发器的效果下拉里",
				PowerKinds.Any((EffectKindOption k) => k.Kind == "ExhaustCard")
				&& PowerKinds.Any((EffectKindOption k) => k.Kind == "DiscardCard"), $"{PowerKinds.Count} 种可用");
			PowerTriggerSpec upTrig3 = new PowerTriggerSpec { Kind = "TurnStart" };
			upTrig3.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
			upTrig3.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 2m, CardPick = "Random", SelectPile = "Discard" });
			upPow.Triggers.Add(upTrig3);
			string upSrc3 = CustomPowerGen.Source(upProbe, upPow, 0);
			Check("状态里「自己选牌消耗」走 FromHand + ExhaustSelectionPrompt + CardCmd.Exhaust（玩家取 base.Owner.Player）",
				upSrc3.Contains("CardSelectCmd.FromHand(choiceContext, base.Owner.Player, new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt")
				&& upSrc3.Contains("await CardCmd.Exhaust(choiceContext, __fgExCard);"), "消耗那条");
			Check("状态里「随机丢弃」走本体 RNG + CardCmd.Discard（弃牌会派发「奇巧」那些钩子）",
				upSrc3.Contains("Rng.CombatCardSelection.NextItem(PileType.Discard.GetPile(base.Owner.Player).Cards)")
				&& upSrc3.Contains("await CardCmd.Discard(choiceContext, __fgPick);"), "丢弃那条");
			// 手牌丢弃要用本体那个专用入口（奇巧牌会描金），别用通用 FromHand
			PowerTriggerSpec upTrig4 = new PowerTriggerSpec { Kind = "TurnStart" };
			upTrig4.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
			upPow.Triggers.Add(upTrig4);
			Check("状态里「自己选牌丢弃」用的是丢手牌专用的 FromHandForDiscard（奇巧会描金）",
				CustomPowerGen.Source(upProbe, upPow, 0).Contains("CardSelectCmd.FromHandForDiscard(choiceContext, base.Owner.Player,"), "专用入口");
		}
		Check("状态触发器**仍然不支持**「复制 / 重放 / 回合结束自动打出」（那几个真要卡牌上下文）",
			!PowerTriggers.Supports("CopyCard") && !PowerTriggers.Supports("ReplayCard")
			&& !PowerTriggers.Supports("TurnEndPlay"), "仍然不支持");

		// ===== 「自己受到伤害后 / 失去生命时 → 失去生命」的无限循环闸（用户实测：会循环到死） ====
		{
			CharacterProfile loopProf = ProfileFactory.Sample();
			loopProf.CustomPowers.Clear();
			var loopPower = new CustomPowerSpec { Name = "自伤循环", ClassName = "UiCheckLoopPower", Enabled = true };
			loopPower.Triggers.Add(new PowerTriggerSpec
			{
				Kind = "DamageTaken",
				Effects = { new EffectSpec { Kind = "HpLoss", Amount = 1m, TargetSide = "Self" } },
			});
			loopProf.CustomPowers.Add(loopPower);
			string hpLoopSrc = CustomPowerGen.Source(loopProf, loopPower, 0);
			Check("「自己受到伤害后 → 失去 1 点生命」生成了**重入闸**（否则本体 Damage 又会回调同一个钩子 → 循环到死）",
				hpLoopSrc.Contains("private bool __inHpLoss") && hpLoopSrc.Contains("if (__inHpLoss) return;")
				&& hpLoopSrc.Contains("finally { __inHpLoss = false; }"), "有闸");
			Check("闸是加在钩子外面、**效果照旧生成**（不是把那条效果删掉）",
				hpLoopSrc.Contains("await CreatureCmd.Damage(choiceContext, base.Owner, 1m"), "效果还在");

			CharacterProfile loopProf2 = ProfileFactory.Sample();
			loopProf2.CustomPowers.Clear();
			var loopPower2 = new CustomPowerSpec { Name = "掉血循环", ClassName = "UiCheckLoop2Power", Enabled = true };
			loopPower2.Triggers.Add(new PowerTriggerSpec
			{
				Kind = "HpLost",
				Effects = { new EffectSpec { Kind = "HpLoss", Amount = 1m, TargetSide = "Self" } },
			});
			loopProf2.CustomPowers.Add(loopPower2);
			Check("「自己失去生命时 → 失去 1 点生命」同样有闸（AfterCurrentHpChanged 也是在掉血时触发）",
				CustomPowerGen.Source(loopProf2, loopPower2, 0).Contains("private bool __inHpLoss"), "有闸");

			// 对照组：受伤后只抽牌（不改生命）→ **不该**带闸（默认档一个字节都不能变）
			CharacterProfile noLoopProf = ProfileFactory.Sample();
			noLoopProf.CustomPowers.Clear();
			var noLoopPower = new CustomPowerSpec { Name = "受伤抽牌", ClassName = "UiCheckNoLoopPower", Enabled = true };
			noLoopPower.Triggers.Add(new PowerTriggerSpec
			{
				Kind = "DamageTaken",
				Effects = { new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" } },
			});
			noLoopProf.CustomPowers.Add(noLoopPower);
			Check("（对照）受伤后只抽牌的状态**不带**闸 —— 没这个组合时生成结果一字不变",
				!CustomPowerGen.Source(noLoopProf, noLoopPower, 0).Contains("__inHpLoss"), "没闸");
		}

		// ===== 清除状态 / 清除所有减益 / 牺牲伙伴：状态触发器里现在能用（用户报的用例） ====
		{
			Check("状态触发器里现在支持「清除指定状态」「清除所有减益」「牺牲伙伴」",
				PowerTriggers.Supports("ClearPowerOne") && PowerTriggers.Supports("ClearPowerDebuffs")
				&& PowerTriggers.Supports("PetSacrifice"),
				$"ClearPowerOne={PowerTriggers.Supports("ClearPowerOne")} ClearPowerDebuffs={PowerTriggers.Supports("ClearPowerDebuffs")} PetSacrifice={PowerTriggers.Supports("PetSacrifice")}");
			Check("这三个也出现在状态触发器的效果下拉里（下拉和校验器同源白名单）",
				PowerKinds.Any((EffectKindOption k) => k.Kind == "ClearPowerOne")
				&& PowerKinds.Any((EffectKindOption k) => k.Kind == "ClearPowerDebuffs")
				&& PowerKinds.Any((EffectKindOption k) => k.Kind == "PetSacrifice"),
				string.Join("/", PowerKinds.Where((EffectKindOption k) => k.Kind is "ClearPowerOne" or "ClearPowerDebuffs" or "PetSacrifice").Select((EffectKindOption k) => k.Display)));

			CharacterProfile clearProbe = ProfileFactory.Sample();
			clearProbe.Summons.Clear();
			clearProbe.Summons.Add(new SummonSpec { Enabled = true, ClassName = "UiCheckCpPet", Name = "自检伙伴", Hp = 10 });
			CustomPowerSpec cpSpec = new CustomPowerSpec { Name = "自检清除", ClassName = "UiCheckCpPower", Enabled = true };
			cpSpec.Triggers.Add(new PowerTriggerSpec
			{
				Kind = "TurnStart",
				Effects =
				{
					new EffectSpec { Kind = "ClearPowerOne", PowerId = "WeakPower", TargetSide = "Self" },
					new EffectSpec { Kind = "ClearPowerDebuffs", TargetSide = "Self" },
				},
			});
			cpSpec.Triggers.Add(new PowerTriggerSpec
			{
				Kind = "TurnEnd",
				Effects =
				{
					new EffectSpec { Kind = "PetSacrifice", PetSummon = "UiCheckCpPet", PetSacrificeGain = "Power", PowerId = "StrengthPower", PetSacrificeFormula = "Fixed", Amount = 2, TargetSide = "Self" },
					new EffectSpec { Kind = "PetSacrifice", PetSummon = "UiCheckCpPet", PetSacrificeGain = "Damage", PetSacrificeFormula = "Fixed", Amount = 7, TargetSide = "AllEnemies" },
				},
			});
			clearProbe.CustomPowers.Add(cpSpec);
			Check("校验器不再拦这三个（不再出现「状态触发器里没有这个上下文」之类的错误）",
				!ProfileValidator.Validate(clearProbe).Any((ValidationIssue i) => i.IsError
					&& (i.Message.Contains("ClearPowerOne") || i.Message.Contains("清除") || i.Message.Contains("牺牲伙伴"))),
				"校验干净");

			string cpCode = CustomPowerGen.Source(clearProbe, cpSpec, 0);
			Check("生成端：清除指定状态写成 GetPower<T>() + PowerCmd.Remove（本体原样，不需要选牌上下文）",
				cpCode.Contains("GetPower<WeakPower>()") && cpCode.Contains("PowerCmd.Remove"), "有");
			Check("生成端：清除所有减益按 PowerType.Debuff 过滤后再 Remove",
				cpCode.Contains("TypeForCurrentAmount == PowerType.Debuff") && cpCode.Contains("PowerCmd.Remove"), "有");
			Check("生成端：牺牲伙伴先查宠物（XxxCmd.Get 收 Player）+ 空判守卫",
				cpCode.Contains("UiCheckCpPetCmd.Get(base.Owner.Player)") && cpCode.Contains("is not null"), "有");
			Check("生成端：牺牲伙伴的状态档不再用 cardPlay（状态钩子里没有这张牌）",
				!cpCode.Contains("cardPlay"), "没有 cardPlay");
			// 有「牺牲伙伴 + 收益 = 伤害」就必须生成 FromPetAttacker 那个扩展方法，否则 CS1061
			Check("有「牺牲伙伴（收益 = 伤害）」时会生成 FromPetAttacker 扩展方法（和卡牌那条路同一份判断）",
				PetGen.UsesAttackExtension(clearProbe), "会生成");
			CharacterProfile noPetAtk = ProfileFactory.Sample();
			noPetAtk.CustomPowers.Clear();
			Check("（对照）没有「收益 = 伤害」的牺牲伙伴 → 不必生成扩展方法",
				!PetGen.UsesAttackExtension(noPetAtk), "不生成");
			// 报错文案按真实原因分档：「重放卡牌」说要「打出这张牌」的上下文；「给予卡牌关键词」说生成端还没实现"
			CharacterProfile wordingProbe = ProfileFactory.Sample();
			wordingProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "文案状态", Enabled = true,
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "GiveKeyword", Amount = 1m, GivenKeyword = "Retain" } } } },
			});
			string wording = string.Join(" ｜ ", ProfileValidator.Validate(wordingProbe)
				.Where((ValidationIssue i) => i.IsError && i.Message.Contains("文案状态")).Select((ValidationIssue i) => i.Message));
			Check("文案分档：不是「卡牌上下文」的那种，说的是「生成端还没实现这个效果种类」",
				wording.Contains("还没给") && !wording.Contains("打出这张牌"), wording.Length > 50 ? wording.Substring(0, 50) + "…" : wording);
		}

		// ===== 丢弃卡牌（用户要求的新效果：手牌 / 抽牌堆里丢 N 张进弃牌堆）=====
		{
			Check("效果种类里有「丢弃卡牌」（张数 0~9，0 = 不生效）",
				EffectCatalog.EffectKinds.Any((EffectKindOption k) => k.Kind == "DiscardCard")
				&& EffectCatalog.FindKind("DiscardCard").Min == 0m && EffectCatalog.FindKind("DiscardCard").Max == 9m,
				EffectCatalog.FindKind("DiscardCard").Display);
			Check("丢弃能选四摞（手牌 / 抽牌堆 / 弃牌堆 / 消耗牌堆 —— 用户要求把消耗牌堆加进来）",
				new EffectSpec { Kind = "DiscardCard" }.SelectPileChoices.Count == 5
				&& new EffectSpec { Kind = "DiscardCard" }.SelectPileChoices.All((PileChoiceOption o) => o.Id is "Hand" or "Draw" or "Discard" or "Exhaust" or "Top")
				&& new EffectSpec { Kind = "ExhaustCard" }.SelectPileChoices.Count == 5,
				string.Join("/", new EffectSpec { Kind = "DiscardCard" }.SelectPileChoices.Select((PileChoiceOption o) => o.Id)));
			Check("丢弃那一行的标题是「从哪里丢弃」（不是「从哪里选牌」）",
				new EffectSpec { Kind = "DiscardCard" }.SelectPileLabel.Contains("丢弃")
				&& new EffectSpec { Kind = "ExhaustCard" }.SelectPileLabel.Contains("选牌"),
				new EffectSpec { Kind = "DiscardCard" }.SelectPileLabel);
			Check("状态触发器里现在能用丢弃卡牌了（用户要求：把它和「消耗卡牌」一起做掉 —— 本体 ToolsOfTheTradePower 就是状态里选牌丢弃）",
				PowerTriggers.Supports("DiscardCard"), "状态里支持");
			CharacterProfile disProbe = ProfileFactory.Sample();
			CardSpec disCard = new CardSpec { Name = "自检丢弃", ClassName = "UiCheckDiscard", Rarity = "Common", Cost = 1, InCardPool = true };
			disCard.Effects.Clear();
			disCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Hand" });
			disCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 3m, CardPick = "Random", SelectPile = "Draw" });
			disProbe.Cards.Add(disCard);
			string disSrc = CSharpCodeGen.CardSource(disProbe, disCard, 0);
			Check("「丢弃卡牌」自己选（手牌）走 CardCmd.Discard + 丢手牌专用的 FromHandForDiscard（奇巧会描金）",
				disSrc.Contains("CardSelectCmd.FromHandForDiscard(choiceContext, base.Owner, new CardSelectorPrefs(CardSelectorPrefs.DiscardSelectionPrompt, 2), null, this)")
				&& disSrc.Contains("await CardCmd.Discard(choiceContext, toDiscard);"), "自己选丢手牌");
			Check("「丢弃卡牌」随机（抽牌堆）从抽牌堆抓牌再丢掉",
				disSrc.Contains("NextItem(PileType.Draw.GetPile(base.Owner).Cards)")
				&& disSrc.Contains("await CardCmd.Discard(choiceContext, pick);"), "随机丢抽牌堆");
			Check("丢弃不声明动态变量（张数写在代码里，不会多出一个用不上的 {Value:diff()}）",
				!disSrc.Contains("new DynamicVar"), "没变量");
			Check("卡面描述写清丢哪一摞 / 怎么丢（张数同样是 {Cards:diff()} / {Cards2:diff()} 占位符）",
				LocalizationGen.CardsJson(disProbe).Contains("自己选丢弃 {Cards:diff()} 张手牌。")
				&& LocalizationGen.CardsJson(disProbe).Contains("随机从抽牌堆里丢弃 {Cards2:diff()} 张牌。"),
				LocalizationGen.CardsJson(disProbe).Replace("\n", " "));
			Check("校验：丢弃会给出「丢进弃牌堆 / 不是消耗」的说明（抽牌堆那条还会提醒奇巧不触发）",
				ProfileValidator.Validate(disProbe).Any((ValidationIssue i) => i.Message.Contains("丢进弃牌堆") && i.Message.Contains("不是消耗"))
				&& ProfileValidator.Validate(disProbe).Any((ValidationIssue i) => i.Message.Contains("不经手牌")), "有提示");
			Check("列表那一行写着「丢弃 / 怎么选 / 从哪一摞」",
				disCard.Effects[1].Display.Contains("丢弃") && disCard.Effects[1].Display.Contains("随机")
				&& disCard.Effects[1].Display.Contains("抽牌堆"), disCard.Effects[1].Display);
			// 遗物 / 药水里也能丢（都有 choiceContext）
			Check("遗物里也能用「丢弃卡牌」（自己选抽牌堆）",
				CSharpCodeGen.RelicSource(disProbe, new RelicSpec
				{
					Name = "自检丢弃遗物", ClassName = "UiCheckDiscardRelic", Trigger = "PlayerTurnStart",
					Effects = { new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Draw" } },
				}, 1).Contains("CardCmd.Discard(choiceContext, toDiscard)"), "遗物");
			Check("药水里也能用「丢弃卡牌」（随机手牌）",
				CSharpCodeGen.PotionSource(disProbe, new PotionSpec
				{
					Name = "自检丢弃药水", ClassName = "UiCheckDiscardPotion", TargetType = "Self",
					Effects = { new EffectSpec { Kind = "DiscardCard", Amount = 2m, CardPick = "Random", SelectPile = "Hand" } },
				}, 2).Contains("CardCmd.Discard(choiceContext, pick)"), "药水");
			// 生成 → 回读：四种组合 + 「从哪里选牌」都要原样回来（以前消耗 / 变化根本回读不出来这个字段）
			string disRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_discard_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				disProbe.Paths.OutputDir = disRoot;
				disProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				disProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				ProfileFactory.Save(disProbe, Path.Combine(disRoot, "discard.json"));
				Check("（准备）丢弃卡牌的存档能生成工程", ModGenerator.Generate(disProbe).Success, disRoot);
				var disRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(disProbe));
				var rc = disRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckDiscard");
				Check("回读：丢弃的「张数 / 怎么选 / 从哪一摞」四种组合都原样回来",
					rc is not null && rc.Effects.Count == 2
					&& rc.Effects[0].Kind == "DiscardCard" && rc.Effects[0].Amount == 2m
					&& rc.Effects[0].CardPick == "Chosen" && rc.Effects[0].SelectPile == "Hand"
					&& rc.Effects[1].Amount == 3m && rc.Effects[1].CardPick == "Random" && rc.Effects[1].SelectPile == "Draw",
					rc is null ? "(没回读出来)" : string.Join("、", rc.Effects.Select((EffectSpec x) => $"{x.Kind} {x.Amount} {x.CardPick} {x.SelectPile}")));
				Check("回读没有认不出来的语句", !disRec.HasUnparsed, disRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(disRoot)) Directory.Delete(disRoot, recursive: true); } catch { }
			}
			// 消耗 / 变化：以前「从哪里选牌」回读会静默退回手牌（顺手修掉的老 bug）
			string pileRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_pile_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile pileRecProbe = ProfileFactory.Sample();
				pileRecProbe.ExtraResource.Enabled = true;      // 「拥有额外资源量至少 N 点」这个条件要它才算数
				CardSpec pileRecCard = new CardSpec { Name = "自检选牌回读", ClassName = "UiCheckPileBack", Rarity = "Common", Cost = 1, InCardPool = true };
				pileRecCard.Condition = new ConditionSpec { Kind = "ExtraResourceAtLeast", Amount = 2m };
				pileRecCard.Effects.Clear();
				pileRecCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 2m, CardPick = "Random", SelectPile = "Draw" });
				pileRecCard.Effects.Add(new EffectSpec { Kind = "TransformCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Discard" });
				pileRecCard.Effects.Add(new EffectSpec { Kind = "TakeFromDraw", Amount = 1m });
				pileRecCard.Effects.Add(new EffectSpec { Kind = "TakeFromDiscard", Amount = 2m });
				pileRecProbe.Cards.Add(pileRecCard);
				pileRecProbe.Paths.OutputDir = pileRoot;
				pileRecProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				pileRecProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				ProfileFactory.Save(pileRecProbe, Path.Combine(pileRoot, "pile.json"));
				Check("（准备）消耗 / 变化选牌堆的存档能生成工程", ModGenerator.Generate(pileRecProbe).Success, pileRoot);
				var pileRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(pileRecProbe));
				var pc = pileRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckPileBack");
				Check("回读：消耗的「从哪里选牌 = 抽牌堆」不再退回手牌（以前这个字段根本没回读）",
					pc is not null && pc.Effects.Any((EffectSpec x) => x.Kind == "ExhaustCard" && x.SelectPile == "Draw" && x.CardPick == "Random"),
					pc is null ? "(没回读出来)" : string.Join("、", pc.Effects.Select((EffectSpec x) => $"{x.Kind} {x.CardPick} {x.SelectPile}")));
				Check("回读：变化的「从哪里选牌 = 弃牌堆」也在（留空目标卡那种 TransformToRandom 以前会被记成「没认出来」）",
					pc is not null && pc.Effects.Any((EffectSpec x) => x.Kind == "TransformCard" && x.SelectPile == "Discard")
					&& !pileRec.HasUnparsed, pileRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				Check("回读：「从抽牌堆 / 弃牌堆拿牌到手牌」也认得出来（以前这两种效果回读后直接丢掉）",
					pc is not null && pc.Effects.Any((EffectSpec x) => x.Kind == "TakeFromDraw" && x.Amount == 1m)
					&& pc.Effects.Any((EffectSpec x) => x.Kind == "TakeFromDiscard" && x.Amount == 2m),
					pc is null ? "(没回读出来)" : string.Join("、", pc.Effects.Select((EffectSpec x) => $"{x.Kind} {x.Amount}")));
				Check("回读：「拥有额外资源量至少 2 点」这个条件认得出来（以前记成「条件没认出来」）",
					pc is not null && pc.Condition.Kind == "ExtraResourceAtLeast" && pc.Condition.Amount == 2m,
					pc is null ? "(没回读出来)" : pc.Condition.Kind + " " + pc.Condition.Amount);
			}
			finally
			{
				try { if (Directory.Exists(pileRoot)) Directory.Delete(pileRoot, recursive: true); } catch { }
			}
			// ===== V0.2.213（用户报的「变化卡牌没有取几张这个选项，也没法选择目标卡或者组内的牌进行变化」）=====
			// ① 锻造页（IsForgeChain）的「取几张」以前走的是那份**旧的 6 种清单** → 变化卡牌上看不到这一栏；
			// ② 变化卡牌只能整摞挑，没法限定「只变化这一类 / 这一组 / 指定的那张卡」。
			{
				Check("V0.2.213：锻造页上「变化卡牌」也有「取几张」（以前锻造链走旧清单，这一栏看不到）",
					new EffectSpec { Kind = "TransformCard", IsForgeChain = true, IsCardChain = false }.ShowCountModeRow
					&& new EffectSpec { Kind = "CopyCard", IsForgeChain = true, IsCardChain = false }.ShowCountModeRow
					&& new EffectSpec { Kind = "PlaceCard", IsForgeChain = true, IsCardChain = false }.ShowCountModeRow,
					$"forge: TransformCard={new EffectSpec { Kind = "TransformCard", IsForgeChain = true }.ShowCountModeRow} "
					+ $"CopyCard={new EffectSpec { Kind = "CopyCard", IsForgeChain = true }.ShowCountModeRow}");
				Check("V0.2.213：（红线）卡牌页上「变化卡牌」的「取几张」照旧显示（判据没被削）",
					new EffectSpec { Kind = "TransformCard", IsCardChain = true }.ShowCountModeRow
					&& !new EffectSpec { Kind = "Damage", IsCardChain = true }.ShowCountModeRow, "卡牌页照旧");
				var tfRows = new EffectSpec { Kind = "TransformCard" };
				Check("V0.2.213：「变化哪些牌 / 只变化这张卡」只在「变化卡牌」上出现（别的种类不显示）",
					tfRows.UsesTransformPick && !new EffectSpec { Kind = "GenerateCard" }.UsesTransformPick
					&& !new EffectSpec { Kind = "TransformCardGlobal" }.UsesTransformPick, "只有变化卡牌");
				tfRows.TransformPick = "Attack";
				Check("V0.2.213：填了「变化哪些牌（范围）」→ HasTransformPick，并且列表里写得出「只变化：攻击」",
					tfRows.HasTransformPick && tfRows.HasTransformSourceFilter
					&& tfRows.TransformPickListText.Contains("只变化") && tfRows.TransformPickZh.Contains("攻击"),
					tfRows.TransformPickListText);
				// ⚠ V0.2.221：这里必须用**本存档里真的有的**卡牌类名（Sample 的 SevenCurse）——
				// 校验器现在会拦「只对这张卡 / 只变化这张卡」填了认不出来的类名（不然生成的工程编译不过）。
				tfRows.ScopeCardId = "SevenCurse";
				Check("V0.2.213：填了「只变化这张卡」→ 以它为准（列表里也换成那张卡）",
					tfRows.HasScopeCardId && tfRows.TransformPickListText.Contains("SevenCurse"),
					tfRows.TransformPickListText);

				// 生成：三条路（自己选 / 全部 / 随机）+ 老行为对照
				CharacterProfile tfProf = ProfileFactory.Sample();
				CardSpec tfCard = new CardSpec { Name = "自检只变化", ClassName = "UiCheckTransformFilter", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				var tfChosen = new EffectSpec { Kind = "TransformCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen", TransformPick = "Attack", TargetSide = "Self" };
				var tfAll = new EffectSpec { Kind = "TransformCard", Amount = 1m, SelectPile = "Draw", CardPick = "Random", CountMode = "All", ScopeCardId = "SevenCurse", TargetSide = "Self" };
				var tfOld = new EffectSpec { Kind = "TransformCard", Amount = 2m, SelectPile = "Draw", CardPick = "Random", TargetSide = "Self" };
				tfCard.Effects.Add(tfChosen);
				tfCard.Effects.Add(tfAll);
				tfCard.Effects.Add(tfOld);
				tfProf.Cards.Add(tfCard);
				string tfSrc = CSharpCodeGen.CardSource(tfProf, tfCard, 0);
				Check("V0.2.213：「自己选」那条路把范围当成选牌过滤条件（filter: c => …）",
					tfSrc.Contains("filter: c => c.Type == CardType.Attack", StringComparison.Ordinal), "有 filter");
				Check("V0.2.213：写一行 CET:ChangePick / CET:ChangeCard 标记（回读靠它，从代码反推不回来）",
					tfSrc.Contains("CET:ChangePick=Attack", StringComparison.Ordinal)
					&& tfSrc.Contains("CET:ChangeCard=SevenCurse", StringComparison.Ordinal), "有标记");
				Check("V0.2.213：「取几张 = 全部」那条路在候选牌上套「只变化这张卡」的条件",
					tfSrc.Contains(".Where(c => c.Id == ModelDb.Card<", StringComparison.Ordinal), "套上了");
				Check("V0.2.213：（红线）两栏都空时生成文本与以前一样（随机那条路没有多出任何 .Where）",
					tfSrc.Split(".Where(c => c.Id ==").Length - 1 == 1
					&& tfSrc.Contains("Rng.CombatCardSelection.NextItem(PileType.Draw.GetPile(base.Owner).Cards)", StringComparison.Ordinal),
					"没多写");
				Check("V0.2.213：卡面写清「只变化…」（玩家看得出它只动某一类牌）",
					LocalizationGen.CardsJson(tfProf).Contains("只变化", StringComparison.Ordinal),
					LocalizationGen.CardsJson(tfProf).Contains("只变化") ? "写了" : "(没写)");

				// 回读：这两栏要认得回来
				string tfRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_tf_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					tfProf.Paths.OutputDir = tfRoot;
					tfProf.Paths.VanillaProject = Profile.Paths.VanillaProject;
					tfProf.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var tfGen = ModGenerator.Generate(tfProf);
					Check("（准备）带「只变化」的存档能生成工程", tfGen.Success,
						tfGen.Success ? tfGen.ProjectRoot : string.Join(" ｜ ", tfGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (tfGen.Success)
					{
						var tfRec = ProjectRecovery.FromProject(tfGen.ProjectRoot);
						CardSpec? tfBack = tfRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckTransformFilter");
						Check("V0.2.213：回读「变化哪些牌（范围）」认得回来（CET:ChangePick）",
							tfBack is not null && tfBack.Effects.Any((EffectSpec x) => x.Kind == "TransformCard" && x.TransformPick == "Attack"),
							tfBack is null ? "(没回读出来)" : string.Join("、", tfBack.Effects.Select((EffectSpec x) => $"{x.Kind}|{x.TransformPick}|{x.ScopeCardId}")));
						Check("V0.2.213：回读「只变化这张卡」认得回来（CET:ChangeCard）",
							tfBack is not null && tfBack.Effects.Any((EffectSpec x) => x.Kind == "TransformCard" && x.ScopeCardId == "SevenCurse"),
							tfBack is null ? "(没回读出来)" : string.Join("、", tfBack.Effects.Select((EffectSpec x) => $"{x.Kind}|{x.TransformPick}|{x.ScopeCardId}")));
					}
				}
				finally
				{
					try { if (Directory.Exists(tfRoot)) Directory.Delete(tfRoot, recursive: true); } catch { }
				}
			}
			// ===== V0.2.214（用户报的「丢弃消耗卡牌无法选择目标卡或者组」）=====
			// 「范围界定」只能按类型 / 组筛，没有「就这一张卡」。现在补「只对这张卡（指定）」：
			// 丢弃 / 消耗 / 升级 / 复制 / 重放 / 给关键词 / 从三摞拿牌 / 预见 上都有；
			// 和「范围界定」是**与**的关系；变化卡牌不显示这一行（它有自己那两行）。
			{
				Check("V0.2.214：「只对这张卡」在丢弃 / 消耗 / 升级 / 复制 / 给关键词 上都显示，变化卡牌不显示这一行（它有自己那两行）",
					new EffectSpec { Kind = "DiscardCard" }.UsesScopeCardFilterRow
					&& new EffectSpec { Kind = "ExhaustCard" }.UsesScopeCardFilterRow
					&& new EffectSpec { Kind = "UpgradeCard" }.UsesScopeCardFilterRow
					&& new EffectSpec { Kind = "CopyCard" }.UsesScopeCardFilterRow
					&& new EffectSpec { Kind = "GiveKeyword" }.UsesScopeCardFilterRow
					&& !new EffectSpec { Kind = "TransformCard" }.UsesScopeCardFilterRow
					&& !new EffectSpec { Kind = "Damage" }.UsesScopeCardFilterRow,
					$"Discard={new EffectSpec { Kind = "DiscardCard" }.UsesScopeCardFilterRow} / Transform={new EffectSpec { Kind = "TransformCard" }.UsesScopeCardFilterRow}");
				var ocExhaust = new EffectSpec { Kind = "ExhaustCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen", ScopeCardId = "SevenCurse", TargetSide = "Self" };
				Check("V0.2.214：设了「只对这张卡」→ HasScopeCardId / HasCardSourceFilter，列表里写得出「只对：SevenCurse」",
					ocExhaust.HasScopeCardId && ocExhaust.HasCardSourceFilter && ocExhaust.ScopeCardListText.Contains("只对"),
					ocExhaust.ScopeCardListText);

				CharacterProfile ocProf = ProfileFactory.Sample();
				CardSpec ocCard = new CardSpec { Name = "自检只对一张", ClassName = "UiCheckOnlyCard", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				var ocChosen = new EffectSpec { Kind = "ExhaustCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen", ScopeCardId = "SevenCurse", TargetSide = "Self" };
				var ocBoth = new EffectSpec { Kind = "DiscardCard", Amount = 2m, SelectPile = "Draw", CardPick = "Random", SpawnFilter = "Attack", ScopeCardId = "SevenCurse", TargetSide = "Self" };
				var ocAll = new EffectSpec { Kind = "ExhaustCard", Amount = 1m, SelectPile = "Hand", CardPick = "Random", CountMode = "All", ScopeCardId = "SevenCurse", TargetSide = "Self" };
				ocCard.Effects.Add(ocChosen);
				ocCard.Effects.Add(ocBoth);
				ocCard.Effects.Add(ocAll);
				ocProf.Cards.Add(ocCard);
				string ocSrc = CSharpCodeGen.CardSource(ocProf, ocCard, 0);
				Check("V0.2.214：（消耗·自己选）把「只对这张卡」当成选牌过滤条件（filter: c => c.Id == …）",
					ocSrc.Contains("filter: c => c.Id == ModelDb.Card<", StringComparison.Ordinal), "有 filter");
				Check("V0.2.214：（丢弃·随机）「范围界定」和「只对这张卡」是**与**的关系（两个条件都在同一条 .Where 里）",
					ocSrc.Contains("(c.Type == CardType.Attack) && (c.Id == ModelDb.Card<", StringComparison.Ordinal), "与关系");
				Check("V0.2.214：（消耗·取几张=全部）候选池也按「只对这张卡」筛",
					ocSrc.Contains(".Where(c => c.Id == ModelDb.Card<", StringComparison.Ordinal), "筛了");
				Check("V0.2.214：标记行写 CET:OnlyCard=（回读靠它；默认档没有这一项 → 老存档逐字不变）",
					ocSrc.Contains("CET:OnlyCard=SevenCurse", StringComparison.Ordinal), "有标记");
				// 红线：没设「只对这张卡」时标记行里没有 CET:OnlyCard、也没有多出来的过滤（用源码对拍，不调 internal API）
				{
					CharacterProfile ocPlainProf = ProfileFactory.Sample();
					CardSpec ocPlainCard = new CardSpec { Name = "自检只对一张对照", ClassName = "UiCheckOnlyCardPlain", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					ocPlainCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen", TargetSide = "Self" });
					ocPlainProf.Cards.Add(ocPlainCard);
					string ocPlainSrc = CSharpCodeGen.CardSource(ocPlainProf, ocPlainCard, 0);
					Check("V0.2.214：（红线）没设「只对这张卡」时源码里没有 CET:OnlyCard、选牌 filter 仍是 null（老存档逐字不变）",
						!ocPlainSrc.Contains("CET:OnlyCard", StringComparison.Ordinal)
						&& ocPlainSrc.Contains("filter: null, source: this", StringComparison.Ordinal)
						&& ocSrc.Split("CET:OnlyCard=").Length - 1 == 3,
						$"对照：OnlyCard={ocPlainSrc.Contains("CET:OnlyCard")} / filter: null={ocPlainSrc.Contains("filter: null, source: this")} / 本条 {ocSrc.Split("CET:OnlyCard=").Length - 1} 个标记");
				}
				Check("V0.2.214：卡面写清「只对」",
					LocalizationGen.CardsJson(ocProf).Contains("只对", StringComparison.Ordinal), "写了");

				string ocRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_oc_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					ocProf.Paths.OutputDir = ocRoot;
					ocProf.Paths.VanillaProject = Profile.Paths.VanillaProject;
					ocProf.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var ocGen = ModGenerator.Generate(ocProf);
					Check("（准备）带「只对这张卡」的存档能生成工程", ocGen.Success,
						ocGen.Success ? ocGen.ProjectRoot : string.Join(" ｜ ", ocGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (ocGen.Success)
					{
						var ocRec = ProjectRecovery.FromProject(ocGen.ProjectRoot);
						CardSpec? ocBack = ocRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckOnlyCard");
						Check("V0.2.214：回读「只对这张卡」认得回来（CET:OnlyCard）",
							ocBack is not null && ocBack.Effects.Count((EffectSpec x) => x.ScopeCardId == "SevenCurse") == 3,
							ocBack is null ? "(没回读出来)" : string.Join("、", ocBack.Effects.Select((EffectSpec x) => $"{x.Kind}|{x.ScopeCardId}")));
					}
				}
				finally
				{
					try { if (Directory.Exists(ocRoot)) Directory.Delete(ocRoot, recursive: true); } catch { }
				}
			}
			// ===== V0.2.215（用户截图报的「虚化」生成失败）=====
			// 锻造卡【能量】模块的「打出时消耗的能量」写 X 以前被校验拦成「必须是编译期常量」，
			// 可那一栏的提示里明明写着「X = 消耗掉的能量」（本体 HasEnergyCostX 那套）。
			// 现在 X / Y 真的接上了：构造函数写 0 + HasEnergyCostX / HasStarCostX + __X 走 ResolveEnergyXValue。
			{
				CharacterProfile xcProf = ProfileFactory.Sample();
				var xcCard = new CardSpec { Name = "自检X费锻造", ClassName = "UiCheckXCostForged", CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true, InCardPool = true };
				var xcGraph = new ForgeGraphSpec();
				var xcTrig = new ForgeNodeSpec { Kind = "Trigger" };
				xcTrig.SetField("Timing", ForgeTimings.CardPlayed);
				var xcEnergy = new ForgeNodeSpec { Kind = "Energy" };
				xcEnergy.SetField("EnergyCost", "X");
				var xcEff = new ForgeNodeSpec { Kind = "Effect" };
				xcEff.SetField("Effect", "Damage");
				xcEff.SetField("Amount", "X");
				xcGraph.Nodes.AddRange(new[] { xcTrig, xcEnergy, xcEff });
				xcGraph.Links.Add(new ForgeLinkSpec { From = xcTrig.Id, To = xcEff.Id });
				xcCard.ForgeGraph = xcGraph;
				xcProf.Cards.Add(xcCard);
				Check("V0.2.215：锻造卡【能量】写 X → 校验器不再拦（以前那条「必须是编译期常量」）",
					!ProfileValidator.Validate(xcProf).Any((ValidationIssue i) => i.IsError
						&& i.Message.Contains("打出时消耗的能量", StringComparison.Ordinal)
						&& i.Message.Contains("编译期常量", StringComparison.Ordinal)),
					ProfileValidator.Validate(xcProf).FirstOrDefault((ValidationIssue i) => i.IsError)?.Message ?? "没有错误");
				Check("V0.2.215：写 X 之后这张牌被当成 X 费（IsCostX → 构造函数费用 0）",
					CSharpCodeGen.IsCostX(xcCard) && CSharpCodeGen.CardCostOf(xcProf, xcCard) == 0,
					$"IsCostX={CSharpCodeGen.IsCostX(xcCard)} cost={CSharpCodeGen.CardCostOf(xcProf, xcCard)}");
				string xcSrc = CSharpCodeGen.CardSource(xcProf, xcCard, 0);
				Check("V0.2.215：生成 HasEnergyCostX + `base(0, …)`（本体「天际钻头 / 挽歌」那套）",
					xcSrc.Contains("protected override bool HasEnergyCostX => true;", StringComparison.Ordinal)
					&& xcSrc.Contains(": base(0, CardType.Skill", StringComparison.Ordinal), "X 费");
				Check("V0.2.215：图里的 X = **打出时消耗掉的**能量（`base.ResolveEnergyXValue()`），不是「剩余能量」",
					xcSrc.Contains("decimal __X = base.ResolveEnergyXValue();", StringComparison.Ordinal)
					&& !xcSrc.Contains("decimal __X = ForgeFormulaRuntime.Energy(__fgPlayer);", StringComparison.Ordinal), "走 ResolveEnergyXValue");
				// 红线：费用那栏写普通数字时，__X 仍然是「剩余能量」那套（老存档逐字不变）
				var xcPlain = new CardSpec { Name = "自检普通费锻造", ClassName = "UiCheckPlainCostForged", CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true, InCardPool = true };
				var xcPlainGraph = new ForgeGraphSpec();
				var xcPlainTrig = new ForgeNodeSpec { Kind = "Trigger" };
				xcPlainTrig.SetField("Timing", ForgeTimings.CardPlayed);
				var xcPlainEnergy = new ForgeNodeSpec { Kind = "Energy" };
				xcPlainEnergy.SetField("EnergyCost", "2");
				var xcPlainEff = new ForgeNodeSpec { Kind = "Effect" };
				xcPlainEff.SetField("Effect", "Damage");
				xcPlainEff.SetField("Amount", "6");
				xcPlainGraph.Nodes.AddRange(new[] { xcPlainTrig, xcPlainEnergy, xcPlainEff });
				xcPlainGraph.Links.Add(new ForgeLinkSpec { From = xcPlainTrig.Id, To = xcPlainEff.Id });
				xcPlain.ForgeGraph = xcPlainGraph;
				xcProf.Cards.Add(xcPlain);
				string xcPlainSrc = CSharpCodeGen.CardSource(xcProf, xcPlain, 0);
				Check("V0.2.215：（红线）费用写普通数字时照旧 —— 没有 HasEnergyCostX、__X 还是「剩余能量」",
					!CSharpCodeGen.IsCostX(xcPlain)
					&& !xcPlainSrc.Contains("HasEnergyCostX", StringComparison.Ordinal)
					&& xcPlainSrc.Contains("decimal __X = ForgeFormulaRuntime.Energy(__fgPlayer);", StringComparison.Ordinal)
					&& CSharpCodeGen.CardCostOf(xcProf, xcPlain) == 2, "老样子");
			}
		}
		// 悬停提示：卡面 / 遗物 / 药水里提到的状态要能弹说明（本体状态改写后就是新名字 + 新描述；自定义状态同理）
		CharacterProfile hoverProbe = ProfileFactory.Sample();
		CardSpec hoverCard = new CardSpec { Name = "自检悬停", ClassName = "UiCheckHover", Rarity = "Common", InCardPool = true };
		hoverCard.Effects.Clear();
		hoverCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = 2m, TargetSide = "Enemy" });
		EffectSpec hoverConditionEffect = new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" };
		hoverConditionEffect.Condition.Kind = "HasPowerAtLeast";
		hoverConditionEffect.Condition.PowerId = "VulnerablePower";
		hoverConditionEffect.Condition.Amount = 1m;
		hoverConditionEffect.Condition.Target = "Enemy";
		hoverCard.Effects.Add(hoverConditionEffect);
		hoverProbe.Cards.Add(hoverCard);
		string hoverSrc = CSharpCodeGen.CardSource(hoverProbe, hoverCard, 0);
		Check("卡面提到的状态会生成 ExtraHoverTips（施加的状态 + 条件里盯的状态都算）",
			hoverSrc.Contains("protected override IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips")
			&& hoverSrc.Contains("HoverTipFactory.FromPower<WeakPower>(2)")
			&& hoverSrc.Contains("HoverTipFactory.FromPower<VulnerablePower>()"), "卡牌悬停提示");
		Check("「下回合生效」的状态悬停提示指向那个延迟状态类（本体这样也有说明）",
			CSharpCodeGen.CardSource(hoverProbe, new CardSpec
			{
				Name = "自检延迟悬停",
				ClassName = "UiCheckHoverDelayed",
				Rarity = "Common",
				InCardPool = true,
				Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = 1m, TargetSide = "Enemy", NextTurn = true } },
			}, 1).Contains($"FromPower<{Naming.From(hoverProbe).DelayedPowerClass(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower" })}>("), "延迟状态");
		Check("没提到任何状态的卡不会生成那一段（不写多余代码）",
			!CSharpCodeGen.CardSource(hoverProbe, new CardSpec
			{
				Name = "自检无状态",
				ClassName = "UiCheckHoverNone",
				Rarity = "Common",
				InCardPool = true,
				Effects = { new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" } },
			}, 2).Contains("ExtraHoverTips"), "没生成");
		RelicSpec hoverRelic = new RelicSpec { Name = "自检悬停遗物", ClassName = "UiCheckHoverRelic", Trigger = "CombatStart" };
		hoverRelic.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "SparkleHoverTestPower", Amount = 1m, TargetSide = "Self" });
		string hoverRelicSrc = CSharpCodeGen.RelicSource(hoverProbe, hoverRelic, 0);
		Check("遗物提到自定义状态时也会生成 ExtraHoverTips（protected override，和本体遗物写法一致）",
			hoverRelicSrc.Contains("protected override IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips")
			&& hoverRelicSrc.Contains("FromPower<SparkleHoverTestPower>(1)"), "遗物悬停提示");
		PotionSpec hoverPotion = new PotionSpec { Name = "自检悬停药水", ClassName = "UiCheckHoverPotion", TargetType = "AllEnemies" };
		hoverPotion.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = 3m, TargetSide = "AllEnemies" });
		string hoverPotionSrc = CSharpCodeGen.PotionSource(hoverProbe, hoverPotion, 0);
		Check("药水提到状态时也会生成 ExtraHoverTips（药水基类是 public，必须 public override）",
			hoverPotionSrc.Contains("public override IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips")
			&& hoverPotionSrc.Contains("FromPower<PoisonPower>(3)"), "药水悬停提示");
		Check("用到额外资源量的卡会带上「资源量」那条悬停提示（走**我们自己的**键，不看别的模组改没改本体的辉星）",
			CSharpCodeGen.CardSource(hoverProbe, new CardSpec
			{
				Name = "自检资源提示",
				ClassName = "UiCheckHoverStar",
				Rarity = "Common",
				InCardPool = true,
				Effects = { new EffectSpec { Kind = "ExtraResource", Amount = 2m, TargetSide = "Self" } },
			}, 3).Contains("new LocString(\"static_hover_tips\", \"SEVEN_EXTRA_RESOURCE.title\")"), "资源提示在");
		Check("获得能量的卡会带上本体的能量提示（base.EnergyHoverTip）",
			CSharpCodeGen.CardSource(hoverProbe, new CardSpec
			{
				Name = "自检能量提示",
				ClassName = "UiCheckHoverEnergy",
				Rarity = "Common",
				InCardPool = true,
				Effects = { new EffectSpec { Kind = "Energy", Amount = 1m, TargetSide = "Self" } },
			}, 4).Contains("base.EnergyHoverTip"), "能量提示在");
		Check("「获得卡牌奖励」会带上本体那条静态提示（StaticHoverTip.CardReward）",
			CSharpCodeGen.RelicSource(hoverProbe, new RelicSpec
			{
				Name = "自检卡牌奖励遗物",
				ClassName = "UiCheckHoverReward",
				Trigger = "CombatVictory",
				Effects = { new EffectSpec { Kind = "CardReward", Amount = 3m, TargetSide = "Self" } },
			}, 1).Contains("StaticHoverTip.CardReward"), "卡牌奖励提示在");

		// ---- 「获得能量 / 获得金币」填负数 = 扣除（本体的 GainEnergy / GainGold 对非正数直接 return）----
		{
			Check("「获得能量 / 获得金币」允许填负数（负数 = 失去 / 扣除）",
				EffectCatalog.FindKind("Energy").Min < 0m && EffectCatalog.FindKind("Gold").Min < 0m,
				$"能量 {EffectCatalog.FindKind("Energy").Min}~{EffectCatalog.FindKind("Energy").Max}、"
				+ $"金币 {EffectCatalog.FindKind("Gold").Min}~{EffectCatalog.FindKind("Gold").Max}");
			CharacterProfile negProbe = ProfileFactory.Sample();
			var negCard = new CardSpec
			{
				Name = "自检负能量卡", ClassName = "UiCheckNegEnergy", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects =
				{
					new EffectSpec { Kind = "Energy", Amount = -2m, TargetSide = "Self" },
					new EffectSpec { Kind = "Gold", Amount = -25m, TargetSide = "Self" },
				},
			};
			var posCard = new CardSpec
			{
				Name = "自检正能量卡", ClassName = "UiCheckPosEnergy", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects =
				{
					new EffectSpec { Kind = "Energy", Amount = 2m, TargetSide = "Self" },
					new EffectSpec { Kind = "Gold", Amount = 25m, TargetSide = "Self" },
				},
			};
			// 负数 + 下回合生效：本体 EnergyNextTurnPower 走 GainEnergy（负数无效）→ 用生成的负债 Power
			var negNextCard = new CardSpec
			{
				Name = "自检下回合负能量卡", ClassName = "UiCheckNegEnergyNext", Rarity = "Common", Cost = 1, InCardPool = true,
				Effects = { new EffectSpec { Kind = "Energy", Amount = -3m, TargetSide = "Self", NextTurn = true } },
			};
			// 三张都进存档（描述 / 校验 / 满配巡检 / 回读都要走「存档里真的有的卡」这条路）
			negProbe.Cards.Add(negCard);
			negProbe.Cards.Add(posCard);
			negProbe.Cards.Add(negNextCard);
			string negSrc = CSharpCodeGen.CardSource(negProbe, negCard, 0);
			Check("负数「获得能量」生成的是 LoseEnergy（数值取绝对值，不会把能量扣成负数）",
				negSrc.Contains("PlayerCmd.LoseEnergy(System.Math.Abs(base.DynamicVars.Energy.BaseValue), base.Owner)")
				&& !negSrc.Contains("PlayerCmd.GainEnergy"), "LoseEnergy");
			// 金币没有本体属性写法（VarAccess 对 Gold 走索引器），所以这里断言的是索引器那条
			Check("负数「获得金币」生成的是 LoseGold",
				negSrc.Contains("PlayerCmd.LoseGold(System.Math.Abs(base.DynamicVars[\"Gold\"].BaseValue), base.Owner)")
				&& !negSrc.Contains("PlayerCmd.GainGold"), "LoseGold");
			Check("负数「获得能量 / 金币」的卡面描述写「失去 N」而不是「获得 -N」",
				LocalizationGen.CardsJson(negProbe).Contains("失去 2 点能量")
				&& LocalizationGen.CardsJson(negProbe).Contains("失去 25 枚金币"), "描述");
			Check("校验：负数会给出「会生成失去 N」的提示（不报错）",
				ProfileValidator.Validate(negProbe).Any((ValidationIssue i) => i.Message.Contains("会生成「失去 2 点能量」"))
				&& !ProfileValidator.Validate(negProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("超出允许范围")), "有提示");
			// 正数还是原来的写法（老存档行为不变）
			string posSrc = CSharpCodeGen.CardSource(negProbe, posCard, 1);
			Check("正数「获得能量 / 金币」仍然是 GainEnergy / GainGold",
				posSrc.Contains("PlayerCmd.GainEnergy") && posSrc.Contains("PlayerCmd.GainGold")
				&& !posSrc.Contains("LoseEnergy") && !posSrc.Contains("LoseGold"), "老样子");
			string negNextSrc = CSharpCodeGen.CardSource(negProbe, negNextCard, 2);
			string debtClass = Naming.From(negProbe).EnergyNextTurnDebtPowerClass;
			Check("负数「获得能量」+「下回合生效」用的是生成的负债 Power（EnergyNextTurnPower 扣不动能量）",
				negNextSrc.Contains($"PowerCmd.Apply<{debtClass}>") && !negNextSrc.Contains("PowerCmd.Apply<EnergyNextTurnPower>"), debtClass);
			Check("这个负债 Power 只在用到时才生成（UsesEnergyNextTurnDebt 认得出来）",
				CSharpCodeGen.UsesEnergyNextTurnDebt(negProbe)
				&& !CSharpCodeGen.UsesEnergyNextTurnDebt(ProfileFactory.Sample()), "认得出来");
			string debtSrc = CSharpCodeGen.EnergyNextTurnDebtPowerSource(negProbe);
			Check("负债 Power 在下回合能量重置后 LoseEnergy（并自毁）",
				debtSrc.Contains("public override async Task AfterEnergyReset(Player player)")
				&& debtSrc.Contains("await PlayerCmd.LoseEnergy(base.Amount, player);")
				&& debtSrc.Contains("await PowerCmd.Remove(this);")
				&& !debtSrc.Contains("await PlayerCmd.GainEnergy"), "AfterEnergyReset");
			Check("负数 + 下回合生效的卡面描述写「失去 3 点能量」且带上「下回合开始时」",
				LocalizationGen.CardsJson(negProbe).Contains("下回合开始时，失去 3 点能量"), "描述");
			// 回读：生成 → --recover 应当原样认出负数（LoseEnergy / LoseGold / 负债 Power）
			string negRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_neg_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				negProbe.Paths.OutputDir = negRoot;
				negProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				negProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				string negJson = Path.Combine(negRoot, "neg.json");
				ProfileFactory.Save(negProbe, negJson);
				Check("（准备）负数能量 / 金币的存档能生成工程", ModGenerator.Generate(negProbe).Success, negRoot);
				var negRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(negProbe));
				var rc = negRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckNegEnergy");
				var rn = negRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckNegEnergyNext");
				Check("回读：负数「获得能量 / 金币」原样回来（不会变成正数 / 丢掉）",
					rc is not null && rc.Effects.Any((EffectSpec e) => e.Kind == "Energy" && e.Amount == -2m)
					&& rc.Effects.Any((EffectSpec e) => e.Kind == "Gold" && e.Amount == -25m),
					rc is null ? "(没回读出来)" : $"{rc.Effects.Count} 条");
				Check("回读：负数 + 下回合生效也原样回来（负债 Power 认回「获得能量 -3 + 下回合」）",
					rn is not null && rn.Effects.Any((EffectSpec e) => e.Kind == "Energy" && e.Amount == -3m && e.NextTurn),
					rn is null ? "(没回读出来)" : $"{rn.Effects.Count} 条");
				Check("回读没有认不出来的语句", !negRec.HasUnparsed, negRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(negRoot)) Directory.Delete(negRoot, recursive: true); } catch { }
			}
		}

		// ===== 本轮用户实测修复：遗物 / 药水「施加增益 / 减益」的 cardSource 必须是 null（写成 this 会选错重载）=====
		{
			// PowerCmd.Apply<T> / PowerCmd.ModifyAmount 的**最后一个实参**类型是 CardModel?。卡牌写 this 合法
			//（卡牌自己就是 CardModel），但遗物 / 药水不是 CardModel —— 写 this 会让编译器去选
			// Apply<T>(ctx, IEnumerable<Creature>? targets, …) 那个重载，然后报两条看不懂的错：
			//   参数 2: 无法从 Creature 转换为 IEnumerable<Creature>?
			//   参数 5: 无法从 …Relic1 转换为 MegaCrit.Sts2.Core.Models.CardModel?
			// 整个模组编译不过（用户实测：遗物「每回合开始 → 获得状态」）。V0.2.37「获得类数值支持负数」把遗物 /
			// 药水也并到 CSharpCodeGen.ApplyPowerLine 上时踩过这个坑（遗物段 / 药水段共 9 个调用点现在都显式传
			// cardSourceExpr: "null"）。这里按「取那一行 → 看最后一个实参」逐个锁死三类上下文，免得再犯。
			// 判据只看那一行里有没有 ", null);" / ", this);"：applier 那一位固定是 Creature 表达式，不会是 null，
			// 所以这样判既准又不依赖中间的数值表达式长什么样。

			// ① 遗物：「每回合开始 → 获得状态」（用户实测的那条路；正数走 Apply<T>）
			CharacterProfile argRelicProbe = ProfileFactory.Sample();
			var argRelicPos = new RelicSpec
			{
				Name = "自检遗物状态实参", ClassName = "UiCheckPowerArgRelic", Rarity = "Common", InRelicPool = true,
				Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = 3m, TargetSide = "Self" } },
			};
			argRelicProbe.Relics.Add(argRelicPos);
			string argRelicSrc = CSharpCodeGen.RelicSource(argRelicProbe, argRelicPos, argRelicProbe.Relics.Count - 1);
			string argRelicApplyLine = argRelicSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.Apply<StrengthPower>(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.Apply 那一行)";
			Check("遗物「每回合开始 → 获得状态」：PowerCmd.Apply 的最后一个实参（cardSource）是 null 而不是 this —— 遗物不是 CardModel，写 this 会选错重载、整个模组编译不过",
				argRelicApplyLine.Contains(", null);", StringComparison.Ordinal)
				&& !argRelicApplyLine.Contains(", this);", StringComparison.Ordinal), argRelicApplyLine);

			// ② 遗物：同一条效果的负数（扣除层数）走 ModifyAmount —— 同一个坑，也要 null
			// ⚠ V0.2.139：这里**必须**用「本体不允许负层数」的状态（虚弱），不再是力量 ——
			//   力量属于本体允许负层数的那 5 个（AllowNegative => true），负数改成**直接施加负值**了
			//   （照本体「尖啸」那套），不再走 ModifyAmount 这条路。要钉「ModifyAmount 那条路的 cardSource」
			//   就得挑一个仍旧走那条路的状态。
			var argRelicNeg = new RelicSpec
			{
				Name = "自检遗物扣层数实参", ClassName = "UiCheckPowerArgRelicNeg", Rarity = "Common", InRelicPool = true,
				Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -3m, TargetSide = "Self" } },
			};
			argRelicProbe.Relics.Add(argRelicNeg);
			string argRelicNegSrc = CSharpCodeGen.RelicSource(argRelicProbe, argRelicNeg, argRelicProbe.Relics.Count - 1);
			string argRelicModifyLine = argRelicNegSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.ModifyAmount(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.ModifyAmount 那一行)";
			Check("遗物「每回合开始 → 扣除 N 层状态」（负数）：PowerCmd.ModifyAmount 的最后一个实参也是 null（负数那条路是同一个坑）",
				argRelicModifyLine.Contains(", null);", StringComparison.Ordinal)
				&& !argRelicModifyLine.Contains(", this);", StringComparison.Ordinal), argRelicModifyLine);

			// ③ 遗物：兜底 —— 整段生成代码里一处都不能有
			string[] argRelicThisLines = argRelicSrc.Split('\n')
				.Where((string l) => (l.Contains("PowerCmd.Apply<", StringComparison.Ordinal) || l.Contains("PowerCmd.ModifyAmount(", StringComparison.Ordinal))
					&& l.Contains(", this);", StringComparison.Ordinal)).ToArray();
			Check("（兜底）遗物那一整段生成代码里，没有任何 PowerCmd.Apply / ModifyAmount 把 this 当 cardSource",
				argRelicThisLines.Length == 0,
				argRelicThisLines.Length == 0 ? "一处都没有" : string.Join(" ｜ ", argRelicThisLines.Select((string l) => l.Trim())));

			// ④ 药水：「获得状态」（药水也不是 CardModel）
			CharacterProfile argPotionProbe = ProfileFactory.Sample();
			var argPotionPos = new PotionSpec { Name = "自检药水状态实参", ClassName = "UiCheckPowerArgPotion" };
			argPotionPos.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = 3m, TargetSide = "Self" });
			argPotionProbe.Potions.Add(argPotionPos);
			string argPotionSrc = CSharpCodeGen.PotionSource(argPotionProbe, argPotionPos, argPotionProbe.Potions.Count - 1);
			string argPotionApplyLine = argPotionSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.Apply<PoisonPower>(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.Apply 那一行)";
			Check("药水「获得状态」：PowerCmd.Apply 的最后一个实参是 null 而不是 this（药水同样不是 CardModel）",
				argPotionApplyLine.Contains(", null);", StringComparison.Ordinal)
				&& !argPotionApplyLine.Contains(", this);", StringComparison.Ordinal), argPotionApplyLine);

			// ⑤ 药水：负数（扣除层数）
			var argPotionNeg = new PotionSpec { Name = "自检药水扣层数实参", ClassName = "UiCheckPowerArgPotionNeg" };
			argPotionNeg.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = -3m, TargetSide = "Self" });
			argPotionProbe.Potions.Add(argPotionNeg);
			string argPotionNegSrc = CSharpCodeGen.PotionSource(argPotionProbe, argPotionNeg, argPotionProbe.Potions.Count - 1);
			string argPotionModifyLine = argPotionNegSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.ModifyAmount(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.ModifyAmount 那一行)";
			Check("药水「扣除 N 层状态」（负数）：PowerCmd.ModifyAmount 的最后一个实参也是 null",
				argPotionModifyLine.Contains(", null);", StringComparison.Ordinal)
				&& !argPotionModifyLine.Contains(", this);", StringComparison.Ordinal), argPotionModifyLine);

			// ⑥ 药水：兜底
			string[] argPotionThisLines = argPotionSrc.Split('\n')
				.Where((string l) => (l.Contains("PowerCmd.Apply<", StringComparison.Ordinal) || l.Contains("PowerCmd.ModifyAmount(", StringComparison.Ordinal))
					&& l.Contains(", this);", StringComparison.Ordinal)).ToArray();
			Check("（兜底）药水那一整段生成代码里，没有任何 PowerCmd.Apply / ModifyAmount 把 this 当 cardSource",
				argPotionThisLines.Length == 0,
				argPotionThisLines.Length == 0 ? "一处都没有" : string.Join(" ｜ ", argPotionThisLines.Select((string l) => l.Trim())));

			// ⑦ 卡牌：同一个效果仍然必须是 this（别为了修遗物 / 药水把卡牌也改坏）
			CharacterProfile argCardProbe = ProfileFactory.Sample();
			argCardProbe.VanillaPowerOverrides.Clear();
			var argCardPos = new CardSpec { Name = "自检卡牌状态实参", ClassName = "UiCheckPowerArgCard", Rarity = "Common", Cost = 1, InCardPool = true };
			argCardPos.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = 3m, TargetSide = "Self" });
			argCardProbe.Cards.Add(argCardPos);
			string argCardSrc = CSharpCodeGen.CardSource(argCardProbe, argCardPos, argCardProbe.Cards.Count - 1);
			string argCardApplyLine = argCardSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.Apply<StrengthPower>(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.Apply 那一行)";
			Check("（对照）卡牌上同类效果仍然传 this（卡牌自己就是 CardModel —— 修 bug 不能把卡牌一起改坏）",
				argCardApplyLine.Contains(", this);", StringComparison.Ordinal)
				&& !argCardApplyLine.Contains(", null);", StringComparison.Ordinal), argCardApplyLine);

			// ⑧ 卡牌：负数（扣除层数）也仍然是 this
			// ⚠ V0.2.139：同上 —— 用「本体不允许负层数」的虚弱，力量那条负数已经改成直接施加负值。
			var argCardNeg = new CardSpec { Name = "自检卡牌扣层数实参", ClassName = "UiCheckPowerArgCardNeg", Rarity = "Common", Cost = 1, InCardPool = true };
			argCardNeg.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -3m, TargetSide = "Self" });
			argCardProbe.Cards.Add(argCardNeg);
			string argCardNegSrc = CSharpCodeGen.CardSource(argCardProbe, argCardNeg, argCardProbe.Cards.Count - 1);
			string argCardModifyLine = argCardNegSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.ModifyAmount(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.ModifyAmount 那一行)";
			Check("（对照）卡牌上「扣除 N 层状态」（负数）也仍然是 this",
				argCardModifyLine.Contains(", this);", StringComparison.Ordinal)
				&& !argCardModifyLine.Contains(", null);", StringComparison.Ordinal), argCardModifyLine);

			// ⑨ 自定义状态触发器：状态不是 CardModel，也必须是 null（这条现在就是对的，锁住）
			CharacterProfile argCpProbe = ProfileFactory.Sample();
			argCpProbe.CustomPowers.Clear();
			argCpProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检状态实参", ClassName = "UiCheckPowerArgCp", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = 3m, TargetSide = "Self" } } } },
			});
			string argCpSrc = CustomPowerGen.Source(argCpProbe, argCpProbe.CustomPowers[0], 0);
			string argCpApplyLine = argCpSrc.Split('\n')
				.FirstOrDefault((string l) => l.Contains("PowerCmd.Apply<StrengthPower>(", StringComparison.Ordinal))?.Trim()
				?? "(没找到 PowerCmd.Apply 那一行)";
			Check("自定义状态的触发器里：PowerCmd.Apply 的最后一个实参是 null（状态钩子里没有「这张牌」）",
				argCpApplyLine.Contains(", null);", StringComparison.Ordinal)
				&& !argCpApplyLine.Contains(", this);", StringComparison.Ordinal), argCpApplyLine);
		}

		// ===== 本轮修复：① 自定义状态触发器「施加状态」填负数 / ② 遗物·药水落在没实现的种类上 =====
		{
			// ① 自定义状态触发器的「施加状态」现在和卡牌 / 遗物 / 药水走**同一条**实现
			//（CSharpCodeGen.ApplyPowerLine）。V0.2.139 起那条实现按「本体允不允许负层数」分两档：
			//   · 力量 / 敏捷 / 专注 / 尖啸 / 萎缩（AllowNegative => true）→ **照本体「尖啸」那套直接施加负值**；
			//   · 其余（虚弱 / 毒…）→ 先 GetPower<T>() 取那份实例再 ModifyAmount 扣。
			// 旧写法是在 CustomPowerGen.EmitEffect 里手写 PowerCmd.Apply，负数会被本体拿去**新建一个 -3 层的状态**
			//（ApplyInternal(target, -N, …)）—— 现在不会有这种「凭空挂负层数」的怪东西了。
			CharacterProfile negPowProbe = ProfileFactory.Sample();
			negPowProbe.CustomPowers.Clear();
			negPowProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检负数状态", ClassName = "UiCheckNegPower", Type = "Buff",
				Triggers =
				{
					new PowerTriggerSpec
					{
						Kind = "TurnStart",
						Effects =
						{
							new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -3m, TargetSide = "Self" },
							new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -2m, TargetSide = "AllEnemies" },
							new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = 2m, TargetSide = "Self" },
						},
					},
					new PowerTriggerSpec
					{
						Kind = "Attacked",
						Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = -1m, TargetSide = "Enemy" } },
					},
				},
			});
			string negPowSrc = CustomPowerGen.Source(negPowProbe, negPowProbe.CustomPowers[0], 0);
			Check("V0.2.139：自定义状态触发器「施加状态」填负数 → 按本体允不允许负层数分两档："
				+ "力量（允许）直接施加 -3m；虚弱 / 中毒（不允许）仍旧先取实例再 PowerCmd.ModifyAmount 扣层数"
				+ "（和卡牌 / 遗物 / 药水同一条实现）",
				negPowSrc.Contains("await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, -3m, base.Owner, null);", StringComparison.Ordinal)
				&& !negPowSrc.Contains("GetPower<StrengthPower>", StringComparison.Ordinal)
				&& negPowSrc.Contains("other.GetPower<WeakPower>()", StringComparison.Ordinal)
				&& negPowSrc.Contains("other.GetPower<PoisonPower>()", StringComparison.Ordinal),
				negPowSrc.Split('\n').FirstOrDefault((string l) => l.Contains("PowerCmd.", StringComparison.Ordinal))?.Trim() ?? "(没找到)");
			int negModifyCount = negPowSrc.Split(new[] { "PowerCmd.ModifyAmount(" }, StringSplitOptions.None).Length - 1;
			Check("V0.2.139：（不允许负层数的两条路走 ModifyAmount）全体敌人上的虚弱 -2 / 单体敌人上的中毒 -1 = 2 处；"
				+ "力量 -3 已经改成直接施加负值、不再走这条路",
				negModifyCount == 2, "ModifyAmount 出现 " + negModifyCount + " 次");
			// 「凭空挂一个负层数状态」的老毛病：不允许负层数的状态**一个都不许**出现 Apply(…, 负数)。
			// 允许负层数的状态（力量）出现 Apply(…, -3m) 是**正确的**（本体「尖啸」就是这么写的）。
			string[] negApplyBadLines = negPowSrc.Split('\n')
				.Where((string l) => l.Contains("PowerCmd.Apply<WeakPower>(", StringComparison.Ordinal) && l.Contains(", -", StringComparison.Ordinal)
					|| l.Contains("PowerCmd.Apply<PoisonPower>(", StringComparison.Ordinal) && l.Contains(", -", StringComparison.Ordinal))
				.ToArray();
			Check("V0.2.139：（防回归）**不允许负层数**的状态（虚弱 / 中毒）绝不会生成「新建一个 -N 层状态」的 PowerCmd.Apply；"
				+ "而允许负层数的力量生成 Apply(…, -3m) 正是本体「尖啸」的写法",
				negApplyBadLines.Length == 0,
				negApplyBadLines.Length == 0 ? "一处都没有（不允许负层数的负数全走 ModifyAmount）" : string.Join(" ｜ ", negApplyBadLines.Select((string l) => l.Trim())));
			Check("（对照）同一条链的正数仍然生成 PowerCmd.Apply<…>（只有负数换路）",
				negPowSrc.Contains("await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, 2m, base.Owner, null);", StringComparison.Ordinal),
				negPowSrc.Split('\n').FirstOrDefault((string l) => l.Contains("PowerCmd.Apply<StrengthPower>", StringComparison.Ordinal))?.Trim() ?? "(没找到)");
			string[] negModifyLines = negPowSrc.Split('\n')
				.Where((string l) => l.Contains("PowerCmd.ModifyAmount(", StringComparison.Ordinal)).ToArray();
			Check("自定义状态触发器里负数那条的 cardSource 也是 null（状态不是 CardModel，写 this 会选错重载、编译不过）",
				negModifyLines.Length > 0
				&& negModifyLines.All((string l) => l.Contains(", null);", StringComparison.Ordinal) && !l.Contains(", this);", StringComparison.Ordinal)),
				negModifyLines.FirstOrDefault()?.Trim() ?? "(没找到)");
			Check("校验器：自定义状态触发器「施加状态」填负数 → 给一条提示说清语义（力量允许负层数 → 直接施加 -3 层；"
				+ "不是「给目标挂一个 -3 层的新状态」那种凭空挂负层数）",
				ProfileValidator.Validate(negPowProbe).Any(i => i.Message.Contains("照本体「尖啸」那套直接施加 -3 层")),
				string.Join(" / ", ProfileValidator.Validate(negPowProbe).Where(i => i.Message.Contains("数值是")).Select(i => i.Level + ": " + i.Message)));

			// ③ 自定义状态触发器的「施加状态」没选状态 → 校验器必须报错
			//（生成的是 `PowerCmd.Apply<>`，泛型参数是空的 → dotnet 直接 CS0305）
			CharacterProfile noPowerProbe = ProfileFactory.Sample();
			noPowerProbe.CustomPowers.Clear();
			noPowerProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检没选状态", ClassName = "UiCheckNoPowerState", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "ApplyPower", Amount = 2m, TargetSide = "Self" } } } },
			});
			var noPowerIssues = ProfileValidator.Validate(noPowerProbe);
			Check("自定义状态触发器的「施加状态」没选状态 → 校验器报错",
				noPowerIssues.Any(i => i.IsError && i.Message.Contains("还没选状态")),
				noPowerIssues.Any(i => i.Message.Contains("还没选状态"))
					? string.Join(" / ", noPowerIssues.Where(i => i.Message.Contains("还没选状态")).Select(i => i.Level + ": " + i.Message))
					: "(校验器没说话)");

			// ④ 遗物 / 药水遇到「只做在卡牌上」的效果种类：生成里必须留一行醒目告警注释
			//（以前这两个 switch 没有 default：什么都不生成、也不报错，用户以为配上了）。
			// 「只做在卡牌上」的确切清单 = 卡牌那个大 switch 的 case 减去遗物 / 药水两个 switch 的 case：
			//   Expose / ClearPowerOne / ClearPowerDebuffs / DoublePower / ForbidBlock / ForbidHeal / TimesUp / OverdraftEnergy
			//（TimesUp 本来就有自己的检查；OverdraftEnergy 是这 8 个里唯一以前完全没提示的，这里用它做代表。）
			CharacterProfile cardOnlyProbe = ProfileFactory.Sample();
			var cardOnlyRelic = new RelicSpec
			{
				Name = "自检遗物卡牌专属", ClassName = "UiCheckCardOnlyRelic", Rarity = "Common", InRelicPool = true, Trigger = "PlayerTurnStart",
				Effects =
				{
					new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" },
					new EffectSpec { Kind = "OverdraftEnergy", Amount = 2m, TargetSide = "Self" },
				},
			};
			cardOnlyProbe.Relics.Add(cardOnlyRelic);
			string cardOnlyRelicSrc = CSharpCodeGen.RelicSource(cardOnlyProbe, cardOnlyRelic, cardOnlyProbe.Relics.Count - 1);
			Check("遗物上放「只做在卡牌上」的效果种类 → 生成里留下一行醒目告警注释（以前静默跳过、一行代码都不生成）",
				cardOnlyRelicSrc.Contains("// ⚠⚠ 该效果种类在遗物上**没有实现**", StringComparison.Ordinal),
				cardOnlyRelicSrc.Split('\n').FirstOrDefault((string l) => l.Contains("没有实现", StringComparison.Ordinal))?.Trim() ?? "(没找到告警注释)");
			var cardOnlyRelicIssues = ProfileValidator.Validate(cardOnlyProbe);
			Check("遗物上放「只做在卡牌上」的效果种类 → 校验器在生成前给警告（不是静默丢掉；其余效果照常工作）",
				cardOnlyRelicIssues.Any(i => !i.IsError && i.Message.Contains("只做在卡牌上") && i.Message.Contains("遗物")),
				string.Join(" / ", cardOnlyRelicIssues.Where(i => i.Message.Contains("只做在卡牌上")).Select(i => i.Level + ": " + i.Message)));
			// 整只遗物的效果**全是**这类种类 → 生成出来是个空壳 → 必须是错误
			var deadCardOnlyRelic = new RelicSpec
			{
				Name = "自检空壳遗物", ClassName = "UiCheckDeadRelic", Rarity = "Common", InRelicPool = true, Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "OverdraftEnergy", Amount = 2m, TargetSide = "Self" } },
			};
			cardOnlyProbe.Relics.Add(deadCardOnlyRelic);
			var deadIssues = ProfileValidator.Validate(cardOnlyProbe);
			Check("遗物上「全部效果」都是只做在卡牌上的种类 → 校验器报**错误**（整只遗物生成出来等于没有作用）",
				deadIssues.Any(i => i.IsError && i.Message.Contains("全是这一类")),
				string.Join(" / ", deadIssues.Where(i => i.Message.Contains("只做在卡牌上")).Select(i => i.Level + ": " + i.Message)));
			// 药水同一份判据（药水同样没有「玩家选中的目标」）
			CharacterProfile cardOnlyPotionProbe = ProfileFactory.Sample();
			var cardOnlyPotion = new PotionSpec { Name = "自检药水卡牌专属", ClassName = "UiCheckCardOnlyPotion", Rarity = "Common" };
			cardOnlyPotion.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
			cardOnlyPotion.Effects.Add(new EffectSpec { Kind = "Expose", Amount = 2m, PowerId = "StrengthPower", TargetSide = "Enemy" });
			cardOnlyPotionProbe.Potions.Add(cardOnlyPotion);
			string cardOnlyPotionSrc = CSharpCodeGen.PotionSource(cardOnlyPotionProbe, cardOnlyPotion, cardOnlyPotionProbe.Potions.Count - 1);
			Check("药水同样：生成里留下一行醒目告警注释",
				cardOnlyPotionSrc.Contains("// ⚠⚠ 该效果种类在药水上**没有实现**", StringComparison.Ordinal),
				cardOnlyPotionSrc.Split('\n').FirstOrDefault((string l) => l.Contains("没有实现", StringComparison.Ordinal))?.Trim() ?? "(没找到告警注释)");
			var cardOnlyPotionIssues = ProfileValidator.Validate(cardOnlyPotionProbe);
			Check("药水同样：校验器给出警告",
				cardOnlyPotionIssues.Any(i => !i.IsError && i.Message.Contains("只做在卡牌上") && i.Message.Contains("药水")),
				string.Join(" / ", cardOnlyPotionIssues.Where(i => i.Message.Contains("只做在卡牌上")).Select(i => i.Level + ": " + i.Message)));
		}

		// ===== 本轮新增：自定义状态伤害归属 / 毒性爆发 / 大限已至 / 预见 / 升级卡牌 / 范围限定 / 自定义描述 =====
		{
			// ① 自定义状态造成的伤害不算「角色造成的伤害」：dealer 传 null（本体就是靠它归因的）
			CharacterProfile dmgProbe = ProfileFactory.Sample();
			dmgProbe.CustomPowers.Clear();
			dmgProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检状态伤害", ClassName = "UiCheckDmgPower", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "AllEnemies" } } } },
			});
			string dmgSrc = CustomPowerGen.Source(dmgProbe, dmgProbe.CustomPowers[0], 0);
			Check("自定义状态造成的伤害不归因到角色（dealer 传 null，本体靠它算「你造成的伤害」）",
				dmgSrc.Contains("CreatureCmd.Damage(choiceContext, other, 5m, ValueProp.Unpowered, null, null, null)")
				&& !dmgSrc.Contains("ValueProp.Unpowered, base.Owner)"), "dealer=null");
			Check("（对照）本体的归因条件：dealer 非空才会计入 DamageDealt",
				File.Exists(Path.Combine(Profile.Paths.VanillaProject, "src/Core/Commands/CreatureCmd.cs"))
					? File.ReadAllText(Path.Combine(Profile.Paths.VanillaProject, "src/Core/Commands/CreatureCmd.cs"), Encoding.UTF8)
						.Contains("dealer.Player.ExtraFields.DamageDealt")
					: true, "源码里就是这么写的");

			// ② 毒性爆发（本体 Outbreak）：全体上毒 + 立刻触发一次；走本体 PoisonPower.Trigger
			CharacterProfile outProbe = ProfileFactory.Sample();
			CardSpec outCard = new CardSpec { Name = "自检毒性爆发", ClassName = "UiCheckOutbreak", Rarity = "Common", Cost = 1, InCardPool = true };
			outCard.Effects.Add(new EffectSpec { Kind = "Outbreak", Amount = 7m, TargetSide = "Self" });
			outProbe.Cards.Add(outCard);
			string outSrc = CSharpCodeGen.CardSource(outProbe, outCard, 0);
			Check("毒性爆发：给所有敌人上毒 + 立刻触发中毒（本体 Outbreak 的写法）",
				outSrc.Contains("CET:Effect=Outbreak")
				&& outSrc.Contains("await PowerCmd.Apply<PoisonPower>(choiceContext, foe,")
				&& outSrc.Contains("PoisonPower? poison = foe.GetPower<PoisonPower>();")
				&& outSrc.Contains("await poison.Trigger();"), "对");
			Check("毒性爆发的卡面描述照本体原文（给所有敌人 N 层中毒，并立即触发中毒）",
				LocalizationGen.CardsJson(outProbe).Contains("给予所有敌人 {PoisonPower:diff()} 层[gold]中毒[/gold]，并立即触发[gold]中毒[/gold]。"), "描述对");

			// ③ 大限已至（本体 Time's Up）：伤害 = 目标的灾厄层数（计算变量三件套 + 目标倍率）
			CharacterProfile upProbe = ProfileFactory.Sample();
			CardSpec upCard = new CardSpec { Name = "自检大限", ClassName = "UiCheckTimesUp", CardType = "Attack", Rarity = "Common", Cost = 2, InCardPool = true };
			upCard.Effects.Add(new EffectSpec { Kind = "TimesUp", TargetSide = "Enemy" });
			upProbe.Cards.Add(upCard);
			string upSrc = CSharpCodeGen.CardSource(upProbe, upCard, 0);
			Check("大限已至：伤害 = 目标身上的灾厄层数（CalculatedDamage + GetPowerAmount<DoomPower>）",
				upSrc.Contains("GetPowerAmount<DoomPower>()")
				&& upSrc.Contains("DamageCmd.Attack(base.DynamicVars.CalculatedDamage)")
				&& upSrc.Contains(".Targeting(cardPlay.Target)"), "对");
			Check("大限已至会把这张牌变成「指定敌人」目标（不然打出去时没有目标）",
				CSharpCodeGen.CardSource(upProbe, upCard, 0).Contains("TargetType.AnyEnemy"), "AnyEnemy");
			Check("大限已至只能用在卡牌上（遗物 / 药水里报错拦住）",
				ProfileValidator.Validate(new CharacterProfile
				{
					Relics = { new RelicSpec
					{
						Name = "自检大限遗物", ClassName = "UiCheckTimesUpRelic", Trigger = "PlayerTurnStart",
						Effects = { new EffectSpec { Kind = "TimesUp", TargetSide = "Enemy" } },
					} },
				}).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只能用在**卡牌**上")), "拦住了");

			// ④ 预见（一代观者的 Scry）：看抽牌堆顶 N 张、丢任意张（本体没有这个机制，自己拼）
			CharacterProfile scryProbe = ProfileFactory.Sample();
			CardSpec scryCard = new CardSpec { Name = "自检预见", ClassName = "UiCheckScry", Rarity = "Common", Cost = 1, InCardPool = true };
			scryCard.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 3m, TargetSide = "Self" });
			scryProbe.Cards.Add(scryCard);
			string scrySrc = CSharpCodeGen.CardSource(scryProbe, scryCard, 0);
			Check("预见：抽牌堆顶 = Cards 的前 N 个（本体索引 0 就是顶），选牌走 FromSimpleGrid（min 0 = 可以一张都不丢）",
				scrySrc.Contains("PileType.Draw.GetPile(base.Owner).Cards.Take(3).ToList()")
				&& scrySrc.Contains("CardSelectCmd.FromSimpleGrid(choiceContext, __scryTop, base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, 0, __scryTop.Count))"), "对");
			Check("预见：丢牌走 CardCmd.Discard（派发被丢弃钩子，奇巧照常触发）",
				scrySrc.Contains("await CardCmd.Discard(choiceContext, __scryDiscard);"), "对");

			// ⑤ 升级卡牌（战斗内 / 全局）
			CharacterProfile ugProbe = ProfileFactory.Sample();
			CardSpec ugCard = new CardSpec { Name = "自检升级", ClassName = "UiCheckUpgrade", Rarity = "Common", Cost = 1, InCardPool = true };
			ugCard.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Discard" });
			ugCard.Effects.Add(new EffectSpec { Kind = "UpgradeCardGlobal", Amount = 1m, CardPick = "Chosen" });
			ugProbe.Cards.Add(ugCard);
			string ugSrc = CSharpCodeGen.CardSource(ugProbe, ugCard, 0);
			Check("升级卡牌（战斗内）：从选定的那一摞挑，只列能升级的牌，走本体 CardCmd.Upgrade",
				ugSrc.Contains("CardSelectCmd.FromCombatPile(choiceContext, PileType.Discard.GetPile(base.Owner), base.Owner, new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, 2), c => c.IsUpgradable)")
				&& ugSrc.Contains("foreach (CardModel c in toUpgrade) CardCmd.Upgrade(c);"), "对");
			Check("升级卡牌（全局）：走 FromDeckForUpgrade（本体的「香盒 Pomander」写法），改的是牌组",
				ugSrc.Contains("CardSelectCmd.FromDeckForUpgrade(base.Owner, new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, 1))")
				&& ugSrc.Contains("foreach (CardModel c in toUpgradeDeck) CardCmd.Upgrade(c);"), "对");
			Check("两种升级卡牌在列表里都能一眼区分（战斗内 / 全局）",
				ugCard.Effects[0].Display.Contains("升级") && !ugCard.Effects[0].Display.Contains("全局")
				&& ugCard.Effects[1].Display.Contains("全局"), ugCard.Effects[1].Display);

			// ⑥ 生成 / 变化：范围限定 + 生成出来的卡的附加处理
			CharacterProfile spProbe = ProfileFactory.Sample();
			CardSpec spCard = new CardSpec { Name = "自检范围", ClassName = "UiCheckSpawn", Rarity = "Common", Cost = 1, InCardPool = true };
			spCard.Effects.Add(new EffectSpec
			{
				Kind = "GenerateCard", Amount = 2m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnTo = "Hand",
				SpawnUpgraded = true, SpawnFreeThisTurn = true,
			});
			spCard.Effects.Add(new EffectSpec
			{
				Kind = "TransformCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Curse", CardPick = "Chosen",
				SelectPile = "Hand", SpawnUpgradedThisTurn = true,
			});
			spProbe.Cards.Add(spCard);
			string spSrc = CSharpCodeGen.CardSource(spProbe, spCard, 0);
			Check("按范围随机生成：从角色卡池按牌的类型挑（攻击 / 技能 / 能力），走本体 GetDistinctForCombat",
				spSrc.Contains("CardFactory.GetDistinctForCombat(base.Owner, __genPool, 2, base.Owner.RunState.Rng.CombatCardGeneration)")
				&& spSrc.Contains(".Where(c => c.Type == CardType.Attack)"), "对");
			Check("按范围随机变化：诅咒范围会把本体诅咒卡池一起算进来（你自己的诅咒也在角色卡池里）",
				spSrc.Contains("ModelDb.CardPool<CurseCardPool>().GetUnlockedCards")
				&& spSrc.Contains(".Where(c => c.Rarity == CardRarity.Curse)"), "对");
			Check("生成出来的卡「直接升级 / 仅本回合免费」按本体的 API 生成",
				spSrc.Contains("CardCmd.Upgrade(__gen);") && spSrc.Contains("__gen.SetToFreeThisTurn();"), "对");
			Check("「仅本回合升级」用生成的临时升级状态（本体没有临时升级 API），并在里面记住那几张牌",
				CSharpCodeGen.UsesTempUpgrade(spProbe)
				&& CSharpCodeGen.TempUpgradePowerSource(spProbe).Contains("public void Track(CardModel card)")
				&& CSharpCodeGen.TempUpgradePowerSource(spProbe).Contains("CardCmd.Downgrade(card);"), "对");
			Check("范围限定 / 取卡方式的下拉选项齐全（不限 / 攻击 / 技能 / 能力 / 诅咒 / 状态 / 任务）",
				SpawnFilters.Count == 7 && SpawnPicks.Count == 2
				&& SpawnFilters.Select((SpawnFilterOption f) => f.Id).SequenceEqual(new[] { "", "Attack", "Skill", "Power", "Curse", "Status", "Quest" }),
				string.Join("/", SpawnFilters.Select((SpawnFilterOption f) => f.Zh)));
			// 需求 ⑥：自定义状态的触发器也支持「按范围随机 / 生成出来的卡的附加处理 / 范围界定」
			// —— 那条链（CustomPowerGen.EmitEffect 的 GenerateCard）改成复用卡牌那条链的
			// CSharpCodeGen.EmitGenerateCard（playerExpr: base.Owner.Player + profile），所以这里
			// 既检查「不再报错」，也检查生成出来的**状态源码**用对了玩家表达式（base.Owner 在状态钩子里是 Creature，
			// 写错了生成的工程会 CS1061 / CS1929，编译不过）。
			CharacterProfile pwProbe = ProfileFactory.Sample();
			pwProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运", Description = "命运组" });
			pwProbe.Cards.Add(new CardSpec
			{
				Name = "自检命运牌", ClassName = "UiCheckPwFate", CardType = "Attack", Rarity = "Common", Cost = 1,
				InCardPool = true, KeywordIds = { "FATE" },
				Effects = { new EffectSpec { Kind = "Damage", Amount = 8m, TargetSide = "Enemy" } },
			});
			var pwPower = new CustomPowerSpec { Name = "自检范围状态", ClassName = "UiCheckPwRangePower" };
			pwPower.Triggers.Add(new PowerTriggerSpec
			{
				Kind = "TurnStart",
				Effects =
				{
					new EffectSpec
					{
						Kind = "GenerateCard", Amount = 2m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnTo = "Hand",
						SpawnUpgraded = true, SpawnFree = true, SpawnKeyword = "Exhaust",
					},
					new EffectSpec
					{
						Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Keyword:FATE",
						SpawnChoice = 3m, SpawnTo = "Hand", SpawnUpgradedThisTurn = true, SpawnKeyword = "FATE",
					},
				},
			});
			pwProbe.CustomPowers.Add(pwPower);
			Check("校验器：自定义状态触发器 +「按范围随机 / 附加处理 / 范围界定」不再报错（需求 ⑥ 放开了这两条）",
				!ProfileValidator.Validate(pwProbe).Any((ValidationIssue i) => i.IsError
					&& (i.Message.Contains("按范围随机") || i.Message.Contains("范围界定"))),
				string.Join(" / ", ProfileValidator.Validate(pwProbe).Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message)));
			string pwSrc = CustomPowerGen.Source(pwProbe, pwPower, 0);
			Check("状态触发器里的「按范围随机」用玩家那一侧的对象取卡池 / 抽牌（CardFactory.GetDistinctForCombat(base.Owner.Player, …)）",
				pwSrc.Contains("CardFactory.GetDistinctForCombat(base.Owner.Player, __genPool, 2, base.Owner.Player.RunState.Rng.CombatCardGeneration)"), "对");
			Check("状态触发器里的「附加处理 / 需求⑦ 生成出来的卡加关键词」照旧复用同一份 EmitSpawnModifiers / EmitSpawnKeyword",
				pwSrc.Contains("CardCmd.Upgrade(__gen);") && pwSrc.Contains("__gen.SetToFreeThisCombat();")
				&& pwSrc.Contains("__gen.AddKeyword(CardKeyword.Exhaust);"), "对");
			Check("状态触发器里的「自定义关键词那一组」也能查 profile：候选表按生成期列出来（不再只支持「指定卡」）",
				pwSrc.Contains("ModelDb.Card<UiCheckPwFate>()") && pwSrc.Contains("__picked.AddGivenCustomKeyword(\"FATE\");"), "对");
			Check("状态触发器里默认档（指定卡、不加附加处理）生成的文本与旧版一致：仍走 AddToCombatAndPreview + base.Owner",
				CustomPowerGen.Source(pwProbe, new CustomPowerSpec
				{
					Name = "自检默认档状态", ClassName = "UiCheckPwPlainPower",
					Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Hand" } } } },
				}, 0).Contains("await CardPileCmd.AddToCombatAndPreview<MegaCrit.Sts2.Core.Models.Cards.Shiv>(base.Owner, PileType.Hand, 1, base.Owner.Player);"), "对");
			// （界面）自定义状态那一档也能看到这三样吗？**先核实**：那几行的显隐绑的是
			// UsesSpawnOptions / ShowSpawnFilter / UsesSpawnOptions（附加处理那几行），判据只看效果种类（Kind），
			// 和 ctx 无关；App.xaml 里自定义状态的 EffectEditorPower 模板也是 ContentTemplate=EffectCommon
			// —— 所以不用补界面。这里把「真的显示出来了」钉住：选中「自定义状态」页的状态 → 触发时机 →
			// 效果种类改成「生成卡牌 + 按范围随机」，看那几行在不在。
			SelectTabRoot("自定义状态");
			if (CustomPowerList.Items.Count == 0) OnAddCustomPower(this, new RoutedEventArgs());
			// 上面 #9 那段已经把选中项改成别的了（所以 CustomPowerList.SelectedItem 可能是 null）——
			// 这里自己按名字选一个回来，保证下面那几条真的跑到。
			CustomPowerList.SelectedItem = CustomPowerList.Items.OfType<CustomPowerSpec>()
				.FirstOrDefault((CustomPowerSpec s) => s.Name == "自检范围状态") ?? CustomPowerList.Items[0];
			if (CustomPowerList.SelectedItem is CustomPowerSpec uiPower)
			{
				var uiTrigger = new PowerTriggerSpec { Kind = "TurnStart" };
				uiTrigger.Effects.Clear();
				uiTrigger.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack" });
				uiPower.Triggers.Clear();
				uiPower.Triggers.Add(uiTrigger);
				CustomTriggerList.SelectedItem = uiTrigger;
				UpdateLayout();
				List<Grid> pwGrids = new List<Grid>();
				CollectGrids(SelectTabRoot("自定义状态"), pwGrids);
				Check("（界面）自定义状态触发器里能看到「取卡方式（生成 / 变化）」那一行（V0.2.150 起绑 ShowSpawnPickRow）",
					pwGrids.Any((Grid g) => BindingOperations.GetBinding(g, UIElement.VisibilityProperty)?.Path?.Path == "ShowSpawnPickRow"),
					"在");
				Check("（界面）自定义状态触发器里能看到「生成 / 变化出来的卡」那几个附加处理勾选框（绑 UsesSpawnOptions）",
					CollectBoundPanels(SelectTabRoot("自定义状态"))
						.Any((System.Windows.Controls.Panel p) => BindingOperations.GetBinding(p, UIElement.VisibilityProperty)?.Path?.Path == "UsesSpawnOptions"),
					"在");
				Check("（界面）自定义状态触发器里能看到「范围限定（随机出什么）」那一行（绑 ShowSpawnFilter）",
					pwGrids.Any((Grid g) => BindingOperations.GetBinding(g, UIElement.VisibilityProperty)?.Path?.Path == "ShowSpawnFilter"), "在");
				Check("（界面）自定义状态触发器里也能看到「生成 / 变化出来的卡：加上关键词」那一行（和卡牌页同一个模板）",
					TextsIn(SelectTabRoot("自定义状态")).Any(t => t.StartsWith("生成 / 变化出来的卡：加上关键词", StringComparison.Ordinal)), "在");
			}

			// ⑦ 生成 / 变化出来的卡「加上关键词」（需求 ⑦：像「是否升级」那样给个选项）
			Check("（界面）「生成 / 变化出来的卡：加上关键词」那一行在卡牌页的效果编辑区里",
				TextsIn(SelectTabRoot("卡牌")).Any(t => t.StartsWith("生成 / 变化出来的卡：加上关键词", StringComparison.Ordinal)), "在");
			Check("下拉候选 =「（不加关键词）」+ 本体 7 个 + 存档里的自定义关键词（与「给予关键词」完全同源）",
				SpawnKeywordChoices.Count == 1 + EffectCatalog.VanillaKeywordChoices.Count + KeywordGen.All(Profile).Count
				&& SpawnKeywordChoices[0].Id.Length == 0
				&& SpawnKeywordChoices.Any(k => k.Id == "Retain") && SpawnKeywordChoices.Any(k => k.Id == "Eternal")
				&& SpawnKeywordChoices.Skip(1).Select(k => k.Id).SequenceEqual(KeywordChoices.Select(k => k.Id)),
				$"{SpawnKeywordChoices.Count} 项");
			CharacterProfile skProbe = ProfileFactory.Sample();
			skProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运", Description = "命运组" });
			CardSpec skCard = new CardSpec { Name = "自检生成带关键词", ClassName = "UiCheckSpawnKeyword", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			skCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv", SpawnTo = "Hand", SpawnKeyword = "Exhaust" });
			skCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnTo = "Hand", SpawnKeyword = "FATE" });
			skCard.Effects.Add(new EffectSpec { Kind = "TransformCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnKeyword = "Ethereal" });
			skCard.Effects.Add(new EffectSpec { Kind = "TransformCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnCardId = "Shiv", SpawnKeyword = "Retain" });
			skProbe.Cards.Add(skCard);
			string skSrc = CSharpCodeGen.CardSource(skProbe, skCard, 0);
			Check("选「消耗」→ 生成出来的每张卡都调本体 AddKeyword(CardKeyword.Exhaust)",
				skSrc.Contains("__gen.AddKeyword(CardKeyword.Exhaust);"), "AddKeyword");
			Check("自定义关键词走「给予关键词」同一套（AddGivenCustomKeyword + 注册表 + 卡面 / 悬停补丁一起生成）",
				skSrc.Contains("__gen.AddGivenCustomKeyword(\"FATE\");")
				&& CSharpCodeGen.UsesGivenCustomKeyword(skProbe), "同一套");
			Check("变化出来的卡也能加上关键词（「本体随机变化」与「填了目标卡」两支都接住本体返回的新卡；两边的返回值类型不同，取值写法也不同）",
				skSrc.Contains("var __tr = await CardCmd.TransformToRandom(") && skSrc.Contains("var __tr = await CardCmd.Transform(")
				&& skSrc.Contains("__tr.cardAdded?.AddKeyword(CardKeyword.Ethereal);")
				&& skSrc.Contains("__tr?.cardAdded?.AddKeyword(CardKeyword.Retain);"), "变化也带");
			Check("标记行写了 CET:SpawnKeyword=（回读靠它）",
				skSrc.Contains("CET:SpawnKeyword=Exhaust") && skSrc.Contains("CET:SpawnKeyword=FATE"), "标记在");
			Check("卡面描述写出「生成出来的卡会带上『X』」（本体关键词与自定义关键词各一份）",
				LocalizationGen.CardsJson(skProbe).Contains("生成出来的卡会带上[gold]消耗[/gold]")
				&& LocalizationGen.CardsJson(skProbe).Contains("生成出来的卡会带上[gold]命运[/gold]"), "描述在");
			Check("列表里也写了这一项（只看「生成卡牌」看不出配了它）",
				skCard.Effects[0].Display.Contains("生成出来的卡带上「消耗」"), skCard.Effects[0].Display);
			// 默认档（没选关键词）：标记行 / 生成代码 / 卡面描述 / 列表文字一个字符都不能变
			CharacterProfile skOff = ProfileFactory.Sample();
			CardSpec skOffCard = new CardSpec { Name = "自检生成不带关键词", ClassName = "UiCheckSpawnKeywordOff", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			skOffCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv", SpawnTo = "Hand" });
			skOff.Cards.Add(skOffCard);
			string skOffSrc = CSharpCodeGen.CardSource(skOff, skOffCard, 0);
			Check("默认档（没选关键词）：标记行不带 CET:SpawnKeyword、代码里没有 AddKeyword、描述 / 列表里没有那句话",
				!skOffSrc.Contains("CET:SpawnKeyword") && !skOffSrc.Contains("AddKeyword(") && !skOffSrc.Contains("AddGivenCustomKeyword(")
				&& !LocalizationGen.CardsJson(skOff).Contains("生成出来的卡会带上")
				&& !skOffCard.Effects[0].Display.Contains("生成出来的卡带上"), "默认档逐字不变");
			Check("校验器：选了不存在的自定义关键词 → 报错（生成出来的代码会印出生键名）",
				ProfileValidator.Validate(new CharacterProfile
				{
					Cards = { new CardSpec { Name = "自检坏关键词", ClassName = "UiCheckSpawnKwBad", Effects = { new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Hand", SpawnKeyword = "NOT_A_KEYWORD" } } } },
				}).Any((ValidationIssue i) => i.IsError && i.Message.Contains("生成 / 变化出来的卡")), "报错了");
			Check("校验器：选了本体关键词 → 给一句提示（「生成的卡会带上『虚无』」）",
				ProfileValidator.Validate(new CharacterProfile
				{
					Cards = { new CardSpec { Name = "自检关键词提示", ClassName = "UiCheckSpawnKwHint", Effects = { new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Hand", SpawnKeyword = "Ethereal" } } } },
				}).Any((ValidationIssue i) => !i.IsError && i.Message.Contains("生成 / 变化出来的卡会带上") && i.Message.Contains("虚无")), "有提示");
			// 生成 → 回读：SpawnKeyword 要原样还原，而且新生成的 AddKeyword 那几行不能被当成「没认出来」
			string skRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_spawnkw_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile skGen = ProfileFactory.Sample();
				skGen.Paths.OutputDir = skRoot;
				skGen.Paths.VanillaProject = Profile.Paths.VanillaProject;
				skGen.Paths.GameDataDir = Profile.Paths.GameDataDir;
				skGen.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运", Description = "命运组" });
				CardSpec skGenCard = new CardSpec { Name = "自检生成带关键词", ClassName = "UiCheckSpawnKwGen", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				skGenCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv", SpawnTo = "Hand", SpawnKeyword = "Exhaust" });
				skGenCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnTo = "Hand", SpawnKeyword = "FATE" });
				skGenCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Draw", SpawnUpgraded = true, SpawnKeyword = "Ethereal" });
				skGenCard.Effects.Add(new EffectSpec { Kind = "TransformCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnKeyword = "Retain" });
				skGen.Cards.Add(skGenCard);
				Check("（准备）配了「生成出来的卡加关键词」的存档能生成工程", ModGenerator.Generate(skGen).Success, skRoot);
				var skRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(skGen));
				var skRecCard = skRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckSpawnKwGen");
				Check("回读：SpawnKeyword 原样还原（本体枚举名 + 自定义关键词的键都要认）",
					skRecCard is not null
					&& skRecCard.Effects.Any((EffectSpec e) => e.Kind == "GenerateCard" && e.SpawnKeyword == "Exhaust")
					&& skRecCard.Effects.Any((EffectSpec e) => e.Kind == "GenerateCard" && e.SpawnKeyword == "FATE")
					&& skRecCard.Effects.Any((EffectSpec e) => e.Kind == "GenerateCard" && e.SpawnKeyword == "Ethereal")
					&& skRecCard.Effects.Any((EffectSpec e) => e.Kind == "TransformCard" && e.SpawnKeyword == "Retain"),
					skRecCard is null ? "卡没回来" : string.Join(" / ", skRecCard.Effects.Select((EffectSpec e) => $"{e.Kind}:{e.SpawnKeyword}")));
				Check("回读没有认不出来的语句（生成的 AddKeyword / __tr.cardAdded 那几行不会被误认成别的效果）",
					!skRec.HasUnparsed, skRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(skRoot)) Directory.Delete(skRoot, true); } catch { }
			}

			// ===== 卡牌「自动填入」  「升级后的自定义描述」（用户要求） ====
			// ① 锻造卡以前**卡面描述是空的**（效果栏是空的、节点图又不写文案）→ 现在从节点图写一只"
			// ① 自定义描述旁边有「自动填入」；卡片页还有第二个框「升级后的自定义描述」，
			//    填了就生成本体的 {IfUpgraded:show:升级后|没升级}
			{
				CharacterProfile autoProf = ProfileFactory.Sample();
				var autoCard = new CardSpec { Name = "自检自动描述卡", ClassName = "UiAutoDescCard", CardType = "Attack", Rarity = "Common", Cost = 1, IsForged = true };
				autoCard.ForgeGraph = new ForgeGraphSpec();
				var adTrig = new ForgeNodeSpec { Kind = "Trigger" };
				adTrig.SetField("Timing", ForgeTimings.CardPlayed);
				var adTarget = new ForgeNodeSpec { Kind = "Target" };
				adTarget.SetField("Pick", "ChosenEnemy");
				var adIf = new ForgeNodeSpec { Kind = "If" };
				var adUnit = new ForgeNodeSpec { Kind = "Unit" };
				adUnit.SetField("Pick", "ChosenEnemy");
				var adPower = new ForgeNodeSpec { Kind = "Power" };
				adPower.SetField("PowerId", "WeakPower");
				var adRelate = new ForgeNodeSpec { Kind = "Relate" };
				adRelate.SetField("Op", "Gt");
				adRelate.SetField("Amount", "3");
				var adDmg = new ForgeNodeSpec { Kind = "Effect" };
				adDmg.SetField("Effect", "Damage");
				adDmg.SetField("Amount", "9");
				var adLoss = new ForgeNodeSpec { Kind = "Effect" };
				adLoss.SetField("Effect", "HpLoss");
				adLoss.SetField("Amount", "5");
				autoCard.ForgeGraph.Nodes.AddRange(new[] { adTrig, adTarget, adIf, adUnit, adPower, adRelate, adDmg, adLoss });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adTrig.Id, To = adTarget.Id, FromPort = 0, ToPort = 0 });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adTarget.Id, To = adIf.Id, FromPort = 0, ToPort = 0 });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adUnit.Id, To = adPower.Id, FromPort = 0, ToPort = 0 });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adPower.Id, To = adRelate.Id, FromPort = 0, ToPort = 1 });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adRelate.Id, To = adIf.Id, FromPort = 0, ToPort = 1 });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adIf.Id, To = adDmg.Id, FromPort = 0, ToPort = 0 });
				autoCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = adIf.Id, To = adLoss.Id, FromPort = 1, ToPort = 0 });
				autoProf.Cards.Add(autoCard);
				string autoText = LocalizationGen.CardAutoText(autoProf, autoCard, upgraded: false);
				Check("锻造卡有了**自动写出来**的卡面描述（以前是空的）",
					autoText.Contains("如果 ") && autoText.Contains("否则：") && autoText.Contains("9 点伤害") && autoText.Contains("5 点生命"),
					autoText.Replace("\n", " ⏎ "));
				Check("自动描述读得出节点图里的条件（关系符 + 状态层数）",
					autoText.Contains("大于 3") && autoText.Contains("层数"), autoText.Replace("\n", " ⏎ "));
				Check("生成的 cards.json 里锻造卡不再是空描述",
					LocalizationGen.CardsJson(autoProf).Contains("UI_AUTO_DESC_CARD.description") 
					&& !LocalizationGen.CardsJson(autoProf).Contains("\"UI_AUTO_DESC_CARD.description\": \"\""),
					"有内容");
				Check("自动填入用的就是同一段（界面按钮 = 生成时那段）",
					string.Equals(autoText, LocalizationGen.CardAutoText(autoProf, autoCard, upgraded: false), StringComparison.Ordinal), "同一段");

				// 升级后单独写一段 → 生成 {IfUpgraded:show:升级后|没升级}
				autoCard.UpgradedCustomDescription = "升级后：改为抽 2 张牌。";
				string composed = LocalizationGen.CardsJson(autoProf);
				Check("填了「升级后的自定义描述」→ 生成本体那套 {IfUpgraded:show:升级后|没升级}",
					composed.Contains("{IfUpgraded:show:") && composed.Contains("升级后：改为抽 2 张牌。")
					&& composed.IndexOf("升级后：改为抽 2 张牌。", StringComparison.Ordinal) < composed.IndexOf("|", StringComparison.Ordinal),
					composed.Split('\n').FirstOrDefault(l => l.Contains("UI_AUTO_DESC_CARD.description"))?.Trim() ?? "(没找到 ");
				autoCard.UpgradedCustomDescription = "";
				Check("（对照）把那一栏清空 → 逐字回到自动描述（老存档不受影响）",
					LocalizationGen.CardsJson(autoProf).Contains("\"UI_AUTO_DESC_CARD.description\": \"" + autoText.Replace("\n", "\\n") + "\"")
					&& !LocalizationGen.CardsJson(autoProf).Contains("IfUpgraded"), "清空后逐字一致");

				// 标记 + 回读：第二个框也要能从工程反推回来"
				autoCard.UpgradedCustomDescription = "升级后再说。";
				Check("「升级后的自定义描述」写进了生成代码的标记（回读靠它）",
					CSharpCodeGen.CardSource(autoProf, autoCard, 0).Contains("CET:UpgradedCustomDescription=升级后再说。"), "标记在");
				autoCard.UpgradedCustomDescription = "";
				Check("（对照）没填时不写那行标记（老工程生成一个字都不变）",
					!CSharpCodeGen.CardSource(autoProf, autoCard, 0).Contains("CET:UpgradedCustomDescription"), "没写");

				// 竖线：本体是按字面量 | 切分 IfUpgraded 选项的，写一个会把那句话截断 → 换全见 + 警告
				autoCard.UpgradedCustomDescription = "升级后 | 带竖线";
				Check("描述里的字面量 | 被换成全角 ｜（不换卡面那句话会解析失败）",
					!LocalizationGen.CardsJson(autoProf).Contains("名 | 带") && LocalizationGen.CardsJson(autoProf).Contains("｜"),
					"换了");
				Check("校验器对这种写法给警告（说清已经换成全角了）",
					ProfileValidator.Validate(autoProf).Any(i => i.Level == "警告" && i.Message.Contains("竖线")), "警告了");
				autoCard.UpgradedCustomDescription = "";
			}

			// ⑦ 遗物 / 药水自定义描述 + 「填入参数」
			CharacterProfile cdProbe = ProfileFactory.Sample();
			var cdRelic = new RelicSpec
			{
				Name = "自检自述遗物", ClassName = "UiCheckDescRelic", Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "Block", Amount = 6m, TargetSide = "Self" } },
				CustomDescription = "每回合给你一点安全感。", CustomDescriptionReplaces = true,
			};
			cdProbe.Relics.Add(cdRelic);
			var cdPotion = new PotionSpec
			{
				Name = "自检自述药水", ClassName = "UiCheckDescPotion", TargetType = "Self",
				Effects = { new EffectSpec { Kind = "Block", Amount = 9m, TargetSide = "Self" } },
				CustomDescription = "喝下去就不疼了。",
			};
			cdProbe.Potions.Add(cdPotion);
			Check("遗物自定义描述：勾「替换」时描述就是你写的那段",
				LocalizationGen.RelicsJson(cdProbe).Contains("\"UI_CHECK_DESC_RELIC.description\": \"每回合给你一点安全感。\""), "替换");
			Check("药水自定义描述：不勾「替换」时是「自动描述 + 换行 + 你写的」（不是整段替换）",
				LocalizationGen.PotionsJson(cdProbe).Contains("喝下去就不疼了。")
				&& LocalizationGen.PotionsJson(cdProbe).Contains("\\n喝下去就不疼了。")
				&& !LocalizationGen.PotionsJson(cdProbe).Contains("description\": \"喝下去就不疼了。\""),
				LocalizationGen.PotionsJson(cdProbe).Split('\n').FirstOrDefault(l => l.Contains("UI_CHECK_DESC_POTION.description")) ?? "(没找到)");
			Check("遗物 / 药水自定义描述也会写进生成代码的标记（回读靠它，本地化表里认不出来）",
				CSharpCodeGen.RelicSource(cdProbe, cdRelic, 0).Contains("CET:CustomDescription=每回合给你一点安全感。")
				&& CSharpCodeGen.PotionSource(cdProbe, cdPotion, 0).Contains("CET:CustomDescription=喝下去就不疼了。"), "标记在");
			var pHintCard = new[] { new EffectSpec { Kind = "Damage", Amount = 8m, TargetSide = "Enemy" }, new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" } };
			Check("「填入参数」列出这条模型真正声明过的变量（卡牌带 :diff()、遗物 / 药水不带）",
				CSharpCodeGen.ParamHints(pHintCard, isCard: true).Any(x => x.Token == "{Damage:diff()}")
				&& CSharpCodeGen.ParamHints(cdRelic.Effects, isCard: false).Any(x => x.Token == "{Block}")
				&& CSharpCodeGen.ParamHints(new[] { new EffectSpec { Kind = "Stun" } }, isCard: false).Count == 0,
				string.Join("、", CSharpCodeGen.ParamHints(pHintCard, isCard: true).Select(x => x.Token)));
			// 「填入参数」只能列**真的声明这**的变量：漏一个 / 多一个，卡面上就是「数字显示不出来」、"
			// 用户报过「自定义描述的参数缺失」—— 查到的是「数值 = X」的「从抽牌堆拿牌」这类 
			// 被当成了「有变量」，菜单里跑出一个 {Value:diff()}，可生成代码里根本没声明它。"
			{
				// 做法：逐种类造一张「只有这一条效果」的卡，把生成代码里 CanonicalVars 之后
				// 那一批变量声明**抠出来**，再看「填入参数」给的每个占位符名字在不在里面。"
				var bad = new List<string>();
				foreach (var kind in EffectCatalog.EffectKinds)
				{
					var probeEff = new EffectSpec { Kind = kind.Kind, Amount = 3m, TargetSide = "Self" };
					if (kind.Kind is "ApplyPower" or "TempPower" or "DoublePower" or "Expose" or "ClearPowerOne" or "PetApplyPower")
						probeEff.PowerId = "StrengthPower";
					if (kind.Kind == "GiveKeyword") probeEff.GivenKeyword = "Retain";
					var one = new CardSpec { Name = "占位符探针", ClassName = "UiCheckParamProbe" };
					one.Effects.Add(probeEff);
					string oneSrc = CSharpCodeGen.CardSource(Profile, one, 0);
					int cv = oneSrc.IndexOf("protected override IEnumerable<DynamicVar> CanonicalVars", StringComparison.Ordinal);
					if (cv < 0) cv = oneSrc.IndexOf("CanonicalVars =>", StringComparison.Ordinal);
					string seg = cv < 0 ? "" : oneSrc.Substring(cv, Math.Min(3000, oneSrc.Length - cv));
					var declared = new HashSet<string>(StringComparer.Ordinal);
					foreach (System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(
						seg, "new\\s+(?:[A-Za-z_][\\w]*\\.)?[A-Za-z_]\\w*Var(?:<[^>]+>)?\\(\\s*(?:\"([^\"]+)\")?"))
					{
						string nm = m.Groups[1].Success ? m.Groups[1].Value : "";
						if (nm.Length > 0) declared.Add(nm);
					}
					foreach (var (token, _) in CSharpCodeGen.ParamHints(one.Effects, isCard: true))
					{
						string varName = token.Trim('{', '}').Split(':')[0];
						// 显式写了名字的变量（"Cards2" 这种）必须在声明里出现"
						if (declared.Count > 0 && !declared.Contains(varName)) bad.Add($"{kind.Kind}→{token}");
					}
				}
				Check("「填入参数」不会给出生成代码里没声明的变量（多一个占位符 = 卡面数字显示不出来）",
					bad.Count == 0, bad.Count == 0 ? "都对" : string.Join("）", bad.Take(4)));
				Check("【数值 = X】的「拿牌 / 全局升级」不再冒出 {Value:diff()}（它压根没声明变量）",
					CSharpCodeGen.ParamHints(new[]
					{
						new EffectSpec { Kind = "TakeFromDraw", Amount = 2m, TargetSide = "Self", AmountIsX = true },
						new EffectSpec { Kind = "UpgradeCardGlobal", Amount = 2m, TargetSide = "Self", AmountIsX = true },
					}, isCard: true).Count == 0, "没有假占位符");
				// ===== 「从三摞拿牌」现在真的声明变量了（用户报：「{Value:diff()} 原样印在卡面上」）=====
				// 截图原话：卡面印着「从抽牌堆里拿取{Value:diff()}张牌 / 从弃牌堆里拿取{Value2:diff()}张牌」。"
				// 根因：这三种效果以前被列在 NoDynamicVarKind 里（当成「没有变量」），"
				// 于是卡面写占位符时游戏按 DynamicVar 的键取不到 → **原样把 {Value:diff()} 印出来**。"
				{
					CharacterProfile takeProf = ProfileFactory.Sample();
					takeProf.Cards.Clear();
					var takeCard = new CardSpec { Name = "自检拿牌", ClassName = "UiCheckTake", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					takeCard.Effects.Clear();
					takeCard.Effects.Add(new EffectSpec { Kind = "TakeFromDraw", Amount = 2m, CardPick = "Chosen", SelectPile = "Draw" });
					takeCard.Effects.Add(new EffectSpec { Kind = "TakeFromDiscard", Amount = 3m, CardPick = "Chosen", SelectPile = "Discard" });
					takeCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
					takeCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Random", SelectPile = "Draw" });
					takeProf.Cards.Add(takeCard);
					string takeSrc = CSharpCodeGen.CardSource(takeProf, takeCard, 0);
					Check("「从抽牌堆 / 弃牌堆拿牌」现在声明 CardsVar（卡面才取得到「拿几张」）",
						takeSrc.Contains("new CardsVar(2)") && takeSrc.Contains("new CardsVar(\"Cards2\", 3)"),
						"声明在");
					Check("「消耗 / 丢弃卡牌」也声明 CardsVar（同一套：几张牌）",
						takeSrc.Contains("new CardsVar(\"Cards3\", 1)") && takeSrc.Contains("new CardsVar(\"Cards4\", 1)"),
						"声明在");
					var takeHints = CSharpCodeGen.ParamHints(takeCard.Effects, isCard: true).Select(x => x.Token).ToList();
					Check("「填入参数」里给的是 {Cards:diff()} / {Cards2:diff()} 这种**真的声明过**的名字（不再是 Value）",
						takeHints.Contains("{Cards:diff()}") && takeHints.Contains("{Cards2:diff()}")
						&& takeHints.All(t => !t.Contains("Value")), string.Join(" / ", takeHints));
					Check("「从三摞拿牌」的数值 = X 时仍然不声明变量（X 直接取，卡面写 X 就行）",
						!CSharpCodeGen.CardSource(takeProf, new CardSpec
						{
							Name = "X拿牌", ClassName = "UiCheckTakeX", CardType = "Skill", Cost = 1,
							Effects = { new EffectSpec { Kind = "TakeFromDraw", Amount = 2m, AmountIsX = true } },
						}, 0).Contains("CardsVar"), "没有多余变量");
				}
				// ===== 生成 / 变化卡牌：升级增量终于有地方可写了（用户报：「填了升级增量还是不变」）=====
				{
					CharacterProfile genTrProf = ProfileFactory.Sample();
					genTrProf.Cards.Clear();
					var genTrCard = new CardSpec { Name = "自检生成变化", ClassName = "UiCheckGenTr", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					genTrCard.Effects.Clear();
					genTrCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, UpgradeAmount = 1m, SpawnTo = "Hand", SpawnCardId = "Shiv" });
					genTrCard.Effects.Add(new EffectSpec { Kind = "TransformCard", Amount = 1m, UpgradeAmount = 2m, CardPick = "Random", SelectPile = "Draw", SpawnCardId = "Shiv" });
					genTrProf.Cards.Add(genTrCard);
					string genTrSrc = CSharpCodeGen.CardSource(genTrProf, genTrCard, 0);
					Check("「生成卡牌 / 变化卡牌」现在声明 CardsVar（以前不声明 → 升级增量没地方写）",
						genTrSrc.Contains("new CardsVar(2)") && genTrSrc.Contains("new CardsVar(\"Cards2\", 1)"), "声明在");
					Check("升级增量真的写进 OnUpgrade 了（生成 +1 / 变化 +2）",
						genTrSrc.Contains("base.DynamicVars[\"Cards\"].UpgradeValueBy(1m);")
						&& genTrSrc.Contains("base.DynamicVars[\"Cards2\"].UpgradeValueBy(2m);"), "增量在");
					Check("自动描述也改成占位符了（升级后卡面数字才跟着变）",
						LocalizationGen.CardsJson(genTrProf).Contains("生成 {Cards:diff()} 张")
						&& LocalizationGen.CardsJson(genTrProf).Contains("{Cards2:diff()} 张牌变化为"),
						LocalizationGen.CardsJson(genTrProf).Replace("\n", " ⏎ "));					Check("「填入参数」里给的是这两个名字",
						CSharpCodeGen.ParamHints(genTrCard.Effects, isCard: true).Select(x => x.Token).ToList()
							is { Count: 2 } hs && hs.Contains("{Cards:diff()}") && hs.Contains("{Cards2:diff()}"), "两个 token");
				}
			}
		}
		Check("「选人界面背景大图」的说明是横图（本体画面 1920×1080，以前写成「1000×1400 的竖图」了）",
			ArtSlots.Any((ArtSlot s) => s.Name == "选人界面背景大图"
				&& s.Requirement.Contains("横图") && s.Requirement.Contains("1920×1080") && !s.Requirement.Contains("1000×1400")),
			ArtSlots.FirstOrDefault((ArtSlot s) => s.Name == "选人界面背景大图")?.Requirement ?? "(没找到)");
		EffectCatalog.SetCustomPowers(new(string, string, bool, bool)[1] { (CustomPowerGen.ClassNameOf(cpProbe, cp1, 0), cp1.Name, cp1.AllowNegativeLayers, cp1.Single) });
		RefreshPowerChoices();
