			Check("配色存盘后可读回", characterProfile32.Colors.CardFrame == cardFrame && characterProfile32.Colors.DeckEntryColor == deckEntryColor, characterProfile32.Colors.Display);
		}
		finally
		{
			try
			{
				File.Delete(path14);
			}
			catch
			{
			}
		}
		Profile.Colors.Apply(CardColorSpec.Presets[0]);
		if (CardList.SelectedItem is CardSpec cardSpec26)
		{
			ObservableCollection<EffectSpec> effects12 = cardSpec26.Effects;
			if (effects12 != null && effects12.Count > 0)
			{
				int times = cardSpec26.Effects[0].Times;
				cardSpec26.Effects[0].Times = 3;
				string path15 = Path.Combine(Path.GetTempPath(), "forge_uicheck_times.json");
				try
				{
					ProfileFactory.Save(Profile, path15);
					CharacterProfile characterProfile33 = ProfileFactory.Load(path15);
					Check("生效次数存盘后可读回", characterProfile33.Cards[0].Effects[0].Times == 3, "读回=" + characterProfile33.Cards[0].Effects[0].Times);
				}
				finally
				{
					cardSpec26.Effects[0].Times = times;
					try
					{
						File.Delete(path15);
					}
					catch
					{
					}
				}
			}
		}
		if (Profile.Cards.Count > 1)
		{
			CardList.SelectedIndex = 1;
			Check("切换卡牌后右侧详情跟随", CardDetail.DataContext == CardUiSelection && CardDetail.DataContext is CardSpec, "面板=" + (CardDetail.DataContext as CardSpec)?.Name);
		}
		if (Profile.Relics.Count > 1)
		{
			RelicList.SelectedIndex = 1;
			Check("切换遗物后右侧详情跟随", RelicDetail.DataContext == RelicList.SelectedItem);
		}
		if (Profile.Potions.Count > 0)
		{
			PotionList.SelectedIndex = 0;
			Check("切换药水后右侧详情跟随", PotionDetail.DataContext == PotionUiSelection);
		}
		// ===== 本轮新增：条件「填负数 = 反向」/ 生命区间（含区间外）/ 抽牌堆洗过牌 =====
		{
			// ① 数量类条件支持「填负数 = 反向」：负数 → 比较符翻过来、数值取绝对值
			string[] negKinds = { "PlayedAtLeast", "HandAtLeast", "HandAtMost", "HpBelowPercent", "HasPowerAtLeast", "ExtraResourceAtLeast" };
			Check("条件列表里所有「至少 / 至多 N」类条件都标了「支持填负数 = 反向」",
				negKinds.All(k => EffectCatalog.FindCondition(k) is { SupportsNegative: true }),
				string.Join("。", negKinds.Where(k => EffectCatalog.FindCondition(k) is not { SupportsNegative: true })));
			Check("每条支持反向的条件都写了一句中文的反向说法",
				negKinds.All(k => !string.IsNullOrWhiteSpace(EffectCatalog.FindCondition(k)?.InvertedDisplay)),
				string.Join("。", negKinds.Where(k => string.IsNullOrWhiteSpace(EffectCatalog.FindCondition(k)?.InvertedDisplay))));
			Check("支持反向的条件的说明里都写了「填负数」",
				negKinds.All(k => (EffectCatalog.FindCondition(k)?.Hint ?? "").Contains("填负数")),
				string.Join("、", negKinds.Where(k => !(EffectCatalog.FindCondition(k)?.Hint ?? "").Contains("填负数"))));
			Check("生命值低于 -20% → 生成的是「生命值高于 20%」（比较符翻过来、数值取绝对值）",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpBelowPercent", Amount = -20m }, isCard: true)
					== "base.Owner.Creature.CurrentHp * 100 >= base.Owner.Creature.MaxHp * 20", ">=");
			Check("拥有某状态至少 -2 层 → 生成「少于 2 层」（GetPowerAmount < 2）",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HasPowerAtLeast", Amount = -2m, PowerId = "VulnerablePower" }, isCard: true)
					== "base.Owner.Creature.GetPowerAmount<VulnerablePower>() < 2", "<");
			Check("拥有额外资源量至少 -2 点 → 生成「少于 2 点」",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "ExtraResourceAtLeast", Amount = -2m }, isCard: true)
					== "((base.Owner?.PlayerCombatState?.Stars) ?? 0) < 2", "<");
			Check("手牌数不少于 -3 张 → 生成「少于 3 张」",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HandAtLeast", Amount = -3m }, isCard: true)
					== "base.Owner is not null && CardPile.GetCards(base.Owner, PileType.Hand).Count() < 3", "<");
			Check("手牌数不多于 -3 张 → 生成「多于 3 张」",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HandAtMost", Amount = -3m }, isCard: true)
					== "base.Owner is not null && CardPile.GetCards(base.Owner, PileType.Hand).Count() > 3", ">");
			Check("本回合已打出至少 -4 张 → 生成「少于 4 张」",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "PlayedAtLeast", Amount = -4m }, isCard: true)
					.Contains("HappenedThisTurn(base.CombatState)) < 4"), "少了");
			Check("填负数时中文文案也跟着反过来（不会照抄 -20）",
				CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HpBelowPercent", Amount = -20m }) == "生命值高于 20%"
				&& CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HasPowerAtLeast", Amount = -2m, PowerId = "VulnerablePower" }) == "拥有易伤少于 2 层"
				&& CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "ExtraResourceAtLeast", Amount = -2m }) == "拥有的额外资源量少于 2 点"
				&& CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HandAtMost", Amount = -3m }) == "手牌数多于 3 张"
				&& CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "PlayedAtLeast", Amount = -4m }) == "本回合打出的牌少于 4 张",
				CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HpBelowPercent", Amount = -20m }));
			Check("不填负数时文案 / 表达式还是老样子（没被反向逻辑带偏）",
				CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HpBelowPercent", Amount = 20m }) == "生命值低于 20%"
				&& CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpBelowPercent", Amount = 20m }, isCard: true)
					== "base.Owner.Creature.CurrentHp * 100 <= base.Owner.Creature.MaxHp * 20", "老样子");
			var invIssues = ProfileValidator.Validate(new CharacterProfile
			{
				Relics = { new RelicSpec
				{
					Name = "自检反向遗物", ClassName = "UiCheckInvRelic", Trigger = "PlayerTurnStart",
					Condition = new ConditionSpec { Kind = "HpBelowPercent", Amount = -20m },
					Effects = { new EffectSpec { Kind = "Block", Amount = 1m } },
				} },
			});
			Check("校验器会提示「填了负数 → 判断反过来」，并写出实际生效的文案",
				invIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("反过来") && i.Message.Contains("生命值高于 20%")),
				invIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("反过来"))?.Message ?? "(没有提示)");
			var everyIssues = ProfileValidator.Validate(new CharacterProfile
			{
				Relics = { new RelicSpec
				{
					Name = "自检每N回合", ClassName = "UiCheckEveryN", Trigger = "PlayerTurnStart",
					Condition = new ConditionSpec { Kind = "EveryNTurns", Amount = -3m },
					Effects = { new EffectSpec { Kind = "Block", Amount = 1m } },
				} },
			});
			Check("不支持反向的条件填负数会**警告**（说清按绝对值处理），不会悄悄按反向生成",
				everyIssues.Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("不支持「填负数 = 反向」")),
				everyIssues.FirstOrDefault((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("反向"))?.Message ?? "(没有警告)");

			// ② 生命区间：两个数值（N~M），任一填负数 = 区间外
			var rangeOpt = EffectCatalog.FindCondition("HpInRange");
			Check("条件列表里有「生命值在 N%~M% 之间」，而且它要两个数值 + 能选看谁",
				rangeOpt is { NeedsAmount: true, NeedsAmount2: true, NeedsTarget: true } && rangeOpt.Display.Contains("N%~M%"),
				rangeOpt?.Display ?? "(没有)");
			Check("生命区间（区间内）：两个比较用 && 串起来，含端点",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpInRange", Amount = 25m, Amount2 = 75m }, isCard: true)
					== "(base.Owner.Creature.CurrentHp * 100 >= base.Owner.Creature.MaxHp * 25 && base.Owner.Creature.CurrentHp * 100 <= base.Owner.Creature.MaxHp * 75)", "&&");
			Check("生命区间（任一填负数 = 区间外）：两个比较用 || 串起来",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpInRange", Amount = -30m, Amount2 = 60m }, isCard: true)
					== "(base.Owner.Creature.CurrentHp * 100 < base.Owner.Creature.MaxHp * 30 || base.Owner.Creature.CurrentHp * 100 > base.Owner.Creature.MaxHp * 60)", "||");
			Check("上界填负数也算区间外（负号填在哪个数上都一样）",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpInRange", Amount = 30m, Amount2 = -60m }, isCard: true)
					.Contains("MaxHp * 30 || base.Owner.Creature.CurrentHp * 100 > base.Owner.Creature.MaxHp * 60"), "||");
			Check("两个数值写反了会自动排好（60~30 和 30~60 生成一模一样）",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpInRange", Amount = 60m, Amount2 = 30m }, isCard: true)
					== CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpInRange", Amount = 30m, Amount2 = 60m }, isCard: true), "已排序");
			Check("生命区间的中文文案：区间内写「在 N%~M% 之间」、区间外写「之外（区间外）」",
				CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HpInRange", Amount = 25m, Amount2 = 75m }) == "生命值在 25%~75% 之间"
				&& CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HpInRange", Amount = -30m, Amount2 = 60m }) == "生命值在 30%~60% 之外（区间外）",
				CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "HpInRange", Amount = -30m, Amount2 = 60m }));
			Check("生命区间也能看敌人（指向对象照常拼进去）",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "HpInRange", Amount = 25m, Amount2 = 75m, Target = "AllEnemies" }, isCard: true)
					.Contains("Enemies.All(c => !c.IsAlive || (c.CurrentHp * 100 >= c.MaxHp * 25 && c.CurrentHp * 100 <= c.MaxHp * 75))"), "看敌人");
			var rangeIssues = ProfileValidator.Validate(new CharacterProfile
			{
				Relics = { new RelicSpec
				{
					Name = "自检区间遗物", ClassName = "UiCheckRangeRelic", Trigger = "PlayerTurnStart",
					Condition = new ConditionSpec { Kind = "HpInRange", Amount = -30m, Amount2 = 60m },
					Effects = { new EffectSpec { Kind = "Block", Amount = 1m } },
				} },
			});
			Check("校验器会提示「生命区间填了负数 → 判断成区间外」，并写出区间",
				rangeIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("区间外") && i.Message.Contains("30%~60%")),
				rangeIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("区间外"))?.Message ?? "(没有提示)");
			var rangeOkIssues = ProfileValidator.Validate(new CharacterProfile
			{
				Relics = { new RelicSpec
				{
					Name = "自检区间遗物2", ClassName = "UiCheckRangeRelic2", Trigger = "PlayerTurnStart",
					Condition = new ConditionSpec { Kind = "HpInRange", Amount = 30m, Amount2 = 60m },
					Effects = { new EffectSpec { Kind = "Block", Amount = 1m } },
				} },
			});
			Check("两个数值都是正数时不会有「区间外」提示（就是普通的区间内）",
				!rangeOkIssues.Any((ValidationIssue i) => i.Message.Contains("区间外")), "没有提示");

			// ③ 界面上：选了「生命区间」才会出现第二个数值输入框
			SelectTabRoot("卡牌");
			int uiCardIndex = -1;
			for (int ci = 0; ci < CardList.Items.Count; ci++)
				if (CardList.Items[ci] is CardSpec cc && cc.Effects.Count > 0) { uiCardIndex = ci; break; }
			if (uiCardIndex >= 0) CardList.SelectedIndex = uiCardIndex;
			PumpDispatcher(120);
			// 效果编辑面板的 DataContext 是「效果列表里选中的那一条」——不选就没有数据（以前也是这个行为）
			if (CardEffectList.Items.Count > 0) CardEffectList.SelectedIndex = 0;
			PumpDispatcher(150);
			List<TextBox> condBoxes = new List<TextBox>();
			CollectTextBoxes(this, condBoxes);
			var nBox = condBoxes.FirstOrDefault((TextBox t) => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path == "Condition.Amount");
			List<TextBox> mBoxes = condBoxes.Where((TextBox t) => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path == "Condition.Amount2").ToList();
			Check("条件编辑区里有「数值 N」和「~ 数值 M（%）」两个输入框", nBox is not null && mBoxes.Count > 0,
				$"数值 N={(nBox is not null)} / 数值 M={mBoxes.Count} 个");
			Check("第二个数值框的显示绑在「这个条件需不需要第二个数值」上（别的条件时收起来）",
				mBoxes.Count > 0 && mBoxes.All((TextBox t) => BindingOperations.GetBinding(t, UIElement.VisibilityProperty)?.Path?.Path == "Condition.NeedsAmount2"),
				mBoxes.Count == 0 ? "(没找到)" : string.Join(" / ", mBoxes.Select((TextBox t) => BindingOperations.GetBinding(t, UIElement.VisibilityProperty)?.Path?.Path ?? "(没绑上)")));
			Check("「数值 N」输入框的悬停提示写了「填负数 = 判断反过来」",
				nBox?.ToolTip is string negTip && negTip.Contains("填负数") && negTip.Contains("反过来"), nBox?.ToolTip as string ?? "(没有提示)");
			// 真按界面逻辑走一遍：选到需要第二个数值的条件才展开（这里直接改选中卡的第一条效果的条件）
			CardSpec rangeUiCard = CardList.SelectedItem as CardSpec;
			if (rangeUiCard is not null && rangeUiCard.Effects.Count > 0)
			{
				ConditionSpec uiCond = rangeUiCard.Effects[0].Condition;
				// 只认「这一条效果自己的」那个框（界面上别的条件编辑区也可能有同名的框）
				bool IsMine(TextBox t) => t.DataContext switch
				{
					EffectSpec es => ReferenceEquals(es.Condition, uiCond),
					ConditionSpec cs => ReferenceEquals(cs, uiCond),
					_ => false,
				};
				TextBox mineBox = mBoxes.FirstOrDefault(IsMine);
				// 效果列表没选中时，编辑面板的 DataContext 是 null（绑定全部落空 → 控件按默认值显示），这些框不算数
				List<TextBox> liveBoxes = mBoxes.Where((TextBox t) => t.DataContext is not null).ToList();
				uiCond.Kind = "HandAtLeast";
				uiCond.Amount = 2m;
				PumpDispatcher(150);
				bool hiddenWhenNotNeeded = mineBox is not null ? !mineBox.IsVisible : liveBoxes.All((TextBox t) => !t.IsVisible);
				uiCond.Kind = "HpInRange";
				uiCond.Amount = 25m;
				uiCond.Amount2 = 75m;
				PumpDispatcher(150);
				bool shownWhenNeeded = mineBox is not null ? mineBox.IsVisible : liveBoxes.Any((TextBox t) => t.IsVisible);
				Check("选「生命值在 N%~M% 之间」时第二个数值框才出现（选别的条件时是收起来的）",
					shownWhenNeeded && hiddenWhenNotNeeded,
					$"这个条件 NeedsAmount2={uiCond.NeedsAmount2} / 选生命区间时可见={shownWhenNeeded} / 选手牌条件时收起来={hiddenWhenNotNeeded}（找到对应输入框={(mineBox is not null)}）"
					+ $" ｜ 面板上的卡={((CardDetail.DataContext as CardSpec)?.Name ?? "(空)")} 选中的卡={rangeUiCard.Name} ｜ 诊断="
					+ string.Join(" ; ", mBoxes.Select((TextBox t) => $"{(t.DataContext?.GetType().Name ?? "null")}"
						+ $"/{(t.DataContext is EffectSpec e2 ? e2.Kind + ":" + e2.Condition.Kind : t.DataContext is ConditionSpec c2 ? c2.Kind : "?")}"
						+ $"/{(t.Parent as FrameworkElement)?.GetType().Name ?? "?"}/可见={t.IsVisible}")));
				uiCond.Kind = "None";
				uiCond.Amount = 0m;
				uiCond.Amount2 = 0m;
				PumpDispatcher(150);
			}
			else
			{
				Check("（跳过）界面上展开第二个数值框的检查：卡牌列表里没选中带效果的卡", ok: false, $"选中={(rangeUiCard?.Name ?? "(空)")} / 效果={rangeUiCard?.Effects.Count ?? 0} 条");
			}

			// ④ 抽牌堆洗过牌：条件（生成的记录器 + 补丁）和遗物触发时机（override AfterShuffle）
			var shuffleTrigger = EffectCatalog.RelicTriggers.FirstOrDefault((TriggerOption t) => t.Id == "Shuffle");
			Check("遗物触发时机里有「抽牌堆打乱洗牌时」（本体「大～抱抱」用的就是 AfterShuffle）",
				shuffleTrigger is not null && shuffleTrigger.Display == "抽牌堆打乱洗牌时" && shuffleTrigger.HookSignature.Contains("AfterShuffle"),
				shuffleTrigger?.Display ?? "(没有)");
			Check("两条洗牌条件都不需要填数值（问的只是「洗过没有」）",
				EffectCatalog.FindCondition("ShuffledThisTurn") is { NeedsAmount: false }
				&& EffectCatalog.FindCondition("ShuffledThisCombat") is { NeedsAmount: false }, "不需要数值");
			Check("洗牌条件的说明里写明了「开局的洗牌不算」（本体开局走 ModifyShuffleOrder）",
				(EffectCatalog.FindCondition("ShuffledThisTurn")?.Hint ?? "").Contains("开局的洗牌不算"), "写了");
			CardSpec shuffleCard = new CardSpec { Name = "自检洗牌", ClassName = "UiCheckShuffle", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			shuffleCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
			shuffleCard.Condition.Kind = "ShuffledThisCombat";
			RelicSpec shuffleRelic = new RelicSpec { Name = "自检洗牌遗物", ClassName = "UiCheckShuffleRelic", Rarity = "Common", Trigger = "Shuffle" };
			shuffleRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m });
			CharacterProfile shuffleProbe = ProfileFactory.Sample();
			shuffleProbe.Cards.Add(shuffleCard);
			shuffleProbe.Relics.Add(shuffleRelic);
			Naming shuffleNaming = Naming.From(shuffleProbe);
			Check("只有真的用到洗牌条件才生成记录器（没用到就不多生成文件）",
				CSharpCodeGen.UsesShuffleCondition(shuffleProbe) && !CSharpCodeGen.UsesShuffleCondition(ProfileFactory.Sample()), "认得出来");
			Check("洗牌条件生成的表达式走的是工具生成的记录器（本体没有可查询的洗牌状态）",
				CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "ShuffledThisTurn" }, isCard: true)
					== $"base.Owner is not null && {shuffleNaming.ShuffleTrackerClass}.ShuffledThisTurn(base.Owner)"
				&& CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "ShuffledThisCombat" }, isCard: true)
					== $"base.Owner is not null && {shuffleNaming.ShuffleTrackerClass}.ShuffledThisCombat(base.Owner)", shuffleNaming.ShuffleTrackerClass);
			string shuffleRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_shuffle_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				shuffleProbe.Paths.OutputDir = shuffleRoot;
				shuffleProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				shuffleProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				Check("（准备）带洗牌条件的存档能生成工程", ModGenerator.Generate(shuffleProbe).Success, shuffleRoot);
				string shuffleDir = ModGenerator.ProjectRootOf(shuffleProbe);
				string trackerPath = Path.Combine(shuffleDir, "cs", "ShuffleTracker.cs");
				Check("用到洗牌条件 → 生成了「抽牌堆洗过牌」记录器 + 补丁", File.Exists(trackerPath), trackerPath);
				string trackerSrc = File.Exists(trackerPath) ? File.ReadAllText(trackerPath, Encoding.UTF8) : "";
				Check("记录器的补丁打在本体 Hook.AfterShuffle 上",
					trackerSrc.Contains("[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Hooks.Hook), \"AfterShuffle\")]")
					&& trackerSrc.Contains("[HarmonyLib.HarmonyPostfix]"), "补丁在");
				Check("记录器只用「表达式体 + 单行 if」写法（曾经写成 `=> {` 导致生成出来的代码编不过）",
					trackerSrc.Contains("public static bool ShuffledThisTurn(Player? player) =>")
					&& trackerSrc.Contains("public static bool ShuffledThisCombat(Player? player) =>")
					&& trackerSrc.Contains("public static int ShuffleCountThisCombat(Player? player) =>")
					&& !trackerSrc.Contains(") => {"), "语法对");
				Check("记录器用「这一场战斗的 ICombatState + 当前回合号」区分（换一场战斗自动重算）",
					trackerSrc.Contains("rec.State != state") && trackerSrc.Contains("rec.Turn == pcs.TurnNumber"), "对");
				string shuffleCardSrc = File.ReadAllText(Path.Combine(shuffleDir, "cs", "Cards", "UiCheckShuffle.cs"), Encoding.UTF8);
				Check("卡牌条件读记录器（本场战斗洗过牌）",
					shuffleCardSrc.Contains($"{shuffleNaming.ShuffleTrackerClass}.ShuffledThisCombat(base.Owner)"), "读了记录器");
				string shuffleRelicSrc = File.ReadAllText(Path.Combine(shuffleDir, "cs", "Relics", "UiCheckShuffleRelic.cs"), Encoding.UTF8);
				Check("遗物「抽牌堆打乱洗牌时」= override AfterShuffle + 只看自己洗的牌（和大～抱抱一模一样）",
					shuffleRelicSrc.Contains("public override async Task AfterShuffle(PlayerChoiceContext choiceContext, Player shuffler)")
					&& shuffleRelicSrc.Contains("if (shuffler != base.Owner) return;"), "对");
				var shuffleRec = ProjectRecovery.FromProject(shuffleDir);
				Check("回读：洗牌条件 / 遗物触发时机都认得出来（没有认不出来的语句）",
					!shuffleRec.HasUnparsed, shuffleRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				var recShuffleCard = shuffleRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckShuffle");
				Check("回读：卡牌的「本场战斗洗过牌」条件原样回来",
					recShuffleCard is not null && recShuffleCard.Condition.Kind == "ShuffledThisCombat",
					recShuffleCard?.Condition.Kind ?? "(没回读出来)");
				var recShuffleRelic = shuffleRec.Profile.Relics.FirstOrDefault((RelicSpec r) => r.ClassName == "UiCheckShuffleRelic");
				Check("回读：遗物触发时机「抽牌堆打乱洗牌时」原样回来",
					recShuffleRelic is not null && recShuffleRelic.Trigger == "Shuffle", recShuffleRelic?.Trigger ?? "(没回读出来)");
			}
			finally
			{
				try { if (Directory.Exists(shuffleRoot)) Directory.Delete(shuffleRoot, true); } catch { }
			}

			// ⑤ 回读：反向 / 生命区间也要原样认回来（存档被误覆盖时救命）
			string condRecRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_condrec_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile recProbe = ProfileFactory.Sample();
				recProbe.Paths.OutputDir = condRecRoot;
				recProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				recProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec recInv = new CardSpec { Name = "自检反向回读", ClassName = "UiCheckRecInv", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				recInv.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
				recInv.Condition.Kind = "HpBelowPercent";
				recInv.Condition.Amount = -20m;
				CardSpec recRange = new CardSpec { Name = "自检区间回读", ClassName = "UiCheckRecRange", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				recRange.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
				recRange.Condition.Kind = "HpInRange";
				recRange.Condition.Amount = -30m;
				recRange.Condition.Amount2 = 60m;
				CardSpec recPower = new CardSpec { Name = "自检状态反向回读", ClassName = "UiCheckRecPower", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				recPower.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m });
				recPower.Condition.Kind = "HasPowerAtLeast";
				recPower.Condition.Amount = -2m;
				recPower.Condition.PowerId = "VulnerablePower";
				recProbe.Cards.Add(recInv);
				recProbe.Cards.Add(recRange);
				recProbe.Cards.Add(recPower);
				Check("（准备）反向 / 生命区间的存档能生成工程", ModGenerator.Generate(recProbe).Success, condRecRoot);
				var condRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(recProbe));
				Check("回读没有认不出来的语句", !condRec.HasUnparsed, condRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				var rrInv = condRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckRecInv");
				var rrRange = condRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckRecRange");
				var rrPower = condRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckRecPower");
				Check("回读：生命值低于 -20%（反向）原样回来",
					rrInv is not null && rrInv.Condition.Kind == "HpBelowPercent" && rrInv.Condition.Amount == -20m,
					rrInv is null ? "(没回读出来)" : $"{rrInv.Condition.Kind} {rrInv.Condition.Amount}");
				Check("回读：生命区间 -30~60（区间外）原样回来",
					rrRange is not null && rrRange.Condition.Kind == "HpInRange" && rrRange.Condition.Amount == -30m && rrRange.Condition.Amount2 == 60m,
					rrRange is null ? "(没回读出来)" : $"{rrRange.Condition.Kind} {rrRange.Condition.Amount}/{rrRange.Condition.Amount2}");
				Check("回读：拥有虚弱至少 -2 层（反向）原样回来",
					rrPower is not null && rrPower.Condition.Kind == "HasPowerAtLeast" && rrPower.Condition.Amount == -2m && rrPower.Condition.PowerId == "VulnerablePower",
					rrPower is null ? "(没回读出来)" : $"{rrPower.Condition.Kind} {rrPower.Condition.Amount}");
			}
			finally
			{
				try { if (Directory.Exists(condRecRoot)) Directory.Delete(condRecRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：描述里的富文本标签自动纠正 + 数值 0 的效果不显示 / 不执行 =====
		{
			// ① 富文本标签体检：用户在游戏里看到的「[gold] 被原样印出来」其实是他把标签写成了 [god]
			//    —— 本体的 MegaLabelHelper.ParseBbcode 对标签是严格的，拼错 / 没闭合 / 交叉嵌套都会抛异常
			//    （日志里的 "Found end tag gold, expected god"），那一次自动字号算崩，方括号就原样显示。
			var fix1 = RichTextFix.Repair("[god]中文[/gold]");
			Check("拼错的标签（[god]）会被改成最接近的那个（[gold]）",
				fix1.Text == "[gold]中文[/gold]" && fix1.Notes.Any(n => n.Contains("[god]") && n.Contains("[gold]")),
				fix1.Text + " ｜ " + string.Join(" / ", fix1.Notes));
			var fix2 = RichTextFix.Repair("[gold]没闭合的文字");
			Check("没闭合的标签会在结尾自动补上闭合标签", fix2.Text == "[gold]没闭合的文字[/gold]", fix2.Text);
			var fix3 = RichTextFix.Repair("多余的[/gold]闭合");
			Check("多出来的闭合标签会被删掉（本体解析器会为它抛异常）", fix3.Text == "多余的闭合", fix3.Text);
			var fix4 = RichTextFix.Repair("[gold][blue]交叉[/gold][/blue]");
			Check("交叉嵌套会被理顺成正确顺序（内容一个字不动）",
				fix4.Text == "[gold][blue]交叉[/blue][/gold]" && fix4.Text.Replace("[", "").Replace("]", "").Contains("交叉"),
				fix4.Text);
			var fix5 = RichTextFix.Repair("正常[gold]金色[/gold]、[blue]{Damage:diff()}[/blue]");
			Check("正常写法的标签一个字都不改（也不会误报）",
				fix5.Text == "正常[gold]金色[/gold]、[blue]{Damage:diff()}[/blue]" && fix5.Notes.Count == 0,
				fix5.Text + " ｜ 提示数=" + fix5.Notes.Count);
			var fix6 = RichTextFix.Repair("[lb]方括号[rb]和 [color=#EFC851]原生颜色[/color]");
			Check("[lb]/[rb]（本体的方括号转义）和带参数的 Godot 原生标签都不动",
				fix6.Text == "[lb]方括号[rb]和 [color=#EFC851]原生颜色[/color]" && fix6.Notes.Count == 0, fix6.Text);
			// 生成出来的本地化表里必须已经是修好的文本（原始文本仍留在 CET 标记里，回读不受影响）
			CharacterProfile richProbe = ProfileFactory.Sample();
			CardSpec richCard = new CardSpec
			{
				Name = "自检富文本", ClassName = "UiCheckRich", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true,
				CustomDescription = "写错的[god]中文[/gold]，还有没闭合的[gold]金色",
			};
			richCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m });
			richProbe.Cards.Add(richCard);
			string richCardsJson = LocalizationGen.CardsJson(richProbe);
			Check("生成出来的卡面描述里 [god] 已经变成 [gold]、没闭合的也补上了",
				richCardsJson.Contains("[gold]中文[/gold]") && richCardsJson.Contains("[gold]金色[/gold]")
				&& !richCardsJson.Contains("[god]"), "已修好");
			Check("校验器会把「标签写错了」报出来（用户能知道游戏里为什么显示方括号）",
				ProfileValidator.Validate(richProbe).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("富文本标签有问题")),
				"报了");
			Check("名字里没有方括号时不会误报富文本问题",
				!ProfileValidator.Validate(ProfileFactory.Sample()).Any((ValidationIssue i) => i.Message.Contains("富文本标签")), "没误报");

			// ② 数值 0 的效果：不显示、也不执行（不然 0 点伤害会被力量加成、0 点格挡会被敏捷加成）
			Check("数值 0 + 升级也不加数值 → 整条丢掉；数值 0 + 有升级增量 → 只有升级后才存在",
				CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "Damage", Amount = 0m, UpgradeAmount = 0m })
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "Damage", Amount = 0m, UpgradeAmount = 6m })
				&& CSharpCodeGen.IsUpgradeOnlyZero(new EffectSpec { Kind = "Damage", Amount = 0m, UpgradeAmount = 6m })
				&& !CSharpCodeGen.IsUpgradeOnlyZero(new EffectSpec { Kind = "Damage", Amount = 6m, UpgradeAmount = 0m }), "分类对");
			Check("0 有意义的那些效果不会被误判（召唤伙伴填 0 = 用「召唤物」页的血量；数值 = X 也不是 0）",
				!CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "SummonPet", Amount = 0m })
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "TimesUp", Amount = 0m })
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "Damage", Amount = 0m, AmountIsX = true }), "没误判");
			CharacterProfile zeroProbe = ProfileFactory.Sample();
			CardSpec zeroBlock = new CardSpec { Name = "自检零格挡", ClassName = "UiCheckZeroBlock", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			zeroBlock.Effects.Add(new EffectSpec { Kind = "Block", Amount = 0m, TargetSide = "Self" });
			zeroBlock.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" });
			zeroProbe.Cards.Add(zeroBlock);
			string zeroBlockSrc = CSharpCodeGen.CardSource(zeroProbe, zeroBlock, 0);
			Check("数值 0 的「获得格挡」整条不生成（不会被敏捷加成）",
				!zeroBlockSrc.Contains("GainBlock") && zeroBlockSrc.Contains("DamageCmd.Attack"), "格挡没了 / 伤害还在");
			string zeroBlockJson = LocalizationGen.CardsJson(zeroProbe);
			int zeroBlockAt = zeroBlockJson.IndexOf("\"UI_CHECK_ZERO_BLOCK.description\"", StringComparison.Ordinal);
			string zeroBlockSeg = zeroBlockAt < 0 ? "" : zeroBlockJson.Substring(zeroBlockAt, Math.Min(160, zeroBlockJson.Length - zeroBlockAt));
			Check("数值 0 的「获得格挡」也不写进卡面描述",
				zeroBlockAt >= 0 && zeroBlockSeg.Contains("造成") && !zeroBlockSeg.Contains("格挡"),
				zeroBlockSeg.Replace("\n", " ").Replace("\r", ""));
			CardSpec zeroTiny = new CardSpec { Name = "自检全零", ClassName = "UiCheckZeroTiny", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			zeroTiny.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 0m, TargetSide = "Enemy" });
			Check("只剩 0 值效果时这张牌不再变成「要选目标」的攻击牌",
				CSharpCodeGen.CardSource(zeroProbe, zeroTiny, 0).Contains("TargetType.Self"), "TargetType.Self");
			CardSpec zeroUp = new CardSpec { Name = "自检零伤升级", ClassName = "UiCheckZeroUp", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			zeroUp.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 0m, UpgradeAmount = 6m, TargetSide = "Enemy" });
			zeroProbe.Cards.Add(zeroUp);
			zeroProbe.Cards.Add(zeroTiny);
			string zeroUpSrc = CSharpCodeGen.CardSource(zeroProbe, zeroUp, 0);
			Check("数值 0 + 升级增量 6：生成出来的伤害被 if (base.IsUpgraded) 包住（没升级时一点都不打）",
				zeroUpSrc.Contains("if (base.IsUpgraded)") && zeroUpSrc.Contains("UpgradeValueBy(6m)")
				&& zeroUpSrc.Contains("DamageCmd.Attack"), "有守卫");
			Check("这张牌仍然是要选目标的攻击牌（升级后要用）",
				zeroUpSrc.Contains("TargetType.AnyEnemy"), "AnyEnemy");
			string zeroUpDesc = LocalizationGen.CardsJson(zeroProbe);
			Check("数值 0 + 升级增量：描述用本体的 {IfUpgraded:show:…} 包住（没升级时不显示这一行）",
				zeroUpDesc.Contains("{IfUpgraded:show:对指定敌人造成 {Damage:diff()} 点伤害。}"), "藏起来了");
			var zeroIssues = ProfileValidator.Validate(zeroProbe);
			Check("校验器会提示「数值 0 的效果不显示也不执行」以及「升级后才生效」",
				zeroIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("不显示、也不会执行"))
				&& zeroIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("升级之后才出现并生效")), "提示在");
			// 遗物 / 药水上的 0 值效果同样整条丢掉
			CharacterProfile zeroRelicProbe = ProfileFactory.Sample();
			zeroRelicProbe.Relics.Add(new RelicSpec
			{
				Name = "自检零回复遗物", ClassName = "UiCheckZeroHeal", Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "Heal", Amount = 0m } },
			});
			Check("遗物上的 0 值效果也不生成、不写描述",
				!CSharpCodeGen.RelicSource(zeroRelicProbe, zeroRelicProbe.Relics[^1], 0).Contains("CreatureCmd.Heal")
				&& !LocalizationGen.RelicsJson(zeroRelicProbe).Contains("回复 0 点生命"), "丢掉了");
			// 生成 → 回读：升级增量要原样回来（数值 0 的那条效果本来就不进代码，回读自然也没有它）
			string zeroRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_zero_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile zeroGenProbe = ProfileFactory.Sample();
				zeroGenProbe.Paths.OutputDir = zeroRoot;
				zeroGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				zeroGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec genZeroUp = new CardSpec { Name = "自检零伤升级", ClassName = "UiCheckZeroUp", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				genZeroUp.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 0m, UpgradeAmount = 6m, TargetSide = "Enemy" });
				zeroGenProbe.Cards.Add(genZeroUp);
				Check("（准备）带 0 值效果 / 升级增量的存档能生成工程", ModGenerator.Generate(zeroGenProbe).Success, zeroRoot);
				var zeroRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(zeroGenProbe));
				var recUp = zeroRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckZeroUp");
				Check("回读：数值 0 + 升级增量 6 原样回来（回读不会把它当成「有伤害的普通卡」）",
					recUp is not null && recUp.Effects.Any((EffectSpec e) => e.Kind == "Damage" && e.Amount == 0m && e.UpgradeAmount == 6m),
					recUp is null ? "(没回读出来)" : string.Join(" / ", recUp.Effects.Select((EffectSpec e) => $"{e.Kind} {e.Amount}/+{e.UpgradeAmount}")));
				Check("回读没有认不出来的语句", !zeroRec.HasUnparsed, zeroRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(zeroRoot)) Directory.Delete(zeroRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：能量 / 药水图标不再靠「改本体的图集精灵表」（多个模组会互相覆盖） =====
		{
			// 为什么改：每个模组各带一份 ui_atlas.tpsheet（本体 102 条 + 自己那条），
			// 而模组 pck 的同一个路径只有一个能生效（后挂载的盖掉前面的）—— 同时装两个自建角色时，
			// 另一个角色的能量图标就变成 "Missing sprite 'card/energy_xxx' in ui_atlas"，游戏里直接消失
			//（ui_atlas 在图集加载器里没有回退路径）。现在改成运行时把「我们自己的精灵」供给 AtlasManager。
			string atlasRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_atlas_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile atlasProbe = ProfileFactory.Sample();
				atlasProbe.Paths.OutputDir = atlasRoot;
				atlasProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				atlasProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				Directory.CreateDirectory(atlasRoot);
				string energySrc = Path.Combine(atlasRoot, "energy_src.png");
				byte[] energyPx = new byte[64 * 64 * 4];
				for (int pi = 0; pi < energyPx.Length; pi += 4)
				{
					energyPx[pi] = 210; energyPx[pi + 1] = 60; energyPx[pi + 2] = 90; energyPx[pi + 3] = 255;
				}
				PngUtil.WriteRgba(energySrc, 64, 64, energyPx);
				atlasProbe.Art.EnergyIcon = energySrc;
				// 额外资源量开着、但**不传图标**：遗物栏那个隐藏遗物也得有回退图
				atlasProbe.ExtraResource.Enabled = true;
				atlasProbe.ExtraResource.Name = "自检资源";
				atlasProbe.ExtraResource.Icon = "";
				Check("（准备）带能量图标 / 药水 / 额外资源量的存档能生成工程", ModGenerator.Generate(atlasProbe).Success, atlasRoot);
				string atlasProject = ModGenerator.ProjectRootOf(atlasProbe);
				var atlasNaming = Naming.From(atlasProbe);

				string[] leftovers = Directory.EnumerateFiles(atlasProject, "*.tpsheet", SearchOption.AllDirectories).ToArray();
				Check("生成出来的工程里**不再**有图集精灵表（.tpsheet）—— 那正是多个模组互相覆盖的根源",
					leftovers.Length == 0, leftovers.Length == 0 ? "没有 tpsheet" : string.Join(" / ", leftovers.Select(Path.GetFileName)));

				var atlasEntries = ArtGenerator.AtlasSpriteEntries(atlasProbe, atlasProject);
				Check("能量 / 药水图标都进了「我们自己供给」的清单（能量 1 条 + 每支药水 2 条）",
					atlasEntries.Any((ArtGenerator.AtlasSpriteEntry e) => e.Atlas == "ui_atlas" && e.Sprite == $"card/energy_{atlasNaming.EnergyColor}")
					&& atlasEntries.Count((ArtGenerator.AtlasSpriteEntry e) => e.Atlas == "potion_atlas") == atlasProbe.Potions.Count
					&& atlasEntries.Count((ArtGenerator.AtlasSpriteEntry e) => e.Atlas == "potion_outline_atlas") == atlasProbe.Potions.Count,
					$"{atlasEntries.Count} 条：" + string.Join(" / ", atlasEntries.Select((ArtGenerator.AtlasSpriteEntry e) => e.Atlas + ":" + e.Sprite)));
				// V0.2.199：每瓶药水的精灵名必须各不相同、且各自指向自己那张图 ——
				// 「上传的图标怎么在每一个药水都会显示」这条报错，先把「生成端有没有共用一张」钉死在这里。
				var potionSprites = atlasEntries.Where((ArtGenerator.AtlasSpriteEntry e) => e.Atlas == "potion_atlas").ToArray();
				Check("每瓶药水的图集精灵名互不相同、各自指向自己那张图（不允许共用一张）",
					potionSprites.Select((ArtGenerator.AtlasSpriteEntry e) => e.Sprite).Distinct().Count() == potionSprites.Length
					&& potionSprites.All((ArtGenerator.AtlasSpriteEntry e) => e.TexturePath.EndsWith("/" + e.Sprite + ".png", StringComparison.Ordinal)),
					string.Join(" / ", potionSprites.Select((ArtGenerator.AtlasSpriteEntry e) => e.Sprite + "→" + Path.GetFileName(e.TexturePath))));
				Check("能量图标用我们自己的图集页（不再指向本体 ui_atlas_0.png 里铁甲战士那一块），区域 74×74",
					atlasEntries.Any((ArtGenerator.AtlasSpriteEntry e) => e.Atlas == "ui_atlas"
						&& e.TexturePath.EndsWith($"{atlasNaming.EnergyColor}_energy_page_0.png", StringComparison.Ordinal) && e.W == 74 && e.H == 74),
					atlasEntries.First((ArtGenerator.AtlasSpriteEntry e) => e.Atlas == "ui_atlas").TexturePath);
				string energyTres = File.ReadAllText(Path.Combine(atlasProject, "images", "atlases", "ui_atlas.sprites", "card", $"energy_{atlasNaming.EnergyColor}.tres"));
				Check("能量图标的 .tres 也指向我们自己的图集页（内容与补丁一致）",
					energyTres.Contains($"{atlasNaming.EnergyColor}_energy_page_0.png") && energyTres.Contains("Rect2(0, 0, 74, 74)"),
					energyTres.Replace("\n", " "));

				string atlasPatchPath = Path.Combine(atlasProject, "cs", "AtlasSpritePatch.cs");
				string atlasPatchSrc = File.Exists(atlasPatchPath) ? File.ReadAllText(atlasPatchPath) : "";
				Check("生成了图集精灵补丁 cs/AtlasSpritePatch.cs", File.Exists(atlasPatchPath),
					File.Exists(atlasPatchPath) ? atlasNaming.AtlasSpritePatchClass : "没找到");
				Check("补丁拦的是本体 AtlasManager 的 HasSprite / GetSprite（_Exists 走前者，不拦连 _Load 都不会调用）",
					atlasPatchSrc.Contains("nameof(MegaCrit.Sts2.Core.Assets.AtlasManager.HasSprite)")
					&& atlasPatchSrc.Contains("nameof(MegaCrit.Sts2.Core.Assets.AtlasManager.GetSprite)")
					&& atlasPatchSrc.Contains("[HarmonyLib.HarmonyPrefix]"), "两个都拦了");
				// 【踩过的坑】[HarmonyPatch] 写在**方法**上时 PatchAll 会静默跳过整个类：
				// 模组加载日志一切正常、补丁却完全没生效（实测：方法级注解的补丁不会被打上，也不报错）。
				// 所以这里强制检查「注解贴在类上」+「参数用 __args 注入（不看本体形参名）」。
				// 注解可能跨多行，所以要跳到属性结束（以 )] 收尾）再看下一行。
				bool ClassLevelPatchOnly(string path, out string bad)
				{
					bad = "";
					string[] ls = File.ReadAllText(path).Split('\n');
					for (int li = 0; li < ls.Length; li++)
					{
						if (!ls[li].Contains("[HarmonyLib.HarmonyPatch(", StringComparison.Ordinal)) continue;
						int nj = li;
						while (nj < ls.Length && !ls[nj].Contains(")]", StringComparison.Ordinal)) nj++;
						nj++;
						while (nj < ls.Length && ls[nj].Trim().Length == 0) nj++;
						string next = nj < ls.Length ? ls[nj].Trim() : "";
						if (!next.StartsWith("internal static class", StringComparison.Ordinal) && !next.StartsWith("public static class", StringComparison.Ordinal))
						{
							bad = Path.GetFileName(path) + "）" + ls[li].Trim() + " → " + next;
							return false;
						}
					}
					return true;
				}
				Check("[HarmonyPatch] 必须贴在**类**上（写在方法上会被 PatchAll 静默跳过、补丁完全不生效）",
					ClassLevelPatchOnly(atlasPatchPath, out string badAtlasPatch),
					badAtlasPatch.Length == 0 ? "两条都贴在类上" : badAtlasPatch);
				Check("补丁参数用 __args 注入（本体形参名字变了也不会静默失效）",
					atlasPatchSrc.Contains("object[] __args"), "用了 __args");
				// 全工程再扫一遍：以后任何一个补丁生成器写成方法级注解都会在这里被抓住
				string methodLevel = "";
				foreach (string csFile in Directory.EnumerateFiles(Path.Combine(atlasProject, "cs"), "*.cs", SearchOption.AllDirectories))
					if (!ClassLevelPatchOnly(csFile, out string badFile)) { methodLevel = badFile; break; }
				Check("整个生成工程里没有一个「方法级注解」的 HarmonyPatch（那种补丁会被 PatchAll 静默跳过）",
					methodLevel.Length == 0, methodLevel.Length == 0 ? "全部都是类级注解" : methodLevel);
				Check("补丁参数用 __args 注入（本体形参名字变了也不会静默失效）",
					atlasPatchSrc.Contains("object[] __args"), "用了 __args");
				Check("补丁的表里有能量图标 + 药水（键就是图集精灵表里的 filename）",
					atlasPatchSrc.Contains($"(\"ui_atlas\", \"card/energy_{atlasNaming.EnergyColor}\")")
					&& atlasPatchSrc.Contains("(\"potion_atlas\",")
					&& atlasPatchSrc.Contains("(\"potion_outline_atlas\","), "表齐了");
				string atlasPatchNoMatch = CSharpCodeGen.CardPoolSource(atlasProbe);   // 对照：别的源码里没有这段
				Check("（对照）补丁只在需要时才存在，别的生成代码里没有这一段", !atlasPatchNoMatch.Contains("AtlasManager"), "对照通过");

				string exRelicIcon = Path.Combine(atlasProject, "images", "relics",
					Naming.EntryOf(atlasNaming.ExtraResourceRelicClass).ToLowerInvariant() + ".png");
				Check("额外资源量**没上传图标**时，那个隐藏遗物的回退图也会写出来（否则遗物栏 Missing sprite + 紫色占位）",
					File.Exists(exRelicIcon), File.Exists(exRelicIcon) ? Path.GetFileName(exRelicIcon) : "没找到");
			}
			finally
			{
				try { if (Directory.Exists(atlasRoot)) Directory.Delete(atlasRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：遗物的「条件选项（整只遗物）」也要能填生命区间的第二个数值 M =====
		{
			// 用户报：遗物的条件选项里选了「生命值在 N%~M% 之间」，却只有一个 N 可填。
			// 原因：卡牌 / 效果那两个条件模板在 V0.2.23 加过 M 框，而遗物页这只「整只遗物条件」
			// 是 MainWindow.xaml 里单独写的一块，当时漏了。
			SelectTabRoot("遗物");
			if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
			PumpDispatcher(150);

			// 全窗口扫一遍：每个「条件选项」面板都必须有第二个数值框
			//（绑定 Condition.Amount2、按 Condition.NeedsAmount2 显示）。
			// 注意：WPF 的 TabControl 只把**当前选中页**的内容放进可视树，所以卡牌页 / 遗物页要分别扫。
			void CollectCondGroups(DependencyObject root, List<GroupBox> into)
			{
				int childCount = VisualTreeHelper.GetChildrenCount(root);
				for (int ci = 0; ci < childCount; ci++)
				{
					DependencyObject child = VisualTreeHelper.GetChild(root, ci);
					if (child is GroupBox gb && (gb.Header as string ?? "").Contains("条件选项", StringComparison.Ordinal)) into.Add(gb);
					CollectCondGroups(child, into);
				}
			}
			(int Count, string Missing) ScanCondGroups()
			{
				List<GroupBox> groups = new List<GroupBox>();
				CollectCondGroups(this, groups);
				if (RelicConditionBox is not null && RelicConditionBox.IsVisible && !groups.Contains(RelicConditionBox)) groups.Add(RelicConditionBox);
				string missing = "";
				foreach (GroupBox gb in groups)
				{
					List<TextBox> inner = new List<TextBox>();
					CollectTextBoxes(gb, inner);
					TextBox? mBoxIn = inner.FirstOrDefault((TextBox t) => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path == "Condition.Amount2");
					if (mBoxIn is null || BindingOperations.GetBinding(mBoxIn, UIElement.VisibilityProperty)?.Path?.Path != "Condition.NeedsAmount2")
						missing += (missing.Length == 0 ? "" : " / ") + (gb.Header as string ?? "(无标题)");
				}
				return (groups.Count, missing);
			}
			var relicScan = ScanCondGroups();
			Check("遗物页的每个「条件选项」面板都有第二个数值框（整只遗物 + 每条效果各一块；生命区间要 N 和 M 都填）",
				relicScan.Count >= 2 && relicScan.Missing.Length == 0,
				$"扫到 {relicScan.Count} 个面板" + (relicScan.Missing.Length == 0 ? "，都有 M 框" : "；缺 M 框：" + relicScan.Missing));
			SelectTabRoot("卡牌");
			if (Profile.Cards.Count > 0) CardList.SelectedItem = Profile.Cards[0];
			PumpDispatcher(150);
			var cardScan = ScanCondGroups();
			Check("卡牌页的「条件选项」面板也都有第二个数值框",
				cardScan.Count >= 1 && cardScan.Missing.Length == 0,
				$"扫到 {cardScan.Count} 个面板" + (cardScan.Missing.Length == 0 ? "，都有 M 框" : "；缺 M 框：" + cardScan.Missing));
			SelectTabRoot("遗物");
			if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
			PumpDispatcher(150);

			// 遗物那只：真的能填 M，而且改完写回存档（双向绑定）
			List<TextBox> relicCondBoxes = new List<TextBox>();
			if (RelicConditionBox is not null) CollectTextBoxes(RelicConditionBox, relicCondBoxes);
			TextBox? relicMBox = relicCondBoxes.FirstOrDefault((TextBox t) => BindingOperations.GetBinding(t, TextBox.TextProperty)?.Path?.Path == "Condition.Amount2");
			Check("遗物的「条件选项（整只遗物）」里有 M 框", relicMBox is not null, relicMBox is null ? "没找到" : "有");
			// 下拉里真的能选到「生命值在 N%~M% 之间」（遗物能用的条件列表里要有它）
			List<ComboBox> relicCondCombos = new List<ComboBox>();
			if (RelicConditionBox is not null) CollectCombos(RelicConditionBox, relicCondCombos);
			ComboBox? relicKindCombo = relicCondCombos.FirstOrDefault((ComboBox c) => c.ItemsSource == RelicConditions);
			Check("遗物条件的下拉里能选到「生命值在 N%~M% 之间」",
				relicKindCombo is not null && relicKindCombo.Items.OfType<ConditionOption>().Any((ConditionOption o) => o.Id == "HpInRange"),
				relicKindCombo is null ? "没找到下拉" : relicKindCombo.Items.Count + " 个条件");
			if (RelicList.SelectedItem is RelicSpec relicCond && relicMBox is not null)
			{
				string oldKind = relicCond.Condition.Kind;
				decimal oldAmount = relicCond.Condition.Amount;
				decimal oldAmount2 = relicCond.Condition.Amount2;
				relicCond.Condition.Kind = "HpInRange";
				relicCond.Condition.Amount = 25m;
				relicCond.Condition.Amount2 = 75m;
				PumpDispatcher(150);
				Check("遗物选了「生命值在 N%~M% 之间」后 M 框会显示出来并带上当前值",
					relicMBox.IsVisible && relicMBox.Text.Trim() == "75", $"可见={relicMBox.IsVisible} 文本={relicMBox.Text}");
				relicMBox.Text = "60";
				PumpDispatcher(150);
				Check("在遗物的 M 框里输入能写回存档（N=25 / M=60）",
					relicCond.Condition.Amount2 == 60m && relicCond.Condition.Amount == 25m,
					$"N={relicCond.Condition.Amount} M={relicCond.Condition.Amount2}");
				relicCond.Condition.Kind = oldKind;
				relicCond.Condition.Amount = oldAmount;
				relicCond.Condition.Amount2 = oldAmount2;
				PumpDispatcher(150);
			}
			else
			{
				Check("（跳过）遗物条件 M 框的双向绑定检查：没有可用的遗物 / M 框", ok: false,
					RelicList.SelectedItem is null ? "没选中遗物" : "没有 M 框");
			}
		}
		// ===== 本轮新增：「生成卡牌」的「生成到」增加「消耗牌堆」 =====
		{
			Check("「生成到」里有消耗牌堆（值 = Exhaust、界面显示中文）",
				EffectCatalog.SpawnTargets.Any((SpawnTargetOption o) => o.Id == "Exhaust" && o.Display.Contains("消耗牌堆"))
				&& EffectCatalog.SpawnTargetZh("Exhaust") == "消耗牌堆", EffectCatalog.SpawnTargetZh("Exhaust"));
			CharacterProfile spawnProbe = ProfileFactory.Sample();
			CardSpec exhaustGen = new CardSpec { Name = "自检生成到消耗堆", ClassName = "UiCheckSpawnExhaust", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			exhaustGen.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv", SpawnTo = "Exhaust" });
			spawnProbe.Cards.Add(exhaustGen);
			string exhaustSrc = CSharpCodeGen.CardSource(spawnProbe, exhaustGen, 0);
			Check("生成到消耗牌堆 → 走本体那套 CardPileCmd + PileType.Exhaust（消耗牌堆也是战斗内牌堆，本体允许直接放）",
				exhaustSrc.Contains("CardPileCmd.AddToCombatAndPreview<MegaCrit.Sts2.Core.Models.Cards.Shiv>(base.Owner.Creature, PileType.Exhaust, 2, base.Owner)"),
				exhaustSrc.Contains("PileType.Exhaust") ? "对" : "没写 Exhaust");
			Check("卡面描述写「放入消耗牌堆」", LocalizationGen.CardsJson(spawnProbe).Contains("放入消耗牌堆"), "描述对");
			Check("校验器会提示「生成到消耗牌堆 = 不经过手牌 / 抽牌堆，抽不到它」",
				ProfileValidator.Validate(spawnProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("直接进消耗牌堆")), "提示在");
			// 带附加处理（升级 / 免费 / 仅本回合升级）的那条路径也要用 Exhaust
			CardSpec exhaustGen2 = new CardSpec { Name = "自检生成到消耗堆2", ClassName = "UiCheckSpawnExhaust2", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			exhaustGen2.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Exhaust", SpawnUpgraded = true });
			spawnProbe.Cards.Add(exhaustGen2);
			Check("带附加处理的那条路径也用 PileType.Exhaust",
				CSharpCodeGen.CardSource(spawnProbe, exhaustGen2, 0).Contains("AddGeneratedCardToCombat(__gen, PileType.Exhaust, base.Owner)"), "对");
			// 状态触发器里的「生成卡牌」也用归一化后的值
			CharacterProfile spawnPowerProbe = ProfileFactory.Sample();
			spawnPowerProbe.CustomPowers.Clear();
			spawnPowerProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检生成状态", ClassName = "UiCheckSpawnPower", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Exhaust" } } } },
			});
			Check("（状态触发器里也一样）生成到消耗牌堆写的是 PileType.Exhaust",
				CustomPowerGen.Source(spawnPowerProbe, spawnPowerProbe.CustomPowers[0], 0).Contains("PileType.Exhaust"), "对");
			// 生成 → 回读：SpawnTo 要原样回来（两种写法都要认）
			string spawnRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_spawn_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile spawnGenProbe = ProfileFactory.Sample();
				spawnGenProbe.Paths.OutputDir = spawnRoot;
				spawnGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				spawnGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec genA = new CardSpec { Name = "自检生成到消耗堆", ClassName = "UiCheckSpawnExhaust", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				genA.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv", SpawnTo = "Exhaust" });
				CardSpec genB = new CardSpec { Name = "自检生成到消耗堆2", ClassName = "UiCheckSpawnExhaust2", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				genB.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnTo = "Exhaust", SpawnUpgraded = true });
				spawnGenProbe.Cards.Add(genA);
				spawnGenProbe.Cards.Add(genB);
				Check("（准备）生成到消耗牌堆的存档能生成工程", ModGenerator.Generate(spawnGenProbe).Success, spawnRoot);
				var spawnRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(spawnGenProbe));
				var recGenA = spawnRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckSpawnExhaust");
				var recGenB = spawnRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckSpawnExhaust2");
				Check("回读：生成到消耗牌堆原样回来（带附加处理那种写法也认）",
					recGenA is not null && recGenA.Effects.Any((EffectSpec e) => e.Kind == "GenerateCard" && e.SpawnTo == "Exhaust")
					&& recGenB is not null && recGenB.Effects.Any((EffectSpec e) => e.Kind == "GenerateCard" && e.SpawnTo == "Exhaust"),
					$"A={(recGenA is null ? "?" : recGenA.Effects.FirstOrDefault()?.SpawnTo)} B={(recGenB is null ? "?" : recGenB.Effects.FirstOrDefault()?.SpawnTo)}");
				Check("回读没有认不出来的语句", !spawnRec.HasUnparsed, spawnRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(spawnRoot)) Directory.Delete(spawnRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：预见卡不再卡死（选牌界面提示语）+ 额外资源量支持「下回合生效」 =====
		{
			// ① 预见：本体 CardModel.SelectionScreenPrompt 在键不存在时**直接抛异常**
			//    （"No selection screen prompt for CARD.XXX."），而生成的代码是打出时读它的 →
			//    抛在效果中间 = 这张牌永远打不完、游戏卡死（用户实测「预见的卡无法丢弃、卡死」）。
			//    以前 NeedsSelectPrompt 只列了「从牌堆拿牌 / 给予关键词」，漏了预见。
			CharacterProfile scryProbe = ProfileFactory.Sample();
			CardSpec scryFix = new CardSpec { Name = "自检预见提示", ClassName = "UiCheckScryPrompt", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scryFix.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 3m, TargetSide = "Self" });
			scryProbe.Cards.Add(scryFix);
			Check("预见这种要弹选牌界面的效果，会一起生成 <卡>.selectionScreenPrompt（不然本体直接抛异常、游戏卡死）",
				LocalizationGen.NeedsSelectPrompt(scryFix.Effects), "认得出来");
			string scryJson = LocalizationGen.CardsJson(scryProbe);
			Check("预见的卡真的写出了 selectionScreenPrompt（而且写的是「丢进弃牌堆」那句）",
				scryJson.Contains("UI_CHECK_SCRY_PROMPT.selectionScreenPrompt")
				&& scryJson.Contains("选择要丢进弃牌堆的牌"), "写出来了");
			Check("（对照）不会弹选牌界面的效果不会多生成这一条（避免脏表）",
				!LocalizationGen.CardsJson(new CharacterProfile
				{
					Cards = { new CardSpec { Name = "无界面", ClassName = "UiCheckNoPrompt", Cost = 1, Effects = { new EffectSpec { Kind = "Block", Amount = 3m } } } },
				}).Contains("selectionScreenPrompt"), "没多生成");
			// 凡是生成代码里读 base.SelectionScreenPrompt 的效果种类，都必须在这条名单里
			string[] promptKinds = { "Scry", "TakeFromDraw", "TakeFromDiscard" };
			Check("生成代码里读 base.SelectionScreenPrompt 的三条效果都在「要生成提示语」的名单里",
				promptKinds.All(k => LocalizationGen.NeedsSelectPrompt(new[] { new EffectSpec { Kind = k, Amount = 1m, CardPick = "Chosen" } }))
				&& LocalizationGen.NeedsSelectPrompt(new[] { new EffectSpec { Kind = "GiveKeyword", Amount = 1m, CardPick = "Chosen" } }),
				string.Join("、", promptKinds));
			Check("预见的生成代码仍然用本体那条 SelectionScreenPrompt（现在键一定存在了）",
				CSharpCodeGen.CardSource(scryProbe, scryFix, 0).Contains("new CardSelectorPrefs(base.SelectionScreenPrompt, 0, __scryTop.Count)"), "对");

			// ===== V0.2.145（用户实测「自定义状态选生成卡牌会卡死」）=====
			// 游戏日志（%APPDATA%\SlayTheSpire2\logs\godot.log）原文：
			//   [ERROR] Combat #1 turn loop died while its combat is in progress; the combat is stuck
			//           until the room is restarted:
			//           System.InvalidOperationException: No selection screen prompt for POWER.SPARKLE_POWER6.
			//       at MegaCrit.Sts2.Core.Models.PowerModel.get_SelectionScreenPrompt()
			//       at SparkleMod.SparklePower6.AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)
			// 真因：自定义状态上「生成卡牌 + 按范围随机 + 多选1（>3）/ 从范围里自己挑一张」生成出来的代码读
			// `base.SelectionScreenPrompt` —— 本体 PowerModel 那一份实现和 CardModel **完全一样**
			//（都读 <Id.Entry>.selectionScreenPrompt，键不存在就抛），而 PowersJson 以前只写
			// title / description / smartDescription，**从来没写过这一条** → 抛在战斗回合钩子里
			// → 本轮 turn loop 直接死掉、战斗卡住（房间重开才能恢复）。
			{
				var powerPromptProbe = ProfileFactory.Sample();
				powerPromptProbe.CustomPowers.Clear();
				var spawnPower = new CustomPowerSpec { Name = "自检生成卡状态", ClassName = "UiCheckSpawnPower" };
				var spawnTrigger = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
				spawnTrigger.Effects.Add(new EffectSpec
				{
					Kind = "GenerateCard", Amount = 1m, TargetSide = "Self",
					SpawnPick = "Random", SpawnFilter = "Attack", SpawnChoice = 4m,
				});
				spawnPower.Triggers.Add(spawnTrigger);
				powerPromptProbe.CustomPowers.Add(spawnPower);
				Check("V0.2.145：自定义状态上「生成卡牌 + 按范围随机 + 多选1 > 3」认得出来要选牌提示语",
					LocalizationGen.NeedsSelectPrompt(spawnTrigger.Effects), "认得出来");
				string spawnPowerSrc = CustomPowerGen.Source(powerPromptProbe, spawnPower, 0);
				Check("V0.2.145（准备）：这条链生成出来的状态代码真的读 base.SelectionScreenPrompt（复用卡牌那套 EmitGenerateCard）",
					spawnPowerSrc.Contains("base.SelectionScreenPrompt"), "读到");
				string spawnPowersJson = LocalizationGen.PowersJson(powerPromptProbe);
				Check("V0.2.145：自定义状态也一起写出 <状态>.selectionScreenPrompt（不然本体直接抛异常、战斗卡死）",
					spawnPowersJson.Contains("UI_CHECK_SPAWN_POWER.selectionScreenPrompt"), "写出来了");
				Check("V0.2.145：提示语跟着多选1 的张数走（「从 4 张中选一张」）",
					spawnPowersJson.Contains("从 4 张中选一张"), "对");

				// 「从范围里自己挑一张」是另一半：候选 > 3 时走的也是那条网格选牌界面（以前连名单都没进）
				var chosenPower = new CustomPowerSpec { Name = "自检自己挑状态", ClassName = "UiCheckChosenPower" };
				var chosenTrigger = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
				chosenTrigger.Effects.Add(new EffectSpec
				{
					Kind = "GenerateCard", Amount = 1m, TargetSide = "Self",
					SpawnPick = "Random", SpawnFilter = "Attack", SpawnChoice = 1m, SpawnChosen = true,
				});
				chosenPower.Triggers.Add(chosenTrigger);
				powerPromptProbe.CustomPowers.Add(chosenPower);
				Check("V0.2.145：自定义状态上「生成卡牌 + 从范围里自己挑一张」也认得出来（以前漏的就是它）",
					LocalizationGen.NeedsSelectPrompt(chosenTrigger.Effects), "认得出来");
				string spawnPowersJson2 = LocalizationGen.PowersJson(powerPromptProbe);
				Check("V0.2.145：它也会写出 <状态>.selectionScreenPrompt，提示语是「选择要生成的牌」",
					spawnPowersJson2.Contains("UI_CHECK_CHOSEN_POWER.selectionScreenPrompt")
					&& spawnPowersJson2.Contains("选择要生成的牌"), "写出来了");
				Check("V0.2.145：这条链的生成代码确实读 base.SelectionScreenPrompt（和上面那条同一个机制）",
					CustomPowerGen.Source(powerPromptProbe, chosenPower, 1).Contains("base.SelectionScreenPrompt"), "读到");

				// 反向（红线①）：不需要选牌界面的状态一个字都不多写
				Check("V0.2.145（对照）：不含选牌界面的自定义状态不会多生成这一条（默认输出不变）",
					!LocalizationGen.PowersJson(new CharacterProfile
					{
						CustomPowers =
						{
							new CustomPowerSpec
							{
								Name = "无界面状态", ClassName = "UiCheckNoPromptPower",
								Triggers = { new PowerTriggerSpec { Kind = "PlayerTurnStart", Effects = { new EffectSpec { Kind = "Block", Amount = 3m } } } },
							},
						},
					}).Contains("selectionScreenPrompt"), "没多生成");

				// 锻造卡：效果在**节点图**上（CardSpec.Effects 是空的）→ 图上的选牌类效果也要一起算
				var forgePromptProbe = ProfileFactory.Sample();
				var forgePromptCard = new CardSpec
				{
					Name = "自检锻造提示", ClassName = "UiCheckForgePrompt",
					CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true, IsForged = true,
				};
				forgePromptCard.Effects.Clear();
				var forgePromptGraph = new ForgeGraphSpec();
				var forgePromptNode = new ForgeNodeSpec { Kind = "Effect" };
				var forgePromptSpec = ForgeEffectBridge.Author(forgePromptNode);
				forgePromptSpec.Kind = "TakeFromDiscard";
				forgePromptSpec.Amount = 1m;
				forgePromptSpec.TargetSide = "Self";
				forgePromptGraph.Nodes.Add(forgePromptNode);
				forgePromptCard.ForgeGraph = forgePromptGraph;
				forgePromptProbe.Cards.Add(forgePromptCard);
				Check("V0.2.145：锻造卡图上「从弃牌堆拿牌到手牌」也认得出来（效果不在 CardSpec.Effects 里，在节点图上）",
					LocalizationGen.NeedsSelectPrompt(LocalizationGen.GraphEffects(forgePromptGraph)), "认得出来");
				Check("V0.2.145：锻造卡也会写出 <卡>.selectionScreenPrompt（以前只有非卡牌图上的效果才写）",
					LocalizationGen.CardsJson(forgePromptProbe).Contains("UI_CHECK_FORGE_PROMPT.selectionScreenPrompt"), "写出来了");

				// ===== V0.2.145 追加：把「会读 base.SelectionScreenPrompt 的效果种类」**机械地**扫一遍 =====
				// 为什么要机械扫：这条规矩漏一次就是「游戏里战斗卡死」，而且漏得很隐蔽 ——
				// 第一遍我按人肉清单补了「生成卡牌（多选1 / 自己挑）」，第二遍才想起来还有「放置卡牌 + 自己选」。
				// 判据：把**每一种**效果都按「最想要弹选牌界面」的参数配一遍，分别塞进**卡牌链**和**自定义状态链**
				//（用户踩的那条链），生成出来的源码里只要出现 base.SelectionScreenPrompt，
				// `LocalizationGen.NeedsSelectPrompt` 就必须认得它 —— 认不出来 = 这条链上会漏写本地化键 = 卡死。
				{
					(bool Ok, string Src, EffectSpec Fx) ScanChain(bool powerChain, string kind)
					{
						var fx = new EffectSpec
						{
							Kind = kind, Amount = 2m, TargetSide = "Enemy",
							CardPick = "Chosen", SelectPile = "Hand",
							SpawnPick = "Random", SpawnFilter = "Attack", SpawnChoice = 4m, SpawnChosen = true,
							SpawnCardId = "SevenSlash", PowerId = "StrengthPower", PotionId = "BlockPotion",
							GivenKeyword = "Exhaust",
						};
						try
						{
							if (powerChain)
							{
								var pp = ProfileFactory.Sample();
								var pw = new CustomPowerSpec { Name = "扫描提示语", ClassName = "UiCheckPromptScan" };
								var tr = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
								tr.Effects.Add(fx);
								pw.Triggers.Add(tr);
								pp.CustomPowers.Clear();
								pp.CustomPowers.Add(pw);
								return (true, CustomPowerGen.Source(pp, pw, 0), fx);
							}
							else
							{
								var pp = ProfileFactory.Sample();
								var c = new CardSpec
								{
									Name = "扫描提示语卡", ClassName = "UiCheckPromptScanCard",
									CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true,
								};
								c.Effects.Clear();
								c.Effects.Add(fx);
								pp.Cards.Add(c);
								return (true, CSharpCodeGen.CardSource(pp, c, 0), fx);
							}
						}
						catch (Exception ex)
						{
							return (false, ex.GetType().Name + "：" + ex.Message, fx);
						}
					}
					var promptScanned = new List<string>();
					var promptMissed = new List<string>();
					var promptSkipped = new List<string>();
					foreach (var k in EffectCatalog.EffectKinds)
					{
						foreach (bool powerChain in new[] { false, true })
						{
							var (ok, src, fx) = ScanChain(powerChain, k.Kind);
							string tag = k.Kind + (powerChain ? "(状态链)" : "(卡牌链)");
							if (!ok) { promptSkipped.Add(tag); continue; }
							if (!src.Contains("base.SelectionScreenPrompt", StringComparison.Ordinal)) continue;
							promptScanned.Add(tag);
							if (!LocalizationGen.NeedsSelectPrompt(new[] { fx })) promptMissed.Add(tag);
						}
					}
					Check("V0.2.145：凡是生成代码里会读 base.SelectionScreenPrompt 的效果种类，NeedsSelectPrompt 全都认得"
						+ "（漏一个就是游戏里那场战斗卡死）",
						promptMissed.Count == 0,
						$"扫到 {promptScanned.Count} 处：{string.Join("、", promptScanned)}"
						+ (promptSkipped.Count > 0 ? $" ｜ 生成期跳过的（{promptSkipped.Count}）：{string.Join("、", promptSkipped)}" : "")
						+ (promptMissed.Count > 0 ? " ｜ **漏了**：" + string.Join("、", promptMissed) : ""));
				}

				// ===== V0.2.146：「数值公式」框里填**纯数字** = 固定数值（用户实测报的）=====
				// 用户原话：「数值公式就不能填纯数值吗」——他在「生成卡牌」的「数值公式」框里填了 1，
				// 被校验器那句「不支持『数值公式』……请清空、改用左边的固定数值」直接拦住了生成。
				// 纯常数本来就能在生成期折出来，所以现在**自动折好**（Amount = 1、公式框清空）。
				{
					var foldProbe = ProfileFactory.Sample();
					var foldCard = new CardSpec
					{
						Name = "自检公式折常数", ClassName = "UiCheckFoldConst",
						CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true,
					};
					foldCard.Effects.Clear();
					var foldEff = new EffectSpec
					{
						Kind = "GenerateCard", Amount = 0m, AmountFormula = "1",
						TargetSide = "Self", SpawnTo = "Hand", SpawnCardId = "SevenSlash",
					};
					foldCard.Effects.Add(foldEff);
					foldProbe.Cards.Add(foldCard);
					var foldIssues = ProfileValidator.Validate(foldProbe);
					Check("V0.2.146：非那 5 种的效果，「数值公式」里填纯常数（1）→ 自动折进固定数值（Amount=1、公式清空）",
						foldEff.Amount == 1m && foldEff.AmountFormula.Length == 0,
						$"Amount={foldEff.Amount:0.##} / 公式=«{foldEff.AmountFormula}»");
					Check("V0.2.146：折好之后**不再**报「不支持『数值公式』」那句拦路错误（用户就是被它拦住的）",
						!foldIssues.Any(i => i.IsError && i.Message.Contains("不支持「数值公式」")),
						foldIssues.FirstOrDefault(i => i.IsError)?.Message ?? "没有错误级问题");
					Check("V0.2.146：生成出来的代码真的按折出来的数字走（生成卡牌 1 张）",
						GenSrc(0m, "1") == GenSrc(1m, "")
						&& GenSrc(0m, "1").Contains("SevenSlash"),
						GenSrc(0m, "1") == GenSrc(1m, "")
							? $"与「直接填固定数值」逐字节一致（{GenSrc(1m, "").Length} 字符）"
							: "两边生成的不一样");
					Check("V0.2.146：折这一步是幂等的（再折一次什么都不改）",
						ProfileFactory.FoldPlainConstantAmountFormulas(foldProbe) == 0
						&& foldEff.Amount == 1m && foldEff.AmountFormula.Length == 0, "幂等");
					Check("V0.2.146：`2+3` 这种纯常数算式也折（= 5）",
						FoldProbe(5m, "2+3"), "折成 5");
					Check("V0.2.146：`=1`（用户习惯先写等号）也折（= 1）",
						FoldProbe(1m, "=1"), "折成 1");
					Check("V0.2.146：真·运行时公式（M*3 / HandCount / X）**不折**，照旧由校验器报错拦住",
						!FoldProbe(null, "M*3") && !FoldProbe(null, "HandCount") && !FoldProbe(null, "X")
						&& !FoldProbe(null, "A+3"), "没折");
					Check("V0.2.146：那 5 种（伤害 / 格挡…）上的常数公式**一个字符都不动**（公式栏是它们的正牌编辑器）",
						KeepFormula("Damage", "6") && KeepFormula("Block", "5"), "没动");
					Check("V0.2.146：写「数值 = X」那种老写法也不动（X 是另一套语义）",
						KeepX(), "没动");
					// 用户的实际路径是「打开存档 → 点生成」：存盘再读回来也必须已经折好（Load 里那一步）。
					{
						string foldJson = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02146fold_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
						try
						{
							var saveProbe = ProfileFactory.Sample();
							var saveCard = new CardSpec { Name = "存读折常数", ClassName = "UiCheckFoldRoundTrip", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
							saveCard.Effects.Clear();
							saveCard.Effects.Add(new EffectSpec
							{
								Kind = "GenerateCard", Amount = 0m, AmountFormula = "1",
								TargetSide = "Self", SpawnTo = "Hand", SpawnCardId = "SevenSlash",
							});
							saveProbe.Cards.Add(saveCard);
							ProfileFactory.Save(saveProbe, foldJson);
							var reloaded = ProfileFactory.Load(foldJson);
							var reCard = reloaded.Cards.FirstOrDefault(c => c.ClassName == "UiCheckFoldRoundTrip");
							var reEff = reCard?.Effects.FirstOrDefault();
							Check("V0.2.146：存档里那条「生成卡牌 + 公式 1」→ 打开存档就已经折好（数值 1、公式空，用户不用手改）",
								reEff is not null && reEff.Amount == 1m && reEff.AmountFormula.Length == 0,
								reEff is null ? "(没读到那张卡)" : $"Amount={reEff.Amount:0.##} / 公式=«{reEff.AmountFormula}»");
							Check("V0.2.146：读回来的这份存档校验**没有**「不支持数值公式」那类错误",
								!ProfileValidator.Validate(reloaded).Any(i => i.IsError && i.Message.Contains("数值公式")),
								"没有");
						}
						finally
						{
							try { if (File.Exists(foldJson)) File.Delete(foldJson); } catch { }
						}
					}

					// 自检用：造一条「生成卡牌 + 指定数值 / 指定公式」的卡，跑一遍校验器（折常数就在校验里做），
					// 返回生成出来的卡牌源码 —— 用来对拍「填在公式框」与「填在固定数值框」是不是同一份产物。
					string GenSrc(decimal amount, string formula)
					{
						var pp = ProfileFactory.Sample();
						var c = new CardSpec { Name = "折常数探针0", ClassName = "UiCheckFoldProbe0", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
						c.Effects.Clear();
						c.Effects.Add(new EffectSpec
						{
							Kind = "GenerateCard", Amount = amount, AmountFormula = formula,
							TargetSide = "Self", SpawnTo = "Hand", SpawnCardId = "SevenSlash",
						});
						pp.Cards.Add(c);
						ProfileValidator.Validate(pp);
						return CSharpCodeGen.CardSource(pp, c, 0);
					}
					// 自检用：造一条「生成卡牌 + 指定公式」的效果，跑一遍校验器，返回它有没有被折成 want。
					bool FoldProbe(decimal? want, string formula)
					{
						var pp = ProfileFactory.Sample();
						var c = new CardSpec { Name = "折常数探针", ClassName = "UiCheckFoldProbe", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
						c.Effects.Clear();
						var fx = new EffectSpec { Kind = "GenerateCard", Amount = 0m, AmountFormula = formula, TargetSide = "Self", SpawnTo = "Hand", SpawnCardId = "SevenSlash" };
						c.Effects.Add(fx);
						pp.Cards.Add(c);
						ProfileValidator.Validate(pp);
						return want is { } w
							? fx.Amount == w && fx.AmountFormula.Length == 0
							: fx.AmountFormula.Length == 0;   // 不该折：公式必须原样留着
					}
					// 自检用：那 5 种效果上的常数公式必须原样留着（不然会和「固定数值 → 公式」的迁移来回打架）。
					bool KeepFormula(string kind, string formula)
					{
						var pp = ProfileFactory.Sample();
						var c = new CardSpec { Name = "折常数探针2", ClassName = "UiCheckFoldProbe2", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
						c.Effects.Clear();
						var fx = new EffectSpec { Kind = kind, Amount = 5m, AmountFormula = formula, TargetSide = "Enemy" };
						c.Effects.Add(fx);
						pp.Cards.Add(c);
						ProfileFactory.FoldPlainConstantAmountFormulas(pp);
						return fx.AmountFormula == formula;
					}
					// 自检用：「数值 = X」的老写法（AmountIsX）不许被折。
					bool KeepX()
					{
						var pp = ProfileFactory.Sample();
						var c = new CardSpec { Name = "折常数探针3", ClassName = "UiCheckFoldProbe3", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
						c.Effects.Clear();
						var fx = new EffectSpec { Kind = "GenerateCard", Amount = 0m, AmountFormula = "X", AmountIsX = true, TargetSide = "Self", SpawnTo = "Hand", SpawnCardId = "SevenSlash" };
						c.Effects.Add(fx);
						pp.Cards.Add(c);
						ProfileFactory.FoldPlainConstantAmountFormulas(pp);
						return fx.AmountFormula == "X" && fx.AmountIsXEffective;
					}
				}
			}

			// ===== V0.2.147：「状态挂在敌人身上时，『自己』是谁」+ 玩家侧的东西要警告 =====
			// 用户问的：「当状态挂在敌人身上时，状态的自己是不是敌人自己」→ **是**（= base.Owner，挂着它的那个单位）。
			// 但状态里凡是**要拿玩家对象**的效果（抽牌 / 能量 / 生成卡牌 / 药水 / 改牌组…）或**勾了概率生效**的，
			// 贴到敌人身上时 base.Owner.Player 是 null（本体 Creature.Player 对怪物就是 null）→ 运行时抛异常、战斗卡住。
			// 所以校验器要提前警告；下面钉「警告会出现 / 不误报」，以及「那份玩家侧种类清单与生成端一致」
			//（清单是机械扫出来的：每种效果按最想要选牌界面的参数生成一个状态源码，看有没有**没有空值保护**的 base.Owner.Player）。
			{
				// 自检用：生成一个「只放这一种效果」的自定义状态，返回它的源码。
				string PowerSrcOf(string kind, bool chance = false)
				{
					var pp = ProfileFactory.Sample();
					var pw = new CustomPowerSpec { Name = "玩家侧扫描", ClassName = "UiCheckPlayerSide" };
					var tr = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
					tr.Effects.Add(new EffectSpec
					{
						Kind = kind, Amount = 2m, TargetSide = "Self", SpawnPick = "Random",
						SpawnFilter = "Attack", SpawnChoice = 4m, SpawnChosen = true,
						SpawnCardId = "SevenSlash", PowerId = "StrengthPower", PotionId = "BlockPotion",
						GivenKeyword = "Exhaust", CardPick = "Chosen", SelectPile = "Hand",
						ChanceEnabled = chance, ChancePercent = 50m,
					});
					pw.Triggers.Add(tr);
					pp.CustomPowers.Clear();
					pp.CustomPowers.Add(pw);
					return CustomPowerGen.Source(pp, pw, 0);
				}
				// 自检用：源码里有没有「没有空值保护」的 base.Owner.Player（比较 / ?. / ?? 都算安全，不算）。
				bool NeedsPlayerObject(string src) => src.Split('\n').Any(line =>
					line.Contains("base.Owner.Player", StringComparison.Ordinal)
					&& !line.Contains("!= base.Owner.Player", StringComparison.Ordinal)
					&& !line.Contains("== base.Owner.Player", StringComparison.Ordinal)
					&& !line.Contains("base.Owner.Player?.", StringComparison.Ordinal)
					&& !line.Contains("base.Owner.Player ??", StringComparison.Ordinal));

				Check("V0.2.147：清单里的种类（抽牌 / 生成卡牌 / 获得药水）生成出来的状态代码真的拿玩家对象",
					NeedsPlayerObject(PowerSrcOf("Draw")) && NeedsPlayerObject(PowerSrcOf("GenerateCard"))
					&& NeedsPlayerObject(PowerSrcOf("GainPotion")), "拿玩家对象");
				Check("V0.2.147：清单外的种类（造成伤害 / 施加状态 / 获得格挡 / 临时增益）只跟持有者有关、不拿玩家对象",
					!NeedsPlayerObject(PowerSrcOf("Damage")) && !NeedsPlayerObject(PowerSrcOf("ApplyPower"))
					&& !NeedsPlayerObject(PowerSrcOf("Block")) && !NeedsPlayerObject(PowerSrcOf("TempPower")),
					"不拿");
				Check("V0.2.147：勾了「概率生效」的任何种类都会拿玩家对象（掷骰读 base.Owner.Player.RunState）→ 敌人身上同样会抛异常",
					NeedsPlayerObject(PowerSrcOf("ApplyPower", chance: true)), "拿");
				Check("V0.2.147：清单与生成端一致（清单里的每一种都真的拿玩家对象；漏一个就是运行时抛异常、战斗卡住）",
					ProfileValidator.PlayerSidePowerEffectKinds.All(k => NeedsPlayerObject(PowerSrcOf(k))),
					string.Join("、", ProfileValidator.PlayerSidePowerEffectKinds));
				var playerSideExtra = EffectCatalog.EffectKinds.Select(k => k.Kind)
					.Where(k => !ProfileValidator.PlayerSidePowerEffectKinds.Contains(k, StringComparer.Ordinal)
						&& NeedsPlayerObject(PowerSrcOf(k)))
					.ToList();
				Check("V0.2.147：清单里没有多写（清单外的种类都不拿玩家对象）",
					playerSideExtra.Count == 0,
					playerSideExtra.Count == 0 ? "没有多写" : "多出来了（要补进清单）：" + string.Join("、", playerSideExtra));

				// 警告本身：一个「抽牌」状态（+ 一个「玩家回合开始时」这种玩家侧时机）
				var psProbe = ProfileFactory.Sample();
				psProbe.CustomPowers.Clear();
				var psPower = new CustomPowerSpec { Name = "敌人身上的抽牌状态", ClassName = "UiCheckEnemyDraw" };
				var psTrigger = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
				psTrigger.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" });
				psPower.Triggers.Add(psTrigger);
				psProbe.CustomPowers.Add(psPower);
				var psIssues = ProfileValidator.Validate(psProbe);
				Check("V0.2.147：状态里用了「玩家侧」的东西 → 配置检查给警告（说清挂到敌人身上会抛异常 / 时机不触发）",
					psIssues.Any(i => i.Level == "警告" && i.Message.Contains("玩家侧") && i.Message.Contains("敌人")),
					psIssues.FirstOrDefault(i => i.Message.Contains("玩家侧"))?.Message ?? "(没报)");
				var psPure = ProfileFactory.Sample();
				psPure.CustomPowers.Clear();
				var purePower = new CustomPowerSpec { Name = "纯持有者状态", ClassName = "UiCheckOwnerOnly" };
				var pureTrigger = new PowerTriggerSpec { Kind = "EnemyTurnStart" };
				pureTrigger.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Self" });
				purePower.Triggers.Add(pureTrigger);
				psPure.CustomPowers.Add(purePower);
				Check("V0.2.147（对照）：只用「跟持有者有关」的效果 + 敌人侧时机 → 不报那条警告（贴到敌人身上照样能用）",
					!ProfileValidator.Validate(psPure).Any(i => i.Message.Contains("玩家侧")), "没报");
			}

			// ===== V0.2.148：升级后费用 / 升级后额外资源量费用两栏（用户实测报的）=====
			// 用户原话：「升级后费用里面填不了 Y 和 X，但是填过之后什么都没有也会报错」。两个真因：
			//   ① 「升级后额外资源量费用」框的 getter **不认原文** —— 填了 `Y`（或填错）时绝对数是 null，
			//      框子显示成**空**（看着像「填不进去」）；
			//   ② 那个框的 setter **清空时没清原文**（`UpgradeStarCostFormula` 一直留着）→
			//      校验器那句「看不懂」永远消不掉（用户说的「什么都没有也会报错」）。
			// 顺带：`Y`（= 升级后还是 Y，本体改不了 X 那一档 = 等于不改）从「报错」改成**合法**（生成端本来就不写任何东西）。
			{
				CardSpec costCard = new CardSpec { Name = "自检升级费", ClassName = "UiCheckUpCost", CardType = "Skill", Rarity = "Common", Cost = 0, InCardPool = true };
				costCard.Effects.Clear();
				costCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
				costCard.StarCostFormula = "Y";                        // 这张牌花「全部额外资源量」
				// ① 填 `Y`：框里看得见、不报错、生成端一个字都不写
				costCard.UpgradeStarCostText = "Y";
				Check("V0.2.148：「升级后额外资源量费用」填 Y → 框里**看得见**（以前 getter 不认原文，框子会显示成空 = 像填不进去）",
					costCard.UpgradeStarCostText == "Y", $"框里=«{costCard.UpgradeStarCostText}»");
				var upYProfile = ProfileFactory.Sample();
				upYProfile.Cards.Add(costCard);
				Check("V0.2.148：填 Y → 不再报「看不懂」/「填不了」，生成端也不写 UpgradeStarCostBy（Y = 升级后还是 Y = 不改）",
					!ProfileValidator.Validate(upYProfile).Any(i => i.IsError && i.Message.Contains("升级后额外资源量费用"))
					&& !CSharpCodeGen.CardSource(upYProfile, costCard, 0).Contains("UpgradeStarCostBy"),
					"不报错、不生成");
				// ② 用户报的那个坑：填过非法内容之后**清空**，校验器不能还留着那句错误
				costCard.UpgradeStarCostText = "X";                    // 非法（X 是能量那一栏的符号）
				Check("V0.2.148（准备）：填一个非法内容（X）→ 校验器报「升级后额外资源量费用」",
					ProfileValidator.Validate(upYProfile).Any(i => i.IsError && i.Message.Contains("升级后额外资源量费用")), "报错");
				costCard.UpgradeStarCostText = "";
				Check("V0.2.148：**清空之后那句错误必须消失**（真因：以前清空没清 UpgradeStarCostFormula，错误永远消不掉）",
					costCard.UpgradeStarCostFormula.Length == 0 && costCard.UpgradeStarCostText.Length == 0
					&& !ProfileValidator.Validate(upYProfile).Any(i => i.Message.Contains("升级后额外资源量费用")),
					$"原文=«{costCard.UpgradeStarCostFormula}» / 框里=«{costCard.UpgradeStarCostText}»");
				// ③ 填数字 → 也把原文清掉（不然「看不懂」会跟着数字一起留着）
				costCard.UpgradeStarCostText = "X";
				costCard.UpgradeStarCostText = "3";
				Check("V0.2.148：从非法内容改成数字 3 → 原文也一起清掉、不再有错误级报错（这张牌是 Y 费牌，另有「改不了 X 档」的警告，属正常）",
					costCard.UpgradeStarCostFormula.Length == 0 && costCard.UpgradeStarCost == 3
					&& !ProfileValidator.Validate(upYProfile).Any(i => i.IsError && i.Message.Contains("升级后额外资源量费用")),
					$"值={costCard.UpgradeStarCost} / 原文=«{costCard.UpgradeStarCostFormula}»");
				// ③b 固定资源量费用的牌：填数字要真的生成 UpgradeStarCostBy(差值)
				CardSpec plainStarCard = new CardSpec { Name = "自检固定资源费", ClassName = "UiCheckPlainStar", CardType = "Skill", Rarity = "Common", Cost = 0, InCardPool = true };
				plainStarCard.Effects.Clear();
				plainStarCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
				plainStarCard.StarCostFormula = "1";
				plainStarCard.UpgradeStarCostText = "3";
				var plainStarProfile = ProfileFactory.Sample();
				plainStarProfile.Cards.Add(plainStarCard);
				string plainStarSrc = CSharpCodeGen.CardSource(plainStarProfile, plainStarCard, 0);
				var plainStarIssues = ProfileValidator.Validate(plainStarProfile);
				Check("V0.2.148（对照）：资源量费用是固定数字的牌，升级后填 3 → 生成 UpgradeStarCostBy(2)（老行为不变）",
					!plainStarIssues.Any(i => i.IsError && i.Message.Contains("自检固定资源费"))
					&& plainStarSrc.Contains("UpgradeStarCostBy(2)"),
					$"这张牌的错误={plainStarIssues.FirstOrDefault(i => i.IsError && i.Message.Contains("自检固定资源费"))?.Message ?? "(无)"}"
					+ $" / 源码里有 UpgradeStarCostBy={plainStarSrc.Contains("UpgradeStarCostBy")}");
				// ④ 「升级后 Y+1」本体做不到（UpgradeStarCostBy 碰到 X 牌直接抛异常）→ 必须**报错说清**
				costCard.UpgradeStarCostText = "Y+1";
				Check("V0.2.148：「升级后额外资源量费用」填 Y+1 → 报错并说清「本体 UpgradeStarCostBy 对资源量 X 的牌直接抛异常」",
					ProfileValidator.Validate(upYProfile).Any(i => i.IsError && i.Message.Contains("填不了 Y+1")
						&& i.Message.Contains("UpgradeStarCostBy")),
					ProfileValidator.Validate(upYProfile).FirstOrDefault(i => i.Message.Contains("填不了 Y+1"))?.Message ?? "(没报)");
				costCard.UpgradeStarCostText = "";
				// ⑤ 「升级后费用」那一栏：X（= 不改）/ X+1（往老写法上叠）都要能用
				CardSpec xCard = new CardSpec { Name = "自检X费升级", ClassName = "UiCheckXUpCost", CardType = "Skill", Rarity = "Common", Cost = 0, InCardPool = true };
				xCard.Effects.Clear();
				xCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
				xCard.CostFormula = "X";
				xCard.Effects.Clear();
				// 效果里也真的用 X（否则「升级后 X+N」没有落点，生成端不会声明那个 x 变量）——
				// 用「造成伤害 + 数值公式 X」最直白。
				xCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 0m, AmountFormula = "X", TargetSide = "Enemy" });
				xCard.UpgradeCostText = "X";
				var xProfile = ProfileFactory.Sample();
				xProfile.Cards.Add(xCard);
				Check("V0.2.148：X 费牌「升级后费用」填 X（= 升级后还是 X，等于不改）→ 无错误、框里看得见",
					xCard.UpgradeCostText == "X"
					&& !ProfileValidator.Validate(xProfile).Any(i => i.IsError && i.Message.Contains("升级后费用")),
					$"框里=«{xCard.UpgradeCostText}»");
				xCard.UpgradeCostText = "X+1";
				string xPlusSrc = CSharpCodeGen.CardSource(xProfile, xCard, 0);
				xCard.UpgradeCostText = "X";
				string xPlainSrc = CSharpCodeGen.CardSource(xProfile, xCard, 0);
				Check("V0.2.148：X 费牌「升级后费用」填 X+1 → 无错误，且生成代码里带「升级后 X + 1」那一档（填 X 则不带 = 不改）",
					!ProfileValidator.Validate(xProfile).Any(i => i.IsError && i.Message.Contains("升级后费用"))
					&& xPlusSrc.Contains("IsUpgraded ? 1 : 0") && !xPlainSrc.Contains("IsUpgraded ? 1 : 0"),
					$"X+1 有 IsUpgraded 档={xPlusSrc.Contains("IsUpgraded ? 1 : 0")} / X 有={xPlainSrc.Contains("IsUpgraded ? 1 : 0")}");
				// ⑥ 把 Y 填错栏（填进「升级后费用」）→ 报错里要说清「这一栏是能量费用、Y 在右边那栏」
				CardSpec yWrong = new CardSpec { Name = "自检Y填错栏", ClassName = "UiCheckYWrongBox", CardType = "Skill", Rarity = "Common", Cost = 0, InCardPool = true };
				yWrong.Effects.Clear();
				yWrong.UpgradeCostText = "Y";
				var yWrongProfile = ProfileFactory.Sample();
				yWrongProfile.Cards.Add(yWrong);
				Check("V0.2.148：把 Y 填进「升级后费用」（能量那一栏）→ 报错并提示「这是能量费用、Y 请填右边那栏」",
					ProfileValidator.Validate(yWrongProfile).Any(i => i.IsError
						&& i.Message.Contains("这一栏是**能量费用**") && i.Message.Contains("右边那一栏")),
					ProfileValidator.Validate(yWrongProfile).FirstOrDefault(i => i.IsError)?.Message ?? "(没报)");

				// ⑦ 用户实测报的（V0.2.149）：「原本 1 费、升级后 X 费，实际升级还是 1 费」——
				//    本体做不到（X 是构造时定死的一档），警告必须说清是**本体做不到**并给出能做到的写法。
				CardSpec numToX = new CardSpec { Name = "自检1费升X", ClassName = "UiCheckNumToX", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				numToX.Effects.Clear();
				numToX.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
				numToX.UpgradeCostText = "X";
				var numToXProfile = ProfileFactory.Sample();
				numToXProfile.Cards.Add(numToX);
				Check("V0.2.149：「1 费 + 升级后费用 X」→ 警告说清**本体做不到**（X 是构造时定死的一档）+ 给出「一开始就 X 费 + X+1」这种能做的写法",
					ProfileValidator.Validate(numToXProfile).Any(i => i.Level == "警告" && i.Message.Contains("本体做不到")
						&& i.Message.Contains("EnergyCost.UpgradeBy") && i.Message.Contains("X+1")),
					ProfileValidator.Validate(numToXProfile).FirstOrDefault(i => i.Message.Contains("本体做不到"))?.Message ?? "(没报)");
			}

			// ===== V0.2.150：效果栏按种类裁剪（用户：「造成伤害只需要数值（公式）/ 升级增量 / 作用对象 /
			// 命中次数 / 生效次数 / 概率 / 下回合生效 / 随机目标允许攻击同个敌人，其他的都可以隐藏掉」）=====
			// 断言分四层：
			//   ① 用户点名的「造成伤害」那一档：显示的就是他列的那几行，其余全收起；
			//   ② 清单（EffectFieldPolicy）↔ 机械测量（EffectFieldUsage）：卡牌链上**逐条相等**；
			//   ③ 遗物 / 药水链（共用同一个模板）：清单只许更宽，绝不许「藏起来但生成端其实在读」；
			//   ④ 界面：这几行的 Visibility 真的绑到了那些属性上（不然清单对了、界面没动）。
			{
				// ⚠ 「数值 / 命中次数 / 生效次数 / 概率 / 下回合」这些行的显隐判据带 IsCardChain ——
				// 所以探针效果必须**真的挂在一张卡上**，否则测出来全是 false（第一版自检就踩了这个）。
				var dmgCard = new CardSpec { Name = "自检伤害裁剪", ClassName = "UiCheckTrimDamage", CardType = "Attack", Rarity = "Common", Cost = 1 };
				var dmg = new EffectSpec { Kind = "Damage", TargetSide = "Enemy", IsCardChain = true };
				dmgCard.Effects.Add(dmg);
				// 显隐判据带 IsCardChain —— 探针效果一律挂在一张卡上再问（见上面的注释）。
				EffectSpec AttachedEffect(string kind, string side)
				{
					var probeCard = new CardSpec
					{
						Name = "自检裁剪" + kind + side, ClassName = "UiCheckTrim" + kind + side,
						CardType = "Attack", Rarity = "Common", Cost = 1,
					};
					var probeEffect = new EffectSpec { Kind = kind, TargetSide = side, IsCardChain = true };
					probeCard.Effects.Add(probeEffect);
					return probeEffect;
				}
				Check("V0.2.150：造成伤害显示的就是用户点名的那几行（数值公式 / 升级增量 / 作用对象 / 命中次数 / 生效次数 / 概率 / 下回合生效）",
					!dmg.ShowAmountBox && dmg.ShowAmountFormula && dmg.ShowUpgradeAmountRow
					&& dmg.ShowTargetSideRow && dmg.ShowCardRepeatRow && dmg.ShowCardTimesRow
					&& dmg.ShowCardChanceRow && dmg.ShowCardNextTurnRow,
					$"数值框={dmg.ShowAmountBox} 公式={dmg.ShowAmountFormula} 升级增量={dmg.ShowUpgradeAmountRow} "
					+ $"对象={dmg.ShowTargetSideRow} 命中={dmg.ShowCardRepeatRow} 生效={dmg.ShowCardTimesRow} "
					+ $"概率={dmg.ShowCardChanceRow} 下回合={dmg.ShowCardNextTurnRow}");
				Check("V0.2.150：造成伤害上其余那些栏位全收起（增益减益 / 目标卡 / 生成到 / 选牌方式 / 取几张 / 取卡方式 / 复制 / 重放 / 回合结束 / 刮削 / 临时增益 / 牺牲伙伴）",
					!dmg.ShowPowerRow && !dmg.ShowTargetCardRow && !dmg.ShowSpawnToRow && !dmg.ShowCardPickRow
					&& !dmg.ShowCountModeRow && !dmg.ShowSpawnPickRow && !dmg.ShowCopies && !dmg.ShowReplayTimes
					&& !dmg.ShowTurnEndPlay && !dmg.ShowScrapeOptions && !dmg.IsTempPower
					&& !dmg.IsPetSacrifice && !dmg.UsesSelectPile && !dmg.UsesPlaceTo,
					"全收起");
				Check("V0.2.150：造成伤害的「随机目标允许攻击同个敌人」只在「作用对象 = 随机敌人」时出现",
					!dmg.ShowAllowDuplicatesRow
					&& AttachedEffect("Damage", "RandomEnemies").ShowAllowDuplicatesRow
					&& !AttachedEffect("Damage", "AllEnemies").ShowAllowDuplicatesRow,
					"只看作用对象");
				Check("V0.2.150：造成伤害 + 全部友方时「不包括召唤物」那一行照样出现（这一条是本体语义，不藏）",
					AttachedEffect("Damage", "AllAllies").ShowAllyNoPetsOption,
					"在");

				// ② / ③ 机械测量
				CharacterProfile fxScratch = EffectFieldUsage.CreateScratch();
				string fxCardId = Profile.Cards.Count > 0 ? Profile.Cards[0].ClassName : "Shiv";
				string fxPotionId = EffectCatalog.Potions.Count > 0 ? EffectCatalog.Potions[0].Id : "FirePotion";
				var fxRead = new Dictionary<string, bool>(StringComparer.Ordinal);   // "chain|kind|field" → 读了没
				foreach (string chain in new[] { EffectFieldUsage.CardChain, EffectFieldUsage.RelicChain, EffectFieldUsage.PotionChain })
				{
					foreach (EffectKindOption fxKind in EffectCatalog.EffectKinds)
					{
						IReadOnlyList<(EffectFieldProbe Probe, bool Read)> fxMeasured =
							EffectFieldUsage.Measure(fxScratch, chain, fxKind.Kind, fxCardId, fxPotionId, out string? fxBaselineError);
						foreach ((EffectFieldProbe probe, bool read) in fxMeasured)
							fxRead[chain + "|" + fxKind.Kind + "|" + probe.Name] = read;
						if (fxBaselineError is not null)
							Check($"V0.2.150：（准备）探针基线能生成（{chain} / {fxKind.Kind}）", false, fxBaselineError);
					}
				}
				string[] fxAllKinds = EffectCatalog.EffectKinds.Select((EffectKindOption k) => k.Kind).ToArray();

				// 卡牌链：清单 == 测量（不多不少）
				// Shown 里对「范围限定」这一栏要**并上「范围界定」** —— 同一个 SpawnFilter 字段有两个入口：
				// 生成 / 变化类走「范围限定（随机出什么）」，选牌类走「范围界定（哪些牌能选）」。
				(Func<string, bool, bool> Policy, Func<EffectSpec, bool> Shown, string Field, string Zh)[] fxRows =
				{
					((k, plain) => EffectFieldPolicy.UsesTargetSide(k), s => s.ShowTargetSideRow, "TargetSide", "作用对象"),
					((k, plain) => EffectFieldPolicy.UsesPower(k), s => s.ShowPowerRow, "PowerId", "增益 / 减益"),
					((k, plain) => EffectFieldPolicy.UsesTargetCard(k, plain), s => s.ShowTargetCardRow, "SpawnCardId", "目标卡"),
					((k, plain) => EffectFieldPolicy.UsesSpawnTo(k), s => s.ShowSpawnToRow, "SpawnTo", "生成到"),
					((k, plain) => EffectFieldPolicy.UsesCardPick(k), s => s.ShowCardPickRow, "CardPick", "选牌方式"),
					((k, plain) => EffectFieldPolicy.UsesUpgradeAmount(k), s => s.ShowUpgradeAmountRow, "UpgradeAmount", "升级增量"),
					((k, plain) => EffectFieldPolicy.UsesNextTurn(k), s => s.ShowNextTurn, "NextTurn", "下回合生效"),
					// ⚠ 生效次数 / 升级增量这两条是**卡牌链专用**的行（遗物 / 药水那一份是老控件，
					// 判据不是这一份），所以 plain 一侧直接放行，不去管它。
					((k, plain) => plain || EffectFieldPolicy.UsesTimes(k), s => s.ShowCardTimesRow, "Times", "生效次数"),
					((k, plain) => EffectFieldPolicy.UsesCountMode(k), s => s.ShowCountModeRow, "CountMode", "取几张"),
					((k, plain) => EffectFieldPolicy.UsesSpawnPick(k), s => s.ShowSpawnPickRow, "SpawnPick", "取卡方式"),
					((k, plain) => EffectFieldPolicy.UsesSpawnPick(k) || EffectFieldPolicy.UsesCardScopeFilter(k),
						s => s.ShowSpawnFilter || s.ShowCardScopeFilter, "SpawnFilter", "范围限定 / 范围界定"),
					((k, plain) => EffectFieldPolicy.UsesSpawnPick(k), s => s.ShowSpawnChosen, "SpawnChosen", "从范围里自己挑"),
					((k, plain) => EffectFieldPolicy.UsesSpawnPick(k), s => s.ShowSpawnChoice, "SpawnChoice", "多选1"),
					// V0.2.231：只有「播放音频文件」读它（勾了才改生成 —— 走 cs/ForgeSfx.cs）
					((k, plain) => EffectFieldPolicy.UsesSfxReplace(k), s => s.ShowSfxReplaceRow, "SfxReplace", "被下一个自定义音频顶替"),
				};
				// 遗物 / 药水链上这两栏有**自己的入口**（「转化为先古遗物」那个专用编辑器里的
				// 「要换掉哪个遗物 / 换成哪只遗物」，绑的就是 SpawnFilter / SpawnCardId）。
				string[] fxPlainDedicated = { "SpawnFilter", "SpawnCardId" };
				foreach ((Func<string, bool, bool> policy, Func<EffectSpec, bool> shown, string field, string zh) in fxRows)
				{
					var wrong = new List<string>();
					foreach (string kind in fxAllKinds)
					{
						// 显隐要在「有意义的档位」上问：范围限定 / 多选1 / 从范围里自己挑这几个要求「按范围随机」；
						// IsCardChain 也必须给上（界面在卡牌页会设它，不给的话「命中 / 生效 / 概率 / 下回合」全是 false）。
						var spec = new EffectSpec { Kind = kind, TargetSide = "Enemy", SpawnPick = "Random", IsCardChain = true };
						bool visible = shown(spec);
						bool read = fxRead[EffectFieldUsage.CardChain + "|" + kind + "|" + field];
						if (visible != read) wrong.Add(kind + (visible ? "(摆了但没用)" : "(藏了但有用)"));
						if (policy(kind, false) != visible) wrong.Add(kind + "(界面属性和清单不一致)");
					}
					Check($"V0.2.150：卡牌链「{zh}」——显示的都被生成端用到、藏起来的都没用到（67 种逐条对）",
						wrong.Count == 0, wrong.Count == 0 ? "67 种逐条相等" : string.Join(" / ", wrong.Take(8)));

					var plainWrong = new List<string>();
					foreach (string kind in fxAllKinds)
					{
						if (fxPlainDedicated.Contains(field) && kind == "AncientRelicSwap") continue;   // 有专用入口
						if (!policy(kind, true) && (fxRead[EffectFieldUsage.RelicChain + "|" + kind + "|" + field]
							|| fxRead[EffectFieldUsage.PotionChain + "|" + kind + "|" + field]))
							plainWrong.Add(kind);
					}
					Check($"V0.2.150：遗物 / 药水链「{zh}」——不许「藏起来但生成端在读」",
						plainWrong.Count == 0, plainWrong.Count == 0 ? "没有" : string.Join(" / ", plainWrong.Take(8)));
				}
				// 几条「所有种类都该有」的行，反过来钉住：别哪天被人一起裁掉
				foreach ((string field, string zh) in new[]
					{ ("ChanceEnabled", "概率生效"), ("ChanceFormula", "概率（公式）"), ("Condition", "条件选项") })
				{
					var missing = fxAllKinds.Where((string kind) => !fxRead[EffectFieldUsage.CardChain + "|" + kind + "|" + field]).ToList();
					Check($"V0.2.150：卡牌链「{zh}」67 种全都要有（它和效果种类无关）",
						missing.Count == 0, missing.Count == 0 ? "全都有" : "缺：" + string.Join(" / ", missing.Take(8)));
				}

				// ④ 界面：那几行的 Visibility 真的绑到了这些属性上。
				// ⚠ 要收**所有** FrameworkElement，不能只收 Panel：作用对象 / 生成到 / 选牌方式 那几行是
				// TextBlock + ComboBox（没有外层 Grid），随机允许重复是 CheckBox，只收 Panel 会漏。
				var fxPanelPaths = CollectBoundPaths(SelectTabRoot("卡牌"));
				foreach (string path in new[] { "ShowTargetSideRow", "ShowPowerRow", "ShowTargetCardRow", "ShowSpawnToRow",
					"ShowCardPickRow", "ShowUpgradeAmountRow", "ShowCountModeRow", "ShowSpawnPickRow", "ShowAllowDuplicatesRow" })
					Check($"V0.2.150：（界面）卡牌页有一行的显隐绑在 {path} 上", fxPanelPaths.Contains(path), "在");

				// ===== V0.2.220：抽牌 / 拿牌时「为抽到的牌加永久 / 临时关键词」（用户要求）=====
				// ② 清单 ↔ 机械测量（卡牌链逐条相等；遗物 / 药水链不许「藏了但生成端在读」）
				foreach ((string field, string zh, bool temp) in new[]
				{
					("DrawnKeyword", "为抽到的牌加关键词", false),
					("DrawnKeywordTemp", "抽到的牌的关键词是不是临时的", true),
				})
				{
					var wrongKw = new List<string>();
					foreach (string kind in fxAllKinds)
					{
						// 显隐要在「已经选了关键词」的档位上问（临时那个勾本来就跟着关键词出现）
						var spec = new EffectSpec
						{
							Kind = kind, TargetSide = "Enemy", SpawnPick = "Random", IsCardChain = true, DrawnKeyword = "Retain",
						};
						bool visible = temp ? spec.ShowDrawnKeywordTempRow : spec.ShowDrawnKeywordRow;
						bool read = fxRead[EffectFieldUsage.CardChain + "|" + kind + "|" + field];
						bool policy = temp ? EffectFieldPolicy.UsesDrawnKeywordTemp(kind) : EffectFieldPolicy.UsesDrawnKeyword(kind);
						if (visible != read) wrongKw.Add(kind + (visible ? "(摆了但没用)" : "(藏了但有用)"));
						if (policy != visible) wrongKw.Add(kind + "(界面属性和清单不一致)");
					}
					Check($"V0.2.220：卡牌链「{zh}」——显示的都被生成端用到、藏起来的都没用到（{fxAllKinds.Length} 种逐条对）",
						wrongKw.Count == 0, wrongKw.Count == 0 ? $"{fxAllKinds.Length} 种逐条相等" : string.Join(" / ", wrongKw.Take(8)));
					var plainKwWrong = new List<string>();
					foreach (string kind in fxAllKinds)
						if (!EffectFieldPolicy.UsesDrawnKeyword(kind)
							&& (fxRead[EffectFieldUsage.RelicChain + "|" + kind + "|" + field]
								|| fxRead[EffectFieldUsage.PotionChain + "|" + kind + "|" + field]))
							plainKwWrong.Add(kind);
					Check($"V0.2.220：遗物 / 药水链「{zh}」——不许「藏起来但生成端在读」",
						plainKwWrong.Count == 0, plainKwWrong.Count == 0 ? "没有" : string.Join(" / ", plainKwWrong.Take(8)));
				}
				Check("V0.2.220：这一栏只在「真的把牌拿进手」的那几档出现（抽牌 / 刮削 / 从三摞拿牌 / 填满手牌）",
					EffectFieldPolicy.UsesDrawnKeyword("Draw") && EffectFieldPolicy.UsesDrawnKeyword("ScrapeDraw")
					&& EffectFieldPolicy.UsesDrawnKeyword("TakeFromDraw") && EffectFieldPolicy.UsesDrawnKeyword("TakeFromDiscard")
					&& EffectFieldPolicy.UsesDrawnKeyword("TakeFromExhaust") && EffectFieldPolicy.UsesDrawnKeyword("FillHand")
					&& !EffectFieldPolicy.UsesDrawnKeyword("Damage") && !EffectFieldPolicy.UsesDrawnKeyword("Block")
					&& !EffectFieldPolicy.UsesDrawnKeyword("GiveKeyword") && !EffectFieldPolicy.UsesDrawnKeyword("Scry"),
					"六档在、别的都不在");

				// ① 生成形状：没填关键词 = 老那一句（逐字）；填了才多出「接住抽到的牌 + 加关键词」
				{
					var kwCardBase = new CardSpec
					{
						Name = "自检抽牌关键词", ClassName = "UiCheckDrawnKw", CardType = "Skill", Rarity = "Common", Cost = 1,
						InCardPool = true,
					};
					var plainDraw = new EffectSpec { Kind = "Draw", Amount = 2m, TargetSide = "Self", IsCardChain = true };
					kwCardBase.Effects.Add(plainDraw);
					var kwProfile = ProfileFactory.Sample();
					kwProfile.Cards.Add(kwCardBase);
					string plainSrc = CSharpCodeGen.CardSource(kwProfile, kwCardBase, kwProfile.Cards.Count - 1);
					Check("V0.2.220：没选关键词时「抽牌」还是老那一句（不接抽牌结果、一个字符都不多）",
						plainSrc.Contains("await CardPileCmd.Draw(choiceContext, base.DynamicVars.Cards.BaseValue, base.Owner);")
						&& !plainSrc.Contains("__drawnBatch") && !plainSrc.Contains("__drawnKw"), "老那一句");

					plainDraw.DrawnKeyword = "Retain";
					string permSrc = CSharpCodeGen.CardSource(kwProfile, kwCardBase, kwProfile.Cards.Count - 1);
					Check("V0.2.220：选了关键词 → 接住抽到的牌，再给这几张加关键词（永久 = 本体 AddKeyword）",
						permSrc.Contains("IEnumerable<CardModel> __drawnBatch = await CardPileCmd.Draw(")
						&& permSrc.Contains("foreach (CardModel __drawnKw in __drawnBatch)")
						&& permSrc.Contains("__drawnKw.AddKeyword(CardKeyword.Retain);"), "接住了");
					Check("V0.2.220：回读标记（关键词 + 是不是临时）写在抽牌那一句前面",
						permSrc.Contains("// CET:DrawnKeyword=Retain CET:DrawnKeywordTemp=0"), "写了");

					plainDraw.DrawnKeywordTemp = true;
					string tempSrc = CSharpCodeGen.CardSource(kwProfile, kwCardBase, kwProfile.Cards.Count - 1);
					Check("V0.2.220：勾「临时」→ 保留走本体的单回合标记（GiveSingleTurnRetain，回合末自动复位）",
						tempSrc.Contains("__drawnKw.GiveSingleTurnRetain();")
						&& tempSrc.Contains("// CET:DrawnKeyword=Retain CET:DrawnKeywordTemp=1"), "单回合");

					// 自定义关键词：走 AddGivenCustomKeyword + 生成那个注册表 / 临时关键词 Power
					plainDraw.DrawnKeyword = "FATE";
					string customSrc = CSharpCodeGen.CardSource(kwProfile, kwCardBase, kwProfile.Cards.Count - 1);
					Check("V0.2.220：自定义关键词走同一套（AddGivenCustomKeyword + 生成的临时关键词 Power）",
						customSrc.Contains("__drawnKw.AddGivenCustomKeyword(\"FATE\");")
						&& customSrc.Contains("ForgeTempKeywordPower"), "同一套");
					Check("V0.2.220：配了「为抽到的牌加自定义关键词」→ 必须生成那个注册表（否则 AddGivenCustomKeyword 不存在）",
						CSharpCodeGen.UsesGivenCustomKeyword(kwProfile)
						&& CSharpCodeGen.UsesTempKeywordPower(kwProfile), "都会生成");
					Check("V0.2.220：抽到的牌加关键词时，列表行里也写得出来",
						plainDraw.Display.Contains("抽到的牌带上"), plainDraw.Display);
					plainDraw.DrawnKeyword = "";
					plainDraw.DrawnKeywordTemp = false;
				}

				// ① 生成形状：从三摞拿牌 / 填满手牌也能加（用的是那条效果真的拿到手的那批牌）
				{
					var takeCard = new CardSpec
					{
						Name = "自检拿牌关键词", ClassName = "UiCheckTakeKw", CardType = "Skill", Rarity = "Common", Cost = 1,
						InCardPool = true,
					};
					var take = new EffectSpec
					{
						Kind = "TakeFromDiscard", Amount = 1m, TargetSide = "Self", IsCardChain = true,
						CardPick = "Chosen", SelectPile = "Discard", DrawnKeyword = "Exhaust",
					};
					takeCard.Effects.Add(take);
					var takeProfile = ProfileFactory.Sample();
					takeProfile.Cards.Add(takeCard);
					string takeSrc = CSharpCodeGen.CardSource(takeProfile, takeCard, takeProfile.Cards.Count - 1);
					Check("V0.2.220：从弃牌堆拿牌 → 给拿到手的那几张加关键词（加在 Add 之后）",
						takeSrc.Contains("foreach (CardModel __drawnKw in __taken)")
						&& takeSrc.IndexOf("__drawnKw in __taken", StringComparison.Ordinal)
							> takeSrc.IndexOf("await CardPileCmd.Add(__taken, PileType.Hand)", StringComparison.Ordinal),
						"加在 Add 之后");
					Check("V0.2.220：「全部」那一档也能加（用在那一摞里挑出来的全部牌）",
						true, "（下面单独验）");
					var all = new EffectSpec
					{
						Kind = "TakeFromExhaust", Amount = 1m, TargetSide = "Self", IsCardChain = true,
						CardPick = "Random", SelectPile = "Exhaust", CountMode = "All", DrawnKeyword = "Retain",
					};
					takeCard.Effects.Clear();
					takeCard.Effects.Add(all);
					string allSrc = CSharpCodeGen.CardSource(takeProfile, takeCard, takeProfile.Cards.Count - 1);
					Check("V0.2.220：「全部」那一档 → foreach (… in __fgAllTaken)",
						allSrc.Contains("foreach (CardModel __drawnKw in __fgAllTaken)"), "对");

					var fill = new EffectSpec
					{
						Kind = "FillHand", Amount = 0m, TargetSide = "Self", IsCardChain = true,
						SpawnCardId = "Shiv", DrawnKeyword = "Retain",
					};
					takeCard.Effects.Clear();
					takeCard.Effects.Add(fill);
					string fillSrc = CSharpCodeGen.CardSource(takeProfile, takeCard, takeProfile.Cards.Count - 1);
					Check("V0.2.220：用目标卡填满手牌 → 给填进来的那几张加关键词",
						fillSrc.Contains("foreach (CardModel __drawnKw in __filled)"), "对");
				}

				// ② 校验器：「下回合生效」+ 加关键词 = 加不上，要说清；不抽牌的效果上配了它也要拦一句
				{
					var delayedDraw = new EffectSpec { Kind = "Draw", Amount = 1m, NextTurn = true, DrawnKeyword = "Retain" };
					var delayedProfile = new CharacterProfile
					{
						Cards =
						{
							new CardSpec
							{
								Name = "自检延迟抽牌", ClassName = "UiCheckDrawnDelay", CardType = "Skill", Rarity = "Common", Cost = 1,
								Effects = { delayedDraw },
							},
						},
					};
					Check("V0.2.220：校验器：「下回合生效」的抽牌配了加关键词 → 明确警告「这一项不会生效」",
						ProfileValidator.Validate(delayedProfile).Any((ValidationIssue i) => i.Message.Contains("不会生效")
							&& i.Message.Contains("下回合")),
						"警告了");
					var wrongKind = new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", DrawnKeyword = "Retain" };
					var wrongProfile = new CharacterProfile
					{
						Cards =
						{
							new CardSpec
							{
								Name = "自检不抽牌", ClassName = "UiCheckDrawnWrong", CardType = "Attack", Rarity = "Common", Cost = 1,
								Effects = { wrongKind },
							},
						},
					};
					Check("V0.2.220：校验器：把「加关键词」配到不抽牌的效果上 → 警告会被忽略（不静默）",
						ProfileValidator.Validate(wrongProfile).Any((ValidationIssue i) => i.Message.Contains("不抽牌也不拿牌")),
						"警告了");
				}

				// ③ 生成 → 回读：关键词 + 临时都要认得回来（不许变回「不加」）
				{
					var rtCard = new CardSpec
					{
						Name = "自检抽牌回读", ClassName = "UiCheckDrawnKwBack", CardType = "Skill", Rarity = "Common", Cost = 1,
						InCardPool = true,
					};
					rtCard.Effects.Add(new EffectSpec
					{
						Kind = "Draw", Amount = 2m, TargetSide = "Self", IsCardChain = true,
						DrawnKeyword = "Retain", DrawnKeywordTemp = true,
					});
					rtCard.Effects.Add(new EffectSpec
					{
						Kind = "TakeFromDraw", Amount = 1m, TargetSide = "Self", IsCardChain = true,
						CardPick = "Chosen", SelectPile = "Draw", DrawnKeyword = "FATE",
					});
					var rtProfile = ProfileFactory.Sample();
					rtProfile.Cards.Add(rtCard);
					string rtRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_drawnkw_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					try
					{
						rtProfile.Paths.OutputDir = rtRoot;
						rtProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
						rtProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
						var rtGen = ModGenerator.Generate(rtProfile);
						Check("V0.2.220：（准备）带「为抽到的牌加关键词」的存档能生成工程", rtGen.Success,
							rtGen.Success ? rtGen.ProjectRoot : string.Join(" ｜ ", rtGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
						if (rtGen.Success)
						{
							var rtRec = ProjectRecovery.FromProject(rtGen.ProjectRoot);
							CardSpec? rtBack = rtRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckDrawnKwBack");
							EffectSpec? drawBack = rtBack?.Effects.FirstOrDefault((EffectSpec x) => x.Kind == "Draw");
							EffectSpec? takeBack = rtBack?.Effects.FirstOrDefault((EffectSpec x) => x.Kind == "TakeFromDraw");
							Check("V0.2.220：回读：抽牌的「关键词 + 临时」认得回来",
								drawBack is not null && drawBack.DrawnKeyword == "Retain" && drawBack.DrawnKeywordTemp,
								drawBack is null ? "(缺)" : $"{drawBack.DrawnKeyword} / 临时={drawBack.DrawnKeywordTemp}");
							Check("V0.2.220：回读：拿牌的「自定义关键词」认得回来",
								takeBack is not null && takeBack.DrawnKeyword == "FATE",
								takeBack is null ? "(缺)" : takeBack.DrawnKeyword);
							Check("V0.2.220：回读：加关键词那几行没有被当成「又一条给予关键词」（效果条数 / 未认出语句都要对）",
								rtBack is not null && rtBack.Effects.Count == 2 && !rtRec.HasUnparsed,
								rtRec.HasUnparsed ? (rtRec.Unparsed.FirstOrDefault() ?? "") : $"效果 {rtBack?.Effects.Count} 条");
						}
					}
					finally
					{
						try { Directory.Delete(rtRoot, true); } catch { }
					}
				}

				// ④ 界面：两行真的挂上去了（绑在 ShowDrawnKeywordRow / ShowDrawnKeywordTempRow 上），
				//    下拉候选和「生成出来的卡加关键词」同源（第一项是「不加」）。
				{
					var uiPaths = CollectBoundPaths(SelectTabRoot("卡牌"));
					foreach (string path in new[] { "ShowDrawnKeywordRow", "ShowDrawnKeywordTempRow" })
						Check($"V0.2.220：（界面）卡牌页有一行的显隐绑在 {path} 上", uiPaths.Contains(path), "在");
					Check("V0.2.220：（界面）下拉候选和「生成出来的卡加关键词」同源（第一项 = 不加）",
						DrawnKeywordChoices.Count == SpawnKeywordChoices.Count
						&& DrawnKeywordChoices[0].Id.Length == 0
						&& DrawnKeywordChoices.Select((KeywordChoiceOption k) => k.Id)
							.SequenceEqual(SpawnKeywordChoices.Select((KeywordChoiceOption k) => k.Id)),
						$"{DrawnKeywordChoices.Count} 项");
				}
			}

			// ===== V0.2.220（锻造页那一份）：【效果】模块上的「为抽到的牌加关键词」 =====
			// 判据和卡牌页同一份（EffectFieldPolicy.UsesDrawnKeyword），所以这里验的是「图上真的生成得出来」：
			// 桥（节点字段 ⇄ EffectSpec）、生成文本、（旧图）不填时一个字都不变。
			{
				var effectKindDef = ForgeGraphCatalog.Find("Effect");
				var fxKeys = effectKindDef.Fields.Select((ForgeNodeField f) => f.Key).ToList();
				Check("V0.2.220：锻造【效果】模块上有「为抽到的牌加关键词 / 是不是临时」两栏",
					fxKeys.Contains("DrawnKeyword") && fxKeys.Contains("DrawnKeywordTemp"),
					string.Join(" / ", fxKeys.Where((string k) => k.StartsWith("DrawnKeyword", StringComparison.Ordinal))));

				var kwNode = new ForgeNodeSpec { Kind = "Effect" };
				kwNode.SetField("Effect", "Draw");
				kwNode.SetField("Amount", "2");
				kwNode.SetField("DrawnKeyword", "Retain");
				kwNode.SetField("DrawnKeywordTemp", "1");
				var kwSpecFromNode = ForgeEffectBridge.FromFields(kwNode);
				Check("V0.2.220：桥（节点 → 效果）：关键词 + 临时读得出来",
					kwSpecFromNode.DrawnKeyword == "Retain" && kwSpecFromNode.DrawnKeywordTemp, $"{kwSpecFromNode.DrawnKeyword} / {kwSpecFromNode.DrawnKeywordTemp}");
				kwNode.EffectSpec = kwSpecFromNode;
				ForgeEffectBridge.MirrorToFields(kwNode);
				Check("V0.2.220：桥（效果 → 节点）：关键词 + 临时回写得回去",
					kwNode.Get("DrawnKeyword") == "Retain" && kwNode.Get("DrawnKeywordTemp") == "1",
					$"{kwNode.Get("DrawnKeyword")} / {kwNode.Get("DrawnKeywordTemp")}");

				// 图上生成：一张锻造卡 = 【触发时机：打出这张牌时】→【效果：抽牌 + 加关键词】
				var gCard = new CardSpec
				{
					Name = "自检图抽牌关键词", ClassName = "UiCheckGraphDrawnKw", CardType = "Skill", Rarity = "Common",
					Cost = 1, IsForged = true, InCardPool = true,
				};
				gCard.ForgeGraph = new ForgeGraphSpec();
				var gTrig = new ForgeNodeSpec { Kind = "Trigger" };
				gTrig.SetField("Timing", ForgeTimings.CardPlayed);
				var gEff = new ForgeNodeSpec { Kind = "Effect" };
				gEff.SetField("Effect", "Draw");
				gEff.SetField("Amount", "2");
				gEff.SetField("DrawnKeyword", "Retain");
				gCard.ForgeGraph.Nodes.AddRange(new[] { gTrig, gEff });
				gCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = gTrig.Id, To = gEff.Id });
				var gProfile = ProfileFactory.Sample();
				gProfile.Cards.Clear();
				for (int i = 1; i <= 4; i++)
					gProfile.Cards.Add(new CardSpec
					{
						Name = "filler" + i, ClassName = "UiKwFiller" + i,
						CardType = i % 2 == 1 ? "Attack" : "Skill", Rarity = i == 4 ? "Rare" : "Common", Cost = 1,
						InCardPool = true,
						Effects = { new EffectSpec { Kind = i % 2 == 1 ? "Damage" : "Block", Amount = 6m, TargetSide = i % 2 == 1 ? "Enemy" : "Self" } },
					});
				gProfile.Cards.Add(gCard);
				string gSrc = CSharpCodeGen.CardSource(gProfile, gCard, gProfile.Cards.Count - 1);
				Check("V0.2.220：锻造图里填了关键词 → 生成「接住抽到的牌 + foreach 加关键词」（用图自己的 __fgPlayer）",
					gSrc.Contains("IEnumerable<CardModel> __drawnBatch = await CardPileCmd.Draw(choiceContext, (2m), __fgPlayer)")
					&& gSrc.Contains("foreach (CardModel __drawnKw in __drawnBatch)")
					&& gSrc.Contains("__drawnKw.AddKeyword(CardKeyword.Retain);"), "生成了");
				// 旧图（没有这一栏）→ 还是老那一行（图上逐字不变）。
				// ⚠ 要通过 spec 清（生成端读的就是这个 EffectSpec；界面上那一栏绑的也是它）
				ForgeEffectBridge.Ensure(gEff).DrawnKeyword = "";
				string gOldSrc = CSharpCodeGen.CardSource(gProfile, gCard, gProfile.Cards.Count - 1);
				Check("V0.2.220：旧图（不填关键词）图上还是老那一行（不接抽牌结果）",
					gOldSrc.Contains("await CardPileCmd.Draw(choiceContext, (2m), __fgPlayer)")
					&& !gOldSrc.Contains("__drawnBatch") && !gOldSrc.Contains("__drawnKw"), "老那一行");
			}

			// ===== V0.2.221：消耗 / 丢弃 / 升级（以及从三摞拿牌 / 复制 / 变化 / 预见）
			//       + 「只对这张卡（指定）」在**锻造图**上真的生效（用户报的「消耗丢弃升级指定卡没生效」）=====
			// 真因：图上这几档是**自己内联**拼的选牌语句（EmitCardPick / TakeFrom / 变换 / 预见），
			// 以前 `filter: null` 写死 / 随机挑牌不带 `.Where(...)` —— 界面上「范围界定 / 只对这张卡」
			// 那两栏能填，生成端却一个谓词都没读，填了等于没填（静默失效）。
			{
				// 造一张只有一块【效果】的锻造卡（图：触发时机 → 效果）
				string ForgeOneEffect(string kind, System.Action<EffectSpec>? tweak = null)
				{
					var card = new CardSpec
					{
						Name = "自检图指定卡" + kind, ClassName = "UiOcGraph" + kind, CardType = "Skill", Rarity = "Common",
						Cost = 1, IsForged = true, InCardPool = true,
					};
					card.ForgeGraph = new ForgeGraphSpec();
					var trig = new ForgeNodeSpec { Kind = "Trigger" };
					trig.SetField("Timing", ForgeTimings.CardPlayed);
					var eff = new ForgeNodeSpec { Kind = "Effect" };
					eff.SetField("Effect", kind);
					eff.SetField("Amount", "1");
					var spec = ForgeEffectBridge.Author(eff);
					spec.CardPick = "Chosen";
					spec.SelectPile = "Hand";
					tweak?.Invoke(spec);
					card.ForgeGraph.Nodes.AddRange(new[] { trig, eff });
					card.ForgeGraph.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id });
					var prof = ProfileFactory.Sample();
					prof.Cards.Clear();
					for (int i = 1; i <= 4; i++)
						prof.Cards.Add(new CardSpec
						{
							Name = "filler" + i, ClassName = "UiOcFiller" + i,
							CardType = i % 2 == 1 ? "Attack" : "Skill", Rarity = i == 4 ? "Rare" : "Common", Cost = 1,
							InCardPool = true,
							Effects = { new EffectSpec { Kind = i % 2 == 1 ? "Damage" : "Block", Amount = 6m, TargetSide = i % 2 == 1 ? "Enemy" : "Self" } },
						});
					prof.Cards.Add(card);
					return CSharpCodeGen.CardSource(prof, card, prof.Cards.Count - 1);
				}

				foreach (string kind in new[] { "ExhaustCard", "DiscardCard", "UpgradeCard" })
				{
					// V0.2.223：「升级卡牌」在图上现在也筛 `c.IsUpgradable`（和卡牌页同一口径，见下面那组测试）——
					// 所以没填范围时它**不再**是 `filter: null`，而是 `filter: c => c.IsUpgradable`。
					string without = ForgeOneEffect(kind);
					Check($"V0.2.221：图上「{kind}」没填范围时选牌语句不变（filter: null / 不带 Where）",
						kind == "UpgradeCard"
							? without.Contains("filter: c => c.IsUpgradable") && !without.Contains("ModelDb.Card<")
							: without.Contains("filter: null") && !without.Contains("ModelDb.Card<"), "老文本");
					string with = ForgeOneEffect(kind, (EffectSpec s) => s.ScopeCardId = "Strike");
					Check($"V0.2.221：图上「{kind}」+「只对这张卡」→ 选牌时真的按这张卡筛（卡牌页同一份判据）",
						with.Contains("filter: c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id")
						|| (kind == "UpgradeCard"
							&& with.Contains("filter: c => (c.IsUpgradable) && (c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id)")),
						with.Contains("ModelDb.Card<") ? "筛了" : "没筛");
				}

				// 随机挑牌那条路：谓词要拼进候选表达式（.Where(...)），不然「随机」永远挑到别的牌
				string rand = ForgeOneEffect("DiscardCard", (EffectSpec s) => { s.ScopeCardId = "Strike"; s.CardPick = "Random"; });
				Check("V0.2.221：图上「随机」那条路也筛（候选表达式后面拼 .Where）",
					rand.Contains(".Where(c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id)"), "筛了");
				// 「全部」那条路同样要筛
				string all = ForgeOneEffect("ExhaustCard", (EffectSpec s) => { s.ScopeCardId = "Strike"; s.CountMode = "All"; });
				Check("V0.2.221：图上「取几张 = 全部」也筛",
					all.Contains("CardPile.GetCards(__fgPlayer, PileType.Hand).Where(c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id)"), "筛了");

				// 从三摞拿牌 / 复制 / 变化 / 预见：图上同样要筛（同一个根因）
				string take = ForgeOneEffect("TakeFromDiscard", (EffectSpec s) => s.ScopeCardId = "Strike");
				Check("V0.2.221：图上「从弃牌堆拿牌 + 只对这张卡」也筛",
					take.Contains(", c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id)"), "筛了");
				string copy = ForgeOneEffect("CopyCard", (EffectSpec s) => s.ScopeCardId = "Strike");
				Check("V0.2.221：图上「复制卡牌 + 只对这张卡」也筛",
					copy.Contains("filter: c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id"), "筛了");
				string tr = ForgeOneEffect("TransformCard", (EffectSpec s) => { s.ScopeCardId = "Strike"; s.TransformPick = "Attack"; });
				Check("V0.2.221：图上「变化卡牌 + 只变化这张卡」也筛（用的是变化那一套判据）",
					tr.Contains("filter: c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id"), "筛了");
				string scry = ForgeOneEffect("Scry", (EffectSpec s) => s.ScopeCardId = "Strike");
				Check("V0.2.221：图上「预见 + 只对这张卡」也筛（只看得到那张牌）",
					scry.Contains(".Take((int)((1m))).Where(c => c.Id == ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id)"), "筛了");

				// 卡牌页这边一直是对的 —— 钉住，别再回退
				var pageCard = new CardSpec { Name = "自检页指定卡", ClassName = "UiOcPageCard", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				pageCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen", ScopeCardId = "Strike", TargetSide = "Self" });
				pageCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 2m, SelectPile = "Draw", CardPick = "Random", ScopeCardId = "Strike", TargetSide = "Self" });
				pageCard.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen", ScopeCardId = "Strike", TargetSide = "Self" });
				var pageProf = ProfileFactory.Sample();
				pageProf.Cards.Add(pageCard);
				string pageSrc = CSharpCodeGen.CardSource(pageProf, pageCard, pageProf.Cards.Count - 1);
				int pageHits = pageSrc.Split("ModelDb.Card<MegaCrit.Sts2.Core.Models.Cards.Strike>().Id").Length - 1;
				Check("V0.2.221：卡牌页的消耗 / 丢弃 / 升级 三档都按「只对这张卡」筛（3 处）", pageHits == 3, $"{pageHits} 处");

				// 校验器：「只对这张卡」填了认不出来的类名（手改存档 / 那张卡被删了 / 换机器类名表没跟过来）
				// → 报错说清，而不是让生成的工程编译不过（`ModelDb.Card<不存在>()` = CS0246/CS0234）。
				var badScope = new EffectSpec
				{
					Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", TargetSide = "Self",
					ScopeCardId = "NoSuchCardXyz",
				};
				var badProf = new CharacterProfile
				{
					Cards =
					{
						new CardSpec
						{
							Name = "自检坏指定卡", ClassName = "UiOcBadCard", CardType = "Skill", Rarity = "Common", Cost = 1,
							Effects = { badScope },
						},
					},
				};
				Check("V0.2.221：校验器：只对这张卡的类名认不出来 → 报错（不让工程编译不过）",
					ProfileValidator.Validate(badProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只对这张卡（指定）")),
					"拦住了");
			}

			// ===== V0.2.222：锻造图里「随机敌人」+「命中次数」（用户报的「对群数和命中次数写在一起、
			//      随机多段效果异常」）=====
			// 真因：图上「随机敌人」的候选列表直接拿的是 **EnemyList（全体敌人）**，再套 foreach + WithHitCount(N)
			// → 「随机敌人 + 命中 4」变成「每个敌人各挨 4 下」（离谱地强），「随机 1 个」变成「全体」。
			// 现在：伤害走本体的 TargetingRandomOpponents（每一下随机挑一个 = 本体「随机多段」），
			// 其它按单位施放的效果按「随机挑 N 个」的列表来（N = 命中次数，和「卡牌」页同口径）。
			{
				// 造一张只有一块【效果】+ 一个【对象 = 随机敌人】的锻造卡 / 遗物
				string RandSrc(bool cardScope, string kind, string hits, string powerId = "", bool dup = true)
				{
					if (cardScope)
					{
						var card = new CardSpec
						{
							Name = "自检随机多段" + kind + hits, ClassName = "UiRand" + kind + hits,
							CardType = "Attack", Rarity = "Common", Cost = 1, IsForged = true, InCardPool = true,
						};
						card.ForgeGraph = new ForgeGraphSpec();
						var trig = new ForgeNodeSpec { Kind = "Trigger" };
						trig.SetField("Timing", ForgeTimings.CardPlayed);
						var unit = new ForgeNodeSpec { Kind = "Unit" };
						unit.SetField("Pick", "RandomEnemy");
						unit.SetField("AllowDuplicate", dup ? "1" : "0");
						var eff = new ForgeNodeSpec { Kind = "Effect" };
						eff.SetField("Effect", kind);
						eff.SetField("Amount", "3");
						eff.SetField("Hits", hits);
						if (powerId.Length > 0) eff.SetField("PowerId", powerId);
						card.ForgeGraph.Nodes.AddRange(new[] { trig, unit, eff });
						card.ForgeGraph.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id });
						card.ForgeGraph.Links.Add(new ForgeLinkSpec { From = unit.Id, To = eff.Id, FromPort = 0, ToPort = 2 });
						var prof = ProfileFactory.Sample();
						prof.Cards.Add(card);
						return CSharpCodeGen.CardSource(prof, card, prof.Cards.Count - 1);
					}
					else
					{
						var relic = new RelicSpec
						{
							Name = "自检随机多段遗物" + kind + hits, ClassName = "UiRandR" + kind + hits,
							Rarity = "Common", Trigger = "PlayerTurnStart",
						};
						relic.ForgeGraph = new ForgeGraphSpec();
						var trig = new ForgeNodeSpec { Kind = "Trigger" };
						trig.SetField("Timing", "PlayerTurnStart");
						var unit = new ForgeNodeSpec { Kind = "Unit" };
						unit.SetField("Pick", "RandomEnemy");
						var eff = new ForgeNodeSpec { Kind = "Effect" };
						eff.SetField("Effect", kind);
						eff.SetField("Amount", "3");
						eff.SetField("Hits", hits);
						relic.ForgeGraph.Nodes.AddRange(new[] { trig, unit, eff });
						relic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id });
						relic.ForgeGraph.Links.Add(new ForgeLinkSpec { From = unit.Id, To = eff.Id, FromPort = 0, ToPort = 2 });
						var prof = ProfileFactory.Sample();
						prof.Relics.Add(relic);
						return CSharpCodeGen.RelicSource(prof, relic, prof.Relics.Count - 1);
					}
				}

				string one = RandSrc(true, "Damage", "1");
				Check("V0.2.222：图上「随机敌人 + 命中 1」= 打一个随机敌人一次（走本体 TargetingRandomOpponents，不是对全体 foreach）",
					one.Contains("TargetingRandomOpponents(base.CombatState, allowDuplicates: true).Execute(choiceContext)")
					&& !one.Contains("foreach (Creature __fgFoe in ForgeFormulaRuntime.EnemyList("), "对");
				string four = RandSrc(true, "Damage", "4");
				Check("V0.2.222：图上「随机敌人 + 命中 4」= 随机打 4 下（TargetingRandomOpponents + WithHitCount(4)），"
					+ "不再变成「每个敌人各挨 4 下」",
					four.Contains("TargetingRandomOpponents(base.CombatState, allowDuplicates: true).WithHitCount(4).Execute(choiceContext)")
					&& !four.Contains("foreach (Creature __fgFoe in ForgeFormulaRuntime.EnemyList("), "对");
				string noDup = RandSrc(true, "Damage", "2", dup: false);
				Check("V0.2.222：不勾「随机目标允许重复选中同一个敌人」时照样传进去（allowDuplicates: false）",
					noDup.Contains("TargetingRandomOpponents(base.CombatState, allowDuplicates: false)"), "传了");

				// 施加状态这类「按单位施放」的：命中次数 = 随机挑几个（和「卡牌」页同一口径）
				string debuff = RandSrc(true, "ApplyPower", "3", "WeakPower");
				Check("V0.2.222：图上「随机敌人 + 施加状态 + 命中 3」= 随机挑 3 个敌人各上一层（不是全体）",
					debuff.Contains("Enumerable.Range(0, 3).Select(_ => ForgeFormulaRuntime.RandomEnemy(__fgPlayer, allowDuplicates: true)).OfType<Creature>().ToList()"),
					debuff.Contains("Enumerable.Range(0, 3)") ? "随机 3 个" : "没筛");
				string debuffNoDup = RandSrc(true, "ApplyPower", "2", "VulnerablePower", dup: false);
				Check("V0.2.222：不勾「允许重复」→ 随机挑 2 个**不同**的敌人（洗牌取前 N 个）",
					debuffNoDup.Contains(".OrderBy(_ => __fgPlayer.RunState.Rng.CombatTargets.NextInt(int.MaxValue)).Take(2)"), "不重复");

				// 遗物 / 药水 / 状态布上没有 Attacker（不能调 TargetingRandomOpponents）→ 走「随机 N 个，每个打命中次数下」
				string relic = RandSrc(false, "Damage", "2");
				Check("V0.2.222：遗物布上「随机敌人 + 命中 2」→ 随机挑 2 个，每个打 2 下（不调要 Attacker 的那个 API）",
					relic.Contains("Enumerable.Range(0, 2)")
					&& relic.Contains(".Targeting(__fgFoe).WithHitCount(2)")
					&& !relic.Contains("TargetingRandomOpponents"), "对");
			}

			// ===== V0.2.223：状态牌局内升级（用户报的「但是好像升级没生效」）=====
			// 真因两条：
			//   ① 「诅咒 / 先古 / 状态」那一页**没有**「可被无限升级」开关（只有「卡牌」页有），
			//      而状态牌恰恰只能在这一页编辑 → 永远生成 `MaxUpgradeLevel => 0` → 升级效果什么都不做；
			//   ② 锻造图里的「升级卡牌」**不筛** `c.IsUpgradable`（卡牌页那份一直筛）→ 选牌界面里连
			//      状态牌 / 诅咒 / 已升满的牌都能选，选中后 `CardCmd.Upgrade` 自己跳过（静默无事发生）。
			{
				// ① 界面：特殊卡那一页也要有这一行
				DependencyObject specialRoot = SelectTabRoot("诅咒 / 先古 / 状态");
				UpdateLayout();
				var specialPaths = CollectBoundPaths(specialRoot);
				Check("V0.2.223：（界面）「诅咒 / 先古 / 状态」页有一行显隐绑在 ShowInfinitelyUpgradable 上",
					specialPaths.Contains("ShowInfinitelyUpgradable"),
					specialPaths.Contains("ShowInfinitelyUpgradable") ? "在" : "(没找到)");
				bool boundToInf = false;
				void WalkSpecial(DependencyObject d)
				{
					if (d is System.Windows.Controls.CheckBox cb
						&& System.Windows.Data.BindingOperations.GetBinding(cb,
							System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty)?.Path?.Path == "InfinitelyUpgradable")
						boundToInf = true;
					int n = System.Windows.Media.VisualTreeHelper.GetChildrenCount(d);
					for (int i = 0; i < n; i++) WalkSpecial(System.Windows.Media.VisualTreeHelper.GetChild(d, i));
				}
				WalkSpecial(specialRoot);
				Check("V0.2.223：（界面）那个勾选框的值真的绑在 InfinitelyUpgradable 上", boundToInf, boundToInf ? "绑了" : "没绑");

				// ② 显隐判据：诅咒不显示（生成端写死 0），状态 / 先古 / 普通卡显示
				Check("V0.2.223：诅咒不显示「可被无限升级」（诅咒写死 MaxUpgradeLevel => 0），状态 / 先古 / 普通卡都显示",
					!new CardSpec { Rarity = "Curse" }.ShowInfinitelyUpgradable
					&& new CardSpec { Rarity = "Status" }.ShowInfinitelyUpgradable
					&& new CardSpec { Rarity = "Ancient" }.ShowInfinitelyUpgradable
					&& new CardSpec { Rarity = "Common" }.ShowInfinitelyUpgradable, "对");
				var rarityProbe = new CardSpec { Rarity = "Common" };
				bool sawRarityRaise = false;
				rarityProbe.PropertyChanged += (_, ev) =>
				{
					if (ev.PropertyName == nameof(CardSpec.ShowInfinitelyUpgradable)) sawRarityRaise = true;
				};
				rarityProbe.Rarity = "Curse";
				Check("V0.2.223：改稀有度会通知 ShowInfinitelyUpgradable（不然换成诅咒那一行还留在界面上）",
					sawRarityRaise, "通知了");

				// ③ 生成：状态牌 + 「可被无限升级」= 局内能升（和本体「凋萎」同一效果），不勾仍然 0
				CharacterProfile upProf = ProfileFactory.Sample();
				var upStatus = new CardSpec
				{
					Name = "自检可升级状态", ClassName = "UiStatusUpInf", CardType = "Status", Rarity = "Status",
					Cost = -1, InCardPool = true, InfinitelyUpgradable = true,
				};
				upStatus.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, UpgradeAmount = 3m, TargetSide = "Enemy" });
				upProf.Cards.Add(upStatus);
				string upSrc = CSharpCodeGen.CardSource(upProf, upStatus, upProf.Cards.Count - 1);
				Check("V0.2.223：状态牌勾了「可被无限升级」→ MaxUpgradeLevel => int.MaxValue（不再写 => 0）",
					upSrc.Contains("public override int MaxUpgradeLevel => int.MaxValue;")
					&& !upSrc.Contains("public override int MaxUpgradeLevel => 0;"), "对");
				Check("V0.2.223：每升一级 +升级增量（OnUpgrade 里 DynamicVars 的 UpgradeValueBy(3m)）",
					upSrc.Contains("protected override void OnUpgrade()") && upSrc.Contains("UpgradeValueBy(3m)"), "对");
				var upPlain = new CardSpec
				{
					Name = "自检原样状态", ClassName = "UiStatusUpPlain", CardType = "Status", Rarity = "Status",
					Cost = -1, InCardPool = true,
				};
				upPlain.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, UpgradeAmount = 3m, TargetSide = "Enemy" });
				upProf.Cards.Add(upPlain);
				string plainUpSrc = CSharpCodeGen.CardSource(upProf, upPlain, upProf.Cards.Count - 1);
				Check("V0.2.223：不勾仍然是 MaxUpgradeLevel => 0（和本体「粘液」一样升不了级）",
					plainUpSrc.Contains("public override int MaxUpgradeLevel => 0;"), "对");

				// ④ 锻造图的「升级卡牌」也要筛 c.IsUpgradable（和卡牌页同一口径）
				string GraphUpgrade(Action<EffectSpec>? tweak)
				{
					var card = new CardSpec
					{
						Name = "自检图上升级", ClassName = "UiGraphUp", CardType = "Skill", Rarity = "Common", Cost = 1,
						IsForged = true, InCardPool = true,
					};
					card.ForgeGraph = new ForgeGraphSpec();
					var trig = new ForgeNodeSpec { Kind = "Trigger" };
					trig.SetField("Timing", ForgeTimings.CardPlayed);
					var eff = new ForgeNodeSpec { Kind = "Effect" };
					eff.SetField("Effect", "UpgradeCard");
					eff.SetField("Amount", "1");
					var spec = ForgeEffectBridge.Author(eff);
					spec.CardPick = "Chosen";
					spec.SelectPile = "Hand";
					tweak?.Invoke(spec);
					card.ForgeGraph.Nodes.AddRange(new[] { trig, eff });
					card.ForgeGraph.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id });
					var prof = ProfileFactory.Sample();
					prof.Cards.Add(card);
					return CSharpCodeGen.CardSource(prof, card, prof.Cards.Count - 1);
				}
				string upChosen = GraphUpgrade(null);
				Check("V0.2.223：图上「升级卡牌（自己选）」按 c.IsUpgradable 筛（选不到状态牌 / 诅咒 / 已升满的牌）",
					upChosen.Contains("filter: c => c.IsUpgradable"), "筛了");
				string upAll = GraphUpgrade((EffectSpec s) => { s.CardPick = "Random"; s.CountMode = "All"; });
				Check("V0.2.223：图上「升级卡牌（取几张=全部）」也只升能升级的",
					upAll.Contains(".Where(c => c.IsUpgradable)"), "筛了");
				string upRandom = GraphUpgrade((EffectSpec s) => s.CardPick = "Random");
				Check("V0.2.223：图上「升级卡牌（随机）」也只从能升级的牌里挑",
					upRandom.Contains(".Where(c => c.IsUpgradable)"), "筛了");
				string upScoped = GraphUpgrade((EffectSpec s) => s.ScopeCardId = "SevenCurse");
				Check("V0.2.223：图上「升级卡牌 + 只对这张卡」= (c.IsUpgradable) && (只对这张卡)（和卡牌页同一条判据）",
					upScoped.Contains("(c.IsUpgradable) && (c.Id == ModelDb.Card<"), "与关系");
			}

			// ===== V0.2.224：额外资源量遗物上的效果 = 「战斗开始时」（每场战斗一次），不是每回合 =====
			// 用户实测报的：「额外资源量遗物触发时机不是固定战斗开始时吗，往上面添加效果实际上是玩家回合开始时」。
			// 真因：那块效果生成在 `BeforeSideTurnStart`（每个回合都会调一次），而它**漏了**
			// 「不是第 1 回合就退出」的守卫 —— 和遗物链「战斗开始时」那一档（RelicTriggerGuardLines 的
			// CombatStart 分支）比起来少了这一句，于是每回合都触发。
			{
				var erOn = ProfileFactory.Sample();
				erOn.ExtraResource.Enabled = true;
				erOn.ExtraResource.Initial = 2;
				erOn.ExtraResource.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" });
				string erSrc = CSharpCodeGen.ExtraResourceSource(erOn);
				int beforeAt = erSrc.IndexOf("BeforeSideTurnStart", StringComparison.Ordinal);
				int guardAt = beforeAt < 0 ? -1 : erSrc.IndexOf("TurnNumber > 1", beforeAt, StringComparison.Ordinal);
				int effectAt = erSrc.IndexOf("GainBlock", StringComparison.Ordinal);
				Check("V0.2.224：额外资源量遗物上的效果只跑「战斗开始时」（BeforeSideTurnStart 里有「不是第 1 回合就退出」的守卫）",
					beforeAt > 0 && guardAt > beforeAt && effectAt > guardAt, $"守卫@{guardAt} / 效果@{effectAt}");
				var erOff = ProfileFactory.Sample();
				erOff.ExtraResource.Enabled = true;
				string erOffSrc = CSharpCodeGen.ExtraResourceSource(erOff);
				Check("V0.2.224：（红线）没加效果时还是老样子（根本不生成 BeforeSideTurnStart 那个方法）",
					!erOffSrc.Contains("BeforeSideTurnStart"), "老样子");
			}

			// ===== V0.2.225：条件「本回合预见过 / 本回合已预见至少 N 次」（用户要求）=====
			// 「预见」是工具自己拼的效果（本体没有这个机制），所以次数也只能工具自己记：
			// cs/CombatCounters.cs 里那个静态计数器（和「每 N 个敌人死亡」共用同一个类），
			// 跑一次「预见」+1，按**玩家自己的回合号**自动清零。
			{
				var scryCond = EffectCatalog.FindCondition("ScryThisTurn");
				var scryAtLeast = EffectCatalog.FindCondition("ScryAtLeast");
				Check("V0.2.225：条件列表里有「本回合预见过」「本回合已预见至少 N 次」（卡牌 / 遗物 / 药水 / 状态都能用）",
					scryCond is not null && scryCond.Display.Contains("预见") && scryCond.ForCard && scryCond.ForRelic && scryCond.ForPower
					&& scryAtLeast is not null && scryAtLeast.NeedsAmount && scryAtLeast.InvertedDisplay is not null,
					$"{(scryCond is null ? "(缺)" : scryCond.Display)} / {(scryAtLeast is null ? "(缺)" : scryAtLeast.Display)}");

				Check("V0.2.225：条件文案会写上数值 N（至少 N 次）/ 填负数时用反向说法",
					CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "ScryAtLeast", Amount = 3m }).Contains("3")
					&& CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "ScryAtLeast", Amount = -3m }).Contains("少于 3"),
					CSharpCodeGen.ConditionText(new ConditionSpec { Kind = "ScryAtLeast", Amount = 3m }));

				Check("V0.2.225：生成的条件表达式走工具自己的计数器（卡牌档用 base.Owner）",
					CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "ScryThisTurn" }, CSharpCodeGen.CondCtx.Card)
						.Contains("ForgeCombatCounters.ScryThisTurn(base.Owner) > 0")
					&& CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "ScryAtLeast", Amount = 2m }, CSharpCodeGen.CondCtx.Card)
						.Contains("ForgeCombatCounters.ScryThisTurn(base.Owner) >= 2")
					&& CSharpCodeGen.ConditionExpr(new ConditionSpec { Kind = "ScryAtLeast", Amount = -2m }, CSharpCodeGen.CondCtx.Card)
						.Contains("ForgeCombatCounters.ScryThisTurn(base.Owner) < 2"),
					"走计数器");

				// 生成 → 回读：两条条件都要认得回来，而且「预见」那条效果还要照旧认得出来（不被多认一条）
				CharacterProfile scryProf = ProfileFactory.Sample();
				var scryCard = new CardSpec
				{
					Name = "自检预见条件", ClassName = "UiScryCondCard", CardType = "Skill", Rarity = "Common", Cost = 1,
					InCardPool = true,
				};
				scryCard.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 3m, TargetSide = "Self" });
				scryCard.Effects.Add(new EffectSpec
				{
					Kind = "Block", Amount = 5m, TargetSide = "Self",
					Condition = new ConditionSpec { Kind = "ScryThisTurn" },
				});
				scryCard.Effects.Add(new EffectSpec
				{
					Kind = "Draw", Amount = 1m, TargetSide = "Self",
					Condition = new ConditionSpec { Kind = "ScryAtLeast", Amount = 2m },
				});
				scryProf.Cards.Add(scryCard);
				string scrySrc = CSharpCodeGen.CardSource(scryProf, scryCard, scryProf.Cards.Count - 1);
				Check("V0.2.225：「预见」那条效果里先 +1（用了这两条条件时才写）",
					scrySrc.Contains("SevenForgeCombatCounters.BumpScry(base.Owner);"), "写了");
				Check("V0.2.225：用「本回合预见过 / 至少 N 次」的两条效果各自包了一层计数器判断",
					scrySrc.Contains("SevenForgeCombatCounters.ScryThisTurn(base.Owner) > 0")
					&& scrySrc.Contains("SevenForgeCombatCounters.ScryThisTurn(base.Owner) >= 2"), "包了");

				var noCondProf = ProfileFactory.Sample();
				var noCondCard = new CardSpec { Name = "自检只用预见", ClassName = "UiScryNoCond", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				noCondCard.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 2m, TargetSide = "Self" });
				noCondProf.Cards.Add(noCondCard);
				string noCondSrc = CSharpCodeGen.CardSource(noCondProf, noCondCard, noCondProf.Cards.Count - 1);
				Check("V0.2.225：（红线）没人用这两条条件时，「预见」效果一个字都不多写（老存档逐字不变）",
					!noCondSrc.Contains("BumpScry") && !noCondSrc.Contains("ForgeCombatCounters"), "没写");

				Check("V0.2.225：那个小运行时只在用到时才生成，而且只写用到的那部分（敌人死亡 / 预见）",
					CSharpCodeGen.UsesScryCounter(scryProf) && !CSharpCodeGen.UsesEnemyDeathCounter(scryProf)
					&& CSharpCodeGen.CombatCountersSource(scryProf).Contains("BumpScry")
					&& !CSharpCodeGen.CombatCountersSource(scryProf).Contains("BumpEnemyDeath")
					&& !CSharpCodeGen.UsesCombatCounters(noCondProf), "按需生成");

				// 校验器：用了这两条条件，但整份配置里一条「预见」都没有 → 警告（计数器永远是 0）
				var badScryProf = ProfileFactory.Sample();
				var badScryCard = new CardSpec { Name = "自检没预见", ClassName = "UiScryBad", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				badScryCard.Effects.Add(new EffectSpec
				{
					Kind = "Block", Amount = 3m, TargetSide = "Self",
					Condition = new ConditionSpec { Kind = "ScryThisTurn" },
				});
				badScryProf.Cards.Add(badScryCard);
				Check("V0.2.225：校验器：用了「本回合预见过」却一条「预见」效果都没有 → 警告",
					ProfileValidator.Validate(badScryProf).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("一条「预见」效果都没有")),
					"警告了");

				// 锻造图上的【条件】也算「用到」（否则记录器不生成 → CS0103）
				var graphScryProf = ProfileFactory.Sample();
				var graphScryCard = new CardSpec
				{
					Name = "自检图上预见", ClassName = "UiScryGraph", CardType = "Skill", Rarity = "Common", Cost = 1,
					IsForged = true, InCardPool = true,
				};
				graphScryCard.ForgeGraph = new ForgeGraphSpec();
				var gTrig = new ForgeNodeSpec { Kind = "Trigger" };
				gTrig.SetField("Timing", ForgeTimings.CardPlayed);
				var gCond = new ForgeNodeSpec { Kind = "Condition" };
				gCond.SetField("Cond", "ScryThisTurn");
				graphScryCard.ForgeGraph.Nodes.AddRange(new[] { gTrig, gCond });
				graphScryCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = gTrig.Id, To = gCond.Id });
				graphScryProf.Cards.Add(graphScryCard);
				Check("V0.2.225：锻造图上【条件】选了「本回合预见过」也算用到（记录器照样生成）",
					CSharpCodeGen.UsesScryCounter(graphScryProf), "算了");

				// 生成 → 回读（新条件要能从工程里认回来）
				string scryRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_scrycond_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					scryProf.Paths.OutputDir = scryRoot;
					scryProf.Paths.VanillaProject = Profile.Paths.VanillaProject;
					scryProf.Paths.GameDataDir = Profile.Paths.GameDataDir;
					scryProf.Cards.Add(graphScryCard);
					var scryGen = ModGenerator.Generate(scryProf);
					Check("V0.2.225：（准备）带「预见」条件的存档能生成工程", scryGen.Success,
						scryGen.Success ? scryGen.ProjectRoot : string.Join(" ｜ ", scryGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (scryGen.Success)
					{
						var scryRec = ProjectRecovery.FromProject(scryGen.ProjectRoot);
						CardSpec? scryBack = scryRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiScryCondCard");
						Check("V0.2.225：回读：「本回合预见过 / 已预见至少 2 次」两条条件都认得回来",
							scryBack is not null
							&& scryBack.Effects.Any((EffectSpec x) => x.Condition?.Kind == "ScryThisTurn")
							&& scryBack.Effects.Any((EffectSpec x) => x.Condition?.Kind == "ScryAtLeast" && x.Condition.Amount == 2m),
							scryBack is null ? "(缺)" : string.Join(" / ", scryBack.Effects.Select((EffectSpec x) => x.Kind + "=" + (x.Condition?.Kind ?? "None"))));
						Check("V0.2.225：回读（新增 +1 那一句之后）「预见」那条效果仍然认得出、没有多出来的语句",
							scryBack is not null
							&& scryBack.Effects.Count((EffectSpec x) => x.Kind == "Scry") == 1
							&& !scryRec.HasUnparsed,
							scryRec.HasUnparsed ? (scryRec.Unparsed.FirstOrDefault() ?? "") : "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(scryRoot, true); } catch { }
				}
			}
			// ===== V0.2.226：「复制卡牌」可以复制自己 / 自己选从哪一摞复制 / 复制到哪一摞（用户要求）=====
			// 用户原话：「复制效果能够复制自己或者可以选择从哪里选择复制并且到哪里」。
			{
				Check("V0.2.226：「放到哪一摞」这一栏对「复制卡牌」也生效（和放置卡牌同一份判据）",
					EffectSpec.KindUsesPlaceTo("CopyCard") && new EffectSpec { Kind = "CopyCard" }.UsesPlaceTo
					&& new EffectSpec { Kind = "CopyCard" }.PlaceToChoices.Count == 5
					&& EffectSpec.KindUsesSelectPile("CopyCard"),
					$"CopyCard→PlaceTo={new EffectSpec { Kind = "CopyCard" }.UsesPlaceTo}");
				Check("V0.2.226：「数值 0 = 这张牌自己」对复制卡牌成立（勾了「数值 = X」时不算）",
					CSharpCodeGen.AmountZeroIsSelf(new EffectSpec { Kind = "CopyCard", Amount = 0m })
					&& !CSharpCodeGen.AmountZeroIsSelf(new EffectSpec { Kind = "CopyCard", Amount = 1m })
					&& !CSharpCodeGen.AmountZeroIsSelf(new EffectSpec { Kind = "CopyCard", Amount = 0m, AmountIsX = true }),
					"0 可以复制自己");

				var copySelfProf = ProfileFactory.Sample();
				var copySelfCard = new CardSpec { Name = "自检复制自己", ClassName = "UiCopySelf", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				copySelfCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 0m, Copies = 2, PlaceTo = "Top", TargetSide = "Self" });
				copySelfProf.Cards.Add(copySelfCard);
				string copySelfSrc = CSharpCodeGen.CardSource(copySelfProf, copySelfCard, copySelfProf.Cards.Count - 1);
				Check("V0.2.226：数值 0 的复制卡牌会克隆**这张牌自己** N 份（不是弹选牌界面）",
					copySelfSrc.Contains("CardModel __selfClone = this.CreateClone();")
					&& copySelfSrc.Contains("AddGeneratedCardToCombat(__selfClone, PileType.Draw, base.Owner, CardPilePosition.Top)")
					&& !copySelfSrc.Contains("CardSelectCmd."),
					"克隆自己");
				string copySelfJson = LocalizationGen.CardsJson(copySelfProf);
				Check("V0.2.226：卡面描述写清「复制这张牌本身 N 份」和放到哪一摞",
					copySelfJson.Contains("复制这张牌本身 2 份到牌顶"),
					copySelfJson.Contains("复制这张牌本身 2 份到牌顶") ? "文案对" : "文案不对");

				// 老档红线：默认（数值 ≥ 1、复制到手牌）一个字符都不变
				var copyOldProf = ProfileFactory.Sample();
				var copyOldCard = new CardSpec { Name = "自检老复制", ClassName = "UiCopyOld", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				copyOldCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, Copies = 1, SelectPile = "Hand", PlaceTo = "Hand", CardPick = "Chosen", TargetSide = "Self" });
				copyOldProf.Cards.Add(copyOldCard);
				string copyOldSrc = CSharpCodeGen.CardSource(copyOldProf, copyOldCard, copyOldProf.Cards.Count - 1);
				string copyOldJson = LocalizationGen.CardsJson(copyOldProf);
				Check("V0.2.226：（红线）默认「复制到手牌」生成文本逐字不变（还是手牌那一摞、没有位置实参）",
					copyOldSrc.Contains("PileType.Hand, base.Owner)") && !copyOldSrc.Contains("CardPilePosition")
					&& copyOldSrc.Contains("CET:Copies=1")
					&& copyOldJson.Contains("（每张复制一份到手牌）"),
					copyOldSrc.Contains("PileType.Hand, base.Owner)") ? "逐字不变" : "变了");

				// 「复制到弃牌堆」（数值 ≥ 1 那条路：从抽牌堆选 2 张，每张复制 2 份塞进弃牌堆）
				var copyToProf = ProfileFactory.Sample();
				var copyToCard = new CardSpec { Name = "自检复制到弃牌堆", ClassName = "UiCopyTo", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				copyToCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 2m, Copies = 2, SelectPile = "Draw", CardPick = "Chosen", PlaceTo = "Discard", TargetSide = "Self" });
				copyToProf.Cards.Add(copyToCard);
				string copyToSrc = CSharpCodeGen.CardSource(copyToProf, copyToCard, copyToProf.Cards.Count - 1);
				Check("V0.2.226：复制出来的牌按「放到哪一摞」进弃牌堆（不是死写手牌）",
					copyToSrc.Contains("AddGeneratedCardToCombat(__clone, PileType.Discard, base.Owner)")
					&& copyToSrc.Contains("CET:PlaceTo=Discard"),
					copyToSrc.Contains("PileType.Discard") ? "进弃牌堆" : "还是手牌");

				// 遗物 / 药水 / 状态上没有「这张牌」：数值 0 必须报出来，而不是悄悄什么都不做
				var copyRelicProf = ProfileFactory.Sample();
				var copyRelic = new RelicSpec { Name = "自检复制遗物", ClassName = "UiCopyRelic", Rarity = "Common", Trigger = "PlayerTurnStart" };
				copyRelic.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 0m, PlaceTo = "Top", TargetSide = "Self" });
				copyRelicProf.Relics.Add(copyRelic);
				Check("V0.2.226：遗物上填 0 = 复制自己 → 校验器给出警告（那种布上没有「这张牌」）",
					ProfileValidator.Validate(copyRelicProf).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("只有在**卡牌**上成立")),
					"警告了");

				// 锻造图：节点上的「放到哪一摞」要真的生效（自己那条 + 选自手牌那条）
				var copyGraphProf = ProfileFactory.Sample();
				var copyGraphCard = new CardSpec
				{
					Name = "自检图上复制", ClassName = "UiCopyGraph", CardType = "Skill", Rarity = "Common", Cost = 1,
					IsForged = true, InCardPool = true,
				};
				copyGraphCard.ForgeGraph = new ForgeGraphSpec();
				var cgTrig = new ForgeNodeSpec { Kind = "Trigger" };
				cgTrig.SetField("Timing", ForgeTimings.CardPlayed);
				copyGraphCard.ForgeGraph.Nodes.Add(cgTrig);
				var cgPrev = cgTrig;
				foreach ((string cgAmt, string cgPlace) in new[] { ("0", "Top"), ("1", "Exhaust") })
				{
					var cgNode = new ForgeNodeSpec { Kind = "Effect" };
					cgNode.SetField("Effect", "CopyCard");
					cgNode.SetField("Amount", cgAmt);
					cgNode.SetField("SelectPile", "Hand");
					cgNode.SetField("PlaceTo", cgPlace);
					cgNode.SetField("Pick", "Chosen");
					copyGraphCard.ForgeGraph.Nodes.Add(cgNode);
					copyGraphCard.ForgeGraph.Links.Add(new ForgeLinkSpec { From = cgPrev.Id, To = cgNode.Id });
					cgPrev = cgNode;
				}
				copyGraphProf.Cards.Add(copyGraphCard);
				string copyGraphSrc = CSharpCodeGen.CardSource(copyGraphProf, copyGraphCard, copyGraphProf.Cards.Count - 1);
				Check("V0.2.226：锻造图里「复制卡牌」也认「放到哪一摞」（数值 0 = 复制这张牌自己）",
					copyGraphSrc.Contains("AddGeneratedCardToCombat(__selfClone, PileType.Draw, __fgPlayer, CardPilePosition.Top)")
					&& copyGraphSrc.Contains("PileType.Exhaust, __fgPlayer)"),
					copyGraphSrc.Contains("PileType.Exhaust, __fgPlayer)") ? "图上也对" : "图上没生效");

				// 生成 → 回读（CET:PlaceTo 这条标记要能把「复制到哪一摞」带回来）
				string copyRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_copycard_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					var copyGenProf = ProfileFactory.Sample();
					var copyGenSelf = new CardSpec { Name = "自检回读自己", ClassName = "UiCopyBackSelf", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					copyGenSelf.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 0m, Copies = 2, PlaceTo = "Top", TargetSide = "Self" });
					var copyGenMany = new CardSpec { Name = "自检回读弃牌堆", ClassName = "UiCopyBackMany", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					copyGenMany.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 2m, Copies = 2, SelectPile = "Draw", CardPick = "Chosen", PlaceTo = "Discard", TargetSide = "Self" });
					copyGenProf.Cards.Add(copyGenSelf);
					copyGenProf.Cards.Add(copyGenMany);
					copyGenProf.Paths.OutputDir = copyRoot;
					copyGenProf.Paths.VanillaProject = Profile.Paths.VanillaProject;
					copyGenProf.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var copyGen = ModGenerator.Generate(copyGenProf);
					Check("V0.2.226：（准备）带「复制自己 / 复制到弃牌堆」的存档能生成工程", copyGen.Success,
						copyGen.Success ? copyGen.ProjectRoot : string.Join(" ｜ ", copyGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (copyGen.Success)
					{
						var copyRec = ProjectRecovery.FromProject(copyGen.ProjectRoot);
						CardSpec? copyBackSelf = copyRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCopyBackSelf");
						CardSpec? copyBackMany = copyRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCopyBackMany");
						Check("V0.2.226：回读：复制自己（数值 0）和「放到哪一摞」都认得回来",
							copyBackSelf is not null && copyBackSelf.Effects.Any((EffectSpec x) => x.Kind == "CopyCard" && x.Amount == 0m && x.PlaceTo == "Top" && x.Copies == 2)
							&& copyBackMany is not null && copyBackMany.Effects.Any((EffectSpec x) => x.Kind == "CopyCard" && x.Amount == 2m && x.PlaceTo == "Discard" && x.SelectPile == "Draw"),
							(copyBackSelf is null ? "(缺自己)" : string.Join(" / ", copyBackSelf.Effects.Select((EffectSpec x) => x.Kind + ":" + x.Amount + ":" + x.PlaceTo)))
							+ " ｜ "
							+ (copyBackMany is null ? "(缺弃牌堆)" : string.Join(" / ", copyBackMany.Effects.Select((EffectSpec x) => x.Kind + ":" + x.Amount + ":" + x.PlaceTo))));
						Check("V0.2.226：回读时「复制自己」那段实现整段跳过（不留没认出来的语句）",
							!copyRec.HasUnparsed, copyRec.HasUnparsed ? (copyRec.Unparsed.FirstOrDefault() ?? "") : "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(copyRoot, true); } catch { }
				}
			}

			// ===== V0.2.151：效果栏版式（标签列不许吃掉输入列）+ 「转化为先古卡」的范围候选 =====
			// 用户实测报的四条：①「次数公式怎么不见了」②「转变为先古卡和先古遗物怎么选不了范围」
			// ③「放置卡牌效果怎么没反应」④「有一部分的UI有问题」（附截图：第二列被挤成一条缝）。
			// 真因：效果栏第一列是 Width=Auto 的标签列，「从哪里选牌（…34 个字…）」把第一列撑到约 500px，
			// 第二列（输入列）只剩 40px → 「生效次数（公式）」被挤出可视区（=①）、
			// 「选牌方式 / 从哪里选牌」下拉变成点不动的一条缝（=③④）。
			// ②是另一件事：配对表左边那一栏以前只列**自定义「组」**，一个组都没建时下拉是空的。
			{
				var longLabels = new List<string>();
				foreach (EffectKindOption opt in EffectCatalog.EffectKinds)
				{
					string label = new EffectSpec { Kind = opt.Kind }.SelectPileLabel;
					if (label.Length > 8) longLabels.Add(opt.Kind + ":" + label);
				}
				Check("V0.2.151：「从哪里选牌 / 丢弃 / 升级」那一行的标签都很短（长说明一律进 ToolTip）",
					longLabels.Count == 0, longLabels.Count == 0 ? "都很短" : string.Join(" / ", longLabels.Take(5)));

				CardSpec? trimCard = new CardSpec
				{
					Name = "自检版式", ClassName = "UiCheckLayoutTrim", CardType = "Skill", Rarity = "Common", Cost = 1,
				};
				var trimFx = new EffectSpec { Kind = "GiveKeyword", Amount = 3m, GivenKeyword = "Retain", IsCardChain = true };
				trimCard.Effects.Add(trimFx);
				object? previousCard = null;
				try
				{
					previousCard = CardList.SelectedItem;
					Profile.Cards.Add(trimCard);
					SelectTabRoot("卡牌");
					CardList.SelectedItem = trimCard;
					UpdateLayout();
					CardEffectList.SelectedItem = trimFx;
					UpdateLayout();
					var layoutGrids = new List<Grid>();
					CollectGrids(SelectTabRoot("卡牌"), layoutGrids);
					Grid? effectGrid = layoutGrids.FirstOrDefault((Grid g) => g.DataContext == trimFx
						&& g.ColumnDefinitions.Count == 2 && g.RowDefinitions.Count >= 17);   // V0.2.258：加了「或者清空一个组」那一行 → 18
					Check("V0.2.151：（界面）卡牌页的效果栏真的挂上来了（两列 × 17+ 行那个 Grid）",
						effectGrid is not null, effectGrid is null ? "(没找到)" : "找到");
					if (effectGrid is not null)
					{
						double labelCol = effectGrid.ColumnDefinitions[0].ActualWidth;
						double inputCol = effectGrid.ColumnDefinitions[1].ActualWidth;
						Check("V0.2.151：（界面）标签列不吃掉输入列（标签列 ≤ 360、输入列 ≥ 140）",
							labelCol <= 360 && inputCol >= 140, $"标签列={labelCol:0} / 输入列={inputCol:0}");
					}
				}
				finally
				{
					Profile.Cards.Remove(trimCard);
					CardList.SelectedItem = previousCard;
					UpdateLayout();
				}

				var ancientIds = AncientGroupChoices.Select((SpawnFilterOption f) => f.Id).ToHashSet(StringComparer.Ordinal);
				Check("V0.2.151：「转化为先古卡」的范围下拉里有内置类型（攻击 / 技能 / 能力 / 诅咒 / 状态），没建「组」也能用",
					new[] { "Attack", "Skill", "Power", "Curse", "Status" }.All(ancientIds.Contains),
					ancientIds.Count == 0 ? "(空)" : string.Join(" / ", ancientIds.Take(10)));
				Check("V0.2.151：「转化为先古卡」的范围下拉里没有「不限」（一行「不限」会把能换的牌全换掉）",
					!ancientIds.Contains(""), "没有");
			}

			// ===== V0.2.160：角色页的表单不许伸到可视区外面（用户实测：「角色页右侧的角色显示名…右边都看不到了」）
			// 角色页那 4 列是 `Auto / 320 / Auto / 320`（固定宽），外面那层 ScrollViewer 的
			// 横向滚动默认是 **Disabled** ⇒ 一旦「标签列 + 320 + 标签列 + 320」超过视口宽度，
			// 第 4 列（角色显示名）就被**裁掉**（不是滚动，是根本没有滚动条，看不到也点不到）。
			// 判据：把 Grid 和那一格的右边换算到窗口坐标，和 ScrollViewer 的可视右边比。
			{
				object? previousTabV02160 = MainTabs.SelectedItem;
				try
				{
					DependencyObject roleRoot = SelectTabRoot("角色");
					UpdateLayout();
					var roleGrids = new List<Grid>();
					CollectGrids(roleRoot, roleGrids);
					Grid? roleForm = roleGrids.FirstOrDefault((Grid g) => g.ColumnDefinitions.Count == 4);
					Check("V0.2.160：（界面）角色页那张 4 列表单找得到", roleForm is not null,
						roleForm is null ? "(没找到)" : $"列宽 = {string.Join(" / ", roleForm.ColumnDefinitions.Select((ColumnDefinition cd) => cd.ActualWidth.ToString("0")))}");
					if (roleForm is not null)
					{
						double gridRight = roleForm.TransformToAncestor(this)
							.Transform(new Point(roleForm.ColumnDefinitions.Sum((ColumnDefinition cd) => cd.ActualWidth), 0)).X;
						double boxRight = RoleDisplayNameBox.TransformToAncestor(this)
							.Transform(new Point(RoleDisplayNameBox.ActualWidth, 0)).X;
						double viewportRight = double.MaxValue;
						for (DependencyObject? p = roleForm; p is not null; p = System.Windows.Media.VisualTreeHelper.GetParent(p))
						{
							if (p is ScrollViewer sv)
							{
								viewportRight = sv.TransformToAncestor(this).Transform(new Point(sv.ActualWidth, 0)).X;
								break;
							}
						}
						Check("V0.2.160：（界面）角色页表单整张都落在可视区里（最右那一列没被裁掉）",
							gridRight <= viewportRight + 0.5 && viewportRight < double.MaxValue,
							$"表单右边={gridRight:0} / 可视区右边={viewportRight:0}（窗口宽 {ActualWidth:0}）");
						Check("V0.2.160：（界面）「角色显示名」输入框完整可见（右边不越界、宽度 ≥ 140）",
							boxRight <= viewportRight + 0.5 && RoleDisplayNameBox.ActualWidth >= 140,
							$"输入框右边={boxRight:0} 宽={RoleDisplayNameBox.ActualWidth:0} / 可视区右边={viewportRight:0}");
					}
				}
				finally
				{
					if (previousTabV02160 is TabItem prevTabItem) prevTabItem.IsSelected = true;
					UpdateLayout();
				}
			}

			// ===== V0.2.161：藏起来的栏位，描述里也不许写它 =====
			// 用户实测报的：「为什么抽卡，获得能量之类的效果种类的对象没了，但是显示的是对敌人」。
			// 真因：`EffectSpec._targetSide` 的**默认值就是 "Enemy"**。V0.2.150 按种类把「作用对象」
			// 那一行藏起来了（生成端根本不读），可**列表行行尾**照样印「→ 单体敌人」、**状态描述**照样印
			// 「（对指定敌人）」—— 界面自己和自己矛盾，用户自然以为哪里坏了（其实是显示在说假话）。
			// 判据统一走 `EffectFieldPolicy.UsesTargetSide`（就是那一行的显隐判据）：
			// 「界面上显示的栏位，生成端一定读；藏起来的，生成端一定不读」—— 描述跟着同一条。
			{
				var contradict = new List<string>();
				foreach (EffectKindOption opt in EffectCatalog.EffectKinds)
				{
					var probe = new EffectSpec { Kind = opt.Kind, TargetSide = "Enemy" };
					bool shows = probe.Display.Contains(" → 单体敌人");
					bool expected = EffectFieldPolicy.UsesTargetSide(opt.Kind) && !probe.PetAction;
					if (shows != expected) contradict.Add($"{opt.Kind}(显示={shows}/应={expected})");
				}
				Check("V0.2.161：每一种效果的列表行尾「→ 谁」都和「作用对象」那一行的显隐**同进同出**",
					contradict.Count == 0,
					contradict.Count == 0 ? $"{EffectCatalog.EffectKinds.Count} 种逐条对" : string.Join(" / ", contradict.Take(8)));
				var drawDisplay = new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Enemy" };
				Check("V0.2.161：「抽牌」那一行不再写「→ 单体敌人」（它不读作用对象）",
					!drawDisplay.Display.Contains("单体敌人"), drawDisplay.Display);
				var energyDisplay = new EffectSpec { Kind = "Energy", Amount = 1m, TargetSide = "Enemy" };
				Check("V0.2.161：「获得能量」那一行也不再写「→ 单体敌人」",
					!energyDisplay.Display.Contains("单体敌人"), energyDisplay.Display);
				var dmgDisplay = new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" };
				Check("V0.2.161：（对照）「造成伤害」照旧写「→ 单体敌人」（它真的读作用对象）",
					dmgDisplay.Display.Contains("→ 单体敌人"), dmgDisplay.Display);
				// 状态描述（自定义状态「打出一张牌时」那种）走的是另一段文案，也必须是同一份判据
				var drawPower = new CustomPowerSpec { Name = "自检抽牌状态", ClassName = "UiCheckDrawWho", Enabled = true };
				var drawTrig = new PowerTriggerSpec { Kind = "CardPlayed", PowerTarget = "Self", PowerId = "UiCheckDrawWho" };
				drawTrig.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Enemy" });
				drawPower.Triggers.Add(drawTrig);
				string drawDesc = PowerTriggers.AutoDescription(drawPower);
				Check("V0.2.161：状态描述里的「抽 N 张牌」也不再带「（对指定敌人）」",
					!drawDesc.Contains("对指定敌人"), drawDesc.Replace("\n", " ／ "));
				var dmgPower = new CustomPowerSpec { Name = "自检伤害状态", ClassName = "UiCheckDmgWho", Enabled = true };
				var dmgTrig = new PowerTriggerSpec { Kind = "CardPlayed", PowerTarget = "Self", PowerId = "UiCheckDmgWho" };
				dmgTrig.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Enemy" });
				dmgPower.Triggers.Add(dmgTrig);
				string dmgDesc = PowerTriggers.AutoDescription(dmgPower);
				Check("V0.2.161：（对照）状态描述里的「造成伤害」照旧带「（对指定敌人）」",
					dmgDesc.Contains("对指定敌人"), dmgDesc.Replace("\n", " ／ "));
			}

			// ===== V0.2.162：状态里「某个状态被移除时」盯**敌人**身上的状态收不到通知 =====
			// 用户实测报的：「状态中对于监听某状态移除时的时机疑似无法触发」。
			// 真因（代码里可直接看出来）：补丁的通知范围只有 `power.Owner` 那一只生物 ——
			// 它遍历的是「被移除那个状态所在生物」身上的状态 / 它所属玩家的遗物；
			// 而 UI 允许「盯：任意敌人的状态」，生成出来的守卫里也真的写着
			// `power.Owner != base.Owner && …HittableEnemies.Contains(power.Owner)` ——
			// 挂在自己身上、盯敌人的那种配置**根本等不到这一次通知**（守卫形同虚设、永远不触发）。
			// 修法：通知范围改成**这一场战斗里的所有生物**（`CombatState.Creatures`），各 watcher 的守卫照旧筛。
			{
				CharacterProfile remProfile = ProfileFactory.Sample();
				remProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				remProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var remSelf = new CustomPowerSpec { Name = "自检盯自己", ClassName = "UiCheckRemSelf", Enabled = true };
				var remSelfTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerTarget = "Self", PowerId = "VulnerablePower" };
				remSelfTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				remSelf.Triggers.Add(remSelfTrig);
				remProfile.CustomPowers.Add(remSelf);
				var remFoe = new CustomPowerSpec { Name = "自检盯敌人", ClassName = "UiCheckRemFoe", Enabled = true };
				var remFoeTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerTarget = "AnyEnemy", PowerId = "VulnerablePower" };
				remFoeTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				remFoe.Triggers.Add(remFoeTrig);
				remProfile.CustomPowers.Add(remFoe);
				string remSrc = CSharpCodeGen.PowerRemovalSource(remProfile).Replace("\r\n", "\n");
				Check("V0.2.162：补丁把通知发给**这一场战斗里的所有生物**（不再只发给「被移除那个状态所在的那只」）",
					remSrc.Contains("foreach (Creature __who in __listeners)")
					&& remSrc.Contains("__cs.Creatures")
					&& !remSrc.Contains("foreach (PowerModel __p in owner.Powers.ToList())"),
					remSrc.Contains("__cs.Creatures") ? "发给全部生物" : "(还是只发给自己那一只)");
				Check("V0.2.162：两条「盯自己 / 盯敌人」的自定义状态都进了补丁的通知名单（各一行 case）",
					remSrc.Contains("case UiCheckRemSelf __c:") && remSrc.Contains("case UiCheckRemFoe __c:"),
					$"self={remSrc.Contains("case UiCheckRemSelf __c:")} foe={remSrc.Contains("case UiCheckRemFoe __c:")}");
				Check("V0.2.162：「被移除的那个状态就是自己」那一段在生物循环**外面**（否则会按生物数量重复触发）",
					remSrc.Contains("        }\n        // 3) 被移除的那个状态"),
					remSrc.Contains("        }\n        // 3) 被移除的那个状态") ? "在循环外" : "(被包在循环里了)");
				Check("V0.2.162：每通知一条都计数（排查「没触发」时靠它区分「没人配」和「守卫挡住了」）",
					remSrc.Split("__notified++").Length - 1 == 4,
					$"__notified++ 出现 {remSrc.Split("__notified++").Length - 1} 次（期望 4 = 2 个状态 × (通知段 + 自己被移除段)）");
				Check("V0.2.162：没开「生成调试日志」时补丁里一个字都不多写",
					!remSrc.Contains("[模组调试] 状态被移除"), "没写");
				CharacterProfile remDbg = ProfileFactory.Sample();
				remDbg.Paths.VanillaProject = Profile.Paths.VanillaProject;
				remDbg.Paths.GameDataDir = Profile.Paths.GameDataDir;
				remDbg.DebugLog = true;
				var remDbgPower = new CustomPowerSpec { Name = "自检调试日志", ClassName = "UiCheckRemDbg", Enabled = true };
				var remDbgTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerTarget = "Self" };
				remDbgTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				remDbgPower.Triggers.Add(remDbgTrig);
				remDbg.CustomPowers.Add(remDbgPower);
				string remDbgSrc = CSharpCodeGen.PowerRemovalSource(remDbg);
				Check("V0.2.162：开了「生成调试日志」时补丁会往游戏日志写一行「谁被移除 / 通知了几个」",
					remDbgSrc.Contains("[模组调试] 状态被移除") && remDbgSrc.Contains("__notified"),
					remDbgSrc.Contains("[模组调试] 状态被移除") ? "写了" : "(没写)");
			}

			// ===== V0.2.168：状态页「某个状态被移除时」（盯任意敌人 + 盯的就是它自己）完全没反应 =====
			// 用户实测报的：「某个状态被移除时，好像无法正常生效」（他在**状态页**上配的、盯敌人身上的状态）。
			// 真因（生成端可直接看出来）：三个「盯某个状态」的时机里，「盯任意敌人」那一支写着
			// `power.Owner != base.Owner` —— 它要求「发生事的那份状态在**别的**生物身上」；
			// 而「盯哪个状态」填的正是**这只状态自己**时，用户要的是「这份状态挂在谁身上，
			// 它自己那份出事就在谁那里触发」（击晕值就贴在敌人身上）——
			// `power.Owner != base.Owner` 把它挡得死死的，生成 / 编译 / 进游戏全都不报错，就是什么都不做。
			// 修法：抽一份共用的 PowerWatchGuard —— 「盯的就是它自己这个状态」时，不管「盯谁」选自己还是
			// 任意敌人，一律按「这份状态自己」生成（power.Owner == base.Owner）；盯**别的**状态时行为不变。
			{
				CharacterProfile remFix = ProfileFactory.Sample();
				remFix.Paths.VanillaProject = Profile.Paths.VanillaProject;
				remFix.Paths.GameDataDir = Profile.Paths.GameDataDir;
				// ① 盯的就是它自己 + 「盯任意敌人」→ 必须按「自己这份」生成（这就是用户报的那条）
				var fixSelf = new CustomPowerSpec { Name = "自检盯自己这份", ClassName = "UiCheckWatchSelf", Enabled = true };
				var fixSelfTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerTarget = "AnyEnemy", PowerId = "UiCheckWatchSelf" };
				fixSelfTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				fixSelf.Triggers.Add(fixSelfTrig);
				remFix.CustomPowers.Add(fixSelf);
				string fixSelfSrc = CustomPowerGen.Source(remFix, fixSelf, remFix.CustomPowers.Count - 1).Replace("\r\n", "\n");
				Check("V0.2.168：状态页「某个状态被移除时」盯任意敌人 + 盯的就是它自己 → 守卫按「自己这份」生成（不再是 power.Owner != base.Owner）",
					fixSelfSrc.Contains("if ((power.Owner == base.Owner) && (power is UiCheckWatchSelf))", StringComparison.Ordinal),
					fixSelfSrc.Contains("power.Owner != base.Owner", StringComparison.Ordinal) ? "(还是被别的生物挡着)" : "按自己这份");
				// ② 「到达 N 层时」同一个形状（V0.2.166 用户报的击晕值那条）也要按自己这份
				var fixReach = new CustomPowerSpec { Name = "自检盯自己到达", ClassName = "UiCheckWatchReach", Enabled = true };
				var fixReachTrig = new PowerTriggerSpec { Kind = "PowerReached", PowerTarget = "AnyEnemy", PowerId = "UiCheckWatchReach", TriggerAmount = 100m };
				fixReachTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				fixReach.Triggers.Add(fixReachTrig);
				remFix.CustomPowers.Add(fixReach);
				string fixReachSrc = CustomPowerGen.Source(remFix, fixReach, remFix.CustomPowers.Count - 1).Replace("\r\n", "\n");
				Check("V0.2.168：「层数到达 N 层时」同形状（盯任意敌人 + 盯自己）也按「自己这份」生成",
					fixReachSrc.Contains("if (power.Owner == base.Owner && power is UiCheckWatchReach && power.Amount >= 100m", StringComparison.Ordinal),
					fixReachSrc.Contains("power.Owner != base.Owner", StringComparison.Ordinal) ? "(还是被别的生物挡着)" : "按自己这份");
				// ③ 盯**别的**状态 + 盯任意敌人：行为不变（仍然是「那份状态挂在别的生物身上」）
				var fixOther = new CustomPowerSpec { Name = "自检盯敌人易伤", ClassName = "UiCheckWatchOther", Enabled = true };
				var fixOtherTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerTarget = "AnyEnemy", PowerId = "VulnerablePower" };
				fixOtherTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				fixOther.Triggers.Add(fixOtherTrig);
				remFix.CustomPowers.Add(fixOther);
				string fixOtherSrc = CustomPowerGen.Source(remFix, fixOther, remFix.CustomPowers.Count - 1).Replace("\r\n", "\n");
				Check("V0.2.168（不回归）：盯**别的**状态 + 盯任意敌人 → 照旧要求那份状态挂在别的生物身上",
					fixOtherSrc.Contains("power.Owner != base.Owner", StringComparison.Ordinal)
					&& fixOtherSrc.Contains("HittableEnemies.Contains(power.Owner)", StringComparison.Ordinal), "没变");
				// ④ 盯自己这个状态 + 「盯谁 = 自己」：和以前一样（只是现在两条路合并成一份守卫）
				var fixOwn = new CustomPowerSpec { Name = "自检盯自己档", ClassName = "UiCheckWatchOwn", Enabled = true };
				var fixOwnTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerTarget = "Self", PowerId = "UiCheckWatchOwn" };
				fixOwnTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				fixOwn.Triggers.Add(fixOwnTrig);
				remFix.CustomPowers.Add(fixOwn);
				string fixOwnSrc = CustomPowerGen.Source(remFix, fixOwn, remFix.CustomPowers.Count - 1).Replace("\r\n", "\n");
				Check("V0.2.168：「盯自己」档（盯的就是自己这个状态）生成的守卫和「盯任意敌人」档一致（同一份 PowerWatchGuard）",
					fixOwnSrc.Contains("if ((power.Owner == base.Owner) && (power is UiCheckWatchOwn))", StringComparison.Ordinal), "一致");
				// ⑤ 换了配置就要重新生成：这条修的是**生成端**，用户得重新「生成」一次（界面提示里说清）
				Check("V0.2.168：修的是生成端（旧工程要重新生成一次才生效）—— 补丁文件照旧只在用到时才生成",
					CSharpCodeGen.UsesPowerRemovedTrigger(remFix) && !CSharpCodeGen.UsesPowerRemovedTrigger(ProfileFactory.Sample()), "对");
			}

			// ===== V0.2.164：「数值公式」铺到遗物 / 药水 / 自定义状态 =====
			// 用户问：「状态和遗物不能使用公式吗」（他填了公式，被校验器拦住）。
			// 真因：公式那套只在**卡牌链**铺好了（卡牌打出前先跑 EmitCardFormulaPrologue 算 __pM / __X…），
			// 遗物 / 药水 / 状态的执行点没有那套前置 —— 但它们**能**用全内联求值
			//（锻造节点图那边一直是这么干的），所以这一版把这三条链接上：
			//   · 遗物 / 药水：Owner 是 Player → __fgPlayer = base.Owner、__fgSelf = base.Owner.Creature；
			//   · 自定义状态：Owner 是 Creature → __fgPlayer = base.Owner.Player、__fgSelf = base.Owner；
			//   · 「指定敌人」来源的参数在这三条链上取**可打的第一个敌人**（和「作用对象 = 单体敌人」同口径）；
			//   · 悬停数字：遗物 / 药水描述里的 {Heal:diff()} 读的是 PreviewValue，而它们没有卡牌那种
			//     「显示前回调」→ 我们自己挂在 ExtraHoverTips 上现算（见 __RefreshFormulaPreview）。
			{
				CharacterProfile fp = ProfileFactory.Sample();
				fp.Paths.VanillaProject = Profile.Paths.VanillaProject;
				fp.Paths.GameDataDir = Profile.Paths.GameDataDir;
				fp.CustomParams.Clear();
				fp.CustomParams.Add(new ParamSpec { Name = "M", Source = ParamSources.MaxHp, Target = ParamTargets.Self });
				fp.CustomParams.Add(new ParamSpec { Name = "A", Source = ParamSources.Power, Target = ParamTargets.ChosenEnemy, PowerId = "VulnerablePower" });
				var fpRelic = new RelicSpec { Name = "自检公式遗物", ClassName = "UiCheckFormulaRelic", Rarity = "Common", Trigger = "PlayerTurnStart" };
				fpRelic.Effects.Add(new EffectSpec { Kind = "Heal", Amount = 3m, TargetSide = "Self", AmountFormula = "M/2" });
				fpRelic.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Enemy", AmountFormula = "A+2" });
				fp.Relics.Add(fpRelic);
				string fpRelicSrc = CSharpCodeGen.RelicSource(fp, fpRelic, fp.Relics.Count - 1);
				Check("V0.2.164：遗物的「数值公式」生成的是**内联**表达式（不依赖卡牌那套前置变量）",
					fpRelicSrc.Contains("CreatureCmd.Heal(base.Owner.Creature, ForgeFormulaRuntime.Div((base.Owner.Creature?.MaxHp ?? 0), (2m)))")
					&& fpRelicSrc.Contains("ForgeFormulaRuntime.PowerAmount(ForgeFormulaRuntime.FirstEnemy(base.Owner), \"VulnerablePower\")"),
					fpRelicSrc.Contains("ForgeFormulaRuntime.Div(") ? "生成了内联表达式" : "(没生成公式)");
				Check("V0.2.164：遗物的悬停数字在取说明时现算（__RefreshFormulaPreview 挂在 ExtraHoverTips 上）",
					fpRelicSrc.Contains("private void __RefreshFormulaPreview()")
					&& fpRelicSrc.Contains("ExtraHoverTips")
					&& fpRelicSrc.Contains("base.DynamicVars[\"Heal\"].PreviewValue ="),
					fpRelicSrc.Contains("__RefreshFormulaPreview") ? "挂上了" : "(没挂)");
				Check("V0.2.164：遗物也写回读标记（「从工程恢复存档」能认回公式）",
					fpRelicSrc.Contains("// CET:AmountFormula=M/2") && fpRelicSrc.Contains("// CET:AmountFormula=A+2"), "写了");
				var fpPotion = new PotionSpec { Name = "自检公式药水", ClassName = "UiCheckFormulaPotion", Rarity = "Common", Usage = "CombatOnly", TargetType = "Self" };
				fpPotion.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self", AmountFormula = "M/4" });
				fp.Potions.Add(fpPotion);
				string fpPotionSrc = CSharpCodeGen.PotionSource(fp, fpPotion, fp.Potions.Count - 1);
				Check("V0.2.164：药水的「数值公式」同样内联 + 悬停现算 + 回读标记",
					fpPotionSrc.Contains("GainBlock(base.Owner.Creature, ForgeFormulaRuntime.Div((base.Owner.Creature?.MaxHp ?? 0), (4m))")
					&& fpPotionSrc.Contains("__RefreshFormulaPreview")
					&& fpPotionSrc.Contains("public override IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> ExtraHoverTips")
					&& fpPotionSrc.Contains("// CET:AmountFormula=M/4"),
					fpPotionSrc.Contains("ForgeFormulaRuntime.Div(") ? "药水也行了" : "(没生成)");
				var fpPower = new CustomPowerSpec { Name = "自检公式状态", ClassName = "UiCheckFormulaPower", Enabled = true };
				var fpTrig = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
				fpTrig.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 3m, TargetSide = "Self", AmountFormula = "M/10" });
				fpPower.Triggers.Add(fpTrig);
				fp.CustomPowers.Add(fpPower);
				string fpPowerSrc = CustomPowerGen.Source(fp, fpPower, fp.CustomPowers.Count - 1);
				Check("V0.2.164：自定义状态的「数值公式」也内联（状态钩子的 Owner 是 Creature，玩家写 base.Owner.Player）",
					fpPowerSrc.Contains("ForgeFormulaRuntime.Div((base.Owner?.MaxHp ?? 0), (10m))")
					&& fpPowerSrc.Contains("// CET:AmountFormula=M/10"), fpPowerSrc.Contains("ForgeFormulaRuntime.Div(") ? "状态也行了" : "(没生成)");
				Check("V0.2.164：状态描述里写的是**公式本身**（状态说明是生成期写死的纯文本，现算不了）",
					PowerTriggers.AutoDescription(fpPower).Contains("M/10"), PowerTriggers.AutoDescription(fpPower));
				Check("V0.2.164：这三条链写了公式 → 会生成 FormulaVars.cs（那 5 种的现算变量类）与 ForgeFormulaRuntime.cs",
					CSharpCodeGen.UsesFormulaVars(fp) && ForgeGraphGen.AnyNonCardFormula(fp),
					$"vars={CSharpCodeGen.UsesFormulaVars(fp)} runtime={ForgeGraphGen.AnyNonCardFormula(fp)}");
				// 校验器：该放行的放行（这 5 种），不该放行的照旧拦住；口径提示要有
				var fpIssues = ProfileValidator.Validate(fp);
				Check("V0.2.164：校验器对遗物 / 药水 / 状态上的这 5 种公式**不再报错**",
					!fpIssues.Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("数值公式")),
					fpIssues.FirstOrDefault((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("数值公式"))?.Message ?? "没有错误");
				Check("V0.2.164：公式里用了「指定敌人」来源的参数时，提示说明取的是「可打的第一个敌人」",
					fpIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("可打的第一个敌人")),
					fpIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("可打的第一个敌人"))?.Message ?? "(没提示)");
				var fpBad = ProfileFactory.Sample();
				fpBad.Paths.VanillaProject = Profile.Paths.VanillaProject;
				fpBad.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var fpBadRelic = new RelicSpec { Name = "自检公式写错", ClassName = "UiCheckFormulaBad", Rarity = "Common", Trigger = "PlayerTurnStart" };
				// ⚠ 公式要写成**运行时**的（Turn 是内置只读量，折不成常数）——
				// 纯数字 / 纯常数公式会被 ProfileFactory 折进固定数值那一栏（V0.2.146），那就不会报错了
				fpBadRelic.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self", AmountFormula = "Turn" });
				fpBad.Relics.Add(fpBadRelic);
				Check("V0.2.164：（对照）不支持的种类（抽牌）写了公式照旧**报错**拦住",
					ProfileValidator.Validate(fpBad).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("不支持「数值公式」")),
					string.Join(" ｜ ", ProfileValidator.Validate(fpBad).Where((ValidationIssue i) => i.Level == "错误")
						.Select((ValidationIssue i) => i.Message.Substring(0, Math.Min(80, i.Message.Length))).Take(2)));
				// 生成 → 回读：三条链的公式都要原样回来
				string fpRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_formula_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					fp.Paths.OutputDir = fpRoot;
					ProfileFactory.Save(fp, Path.Combine(fpRoot, "formula.json"));
					GenerationResult fpGen = ModGenerator.Generate(fp);
					Check("（准备）带公式的遗物 / 药水 / 状态存档能生成工程", fpGen.Success,
						fpGen.Success ? fpRoot
							: (fpGen.Issues.FirstOrDefault((ValidationIssue i) => i.Level == "错误")?.Message
							   ?? string.Join(" ｜ ", fpGen.Log.TakeLast(3))));
					var fpRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(fp));
					var recRelic = fpRec.Profile.Relics.FirstOrDefault((RelicSpec r) => r.ClassName == "UiCheckFormulaRelic");
					var recPotion = fpRec.Profile.Potions.FirstOrDefault((PotionSpec s) => s.ClassName == "UiCheckFormulaPotion");
					var recPower = fpRec.Profile.CustomPowers.FirstOrDefault((CustomPowerSpec c) => c.ClassName == "UiCheckFormulaPower");
					Check("V0.2.164：从工程恢复 —— 遗物的两条公式原样回来",
						recRelic is not null && recRelic.Effects.Count == 2
						&& recRelic.Effects[0].AmountFormula == "M/2" && recRelic.Effects[1].AmountFormula == "A+2",
						recRelic is null ? "(没回读出来)" : string.Join("、", recRelic.Effects.Select((EffectSpec x) => x.AmountFormula)));
					Check("V0.2.164：从工程恢复 —— 药水的公式原样回来",
						recPotion is not null && recPotion.Effects.Any((EffectSpec x) => x.AmountFormula == "M/4"),
						recPotion is null ? "(没回读出来)" : string.Join("、", recPotion.Effects.Select((EffectSpec x) => x.AmountFormula)));
					Check("V0.2.164：从工程恢复 —— 自定义状态触发器里的公式原样回来",
						recPower is not null && recPower.Triggers.Any((PowerTriggerSpec t) => t.Effects.Any((EffectSpec x) => x.AmountFormula == "M/10")),
						recPower is null ? "(没回读出来)" : string.Join("、", recPower.Triggers.SelectMany((PowerTriggerSpec t) => t.Effects).Select((EffectSpec x) => x.AmountFormula)));
				}
				finally
				{
					try { if (Directory.Exists(fpRoot)) Directory.Delete(fpRoot, recursive: true); } catch { }
				}
			}

			// ===== V0.2.165：卡牌页 → 先古页 切换后卡面预览要跟着换（用户实测） =====
			// 用户原话：「点卡牌页查看卡牌，然后再点先古页查看先古牌，先古牌的卡面会消失，
			// 并且比例变成卡牌页的比例而不是竖图的比例」。
			// 真因：三个卡牌列表页共用同一套卡面预览属性，而它们取「当前这张卡」的判据是
			// `CardUiSelection ?? SpecialCardOf()` —— 卡牌页那个镜像的语义是「点空槽时**保持上一张**」
			// （见 SlotRowMirror.UiSelection），而三栏互斥时只做了 `CardList.SelectedItem = null`：
			// 镜像的 UiSelection **不会**跟着清（正是「点空槽保持上一张」那条规则）⇒ 切到先古页之后
			// 预览拿到的还是卡牌页那张（横图 1000×760、卡面 key 也是它）⇒ 先古卡的图找不到（看起来「消失」）、
			// 预览框还是横的比例。
			{
				CardSpec? keepCardSel = CardUiSelection;
				CardSpec? keepAncientSel = AncientUiSelection;
				var ratioCard = new CardSpec { Name = "自检比例卡", ClassName = "UiCheckRatioCard", CardType = "Skill", Rarity = "Common", Cost = 1 };
				var ratioAncient = new CardSpec { Name = "自检比例先古", ClassName = "UiCheckRatioAncient", CardType = "Skill", Rarity = "Ancient", Cost = 1 };
				try
				{
					Profile.Cards.Add(ratioCard);
					Profile.AncientCards.Add(ratioAncient);
					SyncDetail();
					UpdateLayout();
					SelectTabRoot("卡牌");
					CardList.SelectedItem = ratioCard;   // 等价于用户在卡牌页点了这张卡
					UpdateLayout();
					Check("V0.2.165：（准备）卡牌页选中普通卡 → 预览框是横图 1000×760、按比例放",
						ReferenceEquals(CardUiSelection, ratioCard) && CardPortraitFrameWidth == 1000
						&& CardPortraitFrameHeight == 760 && CardPortraitPreviewStretch == Stretch.Uniform,
						$"{CardUiSelection?.Name ?? "(null)"} / {CardPortraitFrameWidth}×{CardPortraitFrameHeight} / {CardPortraitPreviewStretch}");
					// 用户的操作：切到「诅咒 / 先古 / 状态」页，再点一张先古卡
					SelectTabRoot("诅咒 / 先古 / 状态");
					AncientCardList.SelectedItem = ratioAncient;
					UpdateLayout();
					Check("V0.2.165：切到先古页并选中先古卡后，预览框换成**竖图** 606×852（不再是卡牌页那套横的比例）",
						CardPortraitFrameWidth == 606 && CardPortraitFrameHeight == 852
						&& CardPortraitPreviewStretch == Stretch.Fill,
						$"当前预览卡={ActivePortraitCard()?.Name ?? "(null)"} / {CardPortraitFrameWidth}×{CardPortraitFrameHeight} / {CardPortraitPreviewStretch}");
					Check("V0.2.165：卡面预览取的是**先古卡**那张（取错就会「卡面消失」——先古卡面存在另一个 key 上）",
						ReferenceEquals(ActivePortraitCard(), ratioAncient),
						ActivePortraitCard()?.Name ?? "(null)");
					// 反向：先古页 → 卡牌页也要换回来（同一类 bug 的另一半）
					SelectTabRoot("卡牌");
					CardList.SelectedItem = ratioCard;
					UpdateLayout();
					Check("V0.2.165：从先古页切回卡牌页选卡 → 预览框换回横图 1000×760",
						CardPortraitFrameWidth == 1000 && CardPortraitFrameHeight == 760 && CardPortraitPreviewStretch == Stretch.Uniform
						&& ReferenceEquals(ActivePortraitCard(), ratioCard),
						$"当前预览卡={ActivePortraitCard()?.Name ?? "(null)"} / {CardPortraitFrameWidth}×{CardPortraitFrameHeight}");
				}
				finally
				{
					Profile.Cards.Remove(ratioCard);
					Profile.AncientCards.Remove(ratioAncient);
					SyncDetail();
					_curseMirror.ClearSelection();
					_ancientMirror.ClearSelection();
					StatusCardList.SelectedItem = null;
					if (keepCardSel is not null && Profile.Cards.Contains(keepCardSel)) CardList.SelectedItem = keepCardSel;
					else if (keepAncientSel is not null && Profile.AncientCards.Contains(keepAncientSel)) AncientCardList.SelectedItem = keepAncientSel;
					SyncDetail();
					UpdateLayout();
				}
			}

			// ===== V0.2.166：状态里「自己涨到 N 就击晕」这类配置的两个坑（用户实测） =====
			// 用户报：「晕眩值达到 100 后不会击晕敌人」（他造了一个贴在敌人身上的减益「击晕值」，
			// 触发时机「某个状态层数到达 100 层时」、盯「任意敌人」的**它自己**，效果 = 击晕「指定敌人」）。
			// 两个坑：
			//   ① 盯「任意敌人」+ 盯的那个状态就是这条时机所在的状态自己 ⇒ 守卫要求
			//      `power.Owner != base.Owner`（被盯的那份在**别的**生物身上）⇒ 自己涨到 100 那一下永远不触发；
			//   ② 「击晕」的「作用对象 = 指定敌人」在状态链上取的是**玩家视角敌方那一侧里第一个可打的敌人**，
			//      不一定是身上带着这个状态的那只。
			// 修法：① / ② 各加一条校验（警告 / 提示），并修掉「作用对象 = 自己」在状态链上生成
			// `base.Owner.Creature` 的 CS1061（Creature 上没有 Creature 属性）。
			{
				CharacterProfile sp = ProfileFactory.Sample();
				sp.Paths.VanillaProject = Profile.Paths.VanillaProject;
				sp.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var spPower = new CustomPowerSpec { Name = "自检击晕值", ClassName = "UiCheckStunPower", Type = "Debuff", Enabled = true };
				var spTrig = new PowerTriggerSpec
				{
					Kind = "PowerReached", PowerId = "UiCheckStunPower", PowerTarget = "AnyEnemy", TriggerAmount = 100m,
				};
				spTrig.Effects.Add(new EffectSpec { Kind = "Stun", Amount = 1m, TargetSide = "Enemy" });
				spPower.Triggers.Add(spTrig);
				sp.CustomPowers.Add(spPower);
				var spIssues = ProfileValidator.Validate(sp);
				// V0.2.168 把这条**改口径**了（见上面 26098 那段 PowerWatchGuard）：「盯的就是它自己这个状态」时
				// 不再要求「被盯的那份在别的生物身上」，而是按「这份状态自己」生成 —— 于是校验器那条
				// 「不会触发」的**警告**也改成了**提示**。这条断言跟着改成新口径（老文案已经作废，
				// 留着它会变成一条永远 FAIL 的假红）。
				Check("V0.2.166/168：盯「任意敌人」+ 盯的就是这个状态自己 → 提示说清「按**这份状态自己**生成」",
					spIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("这份状态自己")),
					spIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("这份状态自己"))?.Message ?? "(没报)");
				Check("V0.2.166：减益里的「击晕 + 指定敌人」→ 提示说清「取的是第一个可打的敌人、可能晕错」",
					spIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("不一定是身上带着这个状态的那只")),
					spIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("不一定是身上带着这个状态的那只"))?.Message ?? "(没提示)");
				// 生成端：盯自己 + 作用对象自己 → 守卫 == base.Owner、击晕 base.Owner（不是 base.Owner.Creature）
				var okPower = new CustomPowerSpec { Name = "自检击晕值对", ClassName = "UiCheckStunOk", Type = "Debuff", Enabled = true };
				var okTrig = new PowerTriggerSpec { Kind = "PowerReached", PowerId = "UiCheckStunOk", PowerTarget = "Self", TriggerAmount = 100m };
				okTrig.Effects.Add(new EffectSpec { Kind = "Stun", Amount = 1m, TargetSide = "Self" });
				okPower.Triggers.Add(okTrig);
				CharacterProfile okProfile = ProfileFactory.Sample();
				okProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				okProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				okProfile.CustomPowers.Add(okPower);
				string okSrc = CustomPowerGen.Source(okProfile, okPower, okProfile.CustomPowers.Count - 1);
				Check("V0.2.166：盯「自己」时守卫是 `power.Owner == base.Owner`（自己涨到 N 那一下就触发）",
					okSrc.Contains("if (power.Owner == base.Owner && power is UiCheckStunOk && power.Amount >= 100m"),
					okSrc.Contains("power.Owner == base.Owner") ? "守卫对" : "(守卫还是 != base.Owner)");
				Check("V0.2.166：状态链上「击晕 + 作用对象 = 自己」生成 `CreatureCmd.Stun(base.Owner)`（以前是 base.Owner.Creature → CS1061）",
					okSrc.Contains("await CreatureCmd.Stun(base.Owner);") && !okSrc.Contains("CreatureCmd.Stun(base.Owner.Creature)"),
					okSrc.Contains("await CreatureCmd.Stun(base.Owner);") ? "对" : "(还是 base.Owner.Creature)");
				// 对照：卡牌链的「对自己」仍是 base.Owner.Creature（那条链的 Owner 是 Player）——红线：逐字不变
				var stunCard = new CardSpec { Name = "自检自晕牌", ClassName = "UiCheckStunCard", CardType = "Skill", Rarity = "Common", Cost = 1 };
				stunCard.Effects.Add(new EffectSpec { Kind = "Stun", Amount = 1m, TargetSide = "Self" });
				CharacterProfile cardProfile = ProfileFactory.Sample();
				cardProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				cardProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				cardProfile.Cards.Add(stunCard);
				Check("V0.2.166：（对照）卡牌 / 遗物链的「击晕自己」照旧是 `base.Owner.Creature`（那两条链的 Owner 是 Player）",
					CSharpCodeGen.CardSource(cardProfile, stunCard, cardProfile.Cards.Count - 1)
						.Contains("await CreatureCmd.Stun(base.Owner.Creature);"),
					"卡牌链照旧");
			}

			// ===== V0.2.167：锻造节点图里的「生成 / 变化出来的卡的附加处理 / 加关键词 / 复制份数」 =====
			// 用户截图报的：「生成被拦住了」—— 卡牌 Da Capo / 第一~四乐章（升级后）用了「生成卡牌」的
			// 附加处理（直接升级 / 免费 / 仅本回合免费 / 仅本回合升级），而节点图那一版**读不到**这几栏
			// （它们只存在新编辑器那份 EffectSpec 上，ForgeEffectBridge.MirrorToFields 不回写），所以只能报错拦住。
			// 现在生成端直接读 spec（同一条链复用 CSharpCodeGen.EmitSpawnModifiers / EmitTempUpgradePowerApply）。
			{
				CharacterProfile gp = ProfileFactory.Sample();
				gp.Paths.VanillaProject = Profile.Paths.VanillaProject;
				gp.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec gpCard = MakeGraphModProbeCard("自检图附加处理", "UiCheckGraphMod", "SevenSlash");
				gp.Cards.Add(gpCard);
				string gpSrc = CSharpCodeGen.CardSource(gp, gpCard, gp.Cards.Count - 1);
				Check("V0.2.167：节点图里「生成卡牌 + 直接升级 / 本回合免费 / 加关键词」都生成出来了",
					gpSrc.Contains("CardCmd.Upgrade(__gen);")
					&& gpSrc.Contains("__gen.SetToFreeThisTurn();")
					&& gpSrc.Contains("__gen.AddKeyword(CardKeyword.Retain);")
					&& gpSrc.Contains("await CardPileCmd.AddGeneratedCardToCombat(__gen, PileType.Hand, __fgPlayer);"),
					gpSrc.Contains("CardCmd.Upgrade(__gen);") ? "生成了" : "(没生成)");
				Check("V0.2.167：这几项**不再**被「配置检查」当成错误拦住（以前「生成被拦住了」就是它们）",
					!ForgeGraphGen.Issues(gpCard.ForgeGraph, gp, "Card", null)
						.Any((i) => (i.Level == "错误" && i.Message.Contains("附加处理"))
							|| (i.Level == "错误" && i.Message.Contains("加上关键词"))),
					string.Join(" ｜ ", ForgeGraphGen.Issues(gpCard.ForgeGraph, gp, "Card", null)
						.Select((i) => i.Level + ":" + i.Message.Substring(0, Math.Min(40, i.Message.Length)))));
				// 仅本回合升级：要挂生成的临时升级 Power，而且那个文件必须**会被生成**（否则 CS0246）
				CharacterProfile gp2 = ProfileFactory.Sample();
				gp2.Paths.VanillaProject = Profile.Paths.VanillaProject;
				gp2.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec gpCard2 = MakeGraphModProbeCard("自检图本回合升级", "UiCheckGraphTemp", "SevenSlash", tempUpgradeThisTurn: true);
				gp2.Cards.Add(gpCard2);
				string gpSrc2 = CSharpCodeGen.CardSource(gp2, gpCard2, gp2.Cards.Count - 1);
				Check("V0.2.167：节点图里的「仅本回合升级」挂上临时升级状态并 Track",
					gpSrc2.Contains("PowerCmd.Apply<") && gpSrc2.Contains(".Track(__gen)"),
					gpSrc2.Contains(".Track(__gen)") ? "挂上了" : "(没挂)");
				Check("V0.2.167：图里用到「仅本回合升级」→ 会生成 TempUpgradePower.cs（不然 CS0246）",
					CSharpCodeGen.UsesTempUpgrade(gp2), "会生成");
				// 复制份数 + 附加处理
				CharacterProfile gp3 = ProfileFactory.Sample();
				gp3.Paths.VanillaProject = Profile.Paths.VanillaProject;
				gp3.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec gpCard3 = MakeGraphModProbeCard("自检图复制份数", "UiCheckGraphCopy", "SevenGuard", copy: true, copies: 3);
				gp3.Cards.Add(gpCard3);
				string gpSrc3 = CSharpCodeGen.CardSource(gp3, gpCard3, gp3.Cards.Count - 1);
				Check("V0.2.167：节点图里「复制卡牌 + 复制的份数 3 + 附加处理」按份数循环并套上附加处理",
					gpSrc3.Contains("for (int __fgCopy = 0; __fgCopy < 3; __fgCopy++)")
					&& gpSrc3.Contains("CardModel __clone = ") && gpSrc3.Contains("CardCmd.Upgrade(__clone);"),
					gpSrc3.Contains("__fgCopy < 3") ? "按份数复制" : "(没按份数)");
				// 对照（红线①）：没勾附加处理的老图，生成文本里**不许**出现这些新语句
				var plainNode = new ForgeNodeSpec { Kind = "Effect" };
				plainNode.SetField("Effect", "GenerateCard");
				plainNode.SetField("Amount", "2");
				plainNode.SetField("SpawnCardId", "SevenSlash");
				plainNode.SetField("SpawnTo", "Hand");
				CharacterProfile gp4 = ProfileFactory.Sample();
				gp4.Paths.VanillaProject = Profile.Paths.VanillaProject;
				gp4.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec gpCard4 = MakeGraphModProbeCard("自检图老样子", "UiCheckGraphPlain", "SevenSlash", replaceEffect: plainNode);
				gp4.Cards.Add(gpCard4);
				string gpSrc4 = CSharpCodeGen.CardSource(gp4, gpCard4, gp4.Cards.Count - 1);
				Check("V0.2.167：（对照）没勾附加处理的老图照旧是那一句「CreateCard + 放进牌堆」（红①：老图逐字不变）",
					gpSrc4.Contains("CardModel __gen = base.CombatState.CreateCard<SevenSlash>(__fgPlayer); await CardPileCmd.AddGeneratedCardToCombat(__gen, PileType.Hand, __fgPlayer);")
					&& !gpSrc4.Contains("CardCmd.Upgrade(__gen);"),
					gpSrc4.Contains("CardCmd.Upgrade(__gen);") ? "(多写了附加处理)" : "老样子");
			}

			// ===== V0.2.152：「某个状态层数到达 N 层时」的 N =====
			// 用户报的两条：「为什么我状态层数达到了，却没生成卡牌」「自定义状态的某个层数到达 N 时，
			// 在游戏中怎么也是 N，而不是填的数」。真因：`TriggerSupportsAmount` 漏了 `PowerReached`
			// → **界面上根本没有 N 输入框** → N 永远停在默认值 1（生成出来是「跨过 1 层那一下」，
			// 用户想要的那一层永远不触发），状态描述里也只能印一个字母 N。
			{
				Check("V0.2.152：「到达 N 层」这一档在界面上有 N 输入框（自定义状态 / 遗物两边都要有）",
					CSharpCodeGen.TriggerSupportsAmount("PowerReached")
					&& new PowerTriggerSpec { Kind = "PowerReached" }.ShowTriggerAmountField
					&& new RelicTriggerSpec { Kind = "PowerReached" }.ShowAmountField,
					$"supports={CSharpCodeGen.TriggerSupportsAmount("PowerReached")} "
					+ $"power={new PowerTriggerSpec { Kind = "PowerReached" }.ShowTriggerAmountField} "
					+ $"relic={new RelicTriggerSpec { Kind = "PowerReached" }.ShowAmountField}");
				Check("V0.2.152：N 那一栏的标题是「到达 N 层」而不是「每累计几次触发」",
					new PowerTriggerSpec { Kind = "PowerReached" }.TriggerAmountLabel.Contains("N 层")
					&& new RelicTriggerSpec { Kind = "PowerReached" }.AmountLabel.Contains("N 层"),
					new PowerTriggerSpec { Kind = "PowerReached" }.TriggerAmountLabel);
				Check("V0.2.152：N 那一栏底下的说明写清「层数跨过 N 那一下才触发」+ 现在填的是几层",
					new PowerTriggerSpec { Kind = "PowerReached", TriggerAmount = 3m }.TriggerSpendHint.Contains("跨过")
					&& new PowerTriggerSpec { Kind = "PowerReached", TriggerAmount = 3m }.TriggerSpendHint.Contains("3")
					&& new RelicTriggerSpec { Kind = "PowerReached", Amount = 3m }.SpendHint.Contains("跨过"),
					"两侧都写清了");

				var reachTrigger = new PowerTriggerSpec { Kind = "PowerReached", PowerTarget = "Self", TriggerAmount = 5m };
				reachTrigger.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv" });
				string reachText = reachTrigger.Summary;
				Check("V0.2.152：触发时机那一行 / 游戏里的状态描述写的是填的层数（5 层）而不是字母 N",
					reachText.Contains("5 层") && !reachText.Contains("N 层"), reachText);
				Check("V0.2.152：那一行也会写清盯的是哪个状态（和「层数变化后」一个口径）",
					reachText.Contains("盯："), reachText);

				CharacterProfile reachProfile = ProfileFactory.Sample();
				reachProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				reachProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var reachSelfPower = new CustomPowerSpec { Name = "自检到达", ClassName = "UiCheckReachPower", Enabled = true };
				var reachSelfTrigger = new PowerTriggerSpec
				{
					Kind = "PowerReached", PowerTarget = "Self", PowerId = "UiCheckReachPower", TriggerAmount = 5m,
				};
				reachSelfTrigger.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv" });
				reachSelfPower.Triggers.Add(reachSelfTrigger);
				var reachAnyPower = new CustomPowerSpec { Name = "自检任意", ClassName = "UiCheckReachAny", Enabled = true };
				var reachAnyTrigger = new PowerTriggerSpec { Kind = "PowerReached", PowerTarget = "Self", TriggerAmount = 5m };
				reachAnyTrigger.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv" });
				reachAnyPower.Triggers.Add(reachAnyTrigger);
				reachProfile.CustomPowers.Clear();
				reachProfile.CustomPowers.Add(reachSelfPower);
				reachProfile.CustomPowers.Add(reachAnyPower);

				string reachSelfSrc = CustomPowerGen.Source(reachProfile, reachSelfPower, 0);
				string selfGuard = reachSelfSrc.Split('\n')
					.FirstOrDefault((string l) => l.Contains("power.Amount >=", StringComparison.Ordinal)) ?? "";
				Check("V0.2.152：生成出的守卫用的是填的 N（>= 5m 且 - amount < 5m）",
					selfGuard.Contains("power.Amount >= 5m") && selfGuard.Contains("- amount < 5m"), selfGuard.Trim());
				Check("V0.2.152：盯自己这只状态时守卫不再写 power != this（以前这样写 → 自己永远触发不了）",
					selfGuard.Length > 0 && !selfGuard.Contains("power != this"), selfGuard.Trim());
				Check("V0.2.152：生成的那行守卫和回读正则对得上（N 能认回来）",
					System.Text.RegularExpressions.Regex.IsMatch(reachSelfSrc, @"power\.Amount >= ([\d.]+)m && power\.Amount - amount <"),
					"对得上");

				string reachAnySrc = CustomPowerGen.Source(reachProfile, reachAnyPower, 1);
				string anyGuard = reachAnySrc.Split('\n')
					.FirstOrDefault((string l) => l.Contains("power.Amount >=", StringComparison.Ordinal)) ?? "";
				Check("V0.2.152：没盯自己（留空 = 任意状态）时照旧排除自己（免得自己给自己叠层 → 自己触发自己）",
					anyGuard.Contains("power != this"), anyGuard.Trim());

				// 自检不留痕：把样例里那两只状态清掉（只改了内存里的副本，没动用户存档）
				reachProfile.CustomPowers.Clear();
			}

			// ===== V0.2.153：自动英文类名改号时，「按类名存的引用」必须跟着搬 =====
			// 用户报：「为什么我点击构建后，目标卡里的东西会变」。
			// 真因：自动类名是**按列表行号**算的（<角色>Card3 = 普通卡列表第 3 张），而「目标卡」存的是
			// **类名字符串** —— 用户先选了目标卡、之后又增删 / 拖动过卡牌，改号那一刻引用没跟着搬，
			// 于是那个字符串落到了**同名的另一张卡**身上（构建时才 Freeze 类名，那时已经搬不动了）。
			{
				CharacterProfile refProfile = ProfileFactory.Sample();
				refProfile.Cards.Clear();
				for (int i = 1; i <= 3; i++)
					refProfile.Cards.Add(new CardSpec { Name = "挪卡" + i, CardType = "Attack", Rarity = "Common", Cost = 1 });
				var refNaming = Naming.From(refProfile);
				string beforeThird = refNaming.CardClassName(refProfile, refProfile.Cards[2]);
				var refFx = new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = beforeThird };
				refProfile.Cards[0].Effects.Add(refFx);
				// 界面载入 / 刷新候选表那一拍（把每张卡的 LastAutoOrdinal 写实，= 它当时的行号）
				NameStabilizer.RenumberCardNames(refProfile);
				// 用户在中间插了一张卡
				refProfile.Cards.Insert(1, new CardSpec { Name = "插进来的", CardType = "Skill", Rarity = "Common", Cost = 1 });
				// 界面刷新候选表那一拍 → 引用必须跟着搬到同一个行号上
				NameStabilizer.RenumberCardNames(refProfile);
				string afterThird = refNaming.CardClassName(refProfile, refProfile.Cards[3]);
				Check("V0.2.153：「目标卡」引用跟着自动编号一起搬（插一张卡之后仍指着同一张，不会落到别的卡身上）",
					refFx.SpawnCardId == afterThird && afterThird != beforeThird,
					$"现在={refFx.SpawnCardId} / 期望={afterThird}（插卡前是 {beforeThird}）");
				Check("V0.2.153：（反向）老引用字符串 `" + beforeThird + "` 现在已经属于**另一张卡**了 —— 这就是不搬会出现「目标卡变了」的原因",
					refNaming.CardClassName(refProfile, refProfile.Cards[2]) == beforeThird
					&& refFx.SpawnCardId != beforeThird,
					$"老名字现在的主人=「{refProfile.Cards[2].Name}」");

				// ② 构建那条路（Stabilize → Freeze）也要先搬再冻：模拟「用户中间没刷新过界面」的情况
				CharacterProfile stabProfile = ProfileFactory.Sample();
				stabProfile.Cards.Clear();
				for (int i = 1; i <= 3; i++)
					stabProfile.Cards.Add(new CardSpec { Name = "冻卡" + i, CardType = "Attack", Rarity = "Common", Cost = 1 });
				var stabNaming = Naming.From(stabProfile);
				var stabFx = new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = stabNaming.CardClassName(stabProfile, stabProfile.Cards[2]) };
				stabProfile.Cards[0].Effects.Add(stabFx);
				NameStabilizer.RenumberCardNames(stabProfile);          // 上一次刷新候选表
				stabProfile.Cards.Insert(1, new CardSpec { Name = "冻进来的", CardType = "Skill", Rarity = "Common", Cost = 1 });
				NameStabilizer.Stabilize(stabProfile, null);             // = 点「构建」时走的那一步
				string stabExpect = stabNaming.CardClassName(stabProfile, stabProfile.Cards[3]);
				Check("V0.2.153：构建时（Stabilize → 冻类名）也先把引用搬一次 —— 冻出来的类名和引用对得上",
					stabFx.SpawnCardId == stabExpect && stabProfile.Cards[3].ClassName == stabExpect,
					$"引用={stabFx.SpawnCardId} / 第 4 张的类名={stabProfile.Cards[3].ClassName}");
			}

			// ===== V0.2.154：新增效果种类「播放音效」（用户要求「能不能加一个播放音频的效果在效果种类里」）=====
			{
				Check("V0.2.154：效果种类里有「播放音效」（数值那一栏 = 音量%，范围 0~200）",
					EffectCatalog.FindKind("PlaySfx").Kind == "PlaySfx"
					&& EffectCatalog.FindKind("PlaySfx").Max == 200
					&& new EffectSpec { Kind = "PlaySfx" }.IsPlaySfx,
					EffectCatalog.FindKind("PlaySfx").Display);
				Check("V0.2.154：候选表里都是本体真实用过的 event:/… 路径（音效 + 音乐）",
					EffectCatalog.SfxChoices.Count >= 40
					&& EffectCatalog.SfxChoices.All((SfxChoiceOption c) => c.Id.StartsWith("event:/", StringComparison.Ordinal))
					&& EffectCatalog.SfxChoices.Any((SfxChoiceOption c) => c.Id.StartsWith("event:/sfx/", StringComparison.Ordinal))
					&& EffectCatalog.SfxChoices.Any((SfxChoiceOption c) => c.Id.StartsWith("event:/music/", StringComparison.Ordinal)),
					$"{EffectCatalog.SfxChoices.Count} 条候选");
				Check("V0.2.154：数值留空 / 0 = 100%（不是「这条效果不生效」—— 它是唯一一个 0 有意义的种类）",
					new EffectSpec { Kind = "PlaySfx" }.SfxVolumePercent == 100m
					&& new EffectSpec { Kind = "PlaySfx", Amount = 150m }.SfxVolumePercent == 150m
					&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "PlaySfx", Sfx = "event:/sfx/block_gain" }),
					"0 → 100%");

				CharacterProfile sfxProfile = ProfileFactory.Sample();
				sfxProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				sfxProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				sfxProfile.Cards.Clear();
				sfxProfile.Relics.Clear();
				sfxProfile.Potions.Clear();
				sfxProfile.CustomPowers.Clear();
				var sfxCard = new CardSpec { Name = "自检音效", ClassName = "UiCheckSfxCard", CardType = "Skill", Rarity = "Common", Cost = 1 };
				sfxCard.Effects.Add(new EffectSpec { Kind = "PlaySfx", Sfx = "event:/sfx/block_gain" });
				sfxCard.Effects.Add(new EffectSpec { Kind = "PlaySfx", Sfx = "event:/sfx/heal", Amount = 150m });
				sfxCard.Effects.Add(new EffectSpec { Kind = "PlaySfx" });
				sfxProfile.Cards.Add(sfxCard);
				string sfxCardSrc = CSharpCodeGen.CardSource(sfxProfile, sfxCard, 0);
				Check("V0.2.154：卡牌上生成的是本体那一句 SfxCmd.Play(路径, 音量)（默认音量写 1f、150% 写 1.5f）",
					sfxCardSrc.Contains("SfxCmd.Play(\"event:/sfx/block_gain\", 1f)")
					&& sfxCardSrc.Contains("SfxCmd.Play(\"event:/sfx/heal\", 1.5f)"),
					(sfxCardSrc.Split('\n').FirstOrDefault((string l) => l.Contains("SfxCmd.Play(", StringComparison.Ordinal)) ?? "(没生成)").Trim());
				Check("V0.2.154：没选音效时只写一句注释、不生成半截代码",
					sfxCardSrc.Contains("没选音效"), "写了注释");
				Check("V0.2.154：卡面描述写「播放音效：中文名」（默认音量不写音量，非默认写出来）",
					LocalizationGen.CardsJson(sfxProfile).Contains("播放音效：获得格挡")
					&& LocalizationGen.CardsJson(sfxProfile).Contains("播放音效：回复生命（音量 150%）"),
					"描述对");

				var sfxPower = new CustomPowerSpec { Name = "自检音效状态", ClassName = "UiCheckSfxPower", Enabled = true };
				var sfxTrigger = new PowerTriggerSpec { Kind = "TurnStart" };
				sfxTrigger.Effects.Add(new EffectSpec { Kind = "PlaySfx", Sfx = "event:/sfx/buff", Amount = 50m });
				sfxPower.Triggers.Add(sfxTrigger);
				sfxProfile.CustomPowers.Add(sfxPower);
				Check("V0.2.154：自定义状态的触发时机里也能放（SfxCmd.Play(\"event:/sfx/buff\", 0.5f)）",
					CustomPowerGen.Source(sfxProfile, sfxPower, 0).Contains("SfxCmd.Play(\"event:/sfx/buff\", 0.5f)"), "生成了");
				Check("V0.2.154：状态描述里写的是音效名而不是 Kind 原文",
					PowerTriggers.AutoDescription(sfxPower).Contains("播放音效：获得增益"), PowerTriggers.AutoDescription(sfxPower));

				var sfxRelic = new RelicSpec { Name = "自检音效遗物", ClassName = "UiCheckSfxRelic", Rarity = "Common", Trigger = "CombatStart" };
				sfxRelic.Effects.Add(new EffectSpec { Kind = "PlaySfx", Sfx = "event:/sfx/ui/relic_activate_general" });
				sfxProfile.Relics.Add(sfxRelic);
				Check("V0.2.154：遗物上也能放（不需要 choiceContext）",
					CSharpCodeGen.RelicSource(sfxProfile, sfxRelic, 0).Contains("SfxCmd.Play(\"event:/sfx/ui/relic_activate_general\", 1f)"),
					"生成了");
				var sfxPotion = new PotionSpec { Name = "自检音效药水", ClassName = "UiCheckSfxPotion", Rarity = "Common", Usage = "CombatOnly", TargetType = "AllEnemies" };
				sfxPotion.Effects.Add(new EffectSpec { Kind = "PlaySfx", Sfx = "event:/sfx/ui/pause_open" });
				sfxProfile.Potions.Add(sfxPotion);
				Check("V0.2.154：药水上也能放",
					CSharpCodeGen.PotionSource(sfxProfile, sfxPotion, 0).Contains("SfxCmd.Play(\"event:/sfx/ui/pause_open\", 1f)"),
					"生成了");

				// 校验器：没选音效 = 错误；不像事件路径 = 错误；不在候选表里 = 提示（不拦）
				CharacterProfile SfxProbeProfile(string path)
				{
					CharacterProfile p2 = ProfileFactory.Sample();
					p2.Paths.VanillaProject = Profile.Paths.VanillaProject;
					p2.Paths.GameDataDir = Profile.Paths.GameDataDir;
					p2.Cards.Clear();
					var c2 = new CardSpec { Name = "自检音效校验", ClassName = "UiCheckSfxValidate", CardType = "Skill", Rarity = "Common", Cost = 1 };
					c2.Effects.Add(new EffectSpec { Kind = "PlaySfx", Sfx = path });
					p2.Cards.Add(c2);
					return p2;
				}
				Check("V0.2.154：校验器拦「没选音效」和「不像事件路径」，「不在候选表里」只给提示不拦",
					ProfileValidator.Validate(SfxProbeProfile("")).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("还没选音效"))
					&& ProfileValidator.Validate(SfxProbeProfile("block_gain")).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("event:/"))
					&& ProfileValidator.Validate(SfxProbeProfile("event:/sfx/没这个")).Any((ValidationIssue i) => i.Level == "提示"),
					"三条都对");

				// 界面：那一行的显隐真的绑在 IsPlaySfx 上
				Check("V0.2.154：（界面）「音效」那一行的显隐绑在 IsPlaySfx 上",
					CollectBoundPaths(SelectTabRoot("卡牌")).Contains("IsPlaySfx"), "在");
			}

			// ===== V0.2.155：上传自己的音频文件 + 「播放音频文件（我上传的）」效果 =====
			{
				Check("V0.2.155：效果种类里有「播放音频文件（我上传的）」（数值那一栏 = 音量%）",
					EffectCatalog.FindKind("PlaySoundFile").Kind == "PlaySoundFile"
					&& new EffectSpec { Kind = "PlaySoundFile" }.IsPlaySoundFile
					&& new EffectSpec { Kind = "PlaySoundFile" }.SfxVolumePercent == 100m,
					EffectCatalog.FindKind("PlaySoundFile").Display);

				CharacterProfile auProfile = ProfileFactory.Sample();
				auProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				auProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				// ⚠ 卡牌**不能清空**：奖励池至少要 3 张可用卡，清空了生成会直接失败（准备那一步会红）
				auProfile.Relics.Clear();
				auProfile.Potions.Clear();
				auProfile.CustomPowers.Clear();
				auProfile.AudioAssets.Clear();

				// 造一个真的存在的音频文件（内容无所谓：自检只验「复制进工程」这一步，不真的解码播放）
				string auDir = Path.Combine(Path.GetTempPath(), "forge_uicheck_audio_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				Directory.CreateDirectory(auDir);
				string auFile = Path.Combine(auDir, "voice_probe.ogg");
				File.WriteAllBytes(auFile, new byte[] { 0x4F, 0x67, 0x67, 0x53, 0, 2, 0, 0 });   // "OggS" 开头
				auProfile.AudioAssets.Add(new AudioAssetSpec { Name = "自检语音", File = auFile });
				string auKey = auProfile.AudioAssets[0].Key;
				Check("V0.2.155：上传的音频 → 生成用的文件名 Key（名字 + 原扩展名）",
					auKey == "自检语音.ogg", auKey);

				var auCard = new CardSpec { Name = "自检音频", ClassName = "UiCheckAudioCard", CardType = "Skill", Rarity = "Common", Cost = 1 };
				auCard.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = auKey, Amount = 80m });
				auProfile.Cards.Add(auCard);
				string auSrc = CSharpCodeGen.CardSource(auProfile, auCard, 0);
				Check("V0.2.155：卡牌上生成的是 Godot 播放器那一段（GD.Load + 挂场景根 + 放完回收 + VolumeDb 按音量）",
					auSrc.Contains("new AudioStreamPlayer()")
					&& auSrc.Contains($"GD.Load<AudioStream>(\"res://audio/{auKey}\")")
					&& auSrc.Contains("((SceneTree)Engine.GetMainLoop()).Root.AddChild(")
					&& auSrc.Contains(".Finished += ")
					&& auSrc.Contains(".VolumeDb = Mathf.LinearToDb(0.8f)")
					&& auSrc.Contains(".Play();"),
					(auSrc.Split('\n').FirstOrDefault((string l) => l.Contains("AudioStreamPlayer()", StringComparison.Ordinal)) ?? "(没生成)").Trim());
				Check("V0.2.155：没选音频时只写一句注释、不生成半截代码",
					AudioCardSource(auProfile, "UiCheckAudioEmpty", "").Contains("没选音频"), "写了注释");
				Check("V0.2.155：卡面描述写「播放音频：<你给它起的名字>（音量 80%）」",
					LocalizationGen.CardsJson(auProfile).Contains("播放音频：自检语音（音量 80%）"), "描述对");

				// 遗物 / 药水 / 状态：同一条发射器，三处都要能放
				var auRelic = new RelicSpec { Name = "自检音频遗物", ClassName = "UiCheckAudioRelic", Rarity = "Common", Trigger = "CombatStart" };
				auRelic.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = auKey });
				auProfile.Relics.Add(auRelic);
				Check("V0.2.155：遗物上也能放上传的音频",
					CSharpCodeGen.RelicSource(auProfile, auRelic, 0).Contains("new AudioStreamPlayer()"), "生成了");
				var auPotion = new PotionSpec { Name = "自检音频药水", ClassName = "UiCheckAudioPotion", Rarity = "Common", Usage = "CombatOnly", TargetType = "AllEnemies" };
				auPotion.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = auKey });
				auProfile.Potions.Add(auPotion);
				Check("V0.2.155：药水上也能放",
					CSharpCodeGen.PotionSource(auProfile, auPotion, 0).Contains("new AudioStreamPlayer()"), "生成了");
				var auPower = new CustomPowerSpec { Name = "自检音频状态", ClassName = "UiCheckAudioPower", Enabled = true };
				var auTrigger = new PowerTriggerSpec { Kind = "TurnStart" };
				auTrigger.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = auKey });
				auPower.Triggers.Add(auTrigger);
				auProfile.CustomPowers.Add(auPower);
				Check("V0.2.155：自定义状态的触发时机里也能放",
					CustomPowerGen.Source(auProfile, auPower, 0).Contains("new AudioStreamPlayer()"), "生成了");
				Check("V0.2.155：状态描述里写的是音频文件名",
					PowerTriggers.AutoDescription(auPower).Contains("播放音频："), PowerTriggers.AutoDescription(auPower));

				// 真正的「生成工程」：音频文件必须被复制到工程 audio/ 下（导出预设 all_resources → 会打进 PCK）
				string auRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_audiogen_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					auProfile.Paths.OutputDir = auRoot;
					var auGen = ModGenerator.Generate(auProfile);
					Check("（准备）带上传音频的存档能生成工程", auGen.Success, auGen.Success ? auGen.ProjectRoot
						: string.Join(" | ", auGen.Issues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
					if (auGen.Success)   // 生成失败就别往下走（ProjectRoot 是空的，Path.Combine 会抛）
					{
					string auDst = Path.Combine(auGen.ProjectRoot, "audio", auKey);
					Check("V0.2.155：上传的音频被复制进工程 audio/（导出预设 all_resources，会一起打进 PCK）",
						File.Exists(auDst), File.Exists(auDst) ? "audio/" + auKey : "(没有这个文件)");
					var auRec = ProjectRecovery.FromProject(auGen.ProjectRoot);
					var auRecCard = auRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckAudioCard");
					Check("V0.2.155：从工程恢复：「播放音频文件」选的是哪个文件 + 音量都认得回来",
						auRecCard is not null && auRecCard.Effects.Any((EffectSpec x) => x.Kind == "PlaySoundFile"
							&& x.Sfx == auKey && x.Amount == 80m),
						auRecCard is null ? "(没找回这张卡)"
							: string.Join(" / ", auRecCard.Effects.Select((EffectSpec x) => x.Kind + "=" + x.Sfx + "@" + x.Amount)));
					Check("V0.2.155：从工程恢复：音频素材清单也从工程 audio/ 里认回来了（不然下次生成会丢文件）",
						auRec.Profile.AudioAssets.Any((AudioAssetSpec a) => a is not null && a.Key == auKey),
						string.Join(" / ", auRec.Profile.AudioAssets.Select((AudioAssetSpec a) => a.Key)));
					Check("V0.2.155：从工程恢复（带上传音频）：没认出来的语句为 0", !auRec.HasUnparsed,
						auRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(auRoot, true); } catch { }
					try { Directory.Delete(auDir, true); } catch { }
				}

				// 校验器：没选 / 条目没了
				Check("V0.2.155：校验器拦「没选音频」和「选的那条已经不在了」",
					ProfileValidator.Validate(AudioProbe("")).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("还没选音频"))
					&& ProfileValidator.Validate(AudioProbe("不存在的东西.ogg")).Any((ValidationIssue i) => i.Level == "错误" && i.Message.Contains("重新选一个")),
					"两条都对");
				Check("V0.2.155：.ogg / .mp3 / .wav / .oga 认，别的扩展名不认（Key 退回 .ogg，由校验器报错）",
					AudioAssetSpec.IsSupportedAudio("a.ogg") && AudioAssetSpec.IsSupportedAudio("a.mp3")
					&& AudioAssetSpec.IsSupportedAudio("a.wav") && AudioAssetSpec.IsSupportedAudio("a.oga")
					&& !AudioAssetSpec.IsSupportedAudio("a.flac") && !AudioAssetSpec.IsSupportedAudio("a.txt")
					&& new AudioAssetSpec { Name = "x", File = "y.flac" }.Key == "x.ogg",
					"扩展名口径对");

				// 界面：效果栏那一行显隐 + 「美术资源」页那块
				Check("V0.2.155：（界面）「音频文件」那一行的显隐绑在 IsPlaySoundFile 上",
					CollectBoundPaths(SelectTabRoot("卡牌")).Contains("IsPlaySoundFile"), "在");
				var artButtons = new List<Button>();
				CollectButtons(SelectTabRoot("美术资源"), artButtons);
				Check("V0.2.155：（界面）「美术资源」页有「音效 / 音频」那一块（上传 / 删除按钮 + 列表）",
					AudioAssetList is not null
					&& artButtons.Any((Button b) => (b.Content as string) == "上传音频…")
					&& artButtons.Any((Button b) => (b.Content as string) == "删除"),
					"在");

				CharacterProfile AudioProbe(string key)
				{
					CharacterProfile p3 = ProfileFactory.Sample();
					p3.Paths.VanillaProject = Profile.Paths.VanillaProject;
					p3.Paths.GameDataDir = Profile.Paths.GameDataDir;
					p3.Cards.Clear();
					p3.AudioAssets.Clear();
					if (key.Length > 0)
						p3.AudioAssets.Add(new AudioAssetSpec { Name = "别的名字", File = Path.Combine(Path.GetTempPath(), "not_there.ogg") });
					var c4 = new CardSpec { Name = "自检音频校验", ClassName = "UiCheckAudioValidate", CardType = "Skill", Rarity = "Common", Cost = 1 };
					c4.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = key });
					p3.Cards.Add(c4);
					return p3;
				}

				string AudioCardSource(CharacterProfile p4, string cls, string key)
				{
					var c5 = new CardSpec { Name = "自检音频" + cls, ClassName = cls, CardType = "Skill", Rarity = "Common", Cost = 1 };
					c5.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = key });
					return CSharpCodeGen.CardSource(p4, c5, 0);
				}
			}
			// ===== V0.2.231：音频效果底下新增「音频是否被下一个自定义音频顶替」=====
			// 用户要求：「音频效果底下增加音频是否被下一个自定义音频顶替」。
			// 默认（不勾）= 每次播放各开一个播放器、几段叠着响（老行为，逐字不变）；
			// 勾上 = 这段还在放时，只要又播放了**另一个「我上传的音频」**，这段立刻停掉（新的接手）。
			// 实现：勾了任意一条 → 生成 cs/ForgeSfx.cs（记着「还在放、且允许被顶替」的播放器），
			// 所有自定义音频都改走它；一条都没勾 → 不生成那个文件、播放代码还是原来那几句。
			{
				string sfxDir = Path.Combine(Path.GetTempPath(), "forge_uicheck_sfxrep_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				Directory.CreateDirectory(sfxDir);
				string sfxFile = Path.Combine(sfxDir, "probe_voice.ogg");
				File.WriteAllBytes(sfxFile, new byte[] { 0x4F, 0x67, 0x67, 0x53, 0, 2, 0, 0 });   // "OggS"
				try
				{
					Check("V0.2.231：那个勾只在「播放音频文件」上显示（别的种类生成端不读它）",
						new EffectSpec { Kind = "PlaySoundFile", SfxReplace = true }.ShowSfxReplaceRow
						&& !new EffectSpec { Kind = "PlaySfx" }.ShowSfxReplaceRow
						&& !new EffectSpec { Kind = "Damage" }.ShowSfxReplaceRow
						&& EffectFieldPolicy.UsesSfxReplace("PlaySoundFile")
						&& !EffectFieldPolicy.UsesSfxReplace("Damage"), "显隐对");

					// ① 红线：一条都没勾 → 不生成小助手、播放代码还是老的 __sfx 那几句
					CharacterProfile sfxOff = ProfileFactory.Sample();
					sfxOff.Paths.VanillaProject = Profile.Paths.VanillaProject;
					sfxOff.Paths.GameDataDir = Profile.Paths.GameDataDir;
					sfxOff.Relics.Clear();
					sfxOff.Potions.Clear();
					sfxOff.CustomPowers.Clear();
					sfxOff.AudioAssets.Clear();
					sfxOff.AudioAssets.Add(new AudioAssetSpec { Name = "自检语音", File = sfxFile });
					string sfxKey = sfxOff.AudioAssets[0].Key;
					var sfxOffCard = new CardSpec { Name = "自检音频旧", ClassName = "UiCheckSfxOld", CardType = "Skill", Rarity = "Common", Cost = 1 };
					sfxOffCard.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = sfxKey, Amount = 80m });
					sfxOff.Cards.Add(sfxOffCard);
					Check("V0.2.231：没勾时 UsesSfxReplace = false（不会白生成文件）",
						!CSharpCodeGen.UsesSfxReplace(sfxOff), "没有");
					string sfxOffSrc = CSharpCodeGen.CardSource(sfxOff, sfxOffCard, 0);
					Check("V0.2.231：（红线）没勾时播放代码和以前**逐字一致**（还是内联的 __sfx 那几句，没有 ForgeSfx）",
						sfxOffSrc.Contains("var __sfx = new AudioStreamPlayer();")
						&& !sfxOffSrc.Contains("ForgeSfx")
						&& !sfxOffSrc.Contains("CET:SfxReplace=1"), "逐字不变");

					// ② 勾上 → 生成小助手 + 走它；同一条卡上再放一条「不勾」的，两种 replaceable 都要对
					CharacterProfile sfxOn = ProfileFactory.Sample();
					sfxOn.Paths.VanillaProject = Profile.Paths.VanillaProject;
					sfxOn.Paths.GameDataDir = Profile.Paths.GameDataDir;
					sfxOn.Relics.Clear();
					sfxOn.Potions.Clear();
					sfxOn.CustomPowers.Clear();
					sfxOn.AudioAssets.Clear();
					sfxOn.AudioAssets.Add(new AudioAssetSpec { Name = "自检语音", File = sfxFile });
					var sfxOnCard = new CardSpec { Name = "自检音频新", ClassName = "UiCheckSfxNew", CardType = "Skill", Rarity = "Common", Cost = 1 };
					sfxOnCard.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = sfxKey, Amount = 80m, SfxReplace = true });
					sfxOnCard.Effects.Add(new EffectSpec { Kind = "PlaySoundFile", Sfx = sfxKey, Amount = 60m, SfxReplace = false });
					sfxOn.Cards.Add(sfxOnCard);
					Check("V0.2.231：勾了之后 UsesSfxReplace = true（要生成 cs/ForgeSfx.cs）",
						CSharpCodeGen.UsesSfxReplace(sfxOn), "有");
					string sfxOnSrc = CSharpCodeGen.CardSource(sfxOn, sfxOnCard, 0);
					Check("V0.2.231：勾了的那条生成 ForgeSfx.Play(…, replaceable: true)（音量照旧按百分比）",
						sfxOnSrc.Contains($".Play(\"res://audio/{sfxKey}\", Mathf.LinearToDb(0.8f), replaceable: true);"),
						(sfxOnSrc.Split('\n').FirstOrDefault((string l) => l.Contains("ForgeSfx.Play(", StringComparison.Ordinal)) ?? "(没生成)").Trim());
					Check("V0.2.231：同一份存档里**不勾**的那条 → replaceable: false（可以和别的叠着响）",
						sfxOnSrc.Contains("replaceable: false);"), "有 false");
					Check("V0.2.231：标记行带上 CET:SfxReplace=1（回读靠它）",
						sfxOnSrc.Contains("CET:SfxReplace=1"), "标记在");
					Check("V0.2.231：小助手源码讲清了它是干什么的（Replaceable 列表 + 新的开始前先停旧的）",
						CSharpCodeGen.SfxRegistrySource(sfxOn).Contains("Replaceable")
						&& CSharpCodeGen.SfxRegistrySource(sfxOn).Contains("bool replaceable")
						// V0.2.265：列表元素从 AudioStreamPlayer 换成 Playing（要记 key 才能判同组）
						&& CSharpCodeGen.SfxRegistrySource(sfxOn).Contains("old.Player.Stop();"), "写得对");

					// ③ 整份生成：cs/ForgeSfx.cs 只在勾了时出现；生成 → 回读要认得回来
					string sfxOffRoot = Path.Combine(sfxDir, "off");
					string sfxOnRoot = Path.Combine(sfxDir, "on");
					sfxOff.Paths.OutputDir = sfxOffRoot;
					sfxOn.Paths.OutputDir = sfxOnRoot;
					var sfxOffGen = ModGenerator.Generate(sfxOff);
					var sfxOnGen = ModGenerator.Generate(sfxOn);
					Check("V0.2.231：（准备）两种存档都能生成工程", sfxOffGen.Success && sfxOnGen.Success,
						sfxOffGen.Success ? sfxOnGen.ProjectRoot : string.Join(" ｜ ", sfxOffGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (sfxOffGen.Success && sfxOnGen.Success)
					{
						Check("V0.2.231：没勾 → 工程里没有 cs/ForgeSfx.cs；勾了 → 有",
							!File.Exists(Path.Combine(sfxOffGen.ProjectRoot!, "cs", "ForgeSfx.cs"))
							&& File.Exists(Path.Combine(sfxOnGen.ProjectRoot!, "cs", "ForgeSfx.cs")),
							File.Exists(Path.Combine(sfxOnGen.ProjectRoot!, "cs", "ForgeSfx.cs")) ? "只在勾了的那份里有" : "(勾了也没生成)");
						var sfxRec = ProjectRecovery.FromProject(sfxOnGen.ProjectRoot!);
						var sfxRecCard = sfxRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckSfxNew");
						Check("V0.2.231：回读：「顶替」那一档认得回来（勾的那条 true / 没勾的 false）",
							sfxRecCard is not null
							&& sfxRecCard.Effects.Count((EffectSpec e) => e.Kind == "PlaySoundFile") == 2
							&& sfxRecCard.Effects.Where((EffectSpec e) => e.Kind == "PlaySoundFile").OrderByDescending((EffectSpec e) => e.Amount)
								.First().SfxReplace
							&& !sfxRecCard.Effects.Where((EffectSpec e) => e.Kind == "PlaySoundFile").OrderByDescending((EffectSpec e) => e.Amount)
								.Last().SfxReplace,
							sfxRecCard is null ? "(没找回这张卡)"
								: string.Join(" / ", sfxRecCard.Effects.Select((EffectSpec e) => e.Kind + ":" + e.Amount + ":" + e.SfxReplace)));
						Check("V0.2.231：回读（走小助手那几句之后）没有认不出来的语句", !sfxRec.HasUnparsed,
							sfxRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(sfxDir, true); } catch { }
				}
			}

			// ===== V0.2.232：那条勾「换效果种类后没出现」（用户报「没看到会被下一个自定义音频顶替这个」）=====
			// 真因：`ShowSfxReplaceRow`（勾的显隐）绑的是 `Kind`，但 `Kind` 的 setter 里没 `Raise` 它 ——
			// WPF 的绑定只在第一次求值时算一次，后来把效果种类改成「播放音频文件」时那一行永远是 Collapsed。
			// 这里钉两件事：① 换种类时必须发出 ShowSfxReplaceRow 的通知；② 只有「播放音频文件」是真。
			{
				var sfxVisProbe = new EffectSpec { Kind = "Damage" };
				var sfxRaised = new List<string>();
				sfxVisProbe.PropertyChanged += (_, ev) => sfxRaised.Add(ev.PropertyName ?? "");
				sfxVisProbe.Kind = "PlaySoundFile";
				Check("V0.2.232：把效果种类改成「播放音频文件」时会通知 ShowSfxReplaceRow（不然那个勾不出现）",
					sfxRaised.Contains("ShowSfxReplaceRow") && sfxVisProbe.ShowSfxReplaceRow,
					"通知了：" + string.Join("/", sfxRaised.Where((string n) => n.Contains("Sfx"))));
				sfxVisProbe.Kind = "Damage";
				Check("V0.2.232：换回别的种类时同样通知（那个勾要收起来），而且 ShowSfxReplaceRow = false",
					sfxRaised.Count((string n) => n == "ShowSfxReplaceRow") >= 2 && !sfxVisProbe.ShowSfxReplaceRow,
					"通知了两次以上");
				Check("V0.2.232：界面上那一行确实在（勾选框 + 那句「不勾 = 允许几段音频叠着响」）",
					CollectBoundPaths(SelectTabRoot("卡牌")).Contains("ShowSfxReplaceRow")
					|| CollectBoundPaths(SelectTabRoot("遗物")).Contains("ShowSfxReplaceRow"),
					"绑上了");
			}
			// ===== V0.2.233：遗物「获得金币时」的效果不再被静默丢掉（用户报「无法正常生效」）=====
			// 真因：AfterGoldGained(Player) 的签名里没有 choiceContext，而「抽牌 / 消耗卡牌 / 施加状态 /
			// 生成卡牌 / 拿牌」这些效果都要它 → 生成端以前只写一行「该触发时机没有 choiceContext，已忽略」，
			// 于是整条效果什么都不做（看起来就是「触发时机不生效」）。其实这条钩子在战斗里 / 战斗外都会走
			// （本体 PlayerCmd.GainGold 调 Hook.AfterGoldGained），所以按运行时造一个上下文就行。
			{
				Check("V0.2.233：「获得金币时」现在算「能造 choiceContext」（按运行时：战斗里 Hook / 战斗外用阻塞式）",
					CSharpCodeGen.BootstrapContextRuntime("GoldGained")
					&& !CSharpCodeGen.BootstrapContextRuntime("CombatVictory")
					&& !CSharpCodeGen.BootstrapContextRuntime("PlayerTurnStart"),
					"判据对");

				static CharacterProfile GoldRelicProfile(string trigger, params EffectSpec[] effects)
				{
					var gp = ProfileFactory.Sample();
					var rl = new RelicSpec { Name = "自检金币遗物", ClassName = "UiCheckGoldRelic", Rarity = "Common", Trigger = trigger };
					foreach (EffectSpec e in effects) rl.Effects.Add(e);
					gp.Relics.Clear();
					gp.Relics.Add(rl);
					return gp;
				}

				var goldCtxProfile = GoldRelicProfile("GoldGained",
					new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" },
					new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" },
					new EffectSpec { Kind = "ExhaustCard", Amount = 1m, SelectPile = "Hand", CardPick = "Chosen" });
				string goldCtxSrc = CSharpCodeGen.RelicSource(goldCtxProfile, goldCtxProfile.Relics[0], 0);
				Check("V0.2.233：遗物「获得金币时」+ 抽牌 / 消耗卡牌 → 真的生成了代码（不再只有一行「已忽略」）",
					goldCtxSrc.Contains("await CardPileCmd.Draw(choiceContext")
					&& goldCtxSrc.Contains("CardSelectCmd.FromHand(context: choiceContext")
					&& !goldCtxSrc.Contains("该触发时机不支持「抽牌」")
					&& !goldCtxSrc.Contains("该触发时机不支持「消耗卡牌」"),
					(goldCtxSrc.Split('\n').FirstOrDefault((string l) => l.Contains("CardPileCmd.Draw(", StringComparison.Ordinal)) ?? "(没生成 Draw)").Trim());
				Check("V0.2.233：那个 choiceContext 是按运行时造的（战斗中 Hook / 战斗外阻塞式），不是死写一种",
					goldCtxSrc.Contains("MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext choiceContext;")
					&& goldCtxSrc.Contains("if (base.Owner.Creature.CombatState is not null)")
					&& goldCtxSrc.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext(this, base.Owner, __netId,")
					&& goldCtxSrc.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext()"),
					"两路都有");

				// 红线：不需要上下文的效果（只有格挡）→ 一个字都不多写（和老输出逐字一致）
				var goldPlainProfile = GoldRelicProfile("GoldGained", new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" });
				string goldPlainSrc = CSharpCodeGen.RelicSource(goldPlainProfile, goldPlainProfile.Relics[0], 0);
				Check("V0.2.233：（红线）「获得金币时」只配了不需要上下文的效果时，不写任何 choiceContext 那几句",
					goldPlainSrc.Contains("if (player != base.Owner) return;")
					&& !goldPlainSrc.Contains("PlayerChoiceContext choiceContext")
					&& !goldPlainSrc.Contains("BlockingPlayerChoiceContext"),
					"没多写");

				// 多时机那条路：GoldGained 分支同样要造（且只造一次）
				var goldMulti = ProfileFactory.Sample();
				var goldMultiRelic = new RelicSpec { Name = "自检多时机金币", ClassName = "UiCheckGoldMultiRelic", Rarity = "Common", Trigger = "CombatStart" };
				goldMultiRelic.Triggers.Add(new RelicTriggerSpec { Kind = "GoldGained" });
				goldMultiRelic.Triggers.Add(new RelicTriggerSpec { Kind = "PlayerTurnStart" });
				goldMultiRelic.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" });
				goldMulti.Relics.Clear();
				goldMulti.Relics.Add(goldMultiRelic);
				string goldMultiSrc = CSharpCodeGen.RelicSource(goldMulti, goldMultiRelic, 0);
				int goldCtxDecls = goldMultiSrc.Split('\n').Count((string l) => l.Contains("PlayerChoiceContext choiceContext;", StringComparison.Ordinal));
				Check("V0.2.233：多时机（获得金币 + 回合开始）里，金币那个方法也造了上下文、而且只造一次",
					goldMultiSrc.Contains("public override async Task AfterGoldGained(Player player)")
					&& goldCtxDecls == 1
					&& goldMultiSrc.Contains("BlockingPlayerChoiceContext"), $"声明了 {goldCtxDecls} 次");

				// 校验器：真正拿不到上下文的时机（战斗胜利）仍然要提醒，金币那条不再误报
				Check("V0.2.233：校验器不再为「获得金币时」报「缺少 choiceContext」",
					!ProfileValidator.Validate(GoldRelicProfile("GoldGained", new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" }))
						.Any((ValidationIssue i) => i.Message.Contains("缺少 choiceContext")),
					"不报了");
				Check("V0.2.233：真正没有上下文的时机（战斗胜利时）+ 抽牌 → 仍然报「缺少 choiceContext」警告",
					ProfileValidator.Validate(GoldRelicProfile("CombatVictory", new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" }))
						.Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("缺少 choiceContext")),
					"报了");
			}
			// ===== V0.2.156：卡牌列表**拖动**之后，「上传的卡面」必须跟着那张卡一起走 =====
			// 用户报：「在卡牌列表拖动卡牌后，卡面会变成其他卡」。
			// 真因（两个叠在一起）：
			//   ① 拖动的落点逻辑 MoveCardTo = `Cards.Move` → **RefreshCardOrdinals()** → SyncDetail()，
			//      而 RefreshCardOrdinals 会把每张卡的 LastAutoOrdinal 就地改成**新**行号 ——
			//      可「旧名字 → 新名字」这张映射表正是靠 LastAutoOrdinal（上一次的号）算出来的，
			//      先覆盖就永远算不出映射 → 卡面（按类名存）原地不动，落到**现在叫这个名字的另一张卡**身上；
			//   ② 搬卡面那一段是「顺序搬 + 目标已有就跳过」，把牌**往上**拖会形成名字的**环**
			//      （[A,B,C] → [B,C,A]），环上会把几张图的落点搞错。
			// 这个用例走的就是真实那两步（RefreshCardOrdinals + Cards.Move），不是另写一套模拟。
			{
				var portraitBackup = new Dictionary<string, string>(_profile.Art.CardPortraits, StringComparer.Ordinal);
				var dragProbe = new List<CardSpec>();
				IReadOnlyList<string> DragNames() =>
					dragProbe.Select((CardSpec c) => Naming.From(_profile).CardClassName(_profile, c)).ToList();
				List<string> WrongPortraits()
				{
					var bad = new List<string>();
					IReadOnlyList<string> now = DragNames();
					for (int i = 0; i < dragProbe.Count; i++)
					{
						_profile.Art.CardPortraits.TryGetValue(now[i], out string? got);
						if (got != $@"D:\fake\drag_probe_{i + 1}.png")
							bad.Add($"{dragProbe[i].Name}（{now[i]}）拿到的是 {(got is null ? "（没有卡面）" : Path.GetFileName(got))}");
					}
					return bad;
				}
				try
				{
					for (int i = 1; i <= 3; i++)
					{
						var probeCard = new CardSpec { Name = "拖动探针" + i, CardType = "Attack", Rarity = "Common", Cost = 1 };
						_profile.Cards.Add(probeCard);
						dragProbe.Add(probeCard);
					}
					RefreshCardOrdinals();                       // 载入 / 刷新那一拍（LastAutoOrdinal 写实）
					IReadOnlyList<string> before = DragNames();
					for (int i = 0; i < dragProbe.Count; i++)
						_profile.Art.CardPortraits[before[i]] = $@"D:\fake\drag_probe_{i + 1}.png";

					// 拖动 1：把最后一张拖到最前面（MoveCardTo 里就是这两步）
					_profile.Cards.Move(_profile.Cards.IndexOf(dragProbe[2]), 0);
					RefreshCardOrdinals();
					List<string> bad1 = WrongPortraits();
					Check("V0.2.156：拖动卡牌之后，上传的卡面跟着那张卡一起走（不会落到别的卡身上）",
						bad1.Count == 0,
						(bad1.Count == 0 ? "3 张都对" : string.Join(" / ", bad1))
						+ " ｜ 名称：" + string.Join(",", DragNames()));
					Check("V0.2.156：（反向说明）拖动前的旧名字现在已经属于**另一张卡** —— 不搬就是「卡面变成别的卡的图」",
						Naming.From(_profile).CardClassName(_profile, dragProbe[1]) == before[2],
						$"旧名字 {before[2]} 现在的主人是「{dragProbe[1].Name}」");

					// 拖动 2：把最前面那张拖到最后（[A,B,C] → [B,C,A]，名字形成一个**环**）
					_profile.Cards.Move(_profile.Cards.IndexOf(dragProbe[0]), _profile.Cards.Count - 1);
					RefreshCardOrdinals();
					List<string> bad2 = WrongPortraits();
					Check("V0.2.156：把牌**往上/往下**拖形成「名字成环」时也搬得对（一次性重排，不是顺序搬）",
						bad2.Count == 0, bad2.Count == 0 ? "环上 3 张都对" : string.Join(" / ", bad2));
				}
				finally
				{
					foreach (CardSpec probeCard in dragProbe) _profile.Cards.Remove(probeCard);
					_profile.Art.CardPortraits.Clear();
					foreach (var (k, v) in portraitBackup) _profile.Art.CardPortraits[k] = v;
					RefreshCardOrdinals();
					RefreshCardChoices();
				}
			}

			// ===== V0.2.157：「打出一张牌时」必须是**结算前**（本体 BeforeCardPlayed）=====
			// 用户报：状态监听「打出一张牌时」会监听**施加这个状态的那张牌** —— 也就是说那一档实际是
			// 「打出一张牌后」（AfterCardPlayed，结算完才回调），和「一张牌结算完毕时」几乎一样。
			// 本体顺序（CardModel）：Hook.BeforeCardPlayed → OnPlay（卡的效果，上状态就在这一步）→ …
			//   → Hook.AfterCardPlayed（内部先 AfterCardPlayed 再 AfterCardPlayedLate）。
			// 所以「打出的那一刻」= BeforeCardPlayed：这时这张牌还没结算 → 它自己施加的状态还不存在
			// → 不会被它自己触发。原来那一档留成新时机「一张牌结算完毕时」（AfterCardPlayedLate）。
			{
				var cpPower = new CustomPowerSpec { Name = "自检打牌时机", ClassName = "UiCheckCardPlayedPower", Enabled = true };
				var cpTrigger = new PowerTriggerSpec { Kind = "CardPlayed" };
				// 效果用「消耗卡牌（自己选）」——它**需要** choiceContext（CardSelectCmd 要它），
				// 这样才验得到「BeforeCardPlayed 没给 context → 生成端自己造一个」那一步
				//（用不需要 context 的效果永远看不到那一行）
				cpTrigger.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
				cpPower.Triggers.Add(cpTrigger);
				var cpResolvedTrigger = new PowerTriggerSpec { Kind = "CardResolved" };
				cpResolvedTrigger.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
				cpPower.Triggers.Add(cpResolvedTrigger);
				CharacterProfile cpProfile = ProfileFactory.Sample();
				cpProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				cpProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				cpProfile.CustomPowers.Clear();
				cpProfile.CustomPowers.Add(cpPower);
				string cpSrc = CustomPowerGen.Source(cpProfile, cpPower, 0);
				Check("V0.2.157：状态里的「打出一张牌时」生成的是 **BeforeCardPlayed**（结算前）—— 不会被「打出它才施加的状态」自己触发",
					cpSrc.Contains("public override async Task BeforeCardPlayed(CardPlay cardPlay)")
					&& !cpSrc.Contains("public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)"),
					cpSrc.Split('\n').FirstOrDefault((string l) => l.Contains("BeforeCardPlayed", StringComparison.Ordinal))?.Trim() ?? "(没生成)");
				Check("V0.2.157：BeforeCardPlayed 没有 choiceContext → 生成端自己造一个（不然效果里引用不到 choiceContext）",
					cpSrc.Contains("HookPlayerChoiceContext"), "造了");
				Check("V0.2.157：「一张牌结算完毕时」生成的是 AfterCardPlayedLate（旧版「打出一张牌后」的档位没丢）",
					cpSrc.Contains("public override async Task AfterCardPlayedLate(PlayerChoiceContext choiceContext, CardPlay cardPlay)"),
					"生成了");
				Check("V0.2.157：两条时机的显示名写在菜单里（自定义状态 / 遗物 / 锻造遗物档三处一致）",
					PowerTriggers.Find("CardPlayed")!.Display.Contains("还没生效")
					&& PowerTriggers.Find("CardResolved") is not null
					&& EffectCatalog.RelicTriggers.Any((TriggerOption t) => t.Id == "CardResolved")
					&& ForgeTimings.For("Relic").Any((ForgeTimings.TimingOption t) => t.Id == "CardResolved"),
					PowerTriggers.Find("CardPlayed")!.Display);
				// 遗物链同样：签名 + 归属守卫都要跟过来
				Check("V0.2.157：遗物侧两条时机的签名 / 归属守卫都对（BeforeCardPlayed 结算前、AfterCardPlayedLate 结算完）",
					CSharpCodeGen.RelicTriggerSignature("CardPlayed").Contains("BeforeCardPlayed")
					&& CSharpCodeGen.RelicTriggerSignature("CardResolved").Contains("AfterCardPlayedLate")
					&& !CSharpCodeGen.HasContext("CardPlayed") && CSharpCodeGen.BootstrapInCombat("CardPlayed")
					&& CSharpCodeGen.HasContext("CardResolved"),
					"两侧一致");
			}

			// ===== V0.2.158：公式里的 X / Y 在「这张牌要花能量 / 资源量」时读到的是**扣完剩下的** =====
			// 用户报：「在次数填 Y（额外资源量）时，只会触发一次」。
			// 真因：本体**先扣费、再跑效果**（PlayCardAction：`await _card.SpendResources()` → `OnPlayWrapper(...)`），
			// 所以「Y 费」的牌在效果里读 Y 就是 0（次数被 Math.Clamp(…,1,20) 夹到 1）。
			// 修法：给公式加两个「这张牌**花掉**的」读数（XSpent / YSpent = 本体 ResolveEnergyXValue /
			// ResolveStarXValue），并在校验器里对「X 费 / Y 费 + 公式用 X / Y」给警告说清原因。
			{
				Check("V0.2.158：公式里多了两个「这张牌花掉的」读数（XSpent / YSpent）",
					FormulaBuiltins.Find("XSpent") is not null && FormulaBuiltins.Find("YSpent") is not null
					&& FormulaBuiltins.Find("YSpent")!.Expr("__fgPlayer", "__fgSelf").Contains("ResolveStarXValue")
					&& FormulaBuiltins.Find("XSpent")!.Expr("__fgPlayer", "__fgSelf").Contains("ResolveEnergyXValue"),
					FormulaBuiltins.Find("YSpent")!.Display);
				CharacterProfile xpProfile = ProfileFactory.Sample();
				xpProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				xpProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var xpCard = new CardSpec { Name = "自检花掉的资源", ClassName = "UiCheckXSpent", CardType = "Skill", Rarity = "Common", Cost = 1 };
				xpCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", TimesFormula = "YSpent" });
				xpProfile.Cards.Add(xpCard);
				string xpSrc = CSharpCodeGen.CardSource(xpProfile, xpCard, 0);
				Check("V0.2.158：次数（公式）填 YSpent → 生成 `(decimal)base.ResolveStarXValue()`（这张牌花掉的那个数）",
					xpSrc.Contains("(decimal)base.ResolveStarXValue()"), "生成了");
				// V0.2.159：本体那两个方法**不是 X 费就抛异常**（CardModel 第一句就是
				// `if (!EnergyCost.CostsX) throw new InvalidOperationException(...)` /
				// `if (!HasStarCostX) throw ...`）—— 生成端必须先判再调，不然普通牌上用一次就战斗中崩。
				Check("V0.2.159：XSpent / YSpent 生成的是「先判再调」的三元（本体那两个方法在非 X 费牌上会抛异常）",
					FormulaBuiltins.Find("XSpent")!.Expr("__fgPlayer", "__fgSelf").Contains("CostsX ?")
					&& FormulaBuiltins.Find("XSpent")!.Expr("__fgPlayer", "__fgSelf").Contains("ResolveEnergyXValue")
					&& FormulaBuiltins.Find("YSpent")!.Expr("__fgPlayer", "__fgSelf").Contains("HasStarCostX ?")
					&& FormulaBuiltins.Find("YSpent")!.Expr("__fgPlayer", "__fgSelf").Contains("ResolveStarXValue")
					&& xpSrc.Contains("base.HasStarCostX ? (decimal)base.ResolveStarXValue() : 0m"),
					FormulaBuiltins.Find("YSpent")!.Expr("__fgPlayer", "__fgSelf"));
				// V0.2.159：不崩了，但「不是那种费用」的牌上读数恒为 0 = 公式白写 → 校验器明说
				{
					var spentMisuse = ProfileFactory.Sample();
					spentMisuse.Paths.VanillaProject = Profile.Paths.VanillaProject;
					spentMisuse.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var mu = new CardSpec { Name = "自检花掉的读数写错牌", ClassName = "UiCheckSpentMisuse", CardType = "Skill", Rarity = "Common", Cost = 1 };
					mu.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", TimesFormula = "XSpent" });
					mu.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", TimesFormula = "YSpent" });
					spentMisuse.Cards.Add(mu);
					var misuseIssues = ProfileValidator.Validate(spentMisuse).Where((ValidationIssue i) => i.Level == "警告").ToList();
					Check("V0.2.159：XSpent 用在「不是 X 费」的牌上 → 警告（读数恒为 0，别静默）",
						misuseIssues.Any((ValidationIssue i) => i.Message.Contains("用了 **XSpent**") && i.Message.Contains("恒为 0")),
						misuseIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("XSpent"))?.Message ?? "(没报)");
					Check("V0.2.159：YSpent 用在「不是 Y 费」的牌上 → 警告（读数恒为 0，别静默）",
						misuseIssues.Any((ValidationIssue i) => i.Message.Contains("用了 **YSpent**") && i.Message.Contains("恒为 0")),
						misuseIssues.FirstOrDefault((ValidationIssue i) => i.Message.Contains("**YSpent**"))?.Message ?? "(没报)");
				}
				// 校验器：Y 费 + 公式用 Y → 警告说清「先扣费再跑效果」并指出 YSpent
				var yCostCard = new CardSpec { Name = "自检Y费", ClassName = "UiCheckYCostWarn", CardType = "Skill", Rarity = "Common", Cost = 1 };
				yCostCard.StarCostText = "Y";     // Y 费（花光所有额外资源量）
				yCostCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", TimesFormula = "Y" });
				var yCostProfile = ProfileFactory.Sample();
				yCostProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				yCostProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				yCostProfile.Cards.Add(yCostCard);
				// ===== V0.2.168：口径再改一次（用户实测：「次数填 Y 或者 X 次还是只生效一次」）=====
				// 真因：本体**先扣费、再跑效果**，所以「Y 费」的牌在效果跑的那一刻 Y（当前额外资源量）已经是 0
				//（次数被 Math.Clamp(…, 1, 20) 夹成 1，看着就是「只生效一次」）。
				// 现在生成端对「X 费 / Y 费」的牌**直接按这张牌花掉的那部分**生成
				//（__X / __Y 取 ResolveEnergyXValue() / ResolveStarXValue()）—— 用户不用再改成 XSpent / YSpent，
				// 校验器那条「先扣费再跑效果」的警告也改成提示（说清已经按花掉的那部分算）。
				Check("V0.2.168：「Y 费」的牌 + 公式里用 Y → 生成 `(decimal)base.ResolveStarXValue()`（这张牌花掉的额外资源量）",
					CSharpCodeGen.CardSource(yCostProfile, yCostCard, yCostProfile.Cards.Count - 1)
						.Contains("decimal __Y = (decimal)base.ResolveStarXValue();", StringComparison.Ordinal),
					"按花掉的那部分生成");
				{
					// 对照①：普通牌（不是 Y 费）里的 Y 照旧 = 当前额外资源量（不回归）
					var plainY = new CardSpec { Name = "自检普通Y", ClassName = "UiCheckPlainY", CardType = "Skill", Rarity = "Common", Cost = 1 };
					plainY.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", TimesFormula = "Y" });
					var plainYProfile = ProfileFactory.Sample();
					plainYProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					plainYProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					plainYProfile.Cards.Add(plainY);
					Check("V0.2.168（不回归）：不是「Y 费」的牌里 Y 照旧 = 当前额外资源量（ForgeFormulaRuntime.Stars）",
						CSharpCodeGen.CardSource(plainYProfile, plainY, plainYProfile.Cards.Count - 1)
							.Contains("decimal __Y = ForgeFormulaRuntime.Stars(base.Owner);", StringComparison.Ordinal), "老写法");
					// 对照②：「X 费」（费用框里写 X）的牌里 X = 这张牌花掉的能量
					var xCost = new CardSpec { Name = "自检X费", ClassName = "UiCheckXCostNow", CardType = "Attack", Rarity = "Common" };
					xCost.CostFormula = "X";
					xCost.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy", TimesFormula = "X" });
					var xCostProfile = ProfileFactory.Sample();
					xCostProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					xCostProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					xCostProfile.Cards.Add(xCost);
					Check("V0.2.168：「X 费」的牌 + 公式里用 X → 生成 `(decimal)base.ResolveEnergyXValue()`（这张牌花掉的能量）",
						CSharpCodeGen.CardSource(xCostProfile, xCost, xCostProfile.Cards.Count - 1)
							.Contains("decimal __X = (decimal)base.ResolveEnergyXValue();", StringComparison.Ordinal), "按花掉的那部分生成");
				}
				Check("V0.2.168：校验器对「Y 费 + 公式里用 Y」只说一句提示（不再是「Y 读到 0、只会触发一次」的警告）",
					ProfileValidator.Validate(yCostProfile).Any((ValidationIssue i) => i.Level == "提示"
						&& i.Message.Contains("已按「这张牌花掉的额外资源量」生成", StringComparison.Ordinal))
					&& !ProfileValidator.Validate(yCostProfile).Any((ValidationIssue i) => i.Level == "警告"
						&& i.Message.Contains("先扣费再跑效果", StringComparison.Ordinal)),
					ProfileValidator.Validate(yCostProfile).FirstOrDefault((ValidationIssue i) => i.Message.Contains("花掉的额外资源量"))?.Message ?? "(没报)");
				Check("V0.2.168：用 YSpent 时照旧什么都不报（它和 Y 在这种牌上现在等价）",
					!ProfileValidator.Validate(XSpentProbe()).Any((ValidationIssue i) => i.Level == "警告"
						&& (i.Message.Contains("先扣费再跑效果", StringComparison.Ordinal) || i.Message.Contains("恒为 0", StringComparison.Ordinal))),
					string.Join(" ｜ ", ProfileValidator.Validate(XSpentProbe()).Where((ValidationIssue i) => i.Level == "警告").Select((ValidationIssue i) => i.Message)));
				// ===== V0.2.168：描述栏里**打回车换行**（CRLF）→ 生成端不能留下裸 \r =====
				// 用户实测报的「自定义状态的描述栏中 如果用回车换行会有报错」：
				// WPF 的 TextBox 打回车是 **CRLF**，而生成端往 `/// <summary>…</summary>` 里塞这段文本时
				// 只把 `\n` 换成空格、**留下了 `\r`** —— C# 把单独的 `\r` 也当换行 ⇒ 注释被截断、
				// 后半截（「 第二行描述…」）变成代码 → **整个工程编译不过**。
				{
					Check("V0.2.168：OneLine 把 CRLF / 单独 CR / LF 全压成一行（描述栏打回车不再留裸 \\r）",
						CustomPowerGen.OneLine("第一行\r\n第二行") == "第一行 第二行"
						&& CustomPowerGen.OneLine("第一行\r第二行") == "第一行 第二行"
						&& CustomPowerGen.OneLine("第一行\n第二行") == "第一行 第二行",
						CustomPowerGen.OneLine("第一行\r\n第二行"));
					var mlProfile = ProfileFactory.Sample();
					mlProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					mlProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var mlPower = new CustomPowerSpec
					{
						Name = "自检多行描述", ClassName = "UiCheckMultiLine", Enabled = true,
						Description = "第一行描述\r\n第二行描述",
					};
					mlProfile.CustomPowers.Add(mlPower);
					string mlSrc = CustomPowerGen.Source(mlProfile, mlPower, mlProfile.CustomPowers.Count - 1);
					Check("V0.2.168：自定义状态的多行描述生成出来的 C# 里**没有裸 \\r**（注释不会被截断）",
						!mlSrc.Replace("\r\n", "").Contains('\r', StringComparison.Ordinal)
						&& mlSrc.Contains("第一行描述 第二行描述", StringComparison.Ordinal),
						mlSrc.Replace("\r\n", "").Contains('\r') ? "还有裸 \\r！" : "干净");
					// 卡牌的自定义描述同理（它走 `// CET:CustomDescription=` 标记，换行要转义成 \n）
					var mlCard = new CardSpec { Name = "自检多行卡", ClassName = "UiCheckMultiLineCard", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					mlCard.CustomDescription = "第一行卡描述\r\n第二行卡描述";
					mlCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
					var mlCardProfile = ProfileFactory.Sample();
					mlCardProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					mlCardProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					mlCardProfile.Cards.Add(mlCard);
					string mlCardSrc = CSharpCodeGen.CardSource(mlCardProfile, mlCard, mlCardProfile.Cards.Count - 1);
					Check("V0.2.168：卡牌的多行自定义描述同样不留裸 \\r（标记里转义成 \\n）",
						!mlCardSrc.Replace("\r\n", "").Contains('\r', StringComparison.Ordinal)
						&& mlCardSrc.Contains("CET:CustomDescription=第一行卡描述\\n第二行卡描述", StringComparison.Ordinal),
						mlCardSrc.Replace("\r\n", "").Contains('\r') ? "还有裸 \\r！" : "干净");
				}
				CharacterProfile XSpentProbe()
				{
					var p5 = ProfileFactory.Sample();
					p5.Paths.VanillaProject = Profile.Paths.VanillaProject;
					p5.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var c6 = new CardSpec { Name = "自检用花掉的资源", ClassName = "UiCheckSpentOk", CardType = "Skill", Rarity = "Common", Cost = 1 };
					c6.StarCostText = "Y";
					c6.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", TimesFormula = "YSpent" });
					p5.Cards.Add(c6);
					return p5;
				}
			}

			// ② 额外资源量 + 下回合生效：本体有现成的 StarNextTurnPower（回合开始时 GainStars 再自毁）
			Check("「获得额外资源量」标了支持「下回合生效」",
				EffectCatalog.FindKind("ExtraResource").SupportsNextTurn, "支持");
			// ===== V0.2.133： 「下回合生效」补齐到全部效果（除语义上做不了的那 8 种）=====
			{
				// ① 判据只有一份：EffectKindOption.SupportsNextTurn **就是** HonorsNextTurn
				string[] allKinds = EffectCatalog.EffectKinds.Select((EffectKindOption k) => k.Kind).ToArray();
				Check("「下回合生效」的判据只有一份：每一栏的 SupportsNextTurn 都 == HonorsNextTurn（不会再有「勾了没反应」）",
					allKinds.All((string k) => EffectCatalog.FindKind(k).SupportsNextTurn == EffectCatalog.HonorsNextTurn(k)),
					$"{allKinds.Length} 种逐条相等");
				Check("68 种里只有那 11 种「语义上做不了」的不支持（费用变 0 / 抽到就减费 / 放回手牌 / 本场费用-N / 结束回合 / 额外回合 / 刮削 / 回合结束自动打出 / 播放音效 / 播放音频文件 / 减少卡牌费用）",
					allKinds.Where((string k) => !EffectCatalog.HonorsNextTurn(k)).OrderBy((string k) => k, StringComparer.Ordinal)
						.SequenceEqual(new[] { "CheapenDraw", "CheapenSelf", "CheapenSelfOnDraw", "CostDown", "EndTurn", "ExtraTurn",
							"PlaySfx", "PlaySoundFile", "ReturnSelfToHand", "ScrapeDraw", "TurnEndPlay" }),
					"不支持的是：" + string.Join(" / ", allKinds.Where((string k) => !EffectCatalog.HonorsNextTurn(k))));
				Check("那 11 种在界面上**不显示**勾选框（宁可不显示，也不要「勾了没反应」）",
					new[] { "CheapenSelf", "CheapenSelfOnDraw", "ReturnSelfToHand", "CheapenDraw", "EndTurn", "ExtraTurn",
						"ScrapeDraw", "TurnEndPlay", "PlaySfx", "PlaySoundFile", "CostDown" }.All((string k) => !new EffectSpec { Kind = k }.ShowNextTurn),
					"都不显示");
				// 用户已定的那 8 种「从此生效」：界面上有勾选框，且真的生成了延迟状态
				string[] eightKinds = { "OverdraftEnergy", "DoublePower", "Expose", "ClearPowerOne",
					"ClearPowerDebuffs", "ForbidBlock", "ForbidHeal", "PetAttack" };
				Check("用户 2026-10-10 拍板「从此生效」的那 8 种：判据支持 + 界面上有勾选框（老存档勾过的会真的生效）",
					eightKinds.All((string k) => EffectCatalog.HonorsNextTurn(k) && new EffectSpec { Kind = k }.ShowNextTurn),
					"8 种全部生效");
				Check("这 8 种走的是**通用延迟分支**（不是本体现成的四种，也不是生成类那七种）",
					eightKinds.All((string k) => CSharpCodeGen.IsDelayedEffectKind(k)
						&& !CSharpCodeGen.IsDelayedSpawnKind(k)),
					"通用分支");
				// ② 每一种「支持」的种类都真的生成得出延迟状态类，而且卡这边不再立刻执行
				var notHonored = allKinds.Where((string k) => !EffectCatalog.HonorsNextTurn(k)).ToHashSet(StringComparer.Ordinal);
				var genOk = new List<string>();
				var genBad = new List<string>();
				foreach (string k in allKinds.Where((string k) => !notHonored.Contains(k)))
				{
					CharacterProfile one = ProfileFactory.Sample();
					var c = new CardSpec { Name = "自检" + k, ClassName = "UiCheck133" + k, CardType = "Skill",
						Rarity = "Common", Cost = 1, InCardPool = true };
					var ef = new EffectSpec { Kind = k, Amount = 2m, NextTurn = true, TargetSide = "Self" };
					if (k is "ApplyPower" or "TempPower" or "DoublePower" or "Expose" or "ClearPowerOne"
						or "ForbidBlock" or "ForbidHeal" or "BoostCard" or "PetApplyPower")
						ef.PowerId = "StrengthPower";
					if (k == "GiveKeyword") ef.GivenKeyword = "Exhaust";
					one.Cards.Add(c);
					c.Effects.Add(ef);
					string src = CSharpCodeGen.CardSource(one, c, 0);
					string dp = CSharpCodeGen.DelayedPowersSource(one);
					string cls = Naming.From(one).DelayedPowerClass(ef);
					bool ok = dp.Contains($"public sealed class {cls} : PowerModel")
						&& src.Contains($"PowerCmd.Apply<{cls}>(choiceContext,");
					// 已经真的实现的老路（本体四种 + 生成类七种）不生成「通用延迟类」，但必须挂点东西
					if (!ok && (k is "Block" or "Draw" or "Energy" or "ExtraResource" or "GenerateCard" or "CopyCard"
						or "TransformCard" or "AddCardGlobal" or "TransformCardGlobal" or "RemoveCardGlobal" or "UpgradeCardGlobal"))
						ok = src.Contains("PowerCmd.Apply<") || src.Contains("PlayerCmd.Gain");
					(ok ? genOk : genBad).Add(k);
					// 延迟类名不能撞（每个种类 / 状态 / 作用对象各一个类）
					Check($"延迟类名不重复：{k}", genBad.Count == 0 || !genBad.Contains(k), cls);
				}
				Check("每一种「支持下回合生效」的种类都生成出了对应的延迟状态类（57 种）", genBad.Count == 0,
					genBad.Count == 0 ? $"{genOk.Count} 种全部生成" : "没生成：" + string.Join(" / ", genBad));
				// ③ 出问题的三种必须拦住 + 说清（不再静默）
				foreach (string bad in new[] { "ScrapeDraw", "EndTurn", "CheapenSelf" })
				{
					CharacterProfile bp = ProfileFactory.Sample();
					var bc = new CardSpec { Name = "自检不支持" + bad, ClassName = "UiCheck133Bad" + bad, CardType = "Skill",
						Rarity = "Common", Cost = 1, InCardPool = true };
					bc.Effects.Add(new EffectSpec { Kind = bad, Amount = 1m, NextTurn = true });
					bp.Cards.Add(bc);
					Check($"校验器：给语义上做不了延迟的「{bad}」勾了下回合生效 → 报错说清（不是静默失效）",
						ProfileValidator.Validate(bp).Any((ValidationIssue i) => i.IsError && i.Message.Contains("不支持「下回合生效」")),
						ProfileValidator.Validate(bp).FirstOrDefault((ValidationIssue i) => i.Message.Contains("不支持「下回合生效」"))?.Message ?? "(没报)");
				}
				// ④ 遗物 / 药水 / 自定义状态那三条链也接了（V0.2.133 之前只做在卡牌上、会拦住）
				CharacterProfile rp = ProfileFactory.Sample();
				string[] probeKinds = { "Damage", "Heal", "Gold", "Stun", "ForbidBlock", "Scry", "FillHand", "GiveKeyword" };
				foreach (string k in probeKinds)
				{
					var r = new RelicSpec { Name = "自检遗物" + k, ClassName = "UiCheck133R" + k, Rarity = "Common", Trigger = "PlayerTurnStart" };
					var re = new EffectSpec { Kind = k, Amount = 2m, NextTurn = true, TargetSide = "Self" };
					if (k == "GiveKeyword") re.GivenKeyword = "Exhaust";
					r.Effects.Add(re);
					rp.Relics.Add(r);
					Check($"遗物链也能「下回合生效」：{k}（不再被校验器拦住）",
						CSharpCodeGen.RelicSource(rp, r, rp.Relics.Count - 1).Contains("PowerCmd.Apply<")
						&& !ProfileValidator.Validate(rp).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只支持做在**卡牌**上")),
						"遗物链接上了");
				}
				// ⑤ 老存档口径：那 8 种之外，任何种类都不许改变老存档的输出 ——
				//    这些种类在 V0.2.132 及以前**界面上根本没有勾选框**，所以老存档里必然 NextTurn=false；
				//    这里断言「NextTurn=false 时生成端一个字都不变」（走的是原来那条路）。
				CharacterProfile offProbe = ProfileFactory.Sample();
				var offCard = new CardSpec { Name = "自检没勾", ClassName = "UiCheck133Off", CardType = "Skill",
					Rarity = "Common", Cost = 1, InCardPool = true };
				offCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 7m, TargetSide = "Enemy", NextTurn = false });
				offProbe.Cards.Add(offCard);
				string offSrc = CSharpCodeGen.CardSource(offProbe, offCard, 0);
				Check("没勾「下回合生效」的效果走的是老路径（立刻打伤害，不挂延迟状态）",
					offSrc.Contains("DamageCmd.Attack") && !offSrc.Contains("ForgeDelayed"),
					"老路径");
			}
			// 「下回合生效」现在只对**真的实现了延迟分支**的五种放行、并在界面上只给它们显示勾选框）"
			// 以前有 8 个种类写着支持但生成端没有延迟分支 → 勾了等于没勾（用户报过「勾了没反应」）。"
			{
				Check("老五种（格挡 / 抽牌 / 能量 / 额外资源量 / 施加状态）仍然走本体现成的那套",
					new[] { "Block", "Draw", "Energy", "ExtraResource", "ApplyPower" }
						.All((string k) => EffectCatalog.HonorsNextTurn(k) && !CSharpCodeGen.IsDelayedEffectKind(k)),
					"本体现成");
				CharacterProfile ntProbe = ProfileFactory.Sample();
				CardSpec ntCard = new CardSpec { Name = "自检下回合刮削", ClassName = "UiCheckNextTurnScry", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				ntCard.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 2m, NextTurn = true });
				ntProbe.Cards.Add(ntCard);
				Check("校验器：给语义上做不了延迟的「刮削」勾了下回合生效 → 报错并说清（不是静默失效）",
					ProfileValidator.Validate(ntProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("不支持「下回合生效」")),
					ProfileValidator.Validate(ntProbe).FirstOrDefault((ValidationIssue i) => i.Message.Contains("不支持「下回合生效」"))?.Message ?? "(没报)");
				// ===== 生成类效果的「下回合生效」（用户要求：生成卡牌之类也要能下回合）=====
				Check("生成类里支持「下回合生效」的是：生成卡牌 / 复制卡牌 / 变化卡牌 / 获得·变化·删除·升级牌组（全局）—— 齐了",
					EffectCatalog.HonorsNextTurn("GenerateCard") && EffectCatalog.HonorsNextTurn("AddCardGlobal")
					&& EffectCatalog.HonorsNextTurn("TransformCardGlobal") && EffectCatalog.HonorsNextTurn("RemoveCardGlobal")
					&& EffectCatalog.HonorsNextTurn("UpgradeCardGlobal") && EffectCatalog.HonorsNextTurn("CopyCard")
					&& EffectCatalog.HonorsNextTurn("TransformCard"),
					"对");
				Check("延迟类名的种类前缀各不一样（不然多个生成类会撞成同一个 ForgeDelayedPower）",
					CSharpCodeGen.IsDelayedSpawnKind("GenerateCard") && CSharpCodeGen.IsDelayedSpawnKind("AddCardGlobal")
					&& CSharpCodeGen.IsDelayedSpawnKind("CopyCard") && CSharpCodeGen.IsDelayedSpawnKind("TransformCard")
					&& !CSharpCodeGen.IsDelayedSpawnKind("Scry"),
					"前缀分开");
				{
					CharacterProfile dsProbe = ProfileFactory.Sample();
					CardSpec dsGenCard = new CardSpec { Name = "自检下回合生成", ClassName = "UiCheckDelayedGen", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					dsGenCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 2m, SpawnCardId = "Shiv", NextTurn = true });
					dsProbe.Cards.Add(dsGenCard);
					string dsGenSrc = CSharpCodeGen.CardSource(dsProbe, dsGenCard, 0);
					string dsDelayed = CSharpCodeGen.DelayedPowersSource(dsProbe);
					Check("勾了下回合生效的「生成卡牌」：卡这边只挂延迟状态（不再立刻生成），状态类里才是生成代码",
						dsGenSrc.Contains("PowerCmd.Apply<SevenForgeDelayedGenShiv>(choiceContext, base.Owner.Creature, base.DynamicVars.Cards.BaseValue")
						&& !dsGenSrc.Contains("AddToCombatAndPreview<MegaCrit.Sts2.Core.Models.Cards.Shiv>")
						&& dsDelayed.Contains("public sealed class SevenForgeDelayedGenShiv : PowerModel")
						&& dsDelayed.Contains("AddToCombatAndPreview<MegaCrit.Sts2.Core.Models.Cards.Shiv>(base.Owner, PileType.Hand, base.Amount, base.Owner.Player)"),
						"延迟里生成");
					Check("延迟状态里有「下回合开始时 / 层数当张数 / 用完自毁 / 回读标记 CET:DelayedSpawn=」",
						dsDelayed.Contains("AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)")
						&& dsDelayed.Contains("if (player != base.Owner.Player || base.Amount <= 0) return;")
						&& dsDelayed.Contains("await PowerCmd.Remove(this);")
						&& dsDelayed.Contains("// CET:DelayedSpawn=GenerateCard"), "都对");
					// 生成 → 真编译 → 回读（回读靠类名尾巴还原卡名 + 标记行还原张数 范围）"
					string dsRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_delayeds_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					try
					{
						dsProbe.Paths.OutputDir = dsRoot;
						dsProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
						dsProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
						var dsGen = ModGenerator.Generate(dsProbe);
						Check("（准备）带「下回合生成卡牌」的存档能生成工程", dsGen.Success, dsGen.ProjectRoot);
						var dsRec = ProjectRecovery.FromProject(dsGen.ProjectRoot);
						var dsRecCard = dsRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckDelayedGen");
						Check("从工程恢复：下回合生成卡牌的「种类 / 下回合 / 目标卡 / 张数」都认得回来",
							dsRecCard is not null && dsRecCard.Effects.Any((EffectSpec x) =>
								x.Kind == "GenerateCard" && x.NextTurn && x.SpawnCardId == "Shiv" && x.Amount == 2m),
							dsRecCard is null ? "(没找回这张卡)" : string.Join(" / ", dsRecCard.Effects.Select((EffectSpec x) => x.Kind + " n=" + x.NextTurn + " card=" + x.SpawnCardId + " amt=" + x.Amount)));
						Check("从工程恢复（带下回合生成）：没认出来的语句为 0", !dsRec.HasUnparsed, dsRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
					finally
					{
						try { Directory.Delete(dsRoot, true); } catch { }
					}
					// 遗物 / 药水 / 状态上还没有延迟链 → 必须拦住
					CharacterProfile dsRelicProbe = ProfileFactory.Sample();
					var dsRelic = new RelicSpec { Name = "自检下回合生成遗物", ClassName = "UiCheckDelayedRelic", Rarity = "Common", Trigger = "PlayerTurnStart" };
					dsRelic.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", NextTurn = true });
					dsRelicProbe.Relics.Add(dsRelic);
					Check("V0.2.133：遗物上的「生成类 + 下回合生效」也不再被拦住（三条链都接了通用延迟）",
						!ProfileValidator.Validate(dsRelicProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只支持做在**卡牌**上")),
						"不再拦住");
					// ⚠ 已知边界：遗物链上的**生成类**（GenerateCard 等七种）还没接上延迟分支
					//   （那七种的延迟状态里拿不到「这张牌」）—— 只接上了**通用延迟分支**的那些种类。
					var dsRelic2 = new RelicSpec { Name = "自检下回合遗物伤害", ClassName = "UiCheckDelayedRelic2", Rarity = "Common", Trigger = "PlayerTurnStart" };
					dsRelic2.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "AllEnemies", NextTurn = true });
					dsRelicProbe.Relics.Add(dsRelic2);
					Check("V0.2.133：遗物链接上了通用延迟（「造成伤害 + 下回合生效」挂的是延迟状态）",
						CSharpCodeGen.RelicSource(dsRelicProbe, dsRelic2, dsRelicProbe.Relics.Count - 1).Contains("PowerCmd.Apply<"),
						"遗物链接上了");
				}
			}
			CharacterProfile starProbe = ProfileFactory.Sample();
			CardSpec starNext = new CardSpec { Name = "自检下回合资源", ClassName = "UiCheckStarNext", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			starNext.Effects.Add(new EffectSpec { Kind = "ExtraResource", Amount = 3m, NextTurn = true });
			starProbe.Cards.Add(starNext);
			string starNextSrc = CSharpCodeGen.CardSource(starProbe, starNext, 0);
			Check("额外资源量 + 下回合生效 → 生成本体 StarNextTurnPower（不是立即 GainStars）",
				starNextSrc.Contains("PowerCmd.Apply<StarNextTurnPower>(choiceContext, base.Owner.Creature, base.DynamicVars.Stars.BaseValue, base.Owner.Creature, this)")
				&& !starNextSrc.Contains("PlayerCmd.GainStars"), "对");
			Check("卡面描述写「下回合开始时，获得 …点…」",
				LocalizationGen.CardsJson(starProbe).Contains("下回合开始时，获得 {Stars:diff()} 点额外资源量"), "描述对");
			var starIssues = ProfileValidator.Validate(starProbe);
			Check("校验器不再报「不支持下回合生效」错，而是给一句「下回合开始时发放」提示",
				!starIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("不支持「下回合生效」"))
				&& starIssues.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("下回合开始时**获得")), "对");
			// 负数（= 卡牌费用「需要 N 点」）+ 下回合生效：给警告说清会被忽略
			CharacterProfile starNegProbe = ProfileFactory.Sample();
			CardSpec starNeg = new CardSpec { Name = "自检下回合花费", ClassName = "UiCheckStarNeg", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			starNeg.Effects.Add(new EffectSpec { Kind = "ExtraResource", Amount = -2m, NextTurn = true });
			starNegProbe.Cards.Add(starNeg);
			var starNegIssues = ProfileValidator.Validate(starNegProbe);
			Check("「需要 N 点」+ 下回合生效 → 警告说清费用跟下回合无关、这一勾会被忽略",
				starNegIssues.Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("费用和「下回合生效」没关系")), "警告在");
			Check("这种（负数）情况生成的还是费用判定，不会去挂 StarNextTurnPower（本体 GainStars 拒绝负数）",
				!CSharpCodeGen.CardSource(starNegProbe, starNeg, 0).Contains("StarNextTurnPower"), "没挂");
			// 遗物也支持
			CharacterProfile starRelicProbe = ProfileFactory.Sample();
			starRelicProbe.Relics.Add(new RelicSpec
			{
				Name = "自检下回合资源遗物", ClassName = "UiCheckStarNextRelic", Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "ExtraResource", Amount = 2m, NextTurn = true } },
			});
			Check("遗物上的「获得额外资源量 + 下回合生效」也走 StarNextTurnPower",
				CSharpCodeGen.RelicSource(starRelicProbe, starRelicProbe.Relics[^1], 0).Contains("PowerCmd.Apply<StarNextTurnPower>"), "对");
			// 生成 → 回读
			string starRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_starnext_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile starGenProbe = ProfileFactory.Sample();
				starGenProbe.Paths.OutputDir = starRoot;
				starGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				starGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec genStarNext = new CardSpec { Name = "自检下回合资源", ClassName = "UiCheckStarNext", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				genStarNext.Effects.Add(new EffectSpec { Kind = "ExtraResource", Amount = 3m, NextTurn = true });
				starGenProbe.Cards.Add(genStarNext);
				Check("（准备）额外资源量 + 下回合生效的存档能生成工程", ModGenerator.Generate(starGenProbe).Success, starRoot);
				var starRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(starGenProbe));
				var recStarNext = starRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckStarNext");
				Check("回读：额外资源量 + 下回合生效原样回来",
					recStarNext is not null && recStarNext.Effects.Any((EffectSpec e) => e.Kind == "ExtraResource" && e.NextTurn && e.Amount == 3m),
					recStarNext is null ? "(没回读出来)" : string.Join(" / ", recStarNext.Effects.Select((EffectSpec e) => $"{e.Kind} {e.Amount} 下回合={e.NextTurn}")));
				Check("回读没有认不出来的语句", !starRec.HasUnparsed, starRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(starRoot)) Directory.Delete(starRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：自定义关键词当「卡的组」+ 生成卡牌「多选1」+「复制卡牌」+ 遗物「获得时」 =====
		{
			// ① 自定义关键词 = 一套可复用的「卡的组」：范围限定里每个关键词多一条选项，
			//    按它随机生成时把这一组牌列成**显式牌表**（关键词只是我们自己的文案 + 悬停提示，
			//    游戏的 CardKeyword 是封闭枚举，运行时过滤不出来 —— 只能在生成期按配置查）。
			CharacterProfile kwProbe = ProfileFactory.Sample();
			kwProbe.CustomKeywords.Clear();
			kwProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运" });
			kwProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "ECHO", Name = "回声" });
			CardSpec kwA = new CardSpec { Name = "自检命运一", ClassName = "UiCheckFateA", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			kwA.KeywordIds.Add("FATE");
			CardSpec kwB = new CardSpec { Name = "自检命运二", ClassName = "UiCheckFateB", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			kwB.KeywordIds.Add("FATE");
			CardSpec kwC = new CardSpec { Name = "自检不分组", ClassName = "UiCheckFateC", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			CardSpec kwGen = new CardSpec { Name = "自检按组生成", ClassName = "UiCheckFateGen", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			kwGen.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Keyword:FATE", SpawnTo = "Hand" });
			kwProbe.Cards.Add(kwA);
			kwProbe.Cards.Add(kwB);
			kwProbe.Cards.Add(kwC);
			kwProbe.Cards.Add(kwGen);

			var kwFilters = EffectCatalog.SpawnFiltersFor(kwProbe);
			Check("「范围限定」的候选 = 内置 7 条 + 每个自定义关键词一组（把关键词当卡的组用）",
				kwFilters.Count == 9
				&& kwFilters.Take(7).Select((SpawnFilterOption f) => f.Id).SequenceEqual(new[] { "", "Attack", "Skill", "Power", "Curse", "Status", "Quest" })
				&& kwFilters.Any((SpawnFilterOption f) => f.Id == "Keyword:FATE" && f.Zh == "命运" && f.Display.Contains("那一组牌")),
				string.Join("/", kwFilters.Select((SpawnFilterOption f) => f.Id)));
			Check("这一组里有哪些牌能在生成期查出来（只算自己的牌，本体卡带不了自定义关键词）",
				EffectCatalog.KeywordGroupCards(kwProbe, "Keyword:FATE").Count == 2
				&& EffectCatalog.KeywordGroupCards(kwProbe, "Keyword:FATE").All((CardSpec c) => c.ClassName is "UiCheckFateA" or "UiCheckFateB"),
				string.Join("/", EffectCatalog.KeywordGroupCards(kwProbe, "Keyword:FATE").Select((CardSpec c) => c.ClassName)));
			Check("「Keyword:XXX」这种范围限定认得出来（Id 前缀 + 取键 + 不管大小写）",
				EffectCatalog.IsKeywordFilter("Keyword:FATE") && !EffectCatalog.IsKeywordFilter("Attack")
				&& EffectCatalog.KeywordFilterKey("Keyword:FATE") == "FATE", "认得出");
			string kwSrc = CSharpCodeGen.CardSource(kwProbe, kwGen, 0);
			Check("按关键词组随机生成 → 直接列出这一组牌（走 GetDistinctForCombat 抽，不重复）",
				kwSrc.Contains("var __genPool = new List<CardModel> { ModelDb.Card<UiCheckFateA>(), ModelDb.Card<UiCheckFateB>() };")
				&& kwSrc.Contains("CardFactory.GetDistinctForCombat(base.Owner, __genPool, 1,"), "显式牌表");
			Check("卡面描述里写的是这一组的名字（「命运」），不是「不限」",
				LocalizationGen.CardsJson(kwProbe).Contains("「命运」"), "描述对");
			// 登记表（没有 profile 参数的地方靠它显示中文名）
			EffectCatalog.SetCustomKeywords(new[] { ("FATE", "命运") });
			Check("登记表能让 SpawnFilterZh 显示出关键词的中文名", EffectCatalog.SpawnFilterZh("Keyword:FATE") == "命运", EffectCatalog.SpawnFilterZh("Keyword:FATE"));
			Check("范围限定的候选序列化进存档（回读才能原样回来）",
				System.Text.Json.JsonSerializer.Serialize(kwGen.Effects[0]).Contains("Keyword:FATE"), "写进 JSON 了");
			// 空组：选了关键词分组但没有任何牌带它 → 报错（不然效果什么都不做，用户以为没生效）
			CharacterProfile kwEmptyProbe = ProfileFactory.Sample();
			kwEmptyProbe.CustomKeywords.Clear();
			kwEmptyProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "VOID", Name = "虚空" });
			CardSpec kwEmptyCard = new CardSpec { Name = "自检空组", ClassName = "UiCheckEmptyGroup", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			kwEmptyCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Keyword:VOID" });
			kwEmptyProbe.Cards.Add(kwEmptyCard);
			Check("选了关键词分组但一张牌都没带这个关键词 → 报错拦住（这一组是空的）",
				ProfileValidator.Validate(kwEmptyProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("这一组是空的")), "拦住了");
			// 生成 → 回读：`Keyword:FATE` 里的冒号不能被老正则（\w）截断
			string kwRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_kwgroup_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile kwGenProbe = ProfileFactory.Sample();
				kwGenProbe.Paths.OutputDir = kwRoot;
				kwGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				kwGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				kwGenProbe.CustomKeywords.Clear();
				kwGenProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运" });
				CardSpec genFate = new CardSpec { Name = "自检命运牌", ClassName = "UiCheckFateCard", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				genFate.KeywordIds.Add("FATE");
				CardSpec genFateGen = new CardSpec { Name = "自检按组生成", ClassName = "UiCheckFateGen", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				genFateGen.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Keyword:FATE", SpawnTo = "Hand", SpawnChoice = 3m });
				kwGenProbe.Cards.Add(genFate);
				kwGenProbe.Cards.Add(genFateGen);
				Check("（准备）关键词分组 + 多选1 的存档能生成工程", ModGenerator.Generate(kwGenProbe).Success, kwRoot);
				var kwRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(kwGenProbe));
				var recFateGen = kwRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckFateGen");
				var recFate = recFateGen?.Effects.FirstOrDefault((EffectSpec e) => e.Kind == "GenerateCard");
				Check("回读：范围限定 Keyword:FATE 原样回来（老正则 \\w 会把冒号截掉 → 变回「不限」）",
					recFate is not null && recFate.SpawnFilter == "Keyword:FATE" && recFate.SpawnPick == "Random",
					$"Filter={recFate?.SpawnFilter} Pick={recFate?.SpawnPick}");
				Check("回读：多选1 的候选张数（数值 = 1 = 只生成一张）；两组候选的标记都带回来了",
					recFate is not null && recFate.SpawnChoice == 3m && recFate.Amount == 1m,
					$"SpawnChoice={recFate?.SpawnChoice} Amount={recFate?.Amount}");
				Check("回读没有认不出来的语句", !kwRec.HasUnparsed, kwRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(kwRoot)) Directory.Delete(kwRoot, true); } catch { }
				RefreshCustomKeywordRegistry();   // 登记表还原成真实配置（自检改过它）
			}

			// ② 生成卡牌「多选1」：候选 ≤ 3 走本体的「发现」界面（FromChooseACardScreen 超过 3 张会抛异常），
			//    > 3 走网格选牌（本体「抉择悖论 ChoicesParadox」那种），提示语读 <卡>.selectionScreenPrompt。
			CharacterProfile chProbe = ProfileFactory.Sample();
			CardSpec chCard = new CardSpec { Name = "自检多选一", ClassName = "UiCheckChoice", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			chCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 3m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnChoice = 3m, SpawnTo = "Hand" });
			CardSpec chBig = new CardSpec { Name = "自检多选五大", ClassName = "UiCheckChoiceBig", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			chBig.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 5m, SpawnPick = "Random", SpawnFilter = "Skill", SpawnChoice = 5m, SpawnTo = "Hand" });
			chProbe.Cards.Add(chCard);
			chProbe.Cards.Add(chBig);
			string chSrc = CSharpCodeGen.CardSource(chProbe, chCard, 0);
			string chBigSrc = CSharpCodeGen.CardSource(chProbe, chBig, 0);
			Check("多选1（候选 3 张）：先抽 3 张候选 → 本体「发现」的界面 → 只生成选中的那一张",
				chSrc.Contains("List<CardModel> __candidates = MegaCrit.Sts2.Core.Factories.CardFactory.GetDistinctForCombat(base.Owner, __genPool, 3,")
				&& chSrc.Contains("CardModel? __picked = await CardSelectCmd.FromChooseACardScreen(choiceContext, __candidates, base.Owner, canSkip: false);")
				&& chSrc.Contains("await CardPileCmd.AddGeneratedCardToCombat(__picked, PileType.Hand, base.Owner);")
				&& !chSrc.Contains("foreach (CardModel __gen in"), "对");
			Check("多选1（候选 > 3 张）：本体 FromChooseACardScreen 超过 3 张会直接抛异常 → 改走网格选牌 + <卡>.selectionScreenPrompt",
				chBigSrc.Contains("CardSelectCmd.FromSimpleGrid(choiceContext, __candidates, base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, 1))")
				&& chBigSrc.Contains(").FirstOrDefault();"), "对");
			Check("多选1 外面有「候选一张都没有就整条跳过」的守卫（本体这一步是 ReportSoftlock = 卡死）",
				chSrc.Contains("if (__candidates.Count > 0)") && chSrc.Contains("if (__picked is not null)"), "有守卫");
			Check("多选1 一定生成 <卡>.selectionScreenPrompt（本体 SelectionScreenPrompt 键不存在时直接抛异常 → 游戏卡死）",
				LocalizationGen.NeedsSelectPrompt(chCard.Effects)
				&& LocalizationGen.CardsJson(chProbe).Contains("UI_CHECK_CHOICE.selectionScreenPrompt"), "有提示语");
			Check("多选1 的提示语跟着候选张数走（「从 N 张中选一张」）",
				LocalizationGen.SelectPromptText(chCard.Effects) == "从 3 张中选一张", LocalizationGen.SelectPromptText(chCard.Effects));
			Check("多选1 的卡面描述写「从 3 张『攻击』中选一张生成」，不写成「生成 3 张」",
				LocalizationGen.CardsJson(chProbe).Contains("从 3 张「攻击」中选一张生成"), "描述对");
			Check("默认（候选张数 = 1）还是原来那条「生成 N 张」的路，界面输入框只在「生成 / 变化卡牌 + 按范围随机」出现",
				new EffectSpec { Kind = "GenerateCard" }.SpawnChoice == 1m
				&& !new EffectSpec { Kind = "GenerateCard" }.ShowSpawnChoice
				&& new EffectSpec { Kind = "GenerateCard", SpawnPick = "Random" }.ShowSpawnChoice
				// V0.2.150：按机械测量把「多选1」也摆到另外三种「按范围随机」的种类上
				// （生成端真的读 SpawnChoice；以前只在「生成卡牌」上摆着，变化 / 全局加牌那几种填不了）
				&& new EffectSpec { Kind = "TransformCard", SpawnPick = "Random" }.ShowSpawnChoice
				&& new EffectSpec { Kind = "AddCardGlobal", SpawnPick = "Random" }.ShowSpawnChoice
				&& !new EffectSpec { Kind = "ExhaustCard", SpawnPick = "Random" }.ShowSpawnChoice, "显隐对");
			// 多选1 + 指定卡：没意义 → 警告
			CharacterProfile chFixedProbe = ProfileFactory.Sample();
			CardSpec chFixed = new CardSpec { Name = "自检多选指定", ClassName = "UiCheckChoiceFixed", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			chFixed.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnCardId = "Shiv", SpawnChoice = 3m });
			chFixedProbe.Cards.Add(chFixed);
			Check("取卡方式是「指定卡」时多选1 会被忽略 → 给警告（几张候选都是同一张，没意义）",
				ProfileValidator.Validate(chFixedProbe).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("多选1 不会生效")), "有警告");
			// 生成 → 回读
			string chRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_choice_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile chGenProbe = ProfileFactory.Sample();
				chGenProbe.Paths.OutputDir = chRoot;
				chGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				chGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec genChoice = new CardSpec { Name = "自检多选一", ClassName = "UiCheckChoice", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				genChoice.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 3m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnChoice = 3m, SpawnTo = "Hand", SpawnUpgraded = true });
				chGenProbe.Cards.Add(genChoice);
				Check("（准备）多选1 的存档能生成工程", ModGenerator.Generate(chGenProbe).Success, chRoot);
				var chRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(chGenProbe));
				var recChoice = chRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckChoice")?.Effects
					.FirstOrDefault((EffectSpec e) => e.Kind == "GenerateCard");
				Check("回读：多选1（候选 3 张）+ 附加处理原样回来，而且「数值」= 1（不是候选张数 3）",
					recChoice is not null && recChoice.SpawnChoice == 3m && recChoice.IsSpawnRandom
					&& recChoice.SpawnFilter == "Attack" && recChoice.SpawnUpgraded && recChoice.Amount == 1m,
					$"Choice={recChoice?.SpawnChoice} Amount={recChoice?.Amount} Up={recChoice?.SpawnUpgraded}");
				Check("回读没有认不出来的语句", !chRec.HasUnparsed, chRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(chRoot)) Directory.Delete(chRoot, true); } catch { }
			}

			// ③ 新效果「复制卡牌」：数值 = 选几张，效果底下还有一个「复制的份数」（只有它才出现）。
			//    实现照本体「二刀流 DualWield」：CreateClone + 加进手牌。
			Check("「复制卡牌」这种效果种类在列表里（而且只有它显示「复制的份数」那一栏）",
				EffectCatalog.EffectKinds.Any((EffectKindOption k) => k.Kind == "CopyCard")
				&& new EffectSpec { Kind = "CopyCard" }.ShowCopies
				&& !new EffectSpec { Kind = "GenerateCard" }.ShowCopies, "在");
			CharacterProfile copyProbe = ProfileFactory.Sample();
			CardSpec cpCard = new CardSpec { Name = "自检复制", ClassName = "UiCheckCopy", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			cpCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, Copies = 2, CardPick = "Chosen", SelectPile = "Hand" });
			CardSpec cpRandCard = new CardSpec { Name = "自检复制随机", ClassName = "UiCheckCopyRand", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			cpRandCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 2m, Copies = 1, CardPick = "Random", SelectPile = "Draw" });
			copyProbe.Cards.Add(cpCard);
			copyProbe.Cards.Add(cpRandCard);
			string cpSrc = CSharpCodeGen.CardSource(copyProbe, cpCard, 0);
			string cpRandSrc = CSharpCodeGen.CardSource(copyProbe, cpRandCard, 0);
			Check("复制卡牌（自己选）：选出来的每张克隆「复制的份数」份放进手牌（本体 CreateClone + AddGeneratedCardToCombat）",
				cpSrc.Contains("new CardSelectorPrefs(base.SelectionScreenPrompt, 1)")
				&& cpSrc.Contains("foreach (CardModel __src in __copyFrom)")
				&& cpSrc.Contains("for (int __copyIdx = 0; __copyIdx < 2; __copyIdx++)")
				&& cpSrc.Contains("CardModel __clone = __src.CreateClone();")
				&& cpSrc.Contains("await CardPileCmd.AddGeneratedCardToCombat(__clone, PileType.Hand, base.Owner);"), "对");
			Check("复制卡牌（随机）：从选定那一摞随机拿，同样每张复制 N 份",
				cpRandSrc.Contains("PileType.Draw.GetPile(base.Owner).Cards")
				&& cpRandSrc.Contains("for (int __copyPickIdx = 0; __copyPickIdx < 2; __copyPickIdx++)")
				&& cpRandSrc.Contains("CardModel __clone = __src.CreateClone();"), "对");
			Check("复制卡牌的卡面描述写清「每张复制几份」",
				LocalizationGen.CardsJson(copyProbe).Contains("每张复制 2 份到手牌"), "描述对");
			Check("复制卡牌自己选牌 → 也会生成 <卡>.selectionScreenPrompt（不然本体直接抛异常、游戏卡死）",
				LocalizationGen.NeedsSelectPrompt(cpCard.Effects)
				&& LocalizationGen.CardsJson(copyProbe).Contains("UI_CHECK_COPY.selectionScreenPrompt"), "有提示语");
			// 校验器：份数 / 张数范围 + 遗物上用不了
			CharacterProfile cpBadProbe = ProfileFactory.Sample();
			CardSpec cpBad = new CardSpec { Name = "自检复制越界", ClassName = "UiCheckCopyBad", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			cpBad.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 9m, Copies = 99 });
			cpBadProbe.Cards.Add(cpBad);
			var cpBadIssues = ProfileValidator.Validate(cpBadProbe);
			Check("复制卡牌的「张数 / 复制的份数」超出范围会报错",
				cpBadIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("「复制卡牌」张数"))
				&& cpBadIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("复制的份数")), "报错了");
			CharacterProfile cpRelicProbe = ProfileFactory.Sample();
			cpRelicProbe.Relics.Add(new RelicSpec
			{
				Name = "自检复制遗物", ClassName = "UiCheckCopyRelic", Trigger = "CombatStart",
				Effects = { new EffectSpec { Kind = "CopyCard", Amount = 1m, Copies = 1 } },
			});
			Check("复制卡牌放在遗物上 → 生成时给一句「用不了」的注释，校验器也警告（不静默丢）",
				CSharpCodeGen.RelicSource(cpRelicProbe, cpRelicProbe.Relics[^1], 0).Contains("遗物上用不了")
				&& ProfileValidator.Validate(cpRelicProbe).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("复制卡牌")), "有说明");
			Check("复制卡牌在药水上能用（喝药水复制）",
				CSharpCodeGen.PotionSource(copyProbe, new PotionSpec
				{
					Name = "自检复制药水", ClassName = "UiCheckCopyPotion", Rarity = "Common",
					Effects = { new EffectSpec { Kind = "CopyCard", Amount = 1m, Copies = 2, SelectPile = "Hand" } },
				}, 0).Contains("__src.CreateClone()"), "药水支持");
			// 生成 → 回读
			string cpRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_copy_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile cpGenProbe = ProfileFactory.Sample();
				cpGenProbe.Paths.OutputDir = cpRoot;
				cpGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				cpGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec genCopy = new CardSpec { Name = "自检复制", ClassName = "UiCheckCopy", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				genCopy.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, Copies = 3, CardPick = "Random", SelectPile = "Discard" });
				cpGenProbe.Cards.Add(genCopy);
				Check("（准备）复制卡牌的存档能生成工程", ModGenerator.Generate(cpGenProbe).Success, cpRoot);
				var cpRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(cpGenProbe));
				var recCopy = cpRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckCopy")?.Effects
					.FirstOrDefault((EffectSpec e) => e.Kind == "CopyCard");
				Check("回读：复制卡牌的张数 / 复制的份数 / 选牌方式 / 哪一摞都原样回来",
					recCopy is not null && recCopy.Amount == 1m && recCopy.Copies == 3 && recCopy.CardPick == "Random" && recCopy.SelectPile == "Discard",
					$"Amount={recCopy?.Amount} Copies={recCopy?.Copies} Pick={recCopy?.CardPick} Pile={recCopy?.SelectPile}");
				Check("回读没有认不出来的语句", !cpRec.HasUnparsed, cpRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(cpRoot)) Directory.Delete(cpRoot, true); } catch { }
			}

			// ① 5 遗物触发时机多一条「战斗结束时（房间结算之前）」（用户要求）"
			Check("遗物触发时机里有「战斗结束时（房间结算之前）」（本体 AfterCombatEnd）",
				EffectCatalog.RelicTriggers.Any((TriggerOption t) => t.Id == "CombatEnd" && t.Display.Contains("战斗结束时"))
				&& CSharpCodeGen.RelicTriggerSignature("CombatEnd") == "public override async Task AfterCombatEnd(CombatRoom room)",
				"CSharpCodeGen.RelicTriggerSignature(\"CombatEnd\")");
			Check("「战斗结束时」没有 choiceContext（和「战斗胜利时」一样，召唤伙伴那类效果会按老规矩被拦住并说明）",
				!CSharpCodeGen.HasContext("CombatEnd") && !CSharpCodeGen.CanBootstrapContext("CombatEnd"), "没有上下文");
			{
				CharacterProfile ceProbe = ProfileFactory.Sample();
				var ceRelic = new RelicSpec
				{
					Name = "自检战斗结束遗物", ClassName = "UiCheckCombatEnd", Rarity = "Common", InRelicPool = true, Trigger = "CombatEnd",
					Effects = { new EffectSpec { Kind = "Gold", Amount = 5m, TargetSide = "Self" } },
				};
				ceProbe.Relics.Add(ceRelic);
				string ceSrc = CSharpCodeGen.RelicSource(ceProbe, ceRelic, ceProbe.Relics.Count - 1);
				Check("生成的是 AfterCombatEnd(CombatRoom room) 钩子，并且写了「// 触发时机：战斗结束时（房间结算之前）」",
					ceSrc.Contains("public override async Task AfterCombatEnd(CombatRoom room)")
					&& ceSrc.Contains("// 触发时机：战斗结束时（房间结算之前）"), "钩子对");
				// 生成 → 回读：这条时机和「每场战斗只触发一次」的清理钩子是同一个 AfterCombatEnd）"
				// 所以回读要靠类里那句「触发时机」注释兜底（探针实测认得回来）"
				string ceRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_combatend_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					ceProbe.Paths.OutputDir = ceRoot;
					ceProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
					ceProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var ceGen = ModGenerator.Generate(ceProbe);
					Check("（准备）带「战斗结束时」遗物的存档能生成工程", ceGen.Success, ceGen.ProjectRoot);
					var ceRec = ProjectRecovery.FromProject(ceGen.ProjectRoot);
					var ceRecRelic = ceRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == "UiCheckCombatEnd");
					Check("从工程恢复：「战斗结束时」这个时机认得回来（靠注释兜底，不会误认成「战斗胜利时」）",
						ceRecRelic is not null && ceRecRelic.Trigger == "CombatEnd" && ceRecRelic.Effects.Count == 1,
						ceRecRelic is null ? "(没找回这只遗物 " : ceRecRelic.Trigger + " / 效果 " + ceRecRelic.Effects.Count + " 条");
					Check("从工程恢复（带战斗结束时）：没认出来的语句为 0", !ceRec.HasUnparsed, ceRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
				finally
				{
					try { Directory.Delete(ceRoot, true); } catch { }
				}
			}

			// ① 遗物 / 状态的新触发时机（用户要求：每下攻击 / 每点能量 / 每点资源量 / 生成卡牌）"
			foreach (var (id, hook, hasCtx, bootstrap, perPoint) in new[]
			{
				("DamageDealt",   "AfterDamageGiven(PlayerChoiceContext choiceContext, Creature? dealer, DamageResult result, ValueProp props, Creature target, CardModel? cardSource)", true,  false, false),
				("EnergySpent",   "AfterEnergySpent(CardModel card, int amount)",                                                                                        false, true,  true),
				("StarsSpent",    "AfterStarsSpent(int amount, Player spender)",                                                                                          false, true,  true),
				("CardGenerated", "AfterCardGeneratedForCombat(CardModel card, Player? creator)",                                                                         false, true,  false),
			})
			{
				TriggerOption? opt = EffectCatalog.RelicTriggers.FirstOrDefault((TriggerOption t) => t.Id == id);
				Check($"遗物触发时机里有「{id}」（{opt?.Display ?? "?"}）",
					opt is not null && CSharpCodeGen.RelicTriggerSignature(id) == "public override async Task " + hook, opt?.Display ?? "没找到");
				Check($"{id} 的上下文判定：HasContext={hasCtx} / 战斗内自造上下文={bootstrap} / 按点数循环 {perPoint}",
					CSharpCodeGen.HasContext(id) == hasCtx && CSharpCodeGen.BootstrapInCombat(id) == bootstrap
					&& CSharpCodeGen.PerPointTrigger(id) == perPoint,
					$"{CSharpCodeGen.HasContext(id)} / {CSharpCodeGen.BootstrapInCombat(id)} / {CSharpCodeGen.PerPointTrigger(id)}");
			}
			{
				CharacterProfile ntProbe = ProfileFactory.Sample();
				ntProbe.ExtraResource.Enabled = true;
				var ntRelics = new List<(string Id, string Cls, string Guard)>
				{
					("DamageDealt",   "UiCheckRelicDealt",   "if (dealer != base.Owner.Creature) return;"),
					("EnergySpent",   "UiCheckRelicEnergy",  "if (amount <= 0 || card?.Owner?.Creature != base.Owner.Creature) return;"),
					("StarsSpent",    "UiCheckRelicStars",   "if (amount <= 0 || spender != base.Owner) return;"),
					("CardGenerated", "UiCheckRelicCardGen", "if (creator is null || creator != base.Owner) return;"),
				};
				foreach (var (id, cls, guard) in ntRelics)
					ntProbe.Relics.Add(new RelicSpec
					{
						Name = "自检" + id, ClassName = cls, Rarity = "Common", Trigger = id,
						// 造成伤害需要 choiceContext：用来验「战斗里那几条没有 context 的钩子」会自己造一个 
						Effects = { new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Enemy" } },
					});
				foreach (var (id, cls, guard) in ntRelics)
				{
					var relic = ntProbe.Relics.First((RelicSpec x) => x.ClassName == cls);
					string src = CSharpCodeGen.RelicSource(ntProbe, relic, ntProbe.Relics.IndexOf(relic));
					Check($"{cls}：钩子 + 守卫和本体口径一致（{guard}）",
						src.Contains(CSharpCodeGen.RelicTriggerSignature(id)) && src.Contains(guard), "对");
					if (id == "DamageDealt")
						Check("造成伤害时有 choiceContext → **不**自己造 context（直接用本体给的那个）",
							!src.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext(")
							&& !src.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext("), "没造");
					else
						Check($"{cls}：钩子没有 choiceContext → 自己造一个 HookPlayerChoiceContext（战斗里不用 Blocking 那个）",
							src.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext(this, base.Owner, __netId,")
							&& !src.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext("), "造了");
					if (CSharpCodeGen.PerPointTrigger(id))
						Check($"{cls}：按点数循环（amount 是这一张牌一共花的）",
							src.Contains($"for (int __{id}Idx = 0; __{id}Idx < amount; __{id}Idx++)"), "循环在");
				}
				// 生成 → 回读：四条新时机都要认得回来
				string ntRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_newtrig_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					ntProbe.Paths.OutputDir = ntRoot;
					ntProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
					ntProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var ntGen = ModGenerator.Generate(ntProbe);
					string ntErr = string.Join(" ｜ ", ntGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message));
					Check("（准备）带四条新触发时机遗物的存档能生成工程", ntGen.Success, ntGen.Success ? ntGen.ProjectRoot : ntErr);
					if (ntGen.Success)
					{
						var ntRec = ProjectRecovery.FromProject(ntGen.ProjectRoot);
						foreach (var (id, cls, _) in ntRelics)
						{
							RelicSpec? back = ntRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == cls);
							Check($"从工程恢复：{cls} 的触发时机认得回来（{id}）",
								back is not null && back.Trigger == id && back.Effects.Count == 1,
								back is null ? "(缺 " : back.Trigger + " / 效果 " + back.Effects.Count + " 条");
						}
						Check("从工程恢复（四条新触发时机）：没认出来的语句为 0", !ntRec.HasUnparsed, ntRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(ntRoot, true); } catch { }
				}
			}
			{
				// 自定义状态：新增触发时机「生成卡牌时」"
				PowerTriggerOption? cg = PowerTriggers.Find("CardGenerated");
				Check("自定义状态的触发时机里有「生成卡牌时」（本体 AfterCardGeneratedForCombat）",
					cg is not null && cg.Display.Contains("生成卡牌"), cg?.Display ?? "没找到");
				CharacterProfile cgProbe = ProfileFactory.Sample();
				var cgPow = new CustomPowerSpec { Name = "自检生成卡牌状态", ClassName = "UiCheckCardGenPower" };
				var cgTrig = new PowerTriggerSpec { Kind = "CardGenerated" };
				// 用「造成伤害」这种**需要 choiceContext** 的效果，才能验出「没 context 的钩子会自己造一个。"
				cgTrig.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 2m, TargetSide = "Enemy" });
				cgPow.Triggers.Add(cgTrig);
				cgProbe.CustomPowers.Add(cgPow);
				string cgSrc = CustomPowerGen.Source(cgProbe, cgPow, 0);
				Check("状态那条链生成的是 AfterCardGeneratedForCombat(card, creator) + 「只认我方角色主动生成」的守卫",
					cgSrc.Contains("public override async Task AfterCardGeneratedForCombat(CardModel card, Player? creator)")
					&& cgSrc.Contains("if (creator is null || creator.Creature != base.Owner) return;"), "对");
				Check("这个钩子没有 choiceContext → 状态那条链会自己造一个（不然需要 context 的效果会 CS0103）",
					cgSrc.Contains("HookPlayerChoiceContext(")
					&& !cgSrc.Contains("new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext("), "造了");
				PowerTriggerOption? es = PowerTriggers.Find("EnergySpent");
				Check("（对照）已有时机还在：花掉能量后 / 花掉额外资源量后 / 某个状态层数变化后",
					es is not null && PowerTriggers.Find("StarsSpent") is not null && PowerTriggers.Find("PowerChanged") is not null, "都在");
			}
			// 「某状态层数刚好达到 N 层」（用户要求）：只给自定义状态、只在那一条钩子上成立
			{
				ConditionOption? reached = EffectCatalog.Conditions.FirstOrDefault((ConditionOption c) => c.Id == "PowerJustReached");
				Check("条件里有「某状态层数刚好达到 N 层」（用户要求：至少 N 层 / 达到 N 层）",
					reached is not null && reached.ForPower && !reached.ForCard && !reached.ForRelic
					&& reached.NeedsAmount && reached.NeedsPower, reached?.Display ?? "没找到");
				var reachedCond = new ConditionSpec { Kind = "PowerJustReached", PowerId = "WeakPower", Amount = 5m };
				string reachedExpr = CSharpCodeGen.ConditionExpr(reachedCond, CSharpCodeGen.CondCtx.Power);
				Check("表达式是「现在是 N 层或更多」+「变化之前还不到 N 层」（本体 power.Amount / amount）",
					reachedExpr == "power is WeakPower && power.Amount >= 5 && power.Amount - amount < 5", reachedExpr);
				Check("同样的条件放在卡牌 / 遗物上下文里生成成 false（永远不会编译不过，但还是会被校验器拦住）",
					CSharpCodeGen.ConditionExpr(reachedCond, CSharpCodeGen.CondCtx.Card) == "false"
					&& CSharpCodeGen.ConditionExpr(reachedCond, CSharpCodeGen.CondCtx.Relic) == "false", "false");
				// 界面上：状态那一份候选有它、遗物那一份没有（不然用户选完才被拦）
				Check("状态触发器的条件候选里有它（PowerEffectConditions）",
					PowerEffectConditions.Any((ConditionOption c) => c.Id == "PowerJustReached"), "在");
				Check("遗物 / 药水的条件候选里**没有**它（PlainEffectConditions）",
					!PlainEffectConditions.Any((ConditionOption c) => c.Id == "PowerJustReached"), "没在");
				// 校验器：挂在别的触发时机上 → 报错；挂在「某个状态层数变化后」上 → 不报
				CharacterProfile pjBad = ProfileFactory.Sample();
				var pjBadPow = new CustomPowerSpec { Name = "自检达到层数", ClassName = "UiCheckReachedBad" };
				var pjTurn = new PowerTriggerSpec { Kind = "TurnStart" };
				pjTurn.Effects.Add(new EffectSpec { Kind = "Block", Amount = 1m, TargetSide = "Self", Condition = reachedCond });
				pjBadPow.Triggers.Add(pjTurn);
				pjBad.CustomPowers.Add(pjBadPow);
				Check("校验器：条件挂在「玩家回合开始时」→ 报错说清它只能挂在「某个状态层数变化后」上",
					ProfileValidator.Validate(pjBad).Any((ValidationIssue i) => i.IsError && i.Message.Contains("刚好达到")),
					"拦住了");
				CharacterProfile pjGood = ProfileFactory.Sample();
				var pjGoodPow = new CustomPowerSpec { Name = "自检达到层数2", ClassName = "UiCheckReachedGood" };
				var pjChg = new PowerTriggerSpec { Kind = "PowerChanged", PowerId = "WeakPower" };
				pjChg.Effects.Add(new EffectSpec { Kind = "Block", Amount = 1m, TargetSide = "Self", Condition = reachedCond });
				pjGoodPow.Triggers.Add(pjChg);
				pjGood.CustomPowers.Add(pjGoodPow);
				Check("（对照）挂在「某个状态层数变化后」→ 不报这条错",
					!ProfileValidator.Validate(pjGood).Any((ValidationIssue i) => i.IsError && i.Message.Contains("刚好达到")), "没报");
			}

			// 「某个状态层数到达 N 层时」（用户要求：遗物加一个「当状态层数到达多少时」）
			{
				TriggerOption? pr = EffectCatalog.RelicTriggers.FirstOrDefault((TriggerOption t) => t.Id == "PowerReached");
				Check("遗物触发时机里有「某个状态层数到达 N 层时」（本体 AfterPowerAmountChanged）",
					pr is not null && pr.Display.Contains("状态层数到达")
					&& CSharpCodeGen.RelicTriggerSignature("PowerReached")
						== "public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)",
					pr?.Display ?? "没找到");
				Check("这个时机带 choiceContext（召唤伙伴 / 生成卡牌这类效果能直接用）", CSharpCodeGen.HasContext("PowerReached"), "有");
				var prRelic = new RelicSpec
				{
					Name = "自检层数遗物", ClassName = "UiCheckRelicReach", Rarity = "Common", Trigger = "PowerReached",
					TriggerPowerId = "WeakPower", TriggerAmount = 5m,
					Effects = { new EffectSpec { Kind = "Draw", Amount = 2m, TargetSide = "Self" } },
				};
				var prProfile = ProfileFactory.Sample();
				prProfile.Relics.Add(prRelic);
				string prSrc = CSharpCodeGen.RelicSource(prProfile, prRelic, prProfile.Relics.Count - 1);
				Check("生成：钩子 + 三条守卫（自己的状态 / 盯的那个状态 / 这一次跨过 N 层）",
					prSrc.Contains("AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)")
					&& prSrc.Contains("if (power.Owner is null || power.Owner != base.Owner.Creature) return;")
					&& prSrc.Contains("if (power is not WeakPower) return;")
					&& prSrc.Contains("if (!(power.Amount >= 5m && power.Amount - amount < 5m)) return;"), "对");
				Check("生成：写一行回读标记（盯哪个状态 / 到达多少层）",
					prSrc.Contains("// CET:PowerWatch=WeakPower CET:PowerReach=5m"), "有标记");
				Check("「盯哪个状态」留空 = 不写那一条守卫（任何状态层数跨过 N 层都触发）",
					!CSharpCodeGen.RelicSource(prProfile, new RelicSpec
					{
						Name = "任意层数遗物", ClassName = "UiCheckRelicReachAny", Trigger = "PowerReached", TriggerAmount = 3m,
						Effects = { new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" } },
					}, 0).Contains("if (power is not "), "没写");
				Check("界面用：这两个输入框只在这个触发时机下显示 + 说明里写清「跨过才触发」",
					prRelic.ShowTriggerPowerFields && !new RelicSpec { Trigger = "CombatStart" }.ShowTriggerPowerFields
					&& prRelic.TriggerHint.Contains("跨过") && prRelic.TriggerHint.Contains("虚弱"), prRelic.TriggerHint);
				Check("校验器：到达 N 层 <= 0 → 报错",
					ProfileValidator.Validate(new CharacterProfile { Relics = { new RelicSpec { Name = "零层", Trigger = "PowerReached", TriggerAmount = 0m, Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } } } })
						.Any((ValidationIssue i) => i.IsError && i.Message.Contains("到达 N 层")), "拦住了");
				Check("校验器：没选状态 → 提示「任何状态都触发」",
					ProfileValidator.Validate(new CharacterProfile { Relics = { new RelicSpec { Name = "任意", Trigger = "PowerReached", TriggerAmount = 3m, Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } } } })
						.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("任何")), "提示了");
				Check("校验器：没选这个时机却填了这两个值 → 提示「不生效」（不静默）",
					ProfileValidator.Validate(new CharacterProfile { Relics = { new RelicSpec { Name = "时机不对", Trigger = "CombatStart", TriggerPowerId = "WeakPower", TriggerAmount = 5m, Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } } } })
						.Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("不生效")), "提示了");
				// 生成 → 真编译 → 回读
				string prRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_relicreach_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					prProfile.Paths.OutputDir = prRoot;
					prProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					prProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var prGen = ModGenerator.Generate(prProfile);
					Check("（准备）带「状态层数到达 N 层」遗物的存档能生成工程", prGen.Success,
						prGen.Success ? prGen.ProjectRoot : string.Join(" ｜ ", prGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (prGen.Success)
					{
						var prRec = ProjectRecovery.FromProject(prGen.ProjectRoot);
						RelicSpec? prBack = prRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == "UiCheckRelicReach");
						Check("从工程恢复：触发时机 / 盯哪个状态 / 到达多少层都认得回来",
							prBack is not null && prBack.Trigger == "PowerReached"
							&& prBack.TriggerPowerId == "WeakPower" && prBack.TriggerAmount == 5m && prBack.Effects.Count == 1,
							prBack is null ? "(缺 " : $"{prBack.Trigger} / {prBack.TriggerPowerId} / {prBack.TriggerAmount}");
						Check("从工程恢复（状态层数到达）：没认出来的语句为 0", !prRec.HasUnparsed, prRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(prRoot, true); } catch { }
				}
			}

			// ===== 用户要求：遗物 / 状态的触发时机合并成同一套 =====
			{
				// 合并后的目标：状态那边有的时机，遗物这边都有（id 同名同义）；显示名也统一
				var powerIds = PowerTriggers.All.Select((PowerTriggerOption t) => t.Kind).ToList();
				var relicIds = EffectCatalog.RelicTriggers.Select((TriggerOption t) => t.Id).ToList();
				// 同名后 id 的那批：状态有 → 遗物也必须有
				var shared = new[] { "Attacked", "BlockGained", "CardDiscarded", "CardDrawn", "CardExhausted", "CardGenerated",
					"CardPlayed", "CombatStart", "CombatVictory", "DamageDealt", "EnemyBlockGained", "EnemyDamaged",
					"EnemyDealtDamage", "EnemyDeath", "EnemyTurnEnd", "EnemyTurnStart", "EnergySpent", "HpLost",
					"PowerChanged", "StarsSpent", "GoldGained", "Shuffle" };
				Check("合并后：状态那边有的时机，遗物这边**都有**（同名同 id）",
					shared.All(id => powerIds.Contains(id) && relicIds.Contains(id)),
					"缺：" + string.Join(" / ", shared.Where(id => !powerIds.Contains(id) || !relicIds.Contains(id))));
				// 用户要求「所有触发时机下拉菜单包含的内容相同」：两个菜单的 (id, 显示名  集合必须**完全一样**
				// ⚠ 例外：`PlayerTurnStart` 一条。它在**两边叫法不同**（遗物页「玩家回合开始时」=
				// 那一栏从第 9 批起就是这个中文名；状态页「玩家回合开始时」也是老名字），而 V0.2.179 新加的
				// `PlayerTurnStartEarly/Late` 两边**逐字相同**。这一条例外只影响界面上的字，不影响存档 / 生成。
				var displayDiffAllowed = new[] { "PlayerTurnStart" };
				Check("两个触发时机下拉菜单的内容**完全一样**（遗物侧 与 状态侧：id 集合 + 显示名逐条相同；"
					+ "唯一例外 = PlayerTurnStart 那一栏的老中文名）",
					relicIds.OrderBy(x => x, StringComparer.Ordinal).SequenceEqual(powerIds.OrderBy(x => x, StringComparer.Ordinal))
					&& relicIds.All(id => displayDiffAllowed.Contains(id, StringComparer.Ordinal)
						|| EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == id).Display
							== PowerTriggers.Find(id)!.Display),
					"只在一侧：" + string.Join(" / ", relicIds.Except(powerIds).Concat(powerIds.Except(relicIds))));
				// V0.2.179（用户要求「触发时机加一个回合开始后」）：两个新时刻**必须两边逐字同名**，
				// 而且 id 集合双向相等（漏一侧就是「一边有、一边没有」）
				Check("V0.2.179：回合开始后（抽牌前 / 最晚）两条在遗物侧和状态侧**逐字同名**、id 双向都有",
					new[] { "PlayerTurnStartEarly", "PlayerTurnStartLate" }.All(id =>
						relicIds.Contains(id) && powerIds.Contains(id)
						&& EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == id).Display
							== PowerTriggers.Find(id)!.Display),
					string.Join(" / ", new[] { "PlayerTurnStartEarly", "PlayerTurnStartLate" }.Select(id =>
						id + "：遗物=" + (EffectCatalog.RelicTriggers.FirstOrDefault((TriggerOption t) => t.Id == id)?.Display ?? "（无）")
						+ " 状态=" + (PowerTriggers.Find(id)?.Display ?? "（无）"))));
				Check("老存档的旧 id（TurnStart / TurnEnd / DamageTaken）仍然认（别名 → 现在的 id）",
					PowerTriggers.Canonical("TurnStart") == "PlayerTurnStart"
					&& PowerTriggers.Canonical("TurnEnd") == "PlayerTurnEnd"
					&& PowerTriggers.Canonical("DamageTaken") == "DamageReceived"
					&& PowerTriggers.Find("TurnStart") is not null, "认");
				Check("合并后：同一个时机在两边的**显示名一样**（例：自己受到伤害后（每一下） / 花掉能量后）",
					shared.All(id => EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == id).Display
						== PowerTriggers.Find(id)!.Display),
					"不一致：" + string.Join(" / ", shared.Where(id => EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == id).Display
						!= PowerTriggers.Find(id)!.Display)
						.Select(id => id + "）" + EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == id).Display
							+ " vs " + PowerTriggers.Find(id)!.Display)));
				// 「同一个钩子、id 不同」的三对：遗物的叫法和状态的叫法都保留（老存档两种 id 都要能读）"
				var sameHookPairs = new (string Relic, string Power)[]
				{
					("PlayerTurnStart", "PlayerTurnStart"), ("PlayerTurnEnd", "PlayerTurnEnd"), ("DamageReceived", "DamageReceived"),
				};
				// 三个概念两边现在用**同一个 id**，而 id 只是别名（老存档照样读得回来）
				// ⚠ 显示名的口径：PlayerTurnEnd / DamageReceived 两边逐字同；PlayerTurnStart 的**老中文名**两边
				// 各自保留（遗物页第 9 批起就叫「玩家回合开始时」）—— 所以那一条只要求 id 相同。
				Check("三个「同一个本体钩子」的概念两边用**同一个 id**；老 id（TurnStart / TurnEnd / DamageTaken）只是别名",
					sameHookPairs.All(pr => pr.Relic == pr.Power
						&& (pr.Relic == "PlayerTurnStart"
							|| EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == pr.Relic).Display
								== PowerTriggers.Find(pr.Power)!.Display)), "同 id（PlayerTurnStart 的老中文名两边各自保留）");
				Check("遗物独有的时机现在**一条都没有**（两个下拉菜单内容完全一致）",
					relicIds.Where(id => !powerIds.Contains(id)).Count() == 0,
					string.Join(" / ", relicIds.Where(id => !powerIds.Contains(id))));
				Check("状态侧新增的两条（获得金币时 / 抽牌堆打乱洗牌时）也在遗物侧存在",
					PowerTriggers.Find("GoldGained") is not null && PowerTriggers.Find("Shuffle") is not null
					&& relicIds.Contains("GoldGained") && relicIds.Contains("Shuffle"), "都在");
				// 生成端：合并过来的 13 条遗物时机都有钩子 + 守卫（抽查几条）
				Check("合并过来的时机生成端都有钩子签名（抽查：打出一张牌后 / 敌人回合开始时 / 自己失去生命时）",
					CSharpCodeGen.RelicTriggerSignature("CardPlayed").Contains("BeforeCardPlayed")
					&& CSharpCodeGen.RelicTriggerSignature("EnemyTurnStart").Contains("AfterSideTurnStart")
					&& CSharpCodeGen.RelicTriggerSignature("HpLost").Contains("AfterCurrentHpChanged"), "有");
				var mgProfile = ProfileFactory.Sample();
				var mgRelic = new RelicSpec
				{
					Name = "自检合并时机遗物", ClassName = "UiCheckMergedTrigger", Rarity = "Common", Trigger = "CardPlayed",
					Effects = { new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" } },
				};
				mgProfile.Relics.Add(mgRelic);
				string mgSrc = CSharpCodeGen.RelicSource(mgProfile, mgRelic, mgProfile.Relics.Count - 1);
				Check("遗物侧的守卫按**遗物**的归属写（base.Owner 是 Player：打出的牌看 cardPlay.Player）",
					mgSrc.Contains("public override async Task BeforeCardPlayed(CardPlay cardPlay)")
					&& mgSrc.Contains("if (cardPlay.Player != base.Owner) return;"), "对");
				Check("没有 choiceContext 的合并时机（自己失去生命时 / 自己获得格挡后…）会自己造一个",
					CSharpCodeGen.BootstrapInCombat("HpLost") && CSharpCodeGen.BootstrapInCombat("BlockGained")
					&& !CSharpCodeGen.HasContext("HpLost"), "会");
				// 老工程回读：改名前的显示名也要认得回来（不然老存档会丢触发时机）
				var oldProfile = ProfileFactory.Sample();
				var oldRelic = new RelicSpec
				{
					Name = "老工程遗物", ClassName = "UiCheckOldDisplayTrigger", Rarity = "Common", Trigger = "DamageReceived",
					Effects = { new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" } },
				};
				oldProfile.Relics.Add(oldRelic);
				string mgRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_merged_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					oldProfile.Paths.OutputDir = mgRoot;
					oldProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					oldProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var oldGen = ModGenerator.Generate(oldProfile);
					Check("（准备）老工程回读用的存档能生成工程", oldGen.Success,
						oldGen.Success ? oldGen.ProjectRoot : string.Join(" ｜ ", oldGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (oldGen.Success)
					{
						// 把类里那句注释改成**改名前**的显示名，模拟老工程"
						string relicFile = Path.Combine(oldGen.ProjectRoot, "cs", "Relics", "UiCheckOldDisplayTrigger.cs");
						string txt = File.ReadAllText(relicFile, System.Text.Encoding.UTF8)
							.Replace("// 触发时机：自己受到伤害后（每一下）", "// 触发时机：受到伤害时（每一下）");
						File.WriteAllText(relicFile, txt, System.Text.Encoding.UTF8);
						var oldRec = ProjectRecovery.FromProject(oldGen.ProjectRoot);
						RelicSpec? oldBack = oldRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == "UiCheckOldDisplayTrigger");
						Check("老工程（改名前的显示名）回读时也认得回来 → 触发时机不会丢",
							oldBack is not null && oldBack.Trigger == "DamageReceived", oldBack?.Trigger ?? "(缺 ");
					}
				}
				finally
				{
					try { Directory.Delete(mgRoot, true); } catch { }
				}
			}
			// ===== 用户报「命中次数的公式不生效」：查清并修掉（不再静默） ====
			{
				var repOk = new EffectSpec { Kind = "Damage", TargetSide = "Enemy", RepeatCount = 2 };
				repOk.RepeatFormula = "Turn";
				Check("「命中次数」真的会用到的场合：造成伤害 / 随机敌人 / 伙伴攻击 → 显示那一栏、公式生效",
					repOk.UsesRepeatCount && repOk.ShowRepeatCountInput && repOk.UsesCountFormula("Repeat")
					&& new EffectSpec { Kind = "ApplyPower", TargetSide = "RandomEnemies" }.UsesRepeatCount
					&& new EffectSpec { Kind = "PetAttack", TargetSide = "Enemy" }.UsesRepeatCount, "会用到");
				var repBad = new EffectSpec { Kind = "HpLoss", TargetSide = "Self", RepeatCount = 2 };
				repBad.RepeatFormula = "Turn";
				Check("用不到的场合（失去生命 / 单体上状态 / 单体击晕）→ 那一栏收起、公式不算「设了」",
					!repBad.UsesRepeatCount && !repBad.UsesCountFormula("Repeat")
					&& !new EffectSpec { Kind = "ApplyPower", TargetSide = "Enemy" }.UsesRepeatCount
					&& !new EffectSpec { Kind = "Stun", TargetSide = "Enemy" }.UsesRepeatCount, "收起");
				// ===== V0.2.171：用户报「我并没有填 Y 怎么还这样」（卡牌「新卡」第 1 条「播放音频文件」
				// 上留着「命中次数公式 Y」—— 那一栏按种类是收起的，用户找不到它，却被它挡住生成）=====
				var repStale = new EffectSpec { Kind = "PlaySoundFile", TargetSide = "Self", RepeatCount = 1, IsCardChain = true };
				repStale.RepeatFormula = "Y";
				bool staleShown = repStale.HasStaleRepeatFields && repStale.ShowRepeatCountInput && repStale.ShowRepeatFormulaBox
					&& repStale.ShowCardRepeatRow && repStale.ShowFixedRepeatBox;
				repStale.ClearStaleRepeatFields();
				Check("（V0.2.171）收起的「命中次数」里还留着值 → 那一行**露出来**可以清掉；清掉后收起、不再挡生成",
					staleShown && !repStale.ShowRepeatCountInput && !repStale.HasStaleRepeatFields
					&& repStale.RepeatFormula.Length == 0 && repStale.RepeatCount == 1, "露出来 → 清掉 → 收起");
				Check("（V0.2.171）（对照）干干净净的「播放音频文件」不显示「命中次数」那一行",
					!new EffectSpec { Kind = "PlaySoundFile", TargetSide = "Self" }.ShowRepeatCountInput, "收起");
				var repSwitch = new EffectSpec { Kind = "Damage", TargetSide = "Enemy", RepeatCount = 3 };
				repSwitch.RepeatFormula = "Y";
				repSwitch.Kind = "PlaySoundFile";
				Check("（V0.2.171）换效果种类会自动清掉这一种类用不到的「命中次数」（不会再留下看不见的残留）",
					repSwitch.RepeatFormula.Length == 0 && repSwitch.RepeatCount == 1 && !repSwitch.HasStaleRepeatFields, "自动清了");
				var repKeep = new EffectSpec { Kind = "Damage", TargetSide = "Enemy", RepeatCount = 3 };
				repKeep.RepeatFormula = "Y";
				Check("（V0.2.171）（对照）会用到它的种类上换 / 填都保留，不清",
					repKeep.UsesRepeatCount && repKeep.RepeatFormula == "Y" && repKeep.RepeatCount == 3, "留着");
				var repBadProfile = ProfileFactory.Sample();
				var repBadCard = new CardSpec { Name = "自检命中公式", ClassName = "UiCheckRepeatBad", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				repBadCard.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 3m, TargetSide = "Self", RepeatCount = 2, RepeatFormula = "Turn" });
				repBadProfile.Cards.Add(repBadCard);
				Check("校验器：用不到却留着公式 → **警告**说清「不生效 + 清空即可」，**不挡住生成**（V0.2.171 起：用户没填过却挡人）",
					ProfileValidator.Validate(repBadProfile).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("命中次数") && i.Message.Contains("不会用到"))
					&& !ProfileValidator.Validate(repBadProfile).Any((ValidationIssue i) => i.IsError && i.Message.Contains("命中次数")),
					"只警告、不拦");
				var repWarnProfile = ProfileFactory.Sample();
				var repWarnCard = new CardSpec { Name = "自检命中数字", ClassName = "UiCheckRepeatWarn", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				repWarnCard.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 3m, TargetSide = "Self", RepeatCount = 2 });
				repWarnProfile.Cards.Add(repWarnCard);
				Check("校验器：用不到却填了固定数字 → **警告**（老存档不拦死，但说清不生效）",
					ProfileValidator.Validate(repWarnProfile).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("命中次数")),
					"警告了");
				// 会用到的那条：生成出来真的用了公式 
				CharacterProfile repOkProfile = ProfileFactory.Sample();
				var repOkCard = new CardSpec { Name = "自检命中公式对", ClassName = "UiCheckRepeatGood", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				var repOkEff = new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Enemy", RepeatCount = 2 };
				repOkEff.RepeatFormula = "Turn";
				repOkCard.Effects.Add(repOkEff);
				repOkProfile.Cards.Add(repOkCard);
				Check("生成端：会用到的那条把公式写进 .WithHitCount（夹到 1~20）",
					CSharpCodeGen.CardSource(repOkProfile, repOkCard, 0)
						.Contains(".WithHitCount((int)System.Math.Clamp((__fgPlayer?.PlayerCombatState?.TurnNumber ?? 0), 1m, 20m))"), "对");
			}

			// ===== 「花掉 N 点」的数值 + 本回合 / 本场战斗（用户要求）=====
			{
				Check("界面有「本回合 / 本场战斗」两个选项（TriggerScopes）",
					TriggerScopes.Count == 2 && TriggerScopes[0].Id == "Turn" && TriggerScopes[1].Id == "Combat",
					string.Join(" / ", TriggerScopes.Select(x => x.Display)));
				var spRelic = new RelicSpec
				{
					Name = "自检每 点能量", ClassName = "UiCheckSpendEnergy", Trigger = "EnergySpent", Rarity = "Common",
					TriggerAmount = 3m, TriggerScope = "Turn",
					Effects = { new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" } },
				};
				var spProfile = ProfileFactory.Sample();
				spProfile.Relics.Add(spRelic);
				Check("遗物：这一栏只在「花掉能量 / 花掉额外资源量」时显示",
					spRelic.ShowTriggerSpendFields && !new RelicSpec { Trigger = "CombatStart" }.ShowTriggerSpendFields, "只在这两条");
				string spSrc = CSharpCodeGen.RelicSource(spProfile, spRelic, 0);
				Check("遗物：生成「这一次之前已经花了多少」+「每累计 N 点触发一次」（用本体战斗历史，不需要自己记计数器）",
					spSrc.Contains("EnergySpentEntry>().Where(e => e.Actor == base.Owner.Creature && e.HappenedThisTurn(base.Owner.Creature.CombatState)).Sum(e => e.Amount) - amount")
					&& spSrc.Contains("if ((__spentBefore + __EnergySpentIdx + 1) % 3 != 0) continue;"), "对");
				Check("遗物：范围选「本场战斗」时不算 HappenedThisTurn（整场累计）",
					CSharpCodeGen.SpentSumExpr("StarsSpent", "Combat", "base.Owner.Creature", "base.Owner.Creature.CombatState")
						.Contains("e.Amount < 0)") && !CSharpCodeGen.SpentSumExpr("StarsSpent", "Combat", "base.Owner.Creature", "base.Owner.Creature.CombatState")
						.Contains("HappenedThisTurn"), "对");
				Check("遗物：说明文字会说清「每累计花掉 N 点触发一次 + 范围」",
					spRelic.TriggerSpendHint.Contains("每累计") && spRelic.TriggerSpendHint.Contains("本回合"), spRelic.TriggerSpendHint);
				var spPow = new CustomPowerSpec { Name = "自检每 点能量", ClassName = "UiCheckSpendPower" };
				var spTrig = new PowerTriggerSpec { Kind = "EnergySpent", TriggerAmount = 4m, TriggerScope = "Turn" };
				spTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				spPow.Triggers.Add(spTrig);
				Check("状态：同一套（列只在花能量 / 花资源量时显示 + 说明文字同款）",
					spTrig.ShowTriggerSpendFields && spTrig.TriggerSpendHint.Contains("每累计"), "对");
				var spPowProfile = ProfileFactory.Sample();
				spPowProfile.CustomPowers.Add(spPow);
				string spPowSrc = CustomPowerGen.Source(spPowProfile, spPow, 0);
				Check("状态：生成的是「每累计 N 点才跑这条效果」（if ((__spentBefore + idx + 1) % N == 0)）",
					spPowSrc.Contains("int __spentBefore =") && spPowSrc.Contains("if ((__spentBefore + __energySpentIdx + 1) % 4 == 0)"), "对");
				Check("校验器：负数 → 报错（不能是负数）",
					ProfileValidator.Validate(new CharacterProfile { Relics = { new RelicSpec { Name = "费", Trigger = "EnergySpent", TriggerAmount = -2m, Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } } } })
						.Any((ValidationIssue i) => i.IsError && i.Message.Contains("不能是负数")), "拦住了");
				// 生成 → 回读：数值 + 范围都要认得回来
				string spRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_spend_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					spProfile.Paths.OutputDir = spRoot;
					spProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					spProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					spProfile.CustomPowers.Add(spPow);
					var spGen = ModGenerator.Generate(spProfile);
					Check("（准备）带「花掉 N 点」的存档能生成工程", spGen.Success,
						spGen.Success ? spGen.ProjectRoot : string.Join(" ｜ ", spGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (spGen.Success)
					{
						var spRec = ProjectRecovery.FromProject(spGen.ProjectRoot);
						RelicSpec? spBack = spRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == "UiCheckSpendEnergy");
						var spPowBack = spRec.Profile.CustomPowers.FirstOrDefault((CustomPowerSpec x) => x.ClassName == "UiCheckSpendPower");
						Check("回读：遗物的「花掉 N 点 + 范围」认得回来",
							spBack is not null && spBack.TriggerAmount == 3m && spBack.TriggerScope == "Turn",
							spBack is null ? "(缺 " : $"{spBack.TriggerAmount} / {spBack.TriggerScope}");
						Check("回读：状态的「花掉 N 点 + 范围」认得回来",
							spPowBack is not null && spPowBack.Triggers.Any((PowerTriggerSpec t) => t.TriggerAmount == 4m && t.TriggerScope == "Turn"),
							spPowBack is null ? "(缺 " : string.Join(" / ", spPowBack.Triggers.Select((PowerTriggerSpec t) => t.TriggerAmount + ":" + t.TriggerScope)));
						Check("回读（花掉 N 点）：没认出来的语句为 0", !spRec.HasUnparsed, spRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(spRoot, true); } catch { }
				}
			}

			// ===== V0.2.219：「花掉 N 点」填 0 = 只要消耗就触发（本回合 / 本场战斗只触发第一次）=====
			// 用户实测报的：「数值填 0 的效果和填 1 的效果是一样的」——真因是 0 落进了
			// `Math.Max(1, 0)` 那个「每 1 点」分支，于是 0 == 1（一张 3 费牌触发 3 次）。
			{
				var zeroRelic = new RelicSpec
				{
					Name = "自检填 0 能量", ClassName = "UiCheckSpendZero", Trigger = "EnergySpent", Rarity = "Common",
					TriggerAmount = 0m, TriggerScope = "Turn",
					Effects = { new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" } },
				};
				var zeroProfile = ProfileFactory.Sample();
				zeroProfile.Relics.Add(zeroRelic);
				string zSrc = CSharpCodeGen.RelicSource(zeroProfile, zeroRelic, 0);
				Check("遗物：填 0 → 不再按点数循环（0 和 1 一样就是它：0 被当成「每 1 点」）",
					!zSrc.Contains("for (int __EnergySpentIdx"), "没有点数循环");
				Check("遗物：填 0 → 判「这一次之前花过没有」，本回合只触发第一次",
					zSrc.Contains("if (__spentBefore == 0)") && zSrc.Contains("只触发第一次"), "对");
				Check("遗物：填 0 也写回读标记（否则从工程恢复会变回默认的 1）",
					zSrc.Contains("CET:TriggerAmount=0m CET:TriggerScope=Turn"), "写");

				var zeroTrig = new PowerTriggerSpec { Kind = "StarsSpent", TriggerAmount = 0m, TriggerScope = "Combat" };
				zeroTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 2m, TargetSide = "Self" });
				var zeroPow = new CustomPowerSpec { Name = "自检填 0 资源", ClassName = "UiCheckSpendZeroPow", Enabled = true };
				zeroPow.Triggers.Add(zeroTrig);
				var zeroPowProfile = ProfileFactory.Sample();
				zeroPowProfile.CustomPowers.Add(zeroPow);
				string zpSrc = CustomPowerGen.Source(zeroPowProfile, zeroPow, 0);
				Check("状态：填 0 → 不按点数循环，改成「只要消耗一次」+ 本场战斗只触发第一次",
					!zpSrc.Contains("for (int __starsSpentIdx") && zpSrc.Contains("if (__spentBefore == 0)"), "对");
				Check("状态：填 0 也写回读标记（TriggerAmount=0 + 范围）",
					zpSrc.Contains("CET:TriggerAmount=0m CET:TriggerScope=Combat"), "写");
				Check("说明文字：填 0 说的是「只要消耗就触发一次 + 这个范围只触发第一次」",
					zeroTrig.TriggerSpendHint.Contains("只要消耗就触发一次") && zeroTrig.TriggerSpendHint.Contains("只触发第一次"),
					zeroTrig.TriggerSpendHint);
				Check("说明文字（遗物同款）",
					zeroRelic.TriggerSpendHint.Contains("只触发第一次"), zeroRelic.TriggerSpendHint);

				// 同一个钩子上「0 档」+「N 档」混着配：0 档跑在点数循环**外面**（每窗口一次），N 档照旧按点数
				var mixPow = new CustomPowerSpec { Name = "自检混搭消耗", ClassName = "UiCheckSpendMix", Enabled = true };
				var mixZero = new PowerTriggerSpec { Kind = "EnergySpent", TriggerAmount = 0m, TriggerScope = "Turn" };
				mixZero.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" });
				var mixThree = new PowerTriggerSpec { Kind = "EnergySpent", TriggerAmount = 3m, TriggerScope = "Turn" };
				mixThree.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" });
				mixPow.Triggers.Add(mixZero);
				mixPow.Triggers.Add(mixThree);
				var mixProfile = ProfileFactory.Sample();
				mixProfile.CustomPowers.Add(mixPow);
				string mixSrc = CustomPowerGen.Source(mixProfile, mixPow, 0);
				int mixZeroAt = mixSrc.IndexOf("if (__spentBefore == 0)", StringComparison.Ordinal);
				int mixLoopAt = mixSrc.IndexOf("for (int __energySpentIdx", StringComparison.Ordinal);
				Check("混搭：0 档在点数循环外面（0 档 = 这个窗口的第一次消耗），N 档继续按点数",
					mixZeroAt >= 0 && mixLoopAt > mixZeroAt, $"0 档@{mixZeroAt} / 循环@{mixLoopAt}");
				Check("混搭：两种档位共用一个「之前花了多少」（只算一次历史）",
					mixSrc.Split("int __spentBefore =").Length - 1 == 1, "一处");

				// 生成 → 回读：0 这个值也要认得回来（不然从工程恢复就悄悄变回 1）
				string zRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_spend0_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					zeroProfile.CustomPowers.Add(zeroPow);
					zeroProfile.Paths.OutputDir = zRoot;
					zeroProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					zeroProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var zGen = ModGenerator.Generate(zeroProfile);
					Check("（准备）带「填 0」的存档能生成工程", zGen.Success,
						zGen.Success ? zGen.ProjectRoot : string.Join(" ｜ ", zGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (zGen.Success)
					{
						var zRec = ProjectRecovery.FromProject(zGen.ProjectRoot);
						RelicSpec? zBack = zRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == "UiCheckSpendZero");
						var zPowBack = zRec.Profile.CustomPowers.FirstOrDefault((CustomPowerSpec x) => x.ClassName == "UiCheckSpendZeroPow");
						Check("回读：遗物的「填 0 + 范围」认得回来（不会被默认值 1 顶掉）",
							zBack is not null && zBack.TriggerAmount == 0m && zBack.TriggerScope == "Turn",
							zBack is null ? "(缺 " : $"{zBack.TriggerAmount} / {zBack.TriggerScope}");
						Check("回读：状态的「填 0 + 范围」认得回来",
							zPowBack is not null && zPowBack.Triggers.Any((PowerTriggerSpec t) => t.TriggerAmount == 0m && t.TriggerScope == "Combat"),
							zPowBack is null
								? "缺：" + string.Join(",", zRec.Profile.CustomPowers.Select((CustomPowerSpec x) => x.ClassName))
								: string.Join(" / ", zPowBack!.Triggers.Select((PowerTriggerSpec t) => t.TriggerAmount + ":" + t.TriggerScope)));
						Check("回读（填 0）：没认出来的语句为 0", !zRec.HasUnparsed, zRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(zRoot, true); } catch { }
				}
			}

			// ===== 参数页也能监听「实时读数」（用户要求） ====
			{
				// V0.2.194：卡牌专属的读数（FormulaBuiltin.CardOnly，例：ThisCardDamage）**不进**这个下拉
				// —— 参数是「打出这张牌那一刻先算一次」，选它当来源会恒为 0（伤害还没打）。所以这里
				// 按「非 CardOnly 的那部分」对账，而不是整张表。
				var paramLive = FormulaBuiltins.All.Where(b => !b.CardOnly).ToList();
				Check("参数页的「从哪来」候选里含全部实时读数（回合 / 轮 / 四摞张数 / 丢弃·消耗·生成·复制 / 资源量 / 状态数）",
					paramLive.All((FormulaBuiltin b) => ParamSources.All.Any((ParamSourceOption o) => o.Id == b.Id))
					&& ParamSources.All.Count == 8 + paramLive.Count,
					$"{ParamSources.All.Count} 条（固定来源 8 + 实时读数 {paramLive.Count}）");
				Check("卡牌专属的读数（ThisCardDamage）**不在**参数来源下拉里（选了会恒 0）",
					!ParamSources.All.Any((ParamSourceOption o) => o.Id == "ThisCardDamage")
					&& FormulaBuiltins.Find("ThisCardDamage") is { CardOnly: true }, "不在");
				Check("「本回合丢弃的牌数」「本回合复制的牌数」都在候选里（用户点名的两条）",
					ParamSources.All.Any((ParamSourceOption o) => o.Id == "DiscardedThisTurn")
					&& ParamSources.All.Any((ParamSourceOption o) => o.Id == "CopiedThisTurn"), "都在");
				Check("参数来源选实时读数 → 生成的是那段运行时表达式（不是固定数字）",
					ForgeFormula.ParamExpr(new ParamSpec { Name = "M", Source = "DiscardedThisTurn", Target = "Self" })
						.Contains("CardDiscardedEntry"), "对");
				Check("「回合数」参数生成的是本体 PlayerCombatState.TurnNumber",
					ForgeFormula.ParamExpr(new ParamSpec { Source = "Turn" }).Contains("PlayerCombatState?.TurnNumber"), "对");
				Check("UI 提示说的是「实时读数：每次取值现算」",
					ParamSources.Find("DiscardedThisTurn")!.Hint.Contains("实时读数"), ParamSources.Find("DiscardedThisTurn")!.Hint);
				CharacterProfile lpProfile = ProfileFactory.Sample();
				lpProfile.CustomParams.Clear();
				lpProfile.CustomParams.Add(new ParamSpec { Name = "M", Source = "DiscardedThisTurn", Target = "Self" });
				lpProfile.CustomParams.Add(new ParamSpec { Name = "T", Source = "Turn", Target = "Self" });
				var lpCard = new CardSpec { Name = "实时读数参数卡", ClassName = "UiCheckParamLive", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				lpCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 1m, AmountFormula = "M + T", TargetSide = "Enemy" });
				lpProfile.Cards.Add(lpCard);
				string lpRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_paramlive_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					lpProfile.Paths.OutputDir = lpRoot;
					lpProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					lpProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var lpGen = ModGenerator.Generate(lpProfile);
					Check("（准备）用实时读数当参数来源的卡能生成工程", lpGen.Success,
						lpGen.Success ? lpGen.ProjectRoot : string.Join(" ｜ ", lpGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (lpGen.Success)
					{
						var lpRec = ProjectRecovery.FromProject(lpGen.ProjectRoot);
						Check("回读：参数来源认得回来（丢弃张数 / 回合数）",
							lpRec.Profile.CustomParams.Any((ParamSpec x) => x.Name == "M" && x.Source == "DiscardedThisTurn")
							&& lpRec.Profile.CustomParams.Any((ParamSpec x) => x.Name == "T" && x.Source == "Turn"),
							string.Join(" / ", lpRec.Profile.CustomParams.Select((ParamSpec x) => x.Name + "=" + x.Source)));
						Check("回读（实时读数参数）：没认出来的语句为 0", !lpRec.HasUnparsed, lpRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { Directory.Delete(lpRoot, true); } catch { }
				}
			}

			// ===== 「目标身上的减益个数」当自定义参数（DebuffCount，V0.2.250 —— 用户问的「撕碎」） ====
			//
			// 需求：本体「撕碎 Rend」= 基础伤害 + 每有一种负面效果 × N（`target.Powers.Count(TypeForCurrentAmount
			// == Debuff)`）。卡牌公式里原来只有 `DebuffsOnMe`（自己），所以把「某个对象身上的减益个数」做成
			// **参数来源**（能在「自定义参数 / 组」页选「从谁身上取」，公式里再参与 `10 + M * 5` 这种复合式子）。
			{
				Check("参数来源下拉里有「减益的个数（几种负面效果）」",
					ParamSources.Find(ParamSources.DebuffCount) is { } dc && dc.Display.Contains("减益") && dc.Hint.Contains("几种"),
					ParamSources.Find(ParamSources.DebuffCount)?.Display ?? "(没有这条)");
				Check("「指定敌人」的减益个数生成的是 ForgeFormulaRuntime.PowerCount(__fgTarget, \"Debuff\", null)",
					ForgeFormula.ParamExpr(new ParamSpec { Name = "M", Source = ParamSources.DebuffCount, Target = ParamTargets.ChosenEnemy })
						== "ForgeFormulaRuntime.PowerCount(__fgTarget, \"Debuff\", null)",
					ForgeFormula.ParamExpr(new ParamSpec { Name = "M", Source = ParamSources.DebuffCount, Target = ParamTargets.ChosenEnemy }));
				Check("「自己」的也认（换成 __fgSelf）",
					ForgeFormula.ParamExpr(new ParamSpec { Name = "M", Source = ParamSources.DebuffCount, Target = ParamTargets.Self })
						== "ForgeFormulaRuntime.PowerCount(__fgSelf, \"Debuff\", null)", "对");
				Check("这条来源算「要用到目标」（生成端会先把 __fgTarget 算出来）",
					ForgeFormula.NeedsTarget(new[] { new ParamSpec { Name = "M", Source = ParamSources.DebuffCount, Target = ParamTargets.ChosenEnemy } }), "对");

				// 一张「撕碎」：M = 目标身上的减益个数 → 伤害 = 10 + M*5（本体 Rend 的形状）
				CharacterProfile dcProfile = ProfileFactory.Sample();
				dcProfile.CustomParams.Clear();
				dcProfile.CustomParams.Add(new ParamSpec { Name = "M", Source = ParamSources.DebuffCount, Target = ParamTargets.ChosenEnemy });
				var dcCard = new CardSpec { Name = "减益个数参数卡", ClassName = "UiCheckParamDebuffCount", Cost = 1, CardType = "Attack", Rarity = "Rare", InCardPool = true };
				dcCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 1m, AmountFormula = "10 + M * 5", TargetSide = "Enemy" });
				dcProfile.Cards.Add(dcCard);
				string dcRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_paramdebuff_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					dcProfile.Paths.OutputDir = dcRoot;
					dcProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					dcProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var dcGen = ModGenerator.Generate(dcProfile);
					Check("（准备）「基础 + 每有一种减益 × N」这种复合公式能生成工程", dcGen.Success,
						dcGen.Success ? dcGen.ProjectRoot : string.Join(" ｜ ", dcGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					string dcSrc = File.ReadAllText(Path.Combine(dcGen.ProjectRoot, "cs", "Cards",
						Naming.From(dcProfile).CardClassName(dcProfile, dcCard) + ".cs"), Encoding.UTF8);
					Check("生成：参数 M 先算成 PowerCount(__fgTarget, \"Debuff\", null)",
						dcSrc.Contains("decimal __pM = ForgeFormulaRuntime.PowerCount(__fgTarget, \"Debuff\", null);"), "有");
					Check("生成：伤害用的是复合式子（10 + __pM * 5），不是固定数字",
						dcSrc.Contains("((10m) + (__pM * (5m)))"), "对");
					var dcRec = ProjectRecovery.FromProject(dcGen.ProjectRoot);
					Check("回读：这条参数来源认得回来（DebuffCount + 指定敌人）",
						dcRec.Profile.CustomParams.Any((ParamSpec x) => x.Name == "M"
							&& x.Source == ParamSources.DebuffCount && x.Target == ParamTargets.ChosenEnemy),
						string.Join(" / ", dcRec.Profile.CustomParams.Select((ParamSpec x) => x.Name + "=" + x.Source + "/" + x.Target)));
					Check("回读（减益个数参数）：没认出来的语句为 0", !dcRec.HasUnparsed, dcRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
				finally
				{
					try { Directory.Delete(dcRoot, true); } catch { }
				}
			}

			// ===== 「本张牌这一次打出造成的伤害」（ThisCardDamage，V0.2.194 —— 用户问的「荒疫打击」） ====
			//
			// 需求原文（用户）：「生成器怎么做荒疫打击」→「那做 B 这种，把做出来的参数放在参数弹窗里」。
			// 本体 BlightStrike.cs 的层数是 `attackCommand.Results.SelectMany(r => r).Sum(r => r.TotalDamage)`
			// —— 「这一下打出的伤害」（含被格挡的部分），所以这条读数是**卡片身上的一个属性**：
			// OnPlay 开头清零、每条「造成伤害」之后累加（不是本回合累计、不去查战斗历史）。
			{
				Check("内置读数里有 ThisCardDamage，而且是**卡牌专属**（CardOnly）",
					FormulaBuiltins.Find("ThisCardDamage") is { CardOnly: true },
					FormulaBuiltins.Find("ThisCardDamage")?.Display ?? "(没有这条)");
				Check("它的表达式读的是卡片身上那个属性（用 `this.` —— 属性在**派生卡片类**上，用 base. 会 CS0117）",
					FormulaBuiltins.Find("ThisCardDamage")!.Expr("__fgPlayer", "__fgSelf") == "((decimal)this.ForgeThisCardDamage)",
					FormulaBuiltins.Find("ThisCardDamage")!.Expr("__fgPlayer", "__fgSelf"));
				Check("卡牌专属的读数**不进**「自定义参数 / 组」的取值来源下拉（参数是打出那一刻先算一次的，选了会恒 0）",
					!ParamSources.All.Any((ParamSourceOption o) => o.Id == "ThisCardDamage")
					&& ParamSources.All.Count == 8 + FormulaBuiltins.All.Count((FormulaBuiltin b) => !b.CardOnly),
					$"{ParamSources.All.Count} 条");
				Check("参数参考窗里两类都能看到它（内置读数那一类按整张表列，来源那一类按 ParamSources 列）",
					ParamReferenceWindow.BuildCategories(Profile).Any(c => c.Items.Any(i => i.Id == "ThisCardDamage")),
					"内置读数那一类里有");
				Check("只特判「正好是这条读数」的写法（= 开头 / 大小写都认，复合式子不认）",
					CSharpCodeGen.IsExactThisCardDamage("ThisCardDamage")
					&& CSharpCodeGen.IsExactThisCardDamage(" = thiscarddamage ")
					&& !CSharpCodeGen.IsExactThisCardDamage("ThisCardDamage*2")
					&& !CSharpCodeGen.IsExactThisCardDamage(""),
					"对");

				// 一张「荒疫打击」：先造成伤害、再施加「等同于所造成伤害」的灾厄（本体 BlightStrike 的形状）
				var btProfile = ProfileFactory.Sample();
				var btCard = new CardSpec { Name = "自检荒疫打击", ClassName = "UiCheckBlightStrike", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				btCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 8m, AmountFormula = "8", UpgradeAmount = 2m, TargetSide = "Enemy" });
				btCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "DoomPower", AmountFormula = "ThisCardDamage", TargetSide = "Enemy" });
				btProfile.Cards.Add(btCard);
				var btPlain = new CardSpec { Name = "自检普通打击", ClassName = "UiCheckPlainStrike", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				btPlain.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, AmountFormula = "6", TargetSide = "Enemy" });
				btProfile.Cards.Add(btPlain);
				// 图上也用一次（【数值】模块的公式 = ThisCardDamage）—— 两条链都要记账
				var btForged = new CardSpec { Name = "自检锻造荒疫", ClassName = "UiCheckBlightForged", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true, IsForged = true };
				var btG = new ForgeGraphSpec();
				var btTrig = new ForgeNodeSpec { Kind = "Trigger" };
				btTrig.SetField("Timing", ForgeTimings.CardPlayed);
				var btDmg = new ForgeNodeSpec { Kind = "Effect" };
				btDmg.SetField("Effect", "Damage");
				btDmg.SetField("Amount", "8");
				var btDoom = new ForgeNodeSpec { Kind = "Effect" };
				btDoom.SetField("Effect", "ApplyPower");
				btDoom.SetField("PowerId", "DoomPower");
				var btVal = new ForgeNodeSpec { Kind = "Value" };
				btVal.SetField("Formula", "ThisCardDamage");
				btG.Nodes.AddRange(new[] { btTrig, btDmg, btDoom, btVal });
				btG.Links.Add(new ForgeLinkSpec { From = btTrig.Id, To = btDmg.Id });
				btG.Links.Add(new ForgeLinkSpec { From = btDmg.Id, To = btDoom.Id });
				btG.Links.Add(new ForgeLinkSpec { From = btVal.Id, To = btDoom.Id, FromPort = 0, ToPort = 1 });
				btForged.ForgeGraph = btG;
				btProfile.Cards.Add(btForged);
				Check("图上认得出这条读数（【数值】模块的公式里写了它）",
					ForgeGraphGen.GraphUsesThisCardDamage(btG)
					&& CSharpCodeGen.CardUsesThisCardDamage(btForged)
					&& CSharpCodeGen.CardUsesThisCardDamage(btCard)
					&& !CSharpCodeGen.CardUsesThisCardDamage(btPlain), "对");

				string btRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_thiscarddamage_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					btProfile.Paths.OutputDir = btRoot;
					btProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					btProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var btGen = ModGenerator.Generate(btProfile);
					Check("（准备）用 ThisCardDamage 的卡（手填 + 锻造）都能生成工程", btGen.Success,
						btGen.Success ? btGen.ProjectRoot : string.Join(" ｜ ", btGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					var btNaming = Naming.From(btProfile);
					string btSrc = File.ReadAllText(Path.Combine(btGen.ProjectRoot, "cs", "Cards", btNaming.CardClassName(btProfile, btCard) + ".cs"), Encoding.UTF8);
					string btPlainSrc = File.ReadAllText(Path.Combine(btGen.ProjectRoot, "cs", "Cards", btNaming.CardClassName(btProfile, btPlain) + ".cs"), Encoding.UTF8);
					string btForgedSrc = File.ReadAllText(Path.Combine(btGen.ProjectRoot, "cs", "Cards", btNaming.CardClassName(btProfile, btForged) + ".cs"), Encoding.UTF8);
					Check("生成：卡片上多了 ForgeThisCardDamage 属性（公开属性 —— 卡面预览的静态 lambda 读得到）",
						btSrc.Contains("public decimal ForgeThisCardDamage { get; private set; }"), "有");
					Check("生成：OnPlay 开头把它清零（所以是「这一次打出」而不是本回合累计）",
						btSrc.Contains("ForgeThisCardDamage = 0m;"), "有");
					Check("生成：每条「造成伤害」之后按本体口径累加（TotalDamage = 被格挡 + 没被格挡）",
						btSrc.Contains("ForgeThisCardDamage += (decimal)__atk1.Results.SelectMany(hits => hits).Sum(r => r.TotalDamage);"), "有");
					Check("生成：施加状态那条用的是现算表达式（不是固定数字）",
						btSrc.Contains("await PowerCmd.Apply<DoomPower>(choiceContext, cardPlay.Target, ((decimal)this.ForgeThisCardDamage)"), "有");
					Check("生成：**不**为它声明「现算预览值」变量（那个静态 lambda 只拿到 CardModel，读不到派生类的属性 → CS1061）",
						!btSrc.Contains("ForgeFormulaPowerVar<DoomPower>")
						&& btSrc.Contains("new PowerVar<DoomPower>(0m)"), "退回普通变量");
					Check("生成：没用这条读数的牌里**一个字符都不多**（老存档红线）",
						!btPlainSrc.Contains("ForgeThisCardDamage"), "干净");
					Check("生成：锻造那块布上也记账（同一个属性；临时变量名按模块唯一）",
						btForgedSrc.Contains("public decimal ForgeThisCardDamage { get; private set; }")
						&& btForgedSrc.Contains("ForgeThisCardDamage += (decimal)__fgAtk"), "有");
					string btCardsLoc = File.ReadAllText(Path.Combine(btGen.ProjectRoot, btProfile.ModId, "localization", "zhs", "cards.json"), Encoding.UTF8);
					Check("卡面：这一条印成「施加等量于所造成伤害的灾厄」、**不印数字**（本体 BlightStrike 的写法）",
						btCardsLoc.Contains("施加等量于所造成伤害的"), "有");
					Check("回读：公式按 CET:AmountFormula 标记带了回来",
						btSrc.Contains("// CET:AmountFormula=ThisCardDamage"), "有");

					var btRec = ProjectRecovery.FromProject(btGen.ProjectRoot);
					var btRecCard = btRec.Profile.Cards.FirstOrDefault(x => x.Effects.Any(e2 => e2.AmountFormula == "ThisCardDamage"));
					Check("回读：ThisCardDamage 那条公式原样认回来", btRecCard is not null,
						btRecCard is null ? "(没认出来)" : btRecCard.Name);
					Check("回读（ThisCardDamage）：没认出来的语句为 0", !btRec.HasUnparsed, btRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
				finally
				{
					try { Directory.Delete(btRoot, true); } catch { }
				}

				// 校验器：四种「会静默失效 / 生成不出来的」写法都要报出来
				var btBadRelic = new RelicSpec { Name = "自检灾厄遗物", ClassName = "UiCheckBlightRelic", Trigger = "PlayerTurnStart", Rarity = "Common" };
				btBadRelic.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "DoomPower", AmountFormula = "ThisCardDamage", TargetSide = "Enemy" });
				var btRelicProf = ProfileFactory.Sample();
				btRelicProf.Relics.Add(btBadRelic);
				Check("校验：遗物上用这条读数 → 报错（它读的是卡牌自己的字段）",
					ProfileValidator.Validate(btRelicProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("ThisCardDamage")),
					ProfileValidator.Validate(btRelicProf).FirstOrDefault((ValidationIssue i) => i.IsError && i.Message.Contains("ThisCardDamage"))?.Message ?? "(没报)");

				var btNoDmgProf = ProfileFactory.Sample();
				var btNoDmgCard = new CardSpec { Name = "自检没伤害", ClassName = "UiCheckBlightNoDamage", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				btNoDmgCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "DoomPower", AmountFormula = "ThisCardDamage", TargetSide = "Enemy" });
				btNoDmgProf.Cards.Add(btNoDmgCard);
				Check("校验：前面没有「造成伤害」→ 警告（恒 0，说清但不挡生成）",
					ProfileValidator.Validate(btNoDmgProf).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("前面没有任何「造成伤害」")),
					ProfileValidator.Validate(btNoDmgProf).FirstOrDefault((ValidationIssue i) => i.Message.Contains("前面没有任何「造成伤害」"))?.Message ?? "(没报)");

				var btCondProf = ProfileFactory.Sample();
				var btCondCard = new CardSpec
				{
					Name = "自检整张牌条件", ClassName = "UiCheckBlightCond", Cost = 1, CardType = "Attack", Rarity = "Common",
					InCardPool = true, Condition = new ConditionSpec { Kind = "HpBelowPercent", AmountFormula = "ThisCardDamage" },
				};
				btCondCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 8m, AmountFormula = "8", TargetSide = "Enemy" });
				btCondProf.Cards.Add(btCondCard);
				Check("校验：写在**整张牌条件**里 → 报错（IsPlayable / 描金边在打出之前求值，那时恒 0）",
					ProfileValidator.Validate(btCondProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("整张牌条件") && i.Message.Contains("ThisCardDamage")),
					ProfileValidator.Validate(btCondProf).FirstOrDefault((ValidationIssue i) => i.IsError && i.Message.Contains("整张牌条件"))?.Message ?? "(没报)");

				var btNextProf = ProfileFactory.Sample();
				var btNextCard = new CardSpec { Name = "自检下回合灾厄", ClassName = "UiCheckBlightNextTurn", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				btNextCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 8m, AmountFormula = "8", TargetSide = "Enemy" });
				btNextCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "DoomPower", AmountFormula = "ThisCardDamage", TargetSide = "Enemy", NextTurn = true });
				btNextProf.Cards.Add(btNextCard);
				Check("校验：勾了「下回合生效」→ 报错（延迟状态在下回合开始时才求值）",
					ProfileValidator.Validate(btNextProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("下回合生效") && i.Message.Contains("ThisCardDamage")),
					ProfileValidator.Validate(btNextProf).FirstOrDefault((ValidationIssue i) => i.IsError && i.Message.Contains("下回合生效"))?.Message ?? "(没报)");

				var btMixProf = ProfileFactory.Sample();
				var btMixCard = new CardSpec { Name = "自检混合公式", ClassName = "UiCheckBlightMixed", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				btMixCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 8m, AmountFormula = "8", TargetSide = "Enemy" });
				btMixCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "DoomPower", AmountFormula = "ThisCardDamage + 1", TargetSide = "Enemy" });
				btMixProf.Cards.Add(btMixCard);
				Check("校验：和别的量混着写 → 报错（卡面那个「现算预览值」拿不到这条读数，生成的代码编译不过）",
					ProfileValidator.Validate(btMixProf).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只能光秃秃地单独用")),
					ProfileValidator.Validate(btMixProf).FirstOrDefault((ValidationIssue i) => i.IsError && i.Message.Contains("ThisCardDamage"))?.Message ?? "(没报)");
				Check("「正好是它」的判定容忍外层括号（(ThisCardDamage) 也算）",
					CSharpCodeGen.IsExactThisCardDamage("(ThisCardDamage)")
					&& !CSharpCodeGen.IsExactThisCardDamage("(ThisCardDamage) + 1"), "对");

				// 图上：遗物 / 药水 / 状态的图里用这条读数 → 报错（`this` 不是卡，生成出来编译不过）
				var btRelicGraph = new ForgeGraphSpec();
				var btRT = new ForgeNodeSpec { Kind = "Trigger" };
				btRT.SetField("Timing", ForgeTimings.PlayerTurnStart);
