					ProfileValidator.Validate(btBlockRelicProf).FirstOrDefault((ValidationIssue i) => i.IsError && i.Message.Contains("ThisCardBlock"))?.Message ?? "(没报)");

				var btBlockNoBlockProf = ProfileFactory.Sample();
