						.SequenceEqual(new[]
						{
							"((decimal)this.ForgeThisCardExhaust)", "((decimal)this.ForgeThisCardDiscard)",
							"((decimal)this.ForgeThisCardTransform)", "((decimal)this.ForgeThisCardGenerate)",
						}), "对");

				var btCntProfile = ProfileFactory.Sample();
