			}

			// ===== 触发时机上的数值（用户要求：遗物 / 状态两边都要有 + 界面上看得见） ====
			{
				Check("数值那一栏在这些触发时机下显示（打牌 / 消耗 / 弃掉 / 抽到 / 生成 / 受伤 / 造伤 / 失去生命 / 格挡 / 花能量 / 花资源量）",
					new[] { "CardPlayed", "CardExhausted", "CardDiscarded", "CardDrawn", "CardGenerated",
							"DamageReceived", "DamageDealt", "HpLost", "BlockGained", "EnergySpent", "StarsSpent" }
						.All(k => new RelicSpec { Trigger = k }.ShowTriggerAmountField)
					&& !new RelicSpec { Trigger = "CombatStart" }.ShowTriggerAmountField, "显隐对");
				Check("「本回合 / 本场战斗」只给计数类显示（阈值类不显示）",
					new RelicSpec { Trigger = "CardPlayed" }.ShowTriggerScopeField
					&& !new RelicSpec { Trigger = "DamageReceived" }.ShowTriggerScopeField, "对");
				Check("标题按触发时机换说法（每累计几次 / 伤害至少多少 / 花掉多少点）",
					new RelicSpec { Trigger = "CardPlayed" }.TriggerAmountLabel.Contains("几次")
					&& new RelicSpec { Trigger = "DamageReceived" }.TriggerAmountLabel.Contains("伤害至少")
					&& new RelicSpec { Trigger = "EnergySpent" }.TriggerAmountLabel.Contains("花掉多少点"), "换了");
				var amtProfile = ProfileFactory.Sample();
				var amtPlayed = new RelicSpec
				{
					Name = "自检每 张牌", ClassName = "UiCheckAmtPlayed", Trigger = "CardPlayed", Rarity = "Common",
					TriggerAmount = 3m, TriggerScope = "Turn",
					Effects = { new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" } },
				};
				var amtDamaged = new RelicSpec
				{
					Name = "自检伤害5", ClassName = "UiCheckAmtDamaged", Trigger = "DamageReceived", Rarity = "Common",
					TriggerAmount = 5m,
					Effects = { new EffectSpec { Kind = "Block", Amount = 2m, TargetSide = "Self" } },
				};
				amtProfile.Relics.Add(amtPlayed);
				amtProfile.Relics.Add(amtDamaged);
				// V0.2.173（用户实测报的「每打出 3 张技能牌获得增益，但实际没生效」）：
				// 「打出一张牌时」= BeforeCardPlayed，本体这时**还没把这张牌记进 CardPlaysFinished**
				//（OnPlayWrapper 的顺序：Hook.BeforeCardPlayed → History.CardPlayStarted → OnPlay → … →
				// History.CardPlayFinished → Hook.AfterCardPlayedLate），所以计数必须用 CardPlaysStarted（含这一张），
				// 而且「只对哪类牌生效」也要拼进计数表达式（否则「每 3 张技能」= 每 3 张牌）。
				var amtSkill = new RelicSpec
				{
					Name = "自检每 张技能牌", ClassName = "UiCheckAmtSkill", Trigger = "CardPlayed", Rarity = "Common",
					TriggerAmount = 3m, TriggerScope = "Turn", TriggerCardFilter = "Skill",
					Effects = { new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" } },
				};
				amtProfile.Relics.Add(amtSkill);
				Check("打出一张牌时：计数用 CardPlaysStarted（含正在打出的这一张，Finished 会永远差一张 → 填 3 一次都不触发）",
					CSharpCodeGen.RelicSource(amtProfile, amtPlayed, 0)
						.Contains("CardPlaysStarted.Count(e => e.Actor == base.Owner.Creature && e.HappenedThisTurn(base.Owner.Creature.CombatState)) % 3 != 0) return;")
					&& !CSharpCodeGen.RelicSource(amtProfile, amtPlayed, 0).Contains("CardPlaysFinished.Count"), "对");
				Check("打出一张牌时：计数也按「只对哪类牌生效」筛（每 3 张技能牌 ≠ 每 3 张牌）",
					CSharpCodeGen.RelicSource(amtProfile, amtSkill, 1)
						.Contains("CardPlaysStarted.Count(e => e.Actor == base.Owner.Creature && e.CardPlay.Card.Type == CardType.Skill && e.HappenedThisTurn(base.Owner.Creature.CombatState)) % 3 != 0) return;"), "对");
				Check("打出一张牌时：没填牌型（Any）时计数里不带类型判据（老行为）",
					!CSharpCodeGen.RelicSource(amtProfile, amtPlayed, 0).Contains("e.CardPlay.Card.Type"), "不带");
				Check("阈值类生成「数值 ≥ N 才触发」",
					CSharpCodeGen.RelicSource(amtProfile, amtDamaged, 2).Contains("if (result.UnblockedDamage < 5m) return;"), "对");
				Check("生成端也写了 CET:TriggerAmount 标记（回读靠它）",
					CSharpCodeGen.RelicSource(amtProfile, amtPlayed, 0).Contains("// CET:TriggerAmount=3m CET:TriggerScope=Turn"), "有标记");
				// 状态那边同一套 
				var amtPow = new CustomPowerSpec { Name = "自检每 张消耗", ClassName = "UiCheckAmtExhaust" };
				var amtTrig = new PowerTriggerSpec { Kind = "CardExhausted", TriggerAmount = 2m, TriggerScope = "Combat" };
				amtTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				amtPow.Triggers.Add(amtTrig);
				Check("状态：`if (累计次数 % N == 0) { 这条效果 }` + 范围（本场战斗不带 HappenedThisTurn）",
					CSharpCodeGen.TriggerAmountCond("CardExhausted", 2m, "Combat", "base.Owner", "base.Owner.CombatState", "base.Owner.Player")
						is { } c && c.Contains("CardExhaustedEntry") && !c.Contains("HappenedThisTurn"), "对");
				// ===== V0.2.168：状态侧的「每累计 N 次」要**从这个状态被施加那一刻开始数** =====
				// 用户实测报的：「状态会直接统计整个回合（战斗）的计数，然后哪怕那时候还没上状态，也会计数……
				// 要打 4 张牌触发，但在上状态之前就打了 3 张，上状态之后只需要打 1 张就行了」。
				// 真因：本体历史是整个回合 / 整场战斗的累计，老写法直接 `累计 % N == 0` —— 把上状态之前的事也数了。
				// 修法：每个状态实例一个基准值字段（-1 = 还没记过），只数基准之后的事件。
				{
					var cntProf = ProfileFactory.Sample();
					var cntPow = new CustomPowerSpec { Name = "自检每累计", ClassName = "UiCheckCountBase" };
					var cntExhaust = new PowerTriggerSpec { Kind = "CardExhausted", TriggerAmount = 2m, TriggerScope = "Combat" };
					cntExhaust.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					var cntPlayed = new PowerTriggerSpec { Kind = "CardPlayed", TriggerAmount = 4m, TriggerScope = "Turn" };
					cntPlayed.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					cntPow.Triggers.Add(cntExhaust);
					cntPow.Triggers.Add(cntPlayed);
					cntProf.CustomPowers.Add(cntPow);
					string cntSrc = CustomPowerGen.Source(cntProf, cntPow, cntProf.CustomPowers.Count - 1);
					Check("V0.2.168：状态侧的「每累计 N 次」有**本实例基准值**字段（-1 = 还没记过；本回合 / 本场战斗各一份）",
						cntSrc.Contains("private int __cntCardExhaustedCombat = -1", StringComparison.Ordinal)
						&& cntSrc.Contains(", __cntCardPlayedTurn = -1", StringComparison.Ordinal), "有字段");
					Check("V0.2.168：基准值在第一次走到时记成「本次 - 1」（= 从上状态那一刻起，这次算第 1 次）",
						cntSrc.Contains("if (__cntCardPlayedTurn < 0 || __cnt <= __cntCardPlayedTurn) __cntCardPlayedTurn = __cnt - 1;", StringComparison.Ordinal)
						&& cntSrc.Contains("if (__cntCardExhaustedCombat < 0 || __cnt <= __cntCardExhaustedCombat) __cntCardExhaustedCombat = __cnt - 1;", StringComparison.Ordinal), "会记基准");
					Check("V0.2.168：判断用的是**相对基准**的差值（`(__cnt - 基准) % N == 0`），不是本体历史的总数",
						cntSrc.Contains("if (__cnt > __cntCardPlayedTurn && (__cnt - __cntCardPlayedTurn) % 4 == 0)", StringComparison.Ordinal)
						&& cntSrc.Contains("if (__cnt > __cntCardExhaustedCombat && (__cnt - __cntCardExhaustedCombat) % 2 == 0)", StringComparison.Ordinal)
						&& cntSrc.Contains("int __cnt = CombatManager.Instance.History.CardPlaysStarted.Count(e => e.Actor == base.Owner", StringComparison.Ordinal),
						"按差值判");
					// V0.2.173：`__cnt > 基准` 这一条**必须**有 —— 「打出一张牌时」跑的时候本体还没记这张牌，
					// 而 CardPlaysStarted 含正在打出的这一张 → 不挡掉「施加这个状态的那一张」的话，
					// 上状态前已经打够 N 张时一上状态就当场响一次。
					Check("V0.2.173：状态侧「每累计 N 次」把**施加这个状态的那一张牌**排除在外（`__cnt > 基准`）",
						cntSrc.Contains("if (__cnt > __cntCardPlayedTurn && (__cnt - __cntCardPlayedTurn) % 4 == 0)", StringComparison.Ordinal), "排除了");
					// 「敌人死亡」（本体历史里没有死亡记录，工具自己数）也一样要按基准
					var cntDeathProf = ProfileFactory.Sample();
					var cntDeath = new CustomPowerSpec { Name = "自检每累计死亡", ClassName = "UiCheckCountDeath" };
					var cntDeathTrig = new PowerTriggerSpec { Kind = "EnemyDeath", TriggerAmount = 2m, TriggerScope = "Combat" };
					cntDeathTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					cntDeath.Triggers.Add(cntDeathTrig);
					cntDeathProf.CustomPowers.Add(cntDeath);
					string cntDeathSrc = CustomPowerGen.Source(cntDeathProf, cntDeath, cntDeathProf.CustomPowers.Count - 1);
					Check("V0.2.168：「每 N 个敌人死亡」同样按基准（上状态之前死的敌人不算）",
						cntDeathSrc.Contains("private int __cntEnemyDeathCombat = -1", StringComparison.Ordinal)
						&& cntDeathSrc.Contains("BumpEnemyDeath(base.Owner.CombatState)", StringComparison.Ordinal)
						&& cntDeathSrc.Contains("if (__cnt > __cntEnemyDeathCombat && (__cnt - __cntEnemyDeathCombat) % 2 == 0)", StringComparison.Ordinal), "按基准");
				}
				// ===== V0.2.211：同一个状态上**两条筛选不同**的计数时机必须各记一份基准值 =====
				// 用户实测报的：「触发次数设置的 3+3，但第一次触发只需要 1+1 就行，后续触发才是 3+3」
				//（自定义状态里两条「每累计几次触发」：打出攻击牌 3 次 / 打出技能牌 3 次）。
				// 真因：基准值字段名以前只有「时机 + 范围」，两条共用 `__cntCardPlayedTurn` ——
				// 两条的累计值不同，各自都会执行 `if (字段 < 0 || 累计 <= 字段) 字段 = 累计 - 1;`，
				// 后跑的那条会用自己更小的「累计 - 1」把先跑那条的基准冲掉 → 差值虚高 → 第一次就凑够了。
				{
					var cntMultiProf = ProfileFactory.Sample();
					var cntMultiPow = new CustomPowerSpec { Name = "自检双计数", ClassName = "UiCheckCountTwo" };
					var cntAtk = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack", TriggerAmount = 3m, TriggerScope = "Turn" };
					cntAtk.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					var cntSkill = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Skill", TriggerAmount = 3m, TriggerScope = "Turn" };
					cntSkill.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m });
					cntMultiPow.Triggers.Add(cntAtk);
					cntMultiPow.Triggers.Add(cntSkill);
					cntMultiProf.CustomPowers.Add(cntMultiPow);
					string cntMultiSrc = CustomPowerGen.Source(cntMultiProf, cntMultiPow, cntMultiProf.CustomPowers.Count - 1);
					Check("V0.2.211：两条筛选不同的计数时机**各有一个基准值字段**（攻击一份、技能一份，不再共用）",
						cntMultiSrc.Contains("__cntCardPlayedTurnAttack = -1", StringComparison.Ordinal)
						&& cntMultiSrc.Contains("__cntCardPlayedTurnSkill = -1", StringComparison.Ordinal)
						&& !cntMultiSrc.Contains("private int __cntCardPlayedTurn = -1", StringComparison.Ordinal),
						"各一份");
					Check("V0.2.211：每条用的都是自己那份（`(累计 - 自己的基准) % 3 == 0`），两条互不覆盖",
						cntMultiSrc.Contains("e.CardPlay.Card.Type == CardType.Attack", StringComparison.Ordinal)
						&& cntMultiSrc.Contains("if (__cnt > __cntCardPlayedTurnAttack && (__cnt - __cntCardPlayedTurnAttack) % 3 == 0)", StringComparison.Ordinal)
						&& cntMultiSrc.Contains("e.CardPlay.Card.Type == CardType.Skill", StringComparison.Ordinal)
						&& cntMultiSrc.Contains("if (__cnt > __cntCardPlayedTurnSkill && (__cnt - __cntCardPlayedTurnSkill) % 3 == 0)", StringComparison.Ordinal),
						"各用各的");
					// 红线：只有一条计数时机（或两条筛选相同）时字段名一个字都不变（老工程逐字一致）
					var cntOneProf = ProfileFactory.Sample();
					var cntOnePow = new CustomPowerSpec { Name = "自检单计数", ClassName = "UiCheckCountOne" };
					var cntOneTrig = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack", TriggerAmount = 3m, TriggerScope = "Turn" };
					cntOneTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					cntOnePow.Triggers.Add(cntOneTrig);
					cntOneProf.CustomPowers.Add(cntOnePow);
					string cntOneSrc = CustomPowerGen.Source(cntOneProf, cntOnePow, cntOneProf.CustomPowers.Count - 1);
					Check("V0.2.211：（红线）只有一条计数时机时字段名照旧是 `__cntCardPlayedTurn`（老工程生成文本不变）",
						cntOneSrc.Contains("private int __cntCardPlayedTurn = -1", StringComparison.Ordinal)
						&& cntOneSrc.Contains("if (__cnt > __cntCardPlayedTurn && (__cnt - __cntCardPlayedTurn) % 3 == 0)", StringComparison.Ordinal),
						"没变");
					// 两条筛选用同一个值（都 Attack）→ 计数表达式相同 → 仍然共用一份（不该凭空多一个字段）
					var cntSameProf = ProfileFactory.Sample();
					var cntSamePow = new CustomPowerSpec { Name = "自检同筛选", ClassName = "UiCheckCountSame" };
					var cntSameA = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack", TriggerAmount = 3m, TriggerScope = "Turn" };
					cntSameA.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					var cntSameB = new PowerTriggerSpec { Kind = "CardPlayed", CardFilter = "Attack", TriggerAmount = 5m, TriggerScope = "Turn" };
					cntSameB.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m });
					cntSamePow.Triggers.Add(cntSameA);
					cntSamePow.Triggers.Add(cntSameB);
					cntSameProf.CustomPowers.Add(cntSamePow);
					string cntSameSrc = CustomPowerGen.Source(cntSameProf, cntSamePow, cntSameProf.CustomPowers.Count - 1);
					Check("V0.2.211：两条筛选**相同**时仍共用一份基准值（计数表达式一样，没必要各记一份）",
						cntSameSrc.Contains("private int __cntCardPlayedTurn = -1", StringComparison.Ordinal)
						&& !cntSameSrc.Contains("__cntCardPlayedTurnAttack", StringComparison.Ordinal),
						"共用");
					// 「每 N 个敌人死亡」的计数是工具自己 Bump 的：一个钩子上两条时必须只数一次
					var cntDeath2Prof = ProfileFactory.Sample();
					var cntDeath2Pow = new CustomPowerSpec { Name = "自检双死亡计数", ClassName = "UiCheckCountDeathTwo" };
					var cntDeath2A = new PowerTriggerSpec { Kind = "EnemyDeath", TriggerAmount = 2m, TriggerScope = "Combat" };
					cntDeath2A.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					var cntDeath2B = new PowerTriggerSpec { Kind = "EnemyDeath", TriggerAmount = 3m, TriggerScope = "Combat" };
					cntDeath2B.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m });
					cntDeath2Pow.Triggers.Add(cntDeath2A);
					cntDeath2Pow.Triggers.Add(cntDeath2B);
					cntDeath2Prof.CustomPowers.Add(cntDeath2Pow);
					string cntDeath2Src = CustomPowerGen.Source(cntDeath2Prof, cntDeath2Pow, cntDeath2Prof.CustomPowers.Count - 1);
					Check("V0.2.211：一处钩子上两条「每 N 个敌人死亡」→ 死亡计数只 Bump 一次（不然每次死亡被数成 2 个）",
						cntDeath2Src.Split("BumpEnemyDeath(").Length - 1 == 1
						&& cntDeath2Src.Contains("int __deathsNow = ", StringComparison.Ordinal)
						&& cntDeath2Src.Contains("int __cnt = __deathsNow;", StringComparison.Ordinal),
						$"Bump {cntDeath2Src.Split("BumpEnemyDeath(").Length - 1} 次");
				}
				// V0.2.173（用户实测：锻造卡「你去！」打出后抛 No selection screen prompt ⇒ 整张牌卡住）：
				// **「变化卡牌 + 取牌方式 = 自己选」** 这一档，节点图发射器（ForgeGraphGen.EmitEffect 第 2358 行）
				// 会读 base.SelectionScreenPrompt，而 NeedsSelectPrompt 以前没有这一档 → 本地化键没写 → 本体抛异常。
				// 钉死：生成代码里出现 base.SelectionScreenPrompt，对应键就必须写出来。
				{
					var promptProf = ProfileFactory.Sample();
					var promptCard = new CardSpec { Name = "选择变化探针", ClassName = "UiCheckPromptTransform", CardType = "Skill", Rarity = "Common", Cost = 1 };
					promptCard.Effects.Add(new EffectSpec
					{
						Kind = "TransformCard", Amount = 1m, TargetSide = "Self",
						CardPick = "Chosen", SelectPile = "Draw", SpawnPick = "Fixed", SpawnCardId = "Strike",
					});
					promptProf.Cards.Add(promptCard);
					string promptSrc = CSharpCodeGen.CardSource(promptProf, promptCard, promptProf.Cards.Count - 1);
					string promptJson = LocalizationGen.CardsJson(promptProf);
					Check("V0.2.173：变化卡牌 + 自己选（图上 Pick=Chosen）—— 本地化键写出来了（以前缺键 ⇒ 本体抛异常、那张牌一条效果都不跑）",
						!promptSrc.Contains("base.SelectionScreenPrompt")
						|| promptJson.Contains("\"UI_CHECK_PROMPT_TRANSFORM.selectionScreenPrompt\""), "键在");
					Check("V0.2.173：NeedsSelectPrompt 认「变化卡牌 + 自己选」这一档",
						LocalizationGen.NeedsSelectPrompt(promptCard.Effects), "认了");
				}
				// V0.2.174（用户实测：「格挡怎么不能失去」）——**节点图**上的【效果】=格挡 + 数值填负数。
				// 卡牌页那条链一直是对的（负数 → CreatureCmd.LoseBlock），但节点图那条直接写
				// `CreatureCmd.GainBlock(__fgFoe, (-5m), …)` —— 本体 GainBlock 对非正数**什么都不做**，
				// 于是「格挡一点没少」且没有任何报错。这里钉死：图上负数必须生成 LoseBlock。
				{
					var blkProf = ProfileFactory.Sample();
					var blkCard = new CardSpec { Name = "失去格挡探针", ClassName = "UiCheckLoseBlock", CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true };
					var blkGraph = ForgeGraphSpec.NewWithTiming("CardPlayed");
					var blkNode = new ForgeNodeSpec { Id = "blk1", Kind = "Effect" };
					blkNode.SetField("Effect", "Block");
					blkNode.SetField("Amount", "-5");
					blkNode.SetField("Pick", "Self");
					blkGraph.Nodes.Add(blkNode);
					blkGraph.Links.Add(new ForgeLinkSpec { From = blkGraph.TriggerNode!.Id, FromPort = 0, To = "blk1", ToPort = 0 });
					blkCard.ForgeGraph = blkGraph;
					blkProf.Cards.Add(blkCard);
					string blkSrc = CSharpCodeGen.CardSource(blkProf, blkCard, blkProf.Cards.Count - 1);
					Check("V0.2.174：节点图上「格挡 = 负数」生成 LoseBlock（以前生成 GainBlock(-5) ⇒ 本体什么都不做、格挡不会失去）",
						blkSrc.Contains("CreatureCmd.LoseBlock(") && !blkSrc.Contains("GainBlock(__fgFoe, (-5m)"), "生成了 LoseBlock");
				}
				Check("（红线）没填数值的触发时机：一个字符都不多（Condition 为空）",
					CSharpCodeGen.TriggerAmountCond("CardPlayed", 0m, "Turn", "base.Owner", "base.Owner.CombatState", "base.Owner.Player") is null
					&& CSharpCodeGen.TriggerAmountLines("CardPlayed", 0m, "Turn", "a", "b", "c").Count == 0, "老样子");
				// 用户实测报的坑（截图）：在编辑器里把「触发时机」换掉之后，那一样**不出现** —— 
				// 只有重新在左边列表点一次遗物 / 状态才会出来。原因是那几个「显隐 / 标题」是算出来的属性，
				// 而 Trigger（遗物）/ Kind（状态触发器）的 setter 只通知了「盯哪个状态」那几项，没通知它们。"
				// 所以这里**真的打开遗物页 / 状态页、真的去动那两个下拉**，再看编辑器里有没有那一栏。"
				{
					var amtUiRelic = new RelicSpec { Name = "自检数值栏遗物", ClassName = "UiCheckAmtRow", Rarity = "Common", Trigger = "CombatStart" };
					amtUiRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 1m, TargetSide = "Self" });
					Profile.Relics.Add(amtUiRelic);
					MainTabs.SelectedItem = MainTabs.Items.OfType<TabItem>().FirstOrDefault(x => (x.Header as string) == "遗物");
					RelicList.SelectedItem = amtUiRelic;
					UpdateLayout();
					// 第 10 批起：「触发时机」下拉搬到了「触发时机列表」下面那条编辑器里
					// （属性区不再放单时机控件，免得两处都能改）——找到那一条并选中它。
					// ⚠ 不能只按属性名 "Kind" 找：遗物页同时还有「条件选项」的下拉（绑 Condition.Kind），
					//   按 ItemsSource 认那一个才是触发时机（候选 = RelicTriggers）。
					RelicTriggerList.SelectedItem = amtUiRelic.Triggers.FirstOrDefault();
					UpdateLayout();
					List<ComboBox> allRelicCombos = new List<ComboBox>();
					CollectComboBoxes(RelicDetail, allRelicCombos);
					ComboBox? amtCombo = allRelicCombos.FirstOrDefault(c => ReferenceEquals(c.ItemsSource, RelicTriggers))
						?? FindComboBoundTo(RelicDetail, "Kind");
					Check("（准备）遗物页打开了、也找到了「触发时机」那个下拉", amtCombo is not null,
						amtCombo is null ? "(没找到 " : (amtCombo.SelectedValue as string) ?? "(空 ");
					Check("（对照）「战斗开始时」这种没有数值的时机：那一栏确实不显示",
						!VisibleTextsIn(RelicDetail).Any(t => t.Contains("每累计") || t.Contains("至少多少") || t.Contains("统计范围")), "不显示");
					if (amtCombo is not null)
					{
						amtCombo.SelectedValue = "CardPlayed";
						UpdateLayout();
						Check("遗物页：编辑器里换成「打出一张牌后」→「每累计几次触发」那一栏**当场出现**（不用重新点一次遗物）",
							VisibleTextsIn(RelicDetail).Any(t => t.Contains("每累计几次触发")) && VisibleTextsIn(RelicDetail).Any(t => t.Contains("统计范围")),
							string.Join(" / ", VisibleTextsIn(RelicDetail).Where(t => t.Contains("触发")).Take(4)));
						amtCombo.SelectedValue = "DamageReceived";
						UpdateLayout();
						Check("再换成「受到伤害后」→ 标题当场变成「伤害至少多少才触发」、范围那栏收起来",
							VisibleTextsIn(RelicDetail).Any(t => t.Contains("伤害至少多少才触发"))
							&& !VisibleTextsIn(RelicDetail).Any(t => t.Contains("统计范围")), "换了");
					}
					// 状态那边（用户另一张截图：说明里写着「N 填在下面那栏」但下面没有那栏）"
					var amtUiPower = new CustomPowerSpec { Name = "自检数值栏状态", ClassName = "UiCheckAmtRowPower" };
					var amtUiTrig = new PowerTriggerSpec { Kind = "TurnStart" };
					amtUiTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 1m, TargetSide = "Self" });
					amtUiPower.Triggers.Add(amtUiTrig);
					Profile.CustomPowers.Add(amtUiPower);
					MainTabs.SelectedItem = CustomPowerTab;
					CustomPowerList.SelectedItem = amtUiPower;
					UpdateLayout();
					CustomTriggerList.SelectedItem = amtUiTrig;
					UpdateLayout();
					ComboBox? amtKindCombo = FindComboBoundTo(CustomPowerDetail, "Kind");
					Check("（准备）状态页打开了、也找到了那条时机的「触发时机」下拉", amtKindCombo is not null,
						amtKindCombo is null ? "(没找到 " : (amtKindCombo.SelectedValue as string) ?? "(空 ");
					if (amtKindCombo is not null)
					{
						amtKindCombo.SelectedValue = "PowerReached";
						UpdateLayout();
						Check("状态页：编辑器里换成「某个状态层数到达 N 层时」→「到达 N 层」那栏**当场出现**",
							VisibleTextsIn(CustomPowerDetail).Any(t => t.Contains("到达 N 层")),
							string.Join(" / ", VisibleTextsIn(CustomPowerDetail).Where(t => t.Contains("到达") || t.Contains("状态层数")).Take(4)));
						amtKindCombo.SelectedValue = "CardExhausted";
						UpdateLayout();
						Check("状态页：再换成「消耗一张牌后」→「每累计几次触发」+「统计范围」那两栏也当场出现",
							VisibleTextsIn(CustomPowerDetail).Any(t => t.Contains("每累计几次触发"))
							&& VisibleTextsIn(CustomPowerDetail).Any(t => t.Contains("统计范围"))
							&& !VisibleTextsIn(CustomPowerDetail).Any(t => t.Contains("到达 N 层")),
							string.Join(" / ", VisibleTextsIn(CustomPowerDetail).Where(t => t.Contains("触发") || t.Contains("统计")).Take(5)));
					}
					Profile.Relics.Remove(amtUiRelic);
					Profile.CustomPowers.Remove(amtUiPower);
				}
			}

			// ===== 遗物页：序号按「每块 5 个」预留显示（用户要求 2026-10-XX）=====
			// 用户原话：「左侧序号直接显示，可以每次多生成五个序号，比如有 3 个选项时，左侧序号显示 1~5，
			// 加第 6 个的时候，显示 6~10.」
			// 实现口径（也和用户对齐过）：列表里显示的**序号行数** = 5 × ceil(max(N,1)/5)（N = 真遗物数）；
			// 多出来的行是**空槽**（SlotPlaceholder，只显示灰色序号，没有内容，不能被当成遗物选中，
			// 但可以当拖放落点）；序号仍然是**位置号 1..N 连续**，不是块内 1..5 循环；
			// 空槽只活在界面镜像集合 RelicRows 里，Profile.Relics 里永远只有真遗物。
			{
				IList<RelicSpec> kept = Profile.Relics.ToList();      // 这一轮的临时改动最后原样还回去
				RelicSpec? savedSelection = RelicUiSelection;
				SelectTabRoot("遗物");                                 // 断言要看布局，得先切到遗物页
				// 界面上真能看到序号列：行里的 TextBlock 数 = 「序号.」形状的文字个数
				//（列表虚拟化 → 得先量过布局才有容器；不改虚拟化设置，布局断言还按老口径量列表宽高）
				int VisibleOrdinalTexts(int count)
				{
					UpdateLayout();
					List<TextBlock> blocks = new List<TextBlock>();
					CollectTextBlocks(RelicList, blocks);
					return blocks.Count(t => (t.Text ?? "").EndsWith(".") && (t.Text ?? "").Length >= 2
						&& char.IsDigit((t.Text ?? "x")[0]) && t.Text!.Length <= 3);
				}
				try
				{
					// ---- 断言 1：3 只遗物 → 显示 1~5 行，4/5 是空槽、不能被当成遗物选中 ----
					Profile.Relics.Clear();
					Profile.Relics.Add(new RelicSpec { Name = "槽甲", ClassName = "UiCheckSlot1", Rarity = "Common", Trigger = "CombatStart" });
					Profile.Relics.Add(new RelicSpec { Name = "槽乙", ClassName = "UiCheckSlot2", Rarity = "Rare", Trigger = "CombatStart" });
					Profile.Relics.Add(new RelicSpec { Name = "槽丙", ClassName = "UiCheckSlot3", Rarity = "Shop", Trigger = "CombatStart" });
					RelicList.SelectedItem = Profile.Relics[0];
					UpdateLayout();
					string ord3 = string.Join(",", RelicRows.Select(r => r.OrdinalText));
					string roster3 = string.Join(" | ", RelicRows.Select(r => r is RelicSpec rr ? "遗物:" + rr.Name + ":" + rr.Ordinal : "空槽:" + r.OrdinalText));
					Check("（空槽 ①）3 只遗物 → 列表显示 1~5 行（4、5 是空槽）",
						RelicRows.Count == 5 && ord3 == "1.,2.,3.,4.,5."
						&& RelicRows.Take(3).All(r => !r.IsPlaceholder) && RelicRows.Skip(3).All(r => r.IsPlaceholder)
						&& RelicList.Items.Count == 5,
						$"行 {RelicRows.Count} / 序号 {ord3} / 列表 Items {RelicList.Items.Count} / 名册[{roster3}]");
					Check("（空槽 ①）界面上真画出了 5 个序号（不是只算在集合里）",
						VisibleOrdinalTexts(3) == 5, $"看到 {VisibleOrdinalTexts(3)} 个「N.」");
					// 选中空槽：不能被当成遗物（SelectedItem 不是 RelicSpec）、也不能改了任何一只真遗物
					string beforeDump = string.Join(" | ", Profile.Relics.Select(r => r.Name + ":" + r.Ordinal + ":" + r.ClassName));
					RelicList.SelectedItem = Profile.Relics[0];            // 先明确选中「槽甲」，下面再点空槽
					RelicSpec? beforeSel = RelicUiSelection;
					RelicList.SelectedItem = RelicRows[3];
					UpdateLayout();
					Check("（空槽 ①）选中空槽行：选中项不是 RelicSpec、当前选中的真遗物没变、真遗物一个字段都没被改",
						RelicList.SelectedItem is not RelicSpec && ReferenceEquals(RelicUiSelection, beforeSel)
						&& string.Join(" | ", Profile.Relics.Select(r => r.Name + ":" + r.Ordinal + ":" + r.ClassName)) == beforeDump
						&& Profile.Relics.Count == 3,
						$"SelectedItem={RelicList.SelectedItem?.GetType().Name ?? "(null)"}（空槽行） UiSel={RelicUiSelection?.Name ?? "(null)"} 遗物 {Profile.Relics.Count} 只");

					// ---- 断言 2：加到 6 只 → 显示 1~10 行，7~10 是空槽 ----
					for (int i = 4; i <= 6; i++)
						Profile.Relics.Add(new RelicSpec { Name = "槽" + i, ClassName = "UiCheckSlot" + i, Rarity = "Common", Trigger = "CombatStart" });
					UpdateLayout();
					string ord6 = string.Join(",", RelicRows.Select(r => r.OrdinalText));
					Check("（空槽 ②）加到 6 只 → 列表显示 1~10 行（7~10 是空槽）",
						RelicRows.Count == 10 && ord6 == string.Join(",", Enumerable.Range(1, 10).Select(i => i + "."))
						&& RelicRows.Take(6).All(r => !r.IsPlaceholder) && RelicRows.Skip(6).All(r => r.IsPlaceholder),
						$"行 {RelicRows.Count} / 序号 {ord6}");
					Check("（空槽 ②）界面上真画出了 10 个序号", VisibleOrdinalTexts(6) == 10, $"看到 {VisibleOrdinalTexts(6)} 个「N.」");

					// ---- 断言 3：删回 5 只 → 行数回到 5，序号 1~5 ----
					Profile.Relics.RemoveAt(5);
					UpdateLayout();
					string ord5 = string.Join(",", RelicRows.Select(r => r.OrdinalText));
					Check("（空槽 ③）删回 5 只 → 行数回到 5（序号 1~5，没有空槽）",
						RelicRows.Count == 5 && ord5 == "1.,2.,3.,4.,5." && RelicRows.All(r => !r.IsPlaceholder)
						&& Profile.Relics.Count == 5,
						$"行 {RelicRows.Count} / 序号 {ord5} / 真遗物 {Profile.Relics.Count}");

					// ---- 断言 4：拖一只遗物到空槽 → Profile.Relics 顺序真的变、序号仍是 1..N 连续 ----
					Profile.Relics.RemoveAt(4);                    // 退回 4 只：1~4 真遗物 + 第 5 行空槽
					RelicSpec draggedRelic = Profile.Relics[0];
					RelicList.SelectedItem = draggedRelic;         // 明确把选中项放成「槽甲」，点空槽时才好验「没变」
					UpdateLayout();
					// 第 5 行（行号 5 → UI 索引 4）是空槽：RelicRowAtPoint 给的 Relic 必须是 null。
					// ⚠ 鼠标位置要用**列表坐标系**：ItemContainer 左上角在列表里的位置 + 行内偏移。
					DependencyObject? rowC = RelicList.ItemContainerGenerator.ContainerFromIndex(4) as DependencyObject;
					(RelicSpec? rowCData, string rowCDetail) = (null, "(没有容器)");
					if (rowC is FrameworkElement rowCFe)
					{
						Point offset = rowCFe.TransformToVisual(RelicList).Transform(new Point(0, 0));
						var probes = new (double Fx, double Fy)[] { (0.5, 0.5), (0.5, 0.25), (0.5, 0.75) };
						int nullHits = 0;
						var got = new List<string>();
						foreach ((double fx, double fy) in probes)
						{
							var at = RelicRowAtPoint(new Point(offset.X + rowCFe.ActualWidth * fx, offset.Y + rowCFe.ActualHeight * fy));
							got.Add($"({fx:F2},{fy:F2})→行{at.Index}/{(at.Relic?.Name ?? "无遗物")}");
							if (at.Relic is null) nullHits++;
						}
						rowCData = nullHits > 0 ? null : RelicRowAtPoint(new Point(offset.X + rowCFe.ActualWidth / 2, offset.Y + rowCFe.ActualHeight / 2)).Relic;
						rowCDetail = $"容器 {rowCFe.ActualWidth:F0}x{rowCFe.ActualHeight:F0}@{offset.X:F0},{offset.Y:F0} " + string.Join(" ", got);
					}
					Check("（空槽 ④）空槽那一行在屏幕上点得到、而且它不给出任何遗物（Relic = null）",
						rowC is not null && rowCData is null && RelicRows[4].IsPlaceholder,
						rowCDetail);
					bool slotMoved = MoveRelicTo(draggedRelic, null, 4);       // 拖到第 5 行（空槽）→ 夹到末尾
					UpdateLayout();
					Check("（空槽 ④）拖一只遗物到空槽：Profile.Relics 顺序真的变、序号仍是 1..N 连续",
						slotMoved && Profile.Relics.Count == 4
						&& ReferenceEquals(Profile.Relics[3], draggedRelic)
						&& Profile.Relics.Select((r, i) => r.Ordinal == i + 1 && r.OrdinalText == (i + 1) + ".").All(x => x)
						&& RelicRows.Take(4).SequenceEqual<IRelicSlotRow>(Profile.Relics)
						&& RelicRows[4].IsPlaceholder && RelicRows.Count == 5,
						$"拖到末尾 → " + string.Join(" → ", Profile.Relics.Select(r => r.Name)) + $" ／ 序号 {string.Join(",", RelicRows.Select(r => r.OrdinalText))}");

					// ---- 断言 5：占位项不影响任何真数据 / 不影响生成结果 ----
					var slotDemo = new RelicSpec { Name = "空槽演示", ClassName = "", Rarity = "Common", Trigger = "CombatStart" };
					slotDemo.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
					var slotProfileA = ProfileFactory.Sample();
					var slotProfileB = ProfileFactory.Sample();
					slotProfileA.Relics.Clear();
					slotProfileB.Relics.Clear();
					slotProfileA.Relics.Add(slotDemo);
					slotProfileB.Relics.Add(slotDemo);
					slotProfileA.Paths.OutputDir = Path.Combine(Path.GetTempPath(), "forge_slot_a_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					slotProfileB.Paths.OutputDir = Path.Combine(Path.GetTempPath(), "forge_slot_b_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					slotProfileA.Paths.VanillaProject = Profile.Paths.VanillaProject;
					slotProfileB.Paths.VanillaProject = Profile.Paths.VanillaProject;
					slotProfileA.Paths.GameDataDir = Profile.Paths.GameDataDir;
					slotProfileB.Paths.GameDataDir = Profile.Paths.GameDataDir;
					// 载荷逐字相等：数量 1（真遗物数）与顺序，占位项一个都进不去
					Check("（空槽 ⑤）Profile.Relics 里只有真遗物（1 只），空槽项一个都没混进去",
						slotProfileA.Relics.Count == 1 && slotProfileB.Relics.Count == 1
						&& ReferenceEquals(slotProfileA.Relics[0], slotDemo)
						&& !RelicRows.OfType<RelicSpec>().Any(r => ReferenceEquals(r, slotDemo) == false && !Profile.Relics.Contains(r)),
						$"A={slotProfileA.Relics.Count} 只 / B={slotProfileB.Relics.Count} 只");
					// 生成端：模组入口（含所有遗物类名）逐字一致（口径和 V0.2.124 一样：只比生成结果）
					string slotEntryA = PatchesGen.ModEntrySource(slotProfileA, null);
					string slotEntryB = PatchesGen.ModEntrySource(slotProfileB, null);
					Check("（空槽 ⑤）生成结果和「没有空槽」时逐字一致（模组入口源码长度 + 内容都相同）",
						slotEntryA == slotEntryB && slotEntryA.Length > 0,
						$"长度 {slotEntryA.Length} / {slotEntryB.Length}，逐字相同={slotEntryA == slotEntryB}");
					// 真生成一遍：输出文件清单里不能出现任何空槽痕迹
					var slotGen = ModGenerator.Generate(slotProfileA);
					string slotFiles = slotGen.Success
						? string.Join("\n", Directory.GetFiles(slotGen.ProjectRoot, "*", SearchOption.AllDirectories)
							.Select(f => Path.GetRelativePath(slotGen.ProjectRoot, f).Replace('\\', '/'))
							.OrderBy(x => x, StringComparer.Ordinal))
						: "";
					Check("（空槽 ⑤）真生成一遍：没有空槽类 / 空槽文件（也没多出第 2 只遗物）",
						slotGen.Success && slotFiles.Length > 0
						&& !slotFiles.Contains("SlotPlaceholder") && !slotFiles.Contains("UiCheckSlot")
						&& !slotFiles.Contains("空槽") && slotProfileA.Relics.Count == 1,
						slotGen.Success ? $"生成 {slotFiles.Split('\n').Length} 个文件，一个「空槽」都没有" : string.Join(" / ", slotGen.Issues.Where(i => i.IsError).Take(3)));
					try { if (Directory.Exists(slotProfileA.Paths.OutputDir)) Directory.Delete(slotProfileA.Paths.OutputDir, true); } catch { }
					try { if (Directory.Exists(slotProfileB.Paths.OutputDir)) Directory.Delete(slotProfileB.Paths.OutputDir, true); } catch { }

					// ---- 断言 6：空槽行只有灰序号（颜色实测和真遗物行不一样），而且不参与选中 ----
					// ⚠ 列表是虚拟化的 → 只有**已经实化**的行才在可视树上：这里把实化到的序号 TextBlock
					// 全收集起来，按「真遗物行 / 空槽行」分组比颜色（不去假设第 1 行一定实化了）。
					UpdateLayout();
					List<TextBlock> ordBlocks = new List<TextBlock>();
					CollectTextBlocks(RelicList, ordBlocks);
					var ordInfos = ordBlocks
						.Where(t => (t.Text ?? "").Length is 2 or 3 && (t.Text ?? "").EndsWith(".") && char.IsDigit((t.Text ?? "x")[0]))
						.Select(t => (Text: t.Text!, Color: (t.Foreground as SolidColorBrush)?.Color.ToString() ?? "(不是纯色)", Visible: t.IsVisible))
						.ToList();
					var realInfos = ordInfos.Where(o => Profile.Relics.Any(r => r.OrdinalText == o.Text)).ToList();
					var slotInfos = ordInfos.Where(o => RelicRows.Any(r => r.IsPlaceholder && r.OrdinalText == o.Text)).ToList();
					Check("（空槽 ⑥）空槽行的序号是**灰**的：颜色和真遗物行不一样、行本身可见",
						realInfos.Count > 0 && slotInfos.Count > 0
						&& slotInfos.All(s => s.Visible
							&& (s.Color.Contains("AAAAAA", StringComparison.OrdinalIgnoreCase) || s.Color.Contains("170,170,170", StringComparison.Ordinal)))
						&& realInfos.All(r => !r.Color.Contains("AAAAAA", StringComparison.OrdinalIgnoreCase) && !r.Color.Contains("170,170,170", StringComparison.Ordinal)),
						$"实化序号 {string.Join(" / ", ordInfos.Select(o => o.Text + "=" + o.Color + (o.Visible ? "" : "(不可见)")))} ／ 真遗物 {realInfos.Count} 行、空槽 {slotInfos.Count} 行");
					Check("（空槽 ⑥）空槽行的「遗物名」那一列是空的（没有内容）",
						RelicRows[4] is SlotPlaceholder ph6 && ph6.Display.Length == 0 && ph6.RowTip is null
						&& string.IsNullOrEmpty(RelicRows[4].OrdinalText) == false,
						$"Display='{((SlotPlaceholder)RelicRows[4]).Display}' RowTip={(RelicRows[4].RowTip ?? "(null)")}");
					// 全选也不能把空槽算进去（它比真遗物多，是最容易漏掉的一条链路）
					RelicList.SelectedItems.Clear();
					foreach (IRelicSlotRow row in RelicRows)
					{
						if (!row.IsPlaceholder) RelicList.SelectedItems.Add(row);
					}
					Check("（空槽 ⑥）「全选」只选中真遗物：SelectedItems 里一个空槽都没有",
						RelicList.SelectedItems.Count == Profile.Relics.Count
						&& RelicList.SelectedItems.OfType<SlotPlaceholder>().Count() == 0
						&& !RelicList.SelectedItems.Cast<object>().Any(o => o is IRelicSlotRow { IsPlaceholder: true }),
						$"选中 {RelicList.SelectedItems.Count} / 真遗物 {Profile.Relics.Count} / 行数 {RelicRows.Count}");
					RelicList.SelectedItems.Clear();
				}
				finally
				{
					Profile.Relics.Clear();
					foreach (RelicSpec r in kept) Profile.Relics.Add(r);
					RefreshRelicOrdinals();
					RelicList.SelectedItem = (savedSelection is not null && Profile.Relics.Contains(savedSelection))
						? savedSelection
						: Profile.Relics.FirstOrDefault();
					SyncDetail();
					UpdateLayout();
				}
			}

			// ===== 「某个状态被移除时」（用户要求） ====
			// 本体**没有**任何「状态被移除」的全局钩子：PowerModel.AfterRemoved 是那个状态自己的实例钩子
			//（遗物 / 别的状态都收不到），而「被效果直接清除」（PowerCmd.Remove）也不走层数变化那条路。"
			// 所以这条由工具自己给 PowerModel.RemoveInternal（本体所有移除的唯一出口）打补丁再转发。"
			{
				Check("遗物 / 状态两边的触发时机菜单里都有「某个状态被移除时」（同一个 id + 同一个显示名）",
					EffectCatalog.RelicTriggers.Any((TriggerOption t) => t.Id == "PowerRemoved" && t.Display == "某个状态被移除时")
					&& PowerTriggers.All.Any((PowerTriggerOption t) => t.Kind == "PowerRemoved" && t.Display == "某个状态被移除时"), "都在");
				var prRelic = new RelicSpec { Trigger = "PowerRemoved" };
				Check("选了它就会出现「盯哪个状态」那两栏（留空 = 任意状态），并说清这条是工具补的钩子",
					prRelic.ShowTriggerPowerFields && prRelic.TriggerHint.Contains("被移除") && prRelic.TriggerHint.Contains("补丁"), prRelic.TriggerHint);
				Check("状态那边同样能选「盯哪个状态」",
					new PowerTriggerSpec { Kind = "PowerRemoved" }.NeedsPower, "能");
				// 生成：遗物侧
				var prProfile = ProfileFactory.Sample();
				var prRelicSpec = new RelicSpec
				{
					Name = "自检易伤被移除", ClassName = "UiCheckRemoveRelic", Rarity = "Common",
					Trigger = "PowerRemoved", TriggerPowerId = "VulnerablePower",
				};
				prRelicSpec.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" });
				prProfile.Relics.Add(prRelicSpec);
				string prRelicSrc = CSharpCodeGen.RelicSource(prProfile, prRelicSpec, 0);
				Check("遗物侧生成的是**普通方法**（不是 override —— 本体没有这个钩子，补丁调它）",
					prRelicSrc.Contains("public async Task OnForgePowerRemovedAsync(PowerModel power)")
					&& !prRelicSrc.Contains("public override async Task OnForgePowerRemovedAsync"), "普通方法");
				Check("遗物侧守卫：只看自己身上的状态 + 只盯选中的那个状态",
					prRelicSrc.Contains("power.Owner != base.Owner.Creature") && prRelicSrc.Contains("power is not VulnerablePower"), "守卫对");
				Check("「盯哪个状态」写一行回读标记（守卫以后改写法也不丢配置）",
					prRelicSrc.Contains("// CET:PowerWatch=VulnerablePower"), "有标记");
				Check("需要 choiceContext 的效果（抽牌）→ 工具自己造一个 HookPlayerChoiceContext（战斗里专用）",
					prRelicSrc.Contains("HookPlayerChoiceContext"), "造了");
				// 生成：状态侧
				var prPow = new CustomPowerSpec { Name = "自检移除状态", ClassName = "UiCheckRemovePower" };
				var prTrig = new PowerTriggerSpec { Kind = "PowerRemoved", PowerId = "WeakPower" };
				prTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self" });
				prPow.Triggers.Add(prTrig);
				prProfile.CustomPowers.Add(prPow);
				string prPowSrc = CustomPowerGen.Source(prProfile, prPow, 0);
				Check("状态侧也是普通方法 + 只盯自己的那一个状态",
					prPowSrc.Contains("public async Task OnForgePowerRemovedAsync(PowerModel power)")
					&& prPowSrc.Contains("power.Owner == base.Owner") && prPowSrc.Contains("power is WeakPower"), "对");
				// 补丁那个文件
				Check("（红线）没用到这条时机 → 不生成补丁文件（默认存档输出逐字不变）",
					!CSharpCodeGen.UsesPowerRemovedTrigger(ProfileFactory.Sample()), "不生成");
				Check("用到 → 判定为「要生成补丁文件」", CSharpCodeGen.UsesPowerRemovedTrigger(prProfile), "要生成");
				string prPatch = CSharpCodeGen.PowerRemovalSource(prProfile);
				Check("补丁打在**同步**的 PowerModel.RemoveInternal 上（本体所有移除的唯一出口：PowerCmd.Remove / 清除减益 / 战斗结束清状态都走它）",
					prPatch.Contains("typeof(PowerModel), \"RemoveInternal\"") && prPatch.Contains("[HarmonyLib.HarmonyPostfix]"), "打在对的地方");
				Check("补丁把通知转发给：该玩家的遗物 + 该生物身上还留着的自定义状态 + 被移除的那个状态自己",
					prPatch.Contains("UiCheckRemoveRelic __r") && prPatch.Contains("UiCheckRemovePower __c") && prPatch.Contains("UiCheckRemovePower __me"), "三处都转发");
				Check("转发是 fire-and-forget（补丁是同步的，用本体自带的 TaskHelper.RunSafely 起安全任务）",
					prPatch.Contains("TaskHelper.RunSafely("), "用了 TaskHelper");
				// 生成 → 回读
				string prRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_powremoved_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					prProfile.Paths.OutputDir = prRoot;
					prProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					prProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var prGen = ModGenerator.Generate(prProfile);
					Check("（准备）带「某个状态被移除时」的存档能生成工程", prGen.Success,
						prGen.Success ? prGen.ProjectRoot : string.Join(" ｜ ", prGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (prGen.Success)
					{
						Check("工程里真的有 cs/PowerRemoval.cs（用到才写）",
							File.Exists(Path.Combine(prGen.ProjectRoot, "cs", "PowerRemoval.cs")), "有");
						var prRec = ProjectRecovery.FromProject(prGen.ProjectRoot);
						RelicSpec? prBack = prRec.Profile.Relics.FirstOrDefault((RelicSpec x) => x.ClassName == "UiCheckRemoveRelic");
						Check("回读：遗物的触发时机 / 盯哪个状态 / 效果都认得回来",
							prBack is not null && prBack.Trigger == "PowerRemoved" && prBack.TriggerPowerId == "VulnerablePower" && prBack.Effects.Count == 1,
							prBack is null ? "(缺 " : $"{prBack.Trigger} / {prBack.TriggerPowerId} / {prBack.Effects.Count}");
						CustomPowerSpec? prBackPow = prRec.Profile.CustomPowers.FirstOrDefault((CustomPowerSpec x) => x.ClassName == "UiCheckRemovePower");
						Check("回读：状态那边的触发时机 / 盯哪个状态也认得回来",
							prBackPow is not null && prBackPow.Triggers.Any((PowerTriggerSpec x) => x.Kind == "PowerRemoved" && x.PowerId == "WeakPower"),
							prBackPow is null ? "(缺 " : string.Join("/", prBackPow.Triggers.Select((PowerTriggerSpec x) => x.Kind + ":" + x.PowerId)));
						Check("回读没有认不出来的语句", !prRec.HasUnparsed, prRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { if (Directory.Exists(prRoot)) Directory.Delete(prRoot, true); } catch { }
				}
			}

			// ④ 遗物触发时机多一条「获得时」（本体 AfterObtained：本体的「好吃饼干 / 磨刀石 / 爪子」都是它）
			Check("遗物触发时机里有「获得时」，而且排在第一位（第一个选项也是原来那条「战斗开始时」的兜底不受影响）",
				EffectCatalog.RelicTriggers.Any((TriggerOption t) => t.Id == "Obtained" && t.Display == "获得时")
				&& EffectCatalog.RelicTriggers.First((TriggerOption t) => t.Id == "Obtained").HookSignature == "AfterObtained()", "在");
			Check("「获得时」没有 choiceContext，但生成端会自己造一个（本体 BlockingPlayerChoiceContext 就是为遗物 AfterObtained 准备的）",
				!CSharpCodeGen.HasContext("Obtained") && CSharpCodeGen.CanBootstrapContext("Obtained")
				&& !CSharpCodeGen.CanBootstrapContext("GoldGained"), "会补上下文");
			CharacterProfile obProbe = ProfileFactory.Sample();
			obProbe.Relics.Add(new RelicSpec
			{
				Name = "自检获得时遗物", ClassName = "UiCheckOnObtain", Rarity = "Common", Trigger = "Obtained",
				Effects =
				{
					new EffectSpec { Kind = "Draw", Amount = 1m },
					new EffectSpec { Kind = "CardReward", Amount = 3m },
				},
			});
			CharacterProfile obSimpleProbe = ProfileFactory.Sample();
			obSimpleProbe.Relics.Add(new RelicSpec
			{
				Name = "自检获得时遗物简单", ClassName = "UiCheckOnObtainSimple", Rarity = "Common", Trigger = "Obtained",
				Effects = { new EffectSpec { Kind = "Gold", Amount = 50m } },
			});
			string obSrc = CSharpCodeGen.RelicSource(obProbe, obProbe.Relics[^1], 0);
			string obSimpleSrc = CSharpCodeGen.RelicSource(obSimpleProbe, obSimpleProbe.Relics[^1], 0);
			Check("「获得时」生成的是本体的 AfterObtained() 钩子 + HasUponPickupEffect（拾取时生效的遗物都这么声明）",
				obSrc.Contains("public override async Task AfterObtained()")
				&& obSrc.Contains("public override bool HasUponPickupEffect => true;"), "对");
			Check("需要选牌上下文的效果（抽牌 / 卡牌奖励）→ 生成端自己造一个阻塞式 choiceContext",
				obSrc.Contains("var choiceContext = new MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext();")
				&& obSrc.Contains("CardPileCmd.Draw(choiceContext,") && obSrc.Contains("CardSelectCmd.FromChooseACardScreen(choiceContext,"), "造了");
			Check("不需要上下文的效果不会多造一个用不上的变量（免得编译告警）",
				!obSimpleSrc.Contains("BlockingPlayerChoiceContext") && obSimpleSrc.Contains("PlayerCmd.GainGold"), "不会");
			Check("校验器给「获得时」一句说明，而且不再报「缺少 choiceContext」那种警告",
				ProfileValidator.Validate(obProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("获得时"))
				&& !ProfileValidator.Validate(obProbe).Any((ValidationIssue i) => i.Message.Contains("缺少 choiceContext")), "有说明");
			// 生成 → 回读：AfterObtained 要能认回「获得时」
			string obRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_obtain_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile obGenProbe = ProfileFactory.Sample();
				obGenProbe.Paths.OutputDir = obRoot;
				obGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				obGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				obGenProbe.Relics.Add(new RelicSpec
				{
					Name = "自检获得时遗物", ClassName = "UiCheckOnObtain", Rarity = "Common", Trigger = "Obtained",
					Effects = { new EffectSpec { Kind = "Draw", Amount = 2m }, new EffectSpec { Kind = "CardReward", Amount = 3m } },
				});
				Check("（准备）「获得时」遗物的存档能生成工程", ModGenerator.Generate(obGenProbe).Success, obRoot);
				var obRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(obGenProbe));
				var recOb = obRec.Profile.Relics.FirstOrDefault((RelicSpec r) => r.ClassName == "UiCheckOnObtain");
				Check("回读：AfterObtained 认回「获得时」，效果也在",
					recOb is not null && recOb.Trigger == "Obtained" && recOb.Effects.Any((EffectSpec e) => e.Kind == "Draw" && e.Amount == 2m),
					$"Trigger={recOb?.Trigger} 效果数={recOb?.Effects.Count}");
				Check("回读：其它时机上的「获得卡牌奖励」也认得出来（以前只认「战斗胜利后」那种 AddExtraReward 写法）",
					recOb is not null && recOb.Effects.Any((EffectSpec e) => e.Kind == "CardReward" && e.Amount == 3m),
					string.Join(" / ", recOb?.Effects.Select((EffectSpec e) => $"{e.Kind} {e.Amount}") ?? Array.Empty<string>()));
				Check("回读没有认不出来的语句", !obRec.HasUnparsed, obRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(obRoot)) Directory.Delete(obRoot, true); } catch { }
			}

			// ④b 「受到伤害时」是每一下都触发（用户报「5 点伤害触发了五次」）→ 新增「受到攻击后（连击只算一次）」，
			//     走本体的 AfterAttack（AbstractModel 注释写明 multi-attack 时它在所有命中结束后只跑一次），
			//     并给原来那条补上本体的判据 result.UnblockedDamage > 0（全被格挡的那一下不算）。
			Check("遗物触发时机里有「受到攻击后（连击只算一次）」，用的就是本体的 AfterAttack",
				EffectCatalog.RelicTriggers.Any((TriggerOption t) => t.Id == "Attacked" && t.Display.Contains("连击只算一次"))
				&& CSharpCodeGen.HasContext("Attacked"), "在");
			Check("自定义状态的触发时机里也有它（同名两条：每一下 / 连击只算一次）",
				PowerTriggers.All.Any((PowerTriggerOption t) => t.Kind == "Attacked" && t.Display.Contains("连击只算一次"))
				&& PowerTriggers.All.Any((PowerTriggerOption t) => t.Kind == "DamageReceived" && t.Display.Contains("每一下")), "在");
			CharacterProfile atkProbe = ProfileFactory.Sample();
			atkProbe.Relics.Add(new RelicSpec
			{
				Name = "自检挨打遗物", ClassName = "UiCheckAttacked", Rarity = "Common", Trigger = "Attacked",
				Effects = { new EffectSpec { Kind = "Block", Amount = 3m } },
			});
			atkProbe.Relics.Add(new RelicSpec
			{
				Name = "自检每一下遗物", ClassName = "UiCheckPerHit", Rarity = "Common", Trigger = "DamageReceived",
				Effects = { new EffectSpec { Kind = "Block", Amount = 3m } },
			});
			string atkSrc = CSharpCodeGen.RelicSource(atkProbe, atkProbe.Relics[^2], 0);
			string perHitSrc = CSharpCodeGen.RelicSource(atkProbe, atkProbe.Relics[^1], 0);
			Check("「受到攻击后」生成 AfterAttack + 「这一次攻击真的打到我」的判据（连击只跑一次）",
				atkSrc.Contains("public override async Task AfterAttack(PlayerChoiceContext choiceContext, MegaCrit.Sts2.Core.Commands.Builders.AttackCommand command)")
				&& atkSrc.Contains("decimal __takenThisAttack = command.Results.SelectMany(hits => hits).Where(r => r.Receiver == base.Owner.Creature).Sum(r => r.UnblockedDamage);")
				&& atkSrc.Contains("if (__takenThisAttack <= 0) return;"), "对");
			Check("「受到伤害时（每一下）」补上了本体那句判据：全被格挡 / 0 伤害不算（和本体原体黏土一致）",
				perHitSrc.Contains("if (result.UnblockedDamage <= 0) return;"), "补上了");
			CharacterProfile atkPowerProbe = ProfileFactory.Sample();
			atkPowerProbe.CustomPowers.Clear();
			atkPowerProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检挨打状态", ClassName = "UiCheckAttackedPower", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "Attacked", Effects = { new EffectSpec { Kind = "Block", Amount = 2m } } } },
			});
			atkPowerProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检每一下状态", ClassName = "UiCheckPerHitPower", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "DamageTaken", Effects = { new EffectSpec { Kind = "Block", Amount = 2m } } } },
			});
			string atkPowerSrc = CustomPowerGen.Source(atkPowerProbe, atkPowerProbe.CustomPowers[0], 0);
			string perHitPowerSrc = CustomPowerGen.Source(atkPowerProbe, atkPowerProbe.CustomPowers[1], 0);
			Check("自定义状态里的「自己受到攻击后」也走 AfterAttack（连击只算一次），并且带 same 判据",
				atkPowerSrc.Contains("public override async Task AfterAttack(PlayerChoiceContext choiceContext, MegaCrit.Sts2.Core.Commands.Builders.AttackCommand command)")
				&& atkPowerSrc.Contains("Where(r => r.Receiver == base.Owner)"), "对");
			Check("自定义状态里的「自己受到伤害后（每一下）」也有 UnblockedDamage > 0 的判据",
				perHitPowerSrc.Contains("if (result.UnblockedDamage <= 0) return;"), "有");

			// ---- ④c 第 10 批 ②：「失去生命」不再算「受到伤害」（用户实测：血祭 / 献祭这种掉血也触发了「自己受到伤害后」）----
			//     本体 DamageProps.cardHpLoss = Unblockable | Unpowered（穿盾 + 没有来源加成）= 血祭 / 献祭 / 中毒那类掉血；
			//     Hook.AfterDamageReceived 在 CreatureCmd.Damage 里**无条件**广播（不看 props）→ 必须自己判。
			//     三份守卫（遗物页 / 锻造页 / 状态页）都得有这一句，而且只有 DamageReceived / DamageDealt 这两条有；
			//     敌人那两条**故意不加**（敌人侧没有「敌人失去生命」这条时机可以替代，排掉就等于功能丢了）。
			{
				const string hpLossGuard = "if (props.HasFlag(ValueProp.Unblockable) && props.HasFlag(ValueProp.Unpowered)) return;";
				var selfDmgGuardProf = ProfileFactory.Sample();
				selfDmgGuardProf.Relics.Clear();
				selfDmgGuardProf.Relics.Add(new RelicSpec
				{
					Name = "自检失去生命不算受伤", ClassName = "UiCheckHpLossGuard", Rarity = "Common",
					Trigger = "DamageReceived", Effects = { new EffectSpec { Kind = "Block", Amount = 1m } },
				});
				// 守卫必须**排在那条归属守卫之后**：`if (target != base.Owner.Creature) return;` 是「只认自己」，
				// 新守卫插在它后面、其它判据之前（顺序错了行为一样，但自检里钉住位置，以后重构不会挪错地方）。
				string selfDmgGuardSrc = CSharpCodeGen.RelicSource(selfDmgGuardProf, selfDmgGuardProf.Relics[0], 0);
				int guardAt = selfDmgGuardSrc.IndexOf(hpLossGuard, StringComparison.Ordinal);
				bool relicOk = guardAt >= 0
					&& selfDmgGuardSrc.IndexOf("if (target != base.Owner.Creature) return;", StringComparison.Ordinal) < guardAt;
				Check("遗物页「自己受到伤害后」：生成结果里带「失去生命不算受到伤害」的那句守卫，"
					+ "而且排在「只认自己」那条归属守卫**之后**（排除 Unblockable + Unpowered = 本体 DamageProps.cardHpLoss）",
					relicOk, relicOk ? "在（位置也对）" : "不在 / 顺序不对");

				bool forgeReceivedGuard = CSharpCodeGen.ForgeTriggerGuardLines(ForgeTimings.DamageReceived, "", 0m)
					.Any(l => l.Contains(hpLossGuard, StringComparison.Ordinal));
				bool forgeDealtGuard = CSharpCodeGen.ForgeTriggerGuardLines(ForgeTimings.DamageDealt, "", 0m)
					.Any(l => l.Contains(hpLossGuard, StringComparison.Ordinal));
				bool pageReceivedGuard = CSharpCodeGen.RelicTriggerGuardLines("DamageReceived", "", 0m, "Any", selfDmgGuardProf)
					.Any(l => l.Contains(hpLossGuard, StringComparison.Ordinal));
				bool pageDealtGuard = CSharpCodeGen.RelicTriggerGuardLines("DamageDealt", "", 0m, "Any", selfDmgGuardProf)
					.Any(l => l.Contains(hpLossGuard, StringComparison.Ordinal));
				var hpLossProf = ProfileFactory.Sample();
				hpLossProf.CustomPowers.Clear();
				hpLossProf.CustomPowers.Add(new CustomPowerSpec
				{
					Name = "自检失去生命不算受伤状态", ClassName = "UiCheckHpLossGuardPower", Type = "Buff",
					Triggers = { new PowerTriggerSpec { Kind = "DamageTaken", Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } } },
				});
				hpLossProf.CustomPowers.Add(new CustomPowerSpec
				{
					Name = "自检失去生命不算造成伤害状态", ClassName = "UiCheckHpLossGuardDealtPower", Type = "Buff",
					Triggers = { new PowerTriggerSpec { Kind = "DamageDealt", Effects = { new EffectSpec { Kind = "Block", Amount = 1m } } } },
				});
				string hpLossPowerSrc = CustomPowerGen.Source(hpLossProf, hpLossProf.CustomPowers[0], 0);
				string hpLossPowerDealtSrc = CustomPowerGen.Source(hpLossProf, hpLossProf.CustomPowers[1], 0);
				bool powerOk = hpLossPowerSrc.Contains(hpLossGuard, StringComparison.Ordinal)
					&& hpLossPowerDealtSrc.Contains(hpLossGuard, StringComparison.Ordinal);
				Check("三份守卫**完全一致**：遗物页 / 锻造页 / 状态页的「自己受到伤害后」和「自己造成伤害后」都带同一句"
					+ "（`props.HasFlag(ValueProp.Unblockable) && props.HasFlag(ValueProp.Unpowered)`），缺一份就会有一处照旧被血祭骗到",
					pageReceivedGuard && pageDealtGuard && forgeReceivedGuard && forgeDealtGuard && powerOk,
					$"遗物页 受伤={pageReceivedGuard} 造成={pageDealtGuard} ｜ 锻造页 受伤={forgeReceivedGuard} 造成={forgeDealtGuard} ｜ 状态页 受伤={hpLossPowerSrc.Contains(hpLossGuard, StringComparison.Ordinal)} 造成={hpLossPowerDealtSrc.Contains(hpLossGuard, StringComparison.Ordinal)}");
				Check("敌人那两条（敌人受到伤害后 / 敌人造成伤害后）**故意不带**这句守卫 —— "
					+ "敌人侧没有「敌人失去生命」这条时机可以替代，排掉就等于功能丢了（代码注释里也写了为什么不动）",
					(CSharpCodeGen.RelicTriggerGuardLines("EnemyDamaged", "", 0m, "Any", selfDmgGuardProf)
						.Concat(CSharpCodeGen.RelicTriggerGuardLines("EnemyDealtDamage", "", 0m, "Any", selfDmgGuardProf))
						.Concat(CSharpCodeGen.ForgeTriggerGuardLines(ForgeTimings.EnemyDamaged, "", 0m))
						.Concat(CSharpCodeGen.ForgeTriggerGuardLines(ForgeTimings.EnemyDealtDamage, "", 0m)))
					.All(l => !l.Contains(hpLossGuard, StringComparison.Ordinal)), "没带（对）");

				// 「对自己造成伤害」（卡牌链，Kind="Damage" + TargetSide="Self"）生成的是 Unpowered | Move（**格挡能挡**）——
				// 不含 Unblockable → 新守卫不会误伤它，照旧算「受到伤害」（想无视格挡请用效果种类「失去生命」）。
				var selfDmgProf = ProfileFactory.Sample();
				selfDmgProf.Relics.Clear();
				selfDmgProf.Relics.Add(new RelicSpec
				{
					Name = "自检对自己造成伤害", ClassName = "UiCheckSelfDamage", Rarity = "Common", Trigger = "DamageReceived",
					Effects = { new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Self" } },
				});
				string selfDmgSrc = CSharpCodeGen.RelicSource(selfDmgProf, selfDmgProf.Relics[0], 0);
				string selfDmgLine = "await CreatureCmd.Damage(choiceContext, base.Owner.Creature, base.DynamicVars.Damage.BaseValue, ValueProp.Unpowered, null, null);";
				bool selfDmgOk = selfDmgSrc.Contains(selfDmgLine, StringComparison.Ordinal)
					&& !selfDmgSrc.Contains("ValueProp.Unblockable | ValueProp.Unpowered", StringComparison.Ordinal);
				string selfDmgActual = selfDmgSrc.Split('\n')
					.FirstOrDefault(l => l.Contains("base.Owner.Creature, ", StringComparison.Ordinal)
						&& l.Contains("CreatureCmd.Damage", StringComparison.Ordinal))?.Trim() ?? "(没生成)";
				Check("「对自己造成伤害」（TargetSide=Self）= Unpowered（不含 Unblockable，**格挡能挡**）→ 仍旧算「受到伤害」，"
					+ "不会被新守卫误伤（和「失去生命」分得开）",
					selfDmgOk, selfDmgOk ? selfDmgLine : ("实际生成：" + selfDmgActual));

				// 卡牌链上同一件事（本体 DamageProps.cardUnpowered = `Unpowered | Move`，也**没有** Unblockable）：
				// 新守卫要求「同时带 Unblockable」，所以卡面上的「对自己造成伤害」照旧算「受到伤害」（格挡能挡）。
				var selfDmgCardProf = ProfileFactory.Sample();
				var selfDmgCard = new CardSpec
				{
					Name = "自检自伤牌", ClassName = "UiCheckSelfDamageCard", CardType = "Skill", Rarity = "Common",
					Cost = 1, InCardPool = true,
					Effects = { new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Self" } },
				};
				selfDmgCardProf.Cards.Add(selfDmgCard);
				string selfDmgCardLine = "await CreatureCmd.Damage(choiceContext, base.Owner.Creature, base.DynamicVars.Damage.BaseValue, ValueProp.Unpowered | ValueProp.Move, this, cardPlay);";
				string selfDmgCardSrc = CSharpCodeGen.CardSource(selfDmgCardProf, selfDmgCard, 0);
				Check("卡牌链的「对自己造成伤害」= 本体 DamageProps.cardUnpowered（`Unpowered | Move`，不含 Unblockable）→ "
					+ "新守卫也不会误伤它（卡面写「受到 N 点伤害」、护盾能挡）",
					selfDmgCardSrc.Contains(selfDmgCardLine, StringComparison.Ordinal), selfDmgCardLine);
			}

			// ===== V0.2.139 ①：致死的那一下不许再跑效果（否则「回复生命」= 多人模式下的复活）=====
			// 三条时机（受到伤害 / 失去生命 / 受到攻击后）× 三条链（状态 / 遗物 / 锻造）都要有
			// 「自己已经死了就直接返回」，而且要排在效果之前、用各自链上**正确的实例表达式**：
			//   · 状态链的 base.Owner 本身就是 Creature → `base.Owner.IsDead`；
			//   · 遗物链 / 锻造链的 base.Owner 是 **Player** → 必须 `base.Owner.Creature.IsDead`
			//     （锻造链的守卫由 CSharpCodeGen.ForgeTriggerGuardLines 生成，遗物链 / 锻造链共用同一套文本）。
			{
				string deadPower = "if (base.Owner.IsDead) return;";
				string deadOwnerCreature = "if (base.Owner.Creature.IsDead) return;";
				var deadProbeProfile = ProfileFactory.Sample();
				deadProbeProfile.CustomPowers.Clear();
				deadProbeProfile.Relics.Clear();
				string[] deadTimings = { "DamageReceived", "HpLost", "Attacked" };
				var deadMissing = new List<string>();
				var deadOrderBad = new List<string>();
				foreach (string dt in deadTimings)
				{
					// 状态链
					var dp = new CustomPowerSpec { Name = "自检致死回血状态" + dt, ClassName = "UiCheckDeadPower" + dt, Type = "Buff" };
					dp.Triggers.Add(new PowerTriggerSpec
					{
						Kind = dt,
						Effects = { new EffectSpec { Kind = "Heal", Amount = 3m, TargetSide = "Self" } },
					});
					deadProbeProfile.CustomPowers.Clear();
					deadProbeProfile.CustomPowers.Add(dp);
					string powerSrcDead = CustomPowerGen.Source(deadProbeProfile, dp, 0);
					if (!powerSrcDead.Contains(deadPower, StringComparison.Ordinal)) deadMissing.Add("状态:" + dt);
					int deadAt = powerSrcDead.IndexOf(deadPower, StringComparison.Ordinal);
					int healAt = powerSrcDead.IndexOf("CreatureCmd.Heal", StringComparison.Ordinal);
					if (deadAt < 0 || healAt < 0 || deadAt > healAt) deadOrderBad.Add("状态:" + dt);

					// 遗物链
					var dr = new RelicSpec
					{
						Name = "自检致死回血遗物" + dt, ClassName = "UiCheckDeadRelic" + dt, Rarity = "Common", Trigger = dt,
						Effects = { new EffectSpec { Kind = "Heal", Amount = 3m, TargetSide = "Self" } },
					};
					deadProbeProfile.Relics.Clear();
					deadProbeProfile.Relics.Add(dr);
					string relicSrcDead = CSharpCodeGen.RelicSource(deadProbeProfile, dr, 0);
					if (!relicSrcDead.Contains(deadOwnerCreature, StringComparison.Ordinal)) deadMissing.Add("遗物:" + dt);
					int rDeadAt = relicSrcDead.IndexOf(deadOwnerCreature, StringComparison.Ordinal);
					int rHealAt = relicSrcDead.IndexOf("CreatureCmd.Heal", StringComparison.Ordinal);
					if (rDeadAt < 0 || rHealAt < 0 || rDeadAt > rHealAt) deadOrderBad.Add("遗物:" + dt);

					// 锻造链（守卫行由 ForgeTriggerGuardLines 生成，图和遗物页同一套）
					string forgeGuardDead = string.Join("\n", CSharpCodeGen.ForgeTriggerGuardLines(dt, "StrengthPower", 3m));
					if (!forgeGuardDead.Contains(deadOwnerCreature, StringComparison.Ordinal)) deadMissing.Add("锻造:" + dt);
				}
				Check("V0.2.139：三条时机（受到伤害 / 失去生命 / 受到攻击后）× 三条链（状态 / 遗物 / 锻造）的守卫里"
					+ "都有「自己已经死了就直接返回」—— 致死的那一下不再跑效果（否则效果里的「回复生命」会把自己拉回来，"
					+ "多人模式下队友还活着看起来就是复活）",
					deadMissing.Count == 0, deadMissing.Count == 0 ? "9 处全有" : "缺：" + string.Join("/", deadMissing));
				Check("V0.2.139：「自己已经死了」那句守卫排在效果**之前**（状态链 / 遗物链逐字查位置）",
					deadOrderBad.Count == 0, deadOrderBad.Count == 0 ? "都在效果之前" : "顺序不对：" + string.Join("/", deadOrderBad));
				Check("V0.2.139：三条链各自用**正确的实例表达式** —— 状态链 base.Owner.IsDead（base.Owner 就是 Creature），"
					+ "遗物链 / 锻造链 base.Owner.Creature.IsDead（那两条链的 base.Owner 是 Player，写错会 CS1061 编译不过）",
					!CSharpCodeGen.RelicTriggerGuardLines("DamageReceived", "", 0m, "Any", deadProbeProfile)
						.Concat(CSharpCodeGen.ForgeTriggerGuardLines("DamageReceived", "", 0m))
						.Any(l => l.Contains("if (base.Owner.IsDead)", StringComparison.Ordinal))
					&& CSharpCodeGen.RelicTriggerGuardLines("HpLost", "", 0m, "Any", deadProbeProfile)
						.Concat(CSharpCodeGen.ForgeTriggerGuardLines("HpLost", "", 0m))
						.Concat(CSharpCodeGen.RelicTriggerGuardLines("Attacked", "", 0m, "Any", deadProbeProfile))
						.Concat(CSharpCodeGen.ForgeTriggerGuardLines("Attacked", "", 0m))
						.All(l => !l.Contains("if (base.Owner.IsDead)", StringComparison.Ordinal)), "对");
			}

			// ===== V0.2.139 ②：负值「施加增益/减益」按「本体允不允许负层数」分流 =====
			// 用户报的：「在生成器填负值的力量不生效」（卡牌「施加增益/减益」数值 -2、未升级）。
			// 根因：负数**一律**走 GetPower + ModifyAmount → 目标身上本来没有力量时什么都不做。
			// 改成：允许负层数的 5 个状态（力量/敏捷/专注/尖啸/萎缩）→ 照本体「尖啸」那套**直接施加负数**；
			// 其余（虚弱/易伤…）保持 GetPower + ModifyAmount。
			{
				Check("V0.2.139：本体允许负层数的名单 = 力量 / 敏捷 / 专注 / 尖啸 / 萎缩，虚弱 / 易伤不在里面"
					+ "（生成端就是按这份名单分流的唯一判据）",
					EffectCatalog.AllowsNegativeLayers("StrengthPower")
					&& EffectCatalog.AllowsNegativeLayers("DexterityPower")
					&& EffectCatalog.AllowsNegativeLayers("FocusPower")
					&& EffectCatalog.AllowsNegativeLayers("ShriekPower")
					&& EffectCatalog.AllowsNegativeLayers("ShrinkPower")
					&& !EffectCatalog.AllowsNegativeLayers("WeakPower")
					&& !EffectCatalog.AllowsNegativeLayers("VulnerablePower"), "对");

				var negPowProfile = ProfileFactory.Sample();
				negPowProfile.CustomPowers.Clear();
				var negPow = new CustomPowerSpec { Name = "自检负值力量状态", ClassName = "UiCheckNegPowerStr", Type = "Buff" };
				negPow.Triggers.Add(new PowerTriggerSpec
				{
					Kind = "PlayerTurnStart",
					Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, TargetSide = "Self" } },
				});
				negPowProfile.CustomPowers.Add(negPow);
				string negPowSrc = CustomPowerGen.Source(negPowProfile, negPow, 0);

				var negCardProfile = ProfileFactory.Sample();
				var negCard = new CardSpec
				{
					Name = "自检负值力量卡", ClassName = "UiCheckNegStrCard", CardType = "Skill", Rarity = "Common",
					Cost = 1, InCardPool = true,
				};
				negCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, UpgradeAmount = 0m, TargetSide = "Self" });
				negCardProfile.Cards.Add(negCard);
				string negCardSrc = CSharpCodeGen.CardSource(negCardProfile, negCard, 0);

				var negRelicProfile = ProfileFactory.Sample();
				negRelicProfile.Relics.Clear();
				var negRelic = new RelicSpec
				{
					Name = "自检负值力量遗物", ClassName = "UiCheckNegStrRelic", Rarity = "Common", Trigger = "PlayerTurnStart",
					Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, UpgradeAmount = 0m, TargetSide = "Self" } },
				};
				negRelicProfile.Relics.Add(negRelic);
				string negRelicSrc = CSharpCodeGen.RelicSource(negRelicProfile, negRelic, 0);

				var negPotionProfile = ProfileFactory.Sample();
				negPotionProfile.Potions.Clear();
				var negPotion = new PotionSpec
				{
					Name = "自检负值力量药水", ClassName = "UiCheckNegStrPotion",
					Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, UpgradeAmount = 0m, TargetSide = "Self" } },
				};
				negPotionProfile.Potions.Add(negPotion);
				string negPotionSrc = CSharpCodeGen.PotionSource(negPotionProfile, negPotion, 0);

				Check("V0.2.139：力量 -2（本体允许负层数）→ 生成的是**直接施加负值** `PowerCmd.Apply<StrengthPower>(…)`"
					+ "（照本体「尖啸 PiercingWail」那套：目标身上本来 0 层也能扣成 -2），而且**不出现** GetPower<StrengthPower>",
					negPowSrc.Contains("PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, -2m,", StringComparison.Ordinal)
					&& !negPowSrc.Contains("GetPower<StrengthPower>", StringComparison.Ordinal)
					// 卡牌链上「数值」实参长什么样取决于档案是不是**从文件载入的**
					//（ProfileFactory.Load / Sample 会把固定数值迁进「数值公式」那一栏，生成的是 -((2m))；
					//  自检里现造的卡没走过那道迁移，生成的是 base.DynamicVars["StrengthPower"].BaseValue）——
					// 两种形态都是「直接施加负值」，所以这里两种都认，但**必须**是负数、且不许有 GetPower。
					&& Regex.IsMatch(negCardSrc, @"PowerCmd\.Apply<StrengthPower>\(choiceContext, base\.Owner\.Creature, (-\(\(2m\)\)|base\.DynamicVars\[""StrengthPower""\]\.BaseValue),", RegexOptions.None)
					&& !negCardSrc.Contains("GetPower<StrengthPower>", StringComparison.Ordinal)
					&& !negCardSrc.Contains("ModifyAmount", StringComparison.Ordinal), "对");
				Check("V0.2.139：遗物 / 药水链上的力量 -2 也走同一条写法（cardSource 照旧传 null —— 遗物/药水不是 CardModel，"
					+ "传 this 会让整个模组编译不过）",
					negRelicSrc.Contains("PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner.Creature, base.DynamicVars[\"StrengthPower\"].BaseValue, base.Owner.Creature, null)", StringComparison.Ordinal)
					&& negPotionSrc.Contains("PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner.Creature, base.DynamicVars[\"StrengthPower\"].BaseValue, base.Owner.Creature, null)", StringComparison.Ordinal)
					&& !negRelicSrc.Contains("GetPower<StrengthPower>", StringComparison.Ordinal)
					&& !negPotionSrc.Contains("GetPower<StrengthPower>", StringComparison.Ordinal), "对");

				// 用户报告的那条路的**端到端复现**：存成 JSON 再 Load 回来（ProfileFactory.Load 会把固定数值
				// 迁进「数值公式」那一栏，界面加载存档再生成就是这条路）。
				// 以前 IsNegativeAmount 看到 UsesAmountFormula 就直接把负数分档关掉了，
				// 于是「填 -2 的力量」被当成正数生成：力量**和虚弱**都变成 Apply(…, -2/-1)。
				string negMigJson = Path.Combine(Path.GetTempPath(), "forge_uicheck_negmig_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
				string negMigSrc = "";
				bool negMigMigrated = false;
				try
				{
					var negMigProfile = ProfileFactory.Sample();
					negMigProfile.Cards.Clear();
					var negMigCard = new CardSpec { Name = "自检负值力量卡", ClassName = "UiCheckNegStrCardMig", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					negMigCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, UpgradeAmount = 0m, TargetSide = "Self" });
					negMigCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -1m, UpgradeAmount = 0m, TargetSide = "Self" });
					negMigProfile.Cards.Add(negMigCard);
					ProfileFactory.Save(negMigProfile, negMigJson);
					var negMigLoaded = ProfileFactory.Load(negMigJson);
					var negMigCardLoaded = negMigLoaded.Cards.First(c => c.ClassName == "UiCheckNegStrCardMig");
					negMigMigrated = negMigCardLoaded.Effects[0].UsesAmountFormula && negMigCardLoaded.Effects[1].UsesAmountFormula;
					negMigSrc = CSharpCodeGen.CardSource(negMigLoaded, negMigCardLoaded, 0);
				}
				finally
				{
					try { if (File.Exists(negMigJson)) File.Delete(negMigJson); } catch { }
				}
				Check("V0.2.139：（端到端）从文件载入的那种卡（固定数值已迁进「数值公式」栏 → UsesAmountFormula=true）—— 先确认迁移确实发生了",
					negMigMigrated, negMigMigrated ? "迁移发生了" : "**没迁移**（这条断言的前提不成立）");
				Check("V0.2.139：（端到端）迁移过的卡上：力量 -2 → Apply<StrengthPower>(…, -((2m)), …)、"
					+ "虚弱 -1 → GetPower<WeakPower> + ModifyAmount（两档都对，才说明公式那一档没把负数判丢）",
					Regex.IsMatch(negMigSrc, @"PowerCmd\.Apply<StrengthPower>\(choiceContext, base\.Owner\.Creature, -\(\(2m\)\),")
					&& !negMigSrc.Contains("GetPower<StrengthPower>", StringComparison.Ordinal)
					&& negMigSrc.Contains("GetPower<WeakPower>", StringComparison.Ordinal)
					&& negMigSrc.Contains("ModifyAmount", StringComparison.Ordinal)
					&& !Regex.IsMatch(negMigSrc, @"PowerCmd\.Apply<WeakPower>\(choiceContext, base\.Owner\.Creature, -\(\(1m\)\),"), "对");

				// 回读（V0.2.139）：两种负数写法都要认得回来，而且**符号不能读反**
				//（以前那种「一律 ModifyAmount」的回读分支只看第 1 个实参 —— 那是目标表达式，永远判不成负数）。
				string negRecRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_negrec_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					var negRecProfile = ProfileFactory.Sample();
					negRecProfile.Paths.OutputDir = negRecRoot;
					// 路径照界面那份（自检里示例配置的这两栏可能是空的，而生成要读解包工程 / sts2.dll）
					negRecProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					negRecProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					// ⚠ 不清卡池：示例配置本来就有 Common / Uncommon / Rare 各一张（奖励抽 3 张要至少 3 张）
					var negRecCard = new CardSpec { Name = "自检负值回读卡", ClassName = "UiCheckNegRecCard", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					negRecCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, UpgradeAmount = 0m, TargetSide = "Self" });
					negRecCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -1m, UpgradeAmount = 0m, TargetSide = "Self" });
					negRecProfile.Cards.Add(negRecCard);
					var negRecGen = ModGenerator.Generate(negRecProfile);
					if (!negRecGen.Success)
					{
						Check("V0.2.139：（回读）负数「施加状态」的工程能生成", false,
							string.Join(" / ", negRecGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
					}
					else
					{
						var negRec = ProjectRecovery.FromProject(negRecGen.ProjectRoot);
						var negRecBack = negRec.Profile.Cards.FirstOrDefault(c => c.ClassName == "UiCheckNegRecCard");
						Check("V0.2.139：（回读）负数「施加状态」从工程认回来时**符号不反**："
							+ "力量 -2 → -2（本体允许负层数那条 Apply<T> 写法）、虚弱 -1 → -1（ModifyAmount 那条写法）",
							negRecBack is not null
							&& negRecBack.Effects.Count == 2
							&& negRecBack.Effects[0].Kind == "ApplyPower" && negRecBack.Effects[0].PowerId == "StrengthPower" && negRecBack.Effects[0].Amount == -2m
							&& negRecBack.Effects[1].Kind == "ApplyPower" && negRecBack.Effects[1].PowerId == "WeakPower" && negRecBack.Effects[1].Amount == -1m,
							negRecBack is null ? "(没回读到这张卡)"
								: string.Join(" / ", negRecBack.Effects.Select(e => $"{e.PowerId}={e.Amount}")));
						Check("V0.2.139：（回读）这次回读没有「没认出来」的语句",
							!negRec.HasUnparsed, negRec.Unparsed.FirstOrDefault() ?? "0 条");
					}
				}
				finally
				{
					try { if (Directory.Exists(negRecRoot)) Directory.Delete(negRecRoot, true); } catch { }
				}

				var negWeakProfile = ProfileFactory.Sample();
				var negWeak = new CardSpec
				{
					Name = "自检负值虚弱卡", ClassName = "UiCheckNegWeakCard", CardType = "Skill", Rarity = "Common",
					Cost = 1, InCardPool = true,
				};
				negWeak.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -1m, UpgradeAmount = 0m, TargetSide = "Self" });
				negWeakProfile.Cards.Add(negWeak);
				string negWeakSrc = CSharpCodeGen.CardSource(negWeakProfile, negWeak, 0);
				var negWeakPow = new CustomPowerSpec { Name = "自检负值虚弱状态", ClassName = "UiCheckNegPowerWeak", Type = "Buff" };
				negWeakPow.Triggers.Add(new PowerTriggerSpec
				{
					Kind = "PlayerTurnStart",
					Effects = { new EffectSpec { Kind = "ApplyPower", PowerId = "WeakPower", Amount = -1m, TargetSide = "Self" } },
				});
				negPowProfile.CustomPowers.Clear();
				negPowProfile.CustomPowers.Add(negWeakPow);
				string negWeakPowSrc = CustomPowerGen.Source(negPowProfile, negWeakPow, 0);

				Check("V0.2.139：虚弱 -1（本体**不**允许负层数）→ 仍然是 `GetPower<WeakPower>` + `ModifyAmount` 扣已有层数"
					+ "（层数不能凭空变成负的），**绝不出现** Apply<WeakPower>(…, 负数)",
					negWeakSrc.Contains("GetPower<WeakPower>", StringComparison.Ordinal)
					&& negWeakSrc.Contains("ModifyAmount", StringComparison.Ordinal)
					&& !Regex.IsMatch(negWeakSrc, @"PowerCmd\.Apply<WeakPower>\(choiceContext, [^,]+, -")
					&& negWeakPowSrc.Contains("GetPower<WeakPower>", StringComparison.Ordinal)
					&& negWeakPowSrc.Contains("ModifyAmount", StringComparison.Ordinal)
					&& !negWeakPowSrc.Contains("PowerCmd.Apply<WeakPower>(choiceContext, base.Owner, -1m,", StringComparison.Ordinal), "对");

				// 旧写法**逐字不变**：遗物 / 药水链上「力量 -2」以前生成的那一行（ModifyAmount + __negPower）
				// 不许再出现在力量这类状态上；而**不允许负层数**的那一档文案一个字都没动，回读也照旧。
				Check("V0.2.139：力量 -2 上不再出现 `__negPower` + `ModifyAmount`（那是「只扣已有层数」的旧写法，"
					+ "目标身上本来没有力量时什么都不做 —— 正是用户报的「填负值的力量不生效」）",
					!negCardSrc.Contains("__negPower", StringComparison.Ordinal)
					&& !negRelicSrc.Contains("__negPower", StringComparison.Ordinal)
					&& !negPotionSrc.Contains("__negPower", StringComparison.Ordinal)
					&& !negPowSrc.Contains("__negPower", StringComparison.Ordinal), "对");
			}

			// ===== V0.2.141：回读不能把「数值公式 + 升级增量」的增量**算重一倍** =====
			//
			// 用户实测报的 BUG：「在生成器填负值的力量不生效」。真因（主代理已 100% 复现）：
			// 生成端对「数值公式 + 升级增量」的 5 种效果把**同一个增量写三遍** ——
			//   ① 变量构造第二个参数 `new ForgeFormulaPowerVar<StrengthPower>(static (card, target) => (1m), 1m)`
			//   ② 打出时那个三元式 `(base.IsUpgraded ? 2m : 1m)`
			//   ③ `OnUpgrade` 里的 `base.DynamicVars["StrengthPower"].UpgradeValueBy(1m)`
			// 回读时 ①② 已经由 FillExpr 算出增量（1），③ 是**同一个数** —— 以前无条件 `+=`，
			// 于是「力量 +1 / 升级增量 1」回读成 UpgradeAmount=2，再生成出来就是 `? 3m : 1m`；
			// 用户把公式改成 -2 之后，升级过的那张打出去是 `-2 + 2 = 0` 层 = 完全没效果。
			{
				CharacterProfile upg141 = ProfileFactory.Sample();

				// ① 最小产物（照抄用户那张真卡的 L9 / L29 / L35 三行形态）：公式 "1" + 升级增量 1。
				//    ⚠ 必须同时给 AmountFormula：生成端只有「写了数值公式」那条路才会把升级增量并进打出时的表达式
				//    （见 CSharpCodeGen.EmitCardEffectOnce：`if (formula is not null && e.UpgradeAmount != 0m)`）——
				//    只给固定数值时生成的是 `base.DynamicVars["X"].BaseValue`，那形态跟本 BUG 无关。
				//    用户那张真卡的 AmountFormula 也是 "1"（打开存档时 MigrateAmountsToFormulas 迁出来的）。
				CardSpec ternaryCard = new CardSpec { Name = "自检三元式增量", ClassName = "UiCheckUpgTernary", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				ternaryCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = 1m, AmountFormula = "1", UpgradeAmount = 1m, TargetSide = "Self" });
				upg141.Cards.Add(ternaryCard);
				string ternarySrc = CSharpCodeGen.CardSource(upg141, ternaryCard, 0);
				Check("V0.2.141：（准备）生成端确实是**三处**写法（变量构造第二参 `, 1m)` + 打出时三元式 + OnUpgrade 的 UpgradeValueBy）"
					+ "—— 回读就是在这三处上把增量算了两遍",
					ternarySrc.Contains("? 2m : 1m", StringComparison.Ordinal)
					&& ternarySrc.Contains("UpgradeValueBy(1m)", StringComparison.Ordinal), "对");
				string t141Root = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02141_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					upg141.Paths.OutputDir = t141Root;
					upg141.Paths.VanillaProject = Profile.Paths.VanillaProject;
					upg141.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var t141Gen = ModGenerator.Generate(upg141);
					Check("V0.2.141：（准备）「数值公式 + 升级增量」的存档能生成工程", t141Gen.Success,
						t141Gen.Success ? t141Gen.ProjectRoot : string.Join(" ｜ ", t141Gen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (t141Gen.Success)
					{
						var t141Rec = ProjectRecovery.FromProject(t141Gen.ProjectRoot);
						CardSpec? t141Back = t141Rec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckUpgTernary");
						// ★ 修好之前这里读出来是 2（1 由三元式 + 1 由 UpgradeValueBy）→ 这条**必须**能 FAIL 在修之前
						Check("V0.2.141：回读不重复累加 —— 三元式给的增量与 UpgradeValueBy 相等时**跳过**（UpgradeAmount == 1，不是 2）",
							t141Back is not null && t141Back.Effects.Count == 1 && t141Back.Effects[0].UpgradeAmount == 1m,
							t141Back is null ? "(没回读到这张卡)"
								: $"UpgradeAmount={t141Back.Effects[0].UpgradeAmount}（期望 1）");
						Check("V0.2.141：（回读）这次回读没有「没认出来」的语句", !t141Rec.HasUnparsed, t141Rec.Unparsed.FirstOrDefault() ?? "0 条");

						// 拿回读结果**再生成**：必须回到 `? 2m : 1m`，而且**不许出现 3m**（那正是 BUG 的产物）
						t141Rec.Profile.Paths.OutputDir = Path.Combine(t141Root, "again");
						t141Rec.Profile.Paths.VanillaProject = Profile.Paths.VanillaProject;
						t141Rec.Profile.Paths.GameDataDir = Profile.Paths.GameDataDir;
						var t141Gen2 = ModGenerator.Generate(t141Rec.Profile);
						string t141Again = t141Gen2.Success
							? File.ReadAllText(Path.Combine(t141Gen2.ProjectRoot, "cs", "Cards", "UiCheckUpgTernary.cs"))
							: "";
						Check("V0.2.141：拿回读结果再生成 → 还是 `? 2m : 1m`，而且**不出现** `3m`（增量没有被算重一倍）",
							t141Gen2.Success
							&& t141Again.Contains("? 2m : 1m", StringComparison.Ordinal)
							&& !t141Again.Contains("3m", StringComparison.Ordinal),
							t141Gen2.Success ? (t141Again.Contains("3m", StringComparison.Ordinal) ? "出现了 3m（增量算重了）" : "对") : "(第二次生成失败)");
					}
				}
				finally
				{
					try { if (Directory.Exists(t141Root)) Directory.Delete(t141Root, true); } catch { }
				}

				// ② 老写法（非公式那条路）不许被改坏：没有三元式，只有 UpgradeAmount → 照旧累加
				CardSpec upgAlone = new CardSpec { Name = "自检只有增量", ClassName = "UiCheckUpgOnly", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				upgAlone.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, UpgradeAmount = 3m, TargetSide = "Enemy" });
				string aloneSrc = CSharpCodeGen.CardSource(upg141, upgAlone, 0);
				Check("V0.2.141：（准备）老写法（只有「升级增量」、没有数值公式）生成的是 `new DamageVar(6m, …)` + `UpgradeValueBy(3m)`，没有三元式",
					aloneSrc.Contains("new DamageVar(6m", StringComparison.Ordinal) && aloneSrc.Contains("UpgradeValueBy(3m)", StringComparison.Ordinal)
					&& !aloneSrc.Contains("IsUpgraded", StringComparison.Ordinal), "对");
				string aloneRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02141a_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					var aloneProfile = ProfileFactory.Sample();
					aloneProfile.Cards.Add(upgAlone);
					aloneProfile.Paths.OutputDir = aloneRoot;
					aloneProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					aloneProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var aloneGen = ModGenerator.Generate(aloneProfile);
					Check("V0.2.141：（准备）老写法的存档能生成工程", aloneGen.Success,
						aloneGen.Success ? aloneGen.ProjectRoot : string.Join(" ｜ ", aloneGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (aloneGen.Success)
					{
						var aloneRec = ProjectRecovery.FromProject(aloneGen.ProjectRoot);
						CardSpec? aloneBack = aloneRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckUpgOnly");
						Check("V0.2.141：老写法（非公式）**没被改坏** —— `new DamageVar(6)` + `UpgradeValueBy(3m)` 回读 UpgradeAmount == 3",
							aloneBack is not null && aloneBack.Effects.Count == 1 && aloneBack.Effects[0].UpgradeAmount == 3m,
							aloneBack is null ? "(没回读到这张卡)" : $"UpgradeAmount={aloneBack.Effects[0].UpgradeAmount}（期望 3）");
					}
				}
				finally
				{
					try { if (Directory.Exists(aloneRoot)) Directory.Delete(aloneRoot, true); } catch { }
				}

				// ③ 真·现算公式（走不到 FillExpr 的三元式分支）：靠 UpgradeValueBy 得到 3，而且公式原文必须原样回来
				CardSpec realFx = new CardSpec { Name = "自检现算公式增量", ClassName = "UiCheckUpgReal141", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				realFx.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 0m, AmountFormula = "M*2", UpgradeAmount = 3m, TargetSide = "Enemy" });
				var realFxProfile = ProfileFactory.Sample();
				realFxProfile.CustomParams.Add(new ParamSpec { Name = "M", Source = ParamSources.Power, Target = ParamTargets.Self, PowerId = "VulnerablePower" });
				string realFxSrc = CSharpCodeGen.CardSource(realFxProfile, realFx, 0);
				Check("V0.2.141：（准备）真·现算公式（M*2）+ 升级增量 3 生成的是「升级后 / 升级前各写一次公式」，**不是**三常数三元式",
					realFxSrc.Contains("base.IsUpgraded ?", StringComparison.Ordinal)
					&& realFxSrc.Contains("* (2m)", StringComparison.Ordinal)
					&& realFxSrc.Contains("+ 3m)", StringComparison.Ordinal)
					&& !Regex.IsMatch(realFxSrc, @"base\.IsUpgraded \? [\d.]+m : [\d.]+m"), "对");
				string realRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02141r_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					realFxProfile.Cards.Add(realFx);
					realFxProfile.Paths.OutputDir = realRoot;
					realFxProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					realFxProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var realGen = ModGenerator.Generate(realFxProfile);
					Check("V0.2.141：（准备）真·现算公式 + 升级增量的存档能生成工程", realGen.Success,
						realGen.Success ? realGen.ProjectRoot : string.Join(" ｜ ", realGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (realGen.Success)
					{
						var realRec = ProjectRecovery.FromProject(realGen.ProjectRoot);
						CardSpec? realBack = realRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckUpgReal141");
						Check("V0.2.141：真·现算公式没被改坏 —— 回读 UpgradeAmount == 3（不是 6）",
							realBack is not null && realBack.Effects.Count == 1 && realBack.Effects[0].UpgradeAmount == 3m,
							realBack is null ? "(没回读到这张卡)" : $"UpgradeAmount={realBack.Effects[0].UpgradeAmount}（期望 3）");
						Check("V0.2.141：真·现算公式的**原文**原样回来（`M*2`，不是变回一个常数）",
							realBack is not null && realBack.Effects.Count == 1
							&& EffectSpec.FormulaText(realBack.Effects[0].AmountFormula) == "M*2",
							realBack is null ? "(没回读到这张卡)" : $"公式=「{realBack.Effects[0].AmountFormula}」（期望 M*2）");
					}
				}
				finally
				{
					try { if (Directory.Exists(realRoot)) Directory.Delete(realRoot, true); } catch { }
				}

				// ④ 「升级增量把数值抵成 0」→ **警告**（不是错误）；增量为 0 时**不报**。
				//    这条正是用户看不到任何提示、才以为「负值不生效」的那个坑。
				var negUpgProfile = ProfileFactory.Sample();
				CardSpec negUpgCard = new CardSpec { Name = "自检升级抵成零", ClassName = "UiCheckUpgZero141", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				negUpgCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, AmountFormula = "-2", UpgradeAmount = 2m, TargetSide = "Self" });
				negUpgProfile.Cards.Add(negUpgCard);
				var negUpgIssues = ProfileValidator.Validate(negUpgProfile);
				string negUpgWarnText = string.Join(" ｜ ", negUpgIssues.Where((ValidationIssue i) => i.Message.Contains("抵成了")).Select((ValidationIssue i) => i.Level + ": " + i.Message));
				Check("V0.2.141：公式 -2 + 升级增量 2 → 有那条「升级后打出去不会有任何效果」的警告，而且**严重度是警告**（不是错误 —— 绝不能拦住老存档生成）",
					negUpgIssues.Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("升级增量") && i.Message.Contains("抵成了") && i.Message.Contains("不会有任何效果")),
					negUpgWarnText.Length > 0 ? negUpgWarnText : "(没报)");
				Check("V0.2.141：（数一数）负数不会被写成「-2抵成了」这种粘在一起的话（公式和固定数值两条路都要留空格）",
					negUpgWarnText.Contains("把数值公式里的 -2 抵成了", StringComparison.Ordinal),
					negUpgWarnText.Length > 0 ? negUpgWarnText.Substring(0, Math.Min(70, negUpgWarnText.Length)) : "(没报)");
				Check("V0.2.141：「升级后为 0」那条**不得**新增任何「错误」",
					!negUpgIssues.Any((ValidationIssue i) => i.IsError && i.Message.Contains("抵成了")),
					string.Join(" ｜ ", negUpgIssues.Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message).Take(2)));
				var negStrProfile = ProfileFactory.Sample();
				CardSpec negStrCard = new CardSpec { Name = "自检升级零对照", ClassName = "UiCheckUpgZeroNo141", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				negStrCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, AmountFormula = "-2", UpgradeAmount = 0m, TargetSide = "Self" });
				negStrProfile.Cards.Add(negStrCard);
				Check("V0.2.141：（对照）同样填 -2 但升级增量是 0 → **没有**那条警告（升级前后都是 -2，一切正常）",
					!ProfileValidator.Validate(negStrProfile).Any((ValidationIssue i) => i.Message.Contains("抵成了")), "没报");

				// ④-b 非卡牌链（老存档里遗物效果残留升级增量）：那些没有「数值公式」，用固定 Amount —— 同一个判据的另一支
				var fixedAmtProfile = ProfileFactory.Sample();
				fixedAmtProfile.Relics.Clear();
				var fixedAmtRelic = new RelicSpec { Name = "自检抵零遗物", ClassName = "UiCheckUpgZeroRelic141", Rarity = "Common", Trigger = "PlayerTurnStart" };
				fixedAmtRelic.Effects.Add(new EffectSpec { Kind = "Damage", Amount = -2m, UpgradeAmount = 2m, TargetSide = "Enemy" });
				fixedAmtProfile.Relics.Add(fixedAmtRelic);
				string fixedAmtWarnText2 = string.Join(" ｜ ", ProfileValidator.Validate(fixedAmtProfile)
					.Where((ValidationIssue i) => i.Message.Contains("抵成了")).Select((ValidationIssue i) => i.Level + ": " + i.Message));
				Check("V0.2.141：非卡牌链（遗物里残留「数值 -2 + 升级增量 2」）也走同一个判据 —— 同样是**警告**，不是错误",
					fixedAmtWarnText2.Contains("警告") && ProfileValidator.Validate(fixedAmtProfile).All((ValidationIssue i) => !(i.IsError && i.Message.Contains("抵成了")))
					&& fixedAmtWarnText2.Contains("把数值 -2 抵成了", StringComparison.Ordinal),
					fixedAmtWarnText2.Length > 0 ? fixedAmtWarnText2 : "(没报)");

				// ⑤ 效果列表摘要行要把「升级后最终值」写出来（用户不用点开逐条看也能发现「升级后 = 0」）
				EffectSpec negSummary = new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -2m, AmountFormula = "-2", UpgradeAmount = 2m, TargetSide = "Self" };
				Check("V0.2.141：效果列表摘要行里能看见「（升级后 0）」—— 一眼就能看出升级后这条没效果",
					negSummary.Display.Contains("（升级后 0）", StringComparison.Ordinal), negSummary.Display);
				EffectSpec posSummary = new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = 1m, AmountFormula = "1", UpgradeAmount = 1m, TargetSide = "Self" };
				Check("V0.2.141：常数公式 + 增量不为零时摘要行写升级后的最终值（公式 1 + 增量 1 → 「（升级后 2）」）",
					posSummary.Display.Contains("（升级后 2）", StringComparison.Ordinal), posSummary.Display);
				EffectSpec fxSummary = new EffectSpec { Kind = "Damage", Amount = 0m, AmountFormula = "M*2", UpgradeAmount = 3m, TargetSide = "Enemy" };
				Check("V0.2.141：（对照）真·现算公式**不写**「升级后 X」（折不出常数，写个假数字不如不写），照旧只显示公式本身",
					!fxSummary.Display.Contains("升级后", StringComparison.Ordinal) && fxSummary.Display.Contains("M*2", StringComparison.Ordinal), fxSummary.Display);
			}

			// ⑤ 本轮新增：「自己失去生命时」= 本体 AfterCurrentHpChanged 里 delta < 0 的那一半。
			//    它比「受到伤害后」更宽（那条只认伤害管线），而且这个钩子本体不给 choiceContext。
			Check("自定义状态的触发时机里有「自己失去生命时」，走本体的 AfterCurrentHpChanged",
				PowerTriggers.All.Any((PowerTriggerOption t) => t.Kind == "HpLost" && t.Display.Contains("失去生命")), "在");
			CharacterProfile hpLostProbe = ProfileFactory.Sample();
			hpLostProbe.CustomPowers.Clear();
			hpLostProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检掉血状态", ClassName = "UiCheckHpLost", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "HpLost", Effects = { new EffectSpec { Kind = "Block", Amount = 3m } } } },
			});
			hpLostProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检掉血打人状态", ClassName = "UiCheckHpLostDamage", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "HpLost", Effects = { new EffectSpec { Kind = "Damage", Amount = 2m, TargetSide = "Enemy" } } } },
			});
			string hpLostSrc = CustomPowerGen.Source(hpLostProbe, hpLostProbe.CustomPowers[0], 0);
			string hpLostDmgSrc = CustomPowerGen.Source(hpLostProbe, hpLostProbe.CustomPowers[1], 0);
			Check("生成：AfterCurrentHpChanged + 只认自己 + **只认掉血**（delta >= 0 是回血，直接 return）",
				hpLostSrc.Contains("public override async Task AfterCurrentHpChanged(Creature creature, decimal delta)")
				&& hpLostSrc.Contains("if (creature != base.Owner) return;")
				&& hpLostSrc.Contains("if (delta >= 0m) return;"), "对");
			Check("这个钩子本体不给 choiceContext：效果要用它时按本体做法自己造一个（不然造成伤害会 CS0103）",
				hpLostDmgSrc.Contains("var choiceContext = new MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext(this, __netId, base.CombatState, MegaCrit.Sts2.Core.Entities.Multiplayer.GameActionType.Combat);")
				&& hpLostDmgSrc.Contains("Creature? other = base.Owner.CombatState.HittableEnemies.FirstOrDefault();"), "造了");
			Check("校验器把「失去生命时」和「受到伤害后」的差别写清楚（前者是后者的超集）",
				ProfileValidator.Validate(hpLostProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("生命值真的少了")), "写了");

			// ⑪ 本轮新增：刮削（本体卡「刮削 Scrape」）——抽 N 张，丢弃其中所有非 0 费牌
			Check("（配置）有「刮削」这个效果种类，数值 0~10（0 = 不生效，守「都能填 0」那条规矩）",
				EffectCatalog.FindKind("ScrapeDraw") is not null
				&& EffectCatalog.FindKind("ScrapeDraw").Min == 0 && EffectCatalog.FindKind("ScrapeDraw").Max == 10
				&& EffectCatalog.FindKind("ScrapeDraw").Display.Contains("刮削"),
				EffectCatalog.FindKind("ScrapeDraw")?.Display ?? "(没有)");
			CharacterProfile scrapeProbe = ProfileFactory.Sample();
			scrapeProbe.VanillaPowerOverrides.Clear();
			CardSpec scrapeCard = new CardSpec { Name = "刮削探针", ClassName = "UiCheckScrape", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeCard.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 4m, TargetSide = "Self" });
			scrapeProbe.Cards.Add(scrapeCard);
			string scrapeSrc = CSharpCodeGen.CardSource(scrapeProbe, scrapeCard, 0);
			Check("生成：声明 CardsVar（卡面 {Cards:diff()} 与升级增量都跟着走）",
				scrapeSrc.Contains("new CardsVar(4)"), "变量在");
			Check("生成：抽 N 张 → 按本体的判据筛掉 0 费牌 → CardCmd.Discard（和本体 Scrape 写法一致）",
				scrapeSrc.Contains("CET:Effect=ScrapeDraw")
				&& scrapeSrc.Contains("IEnumerable<CardModel> __scraped = (await CardPileCmd.Draw(choiceContext, base.DynamicVars.Cards.BaseValue, base.Owner)).Where(c => c.EnergyCost.GetWithModifiers(CostModifiers.All) != 0 || c.EnergyCost.CostsX);")
				&& scrapeSrc.Contains("await CardCmd.Discard(choiceContext, __scraped);"), "对");
			string scrapeJson = LocalizationGen.CardsJson(scrapeProbe);
			Check("卡面描述写清「丢弃其中所有非 0 费牌」",
				scrapeJson.Contains("抽 {Cards:diff()} 张牌，丢弃其中所有非 0 费牌。"), "描述对");
			RelicSpec scrapeRelic = new RelicSpec
			{
				Name = "刮削遗物", ClassName = "UiCheckScrapeRelic", Rarity = "Common", Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self" } },
			};
			scrapeProbe.Relics.Add(scrapeRelic);
			string scrapeRelicSrc = CSharpCodeGen.RelicSource(scrapeProbe, scrapeRelic, 0);
			Check("遗物上也能用（同一段实现；触发时机不给 choiceContext 时是警告而不是坏代码）",
				scrapeRelicSrc.Contains("__scraped"), "遗物上也在");

			// ⑫ 刮削的「条件 + 操作」（用户要求：抽 N 张 → 对其中**符合条件**的牌执行**选定的操作**）。
			// 老存档没有这两个字段，默认必须是「非 0 费 + 丢弃」，生成的文本一个字都不能变 —— 先整块钉死。
			string scrapeNl = scrapeSrc.Replace("\r\n", "\n");
			Check("默认（非 0 费 + 丢弃）生成出来的一整段与旧版**逐字一致**（标记行 / 注释 / 抽牌 / 丢牌四行都没动）",
				scrapeNl.Contains("// CET:Effect=ScrapeDraw CET:Amount=4m CET:Pick=Random CET:Pile=Hand CET:Stack=0 CET:X=0 CET:Copies=1 CET:Power=\"\" CET:Side=Self\n")
				&& scrapeNl.Contains("            // 抽 base.DynamicVars.Cards.BaseValue 张牌，丢弃其中所有「非 0 费」的牌（本体「刮削 Scrape」的写法）\n"
					+ "            IEnumerable<CardModel> __scraped = (await CardPileCmd.Draw(choiceContext, base.DynamicVars.Cards.BaseValue, base.Owner)).Where(c => c.EnergyCost.GetWithModifiers(CostModifiers.All) != 0 || c.EnergyCost.CostsX);\n"
					+ "            await CardCmd.Discard(choiceContext, __scraped);")
				&& !scrapeNl.Contains("CET:ScrapeCond") && !scrapeNl.Contains("CET:ScrapeOp"),
				"逐字一致");
			Check("（配置）条件候选 = 非 0 费 / 不限 + 范围限定那一整份（含自定义关键词分组）；操作候选 = 丢弃 / 消耗 / 升级",
				EffectCatalog.ScrapeCondsFor(scrapeProbe).Select((SpawnFilterOption f) => f.Id)
					.SequenceEqual(new[] { "NonZeroCost", "Any", "Attack", "Skill", "Power", "Curse", "Status", "Quest" })
				&& EffectCatalog.ScrapeCondsFor(scrapeProbe)[1].Zh == "不限"
				&& EffectCatalog.ScrapeOps.Select((SpawnFilterOption f) => f.Id).SequenceEqual(new[] { "Discard", "Exhaust", "Upgrade" })
				&& EffectCatalog.ScrapeOpZh("Exhaust") == "消耗掉",
				string.Join("/", EffectCatalog.ScrapeCondsFor(scrapeProbe).Select((SpawnFilterOption f) => f.Id)));
			// 条件 = 攻击 + 操作 = 消耗
			CardSpec scrapeAtk = new CardSpec { Name = "刮削攻击消耗", ClassName = "UiCheckScrapeExhaust", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeAtk.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self", ScrapeCond = "Attack", ScrapeOp = "Exhaust" });
			scrapeProbe.Cards.Add(scrapeAtk);
			string scrapeAtkSrc = CSharpCodeGen.CardSource(scrapeProbe, scrapeAtk, 0);
			Check("条件 = 攻击 + 操作 = 消耗 → 判据是 CardType.Attack、动作是 CardCmd.Exhaust（和「消耗卡牌」同一个命令）",
				scrapeAtkSrc.Contains("IEnumerable<CardModel> __scraped = (await CardPileCmd.Draw(choiceContext, base.DynamicVars.Cards.BaseValue, base.Owner)).Where(c => c.Type == CardType.Attack);")
				&& scrapeAtkSrc.Contains("foreach (CardModel c in __scraped) await CardCmd.Exhaust(choiceContext, c);")
				&& scrapeAtkSrc.Contains("CET:ScrapeCond=Attack CET:ScrapeOp=Exhaust"), "对");
			Check("卡面描述写出了条件与操作（「把其中「攻击」的牌消耗掉」）",
				LocalizationGen.CardsJson(scrapeProbe).Contains("抽 {Cards:diff()} 张牌，把其中「攻击」的牌消耗掉。"), "描述对");
			// 条件 = 不限 + 操作 = 升级
			CardSpec scrapeAny = new CardSpec { Name = "刮削不限升级", ClassName = "UiCheckScrapeUpgrade", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeAny.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self", ScrapeCond = "Any", ScrapeOp = "Upgrade" });
			scrapeProbe.Cards.Add(scrapeAny);
			string scrapeAnySrc = CSharpCodeGen.CardSource(scrapeProbe, scrapeAny, 0);
			string scrapeAnyDraw = scrapeAnySrc.Split('\n').First((string l) => l.Contains("__scraped = ")).Trim();
			Check("条件 = 不限 + 操作 = 升级 → 完全不筛（那一句里没有 .Where(）、动作是 CardCmd.Upgrade",
				scrapeAnyDraw == "IEnumerable<CardModel> __scraped = await CardPileCmd.Draw(choiceContext, base.DynamicVars.Cards.BaseValue, base.Owner);"
				&& !scrapeAnyDraw.Contains(".Where(")
				&& scrapeAnySrc.Contains("foreach (CardModel c in __scraped) CardCmd.Upgrade(c);")
				&& scrapeAnySrc.Contains("CET:ScrapeCond=Any CET:ScrapeOp=Upgrade"), "对");
			Check("卡面描述写的是「每一张牌升级」（不限时不说「符合条件的」）",
				LocalizationGen.CardsJson(scrapeProbe).Contains("抽 {Cards:diff()} 张牌，把其中每一张牌升级。"), "描述对");
			// 条件 = 自定义关键词那一组（把关键词当「卡的组」用，生成期查成显式条件）
			CharacterProfile scrapeKw = ProfileFactory.Sample();
			scrapeKw.VanillaPowerOverrides.Clear();
			scrapeKw.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运" });
			CardSpec scrapeKwA = new CardSpec { Name = "刮削命运一", ClassName = "UiCheckScrapeFateA", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeKwA.KeywordIds.Add("FATE");
			CardSpec scrapeKwB = new CardSpec { Name = "刮削命运二", ClassName = "UiCheckScrapeFateB", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeKwB.KeywordIds.Add("FATE");
			CardSpec scrapeKwCard = new CardSpec { Name = "刮削按组", ClassName = "UiCheckScrapeKw", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeKwCard.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self", ScrapeCond = "Keyword:FATE", ScrapeOp = "Discard" });
			scrapeKw.Cards.Add(scrapeKwA);
			scrapeKw.Cards.Add(scrapeKwB);
			scrapeKw.Cards.Add(scrapeKwCard);
			string scrapeKwSrc = CSharpCodeGen.CardSource(scrapeKw, scrapeKwCard, 0);
			Check("条件 = 自定义关键词那一组 → 生成期查成显式条件（c.Id == ModelDb.Card<X>().Id，复用范围界定那份查表）",
				scrapeKwSrc.Contains(".Where(c => c.Id == ModelDb.Card<UiCheckScrapeFateA>().Id || c.Id == ModelDb.Card<UiCheckScrapeFateB>().Id);")
				&& scrapeKwSrc.Contains("CET:ScrapeCond=Keyword:FATE CET:ScrapeOp=Discard"), "显式牌表");
			Check("卡面描述写的是这一组的名字（「命运」）",
				LocalizationGen.CardsJson(scrapeKw).Contains("把其中「命运」的牌丢弃。"), "描述对");
			// 空组：选了关键词分组、但一张牌都没带这个关键词 → 报错（和「范围限定 / 范围界定」同一条规矩）
			CharacterProfile scrapeKwEmpty = ProfileFactory.Sample();
			scrapeKwEmpty.CustomKeywords.Clear();
			scrapeKwEmpty.CustomKeywords.Add(new CustomKeywordSpec { Key = "VOID", Name = "虚空" });
			CardSpec scrapeKwEmptyCard = new CardSpec { Name = "刮削空组", ClassName = "UiCheckScrapeKwEmpty", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeKwEmptyCard.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self", ScrapeCond = "Keyword:VOID", ScrapeOp = "Discard" });
			scrapeKwEmpty.Cards.Add(scrapeKwEmptyCard);
			Check("条件选了自定义关键词、但那一组一张牌都没有 → 校验器**报错**",
				ProfileValidator.Validate(scrapeKwEmpty).Any((ValidationIssue i) => i.IsError && i.Message.Contains("这一组是空的")), "报错了");
			Check("条件 / 操作 Id 认不出来 → 校验器报错（不静默退化成「一张都不动手」）",
				ProfileValidator.Validate(new CharacterProfile
				{
					Cards = { new CardSpec { Name = "刮削坏 Id", ClassName = "UiCheckScrapeBad", CardType = "Attack", Rarity = "Common", Cost = 1,
						Effects = { new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self", ScrapeCond = "Bogus", ScrapeOp = "Bogus" } } } },
				}).Count((ValidationIssue x) => x.IsError && x.Message.Contains("认不出来")) == 2, "条件和操作各报一条");
			Check("校验器给了一句「抽 N 张 → 对其中 X 的牌执行 Y」的提示",
				ProfileValidator.Validate(scrapeProbe).Any((ValidationIssue i) => i.Message.Contains("会抽 3 张牌，然后对其中「攻击」的牌消耗掉")), "提示在");
			// 生成 → 回读：两个字段要原样回来（默认那一档回来还是默认值），而且没有「没认出来」
			string scrapeRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_scrape_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile scrapeGen = ProfileFactory.Sample();
				scrapeGen.VanillaPowerOverrides.Clear();
				scrapeGen.CustomKeywords.Clear();
				scrapeGen.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运" });
				scrapeGen.Paths.OutputDir = scrapeRoot;
				scrapeGen.Paths.VanillaProject = Profile.Paths.VanillaProject;
				scrapeGen.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec scrapeGenFate = new CardSpec { Name = "自检刮削命运牌", ClassName = "UiCheckScrapeRoundFate", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				scrapeGenFate.KeywordIds.Add("FATE");
				CardSpec scrapeRound = new CardSpec { Name = "自检刮削往返", ClassName = "UiCheckScrapeRound", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				// 四条摆在一起：默认那一档 + 三种非默认（同一张牌上还有 Cards2 / Cards3 / Cards4 的别名要一起对上）
				scrapeRound.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 4m, TargetSide = "Self" });
				scrapeRound.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 3m, TargetSide = "Self", ScrapeCond = "Attack", ScrapeOp = "Exhaust" });
				scrapeRound.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 2m, TargetSide = "Self", ScrapeCond = "Any", ScrapeOp = "Upgrade" });
				scrapeRound.Effects.Add(new EffectSpec { Kind = "ScrapeDraw", Amount = 1m, TargetSide = "Self", ScrapeCond = "Keyword:FATE", ScrapeOp = "Discard" });
				scrapeGen.Cards.Add(scrapeGenFate);
				scrapeGen.Cards.Add(scrapeRound);
				Check("（准备）带刮削条件 / 操作的存档能生成工程", ModGenerator.Generate(scrapeGen).Success, scrapeRoot);
				var scrapeRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(scrapeGen));
				var scrapeRecCard = scrapeRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckScrapeRound");
				List<EffectSpec> scrapeRecFx = scrapeRecCard is null ? new List<EffectSpec>() : scrapeRecCard.Effects.ToList();
				Check("回读：刮削的条件 / 操作原样回来（默认那一档回来仍是默认值，没有多写标记项）",
					scrapeRecFx.Count == 4
					&& scrapeRecFx[0].Kind == "ScrapeDraw" && scrapeRecFx[0].ScrapeCond == "NonZeroCost" && scrapeRecFx[0].ScrapeOp == "Discard"
					&& scrapeRecFx[1].ScrapeCond == "Attack" && scrapeRecFx[1].ScrapeOp == "Exhaust"
					&& scrapeRecFx[2].ScrapeCond == "Any" && scrapeRecFx[2].ScrapeOp == "Upgrade"
					&& scrapeRecFx[3].ScrapeCond == "Keyword:FATE" && scrapeRecFx[3].ScrapeOp == "Discard",
					string.Join(" · ", scrapeRecFx.Select((EffectSpec x) => x.ScrapeCond + "/" + x.ScrapeOp)));
				Check("回读：生成代码一条都没漏（没认出来的语句为 0）", !scrapeRec.HasUnparsed, scrapeRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(scrapeRoot)) Directory.Delete(scrapeRoot, true); } catch { }
			}

			// ⑪ 本轮新增：用「目标卡」填满手牌（本体卡「迫降 CrashLanding」的机制）
			Check("（配置）有「用目标卡填满手牌」这个效果种类（数值 0~0：张数由手牌上限决定）",
				EffectCatalog.FindKind("FillHand") is not null
				&& EffectCatalog.FindKind("FillHand").Min == 0 && EffectCatalog.FindKind("FillHand").Max == 0
				&& EffectCatalog.FindKind("FillHand").Display.Contains("填满手牌"),
				EffectCatalog.FindKind("FillHand")?.Display ?? "(没有)");
			CharacterProfile fillProbe = ProfileFactory.Sample();
			fillProbe.VanillaPowerOverrides.Clear();
			CardSpec fillCard = new CardSpec { Name = "填手探针", ClassName = "UiCheckFillHand", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			fillCard.Effects.Add(new EffectSpec { Kind = "FillHand", SpawnCardId = "Shiv", TargetSide = "Self" });
			fillProbe.Cards.Add(fillCard);
			string fillSrc = CSharpCodeGen.CardSource(fillProbe, fillCard, 0);
			Check("生成：算「手牌上限 - 当前手牌数」→ 逐张 CreateCard → 一次性加进手牌（本体「迫降」的写法）",
				fillSrc.Contains("CET:Effect=FillHand") && fillSrc.Contains("CET:Card=Shiv")
				&& fillSrc.Contains("int __fillTo = CardPile.MaxCardsInHand - CardPile.GetCards(base.Owner, PileType.Hand).Count();")
				&& fillSrc.Contains("__filled.Add(base.CombatState.CreateCard<Shiv>(base.Owner));")
				&& fillSrc.Contains("await CardPileCmd.AddGeneratedCardsToCombat(__filled, PileType.Hand, base.Owner);"), "对");
			Check("它不声明动态变量（数值永远是 0，声明了反而会多出用不上的占位符 / 撞名）",
				!fillSrc.Contains("new DynamicVar(") && !fillSrc.Contains("new CardsVar("), "没声明");
			string fillJson = LocalizationGen.CardsJson(fillProbe);
			Check("卡面描述写清「用哪张卡填满手牌」",
				fillJson.Contains("填满你的[gold]手牌[/gold]") && fillJson.Contains("Shiv"), "描述对");
			Check("校验器说明「张数 = 手牌上限 - 当前手牌数」，没选目标卡时给警告（并退成小刀）",
				ProfileValidator.Validate(fillProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("手牌上限")), "提示在");
			CardSpec fillBare = new CardSpec { Name = "填手没选卡", ClassName = "UiCheckFillHandBare", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			fillBare.Effects.Add(new EffectSpec { Kind = "FillHand", TargetSide = "Self" });
			fillProbe.Cards.Add(fillBare);
			Check("没选目标卡时：校验器给警告，生成的代码退成小刀（Shiv）",
				ProfileValidator.Validate(fillProbe).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("小刀"))
				&& CSharpCodeGen.CardSource(fillProbe, fillBare, 0).Contains("CreateCard<Shiv>(base.Owner)"), "退成小刀");

			// ⑪ 本轮新增：抽到就减费（N 回合内每次抽到的牌费用 -1，自己生成的 Power）
			Check("（配置）有「抽到就减费」这个效果种类，数值 -5~5（负数 = 反向扣层数）",
				EffectCatalog.FindKind("CheapenDraw") is not null
				&& EffectCatalog.FindKind("CheapenDraw").Min == -5 && EffectCatalog.FindKind("CheapenDraw").Max == 5
				&& EffectCatalog.FindKind("CheapenDraw").Display.Contains("抽到就减费"),
				EffectCatalog.FindKind("CheapenDraw")?.Display ?? "(没有)");
			CharacterProfile cheapProbe = ProfileFactory.Sample();
			cheapProbe.VanillaPowerOverrides.Clear();
			CardSpec cheapCard = new CardSpec { Name = "减费探针", ClassName = "UiCheckCheapen", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			cheapCard.Effects.Add(new EffectSpec { Kind = "CheapenDraw", Amount = 3m, TargetSide = "Self" });
			cheapCard.Effects.Add(new EffectSpec { Kind = "CheapenDraw", Amount = -1m, TargetSide = "Self" });
			cheapProbe.Cards.Add(cheapCard);
			Check("门控：只有存档里真的用到这个效果才生成那个 Power 类（不用就不生成）",
				CSharpCodeGen.NeedsDrawCostPower(cheapProbe) && !CSharpCodeGen.NeedsDrawCostPower(ProfileFactory.Sample()), "门控对");
			string cheapCls = Naming.From(cheapProbe).DrawCostPowerClass;
			string cheapPower = CSharpCodeGen.DrawCostPowerSource(cheapProbe);
			Check("生成的 Power：抽到牌就把那张牌的费用 SetThisCombat(当前-1) + 每回合掉 1 层自毁",
				cheapPower.Contains($"public sealed class {cheapCls} : PowerModel")
				&& cheapPower.Contains("if (card.EnergyCost.CostsX || card.EnergyCost.Canonical < 0) return;")
				&& cheapPower.Contains("int __now = card.EnergyCost.GetWithModifiers(CostModifiers.All);")
				&& cheapPower.Contains("card.EnergyCost.SetThisCombat(__now - 1);")
				&& cheapPower.Contains("if (base.Amount <= 1)")
				&& cheapPower.Contains("SetAmount(base.Amount - 1);"), "对");
			string cheapSrc = CSharpCodeGen.CardSource(cheapProbe, cheapCard, 0);
			Check("生成：正数是施加那个状态，负数是取实例后 ModifyAmount 扣层数（复用「负数 = 反向」那套）",
				cheapSrc.Contains("CET:Effect=CheapenDraw")
				&& cheapSrc.Contains($"await PowerCmd.Apply<{cheapCls}>(choiceContext, base.Owner.Creature, 3, base.Owner.Creature, this);")
				&& cheapSrc.Contains($"PowerModel? __negPower = base.Owner.Creature.GetPower<{cheapCls}>();"), "对");
			Check("它不声明动态变量（数值是生成期字面量）",
				!cheapSrc.Contains("new DynamicVar("), "没声明");
			string cheapJson = LocalizationGen.CardsJson(cheapProbe);
			Check("卡面描述：正数写「在 N 回合内…费用 -1」，负数写「解除…N 层」",
				cheapJson.Contains("每抽到一张牌，那张牌本场战斗的费用 -1") && cheapJson.Contains("解除「抽到就减费」1 层"), "描述对");

			// ⑨ 本轮新增：禁止目标回复生命（自造状态 + CreatureCmd.Heal 治疗量清零补丁）
			Check("（配置）有「禁止目标回复生命」这个效果种类，数值 -99~99（负数 = 反向扣层数）",
				EffectCatalog.FindKind("ForbidHeal") is not null
				&& EffectCatalog.FindKind("ForbidHeal").Min == -99 && EffectCatalog.FindKind("ForbidHeal").Max == 99
				&& EffectCatalog.FindKind("ForbidHeal").Display.Contains("回复生命"),
				EffectCatalog.FindKind("ForbidHeal")?.Display ?? "(没有)");
			CharacterProfile noHealProbe = ProfileFactory.Sample();
			noHealProbe.VanillaPowerOverrides.Clear();
			CardSpec noHealCard = new CardSpec { Name = "禁疗探针", ClassName = "UiCheckNoHeal", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			noHealCard.Effects.Add(new EffectSpec { Kind = "ForbidHeal", Amount = 2m, TargetSide = "Enemy" });
			noHealCard.Effects.Add(new EffectSpec { Kind = "ForbidHeal", Amount = -1m, TargetSide = "Enemy" });
			noHealProbe.Cards.Add(noHealCard);
			Check("门控：只有存档里用到这个效果才生成那个状态 + 补丁",
				CSharpCodeGen.NeedsNoHealPower(noHealProbe) && !CSharpCodeGen.NeedsNoHealPower(ProfileFactory.Sample()), "门控对");
			string noHealCls = Naming.From(noHealProbe).NoHealPowerClass;
			string noHealPower = CSharpCodeGen.NoHealPowerSource(noHealProbe);
			Check("补丁：把 CreatureCmd.Heal 的 ref amount 改成 0（**不跳过**原方法 —— async Task 跳过会让调用方 await 到 null）",
				noHealPower.Contains($"public sealed class {noHealCls} : PowerModel")
				&& noHealPower.Contains("[HarmonyLib.HarmonyPatch(typeof(MegaCrit.Sts2.Core.Commands.CreatureCmd), nameof(MegaCrit.Sts2.Core.Commands.CreatureCmd.Heal))]")
				&& noHealPower.Contains("private static void Prefix(Creature creature, ref decimal amount)")
				&& noHealPower.Contains($"if (creature is not null && creature.HasPower<{noHealCls}>()) amount = 0m;"), "对");
			string noHealSrc = CSharpCodeGen.CardSource(noHealProbe, noHealCard, 0);
			Check("生成：只带「禁止回复生命」的牌也会变成「要选目标」；正数是施加、负数是扣层数",
				noHealSrc.Contains("TargetType.AnyEnemy")
				&& noHealSrc.Contains($"await PowerCmd.Apply<{noHealCls}>(choiceContext, cardPlay.Target, 2, base.Owner.Creature, this);")
				&& noHealSrc.Contains($"PowerModel? __negPower = cardPlay.Target.GetPower<{noHealCls}>();"), "对");
			string noHealJson = LocalizationGen.CardsJson(noHealProbe);
			Check("卡面描述：正数写「N 回合内无法回复生命」，负数写「解除…效果」",
				noHealJson.Contains("在 2 回合内无法回复生命") && noHealJson.Contains("解除"), "描述对");
			RelicSpec noHealRelic = new RelicSpec
			{
				Name = "禁疗遗物", ClassName = "UiCheckNoHealRelic", Rarity = "Common", Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "ForbidHeal", Amount = 2m, TargetSide = "Enemy" } },
			};
			noHealProbe.Relics.Add(noHealRelic);
			Check("校验器：把「禁止回复生命」放在遗物上直接报错（它需要「选中的目标」，只做在卡牌上）",
				ProfileValidator.Validate(noHealProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只做在卡牌上")), "拦住了");
			Check("校验器把两条触发时机的差别写清楚（每一下会触发多次 → 指路「连击只算一次」）",
				ProfileValidator.Validate(atkProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("每一下伤害都会触发一次"))
				&& ProfileValidator.Validate(atkProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("所有命中都结束之后")),
				string.Join(" ｜ ", ProfileValidator.Validate(atkProbe).Where((ValidationIssue i) => i.Message.Contains("触发时机")).Select((ValidationIssue i) => i.Level + ":" + i.Message)));
			CharacterProfile atkStackProbe = ProfileFactory.Sample();
			atkStackProbe.CustomPowers.Clear();
			atkStackProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检挨打叠层状态", ClassName = "UiCheckAttackedStack", Type = "Buff",
				Triggers =
				{
					new PowerTriggerSpec
					{
						Kind = "DamageTaken",
						Effects = { new EffectSpec { Kind = "Block", Amount = 2m, Times = 5, TimesIsStack = true } },
					},
				},
			});
			Check("「每一下都触发」×「按层数重复」会相乘 → 校验器直接把算式写出来（一次 5 连击 × 5 层 = 25 次）",
				ProfileValidator.Validate(atkStackProbe).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("相乘")),
				"警告在");
			// 生成 → 回读：AfterAttack 要能认回「受到攻击后」
			string atkRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_attacked_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile atkGenProbe = ProfileFactory.Sample();
				atkGenProbe.Paths.OutputDir = atkRoot;
				atkGenProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				atkGenProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				atkGenProbe.Relics.Add(new RelicSpec
				{
					Name = "自检挨打遗物", ClassName = "UiCheckAttacked", Rarity = "Common", Trigger = "Attacked",
					Effects = { new EffectSpec { Kind = "Block", Amount = 3m } },
				});
				Check("（准备）「受到攻击后」遗物的存档能生成工程", ModGenerator.Generate(atkGenProbe).Success, atkRoot);
				var atkRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(atkGenProbe));
				var recAtk = atkRec.Profile.Relics.FirstOrDefault((RelicSpec r) => r.ClassName == "UiCheckAttacked");
				Check("回读：AfterAttack 认回「受到攻击后（连击只算一次）」",
					recAtk is not null && recAtk.Trigger == "Attacked", $"Trigger={recAtk?.Trigger}");
				Check("回读没有认不出来的语句", !atkRec.HasUnparsed, atkRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(atkRoot)) Directory.Delete(atkRoot, true); } catch { }
			}

			// ⑤ 界面：这两栏只在选到对应效果时出现（用户要求「只有选择这个效果时才出现」）
			DependencyObject newCardRoot = SelectTabRoot("卡牌");
			CardSpec copyUiCard = new CardSpec { Name = "自检复制界面", ClassName = "UiCheckCopyUi", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			copyUiCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, Copies = 2 });
			Profile.Cards.Add(copyUiCard);
			CardList.SelectedItem = copyUiCard;
			CardEffectList.SelectedIndex = 0;
			UpdateLayout();
			Check("选「复制卡牌」时界面上出现「复制的份数」那一栏",
				HasBox("Copies") && VisibleTextsIn(newCardRoot).Any((string t) => t.Contains("复制的份数")), "在");
			copyUiCard.Effects[0].Kind = "GenerateCard";
			copyUiCard.Effects[0].SpawnPick = "Random";
			copyUiCard.Effects[0].SpawnFilter = "Attack";
			UpdateLayout();
			Check("不是复制卡牌时「复制的份数」那一栏不出现（只有选这个效果才出现）",
				!VisibleTextsIn(newCardRoot).Any((string t) => t.Contains("份 / 张")), "没出现");
			Check("换成「生成卡牌 + 按范围随机」后，「多选1」那一栏出现（默认 1 = 直接生成）",
				HasBox("SpawnChoice") && VisibleTextsIn(newCardRoot).Any((string t) => t.Contains("多选1"))
				&& VisibleTextsIn(newCardRoot).Any((string t) => t.Contains("张中选一张")), "在");
			Check("「多选1」那一栏填 3 → 列表里的说明立刻变成「3 张中选一张」",
				SetSpawnChoiceAndDisplay(copyUiCard.Effects[0], 3m).Contains("3 张中选一张"),
				SetSpawnChoiceAndDisplay(copyUiCard.Effects[0], 3m));
			Profile.Cards.Remove(copyUiCard);
			CardList.SelectedItem = Profile.Cards.FirstOrDefault();     // V0.2.140：用对象选（列表里有空槽行）
			UpdateLayout();
			Check("（收尾）自检加的那张复制卡已清掉", !Profile.Cards.Contains(copyUiCard));
		}
		// ===== 本轮新增：消耗牌堆可选中 + 数值 0 一律允许（= 不生效）+ 获得最大生命 + 重放 +
		//              回合结束时自动打出 + 斩杀条件 =====
		{
			// ① 所有能选牌堆的地方都加上「消耗牌堆」（它和另外三摞一样是**战斗牌堆**）
			Check("「从哪里选牌」四摞齐全（+「牌顶」共 5 项）：手牌 / 抽牌堆 / 弃牌堆 / 消耗牌堆 / 牌顶",
				EffectCatalog.SelectPiles.Count == 5
				&& EffectCatalog.SelectPiles.Any((PileChoiceOption o) => o.Id == "Exhaust")
				&& EffectCatalog.SelectPileZh("Exhaust") == "消耗牌堆"
				&& EffectCatalog.SelectPileZh("Top") == "牌顶"
				&& new EffectSpec { SelectPile = "Exhaust" }.SelectPileZh == "消耗牌堆", "四摞 + 牌顶");
			Check("消耗 / 变化 / 升级 / 丢弃 / 复制 / 重放 / 给关键词 都能选消耗牌堆（四摞 + 牌顶共 5 项）",
				new[] { "ExhaustCard", "TransformCard", "UpgradeCard", "CopyCard", "ReplayCard", "GiveKeyword" }
					.All(k => new EffectSpec { Kind = k }.UsesSelectPile && new EffectSpec { Kind = k }.SelectPileChoices.Count == 5)
				// 丢弃带张数时同样能选那几摞（数值 0 = 丢弃这张牌自己那一档不挑牌，见上一条）
				&& new EffectSpec { Kind = "DiscardCard", Amount = 1m }.UsesSelectPile
				&& new EffectSpec { Kind = "DiscardCard", Amount = 1m }.SelectPileChoices.Count == 5, "都行");
			Check("效果种类里有「从消耗牌堆拿牌到手牌」（和另外两摞一个写法）",
				EffectCatalog.EffectKinds.Any((EffectKindOption k) => k.Kind == "TakeFromExhaust"), "在");
			// 「牌顶」（用户要求：选牌 / 取牌方式里多一个「牌顶」）= 抽牌堆最上面那张，直接拿走（不问、不随机）"
			{
				Check("（前置）「牌顶」这一档：PileExpr 给的是抽牌堆，取法是 FirstOrDefault（不随机）",
					CSharpCodeGen.IsPileTop(new EffectSpec { SelectPile = "Top" })
					&& !CSharpCodeGen.IsPileTop(new EffectSpec { SelectPile = "Draw" }), "判定对");
				CharacterProfile topProfile = ProfileFactory.Sample();
				CardSpec topCard = new CardSpec { Name = "牌顶卡", ClassName = "UiCheckPileTop", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				foreach (string kind in new[] { "ExhaustCard", "DiscardCard", "CopyCard", "UpgradeCard", "TransformCard", "ReplayCard", "GiveKeyword", "TurnEndPlay" })
				{
					var fx = new EffectSpec { Kind = kind, Amount = 1m, CardPick = "Random", SelectPile = "Top", TargetSide = "Self" };
					if (kind == "GiveKeyword") fx.GivenKeyword = "Retain";
					topCard.Effects.Add(fx);
				}
				topProfile.Cards.Add(topCard);
				string topSrc = CSharpCodeGen.CardSource(topProfile, topCard, 0);
				Check("八种「选牌」效果选「牌顶」时都是从抽牌堆顶拿（PileType.Draw.GetPile + FirstOrDefault / Take）",
					topSrc.Split("PileType.Draw.GetPile").Length - 1 >= 6
					&& (topSrc.Contains(".FirstOrDefault()") || topSrc.Contains(".Take(")), "都从牌顶拿");
				Check("「牌顶」不会去弹选牌界面（不生成 CardSelectCmd.FromHand / FromCombatPile）",
					!topSrc.Contains("CardSelectCmd.FromHand(") && !topSrc.Contains("CardSelectCmd.FromCombatPile("), "不问玩家");
				Check("「牌顶」也不随机抓（不生成 NextItem(PileType.Draw）",
					!topSrc.Contains("NextItem(PileType.Draw"), "不随机");
				Check("标记行里带上 CET:Pile=Top（回读按它还原，不然会被当成「抽牌堆」）",
					topSrc.Contains("CET:Pile=Top"), "有标记");
				// 生成 → 回读
				string topRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_piletop_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				try
				{
					topProfile.Paths.OutputDir = topRoot;
					topProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
					topProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var topGen = ModGenerator.Generate(topProfile);
					Check("（准备）带「牌顶」的存档能生成工程", topGen.Success,
						topGen.Success ? topGen.ProjectRoot : string.Join(" ｜ ", topGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
					if (topGen.Success)
					{
						var topRec = ProjectRecovery.FromProject(topGen.ProjectRoot);
						CardSpec? topBack = topRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckPileTop");
						Check("回读：「牌顶」这一档原样认得回来（不会被降级成「抽牌堆」或「手牌」）",
							topBack is not null && topBack.Effects.Count >= 6 && topBack.Effects.All((EffectSpec x) => x.SelectPile == "Top"),
							topBack is null ? "(缺 " : string.Join("/", topBack.Effects.Select((EffectSpec x) => x.Kind + ":" + x.SelectPile)));
						Check("回读（带牌顶）：没认出来的语句为 0", !topRec.HasUnparsed, topRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
					}
				}
				finally
				{
					try { if (Directory.Exists(topRoot)) Directory.Delete(topRoot, true); } catch { }
				}
			}
			CharacterProfile exProbe = ProfileFactory.Sample();
			CardSpec exCard = new CardSpec { Name = "自检消耗堆", ClassName = "UiCheckExhaustPile", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			exCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Exhaust" });
			exCard.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Exhaust" });
			exCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Random", SelectPile = "Exhaust" });
			exCard.Effects.Add(new EffectSpec { Kind = "TakeFromExhaust", Amount = 2m });
			exProbe.Cards.Add(exCard);
			string exSrc = CSharpCodeGen.CardSource(exProbe, exCard, 0);
			Check("从消耗牌堆消耗 / 升级 / 丢弃：都是 PileType.Exhaust.GetPile(base.Owner)",
				exSrc.Split(new[] { "PileType.Exhaust.GetPile(base.Owner)" }, StringSplitOptions.None).Length - 1 >= 3, "三处");
			Check("「从消耗牌堆拿牌到手牌」走 FromCombatPile + Add(…, Hand)，描述也写「消耗牌堆」",
				exSrc.Contains("CardSelectCmd.FromCombatPile(choiceContext, PileType.Exhaust.GetPile(base.Owner), base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, 2))")
				&& exSrc.Contains("if (__taken.Count > 0) await CardPileCmd.Add(__taken, PileType.Hand);")
				&& LocalizationGen.CardsJson(exProbe).Contains("从消耗牌堆里选 {Cards4:diff()} 张牌拿到手牌。"), "对");
			Check("自己选消耗牌堆里的牌 → 也会生成 <卡>.selectionScreenPrompt（不然本体直接抛异常、游戏卡死）",
				LocalizationGen.NeedsSelectPrompt(exCard.Effects)
				&& LocalizationGen.CardsJson(exProbe).Contains("UI_CHECK_EXHAUST_PILE.selectionScreenPrompt")
				&& LocalizationGen.SelectPromptText(new[] { new EffectSpec { Kind = "TakeFromExhaust" } }) == "从消耗牌堆选择要拿到手牌的牌", "有提示语");

			// ② 数值一律允许填 0（0 = 不生效）
			var badMin = EffectCatalog.EffectKinds.Where((EffectKindOption k) => k.Min > 0m).ToList();
			Check("所有效果种类的数值范围都允许 0（用户要求：不能填 0 的也能填 0）",
				badMin.Count == 0, badMin.Count == 0 ? "全部 ≤ 0" : string.Join("/", badMin.Select((EffectKindOption k) => $"{k.Kind}:{k.Min}")));
			Check("0 值效果一律「不显示也不执行」（以前不能填 0 的那些也一样；例外的只有「0 = 这张牌自己」那几档）",
				new[] { "GenerateCard", "TransformCard", "UpgradeCard", "Scry",
						"ReplayCard", "TakeFromDraw", "TakeFromDiscard", "TakeFromExhaust",
						"AddCardGlobal", "CardReward", "ApplyPower", "Draw" }
					.All(k => CSharpCodeGen.IsInertZero(new EffectSpec { Kind = k, Amount = 0m })), "都算不生效");
			Check("三种「0 有别的含义」的效果**不**算不生效（召唤伙伴用配置血量 / 给予关键词=这张牌自己 / 回合结束=这张牌自己）",
				!CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "SummonPet", Amount = 0m })
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "GiveKeyword", Amount = 0m })
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "TurnEndPlay", Amount = 0m })
				// V0.2.226：复制卡牌填 0 = 复制**这张牌自己**，也有含义（以前这里算「不生效」）
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "CopyCard", Amount = 0m }), "有含义");
			CharacterProfile zeroProbe = ProfileFactory.Sample();
