			zeroCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 0m, SpawnCardId = "Shiv" });
			zeroCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 0m });
