				&& CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "ReturnSelfToHand", Amount = 0m, UpgradeAmount = 1m })
				&& !CSharpCodeGen.IsInertZero(new EffectSpec { Kind = "ReturnSelfToHand", Amount = 1m }), "开关型");
