				new EffectSpec { Kind = "CopyCard" }.UsesSpawnOptions
				&& new EffectSpec { Kind = "CopyCard", SpawnFree = true }.HasSpawnModifier, "在");
			CharacterProfile cpModProbe = ProfileFactory.Sample();
