					var dsRec = ProjectRecovery.FromProject(dsGen.ProjectRoot);
					var dsRecCard = dsRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckDiscardSelf");
					Check("从工程恢复：效果**不多不少**正好 3 条，张数 0 也认得回来（实现那一句不会被当成第二条丢弃）",
						dsRecCard is not null && dsRecCard.Effects.Count == 3
						&& dsRecCard.Effects[1].Kind == "DiscardCard" && dsRecCard.Effects[1].Amount == 0m
						&& dsRecCard.Effects[2].Kind == "Damage" && dsRecCard.Effects[2].UpgradeAmount == 3m,
						dsRecCard is null ? "(没找回这张卡)" : string.Join(" / ", dsRecCard.Effects.Select((EffectSpec x) => x.Kind + "=" + x.Amount + "+" + x.UpgradeAmount)));
					Check("从工程恢复（带丢弃自己）：没认出来的语句为 0", !dsRec.HasUnparsed, dsRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
				finally
				{
					try { Directory.Delete(dsRoot, true); } catch { }
				}
			}

			CharacterProfile srRelicProbe = ProfileFactory.Sample();
			var srRelic = new RelicSpec
			{
				Name = "自检回手遗物", ClassName = "UiCheckReturnRelic", Rarity = "Common", InRelicPool = true, Trigger = "PlayerTurnStart",
				Effects = { new EffectSpec { Kind = "ReturnSelfToHand", Amount = 1m, TargetSide = "Self" } },
			};
			srRelicProbe.Relics.Add(srRelic);
			Check("校验器：把「将此牌放回手牌」配到遗物上会被拦住（遗物没有「这张牌」）",
				ProfileValidator.Validate(srRelicProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只做在卡牌上") && i.Message.Contains("这张牌自己")),
				ProfileValidator.Validate(srRelicProbe).FirstOrDefault((ValidationIssue i) => i.Message.Contains("只做在卡牌上"))?.Message ?? "(没报)");

			// ③ 「获得最大生命」（用户找的就是这个名字）

			Check("效果种类里的「获得最大生命（负数 = 失去）」（用户报过找不到）",
				EffectCatalog.FindKind("MaxHp").Display.Contains("获得最大生命")
				&& EffectCatalog.FindKind("MaxHp").Min < 0m, EffectCatalog.FindKind("MaxHp").Display);

			// ④ 重放卡牌（本体 CardModel.BaseReplayCount）
			Check("效果种类里有「重放卡牌」，而且只有它显示「重放次数」那一栏",
				EffectCatalog.EffectKinds.Any((EffectKindOption k) => k.Kind == "ReplayCard")
				&& new EffectSpec { Kind = "ReplayCard" }.ShowReplayTimes
				&& !new EffectSpec { Kind = "CopyCard" }.ShowReplayTimes, "在");
			CharacterProfile rpProbe = ProfileFactory.Sample();
			CardSpec rpCard = new CardSpec { Name = "自检重放", ClassName = "UiCheckReplay", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			rpCard.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 1m, ReplayTimes = 2, CardPick = "Chosen", SelectPile = "Hand" });
			CardSpec rpRandCard = new CardSpec { Name = "自检重放随机", ClassName = "UiCheckReplayRand", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			rpRandCard.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 2m, ReplayTimes = 1, CardPick = "Random", SelectPile = "Exhaust" });
			rpProbe.Cards.Add(rpCard);
			rpProbe.Cards.Add(rpRandCard);
			string rpSrc = CSharpCodeGen.CardSource(rpProbe, rpCard, 0);
			string rpRandSrc = CSharpCodeGen.CardSource(rpProbe, rpRandCard, 0);
			Check("重放（自己选）：先算候选池（排除打不出去 / 已有重放的），池空就整条跳过；选出来的每张 BaseReplayCount += N，最后一次性预览",
				rpSrc.Contains("__replayPool = PileType.Hand.GetPile(base.Owner).Cards.Where(c => !c.Keywords.Contains(CardKeyword.Unplayable) && c.GetEnchantedReplayCount() < 1).ToList();")
				&& rpSrc.Contains("if (__replayPool.Count > 0) {")
				&& rpSrc.Contains("int __replayWant = Math.Min(1, __replayPool.Count);")
				&& rpSrc.Contains("new CardSelectorPrefs(base.SelectionScreenPrompt, __replayWant)")
				&& rpSrc.Contains("__replayCard.BaseReplayCount += 2;")
				&& rpSrc.Contains("CardCmd.Preview(__replayFrom);"), "对");
			Check("重放（随机）：从那一摞（这里是消耗牌堆）的候选池里随机拿（最多 N 张）再加",
				rpRandSrc.Contains("__replayPool = PileType.Exhaust.GetPile(base.Owner).Cards.Where(c => !c.Keywords.Contains(CardKeyword.Unplayable) && c.GetEnchantedReplayCount() < 1).ToList();")
				&& rpRandSrc.Contains("TakeRandom(__replayPool, __replayWant, base.Owner.RunState.Rng.CombatCardSelection)")
				&& rpRandSrc.Contains("__replayCard.BaseReplayCount += 1;"), "对");
			Check("重放的卡面描述写清「额外打出 N 次」",
				LocalizationGen.CardsJson(rpProbe).Contains("本场战斗内额外打出 2 次"), "描述对");
			Check("校验器说清「重放只能给别的牌加」（自己这张牌的重放次数是本体的 OnPlay 之前算好的）",
				ProfileValidator.Validate(rpProbe).Any((ValidationIssue i) => i.Level == "提示" && i.Message.Contains("只能给别的牌")), "有说明");
			CharacterProfile rpPowerProbe = ProfileFactory.Sample();
			rpPowerProbe.CustomPowers.Clear();
			rpPowerProbe.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检重放状态", ClassName = "UiCheckReplayPower", Type = "Buff",
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "ReplayCard", Amount = 1m, ReplayTimes = 1 } } } },
			});
			Check("自定义状态里放重放 → 校验器给警告（生成时留一行说明）",
				ProfileValidator.Validate(rpPowerProbe).Any((ValidationIssue i) => i.Level == "警告" && i.Message.Contains("重放卡牌")), "有警告");

			// ⑤ 回合结束时自动打出
			Check("效果种类里有「回合结束时自动打出」，数值 0 有含义（不是「不生效」）",
				EffectCatalog.EffectKinds.Any((EffectKindOption k) => k.Kind == "TurnEndPlay")
				&& EffectCatalog.FindKind("TurnEndPlay").Min == 0m
				&& new EffectSpec { Kind = "TurnEndPlay" }.IsTurnEndPlay
				&& new EffectSpec { Kind = "TurnEndPlay" }.ShowTurnEndPlay, "在");
			CharacterProfile teProbe = ProfileFactory.Sample();
			CardSpec teSelf = new CardSpec { Name = "自检回合末自己", ClassName = "UiCheckTurnEndSelf", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			teSelf.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 0m });
			CardSpec tePick = new CardSpec { Name = "自检回合末选牌", ClassName = "UiCheckTurnEndPick", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			tePick.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 2m, CardPick = "Chosen", SelectPile = "Exhaust" });
			CardSpec teRand = new CardSpec { Name = "自检回合末随机", ClassName = "UiCheckTurnEndRand", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			teRand.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 1m, CardPick = "Random", SelectPile = "Hand" });
			teProbe.Cards.Add(teSelf);
			teProbe.Cards.Add(tePick);
			teProbe.Cards.Add(teRand);
			string teSelfSrc = CSharpCodeGen.CardSource(teProbe, teSelf, 0);
			string tePickSrc = CSharpCodeGen.CardSource(teProbe, tePick, 0);
			string teRandSrc = CSharpCodeGen.CardSource(teProbe, teRand, 0);
			Check("数值 0：挂上内置 Power 并把**这张牌自己**交给它（本回合结束时再打一次）",
				teSelfSrc.Contains(".Create(new CardModel[] { this })")
				&& teSelfSrc.Contains("ForgeTurnEndPlayPower.Create"), "对");
			Check("数值 ≥ 1 + 自己选：先选好（走本体选牌界面），再把选出来的牌交给那个 Power",
				tePickSrc.Contains("CardSelectCmd.FromCombatPile(choiceContext, PileType.Exhaust.GetPile(base.Owner), base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, 2))")
				&& tePickSrc.Contains("if (__tePicks.Count > 0) await PowerCmd.Apply(choiceContext,")
				&& tePickSrc.Contains("ForgeTurnEndPlayPower.Create(__tePicks)"), "对");
			Check("数值 ≥ 1 + 随机：直接从那一摞随机拿 N 张",
				teRandSrc.Contains("TakeRandom(PileType.Hand.GetPile(base.Owner).Cards, 1,"), "随机对");
			Check("那个内置 Power 在 BeforeSideTurnEnd 里逐张 CardCmd.AutoPlay（那时本体还没结算手牌）",
				CSharpCodeGen.UsesTurnEndPlay(teProbe)
				&& CSharpCodeGen.TurnEndPlayPowerSource(teProbe).Contains("public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)")
				&& CSharpCodeGen.TurnEndPlayPowerSource(teProbe).Contains("await CardCmd.AutoPlay(choiceContext, __c, null);")
				&& CSharpCodeGen.TurnEndPlayPowerSource(teProbe).Contains("protected override bool IsVisibleInternal => false;"), "对");
			Check("描述：0 写「回合结束时自动打出这张牌」；≥1 写「…回合结束时自动打出它们」",
				LocalizationGen.CardsJson(teProbe).Contains("回合结束时自动打出这张牌。")
				&& LocalizationGen.CardsJson(teProbe).Contains("回合结束时自动打出它们。"), "描述对");
			CharacterProfile teRelicProbe = ProfileFactory.Sample();
			teRelicProbe.Relics.Add(new RelicSpec
			{
				Name = "自检回合末遗物", ClassName = "UiCheckTurnEndRelic", Rarity = "Common", Trigger = "CombatStart",
				Effects = { new EffectSpec { Kind = "TurnEndPlay", Amount = 0m } },
			});
			Check("遗物上填 0（= 这张牌自己）会被校验器拦住（遗物没有「自己这张牌」）",
				ProfileValidator.Validate(teRelicProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只有卡牌才有「自己」"))
				&& CSharpCodeGen.RelicSource(teRelicProbe, teRelicProbe.Relics[^1], 0).Contains("只有卡牌才有「自己」"), "拦住了");

			// ⑥ 条件选项「斩杀」（本体 Fatal）
			Check("条件选项里有「斩杀（这一次攻击杀死了目标）」，而且只给卡牌用",
				EffectCatalog.Conditions.Any((ConditionOption o) => o.Id == "Fatal" && o.ForCard && !o.ForRelic), "在");
			CharacterProfile faProbe = ProfileFactory.Sample();
			CardSpec faCard = new CardSpec { Name = "自检斩杀", ClassName = "UiCheckFatal", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			faCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 10m, TargetSide = "Enemy" });
			faCard.Effects.Add(new EffectSpec { Kind = "Gold", Amount = 20m, Condition = new ConditionSpec { Kind = "Fatal" } });
			faProbe.Cards.Add(faCard);
			string faSrc = CSharpCodeGen.CardSource(faProbe, faCard, 0);
			Check("斩杀：OnPlay 开头声明两个变量（上一条攻击 / 打之前记下的「目标允许触发斩杀」）",
				faSrc.Contains("MegaCrit.Sts2.Core.Commands.Builders.AttackCommand? __lastAttack = null;")
				&& faSrc.Contains("bool __fatalOk = false;"), "声明了");
			Check("斩杀：打之前先算 shouldTriggerFatal（本体 Feed / HandOfGreed 的顺序），并把这次攻击记进 __lastAttack",
				faSrc.Contains("__fatalOk = cardPlay.Target is null || cardPlay.Target.Powers.All(pm => pm.ShouldOwnerDeathTriggerFatal());")
				&& faSrc.Contains("__lastAttack = await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue)"), "对");
			Check("斩杀：判据就是本体那套（Results 里 WasTargetKilled）",
				faSrc.Contains("if (__lastAttack is not null && __fatalOk && __lastAttack.Results.SelectMany(hits => hits).Any(r => r.WasTargetKilled))"), "对");
			Check("斩杀：卡牌会挂上本体的「斩杀」悬停说明（StaticHoverTip.Fatal）",
				faSrc.Contains("HoverTipFactory.Static(MegaCrit.Sts2.Core.HoverTips.StaticHoverTip.Fatal)"), "有说明");
			Check("斩杀：卡面描述照本体的写法写「[gold]斩杀[/gold]时，…」", LocalizationGen.CardsJson(faProbe).Contains("[gold]斩杀[/gold]时，获得"), "描述对");
			CharacterProfile faBadProbe = ProfileFactory.Sample();
			CardSpec faBad = new CardSpec { Name = "自检斩杀无伤害", ClassName = "UiCheckFatalBad", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			faBad.Effects.Add(new EffectSpec { Kind = "Gold", Amount = 20m, Condition = new ConditionSpec { Kind = "Fatal" } });
			faBadProbe.Cards.Add(faBad);
			Check("斩杀：前面没有造成伤害的效果 → 报错拦住（不然永远不成立）",
				ProfileValidator.Validate(faBadProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("前面没有任何造成伤害的效果")), "拦住了");
			CharacterProfile faRelicProbe = ProfileFactory.Sample();
			faRelicProbe.Relics.Add(new RelicSpec
			{
				Name = "自检斩杀遗物", ClassName = "UiCheckFatalRelic", Rarity = "Common", Trigger = "CombatStart",
				Effects = { new EffectSpec { Kind = "Damage", Amount = 5m, Condition = new ConditionSpec { Kind = "Fatal" } } },
			});
			Check("斩杀：遗物上用 → 报错（只能用在卡牌上，本体那几个都是攻击牌）",
				ProfileValidator.Validate(faRelicProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只能用在**卡牌**上")), "拦住了");

			// ⑫ V0.2.195（用户要求）：「上一张打出的牌是 攻击/技能/能力/状态/诅咒 牌」。
			// 数据源 = 本体战斗历史 CardPlaysFinished（最后一张结算完的牌，不限回合）；
			// 四条链（卡牌 / 遗物 / 药水 / 自定义状态）+ 锻造页【条件】模块都要能选到、生成正确、文案对。
			{
				string[] lcKinds = { "LastCardAttack", "LastCardSkill", "LastCardPower", "LastCardStatus", "LastCardCurse" };
				Check("条件选项里有 5 条「上一张打出的牌是 攻击 / 技能 / 能力 / 状态 / 诅咒 牌」，四条链都能用（不需要填数值）",
					lcKinds.All((string k) => EffectCatalog.Conditions.Any((ConditionOption o) => o.Id == k && o.ForCard && o.ForRelic && o.ForPower && !o.NeedsAmount && !o.NeedsPower)),
					string.Join(" / ", lcKinds.Select((string k) => EffectCatalog.FindCondition(k)?.Display ?? "(缺)")));
				Check("锻造页【条件】模块的候选里有这 5 条（和卡牌页同一份候选）",
					lcKinds.All((string k) => ForgeGraphCatalog.ConditionPicks.Any((ForgeFieldOption p) => p.Id == k)), "都在");
				CharacterProfile lcProbe = ProfileFactory.Sample();
				CardSpec lcCard = new CardSpec { Name = "自检上一张", ClassName = "UiCheckLastCard", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				lcCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy", Condition = new ConditionSpec { Kind = "LastCardSkill" } });
				lcProbe.Cards.Add(lcCard);
				string lcSrc = CSharpCodeGen.CardSource(lcProbe, lcCard, 0);
				Check("卡牌上：判据是战斗历史里最后一张结算完的牌（CardPlaysFinished.LastOrDefault，不限回合）",
					lcSrc.Contains("CombatManager.Instance.History.CardPlaysFinished.LastOrDefault(e => e.CardPlay.Player == base.Owner)?.CardPlay.Card.Type == CardType.Skill"), "表达式对");
				Check("卡牌上：两个 null 判断都在（没有战斗状态 / 没有玩家时不会炸）",
					lcSrc.Contains("base.CombatState is not null && base.Owner is not null && CombatManager.Instance.History.CardPlaysFinished.LastOrDefault"), "有防护");
				Check("卡面文案：「条件：上一张打出的牌是技能牌（不满足时这张牌的效果不生效）」",
					LocalizationGen.CardsJson(lcProbe).Contains("上一张打出的牌是技能牌"), "文案对");
				Check("校验器：这 5 条条件在卡牌上放行（不报「不能用在这里」）",
					!ProfileValidator.Validate(lcProbe).Any((ValidationIssue i) => i.IsError && i.Message.Contains("不能用在这里")), "放行");
				CharacterProfile lcRelicProf = ProfileFactory.Sample();
				RelicSpec lcRelic = new RelicSpec { Name = "自检上一张遗物", ClassName = "UiCheckLastCardRelic", Rarity = "Common", Trigger = "CombatStart" };
				lcRelic.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, Condition = new ConditionSpec { Kind = "LastCardCurse" } });
				lcRelicProf.Relics.Add(lcRelic);
				string lcRelicSrc = CSharpCodeGen.RelicSource(lcRelicProf, lcRelic, 0);
				Check("遗物上：CombatState 走 base.Owner.Creature.CombatState（遗物模型上没有 CombatState）",
					lcRelicSrc.Contains("base.Owner.Creature.CombatState is not null && base.Owner is not null && CombatManager.Instance.History.CardPlaysFinished.LastOrDefault(e => e.CardPlay.Player == base.Owner)?.CardPlay.Card.Type == CardType.Curse"), "表达式对");
				CharacterProfile lcPotionProf = ProfileFactory.Sample();
				PotionSpec lcPotion = new PotionSpec { Name = "自检上一张药水", ClassName = "UiCheckLastCardPotion", Rarity = "Common" };
				lcPotion.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, Condition = new ConditionSpec { Kind = "LastCardPower" } });
				lcPotionProf.Potions.Add(lcPotion);
				string lcPotionSrc = CSharpCodeGen.PotionSource(lcPotionProf, lcPotion, 0);
				Check("药水上：和遗物同形（CondCtx.Potion），判的是能力牌",
					lcPotionSrc.Contains("base.Owner.Creature.CombatState is not null") && lcPotionSrc.Contains("CardType.Power"), "表达式对");
				CustomPowerSpec lcPower = new CustomPowerSpec { Name = "自检上一张状态", ClassName = "UiCheckLastCardPower", Enabled = true };
				PowerTriggerSpec lcTrig = new PowerTriggerSpec { Kind = "PlayerTurnStart" };
				lcTrig.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, Condition = new ConditionSpec { Kind = "LastCardStatus" } });
				lcPower.Triggers.Add(lcTrig);
				string lcPowerSrc = CustomPowerGen.Source(ProfileFactory.Sample(), lcPower, 0);
				Check("自定义状态上：玩家那一侧取 base.Owner.Player（状态挂在生物身上），判的是状态牌",
					lcPowerSrc.Contains("base.Owner.Player is not null && CombatManager.Instance.History.CardPlaysFinished.LastOrDefault(e => e.CardPlay.Player == base.Owner.Player)?.CardPlay.Card.Type == CardType.Status"), "表达式对");
				Check("回读：这 5 条条件的文案都是完整一句话（下拉 + 卡面用的是同一份）",
					lcKinds.All((string k) => CSharpCodeGen.ConditionText(new ConditionSpec { Kind = k }).StartsWith("上一张打出的牌是", StringComparison.Ordinal)),
					string.Join(" / ", lcKinds.Select((string k) => CSharpCodeGen.ConditionText(new ConditionSpec { Kind = k }))));
				// 真回读（从工程恢复）：生成一遍再反推，条件要从代码里认回来（不是丢成「无条件」）
				CharacterProfile lcRecProfile = ProfileFactory.Sample();
				lcRecProfile.Paths.VanillaProject = Profile.Paths.VanillaProject;
				lcRecProfile.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec lcRecCard = new CardSpec { Name = "自检上一张回读", ClassName = "UiCheckLastCardRec", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				lcRecCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy", Condition = new ConditionSpec { Kind = "LastCardCurse" } });
				lcRecProfile.Cards.Add(lcRecCard);
				var lcRecGen = ModGenerator.Generate(lcRecProfile);
				if (!lcRecGen.Success)
				{
					Check("（回读）「上一张打出的牌是 X 牌」的工程能生成", false,
						string.Join(" / ", lcRecGen.Issues.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
				}
				else
				{
					var lcRec = ProjectRecovery.FromProject(lcRecGen.ProjectRoot);
					var lcBack = lcRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckLastCardRec");
					Check("回读：从工程恢复时「上一张打出的牌是诅咒牌」原样认回来（不会丢成无条件）",
						lcBack is not null && lcBack.Effects.Any((EffectSpec x) => x.Condition is { Kind: "LastCardCurse" }),
						lcBack is null ? "(没回读到这张卡)" : string.Join(" / ", lcBack.Effects.Select((EffectSpec x) => x.Condition?.Kind ?? "None")));
				}
			}

			// ⑩ 条件选项「卡牌时机」+ 6 个子时机
			// 这一条和别的条件**架构上不同**：带它的效果不写进 OnPlay，而是生成成本体对应钩子的 override
			//（本体「战鼓」DrumOfBattle 的做法），所以断言要同时看「钩子挂对了」和「OnPlay 里没有它」。
			Check("条件选项里有「卡牌时机」，而且只给卡牌用（遗物 / 药水 / 自定义状态没有「这张牌被消耗」这一说）",
				EffectCatalog.Conditions.Any((ConditionOption o) => o.Id == "CardTiming" && o.ForCard && !o.ForRelic && !o.ForPower && o.NeedsTiming), "在");
			Check("「卡牌时机」的子时机齐、中文名就是需求里那几个 + 后加的「失去生命时」",
				ConditionTimings.Select((CardTimingOption t) => t.Display)
					.SequenceEqual(new[] { "被消耗", "被生成", "被保留", "被丢弃", "被变化", "被给予自定义关键词", "失去生命时" }),
				string.Join(" / ", ConditionTimings.Select((CardTimingOption t) => t.Display)));
			Check("「卡牌时机」不在遗物 / 自定义状态的条件表里（选了会被校验器拦住）",
				!RelicConditions.Any((ConditionOption o) => o.Id == "CardTiming")
				&& !PlainEffectConditions.Any((ConditionOption o) => o.Id == "CardTiming"), "归属正确");
			// 生成端：一个子时机一条断言（拿到的源码里找签名 / 守卫 / 标记 / 效果体）
			CharacterProfile ctProbe = ProfileFactory.Sample();
			CardSpec ctCard = new CardSpec { Name = "自检时机", ClassName = "UiCheckCardTiming", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true, Retain = true };
			foreach (string timingId in new[] { "Exhausted", "Generated", "Retained", "Discarded", "Transformed", "GivenKeyword", "HpLost" })
				ctCard.Effects.Add(new EffectSpec
				{
					Kind = "Block", Amount = 4m, TargetSide = "Self",
					Condition = new ConditionSpec { Kind = "CardTiming", Timing = timingId },
				});
			ctProbe.Cards.Add(ctCard);
			string ctSrc = CSharpCodeGen.CardSource(ctProbe, ctCard, 0);
			Check("被消耗 → 覆写本体 AbstractModel.AfterCardExhausted（「战鼓」的做法）+ card == this 守卫 + CET 标记",
				ctSrc.Contains("public override async Task AfterCardExhausted(PlayerChoiceContext choiceContext, CardModel card, bool causedByEthereal)")
				&& ctSrc.Contains("if (card != this || base.CombatState is null) return;")
				&& ctSrc.Contains("// CET:CardTiming=Exhausted"), "挂上了");
			Check("被丢弃 → 覆写 AbstractModel.AfterCardDiscarded",
				ctSrc.Contains("public override async Task AfterCardDiscarded(PlayerChoiceContext choiceContext, CardModel card)")
				&& ctSrc.Contains("// CET:CardTiming=Discarded"), "挂上了");
			Check("被生成 → 覆写 AbstractModel.AfterCardGeneratedForCombat（那个同步的 AfterCreated 没有 choiceContext，await 不了命令）",
				ctSrc.Contains("public override async Task AfterCardGeneratedForCombat(CardModel card, Player? creator)")
				&& ctSrc.Contains("new HookPlayerChoiceContext(this,")
				&& ctSrc.Contains("// CET:CardTiming=Generated"), "挂上了");
			Check("被保留 → 覆写 AbstractModel.AfterFlush，判据是「本体把这张牌归进了 retainedCards」",
				ctSrc.Contains("public override async Task AfterFlush(PlayerChoiceContext choiceContext, Player player, IReadOnlyCollection<CardModel> flushedCards, IReadOnlyCollection<CardModel> retainedCards)")
				&& ctSrc.Contains("if (!retainedCards.Contains(this)) return;")
				&& ctSrc.Contains("// CET:CardTiming=Retained"), "挂上了");
			Check("被变化 → 覆写 CardModel.AfterTransformedFrom（本体 Transform 里对「被变成别的牌」那张调的就是它）",
				ctSrc.Contains("public override void AfterTransformedFrom()")
				&& ctSrc.Contains("ForgeOnTransformedFrom(choiceContext)")
				&& ctSrc.Contains("// CET:CardTiming=Transformed"), "挂上了");
			Check("被给予自定义关键词 → 生成卡自己的入口方法，由「给予卡牌关键词」那一步直接调",
				ctSrc.Contains("public async Task ForgeOnGivenCustomKeyword(PlayerChoiceContext choiceContext)")
				&& ctSrc.Contains("// CET:CardTiming=GivenKeyword"), "挂上了");
			Check("失去生命时 → 覆写 AbstractModel.AfterCurrentHpChanged（delta < 0 = 掉了血）+ 只认自己 + 这张牌得在手上",
				ctSrc.Contains("public override async Task AfterCurrentHpChanged(Creature creature, decimal delta)")
				&& ctSrc.Contains("if (creature != base.Owner.Creature || delta >= 0m) return;")
				&& ctSrc.Contains("if (base.Pile?.Type != PileType.Hand) return;")
				&& ctSrc.Contains("// CET:CardTiming=HpLost"), "挂上了");
			// 「不写进 OnPlay」：OnPlay 那段里不能出现这些效果（效果体只在钩子里）
			int ctOnPlayAt = ctSrc.IndexOf("protected override async Task OnPlay", StringComparison.Ordinal);
			int ctHookAt = ctSrc.IndexOf("public override async Task AfterCardExhausted", StringComparison.Ordinal);
			string ctOnPlay = ctOnPlayAt >= 0 && ctHookAt > ctOnPlayAt ? ctSrc[ctOnPlayAt..ctHookAt] : "(没找到 OnPlay)";
			Check("带「卡牌时机」的效果**不在 OnPlay 里**（OnPlay 只留一句 await），效果体全在钩子里",
				!ctOnPlay.Contains("GainBlock") && !ctOnPlay.Contains("CardTiming")
				&& ctSrc.Split("await CreatureCmd.GainBlock").Length - 1 == 7, "不在 OnPlay");
			Check("同一张牌多个时机 → 一个时机一个 override，各跑各的那一条效果",
				ctSrc.Split("await CreatureCmd.GainBlock").Length - 1 == 7, "7 条效果各在一个钩子里");
			// 被给予自定义关键词：给关键词那一步要转发（转发器只在真的用到这个时机时才生成）
			CharacterProfile gkProbe = ProfileFactory.Sample();
			gkProbe.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE10", Name = "命运十" });
			CardSpec gkCard = new CardSpec { Name = "自检给关键词", ClassName = "UiCheckGiven10", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			gkCard.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 0m, GivenKeyword = "FATE10" });
			gkCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "Self", Condition = new ConditionSpec { Kind = "CardTiming", Timing = "GivenKeyword" } });
			gkProbe.Cards.Add(gkCard);
			string gkSrc = CSharpCodeGen.CardSource(gkProbe, gkCard, 0);
			string gkPatch = CSharpCodeGen.GivenKeywordPatchSource(gkProbe);
			Check("被给予自定义关键词：给关键词那一步直接转发给这张牌（复用「给予卡牌关键词」那条链，没有另造机制）",
				gkSrc.Contains("ForgeGivenKeywordTiming.Notify(choiceContext, this)")
				&& gkPatch.Contains("internal static class " + Naming.From(gkProbe).CharClass + "ForgeGivenKeywordTiming")
				&& gkPatch.Contains("case UiCheckGiven10 __given: return __given.ForgeOnGivenCustomKeyword(choiceContext);"), "转发了");
			Check("没有「卡牌时机」的存档不生成任何转发 / 钩子（默认档不变）",
				!CSharpCodeGen.GivenKeywordPatchSource(ProfileFactory.Sample()).Contains("GivenKeywordTiming"), "没生成");
			CharacterProfile ctPlain = ProfileFactory.Sample();
			CardSpec ctPlainCard = new CardSpec { Name = "自检普通卡", ClassName = "UiCheckPlainTiming", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			ctPlainCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
			ctPlain.Cards.Add(ctPlainCard);
			string ctPlainSrc = CSharpCodeGen.CardSource(ctPlain, ctPlainCard, 0);
			Check("普通卡（没有「卡牌时机」）生成结果里没有钩子 override / CET:CardTiming / HookPlayerChoiceContext",
				!ctPlainSrc.Contains("AfterCardExhausted") && !ctPlainSrc.Contains("AfterFlush")
				&& !ctPlainSrc.Contains("CET:CardTiming") && !ctPlainSrc.Contains("HookPlayerChoiceContext"), "干净");
			// 校验器：子时机认不出来 / 用在非普通卡牌上 / 用了「打出的目标」/ 用了 X
			CharacterProfile badTiming = ProfileFactory.Sample();
			CardSpec badTimingCard = new CardSpec { Name = "自检坏时机", ClassName = "UiCheckBadTiming", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			badTimingCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self", Condition = new ConditionSpec { Kind = "CardTiming", Timing = "NotATiming" } });
			badTiming.Cards.Add(badTimingCard);
			Check("子时机认不出来 → 校验器报错",
				ProfileValidator.Validate(badTiming).Any((ValidationIssue i) => i.IsError && i.Message.Contains("子时机认不出来")), "拦住了");
			CharacterProfile badSide = ProfileFactory.Sample();
			CardSpec badSideCard = new CardSpec { Name = "自检时机打目标", ClassName = "UiCheckBadTimingSide", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
			badSideCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 8m, TargetSide = "Enemy", Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Exhausted" } });
			badSide.Cards.Add(badSideCard);
			Check("「卡牌时机」+「打出的目标」→ 报错（钩子里没有 cardPlay.Target，会空引用）",
				ProfileValidator.Validate(badSide).Any((ValidationIssue i) => i.IsError && i.Message.Contains("那个钩子里没有打出记录")), "拦住了");
			CharacterProfile badX = ProfileFactory.Sample();
			CardSpec badXCard = new CardSpec { Name = "自检时机X", ClassName = "UiCheckBadTimingX", CardType = "Skill", Rarity = "Common", Cost = 0, CostIsX = true, InCardPool = true };
			badXCard.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, AmountIsX = true, Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Exhausted" } });
			badX.Cards.Add(badXCard);
			Check("「卡牌时机」+ 数值 = X → 报错（那些钩子里没有打出时取的 X）",
				ProfileValidator.Validate(badX).Any((ValidationIssue i) => i.IsError && i.Message.Contains("没有它")), "拦住了");
			CharacterProfile badRelicTiming = ProfileFactory.Sample();
			badRelicTiming.Relics.Add(new RelicSpec
			{
				Name = "自检时机遗物", ClassName = "UiCheckTimingRelic", Rarity = "Common", Trigger = "CombatStart",
				Effects = { new EffectSpec { Kind = "Block", Amount = 5m, Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Exhausted" } } },
			});
			Check("遗物上选「卡牌时机」→ 报错（遗物没有「这张牌被消耗」这一说）",
				ProfileValidator.Validate(badRelicTiming).Any((ValidationIssue i) => i.IsError
					&& i.Message.Contains("卡牌时机") && i.Message.Contains("不能用在这里")), "拦住了");
			// 诅咒：也是卡（ForCard 那一关过得了），但它的效果写在 OnTurnEndInHand 里、没有这些卡牌钩子
			CharacterProfile badCurseTiming = ProfileFactory.Sample();
			CardSpec badCurseCard = new CardSpec { Name = "自检时机诅咒", ClassName = "UiCheckTimingCurse", CardType = "Skill", Rarity = "Curse", Cost = -1, InCardPool = false };
			badCurseCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self", Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Exhausted" } });
			badCurseTiming.Cards.Add(badCurseCard);
			Check("诅咒上选「卡牌时机」→ 报错（诅咒的效果写在「回合结束时在手上」，挂不上这些卡牌钩子）",
				ProfileValidator.Validate(badCurseTiming).Any((ValidationIssue i) => i.IsError && i.Message.Contains("只对**普通卡牌**有意义")), "拦住了");
			// 卡面描述：写成「当这张牌被消耗时，获得 4 点格挡。」（不是通用的「条件：…（不满足时…）」）
			CharacterProfile ctDesc = ProfileFactory.Sample();
			CardSpec ctDescCard = new CardSpec { Name = "自检时机描述", ClassName = "UiCheckTimingDesc", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			ctDescCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self", Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Exhausted" } });
			ctDescCard.Effects.Add(new EffectSpec { Kind = "Energy", Amount = 1m, TargetSide = "Self", Condition = new ConditionSpec { Kind = "CardTiming", Timing = "Retained" } });
			ctDesc.Cards.Add(ctDescCard);
			string ctDescJson = LocalizationGen.CardsJson(ctDesc);
			Check("卡面描述：「卡牌时机」写成「当这张牌被消耗时，…」（不是通用的「条件：…」）",
				ctDescJson.Contains("当这张牌被消耗时，获得 {Block:diff()} 点格挡")
				&& ctDescJson.Contains("当这张牌被保留时，获得 {Energy:diff()} 点能量")
				&& !ctDescJson.Contains("条件：当这张牌被消耗时"), "描述对");
			// 卡面描述那一条已经在上面单独用一张卡断言过了（见「当这张牌被消耗时，…」）
			// 生成 → 回读：6 个子时机都要原样回来
			string ctRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_timing_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile ctRound = ProfileFactory.Sample();
				ctRound.Paths.OutputDir = ctRoot;
				ctRound.Paths.VanillaProject = Profile.Paths.VanillaProject;
				ctRound.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec ctRoundCard = new CardSpec { Name = "自检时机往返", ClassName = "UiCheckTimingRound", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true, Retain = true };
				foreach (string timingId in new[] { "Exhausted", "Generated", "Retained", "Discarded", "Transformed", "GivenKeyword" })
					ctRoundCard.Effects.Add(new EffectSpec
					{
						Kind = "Block", Amount = 4m, TargetSide = "Self",
						Condition = new ConditionSpec { Kind = "CardTiming", Timing = timingId },
					});
				ctRound.Cards.Add(ctRoundCard);
				Check("（准备）「卡牌时机」的存档能生成工程", ModGenerator.Generate(ctRound).Success, ctRoot);
				var ctRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(ctRound));
				var ctBack = ctRec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckTimingRound");
				Check("回读：6 个子时机（被消耗 / 被生成 / 被保留 / 被丢弃 / 被变化 / 被给予自定义关键词）都原样回来",
					ctBack is not null
					&& new[] { "Exhausted", "Generated", "Retained", "Discarded", "Transformed", "GivenKeyword" }
						.All((string t) => ctBack.Effects.Any((EffectSpec e) => e.Condition is { Kind: "CardTiming" } c2 && c2.Timing == t)),
					ctBack is null ? "(没回读出来)" : string.Join(" / ", ctBack.Effects.Select((EffectSpec e) => e.Condition?.Kind + ":" + (e.Condition?.Timing ?? "-"))));
				Check("回读：带「卡牌时机」的卡没有认不出来的语句", !ctRec.HasUnparsed, ctRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(ctRoot)) Directory.Delete(ctRoot, true); } catch { }
			}

			// 生成 → 回读：本轮六件事的字段都要原样回来
			string roundRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_r30_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile r30Probe = ProfileFactory.Sample();
				r30Probe.Paths.OutputDir = roundRoot;
				r30Probe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				r30Probe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec r30Card = new CardSpec { Name = "自检往返", ClassName = "UiCheckRound30", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				r30Card.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 10m, TargetSide = "Enemy" });
				r30Card.Effects.Add(new EffectSpec { Kind = "MaxHp", Amount = 3m, Condition = new ConditionSpec { Kind = "Fatal" } });
				r30Card.Effects.Add(new EffectSpec { Kind = "TakeFromExhaust", Amount = 2m });
				r30Card.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 1m, ReplayTimes = 3, CardPick = "Random", SelectPile = "Exhaust" });
				r30Card.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 2m, CardPick = "Chosen", SelectPile = "Draw" });
				r30Card.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 0m, SpawnCardId = "Shiv" });
				r30Probe.Cards.Add(r30Card);
				Check("（准备）本轮六件事的存档能生成工程", ModGenerator.Generate(r30Probe).Success, roundRoot);
				var r30Rec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(r30Probe));
				var rec30 = r30Rec.Profile.Cards.FirstOrDefault((CardSpec x) => x.ClassName == "UiCheckRound30");
				Check("回读：消耗牌堆 / 重放次数 / 回合结束时自动打出（0 值那条被丢掉）都原样回来",
					rec30 is not null
					&& rec30.Effects.Any((EffectSpec e) => e.Kind == "TakeFromExhaust" && e.Amount == 2m)
					&& rec30.Effects.Any((EffectSpec e) => e.Kind == "ReplayCard" && e.ReplayTimes == 3 && e.SelectPile == "Exhaust")
					&& rec30.Effects.Any((EffectSpec e) => e.Kind == "TurnEndPlay" && e.Amount == 2m && e.SelectPile == "Draw" && e.CardPick == "Chosen")
					&& !rec30.Effects.Any((EffectSpec e) => e.Kind == "GenerateCard"),
					rec30 is null ? "(没回读出来)" : string.Join(" / ", rec30.Effects.Select((EffectSpec e) => $"{e.Kind} {e.Amount}")));
				Check("回读：「斩杀」条件认回 Fatal",
					rec30 is not null && rec30.Effects.Any((EffectSpec e) => e.Condition is { Kind: "Fatal" }),
					rec30 is null ? "?" : string.Join(" / ", rec30.Effects.Select((EffectSpec e) => e.Kind + ":" + (e.Condition?.Kind ?? "-"))));
				Check("回读没有认不出来的语句", !r30Rec.HasUnparsed, r30Rec.Unparsed.FirstOrDefault() ?? "全部认出来了");
			}
			finally
			{
				try { if (Directory.Exists(roundRoot)) Directory.Delete(roundRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：自动编号的英文类名 / 关键词键「每次构建都重排」导致引用失效、构建失败 =====
		{
			string stabRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_stab_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				string cls = Naming.From(ProfileFactory.Sample()).CharClass;
				// 第一次构建：留空类名的卡（甲 / 乙）+ 留空类名的召唤物 + 两个留空键的自定义关键词
				CharacterProfile stabA = ProfileFactory.Sample();
				stabA.Paths.OutputDir = stabRoot;
				stabA.Paths.VanillaProject = Profile.Paths.VanillaProject;
				stabA.Paths.GameDataDir = Profile.Paths.GameDataDir;
				stabA.Summons.Clear();
				stabA.Summons.Add(new SummonSpec { Name = "大运", ClassName = "", Enabled = true, Hp = 50 });
				stabA.CustomKeywords.Clear();
				stabA.CustomKeywords.Add(new CustomKeywordSpec { Key = "", Name = "命运" });
				stabA.CustomKeywords.Add(new CustomKeywordSpec { Key = "", Name = "回声" });
				CardSpec stabJia = new CardSpec { Name = "甲", ClassName = "", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				stabJia.KeywordIds.Add("KEYWORD_2");
				stabJia.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Fixed", SpawnCardId = cls + "Card4", SpawnTo = "Hand" });
				stabJia.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Keyword:KEYWORD_2", SpawnTo = "Hand" });
				stabJia.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, PetSummon = cls + "Pet" });
				CardSpec stabYi = new CardSpec { Name = "乙", ClassName = "", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				stabYi.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 1m, GivenKeyword = "KEYWORD_1", CardPick = "Chosen", SelectPile = "Hand" });
				stabA.Cards.Add(stabJia);
				stabA.Cards.Add(stabYi);
				string stabProject = ModGenerator.ProjectRootOf(stabA);
				var repA = NameStabilizer.Stabilize(stabA, stabProject);
				string jiaA = stabJia.ClassName, yiA = stabYi.ClassName;   // 自动编号出来的名字（甲 / 乙）
				Check("留空的英文类名 / 关键词键会被**固定**下来（不再每次按位置漂移）",
					repA.Changed && jiaA.StartsWith(cls + "Card") && yiA != jiaA
					&& stabA.Summons[0].ClassName == cls + "Pet"
					&& stabA.CustomKeywords[0].Key == "KEYWORD_1" && stabA.CustomKeywords[1].Key == "KEYWORD_2",
					$"甲={jiaA} 乙={yiA} 宠={stabA.Summons[0].ClassName} 键={stabA.CustomKeywords[0].Key}/{stabA.CustomKeywords[1].Key}");
				string? stabMap = NameStabilizer.MapPathOf(stabProject, Naming.From(stabA).ModId);
				Check("固定结果写进「类名表」（下一次构建靠它按名字把引用认回来）",
					stabMap is not null && File.Exists(stabMap)
					&& File.ReadAllText(stabMap).Contains("命运") && File.ReadAllText(stabMap).Contains("甲"), stabMap ?? "?");
				Check("类名表写在工程目录的**上一级**（不会被导出进 pck）",
					stabMap is not null && string.Equals(Path.GetDirectoryName(stabMap), Path.GetDirectoryName(stabProject), StringComparison.OrdinalIgnoreCase), "上一级");

				// 模拟用户的第二次编辑：① 前面插一张卡（自动编号整体后移）② 召唤物类名填成 BigJian
				// ③ 最前面插一个新关键词（后面那些键整体后移）—— 三处老引用都不动
				CharacterProfile stabB = ProfileFactory.Sample();
				stabB.Paths.OutputDir = stabRoot;
				stabB.Paths.VanillaProject = Profile.Paths.VanillaProject;
				stabB.Paths.GameDataDir = Profile.Paths.GameDataDir;
				stabB.Summons.Clear();
				stabB.Summons.Add(new SummonSpec { Name = "大运", ClassName = "BigJian", Enabled = true, Hp = 50 });
				stabB.CustomKeywords.Clear();
				stabB.CustomKeywords.Add(new CustomKeywordSpec { Key = "", Name = "新插的组" });
				stabB.CustomKeywords.Add(new CustomKeywordSpec { Key = "", Name = "命运" });
				stabB.CustomKeywords.Add(new CustomKeywordSpec { Key = "", Name = "回声" });
				CardSpec bJia = new CardSpec { Name = "甲", ClassName = "", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				bJia.KeywordIds.Add("KEYWORD_2");
				bJia.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Fixed", SpawnCardId = yiA, SpawnTo = "Hand" });
				bJia.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Keyword:KEYWORD_2", SpawnTo = "Hand" });
				bJia.Effects.Add(new EffectSpec { Kind = "SummonPet", Amount = 0m, PetSummon = cls + "Pet" });
				CardSpec bInsert = new CardSpec { Name = "插队卡", ClassName = "", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				CardSpec bYi = new CardSpec { Name = "乙", ClassName = "", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				bYi.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 1m, GivenKeyword = "KEYWORD_1", CardPick = "Chosen", SelectPile = "Hand" });
				stabB.Cards.Add(bJia);
				stabB.Cards.Add(bInsert);
				stabB.Cards.Add(bYi);
				var repB = NameStabilizer.Stabilize(stabB, ModGenerator.ProjectRootOf(stabB));
				Check("（前提）插队卡顶掉了乙原来的编号（乙被挤到了下一个号）",
					bInsert.ClassName == yiA && bYi.ClassName != yiA,
					$"插队卡={bInsert.ClassName}（乙原来是 {yiA}）；乙现在={bYi.ClassName}");
				Check("失效的**卡牌**引用按上一次构建的名字自动改回原来那张（不然会静默指到别的卡上）",
					bJia.Effects[0].SpawnCardId == bYi.ClassName && repB.Notes.Any(n => n.Contains("已自动改成")),
					$"目标卡={bJia.Effects[0].SpawnCardId}（应该改回乙 = {bYi.ClassName}）");
				Check("失效的**召唤物**引用也自动改回来（用户日志里那次「引用的召唤物 DaogePet 找不到」）",
					bJia.Effects[2].PetSummon == "BigJian", bJia.Effects[2].PetSummon ?? "?");
				Check("卡牌上勾的**关键词**、以及「范围限定 = 关键词那一组」都跟着键的重排改回来",
					bJia.KeywordIds[0] == "KEYWORD_3" && bJia.Effects[1].SpawnFilter == "Keyword:KEYWORD_3",
					$"卡上={bJia.KeywordIds[0]} 范围={bJia.Effects[1].SpawnFilter}");
				Check("「给予卡牌关键词」里存的键也改回来",
					bYi.Effects[0].GivenKeyword == "KEYWORD_2", bYi.Effects[0].GivenKeyword ?? "?");
				Check("修完之后校验器不再报「找不到」这类错（以前每次构建都卡在这里）",
					!ProfileValidator.Validate(stabB).Any((ValidationIssue i) => i.IsError
						&& (i.Message.Contains("找不到") || i.Message.Contains("不存在的自定义关键词"))),
					string.Join(" ｜ ", ProfileValidator.Validate(stabB).Where((ValidationIssue i) => i.IsError).Select((ValidationIssue i) => i.Message)));
				var stabGen = ModGenerator.Generate(stabB);
				Check("（准备）修完引用的存档能直接生成工程", stabGen.Success, stabRoot);
				string genCard = Path.Combine(stabGen.ProjectRoot, "cs", "Cards", bJia.ClassName + ".cs");
				Check("生成出来的代码引用的是修好之后的类名 / 召唤物",
					File.Exists(genCard) && File.ReadAllText(genCard).Contains("AddToCombatAndPreview<" + bYi.ClassName + ">")
					&& File.ReadAllText(genCard).Contains("BigJianCmd.Summon"), genCard);
				Check("校验器对宠物效果的「按生命值算」用的是修好之后的引用（不再是 __PETCMD__ 占位符）",
					!File.ReadAllText(genCard).Contains("__PETCMD__"), "没有占位符");
			}
			finally
			{
				try { if (Directory.Exists(stabRoot)) Directory.Delete(stabRoot, true); } catch { }
			}
		}
		// ===== 本轮新增：所有「获得类」数值支持负数 = 反向（获得力量 -3 = 失去 3 点力量）=====
		{
			Check("（配置）格挡 / 施加状态 的数值都允许填负数",
				EffectCatalog.FindKind("Block").Min <= -999
				&& EffectCatalog.FindKind("Block").Display.Contains("负数 = 失去")
				&& EffectCatalog.FindKind("ApplyPower").Min <= -99
				&& EffectCatalog.FindKind("ApplyPower").Display.Contains("负数 = 扣除"),
				$"Block {EffectCatalog.FindKind("Block").Min}【{EffectCatalog.FindKind("Block").Display}】 / ApplyPower {EffectCatalog.FindKind("ApplyPower").Min}");

			CharacterProfile negProbe = ProfileFactory.Sample();
			negProbe.VanillaPowerOverrides.Clear();
			CardSpec negCard = new CardSpec { Name = "反向探针", ClassName = "UiCheckNeg", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			negCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = -5m, TargetSide = "Self" });
			negCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "StrengthPower", Amount = -3m, TargetSide = "Self" });
			negCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = -5m, TargetSide = "Enemy" });
			negCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", PowerId = "PoisonPower", Amount = -2m, TargetSide = "Enemy", NextTurn = true });
			CardSpec negTemp = new CardSpec { Name = "临时负数探针", ClassName = "UiCheckNegTemp", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			negTemp.Effects.Add(new EffectSpec { Kind = "TempPower", PowerId = "StrengthPower", Amount = -3m, TargetSide = "Self" });
			negProbe.Cards.Add(negCard);
			negProbe.Cards.Add(negTemp);
			string negSrc = CSharpCodeGen.CardSource(negProbe, negCard, 0);
			Check("格挡填负数 → 生成 CreatureCmd.LoseBlock（本体 GainBlock 对非正数什么都不做）",
				negSrc.Contains("CreatureCmd.LoseBlock(choiceContext, base.Owner.Creature, System.Math.Abs(base.DynamicVars.Block.BaseValue), base.Owner.Creature)")
				&& !negSrc.Contains("CreatureCmd.GainBlock(base.Owner.Creature, base.DynamicVars.Block.BaseValue"), "LoseBlock");
			// ⚠ V0.2.139：力量属于本体**允许负层数**的 5 个状态（AllowNegative => true）→ 负数改成
			// 「照本体「尖啸」那套直接施加负值」；中毒不允许负层数 → 仍旧先取实例再 ModifyAmount 扣。
			Check("施加状态填负数 → 分两档：力量（本体允许负层数）直接施加 -3m（本体「尖啸」的写法，0 层也能扣成负的）；"
				+ "中毒（不允许负层数）先取目标身上那份实例再 PowerCmd.ModifyAmount 扣（本体 Apply 对负数会新建负层数状态）",
				negSrc.Contains("await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner.Creature, base.DynamicVars[\"StrengthPower\"].BaseValue, base.Owner.Creature, this);")
				&& !negSrc.Contains("GetPower<StrengthPower>")
				&& negSrc.Contains("PowerModel? __negPower = cardPlay.Target.GetPower<PoisonPower>();")
				&& !negSrc.Contains("await PowerCmd.Apply<PoisonPower>(choiceContext, cardPlay.Target, base.DynamicVars[\"PoisonPower\"].BaseValue"), "两档都对");
			string negJson = LocalizationGen.CardsJson(negProbe);
			Check("卡面描述写成「失去 / 扣除」而不是「获得 -5」",
				negJson.Contains("失去 5 点格挡。") && negJson.Contains("失去 3 层力量。") && negJson.Contains("扣除 5 层中毒。"), "描述对");
			var negIssues = ProfileValidator.Validate(negProbe);
			Check("校验器：施加状态「负数 + 下回合生效」这个组合会被拦（下回合那套只会加层数）",
				negIssues.Any((ValidationIssue x) => x.IsError && x.Message.Contains("填了负数（扣除层数）又勾了「下回合生效」")), "拦住了");
			string negTempSrc = CSharpCodeGen.CardSource(negProbe, negTemp, 0);
			var negTempIssues = ProfileValidator.Validate(negProbe);
			// ⚠ 这条以前是「填负数会被**拿**」—— 现在负数有意义了（临时减益：先扣层、到点加回来），
			// 改成提示。断言跟着改：不再有这条错误，而是有一条说清「失去 N 层、到点加回来」的提示。"
			Check("校验器：临时增益填负数不再被拦，改成一条说清会「失去 N 层、到点加回来」的提示",
				!negTempIssues.Any((ValidationIssue x) => x.IsError && x.Message.Contains("临时增益") && x.Message.Contains("负数"))
				&& negTempIssues.Any((ValidationIssue x) => !x.IsError && x.Message.Contains("失去") && x.Message.Contains("加回来")),
				string.Join(" | ", negTempIssues.Where((ValidationIssue x) => x.Message.Contains("临时增益")).Select((ValidationIssue x) => x.Level + ":" + x.Message.Substring(0, Math.Min(30, x.Message.Length)))));
			// 生成 → 回读：负数要原样带回来（回读靠标记行里的 Amount）
			string negRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_neg_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				negProbe.Paths.OutputDir = negRoot;
				negProbe.Paths.VanillaProject = Profile.Paths.VanillaProject;
				negProbe.Paths.GameDataDir = Profile.Paths.GameDataDir;
				// 上面两条会被校验器拦的配置先撤掉，才能生成工程
				negCard.Effects[3].NextTurn = false;
				negTemp.Effects[0].Amount = 3m;
				var negGen = ModGenerator.Generate(negProbe);
				Check("（准备）带负数的配置能生成工程", negGen.Success, negRoot);
				var negRec = ProjectRecovery.FromProject(negGen.ProjectRoot);
				CardSpec? backCard = negRec.Profile?.Cards.FirstOrDefault(c => c.Name == "反向探针");
				Check("回读把负数原样带回来（格挡 -5 / 力量 -3 / 中毒 -5）",
					backCard is not null
					&& backCard.Effects.Any(x => x.Kind == "Block" && x.Amount == -5m)
					&& backCard.Effects.Any(x => x.Kind == "ApplyPower" && x.PowerId == "StrengthPower" && x.Amount == -3m)
					&& backCard.Effects.Any(x => x.Kind == "ApplyPower" && x.PowerId == "PoisonPower" && x.Amount == -5m),
					backCard is null ? "没回读到卡" : string.Join(" / ", backCard.Effects.Select(x => x.Kind + ":" + x.Amount)));
			}
			finally
			{
				try { if (Directory.Exists(negRoot)) Directory.Delete(negRoot, true); } catch { }
			}
		}		// ===== 本轮新增：效果种类「翻倍目标身上的状态层数」=====
		{
			Check("（配置）有「翻倍状态层数」这个效果，数值 = 倍数（0 = 不生效，2 = 翻倍）",
				EffectCatalog.FindKind("DoublePower") is not null
				&& EffectCatalog.FindKind("DoublePower").Min == 0 && EffectCatalog.FindKind("DoublePower").Max == 5
				&& EffectCatalog.FindKind("DoublePower").Display.Contains("翻倍"),
				EffectCatalog.FindKind("DoublePower").Display);
			CharacterProfile dblProbe = ProfileFactory.Sample();
			dblProbe.VanillaPowerOverrides.Clear();
			CardSpec dblCard = new CardSpec { Name = "翻倍探针", ClassName = "UiCheckDbl", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			dblCard.Effects.Add(new EffectSpec { Kind = "DoublePower", Amount = 2m, PowerId = "PoisonPower", TargetSide = "Enemy" });
			dblCard.Effects.Add(new EffectSpec { Kind = "DoublePower", Amount = 3m, PowerId = "StrengthPower", TargetSide = "Self" });
			dblProbe.Cards.Add(dblCard);
			string dblSrc = CSharpCodeGen.CardSource(dblProbe, dblCard, 0);
			Check("生成：先取目标身上那份状态实例，再 ModifyAmount(现有层数 ×(倍数-1))（本体没有「翻倍」API）",
				dblSrc.Contains("PowerModel? __dblPower = cardPlay.Target.GetPower<PoisonPower>();")
				&& dblSrc.Contains("await PowerCmd.ModifyAmount(choiceContext, __dblPower, __dblPower.Amount * 1, base.Owner.Creature, this);")
				&& dblSrc.Contains("__dblPower = base.Owner.Creature.GetPower<StrengthPower>();")
				&& dblSrc.Contains("__dblPower.Amount * 2"), "生成对");
			Check("标记行带上「哪一个状态 / 打谁」（回读要用）",
				dblSrc.Contains("CET:Effect=DoublePower") && dblSrc.Contains("CET:Power=\"PoisonPower\" CET:Side=Enemy")
				&& dblSrc.Contains("CET:Side=Self"), "标记在");
			string dblJson = LocalizationGen.CardsJson(dblProbe);
