					CSharpCodeGen.CardSource(Profile, tgCard, 0).Contains("Cards.Where(c => c.Id == this.Id)"), "变化自己");
				// 锻造图（卡牌）：同样要生成本张牌自己的删除
				CardSpec fgCard = new CardSpec { Name = "锻造自删", ClassName = "UiCheckForgeSelfRemove", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				var fgGraph = new ForgeGraphSpec();
				var fgTrig = new ForgeNodeSpec { Kind = "Trigger" };
				fgTrig.SetField("Timing", "CardPlayed");
				var fgEff = new ForgeNodeSpec { Kind = "Effect" };
				fgEff.SetField("Effect", "RemoveCardGlobal");
				fgEff.SetField("Amount", "0");
				fgEff.SetField("Pick", "Chosen");
				fgGraph.Nodes.AddRange(new[] { fgTrig, fgEff });
				fgGraph.Links.Add(new ForgeLinkSpec { From = fgTrig.Id, To = fgEff.Id });
				fgCard.ForgeGraph = fgGraph;
				Profile.Cards.Add(fgCard);
				string fgSrc = ForgeGraphGen.CardHooks(Profile, fgCard, isUpgraded: false);
				Profile.Cards.Remove(fgCard);
				Check("V0.2.205：卡牌的锻造图里「删除牌 = 0」也生成「删掉这张牌自己」（带 c.Id == this.Id）",
					fgSrc.Contains("c.IsRemovable && c.Id == this.Id"), "锻造图也对");
				// 遗物 / 药水 / 状态的布上没有「这张牌」→ 退回老行为（0 当 1 张），并在代码里写清原因（不静默）
				CardSpec fgRelicCard = new CardSpec { Name = "锻造自删（遗物布）", ClassName = "UiCheckForgeSelfRemoveRelic", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				var relicGraph = new ForgeGraphSpec();
				var rTrig = new ForgeNodeSpec { Kind = "Trigger" };
				rTrig.SetField("Timing", "CardPlayed");
				var rEff = new ForgeNodeSpec { Kind = "Effect" };
				rEff.SetField("Effect", "RemoveCardGlobal");
				rEff.SetField("Amount", "0");
				relicGraph.Nodes.AddRange(new[] { rTrig, rEff });
				relicGraph.Links.Add(new ForgeLinkSpec { From = rTrig.Id, To = rEff.Id });
				var selfRemoveRelic = new RelicSpec { Name = "自检遗物", ClassName = "UiCheckSelfRemoveRelic", Triggers = { new RelicTriggerSpec { Kind = "CombatStart" } }, ForgeGraph = relicGraph };
				string relicSrc = ForgeGraphGen.RelicHooks(Profile, selfRemoveRelic);
				Check("V0.2.205：（对照）同一个「删除牌 = 0」放在遗物 / 药水的布上：没有「这张牌」→ 写注释说明按 1 张处理",
					relicSrc.Contains("没有「这张牌」"), relicSrc.Contains("没有「这张牌」") ? "写清了" : "(没写)");
				// 卡面 / 列表也要说清「0 = 这张牌自己」
				CharacterProfile rmLocProfile = ProfileFactory.Sample();
				rmLocProfile.Cards.Add(rmCard);
				Check("V0.2.205：卡面描述写「把这张牌从牌组里删掉」、列表行尾写「数值 0 = 这张牌自己」",
					LocalizationGen.CardsJson(rmLocProfile).Contains("把[gold]这张牌[/gold]从牌组里删掉")
					&& rmSelf.Display.Contains("这张牌自己"), rmSelf.Display);
			}

			// ===== V0.2.206（用户报「打出后，从指定组中抽 10 张选 1 张 → 展示了所有牌、生成不出牌」）=====
			{
				CardSpec pickAllCard = new CardSpec { Name = "自己挑整组", ClassName = "UiCheckGenPickAll", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				pickAllCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnChosen = true });
				string pickAllSrc = CSharpCodeGen.CardSource(Profile, pickAllCard, 0);
				Check("V0.2.206：「自己挑」挑中的是规范模型 → 先 CreateCard 建实例再入堆（以前直接塞规范模型 → 运行时 CanonicalModelException）",
					pickAllSrc.Contains("CombatState.CreateCard(__picked, base.Owner)")
					&& pickAllSrc.Contains("AddGeneratedCardToCombat(__pickedMade,")
					&& !pickAllSrc.Contains("AddGeneratedCardToCombat(__picked,"),
					pickAllSrc.Contains("__pickedMade") ? "先建实例" : "(还是直接塞规范模型)");
				CardSpec pickMCard = new CardSpec { Name = "自己挑10选1", ClassName = "UiCheckGenPickM", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				pickMCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnChosen = true, SpawnChoice = 10m });
				string pickMSrc = CSharpCodeGen.CardSource(Profile, pickMCard, 0);
				Check("V0.2.206：勾「自己挑」+「多选1 = 10」→ 真的先随机抽 10 张当候选（不再把整组牌全列出来）",
					pickMSrc.Contains("GetDistinctForCombat(base.Owner, __genPool, 10,")
					&& !pickMSrc.Contains("__chosenCand"),
					pickMSrc.Contains("__genPool, 10,") ? "抽 10 张候选" : "(还是整组)");
				Check("V0.2.206：（对照）只勾「自己挑」、多选1 = 1 → 仍然是「候选 = 整组（最多 60）」",
					pickAllSrc.Contains("__chosenCand = __genPool.Take(60)"), "整组候选");
			}

			// ② 生成的候选池**真的**被过滤（把生成文本钉死）
			CharacterProfile csProbe = ProfileFactory.Sample();
			CardSpec csRandom = new CardSpec { Name = "自检范围随机", ClassName = "UiCheckScopeRandom", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csRandom.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csRandom.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Random", SelectPile = "Draw", SpawnFilter = "Skill" });
			csRandom.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csRandom.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csRandom.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csRandom.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csRandom.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 1m, CardPick = "Random", SelectPile = "Hand", GivenKeyword = "Retain", SpawnFilter = "Attack" });
			csProbe.Cards.Add(csRandom);
			string csRandomSrc = CSharpCodeGen.CardSource(csProbe, csRandom, 0);
			Check("随机的那些：候选池就是「那一摞的牌 .Where(范围)」（消耗 / 丢弃 / 升级 / 复制 / 重放 / 回合结束 / 给关键词 七处都在）",
				csRandomSrc.Contains("NextItem(PileType.Hand.GetPile(base.Owner).Cards.Where(c => c.Type == CardType.Attack))")
				&& csRandomSrc.Contains("NextItem(PileType.Draw.GetPile(base.Owner).Cards.Where(c => c.Type == CardType.Skill))")
				&& csRandomSrc.Contains("NextItem(PileType.Hand.GetPile(base.Owner).Cards.Where(c => (c.IsUpgradable) && (c.Type == CardType.Attack)))")
				&& csRandomSrc.Contains("TakeRandom(PileType.Hand.GetPile(base.Owner).Cards.Where(c => c.Type == CardType.Attack), 1,"),
				"候选池被过滤了");
			Check("重放卡牌：范围界定和它本来就有的「能重放」条件 && 到一起（不是覆盖掉）",
				csRandomSrc.Contains(".Where(c => (!c.Keywords.Contains(CardKeyword.Unplayable) && c.GetEnchantedReplayCount() < 1) && (c.Type == CardType.Attack))"),
				"两个条件都在");

			CardSpec csChosen = new CardSpec { Name = "自检范围自己选", ClassName = "UiCheckScopeChosen", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csChosen.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
			csChosen.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
			csChosen.Effects.Add(new EffectSpec { Kind = "TakeFromDraw", Amount = 2m, SpawnFilter = "Attack" });
			csChosen.Effects.Add(new EffectSpec { Kind = "TakeFromExhaust", Amount = 2m, SpawnFilter = "Attack" });
			csChosen.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 3m, SpawnFilter = "Attack" });
			csProbe.Cards.Add(csChosen);
			string csChosenSrc = CSharpCodeGen.CardSource(csProbe, csChosen, 0);
			Check("自己选的那些：谓词当 CardSelectCmd 的 filter 传进去（消耗走 FromHand / 拿牌走 FromCombatPile）",
				csChosenSrc.Contains("prefs: new CardSelectorPrefs(CardSelectorPrefs.ExhaustSelectionPrompt, 2), filter: c => c.Type == CardType.Attack, source: this)")
				&& csChosenSrc.Contains("new CardSelectorPrefs(CardSelectorPrefs.DiscardSelectionPrompt, 2), c => c.Type == CardType.Attack, this)")
				&& csChosenSrc.Contains("new CardSelectorPrefs(base.SelectionScreenPrompt, 2), c => c.Type == CardType.Attack))"),
				"filter 传进去了");
			Check("预见：先取「抽牌堆顶 N 张」，再在那一小撮里按范围筛（只丢符合范围的）",
				csChosenSrc.Contains("var __scryTop = PileType.Draw.GetPile(base.Owner).Cards.Take(3).Where(c => c.Type == CardType.Attack).ToList();"),
				"先取顶 N 张再筛");
			Check("范围界定也写进了生成期的标记行（回读靠它），而且带着效果种类（不会串到别的效果上）",
				csChosenSrc.Contains("CET:SpawnFilter=Attack CET:SpawnChoice=1") && csChosenSrc.Contains("CET:Kind=Scry")
				&& csChosenSrc.Contains("CET:Kind=ExhaustCard"), "标记在");

			// ③ 范围为空时：生成文本与旧版完全一致（回归）
			CharacterProfile csOld = ProfileFactory.Sample();
			CardSpec csOldCard = new CardSpec { Name = "自检无范围", ClassName = "UiCheckScopeOff", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csOldCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Hand" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Hand" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "TakeFromDraw", Amount = 2m });
			csOldCard.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 3m });
			csOldCard.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 1m, CardPick = "Random", SelectPile = "Hand", GivenKeyword = "Retain" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 1m, CardPick = "Random", SelectPile = "Hand" });
			csOldCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand" });
			csOld.Cards.Add(csOldCard);
			string csOldSrc = CSharpCodeGen.CardSource(csOld, csOldCard, 0);
			var csOldPins = new List<KeyValuePair<string, bool>>
			{
				new("没有标记行", !csOldSrc.Contains("CET:SpawnPick=")),
				new("没有范围过滤", !csOldSrc.Contains(".Where(c => c.Type == CardType")),
				new("丢弃（自己选）", csOldSrc.Contains("new CardSelectorPrefs(CardSelectorPrefs.DiscardSelectionPrompt, 2), null, this)")),
				new("升级（自己选）", csOldSrc.Contains("new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, 1), c => c.IsUpgradable, this)")),
				new("预见", csOldSrc.Contains("var __scryTop = PileType.Draw.GetPile(base.Owner).Cards.Take(3).ToList();")),
				new("消耗（随机）", csOldSrc.Contains("CardModel? pick = base.Owner.RunState.Rng.CombatCardSelection.NextItem(PileType.Hand.GetPile(base.Owner).Cards);")),
				new("从抽牌堆拿牌", csOldSrc.Contains("new CardSelectorPrefs(base.SelectionScreenPrompt, 2))).ToList();")),
				new("复制（随机）", csOldSrc.Contains("CardModel? __src = base.Owner.RunState.Rng.CombatCardSelection.NextItem(PileType.Hand.GetPile(base.Owner).Cards);")),
				new("回合结束自动打出（随机）", csOldSrc.Contains("TakeRandom(PileType.Hand.GetPile(base.Owner).Cards, 1,")),
				new("重放（自己选）", csOldSrc.Contains(".Where(c => !c.Keywords.Contains(CardKeyword.Unplayable) && c.GetEnchantedReplayCount() < 1)")),
				new("给关键词（随机）", csOldSrc.Contains("CardModel? __kwCard = base.Owner.RunState.Rng.CombatCardSelection.NextItem(PileType.Hand.GetPile(base.Owner).Cards);")),
			};
			// 「生成 / 变化」那套的标记行长什么样（回归用：不许因为需求 ③ 多出 CET:Kind）
			CharacterProfile csGenProbe = ProfileFactory.Sample();
			CardSpec csGenCard = new CardSpec { Name = "自检生成标记", ClassName = "UiCheckScopeGenMark", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csGenCard.Effects.Add(new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnTo = "Hand" });
			csGenProbe.Cards.Add(csGenCard);
			string csGenOldMarker = CSharpCodeGen.CardSource(csGenProbe, csGenCard, 0)
				.Split('\n').FirstOrDefault((string l) => l.Contains("CET:SpawnPick=")) ?? "";
			Check("（回归）范围为空时：一句新语句都不生成、标记行也不写 —— 与旧版逐字一致",
				csOldPins.All((KeyValuePair<string, bool> kv) => kv.Value) && csOldSrc.Contains("filter: null, source: this)"),
				string.Join(" ｜ ", csOldPins.Where((KeyValuePair<string, bool> kv) => !kv.Value).Select((KeyValuePair<string, bool> kv) => "缺:" + kv.Key))
					+ (csOldSrc.Contains("filter: null, source: this)") ? "" : " ｜ 缺:消耗（自己选）"));
			Check("（回归）「生成 / 变化卡牌」的标记行没有被改动（没有多加 CET:Kind）",
				csGenOldMarker.Length > 0 && csGenOldMarker.Contains("CET:SpawnFilter=Attack")
				&& !csGenOldMarker.Contains("CET:Kind"), csGenOldMarker.Trim());

			// ④ 卡面描述写了范围
			CharacterProfile csDesc = ProfileFactory.Sample();
			CardSpec csDescCard = new CardSpec { Name = "自检范围描述", ClassName = "UiCheckScopeDesc", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csDescCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Random", SelectPile = "Draw", SpawnFilter = "Skill" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "TakeFromDiscard", Amount = 2m, SpawnFilter = "Power" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 2m, SpawnFilter = "Curse" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 1m, CardPick = "Random", SelectPile = "Hand", GivenKeyword = "Retain", SpawnFilter = "Status" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csDescCard.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
			csDesc.Cards.Add(csDescCard);
			string csDescJson = LocalizationGen.CardsJson(csDesc);
			Check("卡面描述写清了范围（例：「…1 张手牌（只限攻击牌）。」）",
				csDescJson.Contains("张手牌（只限攻击牌）。")
				&& csDescJson.Contains("（只限技能牌）。")
				&& csDescJson.Contains("（只限能力牌）。")
				&& csDescJson.Contains("（只限诅咒牌）。")
				&& csDescJson.Contains("（只限状态牌）。"),
				csDescJson.Split('\n').FirstOrDefault((string l) => l.Contains("UI_CHECK_SCOPE_DESC.description")) ?? "(没找到)");
			// 空范围时描述一个字都不多
			CharacterProfile csDescOff = ProfileFactory.Sample();
			CardSpec csDescOffCard = new CardSpec { Name = "自检范围描述关", ClassName = "UiCheckScopeDescOff", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csDescOffCard.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand" });
			csDescOff.Cards.Add(csDescOffCard);
			Check("（回归）范围为空时描述里没有「（只限…牌）」那句",
				!LocalizationGen.CardsJson(csDescOff).Contains("只限"), "描述与旧版一致");

			// ⑤ 三个上下文（卡牌 / 遗物触发 / 药水）都接了
			CharacterProfile csCtx = ProfileFactory.Sample();
			var csRelic = new RelicSpec
			{
				Name = "自检范围遗物", ClassName = "UiCheckScopeRelic", Rarity = "Common", Trigger = "PlayerTurnStart",
				Effects =
				{
					new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" },
					new EffectSpec { Kind = "TakeFromExhaust", Amount = 1m, SpawnFilter = "Attack" },
				},
			};
			csCtx.Relics.Add(csRelic);
			var csPotion = new PotionSpec
			{
				Name = "自检范围药水", ClassName = "UiCheckScopePotion", Rarity = "Common", TargetType = "Self",
				Effects =
				{
					new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" },
					new EffectSpec { Kind = "Scry", Amount = 2m, SpawnFilter = "Attack" },
				},
			};
			csCtx.Potions.Add(csPotion);
			string csRelicSrc = CSharpCodeGen.RelicSource(csCtx, csRelic, csCtx.Relics.IndexOf(csRelic));
			string csPotionSrc = CSharpCodeGen.PotionSource(csCtx, csPotion, csCtx.Potions.IndexOf(csPotion));
			Check("遗物触发那一路也接上了（含「从消耗牌堆拿牌到手牌」）",
				csRelicSrc.Contains("NextItem(PileType.Hand.GetPile(base.Owner).Cards.Where(c => c.Type == CardType.Attack))")
				&& csRelicSrc.Contains("FromCombatPile(choiceContext, PileType.Exhaust.GetPile(base.Owner), base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, 1), c => c.Type == CardType.Attack)"),
				"遗物两处都对");
			Check("药水那一路也接上了（升级 + 预见）",
				csPotionSrc.Contains("c => (c.IsUpgradable) && (c.Type == CardType.Attack), this)")
				&& csPotionSrc.Contains("PileType.Draw.GetPile(base.Owner).Cards.Take(2).Where(c => c.Type == CardType.Attack)"),
				"药水两处都对");

			// ⑥ 空组报错 + 「范围 + 取牌方式」的说明
			CharacterProfile csEmpty = ProfileFactory.Sample();
			csEmpty.CustomKeywords.Clear();
			csEmpty.CustomKeywords.Add(new CustomKeywordSpec { Key = "VOID", Name = "虚空" });
			CardSpec csEmptyCard = new CardSpec { Name = "自检范围空组", ClassName = "UiCheckScopeEmpty", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csEmptyCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Keyword:VOID" });
			csEmpty.Cards.Add(csEmptyCard);
			Check("范围界定选了自定义关键词分组但那一组是空的 → 报错拦住",
				ProfileValidator.Validate(csEmpty).Any((ValidationIssue x) => x.IsError && x.Message.Contains("这一组是空的")),
				"拦住了");
			CharacterProfile csNote = ProfileFactory.Sample();
			CardSpec csNoteCard = new CardSpec { Name = "自检范围说明", ClassName = "UiCheckScopeNote", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csNoteCard.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
			csNote.Cards.Add(csNoteCard);
			var csNotes = ProfileValidator.Validate(csNote);
			Check("校验器给一条「范围 + 取牌方式」的说明（随机 / 自己选，并说清范围里没牌就什么都不做）",
				csNotes.Any((ValidationIssue x) => !x.IsError && x.Message.Contains("范围界定") && x.Message.Contains("取牌方式 = 随机")
					&& x.Message.Contains("不会弹空选牌界面")),
				string.Join(" ｜ ", csNotes.Where((ValidationIssue x) => x.Message.Contains("范围界定")).Select((ValidationIssue x) => x.Message)));
			// 需求 ⑥ 以前这条是「范围界定用在自定义状态触发器里 → 报错拦住」。现在放开了，
			// 所以这里改成钉住**两条边界**：
			//   · 「生成卡牌 + 范围限定」在状态触发器里能配（不再报错）—— 详查见上面「⑥ 状态触发器也支持」那一段；
			//   · 但「给予卡牌关键词」这种**本身就不支持**放进状态触发器的效果，照样拦住（拦的是效果种类，不是范围）。
			// 用 ProfileFactory.Sample() 当底（空存档会先被「卡池至少 3 张」这类通用校验拦下，测不到我们关心的那两条）。
			CharacterProfile scopeProbe = ProfileFactory.Sample();
			var scopePowerOkSpec = new CustomPowerSpec
			{
				Name = "自检范围状态", Enabled = true,
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "GenerateCard", Amount = 1m, SpawnPick = "Random", SpawnFilter = "Attack", SpawnTo = "Hand" } } } },
			};
			scopeProbe.CustomPowers.Add(scopePowerOkSpec);
			// 只断言「没有和范围 / 按范围随机有关的那条错误」：ProfileFactory.Sample() 自带的路径 / 美术类错误
			// 和这一条无关（真实回归由 forge --build 探针兜底：真被拦下来的话校验直接中止生成）。
			var scopePowerOk = ProfileValidator.Validate(scopeProbe);
			Check("「范围界定 / 按范围随机」用在自定义状态的触发器里 → 不再报错（需求 ⑥ 放开）",
				!scopePowerOk.Any((ValidationIssue x) => x.IsError
					&& (x.Message.Contains("按范围随机") || x.Message.Contains("范围界定"))),
				string.Join(" ｜ ", scopePowerOk.Where((ValidationIssue x) => x.IsError).Select((ValidationIssue x) => x.Message)));
			CharacterProfile scopeProbe2 = ProfileFactory.Sample();
			scopeProbe2.CustomPowers.Add(new CustomPowerSpec
			{
				Name = "自检范围状态", Enabled = true,
				Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "GiveKeyword", Amount = 1m, GivenKeyword = "Retain", SpawnFilter = "Attack" } } } },
			});
			// ⚠「给予卡牌关键词」不属于「需要打出这张牌的上下文」（它只是状态那条链还没实现），
			// 所以文案分档之后它走的是「生成端还没实现」那一档 —— 拦是一定要拦住的，断言匹配这一种说法。"
			Check("但「给予卡牌关键词」（本就不支持放进状态触发器）照样拦住 —— 拦的是效果种类，不是范围",
				ProfileValidator.Validate(scopeProbe2).Any((ValidationIssue x) => x.IsError
					&& x.Message.Contains("给予卡牌关键词")
					&& (x.Message.Contains("还没给") || x.Message.Contains("卡牌上下文"))), "拦住了");
			Check("用了范围界定但那条效果种类不支持（例如「造成伤害」）→ 给一句提示，别让人以为配了会有用",
				ProfileValidator.Validate(new CharacterProfile
				{
					Cards = { new CardSpec { Name = "自检范围无效", ClassName = "UiCheckScopeBad", CardType = "Attack", Rarity = "Common", Cost = 1,
						Effects = { new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", SpawnFilter = "Attack" } } } },
				}).Any((ValidationIssue x) => !x.IsError && x.Message.Contains("范围界定")), "提示了");

			// ⑦ 生成 → 回读：范围界定要原样回来
			string csRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_cardscope_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile csGen = ProfileFactory.Sample();
				csGen.CustomKeywords.Clear();
				csGen.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命运" });
				csGen.Paths.OutputDir = csRoot;
				csGen.Paths.VanillaProject = Profile.Paths.VanillaProject;
				csGen.Paths.GameDataDir = Profile.Paths.GameDataDir;
				CardSpec csFate = new CardSpec { Name = "自检命运牌", ClassName = "UiCheckScopeFate", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				csFate.KeywordIds.Add("FATE");
				CardSpec csRound = new CardSpec { Name = "自检范围往返", ClassName = "UiCheckScopeRound", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				csRound.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "DiscardCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Draw", SpawnFilter = "Keyword:FATE" });
				csRound.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "GiveKeyword", Amount = 1m, CardPick = "Random", SelectPile = "Hand", GivenKeyword = "Retain", SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "CopyCard", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "ReplayCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand", SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "TurnEndPlay", Amount = 1m, CardPick = "Chosen", SelectPile = "Hand", SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "TakeFromDraw", Amount = 1m, SpawnFilter = "Attack" });
				csRound.Effects.Add(new EffectSpec { Kind = "TakeFromExhaust", Amount = 1m, SpawnFilter = "Skill" });
				csRound.Effects.Add(new EffectSpec { Kind = "Scry", Amount = 2m, SpawnFilter = "Attack" });
				// 这两条是「回读老毛病」的守门用例（和范围界定无关，但都是这几个种类上的坑）：
				//   · 「自己选消耗」生成的是**单行** foreach，以前回读会掉这条效果 + 多一行「没认出来」；
				//   · 「随机升级」的 `if (pick is null) break;` 会把跳过开关关掉，
				//     紧跟着的 CardCmd.Upgrade(pick) 被当成「升级牌组（全局）」多回读一条。
				csRound.Effects.Add(new EffectSpec { Kind = "ExhaustCard", Amount = 2m, CardPick = "Chosen", SelectPile = "Hand" });
				csRound.Effects.Add(new EffectSpec { Kind = "UpgradeCard", Amount = 1m, CardPick = "Random", SelectPile = "Hand" });
				csGen.Cards.Add(csFate);
				csGen.Cards.Add(csRound);
				Check("（准备）带范围界定的存档能生成工程", ModGenerator.Generate(csGen).Success, csRoot);
				var csRec = ProjectRecovery.FromProject(ModGenerator.ProjectRootOf(csGen));
				var csRecCard = csRec.Profile.Cards.FirstOrDefault((CardSpec c) => c.ClassName == "UiCheckScopeRound");
				List<EffectSpec> csRecFx = csRecCard is null ? new List<EffectSpec>() : csRecCard.Effects.ToList();
				Check("回读：10 条选牌类效果的范围界定都原样回来了（含自定义关键词那一组）",
					csRecFx.Count == 12
					&& csRecFx[0].Kind == "ExhaustCard" && csRecFx[0].SpawnFilter == "Attack"
					&& csRecFx[1].Kind == "DiscardCard" && csRecFx[1].SpawnFilter == "Keyword:FATE"
					&& csRecFx[2].Kind == "UpgradeCard" && csRecFx[2].SpawnFilter == "Attack"
					&& csRecFx[3].Kind == "GiveKeyword" && csRecFx[3].SpawnFilter == "Attack"
					&& csRecFx[4].Kind == "CopyCard" && csRecFx[4].SpawnFilter == "Attack"
					&& csRecFx[5].Kind == "ReplayCard" && csRecFx[5].SpawnFilter == "Attack"
					&& csRecFx[6].Kind == "TurnEndPlay" && csRecFx[6].SpawnFilter == "Attack"
					&& csRecFx[7].Kind == "TakeFromDraw" && csRecFx[7].SpawnFilter == "Attack"
					&& csRecFx[8].Kind == "TakeFromExhaust" && csRecFx[8].SpawnFilter == "Skill"
					&& csRecFx[9].Kind == "Scry" && csRecFx[9].SpawnFilter == "Attack",
					string.Join(" · ", csRecFx.Select((EffectSpec x) => x.Kind + "/" + (x.SpawnFilter.Length == 0 ? "-" : x.SpawnFilter))));
				Check("回读：「自己选消耗」的单行 foreach 也认得出来（以前会掉这条效果 + 多一行「没认出来」）",
					csRecFx[10].Kind == "ExhaustCard" && csRecFx[10].CardPick == "Chosen" && csRecFx[10].Amount == 2m,
					$"{csRecFx[10].Kind}/{csRecFx[10].CardPick}/{csRecFx[10].Amount}");
				Check("回读：「随机升级手牌」不再被当成「升级牌组（全局）」多回读一条",
					csRecFx[11].Kind == "UpgradeCard" && csRecFx[11].CardPick == "Random"
					&& !csRecFx.Any((EffectSpec x) => x.Kind == "UpgradeCardGlobal"),
					string.Join(" · ", csRecFx.Select((EffectSpec x) => x.Kind)));
				Check("回读没有认不出来的语句", !csRec.HasUnparsed, csRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				Check("回读兼容：标记行里没有 CET:Kind 的老工程也照旧配范围（withKind 默认 false，生成 / 变化那条路没变）",
					csGenOldMarker.Length > 0 && !csGenOldMarker.Contains("CET:Kind")
					&& csChosenSrc.Contains("CET:Kind=Scry"),
					"两种写法都在");
			}
			finally
			{
				try { if (Directory.Exists(csRoot)) Directory.Delete(csRoot, true); } catch { }
				RefreshCustomKeywordRegistry();
			}

			// ⑧ 界面：选到这些效果时「范围界定」那一行真的出现（用户报过「找不到在哪限定范围」）
			DependencyObject csUiRoot = SelectTabRoot("卡牌");
			CardSpec csUiCard = new CardSpec { Name = "自检范围界面", ClassName = "UiCheckScopeUi", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			csUiCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
			Profile.Cards.Add(csUiCard);
			CardList.SelectedItem = csUiCard;
			CardEffectList.SelectedIndex = 0;
			UpdateLayout();
			Check("不是选牌类效果时界面上没有「范围界定」那一行",
				!VisibleTextsIn(csUiRoot).Any((string t) => t.Contains("范围界定（哪些牌能选）")), "没出现");
			csUiCard.Effects[0].Kind = "ExhaustCard";
			csUiCard.Effects[0].Amount = 1m;
			UpdateLayout();
			Check("换成「消耗卡牌」后「范围界定（哪些牌能选）」那一行就出现了",
				VisibleTextsIn(csUiRoot).Any((string t) => t.Contains("范围界定（哪些牌能选）")), "在");
			csUiCard.Effects[0].CardPick = "Chosen";
			UpdateLayout();
			Check("「自己选」那一档也一样有（范围界定不是只在随机档才出现 —— 历史上就报过找不到入口）",
				VisibleTextsIn(csUiRoot).Any((string t) => t.Contains("范围界定（哪些牌能选）")), "在");
			csUiCard.Effects[0].Kind = "TurnEndPlay";
			csUiCard.Effects[0].Amount = 0m;
			UpdateLayout();
			Check("数值 0 = 这张牌自己那一档**也照旧显示**「范围界定」（用户报过「怎么不能填范围了」：按数值藏行会让人没法填）",
				VisibleTextsIn(csUiRoot).Any((string t) => t.Contains("范围界定（哪些牌能选）")), "显示了");
			Profile.Cards.Remove(csUiCard);
			CardList.SelectedItem = Profile.Cards.FirstOrDefault();     // V0.2.140：用对象选（列表里有空槽行）
			UpdateLayout();
			Check("（收尾）自检加的那张范围界定卡已清掉", !Profile.Cards.Contains(csUiCard));

			// ⑨ 界面：刮削的「条件 / 操作」那两行只在选到「刮削」时出现
			//（用户要求：别在别的效果种类上也占着位置 —— 条件那一栏还带着一串自定义关键词分组）
			CardSpec scrapeUiCard = new CardSpec { Name = "自检刮削界面", ClassName = "UiCheckScrapeUi", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			scrapeUiCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy" });
			Profile.Cards.Add(scrapeUiCard);
			CardList.SelectedItem = scrapeUiCard;
			CardEffectList.SelectedIndex = 0;
			UpdateLayout();
			Check("不是「刮削」时界面上没有「其中符合条件的牌 / 执行」那两行",
				!VisibleTextsIn(csUiRoot).Any((string t) => t.Contains("其中符合条件的牌"))
				&& !VisibleTextsIn(csUiRoot).Any((string t) => t == "执行"), "没出现");
			scrapeUiCard.Effects[0].Kind = "ScrapeDraw";
			scrapeUiCard.Effects[0].Amount = 3m;
			UpdateLayout();
			Check("换成「刮削」后那两行出现了（并且条件下拉的候选里第一条是「非 0 费」、操作第一条是「丢弃」）",
				VisibleTextsIn(csUiRoot).Any((string t) => t.Contains("其中符合条件的牌"))
				&& VisibleTextsIn(csUiRoot).Any((string t) => t == "执行")
				&& ScrapeConds.Count > 1 && ScrapeConds[0].Id == "NonZeroCost"
				&& ScrapeOps.Count == 3 && ScrapeOps[0].Id == "Discard", "在");
			// 效果列表里那行文案也要说清「抽 N 张 → 对什么条件的牌做什么」，不能还写着老的「丢弃所有非 0 费」
			Check("效果列表那句写的是「抽 N 张 → 对其中「条件」的牌操作」（默认档在列表里也说得清）",
				scrapeUiCard.Effects[0].Display.Contains("对其中「非 0 费」的牌丢弃"), scrapeUiCard.Effects[0].Display);
			Profile.Cards.Remove(scrapeUiCard);
			CardList.SelectedItem = Profile.Cards.FirstOrDefault();     // V0.2.140：用对象选（列表里有空槽行）
			UpdateLayout();
			Check("（收尾）自检加的那张刮削界面卡已清掉", !Profile.Cards.Contains(scrapeUiCard));
		}

		// ==================== 逐帧动画（动图拆帧） ====================
		// 这一块验的是「界面 + 接线 + 校验」；动画本身的算法（解码 / 裁剪 / 抠底 / 剥描边 / 写资源）
		// 已经逐字节对齐参考实现，见 docs\逐帧动画_吸收设计.md 与 _art\anim_ref 里的黄金文件。
		{
			string animGifDir = Path.Combine(Path.GetTempPath(), "forge_uicheck_animgif");
			Directory.CreateDirectory(animGifDir);
			string builtGif = Path.Combine(animGifDir, "selftest_2frames.gif");
			WriteSelfTestGif(builtGif);
			var builtDecoded = GifFrames.Decode(builtGif);
			Check("自检内置的那张 2 帧 GIF 解得开（2×2 / 两帧 / 100ms + 200ms）",
				builtDecoded is not null && builtDecoded.Width == 2 && builtDecoded.Height == 2
				&& builtDecoded.Frames.Count == 2 && builtDecoded.Frames[0].DelayMs == 100 && builtDecoded.Frames[1].DelayMs == 200,
				builtDecoded is null ? "解不开" : $"{builtDecoded.Frames.Count} 帧 / {builtDecoded.Width}×{builtDecoded.Height}");

			// 素材：优先用仓库里的黄金测试动图（逐字节对齐参考实现用的就是它们）；
			// 部署版旁边没有 _art 目录，就退回自检自己造的那张（自检不能依赖仓库文件）。
			string animIdle = FindRepoAnimGif("idle.gif") ?? builtGif;
			string animAttack = FindRepoAnimGif("attack.gif") ?? builtGif;
			string animNotGif = Path.Combine(animGifDir, "not_a_gif.png");
			PngUtil.WriteRgba(animNotGif, 4, 4, new byte[4 * 4 * 4]);
			// 头是 GIF、内容短得解不开：用来验「待机解不开」这条（它不是「不是 GIF」，校验器不该拦）
			string animBrokenGif = Path.Combine(animGifDir, "truncated.gif");
			File.WriteAllBytes(animBrokenGif, new byte[] { 0x47, 0x49, 0x46, 0x38, 0x39, 0x61, 0x02, 0x00 });

			// 自检期间绝不能把改动写进用户的真实存档：把「当前存档路径」指到临时目录
			// （美术那一块也是这么做的）。下面会真的点「清除 / 撤回 / 一键启用」，它们都会落盘。
			string? animOldProfilePath = _currentProfilePath;
			string? animOldSaveName = _profile.SaveName;
			string? animOldAsk = _renameAskKey;
			bool animOldEnabled = Profile.Animation.Enabled;
			string animOldIdle = Profile.Animation.Idle;
			string? animOldSlot0Path = AnimSlots[0].Path;
			string animTempProfile = Path.Combine(animGifDir, "anim_selftest.json");
			ProfileFactory.Save(_profile, animTempProfile);
			_currentProfilePath = animTempProfile;
			_renameAskKey = RenameAskKey(animTempProfile, _profile.ModId);
			try
			{
				HookAnimationSpec();
				SyncAnimSlotsFromProfile();

				// ---------- ① 界面：7 个槽位，待机那一行写明「必须有」 ----------
				DependencyObject animRoot = SelectTabRoot("动画");
				Check("「动画」页在界面上，7 个槽位都在列表里（顺序 = 待机/攻击/施法/受伤/死亡/篝火/商店）",
					AnimSlots.Count == 7 && AnimList.Items.Count == 7
					&& string.Join("/", AnimSlots.Select((AnimSlot s) => s.Name)) == "待机（循环）/攻击/施法/受伤/死亡/篝火/商店",
					string.Join("、", AnimSlots.Select((AnimSlot s) => s.Name)));
				Check("7 个槽位带的本体动画名与生成侧一致（idle_loop/attack/cast/hurt/die/overgrowth_loop/relaxed_loop）",
					string.Join("/", AnimSlots.Select((AnimSlot s) => s.AnimName))
						== "idle_loop/attack/cast/hurt/die/overgrowth_loop/relaxed_loop",
					string.Join("/", AnimSlots.Select((AnimSlot s) => s.AnimName)));
				AnimList.SelectedIndex = 0;
				UpdateLayout();
				Check("「待机（循环）」那一行写明**必须有**（其它动作没素材时都会退回它）",
					VisibleTextsIn(animRoot).Any((string t) => t.Contains("必须有")) && AnimSlots[0].Display.Contains("必须有"),
					AnimSlots[0].Display);

				// ---------- ② 总开关：不勾时设置区不显示；素材已填 → 提示 + 一键启用 ----------
				Profile.Animation.Enabled = false;
				AnimSlots[0].Path = animIdle;
				AnimSlots[0].Save(Profile.Animation);
				SyncAnimSlotsFromProfile();
				UpdateLayout();
				Check("不勾总开关时设置区不显示（抠背景 / 播放速度系数 / 缩放那几行都看不到）",
					!VisibleTextsIn(animRoot).Any((string t) => t.Contains("抠背景"))
					&& !VisibleTextsIn(animRoot).Any((string t) => t.Contains("播放速度系数"))
					&& !VisibleTextsIn(animRoot).Any((string t) => t.Contains("缩放（0 = 按静态立绘高度自动算）")),
					"设置区藏起来了");
				Check("素材已填但总开关没勾 → 提示「上面已经放了动画素材，但总开关是关的」+「一键启用逐帧动画」按钮",
					Profile.Animation.HasAny && AnimNeedsEnableHint
					&& VisibleTextsIn(animRoot).Any((string t) => t == "上面已经放了动画素材，但总开关是关的")
					&& VisibleTextsIn(animRoot).Any((string t) => t == "一键启用逐帧动画"),
					"提示与按钮都在");

				// ---------- ③ 勾上：设置区出现，默认值与参考实现一致 ----------
				OnAnimEnableFromHint(this, new RoutedEventArgs());
				UpdateLayout();
				Check("点「一键启用逐帧动画」→ 总开关打开、提示消失、设置区出现",
					Profile.Animation.Enabled
					&& !VisibleTextsIn(animRoot).Any((string t) => t == "上面已经放了动画素材，但总开关是关的")
					&& VisibleTextsIn(animRoot).Any((string t) => t.Contains("播放速度系数")),
					"总开关=" + (Profile.Animation.Enabled ? "开" : "关"));
				Check("勾上之后那几行设置（容差 / 亮度 / 最近邻 / 速度 / 缩放 / Y 偏移 / 每帧时长 / 篝火商店）连控件都在",
					HasBoxBoundTo(animRoot, "KeyTolerance") && HasBoxBoundTo(animRoot, "OutlineLuminance")
					&& HasBoxBoundTo(animRoot, "SpeedScale") && HasBoxBoundTo(animRoot, "Scale")
					&& HasBoxBoundTo(animRoot, "YOffset") && HasBoxBoundTo(animRoot, "FrameSeconds")
					&& HasBoxBoundTo(animRoot, "ManualCrop")
					&& HasCheckBox(animRoot, "抠背景") && HasCheckBox(animRoot, "剥掉浅色描边")
					&& HasCheckBox(animRoot, "最近邻过滤") && HasCheckBox(animRoot, "篝火 / 商店里保持专属动画"),
					"输入框与勾选框都在");
				Check("设置项的默认值与参考实现一致（KeyTolerance=12 / OutlineLuminance=170 / NearestFilter=true / SpeedScale=1 / 缩放与每帧时长=0 表示自动）",
					new AnimationSpec().KeyTolerance == 12 && new AnimationSpec().OutlineLuminance == 170
					&& new AnimationSpec().NearestFilter && new AnimationSpec().SpeedScale == 1
					&& new AnimationSpec().Scale == 0 && new AnimationSpec().FrameSeconds == 0
					&& new AnimationSpec().KeyBackground == false && new AnimationSpec().StripOutline == false,
					"默认值对");
				Check("界面上**不显示**「按首帧自动对齐」这一行（参考实现里那个字段根本没接进算法，暴露出来就是骗人）",
					!VisibleTextsIn(animRoot).Any((string t) => t.Contains("按首帧自动对齐")),
					"没这一行");

				// ---------- ④ AnimationSpec 的派生属性 ----------
				var animAll = new AnimationSpec
				{
					Idle = "i.gif", Attack = "a.gif", Cast = "c.gif", Hurt = "h.gif",
					Die = "d.gif", RestSite = "r.gif", Merchant = "m.gif",
				};
				Check("Slots 只 yield 填了路径的槽位，顺序与动作名都对（idle_loop/attack/cast/hurt/die/overgrowth_loop/relaxed_loop）",
					string.Join(",", animAll.Slots.Select((ValueTuple<string, string> s) => s.Item1))
						== "idle_loop,attack,cast,hurt,die,overgrowth_loop,relaxed_loop"
					&& !new AnimationSpec().Slots.Any()
					&& new AnimationSpec { Attack = "a.gif" }.Slots.Select((ValueTuple<string, string> s) => s.Item1)
						.SequenceEqual(new[] { "attack" })
					&& new AnimationSpec { Merchant = "m.gif" }.Slots.Select((ValueTuple<string, string> s) => s.Item1)
						.SequenceEqual(new[] { "relaxed_loop" }),
					string.Join(",", animAll.Slots.Select((ValueTuple<string, string> s) => s.Item1)));
				Check("HasAny 只看待机（只填了攻击 = 没有素材；待机是回退目标）",
					!new AnimationSpec { Attack = "a.gif" }.HasAny && new AnimationSpec { Idle = "i.gif" }.HasAny,
					"只看待机");
				Check("Display 三种状态都写对（未启用 / 已启用但没上传待机 / N 个动作 · 最近邻 · 1×）",
					new AnimationSpec().Display == "未启用"
					&& new AnimationSpec { Enabled = true }.Display == "已启用但没上传待机"
					&& new AnimationSpec { Enabled = true, Idle = "i.gif", Attack = "a.gif" }.Display == "2 个动作 · 最近邻 · 1×"
					&& new AnimationSpec { Enabled = true, Idle = "i.gif", NearestFilter = false, SpeedScale = 0.5 }.Display == "1 个动作 · 线性 · 0.5×",
					new AnimationSpec { Enabled = true, Idle = "i.gif", Attack = "a.gif" }.Display);

				// ---------- ⑤ 缩略图：第一帧 ----------
				var animThumb = AnimSlots[0].Preview;
				Check("缩略图用**第一帧**的 RGBA 造得出来（WPF 播不了动图，只有游戏里才逐帧播放）",
					animThumb is not null && animThumb.PixelWidth == AnimSlots[0].PreviewWidth
					&& animThumb.PixelHeight == AnimSlots[0].PreviewHeight
					&& AnimSlots[0].FrameNote.Contains("帧") && AnimSlots[0].FrameNote.Contains("每帧"),
					AnimSlots[0].FrameNote);
				Check("没上传 / 不是 GIF 的槽位缩略图为空、并且说明为什么（不会画出一张花图）",
					new AnimSlot("x", "attack", "", "", (AnimationSpec a) => a.Attack, delegate { }).Preview is null
					&& AnimSlots[1].FrameNote.Length > 0,
					AnimSlots[1].FrameNote);

				// ---------- ⑥ 生成：帧资源 + 两个运行时文件 + ModEntry 注册行 ----------
				string animGenRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_animgen_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				CharacterProfile animGen = ProfileFactory.Sample();
				animGen.Paths.OutputDir = animGenRoot;
				animGen.Paths.VanillaProject = Profile.Paths.VanillaProject;
				animGen.Paths.GameDataDir = Profile.Paths.GameDataDir;
				animGen.Animation.Enabled = true;
				animGen.Animation.Idle = animIdle;
				animGen.Animation.Attack = animAttack;
				try
				{
					AnimFramesGen.Plan animPlan = AnimFramesGen.BuildPlan(animGen, _ => { });
					Check("（准备）勾了逐帧动画 + 待机素材的存档能生成工程", ModGenerator.Generate(animGen).Success, animGenRoot);
					string animProject = ModGenerator.ProjectRootOf(animGen);
					string animCs = Path.Combine(animProject, "cs");
					string animSlug = Naming.From(animGen).CharSlug;
					string animFrameDir = Path.Combine(animProject, "images", "characters", "anim", animSlug);
					Check("工程里有逐帧动画的两个源文件（FrameAnimRuntime.cs / FrameAnimPatches.cs）",
						File.Exists(Path.Combine(animCs, "FrameAnimRuntime.cs")) && File.Exists(Path.Combine(animCs, "FrameAnimPatches.cs")),
						animCs);
					// ===== V0.2.227：篝火卡死（联机 2 号位 FlipX 空引用）=====
					// 用户实测报的「篝火会卡死」：日志里是 NRestSiteCharacter.FlipX() 的空引用（被
					// NRestSiteRoom._Ready 调出来）→ 房间 _Ready 后半段（生成选项 / 连继续按钮 / 同步器事件）全没跑。
					// 真因：篝火补丁把本体 _Ready 整段跳过了，_controlRoot 一直是 null。这里把「不许再跳过」钉死。
					string animPatchSrc = File.ReadAllText(Path.Combine(animCs, "FrameAnimPatches.cs"));
					int animRestActIdx = animPatchSrc.IndexOf("FrameAnimRestSiteAct(__instance));", StringComparison.Ordinal);
					int animRestGateIdx = animPatchSrc.IndexOf("GetNodeOrNull<Control>(\"ControlRoot\")", StringComparison.Ordinal);
					Check("V0.2.227：篝火 _Ready 补丁不再整段跳过本体（先挂帧动画，再检查场景结构、齐了就放行）",
						animRestActIdx >= 0 && animRestGateIdx > animRestActIdx
						&& animPatchSrc.Contains("篝火场景缺 ControlRoot / %Hitbox / %SelectionReticle"),
						animRestActIdx < 0 ? "没找到挂动画那一句" : $"挂动画@{animRestActIdx} 结构检查@{animRestGateIdx}");
					Check("V0.2.227：FlipX 兜底补丁在（_controlRoot 为 null 时跳过翻面，否则联机会把房间初始化打断）",
						animPatchSrc.Contains("FrameAnimRestSiteFlipPatch")
						&& animPatchSrc.Contains("nameof(NRestSiteCharacter.FlipX)")
						&& animPatchSrc.Contains("TryFieldRef<NRestSiteCharacter, Control>(\"_controlRoot\")"),
						"有兜底");
					Check("V0.2.227：非 Spine 篝火立绘在 FlipX 之后补一次水平镜像（本体只会翻 Spine 子节点）",
						animPatchSrc.Contains("FrameAnimSpineProbe.MirrorX(__instance.GetNodeOrNull<Node2D>(\"%Visuals\"))")
						&& animPatchSrc.Contains("FrameAnimSpineProbe.MirrorX(__instance.GetNodeOrNull<Node2D>(\"__FrameAnimSprite\"))"),
						"补了镜像");
					Check("V0.2.227：商店补丁保持原样（NMerchantCharacter._Ready 只做「包第一个子节点」，跳过它是对的）",
						animPatchSrc.Contains("FrameAnimMerchantPatch")
						&& animPatchSrc.Contains("player?.Play(\"relaxed_loop\");"),
						"商店不动");
					string[] animFrameFiles = Directory.Exists(animFrameDir) ? Directory.GetFiles(animFrameDir, "*.png") : Array.Empty<string>();
					Check("工程里有帧 PNG + 每张的 .png.import + _frames.tres + _manifest.json（帧数与计划一致）",
						animFrameFiles.Length == animPlan.Anims.Sum((AnimFramesGen.AnimPlan o) => o.FrameCount)
						&& animFrameFiles.All((string f) => File.Exists(f + ".import"))
						&& File.Exists(Path.Combine(animFrameDir, animSlug + "_idle_loop_frames.tres"))
						&& File.Exists(Path.Combine(animFrameDir, animSlug + "_idle_loop_manifest.json")),
						$"{animFrameFiles.Length} 张帧图（计划 {animPlan.Anims.Sum((AnimFramesGen.AnimPlan o) => o.FrameCount)} 帧）");
					string animEntry = File.ReadAllText(Path.Combine(animCs, "ModEntry.cs"));
					Check("ModEntry.cs 里有 FrameAnimRegistry.Register(...) 和四个 __anim* 常量（缩放 / Y 偏移 / 速度 / 篝火商店）",
						animEntry.Contains("FrameAnimRegistry.Register(")
						&& animEntry.Contains("const float __animScale")
						&& animEntry.Contains("const float __animYOffset")
						&& animEntry.Contains("const float __animSpeed")
						&& animEntry.Contains("const bool __animKeepRestShop"),
						"注册行与常量都在");
					Check("每个动作注册一条，tres 路径指向该动作的 _frames.tres",
						animPlan.Anims.All((AnimFramesGen.AnimPlan o) => animEntry.Contains(
							$"\"{o.Anim}\", \"res://images/characters/anim/{animSlug}/{animSlug}_{o.Anim}_frames.tres\"")),
						$"{animPlan.Anims.Count} 个动作");
					AnimFramesGen.AnimPlan animIdlePlan = animPlan.Anims.First((AnimFramesGen.AnimPlan o) => o.Anim == "idle_loop");
					string animTres = File.ReadAllText(Path.Combine(animFrameDir, animSlug + "_idle_loop_frames.tres"));
					Check("SpriteFrames 是「speed 恒为 1.0 + 每帧 duration 写秒数」（Godot 的 speed 是倍率不是 fps）",
						animTres.Contains("\"speed\": 1.0")
						&& animTres.Contains("\"duration\": " + animIdlePlan.FrameSeconds.ToString("0.####", CultureInfo.InvariantCulture))
						&& animTres.Contains("\"name\": &\"idle_loop\"") && animTres.Contains("\"loop\": true"),
						"每帧 " + animIdlePlan.FrameSeconds.ToString("0.####", CultureInfo.InvariantCulture) + " 秒");
					string animManifest = File.ReadAllText(Path.Combine(animFrameDir, animSlug + "_idle_loop_manifest.json"));
					Check("清单里的裁剪框 / 尺寸 / 帧数 / trigger 与计划一致",
						animManifest.Contains($"\"crop\": [{animPlan.CropX0}, {animPlan.CropY0}, {animPlan.CropX1}, {animPlan.CropY1}]")
						&& animManifest.Contains($"\"size\": [{animPlan.Width}, {animPlan.Height}]")
						&& animManifest.Contains($"\"frames\": {animIdlePlan.FrameCount}")
						&& animManifest.Contains("\"trigger\": \"Idle\""),
						$"裁剪框 {animPlan.CropX0},{animPlan.CropY0}..{animPlan.CropX1},{animPlan.CropY1}");

					// ---------- ⑦ 不勾总开关 = 与以前逐字一样（老存档也走这条） ----------
					string animOffModernRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_animoff_a_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					string animOffLegacyRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_animoff_b_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					CharacterProfile animOffModern = ProfileFactory.Sample();
					animOffModern.Paths.VanillaProject = Profile.Paths.VanillaProject;
					animOffModern.Paths.GameDataDir = Profile.Paths.GameDataDir;
					animOffModern.Paths.OutputDir = animOffModernRoot;
					animOffModern.Animation.Enabled = false;
					animOffModern.Animation.Idle = animIdle;      // 素材留着、总开关关着（用户可能只是暂时关掉）
					// 老存档 = 同一份 JSON 把 "Animation" 整段删掉（V0.2.47 及以前根本没有这一档）
					string animModernJson = JsonSerializer.Serialize(animOffModern, ProfileFactory.JsonOpts);
					string animLegacyJson = RemoveAnimationSection(animModernJson);
					string animLegacyPath = Path.Combine(animGifDir, "legacy_no_animation.json");
					File.WriteAllText(animLegacyPath, animLegacyJson, new UTF8Encoding(false));
					CharacterProfile animOffLegacy = ProfileFactory.Load(animLegacyPath);
					// 两份输出一定要落在**不同**的目录里：否则「逐字一样」这条等于自己跟自己比，
					// 什么都验不出来（第一版就是这么写的，删目录时才发现第二个根根本没建出来）。
					animOffLegacy.Paths.OutputDir = animOffLegacyRoot;
					animOffLegacy.Paths.VanillaProject = Profile.Paths.VanillaProject;
					animOffLegacy.Paths.GameDataDir = Profile.Paths.GameDataDir;
					Check("老存档（JSON 里**没有** Animation 段）读出来就是「不勾总开关、一个素材都没有」",
						!animLegacyJson.Contains("\"Animation\"", StringComparison.Ordinal)
						&& !animOffLegacy.Animation.Enabled && !animOffLegacy.Animation.Slots.Any()
						&& !animOffLegacy.Animation.HasAny,
						animOffLegacy.Animation.Display);
					Check("（准备）关着总开关的两份存档都能生成工程",
						ModGenerator.Generate(animOffModern).Success && ModGenerator.Generate(animOffLegacy).Success,
						animOffModernRoot);
					string animOffModernCs = Path.Combine(ModGenerator.ProjectRootOf(animOffModern), "cs");
					string animOffLegacyCs = Path.Combine(ModGenerator.ProjectRootOf(animOffLegacy), "cs");
					string animOffEntry = File.ReadAllText(Path.Combine(animOffModernCs, "ModEntry.cs"));
					Check("不勾总开关：ModEntry.cs 里没有动画那几行（注册调用 / 四个 __anim* 常量 / 注释都没有）",
						!animOffEntry.Contains("FrameAnimRegistry") && !animOffEntry.Contains("__anim")
						&& !animOffEntry.Contains("逐帧动画"),
						"一行都没写");
					Check("不勾总开关：不生成 FrameAnimRuntime.cs / FrameAnimPatches.cs，也没有帧图目录",
						!File.Exists(Path.Combine(animOffModernCs, "FrameAnimRuntime.cs"))
						&& !File.Exists(Path.Combine(animOffModernCs, "FrameAnimPatches.cs"))
						&& !Directory.Exists(Path.Combine(ModGenerator.ProjectRootOf(animOffModern), "images", "characters", "anim")),
						"没生成任何动画资源");
					Check("老存档（JSON 里没有 Animation 段）走的就是「不勾总开关」那条路：ModEntry.cs 与本轮的输出逐字一样",
						File.ReadAllText(Path.Combine(animOffLegacyCs, "ModEntry.cs")) == animOffEntry
						&& !File.Exists(Path.Combine(animOffLegacyCs, "FrameAnimRuntime.cs"))
						&& !string.Equals(ModGenerator.ProjectRootOf(animOffLegacy), ModGenerator.ProjectRootOf(animOffModern),
							StringComparison.OrdinalIgnoreCase),
						"两份 ModEntry.cs 逐字相同");
					try { if (Directory.Exists(animOffModernRoot)) Directory.Delete(animOffModernRoot, true); } catch { }
					try { if (Directory.Exists(animOffLegacyRoot)) Directory.Delete(animOffLegacyRoot, true); } catch { }

					// ---------- ⑧ 待机解不开：计划作废、一个动画资源都不写，但模组照常能生成 ----------
					string animBadRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_animbad_" + Guid.NewGuid().ToString("N").Substring(0, 8));
					CharacterProfile animBad = ProfileFactory.Sample();
					animBad.Paths.OutputDir = animBadRoot;
					animBad.Paths.VanillaProject = Profile.Paths.VanillaProject;
					animBad.Paths.GameDataDir = Profile.Paths.GameDataDir;
					animBad.Animation.Enabled = true;
					animBad.Animation.Idle = animBrokenGif;      // 头是 GIF，但短得解不开
					List<string> animBadNotes = new List<string>();
					AnimFramesGen.Plan animBadPlan = AnimFramesGen.BuildPlan(animBad, animBadNotes.Add);
					Check("待机解不开 → BuildPlan 给 [错误] 且 Ok=false（整份计划作废）",
						!animBadPlan.Ok && animBadPlan.Notes.Any((string t) => t.StartsWith("[错误]", StringComparison.Ordinal)),
						animBadPlan.Notes.FirstOrDefault((string t) => t.StartsWith("[错误]", StringComparison.Ordinal)) ?? "(没有错误行)");
					Check("（准备）这种存档照样能生成工程（模组能编译，只是没有逐帧动画）",
						ModGenerator.Generate(animBad).Success, animBadRoot);
					string animBadCs = Path.Combine(ModGenerator.ProjectRootOf(animBad), "cs");
					Check("待机解不开时不写任何动画资源 / 运行时代码（宁可什么都没有，也不要写出半套动画）",
						!File.Exists(Path.Combine(animBadCs, "FrameAnimRuntime.cs"))
						&& !File.Exists(Path.Combine(animBadCs, "FrameAnimPatches.cs"))
						&& !Directory.Exists(Path.Combine(ModGenerator.ProjectRootOf(animBad), "images", "characters", "anim"))
						&& !File.ReadAllText(Path.Combine(animBadCs, "ModEntry.cs")).Contains("FrameAnimRegistry"),
						"一个文件都没写");
					try { if (Directory.Exists(animBadRoot)) Directory.Delete(animBadRoot, true); } catch { }

					// ---------- ⑨ 抠底 / 剥描边真的改像素，而且不影响裁剪框 ----------
					string animKeyFrame = Path.Combine(animFrameDir, animSlug + "_idle_loop_000.png");
					animGen.Animation.KeyBackground = false;
					Check("（准备）关着抠底的存档能生成工程", ModGenerator.Generate(animGen).Success, animGenRoot);
					byte[] animFrameNoKey = File.ReadAllBytes(animKeyFrame);
					animGen.Animation.KeyBackground = true;
					Check("（准备）勾上抠底的存档能生成工程", ModGenerator.Generate(animGen).Success, animGenRoot);
					byte[] animFrameKey = File.ReadAllBytes(animKeyFrame);
					Check("抠底真的改了像素：同一帧在 KeyBackground=false/true 下写出来的 PNG 字节不同",
						!animFrameNoKey.SequenceEqual(animFrameKey),
						$"不抠 {animFrameNoKey.Length} 字节 / 抠底 {animFrameKey.Length} 字节");
					animGen.Animation.KeyBackground = false;
					AnimFramesGen.Plan animPlanStrip = AnimFramesGen.BuildPlan(animGen, _ => { });
					animGen.Animation.StripOutline = true;
					AnimFramesGen.Plan animPlanStripOn = AnimFramesGen.BuildPlan(animGen, _ => { });
					Check("抠底 / 剥描边都不影响裁剪框与缩放（计划按原图算，这两步只在写帧时做）",
						animPlanStrip.CropX0 == animPlanStripOn.CropX0 && animPlanStrip.CropY0 == animPlanStripOn.CropY0
						&& animPlanStrip.CropX1 == animPlanStripOn.CropX1 && animPlanStrip.CropY1 == animPlanStripOn.CropY1
						&& animPlanStrip.Scale == animPlanStripOn.Scale && animPlanStrip.YOffset == animPlanStripOn.YOffset,
						$"{animPlanStripOn.CropX0},{animPlanStripOn.CropY0}..{animPlanStripOn.CropX1},{animPlanStripOn.CropY1}");
					// 剥描边要另外造一张图验：仓库那张测试动图的描边是**深色**，剥浅色对它本来就不该有影响
					//（黄金文件实测：variant_strip 与基线逐字节相同），拿它验「剥描边生效」是验不出来的。
					byte[] animProbe = OutlineProbeFrame(400);
					byte[] animNoStrip = AnimFramesGen.CropFrame(animProbe, 400, 400, 0, 0, 400, 400, new AnimationSpec());
					byte[] animStripped = AnimFramesGen.CropFrame(animProbe, 400, 400, 0, 0, 400, 400,
						new AnimationSpec { StripOutline = true, OutlineLuminance = 170 });
					int animStrippedAway = 0;
					for (int i = 0; i < 400 * 400; i++)
						if (animNoStrip[i * 4 + 3] == 255 && animStripped[i * 4 + 3] == 0) animStrippedAway++;
					int animCenter = (200 * 400 + 200) * 4 + 3;
					Check("剥浅色描边真的改了像素：造一张「最外圈透明 + 两圈浅灰」的图，剥掉的就是那两圈（深色主体一动不动）",
						animStrippedAway > 1000 && !animNoStrip.SequenceEqual(animStripped)
						&& animNoStrip[animCenter] == 255 && animStripped[animCenter] == 255,
						$"剥掉 {animStrippedAway} 个像素的 alpha");

					// ---------- ⑩ 「最近邻」：关掉时注册行必须带 Linear（我们对参考实现的修正） ----------
					CharacterProfile animLinear = ProfileFactory.Sample();
					animLinear.Animation.Enabled = true;
					animLinear.Animation.Idle = animIdle;
					animLinear.Animation.NearestFilter = false;
					string animLinearEntry = PatchesGen.ModEntrySource(animLinear, AnimFramesGen.BuildPlan(animLinear, _ => { }));
					Check("「最近邻」关掉时注册行带 filter: Godot.CanvasItem.TextureFilterEnum.Linear"
						+ "（参考实现那个勾选框其实没生效，这里是我们补的）",
						animLinearEntry.Contains("filter: Godot.CanvasItem.TextureFilterEnum.Linear"), "带了 Linear");
					animLinear.Animation.NearestFilter = true;
					string animNearestEntry = PatchesGen.ModEntrySource(animLinear, AnimFramesGen.BuildPlan(animLinear, _ => { }));
					Check("（对照）开着最近邻时不写 filter 参数（用 Register 的默认值 Nearest）",
						animNearestEntry.Contains("FrameAnimRegistry.Register(") && !animNearestEntry.Contains(", filter:"),
						"不带 filter");
				}
				finally
				{
					try { if (Directory.Exists(animGenRoot)) Directory.Delete(animGenRoot, true); } catch { }
				}

				// ---------- ⑪ 「预览动画计划」：写进只读文本框，而且一个文件都不写 ----------
				string animPreviewRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_animpreview_" + Guid.NewGuid().ToString("N").Substring(0, 8));
				Directory.CreateDirectory(animPreviewRoot);
				string animPreviewOldOut = Profile.Paths.OutputDir;
				try
				{
					Profile.Paths.OutputDir = animPreviewRoot;
					SyncAnimSlotsFromProfile();
					AnimList.SelectedIndex = 0;
					OnAnimPlanPreview(this, new RoutedEventArgs());
					Check("「预览动画计划」把裁剪框 / 帧数 / 每帧时长 / 缩放 / 位置 / 提示行都写进了文本框",
						AnimPlanText.Contains("裁剪框：") && AnimPlanText.Contains("每帧 ") && AnimPlanText.Contains("缩放：")
						&& AnimPlanText.Contains("Y 偏移：") && AnimPlanText.Contains("提示 / 警告 / 错误：")
						&& AnimPlanText.Contains("idle_loop"),
						AnimPlanText.Split('\n')[0].Trim());
					Check("「预览动画计划」一个文件都不写（预览用的输出目录里连 images 都没有）",
						!Directory.Exists(Path.Combine(animPreviewRoot, "images")), animPreviewRoot);
					Check("改一下设置，上一份预览就作废（免得拿着旧数字去调）",
						SetAnimSettingAndCheckPreviewInvalidated());
				}
				finally
				{
					Profile.Paths.OutputDir = animPreviewOldOut;
				}

				// ---------- ⑫ 「清除」要能撤回（记 _lastAnimClearedPath） ----------
				SyncAnimSlotsFromProfile();
				AnimList.SelectedIndex = 0;
				string animClearTarget = AnimSlots[0].Path ?? "";
				OnClearAnim(this, new RoutedEventArgs());
				Check("「清除」清掉槽位，并记住上一次清除的路径（清错了能拿回来）",
					string.IsNullOrWhiteSpace(Profile.Animation.Idle) && CanUndoAnim && _lastAnimClearedPath == animClearTarget,
					"记着：" + (_lastAnimClearedPath ?? "空"));
				OnUndoAnim(this, new RoutedEventArgs());
				Check("「撤回清除」把 GIF 路径接回来、按钮状态复位",
					Profile.Animation.Idle == animClearTarget && !CanUndoAnim,
					Profile.Animation.Idle.Length > 0 ? Profile.Animation.Idle : "空");

				// ---------- ⑬ 校验器那 6 条 ----------
				CharacterProfile animV = ProfileFactory.Sample();
				animV.Animation.Enabled = true;
				Check("校验器：勾了总开关却没待机 → **错误**（待机是回退目标，没它整条废）",
					ProfileValidator.Validate(animV).Any((ValidationIssue i) => i.IsError && i.Message.Contains("待机是回退目标")),
					"报错了");
				Check("校验器：勾了总开关但一个素材都没有 → 提示（不是错误）",
					ProfileValidator.Validate(animV).Any((ValidationIssue i) => !i.IsError && i.Message.Contains("一个动图都没传")),
					"提示了");
				CharacterProfile animV2 = ProfileFactory.Sample();
				animV2.Animation.Enabled = true;
				animV2.Animation.Idle = Path.Combine(animGifDir, "这个文件根本不存在.gif");
				Check("校验器：填了路径但文件不存在 → **错误**，并指出是哪个槽位",
					ProfileValidator.Validate(animV2).Any((ValidationIssue i) => i.IsError
						&& i.Message.Contains("待机（循环）") && i.Message.Contains("文件不存在")),
					"报错了");
				animV2.Animation.Idle = animNotGif;
				animV2.Animation.Attack = animNotGif;
				Check("校验器：素材不是 GIF → **错误**（逐个槽位各报一条，指出是哪个槽位）",
					ProfileValidator.Validate(animV2).Count((ValidationIssue i) => i.IsError && i.Message.Contains("不是 GIF")) == 2,
					"待机与攻击各一条");
				CharacterProfile animV3 = ProfileFactory.Sample();
				animV3.Animation.Enabled = false;
				animV3.Animation.Idle = animIdle;
				Check("校验器：没勾总开关却留着路径 → 提示（不会生效，别让人以为生效了）",
					ProfileValidator.Validate(animV3).Any((ValidationIssue i) => !i.IsError && i.Message.Contains("没勾")),
					"提示了");
				CharacterProfile animV4 = ProfileFactory.Sample();
				animV4.Animation.Enabled = true;
				animV4.Animation.Idle = animIdle;
				animV4.Animation.ManualCrop = "0,0,20";       // 少一个数
				Check("校验器：手动裁剪框格式不对 → **警告**（生成侧会优雅降级改用自动，别拦住整次生成）",
					ProfileValidator.Validate(animV4).Any((ValidationIssue i) => !i.IsError && i.Message.Contains("手动裁剪框") && i.Message.Contains("开区间"))
					&& !ProfileValidator.Validate(animV4).Any((ValidationIssue i) => i.IsError && i.Message.Contains("手动裁剪框")),
					"是警告不是错误");
				CharacterProfile animV5 = ProfileFactory.Sample();
				animV5.Animation.Enabled = true;
				animV5.Animation.Idle = animIdle;
				animV5.Animation.ManualCrop = "7,12,13,21";
				animV5.Animation.Scale = 3;
				Check("（对照）裁剪框写对 / 缩放填了合法值 → 这两条都不报",
					!ProfileValidator.Validate(animV5).Any((ValidationIssue i) => i.Message.Contains("手动裁剪框") || i.Message.Contains("「缩放」")),
					"不报");
				CharacterProfile animV6 = ProfileFactory.Sample();
				animV6.Animation.Enabled = true;
				animV6.Animation.Idle = animIdle;
				animV6.Animation.Scale = -1;
				animV6.Animation.SpeedScale = 0;
				animV6.Animation.KeyTolerance = -1;
				animV6.Animation.OutlineLuminance = 999;
				var animVRange = ProfileValidator.Validate(animV6);
				Check("校验器：Scale / SpeedScale / KeyTolerance / OutlineLuminance 越界 → 四条**错误**",
					animVRange.Count((ValidationIssue i) => i.IsError && i.Message.Contains("逐帧动画：")) == 4,
					string.Join(" ｜ ", animVRange.Where((ValidationIssue i) => i.IsError && i.Message.Contains("逐帧动画：")).Select((ValidationIssue i) => i.Message)));

				// 校验器的这几条不能把正常配置也拦下来（示例配置 + 一张合法动图 → 一条逐帧动画的问题都不该有）
				CharacterProfile animV7 = ProfileFactory.Sample();
				animV7.Animation.Enabled = true;
				animV7.Animation.Idle = animIdle;
				animV7.Animation.Attack = animAttack;
				Check("（对照）正常配置一条逐帧动画的问题都不报",
					!ProfileValidator.Validate(animV7).Any((ValidationIssue i) => i.Message.Contains("逐帧动画：")),
					"干净");
			}
			finally
			{
				// 自检结束：把存档路径 / 开关 / 槽位都还原（绝不把自检期间的改动留在用户存档上）
				_currentProfilePath = animOldProfilePath;
				_renameAskKey = animOldAsk;
				_profile.SaveName = animOldSaveName;
				Profile.Animation.Enabled = animOldEnabled;
				Profile.Animation.Idle = animOldIdle;
				AnimSlots[0].Path = animOldSlot0Path;
				SyncAnimSlotsFromProfile();
				HookAnimationSpec();
			}
		}
		// ==================================================================================
		// V0.2.132（《卡牌页优化.md》右侧④）：作用对象 7 档 + 概率独立 + 卡牌链编辑器重排
		// ==================================================================================
		{
			// ---- A. 作用对象 7 档（共用表）----
			var want7 = new[] { "Self", "Ally", "AllAllies", "Enemy", "RandomEnemies", "AllEnemies", "AllUnits" };
			Check("作用对象扩到 7 档、顺序与需求一致（自己 / 指定队友 / 全部友方 / 单体敌人 / 随机敌人 / 全部敌人 / 全体单位）",
				EffectCatalog.TargetSides.Count == 7 && want7.All(x => EffectCatalog.TargetSides.Contains(x))
				&& string.Join(",", EffectCatalog.TargetSides) == string.Join(",", want7),
				string.Join(" / ", EffectCatalog.TargetSides));
			Check("作用对象的中文名表齐了（界面 / 校验消息共用）",
				EffectCatalog.TargetSideZh("AllUnits") == "全体单位" && EffectCatalog.TargetSideZh("AllAllies") == "全部友方"
				&& EffectCatalog.TargetSideZh("Ally") == "指定队友" && EffectCatalog.TargetSideZh("RandomEnemies") == "随机敌人");
			Check("「全体单位」的支持名单和生成端一致（8 种）",
				EffectCatalog.SupportsAllUnits("Damage") && EffectCatalog.SupportsAllUnits("Stun")
				&& EffectCatalog.SupportsAllUnits("ApplyPower") && !EffectCatalog.SupportsAllUnits("Draw")
				&& !EffectCatalog.SupportsAllUnits("GenerateCard"), "伤害/击晕/施加状态支持，抽牌/生成卡牌不支持");

			// ---- 生成：默认档（全部友方含召唤物）必须与老版本逐字相同；勾「不包括召唤物」才多一句过滤 ----
			CharacterProfile tgtProfile = ProfileFactory.Sample();
			CardSpec allyCardBefore = new CardSpec { Name = "全友方旧档", ClassName = "UiCheckAllAlliesOld", Cost = 1, CardType = "Skill", Rarity = "Common", InCardPool = true };
			allyCardBefore.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "AllAllies" });
			tgtProfile.Cards.Add(allyCardBefore);
			string allyOldSrc = CSharpCodeGen.CardSource(tgtProfile, allyCardBefore, 0);
			Check("（红线）「全部友方」默认档生成的就是老那句过滤条件（含召唤物，逐字不变）",
				allyOldSrc.Contains(".Where(c => c.IsAlive && c != base.Owner.Creature).ToList()")
				&& !allyOldSrc.Contains("PetOwner"), "老写法");
			EffectSpec allyEff = new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "AllAllies", AllAlliesExcludePets = true };
			CardSpec allyCardAfter = new CardSpec { Name = "全友方不含召唤物", ClassName = "UiCheckAllAlliesNoPets", Cost = 1, CardType = "Skill", Rarity = "Common", InCardPool = true };
			allyCardAfter.Effects.Add(allyEff);
			tgtProfile.Cards.Add(allyCardAfter);
			string allyNewSrc = CSharpCodeGen.CardSource(tgtProfile, allyCardAfter, 0);
			Check("勾「全部友方不包括召唤物」→ 过滤条件尾巴补 `&& c.PetOwner is null`",
				allyNewSrc.Contains(".Where(c => c.IsAlive && c != base.Owner.Creature && c.PetOwner is null).ToList()"), "补上了");
			Check("「全部友方」的两档都写 `// CET:TargetSide=AllAllies` 标记（回读用）；勾了不含召唤物时标记里多一项",
				allyOldSrc.Contains("// CET:TargetSide=AllAllies")
				&& allyNewSrc.Contains("// CET:TargetSide=AllAllies CET:AllyNoPets=1"), "有标记");

			// ---- V0.2.201（用户问「怎么选全部友方包括自己」）：新加「包括自己」这个子选项 ----
			{
				var allySelfEff = new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "AllAllies", AllAlliesIncludeSelf = true };
				CardSpec allySelfCard = new CardSpec { Name = "全友方含自己", ClassName = "UiCheckAllAlliesSelf", Cost = 1, CardType = "Skill", Rarity = "Common", InCardPool = true };
				allySelfCard.Effects.Add(allySelfEff);
				tgtProfile.Cards.Add(allySelfCard);
				string allySelfSrc = CSharpCodeGen.CardSource(tgtProfile, allySelfCard, 0);
				Check("V0.2.201：勾「全部友方 · 包括自己」→ 过滤条件里**没有** `c != base.Owner.Creature`（自己也被算上）",
					allySelfSrc.Contains(".Where(c => c.IsAlive).ToList()")
					&& !allySelfSrc.Contains("c != base.Owner.Creature"), "去掉了排除自己");
				Check("V0.2.201：两个勾可以叠加（包括自己 + 不包括召唤物）",
					CSharpCodeGen.CardSource(tgtProfile, new CardSpec
					{
						Name = "叠加", ClassName = "UiCheckAllAlliesBoth", Cost = 1, CardType = "Skill", Rarity = "Common", InCardPool = true,
						Effects = { new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "AllAllies", AllAlliesIncludeSelf = true, AllAlliesExcludePets = true } },
					}, 0).Contains(".Where(c => c.IsAlive && c.PetOwner is null).ToList()"), "两个勾都生效");
				Check("V0.2.201：勾了「包括自己」会写 `CET:AllySelf=1` 标记（工程回读能还原）",
					allySelfSrc.Contains("// CET:TargetSide=AllAllies CET:AllySelf=1"), "有标记");
				var allySelfUi = new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "AllAllies" };
				Check("V0.2.201：「全部友方 · 包括自己」那一行只在作用对象 = 全部友方时显示",
					allySelfUi.ShowAllAlliesIncludeSelfRow
					&& !new EffectSpec { Kind = "Damage", TargetSide = "AllEnemies" }.ShowAllAlliesIncludeSelfRow
					&& !new EffectSpec { Kind = "Damage", TargetSide = "Self" }.ShowAllAlliesIncludeSelfRow, "显隐对");
				var selfRowRaises = new List<string>();
				PropertyChangedEventHandler selfRowSpy = (_, ev) => { if (ev.PropertyName is { Length: > 0 } sp) selfRowRaises.Add(sp); };
				var selfRowProbe = new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "Enemy" };
				selfRowProbe.PropertyChanged += selfRowSpy;
				try { selfRowProbe.TargetSide = "AllAllies"; } finally { selfRowProbe.PropertyChanged -= selfRowSpy; }
				Check("V0.2.201：把作用对象切成「全部友方」会通知界面刷新那一行",
					selfRowRaises.Contains("ShowAllAlliesIncludeSelfRow"), string.Join("/", selfRowRaises));
				Check("V0.2.201：列表行尾写「全体友方（含自己）」、卡面写「你、队友和所有召唤物」",
					allySelfEff.Display.Contains("全体友方（含自己）")
					&& LocalizationGen.CardsJson(tgtProfile).Contains("你、队友和所有召唤物"), allySelfEff.Display);
				// 生成端不再碰 PlayerCreatures（召唤物不在那个列表里 —— 就是「全部友方什么都不打」的老病根）
				Check("V0.2.201：（病根）「全部友方」不再用 CombatState.PlayerCreatures（那个列表只有 `Player != null` 的单位，召唤物不在里面）",
					!allySelfSrc.Contains("PlayerCreatures") && !allyOldSrc.Contains("PlayerCreatures"), "都换成 Allies 了");
			}

			// ---- 生成：全体单位（7 档里新增的那一档）五条链都真的展开成「两边所有存活单位」 ----
			string unitsExpr = "base.Owner.Creature.CombatState.Creatures.Where(c => c.IsAlive).ToList()";
			var unitsCases = new (string Kind, string Label)[]
			{
				("Damage", "造成伤害"), ("Block", "获得格挡"), ("ApplyPower", "施加增益减益"),
				("TempPower", "临时增益"), ("Stun", "击晕"),
			};
			foreach (var (ukind, ulabel) in unitsCases)
			{
				CharacterProfile up = ProfileFactory.Sample();
				var uc = new CardSpec { Name = "全体单位" + ulabel, ClassName = "UiCheckAllUnits" + ukind, Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				uc.Effects.Add(new EffectSpec
				{
					Kind = ukind, Amount = 3m, TargetSide = "AllUnits",
					PowerId = ukind is "ApplyPower" or "TempPower" ? "WeakPower" : null,
				});
				up.Cards.Add(uc);
				string usrc = CSharpCodeGen.CardSource(up, uc, 0);
				Check($"「全体单位」+「{ulabel}」→ 循环体遍历 CombatState.Creatures 的存活单位",
					usrc.Contains(unitsExpr) && usrc.Contains("// CET:TargetSide=AllUnits"), usrc.Contains(unitsExpr) ? "展开了" : "没展开");
			}
			Check("（对照）「全体单位」不再落到 default 里被当成「对自己」",
				!CSharpCodeGen.CardSource(ProfileFactory.Sample(), new CardSpec
				{
					Name = "对照全体单位", ClassName = "UiCheckAllUnitsCtl", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true,
					Effects = { new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "AllUnits" } },
				}, 0).Contains("await CreatureCmd.GainBlock(base.Owner.Creature,"), "没有直接给自己");

			// 校验器：没实现「全体单位」的种类必须报错拦住（不许静默变成「对自己」）
			CharacterProfile uv = ProfileFactory.Sample();
			var uvCard = new CardSpec { Name = "全体单位越界", ClassName = "UiCheckAllUnitsBad", Cost = 1, CardType = "Skill", Rarity = "Common", InCardPool = true };
			uvCard.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "AllUnits" });
			uv.Cards.Add(uvCard);
			var uvIssues = ProfileValidator.Validate(uv);
			Check("校验器：「抽牌 + 全体单位」→ 错误说清这一档还没实现、并列出支持的种类",
				uvIssues.Any(i => i.IsError && i.Message.Contains("全体单位") && i.Message.Contains("对自己")), 
				uvIssues.FirstOrDefault(i => i.IsError)?.Message ?? "(没报错)");
			uvCard.Effects[0].Kind = "Block";
			uvCard.Effects[0].Amount = 4m;
			Check("（对照）「格挡 + 全体单位」不报错（生成端真的实现了这一档）",
				!ProfileValidator.Validate(uv).Any(i => i.IsError && i.Message.Contains("全体单位")), "不报");

			// V0.2.200：「牺牲伙伴 → 造成伤害」现在也走 EmitPerCreature 按作用对象展开，
			// 所以「全体单位 / 全部队友」对它同样合法；收益不是伤害时生成端**不读**作用对象，必须照旧拦住。
			CharacterProfile uvSac = ProfileFactory.Sample();
			uvSac.Summons.Add(new SummonSpec { Name = "自检伙伴", ClassName = "UiCheckSacAllUnitsPet", Enabled = true });
			var uvSacDmg = new CardSpec { Name = "牺牲群伤", ClassName = "UiCheckSacAllUnitsDmg", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
			uvSacDmg.Effects.Add(new EffectSpec
			{
				Kind = "PetSacrifice", PetSacrificeGain = "Damage", PetSacrificeFormula = "Fixed", Amount = 5m,
				TargetSide = "AllUnits", PetSummon = "UiCheckSacAllUnitsPet",
			});
			uvSac.Cards.Add(uvSacDmg);
			Check("V0.2.200：校验器放行「牺牲伙伴 → 造成伤害 + 全体单位」（生成端真的按作用对象展开）",
				!ProfileValidator.Validate(uvSac).Any(i => i.IsError && i.Message.Contains("全体单位")),
				ProfileValidator.Validate(uvSac).FirstOrDefault(i => i.IsError)?.Message ?? "不报");
			uvSacDmg.Effects[0].PetSacrificeGain = "Block";
			Check("V0.2.200：（对照）牺牲伙伴收益=格挡时「全体单位」照旧报错拦住（那一档不读作用对象）",
				ProfileValidator.Validate(uvSac).Any(i => i.IsError && i.Message.Contains("全体单位")), "报错拦住了");

			// ---- 锻造节点图：这一档映射成【对象】里本来就有的 AllUnits（同一个运行时助手） ----
			Check("锻造节点图：「全体单位」映射到【对象】的 AllUnits 档（文案 + 生成一致）",
				ForgeGraphGen.TargetSideToPick("AllUnits") == "AllUnits"
				&& ForgeGraphGen.TargetSideToPick("AllAllies") == "AllAllies", "映射对");

			// ---- 自定义状态（能力）那条链：「全体单位」也要真的展开 ----
			// ⚠ 这条链上 base.Owner **本身就是 Creature**（不是 Player）—— 写死 base.Owner.Creature 会
			// CS1061（探针真编译踩到过一次），所以这里两条断言把「写对了 + 没写 .Creature」都钉住。
			CharacterProfile auraProfile = ProfileFactory.Sample();
			var auraPower = new CustomPowerSpec { Name = "自检全体单位光环", Type = "Buff" };
			var auraTrigger = new PowerTriggerSpec { Kind = "TurnStart" };
			auraTrigger.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 3m, TargetSide = "AllUnits" });
			auraTrigger.Effects.Add(new EffectSpec { Kind = "ApplyPower", Amount = 1m, TargetSide = "AllUnits", PowerId = "WeakPower" });
			auraTrigger.Effects.Add(new EffectSpec { Kind = "TempPower", Amount = 1m, TargetSide = "AllUnits", PowerId = "StrengthPower" });
			auraTrigger.Effects.Add(new EffectSpec { Kind = "Stun", Amount = 1m, TargetSide = "AllUnits" });
			auraTrigger.Effects.Add(new EffectSpec { Kind = "ClearPowerOne", Amount = 1m, TargetSide = "AllUnits", PowerId = "WeakPower" });
			auraPower.Triggers.Add(auraTrigger);
			auraProfile.CustomPowers.Add(auraPower);
			string auraSrc = CustomPowerGen.Source(auraProfile, auraPower, 0);
			Check("自定义状态链：「全体单位」展开成 `base.Owner.CombatState.Creatures`（状态钩子里 base.Owner 就是 Creature）",
				auraSrc.Contains("foreach (Creature other in base.Owner.CombatState.Creatures.Where(c => c.IsAlive).ToList())")
				&& auraSrc.Contains("foreach (Creature unit in base.Owner.CombatState.Creatures.Where(c => c.IsAlive).ToList())"),
				"展开了");
			Check("自定义状态链：击晕的「全体单位」从 player 取战斗状态（base.Owner.Player.Creature.CombatState）",
				auraSrc.Contains("foreach (Creature unit in base.Owner.Player.Creature.CombatState.Creatures.Where(c => c.IsAlive).ToList())"),
				"对");
			Check("（红线）自定义状态链上**从不**出现 `base.Owner.Creature`（那会 CS1061，探针真编译踩到过）",
				!auraSrc.Contains("base.Owner.Creature"), "没有");
			Check("校验器：自定义状态链上「格挡 + 全体单位」→ 报错（那条链的格挡是手写只打自己的）",
				ProfileValidator.Validate(new CharacterProfile
				{
					CustomPowers = { new CustomPowerSpec { Name = "自检越界光环", Type = "Buff", Triggers = { new PowerTriggerSpec { Kind = "TurnStart", Effects = { new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "AllUnits" } } } } } },
				}).Any(i => i.IsError && i.Message.Contains("全体单位")), "拦住了");

			// ---- B. 概率「不同效果之间是否独立」 ----
			// 默认（不勾）= 老行为：同组共用一次掷骰、各占区间
			CharacterProfile chp = ProfileFactory.Sample();
			var chpCard = new CardSpec { Name = "概率默认档", ClassName = "UiCheckChanceOld", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
			chpCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", ChanceEnabled = true, ChancePercent = 60m });
			chpCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", ChanceEnabled = true, ChancePercent = 30m });
			chp.Cards.Add(chpCard);
			string chOld = CSharpCodeGen.CardSource(chp, chpCard, 0);
			Check("（红线）概率默认档：仍是「共用一次掷骰 + 各占区间」（第一条 0~60、第二条 60~90）",
				chOld.Contains("概率生效：同组效果共用这一次掷骰") && chOld.Contains("__chanceRoll >= 0 && __chanceRoll < 60")
				&& chOld.Contains("__chanceRoll >= 60 && __chanceRoll < 90") && !chOld.Contains("ChanceIndependent"), "老写法");
			// 勾「独立」：这一条自己掷一次、不参与区间划分、并写回读标记
			chpCard.Effects[0].ChanceIndependent = true;
			chpCard.Effects[0].ChancePercent = 70m;
			string chNew = CSharpCodeGen.CardSource(chp, chpCard, 0);
			Check("勾「不同效果的概率各自独立判定」→ 这一条自己掷一次（NextDouble() * 100 < 70）",
				chNew.Contains("base.Owner.RunState.Rng.Niche.NextDouble() * 100.0 < 70"), "独立判一次");
			Check("独立的那一条**退出**区间划分，同组别的效果照旧占区间（60 起算）",
				!chNew.Contains("__chanceRoll >= 0 && __chanceRoll < 70") && chNew.Contains("__chanceRoll >= 0 && __chanceRoll < 30"), "退出了");
			Check("独立档写回读标记（只在勾了非默认档时才写）",
				chNew.Contains("// CET:ChanceIndependent=1 CET:ChancePct=70")
				&& !chOld.Contains("CET:ChanceIndependent"), "有标记");
			// 全部独立 → 不声明共用掷骰变量
			chpCard.Effects[1].ChanceIndependent = true;
			string chAllIndep = CSharpCodeGen.CardSource(chp, chpCard, 0);
			Check("全部勾独立时不声明 `__chanceRoll`（没有区间、没有公式就不需要它）",
				!chAllIndep.Contains("double __chanceRoll") && chAllIndep.Contains("NextDouble() * 100.0 < 70")
				&& chAllIndep.Contains("NextDouble() * 100.0 < 30"), "不声明");
			Check("校验器：勾了「独立」→ 提示说清和老行为（共用掷骰 / 互斥）的区别",
				ProfileValidator.Validate(chp).Any(i => i.Level == "提示" && i.Message.Contains("各自独立判定")), "提示了");
			chpCard.Effects[0].ChanceIndependent = false;
			chpCard.Effects[1].ChanceIndependent = false;

			// ---- 界面：卡牌链重排后「概率 + 是否独立 + 下回合生效」在卡牌链上、其余四条链一个字不变 ----
			var cardChain = new EffectSpec { Kind = "Damage", Amount = 5m, NextTurn = false, IsCardChain = true };
			var plainChain = new EffectSpec { Kind = "Damage", Amount = 5m, NextTurn = false };
			Check("卡牌链：新摆的「概率」「下回合生效」两行显示、老位置那两行收起",
				cardChain.ShowCardChanceRow && !cardChain.ShowPlainChanceRow && !cardChain.ShowPlainNextTurnRow
				&& cardChain.ShowCardTimesRow && !cardChain.ShowPlainFixedTimesBox, "重排生效");
			Check("（红线）遗物 / 药水 / 自定义状态 / 锻造链：还是老位置那两行（新摆的两行对它们恒为 Collapsed）",
				!plainChain.ShowCardChanceRow && !plainChain.ShowCardNextTurnRow && plainChain.ShowPlainChanceRow
				&& plainChain.ShowPlainFixedTimesBox && !plainChain.ShowCardTimesRow, "老样子");
			var drawChain = new EffectSpec { Kind = "Draw", Amount = 2m, TargetSide = "Self", IsCardChain = true };
			Check("卡牌链：用不到「命中次数」的种类（抽牌）那一行仍然收起（沿用原有按种类显隐规则）",
				!drawChain.ShowCardRepeatRow && !drawChain.ShowPlainFixedRepeatBox, "收起了");
			var dmgChain = new EffectSpec { Kind = "Damage", Amount = 5m, TargetSide = "Enemy", IsCardChain = true };
			Check("卡牌链：造成伤害时「命中次数」那一行（固定框 + 公式框）出现",
				dmgChain.ShowCardRepeatRow, "出现");
			Check("界面：卡牌效果编辑器里有「不同效果的概率各自独立判定」勾选框（绑 ChanceIndependent）",
				dmgChain.ChanceIndependent == false, "默认关");
			SelectTabRoot("卡牌");
			if (CardUiSelection is CardSpec { Effects.Count: > 0 }) CardEffectList.SelectedIndex = 0;
			UpdateLayout();
			var cardPageRoot = SelectTabRoot("卡牌");
			var pageChecks = new List<CheckBox>();
			CollectCheckBoxes(cardPageRoot, pageChecks);
			var pageCheckPaths = pageChecks.Select(c => BindingOperations.GetBinding(c, ToggleButton.IsCheckedProperty)?.Path?.Path).ToList();
			Check("界面（卡牌页）：效果编辑器里有「概率生效」「概率独立」「不包括召唤物」三个勾选框",
				pageCheckPaths.Contains("ChanceEnabled") && pageCheckPaths.Contains("ChanceIndependent")
				&& pageCheckPaths.Contains("AllAlliesExcludePets"), string.Join(" / ", pageCheckPaths));
			// ⚠ 判显隐必须看 IsVisible：Collapsed 的控件照样在可视化树里（老坑，见 QUEUE 里
			//「TextsIn 会把 Collapsed 里的文字也收进来」那条）—— 上面那几个绑定路径别的链也能收到。
			Check("界面（卡牌页）：「概率独立」那一行在卡牌链上**真的可见**",
				pageChecks.Any(c => BindingOperations.GetBinding(c, ToggleButton.IsCheckedProperty)?.Path?.Path == "ChanceIndependent" && c.IsVisible),
				"可见");
			var cardPageBoxes = new List<TextBox>();
			CollectTextBoxes(cardPageRoot, cardPageBoxes);
			var cardPageBoxPaths = cardPageBoxes.Select(b => BindingOperations.GetBinding(b, TextBox.TextProperty)?.Path?.Path).ToList();
			Check("界面（卡牌页）：命中次数 / 生效次数 / 概率 三格公式框都在（重排后没丢）",
				cardPageBoxPaths.Contains("RepeatFormula") && cardPageBoxPaths.Contains("TimesFormula")
				&& cardPageBoxPaths.Contains("ChanceFormula"), string.Join(" / ", cardPageBoxPaths.Distinct()));
			var relicPageRoot = SelectTabRoot("遗物");
			var relicChecks = new List<CheckBox>();
			CollectCheckBoxes(relicPageRoot, relicChecks);
			var relicChanceIndep = relicChecks
				.Where(c => BindingOperations.GetBinding(c, ToggleButton.IsCheckedProperty)?.Path?.Path == "ChanceIndependent")
				.ToList();
			// 看得见时把「它挂在哪条效果上 / 在哪块面板里」写出来，方便一眼看出是谁漏了清 IsCardChain。
			string ChanceIndepCulprit()
			{
				CheckBox? hit = relicChanceIndep.FirstOrDefault(c => c.IsVisible);
				if (hit is null) return "遗物页看不见";
				var names = new List<string>();
				for (DependencyObject? n = hit; n is not null && names.Count < 5; n = VisualTreeHelper.GetParent(n))
					if (n is FrameworkElement fe && !string.IsNullOrEmpty(fe.Name)) names.Add(fe.Name);
				var fx = hit.DataContext as EffectSpec;
				return "看见了 / 面板=" + string.Join("<", names)
					+ " / DataContext=" + (fx is null ? (hit.DataContext?.GetType().Name ?? "null") : $"{fx.Kind}(IsCardChain={fx.IsCardChain})")
					+ " / 当前遗物=" + (RelicUiSelection?.Name ?? "(null)");
			}
			Check("（红线）遗物页的效果编辑器里「概率独立」那一行是**收起的**（那一档只做在卡牌链上）",
				!relicChanceIndep.Any(c => c.IsVisible), ChanceIndepCulprit());
			SelectTabRoot("卡牌");

			// ---- 生成 → 回读：新档位（全体单位 / 全部友方不含召唤物）+ 概率独立全部还原 ----
			string tgRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02132_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				CharacterProfile rp = ProfileFactory.Sample();
				var rc = new CardSpec { Name = "回读新档位", ClassName = "UiCheckV02132", Cost = 1, CardType = "Attack", Rarity = "Common", InCardPool = true };
				rc.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "AllUnits" });
				rc.Effects.Add(new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "AllAllies", AllAlliesExcludePets = true });
				rc.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Enemy", ChanceEnabled = true, ChanceIndependent = true, ChancePercent = 70m });
				rp.Cards.Add(rc);
				rp.Paths.OutputDir = tgRoot;
				rp.Paths.VanillaProject = Profile.Paths.VanillaProject;
				rp.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var rgen = ModGenerator.Generate(rp);
				Check("（准备）带「全体单位 / 全部友方不含召唤物 / 概率独立」的存档能生成工程", rgen.Success,
					rgen.Success ? rgen.ProjectRoot : string.Join(" ｜ ", rgen.Issues.Where(x => x.IsError).Select(x => x.Message)));
				if (rgen.Success)
				{
					var rrec = ProjectRecovery.FromProject(rgen.ProjectRoot);
					CardSpec? rback = rrec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckV02132");
					Check("从工程恢复：作用对象「全体单位」认得回来（靠 CET:TargetSide=AllUnits）",
						rback is not null && rback.Effects.Count == 3 && rback.Effects[0].TargetSide == "AllUnits",
						rback is null ? "(缺卡)" : string.Join(" / ", rback.Effects.Select(x => x.TargetSide)));
					Check("从工程恢复：「全部友方 + 不包括召唤物」也认得回来（靠 CET:AllyNoPets=1）",
						rback is not null && rback.Effects.Count == 3 && rback.Effects[1].TargetSide == "AllAllies"
						&& rback.Effects[1].AllAlliesExcludePets,
						rback is null ? "(缺卡)" : $"TargetSide={rback.Effects[1].TargetSide} ExcludePets={rback.Effects[1].AllAlliesExcludePets}");
					Check("从工程恢复：概率「独立」+ 百分比认得回来（靠 CET:ChanceIndependent=1 CET:ChancePct=70）",
						rback is not null && rback.Effects.Count == 3 && rback.Effects[2].ChanceEnabled
						&& rback.Effects[2].ChanceIndependent && rback.Effects[2].ChancePercent == 70m,
						rback is null ? "(缺卡)" : $"Chance={rback.Effects[2].ChanceEnabled}/{rback.Effects[2].ChanceIndependent}/{rback.Effects[2].ChancePercent}");
					Check("从工程恢复（V0.2.132 新档位）：没认出来的语句为 0", !rrec.HasUnparsed,
						rrec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
			}
			finally
			{
				try { Directory.Delete(tgRoot, true); } catch { }
			}
		}
		// ===== V0.2.134：锻造节点图**能从工程恢复**（`// CET:ForgeGraph=` 标记）=====
		// 用户 2026-10-10 拍板要做这一版。自检覆盖整条闭环：
		//   图非空才写标记 → 从工程恢复出图 + IsForged → 逐字段还原 → 再生成一次逐字节一致；
		//   外加两条**不许静默**：版本不认识 / Base64 坏了必须报错说清；老工程（没标记）一条都不报。
		{
			string fgRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02134_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			string noGraphRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02134n_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			string recRoot134 = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02134r_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			string fgen1RootForProbe = "";
			try
			{
				// ⚠ 这一段刻意**不用 ProfileFactory.Sample()**：示例存档里有几张卡踩到「从工程恢复」的老口径
				// （延迟状态的作用对象 / 先古对话行数 / 升级增量那几处，V0.2.133 及以前就这样，与本版无关）——
				// 掺进来会让「两次生成逐字节一致」这条断言变成在测**那些老问题**，而不是测本版。
				// 自检要的是「图标记让往返不破」，所以起点是一份**干净的、只含本版关心的东西**的配置：
				//   · 一张锻造卡（升级前 + 升级后两块布，含【效果】模块的新编辑器 spec 与公式原文）；
				//   · 一张**图是空的**对照卡（标记一行都不该写）；
				//   · 三张卡（卡池奖励校验要求至少 3 张可用）。
				var fp = new CharacterProfile
				{
					ModId = "UiCheckForge134", ModDisplayName = "自检角色", CharacterClass = "UiCheckForge134",
					DisplayName = "自检角色", StartingHp = 80, StartingGold = 99,
					ForgeGraphPortVersion = ForgeGraphGen.PortVersion,
				};
				fp.Paths.OutputDir = fgRoot;
				fp.Paths.VanillaProject = Profile.Paths.VanillaProject;
				fp.Paths.GameDataDir = Profile.Paths.GameDataDir;
				// 【数值】里写公式要有个**认得的量**（不然校验器会正确地报「不是一个参数」）——
				// 顺带把「自定义参数也能跟着图一起从工程回来」这条也验到。
				fp.CustomParams.Add(new ParamSpec { Name = "M", Source = ParamSources.CurrentHp, Target = ParamTargets.Self });
				ForgeGraphSpec baseGraph = ForgeGraphProbeGraph("A");
				ForgeGraphSpec upGraph = ForgeGraphProbeGraph("B");
				var fc = new CardSpec
				{
					Name = "锻造图自检卡", ClassName = "UiCheckForgedCard", Cost = 0,
					CardType = "Attack", Rarity = "Common", InCardPool = true,
					IsForged = true, ForgeGraph = baseGraph, UpgradedForgeGraph = upGraph,
				};
				// 两块布的【效果】模块都走新编辑器那份 spec（EffectFromLegacy=false）：生成前桥会把它回写成老字段，
				// 所以它同时验到「spec 也进了标记、恢复后逐字段一样」。
				foreach (var g in new[] { baseGraph, upGraph })
				{
					ForgeNodeSpec? en = g.Nodes.FirstOrDefault(x => x.Kind == "Effect");
					if (en is null) continue;
					var spec = ForgeEffectBridge.Author(en);
					spec.Kind = "Damage";
					spec.ForgeAmountText = "9";
					spec.Amount = 9m;
					spec.TimesFormula = "2";
					en.EffectFromLegacy = false;
				}
				fp.Cards.Add(fc);
				// 对照卡：**没有图**（标记一行都不该写）
				var plain = new CardSpec { Name = "无图自检卡", ClassName = "UiCheckPlain134", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				plain.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
				fp.Cards.Add(plain);
				var plain2 = new CardSpec { Name = "无图自检卡乙", ClassName = "UiCheckPlain134B", CardType = "Attack", Rarity = "Uncommon", Cost = 1, InCardPool = true };
				plain2.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 7m, TargetSide = "Enemy" });
				fp.Cards.Add(plain2);

				// 「用户手上的存档」是**存过盘、再打开**过的（ProfileFactory.Load 会跑 Normalize / 老存档迁移，
				// 比如把卡牌那 5 种效果的固定数值迁成公式）。自检里这份是内存里现造的 ——
				// 先按真实路径落盘再读回来，两次生成的起点才真的一样（不然比的是两套不同的迁移结果）。
				Directory.CreateDirectory(recRoot134);
				string startPath = Path.Combine(recRoot134, "UiCheckForge134start.json");
				ProfileFactory.Save(fp, startPath);
				CharacterProfile start = ProfileFactory.Load(startPath);
				start.Paths.OutputDir = fgRoot;
				start.Paths.VanillaProject = Profile.Paths.VanillaProject;
				start.Paths.GameDataDir = Profile.Paths.GameDataDir;

				var fgen1 = ModGenerator.Generate(start);
				Check("（准备）带锻造节点图的存档能生成工程", fgen1.Success,
					fgen1.Success ? fgen1.ProjectRoot : string.Join(" ｜ ", fgen1.Issues.Where(x => x.IsError).Select(x => x.Message)));
				fgen1RootForProbe = fgen1.ProjectRoot;
				if (fgen1.Success)
				{
					string cardFile = Path.Combine(fgen1.ProjectRoot, "cs", "Cards", "UiCheckForgedCard.cs");
					string plainFile = Path.Combine(fgen1.ProjectRoot, "cs", "Cards", "UiCheckPlain134.cs");
					string cardText = File.Exists(cardFile) ? File.ReadAllText(cardFile) : "";
					Check("生成端：图非空的卡在 cs 里写了图标记（// CET:ForgeGraph=<版本>:<Base64>）",
						cardText.Contains("// CET:ForgeGraph=", StringComparison.Ordinal), "写了 " + ForgeGraphGen.MarkerVersion + " 版标记");
					Check("生成端：**图是空的条目一行标记都不写**（没有图的存档生成结果逐字节不变）",
						File.Exists(plainFile) && !File.ReadAllText(plainFile).Contains("CET:ForgeGraph", StringComparison.Ordinal), "无图卡里没有标记");
					Check("生成端：升级前 / 升级后两块布各一行标记（卡牌一共 2 行）",
						System.Text.RegularExpressions.Regex.Matches(cardText, "// CET:ForgeGraph=").Count == 2,
						System.Text.RegularExpressions.Regex.Matches(cardText, "// CET:ForgeGraph=").Count + " 行");

					// ---- 端到端往返：从工程恢复 ----
					RecoveryResult frec = ProjectRecovery.FromProject(fgen1.ProjectRoot);
					CardSpec? fback = frec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckForgedCard");
					Check("从工程恢复：锻造卡 IsForged 认回来（老版本这里是 false）",
						fback is not null && fback.IsForged, fback is null ? "(缺卡)" : "IsForged=" + fback.IsForged);
					Check("从工程恢复：ForgeGraph 非空（节点 / 连线数都对得上）",
						fback?.ForgeGraph is { IsEmpty: false } bg && bg.Nodes.Count == baseGraph.Nodes.Count && bg.Links.Count == baseGraph.Links.Count,
						fback?.ForgeGraph is null ? "(图是 null)" : $"{fback.ForgeGraph.Nodes.Count} 模块 / {fback.ForgeGraph.Links.Count} 连线");
					Check("从工程恢复：升级后那块布也认回来",
						fback?.UpgradedForgeGraph is { IsEmpty: false } ug && ug.Nodes.Count == upGraph.Nodes.Count,
						fback?.UpgradedForgeGraph is null ? "(升级后图是 null)" : fback.UpgradedForgeGraph.Nodes.Count + " 模块");
					// 逐字段对照（节点 Id / 种类 / 坐标 / 每个字段 / 连线 / EffectSpec / Note）——
					// 用和记录桥同一套 JSON 口径比，一处不同就返回那一处的说明。
					string diffBase = fback?.ForgeGraph is null ? "(缺图)" : ForgeGraphSpecDiff(baseGraph, fback.ForgeGraph);
					Check("从工程恢复：**逐字段**还原（节点 Id / 种类 / 坐标 / 每格 Fields / 连线 / EffectSpec / 备注，一处都不能差）",
						diffBase.Length == 0, diffBase.Length == 0 ? "全部逐字段一致" : diffBase);
					string diffUp = fback?.UpgradedForgeGraph is null ? "(缺升级后图)" : ForgeGraphSpecDiff(upGraph, fback.UpgradedForgeGraph);
					Check("从工程恢复：升级后那块布也逐字段一致", diffUp.Length == 0,
						diffUp.Length == 0 ? "全部逐字段一致"
						: diffUp + " ｜ 升级后 EffectSpec=" + System.Text.Json.JsonSerializer.Serialize(
							fback!.UpgradedForgeGraph!.Nodes.FirstOrDefault(n => n.Kind == "Effect")?.EffectSpec, ProfileFactory.JsonOpts));
					Check("从工程恢复：Restore 之后端口版本抬到当前值（不让 MigrateIfPorts 再迁一次、把 if 的是/否挪位）",
						frec.Profile.ForgeGraphPortVersion == ForgeGraphGen.PortVersion,
						"PortVersion=" + frec.Profile.ForgeGraphPortVersion);
					Check("从工程恢复（V0.2.134）：没认出来的语句为 0", !frec.HasUnparsed,
						frec.Unparsed.FirstOrDefault() ?? "全部认出来了");

					// ---- 用恢复出来的存档**再生成一次**，与第一次逐文件对拍（.sln 的 GUID 例外）----
					Directory.CreateDirectory(recRoot134);
					string recPath = Path.Combine(recRoot134, "UiCheckForge134.json");
					ProfileFactory.Save(frec.Profile, recPath);
					CharacterProfile refilled = ProfileFactory.Load(recPath);
					Check("恢复出来的存档：存一遍再读回来，图的端口版本 / 图本身都不变（不会一 Load 就被再迁一次）",
						refilled.ForgeGraphPortVersion == ForgeGraphGen.PortVersion
						&& refilled.Cards.FirstOrDefault(x => x.ClassName == "UiCheckForgedCard")?.ForgeGraph is { IsEmpty: false } rg2
						&& ForgeGraphSpecDiff(baseGraph, rg2).Length == 0,
						"PortVersion=" + refilled.ForgeGraphPortVersion);
					refilled.Paths.OutputDir = fgRoot;
					// 环境路径照旧从当前配置补（恢复出的存档里那份是模板带来的，自检里未必指向真工程）
					refilled.Paths.VanillaProject = Profile.Paths.VanillaProject;
					refilled.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var fgen2 = ModGenerator.Generate(refilled);
					Check("（准备）用恢复出来的存档再生成一次", fgen2.Success,
						fgen2.Success ? "成功" : string.Join(" ｜ ", fgen2.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (fgen2.Success)
					{
						var miss = new List<string>();
						int same = 0;
						foreach (string g1 in Directory.GetFiles(fgen1.ProjectRoot, "*", SearchOption.AllDirectories))
						{
							string rel = Path.GetRelativePath(fgen1.ProjectRoot, g1);
							string g2 = Path.Combine(fgen2.ProjectRoot, rel);
							if (!File.Exists(g2)) { miss.Add("第二次没有 " + rel); continue; }
							if (System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(g1))
								.AsSpan().SequenceEqual(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(g2)))) same++;
							else if (!rel.EndsWith(".sln", StringComparison.OrdinalIgnoreCase))
								miss.Add("内容不同 " + rel + FirstLineDiff(g1, g2));
						}
						Check("两次生成**逐文件对拍**：除了 .sln 的随机 GUID，全部逐字节一致（图的标记也一模一样）",
							miss.Count == 0, miss.Count == 0 ? $"逐字节一致 {same} 个文件" : string.Join("；", miss.Take(4)));
					}
				}

				// ---- 老工程（没有标记）：照旧，一条「没认出来」都不该多 ----
				CharacterProfile np = ProfileFactory.Sample();
				np.Paths.OutputDir = noGraphRoot;
				np.Paths.VanillaProject = Profile.Paths.VanillaProject;
				np.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var ngen = ModGenerator.Generate(np);
				Check("（准备）没有锻造图的存档能生成工程", ngen.Success, ngen.Success ? "成功" : "失败");
				if (ngen.Success)
				{
					RecoveryResult nrec = ProjectRecovery.FromProject(ngen.ProjectRoot);
					Check("老工程（没有图标记）→ 从工程恢复：一条图都没认回来、但**不是错误**（图空、其它字段照旧）",
						nrec.IsForged.Count == 0 && !nrec.HasUnparsed,
						$"图 {nrec.IsForged.Count} 张 / 没认出来 {nrec.Unparsed.Count} 条");
				}

				// ---- 标记坏了 / 版本不认识：必须说清，不许静默丢图 ----
				{
					string? problem;
					ForgeGraphGen.ReadMarker("// CET:ForgeGraph=99:AAAA", out problem);
					Check("标记版本不认识 → 说清是「更新的版本生成的」（不是静默当没看见）",
						problem is not null && problem.Contains("版本不认识", StringComparison.Ordinal), problem ?? "(没报错！)");
					ForgeGraphGen.ReadMarker("// CET:ForgeGraph=1:@@@@", out problem);
					Check("标记的 Base64 坏了 → 说清读不出来（不是静默丢图）",
						problem is not null && problem.Contains("读不出来", StringComparison.Ordinal), problem ?? "(没报错！)");
					// 真工程上验一遍：把一张卡那行标记的版本改成 99 → 恢复时必须报出来
					if (fgen1RootForProbe.Length > 0)
					{
						string brokenRoot = fgen1RootForProbe + "_broken";
						try
						{
							if (Directory.Exists(brokenRoot)) Directory.Delete(brokenRoot, true);
							CopyFolder(fgen1RootForProbe, brokenRoot);
							string bf = Path.Combine(brokenRoot, "cs", "Cards", "UiCheckForgedCard.cs");
							string bt = File.ReadAllText(bf);
							File.WriteAllText(bf, bt.Replace("// CET:ForgeGraph=1:", "// CET:ForgeGraph=99:"), new System.Text.UTF8Encoding(false));
							RecoveryResult brec = ProjectRecovery.FromProject(brokenRoot);
							Check("真工程里那行标记版本被改成 99 → 从工程恢复**报出来**（进「没认出来」清单）",
								brec.Unparsed.Any(x => x.Contains("版本不认识", StringComparison.Ordinal)),
								brec.Unparsed.FirstOrDefault() ?? "(没报错！)");
						}
						finally { try { if (Directory.Exists(brokenRoot)) Directory.Delete(brokenRoot, true); } catch { } }
					}
				}
			}
			finally
			{
				foreach (string d in new[] { fgRoot, noGraphRoot, recRoot134 })
					try { if (Directory.Exists(d)) Directory.Delete(d, true); } catch { }
			}
		}
		// ===== V0.2.169：卡牌链的「锻造图【触发时机】」和「这张牌自己的钩子」撞同一个方法名 =====
		// 用户实测报的：AinardiCard8 那张牌上既挂了锻造图的一块「这张牌被消耗时」，又有一条普通效果的
		// 「卡牌时机 = 被消耗」→ 生成出来是同一个类里**两个签名一样的 override** → CS0111，
		// 整个模组编译不过（他反复重建十几次都是同一条）。遗物那条链早就用「把图嵌进触发钩子」绕开了
		// （ForgeGraphGen.RelicGraphNestsInTrigger），卡牌这条现在照同一套办：
		// 图那一边生成私有方法 ForgeGraphOnXxx(choiceContext)，由那个钩子在末尾调用它。
		// 这里把三种撞法（被消耗 / 被保留 / 被抽到）都过一遍：既要「一个类里同名 override 只有一个」，
		// 也要「生成出来的东西回读得回来」（那句调用是胶水代码，靠 CET:ForgeNested 标记跳过）。
		{
			string clashRoot169 = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02169_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				var p169 = new CharacterProfile
				{
					ModId = "UiCheckClash169", ModDisplayName = "自检角色", CharacterClass = "UiCheckClash169",
					DisplayName = "自检角色", StartingHp = 80, StartingGold = 99,
					ForgeGraphPortVersion = ForgeGraphGen.PortVersion,
				};
				p169.Paths.OutputDir = clashRoot169;
				p169.Paths.VanillaProject = Profile.Paths.VanillaProject;
				p169.Paths.GameDataDir = Profile.Paths.GameDataDir;

				// 一张锻造卡：图上某一块【触发时机】+ 一条普通效果的「卡牌时机」= 同一个本体钩子
				CardSpec ClashCard(string cls, string timing, string effect, string subTiming, EffectSpec? extra = null)
				{
					var card = new CardSpec
					{
						Name = cls, ClassName = cls, Cost = 1, CardType = "Skill", Rarity = "Common",
						InCardPool = true, IsForged = true, ForgeGraph = new ForgeGraphSpec(),
					};
					var trig = new ForgeNodeSpec { Kind = "Trigger", X = 0, Y = 0 };
					trig.SetField("Timing", timing);
					var eff = new ForgeNodeSpec { Kind = "Effect", X = 300, Y = 0 };
					eff.SetField("Effect", effect);
					eff.SetField("Amount", "5");
					card.ForgeGraph.Nodes.Add(trig);
					card.ForgeGraph.Nodes.Add(eff);
					card.ForgeGraph.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id, FromPort = 0, ToPort = 0 });
					var timed = new EffectSpec { Kind = "Draw", Amount = 1m, TargetSide = "Self" };
					timed.Condition = new ConditionSpec { Kind = "CardTiming", Timing = subTiming };
					card.Effects.Add(timed);
					if (extra is not null) card.Effects.Add(extra);
					return card;
				}

				p169.Cards.Add(ClashCard("UiCheckClashExhaust", ForgeTimings.CardExhausted, "Damage", "Exhausted"));
				p169.Cards.Add(ClashCard("UiCheckClashRetain", ForgeTimings.CardRetained, "Block", "Retained"));
				p169.Cards.Add(ClashCard("UiCheckClashDrawn", ForgeTimings.CardDrawn, "Block", "Exhausted",
					new EffectSpec { Kind = "CheapenSelfOnDraw", Amount = 1m, TargetSide = "Self" }));
				var plain169 = new CardSpec { Name = "无图自检卡", ClassName = "UiCheckClashPlain169", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				plain169.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 7m, TargetSide = "Enemy" });
				p169.Cards.Add(plain169);
				// 顺手钉住「卡牌时机 = 失去生命时」这条：它的钩子是 AfterCurrentHpChanged，而
				// CSharpCodeGen.CardTimingMethodName 以前**漏了这一档** → 兜底返回 AfterCardExhausted，
				// 于是 ProjectRecovery 按方法名去找钩子方法体时会找**错的那个**（需求⑩ 的回读那条链）。
				var hpLost169 = new CardSpec { Name = "掉血自检卡", ClassName = "UiCheckHpLost169", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				var hpEff = new EffectSpec { Kind = "Draw", Amount = 2m, TargetSide = "Self" };
				hpEff.Condition = new ConditionSpec { Kind = "CardTiming", Timing = "HpLost" };
				hpLost169.Effects.Add(hpEff);
				p169.Cards.Add(hpLost169);

				var gen169 = ModGenerator.Generate(p169);
				Check("（准备）「图上时机 + 卡牌时机撞同一个钩子」的存档能生成工程", gen169.Success,
					gen169.Success ? gen169.ProjectRoot : string.Join(" ｜ ", gen169.Issues.Where(x => x.IsError).Select(x => x.Message)));
				if (gen169.Success)
				{
					// 一个类里**同名同参**的 override 只能有一个（不然就是 CS0111）。
					// 判据直接数生成出来的文本：`public override async Task <名字>(` 出现几次。
					int OverrideCount(string file, string name) =>
						System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(file),
							@"public override (?:async )?(?:Task|void) " + name + @"\(").Count;
					bool HasDupOverride(string file) =>
						System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(file),
							@"public override (?:async )?(?:Task|void) ([A-Za-z_]\w*)\(")
						.GroupBy(m => m.Groups[1].Value).Any(g => g.Count() > 1);

					string file169(string cls) => Path.Combine(gen169.ProjectRoot, "cs", "Cards", cls + ".cs");
					string exhaustText = File.Exists(file169("UiCheckClashExhaust")) ? File.ReadAllText(file169("UiCheckClashExhaust")) : "";
					string retainText = File.Exists(file169("UiCheckClashRetain")) ? File.ReadAllText(file169("UiCheckClashRetain")) : "";
					string drawnText = File.Exists(file169("UiCheckClashDrawn")) ? File.ReadAllText(file169("UiCheckClashDrawn")) : "";

					Check("锻造图「被消耗」+ 卡牌时机「被消耗」：AfterCardExhausted 只生成一个（不是 CS0111 的两个）",
						OverrideCount(file169("UiCheckClashExhaust"), "AfterCardExhausted") == 1,
						"实际 " + OverrideCount(file169("UiCheckClashExhaust"), "AfterCardExhausted") + " 个");
					Check("被消耗那一档：图变成私有方法 ForgeGraphOnAfterCardExhausted(choiceContext)，并在钩子里被调用",
						exhaustText.Contains("public async Task ForgeGraphOnAfterCardExhausted(PlayerChoiceContext choiceContext)", StringComparison.Ordinal)
						&& exhaustText.Contains("await ForgeGraphOnAfterCardExhausted(choiceContext)", StringComparison.Ordinal));
					Check("锻造图「被保留」+ 卡牌时机「被保留」：AfterFlush 只生成一个",
						OverrideCount(file169("UiCheckClashRetain"), "AfterFlush") == 1 && !HasDupOverride(file169("UiCheckClashRetain")),
						"AfterFlush " + OverrideCount(file169("UiCheckClashRetain"), "AfterFlush") + " 个");
					Check("锻造图「被抽到」+ 卡牌自带的 AfterCardDrawn（抽到时费用 -N）：只生成一个 AfterCardDrawn",
						OverrideCount(file169("UiCheckClashDrawn"), "AfterCardDrawn") == 1 && !HasDupOverride(file169("UiCheckClashDrawn")),
						"AfterCardDrawn " + OverrideCount(file169("UiCheckClashDrawn"), "AfterCardDrawn") + " 个");
					Check("三张撞车卡：任何一个类里都没有同名 override 重复", !HasDupOverride(file169("UiCheckClashExhaust"))
						&& !HasDupOverride(file169("UiCheckClashRetain")) && !HasDupOverride(file169("UiCheckClashDrawn")));

					// 回读：那句调用是胶水代码（CET:ForgeNested），不许被当成「没认出来的语句」，
					// 而且卡牌时机那条效果 + 图本身都要原样回来。
					RecoveryResult rec169 = ProjectRecovery.FromProject(gen169.ProjectRoot);
					var back169 = rec169.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckClashExhaust");
					Check("从工程恢复：撞车卡能认回来（图非空 + IsForged）",
						back169 is not null && back169.IsForged && back169.ForgeGraph is { IsEmpty: false },
						back169 is null ? "(缺卡)" : "IsForged=" + back169.IsForged);
					Check("从工程恢复：「撞车的那句调用」不算「没认出来的语句」（它带 CET:ForgeNested，整行跳过）",
						!rec169.HasUnparsed, rec169.Unparsed.FirstOrDefault() ?? "全部认出来了");
					Check("从工程恢复：卡牌时机「被消耗」那条效果认得回来（Condition=CardTiming/Exhausted）",
						back169 is not null && back169.Effects.Any(e => string.Equals(e.Condition?.Kind, "CardTiming", StringComparison.Ordinal)
							&& string.Equals(e.Condition!.Timing, "Exhausted", StringComparison.Ordinal)));
					var backHp169 = rec169.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckHpLost169");
					Check("从工程恢复：卡牌时机「失去生命时」也认得回来（钩子方法名是 AfterCurrentHpChanged —— "
						+ "CardTimingMethodName 以前漏了这一档，回读会去找 AfterCardExhausted 那个方法体）",
						backHp169 is not null && backHp169.Effects.Any(e => string.Equals(e.Condition?.Kind, "CardTiming", StringComparison.Ordinal)
							&& string.Equals(e.Condition!.Timing, "HpLost", StringComparison.Ordinal)),
						backHp169 is null ? "(缺卡)" : string.Join(" / ", backHp169.Effects.Select(e => e.Condition?.Kind + ":" + e.Condition?.Timing)));
				}
				// ---- 斩杀（Fatal）：条件只能挂在「打出时」那一段（V0.2.169 新增 ValidateFatalPlacement）----
				// 用户实测报的：AinardiCard13.cs(28,13) CS0103 __lastAttack / __fatalOk ——
				// 那两个变量只在 OnPlay 开头声明，而带「斩杀」的那条效果如果**不在 OnPlay 里发射**
				// （「抽到这张牌时费用 -N」→ AfterCardDrawn；「将此牌放回手牌」→ AfterCardPlayedLate），
				// 生成出来就是引用两个不存在的名字。语义上也没救（那两个钩子里没有「上一条攻击」），
				// 所以校验器直接报错拦住。探针 _probe\fatalcheck 里连「用户那种形状」都复现过。
				CardSpec FatalProbeCard(string cls, string hookOnlyKind)
				{
					var fc = new CardSpec { Name = cls, ClassName = cls, CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
					fc.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" });
					var f = new EffectSpec { Kind = hookOnlyKind, Amount = 1m, TargetSide = "Enemy" };
					f.Condition = new ConditionSpec { Kind = "Fatal" };
					fc.Effects.Add(f);
					return fc;
				}
				var vpDraw = new CharacterProfile { ModId = "UiCheckFatal169", CharacterClass = "UiCheckFatal169" };
				vpDraw.Cards.Add(FatalProbeCard("UiCheckFatalDraw", "CheapenSelfOnDraw"));
				var vIssuesDraw = ProfileValidator.Validate(vpDraw);
				Check("V0.2.169：伤害 + 斩杀挂在「抽到这张牌时费用 -N」上 → 校验器报错（生成端写在 AfterCardDrawn 里，引用不到 __lastAttack → CS0103）",
					vIssuesDraw.Any(i => i.Level == "错误" && i.Message.Contains("AfterCardDrawn")),
					vIssuesDraw.FirstOrDefault(i => i.Message.Contains("AfterCardDrawn"))?.Message ?? "(没报)");
				var vpReturn = new CharacterProfile { ModId = "UiCheckFatal169b", CharacterClass = "UiCheckFatal169b" };
				vpReturn.Cards.Add(FatalProbeCard("UiCheckFatalReturn", "ReturnSelfToHand"));
				var vIssuesReturn = ProfileValidator.Validate(vpReturn);
				Check("V0.2.169：伤害 + 斩杀挂在「将此牌放回手牌」上 → 校验器报错（实现在 AfterCardPlayedLate 里）",
					vIssuesReturn.Any(i => i.Level == "错误" && i.Message.Contains("AfterCardPlayedLate")),
					vIssuesReturn.FirstOrDefault(i => i.Message.Contains("AfterCardPlayedLate"))?.Message ?? "(没报)");
				var vpOk = new CharacterProfile { ModId = "UiCheckFatal169c", CharacterClass = "UiCheckFatal169c" };
				vpOk.Cards.Add(FatalProbeCard("UiCheckFatalOk", "Block"));
				var vIssuesOk = ProfileValidator.Validate(vpOk);
				Check("V0.2.169（不回归）：打出时的「伤害 + 斩杀」不报错（本体狂暴 / 贪婪之手那种合法档）",
					!vIssuesOk.Any(i => i.Level == "错误" && i.Message.Contains("斩杀")),
					vIssuesOk.FirstOrDefault(i => i.Level == "错误" && i.Message.Contains("斩杀"))?.Message ?? "(没报，对)");
			}
			catch (Exception ex) { Check("V0.2.169 撞车自检整段跑完", false, ex.Message); }
			finally { try { if (Directory.Exists(clashRoot169)) Directory.Delete(clashRoot169, true); } catch { } }
		}
		// ===== V0.2.169②：类名 → 本体 Entry 的换算必须和本体**逐字同源** =====
		// 用户实测（角色英文类名全大写 EVE）：在选人界面点他那个角色，抛
		//   LocException: Key=E_VE_RELIC1.title not found in table=relics
		//   at NCharacterSelectScreen.SelectCharacter(...)
		// → 选择流程中断、大厅里还是上一个角色（现象：「选人页看着是对的，选完变成其他角色」）。
		//
		// 真因：Naming.Slug() 以前自己写成「每个大写字母前都插一个下划线」，而本体那对正则
		//   ([A-Za-z0-9]|\G(?!^))([A-Z]) → "$1_$2"
		// 是**成对消费**的 —— 连续大写里每隔一个才插：EVERelic1 本体给 E_VE_RELIC1，旧实现给 E_V_E_RELIC1。
		// 只有「3 个以上连续大写」才露馅，所以 Anon / Vemiu / Seven / TachiShrimp 那些存档从来没撞到。
		{
			Check("V0.2.169②：类名→Entry 与本体算法逐字一致（EVERelic1 → E_VE_RELIC1，就是游戏查的那个键）",
				Naming.Slug("EVERelic1") == "E_VE_RELIC1", Naming.Slug("EVERelic1"));
			Check("V0.2.169②：同一形状的 ABCRelic1 → A_BC_RELIC1", Naming.Slug("ABCRelic1") == "A_BC_RELIC1", Naming.Slug("ABCRelic1"));
			Check("V0.2.169②：AIPet → A_I_PET（本体注释里点名的例子）", Naming.Slug("AIPet") == "A_I_PET", Naming.Slug("AIPet"));
			Check("V0.2.169②：EVE → E_V_E（角色自己的 Entry 没变，所以选人页一直是正常的）",
				Naming.Slug("EVE") == "E_V_E", Naming.Slug("EVE"));
			Check("V0.2.169②（红线）：常规驼峰命名的 Entry 一个都不变",
				Naming.Slug("AnonCard10") == "ANON_CARD10" && Naming.Slug("VemiuRelic1") == "VEMIU_RELIC1"
				&& Naming.Slug("SevenCrush") == "SEVEN_CRUSH" && Naming.Slug("TachiShrimpCard3") == "TACHI_SHRIMP_CARD3"
				&& Naming.Slug("WhiteCloakHeaven") == "WHITE_CLOAK_HEAVEN" && Naming.Slug("UIButton") == "U_I_BUTTON",
				Naming.Slug("AnonCard10") + " / " + Naming.Slug("VemiuRelic1") + " / " + Naming.Slug("SevenCrush"));

			// 端到端：类名全大写的存档 → 生成出来的 relics.json 里那个键必须是**游戏会查的那一个**
			var upper169 = new CharacterProfile { ModId = "UiCheckSlug169", CharacterClass = "EVE" };
			upper169.Relics.Add(new RelicSpec { Name = "自检遗物", Rarity = "Common" });
			string relicsJson169 = LocalizationGen.RelicsJson(upper169);
			Check("V0.2.169②：CharClass=EVE 的存档，relics.json 写的是 E_VE_RELIC1.title（不再是 E_V_E_RELIC1.title）",
				relicsJson169.Contains("E_VE_RELIC1.title", StringComparison.Ordinal)
				&& !relicsJson169.Contains("E_V_E_RELIC1", StringComparison.Ordinal),
				relicsJson169.Contains("E_VE_RELIC1.title", StringComparison.Ordinal)
					? "写对了" : relicsJson169.Substring(0, Math.Min(160, relicsJson169.Length)));
		}
		// ===== V0.2.180②：生成代码里引用**本体类型**必须写全名 =====
		// 用户实测两条编译错误：
		//   cs\Cards\TheShadowCard12.cs(36,53): error CS0104: "Void" 是 "…Cards.Void" 和 "void" 之间的不明确的引用
		//   cs\Patches.cs(121,54):             error CS8121: "Defect" 类型的模式无法处理 "CharacterModel" 类型的表达式
		// 真因：生成端引用本体卡 / 本体角色时**写的是短类名** —— 本体有一张卡就叫 Void（和 System.Void 撞），
		// 而 Patches.cs 那句「是不是本体角色」的 `is Ironclad or … or Defect or …` 会被本 mod 里任何同名类抢走
		//（本 mod 自己有个类叫 Defect 时，编译器就把 Defect 当模式类型 → CS8121）。
		// 修法：本体卡走 CSharpCodeGen.CardTypeExpr（一律全名），本体角色 / 卡池也一律写全名。
		{
			Check("V0.2.180②：本体卡写全名（Void → MegaCrit.Sts2.Core.Models.Cards.Void；留空 = Shiv）",
				CSharpCodeGen.CardTypeExpr(null, "Void") == "MegaCrit.Sts2.Core.Models.Cards.Void"
				&& CSharpCodeGen.CardTypeExpr(null, "") == "MegaCrit.Sts2.Core.Models.Cards.Shiv",
				CSharpCodeGen.CardTypeExpr(null, "Void"));
			var nqProbe = ProfileFactory.Sample();
			// 红线：**我们自己生成的卡**必须仍然写短名（同命名空间，加了前缀反而编译不过）
			var nqOwn = new CharacterProfile { ModId = "UiCheckNq", CharacterClass = "UiCheckNq" };
			nqOwn.Cards.Add(new CardSpec { Name = "自检自己的卡", ClassName = "UiCheckNqOwn", CardType = "Skill", Rarity = "Common", Cost = 1 });
			string nqCls = CSharpCodeGen.CardTypeExpr(nqOwn, "UiCheckNqOwn");
			Check("V0.2.180②（红线）：我们自己的卡仍然写短名（同一个命名空间，不加前缀）",
				nqCls == "UiCheckNqOwn", nqCls);
			string nqPatches = PatchesGen.PatchesSource(nqProbe);
			Check("V0.2.180②：Patches.cs 里本体角色判断那 6 个全是全名，且不再有裸的 `is Ironclad or` / `or Defect or`",
				nqPatches.Contains("MegaCrit.Sts2.Core.Models.Characters.Ironclad", StringComparison.Ordinal)
				&& nqPatches.Contains("MegaCrit.Sts2.Core.Models.Characters.Defect", StringComparison.Ordinal)
				&& !nqPatches.Contains("is Ironclad or", StringComparison.Ordinal)
				&& !nqPatches.Contains("or Defect or", StringComparison.Ordinal),
				"全名");
		}
		// ===== V0.2.200：锻造图「造成伤害」在**非卡牌档**不能调 FromCard =====
		// 用户实测「敌人回合开始时卡死」：栈是 AttackCommand.FromCard ← Gokuen.AfterSideTurnStart
		// ← Hook.AfterSideTurnStart ← CombatManager.StartTurn。本体 FromCard 的第一句就是
		// `Player owner = card.Owner;` —— 状态/遗物/药水档的图没有「这张牌」，以前照样拼
		// `.FromCard(null, null)` ⇒ 运行时 NRE ⇒ 回合循环死掉（战斗卡住，只能重开房间）。
		// 现在：非卡牌档**不调 FromCard**（源卡留空）；卡牌档照旧（红线：卡牌输出不变）。
		{
			ForgeGraphSpec FgDamageGraph(string timing)
			{
				var g = new ForgeGraphSpec();
				var trig = new ForgeNodeSpec { Kind = "Trigger", X = 0, Y = 0 };
				trig.SetField("Timing", timing);
				var eff = new ForgeNodeSpec { Kind = "Effect", X = 300, Y = 0 };
				eff.SetField("Effect", "Damage");
				eff.SetField("Amount", "9");
				g.Nodes.Add(trig);
				g.Nodes.Add(eff);
				g.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id, FromPort = 0, ToPort = 0 });
				return g;
			}
			var fgCardP = ProfileFactory.Sample();
			var fgCard = new CardSpec
			{
				Name = "自检锻造卡", ClassName = "UiCheckFgCard200", CardType = "Attack", Rarity = "Common", Cost = 1,
				InCardPool = true, IsForged = true, ForgeGraph = FgDamageGraph(ForgeTimings.CardPlayed),
			};
			fgCardP.Cards.Add(fgCard);
			string fgCardSrc = CSharpCodeGen.CardSource(fgCardP, fgCard, fgCardP.Cards.Count - 1);
			Check("V0.2.200（红线）：卡牌档的锻造图「造成伤害」仍然 .FromCard(this, cardPlay)",
				fgCardSrc.Contains(".FromCard(this, cardPlay)", StringComparison.Ordinal), "在");

			var fgPowP = ProfileFactory.Sample();
			var fgPow = new CustomPowerSpec
			{
				Name = "自检锻造状态", ClassName = "UiCheckFgPower200", Type = "Debuff", Enabled = true,
				ForgeGraph = FgDamageGraph(ForgeTimings.EnemyTurnStart),
			};
			fgPowP.CustomPowers.Add(fgPow);
			string fgPowSrc = CustomPowerGen.Source(fgPowP, fgPow, fgPowP.CustomPowers.Count - 1);
			Check("V0.2.200：状态档的锻造图「造成伤害」**不再调 FromCard**（以前传 null → 敌人回合开始 NRE → 战斗卡死）",
				fgPowSrc.Contains("DamageCmd.Attack(", StringComparison.Ordinal)
				&& !fgPowSrc.Contains(".FromCard(", StringComparison.Ordinal),
				fgPowSrc.Contains(".FromCard(", StringComparison.Ordinal) ? "还有 FromCard！" : "干净");
		}
		// ===== V0.2.201：锻造图里同一个【数值 / 能量】模块被**两个分支**各取一次 → CS0103 =====
		// 用户实测报的：`MimikyuCard52.cs(80,122): error CS0103: 当前上下文中不存在名称"__fgf73650"`。
		// 两个原因（都在 ForgeGraphGen，已修）：
		//   ① 声明是就地写进当前语句流的：`if` 真支里那句 `decimal __fgXXXX = …;` 出了大括号就没了，
		//      假支再取同一个模块时只拿到缓存里的**引用** → CS0103。
		//   ② 缓存键带出口序号（`#1`），回收时却返回 node.VarName（不带 p1）→ 出口 1 复用时名字对不上 → CS0103。
		{
			// 在生成的源码里按**大括号作用域**找「引用了、但自己这层和祖先层都没声明」的 __fgXXXXXX
			List<string> FgScopeProblems(string src)
			{
				var bad = new List<string>();
				var declRx = new System.Text.RegularExpressions.Regex(@"decimal (__fg\w+) =");
				var refRx = new System.Text.RegularExpressions.Regex(@"__fg[0-9a-f]{6}(p\d+)?");
				var scopes = new List<HashSet<string>> { new(StringComparer.Ordinal) };
				int depth = 0;
				bool inBody = false;
				foreach (string line in src.Split('\n'))
				{
					if (!inBody)
					{
						if (line.Contains("public async Task ForgeGraphOnPlay", StringComparison.Ordinal)) inBody = true;
						continue;
					}
					var own = new HashSet<string>(StringComparer.Ordinal);
					foreach (System.Text.RegularExpressions.Match m in declRx.Matches(line)) own.Add(m.Groups[1].Value);
					foreach (System.Text.RegularExpressions.Match m in refRx.Matches(line))
					{
						string n = m.Value;
						if (own.Contains(n)) continue;
						bool ok = false;
						foreach (var s in scopes) if (s.Contains(n)) { ok = true; break; }
						if (!ok && !bad.Contains(n)) bad.Add(n);
					}
					foreach (string n in own) scopes[^1].Add(n);
					foreach (char c in line)
					{
						if (c == '{') { depth++; if (scopes.Count <= depth) scopes.Add(new HashSet<string>(StringComparer.Ordinal)); }
						else if (c == '}')
						{
							if (scopes.Count > 1 && depth + 1 >= scopes.Count) scopes.RemoveAt(scopes.Count - 1);
							depth--;
							if (depth <= 0) return bad;
						}
					}
				}
				return bad;
			}
			string FgCardOf(ForgeGraphSpec g, string cls)
			{
				var prof = ProfileFactory.Sample();
				var c = new CardSpec
				{
					Name = cls, ClassName = cls, CardType = "Attack", Rarity = "Common", Cost = 1,
					InCardPool = true, IsForged = true, ForgeGraph = g,
				};
				prof.Cards.Add(c);
				return CSharpCodeGen.CardSource(prof, c, prof.Cards.Count - 1);
			}

			// ① 同一个【数值】模块：if 真支一张【造成伤害】、假支一张（两支共用同一个模块）
			{
				var g = new ForgeGraphSpec();
				var trig = new ForgeNodeSpec { Kind = "Trigger", X = 0, Y = 0 };
				trig.SetField("Timing", ForgeTimings.CardPlayed);
				var iff = new ForgeNodeSpec { Kind = "If", X = 200, Y = 0 };
				var val = new ForgeNodeSpec { Kind = "Value", X = 200, Y = 200 };
				val.SetField("Formula", "3");
				var t = new ForgeNodeSpec { Kind = "Effect", X = 400, Y = -120 };
				t.SetField("Effect", "Damage");
				var f = new ForgeNodeSpec { Kind = "Effect", X = 400, Y = 120 };
				f.SetField("Effect", "Damage");
				g.Nodes.Add(trig);
				g.Nodes.Add(iff);
				g.Nodes.Add(val);
				g.Nodes.Add(t);
				g.Nodes.Add(f);
				g.Links.Add(new ForgeLinkSpec { From = trig.Id, To = iff.Id, FromPort = 0, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = iff.Id, To = t.Id, FromPort = 0, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = iff.Id, To = f.Id, FromPort = 1, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = val.Id, To = t.Id, FromPort = 0, ToPort = 1 });
				g.Links.Add(new ForgeLinkSpec { From = val.Id, To = f.Id, FromPort = 0, ToPort = 1 });
				string src = FgCardOf(g, "UiCheckFgScope201");
				var bad = FgScopeProblems(src);
				Check("V0.2.201：同一个【数值】模块在 if 真支 / 假支各用一次 → 没有「引用了却没声明」的 __fgXXXXXX"
					+ "（以前假支直接引用真支里的局部变量 → CS0103，用户实测报的 MimikyuCard52）",
					bad.Count == 0, bad.Count == 0 ? "干净" : "没声明：" + string.Join(" / ", bad));
				int decls = System.Text.RegularExpressions.Regex.Matches(src, @"decimal __fg[0-9a-f]{6} = \(3m\);").Count;
				Check("V0.2.201：两个分支各声明一份（同名落在兄弟块里是合法 C#）", decls == 2, decls + " 处声明");
			}

			// ② 同一个【能量】模块的「额外资源量」出口（出口 1）在**同一个作用域**里被两张【造成伤害】各取一次
			{
				var g = new ForgeGraphSpec();
				var trig = new ForgeNodeSpec { Kind = "Trigger", X = 0, Y = 0 };
				trig.SetField("Timing", ForgeTimings.CardPlayed);
				var cond = new ForgeNodeSpec { Kind = "Condition", X = 200, Y = 0 };
				var energy = new ForgeNodeSpec { Kind = "Energy", X = 200, Y = 200 };
				var e1 = new ForgeNodeSpec { Kind = "Effect", X = 420, Y = -100 };
				e1.SetField("Effect", "Damage");
				var e2 = new ForgeNodeSpec { Kind = "Effect", X = 420, Y = 100 };
				e2.SetField("Effect", "Damage");
				g.Nodes.Add(trig);
				g.Nodes.Add(cond);
				g.Nodes.Add(energy);
				g.Nodes.Add(e1);
				g.Nodes.Add(e2);
				g.Links.Add(new ForgeLinkSpec { From = trig.Id, To = cond.Id, FromPort = 0, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = cond.Id, To = e1.Id, FromPort = 0, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = cond.Id, To = e2.Id, FromPort = 0, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = energy.Id, To = e1.Id, FromPort = 1, ToPort = 1 });
				g.Links.Add(new ForgeLinkSpec { From = energy.Id, To = e2.Id, FromPort = 1, ToPort = 1 });
				string src = FgCardOf(g, "UiCheckFgPort201");
				var bad = FgScopeProblems(src);
				Check("V0.2.201：同一个【能量】「额外资源量」出口用两处 → 两处都带 p1 后缀"
					+ "（以前第二次返回不带 p1 的名字 → CS0103）",
					bad.Count == 0
					&& System.Text.RegularExpressions.Regex.IsMatch(src, @"decimal __fg[0-9a-f]{6}p1 = __Y;")
					&& System.Text.RegularExpressions.Regex.Matches(src, @"Attack\(__fg[0-9a-f]{6}\)").Count == 0,
					bad.Count == 0 ? "带 p1" : "没声明：" + string.Join(" / ", bad));
			}

			// ③ 红线：一个模块只用一次的老写法，仍然只声明一次
			{
				var g = new ForgeGraphSpec();
				var trig = new ForgeNodeSpec { Kind = "Trigger", X = 0, Y = 0 };
				trig.SetField("Timing", ForgeTimings.CardPlayed);
				var val = new ForgeNodeSpec { Kind = "Value", X = 100, Y = 100 };
				val.SetField("Formula", "3");
				var eff = new ForgeNodeSpec { Kind = "Effect", X = 300, Y = 0 };
				eff.SetField("Effect", "Damage");
				g.Nodes.Add(trig);
				g.Nodes.Add(val);
				g.Nodes.Add(eff);
				g.Links.Add(new ForgeLinkSpec { From = trig.Id, To = eff.Id, FromPort = 0, ToPort = 0 });
				g.Links.Add(new ForgeLinkSpec { From = val.Id, To = eff.Id, FromPort = 0, ToPort = 1 });
				string src = FgCardOf(g, "UiCheckFgOnce201");
				int decls = System.Text.RegularExpressions.Regex.Matches(src, @"decimal __fg[0-9a-f]{6} = \(3m\);").Count;
				Check("V0.2.201（红线）：一个模块只用一次 → 仍然只声明一次（老存档生成文本不变）",
					decls == 1 && FgScopeProblems(src).Count == 0, decls + " 处声明");
			}
		}
		// ===== V0.2.137：高亮改成**用户自己填**（用户拍板 A，撤掉 V0.2.135 那套按钮 + 弹窗 + 汇总）=====
		// 用户原话：「自定义描述的高亮字段指的是把游戏本体中显示高亮的字符直接显示在生成器的升级后自定义描述中，
		// 让用户可以自己填。」→ 界面**不再**提供多选弹窗：本体那套写法 `{Damage:diff()}` 就是普通文字，
		// 用户在框里自己写。这一段钉三件事：
		//   ① 那套按钮 / 弹窗 / 汇总**真的从界面上消失了**（钉住「撤掉」这件事本身，别哪天被谁加回来）；
		//   ② 「填入参数…」给的就是**带 :diff() 的高亮写法**（用户要的「直接显示」落点就在这里）；
		//   ③ 校验器那两条**保留**（写了 :diff() 但字段不存在 → 错误；裸 {X} 不存在 → 警告；
		//     写了 :diff() 却整段没有 {} → 警告）—— 界面撤掉不等于校验放松。
		{
			// ① 撤掉的证据：卡牌页整棵可视树里再没有「高亮字段…」这个按钮 / 「已高亮 N 个字段」那行汇总
			SelectTabRoot("卡牌");
			UpdateLayout();
			DependencyObject hlRoot = FindTab("卡牌").Content as DependencyObject ?? this;
			var hlButtons = new List<Button>();
			CollectButtons(hlRoot, hlButtons);
			Check("① 卡牌页上**没有**「高亮字段…」按钮了（V0.2.137 按用户要求撤掉弹窗多选）",
				!hlButtons.Any(b => (b.Content as string ?? "").Contains("高亮字段", StringComparison.Ordinal)),
				"按钮：" + string.Join(" / ", hlButtons.Select(b => b.Content as string).Where(t => !string.IsNullOrWhiteSpace(t)).Take(12)));
			Check("① 也没有那行「已高亮 N 个字段」的实时汇总（按钮和汇总一起撤）",
				!TextsIn(hlRoot).Any(t => t.Contains("已高亮", StringComparison.Ordinal)
					|| (t.Contains("这段里没有 {} 占位符", StringComparison.Ordinal) && t.Contains("高亮用不上", StringComparison.Ordinal))),
				"没有汇总行");
			Check("① 改成了**写在界面上的说明**：这一段里直接写 {Damage:diff()} 就高亮、写 {Damage} 就普通色",
				TextsIn(hlRoot).Any(t => t.Contains("{Damage:diff()}", StringComparison.Ordinal)
					&& t.Contains("普通颜色", StringComparison.Ordinal)),
				TextsIn(hlRoot).FirstOrDefault(t => t.Contains("{Damage:diff()}", StringComparison.Ordinal)) ?? "(没找到说明)");

			// ② 「填入参数…」的候选：卡牌给的就是**带 :diff() 的写法**（用户要的「直接显示 + 自己填」）
			var hlCard = new CardSpec { Name = "高亮自检卡", ClassName = "UiHighlightCard", CardType = "Attack", Rarity = "Common", Cost = 1 };
			hlCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" });
			hlCard.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, TargetSide = "Self" });
			var hlHints = CSharpCodeGen.ParamHints(hlCard.Effects, isCard: true);
			Check("②「填入参数…」给卡牌的就是带 :diff() 的高亮写法（{Damage:diff()} / {Block:diff()}，带中文效果名）",
				hlHints.Any(x => x.Token == "{Damage:diff()}") && hlHints.Any(x => x.Token == "{Block:diff()}")
				&& hlHints.All(x => x.Token.EndsWith(":diff()}", StringComparison.Ordinal)),
				string.Join("、", hlHints.Select(x => x.Token + "（" + x.Desc + "）")));
			Check("②（对照）遗物 / 药水（不能升级）给的是**不带 :diff()** 的普通写法",
				CSharpCodeGen.ParamHints(hlCard.Effects, isCard: false).All(x => x.Token == "{Damage}" || x.Token == "{Block}"),
				string.Join("、", CSharpCodeGen.ParamHints(hlCard.Effects, isCard: false).Select(x => x.Token)));
			Check("② 候选粒度 = 每一条效果各自声明的变量（没有变量的效果不出现在列表里）",
				CSharpCodeGen.ParamHints(new[] { new EffectSpec { Kind = "Stun" } }, isCard: true).Count == 0, "没有可高亮的字段");
			// 纯文本改写工具还在（HighlightDiffText，本轮不再被界面调用，但注释里说明了保留理由）；
			// 「用户自己手写的 {X:diff()} 原样留在正文里、回读 / 生成一个字节都不改」由进程内往返钉住：
			{
				CharacterProfile hlRt = ProfileFactory.Sample();
				var hlRtCard = new CardSpec { Name = "高亮往返卡", ClassName = "UiHighlightRt", CardType = "Attack", Rarity = "Common", Cost = 1 };
				hlRtCard.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" });
				hlRtCard.UpgradedCustomDescription = "造成 {Damage:diff()} 点伤害。";
				hlRt.Cards.Add(hlRtCard);
				string hlJson = System.Text.Json.JsonSerializer.Serialize(hlRt, ProfileFactory.JsonOpts);
				CharacterProfile hlBack = System.Text.Json.JsonSerializer.Deserialize<CharacterProfile>(hlJson, ProfileFactory.JsonOpts)!;
				Check("② 用户手写的 {Damage:diff()} 存 / 读一圈**逐字不变**（高亮就是正文的一部分，不加任何新标记）",
					hlBack.Cards.First(c => c.ClassName == "UiHighlightRt").UpgradedCustomDescription == "造成 {Damage:diff()} 点伤害。",
					hlBack.Cards.First(c => c.ClassName == "UiHighlightRt").UpgradedCustomDescription);
				Check("② 生成端把这些占位符原样写进 cards.json（不做任何转义 / 改写）",
					CSharpCodeGen.CardSource(hlRt, hlRtCard, 0).Length > 0
					&& LocalizationGen.CardsJson(hlRt).Contains("{Damage:diff()}", StringComparison.Ordinal),
					"cards.json 里原样带着 {Damage:diff()}");
			}

			// ③ 校验器那两条**保留**（界面撤掉 ≠ 校验放松）
			CharacterProfile hlProf = ProfileFactory.Sample();
			var hlBad = new CardSpec { Name = "高亮校验卡", ClassName = "UiHighlightValidate", CardType = "Attack", Rarity = "Common", Cost = 1 };
			hlBad.Effects.Add(new EffectSpec { Kind = "HpLoss", Amount = 3m, TargetSide = "Self" });
			hlBad.UpgradedCustomDescription = "失去 {Value:diff()} 点生命。";
			hlProf.Cards.Add(hlBad);
			var hlIssues = ProfileValidator.Validate(hlProf);
			Check("③ 校验器（保留）：{Value:diff()} 这张牌没声明过 → **错误**，且文案里点名是哪张牌",
				hlIssues.Any(i => i.IsError && i.Message.Contains("高亮校验卡", StringComparison.Ordinal)
					&& i.Message.Contains("没有声明过", StringComparison.Ordinal)
					&& i.Message.Contains("{Value:diff()}", StringComparison.Ordinal)),
				hlIssues.FirstOrDefault(i => i.IsError && i.Message.Contains("高亮校验卡", StringComparison.Ordinal))?.Message ?? "(没报错！)");
			Check("③ 校验器（保留）：这张牌真的声明过的变量（{HpLoss:diff()}）不误报",
				!hlIssues.Any(i => i.IsError && i.Message.Contains("{HpLoss:diff()}", StringComparison.Ordinal)), "没误报");
			// 写了 :diff() 却一个 {} 占位符都没有 → 警告说清「请先点『填入参数…』」
			// （用户现场就是这种：纯中文 + 直接写死的数字）
			CharacterProfile hlNoPhProf = ProfileFactory.Sample();
			var hlNoPh = new CardSpec { Name = "高亮无占位卡", ClassName = "UiHighlightNoPh", CardType = "Attack", Rarity = "Common", Cost = 1 };
			hlNoPh.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, TargetSide = "Enemy" });
			hlNoPh.UpgradedCustomDescription = "对指定敌人造成 4 点伤害。";
			hlNoPhProf.Cards.Add(hlNoPh);
			Check("③（对照）没写 :diff() 的纯数字描述不会报警告（老存档零噪音）",
				!ProfileValidator.Validate(hlNoPhProf).Any(i => i.Message.Contains("高亮不会生效", StringComparison.Ordinal)), "没噪音");
			hlNoPh.UpgradedCustomDescription = "对指定敌人造成 4 点伤害（Damage:diff() 是空写的）。";
			Check("③ 校验器（保留）：写了 :diff() 却一个 {} 占位符都没有 → 警告说清「请先点『填入参数…』」",
				ProfileValidator.Validate(hlNoPhProf).Any(i => i.Level == "警告" && i.Message.Contains("高亮不会生效", StringComparison.Ordinal)
					&& i.Message.Contains("填入参数", StringComparison.Ordinal)),
				ProfileValidator.Validate(hlNoPhProf).FirstOrDefault(i => i.Message.Contains("高亮不会生效", StringComparison.Ordinal))?.Message ?? "(没报错！)");
		}
		// ===== V0.2.137（红线⑧）：CLI 的 `--build` **不给 `--install` 时绝不安装** =====
		// 根因：CLI 里写的是 `ModBuilder.Build(..., installDir ?? profile.Paths.InstallDir, ...)` ——
		// 不给 `--install` 时会退回用**存档里**的 InstallDir（那个字段是给图形界面用的），于是
		// 「只想编译一下」的探针把模组真的装进了存档里写着的游戏 mods 目录（V0.2.135 / V0.2.137 各一次）。
		// 这一条是**回归护栏**：真正把行为钉死的是 CLI 的 `--buildcheck`（构建前后数一遍陷阱目录）；
		// 这里再补两道静态检查，谁把兜底写回去就会当场 FAIL。
		{
			var cliChk = CheckCliNeverInstallsImplicitly();
			Check("⑧ CLI 的 --build 不给 --install 时**绝不安装**（源码里没有 `installDir ?? profile.Paths.InstallDir` 兜底、installDir 直接透传）",
				cliChk.Ok, cliChk.Detail + (cliChk.ContractOnly ? "（本次只验到契约层）" : ""));
			var guiChk = CheckGuiInstallIsExplicit();
			Check("⑧ 图形界面侧「装不装」是用户点的：`install ? text : null` 那道闸在、且透传进 ModBuilder（不许硬装 Paths.InstallDir）",
				guiChk.Ok, guiChk.Detail);
		}
		// ===== V0.2.136：升级后获得 / 失去**自定义关键词**（需求《卡牌页优化.md》②④）=====
		// 机制事实（预研已核实）：本体 CardKeyword 是封闭枚举、模组加不了新值，自定义关键词本来就是
		// 「卡面那行 [gold]名字[/gold]。+ ExtraHoverTips 覆写 + card_keywords 本地化键」拼出来的**显示等价物**，
		// 游戏侧没有任何按它判定的逻辑 —— 所以这两栏**只影响显示**。自检把整条闭环钉住：
		//   描述那行用 {IfUpgraded:show:升级后|没升级} 包（顺序不能反）→ ExtraHoverTips 按 base.IsUpgraded 条件加
		//   → 回读标记 → 校验器（引用不存在=错误 / 升不了级的牌=提示）→ **没填那两栏的老形状逐字节不变**。
		{
			string ukwRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02136_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			string ukwBase = Path.Combine(Path.GetTempPath(), "forge_uicheck_v02136b_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				// ⚠ 这一段刻意**不用 ProfileFactory.Sample()** 当主体：示例存档里有几张卡踩到「从工程恢复」的老口径
				// （`ApplyPower` 的升级增量会被回读端多算一次、延迟状态的作用对象、先古对话行数…，V0.2.133 及以前
				// 就这样，与本版无关）—— 掺进来会让「恢复后再生成逐字节一致」这条断言变成在测**那些老问题**，
				// 而不是测本版。所以起点是一份**干净的、只含本版关心的东西**的配置（和 V0.2.134 那段同一个取舍）：
				//   · 一张「升级后获得 + 失去 + 一直在」的卡；两张对照卡（凑够卡池 3 张）；
				//   · 一张诅咒（升不了级的那条提示 + 标记照写）。
				var vp136 = new CharacterProfile
				{
					ModId = "UiCheckKw136", ModDisplayName = "自检角色136", CharacterClass = "UiCheckKw136",
					DisplayName = "自检角色136", StartingHp = 80, StartingGold = 99,
				};
				vp136.CustomKeywords.Clear();
				vp136.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命定", Description = "自检用·命定" });
				vp136.CustomKeywords.Add(new CustomKeywordSpec { Key = "ECHO", Name = "回声", Description = "自检用·回声" });
				vp136.CustomKeywords.Add(new CustomKeywordSpec { Key = "VOID", Name = "虚空", Description = "自检用·虚空" });

				// ① 获得 + 失去 + 一直在（三栏都填：验顺序与两段分叉）；再带一条**数值也升级**的效果，
				//    这样「升级增量回读」那条老路也被覆盖到（老形状的老问题不会混进来）
				//
				// V0.2.177：卡面上**两个**词 —— ECHO（一直在）、FATE（升级后获得）。再加一条**升级后失去**的
				// 作为对照：它不勾在「一直在」里，所以卡面上本来就没这一行，**但它照样会被写进
				// ExtraHoverTips 的「没升级」那段**（生成端那一组是按「失去」栏算的，不看它有没有勾在一直那栏）
				// —— 升级后那段必须把它丢掉，这正是用户报的「升级后失去关键词不生效」。
				// （以前这条**没有任何断言盯着**：upDel 算出来一个字没用、升级后悬停说明还在，就是这么漏过去的。）
				// ⚠ VOID **不能**同时勾在「一直在」里：那样「描述」和「悬停说明」两处会各自按不同口径处理
				// （描述以「失去」为准、说明以「一直在」为准），而且回读端本来就会把「失去」那栏的键从
				// KeywordIds 里摘掉 → 幂等会破。用户这么勾时校验器会给提示（见 ProfileValidator）。
				var ukwAdd = new CardSpec { Name = "升获自检卡", ClassName = "UiCheckKwAdd", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				ukwAdd.Effects.Add(new EffectSpec { Kind = "Draw", Amount = 2m, UpgradeAmount = 1m, TargetSide = "Self" });
				ukwAdd.KeywordIds = new List<string> { "ECHO" };
				ukwAdd.UpgradeAddedCustomKeywords = new List<string> { "FATE" };
				ukwAdd.UpgradeRemovedCustomKeywords = new List<string> { "VOID" };
				vp136.Cards.Add(ukwAdd);
				// ② 两栏一个都没填（老形状：走老路径，产物必须逐字节不变）+ ③ 凑够卡池 3 张
				// 用 EffectSpec.Amount=5 / UpgradeAmount=3（不给 UpgradedCustomDescription）：
				// 卡面文案按 {Block:diff()} 出，升级前后**只有关键词那行**不一样 —— 这样这条断言测的就是本版的关键词分叉。
				var ukwPlain = new CardSpec { Name = "升获自检对照卡", ClassName = "UiCheckKwPlain", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				ukwPlain.Effects.Add(new EffectSpec { Kind = "Block", Amount = 5m, UpgradeAmount = 3m, TargetSide = "Self" });
				vp136.Cards.Add(ukwPlain);
				var ukwFiller = new CardSpec { Name = "升获自检填充卡", ClassName = "UiCheckKwFiller", CardType = "Attack", Rarity = "Common", Cost = 1, InCardPool = true };
				ukwFiller.Effects.Add(new EffectSpec { Kind = "Damage", Amount = 6m, UpgradeAmount = 0m, TargetSide = "Enemy" });
				vp136.Cards.Add(ukwFiller);
				// ④ 诅咒：升不了级（校验器要提示，且**照样要写标记** —— 不写会让回读把关键词搬错栏）
				var ukwCurse = new CardSpec { Name = "升获自检诅咒", ClassName = "UiCheckKwCurse", CardType = "Curse", Rarity = "Curse", Cost = -1, InCardPool = false };
				ukwCurse.UpgradeAddedCustomKeywords = new List<string> { "ECHO" };
				vp136.Curses.Add(ukwCurse);

				vp136.Paths.OutputDir = ukwRoot;
				vp136.Paths.VanillaProject = Profile.Paths.VanillaProject;
				vp136.Paths.GameDataDir = Profile.Paths.GameDataDir;
				// 先落盘再读回来：真实用户手上的存档就是「存过、再打开」的（ProfileFactory.Load 会跑 Normalize）
				string ukwStart = Path.Combine(ukwRoot, "UiCheckKw136start.json");
				Directory.CreateDirectory(ukwRoot);
				ProfileFactory.Save(vp136, ukwStart);
				CharacterProfile ukwRun = ProfileFactory.Load(ukwStart);
				ukwRun.Paths.OutputDir = ukwRoot;
				ukwRun.Paths.VanillaProject = Profile.Paths.VanillaProject;
				ukwRun.Paths.GameDataDir = Profile.Paths.GameDataDir;

				var ukwGen = ModGenerator.Generate(ukwRun);
				Check("（准备）带「升级后获得 / 失去自定义关键词」的存档能生成工程", ukwGen.Success,
					ukwGen.Success ? ukwGen.ProjectRoot : string.Join(" ｜ ", ukwGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
				if (ukwGen.Success)
				{
					string cardsJson = File.ReadAllText(Path.Combine(ukwGen.ProjectRoot, "UiCheckKw136", "localization", "zhs", "cards.json"));
					string descAdd = LineValue(cardsJson, "\"UI_CHECK_KW_ADD.description\": \"");
					Check("生成端：描述里两段都用本体的 {IfUpgraded:show:…|…} 包起来（只有一个词在两段之间变也要包）",
						descAdd.StartsWith("{IfUpgraded:show:", StringComparison.Ordinal), descAdd);
					Check("生成端：**顺序不能反** —— `show:` 后面第一段是「升级后」：普通词 + 升级后获得的都在里面",
						descAdd.Contains("show:[gold]回声[/gold]。\\n[gold]命定[/gold]。", StringComparison.Ordinal),
						descAdd);
					Check("生成端：`|` 后面那段是「没升级」：普通词 + 升级后失去的都在里面",
						descAdd.Contains("|[gold]回声[/gold]。\\n[gold]虚空[/gold]。", StringComparison.Ordinal), descAdd);
					Check("生成端：升级后**获得的**那一行只出现在「升级后」那段（没升级那段里不许有）",
						descAdd.IndexOf("[gold]命定[/gold]。", StringComparison.Ordinal)
							< descAdd.IndexOf('|'), "命定在 | 之前");
					Check("生成端：升级后**失去的**那一行只出现在「没升级」那段",
						descAdd.IndexOf("[gold]虚空[/gold]。", StringComparison.Ordinal)
							> descAdd.IndexOf('|'), "虚空在 | 之后");
					string descPlain = LineValue(cardsJson, "\"UI_CHECK_KW_PLAIN.description\": \"");
					Check("生成端：**没填那两栏的卡**描述里一个 {IfUpgraded 都没有（老形状逐字节不变的口径）",
						!descPlain.Contains("{IfUpgraded", StringComparison.Ordinal), descPlain);
					string descFiller = LineValue(cardsJson, "\"UI_CHECK_KW_FILLER.description\": \"");
					Check("（对照）数值靠 {…:diff()} 自己变的卡描述本来就不一样：没有关键词分叉时**不**多包一层 {IfUpgraded}",
						!descFiller.Contains("{IfUpgraded", StringComparison.Ordinal) && descFiller.Contains("{Damage:diff()}", StringComparison.Ordinal),
						descFiller);

					string addSrc = File.ReadAllText(Path.Combine(ukwGen.ProjectRoot, "cs", "Cards", "UiCheckKwAdd.cs"));
					Check("生成端：标记只写非空的那一栏、两个标记**各自一行**（同一行会被贪婪匹配吃串）",
						addSrc.Contains("// CET:UpgradeKeywordAdd=FATE", StringComparison.Ordinal)
						&& addSrc.Contains("// CET:UpgradeKeywordRemove=VOID", StringComparison.Ordinal),
						"两行都在");
					Check("生成端：ExtraHoverTips 按 base.IsUpgraded 条件加/不加那条（升级后才有的关键词只出现在升级后）",
						addSrc.Contains("..(base.IsUpgraded ? new MegaCrit.Sts2.Core.HoverTips.IHoverTip[]", StringComparison.Ordinal)
						&& addSrc.Contains("base.IsUpgraded ? new MegaCrit.Sts2.Core.HoverTips.IHoverTip[]", StringComparison.Ordinal),
						"条件展开写了");
					Check("生成端：条件里既包含**升级后获得的**也包含**一直在的**（升级后两者都该显示）",
						addSrc.Contains("\"FATE.title\"", StringComparison.Ordinal)
						&& addSrc.Contains("\"ECHO.title\"", StringComparison.Ordinal), "FATE + ECHO 都在");
					// V0.2.177：悬停说明那一半的「升级后失去」（用户报的「升级后失去关键词不生效」）。
					// 断言必须分辨「升级后那段」和「一直在那段」—— 光看整个文件里有几个 VOID 是没用的
					// （VOID 本来就该在「没升级」那段里出现一次，以前是升级后那段也多了一次，两次都数得出来）。
					string upArray = addSrc.Substring(addSrc.IndexOf("base.IsUpgraded ? new", StringComparison.Ordinal));
					upArray = upArray.Substring(0, upArray.IndexOf("Array.Empty", StringComparison.Ordinal));
					Check("生成端：升级后那段里**没有**「升级后失去的」那条（悬停说明也要真的丢掉，不只是卡面那行字）",
						!upArray.Contains("\"VOID.title\"", StringComparison.Ordinal), "升级后那段里没有 VOID");
					Check("生成端：「升级后失去的」那条在**没升级**那段里还在（不该被一起抹掉）",
						addSrc.Contains("\"VOID.title\"", StringComparison.Ordinal), "没升级那段里还有 VOID");
					Check("生成端：升级后那段不是空的（FATE 在里面）—— 免得上面的断言靠「整段被清空」蒙过去",
						upArray.Contains("\"FATE.title\"", StringComparison.Ordinal), "FATE 在升级后那段里");
					// 卡面那半截对同一条要有一致的行为：升级后那段里也不能有「失去的」那一行
					int barIdx = descAdd.IndexOf('|');
					Check("生成端：卡面描述里升级后那段也**没有**「升级后失去的」那一行（描述 ⇄ 悬停说明两处口径一致）",
						barIdx >= 0 && descAdd.IndexOf("[gold]虚空[/gold]。", StringComparison.Ordinal) > barIdx, "虚空只在 | 之后");
					string plainSrc = File.ReadAllText(Path.Combine(ukwGen.ProjectRoot, "cs", "Cards", "UiCheckKwPlain.cs"));
					Check("生成端：没填这两栏的卡**一个字节都没变** —— ExtraHoverTips 还是老写法（`=> [ … ]`，没有条件展开）",
						!plainSrc.Contains("base.IsUpgraded ? new MegaCrit.Sts2.Core.HoverTips.IHoverTip[]", StringComparison.Ordinal)
						&& !plainSrc.Contains("CET:UpgradeKeyword", StringComparison.Ordinal), "老路径");
					string curseSrc = File.ReadAllText(Path.Combine(ukwGen.ProjectRoot, "cs", "Cards", "UiCheckKwCurse.cs"));
					Check("生成端：升不了级的牌（诅咒）也照写标记（不写会让回读把关键词搬到普通那一栏）",
						curseSrc.Contains("// CET:UpgradeKeywordAdd=ECHO", StringComparison.Ordinal), "诅咒里也有标记");

					// ---- 回读：标记 → 两栏；ExtraHoverTips 那两条不算「一直都有」----
					RecoveryResult ukwRec = ProjectRecovery.FromProject(ukwGen.ProjectRoot);
					CardSpec? r1 = ukwRec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckKwAdd");
					Check("回读：升级后获得 / 失去两栏逐项还原",
						r1 is not null
						&& r1.UpgradeAddedCustomKeywords.SequenceEqual(new[] { "FATE" })
						&& r1.UpgradeRemovedCustomKeywords.SequenceEqual(new[] { "VOID" }),
						r1 is null ? "(缺卡)" : $"+[{string.Join(",", r1.UpgradeAddedCustomKeywords)}] -[{string.Join(",", r1.UpgradeRemovedCustomKeywords)}]");
					Check("回读：**一直都有**的那个词没被那两栏的标记带跑（KeywordIds 里只剩 ECHO）",
						r1 is not null && r1.KeywordIds.SequenceEqual(new[] { "ECHO" }),
						r1 is null ? "(缺卡)" : string.Join(",", r1.KeywordIds));
					CardSpec? r2 = ukwRec.Profile.Cards.FirstOrDefault(x => x.ClassName == "UiCheckKwPlain");
					Check("回读：没填这两栏的卡，两栏保持空",
						r2 is not null && r2.UpgradeAddedCustomKeywords.Count == 0 && r2.UpgradeRemovedCustomKeywords.Count == 0, "两栏都空");
					Check("回读：回读端没多出「没认出来」的语句", !ukwRec.HasUnparsed, ukwRec.Unparsed.FirstOrDefault() ?? "全部认出来了");

					// ---- 恢复出来的存档再生成一次：逐字节不变（证明两栏是幂等的、不会越生成越多）----
					string recPath136 = Path.Combine(ukwRoot, "UiCheckKw136rec.json");
					ProfileFactory.Save(ukwRec.Profile, recPath136);
					CharacterProfile ukwRe = ProfileFactory.Load(recPath136);
					ukwRe.Paths.OutputDir = ukwRoot;
					ukwRe.Paths.VanillaProject = Profile.Paths.VanillaProject;
					ukwRe.Paths.GameDataDir = Profile.Paths.GameDataDir;
					var ukwGen2 = ModGenerator.Generate(ukwRe);
					Check("（准备）用恢复出来的存档再生成一次", ukwGen2.Success,
						ukwGen2.Success ? "成功" : string.Join(" ｜ ", ukwGen2.Issues.Where(x => x.IsError).Select(x => x.Message)));
					if (ukwGen2.Success)
					{
						var ukwMiss = new List<string>();
						int ukwSame = 0;
						foreach (string g1 in Directory.GetFiles(ukwGen.ProjectRoot, "*", SearchOption.AllDirectories))
						{
							string rel = Path.GetRelativePath(ukwGen.ProjectRoot, g1);
							string g2 = Path.Combine(ukwGen2.ProjectRoot, rel);
							if (!File.Exists(g2)) { ukwMiss.Add("第二次没有 " + rel); continue; }
							if (System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(g1))
								.AsSpan().SequenceEqual(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(g2)))) ukwSame++;
							else if (!rel.EndsWith(".sln", StringComparison.OrdinalIgnoreCase))
								ukwMiss.Add("内容不同 " + rel + FirstLineDiff(g1, g2));
						}
						Check("「生成 → 从工程恢复 → 再生成」除了 .sln 的随机 GUID **逐字节一致**（两栏是幂等的）",
							ukwMiss.Count == 0, ukwMiss.Count == 0 ? $"逐字节一致 {ukwSame} 个文件" : string.Join("；", ukwMiss.Take(4)));
					}
				}

				// ---- 老形状对拍：一份**没有那两栏**的存档，改动前后生成结果必须逐字节一致 ----
				// 自检里没法跑「改动前的版本」，所以这里钉住等价口径：那两栏为空 ⇒ 生成端走的就是老路径
				//（描述不包 {IfUpgraded}、ExtraHoverTips 还是表达式体、一个 CET:UpgradeKeyword 都不写）。
				CharacterProfile old136 = ProfileFactory.Sample();
				old136.ModId = "UiCheckKw136b";
				old136.ModDisplayName = "自检角色136b";
				old136.CharacterClass = "UiCheckKw136b";
				old136.DisplayName = "自检角色136b";
				old136.CustomKeywords.Clear();
				old136.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命定", Description = "自检用·命定" });
				foreach (var oc in old136.Cards) oc.KeywordIds = new List<string> { "FATE" };
				old136.Paths.OutputDir = ukwBase;
				old136.Paths.VanillaProject = Profile.Paths.VanillaProject;
				old136.Paths.GameDataDir = Profile.Paths.GameDataDir;
				var oldGen = ModGenerator.Generate(old136);
				Check("（准备）只勾了普通自定义关键词、没填那两栏的存档能生成工程", oldGen.Success,
					oldGen.Success ? "成功" : string.Join(" ｜ ", oldGen.Issues.Where(x => x.IsError).Select(x => x.Message)));
				if (oldGen.Success)
				{
					string oldCards = File.ReadAllText(Path.Combine(oldGen.ProjectRoot, "UiCheckKw136b", "localization", "zhs", "cards.json"));
					Check("老形状：描述里没有 {IfUpgraded（关键词行照旧拼在最前面）",
						!oldCards.Contains("{IfUpgraded", StringComparison.Ordinal) && oldCards.Contains("[gold]命定[/gold]。", StringComparison.Ordinal), "老样子");
					string oldCard = Path.Combine(oldGen.ProjectRoot, "cs", "Cards", "SevenCrush.cs");
					string oldSrc = File.Exists(oldCard) ? File.ReadAllText(oldCard) : "";
					Check("老形状：一个 CET:UpgradeKeyword 标记都不写（老存档产物一个字符都不多）",
						oldSrc.Length > 0 && !oldSrc.Contains("CET:UpgradeKeyword", StringComparison.Ordinal), "没标记");
					Check("老形状：ExtraHoverTips 还是老写法（表达式体，没有 base.IsUpgraded 条件展开）",
						oldSrc.Contains("ExtraHoverTips =>", StringComparison.Ordinal)
						&& !oldSrc.Contains("base.IsUpgraded ? new MegaCrit.Sts2.Core.HoverTips.IHoverTip[]", StringComparison.Ordinal), "老写法");
				}

				// ---- 校验器：引用不存在的自定义关键词 → **错误**（生成端也会拦住）----
				CharacterProfile bad136 = ProfileFactory.Sample();
				bad136.CustomKeywords.Clear();
				bad136.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命定", Description = "自检用" });
				var badCard = new CardSpec { Name = "升获校验卡", ClassName = "UiCheckKwBad", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				badCard.UpgradeAddedCustomKeywords = new List<string> { "NO_SUCH_KEY" };
				bad136.Cards.Add(badCard);
				var badIssues = ProfileValidator.Validate(bad136);
				Check("校验器：升级后获得引用了不存在的自定义关键词 → **错误**，点名卡牌与那一栏",
					badIssues.Any(i => i.IsError && i.Message.Contains("升获校验卡", StringComparison.Ordinal)
						&& i.Message.Contains("NO_SUCH_KEY", StringComparison.Ordinal)
						&& i.Message.Contains("升级后获得", StringComparison.Ordinal)),
					badIssues.FirstOrDefault(i => i.IsError && i.Message.Contains("NO_SUCH_KEY", StringComparison.Ordinal))?.Message ?? "(没报错！)");
				// ---- 校验器：诅咒（升不了级）填了这两栏 → 提示 ----
				CharacterProfile curse136 = ProfileFactory.Sample();
				curse136.CustomKeywords.Clear();
				curse136.CustomKeywords.Add(new CustomKeywordSpec { Key = "FATE", Name = "命定", Description = "自检用" });
				var curseCard136 = new CardSpec { Name = "升获校验诅咒", ClassName = "UiCheckKwCurseV", CardType = "Curse", Rarity = "Curse", Cost = -1, InCardPool = false };
				curseCard136.UpgradeAddedCustomKeywords = new List<string> { "FATE" };
				curse136.Curses.Add(curseCard136);
				var curseIssues136 = ProfileValidator.Validate(curse136);
				Check("校验器：诅咒（升不了级）填了这两栏 → 提示（照既有诅咒那条的写法），并说清只影响显示",
					curseIssues136.Any(i => i.Level == "警告" && i.Message.Contains("升获校验诅咒", StringComparison.Ordinal)
						&& i.Message.Contains("升不了级", StringComparison.Ordinal)
						&& i.Message.Contains("只影响显示", StringComparison.Ordinal)),
					curseIssues136.FirstOrDefault(i => i.Level == "警告" && i.Message.Contains("升不了级", StringComparison.Ordinal))?.Message ?? "(没提示！)");
				// ---- 界面：两栏的勾选行 + 那行小结 ----
				Check("界面：卡牌页有「升级后获得 / 升级后失去」两栏的勾选行（当前选中的卡 × 全部关键词）",
					typeof(MainWindow).GetProperty("UpgradeAddedKeywordRows") is not null
					&& typeof(MainWindow).GetProperty("UpgradeRemovedKeywordRows") is not null
					&& typeof(MainWindow).GetProperty("UpgradeCustomKeywordHint") is not null, "三个窗口级属性都在");
				Check("界面：「只影响显示」这句话确实写在界面上（用户不会以为机制变了）",
					TextsIn(SelectTabRoot("卡牌")).Any(t => t.Contains("只影响显示", StringComparison.Ordinal)),
					"界面文案里有");
				Check("界面：那两栏的标题也写在卡牌页上（「升级后获得（留空 = 不变）」/「升级后失去（留空 = 不变）」）",
					TextsIn(SelectTabRoot("卡牌")).Any(t => t.Contains("升级后获得（留空 = 不变）", StringComparison.Ordinal))
					&& TextsIn(SelectTabRoot("卡牌")).Any(t => t.Contains("升级后失去（留空 = 不变）", StringComparison.Ordinal)),
					"两个标题都在");
			}
			catch (Exception ex)
			{
				Check("V0.2.136 升级后自定义关键词自检整段跑通", ok: false, ex.Message);
			}
		}
		// ===== V0.2.136：卡牌页「类型 / 稀有度」英文 → 中文（需求《卡牌页优化.md》第 2 条 ①）=====
		// 用户原话：「**将类型和稀有度的英文替换成中文**」。
		// 做法照抄遗物 / 药水页那一套（`RelicRarityOptions` / `PotionRarityOptions`）：
		// **Id 保持英文**（存档 / 生成端 / 校验器 / 回读全按英文 id 判 → 存档面零变化）、
		// **Display 是中文**（照抄游戏本体 `localization\zhs\gameplay_ui.json` 的 CARD_TYPE.* / CARD_RARITY.*）。
		{
			Check("卡牌类型下拉的选项：中文照抄游戏本体 CARD_TYPE.*（攻击 / 技能 / 能力 / 状态 / 诅咒 / 任务），Id 还是英文",
				EffectCatalog.CardTypeOptions.Select(o => o.Id).SequenceEqual(EffectCatalog.CardTypes)
				&& EffectCatalog.CardTypeOptions.Select(o => o.Display).SequenceEqual(new[] { "攻击", "技能", "能力", "状态", "诅咒", "任务" }),
				string.Join(" / ", EffectCatalog.CardTypeOptions.Select(o => o.Id + "=" + o.Display)));
			Check("卡牌稀有度下拉的选项：中文照抄游戏本体 CARD_RARITY.*（基础 / 普通 / 罕见 / 稀有 / 先古 / 状态 / 诅咒），档位与老表一模一样",
				EffectCatalog.CardRarityOptions.Select(o => o.Id).SequenceEqual(EffectCatalog.CardRarities)
				&& EffectCatalog.CardRarityOptions.Select(o => o.Display)
					.SequenceEqual(new[] { "基础", "普通", "罕见", "稀有", "先古", "状态", "诅咒" }),
				string.Join(" / ", EffectCatalog.CardRarityOptions.Select(o => o.Id + "=" + o.Display)));
			Check("（对照）遗物 / 药水页的稀有度中文没被改动（两页是**不同枚举**，措辞本来就不一样）",
				EffectCatalog.RelicRarityOptions.Select(o => o.Display).SequenceEqual(new[] { "初始", "常见", "罕见", "稀有", "先古", "商店" })
				&& EffectCatalog.PotionRarityOptions.Select(o => o.Display).SequenceEqual(new[] { "常见", "罕见", "稀有" }),
				"遗物 6 档 / 药水 3 档照旧");
			Check("中文显示名映射：CardTypeZh / CardRarityZh 认得每一档，认不出来的原样返回（不吞、不静默变默认）",
				EffectCatalog.CardTypeZh("Attack") == "攻击" && EffectCatalog.CardRarityZh("Uncommon") == "罕见"
				&& EffectCatalog.CardTypeZh("SomethingElse") == "SomethingElse"
				&& EffectCatalog.CardRarityZh("SomethingElse") == "SomethingElse", "映射对");
			// 中间那一栏的两个下拉（自检里已经选中了一张卡）
			Check("中间栏：类型下拉绑到 CardTypeOptions（DisplayMemberPath=Display / SelectedValuePath=Id / SelectedValue=CardType）",
				CardTypeCombo is not null && ReferenceEquals(CardTypeCombo.ItemsSource, CardTypeOptions)
				&& CardTypeCombo.DisplayMemberPath == "Display" && CardTypeCombo.SelectedValuePath == "Id"
				&& BindingOperations.GetBinding(CardTypeCombo, Selector.SelectedValueProperty)?.Path?.Path == "CardType",
				CardTypeCombo is null ? "(没找到下拉)" : "绑定对");
			Check("中间栏：稀有度下拉绑到 CardRarityOptions（同上）",
				CardRarityCombo is not null && ReferenceEquals(CardRarityCombo.ItemsSource, CardRarityOptions)
				&& CardRarityCombo.DisplayMemberPath == "Display" && CardRarityCombo.SelectedValuePath == "Id"
				&& BindingOperations.GetBinding(CardRarityCombo, Selector.SelectedValueProperty)?.Path?.Path == "Rarity",
				CardRarityCombo is null ? "(没找到下拉)" : "绑定对");
			// 「诅咒 / 先古卡」页那一栏（同一份模板的三处下拉之一）
			Check("诅咒 / 先古卡页：类型下拉也换成中文选项表（Display / SelectedValuePath 都对）",
				CurseCardTypeCombo is not null && ReferenceEquals(CurseCardTypeCombo.ItemsSource, CardTypeOptions)
				&& CurseCardTypeCombo.DisplayMemberPath == "Display" && CurseCardTypeCombo.SelectedValuePath == "Id",
				CurseCardTypeCombo is null ? "(没找到下拉)" : "绑定对");
			// 下拉里**显示**的确实是中文（读的是选项表的 Display，不是英文 id）
			Check("下拉里显示的是中文（逐项核 Display，没有一个纯英文 id 混进去）",
				CardTypeCombo is not null && CardTypeCombo.Items.Cast<RarityOption>()
					.All(o => o.Display.Length > 0 && !o.Display.All(ch => ch < 128))
				&& CardRarityCombo is not null && CardRarityCombo.Items.Cast<RarityOption>()
					.All(o => o.Display.Length > 0 && !o.Display.All(ch => ch < 128)),
				string.Join(" / ", (CardTypeCombo?.Items ?? CardTypeCombo!.Items).Cast<RarityOption>().Select(o => o.Display)));

			// ---- 选中之后**存进模型的还是英文 Id**（不能把存档写成中文）----
			CardSpec? uiCard = ActiveCardForDetail();
			Check("（准备）自检里选着一张卡（下拉绑的就是它）", uiCard is not null, uiCard?.Name ?? "(没选中)");
			if (uiCard is not null && CardTypeCombo is not null && CardRarityCombo is not null)
			{
				string keepType = uiCard.CardType, keepRarity = uiCard.Rarity;
				try
				{
					// 用 SelectedValue（= Id）选中，模拟用户在下拉里点「能力 / 稀有」——
					// 存进模型的必须还是 "Power" / "Rare" 这两个英文 id
					CardTypeCombo.SelectedValue = "Power";
					Check("选中「能力」之后 CardSpec.CardType 还是英文 `Power`（不是「能力」）",
						uiCard.CardType == "Power", uiCard.CardType);
					CardRarityCombo.SelectedValue = "Uncommon";
					Check("选中「罕见」之后 CardSpec.Rarity 还是英文 `Uncommon`（不是「罕见」）",
						uiCard.Rarity == "Uncommon", uiCard.Rarity);
					// 反过来：模型里是英文 id 时，下拉能按 SelectedValuePath 认出来（回来时不会变成空）
					uiCard.CardType = "Skill"; uiCard.Rarity = "Rare";
					UpdateLayout();
					Check("模型里写英文 id → 下拉按 SelectedValuePath 认出来（选中值 = 那个 id，回到界面不会变空）",
						Equals(CardTypeCombo.SelectedValue, "Skill") && Equals(CardRarityCombo.SelectedValue, "Rare"),
						$"类型={CardTypeCombo.SelectedValue} 稀有度={CardRarityCombo.SelectedValue}");
					// 模拟「用户在下拉里点了中文那一项」：把 SelectedItem 设成选项对象（和鼠标点选等价）
					CardTypeCombo.SelectedItem = CardTypeCombo.Items.Cast<RarityOption>().First(o => o.Display == "攻击");
					CardRarityCombo.SelectedItem = CardRarityCombo.Items.Cast<RarityOption>().First(o => o.Display == "先古");
					UpdateLayout();
					Check("点「攻击」/「先古」这两项之后，模型里写的还是英文 id（`Attack` / `Ancient`）—— 界面中文、存档英文",
						uiCard.CardType == "Attack" && uiCard.Rarity == "Ancient",
						$"{uiCard.CardType} / {uiCard.Rarity}");
				}
				finally
				{
					uiCard.CardType = keepType;
					uiCard.Rarity = keepRarity;
					UpdateLayout();
				}
			}
			// 卡牌列表那一行（Display）里显示的也必须是中文
			Check("卡牌列表那一行显示的是中文类型 / 稀有度（Display 原文里是「能力 / 罕见」，没有英文 id）",
				DisplayIsChinese());
			// 生成端读的仍然是英文 id（这两句话钉住「界面换中文 = 只换显示」）
			Check("生成端不受影响：CardSource 里写的还是本体枚举名 `CardType.Power` / `CardRarity.Uncommon`",
				CSharpCodeGen.CardSource(Profile, new CardSpec { Name = "自检中文档位卡", ClassName = "UiCheckZhTier", CardType = "Power", Rarity = "Uncommon", Cost = 1 }, 0)
					.Contains("CardType.Power", StringComparison.Ordinal)
				&& CSharpCodeGen.CardSource(Profile, new CardSpec { Name = "自检中文档位卡", ClassName = "UiCheckZhTier", CardType = "Power", Rarity = "Uncommon", Cost = 1 }, 0)
					.Contains("CardRarity.Uncommon", StringComparison.Ordinal),
				"英文枚举名照旧");
			// 校验器 / 回读也按英文判（把中文写进模型会被拦下来）
			CharacterProfile zhProf = ProfileFactory.Sample();
			var zhBad = new CardSpec { Name = "中文档位卡", ClassName = "UiCheckZhBad", CardType = "能力", Rarity = "稀有", Cost = 1, InCardPool = true };
			zhProf.Cards.Add(zhBad);
			Check("校验器：模型里被写成中文档位 → **报错**（说明只能存英文 id，界面换中文没动校验口径）",
				ProfileValidator.Validate(zhProf).Any(i => i.IsError && i.Message.Contains("中文档位卡", StringComparison.Ordinal)
					&& (i.Message.Contains("类型非法", StringComparison.Ordinal) || i.Message.Contains("稀有度非法", StringComparison.Ordinal))),
				ProfileValidator.Validate(zhProf).FirstOrDefault(i => i.IsError && i.Message.Contains("中文档位卡", StringComparison.Ordinal))?.Message ?? "(没报错！)");
			// 本地函数：Display 里中文
			bool DisplayIsChinese()
			{
				var probe = new CardSpec { Name = "自检显示卡", ClassName = "UiCheckZhShow", CardType = "Power", Rarity = "Uncommon", Cost = 1, InCardPool = true };
				string text = probe.Display;
				return text.Contains("能力", StringComparison.Ordinal) && text.Contains("罕见", StringComparison.Ordinal)
					&& !text.Contains("Uncommon", StringComparison.Ordinal) && !text.Contains("/ Power", StringComparison.Ordinal);
			}
		}

		// ===== V0.2.142：生成调试日志开关（排查用；**默认关着时生成结果一个字节都不变**）=====
		// 为什么这些断言必须钉住：这个开关最大的风险不是「打不出日志」，而是**悄悄改掉默认输出**
		//（用户没勾它，生成出来的模组却变了）。所以下面既钉「开关真的进了存档 / 界面上真有那个勾选框
		// 且文案说清只影响日志」，也钉「开 → 有日志、关 → 一个字都不多」这条闭环。
		{
			// ① 默认关（老存档没有这个字段 → 读进来就是 false，行为和以前完全一样）
			CharacterProfile dbgDefault = ProfileFactory.Sample();
			Check("V0.2.142：调试日志开关默认关着（老存档读进来也是 false）", !dbgDefault.DebugLog, $"DebugLog={dbgDefault.DebugLog}");
			Check("V0.2.142：界面「角色」页上有那个勾选框、且文案写明「只影响日志」（用户在界面上看得到）",
				TextsIn(SelectTabRoot("角色")).Any(t => t.Contains("打开「生成调试日志」", StringComparison.Ordinal))
				&& TextsIn(SelectTabRoot("角色")).Any(t => t.Contains("只影响日志", StringComparison.Ordinal))
				&& TextsIn(SelectTabRoot("角色")).Any(t => t.Contains("不影响游戏行为", StringComparison.Ordinal))
				&& TextsIn(SelectTabRoot("角色")).Any(t => t.Contains("排查完请关掉", StringComparison.Ordinal)),
				string.Join(" ｜ ", TextsIn(SelectTabRoot("角色")).Where(t => t.Contains("调试", StringComparison.Ordinal)).Take(3)));
			// ② 开关进存档：存一遍再读回来还是 true（不加 [JsonIgnore] 才成立）
			CharacterProfile dbgSaved = ProfileFactory.Sample();
			dbgSaved.DebugLog = true;
			string dbgJson = Path.Combine(Path.GetTempPath(), "forge_uicheck_debuglog_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
			ProfileFactory.Save(dbgSaved, dbgJson);
			Check("V0.2.142：开关会写进存档（存一遍读回来还是 true）", ProfileFactory.Load(dbgJson).DebugLog, dbgJson);
			File.Delete(dbgJson);
			// ③ 开 → 生成文本里出现日志；关 → 一个字都不多
			CardSpec dbgCard = new CardSpec { Name = "自检调试日志卡", ClassName = "UiCheckDebugLog", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
			dbgCard.Effects.Add(new EffectSpec { Kind = "ApplyPower", Amount = -2m, PowerId = "StrengthPower", TargetSide = "Enemy" });
			CharacterProfile dbgOff = ProfileFactory.Sample();
			dbgOff.Cards.Add(dbgCard);
			CharacterProfile dbgOn = ProfileFactory.Sample();
			dbgOn.Cards.Add(new CardSpec
			{
				Name = dbgCard.Name, ClassName = dbgCard.ClassName, CardType = dbgCard.CardType, Rarity = dbgCard.Rarity,
				Cost = dbgCard.Cost, InCardPool = true,
				Effects = { new EffectSpec { Kind = "ApplyPower", Amount = -2m, PowerId = "StrengthPower", TargetSide = "Enemy" } },
			});
			dbgOn.DebugLog = true;
			string dbgOffSrc = CSharpCodeGen.CardSource(dbgOff, dbgOff.Cards[^1], 0);
			string dbgOnSrc = CSharpCodeGen.CardSource(dbgOn, dbgOn.Cards[^1], 0);
			Check("V0.2.142：开关**关着**时生成文本里一个日志字符都没有（红线①：默认输出不变）",
				!dbgOffSrc.Contains("GD.Print", StringComparison.Ordinal) && !dbgOffSrc.Contains("CET:DebugLog", StringComparison.Ordinal),
				dbgOffSrc.Contains("GD.Print", StringComparison.Ordinal) ? "竟然有 GD.Print！" : "干净");
			Check("V0.2.142：开关**打开**时生成文本里出现日志（Godot.GD.Print + CET:DebugLog 标记）",
				dbgOnSrc.Contains("Godot.GD.Print", StringComparison.Ordinal) && dbgOnSrc.Contains("CET:DebugLog", StringComparison.Ordinal),
				dbgOnSrc.Contains("Godot.GD.Print", StringComparison.Ordinal) ? "有" : "没有！");
			// ④ 「本来没有这个状态」和「已经有了」两种情形都要能打出来（这正是加这个开关的目的）
			Check("V0.2.142：施加状态的日志里同时有「执行前层数」与「执行后层数」两行",
				dbgOnSrc.Contains("执行前层数=", StringComparison.Ordinal) && dbgOnSrc.Contains("执行后层数=", StringComparison.Ordinal), "两行都在");
			Check("V0.2.142：目标身上**本来没有**这个状态时会标「本来没有这个状态」（层数记 -）",
				dbgOnSrc.Contains("本来没有这个状态", StringComparison.Ordinal) && dbgOnSrc.Contains("已经有了这个状态", StringComparison.Ordinal),
				"按 GetPower 是不是 null 分别标记");
			Check("V0.2.142：日志里写明「谁在跑」（卡牌名 + 类名）与「目标是谁」（名字 + 是不是自己）",
				dbgOnSrc.Contains("卡牌「自检调试日志卡」(UiCheckDebugLog)", StringComparison.Ordinal)
				&& dbgOnSrc.Contains(".Name ??", StringComparison.Ordinal) && dbgOnSrc.Contains("（不是自己）", StringComparison.Ordinal),
				"来源 + 目标都在");
			Check("V0.2.142：负数施加状态时日志说清是哪一档（力量 → 「实际按『施加负层数』执行」）",
				dbgOnSrc.Contains("实际按「施加负层数」执行", StringComparison.Ordinal), "说清了");
			// ===== V0.2.236：用户报「投斧（ThrowingAxe）对某张牌不生效」=====
			// 本体 `CardModel.OnPlayWrapper` 是 `for (int i = 0; i < playCount; i++) await OnPlay(...)`
			// （CardModel.cs:1896-1971）—— 遗物 / 状态改的是 playCount，多打的那一次**会再跑一遍 OnPlay**，
			// 但能力牌打出后就进 PileType.None、界面上往往看不出来（用户前面报过一次「能力牌不触发头斧」）。
			// 日志里带上「第 k/K 次」，一眼就能分清两种情形：只有「1/1」= playCount 压根没被改；
			// 出现「2/2」= 多打的那次真的执行了，「没效果」只能是效果本身不可叠加。
			Check("V0.2.236：开着调试日志时 OnPlay 开头打出「第几次 / 一共几次」（改 playCount 的遗物靠它验证）",
				dbgOnSrc.Contains("打出第 ", StringComparison.Ordinal)
				&& dbgOnSrc.Contains("cardPlay.PlayIndex + 1", StringComparison.Ordinal)
				&& dbgOnSrc.Contains("cardPlay.PlayCount", StringComparison.Ordinal),
				"有「第 k/K 次」");
			Check("V0.2.236：这一行也带 CET:DebugLog 标记（从工程反推存档时按行跳过，不会变成假效果）",
				dbgOnSrc.Split('\n').Any(l => l.Contains("打出第 ", StringComparison.Ordinal) && l.Contains("CET:DebugLog", StringComparison.Ordinal)),
				"带标记");
			Check("V0.2.236：关着调试日志时这一行也不出现（红线①：默认输出一个字节都不变）",
				!dbgOffSrc.Contains("打出第 ", StringComparison.Ordinal), "干净");
			// ===== V0.2.168：开着调试日志时**锻造节点图**那张卡编译不过（用户实测）=====
			// 真因：日志那一行是以行尾注释 `// CET:DebugLog` 收尾的，而锻造图那几档（造成伤害 / 获得格挡 /
			// 失去生命 …）是「foreach { <日志行><语句> }」这种拼在一起的形状 —— 那行注释把**后面整条语句
			// 和 foreach 收尾的 }** 一起吃成了注释 ⇒ CS8641「else 不能用在语句的开头」+ CS1513 应输入 }。
			// 现在：日志行**自带换行**（自己占一行、后面不再跟别的语句），目标名也改成按运行时打
			//（以前是 `目标=[' + ((x)?.Name ?? \"?\") + ']` 这一串**字面量**印到日志里，看不到真正打到谁）。
			{
				var dbgGraph = new ForgeGraphSpec();
				var dbgTrig = new ForgeNodeSpec { Kind = "Trigger" };
				dbgTrig.SetField("Timing", ForgeTimings.CardPlayed);
				dbgGraph.Nodes.Add(dbgTrig);
				string dbgPrev = dbgTrig.Id;
				foreach (var (fxKind, fxAmount, fxPower) in new (string, string, string)[]
				{
					("Damage", "6", ""), ("Block", "5", ""), ("ApplyPower", "2", "VulnerablePower"),
				})
				{
					var fxNode = new ForgeNodeSpec { Kind = "Effect" };
					fxNode.SetField("Effect", fxKind);
					fxNode.SetField("Amount", fxAmount);
					if (fxPower.Length > 0) fxNode.SetField("PowerId", fxPower);
					dbgGraph.Nodes.Add(fxNode);
					dbgGraph.Links.Add(new ForgeLinkSpec { From = dbgPrev, To = fxNode.Id, FromPort = 0, ToPort = 0 });
					dbgPrev = fxNode.Id;
				}
				var dbgGraphCard = new CardSpec { Name = "自检调试日志锻造卡", ClassName = "UiCheckDebugLogGraph", CardType = "Skill", Rarity = "Common", Cost = 1, IsForged = true, InCardPool = true, ForgeGraph = dbgGraph };
				dbgOn.Cards.Add(dbgGraphCard);
				string dbgGraphSrc = CSharpCodeGen.CardSource(dbgOn, dbgGraphCard, dbgOn.Cards.Count - 1);
				var dbgLines = dbgGraphSrc.Replace("\r\n", "\n").Split('\n');
				Check("V0.2.168：锻造图里每一条调试日志都**自成一个行尾注释**（后面没有跟着会被吃掉的语句 / 收尾的 }）",
					dbgLines.Any(l => l.Contains("CET:DebugLog", StringComparison.Ordinal))
					&& dbgLines.Where(l => l.Contains("CET:DebugLog", StringComparison.Ordinal))
						.All(l => l.TrimEnd().EndsWith("CET:DebugLog", StringComparison.Ordinal)),
					"共 " + dbgLines.Count(l => l.Contains("CET:DebugLog", StringComparison.Ordinal)) + " 行日志");
				Check("V0.2.168：日志里的目标名按**运行时**打（`((__fgFoe)?.Name ?? \"?\")`），不再是转义后的字面量代码",
					dbgGraphSrc.Contains("((__fgFoe)?.Name ?? \"?\")", StringComparison.Ordinal)
					&& !dbgGraphSrc.Contains("Name ?? \\\"?\\\"", StringComparison.Ordinal), "运行时求值");
			}
			// ⑤ 真的编译得动（不是只有自检通过）：生成 → dotnet build
			string dbgRoot = Path.Combine(Path.GetTempPath(), "forge_uicheck_debuglog_" + Guid.NewGuid().ToString("N").Substring(0, 8));
			try
			{
				dbgOn.Paths.OutputDir = dbgRoot;
				dbgOn.Paths.VanillaProject = Profile.Paths.VanillaProject;
				dbgOn.Paths.GameDataDir = Profile.Paths.GameDataDir;
				dbgOn.Paths.GodotExe = Profile.Paths.GodotExe;
				dbgOn.Paths.DotnetExe = Profile.Paths.DotnetExe;
				var dbgGen = ModGenerator.Generate(dbgOn);
				Check("（准备）开着调试日志的存档能生成工程", dbgGen.Success, dbgGen.ProjectRoot);
				if (dbgGen.Success)
				{
					string dbgCardFile = Path.Combine(dbgGen.ProjectRoot, "cs", "Cards", "UiCheckDebugLog.cs");
					string dbgFileText = File.Exists(dbgCardFile) ? File.ReadAllText(dbgCardFile) : "";
					Check("（准备）生成出来的卡牌源码里那两行日志在**各自单独的行**上（回读按行跳过，见 ProjectRecovery）",
						dbgFileText.Contains("CET:DebugLog", StringComparison.Ordinal)
						&& dbgFileText.Split('\n').Any(l => l.Contains("CET:DebugLog", StringComparison.Ordinal) && l.TrimStart().StartsWith("await PowerCmd.Apply", StringComparison.Ordinal) == false
							&& l.Contains("Godot.GD.Print", StringComparison.Ordinal)),
						"日志行自成一行的占多数");
					var dbgBuild = Sts2CharForge.Core.Build.ModBuilder.Build(dbgGen.ProjectRoot, Naming.From(dbgOn).ModId,
						dbgOn.Paths.GodotExe, null, null, dbgOn.Paths.DotnetExe);
					var dbgDllStep = dbgBuild.Steps.FirstOrDefault(st => st.Name.Contains("编译 DLL", StringComparison.Ordinal));
					Check("V0.2.142：开着调试日志生成出来的工程真的编译得过（dotnet build 0 错误）", dbgDllStep is { Success: true },
						dbgDllStep is null ? "(没找到编译那一步)" : dbgDllStep.Output.Split('\n').LastOrDefault(l => l.Contains("个错误", StringComparison.Ordinal)) ?? dbgDllStep.Name);
				}
			}
			finally
			{
				try { if (Directory.Exists(dbgRoot)) Directory.Delete(dbgRoot, true); } catch { }
			}
		}
		// ===== V0.2.234：开着调试日志 + 作用对象 = 全部友方 / 全体单位 → 生成的工程编译不过 =====
		// 用户实测（构建日志）：VitaCard21.cs(48,160) / VitaCard23.cs(23,89) 等
		//   error CS0103: 当前上下文中不存在名称“ally”
		// 真因：这两档是「逐个动手」（foreach (Creature ally …) / … unit …），而日志那一行是在
		// **循环外面**打的，却把目标名写成了 `(ally)?.Name` → 生成出来引用了一个还没声明的循环变量。
		// 现在多目标档改成写一句固定说明（「全部友方（逐个动手）」），不再引用循环变量。
		{
			Check("V0.2.234：「全部友方 / 全体单位」在调试日志里有固定的说明文字（不再引循环变量）",
				CSharpCodeGen.MultiTargetGroupZh(new EffectSpec { Kind = "Block", TargetSide = "AllAllies" }) == "全部友方（逐个动手）"
				&& CSharpCodeGen.MultiTargetGroupZh(new EffectSpec { Kind = "Block", TargetSide = "AllUnits" }) == "全体单位（逐个动手）"
				&& CSharpCodeGen.MultiTargetGroupZh(new EffectSpec { Kind = "Block", TargetSide = "Enemy" }) is null
				&& CSharpCodeGen.MultiTargetGroupZh(new EffectSpec { Kind = "Block", TargetSide = "Self" }) is null,
				"判据对");

			static CharacterProfile DbgMultiProfile(string side, params EffectSpec[] fx)
			{
				var gp = ProfileFactory.Sample();
				var c = new CardSpec { Name = "自检调试多目标", ClassName = "UiCheckDbgMulti", CardType = "Skill", Rarity = "Common", Cost = 1, InCardPool = true };
				foreach (EffectSpec e in fx) c.Effects.Add(e);
				gp.Cards.Add(c);
				gp.DebugLog = true;
				return gp;
			}

			var dbgAlly = DbgMultiProfile("AllAllies",
				new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "AllAllies" },
				new EffectSpec { Kind = "Heal", Amount = 2m, TargetSide = "AllAllies" },
				new EffectSpec { Kind = "HpLoss", Amount = 1m, TargetSide = "AllAllies" },
				new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "AllAllies" },
				// V0.2.234：施加状态 / 临时增益这两档的「目标」打印也在循环外面（以前同样 CS0103）
				new EffectSpec { Kind = "ApplyPower", Amount = 1m, PowerId = "StrengthPower", TargetSide = "AllAllies" },
				new EffectSpec { Kind = "TempPower", Amount = 1m, PowerId = "StrengthPower", TargetSide = "AllAllies" });
			string dbgAllySrc = CSharpCodeGen.CardSource(dbgAlly, dbgAlly.Cards[^1], 0);
			string[] dbgAllyPrints = dbgAllySrc.Replace("\r\n", "\n").Split('\n').Where(l => l.Contains("Godot.GD.Print", StringComparison.Ordinal)).ToArray();
			// 只查「独立成行的 Target 日志」（PowerBefore/After 那种是 `{ … }` 包起来、在循环**里面**的，引用 ally 合法）
			string[] dbgAllyFlat = dbgAllyPrints.Where(l => l.TrimStart().StartsWith("Godot.GD.Print(", StringComparison.Ordinal)).ToArray();
			Check("V0.2.234：全部友方 + 调试日志 → 循环外面那几行日志**不再出现** (ally) 这种循环变量（以前是 CS0103）",
				dbgAllyFlat.Length > 0 && !dbgAllyFlat.Any(l => l.Contains("(ally)", StringComparison.Ordinal)),
				dbgAllyFlat.FirstOrDefault() ?? "(没有日志行)");
			Check("V0.2.234：那几行日志的目标写成「全部友方（逐个动手）」",
				dbgAllyFlat.Count(l => l.Contains("目标=[全部友方（逐个动手）]", StringComparison.Ordinal)) >= 5,
				"命中 " + dbgAllyFlat.Count(l => l.Contains("全部友方（逐个动手）", StringComparison.Ordinal)) + " 行");

			var dbgUnit = DbgMultiProfile("AllUnits",
				new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "AllUnits" },
				new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "AllUnits" });
			string dbgUnitSrc = CSharpCodeGen.CardSource(dbgUnit, dbgUnit.Cards[^1], 0);
			string[] dbgUnitPrints = dbgUnitSrc.Replace("\r\n", "\n").Split('\n').Where(l => l.Contains("Godot.GD.Print", StringComparison.Ordinal)).ToArray();
			Check("V0.2.234：全体单位同理（日志行里没有 (unit) 这种循环变量，改成「全体单位（逐个动手）」）",
				dbgUnitPrints.Length > 0
				&& !dbgUnitPrints.Any(l => l.Contains("(unit)", StringComparison.Ordinal))
				&& dbgUnitPrints.Any(l => l.Contains("目标=[全体单位（逐个动手）]", StringComparison.Ordinal)),
				dbgUnitPrints.FirstOrDefault() ?? "(没有日志行)");

			// 红线：单目标那几档的日志形状一个字都没动（目标名仍按运行时打）
			var dbgEnemy = DbgMultiProfile("Enemy", new EffectSpec { Kind = "Damage", Amount = 4m, TargetSide = "Enemy" });
			string dbgEnemySrc = CSharpCodeGen.CardSource(dbgEnemy, dbgEnemy.Cards[^1], 0);
			Check("V0.2.234：（红线）单目标档的调试日志形状一个字都没动（仍然是那一行 GD.Print，没有多出目标段）",
				dbgEnemySrc.Contains("Godot.GD.Print(", StringComparison.Ordinal)
				&& !dbgEnemySrc.Contains("目标=[", StringComparison.Ordinal),
				"没动");
			// 红线②：开关关着时一个日志字符都不写（和 V0.2.142 同一条规矩）
			var dbgOffMulti = DbgMultiProfile("AllAllies", new EffectSpec { Kind = "Block", Amount = 3m, TargetSide = "AllAllies" });
			dbgOffMulti.DebugLog = false;
			Check("V0.2.234：（红线）调试日志关着时，多目标那几档仍然一个日志字符都不写",
				!CSharpCodeGen.CardSource(dbgOffMulti, dbgOffMulti.Cards[^1], 0).Contains("CET:DebugLog", StringComparison.Ordinal),
				"干净");
			// ===== V0.2.235：自定义状态链的「临时增益 + 全体单位 / 全部敌人」同款 CS0103（other）=====
			// 真因同上：那行日志打在 foreach **外面**，却引用了循环变量 `other`。
			var dbgPowProf = ProfileFactory.Sample();
			dbgPowProf.DebugLog = true;
			var dbgPow = new CustomPowerSpec { Name = "自检调试状态全体", ClassName = "UiCheckDbgUnitsPower", Enabled = true };
			var dbgPowTrig = new PowerTriggerSpec { Kind = "TurnStart" };
			dbgPowTrig.Effects.Add(new EffectSpec { Kind = "TempPower", Amount = 1m, PowerId = "StrengthPower", TargetSide = "AllUnits", TargetSideCustom = true });
			dbgPowTrig.Effects.Add(new EffectSpec { Kind = "TempPower", Amount = 1m, PowerId = "StrengthPower", TargetSide = "AllEnemies", TargetSideCustom = true });
			dbgPow.Triggers.Add(dbgPowTrig);
			dbgPowProf.CustomPowers.Add(dbgPow);
			string dbgPowSrc = CustomPowerGen.Source(dbgPowProf, dbgPow, dbgPowProf.CustomPowers.Count - 1);
			string[] dbgPowPrints = dbgPowSrc.Replace("\r\n", "\n").Split('\n')
				.Where(l => l.TrimStart().StartsWith("Godot.GD.Print(", StringComparison.Ordinal)).ToArray();
			Check("V0.2.235：自定义状态的「临时增益 · 全体」日志里不再引用循环变量 other（以前是 CS0103）",
				dbgPowPrints.Length > 0 && !dbgPowPrints.Any(l => l.Contains("(other)", StringComparison.Ordinal)),
				dbgPowPrints.FirstOrDefault() ?? "(没有日志行)");
			Check("V0.2.235：那两行写成「全体单位（逐个动手）」/「全部敌人（逐个动手）」",
				dbgPowPrints.Any(l => l.Contains("目标=[全体单位（逐个动手）]", StringComparison.Ordinal))
				&& dbgPowPrints.Any(l => l.Contains("目标=[全部敌人（逐个动手）]", StringComparison.Ordinal)),
				"两档都在");
		}
		// ===== V0.2.144（用户拍板 A）：遗物 / 药水 / 额外资源量三页效果栏照卡牌页版式 =====
		// 用户原话：「遗物药水右侧的效果栏能不能同步卡牌的」。
		// 版式：上面一行摘要列表（普通 ListBoxItem）→ 点一条 = 原生选中；下面一整块共享编辑区
		// （DataContext 绑 SelectedItem；单条效果自己的「条件选项」就在编辑区里，不再有右下角那块独立框）。
		//
		// 为什么这版是「改版式」而不是再修一次补丁：V0.2.143 那个「条件选完存不住」的真因是
		// 「整行是一颗 Button → 冒泡阶段吃掉 MouseLeftButtonDown → 外层 ListBoxItem 永远选不中」。
		// 这版把行换回普通 ListBoxItem（和卡牌页一样），那个结构性原因**从根上没有了**。
		// 所以这一段钉的是：
		//   ① 点行（用 ListBoxItem.IsSelected，和鼠标点下去是同一条路）→ SelectedItem 就是这条效果；
		//   ② 编辑区那块 Border 的 DataContext 立刻跟过去（条件编辑器就在它里面）；
		//   ③ 在编辑区里选条件 → 写回 EffectSpec.Condition.Kind → 切走再切回来还在（用户说的「存住了」）；
		//   ④ 卡牌页回归：它本来就是这个版式，一个字都不该被这次改动带到。
		{
			// 自检用：把列表里第 row 行**选中**（等价于用户点这一行：ListBoxItem 收到鼠标就是置 IsSelected）。
			// 刻意走「行容器 → 列表选中」这条路（而不是直接写 SelectedItem），才测得出「点得中」。
			bool ClickEffectRow(ListBox list, int row)
			{
				if (EffectRowContainer(list, row) is not ListBoxItem item) return false;
				item.IsSelected = true;
				UpdateLayout();
				return list.SelectedItem is not null;
			}
			// 自检用：在某一页编辑区里那个「条件」下拉里真的选一个条件
			// （SelectedItem 是双侧绑定 → 直接写回 Condition.Kind）。
			ComboBox? ConditionComboOf(Border? box) =>
				box is null ? null : FindFirstComboBoxBound(box, "Condition.Kind");
			bool PickCondition(ComboBox combo, string id)
			{
				ConditionOption? opt = PlainEffectConditions.FirstOrDefault(o => o.Id == id);
				if (opt is null || !ReferenceEquals(combo.ItemsSource, PlainEffectConditions)) return false;
				combo.SelectedItem = opt;
				combo.GetBindingExpression(Selector.SelectedValueProperty)?.UpdateSource();
				UpdateLayout();
				return true;
			}
			// 自检用：把一条效果的条件存下来 / 原样还回去（自检不留痕）。
			(ConditionSpec Snap, object? ComboLocalValue) SnapshotCondition(EffectSpec fx, Border? box)
			{
				var c = fx.Condition ?? new ConditionSpec();
				fx.Condition = c;
				var combo = ConditionComboOf(box);
				return (
					new ConditionSpec
					{
						Kind = c.Kind, Timing = c.Timing, Target = c.Target,
						Amount = c.Amount, Amount2 = c.Amount2,
						AmountFormula = c.AmountFormula, Amount2Formula = c.Amount2Formula,
						PowerId = c.PowerId, WhenUnmet = c.WhenUnmet,
					},
					combo?.ReadLocalValue(Selector.SelectedValueProperty));
			}
			void RestoreCondition(EffectSpec fx, Border? box, (ConditionSpec Snap, object? ComboLocalValue) save)
			{
				ConditionSpec s = save.Snap;
				fx.Condition.Kind = s.Kind;
				fx.Condition.Timing = s.Timing;
				fx.Condition.Target = s.Target;
				fx.Condition.Amount = s.Amount;
				fx.Condition.Amount2 = s.Amount2;
				fx.Condition.AmountFormula = s.AmountFormula;
				fx.Condition.Amount2Formula = s.Amount2Formula;
				fx.Condition.PowerId = s.PowerId;
				fx.Condition.WhenUnmet = s.WhenUnmet;
				ConditionComboOf(box)?.ClearValue(Selector.SelectedValueProperty);
				UpdateLayout();
			}

			// ---- ① 遗物页：点一行 → 那一行必须被选中，编辑区跟着换 ----
			{
				SelectTabRoot("遗物");
				if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
				if (RelicTriggerList.Items.Count > 0) RelicTriggerList.SelectedIndex = 0;
				UpdateLayout();
				Check("V0.2.144 遗物页：样例存档里有遗物 + 效果可以拿来验「点行 = 选中行」",
					RelicEffectList.Items.Count > 0, RelicEffectList.Items.Count + " 条效果");
				if (RelicEffectList.Items.Count > 0)
				{
					var fx1 = (EffectSpec)RelicEffectList.Items[0];
					// 刻意把选中清掉（= 用户还没点过这一行的状态）：只有「点得中」才会重新有选中。
					RelicEffectList.SelectedItem = null;
					UpdateLayout();
					Check("V0.2.144 遗物页（前提）：没点之前那一行确实没被选中（否则这条测试没有意义）",
						RelicEffectList.SelectedItem is null, RelicEffectList.SelectedItem?.GetType().Name ?? "(null)");
					bool clicked = ClickEffectRow(RelicEffectList, 0);
					Check("V0.2.144 遗物页：点这一行 → **这一行被选中**（RelicEffectList.SelectedItem 就是这条效果）",
						clicked && ReferenceEquals(RelicEffectList.SelectedItem, fx1),
						"SelectedItem=" + (RelicEffectList.SelectedItem as EffectSpec)?.Kind + " / 期望=" + fx1.Kind);
					FrameworkElement? rowSel = EffectRowContainer(RelicEffectList, 0);
					Check("V0.2.144 遗物页：行容器自己的 IsSelected 也是 true（列表里看得出高亮）",
						rowSel is ListBoxItem { IsSelected: true },
						rowSel is ListBoxItem li ? "IsSelected=" + li.IsSelected : "(没生成行容器)");
					Check("V0.2.144 遗物页：点完这一行之后，下面那块编辑区的 DataContext 立刻变成这条效果"
						+ "（用户点完就能直接改它、改它自己的条件）",
						ReferenceEquals(RelicEffectEditorBox?.DataContext, fx1) && RelicEffectEditorBox?.IsVisible == true,
						"DataContext=" + ((RelicEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
					Check("V0.2.144 遗物页：这一行行里**没有 Button**（不再有「展开 / 收起」那套吃点击的交互）",
						rowSel is not null && !EffectRowContainsButton(rowSel),
						rowSel is null ? "(没生成行容器)" : "行里没有按钮");
				}
			}

			// ---- ② 遗物页：编辑区里的条件下拉选条件 → 写回 EffectSpec.Condition.Kind → 切走切回还在 ----
			{
				SelectTabRoot("遗物");
				if (RelicList.Items.Count > 0) RelicList.SelectedIndex = 0;
				UpdateLayout();
				if (RelicEffectList.Items.Count > 0) RelicEffectList.SelectedItem = RelicEffectList.Items[0];
				UpdateLayout();
				if (RelicEffectList.Items.Count > 0)
				{
					var fx2 = (EffectSpec)RelicEffectList.Items[0];
					var save2 = SnapshotCondition(fx2, RelicEffectEditorBox);
					var combo2 = ConditionComboOf(RelicEffectEditorBox);
					Check("V0.2.144 遗物页：编辑区里的条件框 DataContext 就是上面选中的那条效果（不是 null / 不是上一条）",
						ReferenceEquals(RelicEffectEditorBox?.DataContext, fx2)
						&& RelicEffectEditorBox?.IsVisible == true,
						"DataContext=" + ((RelicEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
					Check("V0.2.144 遗物页：编辑区里的「条件」下拉绑的是 EffectSpec.Condition.Kind，候选表是 PlainEffectConditions",
						combo2 is not null && ReferenceEquals(combo2.ItemsSource, PlainEffectConditions),
						combo2 is null ? "(没找到条件下拉)" : combo2.Items.Count + " 个候选");
					string origKind2 = fx2.Condition.Kind;
					ConditionOption? target2 = PlainEffectConditions.FirstOrDefault(o => o.Id != origKind2);
					Check("V0.2.144 遗物页（准备）：条件候选里有一条与当前不同的条件可选",
						target2 is not null, "当前=" + origKind2 + " / 待选=" + (target2?.Id ?? "(没有)"));
					if (target2 is not null)
					{
						bool picked = PickCondition(combo2!, target2.Id);
						Check("V0.2.144 遗物页：在编辑区里**真的选一个条件** → 写回 EffectSpec.Condition.Kind",
							picked && fx2.Condition.Kind == target2.Id,
							origKind2 + " → " + fx2.Condition.Kind + "（期望 " + target2.Id + "）");
						// 切到另一只遗物、再切回来 —— 条件必须还在（这就是用户说的「存住了」）
						int other2 = -1;
						for (int i = 1; i < RelicList.Items.Count; i++)
							if (RelicList.Items[i] is RelicSpec) { other2 = i; break; }
						Check("V0.2.144 遗物页（准备）：列表里还有第二只遗物可以切过去",
							other2 > 0, "第 " + (other2 + 1) + " 行");
						if (other2 > 0)
						{
							RelicList.SelectedIndex = other2;
							UpdateLayout();
							RelicList.SelectedIndex = 0;
							UpdateLayout();
							if (RelicEffectList.Items.Count > 0) RelicEffectList.SelectedItem = RelicEffectList.Items[0];
							UpdateLayout();
							Check("V0.2.144 遗物页：**切到另一只遗物再切回来，条件还在**（写的是模型、不是只改了界面）",
								RelicEffectList.Items.Count > 0 && ((EffectSpec)RelicEffectList.Items[0]).Condition.Kind == target2.Id,
								"切回来=" + (((EffectSpec)RelicEffectList.Items[0]).Condition.Kind) + " / 期望 " + target2.Id);
							Check("V0.2.144 遗物页：切回来编辑区绑的还是这条效果（DataContext 没串到别的效果上）",
								ReferenceEquals(RelicEffectEditorBox?.DataContext, RelicEffectList.Items[0]),
								"DataContext=" + ((RelicEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
						}
					}
					RestoreCondition(fx2, RelicEffectEditorBox, save2);
					Check("V0.2.144 遗物页：自检不留痕（条件已原样还回去）",
						fx2.Condition.Kind == save2.Snap.Kind, fx2.Condition.Kind);
				}
			}

			// ---- ③ 药水页：同一套（点行 → 选中 → 在编辑区改条件 → 写回 → 切走切回还在）----
			{
				SelectTabRoot("药水");
				if (PotionList.Items.Count > 0) PotionList.SelectedIndex = 0;
				UpdateLayout();
				Check("V0.2.144 药水页：样例存档里有药水效果可以验（点行 = 选中行）",
					PotionEffectList.Items.Count > 0, PotionEffectList.Items.Count + " 条效果");
				if (PotionEffectList.Items.Count > 0)
				{
					var pfx2 = (EffectSpec)PotionEffectList.Items[0];
					PotionEffectList.SelectedItem = null;
					UpdateLayout();
					bool pClicked = ClickEffectRow(PotionEffectList, 0);
					Check("V0.2.144 药水页：点那一行 → 这一行被选中，编辑区跟着换",
						pClicked && ReferenceEquals(PotionEffectList.SelectedItem, pfx2)
						&& ReferenceEquals(PotionEffectEditorBox?.DataContext, pfx2),
						"SelectedItem=" + (PotionEffectList.SelectedItem as EffectSpec)?.Kind + " / 期望=" + pfx2.Kind);
					var pSave = SnapshotCondition(pfx2, PotionEffectEditorBox);
					var pCombo = ConditionComboOf(PotionEffectEditorBox);
					Check("V0.2.144 药水页：编辑区里的条件框绑的是上面选中的那条效果、下拉绑定对",
						ReferenceEquals(PotionEffectEditorBox?.DataContext, pfx2) && pCombo is not null
						&& ReferenceEquals(pCombo.ItemsSource, PlainEffectConditions),
						"DataContext=" + ((PotionEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
					string pOrig = pfx2.Condition.Kind;
					ConditionOption? pTarget = PlainEffectConditions.FirstOrDefault(o => o.Id != pOrig);
					if (pCombo is not null && pTarget is not null)
					{
						bool pPicked = PickCondition(pCombo, pTarget.Id);
						Check("V0.2.144 药水页：在编辑区里真的选一个条件 → 写回 EffectSpec.Condition.Kind",
							pPicked && pfx2.Condition.Kind == pTarget.Id,
							pOrig + " → " + pfx2.Condition.Kind + "（期望 " + pTarget.Id + "）");
						// 切走再切回来（把药水列表的选择清掉再选回那一瓶 —— 效果列表重新读一遍模型）
						object? potionRow = PotionList.SelectedItem;
						PotionList.SelectedItem = null;
						UpdateLayout();
						PotionList.SelectedItem = potionRow;
						UpdateLayout();
						if (PotionEffectList.Items.Count > 0) PotionEffectList.SelectedItem = PotionEffectList.Items[0];
						UpdateLayout();
						Check("V0.2.144 药水页：切走再切回来条件还在（写的是模型）",
							PotionEffectList.Items.Count > 0 && ((EffectSpec)PotionEffectList.Items[0]).Condition.Kind == pTarget.Id,
							"切回来=" + (((EffectSpec)PotionEffectList.Items[0]).Condition.Kind) + " / 期望 " + pTarget.Id);
					}
					RestoreCondition(pfx2, PotionEffectEditorBox, pSave);
					Check("V0.2.144 药水页：自检不留痕（条件已原样还回去）",
						pfx2.Condition.Kind == pSave.Snap.Kind, pfx2.Condition.Kind);
				}
			}

			// ---- ④ 额外资源量页：同一套（样例存档里这一份效果是空的 → 自检自己放一条进去，用完原样还回去）----
			{
				bool erWasOn = Profile.ExtraResource.Enabled;
				var erKeepFx = Profile.ExtraResource.Effects.ToList();
				Profile.ExtraResource.Enabled = true;
				Raise("ExtraResourceRelicVisible");
				SelectTabRoot("额外资源量");
				UpdateLayout();
				try
				{
					if (ExtraResourceEffectList.Items.Count == 0)
					{
						// 样例存档的额外资源量效果是空的：临时放一条（自检不留痕，finally 里清掉）
						Profile.ExtraResource.Effects.Add(new EffectSpec { Kind = "Block", Amount = 4m, TargetSide = "Self" });
						UpdateLayout();
					}
					Check("V0.2.144 额外资源量页：效果栏里有可以点的效果行（样例为空时自检自己放一条临时的）",
						ExtraResourceEffectList.Items.Count > 0, ExtraResourceEffectList.Items.Count + " 条效果");
					if (ExtraResourceEffectList.Items.Count > 0)
					{
						var efx = (EffectSpec)ExtraResourceEffectList.Items[0];
						ExtraResourceEffectList.SelectedItem = null;
						UpdateLayout();
						bool eClicked = ClickEffectRow(ExtraResourceEffectList, 0);
						Check("V0.2.144 额外资源量页：点那一行 → 这一行被选中，编辑区跟着换",
							eClicked && ReferenceEquals(ExtraResourceEffectList.SelectedItem, efx)
							&& ReferenceEquals(ExtraResourceEffectEditorBox?.DataContext, efx),
							"SelectedItem=" + (ExtraResourceEffectList.SelectedItem as EffectSpec)?.Kind + " / 期望=" + efx.Kind);
						var eSave = SnapshotCondition(efx, ExtraResourceEffectEditorBox);
						var eCombo = ConditionComboOf(ExtraResourceEffectEditorBox);
						Check("V0.2.144 额外资源量页：编辑区里的条件框绑的是上面选中的那条效果、下拉绑定对",
							ReferenceEquals(ExtraResourceEffectEditorBox?.DataContext, efx) && eCombo is not null
							&& ReferenceEquals(eCombo.ItemsSource, PlainEffectConditions),
							"DataContext=" + ((ExtraResourceEffectEditorBox?.DataContext as EffectSpec)?.Kind ?? "(null)"));
						string eOrig = efx.Condition.Kind;
						ConditionOption? eTarget = PlainEffectConditions.FirstOrDefault(o => o.Id != eOrig);
						if (eCombo is not null && eTarget is not null)
						{
							bool ePicked = PickCondition(eCombo, eTarget.Id);
							Check("V0.2.144 额外资源量页：在编辑区里真的选一个条件 → 写回 EffectSpec.Condition.Kind",
								ePicked && efx.Condition.Kind == eTarget.Id,
								eOrig + " → " + efx.Condition.Kind + "（期望 " + eTarget.Id + "）");
							// 切走再切回来（把效果列表的选中清掉再选回来 —— 列表重新读一遍模型）
							ExtraResourceEffectList.SelectedItem = null;
							UpdateLayout();
							ExtraResourceEffectList.SelectedItem = ExtraResourceEffectList.Items[0];
							UpdateLayout();
							Check("V0.2.144 额外资源量页：切走再切回来条件还在（写的是模型）",
								((EffectSpec)ExtraResourceEffectList.Items[0]).Condition.Kind == eTarget.Id,
								"切回来=" + (((EffectSpec)ExtraResourceEffectList.Items[0]).Condition.Kind) + " / 期望 " + eTarget.Id);
						}
						RestoreCondition(efx, ExtraResourceEffectEditorBox, eSave);
					}
				}
				finally
				{
					// 把额外资源量的效果恢复成进来时的样子（自检不留痕）
					if (!Profile.ExtraResource.Effects.SequenceEqual(erKeepFx))
					{
						Profile.ExtraResource.Effects.Clear();
						foreach (EffectSpec k in erKeepFx) Profile.ExtraResource.Effects.Add(k);
					}
					Profile.ExtraResource.Enabled = erWasOn;
					Raise("ExtraResourceRelicVisible");
					SelectTabRoot("遗物");
					UpdateLayout();
				}
			}

			// ---- ⑤ 卡牌页回归：卡牌页本来就是「一行摘要列表 + 一块共享编辑区」，这次改动一个字都不该动到它 ----
			{
				SelectTabRoot("卡牌");
				UpdateLayout();
				Check("V0.2.144 卡牌页回归：卡牌页的效果列表还是「一行摘要」（DisplayMemberPath=Display、没有 ItemTemplate）",
					CardEffectList.ItemTemplate is null && CardEffectList.DisplayMemberPath is not null,
					"ItemTemplate=" + (CardEffectList.ItemTemplate is null ? "无" : "有")
					+ " / DisplayMemberPath=" + (CardEffectList.DisplayMemberPath ?? "(null)"));
				Check("V0.2.144 卡牌页回归：卡牌页的编辑区还是绑在 SelectedItem 上（三页现在是同一个形状）",
					CardEffectEditorBox is not null
					&& BindingOperations.GetBinding(CardEffectEditorBox, FrameworkElement.DataContextProperty)?.ElementName == "CardEffectList"
					&& BindingOperations.GetBinding(CardEffectEditorBox, FrameworkElement.DataContextProperty)?.Path?.Path == "SelectedItem",
					CardEffectEditorBox is null ? "(没找到)" : "绑 SelectedItem");
				if (CardEffectList.Items.Count > 0)
				{
					var cfx = CardEffectList.Items[0] as EffectSpec;
					// ⚠ 卡牌页的卡牌效果列表是**直接** ItemsSource=选中卡的 Effects（选项照旧能选中），
					//   这里只选第一条、不做清空（清空会把「编辑区绑 SelectedItem」那条 Binding 换成局部值）。
					CardEffectList.SelectedItem = CardEffectList.Items[0];
					UpdateLayout();
					Check("V0.2.144 卡牌页回归：选一条卡牌效果 → 那条效果的「条件选项」编辑器就在（和以前一样）",
						cfx is not null && ReferenceEquals(CardEffectEditorBox?.DataContext, cfx),
						cfx is null ? "(没有效果)" : "DataContext=" + cfx.Kind);
				}
			}
			SelectTabRoot("遗物");
		}

		Close();
		// 自检结束：把存档目录还原回真实值（并把临时目录删掉），
		// 免得自检产生的临时存档留在真实存档目录里、或者后面还有代码用到它。
		if (_selfTestRealProfileFolder is not null)
		{
			OverrideProfileFolderForTest(_selfTestRealProfileFolder);
			_selfTestRealProfileFolder = null;
		}
		try
		{
			if (Directory.Exists(selfTestFolder)) Directory.Delete(selfTestFolder, true);
		}
		catch { }
		return sb.ToString();
