	/// <summary>
	/// 从程序所在目录往上找一件**仓库相对路径**的文件（开发时有、部署版没有）。"
	/// 为什么不用写死的绝对路径：那种字符串会被编进 DLL，而打包脚本有「不许泄漏本机路径」的自检
	/// （`C:\Users\&lt;用户名 gt;` 一旦出现在发布产物里就会拒绝出包）。返回 null = 这台机器没有「"
	/// </summary>
	private static string? FindRepoFile(string relativePath)
	{
		var dir = new DirectoryInfo(AppContext.BaseDirectory);
		for (int up = 0; up < 8 && dir is not null; up++, dir = dir.Parent)
		{
			string candidate = Path.Combine(dir.FullName, relativePath);
			if (File.Exists(candidate)) return candidate;
		}
		return null;
	}

	/// <summary>
	/// 找仓库里那份「黄金测试动图」（<c>_art\anim_ref\testgif</c>）。
	/// 从程序所在目录往上找：开发时是 <c>src\...\bin\Debug\net9.0-windows</c>，往上 5 层就是仓库根。
	/// 找不到返回 null（部署版 --uicheck 就用自检自己造的那张 —— 自检不能依赖仓库文件）。
	/// </summary>
	private static string? FindRepoAnimGif(string name)
	{
		var dir = new DirectoryInfo(AppContext.BaseDirectory);
		for (int up = 0; up < 8 && dir is not null; up++, dir = dir.Parent)
		{
			string candidate = Path.Combine(dir.FullName, "_art", "anim_ref", "testgif", name);
			if (File.Exists(candidate)) return candidate;
		}
		return null;
	}

	/// <summary>
	/// 自检自己造的那张动图：2 帧、2×2、白底、每帧 100ms / 200ms。
	/// 为什么要内置一张：部署版的 <c>--uicheck</c> 旁边没有仓库的 <c>_art</c> 目录，
	/// 而「拆帧 → 写资源」这条路必须能在任何机器上验一遍。
	/// 字节是手写的（GIF89a + 全局色表 + 两个 GCE + 两个图像块），LZW 数据里每两个像素插一个 Clear 码 ——
	/// 这样字典项数不会涨到要加码长，7 个 3 位码正好 3 个字节（见下面的断言：它必须解得开）。
	/// </summary>
	private static void WriteSelfTestGif(string path)
	{
		byte[] gif = new byte[]
		{
			0x47, 0x49, 0x46, 0x38, 0x39, 0x61,                          // "GIF89a"
			0x02, 0x00, 0x02, 0x00, 0x80, 0x00, 0x00,                    // 画布 2×2，有全局色表（2 色），背景色 0，宽高比 0
			0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00,                          // 全局色表：白、黑
			0x21, 0xF9, 0x04, 0x00, 0x0A, 0x00, 0x00, 0x00,              // 图形控制扩展：延时 10（=100ms）
			0x2C, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00,  // 图像描述符：0,0 起，2×2，无局部色表、不隔行
			0x02, 0x03, 0x04, 0x08, 0x14, 0x00,                          // LZW 最小码长 2 + 3 字节数据 + 块结束
			0x21, 0xF9, 0x04, 0x00, 0x14, 0x00, 0x00, 0x00,              // 第二帧：延时 20（=200ms）
			0x2C, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00,
			0x02, 0x03, 0x04, 0x08, 0x14, 0x00,
			0x3B,                                                        // 文件结束
		};
		Directory.CreateDirectory(Path.GetDirectoryName(path)!);
		File.WriteAllBytes(path, gif);
	}

	/// <summary>
	/// 把存档 JSON 里的 <c>"Animation"</c> 整段删掉，用来模拟**V0.2.47 及以前的老存档**
	/// （那时候 JSON 里根本没有这一档）。AnimationSpec 里没有嵌套对象，所以这一段是连续的若干行。
	/// </summary>
	private static string RemoveAnimationSection(string json)
	{
		var kept = new List<string>();
		bool skipping = false;
		foreach (string line in json.Replace("\r\n", "\n").Split('\n'))
		{
			if (skipping)
			{
				string trimmed = line.TrimEnd();
				if (trimmed.EndsWith("},", StringComparison.Ordinal) || trimmed.EndsWith("}", StringComparison.Ordinal)) skipping = false;
				continue;
			}
			if (line.TrimStart().StartsWith("\"Animation\"", StringComparison.Ordinal))
			{
				skipping = true;
				continue;
			}
			kept.Add(line);
		}
		return string.Join("\n", kept);
	}

	/// <summary>
	/// 造一帧「中间一大块不透明深色 + 最外圈透明 + 再两圈浅灰」的 RGBA，用来验剥描边真的改了像素。
	/// 为什么要造：仓库那张测试动图的描边是**深色**，剥浅色描边对它本来就不该有任何效果
	/// （黄金文件实测：<c>variant_strip</c> 与基线逐字节相同）—— 拿它验「剥描边生效」是验不出来的。
	/// 尺寸要够大：剥掉的像素超过全图 2.5% 时算法会整块还原（保护素材别被剥没），小图必然触发那个兜底。
	/// </summary>
	private static byte[] OutlineProbeFrame(int size)
	{
		var rgba = new byte[size * size * 4];
		for (int y = 0; y < size; y++)
		{
			for (int x = 0; x < size; x++)
			{
				int o = (y * size + x) * 4;
				int ring = Math.Min(Math.Min(x, y), Math.Min(size - 1 - x, size - 1 - y));   // 0 = 最外圈
				byte v = ring == 0 ? (byte)10 : ring <= 2 ? (byte)220 : (byte)10;             // 最外圈透明，再两圈浅灰
				rgba[o] = rgba[o + 1] = rgba[o + 2] = v;
				rgba[o + 3] = ring == 0 ? (byte)0 : (byte)255;
			}
		}
		return rgba;
	}

	private void PumpDispatcher(int ms)
	{
		DateTime dateTime = DateTime.UtcNow.AddMilliseconds(ms);
		while (DateTime.UtcNow < dateTime)
		{
			base.Dispatcher.Invoke(delegate
			{
			}, DispatcherPriority.Background);
			Thread.Sleep(15);
		}
	}

	private static void CollectWrapPanels(DependencyObject root, List<WrapPanel> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is WrapPanel item)
			{
				into.Add(item);
			}
			CollectWrapPanels(child, into);
		}
	}

	private static void CollectTextBlocks(DependencyObject root, List<TextBlock> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is TextBlock item)
			{
				into.Add(item);
			}
			CollectTextBlocks(child, into);
		}
	}

	/// <summary>自检用：把一棵可视化树里的 Grid 全收出来（需求 ⑥ 查「那几行到底有没有显示出来」）。</summary>
	private static void CollectGrids(DependencyObject root, List<Grid> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is Grid item)
			{
				into.Add(item);
			}
			CollectGrids(child, into);
		}
	}

	/// <summary>
	/// 自检用：把一棵可视化树里所有 <see cref="FrameworkElement"/> 的 Visibility 绑定路径收出来。
	/// 为什么不只收 Panel：V0.2.150 那几行有的绑在 TextBlock / ComboBox / CheckBox 上（没有外层 Grid）。
	/// </summary>
	private static HashSet<string> CollectBoundPaths(DependencyObject root)
	{
		var into = new HashSet<string>(StringComparer.Ordinal);
		CollectBoundPathsInto(root, into);
		return into;
	}

	private static void CollectBoundPathsInto(DependencyObject root, HashSet<string> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is FrameworkElement fe && BindingOperations.GetBinding(fe, UIElement.VisibilityProperty)?.Path?.Path is { Length: > 0 } path)
				into.Add(path);
			CollectBoundPathsInto(child, into);
		}
	}

	/// <summary>
	/// 自检用：把一棵可视化树里的 Panel（Grid / StackPanel / WrapPanel…）全收出来。
	/// </summary>
	private static List<System.Windows.Controls.Panel> CollectBoundPanels(DependencyObject root)
	{
		var into = new List<System.Windows.Controls.Panel>();
		CollectPanels(root, into);
		return into;
	}

	private static void CollectPanels(DependencyObject root, List<System.Windows.Controls.Panel> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
