	/// <summary>
	/// 「某个页签里那块写着 <paramref name="label"/> 的文字，所在的面板有没有可滚动的祖先」。
	/// 用来检查小窗口下属性栏能不能滚下去（用户反馈过看不到下面的内容）。
	/// </summary>
	private bool FindLabelledTextAndHasScrollAncestor(string label, string tabHeader)
	{
		DependencyObject root = SelectTabRoot(tabHeader);
		List<TextBlock> blocks = new List<TextBlock>();
		CollectTextBlocks(root, blocks);
		TextBlock? hit = blocks.FirstOrDefault((TextBlock b) => (b.Text ?? "").Trim() == label);
		if (hit is null) return false;
		DependencyObject? node = hit;
		while (node is not null)
		{
			if (node is ScrollViewer sv)
				return sv.VerticalScrollBarVisibility is ScrollBarVisibility.Auto or ScrollBarVisibility.Visible;
			node = System.Windows.Media.VisualTreeHelper.GetParent(node);
		}
		return false;
	}

	/// <summary>某个组件外面有没有滚动条（同上，按控件找）。</summary>
	private static bool HasScrollAncestor(DependencyObject node)
	{
		DependencyObject? cur = node;
		while (cur is not null)
		{
			if (cur is ScrollViewer sv)
				return sv.VerticalScrollBarVisibility is ScrollBarVisibility.Auto or ScrollBarVisibility.Visible;
			cur = System.Windows.Media.VisualTreeHelper.GetParent(cur);
		}
		return false;
	}

	/// <summary>某个元素在某页签里（用于断言控件确实在界面上）。</summary>
	private bool ExistsInTab(DependencyObject? node, string tabHeader)
	{
		if (node is null) return false;
		DependencyObject root = SelectTabRoot(tabHeader);
		DependencyObject? cur = node;
		while (cur is not null)
		{
			if (ReferenceEquals(cur, root)) return true;
			cur = System.Windows.Media.VisualTreeHelper.GetParent(cur);
		}
		return false;
	}

	private static GroupBox? FindGroupBoxByHeader(string header, DependencyObject root)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is GroupBox groupBox && string.Equals(groupBox.Header as string, header, StringComparison.Ordinal))
			{
				return groupBox;
			}
			GroupBox groupBox2 = FindGroupBoxByHeader(header, child);
			if (groupBox2 != null)
			{
				return groupBox2;
			}
		}
		return null;
	}

	/// <summary>把一个控件树里的下拉都收出来（自检里要「真的去动某个下拉」，先得找到它）。 /summary>
	private static void CollectComboBoxes(DependencyObject root, List<ComboBox> into)
	{
		int childrenCount = VisualTreeHelper.GetChildrenCount(root);
		for (int i = 0; i < childrenCount; i++)
		{
			DependencyObject child = VisualTreeHelper.GetChild(root, i);
			if (child is ComboBox item)
			{
				into.Add(item);
			}
			CollectComboBoxes(child, into);
		}
	}

	/// <summary>
	/// 按「绑定的属性名」找一个下拉（例：遗物编辑器里给 <c>Trigger</c> 的那个「触发时机」下拉）。"
	/// 自检要靠它模拟用户在下拉里换选项，才能验出「换完时机那一栏没跟着变」这类界面上的坑。"
	/// </summary>
	private static ComboBox? FindComboBoundTo(DependencyObject root, string propertyPath)
	{
		List<ComboBox> list = new List<ComboBox>();
		CollectComboBoxes(root, list);
		foreach (ComboBox combo in list)
		{
			foreach (DependencyProperty prop in new[] { Selector.SelectedValueProperty, Selector.SelectedItemProperty, Selector.SelectedIndexProperty })
			{
				if (combo.GetBindingExpression(prop)?.ParentBinding.Path?.Path == propertyPath)
				{
					return combo;
				}
			}
		}
		return null;
	}

	private static List<string> TextsIn(DependencyObject root)
	{
		List<TextBlock> list = new List<TextBlock>();
		CollectTextBlocks(root, list);
		List<string> list2 = list.Select((TextBlock t) => t.Text ?? "").ToList();
		List<CheckBox> list3 = new List<CheckBox>();
		CollectCheckBoxes(root, list3);
		list2.AddRange(list3.Select((CheckBox c) => (c.Content as string) ?? ""));
		List<Button> list4 = new List<Button>();
		CollectButtons(root, list4);
		list2.AddRange(list4.Select((Button b) => (b.Content as string) ?? ""));
		return list2;
	}

	/// <summary>
	/// 和 <see cref="TextsIn"/> 一样，但**只收真正可见的那些**（<c>IsVisible</c> 会把祖先的 Visibility 一起算上）。
	/// 为什么要它：TextsIn 连 Collapsed 里的文字也收，验「这一行现在到底显示没有」时会被骗过（实测踩过）。
	/// </summary>
	private static List<string> VisibleTextsIn(DependencyObject root)
	{
		List<TextBlock> list = new List<TextBlock>();
		CollectTextBlocks(root, list);
		List<string> list2 = list.Where((TextBlock t) => t.IsVisible).Select((TextBlock t) => t.Text ?? "").ToList();
		List<CheckBox> list3 = new List<CheckBox>();
		CollectCheckBoxes(root, list3);
		list2.AddRange(list3.Where((CheckBox c) => c.IsVisible).Select((CheckBox c) => (c.Content as string) ?? ""));
		List<Button> list4 = new List<Button>();
		CollectButtons(root, list4);
		list2.AddRange(list4.Where((Button b) => b.IsVisible).Select((Button b) => (b.Content as string) ?? ""));
		return list2;
	}



public sealed class AncientRow
{
	public AncientEntry Entry { get; }

	public AncientTalkSpec Talk { get; }

	public ObservableCollection<AncientDialogueSpec> Dialogues { get; }

	/// <summary>
	/// 遗物替换记录（转发给 Talk，方便 XAML 里直接绑定）。
	/// 注意：这一页的 DataContext 是 AncientRow 而不是 AncientTalkSpec，
	/// 少了这个转发属性，界面上的 `{Binding RelicReplacements}` 会静默绑不上 ——
	/// 表现就是「替换记录列表永远空的、点了也没反应」（踩过）。
	/// </summary>
	public ObservableCollection<AncientRelicReplaceSpec> RelicReplacements => Talk.RelicReplacements;

	public string Display => Entry.Display + (Talk.HasAnyText ? "  ✅" : "");

	public bool IsArchitect => string.Equals(Entry.Id, "THE_ARCHITECT", StringComparison.OrdinalIgnoreCase);

	public string UnitFieldLabel
	{
		get
		{
			if (!IsArchitect)
			{
				return "第几次到访";
			}
			return "第几次";
		}
	}

	public string UnitLabel
	{
		get
		{
			if (!IsArchitect)
			{
				return "次到访";
			}
			return "次";
		}
	}

	public string UnitHint
	{
		get
		{
			if (!IsArchitect)
			{
				return "这里填的是「第几次」，从 1 开始：1 = 第 1 次到访，2 = 第 2 次…；-1 = 每次都可能说。注意：所有角色第 1 次见到他时，本体会先放它自己的那句固定台词，所以第 1 次轮不到我们 —— 想让你这段最早出现就填 2。";
			}
			return "这里填的是「第几次」，从 1 开始：1 = 还没通关过时（第一次遇到他），2 = 通关过 1 次之后，3 = 通关过 2 次之后；-1 = 每次都可能说。";
		}
	}

	public string Hint
	{
		get
		{
			if (!Entry.HasNativeAnyDialogue)
			{
				return "本体没给他写过「任意角色」的对话（建筑师就是这样），但模组里的补丁会把我们的角色塞进本体对话表，所以这里照样能写。";
			}
			return "本体给「任意角色」写的原文：" + string.Join(" / ", (from s in Entry.NativeSlots
				where s.VanillaFirstLine.Length > 0
				select s.VanillaFirstLine).Take(3)) + "（我们写的对话会取代它，句数不受它限制）";
		}
	}

	public AncientRow(AncientEntry entry, AncientTalkSpec talk)
	{
		Entry = entry;
		Talk = talk;
		Dialogues = talk.Dialogues;
	}
}



/// <summary>
/// 「升级后的关键字」界面里的一行：某个关键字在「升级后」是什么状态
/// （不变 / 升级后获得 / 升级后失去）。绑定到当前选中卡牌的 UpgradeKeywords。
/// </summary>
public sealed class KeywordUpgradeRow : INotifyPropertyChanged
{
	private readonly CardSpec _card;

	private readonly string _field;

	public string Zh { get; }

	public KeywordUpgradeRow(CardSpec card, string field, string zh)
	{
		_card = card;
		_field = field;
		Zh = zh;
	}

	/// <summary>三态：Keep / Add / Remove（下拉框里显示的是中文）。</summary>
	public string State
	{
		get => _card.UpgradeKeywords.Get(_field);
		set
		{
			if (string.Equals(_card.UpgradeKeywords.Get(_field), value, StringComparison.Ordinal)) return;
			_card.UpgradeKeywords.Set(_field, value);
			Raise("State");
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

/// <summary>
/// 「卡牌」页里「自定义关键词」的一行：一张卡 × 一条关键词。
/// 勾选写入这张卡的 KeywordIds（存本地化键；生成时卡面描述开头 + 悬停说明都按它来）。
/// </summary>
public sealed class CustomKeywordRow : INotifyPropertyChanged
{
	private readonly CardSpec _card;

	private readonly CustomKeywordSpec _spec;

	private readonly string _key;

	public CustomKeywordRow(CardSpec card, CustomKeywordSpec spec, string key)
	{
		_card = card;
		_spec = spec;
		_key = key;
	}

	public string Name => string.IsNullOrWhiteSpace(_spec.Name) ? _key : _spec.Name.Trim();

	public string KeyHint => _key;

	public bool IsChecked
	{
		get => _card.CustomKeywordList.Any(x =>
			string.Equals(x, _key, StringComparison.OrdinalIgnoreCase)
			|| string.Equals(x, (_spec.Name ?? "").Trim(), StringComparison.OrdinalIgnoreCase));
		set
		{
			var list = new List<string>(_card.CustomKeywordList);
			string name = (_spec.Name ?? "").Trim();
			if (value)
			{
				// 统一存「本地化键」，和生成代码里的 LocString 键保持一致
				list.RemoveAll(x => string.Equals(x, name, StringComparison.OrdinalIgnoreCase));
				if (!list.Any(x => string.Equals(x, _key, StringComparison.OrdinalIgnoreCase))) list.Add(_key);
			}
			else
			{
				list.RemoveAll(x => string.Equals(x, _key, StringComparison.OrdinalIgnoreCase)
					|| string.Equals(x, name, StringComparison.OrdinalIgnoreCase));
			}
			_card.KeywordIds = list;
			Raise(nameof(IsChecked));
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

/// <summary>
/// V0.2.136：「自定义关键词 · 升级后获得 / 升级后失去」两栏里的一行（一张卡 × 一条关键词 × 方向）。
/// 勾选写进这张卡的 UpgradeAddedCustomKeywords / UpgradeRemovedCustomKeywords（存本地化键）。
///
/// <para>⚠ 这两栏**只影响显示**：自定义关键词是本体封闭枚举之外的显示等价物
///（卡面那行 <c>[gold]名字[/gold]。</c> + <c>ExtraHoverTips</c> + <c>card_keywords</c> 本地化键），
/// 游戏侧没有任何按它判定的逻辑 —— 所以这里勾的不是「机制」，是「升级后卡面上显不显示这个词」。</para>
/// </summary>
public sealed class UpgradeCustomKeywordRow : INotifyPropertyChanged
{
	private readonly CardSpec _card;

	private readonly CustomKeywordSpec _spec;

	private readonly string _key;

	private readonly bool _added;

	public UpgradeCustomKeywordRow(CardSpec card, CustomKeywordSpec spec, string key, bool added)
	{
		_card = card;
		_spec = spec;
		_key = key;
		_added = added;
	}

	public string Name => string.IsNullOrWhiteSpace(_spec.Name) ? _key : _spec.Name.Trim();

	public string KeyHint => _key;

	/// <summary>这一栏当前勾的引用列表（本地化键）。</summary>
	private List<string> Current =>
		new(_added ? _card.UpgradeAddedCustomKeywords : _card.UpgradeRemovedCustomKeywords);

	public bool IsChecked
	{
		get => Current.Any(x =>
			string.Equals(x, _key, StringComparison.OrdinalIgnoreCase)
			|| string.Equals(x, (_spec.Name ?? "").Trim(), StringComparison.OrdinalIgnoreCase));
		set
		{
			var list = Current;
			string name = (_spec.Name ?? "").Trim();
			if (value)
			{
				// 统一存「本地化键」，和生成代码里的 LocString 键 / CET 标记保持一致
				list.RemoveAll(x => string.Equals(x, name, StringComparison.OrdinalIgnoreCase));
				if (!list.Any(x => string.Equals(x, _key, StringComparison.OrdinalIgnoreCase))) list.Add(_key);
			}
			else
			{
				list.RemoveAll(x => string.Equals(x, _key, StringComparison.OrdinalIgnoreCase)
					|| string.Equals(x, name, StringComparison.OrdinalIgnoreCase));
			}
			if (_added) _card.UpgradeAddedCustomKeywords = list;
			else _card.UpgradeRemovedCustomKeywords = list;
			Raise(nameof(IsChecked));
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

public sealed class ArtSlot : INotifyPropertyChanged
{
	private string? _path;

	private readonly Func<ArtSpec, string?> _get;

	private readonly Action<ArtSpec, string?> _set;

	public string Name { get; }

	public string Hint { get; }

	public string Requirement { get; }

	/// <summary>游戏里这块的显示尺寸（宽；0 = 这个槽位没有固定的显示区域）。</summary>
	public int FrameWidth { get; }

	/// <summary>游戏里这块的显示尺寸（高；0 = 这个槽位没有固定的显示区域）。</summary>
	public int FrameHeight { get; }

	/// <summary>有没有「游戏里的显示区域」——有就按它的比例画预览黑框（能看到黑边）。</summary>
	public bool HasFrame => FrameWidth > 0 && FrameHeight > 0;

	/// <summary>上传图和显示区域的比例说明（预览下面那行小字；没上传 / 比例一致时也有话说）。</summary>
	public string AspectNote => HasFrame
		? MainWindow.AspectNoteOf(_path, FrameWidth, FrameHeight, $"游戏里这块（{Name}）")
		: "";

	public string? Path
	{
		get
		{
			return _path;
		}
		set
		{
			_path = value;
			Raise("Path");
			Raise("PathOrEmpty");
			Raise("Preview");
			Raise("AspectNote");
			Raise("Display");
		}
	}

	public BitmapImage? Preview
	{
		get
		{
			if (string.IsNullOrWhiteSpace(_path) || !File.Exists(_path))
			{
				return null;
			}
			try
			{
				BitmapImage bitmapImage = new BitmapImage();
				bitmapImage.BeginInit();
				bitmapImage.CacheOption = BitmapCacheOption.OnLoad;
				bitmapImage.UriSource = new Uri(_path);
				bitmapImage.EndInit();
				return bitmapImage;
			}
			catch
			{
				return null;
			}
		}
	}

	public string Display
	{
		get
		{
			if (!string.IsNullOrWhiteSpace(_path))
			{
				return Name + "（已上传）";
			}
			return Name + "（" + EmptyLabel + "）";
		}
	}

	/// <summary>没上传时列表里显示的那个词（默认「占位」；像「拿取」这种本体没有的槽位是「未上传」）。 /summary>
	public string EmptyLabel { get; }

	/// <summary>没上传时详情页那行说明（默认照旧说「用铁甲战士占位」）。 /summary>
	public string EmptyNote { get; }

	/// <summary>详情页显示的那行：上传了就是路径，没上传就是 <see cref="EmptyNote"/>。 /summary>
	public string PathOrEmpty => string.IsNullOrWhiteSpace(_path) ? EmptyNote : _path!;

	public event PropertyChangedEventHandler? PropertyChanged;

	public ArtSlot(string name, string hint, string requirement, Func<ArtSpec, string?> get, Action<ArtSpec, string?> set,
		int frameWidth = 0, int frameHeight = 0, string emptyLabel = "占位", string? emptyNote = null)
	{
		Name = name;
		Hint = hint;
		Requirement = requirement;
		_get = get;
		_set = set;
		FrameWidth = frameWidth;
		FrameHeight = frameHeight;
		EmptyLabel = emptyLabel;
		EmptyNote = emptyNote ?? "（未上传，当前使用铁甲战士占位）";
	}

	public void Load(ArtSpec art)
	{
		Path = _get(art);
	}

	public void Save(ArtSpec art)
	{
		_set(art, Path);
	}

	private void Raise(string n)
	{
		this.PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(n));
	}
}

/// <summary>
/// 「动画」页的一个槽位（一个动作）。形状照 <see cref="ArtSlot"/>：列表行 + 详情 + 预览 + 清除，
/// 区别只有一个 —— 数据落在 <see cref="AnimationSpec"/> 上，而且预览**只能给第一帧**
/// （WPF 播不了动图，真正逐帧播放的是游戏里那套运行时）。
/// </summary>
public sealed class AnimSlot : INotifyPropertyChanged
{
	private string? _path;

	/// <summary>解码结果按路径缓存：一张动图可能几十帧、几 MB，界面每刷一次都重解会很卡。</summary>
	private string? _cachePath;

	private GifFrames.Result? _cacheGif;

	private readonly Func<AnimationSpec, string?> _get;

	private readonly Action<AnimationSpec, string?> _set;

	/// <summary>界面上的槽位名（待机（循环）/ 攻击 / …）。</summary>
	public string Name { get; }

	/// <summary>本体那边的动画名（idle_loop / attack / cast / hurt / die / overgrowth_loop / relaxed_loop）。</summary>
	public string AnimName { get; }

	/// <summary>这个动作在游戏里什么时候播。</summary>
	public string Hint { get; }

	/// <summary>素材要求（GIF / 可选 / 必须有）。</summary>
	public string Requirement { get; }

	public string? Path
	{
		get => _path;
		set
		{
			_path = value;
			Raise(nameof(Path));
			Raise(nameof(Preview));
			Raise(nameof(PreviewWidth));
			Raise(nameof(PreviewHeight));
			Raise(nameof(FrameNote));
			Raise(nameof(Display));
		}
	}

	/// <summary>缩略图：动图的**第一帧**（没上传 / 文件不在 / 解不开都给 null，界面就空着）。</summary>
	public BitmapSource? Preview
	{
		get
		{
			GifFrames.Result? gif = Decode();
			if (gif is null || gif.Frames.Count == 0) return null;
			return MainWindow.BitmapFromRgba(gif.Width, gif.Height, gif.Frames[0].Rgba);
		}
	}

	/// <summary>预览框的宽 / 高 = 动图自己的画布尺寸（这样界面里能看到素材的真实比例）。</summary>
	public int PreviewWidth => Decode()?.Width ?? 0;

	public int PreviewHeight => Decode()?.Height ?? 0;

	/// <summary>预览下面那行小字：几帧 / 多大 / 每帧多久（或为什么显示不出来）。</summary>
	public string FrameNote
	{
		get
		{
			if (string.IsNullOrWhiteSpace(_path)) return "（没上传：这个动作会退回待机）";
			if (!File.Exists(_path)) return "文件不在了：" + _path;
			GifFrames.Result? gif = Decode();
			if (gif is null) return "解不开（只支持 GIF）：" + _path;
			return $"{gif.Frames.Count} 帧 · {gif.Width}×{gif.Height} · 每帧 "
				+ AnimFramesGen.AverageSeconds(gif).ToString("0.###", System.Globalization.CultureInfo.InvariantCulture)
				+ " 秒（按动图自己的延时取平均）";
		}
	}

	public string Display
	{
		get
		{
			if (!string.IsNullOrWhiteSpace(_path)) return Name + "（已上传）";
			// 「待机必须有」这件事要在列表上就能看见，不能只在详情里写
			return AnimName == "idle_loop" ? Name + "（必须有，还没上传）" : Name + "（没上传：退回待机）";
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	public AnimSlot(string name, string animName, string hint, string requirement,
		Func<AnimationSpec, string?> get, Action<AnimationSpec, string?> set)
	{
		Name = name;
		AnimName = animName;
		Hint = hint;
		Requirement = requirement;
		_get = get;
		_set = set;
	}

	public void Load(AnimationSpec anim)
	{
		Path = _get(anim);
	}

	public void Save(AnimationSpec anim)
	{
		_set(anim, Path);
	}

	private GifFrames.Result? Decode()
	{
		// 只按路径判缓存：界面上的路径变了就重解（同一路径换了文件内容这种极端情况不管 ——
		// 这一页只是给个缩略图，真正的解码在生成时才做）
		if (string.Equals(_cachePath, _path, StringComparison.Ordinal)) return _cacheGif;
		_cachePath = _path;
		_cacheGif = string.IsNullOrWhiteSpace(_path) ? null : GifFrames.Decode(_path);
		return _cacheGif;
	}

	private void Raise(string n)
	{
		this.PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(n));
	}
}


