/// <summary>
/// V0.2.255（用户要求「让状态进组」）：组右边「这个组里有哪些状态」的一行（勾选即加入 / 取消）。
/// 候选 = 你自己的自定义状态 + 已经加进组的（哪怕已停用）+ 本体状态。
/// </summary>
public sealed class PowerGroupMemberRow : INotifyPropertyChanged
{
	private readonly CharacterProfile? _profile;

	private readonly CardGroupSpec _group;

	private readonly MainWindow? _win;

	public string PowerId { get; }

	public string Display { get; }

	private PowerGroupMemberRow(CharacterProfile? profile, CardGroupSpec group, string powerId, string display, MainWindow? win)
	{
		_profile = profile;
		_group = group;
		PowerId = powerId;
		Display = display;
		_win = win;
	}

	/// <summary>
	/// V0.2.257：`group` 先按 Id 在**当前存档**里重新找一次 —— 界面上的列表有时还持有上一份存档的组实例，
	/// 往旧实例上写等于白写（用户报「勾了但没进组、存出来还是空的」）。
	/// </summary>
	public static List<PowerGroupMemberRow> Build(CharacterProfile profile, CardGroupSpec group, MainWindow? win = null)
	{
		var live = profile.CardGroups.FirstOrDefault(x => x is not null && string.Equals(x.Id, group.Id, StringComparison.Ordinal)) ?? group;
		var rows = new List<PowerGroupMemberRow>();
		var seen = new HashSet<string>(StringComparer.Ordinal);
		for (int i = 0; i < profile.CustomPowers.Count; i++)
		{
			var cp = profile.CustomPowers[i];
			if (cp is null) continue;
			string cls = CustomPowerGen.ClassNameOf(profile, cp, i);
			if (!seen.Add(cls)) continue;
			string name = string.IsNullOrWhiteSpace(cp.Name) ? cls : cp.Name.Trim();
			rows.Add(new PowerGroupMemberRow(profile, live, cls, $"（你自己的状态）{name}", win));
		}
		foreach (string cls in live.PowerIdList)
			if (seen.Add(cls))
				rows.Add(new PowerGroupMemberRow(profile, live, cls, $"（已加入，但当前配置里没有这个状态）{cls}", win));
		foreach (var p in EffectCatalog.Powers.OrderBy(x => x.Zh, StringComparer.Ordinal))
			if (seen.Add(p.Id))
				rows.Add(new PowerGroupMemberRow(profile, live, p.Id, $"（本体）{p.Zh}", win));
		return rows;
	}

	public bool IsChecked
	{
		get => _group.PowerIdList.Contains(PowerId);
		set
		{
			try
			{
				MainWindow.SetPowerGroupMembership(_profile, _group, PowerId, value);
				_win?.SetStatus(value
					? $"已把状态「{Display}」加入组「{_group.Name}」（组里现在有 {_group.PowerIdList.Count} 个状态）。"
					: $"已把状态「{Display}」移出组「{_group.Name}」（组里还剩 {_group.PowerIdList.Count} 个状态）。");
			}
			catch (Exception ex)
			{
				_win?.SetStatus("加入组失败：" + ex.Message);
			}
			Raise("IsChecked");
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

/// <summary>
/// V0.2.265（用户要求「音频也能加入组」）：组右边第三列「这个组里有哪些音频」的一行（勾选即加入 / 取消）。
/// 成员记在组身上（<see cref="CardGroupSpec.AudioIds"/>，存的是音频 Key）。
/// </summary>
public sealed class AudioGroupMemberRow : INotifyPropertyChanged
{
	private readonly CharacterProfile? _profile;

	private readonly CardGroupSpec _group;

	private readonly MainWindow? _win;

	public string AudioKey { get; }

	public string Display { get; }

	private AudioGroupMemberRow(CharacterProfile? profile, CardGroupSpec group, string audioKey, string display, MainWindow? win)
	{
		_profile = profile;
		_group = group;
		AudioKey = audioKey;
		Display = display;
		_win = win;
	}

	/// <summary>和状态那边一样：先按 Id 在**当前存档**里重新找一次组，往旧实例上写等于白写。</summary>
	public static List<AudioGroupMemberRow> Build(CharacterProfile profile, CardGroupSpec group, MainWindow? win = null)
	{
		var live = profile.CardGroups.FirstOrDefault(x => x is not null && string.Equals(x.Id, group.Id, StringComparison.Ordinal)) ?? group;
		var rows = new List<AudioGroupMemberRow>();
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var a in profile.AudioAssets)
		{
			if (a is null) continue;
			string key = (a.Key ?? "").Trim();
			if (key.Length == 0 || !seen.Add(key)) continue;
			string name = string.IsNullOrWhiteSpace(a.Name) ? key : a.Name.Trim();
			rows.Add(new AudioGroupMemberRow(profile, live, key, $"（音频）{name}  ｜ {key}", win));
		}
		foreach (string key in live.AudioIdList)
			if (seen.Add(key))
				rows.Add(new AudioGroupMemberRow(profile, live, key, $"（已加入，但「美术资源」页里没有这个音频）{key}", win));
		return rows;
	}

	public bool IsChecked
	{
		get => _group.AudioIdList.Contains(AudioKey, StringComparer.OrdinalIgnoreCase);
		set
		{
			try
			{
				MainWindow.SetAudioGroupMembership(_profile, _group, AudioKey, value);
				_win?.SetStatus(value
					? $"已把音频「{Display}」加入组「{_group.Name}」（组里现在有 {_group.AudioIdList.Count} 个音频）。"
					: $"已把音频「{Display}」移出组「{_group.Name}」（组里还剩 {_group.AudioIdList.Count} 个音频）。");
			}
			catch (Exception ex)
			{
				_win?.SetStatus("音频加入组失败：" + ex.Message);
			}
			Raise("IsChecked");
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

/// <summary>「清除指定状态 → 或者清空一个组」下拉里的一项（组名 + 组 Id）。</summary>
public sealed record GroupChoice(string Display, string Id);

/// <summary>
/// 「转化为先古卡」配对表里的一行（左：源组下拉；右：这一行已经勾了哪些先古卡 + 删除按钮）。
/// 选中行 = 下面那排「先古卡池」勾选框写进哪一行。
/// </summary>
public sealed class AncientRowItem : INotifyPropertyChanged
{
	private readonly MainWindow _win;

	public AncientTranscendRow Row { get; }

	public int Index { get; }

	public AncientRowItem(MainWindow win, AncientTranscendRow row, int index)
	{
		_win = win;
		Row = row;
		Index = index;
	}

	/// <summary>右边那一句「已经勾了哪些先古卡」（勾选 / 改组之后重刷）。 /summary>
	public string PoolText => Row.AncientCards.Count == 0
		? "（还没勾先古卡）"
		: string.Join("。", Row.AncientCards);

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

/// <summary>配对表下面「先古卡池」里的一个勾选框（写进当前正在配的那一行）。 /summary>
public sealed class AncientCardItem : INotifyPropertyChanged
{
	private readonly MainWindow _win;

	private readonly AncientTranscendRow _row;

	public string ClassName { get; }

	public string Name { get; }

	public AncientCardItem(MainWindow win, AncientTranscendRow row, string className, string name)
	{
		_win = win;
		_row = row;
		ClassName = className;
		Name = name;
	}

	/// <summary>悬停提示：本体卡显示类名（生成里就是它），自己的卡显示「你自己的先古卡」。 /summary>
	public string Hint => $"{Name}（{ClassName}）";

	public bool IsChecked
	{
		get => _row.AncientCards.Contains(ClassName, StringComparer.Ordinal);
		set
		{
			if (value)
			{
				if (!_row.AncientCards.Contains(ClassName, StringComparer.Ordinal)) _row.AncientCards.Add(ClassName);
			}
			else
			{
				_row.AncientCards.RemoveAll(x => string.Equals(x, ClassName, StringComparison.Ordinal));
			}
			_win.RefreshAncientRows();
			Raise("IsChecked");
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	private void Raise(string name) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

}





